D[6607] = {[1]="Nat Pagle, Angler Extreme",[2]={{12919}},[3]={{12919}},[4]=35,[5]=45,[8]={"Nat Pagle wants you to catch the following fish:","","Misty Reed Mahi Mahi from the Misty Reed Strand in the Swamp of Sorrows.","","A Sar'theris Striker from the Sar'theris Strand in Desolace.","","Feralas Ahi from the Verdantis River of Feralas.","","Savage Coast Blue Sailfin from the Savage Coast of Stranglethorn Vale.","","Return to Nat Pagle when you have reeled them all in!"},[10]={[3]={{16967,nil,0},{16970,nil,0},{16968,nil,0},{16969,nil,0}}},[17]=-101,[23]=8}
