D[6609] = {[1]="I Got Nothin' Left!",[2]={{5161}},[3]={{12919}},[4]=35,[5]=45,[6]=1101,[8]={"Travel to Kalimdor, to the coastal city of Theramore. From there you must search for an island, south of the main town. Nat Pagle awaits your arrival!"},[17]=-101,[22]=6607,[23]=8,[27]=6607}
