D[7849] = {[1]="Separation Anxiety",[2]={{14741}},[3]={{14741}},[4]=46,[5]=50,[6]=690,[8]={"Huntsman Markhor at Revantusk Village in the Hinterlands wants you to recover his twin brother's remains. Find and return Huntsman Malkhor's Skull and Huntsman Malkhor's Bones to Huntsman Markhor.","","Markhor mentioned that his brother's remains were fed to the oozes and wolves of the Vilebranch. He also mentioned that there is a refuse pit filled with oozes in Jintha'alor as well as a wolf den. Both of these places are near the top of the temple."},[10]={[3]={{19069,nil,0},{19070,nil,0}}},[17]=47,[23]=8}
