(function() local D = SUIQuestScopeData.L10n.deDE.Quest
D[1] = {"Kanrethads Quest",{"Sprecht mit Kanrethad, um Eure Talente, Waffen und Euer Reittier wiederherzustellen."}}
D[2] = {"Klaue von Scharfkralle",{"Bringt die Klaue von Scharfkralle zu Senani Donnerherz im Splitterholzposten im Eschental."}}
D[5] = {"Bibbers' knurrender Magen",{"Sprecht mit Küchenchef Grual."}}
D[6] = {"Kopfgeld auf Garrick Schleichfuß",{"Tötet Garrick Schleichfuß und bringt seinen Kopf zu Stellvertreter Willem in der Nähe der Abtei von Nordhain."}}
D[7] = {"Säuberung im Koboldlager",{"Tötet 8 von dem Koboldgezücht und kehrt dann zu Marschall McBride zurück."}}
D[8] = {"Ein Schurkenhandel",{"Liefert den unscheinbaren Brief bei Gastwirtin Renee in Tirisfal ab."}}
D[9] = {"Tod auf den Feldern",{"Bauer Saldean möchte, dass Ihr 20 Erntebehüter tötet."}}
D[10] = {"Die Erlösung von Kieselschliff",{"Erforscht das Schicksal von Unterfeldmesser Kieselschliff und bringt entweder ihn oder seine Feldmesserausrüstung nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels."}}
D[11] = {"Kopfgeld auf die Flusspfotengnolle",{"Bringt Stellvertreter Rainer in der Kaserne 8 bemalte Gnollarmbinden."}}
D[12] = {"Die Volksmiliz",{"Gryan Starkmantel möchte, dass Ihr 15 Fallensteller der Defias und 15 Schmuggler der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}}
D[13] = {"Die Volksmiliz",{"Gryan Starkmantel möchte, dass Ihr 15 Plünderer der Defias und 15 Ausplünderer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}}
D[14] = {"Die Volksmiliz",{"Gryan Starkmantel möchte, dass Ihr 15 Straßenräuber der Defias, 5 Pfadpirscher der Defias und 5 Knöchelhauer der Defias tötet und zu ihm auf die Späherkuppe zurückkehrt."}}
D[15] = {"Überprüfung der Echokammmine",{"Tötet 8 Koboldtagelöhner und erstattet dann Marschall McBride Euren Bericht."}}
D[16] = {"Etwas zu trinken für Gerard"}
D[17] = {"Reagenzsuche in Uldaman",{"Bringt zwölf Magentafunguskappen nach Thelsamar zu Ghak Heilsegen."}}
D[18] = {"Bruderschaft der Diebe",{"Bringt 8 rote Sackleinenkopftücher zu Stellvertreter Willem in der Nähe der Abtei von Nordhain."}}
D[19] = {"Tharil'zun",{"Bringt den Kopf von Tharil'zun ins Rotkammgebirge zu Marschall Marris."}}
D[20] = {"Bedrohung durch den Schwarzfelsklan",{"Bringt 10 kampferprobte Äxte nach Seenhain zu Marschall Marris."}}
D[21] = {"Scharmützel in der Echokammmine",{"Tötet 8 Koboldhilfsarbeiter und kehrt dann zu Marschall McBride in der Abtei von Nordhain zurück."}}
D[22] = {"Pastete aus Geiferzahnleber",{"Salma Saldean braucht 8 Geiferzahnlebern für ihre Pastete aus Geiferzahnleber."}}
D[23] = {"Ursangus' Tatze",{"Bringt Ursangus' Tatze zu Senani Donnerherz im Splitterholzposten im Eschental."}}
D[24] = {"Schattumbras Kopf",{"Bringt Schattumbras Kopf zu Senani Donnerherz im Splitterholzposten im Eschental."}}
D[25] = {"Stillstand am Steinkrallenpfad",{"Erledigt 12 beschmutzte Wasserelementare am Mystralsee östlich vom Steinkrallenpfad und südwestlich vom Splitterholzposten.","","Erkundet den Pavillon am Mystralsee, der den nahen Außenposten der Allianz überblickt.","","Kehrt zu Mastok Wutfauch im Splitterholzposten im Eschental zurück."}}
D[26] = {"Eine wertvolle Lektion",{"Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung."}}
D[27] = {"Eine wertvolle Lektion",{"Sprecht mit Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung."}}
D[28] = {"Prüfung des Sees",{"Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.","","Ihr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}}
D[29] = {"Prüfung des Sees",{"Sucht ein Schreinschmuckstück im See von Elune'ara und bringt es zum Schrein von Remulos im Nordwesten der Mondlichtung. Wenn Ihr dort seid, benutzt das Schreinschmuckstück.","","Ihr müsst anschließend mit Tajarri am Schrein sprechen, um die Prüfung abzuschließen."}}
D[30] = {"Prüfung des Seelöwen",{"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserbelastbarkeit. Sprecht mit den Einwohnern der Mondlichtung, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.","","Formt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.","","Bringt den zusammengefügten Anhänger zu Dendrite Sternenschauer im Dorf Nachthafen auf der Mondlichtung."}}
D[31] = {"Wassergestalt",{"Kehrt nach Donnerfels zurück und zeigt Turak Runentotem den Anhänger des Seelöwen."}}
D[32] = {"Aufstieg der Silithiden",{"Bringt den Bericht nach Orgrimmar zu Zilzibin Tomtom."}}
D[33] = {"Wölfe an der Grenze",{"Bringt Eagan Pelzschneider, den Ihr vor der Abtei von Nordshire findet, 8 Pelze von erkrankten Wölfen."}}
D[34] = {"Ein ungebetener Gast",{"Martie Jainrose aus Seenhain möchte, dass Ihr Stopfwanst tötet. Bringt ihr den Hauer des Ebers zum Beweis."}}
D[35] = {"Weitere Sorgen",{"Marschall Dughan möchte, dass Ihr mit Wache Thomas sprecht."}}
D[36] = {"Westfalleintopf",{"Verna Brauenwirbel möchte, dass Ihr ihr Rezept für Westfalleintopf bei Salma Saldean abliefert."}}
D[37] = {"Suche nach den vermissten Wachen",{"Wache Thomas möchte, dass Ihr den Fluss in Richtung Norden nach Rolf und Malakai, den beiden vermissten Wachen, absucht."}}
D[38] = {"Westfalleintopf",{"Salma Saldean möchte 3 Stücke sehniges Geierfleisch, 3 Geiferzahnschnauzen, 3 Murlocaugen und 3 Okraschoten."}}
D[39] = {"Zustellung von Thomas' Bericht",{"Erstattet Marschall Dughan in Goldhain Bericht."}}
D[40] = {"Gefahr aus dem Wasser",{"Remy \"Zweifach\" möchte, dass Ihr in Goldhain mit Marschall Dughan sprecht."}}
D[45] = {"Rolfs Schicksal",{"Durchsucht das Murlocdorf nach Rolf - oder nach Anzeichen für seinen Tod."}}
D[46] = {"Kopfgeld auf die Murlocs",{"Bringt 8 zerrissene Murlocflossen zu Wache Thomas, den ihr an der östlichen Brücke von Elwynn findet."}}
D[47] = {"Tauschhandel mit Goldstaub",{"Bringt 10 Einheiten Goldstaub nach Goldhain zu Remy \"Zweifach\". Goldstaub findet Ihr bei den Kobolden im Wald von Elwynn."}}
D[48] = {"Goldbrauner Samt",{"Bringt Schnapsbart Donnerbräu Wasser von der Heiligen Quelle."}}
D[49] = {"Goldbrauner Samt",{"Schnapsbart Donnerbräu möchte einen Sack Gerste, einen Sack Roggen und einen Sack Korn haben."}}
D[50] = {"Goldbrauner Samt",{"Schnapsbart Donnerbräu braucht Echtsilber."}}
D[51] = {"Goldbrauner Samt",{"Bringt Schnapsbart Donnerbräu den Ast eines Bergahorns."}}
D[52] = {"Grenzschutz",{"Tötet 8 Streuner und 5 junge Waldbären und kehrt dann zu Wache Thomas an der östlichen Brücke von Elwynn zurück."}}
D[53] = {"Goldbrauner Samt",{"Bringt Schnapsbart Donnerbräu ein verkohltes Eichenbündel."}}
D[54] = {"Meldung in Goldhain",{"Liefert Marschall McBrides Dokumente bei Marschall Dughan in Goldhain ab."}}
D[55] = {"Morbent Teufel",{"Verwendet Morbents Bann gegen Morbent Teufel, tötet Morbent Teufel und bringt Morbents Bann anschließend zu Sven in dessen Lager zurück."}}
D[56] = {"Die Nachtwache",{"Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 8 Skelettkrieger und 6 Skelettmagier tötet."}}
D[57] = {"Die Nachtwache",{"Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr 15 Skelettscheusale und 15 Skelettschrecken tötet."}}
D[58] = {"Die Nachtwache",{"Kommandantin Althea Schwarzhaupt aus Dunkelhain möchte, dass Ihr im östlichen Mausoleum von Rabenflucht 20 Seuchenverbreiter tötet."}}
D[59] = {"Rüstung aus Tuch und aus Leder",{"Gebt Sara Roderwald den Rüstungsgutschein der Armee von Sturmwind."}}
D[60] = {"Koboldkerzen",{"Bringt 8 große Kerzen nach Goldhain zu William Pestle."}}
D[61] = {"Lieferung nach Sturmwind",{"Bringt Williams Lieferung in den Handelsdistrikt von Sturmwind zu Morgan Pestle."}}
D[62] = {"Die Tiefenschachtmine",{"Erforscht die Tiefenschachtmine und kehrt dann nach Goldhain zu Marschall Dughan zurück."}}
D[63] = {"Ruf des Wassers",{"Besiegt die verderbte Wassermanifestation und legt die Armschienen der verderbten Manifestation und die verbleibenden Tropfen reinsten Wassers im Silberwald auf die Kohlenpfanne von Immerquell."}}
D[64] = {"Das vergessene Erbstück",{"Bauer Brauenwirbel möchte, dass Ihr seine Taschenuhr holt. Sie befindet sich im Kleiderschrank des Bauernhauses auf der Kürbisfarm im Westen."}}
D[65] = {"Die Bruderschaft der Defias",{"Gryan Starkmantel möchte, dass Ihr in Seenhain mit Wiley sprecht."}}
D[66] = {"Die Legende von Stalvan",{"Sucht Amtmann Daltry im Rathaus von Dunkelhain auf."}}
D[67] = {"Die Legende von Stalvan",{"Begebt Euch zur Schule in Mondbruch und bringt Amtmann Daltry alle neuen Informationen über Stalvan Dunstmantel."}}
D[68] = {"Die Legende von Stalvan",{"Bringt Amtmann Daltry den verstaubten, nie abgeschickten Brief."}}
D[69] = {"Die Legende von Stalvan",{"Begebt Euch zum Gasthaus Zur Höhle des Löwen und fragt dort nach, ob jemand schon einmal den Namen Stalvan gehört hat."}}
D[70] = {"Die Legende von Stalvan",{"Holt Stalvans niemals zugestellten Brief aus der Truhe und liefert ihn im Kanaldistrikt von Sturmwind ab."}}
D[71] = {"Meldung an Thomas",{"Bringt die Medaillons von Rolf und Malakai zu Wache Thomas an die östliche Brücke von Elwynn."}}
D[72] = {"Die Legende von Stalvan",{"Durchsucht die verpackten Besitztümer nach Hinweisen."}}
D[74] = {"Die Legende von Stalvan",{"Die zerrissene Tagebuchseite, die Ihr gefunden habt, gibt Euch den nächsten Hinweis."}}
D[75] = {"Die Legende von Stalvan",{"Marschall Haggard möchte, dass Ihr in der Kiste oben nach der verblassten Tagebuchseite sucht."}}
D[76] = {"Die Jaspismine",{"Erforscht die Jaspismine und kehrt dann nach Goldhain zu Marschall Dughan zurück, um ihm Bericht zu erstatten."}}
D[77] = {"Eine schwierige Situation",{"Holt 10 Flaschen Hinterländer Honigwein aus den Kisten, die sich rund um den verlassenen Stützpunkt der Horde am Lauerfels befinden."}}
D[78] = {"Die Legende von Stalvan",{"Bringt die verblasste Tagebuchseite zu Schankwart Smitts nach Dunkelhain im Dämmerwald."}}
D[79] = {"Die Legende von Stalvan",{"Bringt Kommandant Schwarzhaupt die schlammverschmierte Seite."}}
D[80] = {"Die Legende von Stalvan",{"Zeigt Amtmann Daltry die blutbefleckte Tagebuchseite."}}
D[81] = {"Weinlieferung",{"Liefert das Fass nach Orgrimmar an Dran Droffers."}}
D[82] = {"Erkundung des Giftigen Unterschlupfes",{"Bringt fünf Centipaarinsektenteile vom Giftigen Unterschlupf nach Gadgetzan zum Alchemisten Stößelbruch."}}
D[83] = {"Rote Leinenwaren",{"Bringt 6 rote Leinenkopftücher ins Holzfällerlager des Osttals zu Sara Roderwald."}}
D[84] = {"Zurück zu Billy",{"Bringt die Schweinebauchpastete zu Billy Maclure in den Weinbergen der Maclures."}}
D[85] = {"Die verlorene Halskette",{"Sprecht mit Billy Maclure."}}
D[86] = {"Pastete für Billy",{"Bringt 4 Brocken Eberfleisch zu Tantchen Bernice Steinfeld auf den Hof der Steinfelds."}}
D[87] = {"Goldzahn",{"Bringt Berenices Halskette auf den Hof der Steinfelds zu Tantchen Berenice Steinfeld."}}
D[88] = {"Prinzessin muss sterben!",{"Tötet Prinzessin, nehmt ihr Halsband an Euch und bringt es zu Mutter Steinfeld auf den Hof der Steinfelds."}}
D[89] = {"Die Immerruhbrücke",{"Bringt 5 Eisenspitzen und 5 Eisennieten nach Seenhain zu Großknecht Oslow."}}
D[90] = {"Gewürzter Wolfskebab",{"Beschafft Euch 10 magere Wolfflanken und Würzkräuter aus Sturmwind und kehrt dann zu Küchenchef Grual nach Dunkelhain zurück."}}
D[91] = {"Das Gesetz des Solomon",{"Bringt 10 Schattenfellanhänger ins Rathaus von Seenhain zu Büttel Conacher."}}
D[92] = {"Rotkammgulasch",{"Küchenchefin Breanna aus Seenhain möchte 5 Stücke zähes Kondorfleisch, 5 große Geiferzahnschnauzen und 5 Portionen knuspriges Spinnenfleisch."}}
D[93] = {"Schwärzliche Krebsküchlein",{"Beschafft 6 klebrige Spinnenbeine und bringt sie nach Dunkelhain zu Küchenchef Grual."}}
D[94] = {"Ein wachsames Auge",{"Bringt die Glyphe von Azora zur Löwenstatue in der Nähe des Turms von Ilgalar im Rotkammgebirge."}}
D[95] = {"Svens Rache",{"Begebt Euch zu Svens Hof und findet heraus, was hinter dem alten Baumstumpf vergraben wurde."}}
D[96] = {"Ruf des Wassers",{"Bringt den Splitter des Wassers zu Islen Wasserdeuter am Tidustritt im Brachland."}}
D[97] = {"Die Legende von Stalvan",{"Berichtet Kommandant Schwarzhaupt die Neuigkeiten."}}
D[98] = {"Die Legende von Stalvan",{"Tötet Stalvan Dunstmantel und zeigt Madame Eva den Ring seiner Familie."}}
D[99] = {"Arugals Torheit",{"Bringt Dalar Morgenweber 6 Lohenscheitfesseln zum Grabmal."}}
D[100] = {"Ruf des Wassers",{"Sprecht mit der schwachen Wassermanifestation am nördlichen Gezeitenstrom im Silberwald."}}
D[101] = {"Das Totem des Gegenschlages",{"Bringt 10 Ghulfangzähne, 10 Skelettfinger und 5 Phiolen Spinnengift nach Dunkelhain zu Madame Eva."}}
D[102] = {"Auf Patrouille durch Westfall",{"Bringt 8 Gnolltatzen auf die Späherkuppe zu Hauptmann Danuvin."}}
D[103] = {"Bewahrer der Flamme",{"Bringt 5 Fläschchen Öl zu Kapitän Grausohn beim Leuchtturm von Westfall."}}
D[104] = {"Bedrohung an der Küste",{"Bringt Kapitän Grausohn am Leuchtturm von Westfall eine Schuppe von Trübauge dem Alten."}}
D[105] = {"Weh dir, Andorhal",{"Bringt den Splitter von Arajs Phylakterium zu Hochexekutor Derrington ins Bollwerk in den westlichen Pestländern."}}
D[106] = {"Junge Liebende",{"Gebt Tommy Joe Steinfeld Maybells Liebesbrief."}}
D[107] = {"Nachricht an William",{"Bringt Oma Steinfelds Nachricht zu William Pestle."}}
D[109] = {"Meldung bei Gryan Starkmantel",{"Sprecht mit Gryan Starkmantel. Normalerweise findet man ihn im Steinturm auf der Späherkuppe, ein kleines Stückchen von der Straße weg, mitten in Westfall."}}
D[110] = {"Insektenteil-Analyse",{"Begebt Euch nach Gadgetzan zu Alchemist Stößelbruch und erkundigt Euch nach der Analyse der Insektenteile."}}
D[111] = {"Gespräch mit Oma",{"Sprecht mit Oma Steinfeld."}}
D[112] = {"Die Suche nach dem Tang",{"Bringt 4 Kristalltangwedel nach Goldhain zu William Pestle."}}
D[113] = {"Insektenteil-Analyse",{"Bringt den Bericht nach Gadgetzan zum Leitenden Feldmesser Rutenwünschels. Lasst Euch von ihm eine Kopie des Berichts geben, wie Alchemist Stößelbruch gefordert hat."}}
D[114] = {"Die Flucht",{"Bringt Maybell Maclure den Unsichtbarkeitsschnaps."}}
D[115] = {"Schattenmagie",{"Bringt 3 Mitternachtskugeln nach Seenhain zu Marschall Marris."}}
D[116] = {"Trockene Zeiten",{"Barkeeper Daniels aus Seenhain braucht ein Fässchen Donnerbräu Lagerbier, ein Fässlein Merlot, eine Flasche Fusel und einen Schlauch mit süßem Rum."}}
D[117] = {"Donnerbräu",{"Bringt Schnapsbart Donnerbräu 5 Hopfen, damit er sein besonderes Bier brauen kann."}}
D[118] = {"Der Preis für Hufeisen",{"Bringt Verners Nachricht zu Schmied Argus nach Goldhain im Wald von Elwynn."}}
D[119] = {"Zurück zu Verner",{"Kehrt zu Verner Gutmark nach Seenhain im Rotkammgebirge zurück. Gebt ihm die Kiste mit Hufeisen."}}
D[120] = {"Botschaft nach Sturmwind",{"Magistrat Solomon hat Euch einen Bericht übergeben, der bei General Marcus Jonathan in Sturmwind abgeliefert werden muss. Der Richter möchte, dass Ihr zu ihm zurückkehrt, sobald Ihr die Nachricht zugestellt habt."}}
D[121] = {"Botschaft nach Sturmwind",{"Bringt General Marcus Jonathans Antwortschreiben nach Seenhain zu Magistrat Solomon."}}
D[122] = {"Bauchschuppen",{"Sammelt 6 Welpenbauchschuppen von schwarzen Großdrachenwelpen ein und bringt sie ins Rotkammgebirge zu Verner Gutmark."}}
D[123] = {"Der Sammler",{"Begebt Euch zu Marschall Dughan nach Goldhain und gebt ihm den Zeitplan des Sammlers."}}
D[124] = {"Das Bellen der Gnolle",{"Tötet 10 Schläger der Rotkammgnolle und 8 Mystiker der Rotkammgnolle und kehrt anschließend zu Verner Gutmark zurück."}}
D[125] = {"Die verlorenen Werkzeuge",{"Großknecht Oslow aus Seenhain möchte, dass Ihr seinen Werkzeugkasten vom Grunde des Immerruhsees heraufholt."}}
D[126] = {"Geheul in den Hügeln",{"Bringt Jaulers Tatze nach Seenhain zu Verner Gutmark."}}
D[127] = {"Fischhandel",{"Bringt 10 gefleckte Sonnenfische nach Seenhain zu Dockmeister Baren."}}
D[128] = {"Kopfgeld auf den Schwarzfelsklan",{"Tötet 15 Helden des Schwarzfels, dann erhaltet Ihr von Wache Howe aus Seenhain eine Belohnung."}}
D[129] = {"Ein geschenktes Mittagessen",{"Bringt Parkers Mittagessen zu Wache Parker. Er ist auf der Straße nach Dunkelhain auf Patrouille."}}
D[130] = {"Besuch im Kräuterladen",{"Sprecht mit der Kräuterkundigen des Rotkammgebirges, Martie Jainrose."}}
D[131] = {"Narzissen für eine Dame",{"Gebt Darcy den Narzissenstrauß."}}
D[132] = {"Die Bruderschaft der Defias",{"Bringt Wileys Nachricht nach Westfall zu Gryan Starkmantel."}}
D[133] = {"Ein Ghulbildnis",{"Sammelt 7 Ghulrippen und bringt sie zu Calvinius in seiner Hütte."}}
D[134] = {"Ogerdiebe",{"Bringt Calvinius' Kiste zu Calvinius."}}
D[135] = {"Die Bruderschaft der Defias",{"Bringt Wileys Nachricht nach Sturmwind zu Mathias Shaw."}}
D[136] = {"Käpt'n Sanders' versteckter Schatz",{"Findet Käpt'n Sanders Schließkiste und durchsucht sie, um den nächsten Hinweis zu erhalten."}}
D[138] = {"Käpt'n Sanders' versteckter Schatz",{"Findet das alte Fass in der Nähe des verfallenen Kamins und durchsucht es nach Eurem nächsten Hinweis."}}
D[139] = {"Käpt'n Sanders' versteckter Schatz",{"Durchsucht den leeren Henkelkrug neben der Windmühle nach dem nächsten Hinweis."}}
D[140] = {"Käpt'n Sanders' versteckter Schatz",{"Findet Käpt'n Sanders Truhe und öffnet sie. Darin befindet sich Eure Belohnung."}}
D[141] = {"Die Bruderschaft der Defias",{"Bringt Shaws Bericht nach Westfall zu Gryan Starkmantel."}}
D[142] = {"Die Bruderschaft der Defias",{"Spürt den Boten der Defias in Westfall auf und bringt die Nachricht, die er bei sich hat, zu Starkmantel."}}
D[143] = {"Botschaft nach Westfall",{"Magistrat Solomon möchte, dass Ihr sein Hilfegesuch nach Westfall zu Gryan Starkmantel bringt."}}
D[144] = {"Botschaft nach Westfall",{"Kehrt mit Gryan Starkmantels Antwort zu Magistrat Solomon zurück."}}
D[145] = {"Botschaft nach Dunkelhain",{"Magistrat Solomon möchte, dass Ihr einen Brief zu Lord Schwarzhaupt nach Dunkelhain bringt."}}
D[146] = {"Botschaft nach Dunkelhain",{"Kehrt mit Lord Schwarzhaupts Antwortschreiben zu Magistrat Solomon zurück."}}
D[147] = {"Menschenjagd",{"Findet den \"Sammler\" und tötet ihn, dann kehrt mit dem Ring des Sammlers zu Marschall Dughan zurück."}}
D[148] = {"Lieferung aus Dunkelhain",{"Sprecht mit Madame Eva."}}
D[149] = {"Geisterhaarfaden",{"Bringt der blinden Mary den spektralen Kamm."}}
D[150] = {"Murlocwilderer",{"Bringt 8 Murlocflossen nach Seenhain zu Dockmeister Baren."}}
D[151] = {"Die arme Graumähne",{"Verna Brauenwirbel in Westfall möchte, dass Ihr ihr 8 Hände voll Hafer bringt."}}
D[152] = {"Ärger an der Küste",{"Tötet 7 Gezeitenjäger, 7 Krieger, 7 Orakel sowie 7 Küstenläufer und kehrt dann zu Kapitän Grausohn beim Leuchtturm von Westfall zurück."}}
D[153] = {"Rote Lederkopftücher",{"Bringt 15 rote Lederkopftücher auf die Späherkuppe zu Späher Galiaan."}}
D[154] = {"Rückkehr mit dem Kamm",{"Bringt den Geisterhaarkamm zu Madame Eva nach Dunkelhain."}}
D[155] = {"Die Bruderschaft der Defias",{"Eskortiert den Verräter der Defias zum Geheimversteck der Defiasbruderschaft. Sobald der Verräter der Defias Euch gezeigt hat, wo sich van Cleef und seine Männer aufhalten, kehrt Ihr mit der Information zu Gryan Starkmantel zurück."}}
D[156] = {"Das Sammeln von Faulblüten",{"Sammelt 8 Faulblüten und bringt sie nach Dunkelhain zu Schankwart Smitts."}}
D[157] = {"Abliefern des Fadens",{"Bringt Calvinius den Geisterhaarfaden in seine Hütte nördlich des Friedhofs von Rabenflucht."}}
D[158] = {"Zombiesaft",{"Sprecht mit Schankwart Smitts."}}
D[159] = {"Saftlieferung",{"Bringt Calvinius den Zombiesaft in seine Hütte."}}
D[160] = {"Ein Brief für den Bürgermeister",{"Bringt Calvinius' Brief zu Ello Schwarzhaupt, dem Bürgermeister von Dunkelhain."}}
D[161] = {"Eine dunkle Bedrohung",{"Chefingenieur Hinderweir möchte, dass Ihr das sonderbar riechende Pulver zu Ashlan Schmunzelstein, dem Sprengstoffexperten, bringt. Er befindet sich in Dun Modr im Sumpfland."}}
D[162] = {"Aufstieg der Silithiden",{"Bringt den Bericht über Insektenanalyse nach Darnassus zu Gracina Glaubensmacht."}}
D[163] = {"Rabenflucht",{"Findet heraus, was in Rabenflucht umgeht."}}
D[164] = {"Lieferung an Sven",{"Liefert die Vorräte an Sven."}}
D[165] = {"Der Einsiedler",{"Schaut in der Nähe des Friedhofs von Rabenflucht nach dem alten Mann in der Hütte."}}
D[166] = {"Die Bruderschaft der Defias",{"Tötet Edwin van Cleef und bringt seinen Kopf zu Gryan Starkmantel."}}
D[167] = {"Oh Bruder...",{"Bringt Großknecht Distelklettes Abzeichen der Forscherliga nach Sturmwind zu Wilder Distelklette."}}
D[168] = {"Die Suche nach Andenken",{"Beschafft 4 Gewerkschaftsausweise und bringt sie nach Sturmwind zu Wilder Distelklette."}}
D[169] = {"GESUCHT: Gath'Ilzogg",{"Erledigt Gath'Ilzogg und bringt seinen Kopf zu Magistrat Solomon in Seenhain, um die Belohnung zu erhalten."}}
D[170] = {"Eine neue Bedrohung",{"Balir Frosthammer möchte, dass Ihr 6 Troggs der Felsenkiefer und 6 bullige Troggs der Felsenkiefer tötet."}}
D[171] = {"Tageseltern der Allianz",{"Bringt Euren Schützling in das Waisenhaus von Sturmwind zurück, indem Ihr die Pfeife des Menschenwaisenkindes an Waisenmatrone Nachtigall im Kathedralenviertel übergebt."}}
D[172] = {"Die Kinderwoche",{"Benutzt die Pfeife des Orcwaisenkindes um während der Kinderwoche mit Eurem Schützling zu sprechen."}}
D[173] = {"Worgen in den Wäldern",{"Tötet für Calor aus Dunkelhain 6 Schattenwirker der Nachtheuler."}}
D[174] = {"Der Blick zu den Sternen",{"Viktori Prism'Antras aus Dunkelhain möchte, dass Ihr ihm eine Bronzeröhre bringt."}}
D[175] = {"Der Blick zu den Sternen",{"Findet Mary und überredet sie, einen Gegenstand mit reflektierender Oberfläche zu Viktoris Projekt beizusteuern."}}
D[176] = {"GESUCHT: \"Hogger\"",{"Erschlagt den Gnoll Hogger und bringt seine gewaltige Gnollklaue zu Marschall Dughan."}}
D[177] = {"Der Blick zu den Sternen",{"Nehmt dem irrsinnigen Ghul den Handspiegel der blinden Mary ab und gebt ihn Viktori in Dunkelhain."}}
D[178] = {"Wiederbeschaffung für Theocritus",{"Bringt den verblassten Schattenfellanhänger zu Theocritus, dem Magier. Er befindet sich im Turm von Azora im Wald von Elwynn."}}
D[179] = {"Zwergenausstatter",{"Sten Starkarm hätte gern 8 Stücke zähes Wolfsfleisch."}}
D[180] = {"GESUCHT: Leutnant Fangor",{"Tötet Leutnant Fangor und kehrt mit seiner Tatze zu Magistrat Solomon nach Seenhain zurück."}}
D[181] = {"Der Blick zu den Sternen",{"Findet Zzarc'Vul im südlichen Ogerhort des Dämmerwalds und bringt sein Monokel zu Viktori nach Dunkelhain."}}
D[182] = {"Die Trollhöhle",{"Grelin Weißbart möchte, dass Ihr 10 Trollwelpen der Frostmähnen tötet."}}
D[183] = {"Der Eberjäger",{"Talin Kühnauge möchte, dass Ihr 8 kleine Klippeneber tötet."}}
D[184] = {"Brauenwirbels Urkunde",{"Bringt Brauenwirbels Besitzurkunde zu Bauer Brauenwirbel."}}
D[185] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 junge Schlingendorntiger tötet."}}
D[186] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 Schlingendorntiger tötet."}}
D[187] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr 10 alte Schlingendorntiger tötet."}}
D[188] = {"Beherrschen der Tigerjagd",{"Ajeck Rouack von Nesingwarys Expedition möchte, dass Ihr Sin'Dall tötet und mit ihrer Tatze zurückkehrt."}}
D[189] = {"Ohren der Blutskalpe",{"Verschafft Euch 15 Ohren der Blutskalpe und bringt sie Kebok in Beutebucht."}}
D[190] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 junge Panther tötet."}}
D[191] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Panther tötet."}}
D[192] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr 10 Schattentatzenpanther tötet."}}
D[193] = {"Beherrschen der Pantherjagd",{"Sire S. J. Erlgadin von Nesingwarys Expedition möchte, dass Ihr ihm den Fangzahn von Bhag'thera bringt."}}
D[194] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary Jr. möchte, dass Ihr 10 Schlingendornraptoren tötet."}}
D[195] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary Jr. möchte, dass Ihr 10 Schmetterschwanzraptoren tötet."}}
D[196] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary Jr. möchte, dass Ihr 10 Dschungelpirscher tötet."}}
D[197] = {"Beherrschen der Raptorenjagd",{"Hemet Nesingwary Jr. möchte, dass Ihr Tethis tötet, einen schwer fassbaren, gefährlichen Raptoren des Schlingendorntals."}}
D[198] = {"Vorräte für den Gefreiten Thorsen",{"Liefert die verschiedenen Goblinvorräte bei dem Gefreiten Thorsen ab."}}
D[199] = {"Eine dunkle Bedrohung",{"Kehrt zu Chefingenieur Hinderweir zurück und zeigt ihm den Hinweis, den Ihr entdeckt habt."}}
D[200] = {"Buchhalter Herod",{"Findet Buchmacher Herods Aufzeichnungen."}}
D[201] = {"Untersuchung des Lagers",{"Lokalisiert das Jägerlager und teilt dann Krazek in Beutebucht mit, wo es sich befindet."}}
D[202] = {"Colonel Kurzen",{"Tötet 6 von Kurzens Elitesoldaten, 4 von Kurzens Stabschefs und bringt Kurzens Kopf ins Rebellenlager zu Leutnant Doren."}}
D[203] = {"Die zweite Rebellion",{"Tötet 15 von Kurzens Dschungelkämpfern.","","Kehrt ins Rebellenlager zu Unteroffizier Yohwa zurück."}}
D[204] = {"Schlechte Medizin",{"Bringt Unteroffizier Yohwa im Rebellenlager 7 Dschungelarzneien und 1 Giftfarnextrakt."}}
D[205] = {"Trollhexerei",{"Bringt Bruder Nimetz 4 Fetische der Schädelspalter ins Rebellenlager."}}
D[206] = {"Mai'Zoth",{"Bringt das Gedankenauge zu Bruder Nimetz ins Rebellenlager."}}
D[207] = {"Das Geheimnis um Kurzen",{"Findet die 4 Schrifttafeln und bringt ihre Legenden zu Bruder Nimetz zurück."}}
D[208] = {"Großwildjagd",{"Hemet Nesingwary Jr. möchte, dass Ihr ihm den Kopf von König Bangalash, dem großen weißen Tiger, bringt."}}
D[209] = {"Hauer der Schädelspalter",{"Besorgt 18 Hauer der Schädelspalter und bringt sie zu Kebok."}}
D[210] = {"Kochen mit Krazek",{"Bringt Krazeks Spezialtopf zu Krazek, dem Goblin."}}
D[211] = {"Weh dir, Andorhal",{"Bringt den Splitter von Arajs Phylakterium zu Kommandant Ashlam Ehrenschlag am Zugwindlager in den westlichen Pestländern."}}
D[212] = {"Eine kalte Mahlzeit",{"Tötet einen Kaltaugenbasilisken, beschafft Euch einen gekühlten Basiliskenschenkel und bringt ihn Angus Stern im Blauen Eremiten."}}
D[213] = {"Feindliche Übernahme",{"Beschafft 8 gerommelte Kristalle und bringt sie nach Beutebucht zu Kebok."}}
D[214] = {"Rote Seidenkopftücher",{"Späherin Riell am Turm auf der Späherkuppe möchte, dass Ihr ihr 10 rote Seidenkopftücher bringt."}}
D[215] = {"Geheimnisse im Dschungel",{"Sprecht im Rebellenlager mit Leutnant Doren."}}
D[216] = {"Hart auf hart",{"Schaltet 8 Rächer der Distelfelle und 8 Schamanen der Distelfelle aus. Man findet sie am häufigsten östlich vom Zoramstrand im Lager der Distelfelle. Wenn das erledigt ist, kehrt zu Karang Amakkar beim Außenposten von Zoram'gar im Eschental zurück."}}
D[217] = {"Verteidigung der Länder des Königs",{"Tötet den Anführer der Troggs, Grawmug, sowie seine beiden Wachen, Knirscher und Muskelprotz, und erstattet dann Hauptmann Rugelfuß im südlichen Wachturm Bericht."}}
D[218] = {"Das gestohlene Tagebuch",{"Grelin Weißbart möchte, dass Ihr Grik'nir den Kalten tötet und ihm sein Tagebuch wiederbeschafft."}}
D[219] = {"Vermisst",{"Beschützt Korporal Keeshan auf dem Rückweg ins Rotkammgebirge."}}
D[220] = {"Ruf des Wassers",{"Bringt die Phiole mit reinstem Wasser zu Islen Wasserdeuter am Tidustritt im Brachland."}}
D[221] = {"Worgen in den Wäldern",{"Tötet für Calor aus Dunkelhain 12 Dunkelläufer der Nachtheuler."}}
D[222] = {"Worgen in den Wäldern",{"Tötet für Calor aus Dunkelhain 8 Faulreißer der Nachtheuler und 8 besudelte Nachtheuler."}}
D[223] = {"Worgen in den Wäldern",{"Bringt Calors Notiz zu Jonathan Treuwein."}}
D[224] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Feuerkiesel vom südlichen Wachturm möchte, dass Ihr 10 Splittersteintroggs und 10 Späher der Splittersteintroggs tötet."}}
D[225] = {"Das verwitterte Grab",{"Sprecht in Dunkelhain mit Sirra Von'Indi."}}
D[226] = {"Wölfe sind uns auf den Fersen",{"Tötet 12 verhungernde Terrorwölfe und 8 tollwütige Terrorwölfe und kehrt dann zu Lars in Svens Lager an der westlichen Grenze des Dämmerwalds zurück."}}
D[227] = {"Morgan Ladimore",{"Sprecht in Dunkelhain mit Kommandantin Althea Schwarzhaupt."}}
D[228] = {"Mor'Ladim",{"Tötet Mor'Ladim und bringt seinen Schädel nach Dunkelhain zu Kommandantin Althea Schwarzhaupt."}}
D[229] = {"Die überlebende Tochter",{"Sprecht in Dunkelhain mit Behüterin Sarah Ladimore."}}
D[230] = {"Svens Lager",{"Bringt das Buch von Svens Hof zu Sven."}}
D[231] = {"Die Liebe einer Tochter",{"Bringt Sarah Ladimores Ring zu Morgan Ladimores Grab."}}
D[232] = {"Kurierdienst für Apothekerin Zinge",{"Bringt die Bestellung nach Unterstadt zu Alessandro Luca."}}
D[233] = {"Postbeförderung im Eisklammtal",{"Liefert den Stapel Briefe bei Talin Kühnauge im Eisklammtal ab."}}
D[234] = {"Postbeförderung im Eisklammtal",{"Liefert den Brief bei Grelin Weißbart im Eisklammtal ab."}}
D[235] = {"Die Jagd im Eschental",{"Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental."}}
D[236] = {"Verwüster auftanken",{"Belagerungsmeister Starkhand in der Tausendwinterfestung möchte, dass Ihr zum Flammenkessel geht und den Hordlern dort 10 Stück Immerglut abnehmt."}}
D[237] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Kieselwut im südlichen Wachturm möchte, dass Ihr 10 Schädelhauer der Splittersteintroggs und 10 Seher der Splittersteintroggs tötet und ihm anschließend Bericht erstattet."}}
D[238] = {"Kurierdienst für Apothekerin Zinge",{"Bringt das Feldprobenset nach Unterstadt zu Apothekerin Zinge."}}
D[239] = {"Hilfe für die Weststromgarnison",{"Begebt Euch zur Weststromgarnison und sprecht mit Stellvertreter Rainer."}}
D[240] = {"Rückkehr zu Bibbers",{"Kehrt mit den schwärzlichen Krebsküchlein zu Bibbers zurück."}}
D[243] = {"Auf ins Feld",{"Sprecht in Gadgetzan mit Chefingenieur Bilgenritzel über eine Kraftquelle für das Testset."}}
D[244] = {"Eindringende Gnolle",{"Erstattet Stellvertreter Feldon Bericht. Zu finden ist er an der Brücke südlich von Seenhain im Rotkammgebirge."}}
D[245] = {"Gefahr auf acht Beinen",{"Erledigt 15 Zwerggiftweberspinnen und meldet Euch dann wieder bei Behüter Dodds im Dämmerwald."}}
D[246] = {"Einschätzung der Gefahr",{"Tötet 10 Bastarde der Rotkammgnolle und 6 Wilderer der Rotkammgnolle und meldet Euch anschließend wieder bei Stellvertreter Feldon in Seenhain."}}
D[247] = {"Die Jagd ist abgeschlossen"}
D[248] = {"Weitere Beobachtungen",{"Steigt in den unversehrten Wachturm neben der Burg Steinwacht im Rotkammgebirge hinauf.","","Findet einen passenden Behälter für die Glyphe von Azora und legt diese dort ab."}}
D[249] = {"Morganth",{"Besiegt Morganth.","","Bringt seinen Schattenanhänger zu Theocritus am Turm von Azora im Wald von Elwynn."}}
D[250] = {"Eine dunkle Bedrohung",{"Untersucht den Bereich um die östliche Dammrampe und bringt Chefingenieur Hinderweir einen Hinweis, der Auskunft darüber geben könnte, was die Dunkeleisenzwerge vorhaben."}}
D[251] = {"Übersetzung von Calvinius' Notiz",{"Bringt den Brief an Ello zu Sirra Von'Indi."}}
D[252] = {"Übersetzung für Ello",{"Bringt Lord Ello Schwarzhaupt den übersetzten Brief."}}
D[253] = {"Braut des Einbalsamierers",{"Findet Elizas Grab. Beschafft das Herz des Einbalsamierers, das sie in sich trägt, und kehrt zu Ello Schwarzhaupt zurück."}}
D[254] = {"Graben in der Erde"}
D[255] = {"Söldner",{"Magistrat Stumpfnase aus Thelsamar hat Euch angeheuert, um 4 Oger der Mo'grosh, 4 Schläger der Mo'grosh und 4 Vollstrecker der Mo'grosh zu töten."}}
D[256] = {"GESUCHT: Chok'sul",{"Tötet Chok'sul und bringt Magistrat Stumpfnase in Thelsamar seinen Kopf."}}
D[257] = {"Das Prahlen eines Jägers",{"Tötet 6 Bergbussarde und kehrt innerhalb von 15 Minuten zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück."}}
D[258] = {"Die Herausforderung eines Jägers",{"Tötet 5 alte Bergeber und kehrt innerhalb von 12 Minuten zu Daryl dem Jüngling in die Jagdhütte der Weltenwanderer zurück."}}
D[261] = {"Auf dem Scharlachroten Pfad",{"Vernichtet 30 untote Verheerer und kehrt dann zu Bruder Anton auf die Nijelspitze zurück."}}
D[262] = {"Die Schattengestalt",{"Nehmt das Buch, das Ihr auf Svens Hof gefunden habt, und zeigt es den Einwohnern von Dunkelhain."}}
D[263] = {"Verteidigung der Länder des Königs",{"Gebirgsjäger Wallbang im südlichen Wachturm möchte, dass Ihr 10 Schamanen der Splittersteintroggs und 10 Knochenknacker der Splittersteintroggs tötet."}}
D[264] = {"Bis dass der Tod uns scheidet",{"Legt Clarices Anhänger auf Yurivs Grab in Silberwald."}}
D[265] = {"Die Schattensuche geht weiter",{"Überprüft, ob andere Einwohner Hinweise auf die schattenhafte Gestalt haben."}}
D[266] = {"Nachforschungen im Gasthaus",{"Sucht im Gasthaus nach Hinweisen auf die schattenhafte Gestalt."}}
D[267] = {"Die Bedrohung durch die Troggs",{"Bringt Hauptmann Rugelfuß im südlichen Wachturm 8 Troggsteinzähne."}}
D[268] = {"Rückkehr zu Sven",{"Kehrt mit Bibbers' vollständigem Tagebuch zu Sven zurück."}}
D[269] = {"Auf der Suche nach Weisheit",{"Gebt Bischof Heller in Sturmwind Bibbers' vollendetes Tagebuch."}}
D[270] = {"Die verlorene Flotte",{"Geht zum Hafen von Menethil im Sumpfland und sprecht mit Glorin Stahlbraue."}}
D[271] = {"Vyrins Rache",{"Tötet alte Rußtatze und zeigt Daryl dem Jüngling in der Jagdhütte der Weltenwanderer dann Euer Werk."}}
D[272] = {"Prüfung des Seelöwen",{"Sucht die Anhängerhälfte der Wasserbeweglichkeit und die Anhängerhälfte der Wasserbelastbarkeit. Sprecht mit den Einwohnern der Mondlichtung, um Hinweise darauf zu erhalten, wo sich diese Gegenstände befinden könnten.","","Formt den Anhänger des Seelöwen aus den beiden Anhängerhälften. Ihr müsst in der unmittelbaren Nähe des Schreins von Remulos sein, um dies zu tun.","","Bringt den zusammengefügten Anhänger zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung."}}
D[273] = {"Nachschub für die Ausgrabungsstätte",{"Sprecht mit Huldar."}}
D[274] = {"Eine dunkle Bedrohung",{"Ashlan Schmunzelstein möchte, dass Ihr zum Chefingenieur Hinderweir nach Loch Modan zurückkehrt und ihn von der neuen Entdeckung in Kenntnis setzt."}}
D[275] = {"Schwärendes Land",{"Tötet 8 Moorkrabbler und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}}
D[276] = {"Stapfende Pfoten",{"Tötet 15 Gnolle der Moosfelle sowie 10 Bastarde der Moosfelle und kehrt dann zu Rethiel dem Sumpfhüter im Sumpfland zurück."}}
D[277] = {"Feuer-Tabu",{"Bringt Rethiel dem Sumpfhüter 9 kunstlose Feuersteine."}}
D[278] = {"Eine dunkle Bedrohung",{"Chefingenieur Hinderweir möchte, dass Ihr Lauerergift, einen Kristall der Mo'grosh und eine Krokiliskenträne besorgt."}}
D[279] = {"Klauen aus der Tiefe",{"Tötet 12 Murlocs der Blaukiemen.","","Erschlagt Gobbler und nehmt Euch seinen Kopf.","","Bringt Gobblers Kopf zu Karl Boran in den Hafen von Menethil."}}
D[280] = {"Eine dunkle Bedrohung",{"Chefingenieur Hinderweir will, dass Ihr zum Fuß des Dammes hinunterschwimmt, das Pulverfässchen ausfindig macht und die Entschärfungsmixtur hineinrührt, um eine Explosion zu verhindern."}}
D[281] = {"Waren-Wiederbeschaffung",{"Durchsucht die Kisten und Fässer in den Murloclagern an der Küste."}}
D[282] = {"Senirs Beobachtungen",{"Sprecht mit Gebirgsjäger Thalos."}}
D[283] = {"Eine dunkle Bedrohung",{"Die Entschärfungsmixtur scheint gewirkt zu haben. Kehrt zu Chefingenieur Hinderweir zurück und berichtet ihm die guten Neuigkeiten."}}
D[284] = {"Die Suche geht weiter",{"Sucht nach der Statuette von Menethil."}}
D[285] = {"Suche in weiteren Hütten",{"Sucht weiter in den Hütten der Murlocs nach der Statuette von Menethil."}}
D[286] = {"Rückgabe der Statuette",{"Bringt Karl Boran im Hafen von Menethil im Sumpfland die Statuette von Menethil."}}
D[287] = {"Höhle der Frostmähnen",{"Erforscht die Höhle der Frostmähnen und tötet 5 Kopfjäger der Frostmähnen für Senir Weißbart in Kharanos."}}
D[288] = {"Die Dritte Flotte",{"Spendiert dem ersten Maat Fitzsimmons einen Krug Met."}}
D[289] = {"Die verfluchte Crew",{"Vernichtet 13 verfluchte Seeleute, 5 verfluchte Marinesoldaten und den ersten Maat Snellig. Bringt Snelligs Schnupftabakdose zum ersten Maat Fitzsimmons im Hafen von Menethil."}}
D[290] = {"Brechen des Fluchs",{"Besorgt den Geldkassettenschlüssel der INTREPID von Kapitän Halyndor.","","Verwendet den Schlüssel, um die Geldkassette der INTREPID zu öffnen."}}
D[291] = {"Die Berichte",{"Überbringt Senator Barin Rotstein in Eisenschmiede Senirs Bericht."}}
D[292] = {"Das Auge von Paleth",{"Bringt Glorin Stahlbraue im Hafen von Menethil im Sumpfland das verfluchte Auge von Paleth."}}
D[293] = {"Die Reinigung des Auges",{"Bringt Erzbischof Benedictus das verfluchte Auge von Paleth. Ihr findet Benedictus in der Kathedrale des Lichts, in der Stadt Sturmwind."}}
D[294] = {"Ormers Rache",{"Ormer Eisenzopf von der Whelgars Ausgrabungsstätte möchte, dass Ihr 10 scheckige Kreischer und 10 scheckige Raptoren tötet."}}
D[295] = {"Ormers Rache",{"Ormer Eisenzopf möchte, dass Ihr 10 scheckige Sensenklauen- und 10 scheckige Scharfzahnraptoren tötet und dann zu ihm zu Whelgars Ausgrabungsstätte zurückkommt."}}
D[296] = {"Ormers Rache",{"Ormer Eisenzopf von der Whelgars Ausgrabungsstätte möchte, dass Ihr Sarlatan tötet und mit einer seiner Krallen zu ihm zurückkehrt, sobald Ihr die Aufgabe erledigt habt."}}
D[297] = {"Götzen sammeln",{"Bringt Magmar Todesstreich 8 verzierte Steingötzen."}}
D[298] = {"Bericht über den Fortschritt der Ausgrabungen",{"Bringt Eisenbands Fortschrittsbericht zu Jern Hornhelm in Thelsamar."}}
D[299] = {"Enthüllung der Vergangenheit",{"Ausgrabungsleiter Whelgar wünscht, dass Ihr die Ausgrabungsstätte nach den 4 fehlenden Tafelfragmenten durchkämmt, Ados, Modr, Golm und Neru."}}
D[301] = {"Meldung in Eisenschmiede",{"Bringt Eisenbands Fortschrittsbericht zu Ausgrabungsleiter Sturmlanze."}}
D[302] = {"Pulver für Eisenband",{"Geht nach Thelsamar in Loch Modan und sprecht dort mit Jern Hornhelm."}}
D[303] = {"Der Dunkeleisenkrieg",{"Motley Garmason in Dun Modr möchte, dass Ihr 10 Dunkeleisenzwerge, 5 Tunnelgräber der Dunkeleisenzwerge, 5 Saboteure der Dunkeleisenzwerge und 5 Demolierer der Dunkeleisenzwerge tötet."}}
D[304] = {"Eine grausige Aufgabe",{"Tötet Balgaras den Niederträchtigen und bringt Langzopf dem Grimmigen vor Dun Modr sein Ohr."}}
D[305] = {"Auf der Suche nach dem Ausgrabungstrupp",{"Tarrel Felsweber möchte, dass Ihr zur Ausgrabungsstätte reist und dort Kontakt mit Merrin Felsweber aufnehmt."}}
D[306] = {"Auf der Suche nach dem Ausgrabungstrupp",{"Kehrt mit Merrins Nachricht zu Tarrel Felsweber zurück. Zu finden ist er im Hafen von Menethil im Sumpfland."}}
D[307] = {"Schmutzige Pfoten",{"Geht zur Silberbachmine und sucht 4 Sätze Minenarbeiterausstattung zusammen.","","Kehrt dann zu Gebirgsjäger Sturmlanze zurück."}}
D[308] = {"Jarvens Ablenkung"}
D[309] = {"Beschützen der Fracht",{"Stellt sicher, dass sowohl Miran als auch seine Warenlieferung sicher an der Ausgrabungsstätte ankommen und setzt dann Ausgrabungsleiter Eisenband davon in Kenntnis."}}
D[310] = {"Bittere Rivalen",{"Vertauscht im Keller der Brauerei Donnerbräu in Kharanos ein Fass Donnerbier mit einem Fass Gerstenbräu."}}
D[311] = {"Rückkehr zu Marleth",{"Bringt Marleth Gerstenbräu in Bräuhall das Fass mit Donnerbier."}}
D[312] = {"Tundra MacGranns gestohlene Vorräte",{"Holt Tundra MacGranns Trockenfleisch aus der gestohlenen Fleischtruhe in der Höhle von Eisbart dem Alten."}}
D[313] = {"Der Graufelsbau",{"Sammelt 8 Wendigomähnen und bringt sie Pilot Steinsegel."}}
D[314] = {"Die Herde beschützen",{"Rudra Bernruh möchte, dass Ihr Vagash erschlagt und einen seiner Fangzähne zu ihr auf den Widderhof bringt."}}
D[315] = {"Das perfekte Starkbier",{"Bringt Rejold Gerstenbräu in Bräuhall 6 Schimmerkräuter."}}
D[317] = {"Vorräte für Dampfstrahl",{"Sammelt 4 Brocken Eberfleisch und 2 dicke Bärenfelle und liefert sie bei Pilot Bellfiz in Stahlrosts Depot ab."}}
D[318] = {"Immerschimmer",{"Besorgt von Rejold Gerstenbräu in Bräuhall ein Fässlein Immerschimmer."}}
D[319] = {"Ein Gefallen für etwas Immerschimmer",{"Tötet 6 Eisklauenbären, 8 alte Klippeneber sowie 8 Schneeleoparden und kehrt dann zu Rejold Gerstenbräu nach Bräuhall zurück."}}
D[320] = {"Rückkehr zu Bellfiz",{"Gebt Pilot Bellfiz in Stahlrosts Depot das Fässlein mit Immerschimmer."}}
D[321] = {"Lichtgeschmiedetes Eisen",{"Durchsucht das Wrack der FISCHADLER im Sumpfland."}}
D[322] = {"Gesegnete Waffe",{"Bringt Grimand Elmore in Sturmwind die Kiste mit Lichtschmiedeblöcken."}}
D[323] = {"Bewährungsprobe",{"Vernichtet 15 Skeletträuber, 3 Skelettheiler sowie 3 Skelettwärter und kehrt danach zu Sven zurück."}}
D[324] = {"Die verlorenen Blöcke",{"Sammelt 5 Lichtschmiedeblöcke und kehrt dann zu Glorin Stahlbraue im Sumpfland zurück."}}
D[325] = {"Bewaffnet und bereit",{"Bringt Morbents Bann zu Sven im Dämmerwald."}}
D[328] = {"Der versteckte Schlüssel",{"Verwendet den kleinen Messingschlüssel, um Buchmacher Herods Geldkassette zu öffnen."}}
D[329] = {"Der entlarvte Spion",{"Bringt die schlammverschmierte Notiz zu Leutnant Doren im Rebellenlager."}}
D[330] = {"Patrouillen-Pläne",{"Sprecht mit Korporal Sethmann."}}
D[331] = {"Meldung bei Doren",{"Sprecht mit Leutnant Doren."}}
D[332] = {"Weinladen-Werbung",{"Geht zum Weingut Gallina und gebt Suzetta Gallina den Weingutschein, um eine kostenlose Flasche Wein zu erhalten."}}
D[333] = {"Harlan braucht Nachschub",{"Geht zur Schneiderei und Anpasserei am Kanal und bringt Rema Schneider Harlan Bagleys Stoffanforderung."}}
D[334] = {"Eine Lieferung für Thurman",{"Geht zum Konfektionsgeschäft Larson im Magierviertel von Sturmwind und gebt Thurman Schneider sein Nähkästchen."}}
D[335] = {"Ein nobles Bräu",{"Zardeth der Schwarzen Klaue möchte, dass Ihr ihm eine Tilloaträne aus Dunkelhain und eine Bisamwurzel aus dem Sumpfland bringt."}}
D[336] = {"Ein nobles Bräu",{"Bringt Lord Wischock in der Halle der Bittsteller das Schwarzklauenbier."}}
D[337] = {"Ein altes Geschichtsbuch",{"Bringt das Buch: \"Die Geschichte von Sturmwind\" in die Bibliothek von Sturmwind zurück."}}
D[338] = {"Die Grünen Hügel des Schlingendorntals",{"Sammelt die fehlenden Seiten des Manuskripts von \"Die Grünen Hügel des Schlingendorntals\". Wenn alle vier Kapitel vollständig sind, bringt sie zu Barnil zurück."}}
D[339] = {"Kapitel I",{"Bringt Barnil Steinkrug die Seiten 1, 4, 6 und 8 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel I zu vervollständigen."}}
D[340] = {"Kapitel II",{"Bringt Barnil Steinkrug die Seiten 10, 11, 14 und 16 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel II zu vervollständigen."}}
D[341] = {"Kapitel III",{"Bringt Barnil Steinkrug die Seiten 18, 20, 21 und 24 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel III zu vervollständigen."}}
D[342] = {"Kapitel IV",{"Bringt Barnil Steinkrug die Seiten 25, 26 und 27 von Nesingwarys \"Die Grünen Hügel des Schlingendorntals\", um Kapitel IV zu vervollständigen."}}
D[343] = {"Reden über Kraft",{"Geht in die königliche Bibliothek der Burg von Sturmwind und sprecht mit Milton Garbenbund. Er kann das Buch über Metallurgie für Euch finden, das Bruder Kristoff für seine Rede benötigt."}}
D[344] = {"Bruder Paxton",{"Sprecht mit Bruder Paxton in der Abtei von Nordhain."}}
D[345] = {"Tinten-Zutaten",{"Sprecht mit Großknecht Oslow in Seenhain und fragt ihn nach Rethbaneisenerz."}}
D[346] = {"Rückkehr zu Kristoff",{"Kehrt zu Bruder Kristoff auf den Kathedralenplatz zurück. Gebt ihm das Buch: \"Belastbarkeit von Eisen\"."}}
D[347] = {"Rethbanerz",{"Sammelt 5 Fuhren Rethbanerz und bringt sie Bruder Paxton in der Bibliothek von Nordhain."}}
D[348] = {"Schlingendornfieber",{"Sucht Hexendoktor Unbagwa und lasst ihn Mokk den Wilden beschwören. Bringt das Herz von Mokk zu Fin Fizrackett."}}
D[349] = {"Schlingendornfieber",{"temp text 02 - log"}}
D[350] = {"Auf einen alten Freund verlassen",{"Sprecht mit Elling Trias in Sturmwind."}}
D[351] = {"Findet OOX-17/TN!",{"Bringt das Notsignal zum Leitroboter von Glotz."}}
D[353] = {"Sturmlanzes Lieferung",{"Bringt das Päckchen für Sturmlanze zu Gebirgsjäger Sturmlanze am Loch Modan."}}
D[354] = {"Todesfälle in der Familie",{"Bringt Coleman Heller in Brill die sterblichen Überreste von Gregor, Nissa und Thurman."}}
D[355] = {"Gespräch mit Sevren",{"Sprecht mit Magistrat Sevren in Brill."}}
D[356] = {"Patrouille zur Rückendeckung",{"Tötet 8 blutende Schrecken und 8 wandernde Geister und meldet Euch dann wieder bei Linnea in ihrem Lager."}}
