D[894] = {"Samophlang",{"Verschafft Euch Zugang zur Steuerkonsole in der Forschungseinrichtung der Venture Company."}}
D[895] = {"GESUCHT: Baron Küstenschipper",{"Bringt Gazlowe in Ratschet Baron Küstenschippers Kopf."}}
D[896] = {"Des Minenarbeiters Vermögen",{"Beschafft Euch von einem der Vorarbeiter oder Vollstrecker der Venture Company den Katzenaugensmaragd und bringt ihn zu Werftmeister Flunkerblick in Ratschet."}}
D[897] = {"Der Ernter",{"Bringt den Ernterkopf zu Jorn Himmelsdeuter."}}
D[898] = {"Aus der Gefangenschaft befreit",{"Begleitet Gilthares Feuerzweig sicher zurück zu Kapitän Blendsonn in Ratschet."}}
D[899] = {"Von Hass zerfressen",{"Bringt Mankrik beim Wegekreuz 60 Stacheleberhauer der Borstennacken."}}
D[900] = {"Samophlang",{"Schließt das Treibstoffzufuhrventil, das Regelventil und das Hauptsteuerventil, und benutzt dann noch einmal die Steuerkonsole."}}
D[901] = {"Samophlang",{"Besorgt Euch bei Tüftler Kichers den Konsolenschlüssel, um damit die Steuerkonsole zu öffnen."}}
D[902] = {"Samophlang",{"Bringt das Samophlang zu Stotterspritter in Ratschet."}}
D[903] = {"Streuner des Brachlandes",{"Besorgt für Sergra Dunkeldorn beim Wegekreuz 7 Streunerklauen von den Savannenstreunern."}}
D[905] = {"Die wütenden Sensenklauen",{"Tötet Bluthornraptoren und nehmt ihre Federn mit. Benutzt die Federn bei den drei Sensenklauennestern. Kehrt zu Sergra Dunkeldorn beim Wegekreuz zurück."}}
D[906] = {"Verräter in den eigenen Reihen",{"Bringt Loks Schädel zu Thork beim Wegekreuz im Brachland."}}
D[907] = {"Wütende Donnerechsen",{"Bringt das Blut von 3 Donnerechsen ins Camp Taurajo zu Jorn Himmelsdeuter."}}
D[908] = {"Inmitten der Ruinen",{"Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[909] = {"Baron Aquanis",{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[910] = {"Unten an den Docks",{"Bringt Euren Schützling in die Docks von Ratschet im Brachland."}}
D[911] = {"Das Tor zur Grenze",{"Begleitet Euren Schützling zum Schutzwall von Mor'shan im nördlichen Teil des Brachlands, kurz bevor man das Eschental betritt."}}
D[913] = {"Der Ruf des Donnerfalken",{"Sucht und erschlagt einen Donnerfalken und bringt Jorn Himmelsdeuter in Camp Taurajo seine Flügel."}}
D[914] = {"Anführer der Giftzähne",{"Bringt die Edelsteine von Kobrahn, Anacondra, Pythas und Serpentis nach Donnerfels zu Nara Wildmähne."}}
D[915] = {"Lecker Eis",{"Besorgt für Euren Schützling etwas Erdbeereis. Der Kleine scheint die Marke 'Tigules Eiscreme' zu bevorzugen."}}
