D[924] = {"Die Dämonensaat",{"Nehmt einen fehlerhaften Kraftstein. Bringt ihn zum Altar des Feuers, bevor dessen Wirkung erlischt, und kehrt dann zu Ak'Zeloth zurück."}}
D[925] = {"Cairnes Hufabdruck",{"Reist nach Donnerfels und versucht für Euren Schützling einen Hufabdruck von Cairne Bluthuf zu ergattern."}}
D[926] = {"Fehlerhafter Kraftstein"}
