D[928] = {"Krone der Erde",{"Bringt Corithras Mondzorn in Dolanaar das teilweise gefüllte Gefäß."}}
D[929] = {"Krone der Erde",{"Füllt die Jadephiole und bringt sie Corithras Mondzorn in Dolanaar zurück."}}
D[930] = {"Die leuchtende Frucht",{"Bringt Denalan am Al'Amethsee die leuchtende Frucht."}}
D[931] = {"Der schimmernde Wedel",{"Bringt Denalan am Al'Amethsee einen der schimmernden Wedel."}}
D[932] = {"Krankhafter Hass",{"Tötet Lord Melenas und bringt Tallonkai Flinkwurzel in Dolanaar seinen Kopf."}}
D[933] = {"Krone der Erde",{"Füllt die Turmalinphiole und bringt sie Corithras Mondzorn in Dolanaar."}}
D[934] = {"Krone der Erde",{"Füllt die Amethystphiole und bringt sie Corithras Mondzorn in Dolanaar."}}
D[935] = {"Krone der Erde",{"Bringt dem Erzdruiden Fandral Hirschhaupt in Darnassus das gefüllte Gefäß."}}
