D[937] = {"Die verzauberte Lichtung",{"Beschafft 6 Blutfedergürtel und bringt sie der Schildwache Arynia Wolkenbruch in der Lichtung des Orakels."}}
D[938] = {"Nebel",{"Begleitet Nebel zur Schildwache Arynia Wolkenbruch beim Mondbrunnen in der Nähe des Orakelbaums."}}
D[939] = {"Flöte des Xavaric",{"Bringt die Flöte von Xavaric und 5 Jadefeuerteufelsbinder zu Eridan Blauwind im südlichen Teil des Teufelswalds."}}
