D[974] = {"Die Quelle finden",{"Krakle im Krater von Un'Goro möchte, dass Ihr den heißesten Bereich des Feuersäulengrats findet.","","Immer, wenn Ihr eine heiße Stelle findet, klickt Ihr das Thermometer mit der rechten Maustaste an, um die Temperatur zu überprüfen. Sucht, bis Ihr die heißeste Stelle gefunden habt."}}
D[975] = {"Behälter von Mau'ari",{"Wartet einen Moment und sprecht dann erneut mit Hexendoktorin Mau'ari, um den Glücksbringer zu erhalten."}}
D[976] = {"Nachschub für Auberdine",{"Sprecht mit Delgren dem Läuterer bei Maestras Posten, nachdem Ihr Feero sicher durch das Eschental geführt habt."}}
D[977] = {"Sind wir endlich da, Yeti?",{"Sammelt 2 makellose Yetihörner für Umi Rumpelkicher in der Ewigen Warte."}}
D[978] = {"Mondbestrahltes Wildekin",{"Sammelt 10 mondbestrahlte Federn aus Winterquell und kehrt dann zu Erelas Himmelsbern in Rut'theran zurück."}}
D[979] = {"Ranshalla suchen",{"Sucht nach Ranshalla im östlichen Winterquell."}}
D[980] = {"Die neuen Quellen",{"Reist nach Winterquell und sprecht mit Donova Schneeweh."}}
D[981] = {"Der Turm von Althalaxx",{"Sprecht mit Delgren dem Läuterer in Maestras Posten."}}
D[982] = {"Tiefer Ozean, weites Meer",{"Beschafft die Schließkassette der Silbermorgen und die Schließkassette der Nebelschleier für Gorbold Stahlhand in Auberdine. Beide Gegenstände findet Ihr an Bord der Schiffswracks nördlich des Dorfes."}}
