D[1048] = {"In das Scharlachrote Kloster",{"Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."}}
D[1049] = {"Kompendium der Gefallenen",{"Holt das 'Kompendium der Gefallenen' aus dem Kloster in Tirisfal und bringt es zu dem Weisen Wahrspruch in Donnerfels."}}
D[1050] = {"Mythologie der Titanen",{"Holt die 'Mythologie der Titanen' aus dem Kloster und bringt die der Bibliothekarin Mae Bleichstaub in Eisenschmiede."}}
D[1051] = {"Vorrels Rache",{"Bringt Monika Sengutz in Tarrens Mühle den Ehering von Vorrel Sengutz."}}
D[1052] = {"Auf dem Scharlachroten Pfad",{"Bringt Raleigh dem Andächtigen in Süderstade Bruder Antons Empfehlungsschreiben."}}
D[1053] = {"Im Namen des Lichts",{"Tötet Hochinquisitorin Weißsträhne, den Scharlachroten Kommandant Mograine, Herod, den Scharlachroten Helden sowie den Hundemeister Loksey und meldet Euch dann wieder bei Raleigh dem Andächtigen in Süderstade."}}
D[1054] = {"Die Auswahl der Bedrohung",{"Bringt Raene Wolfsläufer in Astranaar Dal Blutklaues Schädel."}}
D[1055] = {"Raenes Säuberung",{"Kehrt zu Shael'dryn beim Mondbrunnen zurück."}}
D[1056] = {"Reise zum Steinkrallengipfel",{"Reist zu Bewahrer Albagorm auf dem Steinkrallengipfel."}}
D[1057] = {"Die Rückeroberung des verbrannten Tals",{"Bewahrer Albagorm auf dem Steinkrallengipfel möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt."}}
D[1058] = {"Jin'Zils Waldmagie",{"Hexendoktor Jin'Zil in Malaka'jin möchte 5 Portionen Steinkrallensaft, 5 Schnurrhaare eines Mondlichtläufers, 30 Renneraugen und die Schuppe eines Siechdrachen."}}
D[1059] = {"Die Rückeroberung des verbrannten Tals",{"Reist zu Falfindel Wegeshut an der Grenze zwischen Tausend Nadeln und Feralas."}}
D[1060] = {"Brief an Jin'Zil",{"Überbringt Jin'Zil in seiner Höhle in Malaka'jin im Steinkrallengebirge Darsoks Brief."}}
D[1061] = {"Die Geister des Steinkrallengebirges",{"Sprecht mit Seereth Bruchstein an der Grenze zwischen dem Steinkrallengebirge und dem Brachland."}}
D[1062] = {"Goblineindringlinge",{"Tötet 15 Holzfäller der Venture Co. und kehrt dann zu Seereth Bruchstein an der Grenze des Steinkrallengebirges und dem Brachland zurück."}}
D[1063] = {"Die Ältestengreisin",{"Sprecht in Donnerfels mit Magatha."}}
D[1064] = {"Die Hilfe der Verlassenen",{"Sprecht bei den Teichen der Visionen in Donnerfels mit der Apothekerin Zamah."}}
