D[2822] = {"Das Zeichen der Qualität",{"Bringt Jangdor Flinkschreiter im Camp Mojache 10 dicke Yetibälge."}}
D[2841] = {"Maschinenkriege",{"Besorgt die Maschinenblaupausen und Thermadrahts Safekombination aus Gnomeregan und bringt sie zu Nogg nach Orgrimmar."}}
D[2842] = {"Chefingenieur Scooty",{"Sprecht mit Scooty in Beutebucht."}}
D[2843] = {"Gnomer-weeeeg!",{"Wartet, bis Scooty den Goblintransponder kalibriert hat."}}
D[2844] = {"Der Riesenwächter",{"Findet das verlorene Nachtelfenmädchen."}}
D[2845] = {"Streunende Shay",{"Nehmt Shays Glocke aus der Truhe.","","Begleitet Shay Laubschleicher zu Felsbeißers Lager."}}
D[2846] = {"Tiara der Tiefen",{"Bringt die Tiara der Tiefen zu Tabetha in den Düstermarschen."}}
D[2847] = {"Wildlederrüstung",{"Bringt Pratt McGrubben in der Mondfederfeste 10 Stücke dickes Leder."}}
D[2848] = {"Wildlederschultern",{"Bringt Pratt McGrubben in der Mondfederfeste 6 dicke Rüstungssets und eine Wildranke."}}
D[2849] = {"Wildlederweste",{"Bringt Pratt McGrubben in der Mondfederfeste 2 Schildkrötenschuppenbrustplatten, 2 Paar Schildkrötenschuppenhandschuhe und eine Wildranke."}}
D[2850] = {"Wildlederhelm",{"Bringt Pratt McGrubben in der Mondfederfeste 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke."}}
D[2851] = {"Wildlederstiefel",{"Bringt Pratt McGrubben in der Mondfederfeste 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken."}}
D[2852] = {"Wildledergamaschen",{"Bringt Pratt McGrubben in der Mondfederfeste 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken."}}
D[2853] = {"Meister des Wildleders",{"Gebt Telonis, dem Lederverarbeitungsmeister von Darnassus, Pratts Brief."}}
D[2854] = {"Wildlederrüstung",{"Bringt Jangdor Flinkschreiter im Camp Mojache 10 Stücke dickes Leder."}}
D[2855] = {"Wildlederschultern",{"Bringt Jangdor Flinkschreiter im Camp Mojache 6 dicke Rüstungssets und eine Wildranke."}}
D[2856] = {"Wildlederweste",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenbrustplatten, 2 Schildkrötenschuppenhandschuhe und eine Wildranke."}}
D[2857] = {"Wildlederhelm",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Tuniken des Nachtschleichers, 2 Stirnbänder des Nachtschleichers und eine Wildranke."}}
D[2858] = {"Wildlederstiefel",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Hosen des Nachtschleichers, 2 Stiefel des Nachtschleichers und 2 Wildranken."}}
D[2859] = {"Wildledergamaschen",{"Bringt Jangdor Flinkschreiter im Camp Mojache 2 Schildkrötenschuppenhelme, 2 Schildkrötenschuppenarmschienen und 2 Wildranken."}}
D[2860] = {"Meister des Wildleders",{"Gebt Una, der Lederverarbeitungsmeisterin von Donnerfels, Jangdors Schreiben."}}
D[2861] = {"Tabethas Aufgabe",{"Sprecht mit Tabetha in den Düstermarschen."}}
D[2862] = {"Krieg gegen die Waldpfoten",{"Bringt Hadoken Flinkschreiter im Camp Mojache 10 Mähnen eines Waldpfotengnolls."}}
D[2863] = {"Schlag gegen die Alphas",{"Tötet 5 Alphas der Waldpfoten und kehrt innerhalb einer Stunde zu Hadoken Flinkschreiter zurück."}}
D[2864] = {"Tran'rek",{"Sprecht mit Tran'rek in Gadgetzan."}}
D[2865] = {"Skarabäuspanzerschalen",{"Bringt Tran'rek in Gadgetzan 5 unbeschädigte Skarabäuspanzerschalen."}}
D[2866] = {"Die Ruinen von Solarsal",{"Erforscht die Ruinen von Solarsal und findet etwas über die Anwesenheit der Naga dort heraus."}}
D[2867] = {"Kehrt zur Mondfederfeste zurück",{"Kehrt zu Shandris Mondfeder in der Mondfederfeste zurück und berichtet von Euren Entdeckungen."}}
D[2869] = {"Gegen die Hasskämme",{"Bringt Latronicus Mondspeer in der Mondfederfeste 10 Nagaschuppen der Hasskämme."}}
D[2870] = {"Gegen Lord Shalzaru",{"Vernichtet Lord Shalzaru und bringt dann Latronicus Mondspeer in der Mondfederfeste das geheimnisvolle Relikt, das er entdeckt hat."}}
D[2871] = {"Überbringung des Relikts",{"Bringt das geheimnisvolle Relikt zu Vestia Mondspeer in der Mondfederfeste."}}
D[2872] = {"Stoleys Schuld",{"Sprecht mit Stoley beim Dampfdruckpier."}}
D[2873] = {"Stoleys Lieferung",{"Bringt Stoleys Lieferung zu Stoley beim Dampfdruckpier."}}
D[2874] = {"Lieferung für MacKinley",{"Bringt Stoleys Flasche zu \"Seewolf\" MacKinley in Beutebucht."}}
D[2875] = {"GESUCHT: Andre Feuerbart",{"Bringt Sicherheitschef Bilgenritzel beim Dampfdruckpier Andres Kopf."}}
D[2876] = {"Schiffzeitpläne",{"Berichtet den Behörden des Dampfdruckpiers von den Schiffzeitplänen."}}
D[2877] = {"Den Lauerfels aufräumen",{"Tötet 10 grüne Schlicke sowie 10 jadegrüne Schlamme und meldet Euch dann wieder bei Fraggar Donnermantel beim Nistgipfel."}}
D[2878] = {"Verderbte Liedblume"}
D[2879] = {"Der Stock von Equinex",{"Aktiviert Troyas Stock und findet den Monolithen von Equinex."}}
D[2880] = {"Kopfgeld für Trollhalsketten",{"Bringt Fraggar Donnermantel beim Nistgipfel 5 Trollstammeshalsketten."}}
D[2881] = {"Kopfgeld für Trollhalsketten"}
D[2882] = {"Cuergos Gold",{"Findet Cuergos Gold!"}}
D[2902] = {"Waldpfotennachforschung",{"Findet die Schlachtpläne der Gnolle irgendwo in den Gnoll-Lagern südlich vom Camp Mojache."}}
D[2903] = {"Die Schlachtpläne",{"Bringt die Schlachtpläne der Waldpfoten zu Hadoken Flinkschreiter ins Camp Mojache."}}
D[2904] = {"Eine schöne Bescherung",{"Begleitet Kernobee zur Uhrwerkgasse und meldet Euch dann wieder bei Scooty in Beutebucht."}}
D[2922] = {"Rettet Techbots Hirn!",{"Bringt Techbots Speicherkern zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[2923] = {"Tüftlermeister Oberfunks",{"Sprecht mit Tüftlermeister Oberfunks in Eisenschmiede."}}
D[2924] = {"Grundlegende Artifixe",{"Bringt Klockmort Spannersplint in Eisenschmiede 12 grundlegende Artifixe."}}
D[2925] = {"Klockmorts Grundlagen",{"Sprecht mit Klockmort Spannersplint in Eisenschmiede."}}
D[2926] = {"Gnogaine",{"Sammelt mit der leeren bleiernen Sammelphiole radioaktive Ablagerungen bestrahlter Eindringlinge oder Plünderer. Sobald sie voll ist, bringt Ihr sie zu Ozzie Wechselvolt nach Kharanos zurück."}}
