D[3447] = {"Das Geheimnis des Kreises",{"Reist zum Versunkenen Tempel und enthüllt das Geheimnis, das sich in dem Kreis der Statuen verbirgt."}}
D[3448] = {"Die Bürde weitergeben",{"Sprecht mit Magier Tymor in Eisenschmiede."}}
D[3449] = {"Arkane Runen",{"Verwendet das Abschriftenset, um Abpausbilder von der Rune von Beth'Amara, der Rune von Jin'yael, der Rune von Markri und der Rune von Sael'hai herzustellen, bevor Ihr Euch zu der kleinen Insel vor der südlichen Halbinsel von Azshara aufmacht und dem Piloten Xiggs Luntenzünder signalisiert, dass er sie abholen kann."}}
D[3450] = {"Eine einfache Ladung",{"Sprecht mit Xiggs Luntenzünder in Eisenschmiede."}}
D[3451] = {"Signal zum Abholen",{"Sprecht mit Xiggs Luntenzünder in Eisenschmiede und erhaltet von ihm eine Standardleuchtpistole."}}
D[3452] = {"Die Ummantelung der Flamme",{"Bringt ein Symbol von Ragnaros zu Velarok Windklinge."}}
D[3453] = {"Die Fackel der Vergeltung",{"Wartet bis Velarok Windklinge die Fackel der Vergeltung vollendet hat."}}
D[3454] = {"Die Fackel der Vergeltung",{"Nehmt die Fackel der Vergeltung."}}
D[3461] = {"Rückkehr zu Magier Tymor",{"Bringt Magier Tymors Abschriftenset zu ihm zurück nach Eisenschmiede."}}
D[3462] = {"Knappe Malzdarr",{"Sprecht mit dem Knappen Malzdarr."}}
D[3463] = {"Setzt sie in Brand!",{"Steckt die Wachpostentürme im Norden, Süden, Osten und Westen in Brand, indem Ihr die Fackel der Vergeltung innerhalb der einzelnen Gebäude benutzt."}}
D[3481] = {"Plunder...",{"Öffnet die Truhe."}}
D[3482] = {"<NYI> <TXT> The Pocked Black Box",{"Bringt diesen Flugschreiber zu Kravel."}}
D[3483] = {"Signal zum Abholen"}
D[3501] = {"Viel hilft viel",{"Bringt Kum'isha unvollständige Draenethystfragmente und Ihr werdet für jedes, das Ihr bringt, belohnt."}}
D[3502] = {"Des einen Draeneis Plunder...",{"Bringt Kum'isha unvollständige Draenethystfragmente. Jede Art von Monster in den verwüsteten Landen könnte ein Fragment bei sich tragen."}}
D[3503] = {"Treffen mit dem Meister"}
D[3504] = {"Verraten",{"Bringt den versiegelten Brief zu Ag'tor Blutfaust nach Azshara."}}
D[3505] = {"Verraten",{"Tötet 10 Blutelfeneintreiber und 10 Blutelfenfeldmesser, bevor Ihr Magus Rimtoris Lager sucht. Sobald Ihr es gefunden habt, sucht nach etwas, das für sie von Bedeutung ist und das wir nehmen können, um sie in einen Kampf zu locken."}}
D[3506] = {"Verraten",{"Zerstört den arkanen Fokussierkristall, der an Magus Rimtori gebunden ist, und tötet sie danach. Bringt dann den Kopf von Magus Rimtori zu Ag'tor Blutfaust nach Azshara."}}
D[3507] = {"Verraten",{"Sprecht mit Belgrom Felshammer in Orgrimmar."}}
D[3508] = {"Den Zauberschutz brechen",{"Wartet, bis Loramus den Erleuchtungszauber vollendet hat."}}
D[3509] = {"Der Name der Bestie",{"Sprecht mit Lord Arkkoroc in Azshara. Beginnt Eure Suche am Rand des Wassers, um den Tempel von Arkkoran zu finden."}}
D[3510] = {"Der Name der Bestie",{"Erschlagt Hetaera und bringt den blutigen Kopf Hetaeras, den geschlagenen Kopf Hetaeras und den verwundeten Kopf Hetaeras zu Lord Arkkoroc."}}
D[3511] = {"Der Name der Bestie",{"Bringt den Härter zurück zu Loramus Thalipedes."}}
D[3512] = {"Mit Eranikus' eigenen Worten",{"Reist in den östlichen Teil von Winterquell und sprecht mit Umbranse, dem Geistsprecher."}}
D[3513] = {"Die runenverzierte Rolle",{"Bringt die runenverzierte Rolle zum nördlichen Wachturm des Brachlandes."}}
D[3514] = {"Hordenpräsenz",{"Tötet die Anführerin des Krallenbaus, Rynthariel die Schlüsselmeisterin."}}
D[3517] = {"Wissen stehlen",{"Sucht die Schrifttafel von Beth'Amara, die Schrifttafel von Jin'yael, die Schrifttafel von Markri und die Schrifttafel von Sael'hai, bevor Ihr zu Jediga in Azshara zurückkehrt."}}
D[3518] = {"Lieferung an Magatha",{"Bringt die Schrifttafel von Beth'Amara zu Magatha in Donnerfels."}}
D[3519] = {"Ein Freund in Not",{"Sprecht mit Dirania Silberschein im Laubschattental."}}
D[3520] = {"Kreischergeister",{"Fangt die Geister von 3 Kreischern in Feralas ein und kehrt dann zu Yeh'kinya beim Dampfdruckpier zurück."}}
D[3521] = {"Iverrons Gegengift",{"Sammelt 7 Hyazinthpilze, 4 Mondblütenlilien und 1 Waldwebersekret für Dirania Silberschein im Laubschattental."}}
D[3522] = {"Iverrons Gegengift",{"Bringt Iverrons Gegengift zu Iverron, bevor die Zeit um ist. Ihr findet Iverron bei der Höhle im Norden."}}
D[3523] = {"Geißel der Niederungen",{"Wenn Ihr Belnistrasz helfen wollt, sprecht noch einmal mit ihm und übergebt ihm den Schwurstein, den er Euch gab."}}
D[3524] = {"An Land gespült",{"Sammelt Meereskreaturknochen von der gestrandeten Meereskreatur unmittelbar südlich von Auberdine und kehrt dann mit ihnen zu Gwennyth Bly'Leggonde nach Auberdine zurück."}}
D[3525] = {"Ausschalten des Götzen",{"Begleitet Belnistrasz zum Götzen der Stacheleber in den Hügeln der Klingenhauer.","","Beschützt Belnistrasz, während er das Ritual durchführt, um den Götzen auszuschalten."}}
D[3526] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[3527] = {"Die Prophezeiung von Mosh'aru",{"Bringt die erste und die zweite Schrifttafel von Mosh'aru zu Yeh'kinya nach Tanaris."}}
D[3528] = {"Der Gott Hakkar",{"Bringt das gefüllte Ei von Hakkar zu Yeh'kinya nach Tanaris."}}
D[3541] = {"Lieferung an Jes'rimon",{"Bringt die Schrifttafel von Jin'yael zu Jes'rimon nach Orgrimmar."}}
D[3542] = {"Lieferung an Andron Gant",{"Bringt die Schrifttafel von Markri zu Andron Gant nach Unterstadt."}}
D[3561] = {"Lieferung für Erzmagier Xylem",{"Bringt die Schrifttafel von Sael'hai zu Erzmagier Xylem in Azshara."}}
D[3562] = {"Magathas Bezahlung für Jediga",{"Bringt Magathas Notiz zu Jediga in Azshara."}}
D[3563] = {"Jes'rimons Bezahlung für Jediga",{"Bringt Jes'rimons Notiz zu Jediga in Azshara."}}
D[3564] = {"Androns Bezahlung für Jediga",{"Bringt Androns Notiz zu Jediga in Azshara."}}
D[3565] = {"Xylems Bezahlung für Jediga",{"Bringt Xylems Notiz zu Jediga in Azshara."}}
D[3566] = {"Erhebt Euch, Obsidion!",{"Tötet Lathoric den Schwarzen und Obsidion. Kehrt zurück zu Thorius nach Eisenschmiede mit dem Kopf von Lathoric dem Schwarzen und dem Herzen von Obsidion."}}
D[3567] = {"An die Spitze"}
D[3568] = {"Verbreitete Verderbnis",{"Füllt alle 4 leeren Phiolen an den Gezeitenteichen entlang der Küste der Ruinen von Eldarath in Azshara und kehrt dann zu Chemiker Miesmut zurück."}}
D[3569] = {"Verbreitete Verderbnis",{"Gebt Miesmuts Elixier Thersa Windweise in Unterstadt."}}
D[3570] = {"Verbreitete Verderbnis"}
D[3601] = {"Kim'jael, fürwahr!",{"Durchsucht den thalassischen Stützpunkt nach Kim'jaels Kompass, Zielfernrohr, ausgestopftem Huhn und Knobelwizz und bringt ihm dann alles nach Azshara zurück."}}
D[3602] = {"Azsharit",{"Sammelt 20 kristallisierte Azsharite im südlichen Azshara. Ihr könnt den Teufelshund benutzen, damit er Euch beim 'Erschnüffeln' der gut versteckten Ablagerungen behilflich ist.","","Kehrt zu Loramus zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[3621] = {"Die Herstellung von Teufelsbann",{"Bringt die Lieferung zu Galvan dem Alten im Schlingendorntal."}}
D[3625] = {"Verzauberte Azsharitteufelswaffe",{"Wartet, bis Galvan die Waffen fertig geschmiedet hat."}}
D[3626] = {"Rückkehr in die verwüsteten Lande",{"Kehrt zum Gefallenen Helden der Horde zurück. Zu finden ist er an der Splitterspeerkreuzung in den Sümpfen des Elends."}}
D[3627] = {"Das zerbrochene Amulett vereinen",{"Tötet Grol den Zerstörer, Lady Sevine und Erzmagier Allistarj. Nehmt das Amulett von Grol, das Amulett von Sevine und das Amulett von Allistarj von ihren Leichen.","","Denkt daran, Eure Verzauberte Azsharitteufelswaffe zu BENUTZEN, um die Triade zu schwächen. Auf eine andere Weise können sie nicht getötet werden - aber verwendet sie weise..."}}
D[3628] = {"Ihr seid Rakh'likh, Dämon",{"Vernichtet Razelikh den Entweiher und bringt das abgetrennte Horn des Entweihers zum Gefallenen Helden der Horde. Ihr müsst außerdem den Zauberschutz des Entweihers mit zurückbringen, damit der Gefallene Held ihn zerstören und somit verhindern kann, dass er jemals in die falschen Hände fällt."}}
D[3629] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt das Handbuch der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan."}}
D[3630] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3631] = {"Teufelsross beschwören",{"Sprecht mit Strahad Farsan im Brachland."}}
D[3632] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3633] = {"Gobliningenieurskunst",{"Wenn Ihr etwas über die Gobliningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Nixx Sprossfeder nach Gadgetzan in Tanaris."}}
D[3634] = {"Gnomeningenieurskunst",{"Wenn Ihr etwas über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Tüftlermeister Oberfunks nach Eisenschmiede."}}
D[3635] = {"Gnomeningenieurskunst",{"Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht."}}
D[3636] = {"Das Licht bringen",{"Erzbischof Benedictus will, dass Ihr Amnennar den Kältebringer in den Hügeln der Klingenhauer tötet."}}
D[3637] = {"Gnomeningenieurskunst",{"Wenn Ihr mehr über die Gnomeningenieurskunst erlernen wollt, dann bringt die Anleitung der Ingenieurskunstdisziplinen zu Glotz Widrikus nach Beutebucht."}}
D[3638] = {"The Pledge of Secrecy",{"If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan."}}
D[3639] = {"Zeigt Eure Arbeit",{"Bringt 20 große Eisenbomben, 20 robuste Dynamitstangen und 5 explosive Schafe zu Nixx Sprossfeder nach Gadgetzan."}}
D[3640] = {"Der Schwur der Geheimhaltung",{"If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge."}}
D[3641] = {"Zeigt Eure Arbeit",{"Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Tüftlermeister Oberfunks in Eisenschmiede."}}
D[3642] = {"Der Schwur der Geheimhaltung"}
D[3643] = {"Zeigt Eure Arbeit",{"Bringt 6 Mithrilrohre, 1 genaues Zielfernrohr und 2 hochentwickelte Zielattrappen zu Glotz Widrikus in Beutebucht."}}
