D[4245] = {"Chasing A-Me 01",{"Begleitet A-Me 01 zu Karna Wirrbart im Krater von Un'Goro."}}
D[4261] = {"Alter Geist",{"Bringt Arei in Sicherheit und sprecht dann mit Kayneth Stillwind in Waldeslied, im Osten des Eschentals."}}
D[4262] = {"Übermeister Pyron",{"Erschlagt Übermeister Pyron.","","Ihr erinnert Euch an Jalindas Worte, dass Pyron den Steinbruch bewachen würde. Vielleicht solltet Ihr dort nachsehen?"}}
D[4263] = {"Incendius!",{"Sucht Lord Incendius in den Schwarzfelstiefen und vernichtet ihn!"}}
D[4264] = {"Eine zusammengeknüllte Notiz",{"Soeben seid Ihr auf etwas gestoßen, das Marschall Windsor mit Sicherheit sehr interessiert. Vielleicht besteht ja doch noch Hoffnung."}}
D[4265] = {"Flucht aus dem Schwarmbau",{"Begleitet Raschal sicher aus dem Schwarmbau der Zukk'ash hinaus.","","Kehrt zu Ginro Herdfeuer in der Mondfederfeste zurück und lasst ihn wissen, dass Raschal am Leben ist und dass es ihm gut geht."}}
