D[5237] = {"Mission erfüllt!"}
D[5238] = {"Mission erfüllt!"}
D[5241] = {"Onkel Carlin",{"Sucht Carlin Rotpfad."}}
D[5242] = {"Der endgültige Schlag",{"Tötet Moora und Salia und bringt den Kopf von Schattenlord Fel'dan zu Greta Mooshuf im Teufelswald."}}
D[5243] = {"Häuser der Heiligen",{"Begebt Euch nach Stratholme im Norden. Durchsucht die Vorratskisten, die über die Stadt verstreut sind, und holt 5 Einheiten Weihwasser von Stratholme. Kehrt zu Leonidas Bartholomäus dem Geachteten zurück, wenn Ihr genug der gesegneten Flüssigkeit gesammelt habt."}}
D[5244] = {"Die Ruinen von Kel'Theril",{"Sprecht mit Jaron Steinschleifer in Sternfall."}}
D[5245] = {"Die gequälten Seelen von Kel'Theril",{"Benutzt Jarons Hacke, um die vier Fragmente des Hochgeborenenrelikts zu suchen. Bringt sie zu Aurora Himmelsrufer in den östlichen Pestländern."}}
D[5246] = {"Fragmente der Vergangenheit",{"Sucht die hochheiligen Schriften der Hochgeborenen im Tempel von Zin-Malor in Azshara und bringt sie zu Aurora Himmelsrufer beim Nordpassturm in den östlichen Pestländern."}}
D[5247] = {"Fragmente der Vergangenheit",{"Bringt einen verzauberten Thoriumbarren, 5 Kristallflicker und eine Phiole mit Düsterwasser zu Aurora Himmelsrufer beim Nordpassturm in den östlichen Pestländern."}}
D[5248] = {"Gequält von der Vergangenheit",{"Bringt den Kristall von Zin-Malor zum Kel'Therilsee in Winterquell und sucht einen Geist eines Hochgeborenen, der mit Euch sprechen will."}}
D[5249] = {"Nach Winterquell!",{"Sucht Sternfall in Winterquell und sprecht mit Wynd Nachtjagd."}}
D[5250] = {"Sternfall",{"Sucht die Siedlung Sternfall in Winterquell und sprecht mit Wynd Nachtjagd."}}
D[5251] = {"Der Archivar",{"Reist nach Stratholme und sucht Archivar Galford vom Scharlachroten Kreuzzug. Vernichtet ihn und verbrennt das Scharlachrote Archiv."}}
D[5252] = {"Reuevolle Hochgeborene",{"Sprecht mit Wynd Nachtjagd in Sternfall und fragt nach dem richtigen Ort für den Kristall von Zin-Malor."}}
D[5253] = {"Der Kristall von Zin-Malor",{"Überbringt dem Erzdruiden Fandral Hirschhaupt in Darnassus den Kristall von Zin-Malor."}}
D[5261] = {"Eagan Pelzschneider",{"Sprecht mit Eagan Pelzschneider."}}
D[5262] = {"Die Wahrheit zeigt sich mit Macht",{"Bringt den Kopf von Balnazzar zu Fürst Nicholas Zverenhoff in den östlichen Pestländern."}}
D[5263] = {"Übertroffen",{"Zieht nach Stratholme und vernichtet Baron Totenschwur. Nehmt seinen Kopf und kehrt zu Fürst Nicholas Zverenhoff zurück."}}
D[5264] = {"Lord Maxwell Tyrosus",{"Sprecht mit Lord Maxwell Tyrosus. Er befindet sich in der Kirche."}}
D[5265] = {"Der Argentumtresor",{"Öffnet den Argentumtresor und nehmt Euch Eure Belohnung."}}
D[5281] = {"Die ruhelosen Seelen",{"Sucht Egan. Ihr wisst nur, dass er zuletzt in der Nähe von Stratholme gesehen wurde."}}
D[5282] = {"Die ruhelosen Seelen",{"Wendet Egans Blaster auf die geisterhaften und spektralen Bürger von Stratholme an. Wenn die ruhelosen Geister ihre geisterhaften Hüllen sprengen, wendet den Blaster erneut an - dann sind sie endlich frei!","","Befreit 15 ruhelose Seelen und kehrt zu Egan zurück."}}
D[5283] = {"Die Kunst des Rüstungsschmiedes",{"Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Grumnus bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte."}}
D[5284] = {"Der Weg des Waffenschmieds...",{"Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Ironus bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben."}}
D[5301] = {"Die Kunst des Rüstungsschmiedes",{"Um Rüstungsschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Okothos bringen: 4 verschnörkelte Mithrilhelme, 2 verschnörkelte Mithrilstiefel, 1 verschnörkelte Mithrilbrustplatte."}}
D[5302] = {"Der Weg des Waffenschmieds...",{"Um Waffenschmied zu werden, müsst Ihr die folgenden Gegenstände herstellen und zu Borgosh bringen: 4 Mondstahlbreitschwerter, 4 massive Eisenäxte, 2 schwere Mithriläxte und 2 große schwarze Streitkolben."}}
D[5305] = {"Süße Beschaulichkeit",{"Begebt Euch nach Stratholme und tötet den purpurroten Hammerschmied. Nehmt die Schürze des purpurroten Hammerschmiedes und kehrt zu Lilith zurück."}}
D[5306] = {"Schlangenstein der Schattenjägerin",{"Begebt Euch zur Schwarzfelsspitze und erschlagt Schattenjägerin Vosh'gajin. Holt Vosh'gajins Schlangenstein und kehrt zu Kilram zurück."}}
D[5307] = {"Verderbnis",{"Findet den Schwertschmied der schwarzen Wache in Stratholme und vernichtet ihn. Holt die Insignien der schwarzen Wache und kehrt zu Seril Geißelbann zurück."}}
D[5321] = {"Der Schläfer ist erwacht",{"Begleitet Kerlonian Schattenspiel zu Liladris Mondbach in Maestras Posten im Eschental."}}
D[5341] = {"Das Familienvermögen der Barovs",{"Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Alexi Barov zurück, sobald die Aufgabe erledigt ist."}}
D[5342] = {"Der letzte Barov",{"Begebt Euch zum Zugwindlager - Territorium der Allianz - und ermordet Weldon Barov. Nehmt seinen Kopf und kehrt zu Alexi Barov zurück.","","Seid gewarnt, Weldon wird wahrscheinlich gut von Abschaum der Allianz geschützt."}}
D[5343] = {"Das Familienvermögen der Barovs",{"Begebt Euch zur Scholomance und holt das Familienvermögen der Barovs zurück. Dieses Vermögen besteht aus vier Besitzurkunden: Es sind die Besitzurkunde für Darrowehr, die Besitzurkunde für Brill, die Besitzurkunde für Tarrens Mühle und die Besitzurkunde für Süderstade. Kehrt zu Weldon Barov zurück, sobald die Aufgabe erledigt ist."}}
D[5344] = {"Der letzte Barov",{"Begebt Euch zum Bollwerk - Territorium der Horde - und ermordet Alexi Barov. Nehmt seinen Kopf und kehrt zu Weldon Barov zurück.","","Seid gewarnt, Alexi wird wahrscheinlich gut durch Abschaum der Horde geschützt."}}
D[5361] = {"Stammbaum",{"Bringt den Bericht von Klippenbehüter Langhorn zu Nataka Langhorn am Geistwandlerposten in Desolace."}}
D[5381] = {"Hand von Iruxos",{"Holt den Dämonenkasten aus der Festung Donneraxt und kehrt damit zu Taiga Klugmähne nach Schattenflucht zurück."}}
D[5382] = {"Doktor Theolen Krastinov, der Schlächter",{"Sucht Doktor Theolen Krastinov in Scholomance. Vernichtet ihn, verbrennt dann die Überreste von Eva Sarkhoff und die Überreste von Lucien Sarkhoff. Kehrt zu Eva Sarkhoff zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[5383] = {"Krastinovs Tasche der Schrecken",{"Bringt die Tasche der Schrecken zu Eva Sarkhoff in Darrowehr."}}
D[5384] = {"Kirtonos der Herold",{"Kehrt mit dem Blut Unschuldiger zur Scholomance zurück. Sucht die Veranda und legt das Blut der Unschuldigen in die Kohlenpfanne. Kirtonos wird kommen, um sich von Eurer Seele zu nähren.","","Kämpft tapfer, gebt keinen Fußbreit nach! Vernichtet Kirtonos und kehrt zu Eva Sarkhoff zurück."}}
D[5385] = {"Die Überreste von Trey Lichtschmied",{"Bringt die Überreste von Trey Lichtschmied zu Jessir Mondsichel im Teufelswald."}}
D[5386] = {"Der Fang des Tages",{"Sprecht mit Jinar'Zillen in Schattenflucht und bringt Nataka Langhorn dann 2 Blutbauchfische."}}
