D[5421] = {"Fisch im Eimer"}
D[5441] = {"Faule Peons",{"Benutzt den Großknechttotschläger an faulen Peons, wenn sie schlafen. Weckt 5 Peons auf und bringt dann den Großknechttotschläger zu Großknecht Thazz'ril ins Tal der Prüfungen zurück."}}
D[5461] = {"Der Mensch Ras Frostraunen",{"Reist in das Arathihochland zu den Ruinen von Stromgarde. Durchsucht Stromgarde nach einem Andenken der Erinnerung. Wenn Ihr einen solchen Gegenstand findet, kehrt mit ihm zu Magistrat Marduk zurück."}}
D[5462] = {"Der Sterbende Ras Frostraunen",{"Reist zur Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern und sucht Leonidas Bartholomäus den Geachteten auf. Zeigt ihm das Andenken der Erinnerung und berichtet ihm alles, was Ihr entdeckt habt."}}
D[5463] = {"Menethils Geschenk",{"Begebt Euch nach Stratholme und sucht Menethils Geschenk. Platziert das Andenken der Erinnerung auf dem unheiligen Boden."}}
D[5464] = {"Menethils Geschenk",{"Bringt das seelengebundene Andenken zu Leonidas Bartholomäus in den östlichen Pestländern."}}
D[5465] = {"Seelengebundenes Andenken",{"Kehrt zu Magistrat Marduk in Darrowehr zurück. Zeigt ihm das seelengebundene Andenken."}}
D[5466] = {"Der Lich Ras Frostraunen",{"Sucht Ras Frostraunen in Scholomance. Wenn Ihr ihn gefunden habt, wendet das seelengebundene Andenken auf sein untotes Antlitz an. Solltet Ihr ihn erfolgreich in einen Sterblichen zurückverwandeln können, dann schlagt ihn nieder und nehmt den menschlichen Kopf von Ras Frostraunen an Euch. Bringt den Kopf zu Magistrat Marduk."}}
D[5481] = {"Gordos Aufgabe",{"Sammelt 3 Düsterkräuter und bringt sie zu Jungapotheker Holland auf den Friedhof von Brill."}}
D[5482] = {"Verdammniskraut",{"Sammelt 10 Verdammniskräuter und bringt sie zu Jungapotheker Holland."}}
D[5501] = {"Knochenjäger",{"Bringt Bibbly F'utzbuckel bei Kormeks Hütte 10 Kodoknochen vom Kodofriedhof."}}
