D[5504] = {"Mäntel der Dämmerung",{"Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Hasana ins Bollwerk in den westlichen Pestländern."}}
D[5505] = {"Der Schlüssel zur Scholomance"}
D[5507] = {"Mäntel der Dämmerung",{"Bringt 10 Ehrenmarken der Argentumdämmerung zu Rüstmeister Funkellicht im Zugwindlager in den westlichen Pestländern."}}
