D[5893] = {"Vorräte der Eisbeißermine",{"Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Horde in die Burg Frostwolf."}}
D[5901] = {"Eine Plage komme über Euch",{"Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Mickey Levine am Bollwerk in Tirisfal zurück."}}
D[5902] = {"Eine Plage komme über Euch",{"Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen."}}
D[5903] = {"Eine Plage komme über Euch",{"Wendet den leeren Termitenkrug auf die Termitenhügel in den östlichen Pestländern an. Sobald Ihr 100 Pestlandtermiten gesammelt habt, kehrt zu Nathaniel Dumah im Zugwindlager in den westlichen Pestländern zurück."}}
D[5904] = {"Eine Plage komme über Euch",{"Sucht Euch einen geeigneten Ort in der Mitte des Sägewerk des Nordkamms in den westlichen Pestländern, um das Fass mit den Pestlandtermiten abzustellen."}}
D[5921] = {"Mondlichtung",{"Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen."}}
D[5922] = {"Mondlichtung",{"Benutzt den Zauber 'Teleportieren: Mondlichtung', um zur Mondlichtung zu reisen. Wenn Ihr dort ankommt, sprecht mit Dendrite Sternenschauer in Nachthafen."}}
