D[5928] = {"Dem Ruf folgen",{"Sprecht mit Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels."}}
D[5929] = {"Großer Bärengeist",{"Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück."}}
D[5930] = {"Großer Bärengeist",{"Sucht den großen Bärengeist im nordwestlichen Teil der Mondlichtung auf und lernt alles, was er Euch über die Natur des Bären mitzuteilen hat. Wenn Ihr das erledigt habt, kehrt zu Dendrite Sternenschauer nach Nachthafen auf der Mondlichtung zurück."}}
D[5931] = {"Zurück nach Darnassus",{"Kehrt nach Darnassus zurück und sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius."}}
D[5932] = {"Zurück nach Donnerfels",{"Kehrt nach Donnerfels zurück und sprecht mit Turak Runentotem auf der Anhöhe der Ältesten."}}
D[5941] = {"Rückkehr zu Chromie",{"Bringt das Reliktbündel zu Chromie nach Andorhal."}}
D[5942] = {"Versteckte Schätze",{"Bringt Josephs Schlüssel zu Josephs Truhe."}}
D[5943] = {"Gizeltons Karawane",{"Geleitet Gizeltons Karawane am Zirkel der Mannoroc vorbei. Sprecht in Schraubenbuddels Lager mit Smeed, um Eure Belohnung zu erhalten."}}
D[5944] = {"In den Träumen",{"Geleitet Taelan Fordring aus Herdweiler hinaus."}}
D[5961] = {"Der Champion der Bansheekönigin",{"Sprecht mit Nathanos Pestrufer in den östlichen Pestländern. Es heißt, dass er sich in Marris Siedlung niedergelassen hätte."}}
D[5981] = {"Tobende Riesen",{"Rivern Frostwind möchte, dass Ihr 4 Frosthagelriesen und 4 Frosthagelbewahrer besiegt."}}
D[6001] = {"Körper und Herz",{"Benutzt den Mondstaub des Cenarius mit dem Mondkinstein von Auberdine, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Mathrengyl Bärenfährte in Darnassus, wenn Ihr fertig seid."}}
D[6002] = {"Körper und Herz",{"Benutzt den Lunarstaub des Cenarius mit dem Mondkinstein zwischen Mulgore und dem Brachland, um Mondklaue herauszulocken. Danach müsst Ihr Euch Mondklaue stellen und Euch die Kraft des Körpers und des Herzens verdienen, die er besitzt.","","Sprecht mit Turak Runentotem in Donnerfels, wenn Ihr fertig seid."}}
D[6004] = {"Offene Rechnungen",{"Tötet 2 Scharlachrote Sanitäter, 2 Scharlachrote Jäger, 2 Scharlachrote Magier und 2 Scharlachrote Ritter, bevor Ihr zu Kirsta Grubenschatten in den westlichen Pestländern zurückkehrt."}}
D[6021] = {"Zaeldarr der Ausgestoßene",{"Bringt Zaeldarrs Kopf zu Verwalter Alen in der Kapelle des hoffnungsvollen Lichts."}}
D[6022] = {"Töten zu einem bestimmten Zweck",{"Begebt Euch zu Corins Kreuzung im Osten und besiegt die Mitglieder der Geißel, die in der Stadt leben. Sammelt 7 Stücke lebendige Fäulnis in unter 10 Minuten. Zerstoßt die lebendige Fäulnis mit Mörser und Stößel zu geronnener Fäulnis."}}
D[6023] = {"Offene Rechnungen",{"Besiegt Jägerin Radley und Dragoner Durgen, bevor Ihr zu Kirsta Grubenschatten in den westlichen Pestländern zurückkehrt."}}
D[6024] = {"Hameyas Bitte",{"Tötet Spitzel Hameya. Benutzt seinen Schlüssel bei dem Erdhaufen hinter dem Tiefgewölbe."}}
D[6025] = {"Offene Rechnungen",{"Geht nach Herdweiler, sucht einen hohen Aussichtspunkt, von dem aus Ihr die Stadt überblicken könnt, schätzt die Streitkräfte des Scharlachroten Kreuzzugs und kehrt dann zu Kirsta Grubenschatten in den westlichen Pestländern zurück."}}
D[6026] = {"Das ist viel verlangt",{"Smokey LaRue möchte, dass Ihr 2 Thoriumbarren, 1 Goldrute, 8 hochexplosive Bomben und 8 instabile Auslöser beschafft.","","Für diese Gegenstände müsst Ihr einen Schmied und einen Ingenieur finden."}}
D[6027] = {"Buch der Uralten",{"Beschafft das 'Buch der Uralten' und kehrt zu Azore Aldamort im Turm von Ethel Rethor zurück."}}
D[6028] = {"Der Bericht der Ewigen Warte",{"Bringt den Bericht der Ewigen Warte zu Argentumoffizier Reinherz im Zugwindlager in den westlichen Pestländern."}}
D[6029] = {"Der Bericht der Ewigen Warte",{"Bringt den Bericht der Ewigen Warte zu Argentumoffizier Garush im Bollwerk in den westlichen Pestländern."}}
D[6030] = {"Fürst Nicholas Zverenhoff",{"Bringt das Buch 'Studien über das Geistsprechen' zu Fürst Nicholas Zverenhoff in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[6031] = {"Runenstoff",{"Bringt 30 Runenstoff zu Meilosh in der Holzschlundfeste."}}
D[6032] = {"Hochheiliger Stoff",{"Bringt 2 Mondstoff zu Meilosh in der Holzschlundfeste."}}
D[6041] = {"When Smokey Sings, I Get Violent",{"Reist in den Pestwald, nordwestlich der Kapelle des hoffnungsvollen Lichts. Zerstört 8 Geißelbauwerke, indem Ihr Smokeys spezielles Präparat am Mal der Zerstörung in jedem Bauwerk benutzt. Smokey hat die Ziggurats und Schlachthäuser markieren lassen.","","Wenn ihr die Bombe gelegt habt, dann verlasst das Bauwerk und staunt über Euer Geschick.","","Übrigens, Smokeys spezielles Präparat ist recht...instabil."}}
D[6042] = {"Die kleinen Ärgernisse des Un-Lebens",{"Erschlagt 20 giftige Seuchenfledermäuse und 10 monströse Seuchenfledermäuse. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr fertig seid."}}
D[6061] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen ausgewachsenen Ebenenschreiter zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Yaw Scharfmähne ins Dorf der Bluthufe."}}
D[6062] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen scheckigen Terroreber zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Thotar in Klingenhügel."}}
