D[6101] = {"Die Zähmung der Bestie",{"Benutzt die Zähmerrute, um einen pirschenden Nachtsäbler zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6102] = {"Die Zähmung der Bestie",{"Benutzt die Zähmrute, um einen Strigidkreischer zu zähmen. Übt Eure Fertigkeiten und bringt die Zähmrute dann zu Dazalar in Dolanaar."}}
D[6103] = {"Die Ausbildung des Tiers",{"Sprecht mit Jocaste in der Enklave des Cenarius in Darnassus."}}
D[6121] = {"Neue Lektionen",{"Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen."}}
D[6122] = {"Die eigentliche Ursache",{"Benutzt das leere Gefäß bei den Klippenquellfällen und nehmt eine Wasserprobe vom Höhleneingang bei den Wasserfällen.","","Bringt die gefüllte Probe der Klippenquellfälle zu Alanndarian Nachtweise nach Auberdine in Dunkelküste."}}
D[6123] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 12 Lunarfungi zu Alanndarian Nachtweise in Auberdine, damit sie eine Heilsalbe machen kann."}}
D[6124] = {"Heilung der Kranken",{"Benutzt die heilende Tiersalbe bei 10 kränklichen Rehen in ganz Dunkelküste. Das müsste sie heilen. Es wurde berichtet, dass kränkliche Rehe südlich des Klippenquells, im Norden von Auberdine und bis hinunter in die südlichen Regionen von Dunkelküste, wo das Eschental beginnt, aufgetaucht ist."}}
D[6125] = {"Macht über Gift",{"Kehrt zu Mathrengyl Bärenfährte in der Enklave des Cenarius in Darnassus zurück."}}
D[6126] = {"Neue Lektionen",{"Reist zur Mondlichtung und sprecht mit Dendrite Sternenschauer im Dorf Nachthafen."}}
D[6127] = {"Die eigentliche Ursache",{"Benutzt die leere Glutnebelgipfelprobe beim Glutnebelgipfel und nehmt eine Wasserprobe vom Teich auf der Spitze des Gipfels.","","Bringt das gefüllte Behältnis vom Glutnebelgipfel zu Tonga Runentotem beim Wegekreuz im Brachland."}}
D[6128] = {"Das Heilmittel sammeln",{"Bringt 5 Erdwurzeln und 5 Kodohörner zu Tonga Runentotem beim Wegekreuz, damit er eine Heilsalbe machen kann."}}
D[6129] = {"Heilung der Kranken",{"Benutzt die heilende Tiersalbe bei 10 kränklichen Gazellen im nördlichen Teil des Brachlandes. Das müsste sie heilen. Kränkliche Gazellen wurden überall nördlich der Ost-West-Straße beim Wegekreuz gesehen."}}
D[6130] = {"Macht über Gift",{"Kehrt zu Turak Runentotem auf der Anhöhe der Ältesten in Donnerfels zurück."}}
D[6131] = {"Verbündeter der Holzschlundfeste",{"Grazle möchte, dass Ihr Euch beweist, indem Ihr 5 Krieger der Totenwaldfelle, 5 Pfadfinder der Totenwaldfelle und 5 Gärtner der Totenwaldfelle besiegt."}}
D[6132] = {"Holt mich hier raus!",{"Eskortiert Melizza Brummsumms und sprecht anschließend mit Hornizz Brummsumms beim Kodofriedhdof Desolace."}}
D[6133] = {"Das Ersuchen des Waldläuferlords",{"Begebt Euch zur nördlichsten Grenze der östlichen Pestländer und bringt die Registratur von Quel'Thalas zurück. Der Gegenstand befindet sich irgendwo in der Jagdhütte von Quel'Lithien.","","Außerdem müsst Ihr 8 Waldläufer, 8 Pfadschreiter und 8 Waldarbeiter töten."}}
D[6134] = {"Geisterplasmasuche",{"Bringt 8 Einheiten Geisterplasma und die Kiste mit den Geistermagneten zu Hornizz Brummsumms in Desolace."}}
D[6135] = {"Dämmerschwinge, oh, wie ich Euch hasse...",{"Sucht Dämmerschwinge und tötet ihn. Nehmt ein Büschel vom Fell Dämmerschwinges und bringt es zu Nathanos Pestrufer.","","Man sagt, dass Dämmerschwinge nördlich von hier durch das Land streift."}}
D[6136] = {"Der Korpulente",{"Sucht in den nördlichen Wüsten der östlichen Pestländer nach Blutschlinger und vernichtet ihn. Kehrt zu Nathanos Pestrufer zurück, sobald Ihr diese Mission erledigt habt."}}
D[6141] = {"Bruder Anton",{"Sprecht mit Bruder Anton in Nijelspitze in Desolace."}}
D[6142] = {"Muschelköder",{"Sucht 10 Teile Fleisch der weichschaligen Muschel und bringt sie zu Mai'Lahii im Dorf Schattenflucht."}}
D[6143] = {"Andere Fische zu grillen",{"Tötet 7 Myrmidonen der Zackenkämme, 7 Naga der Zackenkämme und 5 Zauberinnen der Zackenkämme, dann sprecht in Desolace mit Drulzegar in Schattenflucht."}}
D[6144] = {"Der Befehl",{"Reist nach Unterstadt und sprecht mit Bragor Blutfaust."}}
D[6145] = {"Der Purpurrote Kurier",{"Kehrt in die östlichen Pestländer zurück und spürt den Purpurroten Kurier auf. Tötet den Kurier und schnappt Euch den Befehl des obersten Kreuzzüglers.","","Bringt den Befehl zu Nathanos Pestrufer und wartet auf weitere Anweisungen."}}
D[6146] = {"Nathanos' List",{"Reist nach Tyrs Hand, südöstlich der Siedlung Marris. Dort angekommen beißt in den faulen Apfel. In der Verkleidung des Scharlachroten Kreuzzugs überbringt Ihr Lord Valdelmar den Befehl des obersten Kreuzzüglers."}}
D[6147] = {"Kehrt zu Nathanos zurück.",{"Kehrt mit der neuen Information zu Nathanos Pestrufer zurück."}}
D[6148] = {"Das scharlachrote Orakel Demetria",{"Der Scharlachrote Kreuzzug ist unterwegs. Irgendwo auf der Straße von Tyrs Hand nach Stratholme findet Ihr das Orakel Demetria und ihr Gefolge. Jagt sie und tötet sie. Kehrt zu Nathanos Pestrufer zurück, wenn Ihr erfolgreich wart."}}
D[6161] = {"Nehmt Rackmores Schatz!",{"Sucht Rackmores Silberschlüssel. Sucht Rackmores goldenen Schlüssel. Sucht und öffnet Rackmores Truhe."}}
D[6162] = {"Eines Ehemanns letzter Kampf",{"Tötet Oberanführer Ror und bringt seine Klaue zu Dreka'Sur beim Blutgiftposten im Teufelswald."}}
D[6163] = {"Ramstein",{"Reist nach Stratholme und tötet Ramstein den Verschlinger. Bringt seinen Kopf als Souvenir zu Nathanos."}}
D[6164] = {"Augustus' Quittungsbuch",{"Beschafft Euch Augustus' Quittungsbuch aus dem Gasthaus im Schreckenstal."}}
D[6181] = {"Eine eilige Nachricht",{"Bringt Lewis' Notiz zu Thor dem Greifenmeister."}}
D[6182] = {"Der Erste und Letzte",{"Sprecht mit Meister Mathias Shaw in der Altstadt von Sturmwind. Er wohnt in der Kaserne."}}
D[6183] = {"Ehret die Toten",{"Sprecht wieder mit Mathias Shaw, wenn Ihr seine Aufgabe annehmen wollt."}}
D[6184] = {"Flint Schattenmoor",{"Reist zum Zugwindlager in den westlichen Pestländern und trefft Euren Kontaktmann Flint Schattenmoor."}}
D[6185] = {"Die östlichen Pestländer",{"Sucht in den östlichen Pestländern nach Hinweisen auf den 'Pestrufer' und die vermissten SI:7-Agenten. Wenn Ihr SI:7-Insignien findet, bringt sie zu Flint Schattenmoor am Zugwindlager."}}
D[6186] = {"Der Pestrufer kommt",{"Kehrt nach Sturmwind zurück und informiert König Varian Wrynn über das Schicksal von Nathanos Marris."}}
D[6187] = {"Ordnung muss wieder hergestellt werden",{"Stellt eine Armee auf und reist zu den östlichen Pestländern. Beginnt einen gnadenlosen Angriff auf Nathanos Pestrufer und jeden Abschaum der Horde, der ihn beschützen mag.","","Bewahrt einen klaren Kopf, Sharmon. Die Horde wird den Waldläuferlord mit dem Leben verteidigen."}}
D[6221] = {"Totenwaldfelle des Nordens",{"Nafien möchte, dass Ihr 5 Höhlenbehüter der Totenwaldfelle, 5 Rächer der Totenwaldfelle und 5 Schamanen der Totenwaldfelle besiegt."}}
D[6241] = {"Aktivität der Winterfelle",{"Salfa möchte, dass Ihr 6 Totemiker der Winterfelle, 6 Höhlenbehüter der Winterfelle und 6 Pfadfinder der Winterfelle erledigt."}}
D[6261] = {"Dungar Trinkfest",{"Bringt Osrics Kiste zu Dungar Trinkfest dem Greifenmeister."}}
D[6281] = {"Weiter nach Sturmwind",{"Bucht einen Greifenritt bei Greifenmeister Thor, dann bringt Lewis' Notiz zu Osric Strang, im Laden Begrenzte Immunität, in Sturmwind."}}
D[6282] = {"Harpyien drohen",{"Maggran Erdbinder in Sonnenfels möchte, dass Ihr 7 Harpyien der Blutfurien, 7 Wegelagerinnen der Blutfurien, 7 Töterinnen der Blutfurien und 7 Wildfedern der Blutfurien erschlagt."}}
D[6283] = {"Blutfuriengeschlecht",{"Maggran in Sonnenfels möchte, dass Ihr die Zerfetzerin der Blutfurien beseitigt und ihre sterblichen Überreste als Beweis für Eure Tat mitbringt."}}
D[6284] = {"Arachnophobie",{"Tötet Besseleth und bringt Besseleths Fangzahn zu Maggran in Sonnenfels."}}
D[6285] = {"Zurück zu Lewis",{"Bucht einen Greifenritt zur Späherkuppe bei Greifenmeister Dungar Trinkfest, dann bringt Osrics Kiste zu Lewis an der Späherkuppe."}}
D[6301] = {"Zyklus der Wiedergeburt",{"Tammra Windfeld in Sonnenfels möchte, dass Ihr 10 Gaeasamenkörner sammelt."}}
D[6321] = {"Nachschub für das Grabmal",{"Bringt Podrigs Anforderungsliste zu Karos Razok."}}
D[6322] = {"Michael Garrett",{"Bringt Gordons Kiste zu Michael Garrett."}}
D[6323] = {"Flug nach Unterstadt",{"Bucht einen Fledermausritt zur Unterstadt bei Fledermausmeister Karos Razok und bringt dann Podrigs Anforderungsliste zu Gordon Wendheim in Unterstadt."}}
D[6324] = {"Rückkehr zu Podrig",{"Bucht einen Fledermausritt zum Grabmal bei Fledermausmeister Michael Garrett und bringt dann Gordons Kiste zu Todeswache Podrig beim Grabmal."}}
D[6341] = {"Die Arten von Teldrassil",{"Bringt Nessas Sammlung zu Vesprystus."}}
D[6342] = {"Flug nach Auberdine",{"Bucht bei Hippogryphenmeister Vesprystus einen Hippogryphen nach Auberdine und bringt dann Nessas Sammlung zu Laird."}}
D[6343] = {"Rückkehr zu Nessa",{"Bringt Lairds Antwort zu Nessa Schattensang."}}
D[6344] = {"Nessa Schattensang",{"Sprecht mit Nessa Schattensang."}}
D[6361] = {"Ein Bündel Bälge",{"Bringt das Bündel Bälge zu Windreitermeister Devrak beim Wegekreuz."}}
D[6362] = {"Flug nach Donnerfels",{"Bucht einen Windreiter nach Donnerfels bei Windreitermeister Devrak und bringt dann das Bündel Bälge zu Ahanu in Donnerfels."}}
D[6363] = {"Tal der Windreitermeister",{"Bringt Ahanus Lederwaren zu Tal in Donnerfels."}}
D[6364] = {"Rückkehr zu Jahan",{"Bucht einen Windreiter zum Wegekreuz bei Windreitermeister Tal und bringt dann Ahanus Lederwaren zu Jahan Falkenschwinge."}}
D[6365] = {"Fleisch für Orgrimmar",{"Bringt Zarghs Fleischwaren zu Devrak beim Wegekreuz."}}
D[6381] = {"Neues Leben",{"Pflanzt 10 Gaeasamenkörner in Gaeaerdhügel und bringt Tammra in Sonnenfels dann die restlichen verzauberten Gaeasamenkörner zurück."}}
D[6382] = {"Die Jagd im Eschental",{"Sprecht mit Senani Donnerherz im Splitterholzposten im Eschental."}}
D[6383] = {"Die Jagd im Eschental"}
D[6384] = {"Flug nach Orgrimmar",{"Bucht einen Windreiter nach Orgrimmar bei Windreitermeister Devrak und bringt dann Zarghs Fleischwaren zu Gryshka in Orgrimmar."}}
D[6385] = {"Doras der Windreitermeister",{"Bringt Gryshkas Brief zu Doras in Orgrimmar."}}
D[6386] = {"Kehrt zum Wegekreuz zurück",{"Bucht einen Windreiter zum Wegekreuz bei Windreitermeister Doras und bringt dann Gryshkas Brief zu Zargh beim Wegekreuz."}}
D[6387] = {"Ehrenstudenten",{"Bringt Brocks Liste zu Thorgrum Borrelson in Thelsamar."}}
D[6388] = {"Gryth Thurden",{"Bringt die Ehrenhacken zu Gryth Thurden in Eisenschmiede."}}
D[6389] = {"Eine Plage komme über Euch",{"Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestlandtermiten zu Nathaniel Dumah im Zugwindlager in den westlichen Pestländern zurück."}}
D[6390] = {"Eine Plage komme über Euch",{"Befreit die Pestlandtermiten im Sägewerk des Nordkamms, dann kehrt mit dem Fass Pestländer-Termiten zu Mickey Levine im Bollwerk in Tirisfal zurück."}}
D[6391] = {"Flug nach Eisenschmiede",{"Bucht einen Greifen nach Eisenschmiede von Greifenmeister Thorgrum Borrelson, dann bringt Brocks Liste zu Golnir Geröllzeh in Eisenschmiede."}}
D[6392] = {"Rückkehr zu Brock",{"Bucht einen Greifen nach Thelsamar bei Greifenmeister Gryth Thurden, dann bringt die Ehrenhacken zu Brock Steinsucher in Thelsamar."}}
D[6393] = {"Krieg der Elementare",{"Bringt 10 Pyrophore zu Tsunaman in Sonnenfels."}}
D[6394] = {"Thazz'rils Hacke",{"Bringt Thazz'rils Hacke zu Großknecht Thazz'ril."}}
D[6395] = {"Marlas letzter Wunsch",{"Bringt Samuel Fipps' sterbliche Überreste zu Marlas Grab und kehrt dann zu Novize Elreth zurück."}}
D[6401] = {"Kaya lebt",{"Teilt Tammra Windfeld, die in Sonnenfels lebt, die gute Nachricht mit."}}
D[6402] = {"Treffen in Sturmwind",{"Reist nach Sturmwind und begebt Euch zu den Stadttoren. Sprecht mit Knappe Rowe, damit er Marschall Windsor über Eure Ankunft informiert."}}
D[6403] = {"Die große Maskerade",{"Folgt Reginald Windsor durch Sturmwind. Schützt ihn vor Gefahren!"}}
D[6421] = {"Steinschlagklamm",{"Erkundet die Tiefen der Höhle in der Steinschlagklamm und bringt Mor'rogal in Sonnenfels 10 Resonitkristalle, damit er sie untersuchen kann."}}
D[6441] = {"Satyrhörner",{"Sammelt für Pixel im Splitterholzposten 16 Satyrhörner."}}
D[6442] = {"Die Naga am Zoramstrand",{"Bringt Marukai am Zoramstrand 20 Köpfe von Rächerflossen."}}
D[6461] = {"Blutfresser",{"Xen'zilla am Malaka'jin möchte, dass Ihr 10 Kluftmooskrabbler und 7 Kluftmoosgiftspucker tötet."}}
D[6462] = {"Trollglücksbringer",{"Bringt Mitsuwa beim Außenposten von Zoram'gar 8 Trollglücksbringer."}}
D[6481] = {"Der Irdene erhebt sich",{"Öffnet den Resonitbehälter mit dem verzauberten Resonitkristall und tötet Goggeroc. Kehrt mit der Vollzugsmeldung und dem verzauberten Resonitkristall zu Mor'rogal zurück."}}
D[6482] = {"Freiheit für Ruul",{"Begleitet Ruul und sprecht dann mit Yama Schneehuf im Splitterholzposten."}}
D[6501] = {"Das Großdrachenauge",{"Ihr müsst die Welt nach jemandem absuchen, der fähig ist, die Macht des Fragments des Großdrachenauges wieder herzustellen. Die einzige Information, die Ihr über ein solches Wesen besitzt ist, dass es existiert."}}
D[6502] = {"Drachenfeueramulett",{"Ihr müsst das Blut des schwarzen Drachenhelden von General Drakkisath bekommen. Ihr findet Drakkisath in seinem Thronsaal hinter den Hallen des Aufstiegs auf der Schwarzfelsspitze."}}
D[6503] = {"Die Kundschafter des Eschentals",{"Tötet 9 Kundschafter des Eschentals und kehrt dann zu Kuray'bin im Splitterholzposten zurück."}}
D[6504] = {"Die verlorenen Seiten",{"Findet die 12 fehlenden Seiten der Schredderanleitung und fügt sie zu den Kapiteln 1, 2 und 3 zusammen. Bringt die Seiten zu Gurda Zornnarbe in der Nähe des Splitterholzpostens zurück."}}
D[6521] = {"Eine unheilige Allianz",{"Bringt den Kopf von Botschafter Malcin zu Bragor Blutfaust nach Unterstadt."}}
D[6522] = {"Eine unheilige Allianz",{"Bringt die kleine Rolle zu Bragor Blutfaust im Königsviertel von Unterstadt."}}
D[6523] = {"Schützt Kaya",{"Begleitet Kaya Flachhuf zum Camp Aparaje und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6541] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6542] = {"Meldung bei Kadrak",{"Meldet Euch im Wachturm im Norden des Brachlands bei Kadrak."}}
D[6543] = {"Die Berichte des Kriegshymnenklans",{"Öffnet die gebündelten Berichte. Bringt die Berichte des Kriegshymnenklans dem Späher des Kriegshymnenklans, dem Läufer des Kriegshymnenklans und der Vorhut des Kriegshymnenklans. Meldet die Neuigkeiten, die Ihr von ihnen erfahrt, Kadrak im nördlichen Wachturm des Brachlands."}}
D[6544] = {"Toreks Angriff",{"Eskortiert Torek bei seinem Angriff auf den Außenposten der Silberschwingen und Duriel Mondfeuer. Erstattet dann Ertog Zornhauer im Splitterholzposten Bericht."}}
D[6545] = {"Aktualisierter Bericht des Läufers des Kriegshymnenklans"}
D[6546] = {"Aktualisierter Bericht der Vorhut des Kriegshymnenklans"}
D[6547] = {"Aktualisierter Bericht des Spähers des Kriegshymnenklans"}
D[6548] = {"Rächt mein Dorf",{"Tötet 8 Grobiane der Grimmtotem und 6 Söldner der Grimmtotem. Kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6561] = {"Schurkerei in der Tiefschwarzen Grotte",{"Bringt den Kopf von Zwielichtfürst Kelris zu Bashana Runentotem in Donnerfels."}}
D[6562] = {"Ärger in der Tiefe",{"Sprecht im Eschental mit Je'neu Sancrea."}}
D[6563] = {"Die Essenz von Aku'mai",{"Bringt 20 Saphire von Aku'mai zu Je'neu Sancrea im Eschental."}}
D[6564] = {"Treue zu den Alten Göttern",{"Bringt die durchfeuchtete Notiz zu Je'neu Sancrea im Außenposten von Zoram'gar im Eschental."}}
D[6565] = {"Treue zu den Alten Göttern",{"Tötet Lorgus Jett in der Tiefschwarzen Grotte und kehrt dann zu Je'neu Sancrea ins Eschental zurück."}}
D[6566] = {"Was der Wind erzählt",{"Hört Thrall zu."}}
D[6567] = {"Der Champion der Horde",{"Sucht in Schattenflucht in Desolace nach Rokaro."}}
D[6568] = {"Meisterin der Illusionen",{"Überbringt Myranda der Vettel in den westlichen Pestländern Rokaros Brief."}}
D[6569] = {"Oculus-Illusionen",{"Reist zur Schwarzfelsspitze und sammelt 20 schwarze Drachenbrutaugen. Kehrt zu Myranda der Vettel zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[6570] = {"Aschenschwinge",{"Reist zum Drachensumpf in den Düstermarschen und begebt Euch in Aschenschwinges Bau. Sobald Ihr darin seid, tragt das Amulett der drachischen Subversion und sprecht mit Aschenschwinge."}}
D[6571] = {"Nachschub des Kriegshymnenklans",{"Tragt den Nachschub des Kriegshymnenklans zusammen: Sägeblätter des Kriegshymnenklans, ein Holzfällerseil, Öl des Kriegshymnenklans und die Axtlieferung des Kriegshymnenklans für Locke Okarr im Splitterholzposten."}}
D[6581] = {"Sägeblätter des Kriegshymnenklans"}
D[6582] = {"Die Prüfung der Schädel, Seher",{"Ihr müsst Seher, den Champion der blauen Großdrachen, finden und ihn töten. Schlagt seinem Kadaver den Schädel ab und bringt ihn zu Aschenschwinge.","","Ihr wisst, dass Seher in Winterquell zu finden ist."}}
D[6583] = {"Die Prüfung der Schädel, Somnus",{"Vernichtet den Drachenchampion des grünen Drachenschwarms, Somnus. Nehmt seinen Schädel und bringt ihn zu Aschenschwinge zurück."}}
D[6584] = {"Die Prüfung der Schädel, Chronalis",{"Chronalis, ein Kind Nozdormus, bewacht die Höhlen der Zeit in der Tanariswüste. Vernichtet ihn und bringt seinen Schädel zu Aschenschwinge."}}
D[6585] = {"Die Prüfung der Schädel, Axtroz",{"Begebt Euch nach Grim Batol und spürt Axtroz auf, den Drachenchampion des roten Drachenschwarms. Vernichtet ihn und nehmt seinen Schädel. Bringt den Schädel zu Aschenschwinge zurück."}}
D[6601] = {"Aufstieg...",{"Mir scheint, als sei die Charade jetzt vorüber. Ihr wisst, dass das Amulett der drachischen Unterwanderung, das Myranda die Vettel für Euch erschuf, auf der Schwarzfelsspitze nicht funktioniert. Vielleicht solltet Ihr Rokaro aufsuchen und ihm Eure Notlage erklären. Zeigt ihm das glanzlose Drachenfeueramulett. Er wird hoffentlich wissen, was als Nächstes zu tun ist."}}
D[6602] = {"Blut des schwarzen Großdrachenhelden",{"Begebt Euch zur Schwarzfelsspitze und tötet General Drakkisath. Sammelt sein Blut und bringt es zu Rokaro."}}
D[6603] = {"Probleme in Winterquell!",{"Findet Donova Schneeweh bei den Thermalquellen in Winterquell."}}
D[6604] = {"Wütende Wildekin",{"Sprecht mit Jaron Steinschleifer in Sternfall."}}
D[6605] = {"Eine seltsame Person",{"Sprecht im Teufelswald mit Winna Hazzard."}}
D[6606] = {"Ein bisschen Glück",{"Sprecht in der Ewigen Warte mit Hexendoktorin Mau'ari."}}
D[6607] = {"Nat Pagle, Extremangler",{"Nat Pagle möchte, dass Ihr folgende Fische fangt:","","Nebelschilf-Mahi Mahi vom Nebelschilfstrand in den Sümpfen des Elends.","","Einen Sar'therisbarsch vom Sar'therisstrand in Desolace.","","Feralas-Ahi aus dem Verdantis in Feralas.","","Blauwimpel von der ungezähmten Küste im Schlingendorntal.","","Kehrt zu Nat Pagle zurück, wenn Ihr alle an Land gezogen habt!"}}
D[6608] = {"Ihr zu gut",{"Ihr nehmt an, dass Lumak Euch zu erklären versucht, dass er nicht mehr tun kann, um Eure Angelfertigkeit zu verbessern. Ihr solltet seinen Freund aufsuchen, diesen Nat Pagle, einen Menschen, der auf einer der Inseln südlich von Theramore (jedenfalls glaubt Ihr, dass Lumak das gemeint hat) auf Fischfang geht."}}
D[6609] = {"Ich hab nix mehr!",{"Reist nach Kalimdor zur Küstenstadt Theramore. Dort müsst Ihr nach einer Insel suchen, die südlich der Hauptstadt liegt. Nat Pagle erwartet Euch!"}}
D[6610] = {"Muschelette Surprise",{"Dirge Schnetzelhack möchte, dass Ihr folgende Dinge besorgt:","","10 Rieseneier. Ihr findet sie bei den Rocs, die Tanaris durchstreifen, oder anderen Großvogelarten.","","10 Stück scharfes Muschelfleisch. Die findet Ihr natürlich in Muscheln!","","20 Stück Alteraclochkäse. Begebt Euch zu einer Käserei!","","Sammelt all diese Gegenstände und kehrt dann zu Dirge zurück."}}
D[6611] = {"Ab mit Euch nach Gadgetzan!",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere."}}
D[6612] = {"Ich kenne einen Typen...",{"Reist nach Gadgetzan in der Tanariswüste und sprecht mit Dirge Schnetzelhack über den Ausbau Eurer Kochkarriere."}}
D[6621] = {"König der Fäulnisklauen",{"Platziert Karangs Banner auf dem Totemhügel der Fäulnisklauen. Die Furbolgs dürfen das Banner nicht zerstören. Besiegt Häuptling Murgut und bringt Murguts Totem zu Karang Amakkar in Zoram'gar."}}
D[6622] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6623] = {"Traumachirurg der Horde",{"Reist nach Hammerfall im Arathihochland und sprecht mit Doktor Gregory Victor darüber, dass Ihr auch ein Traumachirurg der Horde werden wollt."}}
D[6624] = {"Triage",{"Rettet Patienten, indem Ihr deren Wunden mit Triagenverbänden versorgt. Ihr müsst 15 Patienten retten, bevor 6 von ihnen ihren Verletzungen erliegen.","","Denkt an die Einhaltung der Reihenfolge! Schwerstverletzte Soldaten sterben am schnellsten, dann die schwer verletzten Soldaten. Bei verletzten Soldaten dauert es etwas länger, bis sie sterben. Ihr solltet sie retten, NACHDEM Ihr die schwerstverletzten und schwer verletzten Soldaten selektiert habt."}}
D[6625] = {"Traumachirurg der Allianz",{"Reist nach Theramore in die Düstermarschen und sprecht mit Doktor Gustav van Howzen darüber, dass Ihr auch ein Traumachirurg der Allianz werden wollt."}}
D[6626] = {"Ein Hort des Bösen",{"Tötet 8 Schlachtwachen der Klingenhauer, 8 Dornenwirker der Klingenhauer und 8 Kultistinnen der Totenköpfe und kehrt dann zu Myriam Mondsang nahe dem Eingang zu den Hügeln der Klingenhauer zurück."}}
D[6627] = {"Test der Lehre",{"Beantwortet Braug Dämmergeists Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch im Steinkrallengebirge sein, wenn Ihr bereit seid."}}
D[6628] = {"Test der Lehre",{"Beantwortet Parqual Fintallas' Frage richtig und sprecht dann erneut mit ihm. Er wird immer noch in Unterstadt sein, wenn Ihr bereit seid."}}
D[6629] = {"Tötet Grundig Finsterwolke",{"Tötet Grundig Finsterwolke und 6 Schläger der Grimmtotem und kehrt dann zu Makaba Flachhuf am südöstlichen Rand des Steinkrallengebirges zurück."}}
D[6641] = {"Vorsha die Peitscherin",{"Beschützt Muglash, wenn er zu der Kohlenpfanne reist. Helft ihm, indem Ihr die Kohlenpfanne löscht, und beschützt ihn dann, während Ihr gegen die Naga kämpft.","","Wenn Ihr erfolgreich gewesen seid, kehrt zum Außenposten von Zoram'gar zurück und informiert den Läufer des Kriegshymnenklans über den Tod von Vorsha der Peitscherin."}}
D[6642] = {"Gunst der Bruderschaft, Dunkeleisenerz"}
D[6643] = {"Gunst der Bruderschaft, Feuerkern"}
D[6644] = {"Gunst der Bruderschaft, Lavakern"}
D[6645] = {"Gunst der Bruderschaft, Kernleder"}
D[6646] = {"Gunst der Bruderschaft, Blut des Berges"}
D[6661] = {"Tiefenbahn-Ratten-Razzia",{"Fangt mithilfe der Rattenfängerflöte 5 Untergrundratten in der Tiefenbahn. Führt die Ratten zu Monty. Und vergesst nicht, die Flöte zurückzugeben, wenn Ihr fertig seid."}}
D[6662] = {"Mein Bruder Nipsy...",{"Bringt den Karton mit eigenartigem Fleisch zu Nipsy im Tiefenbahndepot von Sturmwind."}}
D[6681] = {"Das Anwesen, Rabenholdt",{"Bringt das Siegel von Rabenholdt zu Fahrad im Rabenholdtanwesen, das versteckt in den Hügeln des Hügellands liegt.","","Unterwegs wird man Eure Schlauheit testen. Seid darauf gefasst."}}
D[6701] = {"Syndikatsembleme"}
D[6721] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar in Teldrassil."}}
D[6722] = {"Der Weg des Jägers",{"Sprecht mit Dazalar in Dolanaar in Teldrassil."}}
D[6741] = {"Mehr Beute!"}
D[6761] = {"Die neue Grenze",{"Sprecht mit Mathrengyl Bärenfährte in der Enklave des Cenarius von Darnassus."}}
D[6762] = {"Rabine Saturna",{"Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung. Die Mondlichtung liegt zwischen dem Teufelswald und Winterquell, und Ihr erreicht es über den Pfad, der aus der Holzschlundfeste herausführt."}}
D[6781] = {"Mehr Rüstungsfetzen"}
D[6801] = {"Lokholar der Eislord"}
D[6804] = {"Vergiftetes Wasser",{"Wendet den Aspekt von Neptulon auf die vergifteten Elementare der östlichen Pestländer an. Bringt 12 disharmonische Armschienen, sowie den Aspekt von Neptulon zu Fürst Hydraxis in Azshara."}}
D[6805] = {"Stürmer und Rumpler",{"Tötet 15 Staubstürmer und 15 Wüstenrumpler und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6821] = {"Auge des Glutsehers",{"Bringt das Auge des Glutsehers zu Fürst Hydraxis in Azshara."}}
D[6822] = {"Der geschmolzene Kern",{"Tötet 1 Feuerlord, 1 geschmolzenen Riesen, 1 uralten Kernhund sowie 1 Lavawoger und kehrt dann zu Fürst Hydraxis in Azshara zurück."}}
D[6823] = {"Agent von Hydraxis",{"Verdient Euch eine geehrte Fraktion bei den hydraxianischen Wasserlords und sprecht dann mit Fürst Hydraxis in Azshara."}}
D[6824] = {"Hände des Feindes",{"Bringt die Hände von Lucifron, Sulfuron, Gehennas und Shazzrah zu Fürst Hydraxis in Azshara."}}
D[6825] = {"Ruf der Lüfte - Guses Luftflotte"}
D[6826] = {"Ruf der Lüfte - Jeztors Luftflotte"}
D[6827] = {"Ruf der Lüfte - Mulvericks Luftflotte"}
D[6843] = {"Da Foo"}
D[6844] = {"Umber, Archivar",{"Bringt das verkrustete Silithidenobjekt zu Umber, dem Archivar des Zirkels des Cenarius, ins Dorf Nachthafen auf der Mondlichtung."}}
D[6845] = {"Enthüllung von Geheimnissen der Vergangenheit",{"Sprecht mit Rabine Saturna im Dorf Nachthafen auf der Mondlichtung."}}
D[6846] = {"Der Angriff soll beginnen!"}
D[6847] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6848] = {"Meister Rysons Allsehendes Auge",{"Holt das allsehende Auge von Meister Ryson aus den Höhlen der Winterax und kehrt damit zu Meister Ryson zurück.","","Seid gewarnt, man sagt, dass das allsehende Auge von Meister Ryson einen schrecklicken Fluch mit sich brächte!"}}
D[6861] = {"Zinnzischelix's tragbare Schreddereinheit",{"Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
D[6862] = {"Zinnzischelix's tragbare Schreddereinheit",{"Meisteringenieur Zinnzischelix möchte, dass Ihr ihm Folgendes bringt:","","*30 Thoriumbarren.","","*50 Mithrilbarren.","","*75 Eisenbarren.","","*1 Dampfsäge."}}
D[6881] = {"Ivus der Waldfürst"}
D[6901] = {"Startet den Angriff!"}
D[6921] = {"Inmitten der Ruinen",{"Bringt den Tiefenkern zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
D[6922] = {"Baron Aquanis",{"Bringt die seltsame Wasserkugel zu Je'neu Sancrea beim Außenposten von Zoram'gar im Eschental."}}
