D[6942] = {"Ruf der Lüfte - Slidores Luftflotte"}
D[6943] = {"Ruf der Lüfte - Ichmans Luftflotte"}
D[6961] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[6962] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Orgrimmar."}}
D[6963] = {"Gestohlene Winterhauchleckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[6964] = {"Der Anlass für die Feiertage",{"Sprecht mit Sagorne Gratläufer im Tal der Weisheit von Orgrimmar über das Winterhauchfest."}}
D[6981] = {"Der leuchtende Splitter",{"Begebt Euch nach Ratschet, um jemanden zu finden, der Euch mehr über den leuchtenden Splitter sagen kann.","","Liefert dann den Splitter ab, wie Ihr angewiesen wurdet."}}
D[6982] = {"Vorräte der Eisbeißermine",{"Bringt 10 Vorräte der Eisbeißermine zum Rüstmeister der Allianz in Dun Baldar."}}
D[6983] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Kaymard Kupferzwick nach Orgrimmar. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet."}}
D[6984] = {"Ein Dankeschön von Kokelwälder!"}
D[6985] = {"Vorräte der Eisenschachtmine",{"Bringt 10 Vorräte der Eisenschachtmine zum Rüstmeister der Horde in die Burg Frostwolf."}}
D[7001] = {"Verwaiste Ställe",{"Findet einen Frostwolf im Alteractal. Wenn Ihr Euch in der Nähe eines Frostwolfs befindet, benutzt den Frostwolfmaulkorb um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Frostwolf bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7002] = {"Widderledernes Zaumzeug"}
D[7003] = {"Geschrumpfte Riesen",{"Benutzt Zorbins Ultraschrumpfer um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt Zorbin von Schiller 15 Schrumpfüberreste von diesen Riesen. Ihr findet Ihn bei den Docks, an der vergessenen Küste in Feralas."}}
D[7021] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7022] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede."}}
D[7023] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Eisenschmiede."}}
D[7024] = {"Altvater Winter ist hier!",{"Sprecht mit Altvater Winter. Er befindet sich in der Nähe des Verkaufsbereichs von Kokelwälder in Orgrimmar."}}
D[7025] = {"Leckereien für Altvater Winter",{"Bringt 5 Lebkuchen und etwas eiskalte Milch zu Altvater Winter in Eisenschmiede."}}
D[7026] = {"Widderzaumzeug"}
D[7027] = {"Verwaiste Ställe",{"Findet einen Alteracwidder im Alteractal. Wenn Ihr Euch in der Nähe eines Alteracwidders befindet, benutzt das Zähmungshalsband der Sturmlanzen um das Tier einzufangen. Nach erfolgreicher Zähmung, folgt Euch der Alteracwidder bis zum Stallmeister zurück. Sprecht mit dem Stallmeister um für Euren Fang belohnt zu werden."}}
D[7028] = {"Dunkles Böses",{"Sammelt 15 theradrische Kristallschnitzereien für Trista in Desolace."}}
D[7029] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Vark Schlachtnarbe in Schattenflucht zurück."}}
D[7041] = {"Schlangenzunges Verderbnis",{"Füllt die beschichtete himmelblaue Phiole am orangefarbenen Kristallteich in Maraudon.","","Benutzt die gefüllte himmelblaue Phiole mit den Schlangenstrunkranken, damit der verderbte Noxxiousspross herausgezwungen wird.","","Heilt 8 Pflanzen, indem Ihr diesen Noxxiousspross tötet und kehrt dann zu Talendria an der Nijelspitze zurück."}}
D[7042] = {"Gestohlene Winterhauchleckereien",{"Sucht den Ermittler von Kokelwälder, der im Alteracgebirge vermisst wird."}}
D[7043] = {"So was Gemeines...",{"Sucht die gestohlenen Leckereien und bringt sie zu Wulmort Klingeltaschen nach Eisenschmiede. Zuletzt befanden sie sich im Besitz des monströsen Griesgrams, der sich in den Schneegebieten des Alteracgebirges befindet."}}
D[7044] = {"Legenden von Maraudon",{"Beschafft die beiden Teile des Szepters von Celebras: den Celebriangriff und den Celebriandiamanten.","","Findet einen Weg, um mit Celebras zu sprechen."}}
D[7045] = {"Ein Dankeschön von Kokelwälder!"}
D[7046] = {"Das Szepter von Celebras",{"Helft Celebras dem Erlösten, während er das Szepter von Celebras herstellt.","","Sprecht mit ihm, nachdem das Ritual vollendet ist."}}
D[7061] = {"Das Winterhauchfest",{"Ihr könnt gern das Buch 'Das Winterhauchfest' lesen, um mehr über diesen Feiertag zu erfahren. Wenn Ihr das Buch gelesen habt, bringt es zu Cairne Bluthuf in Donnerfels."}}
D[7062] = {"Der Anlass für die Feiertage",{"Sprecht mit dem Historiker Karnik in der Forscherliga von Eisenschmiede über das Winterhauchfest."}}
D[7063] = {"Das Winterhauchfest"}
D[7064] = {"Verderbnis von Erde und Samenkorn",{"Tötet Prinzessin Theradras und kehrt zu Selendra in der Nähe von Schattenflucht in Desolace zurück."}}
D[7065] = {"Verderbnis von Erde und Samenkorn",{"Erschlagt Prinzessin Theradras und kehrt zum Bewahrer Marandis an der Nijelspitze in Desolace zurück."}}
D[7066] = {"Samenkorn des Lebens",{"Sucht Remulos bei der Mondlichtung auf und gebt ihm das Samenkorn des Lebens."}}
D[7067] = {"Die Anweisungen des Pariahs",{"Lest die Anweisungen des Pariahs. Beschafft Euch danach das Amulett der Vereinigung von Maraudon und bringt es dem Zentaurenpariah im südlichen Desolace."}}
D[7068] = {"Schattensplitter",{"Sammelt 10 Schattensplitter aus Maraudon und bringt sie zu Uthel'nay nach Orgrimmar."}}
D[7070] = {"Schattensplitter",{"Sammelt 10 Schattensplitter in Maraudon und bringt sie zu Erzmagier Tervosh in den Düstermarschen."}}
D[7081] = {"Die Friedhöfe im Alteractal",{"Erobert einen Friedhof und kehrt zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7082] = {"Die Friedhöfe von Alterac",{"Erobert einen Friedhof und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück."}}
D[7101] = {"Türme und Bunker",{"Erobert einen gegnerischen Turm und kehrt anschließend zu Korporal Teeka Murrblut im Alteracgebirge zurück."}}
D[7102] = {"Türme und Bunker",{"Zerstört das Banner im Inneren eines gegnerischen Bunkers oder Turms. Kehrt anschließend zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7121] = {"Der Rüstmeister",{"Sprecht mit dem Rüstmeister der Sturmlanzen."}}
D[7122] = {"Mine besetzen",{"Erobert eine Mine, die die Sturmlanzen noch nicht kontrollieren, und kehrt dann zu Unteroffizier Durgen Sturmlanze im Alteracgebirge zurück."}}
D[7123] = {"Sprecht mit unserem Rüstmeister",{"Sprecht mit dem Rüstmeister der Frostwölfe."}}
D[7124] = {"Eine Mine besetzen",{"Erobert eine Mine und kehrt zu Korporal Teeka Murrblut im Alteracgebirge zurück."}}
D[7141] = {"Die Schlacht um Alterac",{"Betretet das Alteractal, bezwingt den Hordegeneral Drek'thar und kehrt dann zu Ausgrabungsleiter Steinhauer im Alteracgebirge zurück."}}
D[7142] = {"Die Schlacht ums Alteractal",{"Betretet das Alteractal und bezwingt den Zwergengeneral, Vanndar Sturmlanze. Kehrt anschließend zu Voggah Todesgriff im Alteracgebirge zurück."}}
D[7161] = {"Flaggenjagd",{"Begebt Euch in die Höhle der Wildpfoten südöstlich vom Hauptstützpunkt im Alteractal und findet das Banner der Frostwölfe. Bringt anschließend Kriegsmeister Laggrond das Banner."}}
D[7162] = {"Flaggenjagd",{"Begebt Euch in die Eisschwingenhöhle südwestlich von Dun Baldar im Alteractal und findet das Banner der Sturmlanzen. Bringt anschließend Leutnant Haggerdin im Alteracgebirge das Banner."}}
D[7163] = {"Aufstieg und Anerkennung"}
D[7164] = {"Ehre innerhalb des Klans"}
D[7165] = {"Verdiente Ehrerbietung"}
D[7166] = {"Legendäre Helden"}
D[7167] = {"Das Auge der Führung"}
