D[7170] = {"Verdiente Ehrerbietung"}
D[7171] = {"Legendäre Helden"}
D[7172] = {"Das Auge der Führung"}
D[7181] = {"Die Legende von Korrak",{"Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.","","Solltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Kriegsmeister Laggrond im Alteracgebirge zurück."}}
D[7201] = {"Das letzte Element",{"Begebt Euch in die Schwarzfelstiefen und beschafft 10 Essenzen der Elemente. Euer erster Gedanke ist, die Golems und die Schöpfer der Golems zu suchen. Doch Ihr erinnert Euch, dass Vivian Lagrave auch etwas von Elementaren vor sich hingemurmelt hat."}}
D[7202] = {"Korrak der Blutrünstige",{"Den Legenden nach erscheint der mächtige Anführer der Winteraxtrolle nach Belieben, um Chaos unter den Bewohnern des Alteractals zu stiften.","","Solltet Ihr ihn zu Gesicht bekommen, dann vernichtet ihn und kehrt zu Leutnant Haggerdin im Alteracgebirge zurück."}}
D[7221] = {"Sprecht mit Ausgrabungsleiter Steinhauer",{"Sprecht mit Ausgrabungsleiter Steinhauer in der Garnison von Dun Baldar."}}
D[7222] = {"Sprecht mit Voggah Todesgriff",{"Sprecht mit Voggah in Burg Frostwolf."}}
D[7223] = {"Rüstungsfetzen",{"Bringt Murgot Tiefenschmied in Dun Baldar 20 Rüstungsfetzen."}}
D[7224] = {"Beutezug im Feindesland",{"Bringt 20 Rüstungsfetzen zu Schmied Regzar im Dorf der Frostwölfe."}}
D[7241] = {"Die Verteidigung der Frostwölfe",{"Reist ins Alteractal, das sich im gleichnamigen Gebirge befindet. Sucht dort außerhalb des Tunneleingangs Kriegsmeister Laggrond auf und beginnt Eure Karriere als Soldat der Frostwölfe. Das Alteractal findet Ihr nördlich von Tarrens Mühle am Fuß des Alteracgebirges."}}
D[7261] = {"Die hoheitliche Anordnung",{"Reist ins Alteractal im Vorgebirge des Hügellands. Wenn Ihr dort angekommen seid, meldet Euch umgehend bei Leutnant Haggerdin.","","Für den Ruhm von Bronzebart!"}}
D[7281] = {"Bruderliebe",{"Begebt Euch ins Gebiet der Sturmlanzen und tötet Kommandant Karl Philips. Kehrt zu Kommandant Louis Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7282] = {"Bruderliebe",{"Begebt euch ins Frostwolfgebiet und tötet Kommandant Louis Philips. Kehrt zu Kommandant Karl Philips zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[7301] = {"Gefallene Himmelsstürmer",{"Begebt Euch ins Frostwolfterritorium und sucht nach Schwadronskommandant Slidore, Schwadronskommandant Vipore und Schwadronskommandant Ichman. Meldet Euch bei Kommandant Duffy, sobald Ihr Eure Mission erfüllt habt."}}
D[7302] = {"Gefallene Himmelsstürmer",{"Findet heraus was aus Schwadronskommandant Guse, Schwadronskommandant Jeztor, und Schwadronskommandant Mulverick geworden ist. Wenn Eure Mission erfüllt ist, kehrt zu Kommandant Mulfort zurück."}}
D[7321] = {"Milde Schildkrötensuppe",{"Bringt 10 Stücke Schildkrötenfleisch zu Christoph Jeffkott in Tarrens Mühle."}}
D[7341] = {"Ein gerechter Handel"}
D[7342] = {"Pfeile sind was für Memmen"}
