D[7441] = {"Pusillin und der Älteste Azj'Tordin",{"Reist nach Düsterbruch und macht den Dämonen Pusillin ausfindig. Überzeugt ihn mit allen Mitteln davon, Euch Azj'Tordin's Buch der Zauberformeln zu geben.","","Kehrt mit dem Buch zu Az'Tordin, beim Larisspavillon in Feralas, zurück."}}
D[7461] = {"Der innere Wahnsinn",{"Zerstört alle Wächter, die um die 5 Pylonen herumstehen, welche Immol'thars Gefängnis mit Energie versorgen. Sobald die Pylone deaktiviert wurden, wird sich das Kraftfeld, das Immol'thar umgibt, auflösen.","","Betretet Immol'thars Gefängnis und vernichtet den verdorbenen Dämonen. Anschließend müsst Ihr Prinz Tortheldrin im Athenaeum entgegentreten.","","Kehrt nach Abschluss der Aufgabe zur uralten Shen'dralar im Hof zurück."}}
D[7462] = {"Der Schatz der Shen'dralar",{"Kehrt in das Athenaeum zurück und sucht den Schatz der Shen'dralar. Nehmt Euch Eure Belohnung!"}}
D[7463] = {"Arkane Erfrischung",{"Reist nach Düsterbruch in das Wucherborkenviertel und besiegt den Wasserelementar Hydrobrut. Kehrt anschließend mit der Hydrobrutessenz zum Hüter des Wissens Lydros im Athenaeum zurück."}}
D[7481] = {"Elfische Legenden",{"Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei dem Weisen Korolusk in Camp Mojache."}}
D[7482] = {"Elfische Legenden",{"Sucht in Düsterbruch nach Telmius Traumsucher. Meldet Euch anschließend bei der Gelehrten Runendorn in der Mondfederfeste."}}
D[7483] = {"Buchband der Schnelligkeit",{"Bringt ein Buchband der Schnelligkeit, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 2 mal das Blut von Helden, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum der Schnelligkeit zu erhalten."}}
D[7484] = {"Buchband des Fokus",{"Bringt ein Buchband des Fokus, 1 makellosen schwarzen Diamanten, 4 große glänzende Splitter und 2 mal Schattenhaut, zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Fokus zu erhalten."}}
D[7485] = {"Buchband des Schutzes",{"Bringt ein Buchband des Schutzes, 1 makellosen schwarzen Diamanten, 2 große glänzende Splitter und 1 ausgefranste Monstrositätenstickerei zum Hüter des Wissens Lydros in Düsterbruch, um ein Arkanum des Schutzes zu erhalten."}}
D[7486] = {"Die Belohnung eines Helden",{"Nehmt Eure Belohnung aus Hydraxis' Kasten."}}
D[7487] = {"Abstimmung mit dem Kern",{"Begebt Euch zum Portal in den Schwarzfelstiefen, das in den geschmolzenen Kern führt, und findet ein Kernfragment. Kehrt mit dem Fragment zu Lothos Felsspalter am Schwarzfels zurück."}}
D[7488] = {"Lethtendris' Netz",{"Bringt Lethtendris' Netz zu Latronicus Mondspeer in der Mondfederfeste in Feralas."}}
D[7489] = {"Lethtendris' Netz",{"Bringt Lethtendris' Netz zu Talo Dornhuf im Camp Mojache in Feralas."}}
D[7490] = {"Sieg für die Horde",{"Bringt Onyxias Kopf zu Thrall in Orgrimmar."}}
D[7491] = {"Für alle sichtbar",{"Sucht Oberanführer Runthak im Tal der Stärke auf."}}
D[7492] = {"Camp Mojache",{"Sprecht mit Talo Dornhuf in Camp Mojache, in Feralas."}}
