D[7494] = {"Die Mondfederfeste",{"Sprecht mit Latronicus Mondspeer in der Mondfederfeste in Feralas."}}
D[7495] = {"Sieg für die Allianz",{"Bringt Onyxias Kopf zu König Varian Wrynn in Sturmwind."}}
D[7496] = {"Gute Zeiten feiern",{"Sucht Major Mattingly im Tal der Helden auf."}}
D[7497] = {"Die Reise beginnt erst"}
D[7498] = {"Garona: Eine Studie über Heimlichkeit und Verrat",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7499] = {"Kodex der Verteidigung",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7500] = {"Das Arkanistenkochbuch",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7501] = {"Vom Licht und wie man es schwingt",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7502] = {"Schatten einspannen",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7503] = {"Das größte Volk von Jägern",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7504] = {"Heiliger Fleischklops: Was das Licht Dir nicht erzählt",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7505] = {"Frostschock und Du",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7506] = {"Der Smaragdgrüne Traum",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
D[7507] = {"Nostro's Compendium",{"Return Nostro's Compendium of Dragon Slaying to the Athenaeum."}}
D[7508] = {"Das Schmieden von Quel'Serrar"}
D[7509] = {"The Forging of Quel'Serrar",{"You must get Onyxia to breathe fire on the Unfired Ancient Blade. Once this is done, pick up the now Heated Ancient Blade. Be warned, a Heated Ancient Blade will not remain heated forever - time is of the essence.","","The last step before returning to me is to slay the beast and drive the Heated Ancient Blade into her corpse.","","Do this and Quel'Serrar will be yours."}}
D[7521] = {"Donneraan der Windsucher"}
D[7522] = {"Untersuchung des Gefäßes"}
D[7541] = {"Dienst an der Horde"}
D[7562] = {"Mor'zul Blutbringer",{"Sprecht mit Mor'zul Blutbringer beim Altar der Stürme in der brennenden Steppe."}}
D[7563] = {"Kochendes Blut",{"Mor'zul Blutbringer in der brennenden Steppe möchte, dass Ihr ihm 30 Flaschen mit dem Blut der tobenden Bestien bringt."}}
D[7564] = {"Wildaug",{"Bringt den Behälter mit Blut zu Gorzeeki Wildaug beim Altar der Stürme in der brennenden Steppe."}}
D[7581] = {"Das Fundament des Gefängnisses",{"Reist nach Düsterbruch in Feralas und holt Euch das Blut von 15 Satyrn der Wildhufe, die im Wucherborkenviertel ansässig sind. Kehrt anschließend zu Daio in der faulenden Narbe zurück."}}
D[7582] = {"Die Gefängnishülle",{"Reist in die flüsternde Schlucht in Winterquell und besorgt Euch 5 Tränen bei den Dämonen von Hederine, die in der Schlucht leben. Kehrt zu Daio in der faulenden Narbe zurück, sobald Ihr diese Aufgabe vollständig erledigt habt."}}
D[7583] = {"Unterdrückung",{"Wagt Euch in die faulende Narbe heraus und macht einen Kommandant der Verdammniswache ausfindig.","","Wendet das leuchtende Kristallgefängnis auf den Kommandanten der Verdammniswache an. Bereitet Euch auf eine heftige Serie von Attacken vor, da der Dämon alles gegen seine Gefangennahme unternehmen wird.","","Solltet Ihr erfolgreich sein, bringt die gefangene Verdammniswache zu Daio in der faulenden Narbe."}}
D[7601] = {"Nibys Anweisungen",{"Sprecht mit Impsy im Teufelswald."}}
D[7602] = {"Reine Teufelsessenz",{"Impsy im Teufelswald möchte, dass Ihr ihm drei reine Teufelsessenzen aus drei bestimmten Gebieten besorgt.","","Die Satyrn der Legashi von Azshara bergen die Teufelsessenz ihrer Region. Die Legionäre von Jaedenar in Jaedenar bergen die Teufelsessenz ihrer Region. Die Wachposten der Teufelswache in den verwüsteten Landen bergen die Teufelsessenz ihrer Region.","","Findet die Teufelsessenzen und bringt sie zu Impsy im Teufelswald."}}
D[7603] = {"Kroshius Höllenbestienkern",{"Sucht im Narbengrund im Teufelswald nach den Überresten von Kroshius. Habt Ihr sie gefunden, so verwendet das Teufelsfeuer in deren Nähe und wartet dann auf Kroshius' Rückkehr. Tötet die Höllenbestie und entnehmt ihrem Körper den Höllenbestienkern.","","Bringt Kroshius' Höllenbestienkern zu Niby dem Allmächtigen im Teufelswald."}}
D[7604] = {"Ein verbindlicher Vertrag",{"Bringt den Vertrag der Thoriumbruderschaft zu Lokhtos Düsterfeilsch, wenn Ihr die Pläne für das Sulfuron erhalten möchtet."}}
D[7621] = {"Eine Warnung"}
D[7622] = {"Die Waage von Licht und Schatten",{"Rettet 50 Arbeiter bevor 15 getötet wurden. Sprecht mit Eris Himmelsfeuer, falls Ihr diesen Auftrag erfolgreich zu Ende bringen solltet.","","Konsultiert den Todesposten, um zu sehen wie viele Arbeiter bereits getötet wurden."}}
D[7623] = {"Lord Schattenfluch",{"Erwerbt schattenhafte Tränke von Gorzeeki Wildaug beim Altar der Stürme in der brennenden Steppe.","","Benutzt die Tränke um durch Jaedenar im Teufelswald zu reisen und sprecht mit Lord Schattenfluch in der Schattenfeste."}}
D[7624] = {"Ulathek der Verräter",{"Stellt Euch Ulathek und bringt das Herz des Verräters zu Lord Schattenfluch in Jaedenar."}}
D[7625] = {"Xorothianischer Sternenstaub",{"Erwerbt xorothianischen Sternenstaub von Ur'dan tief im Inneren der Schattenfeste in Jaedenar im Teufelswald. Bringt es anschließend Gorzeeki Wildaug in der brennenden Steppe."}}
D[7626] = {"Die Glocke von Dethmoora",{"Bringt 2 Elixiere der Schattenmacht zu Gorzeeki Wildaug in die brennende Steppe."}}
D[7627] = {"Das Rad des Schwarzen Marsches",{"Bringt 6 große glänzende Splitter und 25 Stücke Dunkeleisenerz zu Gorzeeki Wildaug in die brennende Steppe."}}
D[7628] = {"Die Altarkerze des Jüngsten Gerichts",{"Bringt 3 Schuppen eines schwarzen Drachen zu Gorzeeki Wildaug in der brennenden Steppe."}}
D[7629] = {"Wichtellieferung",{"Bringt den Wichtel im Glas in das Alchemielabor in Scholomance. Bringt das Glas nach der Herstellung des Pergaments zurück zu Gorzeeki Wildaug."}}
D[7630] = {"Arkanit",{"Bringt 1 Arkanitbarren zu Gorzeeki in der brennenden Steppe."}}
D[7631] = {"Schreckensross von Xoroth",{"Lest Morzuls Anweisungen. Beschwört ein xorothianisches Schreckensross, besiegt es und bindet seinen Geist an Euch."}}
D[7632] = {"Das uralte Blatt",{"Findet den Besitzer des uralten, versteinerten Blatts. Viel Glück, Sharmon; die Welt ist groß."}}
D[7633] = {"Eine Einführung"}
D[7634] = {"Uraltes in Sehnen eingewickeltes Laminablatt",{"Hastat der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, blauen Drachen gebeten. Kehrt zu Hastat im Teufelswald zurück, solltet Ihr diese Sehne finden."}}
D[7635] = {"Die passende Sehne",{"Stoma der Uralte hat Euch um die Beschaffung einer Sehne eines ausgewachsenen, schwarzen Drachen gebeten. Solltet Ihr diese Sehne finden, kehrt zu Stoma im Teufelswald zurück."}}
D[7636] = {"Holzstab der Uralten",{"Ihr müsst die vier dämonischen Verderber ausfindig machen und zerstören:","","Simone die Verführerin.","","Klinfran der Wahnsinnige.","","Solenor der Schlächter.","","Artorius der Verhängnisvolle.","","Vernichtet diese Kreaturen und kehrt zu Vartrus dem Uralten im Teufelswald zurück.","","Haltet Euch an die versteinerte Rinde in Eurem Inventar, um Hinweise zu ihren Aufenthaltsorten zu erhalten.","","Ihr MÜSST diese Aufgabe eigenständig erledigen."}}
D[7637] = {"Ein Opfer darbieten",{"Reist nach Eisenschmiede und besorgt Euch Hohepriester Rohans Weihrauchschwenker. Eine Spende von 150 Gold wird erforderlich sein, um es zu bekommen."}}
D[7638] = {"Lord Grayson Schattenbruch",{"Sprecht mit Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind."}}
D[7639] = {"Lass Gerechtigkeit walten",{"Bringt den Weihrauchschwenker zu Lord Grayson Schattenbruch in Sturmwind zurück."}}
D[7640] = {"Der Exorzismus des Schreckenstals",{"Vertreibt mithilfe des Weihrauchschwenkers die Geister im Schreckenstal. Vernichtet 25 Schreckenstalgeister und kehrt anschließend zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind zurück."}}
D[7641] = {"Grimand Elmores Werk",{"Sprecht mit Grimand Elmore im Zwergendistrikt von Sturmwind."}}
D[7642] = {"Fünf Dinge",{"Bringt 40 Lagen Runenstoff, 6 Arkanitbarren, 10 Arthas' Tränen, 5 Phiolen Weihwasser aus Stratholme und 150 Gold zu Grimand Elmore im Zwergendistrikt von Sturmwind."}}
D[7643] = {"Der uralte Pferdegeist",{"Beschafft spezielles Pferdefutter, mit dem man ein Geisterpferd füttern kann. Merideth Carlson in Süderstade scheint dafür eine recht gute Quelle zu sein.","","Reist anschließend nach Düsterbruch in Feralas und tötet Tendris Wucherborke. Dies wird den uralten Pferdegeist befreien. Füttert den Geist zur Beruhigung mit dem speziellen Pferdefutter. Gebt dem Pferdegeist das Arkanitpferdegeschirr, um es segnen zu lassen."}}
D[7644] = {"Gesegnetes Arkanitpferdegeschirr",{"Kehrt mit dem gesegneten Arkanitpferdegeschirr zu Lord Grayson Schattenbruch in das Kathedralenviertel von Sturmwind zurück."}}
D[7645] = {"Mit Manna angereichertes Pferdefutter",{"Treibt 20 angereicherte Mannakekse - die ausschlaggebende Zutat für die Herstellung von mit Manna angereichertem Pferdefutter - für Merideth Carlson aus Süderstade in dem Vorgebirge des Hügellands auf. Die Argentumdämmerung ist als alleiniger Händler dieser Kekse bekannt.","","Zusätzlich müsst Ihr ihre Gefühle noch mit 50 Goldstücken besänftigen."}}
D[7646] = {"Das Orakel der Anrufung",{"Bringt Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind einen azerothischen Diamanten und einen makellosen schwarzen Diamanten."}}
D[7647] = {"Gerechtigkeit und Erlösung",{"Benutzt das Orakel der Anrufung im Herzen des Kellergewölbes des großen Ossuariums, in Scholomance. Damit ruft Ihr die verfluchten Geister, über deren Schicksal Ihr richten müsst. Durch das Besiegen der Geister wird der Todesritter Schattensichel beschworen. Besiegt ihn und holt Euch die verlorene Seele des gefallenen Streitrosses.","","Gebt die Seele des gefallenen Streitrosses und das gesegnete und verzauberte Pferdegeschirr Schattensichels gefallenem Streitross zurück."}}
D[7648] = {"Grimands feinste Arbeit",{"Bringt das Arkanitpferdegeschirr zur Begutachtung zu Lord Grayson Schattenbruch im Kathedralenviertel von Sturmwind."}}
D[7649] = {"Verzauberter Thoriumplattenpanzer: Band I",{"Bringt das Buch seinen rechtmäßigen Besitzern zurück."}}
