D[7701] = {"GESUCHT: Aufseher Maltorius",{"Tief in der Schlackengrube des Kessels in der sengenden Schlucht werdet Ihr den verräterischen Dunkeleisenzwerg, Aufseher Maltorius, finden.","","Tötet den Aufseher Maltorius und nehmt seinen Kopf an Euch. Bringt diesen zum Hauptmann des Ausgucks Lolo Langhieb in der sengenden Schlucht für eine Belohnung."}}
D[7702] = {"Tötet sie mit Schlafentzug",{"Tief in der Schlackengrube des Kessels, findet Ihr die Schlafräume der Dunkeleisenzwerge.","","Findet diese Schlafkammern und stibitzt 20 Dunkeleisenkissen. Kehrt dann zu Evonice Rußraucher in der sengenden Schlucht, wenn Ihr die Aufgabe erfüllt habt."}}
D[7703] = {"Die offene Rechnung der Gordok",{"Findet die Stulpen der Gordokmacht und bringt sie zu Hauptmann Krombruch in Düsterbruch.","","Krombruch zufolge sagen die \"Alte Zeit Geschichten\", dass Tortheldrin - ein \"gruseliger\" Elf, der sich selbst als Prinz bezeichnet- sie einem der Gordokkönige gestohlen hat."}}
D[7704] = {"Schau dir die Größe an!",{"Bringt das Kissen von Zimmermädchen Kissenquetscher zu Evonice Rußraucher in der sengenden Schlucht."}}
D[7721] = {"Treibstoff fürs Schrumpfen",{"Sammelt 10 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks."}}
D[7722] = {"Was zum Fluxus?!",{"Irgendwo in der Schlackengrube des Kessels findet Ihr die geheimen Pläne des Feurigen Fluxus, die der Aufseher Maltorius stahl. Findet diese Pläne und bringt sie zurück zu Meisterschmied Burninate in der sengenden Schlucht."}}
D[7723] = {"Verdammt seien diese fetten Finger",{"Hansel Bleihand möchte, dass Ihr 20 Schwere Kriegsgolems tötet.","","Die Schweren Kriegsgolems wandern in der Gegend um den Kessel in der sengenden Schlucht herum. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7724] = {"Feurige Bedrohung!",{"Hansel Bleihand möchte, dass Ihr 20 große Lavaspinnen in der sengenden Schlucht tötet.","","Die großen Lavaspinnen findet Ihr auf den Plateaus und in den Lavabecken der sengenden Schlucht. Sobald Ihr genug getötet habt, kehrt zu Hansel zurück."}}
D[7725] = {"Und wieder unter den geschrumpften Riesen",{"Benutzt Zorbins Ultraschrumpfer, um jegliche Art von Riesen in Feralas in eine handlichere Form zu schrumpfen. Bringt 10 Schrumpfüberreste, die auf den kleineren handlicheren Riesen liegen zu Zorbin von Schiller am Dock der Vergessenen Küste in Feralas."}}
D[7726] = {"Neuer Treibstoff fürs Schrumpfen",{"Sammelt 6 Wasserelementarkerne von den Meereselementaren und Meeresschauern entlang der Vergessenen Küste von Feralas und bringt sie zurück zu Zorbin von Schiller in der Nähe des dortigen Docks."}}
D[7727] = {"Incendosaurier? Was-auch-immer-Saurier?",{"Hansel Bleihand möchte, dass Ihr 20 Incendosaurier tötet.","","Die Incendosaurier haben sich in den Lavabecken der Schlackengrube eingenistet. Ihr findet die Schlackengrube im Kessel der sengenden Schlucht.","","Sobald Ihr genug Incendosaurier getötet habt, kehrt zu Hansel Bleihand in der sengenden Schlucht zurück."}}
D[7728] = {"GESTOHLEN: Schmiedewindform und ein Ausguckhandfernrohr",{"Sucht die Schmiedewindform und das Ausguckhandfernrohr. Bringt diese Gegenstände zu Zuchtmeister Skrange in der sengenden Schlucht.","","Die einzigen Informationen die Ihr habt sind: Die Schmiedewindform ist ein Schmiedewerkzeug welches von Schmieden verwendet wird und das Ausguckhandfernrohr ist ein unverzichtbares Werkzeug für Spähposten."}}
D[7729] = {"STELLE ZU VERGEBEN: Erledige die Konkurrenz",{"Tötet 15 Zuchtmeister der Dunkeleisenzwerge und 15 Sklavenhändler der Dunkeleisenzwerge. Kehrt zu Zuchtmeister Skrange in der sengenden Schlucht zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[7730] = {"Zukk'ash-Plage",{"Bringt Hadoken Flinkschreiter im Camp Mojache in Feralas 20 Zukk'ashknochenpanzer."}}
D[7731] = {"Zornstachel",{"Besiegt Zornstachel in der verwundenen Tiefe und bringt seine Drüsen zu Hadoken Flinkschreiter im Camp Mojache in Feralas zurück."}}
D[7732] = {"Bericht über die Zukk'ash",{"Bringt den Bericht über die Zukk'ash aus Camp Mojache zu Zilzibin Tomtom. Er wohnt in der Gasse von Orgrimmar."}}
D[7733] = {"Beste Qualität",{"Bringt Pratt McGrubben in der Mondfederfeste in Feralas 10 Wutschrammyetibälge."}}
D[7734] = {"Beste Qualität",{"Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas 10 Wutschrammyetibälge."}}
D[7735] = {"Makelloser Yetibalg",{"Bringt Pratt McGrubben in der Mondfederfeste in Feralas den makellosen Yetibalg."}}
D[7736] = {"Nachschub an feurigem Fluxus: Königsblut"}
D[7737] = {"Noch mehr Anerkennung erlangen"}
D[7738] = {"Perfekter Yetibalg",{"Bringt Jangdor Flinkschreiter im Camp Mojache in Feralas den makellosen Yetibalg."}}
