D[7761] = {"Schwarzfausts Befehl",{"Das war ja vielleicht mal ein dummer Orc. Es sieht so aus, als müsstet Ihr dieses Brandzeichen finden, um an das Mal von Drakkisath zu gelangen. Damit sollte sich die Befehlskugel aktivieren lassen.","","Dem Brief zufolge, wird das Brandzeichen von General Drakkisath bewacht. Vielleicht solltet Ihr diesem Hinweis nachgehen."}}
D[7781] = {"Der Herrscher des Schwarzfels",{"Bringt König Varian Wrynn in Sturmwind den Kopf von Nefarian."}}
D[7782] = {"Der Herrscher des Schwarzfels",{"Reist in nach Sturmwind in das Tal der Helden und sprecht mit Feldmarschall Steinsteg."}}
D[7783] = {"Der Herrscher des Schwarzfels",{"Bringt Thrall in Orgrimmar den Kopf von Nefarian."}}
D[7784] = {"Der Herrscher des Schwarzfels",{"Sprecht mit Oberanführer Runthak in Orgrimmar. Er wartet im Tal der Stärke auf Euch."}}
D[7785] = {"Untersuchung des Gefäßes",{"Untersucht das Gefäß der Wiedergeburt und bringt es zu Hochlord Demitrian."}}
D[7786] = {"Donneraan der Windsucher",{"Um Donneraan den Windsucher aus seiner Gefangenschaft zu befreien, müsst Ihr Hochlord Demitrian in Silithus die rechten und linken Hälften der Fesseln des Windsuchers, 10 Elementiumbarren und die Essenz des Feuerfürsten bringen."}}
D[7787] = {"Donnerzorn erwache!",{"Präsentiert Hochlord Demitrian die vom Wind berührte, schlummernde Klinge."}}
D[7788] = {"Besiegt die Eindringlinge!",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Horde. Verdient Euch ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt zur Schildwache Weltensang am Hain der Silberschwingen zurück."}}
D[7789] = {"Bezwingt die Eindringlinge der Silberschwingen",{"Betretet die Kriegshymnenschlucht und besiegt die Streitkräfte der Allianz. Erwerbt ein Ehrenabzeichen der Kriegshymnenschlucht und kehrt anschließend zu Hauptmann Schädelbrecher im Stützpunkt Mor'shan zurück."}}
