D[8410] = {"Elementarbeherrschung",{"Bath'rah der Windbehüter möchte, dass Ihr jeweils eine Probe Luft, Feuer, Erde und Wasser für ihn sammelt."}}
D[8411] = {"Die Beherrschung der Elemente",{"Bringt Bath'rah dem Windbehüter die Elemente Erde, Luft, Feuer und Wasser."}}
D[8412] = {"Geistertotem",{"Bringt Bath'rah dem Windbehüter die Komponenten für das Geistertotem."}}
D[8413] = {"Die Macht des Voodoos",{"Bringt Bath'rah dem Windbehüter die Voodoofedern."}}
D[8414] = {"Austreibung des Bösen",{"Sammelt 20 Geißelsteine des Dieners und bringt sie zu Hohepriester Thel'danis in den westlichen Pestländern."}}
D[8415] = {"Zugwindlager",{"Sprecht mit Kommandant Ashlam Ehrenschlag im Zugwindlager."}}
D[8416] = {"Gereinigte Geißelsteine",{"Bringt den gereinigten Geißelstein zu Kommandant Ashlan Ehrenschlag an der Zugwindspitze."}}
D[8417] = {"Ein geplagter Geist",{"Sprecht mit dem gefallenen Helden der Horde am Eingang zu den verwüsteten Landen."}}
D[8418] = {"Erschaffung des Steins der Macht",{"Beschafft Euch gelbe, blaue und grüne Voodoofedern von den Trollen im Versunkenen Tempel."}}
D[8419] = {"Die Bitte eines Wichtels",{"Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}}
D[8420] = {"Heiß und brennend",{"Bringt ein Stück Teufelsstoff zu Impsy im Teufelswald."}}
D[8421] = {"Das richtige Zeug",{"Bringt 10 Stück faules Holz und 4 Blutgiftessenzen zu Impsy im Teufelswald."}}
D[8422] = {"Federn von Trollen",{"Bringt 6 Voodoofedern von den Trollen aus dem Versunkenen Tempel."}}
D[8423] = {"Kriegerverwandtschaft",{"Tötet 7 Hölleneber in den verwüsteten Landen und kehrt zu dem gefallenen Helden der Horde zurück."}}
D[8424] = {"Krieg den Schattenanbetern",{"Merzt die Schattenanbeter in den verwüsteten Landen aus und kehrt zum gefallenen Helden der Horde zurück."}}
D[8425] = {"Voodoofedern",{"Bringt die Voodoofedern der Trolle im Versunkenen Tempel zu dem gefallenen Helden der Horde."}}
D[8426] = {"Schlacht der Kriegshymnenschlucht",{"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8427] = {"Schlacht der Kriegshymnenschlucht",{"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
D[8428] = {"Schlacht der Kriegshymnenschlucht",{"Bringt 3 Ehrenabzeichen der Kriegshymnenschlucht zu einem Kriegshetzer der Horde, außerhalb der Schlachtfelder."}}
