D[8446] = {"Eingehüllt in Alpträume",{"Sucht nach jemandem, der die Bedeutung des in Alpträume gehüllten Gegenstands entschlüsseln kann.","","Vielleicht kann Euch ein Druide von großer Macht weiterhelfen."}}
D[8447] = {"Legenden erwachen",{"Wartet, bis Bewahrer Remulos bei der Mondlichtung den von Alpträumen eingehüllten Gegenstand gereinigt hat."}}
D[8460] = {"Verbündeter der Holzschlundfeste",{"Grazle möchte, dass Ihr Euch beweist, indem Ihr 6 Krieger der Totenwaldfelle, 6 Pfadfinder der Totenwaldfelle und 6 Gärtner der Totenwaldfelle besiegt. Kehrt zu ihm in den Süden des Teufelswalds nahe des Smaragdrefugiums zurück, sobald Ihr dies getan habt."}}
D[8461] = {"Totenwaldfelle des Nordens",{"Nafien möchte, dass Ihr 6 Höhlenbehüter der Totenwaldfelle, 6 Rächer der Totenwaldfelle und 6 Schamanen der Totenwaldfelle besiegt. Kehrt danach zu ihm in den Norden des Teufelswalds nahe des Eingangs der Holzschlundfeste zurück."}}
D[8462] = {"Sprecht mit Nafien",{"Reist nach Norden entlang der Hauptstraße des Teufelswalds und sprecht mit einem Furbolg namens Nafien. Er hält außerhalb des Eingangs zur Holzschlundfeste Wache."}}
D[8463] = {"Instabile Manakristalle",{"Bringt Aeldon Sonnenmal auf dem Falkenplatz 6 instabile Manakristalle."}}
D[8464] = {"Aktivität der Winterfelle",{"Salfa möchte, dass Ihr 8 Schamanen der Winterfelle, 8 Höhlenbehüter der Winterfelle und 8 Ursa der Winterfelle erledigt. Salfa befindet sich genau außerhalb des Eingangs zur Holzschlundfeste in Winterquell."}}
D[8465] = {"Sprecht mit Salfa",{"Durchquert die Holzschlundfeste und verlasst sie in Richtung Winterquell. Sprecht mit Salfa, die außerhalb des Eingangs zur Holzschlundfeste Wache steht."}}
D[8466] = {"Federn für Grazle"}
D[8467] = {"Federn für Nafien"}
D[8468] = {"Gesucht: Thaelis der Manadurstige",{"Bringt Thaelis Kopf zu Unteroffizier Kan'ren beim Falkenplatz im Immersangwald."}}
D[8469] = {"Perlen für Salfa"}
D[8470] = {"Ritualtotem der Totenwaldfelle",{"Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist."}}
D[8471] = {"Ritualtotem der Winterfelle",{"Bringt das Ritualtotem in die Holzschlundfeste und findet heraus, ob einer der dortigen Furbolgs eine Verwendung für diesen Gegenstand hat. Die Furbolgs der Holzschlundfeste werden solange nicht mit Euch sprechen, bis Euer Ruf bei ihnen neutral oder höher ist."}}
D[8472] = {"Schwere Fehlfunktion",{"Sammelt 6 Arkankerne von den Arkanpatrouillen, die in den Ruinen von Silbermond umherstreifen, und bringt sie Magister Jaronis beim Falkenplatz im Immersangwald."}}
D[8473] = {"Eine traurige Aufgabe",{"Tötet 10 siechende Waldbehüter beim versengten Hain und meldet Euch anschließend bei Larianna Flusswind, die sich im Turm nordwestlich des versengten Hains im Immersangwald aufhält."}}
D[8474] = {"Weißborkes Anhänger",{"Macht die Person ausfindig, die Weißborkes Anhänger angefertigt haben könnte. Ihr könntet Hinweise über den Gegenstand erfahren."}}
D[8475] = {"Die Todesschneise",{"Tötet 8 Seuchenknochenplünderer und kehrt anschließend zu Waldläuferin Jaela in der Todesschneise im Immersangwald zurück."}}
D[8476] = {"Amaniübergriff",{"Leutnant Dämmerflucht bei der Zuflucht der Weltenwanderer im Immersangwald möchte, dass Ihr 5 Berserker der Amani und 5 Axtwerfer der Amani tötet."}}
D[8477] = {"Der Hammer des Speermachers",{"Sucht in Tor'Watha, südöstlich der Zuflucht der Weltenwanderer, nach Speermacher Otembe und bringt Otembes Hammer zu Arathel Sonnenschmied bei der Zuflucht der Weltenwanderer im Immersangwald."}}
D[8478] = {"Wählt Eure Waffe"}
D[8479] = {"Zul'Marosh",{"Ven'jashi, der gefangene Troll in Tor'Watha möchte, dass Ihr ihm Häuptling Zul'Maroshs Kopf bringt. Häuptling Zul'Marosh befindet sich in Zeb'Watha, jenseits des Elrendarsees."}}
D[8480] = {"Zurückgelassene Waffen",{"Bringt 8 Waffen der Sin'dorei zu Velendris Weißflor im Immersangwald."}}
D[8481] = {"Die Wurzel alles Bösen",{"Stellt die Fackel zur Dämonenbeschwörung im Eingang der Höhle des Oberhäuptlings der Winterfelle, im Lager der Winterfellfurbolgs auf. Besiegt den Dämon und erlangt die Essenz von Xandivious für Gorn Einauge in der Holzschlundfeste."}}
D[8482] = {"Belastende Dokumente",{"Bringt die belastenden Dokumente zu Aeldon Sonnenmal auf dem Falkenplatz im Immersangwald."}}
D[8483] = {"Der zwergische Spion",{"Bringt den Kopf von Ausgrabungsleiter Ambossel zu Aeldon Sonnenmal beim Falkenplatz im Immersangwald."}}
D[8484] = {"Das Bemühen um Frieden",{"Bringt das Friedensangebot der Holzschlundfeste zu König Magni Bronzebart in Eisenschmiede."}}
D[8485] = {"Das Bemühen um Frieden",{"Bringt das Friedensangebot der Holzschlundfeste zu Thrall in Orgrimmar."}}
D[8486] = {"Arkane Instabilität",{"Leybewahrerin Velania möchte, dass Ihr 5 Managespenster und 5 Manapirscher tötet."}}
D[8487] = {"Besudelte Erde",{"Lehrling Mirveda beim Sanktum des Ostens im Immersangwald möchte, dass Ihr 8 besudelte Erdproben einsammelt."}}
D[8488] = {"Ungewöhnliche Ergebnisse",{"Beschützt Lehrling Mirveda vor dem Angriff der Geißel."}}
D[8489] = {"Ein intakter Wandler",{"Bringt den intakten Arkanwandler zu Leybewahrerin Velania."}}
D[8490] = {"Wiederaufladen der Verteidigung",{"Platziert den energieerfüllten Kristall beim Runenstein des Ostens und verteidigt ihn 1 Minute lang vor der Geißel. Bringt den energieerfüllten Kristall anschließend zu Runenwächter Deryan im Immersangwald, um Eure Belohnung zu erhalten."}}
D[8491] = {"Pelzjagd",{"Velan Lichteiche in Morgenluft im Immersangwald möchte, dass Ihr ihm 6 Bachtatzenfelle bringt."}}
D[8492] = {"Die Allianz braucht Kupferbarren!",{"Bringt 20 Kupferbarren zu Unteroffizier Steinbraue im Militärviertel in Eisenschmiede."}}
D[8493] = {"Die Allianz braucht mehr Kupferbarren!",{"Bringt 20 Kupferbarren zu Unteroffizier Steinbraue beim Landeplatz in Dun Morogh."}}
D[8494] = {"Die Allianz braucht Eisenbarren!",{"Bringt 20 Eisenbarren zu Korporal Schwarz im Militärviertel in Eisenschmiede."}}
D[8495] = {"Die Allianz braucht mehr Eisenbarren!",{"Bringt 20 Eisenbarren zu Korporal Schwarz beim Landeplatz in Dun Morogh."}}
D[8496] = {"Verbände für den Feldeinsatz",{"Bringt 30 schwere Runenstoffverbände, 30 schwere Seidenverbände und 30 schwere Magiestoffverbände zu Windruferin Prachthorn auf Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz X, um diese Aufgabe abschließen zu können."}}
D[8497] = {"Wüstenüberlebenspaket",{"Bringt 4 Kugeln des Wassers, 4 mächtige Gegengifte und 4 geräucherte Wüstenknödel zu Calandrath in der Taverne von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz I, um diese Aufgabe abschließen zu können."}}
D[8498] = {"Schlachtordnungen des Schattenhammerklans",{"Beschafft Euch die Schlachtordnungen des Schattenhammerklans und bringt sie zu Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch den taktischen Einsatz X, um diese Aufgabe abschließen zu können."}}
D[8499] = {"Die Allianz braucht Thoriumbarren!",{"Bringt 20 Thoriumbarren zu Dame Doppelzopf im Militärviertel in Eisenschmiede."}}
D[8500] = {"Die Allianz braucht mehr Thoriumbarren!",{"Bringt 20 Thoriumbarren zu Dame Doppelzopf beim Landeplatz in Dun Morogh."}}
D[8501] = {"Ziel: Stecher des Ashischwarms",{"Tötet 30 Stecher des Ashischwarms und erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz XII, um diese Aufgabe abschließen zu können."}}
D[8502] = {"Ziel: Arbeiter des Ashischwarms",{"Tötet 30 Arbeiter des Ashischwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz III, um diese Aufgabe abschließen zu können."}}
D[8503] = {"Die Allianz braucht Würgetang!",{"Bringt 20 Stück Würgetang zu dem Gefreiten Drechselknacks im Militärviertel in Eisenschmiede."}}
D[8504] = {"Die Allianz braucht mehr Würgetang!",{"Bringt 20 Stück Würgetang zu dem Gefreiten Drechselknacks beim Landeplatz in Dun Morogh."}}
D[8505] = {"Die Allianz braucht lila Lotus!",{"Bringt 20 lila Lotus zu Meister Nachtweise im Militärviertel in Eisenschmiede."}}
D[8506] = {"Die Allianz braucht mehr lila Lotus!",{"Bringt 20 lila Lotus zu Meister Nachtweise beim Landeplatz in Dun Morogh."}}
D[8507] = {"Felddienst",{"Erstattet am Posten der Eisenschmiedebrigade beim Zoraschwarmbau Bericht. Bereitet Eure nicht unterzeichneten Felddienstpapiere vor, lasst sie von Hauptmann Rußschmied unterzeichnen und kehrt zu Windrufer Kaldon auf Burg Cenarius in Silithus zurück.","","Hinweis: das Heilen oder Wirken von begünstigenden Zaubern auf ein Mitglied der Eisenschmiedebrigade wird Euch für den PvP-Kampf markieren."}}
D[8508] = {"Felddienstpapiere"}
D[8509] = {"Die Allianz braucht Arthas' Tränen!",{"Bringt 20 Arthas' Tränen zu Stabsfeldwebel Germaine im Militärviertel in Eisenschmiede."}}
D[8510] = {"Die Allianz braucht mehr Arthas' Tränen!",{"Bringt 20 Arthas' Tränen zu Stabsfeldwebel Germaine beim Landeplatz in Dun Morogh."}}
D[8511] = {"Die Allianz braucht leichtes Leder!",{"Bringt 10 Einheiten leichtes Leder zu Bonnie Steinschinder im Militärviertel in Eisenschmiede."}}
D[8512] = {"Die Allianz braucht mehr leichtes Leder!",{"Bringt 10 Einheiten leichtes Leder zu Bonnie Steinschinder beim Landeplatz in Dun Morogh."}}
D[8513] = {"Die Allianz braucht mittleres Leder!",{"Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter im Militärviertel in Eisenschmiede."}}
D[8514] = {"Die Allianz braucht mehr mittleres Leder!",{"Bringt 10 Einheiten mittleres Leder zu dem Gefreiten Porter beim Landeplatz in Dun Morogh."}}
D[8515] = {"Die Allianz braucht dickes Leder!",{"Bringt 10 Einheiten dickes Leder zu Marta Feinspindel im Militärviertel in Eisenschmiede."}}
D[8516] = {"Die Allianz braucht mehr dickes Leder!",{"Bringt 10 Einheiten dickes Leder zu Marta Feinspindel beim Landeplatz in Dun Morogh."}}
D[8517] = {"Die Allianz braucht Leinenverbände!",{"Bringt 20 Leinenverbände zu Schildwache Silberwolke im Militärviertel in Eisenschmiede."}}
D[8518] = {"Die Allianz braucht mehr Leinenverbände!",{"Bringt 20 Leinenverbände zu Schildwache Silberwolke beim Landeplatz in Dun Morogh."}}
D[8519] = {"Eine Spielfigur auf dem Schachbrett der Ewigkeit",{"Lernt so viel Ihr könnt über die Vergangenheit, sprecht dann mit Anachronos in den Höhlen der Zeit in Tanaris."}}
D[8520] = {"Die Allianz braucht Seidenverbände!",{"Bringt 20 Seidenverbände zu Schwester Steinfeld im Militärviertel in Eisenschmiede."}}
D[8521] = {"Die Allianz braucht mehr Seidenverbände!",{"Bringt 20 Seidenverbände zu Schwester Steinfeld beim Landeplatz in Dun Morogh."}}
D[8522] = {"Die Allianz braucht Runenstoffverbände!",{"Bringt 20 Runenstoffverbände zu Bewahrer Mondschatten im Militärviertel in Eisenschmiede."}}
D[8523] = {"Die Allianz braucht mehr Runenstoffverbände!",{"Bringt 20 Runenstoffverbände zu Bewahrer Mondschatten beim Landeplatz in Dun Morogh."}}
D[8524] = {"Die Allianz braucht Regenbogenflossenthunfisch!",{"Bringt 20 Regenbogenflossenthunfische zu Gastronom Glitschko im Militärviertel in Eisenschmiede."}}
D[8525] = {"Die Allianz braucht mehr Regenbogenflossenthunfisch!",{"Bringt 20 Regenbogenflossenthunfische zu Gastronom Glitschko beim Landeplatz in Dun Morogh."}}
D[8526] = {"Die Allianz braucht geröstete Raptoren!",{"Bringt 20 geröstete Raptoren zu Sarah Sorgenpfeifer im Militärviertel in Eisenschmiede."}}
D[8527] = {"Die Allianz braucht mehr geröstete Raptoren!",{"Bringt 20 geröstete Raptoren zu Sarah Sorgenpfeifer beim Landeplatz in Dun Morogh."}}
D[8528] = {"Die Allianz braucht Tüpfelgelbschwänze!",{"Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach im Militärviertel in Eisenschmiede."}}
D[8529] = {"Die Allianz braucht mehr Tüpfelgelbschwänze!",{"Bringt 20 Tüpfelgelbschwänze zu Jägerin Flinkbach beim Landeplatz in Dun Morogh."}}
D[8530] = {"Die Allianz braucht sengende Kernsteine!",{"Bringt 50 sengende Kernsteine zu Kommandant Hammerkraft beim Landeplatz in Dun Morogh."}}
D[8532] = {"Die Horde braucht Kupferbarren!",{"Bringt 20 Kupferbarren zu Minenarbeiter Kromwell im Tal der Geister in Orgrimmar."}}
D[8533] = {"Die Horde braucht mehr Kupferbarren!",{"Bringt 20 Kupferbarren zu Minenarbeiter Kromwell in Durotar."}}
D[8534] = {"Späherbericht des Zoraschwarms",{"Setzt Euch mit der cenarischen Späherin Azenel innerhalb des Zoraschwarmbaus in Verbindung und bringt den Späherbericht des Zoraschwarms zu Windruferin Prachthorn auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz VI, um diese Aufgabe abschließen zu können."}}
D[8535] = {"Weißgrauer Templer",{"Beschwört und vernichtet einen weißgrauen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz IV, um diese Aufgabe abschließen zu können."}}
D[8536] = {"Irdener Templer",{"Beschwört und vernichtet einen irdenen Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz III, um diese Aufgabe abschließen zu können."}}
D[8537] = {"Purpurroter Templer",{"Beschwört und vernichtet einen purpurroten Templer. Erstattet anschließend Bericht bei Bor Wildmähne auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz II, um diese Aufgabe abschließen zu können."}}
D[8538] = {"Die vier Fürsten",{"Findet einen Weg, um den Fürst der Asche, den Fürst der Tiefen, den Fürst der Stürme und den Fürst der Splitter zu beschwören und zu vernichten. Erstattet anschließend Bericht bei Kommandant Mar'alith auf Burg Cenarius. Ihr benötigt auch den taktischen Einsatz V, um diese Aufgabe abschließen zu können."}}
D[8539] = {"Ziel: Schwestern des Zoraschwarms",{"Tötet 30 Schwestern des Zoraschwarms und erstattet Bericht bei Kommandant Mar'alith auf Burg Cenarius in Silithus. Ihr benötigt auch Kampfeinsatz V, um diese Aufgabe abschließen zu können."}}
D[8540] = {"Stiefel für die Wache",{"Bringt 3 Paar verschnörkelte Mithrilstiefel zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz II, um diese Aufgabe abschließen zu können."}}
D[8541] = {"Schleifsteine für die Wache",{"Bringt 10 verdichtete Schleifsteine, 10 robuste Schleifsteine und 10 schwere Schleifsteine zu Vish Kozus, Hauptmann der Wache von Burg Cenarius in Silithus. Ihr benötigt auch Logistikeinsatz III, um diese Aufgabe abschließen zu können."}}
D[8542] = {"Die Horde braucht Zinnbarren!",{"Bringt 20 Zinnbarren zu Grunzer Maug im Tal der Geister in Orgrimmar."}}
D[8543] = {"Die Horde braucht mehr Zinnbarren!",{"Bringt 20 Zinnbarren zu Grunzer Maug in Durotar."}}
D[8544] = {"Schiftung des Eroberers",{"Bringt die Befehlsbindungen der Qiraji, 2 Götzen der Nacht, 5 Steinskarabäen und 5 Tonskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen neutralen Ruf bei der Brut Nozdormus."}}
D[8545] = {"Die Horde braucht Mithrilbarren!",{"Bringt 20 Mithrilbarren zu Schlachtrufer T'kelah im Tal der Geister in Orgrimmar."}}
D[8546] = {"Die Horde braucht mehr Mithrilbarren!"}
D[8547] = {"Willkommen!",{"Bringt den Geschenkgutschein des Falkenplatzes zu Marsilla Morgenstern auf dem Falkenplatz."}}
D[8548] = {"Schlachtrüstung des Kriegsfreiwilligen",{"Bringt 5 cenarische Gefechtsabzeichen, 3 cenarische Versorgungsabzeichen und 7 cenarische Strategieabzeichen zu Vargus auf Burg Cenarius in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf beim Zirkel des Cenarius."}}
D[8549] = {"Die Horde braucht Friedensblumen!",{"Bringt 20 Friedensblumen zu der Kräuterkundigen Stolzfeder im Tal der Geister in Orgrimmar."}}
D[8550] = {"Die Horde braucht mehr Friedensblumen!"}
D[8551] = {"Die Truhe des Kapitäns",{"Bringt Smotts' Truhe zu Hecklebury Smotts nach Beutebucht."}}
D[8552] = {"Die Schärpe mit Monogramm",{"Bringt die Schärpe mit Monogramm zu ihrem Besitzer zurück."}}
D[8553] = {"Der Entersäbel des Kapitäns",{"Sprecht mit Knirpsens."}}
D[8554] = {"Negolash entgegentreten",{"Bringt 10 gegrillte Bussardflügel und 5 Flaschen Dschungelrankenwein zu Käpt'n Smotts Rettungsboot.","","Tötet Negolash und bringt Smotts' Entersäbel zu Kapitän Smotts ins Schlingendorntal."}}
D[8555] = {"Der Bund der Drachenschwärme"}
D[8556] = {"Siegel der unnachgiebigen Stärke",{"Bringt 1 Gebieterring der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius."}}
D[8557] = {"Tuch der unnachgiebigen Stärke",{"Bringt 1 Kampftuch der Qiraji, 2 Onyxgötzen, 5 Sillberskarabäen und 5 Knochenskarabäen zu Keyl Flinkklaue in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen respektvollen Ruf beim Zirkel des Cenarius."}}
D[8558] = {"Sichel der unnachgiebigen Stärke",{"Bringt 1 Stachelgriff der Qiraji, 2 Alabastergötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8559] = {"Schienbeinschützer des Eroberers",{"Bringt die Befehlsbindungen der Qiraji, 2 Götzen des Krieges, 5 Elfenbeinskarabäen und 5 Goldskarabäen zu Kandrostrasz in Ahn'Qiraj. Diese Aufgabe erfordert auch einen neutralen Ruf bei der Brut Nozdormus."}}
D[8560] = {"Beinschützer des Eroberers",{"Bringt Ouros intakte Haut, 2 Götzen des Todes, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Kandrostrasz innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."}}
D[8561] = {"Krone des Eroberers",{"Bringt Vek'nilashs Reif, 2 Götzen der Sonne, 5 Steinskarabäen und 5 Kristallskarabäen zu Andorgos in Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen freundlichen Ruf bei der Brut Nozdormus."}}
D[8562] = {"Brustplatte des Eroberers",{"Bringt den Knochenpanzer des alten Gottes, 2 Götzen des Krieges, 5 Silberskarabäen und 5 Knochenskarabäen zu Vethsera innerhalb von Ahn'Qiraj. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf bei der Brut Nozdormus."}}
D[8563] = {"Ausbildung zum Hexenmeister",{"Sprecht mit Beschwörer Teli'Larien - dem Hexenmeisterlehrer - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[8564] = {"Ausbildung zum Priester",{"Sprecht mit Matrone Arena - der Priesterlehrerin - innerhalb des Sonnenturms auf der Insel der Sonnenwanderer."}}
D[8565] = {"Vergangene Siege im Arathibecken"}
D[8566] = {"Vergangene Siege im Arathibecken"}
D[8567] = {"Vergangene Siege in der Kriegshymnenschlucht"}
D[8568] = {"Vergangene Siege in der Kriegshymnenschlucht"}
