D[8608] = {"Die Horde braucht mehr Magiestoffverbände!"}
D[8609] = {"Die Horde braucht Runenstoffverbände!",{"Bringt 20 Runenstoffverbände zu Steinwache Lehmhuf im Tal der Geister in Orgrimmar."}}
D[8610] = {"Die Horde braucht mehr Runenstoffverbände!"}
