D[8703] = {"Ring der ewigen Gerechtigkeit",{"Bringt 1 Gebieterring der Qiraji, 2 Zinnobergötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius."}}
D[8704] = {"Siegel des unsichtbaren Pfads",{"Bringt 1 Gebieterring der Qiraji, 2 Bernsteingötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Windruferin Yessendra in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen wohlwollenden Ruf beim Zirkel des Cenarius."}}
D[8705] = {"Hammer der unendlichen Weisheit",{"Bringt 1 verschnörkelten Griff der Qiraji, 2 züngelnde Götzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8706] = {"Hammer der aufziehenden Stürme",{"Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Elfenbeinskarabäen und 5 Bronzeskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8707] = {"Klinge der behüteten Geheimnisse",{"Bringt 1 verschnörkelten Griff der Qiraji, 2 Obsidiangötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8708] = {"Streitkolben des endlosen Lebens",{"Bringt 1 verschnörkelten Griff der Qiraji, 2 Jaspisgötzen, 5 Kristallskarabäen und 5 Steinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8709] = {"Dolch der Schattenschleier",{"Bringt 1 Stachelgriff der Qiraji, 2 Zinnobergötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8710] = {"Kris der ungesagten Namen",{"Bringt 1 verschnörkelten Griff der Qiraji, 2 Onyxgötzen, 5 Goldskarabäen und 5 Tonskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8711] = {"Klinge der ewigen Gerechtigkeit",{"Bringt 1 Stachelgriff der Qiraji, 2 Bernsteingötzen, 5 Bronzeskarabäen und 5 Elfenbeinskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
D[8712] = {"Sense des unsichtbaren Pfads",{"Bringt 1 Stachelgriff der Qiraji, 2 Azurgötzen, 5 Silberskarabäen und 5 Knochenskarabäen zu Aufseher Haro in Silithus. Diese Aufgabe erfordert zum Abschluss auch einen ehrfürchtigen Ruf beim Zirkel des Cenarius."}}
