D[9119] = {"Zwischenfall beim Sanktum des Westens",{"Sprecht mit Leybewahrerin Velania beim Sanktum des Westens im Immersangwald."}}
D[9120] = {"Der Niedergang Kel'Thuzads",{"Bringt Kel'Thuzads Phylakterium zu der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9121] = {"Die Zitadelle des Schreckens - Naxxramas",{"Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 5 Arkankristalle, 2 Nexuskristalle, 1 rechtschaffene Kugel und 60 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem wohlwollend sein."}}
D[9122] = {"Die Zitadelle des Schreckens - Naxxramas",{"Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 2 Arkankristalle, 1 Nexuskristall und 30 Goldstücke. Euer Ruf bei der Argentumdämmerung muss außerdem respektvoll sein."}}
D[9123] = {"Die Zitadelle des Schreckens - Naxxramas",{"Erzmagierin Angela Dosantos bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern wird Euch die arkane Tarnung kostenfrei gewähren. Euer Ruf bei der Argentumdämmerung muss ehrfürchtig sein."}}
D[9124] = {"Was man für Gruftpirscherrüstung braucht...",{"Jäger Leopold bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Teile einer Gruftbestie."}}
D[9125] = {"Teile einer Gruftbestie"}
D[9126] = {"Knochensensenjagd",{"Rohan der Assassine bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Knochenfragmente."}}
