D[9129] = {"Kern der Elemente"}
D[9130] = {"Waren von Silbermond",{"Bringt Rüstmeisterin Lymels Frachtbrief zu Himmelsmeister Sonnenschwinge in Tristessa."}}
D[9131] = {"Bindung des Schreckenspanzers",{"Korfax bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Dunkeleisenfragmente."}}
D[9132] = {"Dunkeleisenfragmente"}
D[9133] = {"Fliegt nach Silbermond",{"Erwerbt einen Flug nach Silbermond und bringt Rüstmeisterin Lymels Frachtbrief zu Sathren Morgenblau in Silbermond."}}
D[9134] = {"Himmelsmeisterin Abendlicht",{"Bringt Rüstmeisterin Lymels Waren zu Himmelsmeisterin Abendlicht am Hirtentor direkt außerhalb von Silbermond."}}
D[9135] = {"Zurück zu Rüstmeisterin Lymel",{"Erwerbt einen Flug zurück nach Tristessa in den Geisterlanden und bringt Rüstmeisterin Lymels Waren zu Rüstmeisterin Lymel in Tristessa in den Geisterlanden."}}
D[9136] = {"Wildpflanzen",{"Rayne bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte 30 Wildwedel."}}
D[9137] = {"Wildwedel"}
D[9138] = {"Sonnenkuppe",{"Tötet 10 nerubische Wachen und kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück."}}
D[9139] = {"Goldnebel",{"Besiegt 6 Geister der Quel'dorei und 4 Gespenster der Quel'dorei in Goldnebel. Kehrt anschließend zu Arkanist Vandril in Tristessa in den Geisterlanden zurück."}}
D[9140] = {"Windläuferdorf",{"Sammelt 6 geisterhafte Substanzen und 4 Gargoylefragmente und bringt sie zu Arkanist Vandril in Tristessa in den Geisterlanden."}}
D[9141] = {"Sie nennen mich \"den Schleifer\"",{"Einsatzkommandant Metz bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern möchte eine Ehrenmarke der Argentumdämmerung."}}
D[9142] = {"Handwerksverfügung"}
D[9143] = {"Maßnahmen gegen Zeb'Sora",{"Sammelt 6 Trollohren von Zeb'Sora und bringt sie zu Waldläuferin Valanna in den Geisterlanden."}}
D[9144] = {"Verschollen in den Geisterlanden",{"Folgt der Straße, die von Morgenluft aus nach Süden führt, und haltet Ausschau nach Kurier Morgenwandler, wenn Ihr die Geisterlande erreicht."}}
D[9145] = {"Hilfe für Waldläuferin Valanna!",{"Findet Waldläuferin Valanna und Leutnant Tomathren am Ufer des Elrendarsees nahe Sonnenkuppe in den Geisterlanden."}}
D[9146] = {"Meldung bei Hauptmann Helios",{"Sprecht mit Hauptmann Helios bei der Enklave der Weltenwanderer am südlichen Ufer des Elrendarseese in den Geisterlanden."}}
D[9147] = {"Der sterbende Kurier",{"Apothekerin Thedra im Immersangwald möchte, dass Ihr ihr 4 verseuchte Blutproben von Tieren aus den Geisterlanden bringt."}}
D[9148] = {"Zustellung nach Tristessa",{"Bringt den Brief aus Silbermond zu Arkanist Vandril in Tristessa in den Geisterlanden."}}
D[9149] = {"Die verseuchte Küste",{"Bringt 6 verseuchte Murlocrückgrate zu Apotheker Renzithen in Tristessa in den Geisterlanden."}}
D[9150] = {"Reise zum vergessenen Sanktum",{"Magister Darenis möchte, dass Ihr zum Sanktum des Mondes westlich von Tristessa reist und dort 8 kristallisierte Manaessenzen von den dort hausenden Arkanverschlingern und Manaschleichern erlangt."}}
D[9151] = {"Das Sanktum der Sonne",{"Sprecht mit Magister Idonis im Sanktum der Sonne in den Geisterlanden."}}
D[9152] = {"Tombers Vorräte",{"Erlangt Rathis Tombers Vorräte und kehrt zu ihm in Tristessa in den Geisterlanden zurück."}}
D[9153] = {"Bedrohliche Schatten",{"Benutzt Eure Karte, um von der Geißel angegriffene Gebiete ausfindig zu machen. Geht dorthin und beschädigt eine Nekropole, indem Ihr die Truppen der Geißel, die sie umgeben, besiegt. Bringt 10 ihrer nekrotischen Runen zu Kommandant Thomas Helleran bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9154] = {"Kapelle des hoffnungsvollen Lichts",{"Bringt den Ruf zu den Waffen zum Bewahrer der Schriften in der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9155] = {"Entlang der Todesschneise",{"Tötet 10 hungrige Auferstandene und 10 gegeißelte Kannibalen in der Todesschneise. Kehrt anschließend zu Todespirscher Rathiel in Tristessa zurück, um Eure Belohnung zu erhalten."}}
D[9156] = {"Gesucht: Faulbein und Luzran",{"Sucht in den Geisterlanden nach Faulbein und Luzran. Bringt ihre Köpfe zu Todespirscher Rathiel in Tristessa, um eine Belohnung zu erhalten."}}
D[9157] = {"Vergessene Rituale",{"Bringt 8 Wellenfrontmedaillons zu Geranis Weißflor in den Geisterlanden."}}
D[9158] = {"Überträger der Seuche",{"Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 10 Geisterklauenluchse erschlagt."}}
D[9159] = {"Gebietet der Seuche Einhalt",{"Weltenwanderin Sedina in der Enklave der Weltenwanderer in den Geisterlanden möchte, dass Ihr 8 Spindelweberlauerer und 10 Vampirnebelfledermäuse erschlagt."}}
D[9160] = {"Untersucht An'daroth",{"Untersucht das Gebiet um An'daroth, tötet 12 Spione der Schildwache und kehrt anschließend zu Dame Auriferous in Tristessa in den Geisterlanden zurück."}}
D[9161] = {"Schatten des Verräters",{"Begebt Euch in die Geisterlande zum Morgensternturm und sucht nach möglichen Hinweisen auf Dar'Khans Vergangenheit."}}
D[9162] = {"Die Vergangenheit erwacht",{"Kehrt mit Dar'Khans Tagebuch zu Waldläuferin Vynna bei der Enklave der Weltenwanderer in den Geisterlanden zurück."}}
D[9163] = {"In besetztem Gebiet",{"Stehlt die Nachtelfenpläne: An'daroth, Nachtelfenpläne: An'owyn und Nachtelfenpläne: Auskundschaften der Sin'dorei und kehrt anschließend in die Geisterlande zu Dame Auriferous in Tristessa zurück."}}
D[9164] = {"Gefangene der Todesfestung",{"Nehmt Renzithens Regenerationsgebräu und begebt Euch zur Todesfestung. Befreit dort Lehrling Varnis, Apothekerin Enith und Waldläufer Vedoran. Kehrt danach zu Arkanistin Janeda beim Sanktum der Sonne zurück, um Eure Belohnung zu erhalten."}}
D[9165] = {"Verfügung des freien Geleits",{"Bringt die unterschriebene Verfügung des freien Geleits zu Einsatzkommandant Metz an der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
D[9166] = {"Bringt die Pläne nach An'telas",{"Bringt die Nachtelfenpläne zu Magister Sylastor bei An'telas in den Geisterlanden."}}
D[9167] = {"Der Tod des Verräters",{"Begebt Euch in die Todesfestung und tötet Dar'Khan Drathir. Bringt anschließend Dar'Khans Kopf zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden."}}
D[9168] = {"Im Herzen der Todesfestung",{"Zerstört 8 Augen von Dar'Khan und meldet Euch anschließend bei Magister Idonis am Sanktum der Sonne in den Geisterlanden."}}
D[9169] = {"Die Abschaltung von An'owyn",{"Beschafft die Kristallkontrollkugel und benutzt sie, um die nachtelfischen Mondkristalle bei An'owyn zu deaktivieren. Kehrt anschließend zu Magister Sylastor in An'telas in den Geisterlanden zurück."}}
D[9170] = {"Dar'Khans Gefolgschaft",{"Magister Idonis möchte, dass Ihr Euch zur Todesfestung begebt und Masophet den Schwarzen, Jurion den Betrüger, Borgoth den Blutvergießer und Mirdoran den Gefallenen tötet. Kehrt nach Abschluss Eurer Aufgabe zum Sanktum der Sonne in den Geisterlanden zurück und berichtet ihm."}}
D[9171] = {"Knusperkost",{"Sammelt 5 knusprige Spinnenbeine ein und kehrt zu Meisterkoch Mouldier in Tristessa in den Geisterlanden zurück."}}
D[9172] = {"Bericht an Magister Kaendris",{"Bringt Dar'Khans Tagebuch zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden."}}
D[9173] = {"Rückeroberung des Windläuferturms",{"Besiegt 8 Akolythen der Todesfestung und 10 gefallene Waldläufer, dann kehrt zu Hochexekutor Mavren nach Tristessa in den Geisterlanden zurück."}}
D[9174] = {"Aquantion bezwingen",{"Geranis Weißflor möchte, dass Ihr auf den Grund des Sees östlich von Sonnenkuppe taucht und das Bündel mit Medaillons auf den Altar der Gezeitenbeherrschung legt. Beschwört und besiegt den Elementar Aquantion und kehrt zu Geranis zurück."}}
D[9175] = {"Die Halskette der Lady",{"Bringt die Halskette der Lady zu Hochexekutor Mavren nach Tristessa in den Geisterlanden."}}
D[9176] = {"Die Zwillingsziggurats",{"Reist zur blutenden und zur heulenden Ziggurat und bergt den Stein des Lichts und den Stein der Flamme. Kehrt anschließend zu Magister Kaendris beim Sanktum der Sonne in den Geisterlanden zurück."}}
D[9177] = {"Reise nach Unterstadt",{"Bringt die Halskette der Lady zu Lady Sylvanas Windläufer im Königsviertel von Unterstadt."}}
D[9178] = {"Handwerksverfügung - Verdichteter Gewichtsstein",{"Bringt 120 verdichtete Gewichtssteine und die Handwerksverfügung für die verdichteten Gewichtssteine zu Rottenkommandant Steinberster bei der Kapelle des hoffnungsvollen Lichts in den östlichen Pestländern."}}
