D[10125] = {"Mission: Die Kommunikation unterbrechen",{"Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr To'archs Sprengstoff benutzt, um den Sender der Legion: Bosheit, Sender der Legion: Zorn, Sender der Legion: Hass und Sender der Legion: Furcht zu zerstören."}}
D[10126] = {"Kriegsboss Nekroggs Befehle"}
D[10127] = {"Mission: Das Band zerreißen",{"Vorpostenkommandant To'arch am Häschersturz auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Shi'aziv tötet."}}
D[10128] = {"Der Soldat Imarion"}
D[10129] = {"Mission: Tore Murketh und Shaadraz",{"Sprecht mit Schwadronskommandant Brack, bombardiert Tor Murketh und Tor Shaadrez und kehrt dann zu Vorpostenkommandant To'arch im Häschersturz zurück."}}
D[10130] = {"Die westliche Flanke",{"Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Leutnant Amadi im westlichen Wachturm der Ehrenfeste."}}
D[10131] = {"Fluchtplan"}
D[10132] = {"Eine kolossale Bedrohung",{"Tötet 5 tobende Kolosse und kehrt dann zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück."}}
D[10133] = {"Mission: Tötet den Boten"}
D[10134] = {"Hinweise des purpurnen Kristalls",{"Bringt den Purpurkristallsplitter zu Tola'thion im Posten des Cenarius auf der Höllenfeuerhalbinsel."}}
D[10135] = {"Mission: Seid der Bote"}
D[10136] = {"Grausame Pläne",{"Tötet Arazzius den Grausamen und kehrt danach zu Nazgrel in Thrallmar zurück."}}
D[10137] = {"Den Kriegsboss provozieren"}
D[10138] = {"Auf wessen Befehl hin?"}
D[10139] = {"Die Beseitigung des Kommandanten"}
D[10140] = {"Reise zur Ehrenfeste",{"Fliegt zur Ehrenfeste und übergebt Marschall Isildor Durons Bericht."}}
D[10141] = {"Wiedergeburt der Brennenden Legion",{"Sprecht mit Unteroffizier Altumus bei der östlichen Versorgungskarawane außerhalb der Ehrenfeste im Osten."}}
D[10142] = {"Der Pfad der Pein",{"Unteroffizier Altumus bei der östlichen Versorgungskarawane östlich der Ehrenfeste auf der Höllenfeuerhalbinsel möchte, dass Ihr 4 Flammenschürerwichtel, 6 höllische Kriegshetzer und 1 Schreckensrufer tötet."}}
D[10143] = {"Expeditionsposten",{"Meldet euch bei Vorpostenkommandant Königstein im Expeditionsposten."}}
D[10144] = {"Die Kommunikation unterbrechen",{"Besiegt die Feinde um Portal Grimh und Portal Kaalez herum, um dämonische Runensteine zu sammeln.","","Benutzt Königsteins Zünder in Portal Grimh und Portal Kaalez.","","Kehrt danach mit dem Zünder zu Vorpostenkommandant Königstein zurück."}}
D[10145] = {"Mission: Sever the Tie UNUSED",{"Vorpostenkommandant Wa'ppun beim Expeditionsposten auf de Höllenfeuerhalbinsel möchte, dass Ihr 4 Teufelstreiber, 8 Zornwächter und Unterwerferin Yalqiz tötet."}}
D[10146] = {"Mission: Tor Murketh und Tor Shaadraz",{"Sprecht mit Schwadronskommandant Dabir'ee, bombardiert Tor Murketh und Tor Shaadraz und kehrt dann zu Vorpostenkommandant Wa'ppun am Expeditionsposten zurück."}}
D[10147] = {"Mission: Tötet den Boten"}
D[10148] = {"Mission: Seid der Bote"}
D[10149] = {"Mission: Beendet alles, seid alles"}
D[10150] = {"Die Erstreckung der Zitadelle",{"Durchsucht das nördlichste Lager entlang des nördlichen Bollwerks nach einer Spur von Späherin Makha."}}
D[10151] = {"Kriegsboss Nekroggs Befehle"}
D[10152] = {"Die westliche Flanke",{"Tötet 10 Wachen der Zerschmetterten Hand, 10 Berserker der Zerschmetterten Hand und 5 Akolythen der Zerschmetterten Hand und meldet Euch dann bei Steingardist Ambelan im Rückenbrecherposten in der Nähe von Zeth'Gor."}}
D[10153] = {"Die Späherin Makha"}
D[10154] = {"Fluchtplan"}
D[10155] = {"Den Kriegsboss provozieren"}
D[10156] = {"Auf wessen Befehl hin?"}
D[10157] = {"Die Beseitigung des Kommandanten"}
D[10158] = {"Vorräte des Blutenden Auges"}
D[10159] = {"Haltet den Dornnebelhügel sauber!",{"Tötet 8 Dornenfangfelshetzer und 8 Dornenfanggiftspucker und kehrt dann zu Mahuram Starkhuf im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück."}}
D[10160] = {"Den Feind kennen",{"Sprecht mit Leutnant Amadi im alten Wachturm im Westen der Ehrenfeste."}}
D[10161] = {"Im Notfall...",{"Sammelt 30 Zeppelintrümmer und bringt sie zu \"Schreihals\" Quack Lufthans bei der Zeppelinabsturzstelle."}}
D[10162] = {"Mission: Die Abyssische Untiefe",{"Vorpostenkommandant To'arch im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet."}}
D[10163] = {"Mission: Die Abyssische Untiefe",{"Schwadronskommandant Greifgar im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen vernichtet."}}
D[10164] = {"Alles wird gut",{"Großvater Aldrimus außerhalb der Auchenaikrypta von Auchindoun möchte, dass Ihr in die Auchenaikrypta geht und Exarch Maladaar vernichtet."}}
D[10165] = {"Die Konkurrenz untergraben",{"Nexusprinz Haramad außerhalb der Managruft möchte, dass Ihr Nexusprinz Shaffar tötet und ihm Shaffars Bandagen bringt."}}
D[10166] = {"Weißborkes Erinnerung",{"Larianna Flusswind möchte, dass Ihr Weißborkes Anhänger beim Runenstein im versengten Hain vergrabt."}}
D[10167] = {"Auchindoun...",{"Reist zur Auchenaikrypta in der Knochenwüste der Wälder von Terokkar und tötet Exarch Maladaar um den Geist von D'ore zu befreien."}}
D[10168] = {"Was die Seele sieht",{"Sucht einen Seelenspiegel in der Auchenaikrypta und benutzt ihn, um einen getrübten Geist eines uralten Orcahnen von Nagrand zu rufen. Zerstört 15 getrübte Geister, damit die Ahnen in Frieden ruhen können.","","Kehrt zu Mutter Kashur im Ahnengrund zurück, wenn Ihr fertig seid."}}
D[10169] = {"In Würde verlieren",{"Magister Falris in Shattrath möchte, dass Ihr die Phiole mit Beruhigungsserum zur Terrasse des Lichts bringt und sie in den Kochtopf von Haronems Regiment schüttet."}}
D[10170] = {"Rückkehr zur Großmutter",{"Kehrt nach Garadar zurück und sprecht mit Großmutter Geyah."}}
D[10171] = {"Der untröstliche Häuptling",{"Großmutter Geyah in Garadar möchte, dass Ihr mit Garrosh sprecht."}}
D[10172] = {"Es gibt keine Hoffnung",{"Sprecht mit Großmutter Geyah und erzählt ihr, was Garrosh Euch gesagt hat."}}
D[10173] = {"Der Stab des Erzmagiers",{"Besorgt Erzmagier Vargoths Stab von Ekkorash der Inquisitorin und bringt ihn zu Ravandwyr in Area 52. Um Ekkorash aus ihrem Versteck hervorzulocken, streut das Beschwörungspulver auf die Kohlenpfanne in der Mitte der Ruinen."}}
D[10174] = {"Der Fluch des Violetten Turms",{"Benutzt Erzmagier Vargoths Stab um Kontakt mit Erzmagier Vargoth aufzunehmen.","","Falls Ihr Erzmagier Vargoths Stab verlieren solltet, bittet Ravandwyr in Area 52 um Ersatz."}}
D[10175] = {"Thrall, Sohn Durotans",{"Reist nach Orgrimmar und überbringt Thrall Geyahs Nachricht."}}
D[10176] = {"Ar'kelos der Wächter",{"Betretet den Violetten Turm in der Mitte von Kirin'Var und besiegt Ar'kelos. Sprecht danach mit Erzmagier Vargoth."}}
D[10177] = {"Ärger in Auchindoun",{"Meldet Euch bei Feldkommandeur Mahfuun beim Eingang zum Schattenlabyrinth in Auchindoun in den Wäldern von Terokkar."}}
D[10178] = {"Findet Spion To'gun",{"Findet Spion To'gun im Schattenlabyrinth von Auchindoun."}}
D[10179] = {"Der Hüter von Kirin'Var",{"Sprecht mit Hüter Dierwert in Kirin'Var im Nethersturm."}}
D[10180] = {"Kann es einfach nicht lassen",{"Sprecht mit Isfar beim Eingang zu den Sethekkhallen in Auchindoun."}}
D[10182] = {"Kampfmagier Dathric",{"Sucht die Wohnung von Kampfmagier Dathric in der Zaubergasse und bringt die Klinge zurück in sein Waffenregal. Sprecht danach mit Hüter Dierwert in Kirin'Var."}}
D[10183] = {"Auf nach Area 52",{"Bringt die Notizen des Netheorologen zu Raketenchef Doppeldecker in Area 52 im Nethersturm."}}
D[10184] = {"Bösartige Überbleibsel",{"Hüter Dierwert in Kirin'Var möchte, dass Ihr 20 abtrünnige Geister auf dem Ratsplatz tötet."}}
D[10185] = {"Schlimmer als der Tod",{"Tötet 10 Magiertöter und 10 Manasucher und kehrt zu Hüter Dierwert in Kirin'Var zurück."}}
D[10186] = {"Ihr seid eingestellt!",{"Sammelt 10 Astrallithiummatrixkristalle und kehrt dann zu Raketenchef Doppeldecker in Area 52 im Nethersturm zurück."}}
D[10187] = {"Eine Nachricht für den Erzmagier",{"Sprecht mit Erzmagier Vargoth im Violetten Turm im Nethersturm."}}
D[10188] = {"Das Siegel von Krasus",{"Holt Euch das Siegel von Krasus von Zauberbinderin Maryana in der Manaschmiede Coruu, nordwestlich vom Violetten Turm."}}
D[10189] = {"Manaschmiede B'naar",{"Spionagemeister Thalodien in Area 52 möchte, dass Ihr zum Rand der Manaschmiede B'naar geht und die Stammrolle von B'naar von Hauptmann Arathyn besorgt.","","Das Abschließen von Aufgaben für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10190] = {"Batterien aufladen",{"Benutzt den Batterieladeblaster bei genügend Phasenjägern, um den Batterieladestatus auf 10 zu bringen. Bringt die Batterie danach zu Bot-Spezialistin Alley in den Ruinen von Enkaat im Nethersturm zurück."}}
D[10191] = {"Nummer V lebt!",{"Begleitet Maxx E. Million Nr. V durch die Ruinen von Enkaat und wieder in Sicherheit. Sprecht dann mit Bot-Spezialistin Alley außerhalb der Ruinen von Enkaat im Nethersturm."}}
D[10192] = {"Krasus' Kompendium",{"Holt Euch Krasus' Kompendium - Kapitel 1, Krasus' Kompendium - Kapitel 2 und Krasus' Kompendium - Kapitel 3 vom Ratsplatz von Kirin'Var."}}
D[10193] = {"Hochrangige Ziele",{"Spionagemeister Thalodien in Area 52 möchte, dass Ihr in die Manaschmiede B'naar geht und 2 Warpmeister des Sonnenzorns, 6 Warpingenieure des Sonnenzorns und 8 Geologen des Sonnenzorns tötet.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10194] = {"Heimlicher Flug",{"Sprecht mit Veronia außerhalb von Area 52 und fliegt zur Manaschmiede Coruu.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10195] = {"Söldner sieht, Söldner handelt"}
D[10196] = {"Mehr Arakkoafedern",{"Bringt 30 Arakkoafedern zu Malukaz in der Steinbrecherfeste."}}
D[10197] = {"Eine überzeugende Verkleidung",{"Bringt ein Set Arkanistenroben des Sonnenzorns, ein Paar Forscherhandschuhe des Sonnenzorns und ein Gardistenmedaillon des Sonnenzorns zu Caledis Morgenhell bei der Manaschmiede Coruu im Nethersturm.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10198] = {"Informationen sammeln",{"Benutzt die Sonnenzornverkleidung, geht in die Manaschmiede Coruu und belauscht das Gespräch zwischen Sonnenzornkommandant Morgenschmied und Arkanist Ardonis. Meldet Euch bei Caledis Morgenhell in der Manaschmiede Coruu, wenn Ihr die Aufgabe abgeschlossen habt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10199] = {"Der kleine Extrakick",{"Besorgt 5 Netherrochenstachel und bringt sie zu Stiefels in Area 52 im Nethersturm."}}
D[10200] = {"Rückkehr zu Thalodien",{"Kehrt zu Spionagemeister Thalodien in Area 52 im Nethersturm zurück."}}
D[10201] = {"Der Moment der Wahrheit",{"Geht zu Grek und bittet ihn, das Öl an seiner Waffe auszuprobieren. Bringt das Ergebnis zu Rakoria, wenn er fertig ist."}}
D[10202] = {"Ein Abtrünniger",{"Geht zur Manaschmiede Ara und sprecht mit Magister Theledorn.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10203] = {"Unschätzbare Ausrüstung beamen",{"Benutzt den ultrastarken Dekonsolidierungsstrahler, um den Hyperdreh-Grab-o-Matik, die servopneumatische Baggerklaue, den multispektralen Geländeabtaster und den großen Wagen voller Sprengstoff zurück nach Area 52 zu beamen. Meldet Euch dann beim leitenden Ingenieur Zischeldruck beim östlichen Ende des Risses in Area 52 im Nethersturm."}}
D[10204] = {"Blutjuwelenkristalle",{"Magistrix Larynna möchte, dass Ihr zur Manaschmiede B'naar geht und einen Blutjuwelensplitter von einem Magister des Sonnenzorns besorgt. Benutzt den Splitter in der Nähe von größeren Blutjuwelenkristallen und kehrt zu ihr in Area 52 zurück.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10205] = {"Sphärenräuber Nesaad",{"Tötet Sphärenräuber Nesaad und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück."}}
D[10206] = {"Wählt Eure Rolle",{"Sammelt 10 Stück Astraltechnologie und bringt sie zu Papa Mauschel in Area 52 im Nethersturm."}}
D[10207] = {"Vorposten: Häschersturz"}
D[10208] = {"Die Verstärkung abschneiden",{"Besiegt die Feinde um Portal Xilus und Portal Kruul herum, um dämonische Runensteine zu sammeln.","","Benutzt To'archs Zünder in Portal Xilus und Portal Kruul.","","Kehrt danach mit To'archs Zünder zu To'arch im Häschersturz auf der Höllenfeuerhalbinsel zurück."}}
D[10209] = {"Beschwörer Kanthins Preis",{"Besiegt Beschwörer Kanthin in der Manaschmiede Duro auf der Insel nördlich des Sonnenzornpostens und holt den Stein des Gletscharius zurück."}}
D[10210] = {"A'dal",{"Sprecht mit A'dal, Anführer der Sha'tar in der Mitte der Terrasse des Lichts."}}
D[10211] = {"Stadt des Lichts",{"Folgt Khadgars Diener und hört Euch an, was er zu erzählen hat. Kehrt nach dieser Aufgabe zu Khadgar zurück."}}
D[10212] = {"Held der Mag'har",{"Kehrt zu Großmutter Geyah in Garadar in Nagrand zurück."}}
D[10213] = {"Untersuchung der Absturzstelle",{"Durchsucht die Absturzstelle nach Überlebenden."}}
D[10214] = {"Bringt diese Mine zum beben!",{"Tötet 15 Pioniere der Gan'arg und kehrt dann zu Großknecht Razelcraz zurück."}}
D[10216] = {"Sicherheit geht vor",{"Konstrukteur Morphalius möchte, dass Ihr 10 astrale Grufträuber, 5 astrale Zauberer, 5 Nexuswandler und 5 astrale Zauberbinder tötet.","","Wenn Ihr damit fertig seid, sucht den astralen Transporter in der Kammer vor Shaffars Kammern und aktiviert ihn."}}
D[10218] = {"Jemandes Arbeit zahlt sich aus",{"Begleitet Kryoingenieur Sha'heen sicher durch die Managruft, damit er die Astralmaterie aus Shaffars Astralsammlern entnehmen kann.","","Meldet Euch bei Nexusprinz Haramad außerhalb der Managruft beim Lager des Konsortiums, wenn Ihr erfolgreich wart."}}
D[10219] = {"Gassi gehen"}
D[10220] = {"Bringt sie zum Zuhören",{"Mordiba möchte, dass Ihr 12 unerschütterliche Fußsoldaten, 8 unerschütterliche Krieger und 6 unerschütterliche Zauberhexer beim Expeditionsrüstlager westlich des Rückenbrecherpostens tötet."}}
D[10221] = {"Dr. Bumm!",{"Tötet Dr. Bumm und kehrt dann mit den guten Nachrichten zu dem leitenden Ingenieur Zischeldruck in Area 52 im Nethersturm zurück."}}
D[10222] = {"Die Garnison des Sonnenzornpostens",{"Hüter Dierwert in Kirin'Var möchte, dass Ihr 10 Bogenschützen des Sonnenzorns tötet."}}
D[10223] = {"Nieder mit Daellis",{"Hüter Dierwert in Kirin'Var möchte, dass Ihr Meister Daellis Morgenschlag tötet."}}
D[10224] = {"Essenzen für die Motoren",{"Sammelt 7 Essenzen eines Managespensts und bringt sie zu Chefingenieur Trep bei Area 52 im Nethersturm."}}
D[10225] = {"Meldung beim Chefingenieur",{"Bringt die Astrallithiummatrixkristalle zu Chefingenieur Trep in Area 52 im Nethersturm."}}
D[10226] = {"Elementarenergieextraktor",{"Extrahiert 5 Einheiten Elementarenergie und bringt sie zu Chefingenieur Trep in Area 52 im Nethersturm."}}
D[10227] = {"Ich sehe tote Draenei",{"Sprecht mit Ramdor dem Wahnsinnigen auf dem Knochenhaufen außerhalb der Auchenaikrypta."}}
D[10228] = {"Ezekiel",{"Sprecht mit Ezekiel von Shattrath in Shattrath."}}
D[10229] = {"Den Folianten entziffern",{"Bringt den geheimnisvollen Folianten zu Althen dem Historiker im Rückenbrecherposten."}}
D[10230] = {"Das Kampfhorn",{"Besorgt Euch das Kampfhorn der Unerschütterlichen von Feldkommandant Thalvos und bringt es zu Althen dem Historiker im Rückenbrecherposten."}}
D[10231] = {"Welches Buch? Ich sehe kein Buch.",{"Ezekiel sagt, dass das Buch gestohlen wurde. Eure einzige Spur führt Euch zu den Grobianen. Schaut nach, ob sie irgendwelche Informationen haben."}}
D[10232] = {"Legion in Trümmern",{"Tötet 5 Schicksalsschmiede der Mo'arg und 15 Ingenieure der Gan'arg. Kehrt danach zu Papa Mauschel in Area 52 im Nethersturm zurück."}}
D[10233] = {"Den Sonnenzornposten anzünden",{"Benutzt eine flammende Fackel, zerstört 4 Sonnenzornballisten und 4 Sonnenzornzelte und kehrt dann zu Zaubererleutnant Morran in Kirin'Var zurück."}}
D[10234] = {"Der Müll eines Dämons",{"Sammelt 10 Teile eines Teufelshäschers und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10235] = {"Verdammnisklaue die Krallen stutzen",{"Besorgt Euch Verdammnisklaues Hand und bringt sie zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10236] = {"Die Scherbenwelt ist doof!",{"Großknecht Razelcraz möchte, dass Ihr ihm 6 Schredderteile besorgt. Kehrt danach zu ihm bei der Mine nordwestlich von Thrallmar zurück."}}
D[10237] = {"Warnt Area 52!",{"Überbringt Raketenchef Doppeldecker in Area 52 in Nethersturm die schlechten Nachrichten."}}
D[10238] = {"Wie man Goblins zubereitet",{"Rettet Manni, Moh und Jakk aus den Lagern der Höllenorcs und bringt sie zu Großknecht Razelcraz bei der Mine nordwestlich von Thrallmar zurück."}}
D[10239] = {"Mögliche Energiequelle",{"Zaubererleutnant Morran in Kirin'Var möchte, dass Ihr ihm 10 Energieisolationswürfel von den Blutelfen der Manaschmiede Coruu bringt."}}
D[10240] = {"Eine Verteidigung errichten",{"Benutzt das Gerät zur Aktivierung von Runen bei der östlichen Rune, der nordöstlichen Rune und der westlichen Rune. Die Runen befinden sich entlang der Verteidigung der Zaubergasse und des Ratsplatz von Kirin'Var. Kehrt zu Zaubererleutnant Morran zurück, wenn Ihr die Aufgabe erfüllt habt."}}
D[10241] = {"Ablenkung in der Manaschmiede B'naar",{"Tötet 8 Magister des Sonnenzorns und 8 Blutwärter des Sonnenzorns und kehrt dann zu Exarch Orelis in Area 52 zurück.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Ruf bei den Sehern."}}
D[10242] = {"Der Rückenbrecherposten",{"Apothekerin Zelana beim Häschersturz möchte, dass Ihr mit Schwadronskommandant Brack sprecht, um auf einem Flügeldrachen zum Rückenbrecherposten zu fliegen. Bringt die Blutprobe des Blutenden Auges zu Apotheker Albreck im Rückenbrecherposten."}}
D[10243] = {"Die Technologie der Naaru",{"Geht in die Manaschmiede B'naar und sucht die Steuerkonsole von B'naar.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10244] = {"Liesmich",{"Bringt die Bauanleitung für Teufelshäscher zu Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10245] = {"Steuerungsabschrift von B'naar",{"Bringt die Steuerungsabschrift von B'naar zu Anachoret Karja in Area 52 im Nethersturm.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10246] = {"Angriff auf Manaschmiede Coruu",{"Reist zur Manaschmiede Coruu und tötet 8 Arkanisten des Sonnenzorns und 5 Forscher des Sonnenzorns. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10247] = {"Dr. h. c. tüft. Vomisa",{"Sprecht mit Dr. h. c. tüft. Vomisa in den Versuchsgründen im Nethersturm."}}
D[10248] = {"Du, der Roboter",{"Aktiviert die Steuerung für Schrotthäscher X6000 und testet seine Fähigkeiten aus. Gebt Dr. h. c. tüft. Vomisa bei den Versuchsgründen im Nethersturm danach Eure Rückmeldung."}}
D[10249] = {"Zurück zum Chef!",{"Meldet Euch sofort bei Raketenchef Doppeldecker in Area 52 im Nethersturm!"}}
D[10250] = {"Blutige Rache",{"Stoßt am alten Belagerungsturm der Allianz in das Kampfhorn der Unerschütterlichen. Tötet Urtrak und kehrt danach zu Althen dem Historiker im Rückenbrecherposten zurück."}}
D[10251] = {"Der große Plan des Meisters?",{"Sucht Nitrin den Gelehrten im verlassenen Rüstlager in Nagrand."}}
D[10252] = {"Vision der Toten",{"Nitrin im verlassenen Rüstlager in Nagrand möchte, dass Ihr ihm 1 Augapfel eines Berggronns, 1 fehlerloser Schnabel eines großen Windrocs und 1 Tran eines gealterten Grollhufs bringt."}}
D[10253] = {"Levixus der Seelenrufer",{"Vernichtet Levixus und nehmt Euch das Buch der Toten aus seinem Besitz.","","Bringt das Buch der Toten zu Ramdor dem Wahnsinnigen außerhalb der Auchenaikrypta am Eingang zu Auchindoun.","","Ihr hattet eine Vereinbarung, erinnert Ihr Euch?"}}
D[10254] = {"Truppenkommandant Danath",{"Marschall Isildor möchte, dass Ihr Euch bei Truppenkommandant Danath Trollbann in der Ehrenfeste meldet."}}
D[10255] = {"Das Gegengift testen",{"Probiert das cenarische Gegengift an einem bulligen Hölleneber aus und beobachtet die Folgen. Sobald Ihr die Ergebnisse des Experiments habt, kehrt zu Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel zurück."}}
D[10256] = {"Den Schlüsselmeister finden",{"Sucht Apex und besorgt Euch Apex' Kristallfokus. Kehrt dann zum Violetten Turm zurück und benutzt Apex' Kristallfokus in der Nähe von Erzmagier Vargoths Kugel um herauszufinden, wer den Schlüssel zum Fluch des Turms hat."}}
D[10257] = {"Den Schlüsselstein erobern",{"Reist zur Botanika der Festung der Stürme und besorgt Euch den Schlüsselstein von Kommandant Sarannis. Bringt ihn danach zu Erzmagier Vargoth im Violetten Turm."}}
D[10258] = {"Die Gefallenen ehren",{"Meldet Euch bei Hogarth, dem Kommandanten des Expeditionsrüstlagers."}}
D[10259] = {"Auf in den Kampf!",{"Tötet 6 einfallende Teufelswachen und kehrt dann zum Argentumabgesandten Stolzbrunn zurück."}}
D[10260] = {"Netheorologe Kupfernickel",{"Sprecht mit Netheorologe Kupfernickel bei der Brücke, die vom Nethersturm zum Schergrat führt."}}
D[10261] = {"Gesucht: Vernichterservo!",{"Besorgt einen Vernichterservo und bringt ihn zu Papa Mauschel in Area 52 im Nethersturm."}}
D[10262] = {"Ein Hügel voll Astraler",{"Sammelt 10 Insignien der Zaxxis und kehrt dann zu Netherpirscher Khay'ji in Area 52 im Nethersturm zurück."}}
D[10263] = {"Dem Konsortium helfen",{"Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm."}}
D[10264] = {"Dem Konsortium helfen",{"Sprecht mit Netherpirscher Khay'ji in Area 52 im Nethersturm."}}
D[10265] = {"Kristallsammlung des Konsortiums",{"Besorgt ein Kristallartefakt von Arklon und bringt es zu Netherpirscher Khay'ji in Area 52 im Nethersturm."}}
D[10266] = {"Bitte um Unterstützung",{"Sucht Gahruj und bietet ihm Eure Hilfe an. Er befindet sich im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10267] = {"Rechtmäßiger Besitz",{"Sammelt 10 Kästen mit Vermessungsausrüstung und bringt sie zu Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10268] = {"Eine Audienz beim Prinzen",{"Bringt die Vermessungsausrüstung zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm."}}
D[10269] = {"Triangulationspunkt Eins",{"Benutzt das Triangulationsgerät, um den Weg zum ersten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Händler Hazzin beim Wachposten des Protektorats auf der Insel der Manaschmiede Ultris im Nethersturm."}}
D[10270] = {"Ein nicht-so-bescheidenes Angebot",{"Besorgt Euch die Teleporterenergiezelle und bringt sie zur Astralteleportplattform im Sternensturz östlich der Manaschmiede Ultris. Aktiviert die Plattform und bringt die Teleporterenergiezelle zum Bild von Windhändler Marid, damit er sie einbauen kann."}}
D[10271] = {"Zur Sache",{"Sammelt 8 Einheiten Netherdrachenessenz und kehrt dann zur Gegend bei der Astralteleporterplattform zurück. Die Netherdrachenessenz könnt Ihr von Netherdrachen oder Nethergroßdrachen sammeln."}}
D[10272] = {"Ein viel versprechender Anfang",{"Sammelt 15 Netherdrachkineier und kehrt dann zu Tyri und Jorad im Sternensturz zurück."}}
D[10273] = {"Störende Ablenkung",{"Sprecht mit Windhändler Marid und lockt ihn von seinem Handelsposten fort. Vernichtet ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück."}}
D[10274] = {"Den Sternensturz sichern",{"Benutzt die Herausforderung des blauen Drachenschwarms um Veraku am südlichen Ende des Sternensturzes zu provozieren. Besiegt ihn und kehrt dann zu Tyri und Jorad im Sternensturz zurück."}}
D[10275] = {"Triangulationspunkt Zwei",{"Benutzt das Triangulationsgerät, um den Weg zum zweiten Triangulationspunkt zu bestimmen. Wenn Ihr ihn gefunden habt, meldet die Position an Windhändler Tuluman auf Tulumans Landeplatz auf der anderen Seite der Brücke zu der Insel der Manaschmiede Ara im Nethersturm."}}
D[10276] = {"Das volle Dreieck",{"Besorgt Euch den Kristall von Ata'mal und bringt ihn zum Bild von Nexusprinz Haramad in der Sturmsäule im Nethersturm."}}
D[10277] = {"Die Höhlen der Zeit",{"Andormu in den Höhlen der Zeit möchte, dass Ihr der Bewahrerin der Zeit durch die Höhle folgt."}}
D[10278] = {"Sphärenrisse",{"Benutzt den instabilen Sphärenrissgenerator in den Sphärenfeldern. Sammelt 3 Einheiten Sphärennether von instabilen Leerwandlern und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück."}}
D[10279] = {"Zum Hort des Meisters",{"Sprecht mit Andormu in den Höhlen der Zeit."}}
D[10280] = {"Sonderlieferung nach Shattrath",{"Bringt den Kristall von Ata'mal zu A'dal auf der Terrasse des Lichts in Shattrath."}}
D[10281] = {"Formelle Vorstellung",{"Sucht Tyri am nördlichen Ende des Sternensturzes und sprecht mit ihr."}}
D[10282] = {"Das alte Hügelland",{"Andormu in den Höhlen der Zeit bittet Euch, ins Alte Hügelland zu reisen und mit Erozion zu sprechen."}}
D[10283] = {"Tarethas Ablenkungsmanöver",{"Reist zur Burg Durnholde und platziert mithilfe des Bündels mit Brandbomben, das Ihr von Erozion erhalten habt, 5 Brandsätze auf den Fässern in jeder Internierungsbaracke.","","Sprecht mit Thrall im Kellergefängnis der Burg Durnholde, wenn Ihr die Internierungsbaracken angezündet habt."}}
D[10284] = {"Flucht aus Durnholde",{"Gebt Thrall Bescheid, wenn Ihr bereit seid. Folgt Thrall aus der Burg Durnholde und helft ihm, Taretha zu befreien und sein Schicksal zu erfüllen.","","Sprecht mit Erozion im Alten Hügelland, wenn Ihr diese Aufgabe erfüllt habt."}}
D[10285] = {"Rückkehr zu Andormu",{"Kehrt zu dem jungen Andormu in den Höhlen der Zeit in Tanaris zurück."}}
D[10286] = {"Arelions Geheimnis",{"Magistrix Carinda möchte, dass Ihr Magister Aledis befragt. Aledis wurde zuletzt auf einer Reise von der Falkenwacht zu den Zangarmarschen gesehen."}}
D[10287] = {"Die enttarnte Geliebte",{"Kehrt zu Magistrix Carinda in die Falkenwacht auf der Höllenfeuerhalbinsel zurück."}}
D[10288] = {"Ankunft in der Scherbenwelt",{"Kommandant Duron beim Dunklen Portal auf der Höllenfeuerhalbinsel möchte, dass Ihr Durons Bericht zu Flugmeister Amish Wildhammer bringt."}}
D[10289] = {"Reise nach Thrallmar",{"Nehmt Vlagga Freyfeders Windreiter nach Thrallmar. Bringt Orions Bericht zu General Krakork."}}
D[10290] = {"Auf der Suche nach Farahlit",{"Sammelt 4 Stück Rohfarahlit und kehrt dann zu Zuben Elgenubi in der Sturmsäule zurück."}}
D[10291] = {"Bericht an Nazgrel",{"General Krakork in Thrallmar möchte, dass Ihr mit Nazgrel sprecht."}}
D[10292] = {"Mehr Energie!",{"Zuben Elgenubi möchte, dass Ihr 8 Schusswaffen der Legion besorgt und sie zur Sturmsäule bringt."}}
D[10293] = {"Die Kristallader anzapfen",{"Zuben Elgenubi in der Sturmsäule möchte, dass Ihr einen Farahlitkern besorgt."}}
D[10294] = {"Der Leerengrat",{"Geht zum Leerengrat und tötet die Kreaturen, die Ihr dort findet. Sammelt 40 Seelensplitter des Leerengrats und kehrt dann zu Ogath dem Verrückten im Rückenbrecherposten zurück."}}
D[10295] = {"Aus dem Abgrund",{"Tötet Galaxis und sammelt seinen Seelensplitter. Bringt den Splitter zu Ogath dem Verrückten im Rückenbrecherposten."}}
D[10296] = {"Der schwarze Morast",{"Reist durch die Höhlen der Zeit in den schwarzen Morast während der Öffnung des Dunklen Portals und sprecht mit Sa'at."}}
D[10297] = {"Die Öffnung des Dunklen Portals",{"Sa'at im schwarzen Morast der Höhlen der Zeit möchte, dass Ihr Medivh verteidigt, bis er das Dunkle Portal geöffnet hat.","","Kehrt zu Sa'at zurück, wenn Ihr erfolgreich wart."}}
D[10298] = {"Held des Schwarms",{"Kehrt zum Kind, Andormu, in den Höhlen der Zeit in Tanaris zurück."}}
D[10299] = {"Manaschmiede B'naar abschalten",{"Anachoret Karja möchte, dass Ihr in die Manaschmiede B'naar geht und einen Zugangskristall von Vorarbeiter Theredis besorgt. Benutzt ihn bei der Steuerkonsole von B'naar, um sie abzuschalten und meldet Euch danach bei Anachoret Karja zurück.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10300] = {"Den Stab wiederherstellen",{"Besorgt 4 fehlerlose Kristallsplitter von den Geistern in den Ruinen von Enkaat und bringt sie zu Ravandwyr in Area 52."}}
D[10301] = {"Das Kompendium öffnen",{"Besorgt Euch das heliotrope Oculus von Zauberhäscherin Marathelle im Sonnenzornposten."}}
D[10302] = {"Unberechenbare Mutanten",{"Tötet 8 unberechenbare Mutanten und kehrt dann zu Botanikerin Taerix bei der Absturzstelle im Am'mental zurück."}}
D[10303] = {"Die Blutelfen",{"Tötet 10 Blutelfenspäher und kehrt dann zu Tolaan im Schattenkamm im Am'mental zurück."}}
D[10304] = {"Verteidiger Aldar",{"Sprecht mit Verteidiger Aldar bei der Absturzstelle im Am'mental."}}
D[10305] = {"Bannzauberin Belmara",{"Sucht die Wohnung von Bannzauberin Belmara in der Zaubergasse und bringt das Buch zurück auf seinen Platz im Bücherregal. Sprecht danach mit Hüter Dierwert in Kirin'Var."}}
D[10306] = {"Beschwörer Luminrath",{"Sucht die Wohnung von Beschwörer Luminrath in der Zaubergasse und bringt den Mantel zurück in seine Kommode. Sprecht danach mit Hüter Dierwert in Kirin'Var."}}
D[10307] = {"Cohlien Frostwirker",{"Sucht die Wohnung von Cohlien Frostwirker in der Zaubergasse und bringt die Kappe zurück in seine Schließkiste. Sprecht danach mit Hüter Dierwert in Kirin'Var."}}
D[10308] = {"Noch ein Hügel voller Astraler"}
D[10309] = {"Teufelshäscher mit Herz",{"Besorgt das Herz des Teufelshäschers und bringt es zu N. D. Mieskamp beim Hügel im Nethersturm."}}
D[10310] = {"Sabotage am Warptor!",{"Begleitet Drijya zum Warptor beim Invasionspunkt: Zerstörer und sorgt für seine Sicherheit, während er das Tor sabotiert. Sprecht danach mit Gahruj im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10311] = {"Drijya braucht Eure Hilfe",{"Sprecht mit Drijya in der Nähe des Invasionspunkts: Zerstörer im Nethersturm."}}
D[10312] = {"Die Annalen von Kirin'Var",{"Besorgt die Annalen von Kirin'Var aus dem Rathaus von Kirin'Var und bringt es zu Hüter Dierwert."}}
D[10313] = {"Warpenergien messen",{"Exarch Orelis in Area 52 möchte, dass Ihr die Warpmesskugel zur Manaschmiede B'naar bringt und sie in der Nähe der vier Rohrleitungen benutzt.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eurer Ehre bei den Sehern."}}
D[10314] = {"Ein hartnäckiger Verdacht",{"Sammelt 10 abscheuliche Überreste von den wahnsinnigen Geistern auf dem Kapellenhof in Kirin'Var und bringt sie zu Hüter Dierwert."}}
D[10315] = {"Die Nethermanten neutralisieren",{"Tötet 15 Nethermanten des Sonnenzorns und kehrt dann zu Netherpirscher Oazul auf Tulumans Landeplatz im Nethersturm zurück."}}
D[10316] = {"Auf der Suche nach Beweisen",{"Durchsucht die Häuser auf dem Kapellenhof von Kirin'Var nach Hinweisen darauf, wer sich hinter der Beeinflussung der Geister verbirgt."}}
D[10317] = {"Den Großknecht erledigen",{"Vernichtet Großknecht Sonnenend in der Trelleummine, die sich unter der Manaschmiede Ara im Nethersturm befindet."}}
D[10318] = {"Den Übermeister erledigen",{"Tötet Übermeister Grindgarr. Kehrt dann zu Windhändler Tuluman auf Tulumans Landeplatz im Nethersturm."}}
D[10319] = {"Das Phylakterium entwenden",{"Holt Naberius' Phylakterium vom Kapellenhof in Kirin'Var und bringt es zu Hüter Dierwert."}}
D[10320] = {"Vernichtet Naberius!",{"Hüter Dierwert in Kirin'Var möchte, dass Ihr Naberius auf dem Kapellenhof des Dorfes besiegt."}}
D[10321] = {"Manaschmiede Coruu abschalten",{"Reist zur Manaschmiede Coruu, östlich von Area 52, und besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Manaschmiede abzuschalten, und kehrt dann zu Anachoret Karja zurück.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10322] = {"Manaschmiede Duro abschalten",{"Anachoret Karja möchte, dass Ihr zur Manaschmiede Duro geht und den Zugangskristall von Vorarbeiter Athanel besorgt. Benutzt ihn, um die Steuerungskonsole von Duro abzuschalten.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10323] = {"Manaschmiede Ara abschalten",{"Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10324] = {"Die große Mondweidenjagd",{"Bringt 6 Bälge eines Mondweidenbocks zu Acteon in der Azurwacht."}}
D[10325] = {"Male von Kil'jaeden",{"Bringt 10 Male von Kil'jaeden zu Adyen dem Lichtwächter in Shattrath.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10326] = {"Mehr Male von Kil'jaeden"}
D[10327] = {"Einzelne Male von Kil'jaeden"}
D[10328] = {"Anweisungen des Sonnenzorns",{"Reist zur Manaschmiede Duro und beschafft die Truppenbefehle des Sonnenzorns und die Arkanbefehle des Sonnenzorns von den Einheiten des Sonnenzorns, die dort postiert sind. Kehrt zu Exarch Orelis zurück, wenn Ihr Eure Aufgabe erledigt habt.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10329] = {"Manaschmiede B'naar abschalten",{"Geht zurück zur Manaschmiede B'naar und besorgt Euch den Zugangskristall von Vorarbeiter Theredis. Benutzt ihn bei der Steuerkonsole von B'naar um sie abzuschalten und meldet Euch danach bei Spionagemeister Thalodien zurück.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10330] = {"Manaschmiede Coruu abschalten",{"Besorgt den Zugangskristall von Coruu von Vorarbeiterin Seylanna. Benutzt ihn, um die Steuerkonsole der Manaschmiede abzuschalten und meldet Euch dann bei Caledis Morgenhell.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10331] = {"Unverzichtbare Werkzeuge",{"Besorgt den Schmiedehammer von den Lehrlingen von Kirin'Var und bringt ihn zurück zu Lehrling Andrethan in Kirin'Var."}}
D[10332] = {"Meisterschmied Rhonsus",{"Lehrling Andrethan in Kirin'Var möchte, dass Ihr den Geist von Rhonsus, dem Meisterschmied des Dorfes, vernichtet."}}
D[10333] = {"Helft Mama Mauschel",{"Sprecht mit Mama Mauschel im Mittelreichposten in der Biokuppel Mittelreich im Nethersturm."}}
D[10334] = {"Braucht mehr Kuhglocke",{"Sucht Bessy in den Feldern nordöstlich des Kapellenhügels von Kirin'Var im Nethersturm."}}
D[10335] = {"Die Ruinen beobachten",{"Platziert die drei Vermessungsmarkierungen und kehrt dann zu Zephirion in der Sturmsäule im Nethersturm zurück."}}
D[10336] = {"Diener von Culuthas",{"Tötet 10 Hunde von Culuthas und 5 Augen von Culuthas. Kehrt danach zu Netherpirscher Nauthis in der Sturmsäule im Nethersturm zurück."}}
D[10337] = {"Almabtrieb",{"Begleitet Bessy sicher zu ihrem Besitzer Thadell zurück."}}
D[10338] = {"Manaschmiede Duro abschalten",{"Kehrt zur Manaschmiede Duro zurück und besorgt Euch den Zugangskristall von Vorarbeiter Athanel. Benutzt ihn, um die Steuerkonsole von Duro abzuschalten, und meldet Euch danach bei Spionagemeister Thalodien.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10339] = {"Das Astraleum",{"Kommandant Ameer möchte, dass Ihr 5 Auftragsmörder des Astraleums, 5 Stoßtruppsoldaten des Astraleums, 2 Forscher des Astraleums und Hauptmann Zovax tötet und dann den Transponder des Astraleums Zeta aktiviert."}}
D[10340] = {"Trümmerposten",{"Vorpostenkommandant Königstein möchte, dass Ihr mit Schwadronskommandant Dabir'ee sprecht, auf einem Greifen zum Trümmerposten fliegt und Euch bei Runetog Wildhammer meldet."}}
D[10341] = {"Tretet sie, solange sie am Boden liegen",{"Tötet 8 Beschwörer des Sonnenzorns, 6 Jadgschützen des Sonnenzorns und 4 Zenturios des Sonnenzorns. Kehrt zu Magistrix Larynna in Area 52 zurück, wenn Ihr die Aufgabe erledigt habt.","","Das Abschließen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10342] = {"Schieferhautschiefer",{"Sammelt 5 Stück Schieferhautschiefer und bringt sie zu Stiefels in Area 52 im Nethersturm."}}
D[10343] = {"Die unendliche Invasion",{"Sucht die von Manakreaturen heimgesuchte Gegend in Kirin'Var nach einem Manabombenfragment ab und bringt sie zu Zaubererleutnant Morran."}}
D[10344] = {"Schwadronskommandant Greifgar",{"Sprecht mit Schwadronskommandant Greifgar im Trümmerposten."}}
D[10345] = {"Fleisch geworden",{"Benutzt den Anzünder des Protektorats um 12 siechende Leichen zu zerstören. Bringt den Anzünder des Protektorats zu Agent Araxes außerhalb des Zugangsschachts Zeon zurück, wenn Ihr erfolgreich wart."}}
D[10346] = {"Rückkehr zur abyssischen Untiefe",{"Greifnerin Heulwind im Trümmerposten auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört."}}
D[10347] = {"Rückkehr zur abyssischen Untiefe",{"Schwadronskommandant Brack im Häschersturz auf der Höllenfeuerhalbinsel möchte, dass Ihr 20 Peons der Gan'arg, 5 Vorarbeiter der Mo'arg und 5 Teufelskanonen zerstört."}}
D[10348] = {"Neue Möglichkeiten",{"Sammelt 15 Elfenbeinglocken und kehrt dann zu Mehrdad im Mittelreichposten zurück."}}
D[10349] = {"Die Erdbinderin",{"Bringt den Purpurkristallsplitter zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel."}}
D[10350] = {"Behomat",{"Sprecht mit Behomat bei der Händlertreppe in der Exodar."}}
D[10351] = {"Natürliche Heilmittel",{"Benutzt den Samen der Wiederbelebung beim Zirkel des Erdbinders, um das Land um den Kristall herum zu heilen. Kehrt dann zu Erdbinderin Galandria Nachtluft im Posten des Cenarius auf der Höllenfeuerhalbinsel mit Euren Beobachtungen zurück."}}
D[10352] = {"Spendet Wolle"}
D[10353] = {"Arconus der Unersättliche",{"Agent Sechs-Uhr beim Zugangsschacht Zeon im Nethersturm möchte, dass Ihr Arconus den Unersättlichen tötet und dann zu Kommandant Ameer im Wachposten des Protektorats im Nethersturm zurückkehrt."}}
D[10354] = {"Spendet Seide"}
D[10355] = {"Siechendes Fleisch",{"Sammelt 5 Proben einer verdurstenden Hydra und 5 Proben eines siechenden Sumpflords und bringt sie zu Ruam in Telredor."}}
D[10356] = {"Spendet Magiestoff"}
D[10357] = {"Spendet Runenstoff"}
D[10358] = {"Noch mehr Runenstoff"}
D[10359] = {"Spendet Wolle"}
D[10360] = {"Spendet Seide"}
D[10361] = {"Spendet Magiestoff"}
D[10362] = {"Spendet Runenstoff"}
D[10363] = {"Noch mehr Runenstoff"}
D[10364] = {"Caedmos",{"Sprecht mit Caedmos in der Halle des Lichts der Exodar."}}
D[10365] = {"Manaschmiede Ara abschalten",{"Reist zur Manaschmiede Ara und besorgt Euch einen Zugangskristall von Vorarbeiter Azarad. Benutzt ihn, um die Steuerungskonsole von Ara abzuschalten.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10366] = {"Jol",{"Sprecht mit Jol im Sanktum der Verteidiger in der Exodar."}}
D[10367] = {"Ein Verräter unter uns",{"Naladu in den Ruinen von Sha'naar möchte, dass Ihr den Schlüssel von Sha'naar aus einer Hütte in der Nähe besorgt."}}
D[10368] = {"Die Ältesten des Lumpenpacks",{"Befreit Morod den Windtreiber, Akoru den Feuerrufer und Aylaan den Wasserrufer aus den Ruinen von Sha'naar. Kehrt zu Naladu zurück, wenn Ihr diese Aufgabe erledigt habt."}}
D[10369] = {"Arzeths Untergang",{"Benutzt den Ältestenstab des Lumpenpacks gegen Arzeth den Erbarmungslosen und tötet ihn, nachdem er seine Macht verloren hat. Kehrt danach zu Naladu in den Ruinen von Sha'naar zurück."}}
D[10370] = {"Nazgrels Befehl"}
D[10371] = {"Yorus Gerstenbräu",{"Sprecht mit Yorus Gerstenbräu im Gasthaus Seenhain im Rotkammgebirge."}}
D[10372] = {"Eine diskrete Anfrage",{"Sprecht mit Eralan in Tristessa."}}
D[10373] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Kommandant Ashlam Ehrenschlag auf. Sein Stützpunkt befindet sich am Zugwindlager, nördlich des Alteracgebirges."}}
D[10374] = {"Der Ruf zu den Waffen: Die Pestländer!",{"Sucht Hochexekutor Derrington auf. Sein Stützpunk befindet sich am Bollwerk, östlich von Tirisfal und Unterstadt."}}
D[10375] = {"Obsidiankriegsperlen"}
D[10376] = {"Zeichen der Hoffnung"}
D[10377] = {"Keine Angst"}
D[10378] = {"Magiegebrauch"}
D[10379] = {"Berührung der Schwäche"}
D[10380] = {"Ein dunkler Pakt",{"Kaylaan bei Tulumans Landeplatz in Nethersturm möchte, dass Ihr 6 Warptüftler der Gan'arg, 3 Töchter des Schicksals und 3 Warpmeister der Mo'arg tötet.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10381] = {"Nie mehr Aldor",{"Meldet Euch bei Exarch Orelis in Area 52.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10382] = {"Geht zur Front",{"Nehmt einen Greifen zum Ehrenposten und sprecht mit Feldmarschall Brock."}}
D[10383] = {"Dies ist ein Brotkrumen!",{"Sprecht mit Jonathan LeCraft über die Kaninchen."}}
D[10384] = {"Daten der Astralen",{"Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr die Datenzelle des Astraleums besorgt."}}
D[10385] = {"Hirnschadengefahr = hoch",{"Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr 15 Melderdaten des Astraleums besorgt."}}
D[10386] = {"Der Teufelshäschertöter",{"Sprecht mit Oberanführer Hun Stümmelfaust."}}
D[10387] = {"Der Teufelshäschertöter",{"Sprecht mit Oberanführer Hun Stümmelfaust."}}
D[10388] = {"Rückkehr nach Thrallmar",{"Kehrt nach Thrallmar zurück und sprecht mit Nazgrel."}}
D[10389] = {"Das Leid und die Dunkelheit",{"Magister Blutfalke möchte, dass Ihr 10 Terrorbestien bei den Teichen von Aggonar tötet."}}
D[10390] = {"Konstruktionslager: Mageddon",{"Nazgrel in Thrallmar möchte, dass Ihr das Konstruktionslager: Mageddon angreift, 10 Diener der Gan'arg tötet und mit Schmiedebestie Sägeklinges Kopf zurückkehrt."}}
D[10391] = {"Kanonen des Zorns",{"Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Nazgrel in Thrallmar zurück."}}
D[10392] = {"Die Schwelle zum Abgrund",{"Tötet Arix'Amal und nehmt Euch den Torschlüssel der Brennenden Legion. Benutzt den Schlüssel bei der Rune der Bosheit und kehrt danach zu Nazgrel in Thrallmar zurück."}}
D[10393] = {"Boshafte Pläne",{"Bringt den Schriftwechsel der Legion zu Magister Blutfalke in Thrallmar."}}
D[10394] = {"Unterbrechung beim Konstruktionslager: Mageddon",{"Tötet 10 Diener der Gan'arg und Schmiedebestie Sägeklinge im Konstruktionslager: Mageddon und kehrt danach zu Feldmarschall Brock beim Ehrenposten zurück."}}
D[10395] = {"Der dunkle Schriftwechsel",{"Bringt den Schriftwechsel zu Warpseher Kryv in der Haupthalle der Ehrenfeste."}}
D[10396] = {"Der Feind meines Feindes...",{"Zerstört 3 Teufelskanonen V1 im Konstruktionslager: Zorn und kehrt dann zu Feldmarschall Brock beim Ehrenposten zurück."}}
D[10397] = {"Invasionspunkt: Vernichter",{"Tötet Arix'Amal. Nehmt den Torschlüssel der Brennenden Legion und benutzt ihn bei der Rune der Bosheit."}}
D[10398] = {"Rückkehr zur Ehrenfeste"}
D[10399] = {"Das Herz der Dunkelheit",{"Tötet 10 Terrorbestien bei den Teichen von Aggonar und kehrt dann zu Warpseher Kryv in der Haupthalle der Ehrenfeste zurück."}}
D[10400] = {"Oberanführer",{"Tötet Arazzius den Grausamen bei den Teichen von Aggonar und kehrt danach zu Truppenkommandant Danath Trollbann in der Ehrenfeste zurück."}}
D[10401] = {"Mission: Beendet alles, seid alles"}
D[10403] = {"Naladu",{"Sucht Naladu in den Ruinen von Sha'naar."}}
D[10404] = {"Gegen die Legion",{"Exarch Orelis in Area 52 möchte, dass Ihr zur Konstruktionsbasis: Vergessenheit und zur Konstruktionsbasis: Gehenna geht und 12 Feuerfäuste der Gan'arg, 6 Konstruktionsherren der Gan'arg und 6 Zornschaffer tötet.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10405] = {"S-A-B-O-T-A-G-E",{"Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr eine vorbereitete Bandage des Astraleums besorgt."}}
D[10406] = {"Die Nachricht überbringen",{"Das Bild von Kommandant Ameer bei dem Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Demolierer des Protektorats zur Energieleitung der Manaschmiede Ultris begleitet und ihn beschützt, während er die Leitung sabotiert."}}
D[10407] = {"Socrethars Schatten",{"Anachoret Karja in Area 52 möchte, dass Ihr die erste Hälfte von Socrethars Stein von Konstruktionsmeister Morug in der Konstruktionsbasis: Vergessenheit und die zweite Hälfte des Steins von Konstruktionsmeister Silroth in der Konstruktionsbasis: Gehenna besorgt.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10408] = {"Nexuskönig Salhadaar",{"Das Bild von Kommandant Ameer beim Transponder des Astraleums Zeta im Stützpunkt des Astraleums möchte, dass Ihr den Störer des Protektorats benutzt, um Salhadaar Kraftfelder zu senken und Nexuskönig Salhadaar zu vernichten."}}
D[10409] = {"Todesstoß für die Legion",{"Hohepriesterin Ishanah möchte, dass Ihr zum Transporter der Legion am nordwestlichsten Ende des Nethersturms geht und Euch zu Socrethars Sitz teleportiert. Wenn Ihr dort seid, besiegt Socrethar.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10410] = {"Ishanahs Hilfe",{"Bringt Socrethars Teleportationsstein zu Hohepriesterin Ishanah beim Schrein des endlosen Lichts auf der Aldorhöhe in Shattrath.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10411] = {"Elektroschock!",{"Forscher Navuud im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 30 Leerenabschaumkugeln und 30 Sickerschlickkugeln zerstört."}}
D[10412] = {"Siegel der Feuerschwingen",{"Magistrix Fyalenn in Shattrath möchte, dass Ihr ihr 10 Siegel der Feuerschwingen bringt.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10413] = {"Die Schrecken der Verschmutzung",{"Bringt die Phiole mit Leerenschreckensschlamm zu Forscher Navuud im Wachposten des Protektorakts im Nethersturm."}}
D[10414] = {"Einzelne Siegel der Feuerschwingen"}
D[10415] = {"Mehr Siegel der Feuerschwingen"}
D[10416] = {"Bündelung der Macht",{"Voren'thal der Seher in Shattrath möchte, dass Ihr einen arkanen Folianten besorgt.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10417] = {"Führt eine Diagnose durch!",{"Beschafft die Diagnoseergebnisse und bringt sie zu Mehrdad im Mittelreichposten."}}
D[10418] = {"Die Saboteure ausschalten",{"Mehrdad beim Mittelreichposten möchte, dass Ihr 8 Stachelschuppenkrokilisken tötet."}}
D[10419] = {"Arkane Folianten"}
D[10420] = {"Ein reinigendes Licht",{"Bringt eine Ladung teuflische Waffen zu Ishanah in Shattrath.","","Das Abschließen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10421] = {"Teuflische Waffen"}
D[10422] = {"Hauptmann Tyralius",{"Fleischtreiber Viridius im Wachposten des Protektorats im Nethersturm möchte, dass Ihr Hauptmann Tyralius findet und befreit."}}
D[10423] = {"Zur Sturmsäule",{"Sprecht mit Ghabar in der Sturmsäule im Nethersturm."}}
D[10424] = {"Diagnose: kritisch",{"Benutzt das Diagnosegerät in der Nähe des Generators der Biokuppel Sutheron und bringt die Diagnoseergebnisse zu Ghabar in der Sturmsäule zurück."}}
D[10425] = {"Ausbruch aus dem Stützpunkt",{"Begleitet den gefangenen Vorposten des Protektorats zurück zum Wachposten des Protektorats im Nethersturm."}}
D[10426] = {"Flora der Biokuppel",{"Benutzt den Energiefeldmodulator bei den Farahlonpeitschern. Beobachtet die Ergebnisse und meldet Euch bei Aurine Mondflamm in der Sturmsäule zurück, wenn Ihr 10 Tests durchgeführt habt."}}
D[10427] = {"Fauna der Biokuppel",{"Markiert 12 Talbuks für Aurine Mondflamm in der Sturmsäule. Ihr könnt mit dem Talbukmarkierer sowohl Talbukböcke als auch Talbukkühe markieren."}}
D[10428] = {"Der vermisste Fischer",{"Sucht Cowlen bei den südöstlichen Docks der Silbermythosinsel vor der Küste der Azurmythosinsel."}}
D[10429] = {"Wenn die Natur zu weit geht",{"Aurine Mondflamm in der Sturmsäule möchte, dass Ihr ihr ein titanisches Hydraherz bringt."}}
D[10430] = {"Den Prototyp testen",{"Bringt das Testreparaturgerät zu Tashar in der Biokuppel Fernfeld im Nethersturm."}}
D[10431] = {"Hilfe von außen",{"Geht zu Tulumans Landeplatz, nördlich von Area 52, und sprecht mit Kaylaan.","","Das Ausführen von Quests für die Aldor führt zu einer Verringerung Eures Rufs bei den Sehern."}}
D[10432] = {"Eindeutige Beweise",{"Besorgt Euch 8 Befehle von Kael'thas von den Dämonen bei der Manaschmiede Ara und bringt sie zu Spionagemeister Thalodien in Area 52.","","Das Ausführen von Quests für die Seher führt zu einer Verringerung Eures Rufs bei den Aldor."}}
D[10433] = {"Den Schein wahren",{"Bringt 10 Reißzahnpelze zu Shauly Pore im Mittelreichposten."}}
D[10434] = {"Das dynamische Duo",{"Sprecht mit Audi der Nadel auf der Sturmsäule im Nethersturm."}}
D[10435] = {"Die Waren zurückholen",{"Audi die Nadel bei der Sturmsäule möchte, dass Ihr 10 Kuppelgeneratorsegmente besorgt."}}
D[10436] = {"Freie Bahn!",{"Tashar bei der Biokuppel Fernfeld möchte, dass Ihr 12 Sichelzahnraptoren tötet."}}
D[10437] = {"Anleitung zur Zerstörung",{"Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr 8 Fragmente von Dimensius besorgt."}}
D[10438] = {"Auf netherischen Schwingen",{"Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr den Phasenstörer bei der Leerenleitung auf der Manaschmiede Ultris benutzt. Sendet so viele Störsignale wie möglich aus, um eine komplette Zerstörung zu gewährleisten. Die Entladungen des Phasenstörers werden automatisch das Ziel treffen, solange Ihr nahe genug seid, um ihn zu benutzen.","","Kehrt zu Professor Dabiri zurück, wenn Ihr erfolgreich wart!"}}
D[10439] = {"Dimensius der alles Verschlingende",{"Professor Dabiri im Wachposten des Protektorats im Nethersturm möchte, dass Ihr mit Hauptmann Saeed sprecht, seiner Armee zur Manaschmiede Ultris folgt und Dimensius den alles Verschlingenden tötet!"}}
D[10440] = {"Erfolg!",{"Kehrt zur Sturmsäule zurück und sprecht mit Ghabar im Nethersturm."}}
D[10441] = {"Die Waren unters Volk bringen.",{"Sprecht mit Aurine Mondflamm unten in der Sturmsäule im Nethersturm."}}
D[10442] = {"Dem Posten des Cenarius helfen",{"Falknerin Drenna Flusswind möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet."}}
D[10443] = {"Dem Posten des Cenarius helfen",{"Amaan der Weise möchte, dass Ihr Thiah Rotmähne im Posten des Cenarius auf der Höllenfeuerhalbinsel Eure Dienste anbietet."}}
D[10444] = {"Meldung bei Allerias Posten",{"Jenai Sternwisper möchte, dass Ihr Euch bei Leutnant Meridian in Allerias Posten in den Wäldern von Terokkar meldet."}}
D[10445] = {"Die Phiolen der Ewigkeit",{"Soridormi in den Höhlen der Zeit möchte, dass Ihr die Überreste von Vashjs Phiole von Lady Vashj im Echsenkessel und die Überreste von Kaels Phiole von Kael'thas Sonnenwanderer in der Festung der Stürme besorgt."}}
D[10446] = {"Der finale Code",{"Leutnant Meridian möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Jenai Sternwisper in Allerias Feste in den Wäldern von Terokkar zurück."}}
D[10447] = {"Der finale Code",{"Unteroffizier Chawni möchte, dass Ihr den finalen Code eingebt, um die Manabombe auszulösen. Meldet euch dann bei Tooki in der Steinbrecherfeste in den Wäldern von Terokkar zurück."}}
