D[10668] = {"Gegen die Illidari",{"Altruis der Leidende möchte, dass Ihr Lothros in der Stätte der Illidari im Schattenmondtal tötet."}}
D[10669] = {"Gegen jede Chance",{"Altruis der Leidende möchte, dass Ihr den magieerfüllten Silberspeer bei der Portalsicherung in der Nähe des Sumpflichtsees in den Zangarmarschen verwendet, um Xeleth zu wecken. Kehrt zu Altruis zurück, wenn Ihr den Dämon erlegt habt."}}
D[10670] = {"Träne der Erdenmutter",{"Besorgt die Träne der Erdenmutter von Kriegshetzer O'mrogg und bringt sie zu David Wayne in Waynes Zuflucht."}}
D[10671] = {"Ein Pfund Geschnetzeltes",{"Beschafft Euch 5 Einheiten astralisiertes Fleisch."}}
D[10672] = {"Das ergibt echt keinen Sinn...",{"Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr zu dem Lavastrom in der Nähe der Ruinen von Baa'ri reist und die Arkanosteuereinheit benutzt, um einen Arkanoskorp zu steuern. Schwimmt mit dem Arkanoskorp durch die Lava und markiert 8 große Teufelsfeuerdimetrodonten."}}
D[10673] = {"Teufelsflosse der Große",{"Forscher Tiorus in Schattenmond im Schattenmondtal möchte, dass Ihr Teufelsflosse den Großen tötet und Teufelsflosses Balg beschafft."}}
D[10674] = {"Das Licht der Phantasie einfangen",{"Benutzt die Lichtfalle, um 15 Lichtkugeln der Razaani zu fangen."}}
D[10675] = {"Ein Gnom kennt kein Erbarmen!",{"Beschafft Euch die Seelensammlung."}}
D[10676] = {"Bann der Illidari",{"Wartet, bis David Wayne das Schwert für Euch fertig geschmiedet hat."}}
D[10677] = {"Der zweite Gang...",{"Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr einen überentwickelten Teufelsfeuermuskelmagen besorgt."}}
D[10678] = {"Das Hauptgericht!",{"Gnomus in der Wildhammerfeste im Schattenmondtal möchte, dass Ihr Teufelsflosses Balg besorgt."}}
D[10679] = {"Die Waffe härten",{"Reist zu den Siedenden Teichen in der Nähe des Gipfels der Hand von Gul'dan und härtet die geschmiedete Klinge des Illidaribanns in den Lavabecken. Kehrt dann mit der gehärteten Klinge des Illidaribanns zu David Wayne in Waynes Zuflucht zurück."}}
