D[10711] = {"Testflug: Razaans Landeplatz",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium."}}
D[10712] = {"Testflug: Ruuanwald",{"Sprecht mit Rally Zapschnapper und benutzt das Zephyriumkapazitorium. Lasst auf Eurem Flug die Netherwetterfahne rotieren. Bringt die rotierende Netherwetterfahne zu O'Mally Zapschnapper im ewigen Hain."}}
