D[11375] = {"Gesucht: Murmurs Flüstern",{"Windhändler Zhareem hat Euch darum gebeten, ihm Murmurs Flüstern zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11376] = {"Gesucht: Bösartige Ausbilderinnen",{"Netherpirscher Mah'duun hat Euch damit beauftragt, 3 bösartige Ausbilderinnen zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden."}}
D[11377] = {"Rache ist süß",{"Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs einen Kalirieintopf zu kochen. Kehrt anschließend zu ihm zurück."}}
D[11378] = {"Gesucht: Der Kopf des Epochenjägers",{"Windhändler Zhareem hat Euch darum gebeten, ihm den Kopf des Epochenjägers zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11379] = {"Superheißes Ragout",{"Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs ein Dämonenragout Surprise, zwei Rippchen der Mok'Nathal und eine Knusperschlange zu kochen. Kehrt anschließend zu ihm zurück."}}
D[11380] = {"Manaziös",{"Der Rokk im unteren Viertel von Shattrath möchte, dass Ihr 15 Manabeeren in den Biokuppeln im Nethersturm sammelt."}}
D[11381] = {"Suppe für die Seele",{"Der Rokk im unteren Viertel von Shattrath hat Euch darum gebeten, mithilfe seines Kochtopfs eine spirituelle Suppe zu kochen. Kehrt anschließend zu ihm zurück."}}
D[11382] = {"Gesucht: Aeonus' Stundenglas",{"Windhändler Zhareem hat Euch darum gebeten, ihm Aeonus' Stundenglas zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11383] = {"Gesucht: Fürsten der Zeitenrisse",{"Netherpirscher Mah'duun hat Euch damit beauftragt, 4 Fürsten der Zeitenrisse zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden."}}
D[11384] = {"Gesucht: Warpzweigsplitter",{"Windhändler Zhareem hat Euch darum gebeten, ihm einen Warpzweigsplitter zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11385] = {"Gesucht: Kanalisierer der Sonnensucher",{"Netherpirscher Mah'duun hat Euch damit beauftragt, 6 Kanalisierer der Sonnensucher zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden."}}
D[11386] = {"Gesucht: Pathaleons Projektionsgerät",{"Windhändler Zhareem hat Euch darum gebeten, ihm Pathaleons Projektionsgerät zu beschaffen. Bringt es zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11387] = {"Gesucht: Zerstörer der Sturmschmiede",{"Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Zerstörer der Sturmschmiede zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle vernichtet wurden."}}
D[11388] = {"Gesucht: Horizontiss' Schriftrolle",{"Windhändler Zhareem hat Euch darum gebeten, ihm Horizontiss' Schriftrolle zu beschaffen. Bringt sie zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11389] = {"Gesucht: Schildwachen der Arkatraz",{"Netherpirscher Mah'duun hat Euch damit beauftragt, 5 Schildwachen der Arkatraz zu töten. Kehrt erst zu ihm in das untere Viertel in Shattrath zurück, wenn sie alle dem Tod überantwortet wurden."}}
D[11390] = {"Ich kann fliegen!",{"Der Chefarchäologe des Stählernen Tores möchte, dass Ihr 3 Säcke voller Relikte vom Grund der Ausgrabungsstätte zu einer der Plattformen auf der Nord- oder Südseite des Stählernen Tores befördert.","","Benutzt den Enterhaken der Flugmaschine für diese Aufgabe.","","Meldet Euch bei ihm zurück, sobald Ihr damit fertig seid."}}
D[11391] = {"Patrouille am Stählernen Tor",{"Für die Leute am Stählernen Tor seid Ihr jetzt ein Fliegerass, also will der Chefarchäologe des Stählernen Tores, dass Ihr über der Ausgrabungsstätte patrouilliert und alle Angreifer bekämpft.","","Meldet Euch wieder bei ihm zurück, wenn Ihr Eure Patrouille geflogen habt."}}
D[11392] = {"Ruft den kopflosen Reiter",{"Bringt eine düstere Kerze zur leicht aufgewühlten Erde."}}
D[11393] = {"Wo ist Forscher Jaren?",{"Vorarbeiterin Irena Zasterstein hat Euch gebeten, nach ihrem Verlobten Forscher Jaren zu suchen."}}
D[11394] = {"Und Ihr dachtet, Murlocs würden schlecht riechen!",{"Forscher Jaren hat Euch gebeten, entlang der Küste des Frostmaares wahllos 15 Diener der Geißel zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt."}}
D[11395] = {"Es ist eine Vorrichtung der Geißel",{"Liefert die Vorrichtung der Geißel bei Forscher Jaren an der Küste des Frostmaares ab."}}
D[11396] = {"Die Schilde abschalten",{"Forscher Jaren an der Küste des Frostmaares hat Euch gebeten, 3 geißelnde Kristalle zu zerstören."}}
D[11397] = {"Und Ihr dachtet, Murlocs würden schlecht riechen!",{"Apothekerin Anastasia möchte, dass Ihr entlang der Küste des Frostmaares wahllos 15 Diener der Geißel vernichtet. Kehrt zu ihr zurück, sobald Ihr Eure Aufgabe erledigt habt. Sie befindet sich im Apothekerlager."}}
D[11398] = {"Es ist eine Vorrichtung der Geißel",{"Liefert die Vorrichtung der Geißel bei Apothekerin Anastasia im Apothekerlager ab."}}
D[11399] = {"Die Schilde abschalten",{"Apothekerin Anastasia im Apothekerlager hat Euch gebeten, 3 geißelnde Kristalle zu zerstören."}}
D[11400] = {"Braufestwidder",{"Bringt den Handstempel \"Ehrenbrauer\" zu Pol Bernruh in der Nähe des Eingangs zum Braufestplatz in Dun Morogh."}}
D[11401] = {"Ruft den kopflosen Reiter",{"Bringt eine düstere Kerze zur leicht aufgewühlten Erde."}}
D[11402] = {"Clayton's Quest: Extreme!",{"Seriously, go slay those Evil Squirrels!"}}
D[11403] = {"Endlich frei!",{"Bringt den Folianten von Thomas Thomson zu einer maskierten Waisenmatrone in Durotar, Brill oder beim Falkenplatz."}}
D[11404] = {"Ruft den kopflosen Reiter",{"Bringt eine düstere Kerze zur leicht aufgewühlten Erde."}}
D[11405] = {"Ruft den kopflosen Reiter",{"Bringt eine düstere Kerze zur leicht aufgewühlten Erde."}}
D[11406] = {"Alles muss bereit sein",{"Sprecht mit Gil Grisert in Fort Wildervar."}}
D[11407] = {"Marktschreier für die Brauerei Drohn!",{"Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister."}}
D[11408] = {"Marktschreier für T'chalis Voodoobrauerei!",{"Verbreitet die Kunde vom Braufest bei den Flaggen außerhalb des Auktionshauses im Tal der Stärke, im Tal der Ehre, im Tal der Weisheit und im Tal der Geister."}}
D[11409] = {"Das ist Widderrennen... zumindest fast",{"Ihr habt 4 Minuten, um den Widder zu reiten und dabei 3 verschiedene Geschwindigkeitsstufen für jeweils 8 Sekunden zu halten."}}
D[11410] = {"Der Eine, der entkam",{"Christopher Sloan in Fort Wildervar möchte, dass Ihr Frostflosse besiegt."}}
D[11411] = {"Lager der Winterhufe",{"Sprecht mit Häuptling Aschtotem im Lager der Winterhufe."}}
D[11412] = {"Hin und zurück",{"Holt bei dem Goblin, der auf der Straße in der Nähe von Klingenhügel festsitzt, ein Fässchen ab und bringt es zu Widdermeister Rays Assistenten. Macht das Ganze dreimal, bevor Euer Widder verschwindet."}}
D[11413] = {"Sagte da jemand Souvenir?"}
D[11414] = {"Verrat unter den Brüdern",{"Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.","","Falls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren."}}
D[11415] = {"Verrat unter den Brüdern",{"Ulfang im Bruchwald möchte, dass Ihr die verräterischen Worgs Bjomolf und Varg tötet. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.","","Falls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren."}}
D[11416] = {"Augen des Adlers",{"Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.","","Falls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Behüterin Mondblatt zurückkehren."}}
D[11417] = {"Augen des Adlers",{"Ulfang im Bruchwald möchte, dass Ihr die Augen des Adlers beschafft. Kehrt zu ihm verkleidet zurück, sobald Ihr Eure Aufgabe erfüllt habt.","","Falls Ihr aus irgendeinem Grund die Worgverkleidung verlieren und nach Ersatz suchen solltet, müsstet Ihr zu Weiser Nebelläufer zurückkehren."}}
D[11418] = {"Wir nennen ihn Stahlfeder",{"Spürt Stahlfeder auf, der über Fort Wildervar kreist, und benutzt den gefiederten Glücksbringer, um hinter sein Geheimnis zu kommen. Berichtet Gil Grisert anschließend von dem, was Ihr herausgefunden habt."}}
D[11419] = {"Braufestwidder",{"Bringt den Handstempel \"Ehrenbrauer\" zu Driz Purzelfix in der Nähe des Eingangs zum Braufestplatz in Durotar."}}
D[11420] = {"Der Weg zur Vergeltung",{"Wachoffizier Zorek bei Valgarde am heulenden Fjord möchte, dass Ihr die Harpunenbetriebsanleitung zurückholt."}}
D[11421] = {"Jetzt drehen wir mal richtig auf...",{"Leutnant Eishammer im heulenden Fjord möchte, dass Ihr das Langhaus der Drachenschinder, das Dockhaus der Drachenschinder, das Lager der Drachenschinder und 8 Verteidiger der Drachenschinder vernichtet.","","Bringt den Harpunenkontrollmechanismus zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt."}}
D[11422] = {"Dreizack des Sohnes",{"Alte Eisflosse möchte, dass Ihr Rottkiems Dreizack zurückholt. Er wohnt auf der kleinen Insel an der Küste des Frostmaares."}}
D[11423] = {"Das Vermächtnis des Feindes",{"Reist nach Niffelvar nördlich des Geisterklingenpostens und sucht die Sage des Winterfluchs, die Sage der Val'kyr und die Sage der Zwillinge."}}
D[11424] = {"Schildhügel",{"\"Eisensäge\" Jenny möchte, dass Ihr 5 alte Knochen der Vrykul von den wiederauferstandenen Vrykul beim Schildhügel südlich von Neu-Agamand besorgt."}}
D[11425] = {"Test Quest - Craig",{"Bla, bla."}}
D[11426] = {"Den Mechanismus ausfindig machen",{"Wachoffizier Zorek bei Valgarde am heulenden Fjord möchte, dass Ihr ihm einen Harpunenkontrollmechanismus bringt."}}
D[11427] = {"Trefft Leutnant Eishammer",{"Wachoffizier Zorek möchte, dass Ihr den Harpunenkontrollmechanismus zu Leutnant Eishammer außerhalb von Niffelvar bringt."}}
D[11428] = {"Hüter Welkblatt",{"Lurielle auf der Gefrorenen Lichtung möchte, dass Ihr Hüter Welkblatt tötet."}}
D[11429] = {"Aufstellen und abrocken!",{"Leutnant Eishammer im heulenden Fjord möchte, dass Ihr das Banner der Allianz in Quälheim aufstellt und dieses gegen Angreifer verteidigt.","","Kehrt gemeinsam mit dem Banner zu Leutnant Eishammer zurück, falls Ihr überleben solltet."}}
D[11430] = {"Harpunenmeister Yavus",{"Leutnant Eishammer im heulenden Fjord möchte, dass Ihr Harpunenmeister Yavus in Niffelvar tötet."}}
D[11431] = {"Fangt die wilden Wolpertinger!",{"Der \"Zwerg\" Glodrak Jägerspatz möchte, dass Ihr 5 betäubte Wolpertinger mit dem Wolpertingernetz einfangt. Er hat auch erwähnt, dass Ihr entweder ordentlich betrunken sein oder eine Syntheholbrille tragen müsst, um die Biester sehen zu können."}}
D[11432] = {"Schlafende Riesen",{"Magierleutnant Malister hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich in Westwacht."}}
D[11433] = {"Schlafende Riesen",{"Ahota Weißfrost hat Euch damit beauftragt, 5 schlafende Vrykul zu töten. Kehrt zu ihm zurück, sobald Ihr Eure Aufgabe erledigt habt. Er befindet sich im Lager der Winterhufe."}}
D[11434] = {"Vergessene Schätze",{"Der hübsche Terry im Halunkeneck möchte, dass Ihr ihm 1 Amanivase und 1 Adlerfigurine aus dem Schiffswrack gen Süden holt."}}
D[11436] = {"Gehen wir Harpunenreiten!",{"Katapultiert Euch mithilfe der großen Harpunenkanone der Vrykul nach Valgarde. Erstattet Wachoffizier Zorek Bericht, falls Ihr Erfolg haben solltet."}}
D[11439] = {"Übung bei der Brandwache",{"Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone."}}
D[11440] = {"Übung bei der Brandwache",{"Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der kostümierten Waisenmatrone."}}
D[11441] = {"Braufest!",{"Sprecht mit dem Organisator des Braufests."}}
D[11442] = {"Willkommen auf dem Braufest!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11443] = {"Tauchgang in der Dolchbucht",{"Harold Lagras auf dem Grund der Dolchbucht möchte, dass Ihr ihm 10 Vorratskisten von Valgarde bringt."}}
D[11446] = {"Braufest!",{"Sprecht mit dem Organisator des Braufests."}}
D[11447] = {"Willkommen auf dem Braufest!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11448] = {"Der Außenposten der Forscherliga",{"Liefert McSorfs Bündel bei Stanwad im Außenposten der Forscherliga im heulenden Fjord ab."}}
D[11449] = {"Feuerübung",{"Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone in Brill."}}
D[11450] = {"Feuerübung",{"Löscht 5 Feuer mit Wassereimern und sprecht anschließend mit der maskierten Waisenmatrone beim Falkenplatz."}}
D[11451] = {"Alicias Gedicht",{"Man hat Euch gebeten, Alicias Gedicht zu Caylee Dak in Shattrath in der Scherbenwelt zu bringen."}}
D[11452] = {"Der schlummernde König",{"Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt nach Westwacht zurück, falls Euch dies gelingen sollte, und setzt Hauptmann Adams über Euren Erfolg in Kenntnis."}}
D[11453] = {"Der schlummernde König",{"Besiegt Königin Angerboda und haltet das Ritual, mit dem König Ymiron beschwört werden soll, auf. Kehrt zum Lager der Winterhufe zurück, falls Euch dies gelingen sollte, und berichtet Häuptling Aschtotem über Euren Erfolg."}}
D[11454] = {"Findet die Saboteure",{"Sucht nach Coren Düsterbräu im Grimmigen Säufer in den Schwarzfelstiefen."}}
D[11455] = {"Der Duft des Goldes",{"Der hübsche Terry im Halunkeneck im heulenden Fjord möchte, dass Ihr 4 Einheiten Bärenmoschus von den tollwütigen Braunbären in der Gegend besorgt."}}
D[11456] = {"Den Überlebenden zu essen geben",{"Urahn Atuik in Kamagua im heulenden Fjord möchte, dass Ihr zur Insel der Speere geht und ihm 6 Stück Fleisch eines Inselschaufelhauers beschafft."}}
D[11457] = {"Kamagua bewaffnen",{"Urahn Atuik möchte, dass Ihr ihm 3 Schimärenhörner beschafft."}}
D[11458] = {"Rache für Iskaal",{"Urahn Atuik möchte, dass Ihr nach Iskaal geht und 8 Sklavenhändler des Nordmeeres niederstreckt. Macht von dem Horn von Kamagua Gebrauch, solltet Ihr Unterstützung benötigen."}}
D[11459] = {"Zeh'gehn sachd",{"Kehrt zum hübschen Terry zurück, um herauszufinden, was Zeh'gehn von Euch will."}}
D[11460] = {"Vertrauen will verdient sein",{"Hidalgo im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr nach einer Fjordlarve sucht und sie an einen der Falken im Käfig zu seinen Füßen verfüttert."}}
D[11461] = {"DEPRECATED"}
D[11464] = {"Spielschulden",{"Taruk im Halunkeneck möchte, dass Ihr die Schulden von \"Silbermond\" Harry eintreibt."}}
D[11465] = {"Die geplünderte Karawane",{"Hidalgo im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr mithilfe des dressierten Steinfalkens 5 Fjordtruthähne einfangt.","","Kehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und bringt den Käfig mit."}}
D[11466] = {"Jack hebt gern' mal einen",{"Taruk im Halunkeneck im heulenden Fjord möchte, dass Ihr Jack Adams' Schulden eintreibt."}}
D[11467] = {"Des toten Mannes Schulden",{"Taruk im Halunkeneck will, dass Ihr auf dem Plateau am nordöstlichen Ende der Insel der Speere gleich nördlich von Iskaal auf die Suche nach dem Schatz des Schwarzen Konrad geht."}}
D[11468] = {"Falke gegen Habicht",{"Hidalgo am Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euren dressierten Steinfalken nutzt, um 10 Fjordhabichte zu erbeuten.","","Kehrt mit dem Käfig zu Hidalgo zurück, wenn Ihr die Aufgabe Abgeschlossen habt."}}
D[11469] = {"Schrubbseife",{"Lukchen Frostbug will, dass Ihr Tran vom fetten Roy besorgt, als Hauptbestandteil ihrer magischen Schrubbseife. Kehrt zu ihr auf das östliche Piratenschiff beim Halunkeneck zurück, wenn Ihr ihn habt."}}
D[11470] = {"Unter dem Vogelvieh gibt es keine Ehre",{"Hidalgo im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr mithilfe Eures dressierten Steinfalkens 8 Eier eines Fjordhabichts sammelt.","","Kehrt zu Hidalgo zurück, sobald Ihr Eure Aufgabe erfüllt habt, und nehmt den Käfig mit."}}
D[11471] = {"Jetzt geht's lo-os",{"Annie Bonn im Halunkeneck möchte, dass Ihr Jonah Sterlings Handfernrohr zu ihr bringt."}}
D[11472] = {"Der Weg zu seinem Herzen...",{"Werft einem Riffbullen schmackhafte Rifffische zu, um ihn zu einer Riffkuh zu führen. Habt Ihr den Zweien verholfen, wahre Liebe zu finden, dann kehrt zu Anuniaq in Kamagua zurück."}}
D[11473] = {"Ein Verräter unter uns",{"Sprecht mit Zeh'gehn im Halunkeneck."}}
D[11474] = {"Ärger am hohen Kliff",{"Sprecht mit Walt."}}
D[11475] = {"Das nötige Werkzeug für den Job",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr seine Bauwerkzeuge beschafft."}}
D[11476] = {"Ein Frosch und ein Messer",{"Besorgt Euch ein glänzendes Messer von \"Silbermond\" Harry und fangt einen Ganovenfrosch. Bringt dann beides zu Zeh'Gehn im Halunkeneck."}}
D[11477] = {"Nicht in meinem Element?",{"Donny in Ivalds Ruine im heulenden Fjord möchte, dass Ihr 10 Eisenrunenzerstörer, 5 Eisenrunenhilfsarbeiter und 2 Eisenrunenweise tötet."}}
D[11478] = {"Außenposten dort drüben...",{"Überbringt Donnys Brief an Stanwad im Außenposten der Forscherliga."}}
D[11479] = {"\"Krähenbein\" Dan",{"Konfrontiert \"Krähenbein\" Dan. Er befindet sich auf einem der Schiffe im Halunkeneck. Sprecht mit dem hübschen Terry, sobald diese Aufgabe erfüllt ist."}}
D[11480] = {"Nummer Zwei kennenlernen",{"Sprecht mit Annie Bonn im Halunkeneck."}}
D[11481] = {"Krise am Sonnenbrunnen",{"Adyen der Lichtwächter auf der Aldorhöhe in Shattrath hat Euch gebeten, zum Sonnenbrunnenplateau zu reisen und dort mit Larethor zu sprechen."}}
D[11482] = {"Pflicht ruft",{"Dathris Sonnensturm auf der Sehertreppe in Shattrath besteht darauf, dass Ihr umgehend nach Azeroth reist und Euch bei Larethor am Sonnenbrunnen meldet."}}
D[11483] = {"Wir können es nachbauen",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr ihm ein großes Fass, ein Seil in Industriestärke und Dunkeleisenblöcke bringt."}}
D[11484] = {"Wir haben die Technik",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr ihm einen makellosen Schaufelhauerbalg und ein Stück Rippenstahl bringt."}}
D[11485] = {"Eisenrunenkonstrukte und du: Raketensprünge",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und dessen Fähigkeit 'Raketensprung' bei Walts Eisenrunengravur ausführt.","","Über das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[11486] = {"Das beste aller Biere"}
D[11487] = {"Das beste aller Biere"}
D[11488] = {"Terrasse der Magister",{"Exarch Larethor beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die Terrasse der Magister absucht und einen Blutelfenspion namens Tyrith findet."}}
D[11489] = {"Eisenrunenkonstrukte und du: Daten sammeln",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Daten sammeln' in der Nähe des Eisenzwergrelikts ausführt.","","Über das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[11490] = {"Der Seher der Seher",{"Tyrith möchte, dass Ihr die Kugel auf dem Balkon auf der Terrasse der Magister benutzt."}}
D[11491] = {"Eisenrunenkonstrukte und du: Täuschung",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die Fähigkeit 'Bluffen' auf Lebronski ausführt, nachdem Ihr über seinen Teppich gestiegen seid.","","Über das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[11492] = {"Nicht totzukriegen",{"Kalecgos hat Euch damit beauftragt, Kael'thas auf der Terrasse der Magister zu bezwingen. Ihr sollt Euch mit Kaels Kopf bei Larethor am Sammelpunkt der Zerschmetterten Sonne treffen."}}
D[11494] = {"Blitzerfüllte Relikte",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und mit der Fähigkeit 'Daten sammeln' 15 Lesungen von Eisenrunendaten durchführt.","","Über das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[11495] = {"Der zarte Knall des Donners",{"Walt im Außenposten der Forscherliga im heulenden Fjord möchte, dass Ihr Euch ins Eisenrunenkonstrukt setzt und die donnernde Höhle in Baelguns Ausgrabungsstätte erkundet.","","Über das Begleiterfenster, könnt Ihr das Konstrukt freigeben, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[11496] = {"Die Barrieren des Sanktums",{"Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und getriebenen Verschlingern verschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche den Osten des Sanktums der Sonnenweiten umgeben."}}
D[11497] = {"Fliegen lernen",{"Sprecht mit Ilsa Trubelbräu in der Wildhammerfeste im Schattenmondtal."}}
D[11498] = {"Fliegen lernen",{"Sprecht mit Olrokk in Schattenmond im Schattenmondtal."}}
D[11499] = {"Gesucht: Der Siegelring von Prinz Kael'thas",{"Windhändler Zhareem hat Euch darum gebeten, ihm den Siegelring von Prinz Kael'thas zu beschaffen. Bringt diesen zu ihm ins untere Viertel in Shattrath, um Eure Belohnung zu erhalten.","","Diese Aufgabe kann nur auf der Terrasse der Magister und nur auf dem Schwierigkeitsgrad 'Heroisch' abgeschlossen werden."}}
D[11500] = {"Gesucht: Schwestern der Qual",{"Netherpirscher Mah'duun möchte, dass Ihr 4 Schwestern der Qual erschlagt. Kehrt zu ihm in das untere Viertel in Shattrath zurück, sobald Ihr sie getötet habt, um das Kopfgeld einzufordern."}}
D[11501] = {"Neues aus dem Osten",{"Sprecht mit Hauptmann Adams in Westwacht."}}
D[11502] = {"Zur Verteidigung von Halaa",{"Besiegt 10 feindliche Spieler in Halaa und kehrt zu Lakoor in Telaar zurück."}}
D[11503] = {"Feinde - alte und neue",{"Besiegt 10 feindliche Spieler in Halaa und kehrt zu Karrtog in Garadar zurück."}}
D[11504] = {"Die Toten stehen auf!",{"Orfus von Kamagua am Uralten Aufzug im heulenden Fjord möchte, dass Ihr nach Fengirs Hinweis, Rodins Hinweis, Isuldofs Hinweis und Windans Hinweis sucht."}}
D[11505] = {"Geister von Auchindoun",{"Helft der Allianz, einen Turm in der Knochenwüste zu sichern."}}
D[11506] = {"Geister von Auchindoun",{"Helft der Horde, einen Turm in der Knochenwüste zu sichern."}}
D[11507] = {"Urahn Atuik und Kamagua",{"Orfus von Kamagua im heulenden Fjord möchte, dass Ihr Orfus' Bündel nach Kamagua zu Urahn Atuik bringt."}}
D[11508] = {"Grezzix Achsenbruch",{"Sprecht mit Grezzix Achsenbruch."}}
D[11509] = {"Sich einen Ruf machen",{"Sprecht mit \"Silbermond\" Harry im Halunkeneck über die verschwundenen Vrykulartefakte."}}
D[11510] = {"\"Bodo von der Hermannsklause\"",{"\"Silbermond\" Harry im Halunkeneck möchte, dass Ihr den Orca \"Bodo von der Hermannsklause\" tötet und den Wahrsagerkristall der Sin'dorei wiederbeschafft."}}
D[11511] = {"Der Stab des Sturmfurors",{"Beschafft den Stab des Sturmfurors und bringt ihn zu Orfus von Kamagua im heulenden Fjord."}}
D[11512] = {"Das gefrorene Herz Isuldofs",{"Beschafft das gefrorene Herz Isuldofs und bringt es zu Orfus von Kamagua im heulenden Fjord."}}
D[11513] = {"Manazellen abfangen",{"Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück."}}
D[11514] = {"Das Sonnenbrunnenportal aufrechterhalten",{"Beschafft 10 eingeschmuggelte Manazellen und kehrt anschließend zu Exarch Nasuun auf der Terrasse des Lichts in Shattrath zurück."}}
D[11515] = {"Blut für Blut",{"Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe des Teufelstrinkers 4 ausgemergelte Getriebene des Teufelsbluts tötet. Um den Teufelstrinker zu speisen, benötigt Ihr das Dämonenblut von Racheherolden, die sich in der Nähe befinden."}}
D[11516] = {"Vernichtet den Durchgang",{"Magistrix Seyla auf Kil'jaedens Thron möchte, dass Ihr mit Hilfe der zischenden Glut ein lebendiges Leuchtfeuer beschwört und damit so lange glühende Höllenfunken in seiner Nähe tötet, bis es zu einem instabilen lebendigen Leuchtfeuer wird. Kehrt anschließend mit letzterem zum Durchgang der Legion zurück und zerstört ihn."}}
D[11517] = {"Meldung an Nasuun",{"Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen."}}
D[11518] = {"Sunwell Daily Portal Flag"}
D[11519] = {"Der verlorene Schild der Aesiriten",{"Sprecht mit Kapitän Ellis an Bord der Gnädigen Schwester."}}
D[11520] = {"Die eigenen Wurzeln entdecken",{"Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt."}}
D[11521] = {"Eure Wurzeln wiederentdecken",{"Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr zur Messerdornhöhe in der Scherbenwelt reist, 5 Messerdornwurzeln sammelt und wieder zu ihr zurückkehrt."}}
D[11523] = {"Fahrt die Barrieren hoch!",{"Hauptmann Theris Morgenheim beim Sammelpunkt der Zerschmetterten Sonne will, dass Ihr 4 Manaüberreste von getriebenen Unholden und Verschlingern beschafft und sie benutzt, um eine der Kristallbarrieren aufzuladen, welche die Gebäude der Sonnenweiten umgeben."}}
D[11524] = {"Unberechenbares Verhalten",{"Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht."}}
D[11525] = {"Weitere Konvertierungen",{"Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht."}}
D[11526] = {"Eine Magistrix wird vermisst",{"Benutzt die erbeutete Schriftrolle der Legion in der Nähe des Portals auf dem Platz der Morgenröte. Findet Magistrix Seyla, sobald Ihr auf der anderen Seite des Portals seid."}}
D[11527] = {"Meuterei auf der Gnädigen",{"Kapitän Ellis an Bord der Gnädigen Schwester im heulenden Fjord möchte, dass Ihr 5 Schießpulverfässer aus dem Frachtraum des Schiffs besorgt."}}
D[11528] = {"Ein Winterhauchgeschenk"}
D[11529] = {"Sorlofs Beute",{"Vernichtet Sorlof mithilfe der Dicken Berta, holt Euch Sorlofs Beute und kehrt mit ihr zu Kapitän Ellis auf der Gnädigen Schwester zurück."}}
D[11530] = {"Der Schild der Aesiriten",{"Bringt den Schild der Aesiriten zu Orfus von Kamagua. Er befindet sich am Uralten Aufzug im heulenden Fjord."}}
D[11531] = {"Seltsames Motorteil",{"Bringt K. Lee Kleinfrey in Telredor das seltsame Motorteil."}}
D[11532] = {"Ablenkungsmanöver an der Todesschneise",{"Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker."}}
D[11533] = {"Die Luftangriffe müssen weitergehen",{"Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker."}}
D[11534] = {"Meldung an Nasuun",{"Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen."}}
D[11535] = {"Vorbereitungen",{"Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, 3 Stück Erz aus ihren Truhen zu stehlen."}}
D[11536] = {"Hört jetzt nicht auf!",{"Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, um 3 Stück Erz aus ihren Truhen zu stehlen."}}
D[11537] = {"Die Schlacht muss weitergehen",{"Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen."}}
D[11538] = {"Die Schlacht um die Waffenkammer der Sonnenweiten",{"Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte oder der Waffenkammer der Sonnenweiten niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen."}}
D[11539] = {"Den Hafen einnehmen",{"Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Schützen der Dämmerklingen niederstreckt."}}
D[11540] = {"Vernichtet die Dämmerklingen",{"Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Bogenschützen der Dämmerklingen niederstreckt."}}
D[11541] = {"Belästigung an der Küste der Grünkiemen",{"Kapitänin Valindria möchte, dass Ihr 10 Grünkiemensklaven befreit und zu ihr zurückkehrt, sobald Ihr damit fertig seid. Sie befindet sich auf der 'Silbermonds Stolz' im Hafen der Sonnenweiten."}}
D[11542] = {"Haltet die Verstärkung auf",{"Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet. Fliegt dann über die Unterstützungsflotte der Dämmerklingen hinweg und benutzt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid."}}
D[11543] = {"Den Feind vom Leibe halten",{"Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet und über die Flotte mit Verstärkungstruppen der Dämmerklingen hinwegfliegt. Benutzt solange Ihr fliegt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid."}}
D[11544] = {"Waffen von Ata'mal",{"Schmiedin Hauthaa möchte, dass Ihr 5 Stück gereinigtes Metall von Ata'mal herstellt. Um dies zu tun, müsst Ihr Waffen von Ata'mal auf ihrem Amboss in der Waffenkammer der Sonnenweiten auf der Insel von Quel'Danas zerlegen."}}
D[11545] = {"Eine milde Gabe",{"Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet."}}
D[11546] = {"Geschäft geöffnet",{"Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr 5 Blutbeeren von den Büschen auf Quel'Danas sammelt."}}
D[11547] = {"Kenne deine Leylinien",{"Astromant Darnarian im Sanktum der Sonnenweiten möchte, dass Ihr den Kristall des Astromanten am Blutkristall, am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt."}}
D[11548] = {"Eure weitere Unterstützung",{"Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet."}}
D[11549] = {"Ein großmütiger Spender",{"Anachoret Kairthos möchte, dass Ihr 1000 Gold spendet, um Anachoretin Ayuri in ihrem Vorhaben zu unterstützen. Wenn Ihr die Aufgabe abschließen solltet, werdet Ihr den Namen \"Sharmon der Zerschmetterten Sonne\" tragen."}}
D[11550] = {"Der Betrüger betritt die Bühne...",{"Meldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas, nördlich von Quel'Thalas.","","Sprecht mit Flugmeistern in Eisenschmiede und Silbermond, sie werden Euch dorthin bringen."}}
D[11551] = {"Agamath, das erste Tor"}
D[11552] = {"Rohendor, das zweite Tor"}
D[11553] = {"Archonisus, das letzte Tor"}
D[11554] = {"Ein Freund an der Front"}
D[11555] = {"Eure Verbündeten wollen Euer Wohl"}
D[11556] = {"Auf dem Schlachtfeld zollt man Euch Respekt"}
D[11557] = {"Alle Kämpfer begegnen Euch mit Ehrfurcht"}
D[11558] = {"Gefährliche Liebschaft",{"Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt."}}
D[11559] = {"Winterflossenhandel",{"Sammelt 5 Winterflossenmuscheln und liefert sie bei Ahlurglgr ab. Dieser befindet sich in der Zuflucht der Winterflossen."}}
D[11560] = {"Oh neeiin, die Kaulquappen!",{"König Mrgl-Mrgl möchte, dass Ihr 20 Kaulquappen der Winterflossen befreit und anschließend zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen."}}
D[11561] = {"Die da!",{"Brglmurgl in der Zuflucht der Winterflossen möchte, dass Ihr insgesamt 15 Murlocs der Winterflossen tötet, egal ob Krieger, Orakel oder Küstenschläger."}}
D[11562] = {"Mein Putzmurloc erpresst mich",{"König Mrgl-Mrgl möchte, dass Ihr mit Mrmrglmr sprecht. Er befindet sich im nordwestlichen Teil der Zuflucht der Winterflossen."}}
D[11563] = {"Grmmurggll Mrllggrl Glrggl!!!",{"Mrmrglmr will, dass Ihr mit Glrggls Kopf zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen."}}
D[11564] = {"Saftiger Orcaeintopf",{"Hackebeil Bmurglbrm hat Euch damit beauftragt, 7 Einheiten saftigen Orcatran zu beschaffen. Bringt sie anschließend zu ihm in die Zuflucht der Winterflossen."}}
D[11565] = {"Das Ersatzkostüm",{"Bringt König Mrgl-Mrgls Ersatzkostüm zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen."}}
D[11566] = {"Ergebt Euch... nicht!",{"König Mrgl-Mrgl in der Zuflucht der Winterflossen möchte, dass Ihr ihm die Klaue von Claximus bringt."}}
D[11567] = {"Die uralte Rüstung der Kvaldir",{"Bergt die uralte Rüstung der Kvaldir und bringt sie zu Orfus von Kamagua im heulenden Fjord."}}
D[11568] = {"Wieder zur Ruhe kommen lassen",{"Verwendet das Bündel mit Vrykulartefakten bei den geplünderten Grabhügeln des Schildhügels und legt das gefrorene Herz Isuldofs, den Schild der Aesiriten, den Stab des Sturmfurors und die uralte Rüstung der Kvaldir wieder zurück.","","Kehrt zu Orfus von Kamagua am Uralten Aufzug zurück, falls Ihr erfolgreich sein solltet."}}
D[11569] = {"Schlüsselmeister Urmgrgl",{"Glrglrglr in den Höhlen der Winterflossen möchte, dass Ihr Urmgrgls Schlüssel beschafft."}}
D[11570] = {"Flucht aus den Höhlen der Winterflossen",{"Eskortiert Lurgglbr, bis er in Sicherheit ist, und überbringt anschließend König Mrgl-Mrgl in der Zuflucht der Winterflossen die guten Neuigkeiten."}}
D[11571] = {"Lernen, wie man kommuniziert",{"König Mrgl-Mrgl hat Euch eine Muschel gegeben, die Ihr bei Verbrühers Überresten benutzen sollt. Kehrt mit der gefüllten Muschel des Königs zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen."}}
D[11572] = {"Rückkehr zu Atuik",{"Überbringt Urahn Atuik in Kamagua die schlechten Nachrichten."}}
D[11573] = {"Orfus der Kamagua",{"Sucht am Uralten Aufzug im heulenden Fjord nach Orfus von Kamagua."}}
D[11574] = {"Zu knapp für meinen Geschmack",{"Endorah möchte, dass Ihr Euch auf das Bernsteinflöz nördlich der Kriegshymnenfeste begebt und ihren Rettern ihren Dank aussprecht."}}
D[11575] = {"Gerade noch rechtzeitig",{"Mücke in der Valianzfeste möchte, dass Ihr Euch auf das Bernsteinflöz im Norden begebt und ihren Rettern ihren Dank aussprecht."}}
D[11576] = {"Die Klamm beobachten: Spaltkliffanomalie",{"Garren vom Bernsteinflöz möchte, dass Ihr das Arkanometer bei der Spaltkliffanomalie benutzt."}}
D[11577] = {"WoW Collector's Edition: - DEM - E - FLAG"}
D[11578] = {"Die \"Fress\"-Quest (123)aa",{"Tötet Koboldgezücht - und zwar 2 davon."}}
D[11579] = {"Die \"Fress\"-Quest (123)aa",{"Tötet Koboldgezücht, und zwar 2 davon."}}
D[11580] = {"Entweiht dieses Feuer!"}
D[11581] = {"Entweiht dieses Feuer!"}
D[11582] = {"Die Klamm beobachten: Die Kluft",{"Garren vom Bernsteinflöz möchte, dass Ihr den Arkanometer bei der Kluftanomalie benutzt und mit den Messungen zu ihm zurückkehrt."}}
D[11583] = {"Ehrt die Flamme"}
D[11584] = {"Ehrt die Flamme"}
D[11585] = {"Höllschreis Wacht",{"Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste."}}
D[11586] = {"Höllschreis Wacht",{"Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste."}}
D[11587] = {"Gefängnisausbruch",{"Bibliothekar Donathan vom Bernsteinflöz möchte, dass Ihr den Beryllmagierjägern auf der Beryllspitze den Beryllkerkerschlüssel abnehmt und ihn dazu verwendet, die eingesperrten Magier aus ihren arkanen Gefängnissen zu befreien."}}
D[11590] = {"Entführung",{"Donathan möchte, dass Ihr den arkanen Binder auf einen verwundeten Beryllzauberer auf der Beryllspitze anwendet und ihn anschließend auf das Bernsteinflöz bringt."}}
D[11591] = {"Meldet Euch bei Stahlkiefers Karawane",{"Findet Grunzer Zornfaust. Er befindet sich bei Stahlkiefers Karawane."}}
D[11592] = {"Wir schlagen zu!",{"Helft Fernläufer Stolzhuf und seinen Räubern des Kriegshymnenklans dabei, den Angriff auf Stahlkiefers Karawane zu überleben, und besiegt den Geist des Truppenkommandanten Stahlkiefer.","","Meldet Euch wieder bei Oberanführer Bor'gorok, falls Ihr erfolgreich sein solltet. Er befindet sich im Außenposten Bor'gorok."}}
D[11593] = {"Die geehrten Toten",{"Grunzer Zornfaust bei Stahlkiefers Karawane möchte, dass Ihr mit Zornfausts Fackel insgesamt 10 tote Karawanenwachen oder -arbeiter in beliebiger Kombination einäschert."}}
D[11594] = {"Lasst sie zur Ruhe kommen",{"Zerstört 20 Taunkageister, also entweder geisterhafte Weise oder wiederauferstandene Fernläufer, und geht anschließend zu Stahlkiefers Karawane und meldet Euch dort bei Grunzer Zornfaust."}}
D[11595] = {"Die Verteidigung der Kriegshymnenfeste",{"Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste."}}
D[11596] = {"Die Verteidigung der Kriegshymnenfeste",{"Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste."}}
D[11597] = {"Die Verteidigung der Kriegshymnenfeste",{"Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste."}}
D[11598] = {"Den Großfelsbruch zurückerobern",{"Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 15 Neruber der Nerub'ar tötet."}}
D[11599] = {"Mein Bruder Thassarian",{"Sucht nach William Allerton im Inneren der Mine von Fernhain."}}
D[11600] = {"Der verstorbene William Allerton",{"Bringt den Einberufungsbescheid zu Leryssa in die Valianzfeste in der boreanischen Tundra."}}
D[11601] = {"Verloren und wiedergefunden",{"Sprecht mit James Diakon im Gasthaus der Valianzfeste."}}
D[11602] = {"Von der Quelle abschneiden",{"Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 10 Eiersäcke der Nerub'ar zerstört."}}
D[11603] = {"In vino veritas",{"Bergt eine Flasche Wein der Kul Tiras aus dem gesunkenen Schiffswrack nordöstlich der Valianzfeste und bringt sie zum alten Paßbrand im Gasthaus der Valianzfeste."}}
D[11604] = {"Ein Deserteur",{"Findet das Gefängnis in der inneren Festung der Valianzfeste und sprecht mit dem Deserteur."}}
D[11605] = {"Die geehrten Ahnen",{"Ältester Atkanok außerhalb des Froststeinbruchs möchte, dass Ihr die Statuen des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret identifiziert."}}
D[11606] = {"Geduld ist eine Tugend, die wir nicht brauchen",{"Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr 15 Kisten mit Munition des Kriegshymnenklans besorgt."}}
D[11607] = {"Verlorene Geister",{"Ältester Atkanok am äußeren Rand des Froststeinbruchs möchte, dass ihr die Geister von 3 Handwerkern von Kaskala und 3 Schamanen von Kaskala befreit."}}
D[11608] = {"Begrabt diese Kakerlaken!",{"Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr mithilfe des Bündels mit Zephyriumsprengsätzen die Schlundlöcher der Nerub'ar zerstört. Diese befinden sich südlich, östlich, westlich und nördlich der Kriegshymnenfeste."}}
D[11609] = {"Die Reste beseitigen",{"Bringt Ältester Atkanok 6 Ritualobjekte der Tuskarr. Er befindet sich außerhalb des Froststeinbruchs."}}
D[11610] = {"Die Ahnen nach Hause führen",{"Ältester Atkanok möchte, dass Ihr die Geister des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret zu ihren Steinmonumenten geleitet."}}
D[11611] = {"Von der Geißel eingenommen",{"Großknecht Mortuus in der Kriegshymnenfeste möchte, dass Ihr 5 Peons des Kriegshymnenklans befreit."}}
D[11612] = {"Den Steinbruch zurückerobern",{"Etaruk möchte, dass Ihr 12 Beryllschatzjäger tötet. Er befindet sich in der Nähe des Eingangs zum Froststeinbruch."}}
D[11613] = {"Karuks Schwur",{"Karuk möchte, dass Ihr 6 Räuber der Skadir und 5 Langbootsmänner der Skadir tötet."}}
D[11614] = {"Schweigen ist Gold",{"Findet Schattenpirscher Luther im Großfelsbruch."}}
D[11615] = {"Geheimnisse der Nerub'ar",{"Bringt Luthers Tagebuch zu Schattenpirscher Barthus in der Kriegshymnenfeste."}}
D[11616] = {"Nachricht an Höllschrei",{"Bringt Barthus' Notiz zu Höllschrei in der Kriegshymnenfeste."}}
D[11617] = {"Ihre Flucht vereiteln",{"Etaruk möchte, dass ihr die nördliche Plattform, die östliche Plattform und die westliche Plattform zerstört. Er befindet sich außerhalb des Froststeinbruchs."}}
D[11618] = {"Verstärkung trifft ein...",{"Macht Schattenpirscher Ickoris ausfindig. Er befindet sich bei den Höfen des Kriegshymnenklans westlich der Kriegshymnenfeste."}}
D[11619] = {"Gamel der Grausame",{"Karuk möchte, dass Ihr Gamel den Grausamen tötet. Er befindet sich am Strand der Peitschennarbe."}}
D[11620] = {"Eines Vaters Wort",{"Geht zum Schrein der Schuppen auf dem Strand der Peitschennarbe und haltet dort nach Veehja Ausschau."}}
D[11621] = {"Leviroths Tafel",{"Kehrt zu Karuk zurück und überbringt ihm die Information, die Ihr auf der Tafel gefunden habt."}}
D[11622] = {"Geheimnisse der Peitschennarbe",{"Sucht in den Ruinen der Peitschennarbe in der boreanischen Tundra nach Veehja und sprecht mit ihr."}}
D[11623] = {"Ein Besuch beim Kurator",{"Etaruk am äußeren Rand des Frostfelssteinbruchs möchte, dass Ihr Kurator Insivius tötet."}}
D[11624] = {"Der Himmel wird es wissen",{"Sprecht mit Imperean in den Ruinen von Eldra'nath."}}
D[11625] = {"Der Dreizack von Naz'jan",{"Veehja möchte, dass Ihr zur nordöstlichsten Ecke der Ruinen der Peitschennarbe geht und nach Ragnar Drakkarlund sucht. Tötet ihn und nehmt ihm den Dreizack von Naz'jan ab."}}
D[11626] = {"Der Abgesandte",{"Sucht nach Leviroth unter einem Eisberg, der gleich nördlich der Ruinen der Peitschennarbe im Wasser treibt. Erschlagt ihn mit dem Dreizack von Naz'jan und kehrt zu Karuk in die Gegend nördlich des Strands der Peitschennarbe zurück."}}
D[11627] = {"Siedepunkt",{"Imperean möchte, dass Ihr Brodler und Neer unterwerft. Kehrt zu ihm zurück, sobald sie sich Euch ergeben haben. Er befindet sich in den Ruinen von Eldra'nath."}}
D[11628] = {"Der Mantel der Geißel",{"Häuptling Orkan in Taunka'le möchte, dass Ihr ihm 5 verseuchte Mammutpelze bringt."}}
D[11629] = {"Kehrt zur Geisterflüsterin zurück",{"Liefert Impereans Urluft bei der Geisterflüsterin Fletschfang im Außenposten Bor'gorok ab."}}
D[11630] = {"Schlechte Erde",{"Bringt 8 Klumpen verseuchte Erde zu Häuptling Orkan in Taunka'le."}}
D[11631] = {"Vision der Luft",{"Vollzieht mithilfe von Impereans Urluft ein Ritual bei Fletschfangs Totem im Außenposten Bor'gorok, um Informationen über Weissager Grimmläufer zu beschaffen.","","Sprecht anschließend mit Geistredner Fletschfang."}}
D[11632] = {"Was der kalte Wind mit sich bringt...",{"Bringt Ith'rix' gehärteten Knochenpanzer zu Hochfürst Saurfang in der Kriegshymnenfeste."}}
D[11633] = {"Dabei sein ist alles",{"Häuptling Orkan in Taunka'le möchte, dass Ihr das magieerfüllte Tuch der Geißel in der Tempelstadt En'kilah überwerft und die Säule des Blutes, die Säule der Pein und die Säule der Fäulnis auskundschaftet."}}
D[11634] = {"Windreitermeister To'bor",{"Meldet Euch bei Windmeister To'bor in der Kriegshymnenfeste."}}
D[11635] = {"Weissager Grimmläufers Geist",{"Sprecht mit dem Geist von Weissager Grimmläufer im Inneren von Magmut."}}
D[11636] = {"Ritt auf dem magischen Teppich",{"Sprecht mit Yanni in der Kriegshymnenfeste, um die sichere Reise zur Küste zu arrangieren. Sprecht mit Vernichter Grek'lor, sobald Ihr bei Garroshs Landeplatz angekommen seid."}}
D[11637] = {"Kaganishu",{"Findet Kaganishus Fetisch und wendet ihn auf die Überreste von Weissager Grimmläufer an.","","Ihr werdet nach Magmut gehen und den Fetisch Weissager Grimmläufers Geist geben müssen."}}
D[11638] = {"Bringt meine Überreste zurück",{"Bringt Weissager Grimmläufers Überreste, die zu Füßen seines Geistes liegen, zur Geisterflüsterin Fletschfang im Außenposten Bor'gorok."}}
D[11639] = {"Rache an Magmut",{"Tötet 10 Schamanen der Magmut, 5 Futterwühler der Magmut, 3 Zermalmer der Magmut und 3 Gefährtinnen von Magmutregar. Kehrt anschließend zu Ortrosh im Außenposten Bor'gorok zurück."}}
D[11640] = {"Worte der Macht",{"Bringt die Rolle von Hohepriester Naferset, die Rolle von Hohepriester Talet-Kha und die Rolle von Hohepriester Andorath zu Häuptling Orkan in Taunka'le."}}
D[11641] = {"Ein mutiger Schlag",{"Erschlagt 15 Ghule der En'kilah und 5 Nekromanten der En'kilah und meldet Euch dann wieder bei Durm Eisbalg. Er befindet sich in Taunka'le."}}
D[11642] = {"Panzer reparieren sich nicht von selbst",{"Sprecht mit Mobu auf Garroshs Landeplatz."}}
D[11643] = {"Mobus pneumatisches Panzertransjigamarick",{"Mobu an der Echoküste in der boreanischen Tundra möchte, dass Ihr sein pneumatisches Panzertransjigamarick beschafft."}}
D[11644] = {"Superstarke Metallplatten!",{"Mobu an der Echoküste in der boreanischen Tundra möchte, dass Ihr 10 superstarke Metallplatten sammelt."}}
D[11645] = {"Dreckige, stinkende Schneebolde!",{"Bringt 10 von Pfiffis Werkzeugen zu Pfiffi Wackelspross. Sie befindet sich bei der Landebahn Kurbelzisch."}}
D[11646] = {"Die boreanische Inquisition",{"Donathan hat Euch befohlen, Bibliothekar Normantis Eure Hilfe anzubieten. Er befindet sich im Magierturm auf dem Bernsteinflöz."}}
D[11647] = {"Die Kessel neutralisieren",{"Die Weise Aeire in Taunka'le möchte, dass Ihr mithilfe ihres Totems den Kessel im Osten, den Kessel in der Mitte und den Kessel im Westen der Tempelstadt En'kilah neutralisiert."}}
D[11648] = {"Überredungskunst",{"Bibliothekar Normantis vom Bernsteinflöz möchte, dass Ihr den Neuralinjektor so lange auf den eingesperrten Beryllzauberer anwendet, bis er den Aufenthaltsort von Lady Evanor verrät."}}
D[11649] = {"Partikel der Wutentbrannten",{"Beschafft 5 Sturmpartikel und bringt sie zu Imperean in den Ruinen von Eldra'nath."}}
D[11650] = {"Nur noch ein paar Kleinigkeiten...",{"Findet Pfiffis Werkzeuge, einen überladenen Kondensatoren und eine Handvoll von Felsnars Kies. Bringt dies alles zu Pfiffi Wackelspross, die sich auf Kurbelzischs Landebahn aufhält."}}
D[11651] = {"Danke vielmals...",{"Sprecht mit Vernichter Grek'lor an der Echoküste."}}
D[11652] = {"Die Ebene von Nasam",{"Tötet mithilfe des Belagerungspanzers der Horde 100 Soldaten der Geißel und rettet 3 verletze Soldaten des Kriegshymnenklans auf der Ebene von Nasam. Außerdem müsst Ihr herausfinden, wer der Anführer des Angriffs der Geißel ist.","","Meldet Euch bei Garrosh Höllschrei in der Kriegshymnenfeste, solltet Ihr Erfolg haben."}}
D[11653] = {"Ha! ... Jetzt seid Ihr nicht mehr so groß!",{"Testet Pfiffis ultrafortschrittlichen prototypischen Verkürzungsblaster an 5 Zermalmern der Magmut oder Gefährtinnen von Magmutregar aus. Kehrt wieder zu Ihr zurück, sobald Ihr das erledigt habt. Sie befindet sich auf der Landebahn Kurbelzisch."}}
D[11654] = {"Die Säule des Blutes",{"Sucht in der Säule des Blutes nach weiteren Informationen über die Phiole mit frischem Blut."}}
D[11655] = {"In den Nebel hinein",{"Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr Kvaldir tötet und 8 Relikte der Tuskarr beschafft."}}
D[11656] = {"Setzt ein Zeichen und verbrennt sie",{"Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr die Tuskarrfackel benutzt und die Schiffe der Kvaldir bei Pal'ea und Garroshs Landeplatz verbrennt. Ihr müsst die folgenden Schiffe verbrennen: Die Schlangenschlund, die Kur Drakkar, die Bors Hammer und die Bors Amboss."}}
D[11657] = {"Fackeln fangen",{"Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11658] = {"Plan B",{"Sammelt 10 Kriegshymnenausrüstungen und ein Kriegshymnenbanner. Bringt sie zurück zu Pfiffi Wackelspross an der Landebahn Kurbelzisch."}}
D[11659] = {"Zerschmettert die Kugeln!",{"Zerstört 5 Blutkugeln und meldet Euch anschließend bei Schneefährtenleser Junek in Taunka'le."}}
D[11660] = {"Horn des uralten Seemanns",{"Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr ihm das Horn des uralten Seemanns bringt."}}
D[11661] = {"Orabus der Steuermann",{"Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr mithilfe des Horns des uralten Seemanns Orabus den Steuermann beschwört. Erschlagt Orabus den Steuermann, sobald er beschworen ist."}}
D[11662] = {"Sucht nach Karuk!",{"Sucht Karuk am Strand der Peitschennarbe auf."}}
D[11663] = {"Geheime Nachrichten teilen",{"Normantis möchte, dass Ihr Euch bei Bibliothekar Donathan auf dem Bernsteinflöz meldet."}}
D[11664] = {"Flucht aus dem Nebel",{"Begleitet Muhtoo die Jüngere und helft ihr, aus dem Nebel herauszukommen. Sprecht mit dem Ältesten Muhtoo, solltet Ihr Muhtoo die Jüngere in Sicherheit gebracht haben."}}
D[11665] = {"Krokilisken in der Stadt",{"Bringt dem alten Barlo ein Krokiliskenbaby. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden."}}
D[11666] = {"Köderbanditen",{"Bringt dem alten Barlo einen schwarzen Stachelflosser. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden."}}
D[11667] = {"Der Eine, der entkam",{"Fangt den größten Matschflosser der Welt und bringt ihn zum alten Barlo. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden."}}
D[11668] = {"Garnelenfangen ist nicht einfach",{"Bringt dem alten Barlo 10 riesige Süßwassergarnelen. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden."}}
D[11669] = {"Teufelsblutfilet",{"Bringt dem alten Barlo einen monströsen Teufelsblutschnapper. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden."}}
D[11670] = {"Es waren die Orcs, ganz ehrlich!",{"Spießt Magmutregars Leiche mit dem Kriegshymnenbanner auf, während Ihr als Orc des Kriegshymnenklans verkleidet seid. Kehrt anschließend zu Pfiffi Wackelspross zurück und bringt die Verkleidung mit. Sie befindet sich auf der Landebahn Kurbelzisch."}}
D[11671] = {"Wettlauf gegen die Zeit",{"Donathan vom Bernsteinflöz hat Euch damit beauftragt, mithilfe des Beryllschilddetonators den Schild auf der Beryllspitze zu zerstören. Danach sollt Ihr Salrand besiegen und ihr den Schlüssel abnehmen, den sie bei sich trägt."}}
D[11672] = {"Eingezogen",{"Trefft Euch mit General Arlos im Inneren der Kaserne in der Valianzfeste."}}
D[11673] = {"Holt mich hier raus!",{"Bringt Bonker Wechselvolt in Sicherheit und meldet Euch bei Kurbelzisch Vollgas auf der Landebahn Kurbelzisch."}}
D[11674] = {"Die Weise Hochmesa wird vermisst",{"Findet die Weise Hochmesa in der Nähe der Höhlen des Todes."}}
D[11675] = {"Ein würdiges Ende",{"Erschlagt 10 verseuchte Magnatauren und kehrt anschließend zur Weisen Hochmesa gleich südlich der Höhlen des Todes zurück."}}
D[11676] = {"Gnadenvolle Freiheit",{"Schattenpirscher Canarius auf den Höfen des Kriegshymnenklans möchte, dass Ihr 5 Gefangene der Geißel befreit."}}
D[11677] = {"Haltet die Seuche auf",{"Die Weise Hochmesa gleich südlich der Höhlen des Todes möchte, dass Ihr Hochmesas reinigende Samen auf den Seuchenkessel in den Höhlen des Todes anwendet, um ihn zu neutralisieren."}}
D[11678] = {"Findet Borstenhorn",{"Sucht in Talramas nach Fernläufer Borstenhorn."}}
D[11679] = {"Den Schlüssel neu schmieden",{"Donathan möchte, dass Ihr mit Surristrasz auf dem Bernsteinflöz sprecht."}}
D[11680] = {"Jemanden unter seine Fittiche nehmen",{"Gebt Kriegsmagier Anzim Salrands Schlüssel, wenn Ihr bereit seid, Evanor zu befreien."}}
D[11681] = {"Evanor retten",{"Anzim vom Bernsteinflöz möchte, dass Ihr gemeinsam mit seinen Kriegsmagiern losfliegt, um Lady Evanor auf der Beryllspitze zu befreien. Danach sollt Ihr Euch bei Ihr im Magierturm auf dem Bernsteinflöz melden."}}
D[11682] = {"Drachengespräche",{"Lady Evanor hat Euch ausgesandt, um mit Surristrasz vom Bernsteinflöz zu sprechen."}}
D[11683] = {"Gefallene Nekropole",{"Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zur Weisen Hochmesa zurück, welche sich gleich südlich der Höhlen des Todes befindet."}}
D[11684] = {"Aufspüren der Schlundlöcher",{"Großvater Mahan in Taunka'le möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt."}}
D[11685] = {"Das Herz der Elemente",{"Bringt 5 Elementarherzen zu Windzähmerin Barah in Taunka'le."}}
D[11686] = {"Die Höfe des Kriegshymnenklans",{"Schattenpirscher Ickoris bei den Höfen des Kriegshymnenklans möchte, dass Ihr die Kornkammer des Kriegshymnenklans, Torps Bauernhof und den Schlachthof des Kriegshymnenklans ausspäht."}}
D[11687] = {"Der Doktor und der Lichfürst",{"Vernichtet Doktor Klingengrinser und Lichfürst Frostwinter und kehrt anschließend zur Weisen Hochmesa zurück. Sie befindet sich gleich südlich der Höhlen des Todes."}}
D[11688] = {"Verdammte, dreckige Schweine",{"Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 10 untote Schweine tötet."}}
D[11689] = {"Schlechte Nachrichten überbringen",{"Sprecht mit Großmutter Taiga in Taunka'le."}}
D[11690] = {"Bringt sie lebend zurück",{"Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 8 infizierte Kodobestien rettet."}}
D[11691] = {"Beschwört Ahune",{"Bringt dieses Magmatotem des Irdenen Rings zum Eisbrocken."}}
D[11692] = {"Bei Bixie einchecken",{"Mordle Zahnrad möchte, dass Ihr Bixie Zangkeuler aufsucht, die sich südlich der Höhlen des Todes befindet."}}
D[11693] = {"Oh, großartig... verseuchte Magnatauren!",{"Tötet 10 verseuchte Magnatauren. Kehrt anschließend zu Bixie Zangkeuler südlich der Höhlen des Todes."}}
D[11694] = {"Irgendetwas geht in diesen Höhlen vor",{"Bixie Zangkeuler möchte, dass Ihr Bixies Desinfektionspuder in den Seuchenkessel in den Höhlen des Todes schüttet, um ihn zu neutralisieren. Bixie schleicht gleich südlich der Höhlen des Todes herum."}}
D[11695] = {"Das Horn des Elementarfurors",{"Tötet Häuptling Burbelgobbel und Häuptling Gurgelboggel, nehmt ihnen die untere und obere Hornhälfte ab und bringt sie zu Windzähmerin Barah in Taunka'le."}}
D[11696] = {"Ahune ist hier!",{"Findet Luma Himmelsmutter in den Sklavenunterkünften."}}
D[11697] = {"Mist, Tinky ist in die Nekropole gelaufen!",{"Sucht Tinky Dochtpfiff im Inneren von Talramas."}}
D[11698] = {"Man kann auch gleich die Geißel auslöschen",{"Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zu Bixie Zangkeuler zurück, welche sich gleich südlich der Höhlen des Todes befindet."}}
D[11699] = {"Bin in diesem verdammten Käfig gefangen... aber nicht mehr lange!",{"Findet einen Motorkernkristall, ein magisches Gyroskop und einen Geißelsteuerungsstein. Liefert die Gegenstände anschließend bei Tinky Dochtpfiff in Talramas ab."}}
D[11700] = {"Lasst es Bixie wissen",{"Sprecht mit Bixie Zangkeuler gleich südlich der Höhlen des Todes."}}
D[11701] = {"Zurück zum Landeplatz",{"Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch in der boreanischen Tundra."}}
D[11702] = {"König Mrgl-Mrgl",{"Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen."}}
D[11703] = {"Gelangt zu Getry",{"Geht zu den Höfen des Kriegshymnenklans und findet Schattenpirscher Getry."}}
D[11704] = {"König Mrgl-Mrgl",{"Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen."}}
D[11705] = {"Törichtes Unterfangen",{"Helft Getry dabei, Varidus den Flenser bei den Höfen des Kriegshymnenklans zu besiegen.","","Falls Ihr erfolgreich sein solltet, erstattet Garrosh Höllschrei Bericht."}}
D[11706] = {"Der Kollaps",{"Windzähmerin Barah in Taunka'le möchte, dass Ihr die nerubischen Schlundlöcher mithilfe des Horns des Elementarfurors zum Einsturz bringt und Fürst Kryxix besiegt."}}
D[11707] = {"Notruf",{"Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch."}}
D[11708] = {"Die Mechagnome",{"Hört Euch Kurbelzisch Vollgas' Bericht an und sucht anschließend Jinky Flügelirre auf der Landebahn Kurbelzisch auf."}}
D[11709] = {"Nork Blutwahns Aufgabe",{"Sprecht mit Aufseher Nork Blutwahn in der Kriegshymnenfeste in der boreanischen Tundra."}}
D[11710] = {"Was ist nur los mit der Transmaterie?",{"Sammelt 15 Ersatzteile von Kurbelzisch und liefert sie an Mordle Zahnrad auf der Landebahn Kurbelzisch."}}
D[11711] = {"Angsthasenlieferung... unter 30 Minuten - ansonsten gratis",{"Bringt den Deserteur der Allianz zur Kreuzung östlich der Kriegshymnenfeste und feuert die Leuchtpistole des Kriegshymnenklans ab, um der Allianz ein Zeichen zu geben.","","Meldet Euch bei Späher Tungok, nachdem die Übergabe des Deserteurs der Allianz erfolgreich abgeschlossen wurde."}}
D[11712] = {"Verflucht nochmal!",{"Jinky Flügelirre bei der Landebahn Kurbelzisch möchte, dass Ihr die fluchrekursive Transmaterieinjektion auf 6 der Mechagnome von Kurbelzisch anwendet."}}
D[11713] = {"Aufspüren der Schlundlöcher",{"Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt."}}
D[11714] = {"Ungeziefer vertilgen",{"Späher Tungok in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 8 Blutsporenernter, 5 Blutsporenfeuerteufel und 2 Blutsporenröster tötet."}}
D[11715] = {"Öl für das Projekt",{"Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mit dem tragbaren Ölsammler 8 Fässer Öl sammelt."}}
D[11716] = {"Die wundersamen Blutsporen",{"Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 10 Blutsporenkarpelle beschafft."}}
D[11717] = {"Pollen von den Motten besorgen",{"Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 5 Pollen von Blutsporenmotten besorgt."}}
D[11718] = {"Ein Bot im Mammutpelz",{"Abner Zischeldrill auf Landebahn Kurbelzisch möchte, dass Ihr ihm 6 dicke Mammutbälge bringt."}}
D[11719] = {"Ein geeignetes Versuchsobjekt",{"Blutmagierin Laurith auf der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr die bestäubte Blutsporenblume verwendet und sie dabei zusehen lasst, was passieren wird."}}
D[11720] = {"Die Invasion von Gammut",{"Sprecht mit Ur Machthorn in der Blutsporenprärie in der boreanischen Tundra."}}
D[11721] = {"Gammutra der Peiniger",{"Erschlagt Gammutra und bringt den Kopf von Gammutra zum Tauren namens 'Ur Machthorn' in der Blutsporenprärie in der boreanischen Tundra."}}
D[11722] = {"Trophäen von Gammut",{"Bringt den Kopf von Gammutra zu Garrosh Höllschrei in der Kriegshymnenfeste."}}
D[11723] = {"Setzt den Schüttlo-Rüttlo ein!",{"Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mithilfe des Schüttlo-Rüttlo 5000 die Tunnel der Neruber zum Einsturz bringt und Fürst Kryxix besiegt."}}
D[11724] = {"Mächtiges Mottenomelett?",{"Bringt das schwere leuchtende Ei zu Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra."}}
D[11725] = {"Auf der Suche nach Trudelflug",{"Macht Iggy \"Trudelflug\" Zinkenwechsel auf den Geysirfeldern ausfindig."}}
D[11726] = {"Ein klein wenig Würze",{"Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr 4 Gewürzbeutel der Gorloc sammelt."}}
D[11727] = {"Eine Zeit für Helden",{"Meldet Euch bei Unteroffizier Hammerberg in der Valianzfeste."}}
D[11728] = {"Lupus pupus",{"Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr ihm 8 Mikrofilmteile bringt."}}
D[11729] = {"Der Ultraüberschallschrauber",{"Liefert den Ultraüberschallschrauber bei Pfiffi Wackelspross ab. Sie befindet sich auf der Landebahn Kurbelzisch."}}
D[11730] = {"Meister und Diener",{"Programmiert mithilfe des Ultraüberschallschrauber 15 Roboter um und kehrt anschließend wieder zu Pfiffi Wackelspross bei der Landebahn Kurbelzisch zurück.","","Achtet darauf, die kaputten Roboter zu plündern, bevor Ihr sie umprogrammiert."}}
D[11731] = {"Fackelwurf",{"Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11732] = {"Entweiht dieses Feuer!"}
D[11733] = {"Reise zum Riss",{"Surristrasz möchte, dass Ihr die Reise nach Kaltarra antretet. Sobald Ihr dort angelangt seid, sollt Ihr mit Erzmagier Berinand sprechen."}}
