D[11788] = {"Eine Schraube lockern",{"Nehmt Twonkie, ED-210, Max Kawummso und den Zermalmer auseinander und meldet Euch anschließend bei Jinky Flügelirre."}}
D[11789] = {"Ein Soldat in Not",{"Sanitäter Hagedorn außerhalb der Valianzfeste möchte, dass Ihr Euch ins Innere des Laderaums der Sturmbrecher begebt und Hagedorns Gegengift aus einer Kiste mit Vorräten für Erste Hilfe beschafft."}}
D[11790] = {"Kultisten unter uns",{"Sprecht mit Kapitän \"Linksdatsch\" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste."}}
D[11791] = {"Benachrichtigt Arlos",{"Sprecht mit General Arlos im inneren Bereich der Valianzfeste."}}
D[11792] = {"Feinde des Lichts",{"Herold Vurenn möchte, dass Ihr die Kultisten der Nekrolyten in der Nähe von Fernhain gen Norden der Valianzfeste bekämpft und ihnen das Kommuniqué der Kultisten abnehmt."}}
D[11793] = {"Weitere Ermittlungen",{"Bringt das Kommuniqué der Kultisten zu Verteidigerin Yaala im Gasthaus der Valianzfeste."}}
D[11794] = {"Die Jagd ist eröffnet",{"Verteidigerin Yalaa möchte, dass Ihr das Okular des Exorzisten an den drei genannten Orten in der Valianzfeste einsetzt, um die Mitglieder des Kults der Verdammten zu enttarnen und zu töten."}}
D[11795] = {"Notfallprotokoll: Sektion 8,2. Absatz C",{"Beschafft 6 Insignien eines Piloten von Kurbelzisch von den Leichnamen der Aufklärungspiloten von Kurbelzisch und bringt sie zurück zu Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen."}}
D[11796] = {"Notfallprotokoll: Sektion 8,2. Paragraph D",{"Iggy \"Trudelflug\" Zinkenwechsel möchte, dass Ihr die Wracks im Osten, Süden und Nordwesten beseitigt."}}
D[11797] = {"Die Belagerung",{"Unteroffizier Hammerberg möchte, dass Ihr 6 Gruftkriecher auf den Sanden von Nasam außerhalb der Valianzfeste tötet."}}
D[11798] = {"Der Ritzelmeister",{"Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Kurbelzisch Vollgas zurück."}}
