D[11864] = {"Eine Missionsrichtlinie"}
D[11865] = {"Des Todes unwürdig",{"Zaza im Lager der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr den Haufen Kunstpelze dazu verwendet, um 8 von Nesingwarys Fallenstellern in die Falle zu locken."}}
D[11866] = {"Die Ohren unserer Feinde",{"Erzdruide Lathorius im Lager der D.E.H.T.A. in der boreanischen Tundra hat gesagt, dass er Euch belohnen wird, wenn Ihr ihm 15 Ohren von Nesingwarys Lakaien bringt."}}
D[11867] = {"Spitzt die Ohren",{"Erzdruide Lathorius im Lager der D.E.H.T.A. in der boreanischen Tundra hat gesagt, dass er Euch belohnen wird, wenn Ihr ihm 15 Ohren von Nesingwarys Lakaien bringt."}}
D[11868] = {"Die Schlächterin wird kommen",{"Zaza im Lager der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr Karen die Schlächterin tötet."}}
D[11869] = {"Glücklich wie eine Turnmuschel",{"Hierophant Cenius im Lager der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr 10 beutegierige Taucher tötet."}}
D[11870] = {"Die verlassenen Weiten",{"Sucht Hierophantin Liandra in den verlassenen Weiten auf."}}
D[11871] = {"Nicht, solange wir Wache halten",{"Hierophantin Liandra in den verlassenen Weiten in der boreanischen Tundra möchte, dass ihr 12 Lieferungen von Tierteilen beschafft."}}
D[11872] = {"Der ruchlose Käpt'n...",{"Erschlagt Käpt'n I. Glu, kehrt anschließend ins Lager der D.E.H.T.A. zurück und sprecht mit Hierophantin Cenius."}}
D[11873] = {"Teilt Kurbelzisch die Neuigkeiten mit",{"Begebt Euch zurück zur Landebahn Kurbelzisch und sprecht mit Kurbelzisch Vollgas."}}
D[11874] = {"Upper Deck Promo - Reitrakete"}
D[11875] = {"Einen Vorteil gewinnen",{"Bringt dem Abgesandten Mordin in Shattrath 8 Netherrückstände."}}
D[11876] = {"Hilfe für die Hilflosen",{"Erzdruide Lathorius im Lager der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr mithilfe des Fallenzerstörers der D.E.H.T.A. 8 Mammutkälber befreit."}}
D[11877] = {"Angriffspläne des Sonnenzorns",{"Lord Torvos in Shattrath möchte, dass Ihr die Angriffspläne des Sonnenzorns beschafft."}}
D[11878] = {"Khu'nok wird's wissen",{"Bringt das verwaiste Mammutkalb zu Khu'nok dem Ungetüm in der boreanischen Tundra."}}
D[11879] = {"Kraa der Mammutvernichter",{"Tötet Kraa den Mammutvernichter und beschafft Euch Kraas Kriegshellebarde. Liefert Kraas Kriegshellebarde bei Erzdruide Lathorius im Lager der D.E.H.T.A. in der boreanischen Tundra ab."}}
D[11880] = {"Die Multiphasen-Vermessung",{"Herold Haronem in Shattrath möchte, dass Ihr die spektrografische Multiphasenbrille benutzt, um 6 Multiphasenmessungen durchzuführen."}}
D[11881] = {"Fertig zum Transport!",{"Helft Jenny dabei, von der Absturzstelle bis nach Taunka'le zu Fezzix Drehgang zu gelangen, ohne dabei ihre ganze Ladung zu verlieren."}}
D[11882] = {"Spiel mit dem Feuer",{"Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte."}}
D[11883] = {"Feuertanzen?",{"Sprecht mit einem Feuertanzmeister in einer der Hauptstädte."}}
D[11884] = {"Ned, Herr der Rhinozerosse",{"Killinger der Höhlenbehüter im Außenposten der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr Nedar, den Herrn der Rhinozerosse, und seinen Begleiter \"Vesperhino\" tötet."}}
D[11885] = {"Feindesblut",{"Findet die Schädelhaufen innerhalb der Beschwörungskreise in Skettis. Beschwört die Nachfahren, indem Ihr 10 zeitverlorene Schriftrollen am Schädelhaufen benutzt und bezwingt sie. Kehrt mit einem Beweisstück von jedem zu Hazzik am Schattenwindlager zurück."}}
D[11886] = {"Ungewöhnliche Aktivitäten",{"Geht zum Lager des Schattenhammers südlich des Eingangs zur Tiefschwarzen Grotte am Zoramstrand im Eschental und sucht nach Briefen des Schattenhammers. Die Kultisten werden sie voraussichtlich bei sich tragen. Benutzt anschließend das totemische Leuchtfeuer, um einen Führer des Irdenen Rings zu beschwören."}}
D[11887] = {"Notrationen",{"Sammelt 7 gnomische Notfallwerkzeugkästen und bringt sie zu Fezzix Drehgang in Taunka'le. Die Kästen findet Ihr bei den Leichen abgestürzter Aufklärungspiloten von Kurbelzisch."}}
D[11888] = {"Reitet nach Taunka'le",{"Sprecht mit Weiser Erde und Himmel in Taunka'le."}}
D[11889] = {"Der Tod lauert in der Luft",{"Unteroffizier Hammerberg möchte, dass Ihr mithilfe des verstärkten Netzes 6 verseuchte Flammenspucker außerhalb der Valianzfeste tötet."}}
D[11890] = {"Was haben sie vor?",{"Untersucht die Gegend um die Pumpstation Kurbelzisch herum. Kehrt anschließend wieder zum Weisen Erde und Himmel in Taunka'le zurück."}}
D[11891] = {"Eine unschuldige Verkleidung",{"Benutzt die Krabbenkugel und spioniert das neue Lager des Schattenhammers aus. Es befindet sich westlich des Eingangs zur Tiefschwarzen Grotte auf dem Zoramstrand im Eschental. Benutzt anschließend das totemische Leuchtfeuer, um den Führer des Irdenen Rings zu beschwören."}}
D[11892] = {"Die Ermordung von Harold Fährten",{"Erzdruide Lathorius im Lager der D.E.H.T.A. in der boreanischen Tundra möchte, dass Ihr Harold Fährten tötet."}}
D[11893] = {"Die Macht der Elemente",{"Dorain Frosthuf in Taunka'le möchte, dass Ihr mithilfe des Totems der Windseele die Energie von 10 Dampfwütern sammelt."}}
D[11894] = {"Zusammenflicken",{"Fezzix Drehgang in Taunka'le möchte, dass Ihr ihm 5 dampfgegerbte Bälge bringt."}}
D[11895] = {"Bezwingt den Sturm",{"Besiegt die Sturmbö und kehrt anschließend zum Weisen Erde und Himmel in Taunka'le zurück."}}
D[11896] = {"Eine Schwäche für Blitze",{"Zerstört 15 verschiedene Robotereinheiten im größeren Teichareal um die Pumpstation Kurbelzisch herum, während sie von der Macht des Sturms geschwächt sind. Ignoriert jedoch die Mechagnome.","","Kehrt anschließend zu Weiser Erde und Himmel in Taunka'le zurück."}}
D[11897] = {"Stopft die Schlundlöcher",{"Unteroffizier Hammerberg möchte, dass Ihr mithilfe des Brandsatzes die Schlundlöcher süd- und nordwestlich der Valianzfeste zum Einsturz bringt."}}
D[11898] = {"Durchbrechen",{"Besiegt Prinz Valanar und seine Leutnants Vanthryn den Erbarmungslosen und Luthion den Grässlichen. Meldet Euch anschließend bei Häuptling Orkan in Taunka'le."}}
D[11899] = {"Seelen der vom Fluch befreiten",{"Fangt mithilfe von Großmutters Seelenfänger 10 Seelen der Mechagnome von Kurbelzisch. Kehrt anschließend zu Großmutter Taiga in Taunka'le zurück, sobald Ihr das erledigt habt."}}
D[11900] = {"Die Zähler ablesen",{"Erzmagier Berinand im Transitusschild möchte, dass Ihr mit den Messwerten seiner Instrumente in Kaltarra zu ihm zurückkehrt."}}
D[11901] = {"Truppen? Welche Truppen?",{"Gerald Grün in Fernhain möchte, dass Ihr euch in die Mine im Norden begebt und herausfindet, was mit der Einsatztruppe, die dorthin geschickt wurde, geschehen ist."}}
D[11902] = {"Schädliche Beweise",{"Kehrt zu Gerald Grün in Fernhain zurück."}}
D[11903] = {"Zeit zu handeln",{"Gerald Grün in Fernhain möchte, dass Ihr 14 verseuchte Aasfresser tötet."}}
D[11904] = {"Die Früchte unserer Arbeit",{"Geht zur Mine in Fernhain, nehmt Hauptmann Jacobs den Wegrollsperrenschlüssel ab und macht den Wagen mit Erz los. Kehrt zu Gerald Grün in Fernhain zurück, sobald Ihr Eure Aufgabe beendet habt."}}
D[11905] = {"Das Unvermeidliche hinauszögern",{"Erzmagier Berinand im Transitusschild möchte, dass Ihr den interdimensionalen Refabrikator in der Nähe des Risses im Nexus benutzt."}}
D[11906] = {"Die Teiche säubern",{"Sammelt 15 Ersatzteile von Kurbelzisch und bringt sie zu Eisenauge in Taunka'le."}}
D[11907] = {"Die Offiziere",{"Besiegt Twonkie, ED-210, Max Kawummso und Molok den Zermalmer und meldet Euch anschließend beim Weisen Erde und Himmel in Taunka'le."}}
D[11908] = {"Referenzmaterial",{"Jeremias Hohning möchte, dass Ihr das Buch \"Felder, Fabriken und Werkstätten\" aus dem brennenden Gebäude neben der Mine in Fernhain holt."}}
D[11909] = {"Besiegt den Ritzelmeister",{"Untersucht das Handbuch des Ritzelmeisters und bringt Mechazods Kopf zu Großmutter Taiga in Taunka'le."}}
D[11910] = {"Geheimnisse der Urtume",{"Erzmagier Berinand im Transitusschild möchte, dass Ihr 3 eiszeitliche Späne und 3 magiegebundene Späne von den Urtumen in Kaltarra besorgt."}}
D[11911] = {"Beschleunigen",{"Erzmagier Berinand im Transitusschild möchte, dass Ihr den Nexus betretet und 5 arkane Späne von den kristallinen Beschützern beschafft."}}
D[11912] = {"Verrückt nach Beeren",{"Bibliothekarin Serrah im Transitusschild möchte, dass Ihr 10 Frostbeeren von den Frostbeerbüschen in Kaltarra besorgt."}}
D[11913] = {"Kein Risiko eingehen",{"Wendy Darren möchte, dass Ihr mithilfe von Wendys Fackel 8 Säcke Korn aus Fernhain verbrennt."}}
D[11914] = {"Das Geheimnis hüten",{"Bibliothekarin Serrah im Transitusschild möchte, dass Ihr arkane Schlangen in der Nähe des Nexus tötet und 5 Nexusmanaessenzen sammelt."}}
D[11915] = {"Spiel mit dem Feuer",{"Sprecht mit einem Feuerschluckmeister in einer der Hauptstädte."}}
D[11916] = {"Höllschreis Champion",{"Geht nach Taunka'le und sucht Häuptling Orkan auf."}}
D[11917] = {"Zurückschlagen"}
D[11918] = {"Grundausbildung",{"Raelorasz im Transitusschild möchte, dass Ihr 10 Spruchwirker von Kaltarra tötet."}}
D[11919] = {"Drachenjagd",{"Raelorasz möchte, dass Ihr mithilfe von Raelorasz' Speer ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild."}}
D[11920] = {"Kultisten unter uns",{"Sprecht mit Kapitän \"Linksdatsch\" Gaffelsegel an Deck der Sturmbrecher in der Valianzfeste."}}
D[11921] = {"Noch einmal Fackeln werfen",{"Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11922] = {"Fackelwurf",{"Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister des Sonnenwendfests."}}
D[11923] = {"Fackeln fangen",{"Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11924] = {"Noch einmal Fackeln fangen",{"Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11925] = {"Noch einmal Fackeln fangen",{"Fangt nacheinander 10 Fackeln und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11926] = {"Noch einmal Fackeln werfen",{"Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister."}}
D[11927] = {"Man munkelt",{"Geht zum Gasthaus in der Valianzfeste und sucht Leryssa auf."}}
D[11928] = {"Fernhain",{"Reist nach Fernhain in der boreanischen Tundra und sprecht mit Gerald Grün."}}
D[11929] = {"Taunka'les Untergang",{"Sprecht mit Mutter Tauranook außerhalb von Taunka'le."}}
D[11930] = {"Quer durch Transborea",{"Eskortiert die Evakuierten aus Taunka'le durch die Transborea bis zu Wartuk Eiskind in der Drachenöde."}}
D[11931] = {"Den Code entziffern",{"Raelorasz im Transitusschild möchte, dass Ihr den azurblauen Kodex von Inquisitor Caleras besorgt und 3 schimmernde Runen seiner Zauberbindern von Kaltarra besorgt."}}
D[11932] = {"Feiglinge und Dummköpfe",{"Sprecht mit Ataika in Kaskala nordöstlich der Valianzfeste."}}
D[11933] = {"Raubt die Flamme der Exodar",{"Bringt die Flamme der Exodar zum Geschichtenerzähler."}}
D[11935] = {"Raubt die Flamme von Silbermond",{"Bringt die Flamme von Silbermond zum Meister der Lehren."}}
D[11936] = {"Einen Plan ausbrüten",{"Raelorasz im Transitusschild möchte, dass Ihr Wyrmkin von Kaltarra erschlagt und mit ihren gefrorenen Äxten 5 Eier von blauen Drachen zertrümmert."}}
D[11937] = {"FLAG - all torch return quests are complete"}
D[11938] = {"Zeit schinden",{"Thassarian in der klagenden Ziggurat in der boreanischen Tundra möchte, dass Ihr 20 Anhänger der Geißel in der Tempelstadt En'kilah erschlagt. Benutzt Lurids Knochen, falls Ihr Unterstützung benötigt."}}
D[11939] = {"?????"}
D[11940] = {"Drachenjagd",{"Raelorasz möchte, dass Ihr mithilfe des mit Blut benetzten Speers ein Nexusdrachenjunges bändigt und es anschließend zu ihm zurückbringt. Er befindet sich im Transitusschild."}}
D[11941] = {"Rätselhaft...",{"Bringt das schillernde Fragment zu Raelorasz im Transitusschild."}}
D[11942] = {"Worte der Macht",{"Thassarian in der klagenden Ziggurat möchte, dass Ihr in die Tempelstadt En'kilah geht und Hohepriester Talet-Khas Rolle aus der Säule der Pein, Hohepriester Nafersets Rolle aus der Säule der Fäulnis und Hohepriester Andoraths Rolle aus der Säule des Blutes besorgt."}}
D[11943] = {"Die Zelle",{"Raelorasz im Transitusschild möchte, dass Ihr General Cerulean die Gefängnisummantelung und Kriegshetzer Goredrak den Energiekern abnehmt."}}
D[11944] = {"Umzingelt!",{"Korporal Venn in Todeswehr möchte, dass Ihr 7 Verteidiger der Ziggurat niederstreckt."}}
D[11945] = {"Auf das Schlimmste gefasst sein",{"Utaik möchte, dass Ihr nach Kaskala geht und 8 Kisten mit Vorräten von Kaskala sammelt."}}
D[11946] = {"Keristrasza",{"Keristrasza möchte, dass Ihr sie ansprecht, sobald Ihr bereit seid, Malygos entgegenzutreten.","","Sprecht mit Raelorasz im Transitusschild, falls Ihr Euer verstärktes arkanes Gefängnis verlieren solltet."}}
D[11947] = {"Zurückschlagen"}
D[11948] = {"Zurückschlagen"}
D[11949] = {"Nicht ohne einen Kampf!",{"Ataika möchte, dass Ihr nach Kaskala geht und dort 12 Räuber der Kvaldir tötet."}}
D[11950] = {"Muahits Weisheit",{"Findet den Ältesten Muahit in Kaskala."}}
D[11951] = {"Köder und Rute",{"Keristrasza hat Euch gebeten, 10 kristallisierte Manasplitter in Kaltarra zu sammeln.","","Falls Ihr Euer verstärktes arkanes Gefängnis verliert, sprecht mit Raelorasz beim Transitusschild."}}
D[11952] = {"Zurückschlagen"}
D[11953] = {"Zurückschlagen",{"Beschwört mithilfe des Eisbrockens in den Kavernen des Schattenhammers im Norden von Silithus den Leutnant des Gletschers, zerstört ihn und kehrt anschließend zum Urahnen des Irdenen Rings zurück. Letzterer befindet sich in einer der Hauptstädte."}}
D[11954] = {"Zurückschlagen",{"Beschwört mithilfe des Eisbrockens in der Nähe des Dunklen Portals auf der Höllenfeuerhalbinsel den eisigen Templer, zerstört ihn und kehrt anschließend zu einem der Urahnen des Irdenen Rings zurück. Letztere befinden sich in den Hauptstädten."}}
D[11955] = {"Ahune der Frostfürst",{"Begebt Euch in die Sklavenunterkünfte im Echsenkessel in den Zangarmarschen und sprecht mit Numa Wolkenschwester."}}
D[11956] = {"Findet das Phylakterium",{"Begebt Euch nach Todeswehr und reitet mit Abenddämmerung zu der Stelle, an der sich Tanathals Phylakterium befindet. Nehmt es an Euch und bringt anschließend zu Thassarian im Inneren der klagenden Ziggurat."}}
D[11957] = {"Saragosas Ende",{"Keristrasza möchte, dass Ihr mithilfe des arkanen Kraftfokus' Saragosa anlockt und sie anschließend besiegt."}}
D[11958] = {"Nichts darf verderben",{"Beschafft von den Wolvar 6 gestohlene Güter von Moa'ki. Bringt sie zum Ältesten Ko'nani im Hafen Moa'ki zurück."}}
D[11959] = {"Tötet Loguhn",{"Zeichnet Euch mit Loguhns Blut und kehrt dann zum Ältesten Ko'nani im Hafen Moa'ki zurück."}}
D[11960] = {"Zukunftsplanungen",{"Sammelt 12 Schneewehenwelpen und liefert sie anschließend bei Fallensteller Mau'i im Hafen Moa'ki ab."}}
D[11961] = {"Die Geister wachen über uns",{"Ältester Muahit in der Bucht des Njordatems möchte, dass Ihr im Wasser nach Iruks Leiche sucht und Issliruks Totem bergt."}}
D[11962] = {"Eine letzte Lieferung",{"Liefert die Kiste mit Erz aus Fernhain zu Hilda Steinschmiede in der Valianzfeste."}}
D[11963] = {"Waffen für Fernhain",{"Kehrt zu Gerald Grün in Fernhain zurück."}}
D[11964] = {"Rauchwerk für die Sommerflämmlinge",{"Der Meister der Lehren möchte, dass Ihr einem Sommerflämmling Rauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Allianz."}}
D[11965] = {"Zu den Waffen!",{"Geht zum Rathaus in Fernhain und lasst die Glocke läuten."}}
D[11966] = {"Rauchwerk für die Festflämmlinge",{"Der Geschichtenerzähler möchte, dass Ihr einem Festflämmling Rauchwerk des Sommers bringt. Die Flämmlinge befinden sich außerhalb jeder Siedlung der Horde."}}
D[11967] = {"Die Roten versammeln",{"Keristrasza hat Euch gebeten, sie zu Raelorasz am Transitusschild zu bringen."}}
D[11968] = {"Das Blatt wendet sich",{"Ältester Muahit möchte, dass Ihr Euch zur Bucht des Njordatems begebt und Heigarr den Schrecklichen erschlagt."}}
D[11969] = {"Die Falle zuschnappen lassen",{"Raelorasz möchte, dass Ihr Raelorasz' Funken beim Signalfeuer in Kaltarra benutzt."}}
D[11970] = {"Der Meister der Sommerlehre",{"Sprecht mit einem Meister der Lehren in einer der Hauptstädte."}}
D[11971] = {"Der Erzähler der Sommergeschichten",{"Sprecht mit einem Geschichtenerzähler in einer der Hauptstädte."}}
D[11972] = {"Splitter von Ahune",{"Bringt die Eissplitter zu Luma Himmelsmutter."}}
D[11973] = {"Kriegsgefangene",{"Raelorasz im Transitusschild möchte, dass Ihr den Nexus betretet und Keristrasza befreit."}}
D[11975] = {"Nun, wenn ich einmal groß bin...",{"Geht mit Eurem Waisenkind Salandria zur Straße der Urahnen in Silbermond, um die Elite Tauren Chieftain zu sehen. Ruft sie zu Euch, falls sie nicht bei Euch ist, wenn Ihr ankommt."}}
D[11976] = {"Eissplitter",{"Bringt die Eissplitter zu Luma Himmelsmutter."}}
D[11977] = {"Ein Tauren unter Taunka",{"Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf."}}
D[11978] = {"Mit offenen Armen empfangen",{"Abgesandte Leuchthuf im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 10 Waffen der Horde beschafft."}}
D[11979] = {"Die Taunka und die Tauren",{"Geht zum Flüchtlingslager von Westwind und sucht Abgesandte Leuchthuf auf."}}
D[11980] = {"Stolz der Horde",{"Blutwache Roh'kill im Flüchtlingslager von Westwind in der Drachenöde möchte, dass Ihr 15 Wegelagerer der Anub'ar niederstreckt."}}
D[11981] = {"Findet Kurun!",{"Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt."}}
D[11982] = {"Es regnet Zerstörung",{"Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr die Arbeiten der Eisenzwerge dadurch stört, dass Ihr Felsbrocken in den freigelegten Bereich von Thor Modan werft."}}
D[11983] = {"Blutschwur der Horde",{"Sprecht mit den Taunka im Flüchtlingslager von Westwind und bringt 5 von ihnen dazu, der Horde Treue zu geloben.","","Bringt den Blutschwur der Horde wieder zur Abgesandten Leuchthuf, sobald Ihr diese Aufgabe abgeschlossen habt."}}
D[11984] = {"Die Käfige vollmachen",{"Samir am Granitquell möchte, dass Ihr mithilfe des Käfigs des Kopfgeldjägers einen Troll einfangt, der von Budd betäubt wurde."}}
D[11985] = {"In die Bresche springen",{"Kurun auf dem Hügel, der Thor Modan überblickt, möchte, dass Ihr den Eisenthan Argrum tötet."}}
D[11986] = {"Das beschädigte Tagebuch",{"Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt Torthen Grabtief im Lager der Westfallbrigade das vervollständigte Buch."}}
D[11988] = {"Der Runenschlüsselstein",{"Bringt Torthen Grabtief im Lager der Westfallbrigade 5 Fragmente des Runenschlüsselsteins."}}
D[11989] = {"Waffenstillstand?",{"Drakuru am Granitquell möchte, dass Ihr in der Nähe seines Käfigs das stumpfe Schnitzmesser benutzt und dann mit ihm sprecht."}}
D[11990] = {"Phiole der Visionen",{"Drakuru am Granitquell möchte, dass Ihr ihm eine magieerfüllte Phiole, einen Wassergraswedel und 3 Dunstblätter bringt."}}
D[11991] = {"Interpretationssache",{"Drakuru möchte, dass Ihr 5 Flaschen gefrorenes Mojo von den Drakkaritrollen in den Ruinen von Drak'Zin beschafft und anschließend das Elixier bei Drakurus Kohlenbecken trinkt."}}
D[11993] = {"Die Runenprophezeiungen",{"Torthen Grabtief im Lager der Westfallbrigade möchte, dass Ihr die drei Runenplatten entziffert."}}
D[11994] = {"Junos Flaggentester"}
D[11995] = {"In Sternenruh wird Eure Anwesenheit benötigt",{"Sprecht mit dem Abbild von Erzmagierin Modera in Sternenruh."}}
D[11996] = {"Eure Anwesenheit wird in Agmars Hammer verlangt",{"Sprecht mit dem Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer."}}
D[11997] = {"Findet Gryan Starkmantel",{"Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade."}}
D[11998] = {"Den Schlag abschwächen",{"Bringt Brugar Steinscher im Lager der Westfallbrigade ein Fässchen mit zum Heulen gutem Fusel."}}
D[11999] = {"Leichenfleddern",{"Findet die Pläne der Mondruhgärten und bringt sie zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer."}}
D[12000] = {"Leichenfleddern",{"Findet die Pläne der Mondruhgärten und bringt sie zu Erzmagierin Modera in Sternenruh."}}
D[12002] = {"Brüder in der Schlacht",{"Tötet 10 Runenschlachtgolems und kehrt zu Brugar Steinscher im Lager der Westfallbrigade zurück."}}
D[12003] = {"Die Suche nach den Tunnels",{"Brugar Steinscher im Lager der Westfallbrigade möchte, dass Ihr das Nordgebäude, das Ostgebäude und das Südgebäude von Thor Modan untersucht."}}
D[12004] = {"Verhindert das Abkommen",{"Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild der Erzmagierin Modera in Sternenruh."}}
D[12005] = {"Verhindert das Abkommen",{"Bringt Windhändler Mu'fahs Überreste und die Schuppen von Goramosh zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer."}}
D[12006] = {"Rächt diese Gräueltat!",{"Tötet insgesamt 15 Magierjäger der Drachenöde, Mondruhpirscher, Zauberer der Sognadel, Fokushexer oder eine Kombination aus mehreren. Kehrt zu Ethenial Mondnacht zurück, sobald Ihr das erledigt habt."}}
D[12007] = {"Opfer müssen erbracht werden",{"Drakuru möchte, dass Ihr ihm das Auge der Propheten zum Kohlenbecken in Zeb'Halak bringt.","","Ihr müsst Zim'bos Mojo einsammeln, um Drakurus Elixier dort benutzen zu können."}}
D[12008] = {"Agmars Hammer",{"Reist nach Agmars Hammer in der Drachenöde und sprecht mit Oberanführer Agmar."}}
D[12009] = {"Tua'keas Krabbenfallen",{"Sammelt 8 von Tua'keas Krabbenfallen ein und bringt sie wieder zu ihm. Er befindet sich im Hafen Moa'ki."}}
D[12010] = {"Das Schicksal Orlonds",{"Findet Feldmesser Orlond innerhalb Thor Modans."}}
D[12011] = {"Anzeichen großen wässrigen Ärgers",{"Informiert Tua'kea im Hafen Moa'ki über die zerstörte Krabbenfalle."}}
D[12012] = {"Den Urahnen benachrichtigen",{"Reist in eine der Hauptstädte und sprecht mit dem Urahnen des Irdenen Rings."}}
D[12013] = {"Weg mit Arkanimus",{"Vernichtet Arkanimus und kehrt zu Ethenial Mondnacht bei den Mondruhgärten zurück."}}
D[12014] = {"Fels in der Brandung?",{"Beschafft den tragbaren Seismographen und führt mit ihm Messungen durch, um die Stabilität in Thor Modan zu untersuchen. Kehrt anschließend zu Brugar Steinscher im Lager der Westfallbrigade zurück."}}
D[12015] = {"Test Quest for Craig",{"Craig Amai at wherever wants you to bring him 5 whatevers."}}
D[12016] = {"Der Köder",{"Besorgt das Fleisch von \"Zwei gewaltige Scheren\" und liefert es bei Tua'kea im Hafen Moa'ki ab."}}
D[12017] = {"Fleisch am Haken",{"Streckt Tu'u'gwar nieder und kehrt anschließend zu Tua'kea im Hafen Moa'ki zurück."}}
D[12019] = {"Letzte Riten",{"Geht zur Tempelstadt En'kilah und sucht die Teleportationskugel unter der schwebenden Geißelzitadelle von Naxxanar. Benutzt sie, um ganz nach oben zu gelangen und helft dort Thassarian."}}
D[12020] = {"Dieses eine Mal, als ich betrunken war...",{"Sprecht mit Boxi Bolzdreher im Braufestlager."}}
D[12021] = {"Ein Brief in die Heimat",{"Bringt den Brief zu Lady Alustra in den östlichen Aasfeldern."}}
D[12022] = {"Haut weg das Zeug!",{"Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Boxi Bolzdreher."}}
D[12023] = {"Noch süßere Rache"}
D[12026] = {"Das beschädigte Tagebuch",{"Sammelt 8 der fehlenden Tagebuchseiten, ergänzt damit das Tagebuch und bringt der Weisen Paluna im Camp Oneqwah das vervollständigte Buch."}}
D[12027] = {"Mr. Floppys gefährliches Abenteuer",{"Helft Emily und Mr. Floppy, den Weg zurück zum Lager der Westfallbrigade zu finden, dann sprecht mit dem Knappen Walter."}}
D[12028] = {"Spirituelle Eingebung",{"Sprecht mit Toalu'u dem Mystiker im Hafen Moa'ki, nachdem Euch die spirituelle Eingebung zuteil wurde."}}
D[12029] = {"Die angesengte Geißel",{"Mack beim Granitquell möchte, dass Ihr seinen Grog benutzt, um 20 ausgemergelte Geißeltrolle in Drak'Tharon zu verbrennen."}}
D[12030] = {"Ältester Mana'loa",{"Sprecht mit der Statue vom Ältesten Mana'loa in Indu'le."}}
D[12031] = {"Freiheit den Verweilenden",{"Erlöst insgesamt 15 Geister von Indu'le, egal ob Fischer, Mystiker oder Krieger, und kehrt anschließend zum Ältesten Mana'loa in Indu'le zurück."}}
D[12032] = {"Gespräche mit den Tiefen",{"Nehmt mithilfe der Perle der Tiefen Verbindung mit der Meeresgöttin Oacha'noa auf und tut, was sie befiehlt.","","Kehrt zu Toalu'u dem Mystiker im Hafen Moa'ki zurück, falls Ihr die Feuerprobe bestehen solltet."}}
D[12033] = {"Nachricht aus dem Westen",{"Lest den Brief von Saurfang und zerstört ihn anschließend.","","Sprecht mit Bote Torvus, sobald Ihr die Aufgabe abgeschlossen habt."}}
D[12034] = {"Der Sieg ist nahe...",{"Sprecht mit Schlachtrufer Juktok in Agmars Hammer."}}
D[12035] = {"Wiederverwertung von Technologie",{"Jeremias Hohning in Fernhain möchte, dass Ihr 5 Erntesammler zerstört und dann Jeremias' Werkzeuge benutzt, um sie neu zu verkabeln."}}
D[12036] = {"Aus den Tiefen von Azjol-Nerub",{"Erforscht die Grube von Narjun und kehrt anschließend mit dem, was Ihr gefunden habt, zu Schlachtrufer Juktok in Agmars Hammer zurück."}}
D[12037] = {"Rettungsaktion",{"Mack beim Granitquell möchte, dass Ihr nach Drak'Tharon geht und herausfindet, was mit Kurzel passiert ist."}}
D[12038] = {"Die angesengte Geißel",{"Mack am Granitquell möchte, dass Ihr seinen Grog nehmt und 30 ausgemergelte Geißeltrolle in Flammen aufgehen lasst."}}
D[12039] = {"Das schwarze Blut von Yogg-Saron",{"Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 10 Proben des schwarzen Blutes von Yogg-Saron beschafft."}}
D[12040] = {"Arthas zum Feinde",{"Kilix der Entwirrer in der Grube von Narjun in der Drachenöde möchte, dass Ihr 6 Unterfürsten der Anub'ar tötet."}}
D[12041] = {"Das verlorene Reich",{"Liefert Kilixs Schlachtplan bei Oberanführer Agmar im östlichen Agmars Hammer ab."}}
D[12042] = {"Das Herz der Uralten",{"Drakuru möchte, dass Ihr zur höchsten Kammer beim Holzfällerposten Blauhimmel geht und dort nach dem Herz der Uralten sucht."}}
D[12043] = {"Verteidigung von Düsenrost",{"Tötet 12 Buddler der Weiten und 1 Zuchtmeister der Weiten, die sich in den Ausgrabungsorten um Galakronds Ruhestätte herum befinden. Kehrt anschließend zu Narf im Düsenrostposten zurück, sobald die Aufgabe erledigt ist."}}
D[12044] = {"Aufstocken",{"Geht zu den Ausgrabungsorten, die sich um Galakronds Ruhestätte herum befinden, sammelt 8 Ladungen Kompositerz und bringt sie anschließend zu Xink im Düsenrostposten."}}
D[12045] = {"Eiskristalle",{"Sammelt 4 Eissplitterklumpen von den Eiselementaren gen Norden und bringt sie zu Zivlix im Düsenrostposten."}}
D[12046] = {"Weiches Hüllenmaterial",{"Sammelt 12 dünne Tierbälge von den Jormungartunnelgräbern oder den Drachenknochenkondoren in der Nähe des Düsenrostpostens und bringt sie anschließend zu Zivlix."}}
D[12047] = {"Etwas, das nicht schmilzt",{"Sucht inmitten der Drachenknochen östlich des Düsenrostpostens nach 12 zersplitterten Knochenstücken."}}
D[12048] = {"Waffen der Geißel",{"Borus Eisenbieger in Agmars Hammer in der Drachenöde möchte, dass Ihr ihm 8 Waffen der Geißel bringt."}}
D[12049] = {"Schwer zu schlucken",{"Kämpft so lange gegen einen bulligen Jormungar östlich des Düsenrostpostens, bis er sein Maul öffnet, um dann eine potente Sprengladung hineinzuwerfen. Sammelt, nachdem er explodiert ist, 6 Stücke verbranntes Jormungarfleisch vom Boden auf und bringt sie zu Xink."}}
D[12050] = {"Holz hacken",{"Ruft mithilfe von Xinks Schreddersteuerung einen Schredder, sobald Ihr das Nistgebiet der Harpyien im Norden erreicht habt. Sammelt 50 Bündel Nutzholz von den Bäumen in der Gegend und kehrt anschließend zu Xink im Düsenrostposten zurück.","","Wendet Euch an Xink im Düsenrostposten, falls Ihr Xinks Schreddersteuerung verlieren solltet, um eine neue zu erhalten."}}
D[12051] = {"Ein paar Federn rascheln lassen",{"Narf im Düsenrostposten möchte, dass Ihr 20 Harpyien nordwestlich des Düsenrostpostens tötet."}}
D[12052] = {"Nimm das, Harpyie!",{"Tötet die Meisterin des Kaltwinds und 15 Kaltwindharpyien in den Bergen nordwestlich des Düsenrostpostens. Kehrt zu Narf zurück, sobald die Aufgabe erledigt ist.","","Sprecht mit Xink im Düsenrostposten, falls Ihr seine Schreddersteuerung benötigen solltet."}}
D[12053] = {"Die Macht der Horde",{"Schlachtrufer Juktok in Agmars Hammer in der Drachenöde möchte, dass Ihr die Schlachtstandarte des Kriegshymnenklans in Eisnebel aufstellt und sie gegen alle Angreifer verteidigt.","","Bringt die Schlachtstandarte des Kriegshymnenklans wieder zurück, wenn Ihr die Aufgabe abgeschlossen habt."}}
D[12054] = {"Das Tagebuch entschlüsseln",{"Bringt der Weisen Paluna in Camp Oneqwah einen Geisteratemzweig."}}
D[12055] = {"Ein seltsames Gerät",{"Bringt Goramoshs seltsames Gerät zum Abbild der Erzmagierin Modera in Sternenruh."}}
D[12056] = {"Zum Tode verurteilt: Hochkultist Zangus",{"Tötet Hochkultist Zangus und bringt den Kopf des Hochkultisten Zangus zu Hauptmann Gort in Agmars Hammer in der Drachenöde."}}
D[12057] = {"Der fleischgebundene Foliant",{"Bringt Hauptmann Gort in Agmars Hammer den fleischgebundenen Folianten."}}
D[12058] = {"Prophezeiungen der Runen",{"Die Weise Paluna im Camp Oneqwah möchte, dass Ihr die drei Runenplatten entziffert."}}
D[12059] = {"Ein seltsames Gerät",{"Bringt Goramoshs seltsames Gerät zum Abbild des Erzmagiers Aethas Sonnenhäscher."}}
D[12060] = {"Projektionen und Pläne",{"Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.","","Kehrt anschließend mit den Informationen zum Abbild der Erzmagierin Modera in Sternenruh zurück."}}
D[12061] = {"Projektionen und Pläne",{"Geht zur Projektion auf der Sognadel über den Mondruhgärten, um sie zu untersuchen.","","Kehrt anschließend mit den Informationen zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück."}}
D[12062] = {"Beleidigt Coren Düsterbräu",{"Geht und fangt Streit mit Coren Düsterbräu an."}}
D[12063] = {"Eisnebels Stärke",{"Sucht in Eisnebel nach Banthok Eisnebel."}}
D[12064] = {"Ketten der Anub'ar",{"Banthok Eisnebel in Eisnebel in der Drachenöde möchte, dass Ihr ihm Anok'ras Schlüsselfragment, Tivax' Schlüsselfragment und Sinoks Schlüsselfragment beschafft."}}
D[12065] = {"Der Fokus am Strand",{"Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.","","Kehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück."}}
D[12066] = {"Der Fokus am Strand",{"Beschafft Euch den Steuerungsring des Leylinienfokus und verwendet ihn, um Informationen vom Leylinienfokus am Glimmerstrand zu erhalten.","","Kehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück."}}
D[12067] = {"Ein Brief an Zuhause",{"Liefert Hauptmann Malins Brief bei Kommandantin Saia Azurstahl in Sternenruh ab."}}
D[12068] = {"Stimmen aus dem Staub",{"Drakuru möchte, dass Ihr in die Ruinen von Drakil'jin geht, dort die Tafeln der Drakkari sammelt und 5 Einheiten heiliges Mojo von den Orakeln und Beschützern der Drakkari sammelt. Geht danach zu Drakurus Kohlenbecken in den Ruinen, benutzt Drakurus Elixier und ruft sein Abbild herbei."}}
D[12069] = {"Die Rückkehr des Oberhäuptlings",{"Befreit Oberanführer Eisnebel mit dem Gefängnisschlüssel von Anub'ar und helft ihm dabei, Unterkönig Anub'et'kan zu besiegen.","","Nehmt Euch ein Bruchstück aus Anub'et'kans Panzer und bringt es zurück zu Oberanführer Agmar in Agmars Hammer in der Drachenöde."}}
D[12070] = {"Neue Kraft für die Truppen",{"Benutzt den Splitter der Erde, um den Grizzlyhügelriesen, die in den Felshügeln kämpfen, neue Kraft einzuflößen. Tötet alle Eisenzwerge, die sich Euch widersetzen, und erstattet dann Kurun auf dem Hügel, der Thor Modan überblickt, Bericht."}}
D[12071] = {"Angriff aus der Luft!",{"Sprecht mit Valnok Windzürner in Agmars Hammer."}}
D[12072] = {"Verdammt sollen die Seuchenbestien sein!",{"Geht nach Eisnebel, benutzt Valnoks Leuchtpistole, um einen Kriegsreiter der Kor'kron zu rufen, setzt auf und tötet mit seiner Hilfe 25 Seuchenbestien der Anub'ar!","","Kehrt anschließend wieder zu Valnok Windzürner in Agmars Hammer zurück, sobald Ihr diese Mission erfüllt habt."}}
D[12073] = {"Das Eisen bearbeiten",{"Tötet 10 beliebige Eisenzwerge in Thor Modan und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück."}}
D[12074] = {"Ein nützlicher Verbündeter",{"Sprecht mit Kurun auf dem Hügel, der Thor Modan überblickt."}}
D[12075] = {"Mageres Angebot",{"Beschafft eine Steinfleischprobe von der Eisriesenleiche am Höhleneingang nördlich von Zort in der Kristallschlucht und kehrt wieder zu ihm zurück, sobald die Aufgabe abgeschlossen ist. Er befindet sich in der Nähe des Zentrums der Schlucht."}}
D[12076] = {"Dreckige Angelegenheit",{"Füllt 2 Phiolen mit ätzendem Speichel, indem Ihr den Schaber auf Euch anwendet. Bringt die Phiolen wieder zu Zort in der Kristallschlucht, wenn Eure Aufgabe abgeschlossen ist."}}
D[12077] = {"Zwei Mal am Tag anwenden",{"Bietet das von Zort zubereitete Elixier Ko'char dem Unbezwingbaren an."}}
D[12078] = {"Wurmcowboy",{"Betretet die Höhlen in der Kristallschlucht und fangt mithilfe stabiler Kisten 3 Exemplare der Jormungarbrut. Achtet jedoch darauf, dass Ihr die Kisten einsteckt, sobald die Jormungarbrut gefangen ist!","","Bringt sie dann zu Zort in der Kristallschlucht."}}
D[12079] = {"Das Revier",{"Ko'char der Unbezwingbare möchte, dass Ihr die Höhlen am nördlichen Ende der Kristallschlucht erforscht und 8 Eiskernjormungarfresser tötet."}}
D[12080] = {"Mächtig großer Wurm",{"Betretet die Eiskernhöhlen und streckt Rüttelbohrer nieder. Benutzt Zorts schützendes Elixier, falls Ihr es noch besitzen solltet, um Euch vor dem ätzenden Speichel der Jormungar zu schützen.","","Kehrt zu Ko'char dem Unbezwingbaren in der Kristallschlucht zurück, wenn die Aufgabe abgeschlossen ist."}}
D[12081] = {"Gavrock",{"Sprecht mit Gavrock in den Ruinen von Tethys."}}
D[12082] = {"Dan-ta dan-ta dan-ta-dah!",{"Eskortiert Harrison aus den Ruinen von Drakil'jin, sprecht dann mit Harkor im gleichnamigen Lager."}}
D[12083] = {"Über dem Waldland",{"Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.","","Kehrt anschließend zum Abbild der Erzmagierin Modera in Sternenruh zurück."}}
D[12084] = {"Über den Waldländern",{"Beschafft Euch das Steuerungsamulett des Leylinienfokus und verwendet es, um Informationen vom Leylinienfokus in den Waldländern von Lothalor zu erhalten.","","Kehrt anschließend zum Abbild des Erzmagiers Aethas Sonnenhäscher bei Agmars Hammer zurück."}}
D[12085] = {"Ein Brief an Zuhause",{"Liefert Leutnant Ta'zinnis Brief bei Oberanführer Agmar in Agmars Hammer ab."}}
D[12086] = {"Karkuts Sohn",{"Geht in Richtung Osten nach Todeswehr jenseits von Unu'pe."}}
D[12087] = {"A Little Help Here? DEPRECATED",{"Corporal Venn at Death's Stand wants you to kill 8 Ziggurat Defenders."}}
D[12088] = {"Thassarian der Todesritter",{"Seht nach Thassarian im Inneren der klagenden Ziggurat nördlich von Todeswehr."}}
D[12089] = {"GESUCHT: Magister Keldonus",{"Erschlagt Magister Keldonus und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück."}}
D[12090] = {"Gesucht: Gigantaur",{"Erschlagt Gigantaur und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück."}}
D[12091] = {"GESUCHT: Schreckensklaue",{"Erschlagt Schreckensklaue und kehrt anschließend zu Hauptmann Gort in Agmars Hammer in der Drachenöde zurück."}}
D[12092] = {"Den Urtumen Kraft verleihen",{"Benutzt die Borke der Wanderer und stärkt damit 3 Urtume von Lothalor. Kehrt anschließend zu Sarendryana in Sternenruh zurück."}}
D[12093] = {"Runen des Zwangs",{"Gavrock in den Ruinen von Tethys möchte, dass Ihr die vier Runen des Zwangs ausschaltet, indem Ihr Aufseher Durval, Aufseher Korgan, Aufseher Lochli und Aufseher Brunon besiegt."}}
D[12094] = {"Latente Macht",{"Ladet den Splitter von Gavrock am ersten, zweiten und dritten uralten Stein auf und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück."}}
D[12095] = {"Zum Drachenjägerposten",{"Sprecht mit Rokhan in Drachensturz in der Drachenöde."}}
D[12096] = {"Stärkt die Urtume",{"Benutzt die Borke der Wanderer, um 3 Urtume von Lothalor zu stärken, und kehrt anschließend zu Erdenwächter Graif in Agmars Hammer zurück."}}
D[12097] = {"Sarathstra, Geißel des Nordens",{"Sprecht mit Rokhan, um den Frostwyrm Sarathstra herbeizurufen.","","Tötet Sarathstra und liefert Sarathstras gefrorenes Herz bei Hauptmann Gort in Agmars Hammer ab."}}
D[12098] = {"Durchsucht Indu'le",{"Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen."}}
D[12099] = {"Endlich frei",{"Befreit mit Gavrocks Runenbrecher 4 runenbeschriebene Riesen und kehrt anschließend zu Gavrock in den Ruinen von Tethys zurück."}}
D[12100] = {"Der Verwesung Einhalt gebieten",{"Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr 15 infizierte Wildtiere tötet und ein verwesungsresistentes Organ beschafft."}}
D[12101] = {"Der gute Doktor...",{"Liefert das verwesungsresistente Organ bei Doktor Sintar Malefius in Agmars Hammer ab."}}
D[12102] = {"Auf der Suche nach dem rubinfarbenen Flieder",{"Doktor Sintar Malefius in Agmars Hammer in der Drachenöde möchte, dass Ihr 1 rubinfarbenen Flieder pflückt."}}
D[12104] = {"Kehrt zu Soar zurück",{"Liefert Sintars Impfstoff bei Soar Falkenzorn in Agmars Hammer ab."}}
D[12105] = {"Abstieg in die Dunkelheit",{"Bringt Mikhails Tagebuch zu Leutnant Dumont bei der Ammertannhütte."}}
D[12106] = {"Durchsucht Indu'le",{"Sucht in Indu'le und im Wasser von Indu'le nach dem Kommandanten der Magierjägertruppen."}}
D[12107] = {"Endstation",{"Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.","","Kehrt danach zum Abbild der Erzmagierin Modera in Sternenruh zurück."}}
D[12108] = {"Mikhails Grab",{"Bringt Mikhails Notiz zum Kartografen Tobias bei der Ammertannhütte."}}
D[12109] = {"Meldet Euch bei Gryan Starkmantel... schon wieder",{"Sprecht mit Hauptmann Gryan Starkmantel im Lager der Westfallbrigade."}}
D[12110] = {"Endstation",{"Benutzt den Steuerungstalisman des Leylinienfokus, um Informationen vom Leylinienfokus unter dem Wasser von Indu'le zu erhalten. Geht anschließend nach Osten zum Azurdrachenschrein, der sich vom Zentrum der Drachenöde aus gesehen weiter südlich befindet, und beobachtet das dortige Vorgehen vom westlichen Felsvorsprung aus.","","Kehrt danach zum Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer zurück."}}
D[12111] = {"Wo die wilden Tiere wohnen",{"Soar Falkenzorn in Agmars Hammer in der Drachenöde möchte, dass Ihr mithilfe der Packung mit Impfstoffen 5 Schneewehenelche und 5 arktische Grizzlys impft."}}
D[12112] = {"Erstarrte Verhandlungen",{"Geht zum Zentrum der Kristallschlucht und sucht Zort auf."}}
D[12113] = {"Ohne Fleisch kein Preis",{"Harkor in Harkors Lager möchte, dass Ihr 10 Stück feinfasriges Worgfleisch von den streunenden Grauheulern und 10 Schaufelhornsteaks von den Langhufgrasfressern beschafft."}}
D[12114] = {"Therapie",{"Harkor in Harkors Lager möchte, dass Ihr 10 Drakkaribeschützer und 10 Drakkariorakel außerhalb der Ruinen von Drakil'jin tötet."}}
D[12115] = {"Koltira und die Sprache des Todes",{"Bringt den fleischgebundenen Folianten zu Koltira Todesweber."}}
D[12116] = {"Man braucht schon einen starken Magen...",{"Kraz in Harkors Lager möchte, dass Ihr Euch in die Ruinen von Drakil'jin begebt und 5 Drakkarikanopen einsammelt."}}
D[12117] = {"Reist zum Hafen Moa'ki",{"Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit dem Ältesten Ko'nani."}}
D[12118] = {"Reist zum Hafen Moa'ki",{"Reist zum Hafen Moa'ki in der Drachenöde und sprecht mit Häuptling Ko'nani."}}
D[12119] = {"Eine Audienz erhalten",{"Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab."}}
D[12120] = {"Schlaghammer von Drak'aguul",{"Kraz in Harkors Lager möchte, dass Ihr Drak'aguul außerhalb der Ruinen von Drakil'jin tötet und mit dem Schlaghammer von Drakil'jin zurückkehrt."}}
D[12121] = {"Wir sehen uns auf der anderen Seite wieder",{"Kraz in Harkors Lager möchte, dass Ihr den Schlaghammer von Drakil'jin auf die Gongs außerhalb der Ruinen von Drakil'jin anwendet. Ihr sollt die Ruinen betreten, sobald Ihr erschlagen wurdet, und mit dem Geist von Gan'jo sprechen, solange Ihr tot seid."}}
D[12122] = {"Eine Audienz erhalten",{"Geht zum Wyrmruhtempel und liefert das Vorstellungsschreiben bei Tariolstrasz ab."}}
D[12123] = {"Die Königin verständigen",{"Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab."}}
D[12124] = {"Die Königin verständigen",{"Liefert Euer Vorstellungsschreiben bei Alexstrasza der Lebensbinderin im Wyrmruhtempel ab."}}
D[12125] = {"Im Dienste des Blutes",{"Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Blutgemme auf die verstörten Bewohner von Indu'le anwendet und sie gefüllt wieder zu ihm zurückbringt."}}
D[12126] = {"Im Dienste des Unheiligen",{"Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die unheilige Gemme auf Fürst Vallenhal anwendet und sie gefüllt wieder zu ihm zurückbringt."}}
D[12127] = {"Im Dienste des Frosts",{"Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Frostgemme auf die Eisklagegeister anwendet und sie gefüllt zu ihm zurückbringt."}}
D[12128] = {"Seht mal nach Raegar",{"Sprecht mit Raegar Brechbraue im Prospektorat."}}
D[12129] = {"Der perfekte Plan",{"Bringt Raegar Brechbraue im Prospektorat die kompletten Blaupausen für einen Kriegsgolem."}}
D[12130] = {"Lieber requirieren als produzieren",{"Bringt 8 Teile eines Kriegsgolems zu Raegar Brechbraue im Prospektorat."}}
D[12131] = {"Wir haben die Macht",{"Bringt Durars Energiezelle und Kathorns Energiezelle zu Raegar Brechbraue im Prospektorat."}}
D[12132] = {"Die Macht zu Zerstören...",{"Koltira Todesweber in Agmars Hammer in der Drachenöde möchte, dass Ihr die Welt der Schatten betretet und 6 schattenhafte Peiniger besiegt.","","Sprecht mit Koltira Todesweber, solltet Ihr die Welt der Schatten wieder betreten müssen."}}
D[12133] = {"Zermatsch den Kürbis",{"Bring das versengte, heilige Symbol zur kostümierten Waisenmatrone."}}
D[12134] = {"Sashas Jagd",{"Sasha möchte, dass Ihr nach Julheim geht und dort 12 Jäger von Julheim tötet."}}
D[12135] = {"\"Lasset die Feuer kommen!\"",{"Die kostümierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht, nachdem der kopflose Reiter diese entzündet hat. Sprecht noch einmal mit der kostümierten Matrone, sobald alle Feuer erloschen sind."}}
D[12136] = {"Der übersetzte Foliant",{"Liefert den übersetzten fleischgebundenen Folianten bei Hauptmann Gort in Agmars Hammer ab."}}
D[12137] = {"Ganz ruhig, Mann",{"Gan'jo möchte, dass Ihr den Schnee des ewigen Schlafes von seiner Kiste in den Ruinen von Drakil'jin nehmt.","","Ihr müsst den Schnee bei den dortigen uralten Drakkarigeistern einsetzen und anschließend die Partikel der Drakkarigeister zurück zu Kraz in Harkors Lager bringen."}}
D[12138] = {"... oder vielleicht auch nicht",{"Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt anschließend zu Raegar Brechbraue im Prospektorat zurück."}}
D[12139] = {"\"Lasset die Feuer kommen!\"",{"Die maskierte Matrone bittet um Eure Hilfe. Sie möchte, dass Ihr alle Feuer im Dorf löscht. Sprecht noch einmal mit der maskierten Matrone, sobald alle Feuer erloschen sind."}}
D[12140] = {"Ein Hoch auf Roanauk!",{"Geht nach Agmars Hammer, sucht Roanauk Eisnebel auf und macht ihn zu einem Mitglied und Anführer der Hordestreitkräfte.","","Kehrt anschließend mit dem Blutschwur der Horde zu Oberanführer Agmar zurück, sobald Ihr diese Aufgabe abgeschlossen habt."}}
D[12141] = {"Eine diplomatische Mission",{"Sprecht mit Karuk am Strand der Peitschennarbe südwestlich der Valianzfeste."}}
D[12142] = {"Seuchenkontrolle",{"Duane bei der Front der 7. Legion möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet."}}
D[12143] = {"Jagd durch die Schluchten",{"Duane möchte, dass Ihr die Schneebolde im Canyon nordöstlich der Front der 7. Legion verfolgt und Euch anschließend um deren Anführer kümmert."}}
D[12144] = {"Seuchenkontrolle",{"Kontokanis in Drachensturz möchte, dass Ihr 10 Schneebolde der Schneeebene und 3 Magnatauren der Drachenöde in den Lagern um den Wyrmruhtempel herum tötet."}}
D[12145] = {"Jagd durch die Schluchten",{"Kontokanis möchte, dass Ihr die Schneebolde in der Schlucht südlich von Drachensturz verfolgt und anschließend ihren Anführer beseitigt."}}
D[12146] = {"Beunruhigende Hinweise",{"Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann."}}
D[12147] = {"Beunruhigende Hinweise",{"Bringt das geschmückte Kriegshorn zum Wyrmruhtempel und sucht dort nach jemandem, der die drohende Gefahr einschätzen kann."}}
D[12148] = {"Einzigartig",{"Findet und tötet Knochenkracher in der Nähe der Schlucht nordwestlich des Azurdrachenschreins. Bringt jegliche Informationen zurück zu Aurastrasza im Wyrmruhtempel."}}
D[12149] = {"Die mächtigen Magnatauren",{"Bringt Blutschmaus, Eisberster und Drachenblut, die sich östlich des Wyrmruhtempels befinden, zur Strecke.","","Blutschmaus wohnt im südöstlichen Bereich der Dracheneiswüste, gleich nördlich des Smaragddrachenschreins. Eisberster patrouilliert an der nördlichen Grenze des Spiegels der Morgenröte. Drachenblut wandert am Fuße der Klippen westlich des Bronzedrachenschreins umher.","","Kehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Magnatauren erschlagen habt."}}
D[12150] = {"Der zurückgezogene Runenmeister",{"Sucht Dregmar Runenbrand auf. Er befindet sich in der Nähe seiner Höhle auf dem Weg zu den Klippen am Spiegel der Morgenröte. Fordert ihn heraus und tut, was notwendig ist, um den Namen des magnataurischen Anführers herauszufinden. Kehrt zu Aurastrasza im Wyrmruhtempel zurück, sobald Ihr die Information erhalten habt."}}
D[12151] = {"Rücksichtsloser Kriegsherr",{"Geht zum Fackelring südlich des Azurdrachenschreins und stoßt in das geschmückte Kriegshorn. Besiegt Grom'thar den Donnerbringer und bringt seinen Kopf zurück zu Aurastrasza im Wyrmruhtempel."}}
D[12152] = {"Jin'arraks Ende",{"Kraz in Harkors Lager möchte, dass Ihr die heilige Drakkariopfergabe aus den Ruinen von Drakil'jin holt und den Drakkariseelenstaub darauf benutzt. Benutzt die beseelte Drakkariopfergabe bei den Gongs außerhalb der Ruinen von Drakil'jin."}}
D[12153] = {"Der Eisenthan und sein Amboss",{"Setzt die Fähigkeiten Eures Kriegsgolems ein, besiegt den Eisenthan Zornhammer und kehrt dann zu Raegar Brechbraue im Prospektorat zurück."}}
D[12154] = {"Stromausfall",{"Benutzt Raegars Sprengstoff, um den Runenkraftkern in Dun Argol zu zerstören, und erstattet anschließen Bericht bei Raegar Brechbraue im Prospektorat."}}
D[12155] = {"Zermatsch den Kürbis",{"Bring das versengte, heilige Symbol zur maskierten Waisenmatrone."}}
D[12156] = {"ABGELEHNT",{"Eskortiert den Gesandten der Allianz ins Dorf Silberwasser. Erstattet Leutnant Dumont bei der Ammertannhütte Bericht, sobald Ihr Eure Aufgabe abgeschlossen habt."}}
D[12157] = {"Der vermisste Kurier",{"Sprecht mit Kurier Lanson in Sternenruh in der Drachenöde."}}
D[12158] = {"Hohlsteinmine",{"Sucht nach Hinweisen in der Hohlsteinmine, nordwestlich vom Lager der Westfallbrigade."}}
D[12159] = {"Seelenunfrieden",{"Petrov bei der Hohlsteinmine möchte, dass Ihr mit der Minenarbeiterlaterne die Leichen von 8 Minenarbeitern der Hohlsteinmine verbrennt."}}
D[12160] = {"Ein Name aus der Vergangenheit",{"Kehrt zu Hauptmann Gryan Starkmantel im Lager der Westfallbrigade zurück."}}
D[12161] = {"Ruuna die Blinde",{"Sprecht mit Ruuna der Blinden in Ruunas Lager in der Nähe des Vordrassilpasses."}}
D[12162] = {"Julheim"}
D[12163] = {"Das Böse lauert am Meeresgrund"}
D[12164] = {"Stunde des Worg",{"Sasha im Handelsposten Weißkiefer möchte, dass Ihr zur Blutmondinsel geht und Selas, Varlam, Blutschlund und den Schatten von Arugal tötet."}}
D[12165] = {"Ein faszinierender Plan",{"Bringt die vollständige Blaupause für die Kriegsgolems zu Ausgrabungsleiter Rokar in Camp Oneqwah."}}
D[12166] = {"Das flüssige Feuer Elunes",{"Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, das flüssige Feuer Elunes zu nutzen, um die Kadaver von 6 verseuchten Elchen und 6 tollwütigen Grizzlys zu läutern."}}
D[12167] = {"Tötet die Kultisten",{"Sammelt für Aufseherin Jodi Mondweise 5 funktionstüchtige Kultistenanzüge und bringt sie zu ihr nach Sternenruh."}}
D[12168] = {"Zangus Ehrengabe",{"Bringt Zangus Ehrengabe zu Aufseherin Jodi Mondweise in Sternenruh."}}
D[12169] = {"Der Hochkultist",{"Aufseherin Jodi Mondweise in Sternenruh hat Euch gebeten, Hochkultist Zangus zu töten."}}
D[12170] = {"Keilerei in Schwarzwasser",{"Räuberhauptmann Kronn möchte, dass Ihr 10 Einheiten oder Spieler der Allianz beim Holzfällerlager von Schwarzwasser tötet."}}
D[12171] = {"Von Verrätern und Verrat",{"Zeigt Palena Silberwolke in Sternenruh das Schreiben der Allianz."}}
D[12172] = {"Abstimmung auf Dalaran",{"Das Abbild der Erzmagierin Modera in Sternenruh möchte, dass Ihr Euch auf Nordends Leylinien abstimmt."}}
D[12173] = {"Abstimmung auf Dalaran",{"Das Abbild des Erzmagiers Aethas Sonnenhäscher in Agmars Hammer möchte, dass Ihr Euch auf Nordends Leylinien abstimmt."}}
D[12174] = {"Oberkommandant Halford Wyrmbann",{"Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde."}}
D[12175] = {"Graue Worgbälge",{"Balghändler Jun'ik möchte, dass Ihr ihm 3 graue Worgbälge von Graunebeljägern in den nördlichen Wäldern bringt."}}
D[12176] = {"Ein kleiner Ersatz",{"Balghändler Jun'ik möchte, dass Ihr ihm 6 Grizzlybälge bringt."}}
D[12177] = {"Jun'iks Vertuschung",{"Bringt dem Balghändler Jun'ik in der Burg Siegeswall in den Grizzlyhügeln 1 Kohlestück und 5 Portionen herkömmliches Mehl."}}
D[12178] = {"Lieferung für Krenna",{"Nehmt das Bündel Felle und bringt es zu Krenna in Burg Siegeswall."}}
D[12179] = {"Specialization 1 [PH]",{"LOG: Complete this quest for Specialization 1."}}
D[12180] = {"Die gefangenen Ausgrabungsleiter",{"Befreit die Ausgrabungsleiter Gann, Torgan und Varana, dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück."}}
D[12181] = {"Gebt dem Zeugs einen Namen",{"Zeigt Tobias Sarkhoff in Neu-Agamand die Pesthauchprobe."}}
D[12182] = {"Nach Gallgrimm!",{"Liefert die Pesthauchprobe beim obersten Seuchenfürsten Middleton ab. Er befindet sich in Gallgrimm im Osten der Drachenöde."}}
D[12183] = {"Überzeugende Verkleidung",{"Bringt eine Aufseheruniform zu Gebirgsjäger Kilian im Prospektorat."}}
D[12184] = {"Fotosafari",{"Benutzt Kilians Kamera, um Bilder von 8 Eisenzwergen in Dun Argol aufzunehmen. Dann kehrt zu Gebirgsjäger Kilian im Prospektorat zurück."}}
D[12185] = {"Setzt Eure beste Miene auf für Loken",{"Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und kehrt dann zu Gebirgsjäger Kilian im Prospektorat zurück."}}
D[12186] = {"Flagge: Sieger"}
D[12187] = {"Flagge: Teilnehmer"}
D[12188] = {"Die Seuche der Verlassenen und du: Wie man nicht stirbt",{"Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr ihm 10 ektoplasmische Überreste bringt."}}
D[12189] = {"Schwachköpfe, wo man nur hinsieht!",{"Reist nach Gallgrimm in der Drachenöde und sprecht mit dem obersten Seuchenfürsten Middleton."}}
D[12190] = {"Sagt hallo zu meinem kleinen Freund",{"Prigmon möchte, dass Ihr Harkors Zutaten zu Harkor in Harkors Lager bringt."}}
D[12191] = {"Haut weg das Zeug!",{"Benutzt den Freibierkrug, um A.L.K. fünfmal zu treffen, und sprecht dann mit Bissel Schnellhub."}}
D[12192] = {"Dieses eine Mal, als ich betrunken war...",{"Sprecht mit Bissel Schnellhub im Braufestlager."}}
D[12193] = {"Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?",{"Löst Euren Gutschein für einen Braufestkrug bei Belbi Blitzknips im Braufestlager ein."}}
D[12194] = {"Sagt mal, es gibt dieses Jahr nicht zufällig ein Souvenir?",{"Löst Euren Gutschein für einen Braufestkrug bei Blix Fixtand im hinteren Teil des Braufestlagers ein."}}
D[12195] = {"Ein unerwarteter \"Gast\"",{"Bringt 5 ausgewachsene Hirschgeweihe zu Tormak dem Vernarbten in Camp Oneqwah."}}
D[12196] = {"Von Grund auf",{"Bringt Ausgrabungsleiter Rokar im Camp Oneqwah 8 Teile eines Kriegsgolems."}}
D[12197] = {"Wir haben die Macht",{"Bringt Durars Energiezelle und Kathorns Energiezelle zu Ausgrabungsleiter Rokar im Camp Oneqwah."}}
D[12198] = {"... oder vielleicht doch nicht",{"Ladet Euren Kriegsgolem mit der Energie von 10 Blitzwachen auf und kehrt dann zu Ausgrabungsleiter Rokar in Camp Oneqwah zurück."}}
D[12199] = {"Nieder mit dem Eisenthan!",{"Besiegt den Eisenthan Zornhammer mithilfe Eures Kriegsgolems und kehrt dann zu Tormak dem Vernarbten im Camp Oneqwah zurück."}}
D[12200] = {"Smaragddrachentränen",{"Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr 8 Smaragddrachentränen sammelt."}}
D[12201] = {"Des Aufsehers Schatten",{"Bringt eine Aufseheruniform zu Späher Vor'takh in Oneqwah."}}
D[12202] = {"Fotosafari",{"Benutzt Rokars Kamera, um in Dun Argol die Bilder von 8 Eisenzwergen aufzunehmen und kehrt dann zu Späher Vor'takh im Camp Oneqwah zurück."}}
D[12203] = {"Lokens Befehle",{"Verkleidet Euch als Eisenrunenaufseher, fangt die Nachricht von Loken ab und erstattet dann Späher Vor'takh im Camp Oneqwah Bericht."}}
D[12204] = {"In Lokens Namen",{"Redet Mit Hugh Glass und Gavrock über Loken und übermittelt Eure Erkenntnisse Späher Vor'takh im Camp Oneqwah."}}
D[12205] = {"GESUCHT: Der Scharlachrote Ansturm",{"Tötet 20 Mitglieder des Scharlachroten Ansturms und meldet Euch anschließend bei Hochexekutor Zürner in Gallgrimm."}}
D[12206] = {"Verseuchte letzte Riten",{"Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr das Seuchenfläschchen an dem Gefangenen des Scharlachroten Ansturms austestet."}}
D[12207] = {"Vordrassils Fall",{"Windseherin Grauhorn in Burg Siegeshall möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms besorgt."}}
D[12208] = {"Gute Trolljagd",{"Unteroffizier Thurkin möchte, dass Ihr mit Samir am Granitquell sprecht."}}
D[12209] = {"Kriegsbeute",{"Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 8 Rüstungen des Scharlachroten Ansturms und 8 Waffen des Scharlachroten Ansturms stehlt."}}
D[12210] = {"Trollsaison!",{"Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr mit Samir am Granitquell sprecht."}}
D[12211] = {"Lasst sie nicht wieder auferstehen!",{"Apothekerin Vicky Levine aus Gallgrimm hat Euch gebeten, Ihr Behältnis voller Ratten zu benutzen, um 15 Leichen von Anhängern des Scharlachroten Ansturms in Neuherdweiler zu beseitigen."}}
D[12212] = {"Das Lagerhaus auffüllen",{"Förstermeister Anderhol bei der Ammertannhütte möchte, dass Ihr Großhornhirsche tötet und 8 Stück saftiges Wildbret sammelt."}}
D[12213] = {"Die Dunkelheit darunter",{"Windseherin Grauhorn möchte, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet."}}
D[12214] = {"Ersatzpferde",{"Hänsel Bauer in Gallgrimm möchte, dass Ihr 3 Kriegspferde des Ansturms stehlt, sie anschließend bei ihm abliefert und ihm dann auch die Zügel übergebt."}}
D[12215] = {"Sie oder wir!",{"Anderhol bei der Ammertannhütte möchte, dass Ihr in den Grizzlyhügeln nach 6 Graunebeljägern sucht und sie tötet."}}
D[12216] = {"Bärenhatz!",{"Anderhol bei der Ammertannhütte möchte, dass Ihr 8 Grizzlyflanken von den Grizzlybären in den Grizzlyhügeln ergattert."}}
D[12217] = {"Adleraugen",{"Anderhol bei der Ammertannhütte möchte, dass Ihr 5 Kaiseradler tötet und ihm anschließend Bericht erstattet."}}
D[12218] = {"Verbreitet die guten Neuigkeiten",{"Oberster Seuchenfürst Middleton in Gallgrimm in der Drachenöde möchte, dass Ihr in den Seuchenverbreiter der Verlassenen steigt, zu den Randgebieten der Aasfelder fahrt und dort mithilfe der Seuchenbombe 30 hungernde Tote vernichtet."}}
D[12219] = {"Der eingegangene Weltenbaum",{"Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr zu Vordrassils Ast, Vordrassils Herz oder zu Vordrassils Tränen geht und 6 Schleimproben des entropischen Schlamms beschafft."}}
D[12220] = {"Ein dunkler Einfluss",{"Hierophant Thayreen bei der Ammertannhütte will, dass Ihr zu Vordrassils Herz, Vordrassils Tränen und Vordrassils Ast geht und die Kugel des Geomanten in den Tiefen unter der Erdoberfläche anwendet."}}
D[12221] = {"Die Seuche der Verlassenen",{"Liefert die Seuche der Verlassenen bei Doktor Sintar Malefius in Agmars Hammer ab."}}
D[12222] = {"Geheimnisse der Flammenbinder",{"Bringt dem Förster Drach bei der Ammertannhütte 3 flammenerfüllte Talismane."}}
D[12223] = {"Die Reihen lichten",{"Tötet 12 Huscarls der Drachenschinder und kehrt anschließend zu Förster Drach in der Ammertannhütte zurück."}}
D[12224] = {"Der Vorposten der Kor'kron!",{"Meldet Euch bei Saurfang dem Jüngeren im Vorposten der Kor'kron."}}
D[12225] = {"Mmm... Bernsteinsamen!",{"Sprecht mit Förstermeister Anderhol in der Ammertannhütte."}}
D[12226] = {"Wieder raus damit",{"Anderhol bei der Ammertannhütte möchte, dass Ihr ihm 5 Schwarzwurzelstrünke bringt."}}
D[12227] = {"Tut Eure Pflicht",{"Anderhol bei der Ammertannhütte möchte, dass Ihr Anderhols Karussellstöffsche nehmt und das nahegelegene Plumpsklo aufsucht, um die teilweise verarbeiteten Bernsteinsamen zurückzuholen."}}
D[12228] = {"Sich der Magie wieder bemächtigen"}
D[12229] = {"Eine mögliche Verbindung",{"Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr 8 Proben des Bluts eines wahnsinnigen Furbolgs von den Furbolgs am Schrein des Herzbluts und am Schrein des Grollfangs sammelt."}}
D[12230] = {"Von den Belagerungsschmieden klauen",{"Todeswache Molder in Gallgrimm möchte, dass Ihr 6 Bomben des Belagerungsschmiedes beschafft."}}
D[12231] = {"Die Jungen des Bärengottes",{"Windseherin Grauhorn in der Burg Siegeswall möchte, dass Ihr mit Orsonn am Schrein des Grollfangs und Kodian am Schrein des Herzbluts sprecht."}}
D[12232] = {"Bombardiert die Ballisten",{"Todeswache Molder in Gallgrimm möchte, dass Ihr mit den Bomben des Belagerungsschmiedes 5 Ballisten von Neuherdweiler unter Beschuss nehmt."}}
D[12233] = {"Den Samen aussäen"}
D[12234] = {"Das muss ich wissen",{"Spionagemeisterin Repine möchte, dass Ihr die \"Tagesübersicht des Scharlachroten Ansturms: Abtei\", \"Tagesübersicht des Scharlachroten Ansturms: Kaserne\" und die \"Tagesübersicht des Scharlachroten Ansturms: Strand\" stehlt."}}
D[12235] = {"Naxxramas und der Fall von Wintergarde",{"Sprecht mit dem Greifenkommandanten Urik an der Greifenstation in der Feste Wintergarde."}}
D[12236] = {"Ursoc, der Bärengott",{"Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle findet und Ursoc mit seiner Hilfe besiegt. Streut die geläuterte Asche von Vordrassil auf Ursocs Leiche, nachdem Ihr ihn getötet habt."}}
D[12237] = {"Flug des Verteidigers von Wintergarde",{"Rettet 10 hilflose Dorfbewohner von Wintergarde und kehrt anschließend zum Greifenkommandanten Urik in Wintergarde zurück."}}
D[12238] = {"Die Reinigung Drak'Tharons",{"Drakuru möchte, dass Ihr Drakurus Elixier an seinem Kohlenbecken innerhalb Drak'Tharons benutzt. Um das Elixier dort benutzen zu können, benötigt Ihr 5 Ausdauermojos."}}
D[12239] = {"Der Spion in Neuherdweiler",{"Liefert die Tagesübersicht des Scharlachroten Ansturms bei Agentin Skully in Neuherdweiler ab."}}
D[12240] = {"Ein Mittel zum Zweck",{"Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe der Termiten der Levinefamilie Großknecht Kaleiki hervorlockt und ihn tötet."}}
D[12241] = {"Zerstört den Schössling",{"Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr die grüne Fackel nehmt und sie benutzt, um Vordrassils Schössling zu verbrennen. Bringt Vordrassils Asche zurück zu Windseher Grauhorn."}}
D[12242] = {"Vordrassils Samen",{"Windseherin Grauhorn in Burg Siegeswall möchte, dass Ihr nach Grauschlund geht und 8 Samen von Vordrassil beschafft."}}
D[12243] = {"Feuer auf dem Wasser",{"Apothekerin Vicky Levine in Gallgrimm möchte, dass Ihr mithilfe des Feuerwassers des Apothekers die Segel der Sündenbabel in Brand steckt.","","Geht unter Deck, während die Deckmatrosen damit beschäftigt sind, das Feuer zu löschen, und sucht nach Kapitän Shelys Seekarten."}}
D[12244] = {"Schredder reparieren",{"Synipus beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 3 kaputte Schredder bringt."}}
D[12245] = {"Keine Gnade für Gefangene",{"Spionagemeisterin Repine hat Euch gebeten, Todeswache Schneider, Chefschreiber Kinnedius, Ingenieur Hindermann und Kanzler Amai zu töten.","","Falls Ihr Erfolg habt, berichtet Hochexekutor Zürner in Gallgrimm davon."}}
D[12246] = {"Eine mögliche Verbindung",{"Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr am Schrein des Grollfangs und am Schrein des Herzbluts 8 Blutproben von wahnsinnigen Furbolgs sammelt."}}
D[12247] = {"Kinder von Ursoc",{"Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr mit Orsonn im Schrein des Grollfangs und mit Kodian im Schrein des Herzensblutes sprecht."}}
D[12248] = {"Vordrassils Schössling",{"Hierophant Thayreen in der Ammertannhütte möchte, dass Ihr mithilfe der grünen Fackel Vordrassils Schössling anzündet und ihr die daraus entstehende Asche von Vordrassil bringt."}}
D[12249] = {"Ursoc, der Bärengott",{"Hierophant Thayreen bei der Ammertannhütte möchte, dass Ihr Tur Wutpranke in der Nähe von Ursocs Höhle aufsucht und mit seiner Hilfe Ursoc besiegt. Streut anschließend die geläuterte Asche von Vordrassil auf Ursocs Leiche."}}
D[12250] = {"Vordrassils Samen",{"Hierophant Thayreen in der Ammertannhütte will, dass Ihr zum Grauschlund geht und 8 Samen von Vordrassil besorgt."}}
D[12251] = {"Kehrt zum Oberkommandanten zurück",{"Sprecht mit Oberkommandant Halford Wyrmbann in Wintergarde in der Drachenöde."}}
D[12252] = {"Foltert den Folterer",{"Hochexekutor Zürner in Gallgrimm möchte, dass Ihr Folterer Alphonse fünfmal mit dem Brandeisen bearbeitet und die Informationen aus ihm herausquetscht. Anschließend sollt Ihr ihn töten."}}
D[12253] = {"Rettung vom Marktplatz",{"Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 6 gefangene Dorfbewohner von Wintergarde befreit."}}
D[12254] = {"Ohne Gebet",{"Agentin Skully in Neuherdweiler möchte, dass Ihr das Gebetsbuch von Bischof Straß besorgt."}}
D[12255] = {"Der Than von Voldrune",{"Besiegt mithilfe von Flammenbringer den Than Torvald Eriksson und meldet Euch anschließend bei Förster Drach bei der Ammertannhütte."}}
D[12256] = {"Geheimnis der Flammenbinder",{"Bringt 3 flammenerfüllte Talismane zu Unteroffizier Nazgrim in Burg Siegeswall."}}
D[12257] = {"Eine Demonstration der Stärke",{"Tötet 12 Huscarls der Drachenschinder und kehrt zu Unteroffizier Nazgrim am Siegeswall zurück."}}
D[12258] = {"Das Schicksal der Toten",{"Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 15 rachsüchtige Spuke tötet."}}
D[12259] = {"Der Than von Voldrune",{"Besiegt mithilfe von Flammenbringer Than Torvald Eriksson und meldet Euch anschließend bei Unteroffizier Nazgrim in Burg Siegeswall."}}
D[12260] = {"Die perfekte Heuchelei",{"Agentin Skully in Neuherdweiler möchte, dass Ihr das Abbild eines Rabenpriesters des Ansturms stehlt. Bringt den magischen Spiegel der Banshee wieder zurück, wenn Ihr das getan habt."}}
D[12261] = {"Kein Ausweg",{"Stellt eine zerstörerische Barriere am Ende des Pfades auf, der aus dem Obsidiandrachenschrein hinausführt; dort, wo die Straße in Schnee übergeht. Schützt die Barriere, bis sie vollständig aufgeladen ist und kehrt dann zu Serinar zurück."}}
D[12262] = {"Und niemand, der Euch retten wird...",{"Tötet außerhalb des Obsidiandrachenschreins 6 Nekrolyten der Brennenden Tiefen und 10 glimmende Skelette. Kehrt zu Serinar zurück, sobald Eure Aufgabe abgeschlossen ist."}}
D[12263] = {"Nur die besten Absichten",{"Wartet, bis Serinar Euch in die Verkleidung eines Nekrolyten der Brennenden Tiefen gehüllt hat. Dringt in die Tiefen des Schlundes von Neltharion vor, um aufzudecken, was den Kult der Verdammten hierher lockt. Kehrt mit Details ihres Vorhabens zu Serinar zurück."}}
D[12264] = {"Das Ausmerzen der Verdammten",{"Tötet in Neltharions Schlund 3 Nekromanten der Brennenden Tiefen, 6 glimmende Konstrukte und 6 glimmende Spuke. Kehrt dann zu Serinar zurück."}}
D[12265] = {"Die Schändung der Entweiher",{"Findet 8 nekromantische Runen, die auf den Boden von Neltharions Schlund gezeichnet wurden und löscht sie aus. Kehrt zu Serinar zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12266] = {"Kunde der Zerstörung",{"Kehrt zum Wyrmruhtempel zurück und lasst Yntrige wissen, dass Serinars Aufgabe abgeschlossen ist."}}
D[12267] = {"Neltharions Flamme",{"Äschert mit Neltharions Flamme die Beschwörungskammer im hinteren Teil von Neltharions Schlund ein. Tötet Rothin den Verfallenen, nachdem Ihr seine Aufmerksamkeit auf Euch gezogen habt, und kehrt anschließend zu Serinar am Eingang der Höhle zurück."}}
D[12268] = {"Einzelteile",{"Pipthwak beim Holzfällerposten Blauhimmel möchte, dass Ihr ihm 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern bringt."}}
D[12269] = {"Nicht in unserer Mine",{"Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Bergarbeiterausweise von Wintergarde beschafft."}}
D[12270] = {"Schreddert die Allianz",{"Grekk im Holzfällerlager Blauhimmel möchte, dass Ihr 3 Schredder besorgt und diesen zu ihm zurückkehrt."}}
D[12271] = {"Die Rute des Zwangs",{"Liefert den Stab des Folterers bei Hochexekutor Zürner in Gallgrimm ab."}}
D[12272] = {"Das blutende Erz",{"Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 10 Proben des seltsamen Erzes aus der Mine von Wintergarde beschafft."}}
D[12273] = {"Die Verleumdung",{"Hochexekutor Zürner in Gallgrimm hat Euch damit beauftragt, den Stab des Zwangs auf Kommandant Jordan, Kanonierführer Zierhut, Schmied Gutmann und Stallmeister Mercer anzuwenden.","","Tötet sie, sobald Ihr den Stab verwendet habt, um ihnen als letzte Worte die Verleumdung des Scharlachroten Ansturms abzuverlangen."}}
D[12274] = {"In Ungnade fallen",{"Agentin Skully in Neuherdweiler möchte, dass Ihr die Glocke der Abtei läutet und anschließend vom Hochabt die benötigten Informationen beschafft."}}
D[12275] = {"Der Sprenggnom",{"Sprecht mit Belagerungsingenieur Viertelblitz in der Feste Wintergarde in der Drachenöde."}}
D[12276] = {"Die Suche nach Schleicha",{"Sucht und findet Schleicha den Sprenggnom in den Minen von Wintergarde. Holt Euch Viertelblitz' Zielsuchroboter zu Hilfe, wenn Ihr die Minen nicht finden könnt."}}
D[12277] = {"Überlasst nichts dem Zufall",{"Beschafft eine Minenbombe von Wintergarde und verwendet sie, um den oberen und unteren Minenschacht von Wintergarde zu sprengen. Erstattet Belagerungsingenieur Viertelblitz bei der Feste Wintergarde in Drachenöde Bericht, sobald Ihr die Aufgabe erfüllt habt."}}
D[12278] = {"Bier des Monats e.V.",{"Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede."}}
D[12279] = {"Bärenhunger",{"Bringt Hugh Glass am Handelsposten von Rotholz 6 Nordlachse."}}
D[12280] = {"Reparaturen",{"Lurz beim Holzfällerposten Blauhimmel möchte, dass Ihr 4 gefalzte Zahnräder, 3 gekerbte Winkel und 2 Hochspannungsfedern sammelt."}}
D[12281] = {"Die Kriegsmaschine der Geißel verstehen",{"Liefert Viertelblitz' Paket bei Oberkommandant Halford Wyrmbann in der Feste Wintergarde ab."}}
D[12282] = {"Spuren der Vergangenheit",{"Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr seine Seherkugel holt."}}
D[12283] = {"Die Wahrheit wird herauskommen",{"Agentin Skully möchte, dass Ihr das Tagebuch von Hochgeneral Abbendis beschafft und es zu Hochexekutor Zürner in Gallgrimm bringt."}}
D[12284] = {"Haltet sie auf Trab",{"Kommandant Bargok möchte, dass Ihr beim Holzfällerposten Blauhimmel 15 Einheiten oder Spieler der Allianz tötet."}}
D[12285] = {"Tu anderen...",{"Hochexekutor Zürner in Gallgrimm hat Euch befohlen, mit dem Kopf des Hochgenerals zurückzukehren."}}
D[12286] = {"Eimer mit Süßigkeiten"}
D[12287] = {"Orik Treuherz und der Vergessene Strand",{"Sucht Orik Treuherz auf der Dämmerkuppe in der Drachenöde auf."}}
D[12288] = {"Überfordert!",{"Aumana beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Abschnürbinde auf 10 verwundete Scharmützler anwendet."}}
D[12289] = {"Tritt rein, solang' sie am Boden liegen",{"Unteroffizier Hartsmann möchte, dass Ihr 15 Einheiten oder Spieler der Horde im Holzfällerlager Blauhimmel besiegt."}}
D[12290] = {"Das Düstergraselixier",{"Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr 5 Düstergräser von den Düsterhöhen holt."}}
D[12291] = {"Die vergessene Geschichte",{"Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Euch die Geschichte der vergessenen Arbeiter, vergessenen Scharfschützen, vergessenen Ritter und der vergessenen Fußsoldaten anhört."}}
D[12292] = {"Die Unterstützung der Einheimischen",{"Leutnant Dumont bei der Ammertannhütte möchte, dass Ihr Euch zum Handelsposten Immergrün begebt und die Zedernholzkiste beschafft."}}
D[12293] = {"Schließt den Handel ab",{"Bringt die Zedernholzkiste zu Ivan im Posten des Espenhains."}}
D[12294] = {"Ein vorläufiger Pakt",{"Kehrt zu Leutnant Dumont in der Ammertannhütte zurück."}}
D[12295] = {"Eine Übung in Sachen Diplomatie",{"Sprecht mit dem Entsandten Ducal in Silberwasser."}}
D[12296] = {"Leben oder Tod",{"Rheanna beim Holzfällerposten Blauhimmel möchte, dass Ihr die erneuernde Bandage bei 10 verwundeten Westfall-Einheiten anwendet."}}
D[12297] = {"Von Verrätern und Verrat",{"Hauptmann Adams möchte, dass Ihr das Schreiben der Allianz zu Greer Erzhammer in Westwacht bringt."}}
D[12298] = {"Oberkommandant Halford Wyrmbann",{"Überbringt Oberkommandant Halford Wyrmbann das Schreiben der Allianz. Er befindet sich in der Feste Wintergarde im Osten der Drachenöde."}}
D[12299] = {"Nördliche Gastfreundschaft",{"Sergei in Silberwasser will, dass Ihr 8 Marodeure von Burg Siegeswall tötet."}}
D[12300] = {"Eignungstest",{"Findet Unteroffizier Knochenknack nordwestlich von Silberwasser und besteht den Eignungstest."}}
D[12301] = {"Möge die Wahrheit uns befreien",{"Orik Treuherz auf der Dämmerkuppe in der Drachenöde möchte, dass Ihr Oriks kristalline Kugel in den Ruinen des Vergessenen Strands einsetzt, um die Vergessenen zu erlösen."}}
D[12302] = {"Worte der Warnung",{"Begebt Euch zum nordwestlichen Ende von Silberwasser."}}
D[12303] = {"Die Kriegsanstrengungen finanzieren",{"Quartiermeister Bartlett in Gallgrimm möchte, dass Ihr 6 vergessene Schätze beschafft."}}
D[12304] = {"Ein Grundstück am Strand",{"Feldmesser Hansen gleich nördlich des Vergessenen Strands möchte, dass Ihr 20 vergessene Geister vernichtet."}}
D[12305] = {"Gedanken des Abschieds",{"Kehrt zu Zelig dem Visionär in der Feste Wintergarde in der Drachenöde zurück."}}
D[12306] = {"Bier des Monats e.V.",{"Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar."}}
D[12307] = {"Wolfsbannwurzel",{"Katja in Silberwasser möchte, dass Ihr 8 Wolfsbannwurzeln ausreißt."}}
D[12308] = {"Flucht aus Silberwasser",{"Öffnet den hölzernen Käfig und helft dem befreiten Späher der Allianz, aus Silberwasser zu entkommen. Meldet Euch bei Leutnant Dumont, sobald Ihr die Ammertannhütte erreicht habt."}}
D[12309] = {"Findet Durkon!",{"Sucht Dragoner Durkon bei der Gruft von Wintergarde in der Drachenöde auf."}}
D[12310] = {"Eine prompte Reaktion",{"Leutnant Dumont möchte, dass Ihr zum Posten des Waldrands geht und Vladek sowie 7 Fährtenleser von Silberwasser erledigt."}}
D[12311] = {"Die Gruft des Adligen",{"Dragoner Durkon in der Feste Wintergarde möchte, dass Ihr Nekrolord Amarion tötet."}}
D[12312] = {"Geheimnisse der Geißel",{"Bringt den fleischgebundenen Folianten zu Dragoner Durkon in der Feste Wintergarde in der Drachenöde."}}
D[12313] = {"Rettet das Braufest!",{"Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen."}}
D[12314] = {"Nieder mit Kapitänin Zorna!",{"Tötet Kapitänin Zorna und erstattet Baron Freimann in der Venturebucht Bericht."}}
D[12315] = {"Zerschmettert Kapitän Hellwasser!",{"Tötet Kapitän Hellwasser und erstattet anschließend General Khazgar in der Venturebucht Bericht."}}
D[12316] = {"Haltet sie auf!",{"Besiegt 10 Einheiten oder Spieler der Horde in der Venturebucht und kehrt zu Leutnant Stuart zurück."}}
D[12317] = {"Haltet sie auf!",{"Besiegt 10 Einheiten oder Spieler der Allianz in der Venturebucht und kehrt zu Zenturion Kaggrum zurück."}}
D[12318] = {"Rettet das Braufest!",{"Sprecht mit dem Spion des Braufests im Grimmigen Säufer in den Schwarzfelstiefen."}}
D[12319] = {"Das Rätsel des Folianten",{"Übergebt Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde den fleischgebundenen Foliant."}}
D[12320] = {"Die Sprache des Todes verstehen",{"Bringt den fleischgebundenen Folianten zu Inquisitor Hallard im Gefängnis der Feste Wintergarde."}}
D[12321] = {"Eine rechtschaffene Predigt",{"Wartet, bis Inquisitor Hallard seine rechtschaffene Predigt gehalten hat, und kehrt dann mit Euren Entdeckungen zu Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde zurück."}}
D[12323] = {"Räuchert sie aus",{"Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Unteroffizier Downey."}}
D[12324] = {"Räuchert sie aus",{"Jagt mithilfe der Rauchbombe 20 Nachzügler der Venture Co. aus ihren Gebäuden und meldet Euch anschließend bei Steingardist Rachtotem."}}
D[12325] = {"Hinein ins Feindgebiet",{"Sprecht mit Greifenmeister Urik und fliegt zu Thorsons Posten. Meldet Euch bei Herzog August Feindhammer, wenn Ihr bei Thorsons Posten in der Drachenöde angekommen seid."}}
D[12326] = {"Dampfpanzerüberraschung",{"Zerstört mithilfe des Dampfpanzers der Allianz 6 Seuchewagen und ladet die Elitesoldaten der 7. Legion beim Mausoleum von Wintergarde ab. Sprecht anschließend mit Ambo Unkesch im Inneren des Mausoleums von Wintergarde, wenn Eure Aufgabe erledigt ist."}}
D[12327] = {"Außerkörperliche Erfahrung",{"Trinkt den samtigen Trank bei Ruunas Kristallkugel und werdet Zeuge einer Vision der Vergangenheit."}}
D[12328] = {"Ruunas Bitte",{"Ruuna die Blinde möchte, dass Ihr 4 Handvoll samtigen Staubs besorgt."}}
D[12329] = {"Schicksal und Zufall",{"Sprecht mit Sasha im Handelsposten Weißkiefer."}}
D[12330] = {"Anatol wird reden",{"Sasha im Handelsposten Weißkiefer möchte, dass Ihr den Betäubungspfeil nehmt und ihn auf Tatjana in Julheim schießt. Bringt Tatjana dann zum Handelsposten Weißkiefer zurück."}}
