D[12411] = {"Das Gelöbnis der Schwester",{"Sucht nach Anya im Grauheulerbau in der Nähe von Julheim."}}
D[12412] = {"Freund meines Feindes",{"Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Jäger von Silberwasser und ihren Anführer Vladek am Posten des Waldrands tötet."}}
D[12413] = {"Angriff auf Silberwasser",{"Eroberin Krenna in Burg Siegeswall möchte, dass Ihr 8 Verteidiger von Silberwasser in den Hügeln von Silberwasser erschlagt."}}
D[12414] = {"Aufgesessen",{"Reitet 5 Hochlandmustangs zurück zu Knappe Percy im Lager der Westfallbrigade."}}
D[12415] = {"Der Pferdebrüller",{"Erschreckt 15 Hochlandmustangs und kehrt zu Soolok Sturmwut im Camp Oneqwah zurück."}}
D[12416] = {"Im Eifer des Gefechts",{"Unterstützt Hauptmann Drayzen, die Schluchten zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.","","Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12417] = {"Der Erde übergeben",{"Erlangt über einen der nördlichen oder südlichen Pässe Zugang zum Rubindrachenschrein und sucht nach Rubineicheln. Pflanzt die Rubineicheln in der Nähe der gefallenen roten Drachen ein, um ihre Leichen wieder der Erde zu übergeben. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12418] = {"Durch das Feuer",{"Betretet den Schrein durch einen der nördlichen oder südlichen Pässe, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Ceristrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12419] = {"Das Schicksal des Rubindrachenschreins",{"Bringt Dahlia Sonnenhands Rubinfibel zu Krasus in der Ratskammer im Wyrmruhtempel und berichtet ihm von Dahlias Schicksal."}}
D[12420] = {"Bier des Monats e.V.",{"Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Larkin Donnerbräu in der Steinfeuertaverne in Eisenschmiede."}}
D[12421] = {"Bier des Monats e.V.",{"Bringt Euren Mitgliedschaftsantrag für den \"Bier des Monats e.V.\" zu Ray'ma in der Dunkeldornenlodge im Tal der Geister in Orgrimmar."}}
D[12422] = {"Scheinbegnadigung",{"Liefert den Begnadigungsbrief bei der gefangenen Fallenstellerin in den Silberwasserhügeln ab."}}
D[12423] = {"Mikhails Tagebuch",{"Bringt Mikhails Tagebuch zu Eroberin Krenna in Burg Siegeswall."}}
D[12424] = {"Gorgonna",{"Bringt Mikhails Tagebuch zu Gorgonna in Burg Siegeswall."}}
D[12425] = {"Ruuna die Blinde",{"Sprecht mit Ruuna der Blinden in Ruunas Lager nahe dem Pass von Vordrassil."}}
D[12426] = {"DEPRECATED"}
D[12427] = {"Die Siegeswallgrube: Bärenringen!",{"Besiegt Eisenbalg in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten."}}
D[12428] = {"Die Siegeswallgrube: Kampf gegen irren Furbolg",{"Besiegt Torgg Donnertotem in der Siegeswallgrube und sprecht Buchmacher Vel'jen auf eine Belohnung an."}}
D[12429] = {"Die Siegeswallgrube: Blut und Metall",{"Besiegt Rostblut in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten."}}
D[12430] = {"Die Siegeswallgrube: Der Tod ist wahrscheinlich",{"Besiegt Horgrenn Höllspalter in der Siegeswallgrube und sprecht anschließend mit Buchmacher Vel'jen, um eine Belohnung zu erhalten."}}
D[12431] = {"Die Siegeswallgrube: Entscheidungskampf",{"Besiegt Krenna in der Siegeswallgrube und sprecht anschließend mit Gorgonna, um eine Belohnung zu erhalten."}}
D[12432] = {"Ritt auf der roten Rakete",{"General Gorlok im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Allianz zerstört.","","General Gorlok befindet sich nur dann im Leuchtturm, wenn sich dieser in Besitz der Horde befindet."}}
D[12433] = {"Auf der Suche nach Lösungsmittel",{"Gurtor in der Hordenbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt."}}
D[12434] = {"Immer auf der Suche nach Lösungsmittel"}
D[12435] = {"Erstattet Lord Devrestrasz Bericht",{"Sprecht mit Lord Devrestrasz im Wyrmruhtempel."}}
D[12436] = {"Zusatzeinkommen",{"Versorger Lorkran in Burg Siegeswall will, dass Ihr 5 saftige Wildbrete von Großhornhirschen in der Nähe besorgt."}}
D[12437] = {"Ritt auf der roten Rakete",{"Kommandant Hauser im Leuchtturm in der Venturebucht möchte, dass Ihr den Holzfrachter der Horde zerstört.","","Kommandant Hauser befindet sich nur dann im Leuchtturm, wenn sich dieser im Besitz der Allianz befindet."}}
D[12438] = {"GESUCHT: Kreug Eidbrecher",{"Tötet Kreug Eidbrecher und kehrt zu Hochlord Leoric von Zeldig in der Feste Wintergarde in der Drachenöde zurück, um dort Eure Belohnung abzuholen."}}
D[12439] = {"Erschütterung im Westen",{"Sprecht mit Rodney Wells in der Feste Wintergarde zwecks eines Ritts nach Sternenruh im Westen der Drachöde."}}
D[12440] = {"Nach Sternenruh!",{"Sprecht mit dem Abbild der Erzmagierin Modera in Sternenruh im Westen der Drachenöde."}}
D[12441] = {"GESUCHT: Hochschamane Blutpfote",{"Tötet Hochschamane Blutpfote und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen."}}
D[12442] = {"GESUCHT: Ansturmkommandant Iustus",{"Tötet den Ansturmkommandanten Iustus und kehrt anschließend zu Hochlord Leoric von Zeldig in Wintergarde in der Drachenöde zurück, um Eure Belohnung abzuholen."}}
D[12443] = {"Auf der Suche nach Lösungsmittel",{"Barbelfink in der Allianzbasis in der Venturebucht möchte, dass Ihr ihm einen Kanister Element 115 bringt."}}
D[12444] = {"Gemetzel am Schwarzwasser",{"Feldspäherhauptmann Carter möchte, dass Ihr 10 Einheiten oder Spieler der Horde im Holzfällerlager Schwarzwasser tötet."}}
D[12446] = {"Immer auf der Suche nach Lösungsmittel"}
D[12447] = {"Der Obsidiandrachenschrein",{"Reist zum Obsidiandrachenschrein nordwestlich des Wyrmruhtempels und gleich westlich der Pforte des Zorns. Sucht im Inneren des Schreins nach Serinar und bietet ihm Eure Hilfe an."}}
D[12448] = {"In der Hitze des Gefechts",{"Unterstützt Hauptmann Drayzen, die Canyons zu halten. Tötet 12 eisige Ghulangreifer, 8 eisige Spukangreifer und 1 eisigen Monstrositätenangreifer.","","Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12449] = {"Zur Erde zurückkehren",{"Betretet den Schrein durch den südlichen Pass und sucht nach Rubineicheln. Benutzt die Rubineicheln nahe den gefallenen roten Drachen, um ihre Körper zur Erde zurückkehren zu lassen. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12450] = {"Durch das Feuer",{"Betretet den Schrein durch den südlichen Pass, tötet dann 6 eisige Nekromanten und eliminiert den Quell der Verderbnis unter dem Schrein. Kehrt zu Vargastrasz zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12451] = {"Weiter nach Camp Oneqwah",{"Sprecht mit Späher Vor'takh im Camp Oneqwah."}}
D[12452] = {"zzOLD The Fate of the Ruby Dragonshrine",{"Bringt Dahlias Rubinfibel zu Ceristrasz und erzählt ihm von ihrem Schicksal."}}
D[12453] = {"Der Himmel hat Augen",{"Windseherin Grauhorn möchte, dass Ihr die silberne Feder auf 6 Kaiseradler in den Grizzlyhügeln anwendet."}}
D[12454] = {"Kreislauf des Lebens",{"Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr 5 Smaragdhimmelsklauen niederstreckt."}}
D[12455] = {"In alle Winde verstreut",{"Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 Munitionskisten von Wintergarde beschafft."}}
D[12456] = {"Der Federschmuck von Alystros",{"Nishera die Gartenbewahrerin im Smaragddrachenschrein möchte, dass Ihr den Federschmuck von Alystros beschafft."}}
D[12457] = {"Die Maschinenkanone und du",{"Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr 8 verletzte Soldaten der 7. Legion rettet."}}
D[12458] = {"Samen der Peitscher",{"Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr 3 Peitschersamen zu ihm zurückbringt."}}
D[12459] = {"Das Schaffende kann auch zerstören",{"Lord Itharius in der Spitze des Wyrmruhtempels möchte, dass Ihr einen geschwächten wiedererweckten Frostwyrm, den geschwächten Turgid den Grässlichen und den geschwächten Aufseher Todesblick vernichtet."}}
D[12460] = {"Beim Rubindrachenschrein Bericht erstatten",{"Meldet Euch bei Ceristrasz, der sich auf dem Grat östlich des Rubindrachenschreins befindet. Der Schrein liegt westlich des Wyrmruhtempels."}}
D[12461] = {"Beim Rubindrachenschrein Bericht erstatten",{"Meldet Euch bei Vargastrasz, der sich gleich östlich von Agmars Hammer auf einer Anhöhe in der Nähe des Rubindrachenschreins befindet."}}
D[12462] = {"Schon Spaß gehabt?",{"Yord \"Katastrophe\" Eisbart im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Nekrolord X'avius, Nekrolord Horus und 15 Diener von Naxxramas tötet."}}
D[12463] = {"Ramschbart muss gefunden werden!",{"Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde möchte, dass Ihr Ramschbart findet."}}
D[12464] = {"Mein alter Feind",{"Liefert den Kopf des Hochgenerals bei Kommandant Eligor Morgenbringer in der Feste Wintergarde ab."}}
D[12465] = {"Ramschbarts Tagebuch",{"Beschafft die 4., 5., 6. und 7. Seite von Ramschbarts Tagebuch und bringt sie Ambo Unkesch im Mausoleum von Wintergarde in der Drachenöde."}}
D[12466] = {"Dem Eissturm hinterher: Front der 7. Legion",{"Meldet Euch bei Legionskommandant Tyralion an der Front der 7. Legion im Zentrum der Drachenöde."}}
D[12467] = {"Dem Eissturm hinterher: Thel'zans Phylakterium",{"Nehmt Eissturm Thel'zans Phylakterium ab und bringt es zurück zu Hochkommandant Halford Wyrmbann in der Feste Wintergarde."}}
D[12468] = {"Die Aufgabe des Eroberers",{"Sprecht mit Unteroffizier Nazgrim in Burg Siegeswall."}}
D[12469] = {"Zurück an den Absender",{"Folgt dem Grat nach Osten und liefert das Sprengstoffpaket bei Xink im Düsenrostposten im Norden der Drachenöde ab."}}
D[12470] = {"Mysterium der Unendlichkeit",{"Chromie auf der Spitze des Wyrmruhtempels möchte, dass Ihr zum Bronzedrachenschrein reist. Stellt das Stundenglas der Ewigkeit dort im Inneren des Schreins auf den Boden.","","Beschützt das Stundenglas so lange wie nötig und kehrt anschließend mit den erhaltenen Informationen zu Chromie zurück."}}
D[12471] = {"Grausamkeiten der Kvaldir",{"Sprecht mit Karuk über den eingesperrten Tuskarrgefangenen"}}
D[12472] = {"Endgültigkeit",{"Bringt Thel'zans Phylakterium zu Legionskommandant Yorik im Inneren des Mausoleums von Wintergarde in der Drachenöde."}}
D[12473] = {"Ein Ende und ein neuer Anfang",{"Besiegt Thel'zan den Dämmerbringer und meldet Euch anschließend bei Oberkommandant Halford Wyrmbann in Wintergarde in der Drachenöde."}}
D[12474] = {"Auf zur Feste Fordragon!",{"Geht zur Feste Fordragon in der Drachenöde und sprecht mit Hochlord Bolvar Fordragon."}}
D[12475] = {"Männergeheimnisse",{"Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr die Karte des Scharlachroten Ansturms findet und sie zu ihm zurückbringt."}}
D[12476] = {"Die Rückkehr des Kreuzzugs?",{"Kommandantin Lynore Windstreich in der Feste Wintergarde in der Drachenöde möchte, dass Ihr 20 Mitglieder des Scharlachroten Ansturms im Basislager des Ansturms tötet."}}
D[12477] = {"Der Weg der Erlösung",{"Bringt \"Der Weg der Erlösung\" zu Oberkommandant Halford Wyrmbann in der Feste Wintergarde in der Drachenöde."}}
D[12478] = {"Frostgramhöhlen",{"Zelig der Visionär in der Feste Wintergarde in der Drachenöde möchte, dass Ihr am Ende der Frostgramhöhlen Zeligs Seherkugel benutzt. Lüftet die Geheimnisse der Vergangenheit!"}}
D[12479] = {"Auf nach Nordend!",{"Sprecht mit dem Rekrutierer der Allianz in der Valianzfeste in der boreanischen Tundra oder im Hafen der Vergeltung im heulenden Fjord."}}
D[12480] = {"Auf nach Nordend!",{"Sprecht mit dem Rekrutierer der Horde im Inneren der Kriegshymnenfeste in der boreanischen Tundra oder im Hafen der Vergeltung im heulenden Fjord."}}
D[12481] = {"Salz in die Wunde streuen",{"Lest Björn Halgurdsson in Quälheim die Vrykulbeleidigung laut vor, lockt ihn dann zu Lydells Hinterhalt und helft den anderen, ihn zu töten."}}
D[12482] = {"Gegen Niffelvar",{"Waldläuferhauptmann Areiel möchte, dass Ihr nach Niffelvar geht und 5 Krieger der Drachenschinder, 4 Runenseher der Drachenschinder und 4 Jagdhunde der Drachenschinder tötet."}}
D[12483] = {"Schimmerkappeneintopf",{"Prigmon am Granitquell möchte, dass Ihr 5 Schimmernde Schneekappen und 5 Eisschlangenaugen in den Ruinen von Drak'Zin und 5 Süßwurzeln aus Zeb'Halak sammelt."}}
D[12484] = {"Geißelkebab",{"Prigmon am Granitquell möchte, dass Ihr eine mumifizierte Trollleiche zu Mack Fearsen bringt und sie dort ins Feuer werft."}}
D[12485] = {"Howling Fjord: aa - A - LK FLAG"}
D[12486] = {"Auf zum Außenposten Bor'gorok, schnell!",{"Sprecht mit Geisterflüsterin Fletschfang im Außenposten Bor'gorok."}}
D[12487] = {"Auf nach Burg Siegeswall! Doch Achtung!",{"Stellt Euch Eroberin Krenna vor. Sie befindet sich in Burg Siegeswall in den Grizzlyhügeln."}}
D[12488] = {"Der Hochexekutor braucht Euch",{"Sprecht mit Hochexekutor Zürner in Gallgrimm in der Drachenöde."}}
D[12489] = {"Willkommen im Sholazarbecken",{"Folgt dem Pfad in Richtung Nordwesten, bis Ihr das Lager erreicht, das Monti erwähnt hat."}}
D[12490] = {"Veehjas Rache",{"Veehja im Schrein der Schuppen möchte, dass Ihr 6 Matrosen der Skadir, 3 Nebelwirker der Skadir und 2 Runenmagier der Skadir erschlagt."}}
D[12491] = {"Düsterbräus Düsterbräu",{"Bringt Düsterbräus Düsterbräu zu Ipfelkofer Eisenfass im Braufestlager in der Nähe von Eisenschmiede."}}
D[12492] = {"Düsterbräus Düsterbräu",{"Bringt Düsterbräus Düsterbräu zu Zapfus Schwindelfass im Braufestlager in der Nähe von Orgrimmar."}}
D[12493] = {"PvP-Test",{"Tötet 10 Gegner."}}
D[12494] = {"Flagge: Werbung für den Reitlehrer (20)"}
D[12495] = {"Audienz bei der Drachenkönigin",{"Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf."}}
D[12496] = {"Audienz bei der Drachenkönigin",{"Geht zum Wyrmruhtempel in der Drachenöde und sucht Alexstrasza die Lebensbinderin auf."}}
D[12497] = {"Galakrond und die Geißel",{"Sprecht mit Torastrasza im Wyrmruhtempel in der Drachenöde."}}
D[12498] = {"Auf rubinroten Schwingen",{"Zerstört 30 Ödnisplünderer und beschafft Euch Antioks Sense. Kehrt anschließend zu Alexstrasza der Lebensbinderin im Wyrmruhtempel zurück, solltet Ihr diese Aufgabe abschließen."}}
D[12499] = {"Die Rückkehr nach Angrathar",{"Sprecht mit Hochlord Bolvar Fordragon in der Feste Fordragon und erzählt ihm von Eurem Sieg über die Geißel."}}
D[12500] = {"Die Rückkehr nach Angrathar",{"Sprecht mit Saurfang dem Jüngeren im Vorposten der Kor'kron und erzählt ihm von Eurem Sieg über die Geißel."}}
D[12501] = {"Trollpatrouille",{"Kommandant Kunz von der Argentumwache möchte, dass Ihr die vier Posten des Argentumkreuzzugs besucht, die Befehle der dortigen Hauptmänner ausführt und anschließend zurückkehrt und Bericht erstattet.","","Hauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel findet Ihr in Drak'Agal und Alchemist Finkelstein am Posten von Heb'Valok."}}
D[12502] = {"Trollpatrouille: Standarten hoch",{"Hauptmann Brandon möchte, dass Ihr das Banner des Argentumkreuzzugs auf den Drakkaripodesten in Drak'Sotra aufstellt."}}
D[12503] = {"Verteidigt die Stellung",{"Kommandant Falstaav hat Euch damit beauftragt, 10 beliebige Diener der Geißel auf dem Hof der Argentumwache zu vernichten."}}
D[12504] = {"Der Argentumkreuzzug rückt ab!",{"Unteroffizier Stackhammer am Altar von Sseratus möchte, dass Ihr mit 10 seiner Argentumsoldaten sprecht und ihnen sagt, dass sie sich bei ihm zurückmelden sollen."}}
D[12505] = {"Neue Befehle für Unteroffizier Stackhammer",{"Kommandant Kunz hat Euch gebeten, Unteroffizier Stackhammer am Altar von Sseratus die Neuen Einsatzbefehle zu bringen."}}
D[12506] = {"Ärger am Altar von Sseratus",{"Verhexer Ubungo in der Argentumwache möchte, dass Ihr das Hauptaltargebäude auf dem Altar von Sseratus untersucht."}}
D[12507] = {"Seltsames Mojo",{"Liefert das seltsame Mojo bei Verhexer Ubungo in der Argentumwache ab."}}
D[12508] = {"Die Sache erledigen",{"Korporal Mala am Altar von Sseratus möchte, dass Ihr Champions von Sseratus, Priester von Sseratus oder Schlangenführer der Drakkari tötet - insgesamt jedoch 10."}}
D[12509] = {"Trollpatrouille: Starker Magen",{"Hauptmann Rupert in Drak'Sotra möchte, dass Ihr den Mut der kauernden Rekruten des Kreuzzugs wiederherstellt."}}
D[12510] = {"Kostbare elementare Flüssigkeiten",{"Verhexer Ubungo in der Argentumwache möchte, dass Ihr 3 kostbare elementare Flüssigkeiten beschafft."}}
D[12511] = {"Die Hügel der bärigen Augen",{"Meldet Euch bei Leutnant Dumont bei der Ammertannhütte in den westlichen Grizzlyhügeln."}}
D[12512] = {"Lasst niemanden zurück",{"Dr. Rogers in Drak'Sotra möchte, dass Ihr Kreuzfahrer Lamoof, Kreuzfahrer Jonathan und Kreuzfahrerin Josephine findet. Legt ihnen dann die Verbände des Kreuzfahrers an und gebt ihnen so lange Geleitschutz, bis sie bei Dr. Rogers angelangt sind."}}
D[12513] = {"Netter Hut...",{"Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris."}}
D[12514] = {"Pilzemixer",{"Sammelt 10 Krauskappenfungi und bringt sie zu Verhexer Ubungo in der Argentumwache."}}
D[12515] = {"Netter Hut...",{"Don Carlos hat Euch versehentlich dazu herausgefordert, sein jüngeres Ich im Alten Hügelland zu besiegen. Bringt ihm anschließend seinen Hut als Beweis. Er befindet sich in Tanaris."}}
D[12516] = {"Zu viel des Guten",{"Erschlagt den verworrenen Propheten von Sseratus und kehrt anschließend zu Verhexer Ubungo in der Argentumwache zurück."}}
D[12517] = {"Schurkenkartenset",{"Beschwört mithilfe des Schurkenkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set."}}
D[12518] = {"Magierkartenset",{"Beschwört mithilfe des Magierkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set."}}
D[12519] = {"Trollpatrouille: Was wollt Ihr - 'ne Medaille?",{"Hauptmann Grondel vor dem Kolosseum möchte, dass Ihr 7 Medaillons der Drakkari von den Drakkarileichen in der Nähe beschafft."}}
D[12520] = {"Meister der Rhinozerosjagd: Die Prüfung",{"Tötet 15 Splitterhornrhinozerosse und kehrt anschließend zu Hemet Nesingwary in Nesingwarys Basislager zurück."}}
D[12521] = {"Wo in aller Welt ist Hemet Nesingwary?",{"Ihr befindet Euch auf dieser Quest."}}
D[12522] = {"Brauch 'nen Motor, hol 'nen Motor",{"Weslex Schnellzang in Nesingwarys Basislager möchte, dass Ihr ihm den Motor einer Flugmaschine bringt."}}
D[12523] = {"Hast ein Teil, dann gib ein Teil",{"Bringt 7 Ersatzteile der Venture Co. zu Weslex Schnellzang in Nesingwarys Basislager."}}
D[12524] = {"Missgeschick der Venture Co.",{"Debaar in Nesingwarys Basislager möchte, dass Ihr 15 Mitglieder der Venture Company tötet. Ihr könnt entweder Grobiane der Venture Co. oder Ausgräber der Venture Co. töten."}}
D[12525] = {"Wischt ihm das Grinsen vom Gesicht",{"Tötet Großknecht Schwindelgrins und Fleischklops und kehrt danach zu Debaar in Nesingwarys Basislager zurück."}}
D[12526] = {"Beherrschen der Rhinozerosjagd: Die Verfolgung",{"Sprecht mit Orakel Soo-rahm bei den Knochen von Nozronn."}}
D[12527] = {"Gefräßige Lauerer",{"Bringt 5 Basiliskenkristalle zu Alchemist Finkelstein im Schrein in Heb'Valok."}}
D[12528] = {"Gute Miene zum bösen Spiel",{"Meldet Euch beim Hochschamanen Rakjak auf dem Hügel der Wildherzen und stellt Euch als neuer \"Sklave\" vor."}}
D[12529] = {"Der Sklave der Affenjäger",{"Tötet für Hochschamanen Rakjak in den Hügeln der Wildherzen 8 Hartknöchelfutterwühler und 6 Hartknöchelstürmer.","","Sprecht mit dem Ältesten Harkek im Hügel der Wildherzen, falls Ihr Goregeks Fesseln verlieren solltet."}}
D[12530] = {"Knöchelchen schikanieren",{"Goregek hat Euch einen Knöchelchenpiekser gegeben, den Ihr auf die kleinen Knöchelchen anwenden sollt, um so die Hartknöchelmatriachin aus ihrem Versteck zu locken. Tötet die Hartknöchelmatriachin und erstattet anschließend dem Hochschamanen Rakjak auf dem Hügel der Wildherzen Bericht.","","Solltet Ihr Goregeks Fesseln verlieren, sprecht mit dem Ältesten Harkek vom Hügel der Wildherzen."}}
D[12531] = {"Bedrohung aus dem Untergrund",{"Findet Serfex unter dem Sand des südlichen Flusses, tötet ihn und bringt seine Klaue zu Hochschamane Rakjak auf dem Hügel der Wildherzen.","","Wenn Ihr Dajiks gebrauchte Kreide verliert, sprecht mit Ältesten Harkek auf dem Hügel der Wildherzen."}}
D[12532] = {"Aus dem Staub gemacht!",{"Fangt für den Ältesten Harkek 12 entflohene Hühner.","","Solltet Ihr Dajiks gebrauchte Kreide verlieren, sprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen."}}
D[12533] = {"Der Lehrling des Wespenjägers",{"Tötet für Hochschamanen Rakjak auf dem Hügel der Wildherzen 6 Saphirblaue Schwarmwespen und 9 Saphirblaue Schwarmdronen.","","Sprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Dajiks gebrauchte Kreide verlieren solltet."}}
D[12534] = {"Die Saphirkönigin",{"Bringt den Stachel der Saphirkönigin zu Hochschamane Rakjak auf dem Hügel der Wildherzen.","","Wenn Ihr Dajiks gebrauchte Kreide verliert, wendet Euch an Ältesten Harkek auf dem Hügel der Wildherzen."}}
D[12535] = {"Unfug im Gange",{"Hochschamane Rakjak auf dem Hügel der Wildherzen möchte, dass Ihr ihm 8 Himmelszeltkristallformationen bringt."}}
D[12536] = {"Ein holpriger Ritt",{"Reitet auf dem gefangenen Krokilisken zur Zuflucht der Nebelflüsterer und fragt Zepik nach weiteren Anweisungen.","","Sprecht mit dem Ältesten Harkek auf dem Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet."}}
D[12537] = {"Der Blitz schlägt immer zwei Mal ein",{"Zepik möchte, dass Ihr vor dem Wetterschrein der Nebelflüsterer die Himmelszeltkristallformation zertrümmert.","","Falls Ihr Zepiks Jagdhorn verlieren solltet, dann sprecht mit dem Ältesten Harkek auf den Hügeln der Wildherzen."}}
D[12538] = {"Der Nebel hört nicht zu",{"Zepik möchte, dass Ihr 12 Gorlocs der Nebelflüsterer tötet.","","Sprecht mit dem Ältesten Harkek vom Hügel der Wildherzen, falls Ihr Zepiks Jagdhorn verlieren solltet."}}
D[12539] = {"Und raus hier",{"Sucht den Weg zurück zum Hügel der Wildherzen und sprecht mit Hochschamane Rakjak."}}
D[12540] = {"Tu nur meine Pflicht",{"Sucht für Hochschamanen Rakjak auf dem Hügel der Wildherzen ein verletztes Orakel der Regenrufer."}}
D[12541] = {"Trollpatrouille: Der Lehrling des Alchemisten",{"Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.","","Sprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid."}}
D[12542] = {"Der Ruf des Kreuzzugs",{"Meldet Euch bei Kreuzritter Valus in der Lichtwarte in der Drachenöde."}}
D[12543] = {"Eine Opfergabe für Soo-rahm",{"Bringt dem Orakel Soo-rahm in der Nähe der Knochen von Nozronn 5 Intakte Kobragiftzähne."}}
D[12544] = {"Die Knochen von Nozronn",{"Benutzt Soo-rahms Weihrauch in der Nähe der Knochen von Nozronn, kehrt dann mit den Informationen, die Ihr in Erfahrung gebracht habt, zu Hemet Nesingwary in Nesingwarys Basislager zurück."}}
D[12545] = {"Die Säuberung von Jintha'kalar",{"Kreuzritter Valus bei der Lichtwarte in der Drachenöde möchte, dass Ihr 15 Anhänger der Geißel von Jintha'kalar tötet."}}
D[12546] = {"Wiedergewinnung",{"Geht zur Lawine im Sholazarbecken und verwendet die Omegarune, um den Etymidian zu aktivieren. Tötet mit ihm 200 Diener der Geißel, Bythius den Fleischformer, Urgreth von den Tausend Gräbern und Hagel'skorn.","","Sprecht mit dem Avatar von Freya im Sholazarbecken, sobald Ihr diese Aufgabe abgeschlossen habt."}}
D[12547] = {"Die Aktivierungsrune",{"Besorgt die Omegarune von der Terrasse des Formers und bringt sie zu Etymidian."}}
D[12548] = {"Der Etymidian",{"Durchschreitet das Tor am südlichen Ende des Sholazarbeckens und sucht auf der anderen Seite nach der Waffe, die der Etymidian genannt wird."}}
D[12549] = {"Beherrschen der Schreckenssäblerjagd: Zum Raubtier werden",{"Tötet 15 Schreckenssäbler und kehrt anschließend zu Buck Cantwell in Nesingwarys Basislager zurück."}}
D[12550] = {"Meister der Schreckenssäblerjagd: Der Beute auf der Spur",{"Buck Cantwell in Nesingwarys Basislager möchte, dass Ihr 3 Shangofährten aus den Schreckenssäblerfährten nahe des Bittertidensees herauslest."}}
D[12551] = {"Meister der Krokiliskenjagd: Die Prüfung",{"Tötet 15 Mangalkrokilisken und kehrt zu Debaar in Nesingwarys Basislager zurück."}}
D[12552] = {"Tod den Nekromagiern",{"Unteroffizier Mondsplitter in Drak'Sotra möchte, dass Ihr 8 Nekromagier von Hath'ar vernichtet."}}
D[12553] = {"Seglerspinndrüsen",{"Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr 5 intakte Seglerspinndrüsen beschafft."}}
D[12554] = {"Malas der Verderber",{"Unteroffizier Mondsplitter in Drak'Sotra besteht darauf, dass Ihr ihm den Kopf des Verderbers bringt."}}
D[12555] = {"Ein Wirrgespinst",{"Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr mithilfe des Wirrgespinstwerfers 5 Seuchensprüher zerstört."}}
D[12556] = {"Meister der Rhinozerosjagd: Der Todesstoß",{"Bringt Farunns Horn zu Hemet Nesingwary in Nesingwarys Basislager."}}
D[12557] = {"Laborarbeit",{"Alchemist Finkelstein in Heb'Valok möchte, dass Ihr in sein Labor geht und ihm eine schlammige Moormade, einen getrockneten Fledermausflügel, einen Bernsteinsamen und ein wenig gekühlten Schlangenschleim beschafft."}}
D[12558] = {"Meister der Schreckenssäblerjagd: Bereit zum Angriff",{"Bringt Shangos Pelz zu Buck Cantwell in Nesingwarys Basislager."}}
D[12559] = {"Aufladen des Tors - Hort der Schöpfer",{"Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr Euch zum Hort der Schöpfer begebt und den Aktivierungsschalter Gamma betätigt."}}
D[12560] = {"Meister der Krokiliskenjagd: Der Plan",{"Bringt Debaar in Nesingwarys Basislager 5 Sandfarnwedel."}}
D[12561] = {"Eine Vertrauensfrage",{"Gewinnt Freyas Vertrauen, indem Ihr 6 verseuchte Leichname und 10 Knochensensenverheerer in den verlorenen Landen vernichtet."}}
D[12562] = {"Die Drakkari brauchen keine Wasserelementare!",{"Unterleutnant Jax in der Argentumwache möchte, dass Ihr 10 Wasserbinder der Drakkari tötet."}}
D[12563] = {"Trollpatrouille",{"Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.","","Hauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok."}}
D[12564] = {"Trollpatrouille: Etwas gegen die Schmerzen"}
D[12565] = {"Der Segen von Zim'Abwa",{"Verhexer Ubungo in der Argentumwache möchte, dass Ihr der Statue von Zim'Abwa 10 Drakkariopfergaben darbringt."}}
D[12566] = {"Hilfe für das Lager der Winterhufe",{"Sprecht mit Häuptling Aschtotem im Lager der Winterhufe."}}
D[12567] = {"Der Segen von Zim'Abwa"}
D[12568] = {"Trollpatrouille: todsicher gehen"}
D[12569] = {"Meister der Krokiliskenjagd: Der Hinterhalt",{"Bringt Buschräubers Kiefer zu Debaar in Nesingwarys Basislager."}}
D[12570] = {"Glückliche Missverständnisse",{"Geleitet das verletzte Orakel der Regenrufer sicher zum Baldachin der Regenrufer und sprecht mit dem Hochorakel Soo-say."}}
D[12571] = {"Mach böse Schlangen fort",{"Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Giftspitze und 10 Kaiserkobras tötet.","","Wenn Ihr Lafoos Käfertasche verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12572] = {"Götter wollen Glitzerglitzer",{"Sammelt 6 von den Schätzen, die Lafoo ausgräbt, und bringt sie zum Hochorakel Soo-say auf dem Baldachin der Regenrufer.","","Sprecht mit dem Hochorakel Soo-say auf dem Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet."}}
D[12573] = {"Frieden schließen",{"Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr Schamanen Vekjik ein Friedensangebot unterbreitet und anschließend mit seiner Antwort wieder zurückkehrt.","","Sprecht mit dem Hochorakel Soo-say im Baldachin der Regenrufer, falls Ihr Lafoos Käfertasche verlieren solltet."}}
D[12574] = {"Schon zurück?",{"Reist zur Zuflucht der Nebelflüsterer und sprecht mit Nebelrufer Soo-gan.","","Wenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12575] = {"Der verlorene Schatz der Nebelflüsterer",{"Tötet Kriegsfürst Tartek und bringt den Schatz der Nebelflüsterer für Soo-gan in der Zuflucht der Nebelflüsterer zurück.","","Wenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12576] = {"Mit harter Hand",{"Tötet 8 Speerträger der Wildherzen und 6 Strauchdiebe der Wildherzen für Nebelrufer Soo-gan in der Zuflucht der Nebelflüsterer.","","Wenn Ihr Jaloots Lieblingskristall verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12577] = {"Hausezeit!",{"Kehrt zum Baldachin der Regenrufer zurück."}}
D[12578] = {"Der wütende Gorloc",{"Reist ins Mooswandlerdorf und sprecht gleich nach Eurer Ankunft mit Moodle.","","Wenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12579] = {"Lebensblut des Mooswandlerschreins",{"Moodle möchte, dass Ihr 10 Lebensblutscherben sammelt, aber haltet Euch von der Höhle innerhalb der Säule selbst fern.","","Wenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12580] = {"Retter der Mooswandler",{"Moodle möchte, dass Ihr 6 Mooswandleropfer im Mooswandlerdorf rettet, obwohl manche von ihnen vielleicht bereits nicht mehr länger leben.","","Wenn Ihr Moodles Stressball verliert, wendet Euch an das Hochorakel Soo-say im Baldachin der Regenrufer."}}
D[12581] = {"Bürde eines Helden",{"Tötet Artruis den Herzlosen.","","Da Moodle Euch bei dieser Aufgabe nicht begleiten kann, wird empfohlen, zur Sicherheit auf die Hilfe von Freunden zurückzugreifen."}}
D[12582] = {"Champion der Wildherzen"}
D[12583] = {"Abgestürzter Seuchensprüher",{"Spezialistin Zahnrad in Drak'Sotra möchte, dass Ihr Seuchensprüherteile sammelt."}}
D[12584] = {"Das pure Böse",{"Hauptmann Rupert möchte, dass Ihr 10 Brocken Saronit einsammelt und sie anschließend zu Etrigg in der Argentumwache bringt."}}
D[12585] = {"Trollpatrouille: Annehmlichkeiten"}
D[12586] = {"In Search of Bigger Game",{"Talk to <x> at <x>."}}
D[12587] = {"Trollpatrouille",{"Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.","","Hauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra stationiert, Hauptmann Grondel in Drak'Agal und Alchemist Finkelstein in Heb'Valok."}}
D[12588] = {"Trollpatrouille: Könnt Ihrs aushalten?",{"Hauptmann Brandon in Drak'Sotra möchte, dass Ihr mit dem Stahlspaten in den uralten Erdhaufen in der Nähe herumgrabt, um das uralte Relikt der Drakkari zu finden."}}
D[12589] = {"Kick, was für'n Kick?",{"Schießt mit dem RJR-Gewehr den Apfel vom Kopf von Wilhelm dem Glückspilz und sprecht dann mit Drostan."}}
D[12590] = {"Blahblah[PH]"}
D[12591] = {"Trollpatrouille: Werfen",{"Hauptmann Rupert in Drak'Sotra möchte, dass Ihr hocheffektive Granaten in der Nähe von 5 nerubischen Kratern einsetzt."}}
D[12592] = {"Des großen Jägers Wettstreit",{"Tötet 60 Beutetiere, während Ihr Hemet und seinen Kameraden bei der Jagd helft. Kehrt zu Drostan in Nesingwarys Basislager zurück, wenn Ihr Eure 60 getötet habt, um Ergebnisse zu vergleichen."}}
D[12593] = {"Im Dienste des Lichkönigs",{"Meldet Euch bei Instrukteur Razuvious, sobald Ihr dort seid."}}
D[12594] = {"Trollpatrouille: Juckt mich kein bisschen",{"Hauptmann Grondel möchte, dass Ihr 7 moosbedeckte Amokläufer in Drak'Agal tötet."}}
D[12595] = {"Auf der Suche nach größerem Wild",{"Sprecht mit Dorian Drachenlauer in Dorians Außenposten im Sholazarbecken."}}
D[12596] = {"Pa'trollieren",{"Kommandant Kunz in der Argentumwache möchte, dass Ihr die vier Stützpunkte des Argentumkreuzzugs besucht, den Befehlen der dortigen Anführer gehorcht und anschließend bei ihm Bericht erstattet.","","Hauptmann Brandon und Hauptmann Rupert sind in Drak'Sotra südöstlich von hier stationiert.","","Hauptmann Grondel ist in Drak'Agal gleich im Osten stationiert.","","Alchemist Finkelstein ist in Heb'Valok im Norden stationiert."}}
D[12597] = {"Etwas gegen die Schmerzen",{"Hauptmann Brandon in Drak'Sotra möchte, dass Ihr 5 Stück reifen Wassermohns von den Feldern von Drak'Sotra besorgt."}}
D[12598] = {"Hinunterwerfen",{"Hauptmann Rupert in Drak'Sotra möchte, dass Ihr die hocheffektiven Granaten in der Nähe von 5 nerubischen Kratern verwendet."}}
D[12599] = {"Annehmlichkeiten",{"Hauptmann Grondel in Drak'Agal möchte, dass Ihr ihm 20 Stück abgestorbenes Dornholz bringt."}}
D[12600] = {"Bärenreittier"}
D[12601] = {"Der Lehrling des Alchemisten",{"Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.","","Sprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid."}}
D[12602] = {"Der Lehrling des Alchemisten",{"Alchemist Finkelstein in Heb'Valok möchte, dass Ihr ihm bei der Herstellung eines Wahrheitsserums helft.","","Sprecht ihn an und folgt seinen Anweisungen, sobald Ihr bereit seid."}}
D[12603] = {"Klauen schärfen",{"Tötet 6 urzeitliche Drachen und sprecht anschließend mit Dorian Drachenlauer in Dorians Außenposten."}}
D[12604] = {"Herzlichen Glückwunsch!"}
D[12605] = {"Den Köder sichern",{"Bringt 6 urzeitliche Jungtiere zu Dorian Drachenlauer in Dorians Außenposten."}}
D[12606] = {"In Kokons eingesponnen!",{"Hauptmann Rupert möchte, dass Ihr die nerubischen Kokons in Drak'Sotra öffnet und wieder zu ihm zurückkehrt, sobald Ihr 3 gefangene Fußsoldaten befreit habt."}}
D[12607] = {"Ein Mammutunternehmen",{"Bringt ein Spaltzahnmammut zu Spleenix in Dorians Außenposten."}}
D[12608] = {"Angriff der Kultisten",{"Sprecht mit dem Avatar von Freya im Katarakt der Regenrufer."}}
D[12609] = {"Die Regale einräumen",{"Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 Einheiten frischen Spinnensekrets von den Falltürkrabblern in Zul'Drak sammelt."}}
D[12610] = {"Ihre Flügel stutzen",{"Hauptmann Arnath in Heb'Valok möchte, dass Ihr 7 makellose Fledermausflügel von den Fledermäusen von Zul'Drak sammelt."}}
D[12611] = {"Siebenfach zurückgezahlt",{"Der Avatar von Freya möchte, dass Ihr Thalgran Seuchenbringer besiegt, indem Ihr mit Freyas Wall seine Todesblitze siebenfach auf ihn zurückwerft."}}
D[12612] = {"Die gestürzte Säule",{"Reist zur Lebensblutsäule und sucht nach Hinweisen, die auf die Ursache ihrer Zerstörung hinweisen."}}
D[12613] = {"Aufladen des Tors - Die Warte der Schöpfer",{"Der Avatar von Freya möchte, dass Ihr Euch zur Warte der Schöpfer im Osten des Sholazarbeckens begebt und den Aktivierungsschalter Theta betätigt."}}
D[12614] = {"Postnatale Aggression",{"Tötet Brutmutter Slivina und kehrt zu Dorian Drachenlauer bei Dorians Außenposten zurück."}}
D[12615] = {"Der Segen von Zim'Torga",{"Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Torga 10 Drakkariopfergaben darbringt."}}
D[12616] = {"Kammer der Geheimnisse",{"Der Abgesandte der Argentumdämmerung möchte, dass Ihr Tenris Mirkbluts Kammer in den Bedienstetenunterkünften in Karazhan durchsucht."}}
D[12617] = {"Die Eindringlinge vernichten",{"Der Avatar von Freya am Katarakt der Regenrufer möchte, dass Ihr Euch zum Lager der Todeshand im Nordwesten begebt und 8 infiltrierende Kultisten tötet."}}
D[12618] = {"Der Segen von Zim'Torga"}
D[12619] = {"Die verzierte Runenklinge",{"Geht zu den Waffenregalen in der Schwarzen Festung und sucht nach einem kampferprobten Schwert. Verwandelt es anschließend in einer Runenschmiede zu einem Runenklingenschwert.","","Bringt das Runenklingenschwert danach zu Instrukteur Razuvious in der Schwarzen Festung."}}
D[12620] = {"Der Zorn der Lebenswächterin",{"Der Avatar von Freya im Katarakt der Regenrufer möchte, dass Ihr auf dem Gipfel der Schimmersäule Freyas Horn blast."}}
D[12621] = {"Freyas Pakt",{"Hört zu, was der Avatar von Freya zu sagen hat."}}
D[12622] = {"Die Anführer in Jin'Alai",{"Skalpierer Ahunae in Zim'Torga möchte, dass Ihr den Schatz von Kutube'sa, den Schatz von Gawanil und den Schatz von Chulo dem Verrückten beschafft."}}
D[12623] = {"Auf zum Hexendoktor",{"Sprecht mit Hexendoktor Khufu in Zim'Torga."}}
D[12624] = {"Er könnte überall sein!",{"Sucht nach einem goldenen Verlobungsring, den Ihr in den Mägen der verschiedenen Kreaturen im Sholazarbecken finden könnt."}}
D[12625] = {"Herrschaft über Acherus",{"Meldet Euch bei Meisterbelagerungsschmied Corvus auf der Etage der Garnison in der Schwarzen Festung."}}
D[12627] = {"Nach Jin'Alai durchkommen",{"Hexendoktor Khufu in Zim'Torga möchte, dass Ihr den blauen, grünen, purpurnen und roten Kessel sabotiert."}}
D[12628] = {"Mit Har'koa sprechen",{"Sprecht mit Har'koa am Altar von Har'koa."}}
D[12629] = {"Es gibt kein Entkommen",{"Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt."}}
D[12630] = {"Narsch treten und Haare krümmen",{"Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe von Narsch 10 Haarproben von den siechenden Trollen sammelt.","","Kehrt zu Stefan zurück, falls Ihr Narsch verlieren solltet, damit er ihn für Euch zurückbekommt."}}
D[12631] = {"Eine Art Einladung...",{"Bringt den untoten Halsreif zu Stefan in der Schwarzen Wacht."}}
D[12632] = {"Aber zunächst meine Jungen",{"Har'koa hat Euch gebeten, ihre Barthaare mit den Leichnamen ihrer Kinder zu benutzen und sie wiederzubeleben. Kehrt zu ihr am Altar von Har'koa zurück, sobald Ihr fertig seid."}}
D[12633] = {"Die Finsternis ruft",{"Bringt Stefan in der Schwarzen Wacht den zuckenden Halsreif."}}
D[12634] = {"Die einen machen Limonade draus, die anderen Schnaps",{"Bringt 1 Orange, 2 Bananenbündel und 1 Papaya zu Schnapsbart Donnerbräu in Nesingwarys Basislager."}}
D[12635] = {"Relikte der Schneeleopardengöttin",{"Chronist To'kini in Zim'Torga möchte, dass Ihr 10 Har'koarelikte beschafft."}}
D[12636] = {"Das Auge von Acherus",{"Meldet Euch beim Lichkönig in der Schwarzen Festung."}}
D[12637] = {"Um ein Haar",{"Stefan in der Schwarzen Wacht möchte, dass Ihr den untoten Halsreif zu Datura Blutrose bringt."}}
D[12638] = {"Eine knappe Sache",{"Stefan in der Schwarzen Wacht möchte, dass Ihr den zuckenden Halsreif zu Datura Blutrose bringt."}}
D[12639] = {"Die gefrorene Erde",{"Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 7 Essenzen der gefrorenen Erde beschafft."}}
D[12640] = {"Die Risse versiegeln",{"Skalpierer Ahunae in Zim'Torga möchte, dass Ihr 7 Elementarrisse verschließt."}}
D[12641] = {"Tod kommt von ganz oben",{"Der Lichkönig befiehlt Euch, mithilfe des Auges von Acherus die Scharlachrote Festung, die Schmiede von Neu-Avalon, das Rathaus von Neu-Avalon und die Kapelle der Scharlachroten Flamme zu analysieren.","","Das Auge von Acherus lässt sich mithilfe der Steuerung für das Auge von Acherus kontrollieren."}}
D[12642] = {"Der Geist von Rhunok",{"Sprecht mit dem Geist von Rhunok am Altar von Rhunok."}}
D[12643] = {"Lichtblick",{"Stefan in der Schwarzen Wacht möchte, dass Ihr zur Reliquie der Pein geht und dort 5 eitrige Monstrositäteninnereien von den eitrigen Monstrositäten und 5 Einheiten glibbrigen Ghulsabbers sammelt."}}
D[12644] = {"Immer noch dabei",{"Schließt den Destillationsprozess erfolgreich ab und bringt Donnerbräus Dschungelpunsch, wenn er fertig ist, zu Schnapsbart Donnerbräu in Nesingwarys Basislager."}}
D[12645] = {"Der Geschmackstest",{"Bietet Hemet Nesingwary, Hadrius Harlowe und Tamara Wackelspross eine Probe von Donnerbräus Dschungelpunsch an. Kehrt anschließend zu Schnapsbart Donnerbräu in Nesingwarys Basislager zurück."}}
D[12646] = {"Der Feind mein Prophet",{"Der Geist von Rhunok am Altar von Rhunok möchte, dass Ihr sein Mojo des arktischen Bärengottes wiederbeschafft."}}
D[12647] = {"Dem Leid ein Ende bereiten",{"Der Geist von Rhunok möchte, dass Ihr das Rauchwerk des Foltermeisters dazu einsetzt, um seinen Körper zu erwecken. Danach sollt Ihr Rhunok mithilfe der Macht, die sein Geist Euch verliehen hat, töten.","","Falls aus irgendeinem Grund die Aura für das Mojo von Rhunok von Euch weichen sollte, dann könnt Ihr zum Geist von Rhunok zurückkehren und Euch wieder segnen lassen."}}
D[12648] = {"Leger kleiden",{"Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.","","Während Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen."}}
D[12649] = {"Anziehen!",{"Stefan in der Schwarzen Wacht möchte, dass Ihr mithilfe des bezauberten Halsreifs die Geißelverkleidung auf Euch anwendet.","","Während Ihr in Geißelgestalt seid, sollt Ihr bitteres Plasma von Knorpelsack kaufen.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen."}}
D[12650] = {"Eigene Artefakte plündern",{"Chronist To'kini in Zim'Torga möchte, dass Ihr 7 Rhunokianartefakte beschafft."}}
D[12651] = {"Landeplatz am See",{"Sprecht mit Tamara Wackelspross am Landeplatz am See."}}
D[12652] = {"Gebt dem Ghul Zucker",{"Knorpelsack an der Reliquie der Pein möchte, dass Ihr die Schüssel voll sämigem Hirn mit Kutteln in der Nähe von 10 zerfallenden Ghulen benutzt."}}
D[12653] = {"Zurück zu Har'koa",{"Sprecht mit Har'koa am Altar von Har'koa."}}
D[12654] = {"Der Teilzeitjäger",{"Bringt Pechs Überreste zu Tamara Wackelspross am Landeplatz am See."}}
D[12655] = {"Der Segen von Zim'Rhuk",{"Hexendoktor Khufu möchte, dass Ihr der Statue von Zim'Rhuk 10 Drakkariopfergaben darbringt."}}
D[12656] = {"Der Segen von Zim'Rhuk"}
D[12657] = {"Die Macht der Geißel",{"Der Lichkönig gebietet Euch, seine Befehle zu Hochlord Darion Mograine in der Schwarzen Festung zu bringen.","","Benutzt den leuchtenden Transporter, der sich hinter dem Lichkönig befindet, um zu Hochlord Darion Mograine in die Hallen des Befehls zu gelangen."}}
D[12658] = {"Mein Kuschelroc",{"Bringt Spleenix bei Dorians Außenposten 7 Eier eines Rocs."}}
D[12659] = {"Skalpe!",{"Skalpierer Ahunae in Zim'Torga möchte, dass Ihr Ahunaes Messer benutzt, um 10 Heb'Drakkar Trolle zu skalpieren.","","Der Skalpierer erinnert Euch daran, sie zuerst auszuplündern."}}
D[12660] = {"Vernichtungswaffen",{"Der Avatar von Freya möchte, dass Ihr zum Lager der Todeshand in den Nordwesten geht und 4 Stück des instabilen Sprengstoffs zerstört."}}
D[12661] = {"Als Spion nach Voltarus",{"Stefan möchte, dass Ihr Euren bezauberten Halsreif benutzt, um Euch in Voltarus einzuschleichen und dort alles zu tun, was der Anführer der Geißel von Euch verlangt.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und besorgt Euch einen neuen."}}
D[12662] = {"Heb'Jin erledigen",{"Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr Heb'Jin tötet."}}
D[12663] = {"Wiedervereint"}
D[12664] = {"Dunkler Horizont",{"Drakuru in Voltarus möchte, dass Ihr mit Grindbruch sprecht und den Rundflug über Zul'Drak macht."}}
D[12665] = {"Ich spüre eine Erschütterung",{"Har'koa hat Euch gebeten, herauszufinden, was mit Quetz'lun geschehen ist. Sprecht mit ihr, um heimlich auf einem ihrer Kinder zum Altar von Quetz'lun zu reiten.","","Kehrt zu ihr am Altar von Har'koa zurück, sobald Ihr die Aufgabe erfüllt habt."}}
D[12666] = {"Vorbereitungen für die Unterwelt",{"Har'koa am Altar von Har'koa möchte, dass Ihr 8 Stück heiliger Zier sammelt und sie anschließend bei ihr abliefert."}}
D[12667] = {"Sucht die Windschlangengöttin auf",{"Geht zum Altar von Quetz'lun und sucht Quetz'luns Geist auf."}}
D[12668] = {"Den Weg zur Rache ebnen",{"Quetz'luns Geist am Altar von Quetz'lun hat Euch damit beauftragt, in der Nähe ihrer Seelenbrunnen 12 Trolle zu töten. Diese können entweder Anbeter von Quetz'lun oder schlangengebissene Berserker sein.","","Kehrt erst dann wieder zu ihr zurück, wenn Ihr Eure Aufgabe erfüllt habt."}}
D[12669] = {"So weit, so schlecht",{"Stefan in der Schwarzen Wacht möchte, dass Ihr zu Drakuru zurückkehrt und alles tut, was er von Euch verlangt.","","Während Ihr beim Reliquiar des Schmerzes seid, sollt Ihr die Verdünnungslösung in 5 Seuchenkessel schütten.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen."}}
D[12670] = {"Die Scharlachrote Ernte",{"Meldet Euch bei Prinz Valanar bei der Todesbresche."}}
D[12671] = {"Aufklärungsflug",{"Helft Pilot Vic den Aufklärungsflug abzuschließen."}}
D[12672] = {"Wegbereiter",{"Quetz'luns Geist verlangt, dass Ihr 10 Fragmente unterweltlicher Macht sammelt. Kehrt zu ihr zum Altar von Quetz'lun zurück, wenn Euch dies geglückt ist."}}
D[12673] = {"Nach oben buckeln, nach unten treten",{"Oberanführer Drakuru in Voltarus möchte, dass Ihr das Szepter der Suggestion auf die Seuchenspuke anwendet und sie dann 7 Seuchenkristalle sammeln lasst."}}
D[12674] = {"Zornentbrannte Hölle",{"Quetz'luns Geist am Altar von Quetz'lun möchte, dass Ihr Quetz'luns Verhexungsstecken auf Hohepriester Mu'funu, Hohepriester Tua-Tua und Hohepriester Hawinni anwendet. Anschließend sollt Ihr sie vernichten."}}
D[12675] = {"Eine letzte Sache",{"Liefert die Fragmente unterweltlicher Macht bei Har'koa ab und bittet sie um einen Teil ihres Geistes. Sie befindet sich noch immer am Altar von Har'koa."}}
D[12676] = {"Sabotage",{"Stefan in der Schwarzen Wacht möchte, dass Ihr eine weitere Aufgabe für Drakuru erledigt.","","Zusätzlich dazu müsst Ihr an 5 Geißelwagen im Reliquiar des Schmerzes Sprengladungen anbringen.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen."}}
D[12677] = {"Gefährliche Materialien",{"Stefan in der Schwarzen Wacht möchte, dass Ihr nach Voltarus geht und all das erledigt, was Drakuru Euch aufgibt. Während Ihr dort seid, sollt Ihr 5 geerntete Seuchenkristalle stehlen.","","Kehrt zu Stefan in der Schwarzen Wacht zurück, falls Ihr Euren bezauberten Halsreif verlieren solltet, und Ihr werdet Ersatz bekommen."}}
D[12678] = {"Leid wird vom Chaos getrieben",{"Prinz Valanar in der Todesbresche befiehlt Euch, 10 Scharlachrote Kreuzfahrer oder Scharlachrote Arbeiter, und 10 Bürger von Havenau zu töten."}}
D[12679] = {"Heute Abend speisen wir in Havenau",{"Orithos der Himmelsverdunkler in der Todesbresche möchte, dass ihr 15 Saronitpfeile beschafft."}}
D[12680] = {"Grand Theft Palomino",{"Salanar der Reiter in der Todesbresche möchte, dass Ihr ein Pferd aus den Ställen von Havenau stehlt und es zu ihm bringt."}}
D[12681] = {"Reagenzagent",{"Bringt Colvin Norrington an Dorians Außenposten 5 verdrehte Rocklauen."}}
D[12682] = {"Unerforschtes Gebiet (DEPRECATED)"}
D[12683] = {"Brenn darauf zu helfen",{"Colvin Norrington bei Dorians Außenposten möchte, dass Ihr 5 Proben Hydrasputum sammelt und 5 Bittertidenhydras tötet."}}
D[12684] = {"Das Blut eines toten Gottes",{"Har'koa hat Euch gebeten, 7 Blutproben von Mam'toth zu sammeln. Bringt sie zu ihr am Altar von Har'koa."}}
D[12685] = {"Man erntet, was man sät",{"Erschlagt den ausgelaugten Propheten von Quetz'lun und informiert anschließend Hexendoktor Khufu in Zim'Torga."}}
D[12686] = {"Null Toleranz",{"Drakuru in Voltarus möchte, dass Ihr zum Reliquiar des Schmerzes geht und das Ermächtigungsszepter auf einen Diener von Drakuru anwendet, um anschließend mit seiner Hilfe Darmuk zu töten."}}
D[12687] = {"Ins Reich des Schattens",{"Salanar der Reiter auf der Todesanhöhe hat Euch dazu herausgefordert, einen dunklen Reiter von Acherus zu erschlagen und sein Todesstreitross von Acherus in Eure Gewalt zu bringen.","","Bringt das Todesstreitross von Acherus auf die Todesanhöhe und lasst den Ruf des Reiters ertönen, um Salanar herbeizurufen."}}
D[12688] = {"Ein Desaster konstruieren",{"Helft Ingenieurin Helice, aus Schwindelgrins' Grabungsstätte zu entkommen, und sprecht dann mit Hemet Nesingwary in Nesingwarys Basislager."}}
D[12689] = {"Hand der Orakel"}
D[12690] = {"Brennstoff",{"Drakuru in Voltarus möchte, dass Ihr das Szepter des Befehls auf die aufgeblähten Monstrositäten anwendet und dann ihre Fähigkeiten dazu einsetzt, um 60 Schädelberster der Drakkari zu töten und 3 Häuptlinge der Drakkari hervorzulocken.","","Die Häuptlinge tauchen erst dann auf, wenn genug Schädelberster getötet wurden."}}
D[12691] = {"Eine verwitterte Kiste",{"Erbeutet einen gewaltigen, steinernen Schlüssel von einem der Sholazarwächter in der Nähe und bringt ihn zur verwitterten Kiste bei der Warte der Schöpfer."}}
D[12692] = {"Rückkehr des Lichjägers",{"Kehrt zum Hügel der Wildherzen zurück und sprecht mit dem Ältesten Harkek."}}
D[12693] = {"Wolvar-Fraktionswahl Fährtenleser"}
D[12694] = {"Orakel-Fraktionswahl Fährtenleser"}
D[12695] = {"Rückkehr der netten Trockenhaut",{"Kehrt zum Baldachin der Regenrufer zurück und sprecht mit dem Hochorakel Soo-say."}}
D[12696] = {"Luftüberwachung",{"Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht."}}
D[12697] = {"Gothik der Ernter",{"Sprecht mit Gothik dem Ernter in der Todesbresche."}}
D[12698] = {"Das Geschenk, das nicht aufhört zu schenken",{"Gothik der Ernter in der Todesbresche hat Euch die Gabe des Ernters gegeben, um sie gegen die Scharlachroten Minenarbeiter einzusetzen. Erschafft mithilfe des Geräts 5 Scharlachrote Ghule und kehrt anschließend zu Gothik zurück."}}
D[12699] = {"Der peinliche Vorfall",{"Sucht nach Vics Schlüssel im See am Flussnabel."}}
D[12700] = {"Gelegenheitsangriff",{"Sprecht mit Prinz Valanar in der Todesbresche."}}
D[12701] = {"Massaker am Lichtgipfel",{"Prinz Valanar in der Todesbresche hat Euch befohlen, 100 Scharlachrote Verteidiger zu vernichten."}}
D[12702] = {"Hühnerparty!",{"Fangt 12 entflohene Hühner für Ältesten Harkek auf dem Hügel der Wildherzen."}}
D[12703] = {"Kartaks Wut",{"Bringt eine reine Probe vom Blut der Orakel zum Altar von Kartak, um Kartak zu beschwören. Mit der Hilfe von Kartaks geteilten Kräften sollt Ihr für Schamanen Jakjek in Kartaks Stellung 50 in der Nähe befindliche, funkenbesprühte Gorlocs töten."}}
D[12704] = {"Besänftigung des großen Regensteins",{"Das Hochorakel Soo-say im Baldachin der Regenrufer möchte, dass Ihr einen Gefährten auswählt und 6 glänzende Kostbarkeiten sammelt.","","Sprecht noch einmal mit dem Hochorakel Soo-say, um Euch die Hilfe eines Eurer früheren Gefährten zusichern zu lassen."}}
D[12705] = {"Wille der Titanen",{"Erlangt einen getrübten Kristall von den Wolvar in der Nähe der Zuflucht der Funkenbesprühten und bringt ihn zum großen Blitzstein, um Soo-holu zu beschwören. Tötet mithilfe Soo-holus geteilter Macht 50 in der Nähe befindliche Wolvar der Wildherzen und kehrt anschließend zu Blitzrufer Soo-met in der Nähe des großen Donnersteins zurück."}}
D[12706] = {"Sieg an der Todesbresche!",{"Liefert Prinz Valanars Bericht bei Hochlord Darion Mograine in Acherus: der Schwarzen Festung ab."}}
D[12707] = {"Wollige Gerechtigkeit",{"Skalpierer Ahunae in Zim'Torga möchte, dass Ihr mithilfe des Medaillons von Mam'toth ein tobendes Mammut beruhigt, um dann auf ihm zu reiten. Anschließend sollt Ihr 12 Jünger von Mam'toth zu Tode trampeln."}}
D[12708] = {"Verzauberte Tikikrieger",{"Elementzähmerin Dagoda in Zim'Torga möchte, dass Ihr 12 verzauberte Tikikrieger zerstört."}}
D[12709] = {"Verhexte Behälter",{"Chronist To'kini in Zim'Torga möchte, dass Ihr 12 Behälter der Festung Zol'Maz sammelt."}}
D[12710] = {"Enthüllung",{"Drakuru in Voltarus möchte, dass Ihr den Teleporter benutzt, der in sein oberes Gemach führt."}}
D[12711] = {"Herrenlose Post"}
D[12712] = {"Der Schlüssel des Kriegslords Zol'Maz",{"Har'koa in Zim'Torga möchte, dass Ihr den Schlüssel des Kriegslords Zol'Maz beschafft."}}
D[12713] = {"Verrat",{"Stefan in der Schwarzen Wacht möchte, dass Ihr Drakuru besiegt.","","Falls Ihr Euren bezauberten Halsreif verlieren solltet, dann kehrt zu Stefan in der Schwarzen Wacht zurück und besorgt Euch einen neuen."}}
D[12714] = {"Der Wille des Lichkönigs",{"Kehrt zur Todesbresche zurück und meldet Euch bei Prinz Valanar."}}
D[12715] = {"Die Krypta der Erinnerung",{"Meldet Euch bei Prinz Keleseth in der Krypta der Erinnerung."}}
D[12716] = {"Des Seuchenfürstens Gesuch",{"Noth der Seuchenfürst möchte, dass Ihr ihm 1 leeren Kessel, 1 Eisenkette und 10 Kreuzfahrerschädel bringt."}}
D[12717] = {"Noths Spezialgebräu",{"Werft den Haufen Kreuzfahrerschädel in den Seuchenkessel."}}
D[12718] = {"Mehr Totenschädel fürs Gebräu"}
D[12719] = {"Es gibt kein Entrinnen",{"Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, Bürgermeister Quimby zu töten und die Registratur von Neu-Avalon zu beschaffen."}}
D[12720] = {"Wie man Freunde gewinnt und Feinde beeinflusst",{"Prinz Keleseth in der Krypta der Erinnerung hat Euch befohlen, die Wahrheit über den \"Scharlachroten Morgen\" herauszufinden.","","Nehmt Keleseths Überzeuger aus der juwelenbesetzten Schatulle und bringt damit einen Scharlachroten Kreuzzügler zum Reden."}}
D[12721] = {"Randale",{"Har'koa in Zim'Torga möchte, dass Ihr Akali befreit und danach Hexendoktor Khufu in Zim'Torga benachrichtigt."}}
D[12722] = {"Wie Lämmer zur Schlachtbank",{"Baron Totenschwur in der Krypta der Erinnerung hat Euch befohlen, 10 Soldaten des Scharlachroten Kreuzzugs und 15 Bürger von Neu-Avalon zu erschlagen."}}
D[12723] = {"Hinter den Linien der Scharlachroten",{"Meldet Euch bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon."}}
D[12724] = {"Der Pfad des gerechten Kreuzfahrers",{"Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, die Patrouillenaufstellung von Neu-Avalon aus der Scharlachroten Festung zu stehlen."}}
D[12725] = {"Im Tode vereint",{"Sucht nach Koltira Todesweber in der Scharlachroten Festung."}}
D[12726] = {"Lied von Wind und Wasser",{"Soo-nee möchte, dass Ihr die Trommeln des Sturms auf dem Sturmherrenschelf verwendet und Haifun dabei helft, 3 Sturmwiedergänger und 3 Aqueousgeister zu verschlingen."}}
D[12727] = {"Blutiger Ausbruch",{"Erschlagt Hochinquisitor Valroth und bringt Valroths Kopf zu Thassarian in der Scharlachroten Taverne in Neu-Avalon."}}
D[12728] = {"Die Klamm beobachten: Höhlen der Winterflossen",{"Bibliothekar Garren vom Bernsteinflöz möchte, dass Ihr zu den Höhlen der Winterflossen geht und dort das Arkanometer benutzt."}}
D[12729] = {"Die Götter haben gesprochen",{"Bringt das unbefleckte Herz des Wächters und die stürmische Essenz des Behüters zu Har'koa in Zim'Torga."}}
D[12730] = {"Beschwörung bei Zol'Heb",{"Har'koa in Zim'Torga möchte, dass Ihr den Propheten von Akali tötet."}}
D[12732] = {"Des Herzbluts Stärke",{"Bringt eine Phiole voll Sonnenstrahlherzblut zu Rejek auf dem Hügel der Wildherzen."}}
D[12733] = {"Herausforderung des Todes",{"Olrun die Schlachtenruferin hat Euch befohlen, 5 Duelle mit anderen Todesrittern zu gewinnen.","","Ihr könnt gegen Initianden der Todesritter oder gegen Spieler kämpfen."}}
D[12734] = {"Rejek: Erstes Blut",{"Taucht Rejeks Klinge in das Blut der Leichen von einer saphirblauen Schwarmwespe, einem Hartknöchelstürmer und 3 Mitgliedern des Stamms der Nebelflüsterer - es können entweder Orakel der Nebelflüsterer oder Krieger der Nebelflüsterer sein. Kehrt zu Rejek auf dem Hügel der Wildherzen zurück, sobald die Aufgabe abgeschlossen ist."}}
D[12735] = {"Ein reinigendes Lied",{"Soo-nee beim Baldachin der Regenrufer will, dass Ihr am Bittertidensee, am Tausendwinterfluss und am Flussnabel das läuternde Glockenspiel erklingen lasst und die bösen Geister tötet, die das Wasser dort verschmutzen."}}
D[12736] = {"Lied der Besinnung",{"Soo-nee im Baldachin der Regenrufer möchte, dass Ihr das Didgeridoo des Nachsinnens auf der Spitze der Schimmersäule, der Sonnenstrahlsäule, der Mooslichtsäule und der Himmelszeltsäule verwendet."}}
D[12737] = {"Lied der Fruchtbarkeit",{"Soo-nee beim Baldachin der Regenrufer möchte, dass Ihr zum Sturmherrenschelf nordwestlich des Horts der Schöpfer geht und das Horn der Fruchtbarkeit neben 8 Hügeln durchtränkten Mutterbodens blast."}}
D[12738] = {"Schrei nach Rache!",{"Meldet Euch bei Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme."}}
D[12739] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Malar Tapferhorn hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12740] = {"Fallschirme für den Argentumkreuzzug",{"Kommandant Falstaav in der Argentumwache möchte, dass Ihr 10 Argentumkreuzfahrer oder Argentumschildmänner draußen auf dem Hof mit Fallschirmen versorgt."}}
D[12741] = {"Kraft des Sturms",{"Sammelt 3 Essenzen des Monsuns und 3 Essenzen des Sturms ein und bringt sie zum Sturmschrein. Kehrt mit der wahren Macht des Sturms zu Rejek auf dem Hügel der Wildherzen zurück."}}
D[12742] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Ellen Stanbrück hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12743] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Yazmina Eichendorn hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12744] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Donovan Dulfrost hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12745] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Goby Blastenheimer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12746] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Valok den Gerechten hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12747] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Lady Eonys hinzurichten - eine gefangene Anhängerin der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12748] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Kug Eisenkiefer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12749] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Iggy Dunkelhauer hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
D[12750] = {"Eine besondere Überraschung",{"Ritterkommandant Seuchenfaust an der Kapelle der Scharlachroten Flamme hat Euch befohlen, Antoine Brack hinzurichten - einen gefangenen Anhänger der Argentumdämmerung im Gefängnis in der Nähe."}}
