D[12752] = {"Verzweifelte Forschung"}
D[12753] = {"Eine verzweifelte Allianz"}
D[12754] = {"Überfall am Rundblick",{"Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon hat Euch befohlen, den Scharlachroten Kurier zu töten und seine Sachen und die Nachricht zu beschaffen."}}
D[12755] = {"Begegnung mit dem Schicksal",{"Orbaz Blutbann hat Euch befohlen, die Nachricht des Scharlachroten Kuriers bei Hochgeneral Abbendis im Hafen des Königs abzuliefern."}}
D[12756] = {"Der Scharlachrote Ansturm tritt hervor",{"Liefert das Buch \"Der Weg der Erlösung\" bei Orbaz Blutbann in der Scharlachroten Taverne in Neu-Avalon ab."}}
D[12757] = {"Die Armeen des Scharlachroten Ansturms rücken näher...",{"Liefert das Buch \"Der Weg der Erlösung\" bei Hochlord Darion Mograine in \"Acherus: der Schwarzen Festung\" ab."}}
D[12758] = {"Des Helden Helm",{"Besorgt Sprengstoff der Venture Co. von der Venture Company in Schwindelgrins' Grabungsstätte und benutzt ihn, um den Kopf eines Sturmbetrachters zu erhalten. Bringt Rejek beim Hügel der Wildherzen den Kopf des Sturmbetrachters."}}
D[12759] = {"Instrument des Krieges",{"Holt einige von Zepiks Fallen aus seiner Truhe in Kartaks Stellung. Verwendet die Fallen, um 50 der sich in der Nähe aufhaltenden, funkenbesprühten Gorlocs zu töten, dann kehrt zu Schamane Jakjek in Kartaks Stellung zurück."}}
D[12760] = {"Geheime Kraft der Wildherzen",{"Nutzt den geheimen Trank der Wildherzen und tötet mit der Kraft des Tranks 30 funkenbesprühte Gorlocs um Kartaks Stellung herum."}}
D[12761] = {"Beherrschen der Kristalle",{"Erlangt die Verteidigung des Kristalls in der Zuflucht der Funkenbesprühten und verwendet sie, um 50 in der Nähe befindliche Wildherzwolvar zu töten. Kehrt zu Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten zurück, sobald diese Aufgaben abgeschlossen sind."}}
D[12762] = {"Macht der Großen",{"Ladet den schlafenden polierten Kristall an der offenen Lebensblutsäule. Reist zur Zuflucht der Funkenbesprühten und verwendet die Kraft des Kristalls, um 30 der sich in der Nähe aufhaltenden Wolvar der Wildherzen zu töten. Sprecht anschließend mit Blitzrufer Soo-met in der Zuflucht der Funkenbesprühten."}}
D[12763] = {"Verschiebung von Prioritäten",{"Späher Vor'takh möchte, dass Ihr nach Zul'Drak reist und Euch bei Unteroffizier Riannah an der Lichtbresche meldet.","","Makki Orkan im Lager Oneqwah wird für Euren Transport sorgen."}}
