D[12785] = {"Orgrimmar"}
D[12786] = {"Donnerfels"}
D[12787] = {"Die Unterstadt"}
D[12788] = {"Silbermond"}
D[12789] = {"Auf zur Bresche!",{"Kreuzritter Valus bei der Lichtwarte möchte, dass Ihr Euch bei Unteroffizier Riannah in Lichtbresche in Zul'Drak meldet."}}
D[12790] = {"Hin- und zurückkommen: mit Magie",{"Erzmagierin Celindra am Violetten Tor möchte, dass Ihr den Teleporter zum Kristall der Violetten Wacht und den Teleporter zum Dalarankristall verwendet."}}
D[12791] = {"Das magische Königreich Dalaran",{"Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab."}}
D[12792] = {"Das Wichtigste zuerst",{"Kommandant Kunz in der Argentumwacht möchte, dass Ihr Euch bei Unteroffizier Riannah in der Lichtbresche meldet."}}
D[12793] = {"Rauch am Horizont",{"Khufu in Zim'Torga möchte, dass Ihr zur Lichtbresche reist und Euch bei Unteroffizier Riannah meldet.","","Maaka wird Euch dorthin bringen."}}
D[12794] = {"Das magische Königreich von Dalaran",{"Bringt der Erzmagierin Celindra am Violetten Tor in Dalaran das Signet der Kirin Tor."}}
D[12795] = {"Farbe bekennen",{"Datura Blutrose an der Schwarzen Wacht möchte, dass Ihr mit Kommandant Falstaav in der Argentumwache sprecht."}}
D[12796] = {"Das magische Königreich Dalaran",{"Liefert das Signet der Kirin Tor bei Erzmagierin Celindra am Violetten Tor in Dalaran ab."}}
D[12797] = {"Zurück durchs Tor",{"Bringt die Omegarune zum Avatar von Freya im Katarakt der Regenrufer im Sholazarbecken."}}
D[12798] = {"Schwertkartenset",{"Beschwört mithilfe des Schwertkartensets einen Wahrsager des Dunkelmond-Jahrmarkts und gebt ihm das Set."}}
D[12799] = {"Geister aufsaugen",{"Hauptmann Arnath in Heb'Valok möchte, dass Ihr 5 Einheiten uralten Ektoplasmas von den verlorenen Drakkarigeistern in den Teichen von Zha'jin sammelt."}}
D[12800] = {"Befehl des Lichkönigs",{"Meldet Euch bei Geißelkommandant Thalanor bei Braumanns Mühle."}}
D[12801] = {"Das Licht der Morgendämmerung",{"Besiegt die Streitkräfte der Argentumdämmerung und findet das Licht der Morgendämmerung.","","Meldet Euch bei Hochlord Darion Mograine, falls Ihr überleben solltet."}}
D[12802] = {"Mein Herz liegt in Euren Händen",{"Drakuru möchte, dass Ihr ihm das Herz der Uralten zur Drak'atal Passage bringt.","","Um das Elixier verwenden zu können, müsst Ihr 5 verzweifelte Mojo sammeln."}}
D[12803] = {"Naturgewalt",{"Begebt Euch zur Seuchenfront zwischen dem Katarakt der Regenrufer und den verlorenen Landen im Sholazarbecken und sucht den Avatar von Freya."}}
D[12804] = {"Ein Steak für Jäger",{"Bringt 5 Langhalsgrasfresser-Steaks zu Korg dem Spalter in Nesingwarys Basislager."}}
D[12805] = {"Einfangen von Lebenskraft",{"Der Avatar von Freya möchte, dass Ihr Euch zur Versprengten Scherbe im Südosten begebt und den Edelstein der Lebenskraft an 8 vernichteten Lebensblutelementaren verwendet."}}
D[12806] = {"Zur Todesanhöhe so schnell Ihr könnt!",{"Meldet Euch bei Lordkommandant Arete auf der Todesanhöhe in Eiskrone."}}
D[12807] = {"Was bis jetzt geschehen ist...",{"Lauscht Lordkommandant Aretes Erzählung über die Todesanhöhe."}}
D[12808] = {"Eine verzweifelte Allianz"}
D[12809] = {"Eisenschmiede"}
D[12810] = {"Blut im Wasser",{"Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr die Blutblase mit dem Blut von 10 ausgehungerten Haien füllt."}}
D[12811] = {"Verzweifelte Forschung"}
D[12812] = {"Orgrimmar"}
D[12813] = {"Erhebt euch von den Toten!",{"Setaal Dunkelheiler auf der Todesanhöhe hat Euch die Tinktur des Dunkelheilers gegeben. Träufelt sie auf 10 beliebige Leichen der Einheiten des Scharlachroten Ansturms, die Ihr im Hafen des Ansturms findet."}}
D[12814] = {"Ihr werdet einen Greifen brauchen",{"Bringt Uzo Todesrufer auf der Todesanhöhe einen Greifen des Ansturms."}}
D[12815] = {"Flugsperrzone",{"Uzo Todesrufer auf der Todesanhöhe möchte, dass Ihr 10 Greifenreiter des Ansturms tötet."}}
D[12816] = {"Untersucht die Geißel bei Silbermond",{"Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb von Silbermond und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers."}}
D[12817] = {"Untersucht die Geißel bei der Exodar",{"Sammelt drei dunkle nekrotische Steine von den Dienern der Geißel außerhalb der Exodar und untersucht die leuchtenden Runenkreise in der Nähe ihres Lagers. Kehrt anschließend zu Leutnant Kregor zurück."}}
D[12818] = {"Aufräumen",{"Jeer Funksockel auf dem K3 hätte gerne 10 verbrannte Trümmer."}}
D[12819] = {"Nur einen Minenwurf entfernt",{"Jeer Funksockel am K3 bittet Euch, dass Ihr Funksockels Werkzeuge aus seinem Minenfeld holt."}}
D[12820] = {"Zwölf auf einen Streich",{"Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor 12 Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger."}}
D[12821] = {"Zellenblocktango",{"Ricket am K3 möchte, dass Ihr den Transporterakku findet und damit die Transporterplatte in Garms Erhebung aktiviert."}}
D[12822] = {"Kenne keine Furcht",{"Ricket auf dem K3 möchte, dass Ihr 6 Garmwächter und 8 schneeblinde Anhänger tötet."}}
D[12823] = {"Ein perfekter Plan",{"Gino auf Garms Erhebung möchte, dass Ihr das dichtgepackte Sprengstoffbündel in der Nähe von Frostgeweides Altar anbringt und anschließend Tormar Frostgeweide tötet. Danach sollt Ihr entkommen, bevor die Höhle über Euch einbricht."}}
D[12824] = {"Explosive Stimmung",{"Begebt Euch zu Ricket am K3."}}
D[12825] = {"Ein Zeichen des Dankes",{"[PLACEHOLDER] Use mini-plane to kamakazi on the gnoll leader."}}
D[12826] = {"Leicht instabil",{"Liefert Jeers verbesserte Landminen bei Ricket am K3 ab."}}
D[12827] = {"Rationen-Recycling",{"Ricket am K3 bittet Euch, 16 getrocknete Gnollmahlzeiten von den wilden Hügelgnollen in der Nähe zu beschaffen."}}
D[12828] = {"Welch Eingebung!",{"Ricket auf dem K3 möchte, dass ihr ein I.D.S.V. besorgt, damit ein Mammut in die Luft jagt und 8 Stücke herzhaftes Mammutfleisch einsammelt."}}
D[12829] = {"Einrücken",{"Tore Rumpelschlüssel vor der Kristallnetzhöhle möchte, dass Ihr 12 Kristallnetzspinnen tötet."}}
D[12830] = {"Rückgewinnung des Erzes",{"Tore Rumpelschlüssel vor der Kristallnetzhöhle hätte gerne, dass Ihr 5 Proben unreines Saroniterz sammelt."}}
D[12831] = {"Nur teilweise vergessen",{"Ein verletzter Goblinminenarbeiter in der Kristallnetzhöhle möchte, dass Ihr ihm einen Eisspitzengiftbeutel von einer Eisspitzenspinne bringt."}}
D[12832] = {"Bittere Trennung",{"Begleitet den verletzten Goblinminenarbeiter aus der Kristallnetzhöhle und meldet Euch danach bei Ricket in K3."}}
D[12833] = {"Überbestand",{"Ricket in K3 wünscht, dass Ihr mithilfe der verbesserten Landminen Garms Bann vor den Angreifern verteidigt. Zu den Angreifern zählen Garmeindringlinge sowie schneeblinde Anhänger."}}
D[12834] = {"Weder Regen noch Schnee noch explodierender Flieger",{"[PLACEHOLDER] Test cold-weather bomber on giant."}}
D[12835] = {"Voll ausgewachsen",{"[PLACEHOLDER] Test Grown Up Jormungar on Giant"}}
D[12836] = {"Zeichen der Dankbarkeit",{"Ricket am K3 möchte, dass Ihr Knarzfell tötet."}}
D[12837] = {"Tore hat die Waren",{"[PLACEHOLDER] Meldet Euch bei Tore"}}
D[12838] = {"Informationsbeschaffung",{"Aurochs Grimmbann auf der Todesanhöhe möchte, dass Ihr 5 Geheimdokumente des Ansturms beschafft."}}
D[12839] = {"Der große Plan (des Admirals)",{"Bringt dem Lordkommandanten Arete auf der Todesanhöhe die Nachricht vom Großadmiral."}}
D[12840] = {"Streng vertraulich",{"Lordkommandant Arete auf der Todesanhöhe möchte, dass Ihr Informationen aus den Kapitänen Welsington und Hartford herausprügelt."}}
D[12841] = {"Der Handel der Alten",{"Lok'lira die Greisin in der verlassenen Mine möchte, dass Ihr Yrkvinns Runen von Aufseherin Syra holt."}}
D[12842] = {"Runen schmieden: Vorbereitung auf den Kampf",{"Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, mithilfe Eurer Fertigkeit 'Runen schmieden' eine beliebige Rune in Eure runenbeschriebene Seelenklinge zu prägen.","","Ihr könnt die Prägung auf Eurer Waffe jederzeit durch eine andere ersetzen, solange Ihr Euch in der Nähe einer Runenschmiede befindet."}}
D[12843] = {"Sie haben unsere Männer!",{"Gretchen Zischelfunken möchte, dass Ihr nach Sifreldar geht und 5 Goblingefangene befreit."}}
D[12844] = {"Ausrüstungsbergung",{"Gretchen Zischelfunken möchte, dass Ihr 8 Teile der K3-Ausrüstung aus Sifreldar holt, das nördlich des K3 liegt."}}
D[12845] = {"Dalaran Teleport Crystal Flag"}
D[12846] = {"Lasst keinen Goblin zurück",{"Findet den Eingang zu den verlassenen Minen im Norden von Sifreldar und sucht nach Hinweisen auf Zeev Zischelfunkens Aufenthaltsort."}}
D[12847] = {"Zweite Chancen",{"Tötet Erzbischof Landgren und beschwört anschließend Aretes Tor in Gegenwart seiner Leiche. Sprecht mit Lordkommandant Arete im Hafen des Ansturms, sobald er sein Verhör mit dem Geist des Erzbischofs beendet hat."}}
D[12848] = {"Der endlose Hunger",{"Instrukteur Razuvious in der Schwarzen Festung befiehlt Euch, einen unwürdigen Initianden zu befreien und ihn kaltblütig umzubringen!","","Entweder ist es Euer oder ihr Leben!"}}
D[12849] = {"Die Macht des Blutes, des Frosts und der unheiligen Kraft"}
D[12850] = {"Meldet Euch bei Geißelkommandant Thalanor",{"Meldet Euch beim Geißelkommandanten Thalanor auf dem Balkon auf der ersten Ebene der Schwarzen Festung."}}
D[12851] = {"Eiskalte Jagd",{"Brijana in Brunnhildar möchte, dass Ihr Eiszahn benutzt und 7 Frostworge und 15 Frostriesen im uralten Wintertal tötet."}}
D[12852] = {"Den Admiral aufgespürt",{"Lordkommandant Arete möchte, dass Ihr Euch um Großadmiral Westwind kümmert. Kehrt danach zum Lordkommandanten auf die Todesanhöhe zurück."}}
D[12853] = {"Luxusreise!",{"Sprecht mit Jeer Funksockel am K3 in den Sturmgipfeln."}}
D[12854] = {"Auf Branns Spuren",{"Beschafft die in Sackleinen gewickelte Notiz aus Branns Lager und bringt sie zu Archäologe Andorin in der Eisfestung."}}
D[12855] = {"Den Täter ausschnüffeln",{"Nutzt das Frosthundhalsband im Verlassenen Lager um herauszufinden, wer Branns Habseligkeiten an sich genommen hat. Wenn Ihr sie finden konntet, setzt das Kommunikationsgerät ein und sprecht mit wem auch immer Ihr Kontakt bekommt."}}
D[12856] = {"Kaltherzig",{"Brijana gleich östlich von Brunnhildar möchte, dass Ihr nach Dun Niffelem fliegt, 3 gefangene Protodrachen befreit und 9 gefangene Brunnhildar rettet."}}
D[12857] = {"Gesucht: Rachmähnes Flosse",{"Beschafft Rachmähnes Flosse und bringt sie zu Häuptling Zornklaue in der Lichtbresche in Zul'Drak."}}
D[12858] = {"Puzzleteile",{"Sucht 6 Fragmente der Scheibe des Erfinders und setzt sie damit wieder zusammen."}}
D[12859] = {"Das Allerneueste: Feuer noch immer heiß!",{"Schamanenältester Moky in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe des Feuerlöschers der Zornklauen 15 Hüttenfeuer im Zornklauenbau löscht."}}
D[12860] = {"Daten schürfen",{"Nutzt die Scheibe des Erfinders, um 7 Teile der versteckten Daten aus den Datenbanken zu beschaffen."}}
D[12861] = {"Die Trolle sind durchgedreht!",{"Häuptling Zornklaue in der Lichtbresche in Zul'Drak möchte, dass Ihr mithilfe der \"Schlossöffner\" von Drakuru, welche die verschiedenen Drakurutrolle bei sich tragen, 8 gefangene Zornklauen befreit."}}
D[12862] = {"Wenn alles andere versagt",{"Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen."}}
D[12863] = {"Danksagung",{"Bringt Glorthal Steifbart in der Eisfestung die Kiste mit Heilvorräten."}}
D[12864] = {"Vermisste Späher",{"Glorthal in der Frostfestung hat darum gebeten, im Tal namens Bors Atem und bei Bors Sturz nach Anzeichen für die vermissten Späher der Frosterben zu suchen."}}
D[12865] = {"Treue Gefährten",{"Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 8 Stück frisches Rhinozerosfleisch beschafft und es an die Sturmspitzenadler auf den Gipfeln über der Stadt verfüttert."}}
D[12866] = {"Den Aggressoren Einhalt gebieten",{"Glorthal Steifbart in der Eisfestung möchte, dass Ihr 8 Frostfederkreischerinnen und 8 Frostfederhexen tötet."}}
D[12867] = {"Babydiebe",{"Fjorlin Frostbraue in der Eisfeste möchte, dass Ihr 15 Eier eines Sturmspitzenadlers zurückbringt."}}
D[12868] = {"Sirana Eisschrei",{"Glorthal Steifbart in der Eisfestung möchte, dass Ihr Sirana Eisschrei tötet."}}
D[12869] = {"Zu weit getrieben",{"Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr auf einem Sturmspitzenadler 16 Sturmgipfelwyrm in den Fußmarschen niederstreckt."}}
D[12870] = {"Uralte Relikte",{"Bringt 10 Relikte von Ulduar zu Rork Spitzkinn in die Eisfestung."}}
D[12871] = {"Hilfe von der Forscherliga",{"Bringt Norgannons Schale zu Lagnus in die Eisfestung."}}
D[12872] = {"Norgannons Schale",{"Beschafft Euch Norgannons Schale von Archivar Mechaton."}}
D[12873] = {"Der König der Frosterben",{"Sprecht mit Yorg Sturmherz in der Eisfestung."}}
D[12874] = {"Eifer der Frosterben",{"Yorg Sturmherz in der Eisfestung hat Euch gebeten, mit Fjorlin Frostbraue zu sprechen und Euch der Herausforderung zu stellen."}}
D[12875] = {"Ein erfahrener Führer",{"Macht Drom Frostgriff ausfindig."}}
D[12876] = {"Unwillkommene Gäste",{"Fjorlin Frostbraue in der Eisfestung möchte, dass Ihr 10 Sturmgeschmiedete Eindringlinge tötet."}}
D[12877] = {"Der einsame Wächter",{"Beschafft Frostgriffs Siegelring von einem der Eisenzwergüberwacher und bringt ihn zu Creteus in den Fußmarschen."}}
D[12878] = {"Das versteckte Relikt",{"Creteus in den Fußmarschen hat Euch Informationen zukommen lassen, mit deren Hilfe Ihr Norgannons Kern finden könnt. Macht Euch auf den Weg dorthin."}}
D[12879] = {"Zorn des Frosterbenkönigs",{"Bringt Norgannons Kern zu Creteus in die Fußmarschen."}}
D[12880] = {"Der Meisterforscher",{"Bringt Norgannons Kern zu Brann Bronzebart in die Maschine der Schöpfer."}}
D[12881] = {"Die Gebrüder Bronzebart"}
D[12882] = {"Uralte Relikte",{"Ihr befindet Euch auf dieser Quest."}}
D[12883] = {"Befehle von Drakuru",{"Bringt Drakurus Befehle zu Kreuzfahrerlord Lantinga in der Lichtbresche in Zul'Drak."}}
D[12884] = {"Die Schwarze Wacht",{"Liefert Drakurus Befehle bei Stefan Vadu in der Schwarzen Wacht in Zul'Drak ab."}}
D[12885] = {"Die Verbannten von Ulduar",{"Sprecht mit Bergfels dem Steinformer in Bergfels' Zuflucht."}}
D[12886] = {"Der Drakkensryd",{"Verwendet die Hyldnirharpune, um 10 Drachenreiterinnen des Hildarthings im Tempel der Stürme zu besiegen. Wendet die Hyldnirharpune auf ein Säulenornament an, um den Drakkensryd zu verlassen. Sprecht anschließend mit Thorim, solltet Ihr erfolgreich gewesen sein."}}
D[12887] = {"Nichts als Spaß und Spiele",{"Zerstört das Okular und erstattet danach Baron Splitter im Schattengewölbe Bericht."}}
D[12888] = {"SCHROTT-E",{"Bringt die Zugriffskarte für SCHROTT-E sowie 4 Hand voll Kobaltbolzen und 5 überladene Kondensatoren zu SCHROTT-E in die Bibliothek des Erfinders."}}
D[12889] = {"Die Prototypenkonsole",{"Benutzt die Prototypenkonsole in der Bibliothek des Erfinders."}}
D[12890] = {"Wenn Größe von Bedeutung wäre..."}
D[12891] = {"Ich habe da eine Idee, aber zuerst...",{"Baron Splitter im Schattengewölbe hat Euch gebeten, eine Kultistenrute, einen Monstrositätenhaken, ein Spukseil und 5 Geißelessenzen zu besorgen."}}
D[12892] = {"Nichts als Spaß und Spiele",{"Zerstört das Okular und erstattet Bericht bei Baron Splitter im Schattengewölbe."}}
D[12893] = {"Befreit Euren Geist",{"Baron Splitter im Schattengewölbe möchte, dass Ihr den Herrschaftsstab auf die Leichen von Ekel, Lady Nachtwald und dem Springer anwendet."}}
D[12894] = {"Lager der Kreuzfahrer",{"Sucht Kreuzfahrer MacKellar im Lager der Kreuzfahrer in Zul'Drak auf."}}
D[12895] = {"Der verschwundene Bronzebart",{"Ihr befindet Euch auf dieser Quest."}}
D[12896] = {"Wenn man ihn nicht überzeugen kann",{"Besiegt General Lichtbann und informiert anschließend Thassarian an Bord der Himmelsbrecher über Euren Erfolg."}}
D[12897] = {"Wenn man ihn nicht überzeugen kann...",{"Besiegt General Lichtbann und berichtet dann Koltira Todesweber an Bord des Kanonenboots Orgrims Hammer von Eurem Erfolg."}}
D[12898] = {"Das Schattengewölbe",{"Meldet Euch bei Baron Splitter im Schattengewölbe."}}
D[12899] = {"Das Schattengewölbe",{"Meldet Euch bei Baron Splitter im Schattengewölbe zurück."}}
D[12900] = {"Ein Geschirr anfertigen",{"Astrid Björnrittar aus Brunnhildar möchte, dass Ihr 3 Bälge von Eismähnenyetis besorgt."}}
D[12901] = {"Aus nichts etwas herstellen",{"Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr 10 Stück Metallschrott der Geißel beschafft."}}
D[12902] = {"Auf der Suche nach Antworten",{"Durchsucht den Zornklauenbau nach Hinweisen darüber, wer oder was die Angriffe gegen die Wolvar der Zornklauen eingeleitet hat."}}
D[12903] = {"Dafür sind Freunde da...",{"Kreuzfahrer MacKellar im Lager der Kreuzfahrer möchte, dass Ihr nach Kreuzfahrer Dargath, Gerk und Burr sucht."}}
D[12904] = {"Das Licht verwehrt mir meine Rache",{"Gerk in Thryms Ende in Zul'Drak möchte, dass Ihr 15 Vargul tötet."}}
D[12905] = {"Mildred die Grausame",{"Sprecht mit Mildred der Grausamen in der verlassenen Mine."}}
D[12906] = {"Disziplin",{"Mildred die Grausame an der verlassenen Mine möchte, dass Ihr die Disziplinarrute auf 6 erschöpfte Vrykul anwendet."}}
D[12907] = {"Exempel statuieren",{"Mildred die Grausame in der verlassenen Mine möchte, dass Ihr Garhal tötet."}}
D[12908] = {"Eine bestimmte Gefangene",{"Bringt Mildreds Schlüssel zu Lok'lira der Greisin in die verlassene Mine."}}
D[12909] = {"Der Nase trauen",{"Sprecht mit Khaliisi am Fuße des Berges östlich der Absturzstelle Grom'ash."}}
D[12910] = {"Den Täter ausschnüffeln",{"Schwingt Euch auf Frostbeißer und folgt der Fährte von Branns Notiz bis zu ihrem Ausgangspunkt. Beschafft anschließend Branns Kommunikator und stellt mit seiner Hilfe Kontakt mit Brann Bronzebart her."}}
D[12911] = {"Kill Credit Test",{"/wave at Kill Credit Test"}}
D[12912] = {"Ein großer Sturm rückt an",{"Gymer, König der Sturmriesen, hat Euch gebeten, einen Weg zu finden, ihn aus seinem Käfig zu befreien. Sprecht mit Ingenieur Schilf im Lager der Kreuzfahrer."}}
D[12913] = {"Sprich Orcisch, Mann!",{"Sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash."}}
D[12914] = {"Gymers Rettung",{"Ingenieur Schilf im Lager der Kreuzfahrer in Zul'Drak möchte, dass Ihr ihm 6 Essenzen der Banshees und 6 Einheiten Kieselerde bringt."}}
D[12915] = {"Zäune reparieren",{"Thorim im Tempel der Stürme möchte, dass Ihr Fjorn und 5 Sturmgeschmiedete Eisenriesen in Fjorns Amboss östlich von Dun Niffelem tötet.","","Mit Thorims Glücksbringer der Erde könnt Ihr seine Irdenen zur Unterstützung holen. Zum Benutzen des Glücksbringers benötigt Ihr einen Granitfelsen aus Fjorns Amboss in der Nähe."}}
D[12916] = {"Unsere einzige Hoffnung",{"Sprecht mit Gymer in Thryms Ende in Zul'Drak, nachdem Ihr mit der riesigen Zephyriumladung die Umzäunung der Geißel geöffnet habt, in welcher der Gefangene festgehalten wird."}}
D[12917] = {"Mit der Stimme des Windes sprechen",{"Bringt 5 Stimmen des Windes zu Moteha Windkind an der Absturzstelle Grom'ash."}}
D[12918] = {"Edelsteine perfektionieren",{"Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Ounhulo in Valgarde."}}
D[12919] = {"Die Rache des Sturmkönigs",{"Sprecht mit Gymer, um auf ihm zu reiten.","","Vernichtet 100 Diener der Geißel und Algar den Auserwählten, Thrym und Prinz Navarius. Meldet Euch bei Kreuzfahrer MacKellar im Lager der Kreuzfahrer, falls Ihr erfolgreich sein solltet."}}
D[12920] = {"Brann einholen",{"Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen. Erstattet anschließend Boktar Blutfurie bei der Absturzstelle Grom'ash Bericht.","","Falls Ihr Branns Kommunikator verlieren solltet, dann sprecht mit Moteha Windkind bei der Absturzstelle Grom'ash."}}
D[12921] = {"Tapetenwechsel",{"Trefft Euch mit Lok'lira der Greisin in Brunnhildar."}}
D[12922] = {"Des Veredlers Feuer",{"Ihr müsst 10 wütende Funken von den wutentbrannten Klagegeistern auf dem Frostfeldsee sammeln und anschließend den Amboss bei Fjorns Amboss verwenden."}}
D[12924] = {"Ein Bündnis schließen",{"Ihr sollt nach Dun Niffelem gehen und König Jokkum darum bitten, Thorims Rüstung neu schmieden zu lassen. Nachdem Ihr Jokkums Aufgabe abgeschlossen habt, sollt Ihr mit Njormeld in Dun Niffelem sprechen."}}
D[12925] = {"Missgeburten",{"Thyra Kvinnshal in Brunnhildar möchte, dass Ihr nach Valkyrion geht und Phiolen mit Frostöl von den Streiterinnen von Valkyrions besorgt. Nutzt die Phiolen dann, um 30 verseuchte Eier der Protodrachen zu zerstören."}}
D[12926] = {"Teile des Rätsels",{"Benutzt Branns Kommunikator, um Euch mit Brann Bronzebart in Verbindung zu setzen."}}
D[12927] = {"Daten schürfen",{"Nutzt die Scheibe des Erfinders, um 7 versteckte Daten aus den Datenbanken zu beschaffen."}}
D[12928] = {"Norgannons Schale",{"Beschafft Euch Norgannons Schale von Archivar Mechaton."}}
D[12929] = {"Die Irdenen von Ulduar",{"Sprecht mit Bergfels dem Steinformer in Bergfels’ Zuflucht."}}
D[12930] = {"Seltene Erde",{"Baut mit der Spitzhacke der Irdenen 7 Klumpen verzauberte Erde ab. Bringt anschließend die Erde und 5 Einheiten Froststoff zu Bergfels dem Steinformer in Bergfels' Zuflucht."}}
D[12931] = {"Zurückschlagen",{"Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 10 sturmgeschmiedete Angreifer tötet und anschließend zu ihm zurückkehrt. Ihr könnt entweder sturmgeschmiedete Räuber oder Häscher töten."}}
D[12932] = {"Das Amphitheater der Agonie: Yggdras!",{"Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12933] = {"Das Amphitheater der Agonie: Magnataur!",{"Betretet die Arena im Amphitheater der Agonie und besiegt Stinkbart! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12934] = {"Das Amphitheater der Agonie: Aus einer anderen Welt!",{"Betretet die Arena im Amphitheater der Agonie und besiegt einen der Elementarfürsten! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12935] = {"Das Amphitheater der Agonie: Tuskarrmageddon!",{"Betretet die Arena im Amphitheater der Agonie und besiegt Orinoko Hauerbrecher! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12936] = {"Das Amphitheater der Agonie: Korrak der Blutrünstige!",{"Betretet die Arena im Amphitheater der Agonie und besiegt Korrak den Blutrünstigen! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12937] = {"Unterstützung für die Gefallenen",{"Heilt mithilfe der Vulkanschlammpackung 8 gefallene Irdene Verteidiger und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück."}}
D[12938] = {"Der Herzog",{"Sprecht mit Herzog Lankral im Schattengewölbe."}}
D[12939] = {"Ehrenhafte Herausforderung",{"Herzog Lankral vom Schattengewölbe bittet Euch, die Herausforderungsflagge zu nutzen und 6 Mjordinkrieger zu besiegen."}}
D[12940] = {"Eimer mit Süßigkeiten"}
D[12941] = {"Eimer mit Süßigkeiten"}
D[12942] = {"Reißt ihnen die schwarzen Schwingen aus",{"Iva die Rachsüchtige in Brunnhildar möchte, dass Ihr nach Valkyrion geht und 12 werdende Val'kyr erschlagt."}}
D[12943] = {"Erlass des Schattengewölbes",{"Herzog Lankral vom Schattengewölbe hat angeordnet, dass Ihr den Erlass des Schattengewölbes laut vor Than Ufrang dem Mächtigen vorlest und ihn dann tötet."}}
D[12944] = {"Eimer mit Süßigkeiten"}
D[12945] = {"Eimer mit Süßigkeiten"}
D[12946] = {"Eimer mit Süßigkeiten"}
D[12947] = {"Eimer mit Süßigkeiten"}
D[12948] = {"Der Champion der Agonie",{"Betretet die Arena im Amphitheater der Agonie und besiegt Vladof den Metzger! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12949] = {"Besorgt den Schlüssel",{"Vaelen der Geschundene in Ufranggs Halle hat Euch gebeten, den Schlüssel zu Vaelens Ketten zu besorgen."}}
D[12950] = {"Eimer mit Süßigkeiten"}
D[12951] = {"Gebt dem Baron Bescheid",{"Sprecht mit Baron Splitter im Schattengewölbe."}}
D[12952] = {"Edelsteine perfektionieren",{"Ihr befindet Euch auf dieser Quest."}}
D[12953] = {"Valkyrion muss brennen",{"Benutzt die Harpunenkanone von Valkyrion, um 6 trockene Heuhaufen anzuzünden."}}
D[12954] = {"Das Amphitheater der Agonie: Yggdras!",{"Betretet die Arena im Amphitheater der Agonie und besiegt Yggdras! Kehrt zu Wodin dem Trolldiener zurück, um Eure Belohnung entgegenzunehmen."}}
D[12955] = {"Eliminiert die Konkurrenz",{"Der Springer beim Schattengewölbe möchte, dass Ihr Duelle austragt und Sigrid Eiskind, Efrem den Treuen, Onu'zun und Tinky Dochtpfiff besiegt."}}
D[12956] = {"Ein Funken Hoffnung",{"Ihr sollt das veredelte glänzende Erz zu Thorim in den Tempel des Sturms bringen."}}
D[12957] = {"Sklaven der Sturmgeschmiedeten",{"Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr 6 gefangene Mechagnome befreit und 3 sturmgeschmiedete Zuchtmeister tötet."}}
D[12958] = {"Lieferung: Blutrotes Nephritamulett",{"Kombiniert ein Vrykulamulett mit einem Nephrit und einem Blutstein, um ein blutrotes Nephritamulet herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.","","Vrykulamulette könnt Ihr von jedem Vrykul in Nordend erhalten."}}
D[12959] = {"Lieferung: leuchtende Elfenbeinfigur",{"Kombiniert Elfenbein aus Nordend mit einem Chalzedon und einem Schattenkristall, um eine leuchtende Elfenbeinfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.","","Elfenbein aus Nordend könnt Ihr von jedem Schaufelhauer oder Mammut in Nordend erhalten."}}
D[12960] = {"Lieferung: tückische Sonnenbrosche",{"Kombiniert eine eisenzwergische Brosche mit einem Riesencitrin und einem Sonnenkristall, um eine tückische Sonnenbrosche herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.","","Eisenzwergische Broschen könnt Ihr von jedem Eisenzwerg in Nordend erhalten."}}
D[12961] = {"Lieferung: aufwändige Knochenfigur",{"Kombiniert einen Protodrachenknochen mit einem Sonnenkristall und einem Nephrit, um eine aufwändige Knochenfigur herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.","","Protodrachenknochen könnt Ihr von jedem Protodrachen in Nordend erhalten."}}
D[12962] = {"Lieferung: helles Rüstungsrelikt",{"Kombiniert den Rest einer Elementarrüstung mit einem Blutstein und einem Riesencitrin, um ein helles Rüstungsrelikt herzustellen und es dann zu Jonas Timotheus in Dalaran zu bringen.","","Die Reste einer Elementarrüstung könnt Ihr von jedem Klagegeist in Nordend erhalten."}}
D[12963] = {"Lieferung: unbeständige Sonnenkuriosität",{"Kombiniert eine Geißelkuriosität mit einem Sonnenkristall und einem Schattenkristall, um eine unbeständige Sonnenkuriosität herzustellen und diese dann zu Jonas Timotheus in Dalaran zu bringen.","","Geißelkuriositäten könnt Ihr von jedem Diener der Geißel in Nordend erhalten."}}
D[12964] = {"Das dunkle Erz",{"Bringt 5 Erzproben zu Bergfels dem Steinformer in Bergfels' Zuflucht."}}
D[12965] = {"Lokens Gaben",{"Zerstört Lokens Wut, Lokens Kraft und Lokens Gunst und kehrt dann zu Bergfels dem Steinformer nach Bergfels' Zuflucht zurück."}}
D[12966] = {"Ihr könnt ihn nicht verpassen",{"König Jokkum in Dun Niffelem möchte, dass Ihr zu Fjorns Amboss geht und Njormeld sucht."}}
D[12967] = {"Kampf gegen die Elemente",{"Njormeld wünscht, dass Ihr Snorri zu Fjorns Amboss begleitet und ihm dabei helft, 10 wutentbrannte Klagegeister zu töten."}}
D[12968] = {"Yuldas Torheit",{"Iva die Rachsüchtige aus Brunnhildar möchte, das Ihr Yulda die Sturmwirkerin in Valkyrion tötet."}}
D[12969] = {"Ist das Euer Goblin?",{"Fordert Agnetta Tyrsdottar heraus, um Zeev Zischelfunken zu retten. Kehrt ins Dorf Brunnhildar zu Lok'lira der Greisin zurück, wenn Ihr erfolgreich wart."}}
D[12970] = {"Das Hildarthing",{"Hört Euch den Vorschlag von Lok'lira der Greisin an."}}
D[12971] = {"Sich allen Herausforderern stellen",{"Lok'lira die Greisin in Brunnhildar wünscht, dass Ihr 6 siegreiche Herausforderinnen besiegt."}}
D[12972] = {"Ihr werdet einen Bären brauchen",{"Sprecht mit Brijana, die sich außerhalb von Brunnhildar aufhält."}}
D[12973] = {"Die Gebrüder Bronzebart",{"Begleitet Brann Bronzebart und seine Flugmaschine zur Eisfestung."}}
D[12974] = {"Ruf des Champions!",{"Ihr befindet Euch auf dieser Quest."}}
D[12975] = {"In Gedenken an",{"König Jokkum in Dun Niffelem wünscht, dass Ihr nach Donnerfall geht und 8 Hornfragmente einsammelt."}}
D[12976] = {"Ein Monument für die Gefallenen",{"König Jokkum wünscht, dass Ihr Hodirs Hornfragmente zu Njormeld in Dun Niffelem bringt."}}
D[12977] = {"Hodirs Ruf",{"Ihr müsst am Donnerfall 5 Vorfahren von Niffelem und 5 ruhelose Frosterben besiegen. Lasst dann über ihren Leichen stehend Hodirs Horn ertönen und geht anschließend zurück zu Hodirs Horn in Dun Niffelem."}}
D[12978] = {"Im Angesicht des Sturms",{"Bruor Eisenbann in Bergfels' Zuflucht bittet Euch, 10 Sturmgeschmiedete in Nidavelir zu töten. Tötet Sturmgeschmiedete Champions, Sturmgeschmiedete Magier oder Sturmgeschmiedete Kriegsgolems."}}
D[12979] = {"Rüstung der Dunkelheit",{"Bringt 4 Dunkle Rüstungen zu Bruor Eisenbann in Bergfels' Zuflucht."}}
D[12980] = {"Die Geheimnisse der Rüstung",{"Bringt die dunkle Plattenrüstung zu Mimirs Werkstatt und bittet Tock den Knecht, sie sich näher anzusehen. Kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück, wenn Ihr fertig seid."}}
D[12981] = {"Heiß und kalt",{"Ihr sollt zum Frostfeldsee gehen, die zerbrechlichen Klagegeister dort vernichten und die Essenz des Eises auf den qualmenden Schrott bei Fjorns Amboss anwenden. Anschließend sollt Ihr 6 Trümmer gefrorenen Eisenschrotts sammeln und zu Fjorns Amboss in Dun Niffelem zurückkehren."}}
D[12982] = {"Gefangene der Schwarzen Klinge",{"Vaelen der Geschundene im Schattengewölbe bittet Euch, 8 Gefangene der Schwarzen Klinge zu befreien. Ihr findet sie in den Käfigen in der weiteren Umgebung von Jotunheim."}}
D[12983] = {"Die Letzte ihrer Art",{"Astrid Björnrittar in Brunnhildar wünscht, dass Ihr eine Eisschlundmatriarchin aus der Überwinterungshöhle rettet."}}
D[12984] = {"Valduran der Sturmgeborene",{"Benutzt Bergfels' Kriegshorn, sobald Ihr Valduran den Sturmgeborenen gefunden habt. Besiegt ihn und kehrt anschließend zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück."}}
D[12985] = {"Einen Kopf schmieden",{"Njormeld in Dun Niffelem möchte, dass Ihr mithilfe der Hacke mit Diamantspitze 8 Sturmgeschmiedete Augen von den toten Eisenriesen auf dem Frostfeldsee beschafft und dann anschließend zu ihm zurückkehrt."}}
D[12986] = {"Das Schicksal der Titanen",{"Creteus in den Fußmarschen möchte, dass Ihr zum Tempel des Erfindungsreichtums, Tempel des Winters, Tempel des Lebens und zum Tempel der Ordnung reist und mithilfe der Datenbank jeden Bereich untersucht."}}
D[12987] = {"Hodirs Helm platzieren",{"Njormeld möchte, dass Ihr zur Spitze der nördlich gelegenen Eisspitze in Dun Niffelem fliegt und die Worte auf den Tafeln der Verkündung rezitiert."}}
D[12988] = {"Sabotiert die Schmieden!",{"Sabotiert die Nordblitzschmiede, die Zentralblitzschmiede und die Südblitzschmiede mit Bergfels' Bomben. Kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück."}}
D[12989] = {"Die schleimige Dunkelheit",{"Astrid Björnrittar wünscht, dass Ihr 8 gefräßige Jormungar in der Überwinterungshöhle östlich des Dorfes Brunnhildar tötet."}}
D[12990] = {"Das Wurmloch",{"Bringt Jonathan LeCraft die gesuchten Materialien, um einen schnellen Tod zu vermeiden, und erhaltet einen coolen neuen Zauberspruch."}}
D[12991] = {"Sie treffen, wo es wehtut",{"Tötet 10 Sturmgeschmiedete Konstrukteure und kehrt zu Bruor Eisenbann in Bergfels' Zuflucht zurück."}}
D[12992] = {"Tötet die Vrykul!",{"Ekel im Schattengewölbe möchte, dass Ihr 15 beliebige Vrykul in der weiteren Umgebung von Jotunheim tötet."}}
D[12993] = {"Eine kolossale Bedrohung",{"Gelangt an die Informationen über die Angriffs- und Verteidigungsfähigkeiten des Kolosses und bringt sie zu Bergfels dem Steinformer in Bergfels' Zuflucht."}}
D[12994] = {"Jagd auf Spione",{"Ihr müsst 3 Sturmgeschmiedete Spitzel im uralten Wintertal besiegen.","","Verwendet den Fangzahn eines astralen Worgs bei der Leiche des gefallenen Worgs und beschwört damit einen astralen Frostworg, mit dessen Hilfe Ihr versteckte Feinde entlarven könnt. Wenn das Tal von den Spionen befreit wurde, sollt Ihr zur Frostworghöhlenmutter in Dun Niffelem zurückkehren."}}
D[12995] = {"Setzt ein Zeichen",{"Baron Splitter im Schattengewölbe wünscht, dass Ihr 15 Banner der Schwarzen Klinge in die Nähe der Vrykulleichen steckt, die Ihr in der weiteren Umgebung von Jotunheim findet."}}
D[12996] = {"Das Aufwärmen",{"Astrid Björnrittar aus Brunnhildar möchte, dass Ihr die Zügel der Kriegsbärenmatriarchin nutzt, um Kirgaraak zu besiegen."}}
D[12997] = {"In die Grube",{"Astrid Björnrittar aus Brunnhildar möchte, dass Ihr in die Reißzahngrube geht und mit den Zügeln der Kriegsbärenmatriarchin 6 Kriegsbären des Hildarthings besiegt."}}
D[12998] = {"Das Herz des Sturms",{"Bergfels der Steinformer in Bergfels' Zuflucht möchte, dass Ihr nach Uldis reist und versucht, Aufseher Narvir daran zu hindern, an das Herz des Sturms zu gelangen."}}
D[12999] = {"Die Knochenhexe",{"Sprecht mit der Knochenhexe in der Höhle des Dorfes Njorndar."}}
D[13000] = {"Notfallmaßnahmen",{"Ihr befindet Euch auf dieser Quest."}}
D[13001] = {"Hodirs Speer schmieden",{"Hüter des Wissens Randvir aus Dun Niffelem möchte, dass Ihr 3 Immerfrostsplitter aus den Tiefen der Überwinterungshöhle sowie 3 Bälge ruhiger Mammuts aus dem uralten Wintertal holt."}}
D[13002] = {"Edelsteine perfektionieren",{"Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Geba'li in der Kriegshymnenfeste."}}
D[13003] = {"Drachentöten leicht gemacht",{"Ihr sollt mit Hodirs Speer einen Wildwyrm im uralten Wintertal herausfordern. Wenn Ihr ihn getroffen habt, muss es zu einem Kampf auf Leben und Tod kommen."}}
D[13004] = {"Edelsteine perfektionieren",{"Bringt zwei Riesencitrin, zwei Nephrite und zwei Schattenkristalle zu Alestros in der Valianzfeste."}}
D[13005] = {"Der Eid der Irdenen",{"Thorim, auf der Terrasse der Schöpfer, wünscht, dass Ihr in das Horn der Sturmgipfel blast und die Irdenen ruft, damit sie 20 Eisenzwerge und 7 Eisenschildwachen besiegen."}}
D[13006] = {"Eine schmierige Säuberung",{"Ihr müsst Euch in die Überwinterungshöhle westlich von Dun Niffelem begeben und 5 Einheiten viskoses Öl vom Rohöl dort besorgen.","","Kehrt dann nach Dun Niffelem zurück und tragt das Öl auf Hodirs Helm auf."}}
D[13007] = {"Der Eisenkoloss",{"Nutzt einen gezähmten Jormungar, um den Eisenkoloss zu besiegen, und kehrt dann zu Bergfels dem Steinformer in Bergfels' Zuflucht zurück."}}
D[13008] = {"Die Taktik der Geißel",{"Kreuzzugskommandant Entari in der Argentumvorhut von Eiskrone bittet Euch, 8 eingesponnene Kreuzfahrer zu befreien."}}
D[13009] = {"Ein Neuanfang",{"Njormeld wünscht, dass Ihr die neugeschmiedete Rüstung zu Thorim im Tempel der Stürme bringt."}}
D[13010] = {"Krolmir, Hammer der Stürme",{"Thorim möchte, dass Ihr mit König Jokkum in Dun Niffelem sprecht und in Erfahrung bringt, was er über Krolmir weiß."}}
D[13011] = {"Jorkuttar töten",{"König Jokkum in Dun Niffelem möchte, dass Ihr in die Überwinterungshöhle geht und Jorkuttar niederstreckt."}}
D[13012] = {"Urahne Sardis"}
D[13013] = {"Beldak der Älteste"}
D[13014] = {"Morthie der Älteste"}
D[13015] = {"Fargal der Älteste"}
D[13016] = {"Northal der Älteste"}
D[13017] = {"Jarten der Älteste"}
D[13018] = {"Sandrene der Älteste"}
D[13019] = {"Thoim der Älteste"}
D[13020] = {"Steinbart der Älteste"}
D[13021] = {"Igasho der Älteste"}
D[13022] = {"Nurgen der Älteste"}
D[13023] = {"Kilias der Älteste"}
D[13024] = {"Wanikaya der Älteste"}
D[13025] = {"Lunaro der Älteste"}
D[13026] = {"Blauwolf der Älteste"}
D[13027] = {"Tauros der Älteste"}
D[13028] = {"Graumähne der Älteste"}
D[13029] = {"Pamuya der Älteste"}
D[13030] = {"Whurain der Älteste"}
D[13031] = {"Himmelswächter der Älteste"}
D[13032] = {"Muraco der Älteste"}
D[13033] = {"Arp der Älteste"}
D[13034] = {"Der Zeuge und der Held",{"Xarantaur im Camp Tunka'lo möchte, dass Ihr Euch die erste, zweite und dritte historische Schriftrolle durchlest."}}
D[13035] = {"Lokens Lakaien",{"Thorim möchte, dass Ihr Eisenfaust in der Halle des Formers erschlagt. Außerdem sollt Ihr Halefnir den Zischenden und Duronn den Runenbesetzten auf der Terrasse der Schöpfer töten."}}
D[13036] = {"Ehre über alles",{"Meldet Euch bei Kreuzzugskommandant Entari in der Argentumvorhut in Eiskrone."}}
D[13037] = {"Erinnerungen an Sturmhuf",{"Sprecht mit Häuptling Schnellspeer in der Frostschollentiefe und kehrt dann zu Xarantaur ins Camp Tunka'lo zurück."}}
D[13038] = {"Verzerrungen in der Zeit",{"Nutzt das Totem des Häuptlings, um 4 Frostschollenklüfte zu schließen, und bringt es danach zu Xarantaur ins Camp Tunka'lo."}}
D[13039] = {"Die Vorhut verteidigen",{"Kreuzfahrerlord Dalfors von der Argentumvorhut in Eiskrone hat Euch gebeten, 15 Neruber der Vergessenen Tiefen zu töten."}}
D[13040] = {"Heilmittel für das Unheilbare",{"Vater Gustav aus der Argentumvorhut in Eiskrone bittet Euch, ihm 10 Giftdrüsen der Vergessenen Tiefen zu bringen."}}
D[13041] = {"Die Lieferung abfertigen",{"Bringt einen Chalzedon zu Jonas Timotheus in Dalaran."}}
D[13042] = {"Tief im Inneren des Kellergewölbes",{"Die Knochenhexe aus Njorndar bittet Euch, Informationen bezüglich der Pläne von Dr. Maböse aus Lehrling Osterkilgr herauszuprügeln.","","Tötet den Lehrling anschließend."}}
D[13043] = {"Das Ganze ist größer als die Summe seiner Teile",{"Besteigt Nergeld und übernehmt die Kontrolle. Verteidigt ihn vor den Bewohnern der Hallen des Grauens, bis sich Dr. Maböse zeigt.","","Nutzt Nergeld, um den Doktor zu vernichten, und kehrt dann zur Knochenhexe nach Njorndar zurück."}}
D[13044] = {"Falls es Überlebende gibt...",{"Sprecht mit Penumbrius in der Argentumvorhut in Eiskrone."}}
D[13045] = {"Ins wilde Grün",{"Rettet 3 gefangene Argentumkreuzfahrer aus Geißelholme und bringt sie ins Feldlazarett im Zentrum des Argentumvorpostens. Berichtet Hochlord Tirion Fordring danach von Eurem Erfolg."}}
D[13046] = {"Arngrim füttern",{"Ihr sollt 5 körperlose Jormungar an Arngrim verfüttern und dann zu Arngrims gefrorenem Abbild in Dun Niffelem zurückkehren.","","Ihr müsst ins uralte Wintertal gehen und Arngrims Zahn auf die dort herumstreunenden Jormungar anwenden. Sobald sie eine körperlose Form angenommen haben, müsst Ihr sie bekämpfen, bis sie geschwächt sind."}}
D[13047] = {"Die Abrechnung",{"Trefft Euch mit Thorim in der Nähe des Tempels der Weisheit. Berichtet König Jokkum in Dun Niffelem, wie der Kampf ausgegangen ist."}}
D[13048] = {"Wo die Zeit aus dem Ruder lief",{"Setzt den Lehrenhammer bei den Taunka-Relikten ein, um ihn an Sturmhufs Zeit anzupassen. Kehrt zu Xarantaur nach Camp Tunka'lo zurück, wenn er auf 6 Relikte aus Sturmhufs Zeit eingestimmt wurde."}}
D[13049] = {"Die Waffen des Helden",{"Findet Sturmhufs Rüstung und Speer und bringt die Gegenstände zu Xarantaur in Camp Tunka'lo zurück."}}
D[13050] = {"Veranus",{"Thorim aus dem Tempel der Stürme möchte, dass Ihr ihm 5 kleine Eier von den Protodrachen bringt, die auf den Gipfeln in der Umgebung von Brunnhildar hausen."}}
D[13051] = {"Territoriale Vergehen",{"Legt die gestohlenen Protodracheneier in das Nest der Brutmutter und kehrt dann zu Thorim in den Tempel der Stürme zurück."}}
D[13052] = {"Luftüberwachung",{"Professorin Kalvert möchte, dass Ihr den Flug zum Landeplatz am See nehmt und dort mit Pilot Vic sprecht."}}
D[13053] = {"Suche nach Überlebenden",{"Helft Zak Wackelspross, den Testflug zu beenden."}}
D[13054] = {"Der vermisste Fährtenleser",{"Ihr befindet Euch auf dieser Quest."}}
D[13055] = {"Höhlenmedizin",{"Fährtenleser Val'zij hält sich in Gimoraks Bau auf und möchte, dass Ihr ihm 1 Giftdrüse der Jormungar und 8 Höhlenpilze bringt."}}
D[13056] = {"Für Rache ist immer Zeit",{"Fährtenleser Val'zij möchte, dass Ihr Gimorak in Gimoraks Bau tötet."}}
D[13057] = {"Die Terrasse der Schöpfer",{"Findet Thorim an der südöstlichen Kante der Terrasse der Schöpfer gleich nordwestlich von Dun Niffelem."}}
D[13058] = {"Die Windrichtung ändern",{"Reist mithilfe des Lehrenhammers in der Zeit zurück, schlüpft in Sturmhufs Rolle und stellt Euch dem Nordwind. Beschafft Euch das Horn des Elementarfurors, sobald Sturmhuf gestorben ist und es fallen gelassen hat, und benutzt es, um den Nordwind zu erledigen. Kehrt danach zu Xarantaur ins Camp Tunka'lo zurück."}}
D[13059] = {"Rache für die Vargul",{"Bethod Feigr im Kellergewölbe wünscht, dass Ihr sein Schwert zu Boden werft, um Than Illskar im Kreis des Leidens herauszufordern und zu töten."}}
D[13060] = {"Wenn alles andere versagt",{"Sprecht mit Ricket, um mithilfe von Rickets D16-angetriebenem Lieferungsgerät tiefer in das Gebiet der Sturmgipfel vorzudringen."}}
D[13061] = {"Bereit für den Ruhm",{"Sprecht mit Lok'lira der Greisin in Brunnhildar."}}
D[13062] = {"Lok'liras Abschiedsgeschenk",{"Sprecht mit Gretta der Schiedsfrau in Brunnhildar."}}
D[13063] = {"Für würdig befunden",{"Brijana möchte, dass Ihr nach Brunnhildar geht und mit Astrid Bjornrittar sprecht."}}
D[13064] = {"Rivalität unter Geschwistern",{"Thorim möchte, dass Ihr Euch seine Geschichte anhört."}}
D[13065] = {"Ohanzee der Älteste"}
D[13066] = {"Yurauk der Älteste"}
D[13067] = {"Chogan'gada der Älteste"}
D[13068] = {"Eine Erzählung von Heldenmut",{"Hochlord Tirion Fordring auf dem Kreuzfahrerturm wünscht, dass Ihr den Helden Kreuzfahrer Bridenbrad in der stillen Nachtwache im Nordosten der Eiskrone aufspürt. Seine Feuergrube wird aus der Luft gesehen wahrscheinlich der deutlichste Hinweis auf seinen Aufenthaltsort sein."}}
D[13069] = {"Schießt sie ab!",{"Der Springer beim Schattengewölbe möchte, dass Ihr eine Schnellfeuerharpune von Jotunheim dazu verwendet, 15 Protodrachen von Jotunheim mitsamt ihren Reitern abzuschießen."}}
D[13070] = {"Eine Kaltfront nähert sich",{"Meldet Euch bei Belagerungsmeister Fezzik bei der Argentumvorhut in Eiskrone."}}
D[13071] = {"Ekel mag Feuer!",{"Ekel im Schattengewölbe möchte, dass Ihr einen Protodrachen von Njorndar stehlt und ihn benutzt, um 8 Vrykulgebäude in der weiteren Jotunheimregion in Brand zu setzen.","","Die Festung Balargarde kann aufgrund ihrer Beschaffenheit nicht in Flammen gesetzt werden."}}
D[13072] = {"Ein Held verbleibt",{"Bringt die Neuigkeiten von Kreuzfahrer Bridenbrads Schicksal zu Hochlord Tirion Fordring in den Kreuzfahrerturm."}}
D[13073] = {"Eine Bitte an den Bewahrer",{"Hochlord Tirion Fordring im Kreuzfahrerturm hat Euch gebeten, dass Ihr bei der Erzdruidin Lilliandra Zugang erbittet und mit Bewahrer Remulos redet."}}
D[13074] = {"Hoffnung im Smaragdgrünen Alptraum",{"Bewahrer Remulos auf der Mondlichtung hat Euch aufgetragen, den Smaragdgrünen Traum zu betreten und 3 Smaragdgrüne Eicheln zu besorgen.","","Verlasst die nähere Umgebung des Schreins von Remulos, um nach Azeroth zurückzukehren."}}
D[13075] = {"Remulos' Segen",{"Kehrt mit der Smaragdeichel zu Kreuzfahrer Bridenbrad in die stille Nachtwache in Eiskrone zurück."}}
D[13076] = {"Es bleibt noch Zeit",{"Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten der Smaragdeichel."}}
D[13077] = {"Die Berührung eines Aspekts",{"Erbittet die Hilfe von Alexstrasza der Lebensbinderin im Wyrmruhtempel."}}
D[13078] = {"Dahlias Tränen",{"Alexstrasza die Lebensbinderin im Wyrmruhtempel verlangt von Euch, dass Ihr Dahlias Tränen aus dem Boden bergt, der von den Flammen der Rubinbehüter frisch geläutert ist."}}
D[13079] = {"Alexstraszas Segen",{"Bringt den Atem von Alexstrasza zu Kreuzfahrer Bridenbrad in die stille Nachtwache in Eiskrone."}}
D[13080] = {"Die Hoffnung stirbt zuletzt",{"Kehrt zu Hochlord Tirion Fordring in den Kreuzfahrerturm zurück und berichtet ihm von den Effekten des Atems von Alexstrasza."}}
D[13081] = {"Der Wille der Naaru",{"Erbittet die Hilfe von A'dal in Shattrath in den Wäldern von Terokkar."}}
D[13082] = {"A'dals Segen",{"Kehrt zu Kreuzfahrer Bridenbrad in die stille Nachtwache in Eiskrone zurück."}}
D[13083] = {"Licht im Dunkeln",{"Bringt Kreuzfahrer Bridenbrads Wappenrock zu Hochlord Tirion Fordring in den Kreuzfahrerturm."}}
D[13084] = {"Demoliert Jotunheim",{"Herzog Lankral beim Schattengewölbe möchte, dass Ihr 10 Banner der Vrykul verbrennt."}}
D[13085] = {"Vaelen ist zurückgekehrt",{"Redet mit Vaelen dem Geschundenen im Schattengewölbe."}}
D[13086] = {"Die letzte Verteidigungslinie",{"Benutzt eine Argentumkanone, um 100 Angreifer der Geißel zu vernichten. Außerdem müsst Ihr 3 Frostbrutzerstörer töten.","","Solltet Ihr erfolgreich sein, kehrt zu Belagerungsmeister Fezzik zurück."}}
D[13087] = {"Kochkunst des Nordens",{"Bringt 4 Stück kühles Fleisch zu Brom Bräugießer in Valgarde. Jede Bestie in Nordend verfügt über dieses Fleisch."}}
D[13088] = {"Kochkunst des Nordens",{"Bringt Rollick MacKreel in der Valianzfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch."}}
D[13089] = {"Nordische Kochkunst",{"Bringt 4 Stück kühles Fleisch zu Thomas Kolichio im Hafen der Vergeltung. Alle Bestien in Nordend verfügen über dieses Fleisch."}}
D[13090] = {"Nordische Kochkunst",{"Bringt Orn Zarthuf in der Kriegshymnenfeste 4 Stück kühles Fleisch. Alle Bestien in Nordend verfügen über dieses Fleisch."}}
D[13091] = {"Die Kunst, ein Wasserschrecken zu sein",{"Die Knochenhexe in Njorndar möchte, dass Ihr Besitz von einem Wasserschrecken ergreift und ihn dazu benutzt, 10 Vrykul in der Umgebung von Jotunheim zu töten.","","In Frage kommende Vrykul sind Schlafwächter, Krieger von Jotunheim, Wassermagier der Mjordin, Speerschwestern von Njorndar und Varguls von Valhalas."}}
D[13092] = {"In den Knochen lesen",{"Die Knochenhexe in Njorndar hat Euch aufgetragen, 15 Vrykulknochen zu besorgen."}}
D[13093] = {"In den Knochen lesen"}
D[13094] = {"Schämen sie sich denn nicht?",{"Bibliothekarin Serrah möchte, dass Ihr den Nexus betretet und Berinands Forschungsergebnisse beschafft."}}
D[13095] = {"Schämen sie sich denn nicht?",{"Bibliothekarin Serrah möchte, dass Ihr den Nexus betretet und Berinands Forschungsergebnisse beschafft."}}
D[13096] = {"Gal'darah muss bezahlen",{"Tol'mar in Dubra'Jin möchte, dass Ihr Gal'darah in Gundrak erschlagt."}}
D[13097] = {"Noch ein Hühnchen zu rupfen",{"Har'koa möchte, dass Ihr mit Tol'mar in Dubra'jin sprecht."}}
D[13098] = {"Für die Nachwelt",{"Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und 6 Geschichtstafeln der Drakkari sammelt."}}
D[13099] = {"Nur ma' nachsehen",{"To'kini möchte, dass Ihr mit Bah'kini in Dubra'Jin sprecht."}}
D[13100] = {"Energieerfüllter Pilzhackbraten",{"Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran."}}
D[13101] = {"Versammlung im Zauberkasten",{"Bringt 4 nordische Eintöpfe, die Ihr selbst gekocht habt, und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran."}}
D[13102] = {"Kanaleintopf",{"Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.","","Bringt den fertigen Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran."}}
D[13103] = {"Käse für Leuchtegold",{"Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.","","Bringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier."}}
D[13104] = {"Noch einmal in die Bresche, Held",{"Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche."}}
D[13105] = {"Noch einmal in die Bresche, Held",{"Meldet Euch beim Schwarzen Wächter im Tal der Echos gleich außerhalb der Bresche."}}
D[13106] = {"Die Schwarzwacht",{"Sprecht mit Dunkelreiterin Arly in der Schwarzwacht in Eiskrone."}}
D[13107] = {"Senfwürstchen!",{"Füllt den leeren Picknickkorb mit 4 Rhinowürstchen, die Ihr selbst gekocht habt, und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.","","Bringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran."}}
D[13108] = {"Koste es, was es wolle!",{"König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Loken besiegt. Danach sollt Ihr mit Lokens Zunge zu König Jokkum zurückkehren."}}
D[13109] = {"Diametral entgegengesetzt",{"König Jokkum in Dun Niffelem wünscht, dass Ihr die Hallen der Blitze betretet und Volkhan besiegt."}}
D[13110] = {"Die rastlosen Toten",{"Vater Gustav im Tal der Echos in Eiskrone möchte, dass Ihr die Überreste von wiedererweckten Kreuzfahrern mit Weihwasser benetzt, um 10 ruhelose Seelen zu befreien."}}
D[13111] = {"Einzelstück",{"Chronistin Bah'Kini in Dubra'Jin möchte, dass Ihr nach Gundrak geht und ein Fragment des Kolosses der Drakkari beschafft."}}
D[13112] = {"Energieerfüllter Pilzhackbraten",{"Benutzt Eure Bratenform, um aus 4 energieerfüllten Pilzen aus der Kanalisation von Dalaran und 2 Stück kühlem Fleisch einen Pilzhackbraten herzustellen und bringt das Resultat zu Orton Bennet bei Kuriositäten & Meer auf dem Runenweberplatz in Dalaran."}}
D[13113] = {"Versammlung im Zauberkasten",{"Bringt 4 nordische Eintöpfe und einen Krug Wein aus dem Käseladen in Dalaran zu Arille Azurblick im Zauberkasten auf dem Runenweberplatz in Dalaran."}}
D[13114] = {"Kanaleintopf",{"Gebt 4 Kristallsangkarotten aus dem Kristallsangwald gemeinsam mit 4 Stück kühlem Fleisch in einen Kochtopf und lasst die Zutaten kochen.","","Bringt den Gemüseeintopf anschließend zu Gastwirt Ajay Grün in die Kanalisation von Dalaran."}}
D[13115] = {"Käse für Leuchtegold",{"Kombiniert die leere Käseplatte mit reifem Dalaranlimburger aus dem Käseladen \"Noch ein Gläschen\" und mit 6 halbvollen Dalaranweingläsern, die auf den Tischen in Dalaran gefunden werden können.","","Bringt die Wein- und Käseplatte anschließend zu Ranid Leuchtegold im Lederladen auf dem Handelsmarkt der Magier."}}
D[13116] = {"Senfwürstchen!",{"Füllt den leeren Picknickkorb mit 4 selbstgekochten Rhinowürstchen und 4 Zweigen wilden Senfs, der in den grasbewachsenen Bereichen der Stadt zu finden ist.","","Bringt den Picknickkorb anschließend zu Erzmagier Pentarus bei Krasus' Landeplatz in Dalaran."}}
D[13117] = {"Wo kommen sie her?",{"Untersucht einen Beschwörungsaltar im östlichen Teil der Fleischwerke und berichtet dann Dunkelreiterin Arly bei der Schwarzwacht davon."}}
D[13118] = {"Die Reinigung von Geißelholme",{"Der Schwarze Wächter im Tal der Echos möchte, dass Ihr 3 Hohepriester der Vergessenen Tiefen, 3 Unterkönige der Vergessenen Tiefen und 8 wiedererweckte Kreuzfahrer tötet."}}
D[13119] = {"Zerstört die Altäre",{"Tötet Meisterbeschwörer Zarod und benutzt seinen Beschwörerstab, um den ersten, zweiten, dritten und vierten Beschwörungsaltar zu zerstören. Habt Ihr diese Aufgabe erledigt, kehrt zu Dunkelreiterin Arly bei der Scharzwacht zurück."}}
D[13120] = {"Todesblick",{"Benutzt die Kugel des Todesblicks, um Kugeln in die Kugelhalterung des Monstrositätenlabors, des Fleischriesenlabors und des Kesselbereichs zu legen. Kehrt anschließend zu Dunkelreiterin Arly in die Schwarzwacht zurück."}}
D[13121] = {"Durch das Innere Auge",{"Die Knochenhexe in Njorndar hat Euch beauftragt, das Auge des Lichkönigs zu benutzen, um an Informationen zu gelangen."}}
D[13122] = {"Der Geißelstein",{"Der Schwarze Wächter im Tal der Echos möchte, dass Ihr ihm 15 Geißelsteine bringt."}}
D[13123] = {"WotLK Collector's Edition: - DEM - E - FLAG"}
D[13124] = {"Der Kampf geht weiter",{"Raelorasz möchte, dass Ihr Euch in das Oculus begebt und Belgaristrasz und seine Gefährten befreit."}}
D[13125] = {"Die Luft steht still",{"Der Schwarze Wächter beim Tal der Echos in Eiskrone will, dass Ihr Salranax den Zerfleischer, Unterkönig Talonox und Hohepriester Yath'amon tötet."}}
D[13126] = {"Vereinte Front",{"Belgaristrasz möchte, dass Ihr 10 Zentrifugenkonstrukte zerstört, um Varos' Schild zu beseitigen. Danach müsst Ihr Varos Wolkenwanderer besiegen."}}
D[13127] = {"Magierlord Urom",{"Belgaristrasz möchte, dass Ihr Magierlord Urom im Oculus besiegt."}}
D[13128] = {"Schlacht in den Wolken",{"Belgaristrasz möchte, dass Ihr Eregos im Oculus tötet und anschließend bei Raelorasz im Transitusschild in Kaltarra Bericht erstattet."}}
D[13129] = {"Psychospielchen",{"Kurzel möchte, dass Ihr den Fetzen von Kurzels Bluse auf die Reste von Novos dem Beschwörer in der Feste Drak'Tharon anwendet und anschließend den sekretbefleckten Stoff zu Mack bringt."}}
D[13130] = {"Der Stein, der eine Revolution auslöste",{"Kreuzzugsarchitekt Silas im Tal der Echos in Eiskrone möchte, dass Ihr 10 Stämme kristallines Kernholz und 10 Stücke altes elfisches Mauerwerk sammelt."}}
D[13131] = {"Schrott in der Truhe",{"Brigg im Turm Utgarde möchte, dass Ihr 5 blitzblanke Silberbarren, 3 glänzende Schmuckstücke, 2 goldene Kelche und eine Jadestatue beschafft."}}
D[13132] = {"Die Rache ist mein!",{"Brigg im Turm Utgarde möchte, dass Ihr König Ymiron tötet."}}
D[13133] = {"Findet den Held aus alter Zeit",{"Die Knochenhexe aus Njorndar möchte, dass Ihr mit Iskalder zurückkehrt."}}
D[13134] = {"Lasst ihr Blut fließen"}
