D[13229] = {"Noch bin ich nicht tot!"}
D[13230] = {"Rächt mich!",{"Ein sterbender Berserker hat Euch darum gebeten, 5 sterbende Soldaten an der zerbrochenen Front zu töten. Erstattet Himmelshäscher Korm Schwarznarbe auf der Orgrims Hammer Bericht, sobald dies erledigt ist."}}
D[13231] = {"Die zerbrochene Front",{"Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr Euch an die zerbrochene Front begebt, den sterbenden Soldaten befragt und ihm dann erneut Bericht erstattet."}}
D[13232] = {"Tötet mich!",{"Der sterbende Soldat an der zerbrochenen Front möchte, dass Ihr 5 sterbende Soldaten erlöst und dann Stabshauptmann Justin Bartlett auf der Himmelsbrecher Bericht erstattet."}}
D[13233] = {"Keine Gnade!",{"Stabshauptmann Justin Bartlett an Bord der Himmelsbrecher möchte, dass Ihr in Eiskrone 15 Spieler der Horde tötet."}}
D[13234] = {"Sie müssen zahlen!",{"Himmelshäscher Korm Schwarznarbe möchte, dass Ihr 15 Spieler der Allianz in Eiskrone tötet."}}
