D[2751] = {"Almenas barbáricas",{"Lleva 2 brazales de bronce estampados, 2 espadas magnas de bronce y 2 garras afiladas a Orokk Omosh a Orgrimmar."}}
D[2752] = {"Espaldares de hierro",{"Lleva 4 hachas de batalla de bronce y 4 martillos de guerra de bronce a Orokk Omosh a Orgrimmar."}}
D[2753] = {"¡Aplástalos!",{"Lleva 4 yelmos de hierro verdes, 4 brazales de hierro verdes y 2 pares de leotardos de hierro verdes a Orokk Omosh a Orgrimmar."}}
D[2754] = {"Cuernos de frenesí",{"Lleva 2 grandes mazas de hierro sólido, 2 botas de bronce bañadas en plata y 2 guanteletes de bronce bañados en plata a Orokk Omosh en Orgrimmar."}}
D[2755] = {"Las alegrías de los Omosh",{"Mira la danza de la alegría de los Omosh."}}
D[2756] = {"Los viejos hábitos",{"Lleva 4 corazas de acero y 4 yelmos de placas de acero a Aturk el Yunque a Orgrimmar."}}
D[2757] = {"¡Bahía del Botín o nada!",{"Habla con McGavan en Bahía del Botín."}}
D[2758] = {"El origen de la herrería",{"Lleva seis brazales de escamas doradas a Hank el Martillo en Ventormenta."}}
D[2759] = {"Buscando a Galvan",{"Habla con McGavan en Bahía del Botín."}}
D[2760] = {"La Orden del mitril",{"Habla con Galvan el Antiguo en la Vega de Tuercespina."}}
D[2761] = {"Funde o no funde",{"Lleva cuarenta barras de mitril y cuarenta barras de hierro a Galvan el Antiguo en Tuercespina."}}
D[2762] = {"La veraplata no es verídica",{"Lleva cuarenta barras de mitril y cinco barras de veraplata a Galvan el Antiguo en Tuercespina."}}
D[2763] = {"El arte de imbuir",{"Lleva cuarenta barras de mitril y cuatro citrinos a Galvan el Antiguo en Tuercespina."}}
D[2764] = {"El mejor alumno de Galvan",{"Habla con Trenton Mazaligera en Gadgetzan, en Tanaris."}}
D[2765] = {"¡Experto herrero!",{"Reclama tu recompensa a Galvan el Antiguo."}}
D[2766] = {"¡Encuentra a OOX-22/FE!",{"Lleva el localizador de emergencia al robot mensajero de Oglethorpe a una cueva que hay cerca de Vega Cicatriz Feral."}}
D[2767] = {"¡Escolta a OOX-22/FE!",{"Escolta a OOX-22/FE para que llegue sano y salvo y después preséntate ante Oglethorpe Obnoticus en Bahía del Botín."}}
D[2768] = {"Vara divinomática",{"Lleva la vara divinomática al ingeniero jefe Pasaquillas en Gadgetzan."}}
D[2769] = {"Los hermanos Pernolatón",{"Habla con Wizzle Pernolatón en El Desierto de Sal."}}
D[2770] = {"Gahz'rilla",{"Llévale la escama electrificada de Gahz'rilla a Wizzle Pernolatón, que está en El Desierto de Sal."}}
D[2771] = {"La cabeza sobre los hombros",{"Llévale un par de almófares de mitril y unos sobrehombros de mitril ornamentado a Trenton Mazaligera."}}
D[2772] = {"El mundo a tus pies",{"Llévale un par de botas de mitril pesado y unos pantalones de mitril ornamentado a Trenton Mazaligera."}}
D[2773] = {"El chico de mitril",{"Llévale un par de corazas de mitril pesado y unos guantes de mitril ornamentado a Trenton Mazaligera."}}
D[2781] = {"SE BUSCA: Califa Escorpijón",{"Llévale la cabeza de Califa Escorpijón al ingeniero jefe Pasaquillas, que está en Gadgetzan."}}
D[2782] = {"El secreto de Rin'ji",{"Oran Snakewrithe es una conocida erudita en los trols Secacorteza; quizá pueda descifrar la tablilla. Vive en el Barrio de la Magia de Entrañas."}}
D[2783] = {"Peleas mezquinas",{"Habla con el héroe caído de la Horda donde Las Tierras Devastadas lindan con El pantano."}}
D[2784] = {"Pérdida de honor",{"Escucha la historia del héroe caído de la Horda."}}
D[2801] = {"Una historia triste",{"Escucha la historia del héroe caído de la Horda."}}
D[2821] = {"La marca de la calidad",{"Lleva 10 pellejos de yeti gruesos a Pratt McGrubben al Bastión Plumaluna."}}
D[2822] = {"La marca de la calidad",{"Lleva 10 pellejos de yeti gruesos a Jangdor Zanco Veloz al Campamento Mojache."}}
D[2841] = {"Las guerras de la plataforma",{"Consigue la combinación de la caja fuerte de Termochufe en Gnomeregan y lleva los planos de la plataforma a Nogg a Orgrimmar."}}
D[2842] = {"Scooty, ingeniero jefe",{"Habla con Scooty en Bahía del Botín."}}
D[2843] = {"¡Gnomer-yaaaaa!",{"Espera a que Scooty calibre el transpondedor goblin."}}
D[2844] = {"El guardián gigante",{"Localiza a la elfa de la noche perdida."}}
D[2845] = {"Las andanzas de Shay",{"Coge la campana de Shay del cofre.","","Escolta a Shay Correhoja al campamento de Muerdepiedras."}}
D[2846] = {"Tiara de las Profundidades",{"Lleva la Tiara de las Profundidades a Tabetha en el Marjal Revolcafango."}}
