D[4120] = {"La fuerza de la corrupción",{"Talo Pezuñahendida, del Campamento Mojache de Feralas, quiere que mates a 12 pardos Zarpira y 12 devastadores Zarpayel de Frondavil."}}
D[4121] = {"¡Estás en un aprieto!",{"Escolta al prisionero, Grark Lorkrub, a través de Las Estepas Ardientes y la Montaña Roca Negra hasta La Garganta de Fuego.","","Recuerdas que Lexlort mencionó que tendría a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido.","","También tendrás que entregarle a Lexlort los grilletes de torio."}}
D[4122] = {"Grark Lorkrub",{"Ve a Las Estepas Ardientes y encuentra a Grark Lorkrub. Recuerdas que Lexlort mencionó que lo habían visto por última vez en una colosal fortaleza Roca Negra.","","Cuando encuentres a Grark Lorkrub, usa los grilletes de torio para atarlo y condúcelo de vuelta por la Montaña Roca Negra hasta La Garganta de Fuego. Lexlort tendrá a algunos de sus hombres esperándote al otro lado para llevarse a Grark detenido."}}
D[4123] = {"El corazón de la montaña",{"Llévale el corazón de la montaña a Maxwort Suprandor en Las Estepas Ardientes."}}
D[4124] = {"El mensajero desaparecido",{"Ve al Bastión Plumaluna y habla con Ginro Mechogar."}}
D[4125] = {"El mensajero desaparecido",{"Localiza el bote del mensajero por la costa de Feralas."}}
D[4126] = {"Hurley Negrálito",{"Llévale la receta de Cebatruenos perdida a Ragnar Cebatruenos en Kharanos."}}
D[4127] = {"Los restos del bote",{"Vuelve al Bastión Plumaluna y enseña a Ginro Mechogar el cuchillo perdido que encontraste."}}
D[4128] = {"Ragnar Cebatruenos",{"Habla con Ragnar Cebatruenos."}}
D[4129] = {"La revelación del cuchillo",{"Lleva el cuchillo perdido a Quintis Jonguja al Bastión Plumaluna."}}
D[4130] = {"Lectura psicométrica",{"Ve al Bastión Plumaluna y habla con Ginro Mechogar."}}
D[4131] = {"Los gnolls Zarpaleña",{"Busca el rastro del mensajero o sus pertenencias en los campamentos de los gnoll Zarpaleña del sur de Feralas."}}
D[4132] = {"Operación: muerte a Forjainquina",{"Viaja hasta las Profundidades de Roca Negra ¡y mata al general Forjainquina! Vuelve junto al señor de la guerra Dientegore cuando hayas acabado la tarea."}}
D[4133] = {"Vivian Lagrave",{"Habla con la taumaturgo oscuro Vivian Lagrave en Kargath."}}
D[4134] = {"La receta de Cebatruenos perdida",{"Llévale la receta de Cebatruenos perdida a Vivian Lagrave en Kargath."}}
D[4135] = {"Las Galerías Retorcidas",{"Ahora que has descubierto el rastro de Raschal, adéntrate en Las Galerías Retorcidas y encuéntrale... o encuentra lo que quede de él. Según la nota, debes dirigirte al sur de los campamentos de los Zarpaleña."}}
D[4136] = {"Ribbly Llavenrosca",{"Llévale la cabeza de Ribbly a Yuka Llavenrosca en Las Estepas Ardientes."}}
D[4141] = {"Muigin y Larion",{"Recoge 15 pétalos de sangre y ve a ver a Muigin."}}
D[4142] = {"Visita a Gregan",{"Llévale un pétalo de sangre a Gregan Tirabirras de Feralas."}}
D[4143] = {"Bruma del mal",{"Reúne 5 muestras de calima Atal'ai y después ve a ver de nuevo a Muigin al Cráter de Un'Goro."}}
D[4144] = {"Brotes de pétalo de sangre"}
D[4145] = {"Larion y Muigin",{"Caza 5 azotadores Pétalo de Sangre, 5 trilladores Pétalo de Sangre, 5 desolladores Pétalo de Sangre y 5 tramperos Pétalo de Sangre para Larion en el Refugio de Marshal."}}
D[4146] = {"Combustible de irradior",{"Entrega el Controlador descargado y 5 muestras de calima Atal'ai a Larion, en el Refugio de Marshal."}}
D[4147] = {"El taller de Marvon",{"Viaja hasta el taller de Marvon Buscarroblones en Trinquete."}}
D[4148] = {"Liquidador de pétalos de sangre"}
D[4161] = {"La receta de los kaldorei",{"Recoge 7 patas de araña pequeña para Zarrin, que está en Dolanaar."}}
D[4181] = {"Ingeniería goblin",{"Si quieres saber más sobre ingeniería goblin, llévale el Manual de disciplinas de ingeniería a Nixx Muellepiñón de Gadgetzan."}}
D[4182] = {"La amenaza de los dragonantes",{"Mata 15 estirpes negras, 10 dragauros negros, 4 vermintes negros y 1 draco negro."}}
D[4183] = {"Los verdaderos maestros",{"Viaja a Villa del Lago, en las Montañas Crestagrana, y entrégale la carta de Helendis Rivacuerno al magistrado Solomon."}}
D[4184] = {"Los verdaderos maestros",{"Ve a Ventormenta para entregar la petición de ayuda de Solomon al rey Varian Wrynn.","","Vive en el Castillo de Ventormenta."}}
D[4185] = {"Los verdaderos maestros",{"Habla con el alto señor Bolvar Fordragón después de hablar con Lady Katrana Prestor."}}
D[4186] = {"Los verdaderos maestros",{"Lleva el decreto de Wrynn al magistrado Solomon en la Villa del Lago."}}
D[4201] = {"La poción de enamoramiento",{"Llévale 4 gromsanguinas, 10 venas de plata gigantescas y el vial lleno de Nagmara a la coima Nagmara en las Profundidades de Roca Negra."}}
D[4221] = {"Flor del viento corrupta"}
D[4222] = {"Flor del viento corrupta"}
