D[4581] = {"Kayneth Ventoleve",{"Llévale la nota de Shindrell a Kayneth Ventoleve en Canción del Bosque."}}
D[4601] = {"¡El Destellamatic 5200!",{"Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano."}}
D[4602] = {"¡El Destellamatic 5200!",{"Inserta un objeto sucio en el Destellamatic 5200 y asegúrate de tener 3 monedas de plata a mano."}}
