D[4723] = {"Criatura marina varada",{"Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine."}}
D[4724] = {"La maestra de la manada",{"Mata a Halycon, empaqueta la Maestra del huargo Hacha de Sangre."}}
D[4725] = {"Tortuga marina varada",{"Lleva la caja con símbolos extraños a Gwennyth Bly'Leggonde a Auberdine."}}
D[4726] = {"Esencia de cría",{"Llévale 8 esencias de cría y el Draco-Incarcinatrix 900 a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes."}}
D[4727] = {"Tortuga marina varada",{"Lleva los restos de la tortuga marina a Gwennyth Bly'Leggonde a Auberdine."}}
D[4728] = {"Criatura marina varada",{"Lleva los huesos de la criatura marina a Gwennyth Bly'Leggonde a Auberdine."}}
D[4729] = {"Las mascotas exóticas de Kibler",{"Viaja hasta la Cumbre de Roca Negra y encuentra cachorros de huargo Hacha de Sangre. Usa la jaula para transportar a esas feroces fierecillas. Llévale a Kibler 1 cachorro de huargo enjaulado."}}
