D[4734] = {"Un huevo congelado",{"Usa el prototipo de ovosciloscopio sobre un huevo de El Grajero, en la Cumbre de Roca Negra."}}
D[4735] = {"La colecta de huevos",{"Llévale 8 huevos de dragón y el módulo colectrónico a Tinkee Vaporio en el Peñasco Llamarada, en Las Estepas Ardientes."}}
