D[4740] = {"SE BUSCA: ¡Viscoso!",{"Encuentra y mata al múrloc conocido como Viscoso. Se cree que la criatura está defendiendo el emplazamiento múrloc al sur de Auberdine, cerca del agua.","","Informa de la muerte de Viscoso a la centinela Glynda Nal'Shea, en Auberdine."}}
D[4741] = {"Guardianes salvajes",{"Trull Fallarruina de Frondavil quiere que caces 13 lechubestias lunadón."}}
D[4742] = {"El sello de ascensión",{"Encuentra las 3 gemas del mando: La gema de Espina Ahumada, la gema de Cumbrerroca y la gema de Hacha de Sangre. Llévaselas, junto con el sello de ascensión sin adornar a Vaelan.","","Los generales, como te dijo Vaelan, son: el maestro de guerra Voone de los Espina Ahumada, el alto señor Omokk de los Cumbrerroca y el señor supremo Vermiothalak de los Hacha de Sangre."}}
D[4743] = {"El sello de ascensión",{"Viaja a la Ciénaga de Fuego en Marjal Revolcafango. Encuentra al anciano draco Brasaliza y derrótalo sin contemplaciones hasta doblegar su voluntad.","","Este es el preciso momento en el que debes colocar el Sello de ascensión sin forjar ante la colosal bestia. Debes entonces ser rápido en usar el orbe de energía dracónica sobre su debilitada forma y reclamar el dominio sobre sus facultades mentales. ¡Controla la bestia y dirige las llamas del Vuelo Negro sobre el Sello de ascensión sin forjar!"}}
D[4761] = {"Thundris Tejevientos",{"Ve a Auberdine y habla con Thundris Tejevientos."}}
D[4762] = {"El Río Fonroca",{"Viaja al norte de Auberdine hasta la primera cascada del Río Fonroca y recoge una muestra de agua.","","Vuelve a Auberdine a buscar a Thundris Tejevientos con la muestra del Río Fonroca."}}
D[4763] = {"La corrupción de los Bosque Negro",{"Llena el cuenco purificador vacío en la Poza de la Luna de Auberdine.","","Recoge una muestra de fruta, nueces y grano del campamento del norte de los fúrbolgs Bosque Negro.","","Mezcla todo en el cuenco, llévalo al campamento norte y colócalo cerca de la hoguera más cercana al Río Fonroca; así convocarás al sátiro corruptor.","","Coge el dije de corrupción y llévaselo a Thundris Tejevientos a Auberdine."}}
D[4764] = {"El Broche de Equipasino",{"Llévale el broche de Equipasino a Mayara Alasol en Las Estepas Ardientes."}}
D[4765] = {"Entrega a Bonacresta",{"Llévale el cajón de Bonacresta al conde Remington Bonacresta en el Castillo de Ventormenta, en Ventormenta."}}
D[4766] = {"Mayara Alasol",{"Habla con Mayara Alasol en Vigilia de Morgan en Las Estepas Ardientes."}}
D[4767] = {"Jinete del viento",{"Consigue 10 huevos de dracoleón Nido Alto para Elu en el Poblado Viento Libre."}}
D[4768] = {"La tablilla de Rocanegra",{"Llévale la tablilla de Rocanegra a la maga oscura Vivian Lagrave en Kargath."}}
D[4769] = {"Vivian Lagrave y la tablilla de Rocanegra",{"Habla con la maga oscura Vivian Latumba."}}
D[4770] = {"De vuelta a casa",{"Saca a Pao'ka Monte Presto de Nido Alto y después habla con Motega Crin de Fuego en Campamento del Tramo Blanco."}}
D[4771] = {"Gambito del Alba",{"Coloca el Gambito del Alba en la Sala de la Visión de Scholomance. Derrota a Vectus y ve a ver a Betina Bigglezink."}}
D[4781] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale un lingote de oro a Xizk Cortefino en la Vega de Tuercespina."}}
D[4782] = {"Los componentes para la toga de sangre dorada encantada",{"Regresa junto a Menara Nadiz en Los Baldíos."}}
D[4783] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale 10 viales de sangre Odio Feroz y 1 piedra Infernal inferior a Menara Nadiz en Los Baldíos."}}
D[4784] = {"Los componentes para la toga de sangre dorada encantada",{"Llévale unos hilos finos de oro, 2 trozos de ascuas humeantes y 1 fragmento de alma a Menara Nadiz en Los Baldíos."}}
