D[4808] = {"Felnok Acerovera",{"Entrégale la carta de Tinkee a Felnok Acerovera en Vista Eterna, en Cuna del Invierno."}}
D[4809] = {"Cuernos de Orvallo",{"Reúne 8 cuernos de quimera del Orvallo."}}
D[4810] = {"Regresa junto a Tinkee",{"Llévale el paquete de Felnok a Tinkee Vaporio en el Peñasco Llamarada en Las Estepas Ardientes."}}
D[4811] = {"El cristal rojo",{"Viaja al este de Auberdine y busca un gran cristal rojo en la zona montañosa que hay al este de Costa Oscura. Vuelve a Auberdine e informa de lo que has encontrado a la centinela Glynda Nal'Shea."}}
D[4812] = {"Agua en cascada",{"Llena el tubo de agua vacío en la Poza de la Luna de Auberdine y luego examina el cristal rojo a lo largo de la pared montañosa oriental de Costa Oscura."}}
D[4813] = {"Los trozos del interior",{"Vuelve a Auberdine e informa de lo que has averiguado a la centinela Glynda Nal'Shea."}}
D[4821] = {"Un huevo extraño",{"Devuélvele el huevo extraño a Hagar Pezuña del Rayo, que está en el Poblado Viento Libre."}}
D[4822] = {"¡Quiero un heladooooo!"}
D[4841] = {"Apaciguar al centauro",{"Mata a 12 exploradores Galak, 10 vaqueros Galak y 6 cazavientos Galak, y después ve a ver de nuevo a Vigiarisco Cuerno Largo al Poblado Viento Libre."}}
D[4842] = {"Fuentes extrañas",{"Sigue las indicaciones de Donova Cubilnevado y vuelve a informarle."}}
D[4861] = {"Lechúcico salvaje iracundo",{"Localiza el campamento arrasado y los suministros de Jaron Tallapiedras en la parte sur de Cuna del Invierno."}}
D[4862] = {"Bestia amaestrada",{"Viaja a la Cumbre de Roca Negra y reúne 15 huevos de araña de la cumbre para Kibler.","","Yo diría que se pueden encontrar estos huevos cerca de arañas."}}
D[4863] = {"Lechúcico salvaje iracundo",{"Encuentra el carro destrozado de Jaron Tallapiedras."}}
D[4864] = {"Lechúcico salvaje iracundo",{"Recoge de la nieve los Suministros de Jaron y encuentra al lechúcico salvaje que robó el amuleto del que te habló Jaron.","","Lleva los Suministros de Jaron y el Amuleto de plumas azules a Jaron Tallapiedras en el refugio de Cuna del Invierno."}}
D[4865] = {"Venganza",{"Cuéntale lo que has descubierto a Motega Crin de Fuego en el Campamento del Tramo Blanco, en Las Mil Agujas."}}
D[4866] = {"La leche de la madre",{"En el corazón de la Cumbre de Roca Negra encontrarás a Madre Telabrasada. Provócala para que te envenene. Lo más seguro es que tendrás que matarla también. Vuelve junto a John Andrajoso cuando estés envenenado para que pueda extraer el veneno de ti."}}
D[4867] = {"Urok Aullapocalipsis",{"Lee el pergamino de Warosh. Llévale el mojo de Warosh a Warosh."}}
D[4881] = {"Complot de asesinato",{"Avisa a Kanati Nube Gris, en el Campamento del Tramo Blanco, acerca de la conspiración para acabar con su vida."}}
D[4882] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Trull Fallarruina en el Puesto del Veneno."}}
D[4883] = {"Guardar un secreto",{"Lleva el Collar de plumas azules a Nara Ferocrín."}}
D[4901] = {"Guardianes del altar",{"Protege a Ranshalla mientras intenta reactivar el Altar de Elune. Informa sobre tus descubrimientos a Erelas Cieloámbar de Aldea Rut'theran."}}
D[4902] = {"Lechúcico salvaje de Elune",{"Habla con el archidruida Fandral Corzocelada en Darnassus."}}
D[4903] = {"La orden del Señor de la Guerra",{"Mata al Alto señor Omokk, al maestro de guerra Voone y al Señor Supremo Vermiothalak. Recupera importantes documentos Roca Negra. Vuelve junto al señor de la guerra Dientegore en Kargath cuando hayas cumplido la misión."}}
D[4904] = {"Al fin libre",{"Saca a Lakota Son del Viento de Cumbre de la Nube Negra y después habla con Thalia Pellejo Ámbar, que está en el Poblado Viento Libre."}}
D[4906] = {"Más corrupción",{"Eridan Vientoazul de Frondavil quiere que mates a 8 clamainfernos Fuego de Jade, 8 traidores Fuego de Jade, 8 timadores Fuego de Jade y a Xavaric. Vuelve con Eridan cuando lo hayas hecho."}}
D[4907] = {"Tinkee Vaporio",{"Habla con Tinkee Vaporio en el Peñasco Llamarada, en las Estepas Ardientes."}}
D[4921] = {"Perdida en la batalla",{"Encuentra a la esposa de Mankrik y llévala a El Cruce."}}
D[4941] = {"La sabiduría de Eitrigg",{"Habla con Eitrigg en Orgrimmar. Cuando hayas tratado unos asuntos con Eitrigg, busca el consejo de Thrall.","","Recuerdas haber visto a Eitrigg en la Cámara de Thrall."}}
D[4961] = {"La purificación del orbe de Orahil",{"Mata al demonio del orbe y luego habla con Tabetha."}}
D[4962] = {"Fragmento de can manáfago",{"Coge el rubí de Felhas y úsalo en uno de los canes manáfagos de Desolace. Cuando lo consigas, llévale el rubí de Felhas y el espíritu del can manáfago encarcelado a Menara Nadiz en Los Baldíos."}}
D[4963] = {"Fragmento de infernal",{"Coge la esmeralda de Infus y úsala en uno de los infernales de Desolace. Cuando lo consigas, llévale la esmeralda de Infus y el espíritu del infernal encarcelado a Menara Nadiz en Los Baldíos."}}
D[4964] = {"El orbe completo de Dar'Orahil",{"Espera a Menara Nadiz para completar el orbe de Dar'Orahil y vuelve entonces a hablar con ella."}}
D[4965] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4966] = {"Defensa de Kanati Nube Gris",{"Defiende a Kanati Nube Gris contra el ataque de los centauros."}}
D[4967] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4968] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4969] = {"El conocimiento del orbe de Orahil",{"Habla con Menara Nadiz en Los Baldíos."}}
D[4970] = {"Provisiones Sable de Hielo",{"Recoge 5 carnes de Dentoesquirla y 5 carnes de Orvallo para Rivern Ventogélido de Cuna del Invierno."}}
D[4971] = {"Una cuestión de tiempo",{"Utiliza el desplazador temporal junto a uno de los silos de Andorhal y saca a la luz los parásitos temporales.","","Mata a 10 parásitos temporales y devuélvele el desplazador temporal a Cromi en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4972] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal, los encontrarás en cajas fuertes entre las ruinas de la ciudad. Cuando los tengas regresa con Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4973] = {"Contar el tiempo",{"Localiza 5 relojes de Andorhal entre las ruinas de la ciudad y llévaselos a Cromi, en la posada de Andorhal, en las Tierras de la Peste del Oeste."}}
D[4974] = {"¡Por la Horda!",{"Ve a Cumbre de Roca Negra para matar al Jefe de Guerra Rend Puño Negro. Lleva su cabeza a Orgrimmar."}}
D[4975] = {"El orbe completo de Noh'Orahil",{"Espera a Menara Nadiz para completar el orbe de Noh'Orahil y vuelve entonces a hablar con ella."}}
D[4976] = {"Devolver el orbe purificado",{"Llévale el orbe infernal limpio a Menara Nadiz en Los Baldíos."}}
D[4981] = {"La espía Bijou",{"Viaja hasta la Cumbre de Roca Negra y averigua qué le ha ocurrido a Bijou."}}
D[4982] = {"Las pertenencias de Bijou",{"Encuentra las pertenencias de Bijou y devuélveselas. Recuerdas que ella mencionó haberlas ocultado en la planta baja de la ciudad."}}
D[4983] = {"El informe de reconocimiento de Bijou",{"Llévale el informe de reconocimiento de Bijou al maestro mayor Lexlort en Kargath."}}
D[4984] = {"La naturaleza también sufre",{"Destruye 8 lobos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste."}}
D[4985] = {"La naturaleza también sufre",{"Destruye 8 pardos malsanos y regresa con Mulgris Río Hondo en El Tormento, en las Tierras de la Peste del Oeste."}}
D[4986] = {"Rama de roble con inscripciones",{"Según la magia con la que está encantada La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion en Darnassus. Pide ayuda a uno de los druidas que encontrarás allí."}}
D[4987] = {"Rama de roble con inscripciones",{"Según la magia con la que está encantada de La rama de roble con inscripciones, el siguiente paso del druida tauren debía ser su entrega al Círculo Cenarion de Cima del Trueno. Pide ayuda a uno de los druidas que encontrarás allí."}}
D[5001] = {"Las pertenencias de Bijou",{"Encuentra las pertenencias de Bijou y devuélveselas. ¡Suerte!"}}
D[5002] = {"Un mensaje para Maxwell",{"Viaja a Las Estepas Ardientes y dale la información sobre Bijou al mariscal Maxwell."}}
D[5021] = {"Más vale tarde que nunca",{"Entre lamentos, la mujer fantasmal recordaba tener que entregar un paquete. Según ella estaba junto a su caballo. No puedes entender dónde está el caballo o dónde había que entregar el paquete."}}
D[5022] = {"Más vale tarde que nunca",{"Consulta con los agentes reales de Ventormenta para averiguar el paradero de una tal Emma Piedra Mácula. Suele haber un oficial del censo en el Ayuntamiento."}}
D[5023] = {"Más vale tarde que nunca",{"Consulta con los supervisores reales de Entrañas para averiguar el paradero de Jeremiah Piedra Mácula. Suele haber un oficial del censo junto a la oficina de registro de hermandades y tabardos."}}
D[5041] = {"Suministros para El Cruce",{"Encuentra los cajones de suministros de El Cruce y devuélveselos a Thork en Los Baldíos."}}
D[5042] = {"La fuerza de Agamaggan"}
D[5043] = {"La agilidad de Agamaggan"}
D[5044] = {"La sabiduría de Agamaggan"}
D[5045] = {"Fortaleza de espíritu"}
D[5046] = {"Ocultafilo"}
D[5047] = {"¡Pip Perspicaz, a su servicio!",{"Habla con Malyfous Martilloscuro en Vista Eterna."}}
D[5048] = {"El buen carácter de Emma",{"Encuentra a la Vieja Emma en Ventormenta y descubre si realmente es Emma Piedra Mácula. Si lo es, quizás quiera el paquete que Janice Piedra Mácula hizo para ella."}}
D[5049] = {"La depre de Jeremiah",{"Encuentra a Jeremiah Payson en Entrañas y averigua si en realidad es Jeremiah Piedra Mácula. Si es así, quizás quiera el paquete que Janice Piedra Mácula preparó para él."}}
D[5050] = {"Talismán de buena suerte",{"Devuelve a Janice Piedra Mácula en las Tierras de la Peste del Oeste su Medio talismán de buena suerte."}}
D[5051] = {"Dos mitades hacen una",{"Localiza la otra mitad del talismán de la suerte en algún lugar de la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste, y recomponlo.","","Dale el talismán de la suerte a Janice Piedra Mácula en la Granja de Piedra Mácula, en las Tierras de la Peste del Oeste."}}
D[5052] = {"Esquirlas de sangre de Agamaggan",{"Llévale una esquirla de sangre a Quebrantadientes en el Campamento Taurajo en Los Baldíos.","","Reúne más esquirlas de sangre si quieres que te bendiga con el poder de Agamaggan."}}
D[5054] = {"Ursius de los Dentoesquirla",{"Ventisca Pezuña Umbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Ursius."}}
D[5055] = {"Brumerán de los Orvallo",{"Ventisca Pezuña Umbría de Vista Eterna, en Cuna del Invierno, quiere que mates a Brumerán."}}
