D[5060] = {"Encierro"}
D[5061] = {"Forma acuática",{"Vuelve a Darnassus y enséñale el colgante del león marino a Mathrengyl Garroso."}}
D[5062] = {"El fuego Sagrado",{"Recoge 10 montones de pitas incendiarias y después pide consejo a Magatha Tótem Siniestro en el Alto de los Ancestros de Cima del Trueno."}}
D[5063] = {"Almete del Sabio Escarlata",{"Para crear el Almete del Sabio Escarlata deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 8 cristales Arcanos; 5 hilos escarlata encantados.","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5064] = {"Espiando a los Tótem Siniestro",{"Localiza y reúne las 3 notas secretas que hay en Cumbre de la Nube Negra."}}
D[5065] = {"Las tablillas perdidas Mosh'aru",{"Llévale la tercera y cuarta tablillas Mosh'aru al prospector Ferrobota, que está en Tanaris."}}
D[5066] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5067] = {"Leotardos de Arcana",{"Para crear los leotardos arcana deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 5 costuras desgarradas de abominación; 5 barras de arcanita; 5 líquidos de embalsamar de Murmuhielo.","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5068] = {"Coraza Sed de Sangre",{"Para crear la coraza Sed de Sangre deberás llevarle los siguientes objetos a Malyfous Martilloscuro: 1 pellejo de la Bestia prístino; 10 costuras desgarradas de abominación; 5 barras de arcanita; 5 pieles de Sombra.","","También tendrás que pagar 50 piezas de oro para la elaboración del almete."}}
D[5081] = {"La misión de Maxwell",{"Viaja a la Cumbre de Roca Negra y acaba con el maestro de guerra Voone, el alto señor Omokk y el señor supremo Vermiothalak."}}
D[5082] = {"La amenaza de los Nevada",{"Donova Cubilnevado de Cuna del Invierno quiere que mates 8 abrecaminos Nevada, 8 vigías del cubil Nevada y 8 totémicos Nevada."}}
D[5083] = {"Aguardiente Nevada",{"Lleva el Frasco vacío de aguardiente a Donova Cubilnevado de Cuna del Invierno."}}
D[5084] = {"Sucumbir a la corrupción",{"Busca una pista en el campamento fúrbolg Muertobosque en el norte de Frondavil."}}
D[5085] = {"Baba misteriosa",{"Informa sobre tus descubrimientos a Donova Cubilnevado."}}
D[5086] = {"Horrores tóxicos",{"Recoge 3 gotitas de horror tóxico para Donova Cubilnevado de Cuna del Invierno."}}
D[5087] = {"Corredores Nevada",{"Encuentra a los corredores Nevada y detenlos antes de que entreguen su cargamento en Poblado Nevada."}}
D[5088] = {"Arikara",{"Mata a Arikara. Llévale sus restos y el polvo de incendiaria a Motega Crin de Fuego al Campamento del Tramo Blanco como prueba de tus actos."}}
D[5089] = {"Orden del general Drakkisath",{"Llévale la orden del general Drakkisath al mariscal Maxwell en Las Estepas Ardientes."}}
D[5090] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5091] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al comandante Ashlam Puñovalor. Su campamento base se encuentra en Campamento del Orvallo, al norte de las Montañas de Alterac."}}
D[5092] = {"Despejar el camino",{"Mata 10 despellejadores esqueléticos y 10 necrófagos esclavizantes en la Colina de las Penas.","","Vuelve con el comandante Ashlam Puñovalor en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5093] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5094] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5095] = {"Un llamamiento a las armas: las Tierras de la Peste",{"Busca al sumo ejecutor Derrington; su campamento base está en El Baluarte, al este de Claros de Tirisfal y Entrañas."}}
D[5096] = {"Distracción Escarlata",{"Adéntrate en el campamento base de la Cruzada Escarlata entre el Campo de Piedramácula y el Llanto de Dalson y destruye su tienda de mando.","","Coloca el estandarte de la Plaga en el campamento y vuelve con el sumo ejecutor Derrington en El Baluarte en las Tierras de la Peste del Oeste."}}
D[5097] = {"Todas las atalayas",{"Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.","","Cuando estén marcadas las cuatro atalayas devuelve la antorcha de aviso al comandante Ashlam Puñovalor del Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5098] = {"Todas las atalayas",{"Con la antorcha de aviso, marca las atalayas de Andorhal. Tendrás que estar en la entrada de la atalaya para poder marcarla.","","Cuando estén marcadas las cuatro atalayas, devuelve la antorcha de aviso al sumo ejecutor Derrington en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5101] = {"Lee's Ultimate Test Quest... of Doom!",{"Kill 6 sheep for Benny and then run like hell!","","","","","Just kidding... about the running part."}}
D[5102] = {"Muerte al general Drakkisath",{"Viaja hasta la Cumbre de Roca Negra y mata al general Drakkisath."}}
D[5103] = {"Muerte abrasadora",{"Alguien en este mundo debe de saber qué hacer con estos guanteletes. ¡Suerte!"}}
D[5121] = {"Gran Jefe Nevada",{"Donova Cubilnevado de Cuna del Invierno quiere que derrotes al Gran Jefe Nevada."}}
D[5122] = {"El medallón de Fe"}
D[5123] = {"La pieza final",{"Lleva el Diario mal escrito a Donova Cubilnevado de Cuna del Invierno."}}
D[5124] = {"Guanteletes de placas ígneas",{"Lleva a Malyfous Martilloscuro 6 barras de torio encantado, 2 esencias de fuego y 4 rubíes estrellados. También tendrás que entregarle tus guanteletes de placas sin templar."}}
D[5125] = {"La estimación de Aurius"}
D[5126] = {"La historia de Lorax",{"Habla con Lorax. Escucha todo lo que tiene que decirte."}}
D[5127] = {"La forja demoníaca",{"Viaja a la Cumbre de Roca Negra y encuentra a Goraluk Yunquegrieta. Mátale y utiliza el Pica manchada de sangre sobre su cadáver. Cuando hayas absorbido su alma, la pica estará manchada de alma.","","También debes encontrar la coraza cubierta de runas sin forjar.","","Lleva la pica manchada de alma y la coraza cubierta de runas sin forjar a Lorax en Cuna del Invierno."}}
D[5128] = {"Las palabras del Gran Jefe",{"Lleva el Diario mal escrito a Kelek Guardacielo en el sur de Frondavil."}}
D[5141] = {"Peletería dragontina",{"Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Peter Galen, en Azshara.","","Si completas esta misión tendrás acceso al arte de la peletería dracónica.","","Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla."}}
D[5142] = {"La pequeña Pamela",{"Encuentra a Pamela Rutagrana en Villa Darrow."}}
D[5143] = {"Peletería tribal",{"Lleva 1 jubón de cuero salvaje y 1 casco de cuero salvaje a Caryssia Cazaluna a Feralas.","","Si completas esta misión, tendrás acceso a las artes de Peletería tribal.","","Si lo haces, no podrás aprender peletería dragontina ni peletería elemental; asegúrate de que este es el camino que deseas seguir antes de completar la misión."}}
D[5144] = {"Peletería elemental",{"Lleva 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Sarah Peletero a La Garganta de Fuego.","","Al completar esta tarea aprenderás peletería elemental.","","Si te dedicas a este arte, no podrás aprender peletería dragontina ni peletería tribal; piénsatelo bien antes de decidirte."}}
D[5145] = {"Peletería dragontina",{"Consigue 2 corazas resistentes de escórpido, 2 guantes resistentes de escórpido, y 10 escamas de dragón desgastadas para Thorkaf Dragonojo, en las Tierras Inhóspitas.","","Si completas esta misión tendrás acceso al arte de la peletería dracónica.","","Si lo haces, también dejarás de tener acceso a la peletería elemental y tribal. Tienes que asegurarte de querer seguir este camino antes de completarla."}}
D[5146] = {"Peletería elemental",{"Llévale 2 corazones de fuego, 2 globos de agua, 2 núcleos de tierra y 2 alientos de viento a Brumm Pezuña Invernal en las Tierras Altas de Arathi.","","Cuando completes esta misión tendrás acceso a las artes de peletería elemental.","","Si completas esta misión, no podrás aprender peletería dragontina ni peletería tribal; asegúrate de que este es el camino que deseas seguir antes de tomarlo."}}
D[5147] = {"Se busca: Arnak Tótem Siniestro",{"Mata a Arnak Tótem Siniestro y llévale una prueba de tu hazaña a Vigiarisco Cuerno Largo, que está en el Poblado Viento Libre."}}
D[5148] = {"Peletería tribal",{"Lleva un jubón de cuero salvaje y un casco de cuero salvaje a Se'Jib en la Vega de Tuercespina.","","Completar esta misión te proporcionará acceso a las artes de la peletería tribal.","","Completar esta misión evitará que aprendas peletería dragontina y peletería elemental. Asegúrate que este es el camino que quieres seguir antes de hacerlo."}}
D[5149] = {"La muñeca de Pamela",{"Encuentra la muñeca de Pamela."}}
D[5150] = {"¡Dadanga tiene hambre!"}
D[5151] = {"Hipercondensador",{"Acaba con la bestia y trae de regreso el hipercapacitor y la llave de la jaula a Wizlo Rodabrillante."}}
D[5152] = {"Tía Marlene",{"Habla con Marlene. Está al sur de las Ruinas de Andorhal."}}
D[5153] = {"Una extraña historiadora",{"Lleva la alianza de Joseph a Cromi."}}
D[5154] = {"Las Crónicas de Villa Darrow",{"Lleva el libro Crónicas de Villa Darrow a Cromi a Andorhal."}}
D[5155] = {"Las fuerzas de Jaedenar",{"Entra en Jaedenar y mata a 4 canes Jaedenar, 4 guardianes Jaedenar, 6 adeptos Jaedenar y 6 cultores Jaedenar antes de volver con Greta Pezuñamusgo a Frondavil."}}
D[5156] = {"Investigación acerca de la corrupción",{"Busca y destruye a 2 bestias entrópicas y 2 horrores entrópicos a la vez que exploras la Cañada Gran Cicatriz. Cuando hayas comprobado si los cráteres del lugar aún contienen agua vil corrupta, vuelve con Taronn Plumarroja a Frondavil."}}
D[5157] = {"Una muestra de agua corrupta",{"Lleva la cantimplora vacía a la Poza de la Luna que hay en el centro de Jaedenar y llénala antes de volver con Greta Pezuñamusgo a Frondavil."}}
D[5158] = {"Buscando ayuda espiritual",{"Lleva el agua de la Poza de la Luna corrupta a Islen Vidente del Agua a Los Baldíos."}}
D[5159] = {"El agua purificada vuelve a Frondavil",{"Lleva el agua de la Poza de la Luna purificada a Greta Pezuñamusgo en Frondavil."}}
D[5160] = {"El Protectorado de la matrona",{"Viaja hasta la Cuna del Invierno y encuentra a Haleh. Dale la escama de Awbee."}}
D[5161] = {"La cólera del Vuelo Azul",{"Habla con Haleh si quieres continuar."}}
D[5162] = {"La cólera del Vuelo Azul",{"Habla con Jeziba en las Tierras de la Peste. Vive en Andorhal."}}
D[5163] = {"Yeti... ¿ya hemos llegado?",{"Coge el yeti mecánico de Umi y asusta con él a sus amigos:","","Legacki en Vista Eterna (Cuna del Invierno)","","Roxio en Gadgetzan (Tanaris)","Quixxil en el Refugio de Marshal (Cráter de Un'Goro)","","Cuando hayas terminado, devuelve el yeti mecánico a Umi."}}
D[5164] = {"Catálogo del Díscolo",{"Lee el Catálogo del Díscolo."}}
D[5165] = {"Sofocar las llamas de protección",{"Utiliza el agua de la Poza de la Luna purificada para apagar las llamas de los cuatro Blandones de Protección de la Guarida Sombría de Frondavil y vuelve con Greta Pezuñamusgo al Santuario Esmeralda."}}
D[5166] = {"Coraza del Vuelo Cromático",{"Para forjar la coraza del Vuelo Cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:","","1 caparazón cromático.","","10 escamas cromáticas luminosas.","","10 sangres de héroes.","","10 costuras desgarradas de abominación."}}
D[5167] = {"Quijotes del Desafiante cromático",{"Para forjar los quijotes del desafiante cromático deberás llevarle a Jeziba el 'Escultor\" los siguientes objetos:","","1 caparazón cromático.","","10 escamas cromáticas luminosas.","","10 sangres de héroes.","","5 pieles de Sombra."}}
D[5168] = {"Los héroes de Villa Darrow",{"Lleva el Tratado de Davil y el Escudo de Rutagrana a Carlin Rutagrana."}}
D[5181] = {"Los villanos de Villa Darrow",{"Lleva el cráneo de Horgus y la espada destrozada de Marduk a Carlin Rutagrana a la Capilla de la Esperanza de la Luz."}}
D[5201] = {"Intrusión Nevada",{"Rivern Ventogélido quiere que mates 5 chamanes Nevada y 5 ursas Nevada."}}
D[5202] = {"Una extraña llave roja",{"Recorre Jaedenar y descubre para qué se utiliza la llave roja de sangre."}}
D[5203] = {"El rescate en Jaedenar",{"Escolta a Arko'narin hasta el lugar en el que están Forjaluz y su equipo y protégela en la huida de la Guarida Sombría. Después, busca a Jessir Arcolunar en Frondavil para contarle lo que les ha ocurrido a sus amigos."}}
D[5204] = {"La reprensión de la Luz",{"Vuelve a Jaedenar y mata al súcubo Rakaiah antes de encontrar los Restos de Trey Forjaluz."}}
D[5206] = {"Los merodeadores de Villa Darrow",{"Lleva 5 calaveras resonadoras y el cristal místico a Carlin Rutagrana a las Tierras de la Peste del Este."}}
D[5210] = {"Carlin, el hermano de Joseph",{"Lleva las Crónicas ampliadas de Villa Darrow a Carlin Rutagrana a las Tierras de la Peste del Este."}}
D[5211] = {"Los defensores de Villa Darrow",{"Libera a 15 espíritus de Villa Darrow y vuelve con Carlin Rutagrana."}}
D[5212] = {"La carne no miente",{"Recoge 10 muestras de carne apestada de Stratholme y vuelve con Betina Bigglezink. Sospechas que podrías obtener una muestra de cualquier criatura de Stratholme."}}
D[5213] = {"El agente activo",{"Viaja a Stratholme y busca los zigurats. Encuentra información sobre la Plaga y llévasela a Betina Bigglezink."}}
D[5214] = {"El gran Ezra Grimm",{"Encuentra la Tienda de humo de Ezra Grimm en Stratholme y recupera una caja del tabaco de calidad de Grimm. Cuando lo hayas hecho, vuelve con Smokey LaRue."}}
D[5215] = {"Las calderas de la Plaga",{"Habla con la suma sacerdotisa MacDonnell en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5216] = {"Objetivo: Campo de Piedramácula",{"Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5217] = {"Regresa al Campamento del Orvallo",{"Lleva la Botella rellena del Campo de Piedramácula a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5218] = {"La caldera del Campo de Piedramácula"}
D[5219] = {"Objetivo: Llanto de Dalson",{"Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5220] = {"Regresa al Campamento del Orvallo",{"Lleva la botella del Llanto de Dalson llena a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5221] = {"La caldera del Llanto de Dalson"}
D[5222] = {"Objetivo: El Tormento",{"Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5223] = {"Regresa al Campamento del Orvallo",{"Lleva la Botella llena de El Tormento a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5224] = {"La caldera de El Tormento"}
