D[5226] = {"Regresa al Campamento del Orvallo",{"Lleva la botella llena de la Gangrena de Gahrron a la suma sacerdotisa MacDonnell en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5227] = {"La caldera de la Gangrena de Gahrron"}
D[5228] = {"Las calderas de la Plaga",{"Habla con la sacerdotisa de las Sombras Vandis en el Baluarte, en las Tierras de la Peste del Oeste."}}
D[5229] = {"Objetivo: Campo de Piedramácula",{"Ve al Campo de Piedramácula en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Seguramente tendrá una llave para acceder a la caldera. Debes llevar contigo la Botella vacía del Campo de Piedramácula para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5230] = {"Regresa a El Baluarte",{"Lleva la Botella rellena del Campo de Piedramácula a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5231] = {"Objetivo: Llanto de Dalson",{"Ve al Llanto de Dalson en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la botella vacía del Llanto de Dalson para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5232] = {"Regresa a El Baluarte",{"Lleva la botella del Llanto de Dalson llena a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5233] = {"Objetivo: El Tormento",{"Ve a El Tormento en las Tierras de la Peste del Oeste para localizar y derrotar a su señor de la caldera. Utiliza su llave para acceder a la caldera. Debes llevar contigo la Botella vacía de El Tormento para obtener una muestra de los venenos utilizados en el interior de la caldera."}}
D[5234] = {"Regresa a El Baluarte",{"Lleva la Botella llena de El Tormento a la sacerdotisa de las Sombras Vandis de El Baluarte, en las Tierras de la Peste del Oeste."}}
