D[5441] = {"Peones vagos",{"Utiliza la Cachiporra del supervisor con los peones vagos que estén durmiendo. Despierta a 5 peones y devuélvele la cachiporra al supervisor Thazz'ril en el Valle de los Retos."}}
D[5461] = {"El humano, Ras Murmuhielo",{"Viaja a las Tierras Altas de Arathi, a las Ruinas de Stromgarde. En Stromgarde busca un Libro de los Recuerdos. Si lo encuentras llévaselo al magistrado Marduke."}}
D[5462] = {"El moribundo, Ras Murmuhielo",{"Viaja a Esperanza de la Luz en las Tierras de la Peste del Este y busca a Leonid Barthalomew el Venerado. Enséñale el Libro de los Recuerdos y cuéntale todo lo que has descubierto."}}
D[5463] = {"El Obsequio de Menethil",{"Viaja a Stratholme y encuentra el Obsequio de Menethil. Coloca el Libro de los Recuerdos en suelo no consagrado."}}
D[5464] = {"El Obsequio de Menethil",{"Lleva el Libro de Memorias del Alma a Leonid Barthalomew a las Tierras de la Peste del Este."}}
D[5465] = {"El Libro de Memorias del Alma",{"Vuelve con el magistrado Marduke a Castel Darrow. Muéstrale el Libro de Memorias del Alma."}}
D[5466] = {"El exánime, Ras Murmuhielo",{"Busca a Ras Murmuhielo en Scholomance. Cuando lo hayas encontrado utiliza el Libro de Memorias del Alma sobre su rostro no-muerto. Si consiguieras convertirlo en mortal, derrótale y recupera la Cabeza humana de Ras Murmuhielo. Lleva la cabeza al magistrado Marduke."}}
D[5481] = {"La tarea de Gordo",{"Recoge 3 hierbas luminiscentes y entrégaselas al boticario de segunda Holland en el cementerio de Rémol."}}
D[5482] = {"Apocalíseas",{"Recoge 10 apocalíseas y entrégaselas al boticario de segunda Holland."}}
D[5501] = {"Recolección de kodos",{"Lleva 10 huesos de kodo del Cementerio de Kodos a Bibbly F'utzhebilla a la Cabaña de Kormek."}}
D[5502] = {"Alcaide de la Horda"}
D[5503] = {"Comisión de El Alba Argenta"}
D[5504] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Hasana en El Baluarte, en las Tierras de la Peste del Oeste."}}
D[5505] = {"La llave de Scholomance"}
D[5507] = {"Mantos del Alba",{"Lleva 10 muestras de valor de El Alba Argenta al intendente Chispillo en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
