D[5526] = {"Fragmentos de gangrevid",{"Encuentra gangrevid en La Masacre y coge un fragmento. Es probable que solo puedas conseguirlo si derrotas a Alzzin el Formaferal. Usa el relicario de Pureza para guardar el fragmento y llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5527] = {"Un relicario de Pureza",{"Ve a Silithus a buscar un relicario de Pureza en las ruinas de la Aldea del Viento del Sur. Llévaselo a Rabine Saturna a Amparo de la Noche, en Claro de la Luna."}}
D[5528] = {"La cata de los Gordok"}
D[5529] = {"Crías de dragón apestadas",{"Mata a 20 crías de dragón apestadas y ve a ver a Betina Bigglezink a la Capilla de la Esperanza de la Luz."}}
D[5531] = {"Betina Bigglezink",{"Lleva los huevos congelados a Betina Bigglezink."}}
D[5533] = {"Scholomance",{"Habla con el alquimista Arbington en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5534] = {"El equipamiento \"perdido\" de Kim'jael",{"Encuentra una runa que los nagas guardan en las Ruinas de Eldarath y llévasela a Kim'jael en Azshara."}}
D[5535] = {"Agitación espiritual",{"Mata a 6 aparecidos Altonato y 6 exanimatos Altonato antes de volver junto a Loh'atu en Azshara."}}
D[5536] = {"Una tierra llena de odio",{"Mata 6 sátiros Haldarr, 2 tramposos Haldarr, 2 jurapenas Haldarr y vuelve junto a Loh'atu en la frontera de Vallefresno."}}
D[5537] = {"Trozos esqueléticos",{"Lleva 15 trozos esqueléticos al alquimista Arbington, en el Alto del Orvallo, en las Tierras de la Peste del Oeste."}}
D[5538] = {"Molde rima con... ¿oro?",{"Lleva los trozos esqueléticos imbuidos y 15 piezas de oro a Krinkle Buenacero en Gadgetzan."}}
D[5541] = {"Municiones para Estruendo",{"Lleva la munición de Estruendo a Hegnar Estruendo a Dun Morogh."}}
D[5542] = {"Perros demoníacos",{"Mata 20 cachorros de can de peste, 5 canes de peste y 5 canes de peste demenciados. Cuando hayas terminado tu tarea regresa con Tirion Vadín."}}
D[5543] = {"Cielos sangrientos",{"Mata 30 murcipestes y vuelve con Tirion Vadín."}}
D[5544] = {"Gusanos carroñeros",{"Busca las larvas y devoradores carroñeros de la zona. Mátalos y recoge su carne. Regresa con Tirion Vadín cuando tengas 15 trozos de carne de gusano carroñero."}}
D[5545] = {"El cumplimiento del plazo",{"Lleva 8 fardos de madera a Raelen al Aserradero de la Vega del Este."}}
D[5561] = {"El rodeo kodo",{"Lleva 5 kodos domados y el kombobulador kodo a Smeed Mezclatornillos, al Campamento de los Mezclatornillos."}}
D[5581] = {"Los portales de la Legión",{"Destruye 6 Portales en el Aquelarre Mannoroc y vuelve a la Aldea Cazasombras a hablar con Taiga Crin Sabia."}}
D[5582] = {"Escama de dragón sana",{"Lleva la escama de dragón sana a Betina Bigglezink a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[5601] = {"Pamela, mi hermana",{"Encuentra a Pamela Rutagrana en Villa Darrow."}}
D[5621] = {"Prendas de la luna",{"Encuentra a la centinela Shaya y cura sus heridas utilizando un hechizo de Sanación inferior (Rango 2). A continuación, concédele la Palabra de poder: entereza, y después ve a ver de nuevo a Laurna Luzdelalba a Dolanaar."}}
D[5622] = {"Los caminos de Elune",{"Habla con Laurna Luzdelalba en Teldrassil."}}
D[5623] = {"Al servicio de la Luz",{"Ve al Bosque de Elwynn y habla con la sacerdotisa Josetta."}}
D[5624] = {"Las prendas de la Luz",{"Encuentra al guardia Roberts y cura sus heridas usando Sanación inferior (Rango 2). Después, concédele la Palabra de poder: entereza y vuelve a Villadorada a hablar con la sacerdotisa Josetta."}}
D[5625] = {"Las prendas de la Luz",{"Encuentra al montaraz Dolf y cura sus heridas usando la Sanación inferior (Rango 2). Después, concédele Palabra de Poder: Entereza y vuelve a Kharanos a hablar con Maxan Anvol."}}
