D[6081] = {"Domesticar la bestia",{"Habla con Ormak Tirosiniestro en Orgrimmar."}}
D[6082] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un escórpido acorazado. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo."}}
D[6083] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un reptador de espuma. Practica un poco y devuélvele la fusta de doma a Thotar en Cerrotajo."}}
D[6084] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un leopardo de la nieve. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos."}}
D[6085] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un oso zarpahelada. Practica un poco y devuélvele la fusta a Grif Corazón Salvaje en Kharanos."}}
D[6086] = {"Domesticar la bestia",{"Habla con Belia Tronagranito en Forjaz."}}
