D[7366] = {"La misericordia del arzobispo"}
D[7367] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos Lobo Gélido y mátalo. Vuelve con el experto en explosivos Pico Tormenta cuando hayas acabado este trabajo."}}
D[7368] = {"Acabar con la amenaza",{"Encuentra al experto en explosivos Pico Tormenta y mátalo. Vuelve con el experto en explosivos Lobo Gélido cuando hayas acabado este trabajo."}}
