D[7761] = {"Orden de Puño Negro",{"¡Será estúpido ese orco! Al parecer, tienes que encontrar la enseña y ganar la marca de Drakkisath para poder acceder al orbe de orden.","","Según la carta, el general Drakkisath guarda la enseña. Quizás deberías investigarlo."}}
D[7781] = {"Señor de Roca Negra",{"Lleva la cabeza de Nefarian al rey Varian Wrynn en Ventormenta."}}
D[7782] = {"Señor de Roca Negra",{"Vete al Valle de los Héroes, en Ventormenta, y habla con la mariscal de campo Petraponte."}}
D[7783] = {"Señor de Roca Negra",{"Lleva la cabeza de Nefarian a Thrall a Orgrimmar."}}
D[7784] = {"Señor de Roca Negra",{"Habla con el señor supremo Colmillosauro en Orgrimmar. Te espera en el Valle de la Fuerza."}}
D[7785] = {"Examina la vasija",{"Examina la vasija de renacer y devuélvesela al alto señor Demitrian."}}
D[7786] = {"Thunderaan el Hijo del Viento",{"Para liberar a Thunderaan el Hijo del Viento de su cárcel, debes entregarle al alto señor Demitrian en Silithus la mitad izquierda y la derecha del vínculo del Hijo del Viento, 10 lingotes de elementium y la esencia del Señor de Fuego."}}
D[7787] = {"¡Arriba, Trueno Furioso!",{"Lleva la hoja besada por el viento durmiente al alto señor Demitrian."}}
D[7788] = {"¡Expulsa al invasor!",{"Entra en la Garganta Grito de Guerra y derrota a la Horda, obtén una marca de Honor Grito de Guerra y vuelve con la centinela Cantolejano en el Claro Ala de Plata."}}
D[7789] = {"Acaba con los usurpadores Ala de Plata",{"Entra en la Garganta Grito de Guerra y derrota a la Alianza, obtén una marca de Honor de la Garganta Grito de Guerra y llévasela al capitán Trizacráneo en el Campamento de Mor'shan."}}
