D[8572] = {"Equipamiento de Veterano",{"Lleva 7 distintivos de combate Cenarion, 4 distintivos de logística Cenarion y 4 distintivos de táctica Cenarion a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación de honorable con el Círculo Cenarion para poder completar esta misión."}}
D[8573] = {"Equipamiento de Campeón",{"Lleva 15 distintivos de combate Cenarion, 20 distintivos de logística Cenarion, 20 distintivos de táctica Cenarion y 1 Marca de Cenarius a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación exaltado con el Círculo Cenarion para poder completar esta misión."}}
D[8574] = {"Equipamiento de adepto",{"Lleva 15 distintivos de combate Cenarion, 20 distintivos de logística Cenarion, 17 distintivos de táctica Cenarion y 1 Marca de Remulos a Vargus en el Fuerte Cenarion, en Silithus. También debes conseguir un nivel de reputación venerado con el Círculo Cenarion para poder completar esta misión."}}
D[8575] = {"El libro de contabilidad mágico de Azuregos",{"Entrega el libro de contabilidad mágico de Azuregos a Narain Sabelotodo de Tanaris."}}
D[8576] = {"La traducción del libro de contabilidad"}
D[8577] = {"Guisón, ex mejor amigo",{"Narain Sabelotodo quiere que encuentres a su ex mejor amigo de toda la vida, Guisón, y que recuperes las gafas que le robó."}}
D[8578] = {"¿Unas gafas? ¡Sin problemas!",{"Encuentra las gafas de visión de Narain y llévaselas a Tanaris."}}
