D[8583] = {"¡La Horda necesita más lotos cárdenos!"}
D[8584] = {"¡Nunca me preguntes por mi negocio!",{"Narain Sabelotodo de Tanaris quiere que hables con Dirge Hojágil de Gadgetzan."}}
D[8585] = {"La Isla del Terror",{"Lleva el cadáver de Lakmaeran y 20 solomillos tiernos de quimerok a Dirge Hojágil a Tanaris."}}
D[8586] = {"Fabulosos solomillos de quimerok de Dirge",{"Dirge Hojágil de Gadgetzan quiere que le lleves 20 combustibles de cohete goblin y 20 sales de roca."}}
D[8587] = {"Regresa junto a Narain",{"Entrega el pollo de 500 kilos a Narain Sabelotodo de Tanaris."}}
