D[8857] = {"Los secretos de los Colosos: Ashi",{"Lleva la coraza del coloso de Ashi a Oglethorpe Obnoticus a Bahía del Botín."}}
D[8858] = {"Los secretos de los Colosos: Regal",{"Lleva la coraza del coloso de Regal al sobrestante Puñaceite a La Garganta de Fuego."}}
D[8859] = {"Los secretos de los Colosos: Zora",{"Lleva la coraza del coloso de Zora a Lord Maxwell Neófitus a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[8860] = {"¡Las fiestas de Año Nuevo!",{"Lleva la comida de Pastos de Bosquehumeante a la posadera Allison de Ventormenta."}}
D[8861] = {"¡Las fiestas de Año Nuevo!",{"Lleva la comida de Pastos de Bosquehumeante a la posadera Pala de Cima del Trueno."}}
