D[8867] = {"Fuegos artificiales lunares",{"Dispara 8 fuegos artificiales lunares y 2 cohetes y acude a una presagista del Festival Lunar de cualquier capital."}}
D[8868] = {"La bendición de Elune",{"Invoca a Augurio y derrótalo para ganar la bendición de Elune. Ve a ver a Valadar Cantoestelar a Amparo de la Noche."}}
D[8869] = {"Dulce serenidad",{"Viaja a Stratholme y mata al forjamartillos Carmesí. Consigue el delantal del forjamartillos Carmesí y regresa con Lilith."}}
D[8870] = {"El Festival Lunar",{"Habla con la presagista del Festival Lunar en la Sala Mística de Forjaz. También puedes hablar con la presagista del Festival Lunar en otras capitales."}}
D[8871] = {"El Festival Lunar",{"Habla con el presagista del Festival Lunar en el Distrito del Parque, en Ventormenta. También puedes hablar con otras presagistas del Festival Lunar de otras capitales."}}
D[8872] = {"El Festival Lunar",{"Habla con la presagista del Festival Lunar en el Enclave Cenarion de Darnassus. También puedes hablar con los presagistas del Festival Lunar en otras capitales."}}
D[8873] = {"El Festival Lunar",{"Habla con la presagista del Festival Lunar en el Valle de la Sabiduría, en Orgrimmar. También puedes hablar con la presagista del Festival Lunar en otras capitales."}}
D[8874] = {"El Festival Lunar",{"Habla con la presagista del Festival Lunar en la entrada de Entrañas. También puedes hablar con otras presagistas del Festival Lunar de otras capitales."}}
D[8875] = {"El Festival Lunar",{"Habla con la presagista del Festival Lunar en el Alto de los Ancestros de Cima del Trueno. También puedes hablar con otras presagistas del Festival Lunar de otras capitales."}}
