D[9133] = {"Vuelo a la Ciudad de Lunargenta",{"Compra un vuelo a la Ciudad de Lunargenta y entrégale la nota de embarque del intendente Lymel a Sathren Azurocaso en la Ciudad de Lunargenta."}}
D[9134] = {"La maestra del cielo Anochecer",{"Lleva el envío del intendente Lymel a la maestra del cielo Anochecer, que está junto a la Puerta del Pastor en Ciudad de Lunargenta."}}
D[9135] = {"Regresa junto al intendente Lymel",{"Compra un vuelo de vuelta a Tranquillien, en las Tierras Fantasma, y allí entrégale al intendente Lymel sus bienes en Tranquillien, en las Tierras Fantasma."}}
D[9136] = {"Flora salvaje",{"Rayne, de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere 30 hojas salvajes."}}
D[9137] = {"Hojas salvajes"}
D[9138] = {"La Aldea Corona del Sol",{"Mata a 10 guardias Nerubis y después regresa junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9139] = {"Aldea Bruma Dorada",{"Derrota a 6 fantasmas y 4 ánimas Quel'dorei en la Aldea Bruma Dorada y luego ve a ver al arcanista Vandril a Tranquillien en las Tierras Fantasma."}}
D[9140] = {"La Aldea Brisaveloz",{"Recolecta 6 sustancias fantasmales y 4 fragmentos de gárgola. Vuelve junto al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9141] = {"Me llaman \"El Gallo\"",{"El comandante de envíos Metz de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este, quiere una muestra de valor de El Alba Argenta."}}
D[9142] = {"Libranza del artesano"}
D[9143] = {"Encargarse de Zeb'Sora",{"Lleva 6 orejas de trol de Zeb'Sora a la forestal Valanna a las Tierras Fantasma."}}
D[9144] = {"Desaparecido en las Tierras Fantasma",{"Sigue el camino hacia el sur desde la Aldea Brisa Pura y busca al mensajero Caminalba mientras te acercas a las Tierras Fantasma."}}
D[9145] = {"¡Ayuda a la forestal Valanna!",{"Encuentra a la forestal Valanna y al teniente Tomathren en la orilla del Lago Elrendar, en las Tierras Fantasma cerca de la Aldea Corona del Sol."}}
D[9146] = {"Informar al capitán Helios",{"Habla con el capitán Helios en el Enclave del Errante, en la orilla sur del Lago Elrendar en las Tierras Fantasma."}}
D[9147] = {"El mensajero caído",{"La boticaria Thedra en el Bosque Canción Eterna quiere que le lleves 4 muestras de sangre apestada de las bestias de las Tierras Fantasma."}}
D[9148] = {"Entrega en Tranquillien",{"Llévale la carta de Lunargenta al arcanista Vandril en Tranquillien, en las Tierras Fantasma."}}
D[9149] = {"La costa apestada",{"Llévale 6 espinas dorsales de múrloc apestado al boticario Renzithen en Tranquillien, en las Tierras Fantasma."}}
D[9150] = {"Al rescate del pasado",{"El magister Darenis quiere que vayas al Sagrario de la Luna al oeste de Tranquillien y recuperes 8 esencias de maná cristalizado de los devoradores arcanos y de los conmutadores de maná que pueblan la estructura."}}
D[9151] = {"El Sagrario del Sol",{"Ve al Sagrario del Sol en las Tierras Fantasma y habla con el magister Idonis."}}
D[9152] = {"Los suministros de Tumbero",{"Recupera los suministros de Rathis Sepulturero y llévaselos a Tranquillien, en las Tierras Fantasma."}}
D[9153] = {"Bajo la Sombra",{"Busca en tu mapa una zona que esté bajo el ataque de la Plaga. Ve y derrota a los miembros de la Plaga que custodian la necrópolis. Lleva 10 runas necróticas al comandante Thomas Helleran a la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9154] = {"Capilla de la Esperanza de la Luz",{"Lleva la llamada a las armas al Guardián de los Pergaminos de la Capilla de la Esperanza de la Luz, en las Tierras de la Peste del Este."}}
D[9155] = {"Limpiar La Cicatriz Muerta",{"Mata 10 hambrientos resucitados y 10 caníbales gangliosos en La Cicatriz Muerta. Ve a ver al mortacechador Rathiel a Tranquillien para recibir una recompensa."}}
D[9156] = {"Se busca: Putrenudillos y Luzran",{"Busca a Putrenudillos y Luzran en las Tierras Fantasma. Lleva sus cabezas al mortacechador Rathiel a Tranquillien y recibirás una recompensa."}}
D[9157] = {"Rituales olvidados",{"Lleva 8 medallones rompeolas a Geranis Albodía a las Tierras Fantasma."}}
D[9158] = {"Transmisores de la peste",{"La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 10 linces garrafantasma."}}
D[9159] = {"Control de plagas",{"La errante Sedina del Enclave del Errante en las Tierras Fantasma quiere que mates 8 rondadores husaraña y 10 murciélagos brumosos vampiros."}}
D[9160] = {"Explorando An'daroth",{"Investiga la zona en An'daroth, mata a 12 espías centinela y ve a ver a la Dama Aurífera a Tranquillien en las Tierras Fantasma."}}
D[9161] = {"La sombra del traidor",{"Ve a la Aguja de la Estrella del Alba en las Tierras Fantasma y busca pistas sobre el pasado de Dar'Khan."}}
D[9162] = {"Huellas del pasado",{"Lleva el diario de Dar'Khan a la forestal Vynna al Enclave del Errante."}}
D[9163] = {"En territorio ocupado",{"Roba los Planes de los elfos de la noche: An'daroth, los Planes de los elfos de la noche: An'owyn y los Planes de los elfos de la noche: Espiar a los Sin'dorei, y llévaselos a Dama Aurífera en Tranquillien en las Tierras Fantasma."}}
D[9164] = {"Cautivos en la Ciudad de la Muerte",{"Lleva el jarabe vigorizante de Renzithen a la Ciudad de la Muerte y rescata al aprendiz Varnis, a la boticaria Enith y al forestal Vedoran. Ve a ver a la arcanista Janeda al Sagrario del Sol y recibirás una recompensa."}}
D[9165] = {"La libranza de salvoconducto",{"Entrega la libranza de salvoconducto firmado al comandante de envíos Metz que está en la Capilla de la Esperanza de la Luz de las Tierras de la Peste del Este."}}
D[9166] = {"Entregando los planes a An'telas",{"Entrega los planes de los elfos de la noche al magister Sylastor en An'telas en las Tierras Fantasma."}}
D[9167] = {"La muerte del traidor",{"Mata a Dar'Khan Drathir en la Ciudad de la Muerte y lleva su cabeza al magister Kaendris al Sagrario del Sol en las Tierras Fantasma."}}
D[9168] = {"El corazón de la Ciudad de la Muerte",{"Aniquila a 8 ojos de Dar'Khan e informa al magister Idonis en el Sagrario del Sol en las Tierras Fantasma."}}
D[9169] = {"Desactivando An'owyn",{"Recupera el orbe de control y úsalo para desactivar el cristal lunar de los elfos de la noche en An'owyn. Después ve a ver al magister Sylastor a An'telas en las Tierras Fantasma."}}
D[9170] = {"Los tenientes de Dar'Khan",{"El magister Idonis quiere que vayas a la Ciudad de la Muerte para matar a Masophet el Negro, Jurion el Falsario, Borgoth el Flebotomista y Mirdoran el Caído. Cuando hayas terminado, vuelve a verle en el Sagrario del Sol en las Tierras Fantasma."}}
D[9171] = {"Texturas crujientes",{"Lleva 5 patas de araña crujientes al maestro cocinero Mouldier a Tranquillien en las Tierras Fantasma."}}
D[9172] = {"Informa al magister Kaendris",{"Lleva el diario de Dar'Khan al magister Kaendris al Sagrario del Sol en las Tierras Fantasma."}}
D[9173] = {"Recuperar Aguja Brisaveloz",{"Mata a 8 acólitos de la Ciudad de la Muerte y a 10 forestales caídas y ve a ver al sumo ejecutor Mavren a Tranquillien en las Tierras Fantasma."}}
D[9174] = {"Derrotar a Aquantion",{"Geranis Albodía quiere que nades hasta el fondo del lago al este de la Aldea Corona del Sol y uses los medallones ante el Altar del Dominio de las Mareas. Invoca al elemental llamado Aquantion, ejecútalo y regresa junto a Geranis."}}
