D[9220] = {"Guerra a la Ciudad de la Muerte",{"Mata 5 ojos de Dar'khan, 6 centuriones Nerubis y 6 plañideras en la Ciudad de la Muerte y regresa junto al magister Idonis en el Sagrario del Sol, en las Tierras Fantasma."}}
D[9221] = {"Armamento superior de batalla: amistoso con El Alba",{"Por 30 insignias de El Alba y 30 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta."}}
D[9222] = {"Armamento épico de batalla: amistoso con El Alba",{"Por 110 insignias de El Alba y 110 de la Cruzada, puedes elegir un objeto del tesoro de El Alba Argenta."}}
