D[9365] = {"Una recompensa de ladrón"}
D[9366] = {"Se busca: Sangrevil",{"Ryathen el Sombrío en la Avanzada del Halcón, en la Península del Fuego Infernal, quiere que le lleves 6 muestras de sangrevil de los terroadictos que viven en las Pozas de Aggonar."}}
D[9367] = {"El Festival del Fuego",{"Toca las hogueras de Ventormenta, Forjaz y Darnassus y habla con un maestro del Conocimiento del festival en cada capital."}}
D[9368] = {"El Festival del Fuego",{"Toca las hogueras de Orgrimmar, Cima del Trueno y Entrañas y habla con un Cuentacuentos en cada capital."}}
