D[9370] = {"Detengamos la purificación",{"Coloca la gema de señalización cerca del Altar de Aggonar en las Pozas de Aggonar y derrota a los anacoretas draenei que respondan a tu invocación. Luego lleva la gema a Ryathen el Sombrío a la Avanzada del Halcón."}}
D[9371] = {"La botánica Taerix",{"Habla con la botánica Taerix en el Lugar del Accidente en el Valle Ammen."}}
D[9372] = {"Contaminación demoníaca",{"Thiah Melenarroja en el Puesto Cenarion, en la Península del Fuego Infernal, te ha pedido que consigas 6 muestras de sangre de jabinfernos de los jabinfernos descomunales."}}
D[9373] = {"Carta perdida",{"Llévale el estuche de cuero erosionado a Thiah Melenarroja, que está acampado cerca de las Ruinas de Sha'naar, al oeste de la Península del Fuego Infernal."}}
D[9374] = {"El diario de Arelion",{"La magistrix Carinda de la Avanzada del Halcón en la Península del Fuego Infernal quiere que vayas a las Pozas de Aggonar y recuperes el diario de Arelion."}}
D[9375] = {"Hacia la Avanzada del Halcón",{"Protege a la peregrina elfa de sangre herida en su viaje a la Avanzada del Halcón, luego habla con Taleris Observalba."}}
D[9376] = {"Una peregrina afligida",{"A la peregrina elfa de sangre herida la atacaron los devastadores jabacolmillo cuando deambulaba por el Barranco Pluma Polvorienta. Encuentra los devastadores y mátalos hasta que recuperes la talega desaparecida de la peregrina."}}
D[9378] = {"DND FLAG La ciudadela del terror: Naxxramas"}
D[9380] = {"A seguir cazando canes",{"Reúne 6 cadáveres de can distorsionado intactos y llévaselos al prospector Murantus en el Bastión del Honor."}}
D[9381] = {"Esas flechas sí que vuelan",{"Recolecta 8 plumas de cola de limpiahuesos de buitres limpiahuesos y llévaselos a la halconera Drenna Ríobrisa Avanzada del Halcón."}}
D[9382] = {"El sino de los uñagrietas"}
D[9383] = {"Un plan ambicioso",{"Usa el cristal santificado contra un abisario sin control herido y ve a ver a Elsaana al Templo de Telhamat."}}
D[9385] = {"Devastadores descontrolados",{"Mata 10 devastadores jabacolmillo y ve a ver a Gremni Barbalarga a la Península del Fuego Infernal."}}
D[9386] = {"Una luz en la oscuridad"}
D[9387] = {"El origen de la corrupción",{"Viaja a las Ruinas de Sha'naar en la Península del Fuego Infernal y consigue 5 esencias demoníacas de los capataces Illidari. Vuelve a ver al boticario Azethen a la Avanzada del Halcón cuando hayas completado la tarea."}}
D[9388] = {"La oscilación de las llamas de Kalimdor",{"Toca las hogueras de Vallefresno, Los Baldíos, Costa Oscura y Sierra Espolón y ve a ver al guardián de la llama del Festival."}}
D[9389] = {"La oscilación de las llamas de los Reinos del Este",{"Ve a las hogueras de las Laderas de Trabalomas, el Bosque de Argénteos, los Páramos de Poniente y Los Humedales y habla con el guardián de la llama del Festival."}}
D[9390] = {"En busca de Sedai",{"El anacoreta Obadei quiere que busques a su hermano, Sedai, al este de la Península del Fuego Infernal."}}
D[9391] = {"Iluminar el camino",{"El capitán forestal Venn'ren de la Avanzada del Halcón quiere que vayas a La Gran Fisura en la Península del Fuego Infernal y enciendas la Baliza del Sur, la Baliza Occidental y la Baliza Central. Vuelve junto a él con la antorcha encendida después de completar esta tarea."}}
D[9392] = {"Entrenamiento de pícaros",{"Habla con el acechacaminos Avokor, el instructor de pícaros, en la Aguja del Sol en la Isla del Caminante del Sol."}}
D[9393] = {"Instrucción de cazador",{"Habla con la forestal Sallina, la instructora de clase de cazadores, en La Aguja del Sol en la Isla del Caminante del Sol."}}
D[9394] = {"¿Dónde está Wyllithen?",{"Encuentra al encargado Wyllithen en las Tierras Ocaso Marchito, en el Bosque Canción Eterna."}}
D[9395] = {"El Refugio de Saltheril",{"Ve a Refugio de Saltheril en el Bosque Canción Eterna y habla con Lord Saltheril."}}
D[9396] = {"La magia de los arakkoa",{"Ve a la Avanzada del Halcón, en la Península del Fuego Infernal, y llévale 4 pergaminos Haal'eshi al arcanista Calesthris Estrella del Alba."}}
D[9397] = {"En compañía de pájaros",{"Ve a El Cubil de Haal'esh en la Península del Fuego Infernal y busca en los nidos de kaliri una cría de kaliri hembra. Usa la jaula de pájaros vacía para capturarla y llévasela a la halconera Drenna Ríobrisa en la Avanzada del Halcón."}}
D[9398] = {"Depredadores letales",{"La exploradora Vanura del Templo de Telhamat en la Península del Fuego Infernal quiere que mates 8 crías de guadaña de piedra y 4 alfas guadaña de piedra."}}
D[9399] = {"Capataces crueles",{"Mata a 4 capataces de Illidari en las Ruinas de Sha'naar y vuelve a ver a Ikan en el Templo de Telhamat, en la Península del Fuego Infernal."}}
D[9400] = {"El asesino",{"Nazgrel quiere que vayas por la carretera al norte de la Ciudadela del Fuego Infernal en busca de un asesino llamado Krun Rompeloma."}}
D[9401] = {"Un arma inusual",{"Lleva el hacha de piedra pesada a Nazgrel en Thrallmar en la Península del Fuego Infernal."}}
D[9402] = {"¡Tráeme una cosita!",{"Bucea hasta el fondo de la Charca Plácido Susurro y recupera la ampolla azur para el instructor Antheol."}}
D[9403] = {"El agua más pura",{"El instructor Antheol quiere que llenes la ampolla azur en las Cascadas Elrendar."}}
D[9404] = {"Recientemente vivo",{"Mata a los jardineros Canción Eterna hasta que entreguen una rama viva para el instructor Antheol."}}
D[9405] = {"El mandato del Jefe de Guerra",{"Lleva el hacha pesada de piedra al clarividente Regulkult a Thrallmar, en la Península del Fuego Infernal."}}
D[9406] = {"Los Mag'har",{"Entrega la carta de los Mag'har a Nazgrel en Thrallmar, en la Península del Fuego Infernal."}}
D[9407] = {"A través de El Portal Oscuro",{"Ve hasta El Portal Oscuro y encuentra al teniente general Orion. Te aguarda en el otro lado, en Terrallende."}}
D[9408] = {"Héroes olvidados",{"Habla con el comandante en jefe Danath Aterratrols en el Bastión del Honor."}}
D[9409] = {"Entrega urgente",{"Entrega el juego de viales a Zalduun en el Lugar del Accidente en el Valle Ammen."}}
D[9410] = {"Un espíritu guía",{"Usa el Tótem de lobo en el lugar donde encontraste el cuerpo de Krun Rompeloma y sigue al espíritu de lobo ancestral."}}
D[9415] = {"Preséntate ante el alguacil Murazul",{"Habla con el alguacil Murazul en el campamento de la Alianza cerca de Colmen'Zora."}}
D[9416] = {"Preséntate ante el general Kirika",{"Habla con el general Kirika en el campamento de la Horda cerca de Colmen'Regal."}}
D[9417] = {"La amenaza arakkoa",{"Gremni Barbalarga de la Península del Fuego Infernal quiere que mates a 4 surcadores del viento y 6 garraguardas Haal'eshi."}}
D[9418] = {"El orbe de Avruu",{"Lleva el orbe de Avruu al altar Haal'eshi al sureste de El Cubil de Haal'esh en la Península del Fuego Infernal y dáselo a Aeranas cuando quede libre."}}
D[9419] = {"Peinando el desierto",{"Encuentra y entrega la silitista al extractor de silitista y después habla con el alguacil Murazul en el campamento de la Alianza cerca de Colmen'Zora."}}
D[9420] = {"Las plumas más finas",{"Mirren Barbalarga de la Península del Fuego Infernal quiere que le lleves 8 plumas de kaliri de El Cubil de Haal'esh."}}
D[9421] = {"Entrenamiento de chamán"}
D[9422] = {"Peinando el desierto",{"Encuentra y entrega la silitista al extractor de silitista y después habla con el general Kirika en el campamento de la horda cerca de Colmen'Regal."}}
D[9423] = {"Regresa junto a Obadei",{"Informa al anacoreta Obadei del Templo de Telhamat, en la Península del Fuego Infernal, de la muerte de Sedai."}}
D[9424] = {"La venganza de Makuru",{"Makuru del Templo de Telhamat, en la Península del Fuego Infernal, quiere que le lleves 10 cuentas ancestrales Mag'har."}}
D[9425] = {"Informando en Molino Tarren",{"Ve a Molino Tarren, en las Laderas de Trabalomas, y habla con la consejera Nochealba."}}
D[9426] = {"Las Pozas de Aggonar",{"Amaan el Sabio quiere que vayas a las Pozas de Aggonar y mates 6 terroadictos y 6 putrefacciones virulentas."}}
D[9427] = {"Limpiando las aguas",{"Amaan el Sabio quiere que vayas a las Pozas de Aggonar y uses el vial de limpieza en el cadáver de Aggonar. Ve a ver a Amaan cuando el agua esté limpia de la esencia de Aggonar."}}
D[9428] = {"Misión en Puesto del Hachazo",{"Ve al Puesto del Hachazo en Vallefresno y habla con el consejero Jurasol."}}
D[9429] = {"Viaje a Villa Oscura",{"Ve a Villa Oscura en el Bosque del Ocaso y habla con el anacoreta Delan."}}
D[9430] = {"Las reliquias de Sha'naar",{"Amaan el Sabio del Templo de Telhamat en la Península del Fuego Infernal quiere que vayas a las Ruinas de Sha'naar y recuperes 10 reliquias de Sha'naar."}}
D[9431] = {"Un enfoque diferente",{"Recolecta 2 puñados de tierra purificante de Rocoso tronador y llévaselos a Wizlo Rodabrillante, en el Campamento del Tramo Blanco."}}
D[9432] = {"Viaje a Astranaar",{"Ve a Astranaar en Vallefresno y habla con el vindicador Palais."}}
D[9433] = {"En la Poza de la Luna",{"Usa la unidad de control del Robotrón cerca de la consola de control oculta en unos arbustos en el borde de la aguja más cercana a Thalanaar para tomar control del Robotrón 3000. Conduce al robot al extremo oeste de Las Mil Agujas, donde está la avanzada de la Alianza de Thalanaar. Usa el robot para recoger una muestra de agua de la Poza de la Luna y devuélveselo a Wizlo Rodabrillante en el Campamento del Tramo Blanco."}}
D[9434] = {"Probando el tónico",{"Entrega el cajón de componentes a la magistrix Elosai en el Poblado Viento Libre."}}
D[9435] = {"Los cristales desaparecidos",{"Recupera el envío de cristales raros de los Renegados y devuélveselo a Huraan en Costasur."}}
D[9436] = {"Técnicas Sangrapellejo",{"Nemeth Ojohalcón del campamento Grom'gol quiere que le lleves el tótem de un chamán Sangrapellejo."}}
D[9437] = {"El surcador del ocaso",{"Balandar Estrellaclara de Poblado Murohelecho quiere que rescates el carguero El surcador del ocaso y a su compañera Ithania de las tropas de Theramore en la Torre de la Punta Norte."}}
D[9438] = {"Mensaje para Thrall",{"Ve a Orgrimmar y entrega a Thrall la carta de Nazgrel."}}
D[9439] = {"Equipaje perdido",{"Recupera el paquete de consejero y el estoque de consejero en la Fortaleza de Angor y devuélveselos al consejero Sarophas en Kargath."}}
D[9440] = {"Bocaditos peligrosos",{"Da la comida mácula a los animales de Los Perdidos. Llévale las sobras a Cersei Canto Nocturno a Rocal en el Pantano de las Penas."}}
D[9441] = {"Tributo a los Mag'har",{"Thrall quiere que vayas a ofrecerle tus servicios a Gorkan Puñosangre en el Puesto Mag'har en la Península del Fuego Infernal."}}
D[9442] = {"Enfermedad debilitante",{"Clamor de Tierra Ryga del Puesto Mag'har en la Península del Fuego Infernal quiere que le lleves 1 champiñón capuseca de una cueva de La Gran Fisura."}}
D[9443] = {"La marca del Iluminado",{"Consigue la marca del Iluminado y llévasela a Mehlar Hojalba a El Baluarte en las Tierras de la Peste del Oeste."}}
D[9444] = {"Profanar la Tumba de Uther",{"Profana la Tumba de Uther y ve a ver a Mehlar Hojalba a El Baluarte en las Tierras de la Peste del Oeste."}}
D[9446] = {"La Tumba del Iluminado",{"Acompaña al anacoreta Truuen a la Tumba de Uther en las Tierras de la Peste del Oeste. Después habla con la suma sacerdotisa MacDonnell en el Campamento del Orvallo en las Tierras de la Peste del Oeste."}}
D[9447] = {"El bálsamo",{"Clamor de Tierra Ryga quiere que administres el bálsamo de sanación a 10 brutos Mag'har debilitados cerca del Puesto Mag'har en la Península del Fuego Infernal."}}
D[9448] = {"Piedad para los malditos",{"Mata a 3 Perdidos malditos y ve a ver al anacoreta Avuun a El Puerto en el Pantano de las Penas."}}
D[9449] = {"La llamada de la tierra",{"Habla con el Espíritu del Valle en La Arboleda Sagrada en el Valle Ammen."}}
D[9450] = {"La llamada de la tierra",{"Mata a 4 elementales de Tierra inquietos y ve a ver al Espíritu del Valle a La Arboleda Sagrada en el Valle Ammen."}}
D[9451] = {"La llamada de la tierra",{"Entrega el cristal de Tierra a Firmanvaar en el Lugar del Accidente en el Valle Ammen."}}
D[9452] = {"Delicioso pargo rojo",{"Usa la red de pescar draenei para pescar 10 pargos rojos. Lleva la red y el pescado a Diktynna a la Isla Bruma Azur."}}
D[9453] = {"Busca a Acteon",{"Entrega la caja de pargo rojo a Acteon en la Avanzada Azur."}}
D[9454] = {"La gran cacería de venados lunares",{"Lleva 6 solomillos de venado lunar a Acteon a la Avanzada Azur."}}
D[9455] = {"Extraños hallazgos",{"Entrega el cristal resplandeciente al exarca Menelaous en la Avanzada Azur."}}
D[9456] = {"Eliminando acechadores en la isla 2",{"El exarca Menelaous de la Avanzada Azur quiere que mates 8 cachorros de acechador nocturno infectado."}}
D[9457] = {"Un patrón inusual",{"Usa el don de Naias cerca del Altar de Naias para invocar al elemental de agua Naias. Derrótalo y lleva su corazón a Nemeth Ojohalcón al campamento Grom'gol."}}
D[9460] = {"Aunando fuerzas",{"Keltus Hojaoscura quiere que le robes el pañuelo bordado al jefe de centinelas y se lo lleves."}}
D[9461] = {"La llamada del fuego",{"Busca al profeta Velen en El Exodar en la Isla Bruma Azur."}}
D[9462] = {"La llamada del fuego",{"Busca a Tuluun en la Avanzada Azur en la Isla Bruma Azur."}}
D[9463] = {"Propiedades curativas",{"La anacoreta Fateema de la Avanzada Azur quiere que le lleves 8 ramas de atraparraíces."}}
D[9464] = {"La llamada del fuego",{"Habla con Templar en El Claro de Ascuas en la Isla Bruma Azur."}}
D[9465] = {"La llamada del fuego",{"Recupera la antorcha ritual y devuélvesela a Templar en El Claro de Ascuas en la Isla Bruma Azur."}}
D[9466] = {"Se busca: Garranegra la Indómita",{"Lleva la zarpa de Garranegra al capitán forestal Venn'ren en la Avanzada del Halcón en la Península del Fuego Infernal."}}
D[9467] = {"La llamada del fuego",{"Recolecta las cenizas de Prepotencia y devuélveselas junto con la antorcha ritual a Templar en El Claro de Ascuas, en la Isla Bruma Azur. Recuerda que puedas utilizar el orbe de retorno para teletransportarte junto a Templar cuando tengas las cenizas."}}
D[9468] = {"La llamada del fuego",{"Entrega las cenizas de Prepotencia a Tuluun en la Avanzada Azur en Isla Bruma Azur."}}
D[9469] = {"El apoyo de Barbapluma",{"Ve al Cobertizo de Barbapluma y habla con el enano si está en casa. Si no está, busca alguna pista sobre dónde puede estar."}}
D[9470] = {"Un gesto de buena fe",{"El embajador Rualeth de Pico Nidal quiere que mates al médico brujo Mai'jin y a su mascota araña Tcha'kaz."}}
D[9471] = {"A la caza de los depredadores",{"El embajador Rualeth de Pico Nidal quiere que mates 10 melenargentas sarnosos y 5 lobos melenargenta."}}
D[9472] = {"La amante de Arelion",{"La magistrix Carinda de la Avanzada del Halcón quiere que alejes a Viera Suspirosol del asentamiento y que uses el pergamino de Reprensión de Carinda."}}
D[9473] = {"La alternativa a la alternativa",{"Daedal de la Avanzada Azur quiere que le lleves 5 bulbos de boca de dragón azur."}}
D[9474] = {"La marca del Iluminado",{"Consigue la marca del Iluminado y devuélvesela al anacoreta Truuen en el Campamento del Orvallo, en las Tierras de la Peste del Oeste."}}
D[9475] = {"Reclamar los huevos",{"Recolecta 5 huevos de grifo y regresa junto al embajador Rualeth de Pico Nidal."}}
