D[9485] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un murciélago brumoso y vuelve junto a la teniente Correalba."}}
D[9486] = {"Domesticar la bestia",{"Usa la fusta de doma para domar un garragil mayor y vuelve junto a la teniente Correalba."}}
