D[10426] = {"Flora de los Ecodomos",{"Utiliza el modulador de campo de energía en los azotadores Farahlon. Observa los resultados y ve a ver a Aurine Lunardiente en La Flecha de la Tormenta cuando hayas realizado 10 pruebas."}}
D[10427] = {"Criaturas de los Ecodomos",{"Marca 12 talbuks para Aurine Lunardiente en La Flecha de la Tormenta. Puedes marcar talbulks machos o talbuks hembras utilizando el marcador talbuk."}}
D[10428] = {"El pescador desaparecido",{"Encuentra a Cowlen en el puerto sureste de la Isla Bruma de Plata, frente a la costa de Bruma Azur."}}
D[10429] = {"Cuando la naturaleza va demasiado lejos",{"Aurine Lunardiente de La Flecha de la Tormenta quiere que le lleves un corazón de hidra descomunal."}}
D[10430] = {"Probando el prototipo",{"Lleva el artefacto de reparación a Tashar en el Ecodomo Campolejano, en Tormenta Abisal."}}
