D[10432] = {"Pruebas condenatorias",{"Consigue 8 órdenes de Kael'thas de los demonios de la Forja de Maná Ara y llévaselas al maestro de espías Thalodien en el Área 52.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
D[10433] = {"Guardando las apariencias",{"Lleva diez pelambres de lince Rasgacolmillo a Shauly Poro, en el Puesto de la Tierra Media."}}
D[10434] = {"El dúo dinámico",{"Habla con Audi la Aguja en la Flecha de la Tormenta, en Tormenta Abisal."}}
D[10435] = {"Recuperar las mercancías",{"Audi la Aguja, de la Flecha de la Tormenta, quiere que le lleves diez segmentos de generador de domo."}}
D[10436] = {"¡Todo despejado!",{"Tashar, destacado en el Ecodomo Campolejano, quiere que mates a 12 raptores dienteguadaña."}}
D[10437] = {"Receta para la destrucción",{"El profesor Dabiri de la Avanzada del Protectorado en la Tormenta Abisal quiere que recuperes 8 trozos de Dimensius."}}
D[10438] = {"En alas abisales",{"El profesor Dabiri de la Avanzada del Protectorado en la Tormenta Abisal quiere que uses el perturbador de fase cuando estés en el radio de alcance del conducto del vacío que se encuentra sobre Ultris. Suelta tantas descargas con el perturbador de fase como sea necesario hasta asegurar la aniquilación total. Las cargas del perturbador de fase alcanzarán directamente el conducto del vacío siempre que estés lo suficientemente cerca para usarlo.","","Si lo consigues, regresa junto al profesor Dabiri."}}
D[10439] = {"Dimensius el Devoratodo",{"El profesor Dabiri de la Avanzada del Protectorado, en la Tormenta Abisal, quiere que hables con el capitán Saeed, te unas a su ejército que irá a Forja de Maná Ultris ¡y mates a Dimensius el Devoratodo!"}}
D[10440] = {"¡Bingo!",{"Regresa a La Flecha de la Tormenta, en Tormenta Abisal, y habla con Ghabar."}}
