D[10442] = {"Ayudar al Puesto Cenarion",{"La halconera Drenna Ríobrisa desea que ofrezcas tus servicios a Thiah Melenarroja del Puesto Cenarion, en la Península del Fuego Infernal."}}
D[10443] = {"Ayudar al Puesto Cenarion",{"Amaan el Sabio desea que ofrezcas tus servicios a Thiah Melenarroja del Puesto Cenarion, en la Península del Fuego Infernal."}}
D[10444] = {"Informa en el Puesto Allerian",{"Jenai Susurrestelar quiere que informes al teniente Meridiano del Puesto Allerian en el Bosque de Terokkar."}}
D[10445] = {"Los viales de la eternidad",{"Soridormi de las Cavernas del Tiempo quiere que recuperes los restos del vial de Vashj de Lady Vashj en la Reserva Colmillo Torcido, y los restos del vial de Kael de Kael'thas Caminante del Sol, en El Castillo de la Tempestad."}}
D[10446] = {"El código final",{"El teniente Meridiano quiere que uses el código final para detonar la bomba de maná. Informa después a Jenai Susurrestelar del Bastión Allerian en el Bosque de Terokkar."}}
D[10447] = {"El código final",{"La sargento Chawni quiere que uses el código final para desactivar la bomba de maná. A continuación preséntate ante Tooki en el Bastión Rompepedras, en el Bosque de Terokkar."}}
D[10448] = {"Preséntate en el Campamento Rompepedras",{"Tooki quiere que hables con la sargento Chawni en el Campamento Rompepedras, en el Bosque de Terokkar."}}
D[10449] = {"La boticaria Zelana",{"Vurtox Rompehachas de Thrallmar quiere que lleves muestras de sangre de Mascahuesos a la boticaria Zelana en la Caída del Atracador Vil."}}
D[10450] = {"Sangre de Mascahuesos",{"Llévale 12 viales de sangre de Mascahuesos a Vurtok Rompehachas en Thrallmar."}}
D[10451] = {"Huida de la Cisterna Cicatriz Espiral",{"Escolta a la ensalmadora de la tierra Wilda hasta salir de la Cisterna Cicatriz Espiral y después busca al ensalmador de la tierra Torlok en El Altar de Condenación que se encuentra en la parte oeste de las afueras de La Mano de Gul'dan."}}
