D[10477] = {"Más abalorios de guerra"}
D[10478] = {"¡Más abalorios de guerra!"}
D[10479] = {"Demostrar tu fuerza",{"El celador Tororroc de Garadar quiere que consigas diez abalorios de guerra de obsidiana de los diferentes ogros que habitan Nagrand."}}
D[10480] = {"Espíritus de agua iracundos",{"El ensalmador de la tierra Torlok de El Altar de Condenación, en el Valle Sombraluna, quiere que uses el Tótem de espíritus para capturar 5 almas acuáticas."}}
D[10481] = {"Espíritus de aire iracundos",{"El ensalmador de la tierra Torlok de El Altar de Condenación, en el Valle Sombraluna, quiere que uses el Tótem de espíritus para capturar 10 almas aéreas."}}
D[10482] = {"Orcos viles carroñeros",{"Mata a 20 orcos Mascahuesos y vuelve con Amadi al Bastión del Honor."}}
D[10483] = {"Malos augurios",{"La teniente Amadi, del Bastión del Honor, quiere que le lleves un dije maldito al cabo Crestahierro, de la Punta de Expedición."}}
D[10484] = {"Dijes malditos",{"Lleva 12 dijes malditos al cabo Crestahierro, en la Punta de Expedición."}}
D[10485] = {"Señor de la guerra del Foso Sangrante",{"Lleva la armadura destrozada del señor de la guerra Morkh al cabo Crestahierro, en la Punta de Expedición."}}
D[10486] = {"La naturaleza invasora",{"Mata a doce flebotomistas Alacuchilla."}}
D[10487] = {"Polvo de los dracos",{"Reúne cuatro polvos de draco hada."}}
D[10488] = {"Proteger a los nuestros",{"Usa el ungüento de Gor'drek en 5 de los lobos temibles del Señor del Trueno."}}
D[10489] = {"Talar un antiguo árbol",{"Consigue el tronco de Manofirme Raizhonda."}}
D[10490] = {"La llamada del agua",{"Habla con el clarividente Nobundo en La Sala de Cristal dentro de El Exodar, en la Isla Bruma Azur."}}
D[10491] = {"La llamada del aire",{"Habla con el clarividente Nobundo en La Sala de Cristal dentro de El Exodar, en la Isla Bruma Azur."}}
D[10492] = {"Una propuesta seria",{"Lleva 15 muestras de sangre de Cuna del Invierno, 20 piezas de oro y 1 par de ataduras de elementos a Deliana, en Forjaz."}}
D[10493] = {"Una propuesta seria",{"Lleva 15 muestras de veneno de Silithus, 20 piezas de oro y 1 par de brazales Forjaluz a Mokvar, en Orgrimmar."}}
D[10494] = {"Una compensación justa"}
D[10495] = {"Una compensación justa",{"Lleva 1 cinturón Forjaluz y 1 par de guanteletes Forjaluz a Mokvar a Orgrimmar."}}
D[10496] = {"La despedida de Anthion"}
D[10497] = {"La despedida de Anthion",{"Lleva 1 par de botas, 1 par de quijotes y 1 par de bufas Forjaluz a Mokvar a Orgrimmar."}}
D[10498] = {"Guardar lo mejor para el final"}
D[10499] = {"Guardar lo mejor para el final",{"Dale a Mokvar tu yelmo y tu coraza Forjaluz."}}
D[10500] = {"¡La Horda te necesita!",{"Habla con el señor de la guerra Gorchuk en el Valle de los Espíritus de Orgrimmar."}}
D[10501] = {"¡La Alianza te necesita!",{"Habla con el mariscal de campo Nevanur en La Sala Militar de Forjaz."}}
D[10502] = {"Los ogros Machacasangre",{"Destruye 30 ogros Machacasangre en la Avanzada Machacasangre."}}
D[10503] = {"La amenaza Aguja del Filo",{"Destruye 30 ogros Aguja del Filo y 10 raptores Aguja del Filo en el Bastión Aguja del Filo y los Dominios Aguja del Filo."}}
D[10504] = {"Los ogros Aguja del Filo",{"Destruye 30 ogros Aguja del Filo en el Bastión Aguja del Filo y en los Dominios Aguja del Filo."}}
D[10505] = {"Los ogros Machacasangre",{"Destruye 30 ogros Machacasangre en la Avanzada Machacasangre."}}
D[10506] = {"Una situación extrema",{"Rina Lunabril quiere que te lleves sus polvos de disminución y se los apliques a 5 de los lobos temibles Machacasangre, que se pueden encontrar en la Avanzada Machacasangre y en el Barranco Machacasangre."}}
D[10507] = {"Punto de inflexión",{"Usa la piedra de teletransporte de Socrethar en el Punto de Invasión: Señor Supremo, al norte de la Base Forja: Olvido, para transportar a tu grupo hasta el Embarcadero de Socrethar. Una vez allí, utiliza la Presencia de Voren'thal para vencer a Socrethar.","","Llevar a cabo misiones para los Arúspices hará que tu reputación Aldor disminuya."}}
D[10508] = {"Un regalo para Voren'thal",{"El maestro de espías Thalodien, del Área 52, quiere que consigas la primera mitad de la piedra de Socrethar del maestro de forja Morug, en la Base Forja: Olvido, y la segunda mitad de la piedra de Socrethar del maestro de Silroth, en la Base Forja: Gehenna.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
D[10509] = {"Destinado a la gloria",{"Lleva la piedra de teletransporte de Socrethar a Voren'thal el Vidente, en la Grada del Arúspice, de la Ciudad de Shattrath.","","Llevar a cabo misiones para los Arúspices hará que tu reputación Aldor disminuya."}}
D[10510] = {"En el interior de la Mina Draenetista",{"Consigue 5 cristales de la Mina Draenetista."}}
D[10511] = {"Una extraña cerveza",{"Reúne 11 cervezas Machacasangre aterrabrutos."}}
D[10512] = {"Repostando Aguja del Filo",{"Utiliza el barril de Machacasangre aterrabrutos para intentar emborrachar a 5 ogros Aguja del Filo."}}
D[10513] = {"Oronok Corazón Roto",{"Busca a Oronok Corazón Roto en la Barrera Arrasada - al norte de la Cisterna Cicatriz Espiral."}}
D[10514] = {"Yo era muchas cosas...",{"Oronok Corazón Roto, de la Granja de Oronok, en el Valle Sombraluna, quiere que recuperes diez tubérculos de Sombraluna de las Llanuras Devastadas.","","También quiere que le devuelvas el silbato de jabalíes de Oronok cuando hayas terminado."}}
D[10515] = {"Una lección aprendida",{"Oronok Corazón Roto, de la Granja de Oronok, en el Valle Sombraluna, quiere que destruyas diez huevos de despellejador voraz de las Llanuras Devastadas."}}
D[10516] = {"Las armas de un vindicador",{"Recupera la espada y el escudo de la vindicadora Vuuleen."}}
D[10517] = {"Gorr'Lelo, ha llegado tu hora...",{"Mata a Gorr'Lelo, líder de los ogros del Bastión Aguja del Filo."}}
D[10518] = {"Clavar el estandarte",{"Usa el estandarte de los Aguja del Filo sobre la Torre Quiebranorte para atraer a Gurn Jalazampa. Obtén el estandarte Aguja del Filo y el yelmo de Gurn Jalazampa."}}
D[10519] = {"La Clave de Condenación: historia y verdad",{"Oronok Corazón Roto, en la Granja de Oronok del Valle Sombraluna, quiere que escuches su relato. Habla con Oronok para comenzar a escuchar su relato."}}
D[10520] = {"Ayuda al archidruida Corzocelada",{"Habla con el archidruida Fandral Corzocelada en Darnassus."}}
D[10521] = {"Grom'tor, hijo de Oronok",{"Encuentra a Grom'tor, hijo de Oronok, en el Alto Cicatriz Espiral del Valle Sombraluna."}}
D[10522] = {"La Clave de Condenación: La carga de Grom'tor",{"Grom'tor, hijo de Oronok, en el Alto Cicatriz Espiral del Valle Sombraluna, quiere que recuperes el primer fragmento de la Clave de Condenación."}}
D[10523] = {"La Clave de Condenación - Primer trozo recuperado",{"Lleva la caja fuerte de Grom'tor a Oronok Corazón Roto en la Granja de Oronok, en el Valle Sombraluna."}}
D[10524] = {"Artefactos del clan Señor del Trueno",{"Recupera el tambor del clan Señor del Trueno, la flecha del clan Señor del Trueno, y la tablilla del clan Señor del Trueno."}}
D[10525] = {"Visión guía",{"Usa el trozo de alma ígnea para transformar tu espíritu en una visión guía, que te revelará la ubicación de la última reliquia del Señor del Trueno."}}
D[10526] = {"La Punta de Trueno",{"Recupera la Punta de Trueno."}}
D[10527] = {"Ar'tor, hijo de Oronok",{"Encuentra a Ar'tor, hijo de Oronok, en el Alto Illidari del Valle Sombraluna."}}
D[10528] = {"Cárceles de cristal demoníacas",{"Busca a la maestra del dolor Gabrissa en el Alto Illidari, mátala y vuelve junto al cadáver de Ar'tor, hijo de Oronok, con la llave cristalina."}}
D[10529] = {"El camino del cazador",{"Habla con la teniente Correalba en El Retiro del Errante, en el Bosque Canción Eterna."}}
D[10530] = {"El camino del cazador",{"Habla con la teniente Correalba en El Retiro del Errante, en el Bosque Canción Eterna."}}
D[10531] = {"La batalla por la Cuenca de Arathi",{"Asalta la mina, el aserradero, la herrería y la granja y vuelve entonces junto al mariscal de campo Uluz en el Refugio de la Zaga."}}
D[10532] = {"Córtale el suministro a la Liga de Arathor",{"Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela a Mortacechador Mortis en Sentencia."}}
D[10533] = {"Más cajas de suministros"}
D[10534] = {"La vuelta a casa",{"Caedmos, en El Exodar, te ha pedido que vayas a verle."}}
D[10535] = {"Los recursos de la Cuenca de Arathi",{"Llévate la victoria en la batalla por la Cuenca de Arathi, consigue una caja de suministros de Arathi y llévasela al sargento Maclear en el Refugio de la Zaga."}}
D[10536] = {"Más cajas de suministros"}
D[10537] = {"Lohn'goron, arco del corazón roto",{"El espíritu de Ar'tor en el Alto Illidari, en el Valle Sombraluna, quiere que recuperes Lohn'goron, arco del corazón roto. Lo tiene un demonio de la zona."}}
D[10538] = {"Sangre en ebullición",{"Vierte la sangre de Foso Sangrante en su caldera maldita para obtener sangre hervida. Lleva 12 muestras de sangre hervida al boticario Albreck en la Avanzada Rompeloma."}}
D[10539] = {"La vuelta a casa",{"Caedmos, en El Exodar, te ha pedido que vayas a verle."}}
D[10540] = {"La Clave de Condenación. La carga de Ar'tor",{"El espíritu de Ar'tor en el Alto Illidari, en el Valle Sombraluna, quiere que consigas el segundo fragmento de la Clave de Condenación que tiene Veneratus el Múltiple.","","Las criaturas que ataque o dañe el espíritu cazador no proporcionan botín ni experiencia."}}
D[10541] = {"La Clave de Condenación. Segundo trozo recuperado",{"Lleva la caja fuerte de Ar'tor a Oronok del corazón roto en la Granja de Oronok, en el Valle Sombraluna."}}
D[10542] = {"Mi pipaaa me la robaaaron...",{"Recupera la pipa de agua de T'chali y 10 cervezas Machacasangre aterrabrutos."}}
D[10543] = {"Grimnok y Korgaah, ¡voy a por vosotros!",{"Mata a Grimnok Belinato y a Korgaah."}}
D[10544] = {"¡Una maldición para ambos clanes!",{"Utiliza el fetiche poderoso desalmado para maldecir 5 edificios en el Bastión Aguja del Filo y 2 en la Avanzada Machacasangre."}}
D[10545] = {"La mezcla Aguja del Filo",{"Utiliza el barril de Machacasangre aterrabrutos para emborrachar a 5 ogros Aguja del Filo."}}
D[10546] = {"Borak, hijo de Oronok",{"Encuentra a Borak, hijo de Oronok, cerca de Punta Eclipse, en el Valle Sombraluna."}}
D[10547] = {"Sobre cabezacardos y huevos...",{"Borak, hijo de Oronok en el puente al norte de Punta Eclipse, quiere que encuentres un huevo de arakkoa podrido y se lo lleves a Tobias el Comeporquería en la Ciudad de Shattrath, al noroeste del Bosque de Terokkar."}}
D[10548] = {"La triste verdad",{"Eralan de Tranquillien quiere que recuperes la cabeza reducida del arqueólogo de uno de los cofres de Zeb'Tela o Zeb'Nowa."}}
D[10550] = {"El fardo de cardos de sangre",{"Llévale el fardo de cardos de sangre a Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna."}}
D[10551] = {"Lealtad hacia los Aldor"}
D[10552] = {"Lealtad a los Arúspices"}
D[10553] = {"Voren'thal el vidente",{"Habla con Voren'thal el Vidente dentro de la Biblioteca del Profeta, en la Grada del Arúspice de la Ciudad de Shattrath.","","Llevar a cabo misiones para los Arúspices hará que tu nivel de reputación Aldor disminuya."}}
D[10554] = {"Ishanah",{"Habla con Ishanah dentro del Santuario de Luz Inagotable, en Alto Aldor, de la Ciudad de Shattrath.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10555] = {"Malestar",{"Reúne 18 plumas de Lashh'an arrancadas."}}
D[10556] = {"Arañazos",{"Usa el manojo de plumas en el círculo de hechizos de Lashh'an."}}
D[10557] = {"Vuelo de prueba: el Cefirium Capacitorium",{"Habla con Rally Pillazas para usar el Cefirium Capacitorium."}}
D[10558] = {"Venerado con el Bastión del Honor",{"El comandante en jefe Danath Aterratrols, del Bastión del Honor, en la Península del Fuego Infernal, quiere que seas venerado en el Bastión del Honor luchando contra los orcos viles dentro de Las Salas Arrasadas de la Ciudadela del Fuego Infernal."}}
D[10559] = {"Venerado con Thrallmar",{"Nazgrel, de Thrallmar, en la Península del Fuego Infernal, quiere que seas venerado en Thrallmar luchando contra los orcos viles que hay dentro de Las Salas Arrasadas de la Ciudadela del Fuego Infernal."}}
D[10560] = {"Venerado con Sha'tar",{"A'dal de la Ciudad de Shattrath quiere que seas venerado en Sha'tar venciendo a las tropas de Kael'thas dentro de El Castillo de la Tempestad."}}
D[10561] = {"Venerado con los Vigilantes del Tiempo",{"Andormu, dentro de las Cavernas del Tiempo de Tanaris, quiere que seas venerado entre los Vigilantes del Tiempo, al continuar defendiendo los sucesos de la Antigua Trabalomas y la Ciénaga Negra, en las Cavernas del Tiempo."}}
D[10562] = {"¡Asediados!",{"El comandante del aire Nuainn, fuera del Bastión Martillo Salvaje, quiere que mates a diez agresores infernales."}}
D[10563] = {"Al Bastión de la Legión",{"Ponte en camino hacia el Bastión de la Legión y ubica el aparato de comunicación de la Legión. Cuando estés cerca del aparato, usa tu disfraz y averigua los planes de la Legión. Vuelve con el comandante del aire Nuainn al Bastión Martillo Salvaje cuando hayas completado tu misión."}}
D[10564] = {"¡Volar a los infernales!",{"Acciona la bomba vil cuando estés en el glifo verde, en Bastión de la Legión. Informa al comandante del aire Nuainn en Bastión Martillo Salvaje cuando hayas completado tu misión."}}
D[10565] = {"Las piedras de Vekh'nir",{"Recoge y usa un cristal Vekh'nir del círculo de hechizos de los Vekh'nir para crear un cristal Vekh'nir cargado."}}
D[10566] = {"Ensayo y error",{"Prueba cada varita de Dertrok en un esclavo ogro arakkoa. Con cada varita tendrás que usar un cristal imbuido Vekh'nir."}}
D[10567] = {"Crear el colgante",{"Busca 6 garras de Ruuan'ok y úsalas para invocar a un presagista del Cuervo en el Círculo del Oráculo Ruuan'ok. Mátalo y obtén su colgante de presagista."}}
D[10568] = {"Las tablillas de Baa'ri",{"La anacoreta Ceyla del Altar de Sha'tar quiere que recojas 12 tablillas Baa'ri del suelo y de los trabajadores Lengua de ceniza en las Ruinas de Baa'ri.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10569] = {"Las Ruinas de Sketh'lon",{"Recupera las páginas 1, 2 y 3 del diario del comandante Skethlon del cónclave oscuro arakkoa en las Ruinas de Sketh'lon y entrégaselas al jinete de grifo Kieran."}}
D[10570] = {"Perder la cabeza... por unos cardos",{"Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna, quiere que recuperes la misiva de Tempestira."}}
D[10571] = {"Oronu el Anciano",{"La anacoreta Ceyla del Altar de Sha'tar quiere que consigas las órdenes de Akama de Oronu el Anciano en las Ruinas de Baa'ri.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10572] = {"Preparación de la bomba",{"Consigue 1 batería de atracador vil y 1 placa de armadura de atracador vil. Llévaselas al comandante del aire Nuainn en el Bastión Martillo Salvaje."}}
D[10573] = {"La Forja Muerta",{"Preséntate al agitador Ewan Alasalvaje en la Torre de La Forja Muerta."}}
D[10574] = {"Los corruptores Lengua de Ceniza",{"Recupera los 4 trozos de los medallones de Haalum, Eyeknen, Lakaan y Uylaru, y regresa junto a la anacoreta Ceyla del Altar de Sha'tar, en el Valle Sombraluna.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10575] = {"La Jaula de la Guardiana",{"La anacoreta Ceyla quiere que entres en la Jaula de la Guardiana, al sur de las Ruinas de Baa'ri, e interrogues a Sanoru sobre el paradero de Akama.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10576] = {"Revuelo en Sombraluna",{"Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna, quiere que recuperes 6 piezas de armadura eclipsion."}}
D[10577] = {"Lo que Illidan quiere, lo consigue...",{"Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna, quiere que entregues el mensaje de Illidan al Gran Comandante Ruusk de Punta Eclipse."}}
D[10578] = {"La Clave de Condenación: La carga de Borak",{"Borak, hijo de Oronok, en el puente próximo a la Punta Eclipse en el Valle Sombraluna, quiere que recuperes la tercera parte de la Clave de Condenación de Ruul el Ensombrecedor.","","Para esta misión hará falta un grupo."}}
D[10579] = {"La Clave de Condenación: Tercer trozo recuperado",{"Lleva la caja fuerte de Borak a Oronok Corazón Roto en la Granja de Oronok, en el Valle Sombraluna."}}
D[10580] = {"¿Dónde se han metido esos malditos gnomos?",{"Busca hacia el sur de la Cresta Dentada, en las Montañas Filospada, alguna pista sobre el paradero de Toshley y los demás gnomos."}}
D[10581] = {"Sigue el rastro",{"Sigue el rastro de piezas sueltas por la rampa que conduce a Loma Tajo. Habla con Toshley en la Estación de Toshley, en las Montañas Filoespada."}}
D[10582] = {"Esbirros del Consejo de la Sombra",{"El agitador Ewan Alasalvaje, en la Torre de La Forja Muerta, quiere que mates a 10 guardianes Forja Muerta y a 5 invocadores Forja Muerta."}}
D[10583] = {"El destino de Flanis",{"El agitador Ewan Alasalvaje, en la Torre de La Forja Muerta, quiere que busques en La Forja Muerta a Flanis Alapresta y recuperes su talega."}}
D[10584] = {"Recoger transformadores de energía",{"Usa el acumulador magnético protovoltaico para reunir 5 electromentales."}}
D[10585] = {"La cámara de invocación",{"Consigue 1 desplazador elemental de un herrero Forja Muerta o de un manitas Forja Muerta, y úsalo para perturbar el ritual de la cámara de invocación. Preséntate al agitador Ewan Alasalvaje en la Torre de La Forja Muerta cuando hayas completado la tarea."}}
D[10586] = {"¡Tumba al belisario!",{"Derrota al belisario Razuun, recupera sus órdenes y después preséntate al comandante del aire Nuainn del Bastión Martillo Salvaje."}}
D[10587] = {"Patio de Armas de Karabor",{"La exarca Onaala del Altar de Sha'tar quiere que consigas 8 gujas de Furia del Sol de los suplicantes cazadores de demonios y de los iniciados cazadores de demonios que se encuentran en las Ruinas de Karabor, al sureste del Altar de Sha'tar.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10588] = {"La Clave de Condenación",{"Usa la Clave de Condenación en El Altar de Condenación para invocar a Cyrukh el señor del Fuego.","","Destruye a Cyrukh el señor del Fuego y habla con el ensalmador de la tierra Torlok, que también se encuentra en El Altar de Condenación."}}
D[10589] = {"Obtener acceso",{"Llévale un control de teletransportador de la Legión al comandante del aire Nuainn del Bastión Martillo Salvaje. Sabemos que los forjadores de armas y los caminantes de cólera Mo'arg del Bastión de la Legión llevan estos instrumentos."}}
D[10590] = {"Demuestra tu odio",{"Mehlar Hojalba en El Baluarte quiere que le lleves 20 piedras de la Plaga de los esbirros."}}
D[10592] = {"La sabiduría de la reina alma en pena",{"Llévale los fragmentos de piedra de la Plaga a Lady Sylvanas Brisaveloz en Entrañas."}}
D[10593] = {"Mal ancestral",{"Descubre los secretos de El Templo de Atal'Hakkar para soltar a Atal'alarion y recuperar la vid pútrida de su carne. Vuelve a ver a Mehlar en El Baluarte cuando lo hayas hecho."}}
D[10594] = {"Medir la frecuencia resonante",{"Coloca los escáneres de frecuencia oscilante de tal forma que cuando estés de pie en medio de los mismos, te alcancen 5 campos oscilantes superpuestos."}}
D[10595] = {"¡Asediados!",{"El Guardia de sangre Gulmok, de las afueras de la Aldea Sombraluna, quiere que mates a 10 agresores infernales."}}
D[10596] = {"Al Bastión de la Legión",{"Encamínate al Bastión de la Legión, encuentra el aparato de comunicación de la Legión y averigua los planes de la Legión mientras estés disfrazado. Regresa junto al Guardia de sangre Gulmok en la Aldea Sombraluna cuando hayas completado la misión."}}
D[10597] = {"Preparación de la bomba",{"Consigue 1 batería de atracador vil y 1 placa de armadura de atracador vil. Llévaselos al Guardia de sangre Gulmok en la Aldea Sombraluna."}}
D[10598] = {"¡Infernales por los aires!",{"Usa la bomba vil cuando estés de pie sobre el glifo verde del Bastión de la Legión. Preséntate al Guardia de sangre Gulmok en la Aldea Sombraluna."}}
D[10599] = {"La Forja Muerta",{"Preséntate al explorador Zagran en la Vigía de la Escoria"}}
D[10600] = {"Esbirros del Consejo de la Sombra",{"El explorador Zagran, en la Vigía de la Escoria, quiere que mates a 10 guardianes Forja Muerta y a 5 invocadores Forja Muerta."}}
D[10601] = {"El destino de Kagrosh",{"El explorador Zagran, en la Vigía de la Escoria, quiere que busques en La Forja Muerta a Kagrosh y recuperes su paquete"}}
D[10602] = {"La cámara de invocación",{"Consigue 1 desplazador elemental de un herrero Forja Muerta o de un manitas Forja Muerta, y úsalo para perturbar el ritual de la cámara de invocación. Vuelve junto al explorador Zagran en la Vigía de la Escoria después de completar esta tarea."}}
D[10603] = {"¡Tumba al belisario!",{"Derrota al belisario Razuun, recupera sus órdenes y después preséntate al Guardia de sangre Gulmok en la Aldea Sombraluna."}}
D[10604] = {"Obtener acceso",{"Llévale un control de teletransportador de la Legión al Guardia de sangre Gulmok de la Aldea Sombraluna. Sabemos que los forjadores de armas y los caminantes de cólera Mo'arg del Bastión de la Legión llevan estos instrumentos."}}
D[10605] = {"Cita con Carendin",{"Habla con Carendin Halgar en Entrañas."}}
D[10606] = {"El Arte del Cuidado de los Atracadores Viles",{"Mata al doctor Gutrick y consigue su llave. Usa la llave para abrir la caja fuerte del doctor para recuperar El Arte del Cuidado de los Atracadores Viles y llévale este libro a Plexi en el Punto de invasión: Cataclismo."}}
D[10607] = {"Susurros del Dios Cuervo",{"Mata al arakkoa Grishna para poder entender la palabra del Cuervo durante 2 minutos. Mientras estés bajo los efectos del hechizo, podrás encontrar y recibir la profecía de los cuatro santuarios."}}
D[10608] = {"Limpieza de despellajadores",{"Mata a 10 despellejadores de cristal."}}
D[10609] = {"¿Qué fue primero? ¿El draco o el huevo?",{"Reúne 3 esencias de draco protoinfernal, 3 esencias de draco adolescente y 3 esencias de draco adulto."}}
D[10610] = {"Principios básicos de posibilidad"}
D[10611] = {"El Arte del Cuidado de los Atracadores Viles",{"Mata al Doctor Maleficus y consigue la llave del doctor. Usa la llave para abrir la caja fuerte del doctor, para recuperar El Arte del Cuidado de los Atracadores Viles y entrégale el libro a Nakansi, en el Punto de invasión: Cataclismo."}}
D[10612] = {"El vil y la furia",{"Usa una consola de control de atracador vil para controlar un atracador vil centinela. Destruye a sesenta infernales Forja Muerta antes de que falle tu atracador vil. Cuando hayas completado tu misión, informa a Plexi en el Punto de Invasión: Cataclismo."}}
D[10613] = {"El vil y la furia",{"Usa una consola de control de atracador vil para controlar un atracador vil centinela. Destruye a sesenta infernales Forja Muerta antes de que falle tu atracador vil. Cuando hayas completado tu misión, informa a Nakansi en el Punto de Invasión: Cataclismo."}}
D[10614] = {"Susurros en el viento",{"Busca a Leoroxx en la Aldea Mok'Nathal en las Montañas Filospada."}}
D[10615] = {"La Foresta Ruuan",{"Habla con Timeon en Soto Eterno, que está en la Foresta Ruuan, en las Montañas Filospada."}}
D[10617] = {"Capullos de Alaseda",{"Recoge ocho capullos de Alaseda de las larvas de Alaseda.","","Mata a la larva rápidamente o se convertirá en Alaseda, destruyendo el capullo."}}
D[10618] = {"Las alas más suaves",{"Recoge doce alas iridiscentes."}}
D[10619] = {"La tribu Lengua de Ceniza",{"El vindicador Aluumen quiere que vayas a las Ruinas de Baa'ri y mates a 3 cuidadores Lengua de ceniza, 4 guerreros Lengua de ceniza y 6 chamanes Lengua de ceniza.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10620] = {"La amenaza de Crestaespina",{"Mata a diez acechadoras Crestaespina."}}
D[10621] = {"El fragmento aterraillidari",{"Lleva el fragmento aterraillidari a Ordinn Tronapuño en el Bastión Martillo Salvaje."}}
D[10622] = {"Prueba de lealtad",{"Mata a Zandras en la Jaula de la Guardiana, en el Valle Sombraluna y vuelve a ver a Sanoru."}}
D[10623] = {"El fragmento aterraillidari",{"Lleva el fragmento aterraillidari a Grokom Ojomuerte en la Aldea Sombraluna."}}
D[10624] = {"Una de fantasmas",{"La boticaria jefe Hildagard de la Aldea Sombraluna, en el Valle Sombraluna, quiere que le lleves 15 muestras de ceniza siempreardiente."}}
D[10625] = {"Espectróculos",{"La boticaria jefe Hildagard de la Aldea Sombraluna, en el Valle Sombraluna, quiere que mates a 12 zelotes de Sombraluna."}}
D[10626] = {"Tomar las armas",{"Ordinn Tronapuño en el Bastión Martillo Salvaje quiere que le lleves las gujas de Mazakradon y de Morgroron."}}
D[10627] = {"Tomar las armas",{"Grokom Ojomuerte, de la Aldea Sombraluna, quiere que le lleves la guja de Mazakradon y la guja de Morgroron."}}
D[10628] = {"Akama",{"Habla con Akama en la cámara oculta, en la Jaula de la Guardiana."}}
D[10629] = {"Un trabajo que te cagas",{"Usa el silbato de can manáfago para invocar un can de guardia vil. Dale un paseo al can de guardia vil y mata varios jabinfernos trastornados. Busca las llaves de la trituradora en los \"desechos\" del can de guardia vil. Devuélvele las llaves de la trituradora al supervisor Razelcraz en la mina al noroeste de Thrallmar."}}
D[10630] = {"El subsuelo de Thrallmar",{"Mata a Urga'zz y regresa junto al supervisor Razelcraz en la mina al noroeste de Thrallmar."}}
D[10632] = {"Cortar tus dientes",{"Consigue 5 dientes Faucedaga extra afilados."}}
D[10633] = {"Teron Sanguino: Tradición y Leyenda",{"La boticaria jefe Hildagard de la Aldea Sombraluna, en el Valle Sombraluna, quiere que encuentres el espíritu Sombraluna ancestral.","","Si pierdes tus espectróculos, la boticaria jefe Hildagard puede hacerte otro par."}}
D[10634] = {"Adivinación: la armadura de Sanguino",{"El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la armadura de Sanguino."}}
D[10635] = {"Adivinación: la capa de Sanguino",{"El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la capa de Sanguino."}}
D[10636] = {"Adivinación: la clava de Sanguino",{"El espíritu Sombraluna ancestral en El Altar de las Sombras, al sureste del Valle Sombraluna, quiere que consigas la clava de Sanguino."}}
D[10637] = {"Una distracción necesaria",{"La exarca Onaala quiere que vuelvas a las Ruinas de Karabor y encuentres una forma de liberar a Azaloth de sus captores.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10638] = {"NOT A QUEST",{"Seek <NAME> in the <DISTRICT> of Silvermoon City."}}
D[10639] = {"Yo, Teron Sanguino",{"El espíritu Sombraluna ancestral te ha utilizado como si fueras un títere. Ahora que has conseguido los objetos que necesitaba, ha revelado su verdadera identidad, Teron Sanguino. Para liberarte de su posesión, debes hacer lo que te pide y matar a Karsius el vigía anciano.","","Si tienes éxito, vuelve a ver a la boticaria jefe Hildagard en la Aldea Sombraluna."}}
D[10640] = {"Altruis",{"Dirígete al oeste de Nagrand y encuentra a Altruis el Sufridor.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10641] = {"Contra la Legión",{"Altruis el Sufridor quiere que consigas sangre recién extraída de una sacerdotisa de la cólera de la Base Forja: Gehenna en Tormenta Abisal. Derrámala en el suelo y mata al avatar de Sathal. Regresa junto a Altruis cuando hayas completado esta tarea."}}
D[10642] = {"Un fantasma en la máquina",{"Zorus el Justiciero en el Bastión Martillo Salvaje, en el Valle Sombraluna, quiere que le lleves 15 muestras de ceniza siempreardiente."}}
D[10643] = {"Presagistas de Sombraluna",{"Zorus el Justiciero en el Bastión Martillo Salvaje, en el Valle Sombraluna, quiere que mates a 12 presagistas de Sombraluna."}}
D[10644] = {"Teron Sanguino: Tradición y Leyenda",{"Zorus el Justiciero en el Bastión Martillo Salvaje,en el Valle Sombraluna, quiere que encuentres al espíritu Sombraluna ancestral.","","Si pierdes los espectróculos, Zorus el Justiciero te hará un nuevo par."}}
D[10645] = {"Yo, Teron Sanguino",{"El espíritu Sombraluna ancestral te ha utilizado como si fueras un títere. Ahora que has conseguido los objetos que necesitaba, ha revelado su verdadera identidad, Teron Sanguino. Para liberarte de su posesión, debes hacer lo que te pide y matar a Karsius el vigía anciano.","","Si tienes éxito, vuelve a ver a Zorus el Justiciero en el Bastión Martillo Salvaje."}}
D[10646] = {"El pupilo de Illidan",{"Escucha el relato de Altruis."}}
D[10647] = {"Se busca: Uvuros, plaga de Sombraluna",{"Mata a Uvuros y recupera su crin ígnea. Vuelve junto al clamaguerras Sardon Cortecertero de la Aldea Sombraluna, en el Valle Sombraluna."}}
D[10648] = {"Se busca: Uvuros, plaga de Sombraluna",{"Mata a Uvuros y recupera su crin ígnea. Vuelve junto al clamaguerras Birramorro del Bastión Martillo Salvaje, en el Valle Sombraluna."}}
D[10649] = {"El Libro de Nombres Viles",{"Adéntrate en el Laberinto de las Sombras en Auchindoun y consigue el Libro de Nombres Viles de Negrozón el Incitador. Vuelve junto a Altruis, en Nagrand, después de completar esta tarea."}}
D[10650] = {"Regresa junto a los Aldor",{"Habla con la exarca Onaala del Altar de Sha'tar, en el Valle Sombraluna.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10651] = {"Hay que detener a Varedis",{"La exarca Onaala quiere que vayas a las Ruinas de Karabor y mates a Alandien, Theras, Netharel y Varedis. Utiliza el Libro de Nombres Viles para debilitar a Varedis cuando use la metamorfosis. Vuelve a ver al exarca Onaala con el libro cuando hayas acabado.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10652] = {"Tras las líneas enemigas",{"Habla con Veronia cuando quieras ir a la Forja de Maná Coruu. Cuando llegues, habla con Caledis Alba Brillante.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
D[10653] = {"Marcas de Sargeras",{"Lleva 10 marcas de Sargeras a Adyen el Celador de la Luz en la Ciudad de Shattrath.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10654] = {"Más marcas de Sargeras"}
D[10655] = {"Marca de Sargeras única"}
D[10656] = {"Sellos Furia del Sol",{"La magistrix Fyalenn en la Ciudad de Shattrath quiere que le lleves 10 sellos Furia del Sol.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
D[10657] = {"A lomos del relámpago",{"Usa la esfera de magneto repolarizado para absorber 25 golpes de relámpago de las serpientes Alaescama. Consigue también 5 glándulas de relámpagos de Alaescama."}}
D[10658] = {"Más sellos Furia del Sol"}
D[10659] = {"Sello Furia del Sol único"}
D[10660] = {"Extrañas criaturas",{"El investigador Tiorus de la Aldea Sombraluna, en el Valle Sombraluna, quiere que recuperes 8 bazos de fuego vil."}}
D[10661] = {"Para darte un 'abazo'",{"Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes 8 bazos de fuego vil."}}
D[10662] = {"El herrero ermitaño",{"Lleva la caja de lingotes a David Wayne en el Refugio de Wayne, en el Bosque de Terokkar."}}
D[10663] = {"El herrero ermitaño",{"Lleva la caja de lingotes a David Wayne en el Refugio de Wayne, en el Bosque de Terokkar."}}
D[10664] = {"Más materiales",{"David Wayne del Refugio de Wayne quiere que le lleves 1 marco de adamantita, 4 piezas de cuero de pellejo nudoso grueso y 1 Tótem de amparo demoníaco."}}
D[10665] = {"Recién hechas en El Mechanar",{"David Wayne del Refugio de Wayne quiere que le lleves una célula de maná sobrecargada."}}
D[10666] = {"El Lexicón demoníaco",{"Consigue el Lexicón demoníaco del maestro mayor Vorpil y llévaselo a David Wayne en el Refugio de Wayne."}}
D[10667] = {"Marga del submundo",{"Consigue 1 vial de marga del submundo de la hidromántica Thespia y llévaselo a David Wayne en el Refugio de Wayne."}}
D[10668] = {"Contra los Illidari",{"Altruis el Sufridor quiere que mates a Lothros del Alto Illidari en el Valle Sombraluna."}}
D[10669] = {"Contra todo pronóstico",{"Altruis el Sufridor quiere que lleves la lanza de plata imbuida y la uses en el Portal del Claro del Lago Luz Pantanosa, en la Marisma de Zangar, para despertar a Xeleth. Regresa junto a Altruis cuando hayas matado al demonio."}}
D[10670] = {"La lágrima de la Madre Tierra",{"Recupera la lágrima de la Madre Tierra del belisario O'mrogg y llévasela a David Wayne en el Refugio de Wayne."}}
D[10671] = {"Medio kilo de carne de primera",{"Consigue 5 trozos de carne con energía de éter."}}
D[10672] = {"Francamente, no tiene ningún sentido...",{"El investigador Tiorus en la Aldea Sombraluna, en el Valle Sombraluna, quiere que viajes hasta el río de lava cerca de las Ruinas de Baa'ri y utilices la unidad de control Arcano para controlar un arcano escórpido, nadar en la lava con el arcano escórpido y marcar 8 diemetradones de fuego vil superiores."}}
D[10673] = {"Lomovil el Grande",{"El investigador Tiorus en la Aldea Sombraluna, en el Valle Sombraluna, quiere que mates a Lomovil el Grande y consigas su pellejo."}}
D[10674] = {"Atrapar la Luz fantástica",{"Utiliza la trampa de luz para atrapar 15 orbes de luz Razaani."}}
D[10675] = {"¡Gnomas piedad!",{"Consigue la colección de almas."}}
D[10676] = {"El terror de los Illidari",{"Espera a que David Wayne te forje una espada."}}
D[10677] = {"De segundo...",{"Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes 1 molleja de fuego vil hipertrofiada."}}
D[10678] = {"¡El plato fuerte!",{"Gnomus, del Bastión Martillo Salvaje en el Valle Sombraluna, quiere que recuperes el pellejo de Lomovil."}}
D[10679] = {"Templar la espada",{"Viaja hasta Las Pozas Escaldantes próximas a la cumbre de La Mano de Gul'dan y usa la hoja de pesadilla Illidari forjada para enfriarla en las pozas de lava. Cuando tengas la hoja de pesadilla Illidari templada, regresa junto a David Wayne en el Refugio de Wayne."}}
D[10680] = {"La Mano de Gul'dan",{"Habla con el ensalmador de la tierra Torlok en El Altar de Condenación del Valle Sombraluna."}}
D[10681] = {"La Mano de Gul'dan",{"Habla con el ensalmador de la tierra Torlok en El Altar de Condenación del Valle Sombraluna."}}
D[10682] = {"Tiempos de negociación...",{"Negocia con el sobrestante Nuaar."}}
D[10683] = {"Las tablillas de Baa'ri",{"El arcanista Thelis del Sagrario de las Estrellas quiere que consigas 12 tablillas Baa'ri en las Ruinas de Baa'ri.","","A medida que completas tareas para los Arúspices disminuye tu nivel de reputación con los Aldor."}}
D[10684] = {"Oronu el Anciano",{"El arcanista Thelis del Sagrario de las Estrellas quiere que consigas las órdenes de Akama de Oronu el Anciano en las Ruinas de Baa'ri.","","A medida que completas tareas para los Arúspices disminuye tu nivel de reputación con los Aldor."}}
D[10685] = {"Los corruptores Lengua de Ceniza",{"Recupera los 4 trozos de los medallones de Haalum, Eyeknen, Lakaan y Uylaru, regresa junto al arcanista Thelis del Sagrario de las Estrellas, en el Valle Sombraluna.","","A medida que completas misiones para los Arúspices disminuye tu nivel de reputación con los Aldor."}}
D[10686] = {"La Jaula de la Guardiana",{"El arcanista Thelis quiere que entres en la Jaula de la Guardiana, al sur de las Ruinas de Baa'ri e interrogues a Sanoru sobre el paradero de Akama.","","Completar misiones para los Arúspices hará que tu nivel de reputación entre los Aldor descienda."}}
D[10687] = {"Patio de Armas de Karabor",{"Larissa Golpe Solar en el Sagrario de las Estrellas quiere que consigas 8 gujas de Furia del Sol de suplicantes cazadores de demonios e iniciados cazadores de demonios en las Ruinas de Karabor, al noreste del Sagrario de las Estrellas.","","A medida que completas misiones para los Arúspices disminuye tu nivel de reputación con los Aldor."}}
