D[10803] = {"Carnicería en Peña'mok",{"Mata 5 toscos Peña'mok y 3 chamanes Peña'mok."}}
D[10804] = {"Bondad",{"Mordenai, de los Campos del Ala Abisal, en el Valle Sombraluna, quiere que alimentes a ocho dracos Ala Abisal maduros."}}
D[10805] = {"Masacre en la Guarida de Gruul",{"Mata 10 déspotas Aguja del Filo, 5 magos de batalla Aguja del Filo, 5 devastadores Aguja del Filo y a su líder, Fingrom."}}
D[10806] = {"Enfrentamiento",{"Utiliza el sello de Sablecrín en el altar de Goc y mata a Goc."}}
D[10807] = {"Los Tábidos Lengua de ceniza",{"Varen el Reivindicador quiere que vayas a las Ruinas de Baa'ri y mates a 3 tratantes Lengua de ceniza, 4 guerreros Lengua de ceniza y 6 chamanes Lengua de ceniza.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
D[10808] = {"Frustra los planes del Cónclave",{"Mata a los ritualistas del Cónclave Oscuro y usa el bastón de Parshah para acabar con el ritual de invocación del Cónclave Oscuro. Después, vuelve a Parshah, a los Campos de Magma."}}
D[10809] = {"Se busca: Maestro de huargos Kruush",{"Mata al maestro de huargos Kruush y entrega su cabeza al capitán Aullaoscuro en Avanzada Rompeloma."}}
D[10810] = {"La máscara dañada",{"Entrega la máscara dañada a O'Mally Pillazas en Soto Eterno, en las Montañas Filoespada."}}
D[10811] = {"Buscar a Neltharaku",{"Busca a Nelthakaru, patrón de los dracos Ala Abisal."}}
D[10812] = {"La máscara misteriosa",{"Lleva la máscara misteriosa al Señor Salvaje Antelarion en Soto Eterno, en las Montañas Filospada."}}
D[10813] = {"Los ojos de Grillok",{"Usa el fragmento de Zezzak para capturar un ojo de Grillok y acércate a la caldera de Zezzak para extraerlo. Una vez que lo hayas sacado, devuélvele el fragmento a Zezzak."}}
D[10814] = {"La historia de Neltharaku",{"Habla con Neltharaku y escucha su historia."}}
D[10815] = {"El diario de Val'zareq: augurios de guerra",{"Localiza a Marcus Auralion, alto general de los Sha'tar en la Atalaya Carmesí."}}
D[10816] = {"Reclamar los terrenos sagrados",{"El vindicador Aluumen quiere que mates 8 asesinos Sombraluna, 8 elegidos Sombraluna y 4 tejeoscuros Sombraluna.","","Completar misiones para los Aldor hará que disminuya tu nivel de reputación con los Arúspices."}}
D[10817] = {"El gran castigo",{"Varen el Reivindicador quiere que mates 8 asesinos Sombraluna, 8 elegidos Sombraluna y 4 tejeoscuros Sombraluna.","","Completar misiones para los Arúspices hará que disminuya tu nivel de reputación con los Aldor."}}
