D[10819] = {"La máscara de gas jurapenas",{"Ponte la máscara de gas Jurapenas y usa el comunicador de la Legión en Campamento Forja: Inquina, en las Montañas Filoespada."}}
D[10820] = {"Engañar al enemigo",{"Mata 4 auxiliares de la Forja Maldita y 4 ingenieros de la Forja Maldita."}}
D[10821] = {"¡Largo de aquí!",{"Mata a Fatalidad."}}
