D[11142] = {"Inspecciona la Isla de Alcaz",{"Habla con Cassa Ala Carmesí y utiliza uno de sus grifos para inspeccionar la Isla de Alcaz. Cuando acabes la inspección, habla con Lady Jaina Valiente en Theramore."}}
D[11143] = {"Una conexión sombría",{"Preséntate ante el capitán Darill en la Torre de la Punta Norte."}}
D[11144] = {"Confirmando la sospecha",{"Lleva el plan de batalla de Tótem Siniestro al capitán Darill en Torre de la Punta Norte."}}
D[11145] = {"Prisioneros de los Tótem Siniestro",{"El sargento Lukas en la Torre de la Punta Norte quiere que liberes a 5 prisioneros de Theramore."}}
D[11146] = {"Captor de raptores",{"El sargento Lukas en la Torre de la Punta Norte quiere que captures a 6 raptores. Puedes capturar bien a raptores Cienorrojo a o estridadores Cienorrojo."}}
D[11147] = {"Libera a los raptores",{"El sargento Lukas, de la Torre de la Punta Norte, quiere que coloques la carnada de raptor cerca del molino de viento que hay en el Poblado Pezuñanegra."}}
D[11148] = {"Armas de los Tótem Siniestro",{"El capitán Darill, de la Torre de la Punta Norte, quiere que le traigas 7 armamentos Pezuñanegra."}}
D[11149] = {"La ayuda de Tabetha",{"Habla con Tabetha en su granja."}}
D[11150] = {"¡Arrasa el Puesto Cuernoatroz!",{"Quema la tienda norte, la tienda este y la tienda noreste en el Puesto Cuernoatroz, después vuelve a ver a Tabetha a su granja."}}
D[11151] = {"Justicia para los Hyal",{"Habla con el capitán Garran Vimes que se encuentra en la Ciudadela Garrida de Theramore."}}
D[11152] = {"Al fin paz",{"El capitán Garran Vimes de la Ciudadela Garrida quiere que coloques la corona en el monumento de la familia Hyal."}}
D[11153] = {"Rompe el bloqueo",{"Toma las bombas de racimo de Petrov y lánzalas sobre tantos piratas como sea necesario para matar a 25 piratas del bloqueo y destruir 10 cañones del bloqueo. Cuando hayas terminado, vuelve a ver al bombardero Petrov a la Fortaleza de la Guardia Oeste."}}
D[11154] = {"¡Dales un susto de guano!",{"Consigue 10 guanos Garranegra y entrégaselos al ingeniero Feknut en Las Puertas de Acero."}}
D[11155] = {"¿Sopa de colmipala otra vez?",{"Chef Caldera Negra te ha pedido que consigas 6 pedazos de carne de colmipala y que se los lleves a la Fortaleza de la Guardia Oeste."}}
D[11156] = {"Asaltantes del Puesto Cuernoatroz",{"Mata a 12 Tótem Siniestro Cuernoatroz e informa al aprendiz Morlann en la Granja de Tabetha."}}
D[11157] = {"Las garras del mal",{"Destruye 15 huevos de protodraco y 15 protocrías y regresa junto al capitán Adams a la Fortaleza de la Guardia Oeste."}}
D[11158] = {"Plumas Cienorrojo",{"Lleva 5 plumas Cienorrojo a Brogg en Piñón de Barro."}}
D[11159] = {"Espíritus del bastión Quebrantarrocas",{"Brogg de Piñón de Barro quiere que hagas descansar a 10 espíritus Quebrantarrocas."}}
D[11160] = {"El estandarte de los Quebrantarrocas",{"Recupera el estandarte Quebrantarrocas y llévaselo a Brogg a Piñón de Barro."}}
D[11161] = {"La esencia de la animadversión",{"Llévale 10 esencias de dragonante negro a Brogg a Piñón de Barro."}}
D[11162] = {"Reta al Vuelo Negro",{"Coloca el estandarte Quebrantarrocas cerca de la entrada a la Guarida de Onyxia, espera a recibir la respuesta de Onyxia y después ve a ver a Brogg en Piñón de Barro."}}
D[11163] = {"Hermana clandestina",{"Preséntate ante Donna Brascoe para obtener una recompensa por tu heroísmo en Zul'Aman. En este momento, Donna se encuentra en las Tierras Fantasma, justo a las afueras de Zul'aman."}}
D[11164] = {"Asaltantes colmillo",{"Prigmon necesita que consigas 10 colmillos de trol de bosque de los trols de Zul'Aman. Llévaselos al campamento de Budd en las Tierras Fantasma."}}
D[11165] = {"Un trol entre los trols",{"Prigmon necesita que localices a su primo Zungam y le ayudes. Está en algún lugar de Zul'Aman."}}
D[11166] = {"La X indica... ¡tu perdición!",{"Entra en Zul'Aman y visita la cámara de Halazzi, la plataforma de Jan'alai y la de Akil'zon. Informa de lo que veas a Budd, que está en su campamento en las Tierras Fantasma."}}
D[11167] = {"La nueva peste",{"El boticario Lysander de Campo Venganza quiere que recuperes 10 contenedores de peste intactos de entre los restos del barco al sureste."}}
D[11168] = {"Una mezcla más fuerte",{"Llévale 3 glándulas de toxinas gigantes al boticario Lysander, que conseguirás de los reptadores de marea gigantes. El boticario Lysander se encuentra en Campo Venganza, en el Fiordo Aquilonal."}}
D[11169] = {"El arma Tótem Siniestro",{"El aprendiz Garion de la granja de Tabetha quiere que pruebes el tótem capturado con 10 crocoliscos secorrones jaspeados o faucedagas socorrones."}}
D[11170] = {"Prueba en el mar",{"Habla con la cuidadora de murciélagos Camille y toma un murciélago de montar para interceptar los refuerzos de la Alianza. Una vez sobre sus tropas, utiliza los viales de peste para infectar a 16 reservistas de la Flota Norte."}}
D[11171] = {"¿Señor aojador? ¡Ja!",{"Budd Magallenas en Colinas Hacha quiere que vayas a Zul'Aman y liquides al señor aojador Malacrass."}}
D[11172] = {"El accidente del zepelín",{"Habla con Moxie Soplete en el lugar del Siniestro de Beezil."}}
D[11173] = {"El ladrón de componentes",{"Llévale 6 viales de veneno de marisma al aprendiz Garion a la granja de Tabetha."}}
D[11174] = {"Prevención contra la corrosión",{"Moxie Soplete quiere que disuelvas 10 mocos y que vuelvas junto a ella al Siniestro de Beezil"}}
D[11175] = {"Mi hija",{"Viejo Mantopétreo te ha pedido que vayas a buscar a su hija, la sobrestante Irena Mantopétreo, en Las Puertas de Acero."}}
D[11176] = {"Supervisa el trabajo",{"La sobrestante Irena Mantopétreo te ha pedido que hables con un arqueólogo jefe de Las Puertas de Acero."}}
D[11177] = {"El ermitaño de la Mansión Cienaluz",{"Habla con \"Ojolodo\" Jarl en la Mansión Cienaluz."}}
D[11178] = {"Sangre del señor de la Guerra",{"Lleva la sangre de Zul'jin a Budd en su campamento de las Tierras Fantasma, a las afueras de Zul'Aman."}}
D[11179] = {"[Temporarily Deprecated Awaiting a New Mob]Finlay se ha quedado sin tripas",{"Recoge 7 tripas prístinas de Sable de la Niebla para Finlay Flechero y regresa junto a él en la Fortaleza de la Guardia Oeste."}}
D[11180] = {"¿Quién atormenta la Colina de las Brujas?",{"Mordant Navarro, de la Mansión Cienaluz, quiere que consigas información de 10 cáscaras resucitadas o espíritus resucitados."}}
D[11181] = {"La ruina de las brujas",{"Lleva 9 ramitas de Ruinabruja a Mordant Navarro a la Mansión Cienaluz."}}
D[11182] = {"Causas fundamentales",{"Asesina a 5 cuidadores Desuelladragones y a Skeld Dracónez. Si lo logras, preséntate ante un ancestro de Encierro Ámbar en Encierro Ámbar."}}
D[11183] = {"Limpiar la Colina de las Brujas",{"Mordant Navarro en la Mansión Cienaluz quiere que plantes la antorcha al final del muelle y venzas a todo lo que aparezca."}}
D[11184] = {"SE BUSCA: Garrasangrienta el Voraz",{"Mata a Garrasangrienta el Voraz y preséntate ante Drazzit Gotera en Piñón de Barro."}}
D[11185] = {"La carta de la boticaria",{"Lleva la carta lacrada a Andello Porter a la Granja de Tabetha."}}
D[11186] = {"¿Signos de traición?",{"Lleva la carta lacrada a Nazeer Picasangre al Poblado Murohelecho."}}
D[11187] = {"Teniente mago Malister",{"El capitán Adams te ha pedido que hables con su consejero, el teniente mago Malister, que se encuentra en la Fortaleza de la Guardia Oeste."}}
D[11188] = {"Dos errores...",{"El teniente mago Malister en la Fortaleza de la Guardia Oeste te ha encomendado la tarea de destruir a 3 protodracos."}}
D[11189] = {"Una última vez",{"Escolta al fantasma de expedicionario Jaren hasta llegar junto a la expedicionaria Irena Mantopétreo en Las Puertas de Acero, en el Fiordo Aquilonal."}}
D[11190] = {"El tamaño sí importa",{"El cañonero Ely te ha pedido que recojas 10 bolas de cañón de la Guardia Oeste y que se las lleves a la Fortaleza de la Guardia Oeste."}}
D[11191] = {"Este viejo faro",{"Habla con Babs Dinamométrica en el faro de la isla al este de Theramore."}}
D[11192] = {"Aceite de trillador",{"Lleva 4 contenedores de aceite de trillador a Babs Dinamométrica al faro cerca de Theramore."}}
D[11193] = {"Ruines Moradores de las Profundidades",{"Lleva Ruines Moradores de las Profundidades a \"Sucio\" Michael Crowe a los muelles de Theramore."}}
D[11194] = {"¿Es real?",{"Habla con Nat Pagle en el Embarcadero de Nat, en Marjal Revolcafango."}}
D[11195] = {"Jugando con muñecas",{"Lleva el muñeco de vudú hecho jirones a Griftah en la Ciudad de Shattrath."}}
D[11196] = {"TEMP X",{"Prigmon necesita que localices a su primo Zungam y le ayudes. Está en algún lugar de Zul'Aman."}}
D[11198] = {"¡Elimina a Tethyr!",{"El mayor Molina en los muelles de Theramore quiere que derrotes a Tethyr."}}
D[11199] = {"Informa al Explorador Knowles",{"El capitán Adams te ha pedido que te presentes ante el explorador Knowles en la Torre Lanza Ámbar."}}
D[11200] = {"Más que coincidencia",{"Krog, en el Poblado Murohelecho, quiere que le lleves 7 armamentos Pezuñanegra."}}
D[11201] = {"La trama Tótem Siniestro",{"Lleva el plan de batalla de Tótem Siniestro a Krog al Poblado Murohelecho."}}
D[11202] = {"Misión: Llama eterna",{"El explorador Knowles en la Torre Lanza Ámbar te ha recomendado que utilices las antorchas siempreardientes para destruir los cuatro tanques de peste alrededor de Haltorboll."}}
D[11203] = {"Busca a Tabetha",{"Habla con Tabetha en su granja de El Lodazal."}}
D[11204] = {"Regresa junto a Krog",{"Habla con Krog en el Poblado Murohelecho."}}
D[11205] = {"¡Arrasa el Puesto Cuernoatroz!",{"Quema la tienda norte, la tienda este y la tienda noreste en el Puesto Cuernoatroz, después vuelve a ver a Tabetha a su granja."}}
D[11206] = {"Justicia administrada",{"Vuelve junto a Krog al Poblado Murohelecho."}}
D[11207] = {"¡Asegura el cargamento!",{"Moxie Soplete en el Siniestro de Beezil quiere que recuperes 8 trozos de cargamento del zepelín."}}
D[11208] = {"Envío para Drazzit",{"Lleva el cargamento del zepelín a Drazzit Gotera a Piñón de Barro."}}
D[11209] = {"El trato de Nat",{"Nat Pagle en el Embarcadero de Nat quiere que pruebes su nuevo cebo para pescar."}}
D[11210] = {"Oh, es real",{"Habla con el mayor Molina en los muelles de Theramore."}}
D[11211] = {"Ayuda para Piñón de Barro",{"Habla con Drazzit Gotera en Piñón de Barro."}}
D[11212] = {"La granja de Tabetha",{"Habla con Tabetha en su granja de El Lodazal."}}
D[11213] = {"Vela por Tabetha",{"Habla con Tabetha en su granja de El Lodazal."}}
D[11214] = {"Misión a Piñón de Barro",{"Habla con Drazzit Gotera en Piñón de Barro."}}
D[11215] = {"Ayuda a Piñón de Barro",{"Habla con Drazzit Gotera en Piñón de Barro."}}
D[11216] = {"Archimago Alturus",{"Habla con el archimago Alturus fuera de Karazhan en el Paso de la Muerte."}}
D[11217] = {"Atrapa a un dragón por la cola",{"Gizzix Gluglú en Piñón de barro quiere que le lleves 8 tallos de cola de vermis."}}
D[11218] = {"¡Peligro! ¡Explosivos!",{"Usa la dinamita para tontos de Aro de Acero para recolectar 6 fragmentos de mena de Garganta Susurro y 18 gemas de Garganta Susurro. Después devuélveselas a Zapador Aro de Acero en la Fortaleza de la Guardia Oeste."}}
D[11219] = {"¡Todos contra el fuego!",{"La supervisora de huérfanos disfrazada quiere que ayudes a extinguir todos los incendios de la ciudad. Cuando los apagues, vuelve a hablar con ella."}}
D[11220] = {"El Jinete decapitado",{"Encuentra el Santuario de la Calabaza de El Jinete decapitado."}}
D[11221] = {"Informes desde el campo",{"Habla con la forestal oscura Lyana y con el mortacechador Razael en el campo de batalla de la Vega Sangrante, al sur de Campo Venganza. Preséntate ante el sumo ejecutor Anselm cuando hayas completado esta tarea."}}
D[11222] = {"Prueba de traición",{"Habla con el rey Varian Wrynn en la Fortaleza de Ventormenta."}}
D[11223] = {"Regresa junto a Jaina",{"Habla con Lady Jaina Valiente en Theramore."}}
D[11224] = {"Envíalas de vuelta",{"La expedicionaria Abigail te ha pedido que hagas un /levantarmano a 10 mulas de carga abandonadas y vuelvas a verla a la Fortaleza de la Guardia Oeste."}}
D[11225] = {"El ermitaño de la Colina de las Brujas",{"Habla con \"Ojolodo\" Jarl en la Mansión Cienaluz."}}
D[11227] = {"¡Que coman grajos!",{"Pontius, el vigilante de la perrera de Campo Venganza, quiere que utilices la jaula de can de peste para invocar a un can de peste hambriento y darle carne de grajo para comer. Conseguirás la carne de los grajos de fiordo al oeste de Campo Venganza."}}
D[11228] = {"El infierno se ha congelado...",{"Habla con el vicealmirante Keller en el Puerto de Valgarde."}}
D[11229] = {"La flota de El Brisaveloz",{"Habla con la cuidadora de murciélagos Camille en Campo Venganza y consigue llegar a El Brisaveloz. Preséntate ante la capitana Harker a bordo del barco."}}
D[11230] = {"¡Una emboscada!",{"La capitana Harker, a bordo de El Brisaveloz, quiere que mates a 15 marinos de la Flota Norte."}}
D[11231] = {"De llaves y jaulas",{"Padre Levariol te ha pedido que consigas tantas llaves de jaula de Gjalerbron como sean necesarias para liberar a 10 prisioneros de Gjalerbron. Vuelve a verlo a la Fortaleza de la Guardia Oeste cuando lo consigas."}}
D[11232] = {"Sé nuestros ojos",{"Usa las bengalas de humo en el lugar donde se encuentran los cañones de la Alianza, en el muro norte de Playa Derelicta. Cuando hayas completado esta tarea, informa a la forestal oscura Lyana en la Vega Sangrante."}}
D[11233] = {"Asestar el golpe de gracia",{"La forestal oscura Lyana, al sur de Campo Venganza, quiere que mates al capitán Olster, a la teniente Celeyne y al sargento Lorric en Playa Derelicta."}}
D[11234] = {"Informa a Anselm",{"Informa al sumo ejecutor Anselm en Campo Venganza, en el Fiordo Aquilonal."}}
D[11235] = {"Encargarse de Gjalerbron",{"El capitán Adams te ha pedido que mates 15 guerreros de Gjalerbron, 8 taumaturgos de runas de Gjalerbron y 8 vigías del sueño de Gjalerbron. Después vuelve a verle a la Fortaleza de la Guardia Oeste."}}
D[11236] = {"Necroseñor Supremo Mezhen",{"Mata al Necroseñor Supremo Mezhen y vuelve a ver al capitán Adams en la Fortaleza de la Guardia Oeste."}}
D[11237] = {"Los planes de ataque de Gjalerbron",{"Entrégale los planes de ataque de Gjalerbron al teniente mago Malister en la Fortaleza de la Guardia Oeste."}}
D[11238] = {"La vermis de escarcha y su maestro",{"Mata a Clamavermis Vil y usa el cuerno de clamavermis para llamar y matar a Glacion. Después llévale el cuerno al teniente mago Malister a la Fortaleza de la Guardia Oeste."}}
D[11239] = {"En servicio a la Luz",{"Mata a 10 vigías inextinguibles, 4 horrores aterradores y 2 criaturas pútridas. Después informa de tu éxito al Padre Levariol en la Fortaleza de la Guardia Oeste."}}
D[11240] = {"Líder de los trastornados",{"Mata a Squeeg Cazador de Ídolos y después informa a Zapador Aro de Acero en la Fortaleza de la Guardia Oeste."}}
D[11241] = {"Rastro de fuego",{"Escolta al boticario Hanes fuera de la Playa Derelicta. Informa al boticario Lysander de Campo Venganza en el Fiordo Aquilonal cuando hayas completado esta tarea."}}
D[11242] = {"¡Por fin libre!",{"Lleva el Escrito de Thomas Thomson a la supervisora de huérfanos disfrazada de Villadorada, Kharanos o de la Avanzada Azur."}}
D[11243] = {"Si Valgarde cae...",{"El vicealmirante Keller en el Puerto de Valgarde del Fiordo Aquilonal quiere que mates 12 invasores Desuelladragones o huargos Desuelladragones."}}
D[11244] = {"Rescatar a los rescatadores",{"El vicealmirante Keller del Puerto de Valgarde en el Fiordo Aquilonal quiere que encuentres a 8 exploradores de Valgarde que han sido empalados y abandonados hasta la muerte."}}
D[11245] = {"Torres de cierta fatalidad",{"El Sargento de la Guardia Oeste te ha informado de que sería conveniente usar la Bengala de Sargento para fijar las cuatro torres de Skorn como objetivos para ataques con cañones."}}
D[11246] = {"Horripilante, pero necesario",{"El sargento de la Guardia Oeste te ha pedido que uses el machete del Sargento para desmembrar a 20 vrykuls de la tribu Inbjerskorn en Skorn."}}
D[11247] = {"¡Arde, Skorn, arde!",{"El sargento de la Guardia Oeste tiene órdenes de que, con la antorcha de Sargento, prendas fuego a las casas comunales del noreste y noroeste y a los barracones de Skorn."}}
D[11248] = {"Operación: cólera de Skorn",{"El capitán Adams te ha pedido que uses la insignia de mando de la Guardia Oeste en Skorn, y que después hables con el Sargento de la Guardia Oeste."}}
D[11249] = {"¡Detén la ascensión!",{"Presenta el Pergamino de ascensión vrykul cerca de la pira del señor feudal para hacerle salir y matarlo. Después, debido a la naturaleza del ritual, estás seguro de que a Padre Levariol, en la Fortaleza de la Guardia Oeste, le interesará ver el pergamino."}}
D[11250] = {"¡Aclamad todos al conquistador de Skorn!",{"Devuélvele la Insignia de mando de la Guardia Oeste al capitán Adams en la Fortaleza de la Guardia Oeste."}}
D[11251] = {"Piernas frescas",{"La exploradora Valory quiere que investigues los sonidos de batalla procedentes del noreste del Poblado Calavermis."}}
D[11252] = {"¡A Utgarde!",{"El defensor Mordun te ha encargado la ejecución de Ingvar el Desvalijador que reside en las profundidades de Utgarde.","","Llévale su cabeza al Vicealmirante Keller."}}
D[11253] = {"Sigue la pista del enemigo",{"Utiliza la correa de can de peste junto a las jaulas de can de peste en Campo Venganza y busca pistas en el lugar al que te lleve el can de peste rastreador."}}
D[11254] = {"El mapa de piel de dragón",{"Lleva el mapa de piel de dragón al sumo ejecutor Anselm en Campo Venganza."}}
D[11255] = {"Prisioneros de Calavermis",{"El vicealmirante Keller en el Puerto de Valgarde, en el Fiordo Aquilonal, quiere que rescates a 3 prisioneros de Valgarde."}}
D[11256] = {"¡Skorn debe caer!",{"El cabecilla Tótem de Ceniza te ha pedido que uses el Emblema de Pezuña Invernal en Skorn y después hables con el Valiente Pezuña Invernal."}}
D[11257] = {"Horripilante, pero necesario",{"El valiente Pezuña Invernal te ha pedido que uses el machete de Valiente para desmembrar a 20 vrykuls de la tribu Inbjerskorn en Skorn."}}
D[11258] = {"¡Arde, Skorn, arde!",{"El valiente Pezuña Invernal te ha sugerido que uses la antorcha de Valiente para prender fuego a las casas comunales noreste y noroeste y a los barracones de Skorn."}}
D[11259] = {"Torres de cierta fatalidad",{"El valiente Pezuña Invernal te ha informado de que sería conveniente usar la bengala de Valiente para fijar las cuatro torres de Skorn como objetivos para ataques aéreos."}}
D[11260] = {"¡Detén la ascensión!",{"Presenta el Pergamino de ascensión vrykul cerca de la pira del señor feudal para hacerle salir y matarlo. Después, debido a la naturaleza del ritual, estás seguro de que a la abuela Ankha del Campamento Pezuña Invernal le interesará ver el pergamino."}}
D[11261] = {"¡El conquistador de Skorn!",{"Devuelve el tótem Pezuña Invernal al cabecilla Tótem de Ceniza del Campamento Pezuña Invernal."}}
D[11262] = {"¡Ingvar ha de morir!",{"La forestal oscura Marrah te ha pedido que mates a Ingvar el Desvalijador en la Fortaleza de Utgarde y que luego le lleves su cabeza al sumo ejecutor Anselm a Campo Venganza."}}
D[11263] = {"Encargarse de Gjalerbron",{"El cabecilla Tótem de Ceniza te ha pedido que mates 15 guerreros de Gjalerbron, 8 taumaturgos de runas de Gjalerbron y 8 vigías del sueño de Gjalerbron. Después vuelve a verle al Campamento Pezuña Invernal."}}
D[11264] = {"Necroseñor Supremo Mezhen",{"Mata al Necroseñor Supremo Mezhen y vuelve a ver al cabecilla Tótem de Ceniza en Campamento Pezuña Invernal."}}
D[11265] = {"De llaves y jaulas",{"La abuela Ankha te ha pedido que consigas suficientes llaves de jaula de Gjalerbron para liberar a 10 prisioneros de Gjalerbron. Vuelve a verla al Campamento Pezuña Invernal cuando lo hayas conseguido."}}
D[11266] = {"Los planes de ataque de Gjalerbron",{"Entrégale los planes de ataque de Gjalerbron a Celea Crines de Hielo en el Campamento Pezuña Invernal."}}
D[11267] = {"La vermis de escarcha y su maestro",{"Mata a Clamavermis Vil y usa el cuerno de clamavermis para llamar y matar a Glacion. Después llévale el cuerno a Celea Crines de Hielo al Campamento Pezuña Invernal."}}
D[11268] = {"Los muertos andantes",{"Mata a 10 vigías inextinguibles, 4 horrores aterradores y 2 criaturas pútridas. Después informa de tu éxito a la abuela Ankha del Campamento Pezuña Invernal."}}
D[11269] = {"Esfuerzo final",{"Gil Grisert quiere que le lleves 10 montones de plumón de hipogrifo moteado."}}
D[11270] = {"La guerra es un infierno",{"Estás en esta misión"}}
D[11271] = {"Preparativos precipitados",{"Ahota Escarcha Blanca te ha pedido que le traigas 10 plumones de hipogrifo moteado."}}
D[11272] = {"Ajuste de cuentas",{"El sumo ejecutor Anselm quiere que te adentres en Utgarde y mates al príncipe Keleseth."}}
D[11273] = {"La liga de los humanos",{"Busca a Pulroy en el Poblado Calavermis."}}
D[11274] = {"Es probable que Zedd esté muerto",{"Busca a Zedd en el Poblado Calavermis."}}
D[11275] = {"Haciendo el cuerno",{"Nokoma Vidente de la Nieve del Campamento Pezuña Invernal quiere que le lleves 6 cuernos de carnero sin estropear."}}
D[11276] = {"Solo quedaban dos...",{"Busca a Glorenfeld en las Catacumbas de Utgarde."}}
D[11277] = {"Las profundidades de la depravación",{"Glorenfeld, de las Catacumbas de Utgarde, quiere que consigas 10 tablillas de Calavermis."}}
D[11278] = {"Regresa a Valgarde",{"Lleva el paquete de Glorenfeld a Beltrand McSorf al Puerto de Valgarde."}}
D[11279] = {"Huevos verdes con crías",{"El pesteador Tillinghast te ha pedido que reúnas 10 especímenes de protocría apestadas y que se las lleves a Nuevo Agamand."}}
D[11280] = {"Draconis Gastritis",{"El pesteador Tillinghast en Nuevo Agamand quiere que uses la carne apestada de Tillinghast para atraer a un protodraco y que observes su reacción al comérsela."}}
D[11281] = {"Imitando la llamada de la naturaleza",{"Prueba el cuerno tallado y ve a contarle los resultados que observes a Nokoma Vidente de la Nieve al Campamento Pezuña Invernal."}}
D[11282] = {"Una lección de miedo",{"Gorth quiere que mates a Ulf el Flebotomista, a Oric el Torvo y a Gunnar Thorvardsson y que atravieses sus cuerpos con el estandarte de los Renegados. Mata vrykuls por la zona de bloqueo de los Renegados hasta que aparezcan."}}
D[11283] = {"Recuento de cuerpos de Baleheim",{"El sargento Gorth quiere que mates a 16 vrykuls Inbjerskorn en el interior de Baleheim."}}
D[11284] = {"El yeti de al lado",{"El supervisor Colbey en el Fuerte Vildervar quiere que derrotes a Modorro."}}
D[11285] = {"¡Baleheim debe arder!",{"El sargento Gorth quiere que vayas a Baleheim y utilices la antorcha de Gorth para quemar 1 morada Inbjerskorn, 1 torre de observación Inbjerskorn, 1 puente Inbjerskorn y 1 barraca Inbjerskorn."}}
D[11286] = {"Los artefactos de Las Puertas de Acero",{"El sabio Caminaniebla te ha pedido que consigas 10 artefactos de Las Puertas de Acero. Cuando los tengas todos, vuelve a verle a Las Puertas de Acero."}}
D[11287] = {"Encuentra al sabio Caminaniebla",{"La abuela Ankha te ha pedido que averigües el estado del sabio Caminaniebla. Cree que se encuentra en o cerca de Las Puertas de Acero."}}
D[11288] = {"La luz brillante",{"Ares el Juramentado en las Catacumbas de Utgarde quiere que recuperes el artefacto sacro.","","Esta es una misión contrarreloj."}}
D[11289] = {"Guiado por el honor",{"Devuelve el artefacto sacro a Lord Irulon Filoveraz en Valgarde."}}
D[11290] = {"Planes de batalla de los Desuelladragones",{"El vicealmirante Keller en el Puerto de Valgarde, en el Fiordo Aquilonal, te ha pedido que le lleves los planes de batalla de los Desuelladragones."}}
D[11291] = {"¡A la Fortaleza de la Guardia Oeste!",{"Lleva los planes de batalla de los Desuelladragones al capitán Adams a la Fortaleza de la Guardia Oeste en el Fiordo Aquilonal."}}
D[11292] = {"Acechando a los débiles",{"El trampero Jethan en el Fuerte Vildervar quiere que le lleves 8 trozos de presa atrapada."}}
D[11293] = {"¡Grita por los Cebadiz!"}
D[11294] = {"¡Grita por los Cebatruenos!"}
D[11295] = {"La ofensiva comienza",{"Habla con el sargento Gorth en el bloqueo cerca del elevador oeste de Campo Venganza en el Fiordo Aquilonal."}}
D[11296] = {"Cautivos de El Bosque Hendido",{"El enviado Nube del Cielo te ha pedido que liberes a sus 7 enviados Pezuña Invernal. Cuando lo hayas conseguido, vuelve junto a él a Las Puertas de Acero."}}
D[11297] = {"Observando de cerca a los intrusos",{"Habla con el boticario Malthus en el Campamento de los Boticarios."}}
D[11298] = {"¿Qué lleva esa bebida?",{"El boticario Malthus en el Campamento de los Boticarios quiere que le lleves 5 barriles enanos."}}
D[11299] = {"El Círculo del Juicio",{"Encuentra a Daegarn en El Círculo del Juicio situado dentro de las Catacumbas de Utgarde."}}
D[11300] = {"Una derrota asombrosa en el Círculo",{"Derrota a los gladiadores en el Círculo del Juicio y enfréntate a Oluf el Violento. Vence a Oluf y recupera la clave antigua.","","Devuelve la clave antigua a Glorenfeld en la entrada a las catacumbas de Utgarde."}}
D[11301] = {"¡Cerebros! ¡Cerebros! ¡Cerebros!",{"El boticario Grick en el Campamento de los Boticarios quiere que le lleves 12 Cerebros de expedicionario perturbado."}}
D[11302] = {"Las enigmáticas ninfas escarcha",{"Habla con Lurielle en El Claro Helado."}}
D[11303] = {"La emboscada",{"Habla con Lydell en La Emboscada de Lydell."}}
D[11304] = {"Nuevo Agamand",{"Llévale la cepa de Lysander al jefe pesteador Harris en Nuevo Agamand, al oeste del Fiordo Aquilonal."}}
D[11305] = {"Una fórmula hecha a medida",{"Obtén la sangre de patriarca Desuelladragones de Thorvald en el Campamento de Thorvald y llévasela al jefe pesteador Harris en Nuevo Agamand."}}
D[11306] = {"Calentar y remover",{"Llena el frasco de boticario vacío con el contenido de la caldera de sangre vrykul y luego mezcla el contenido del frasco de sangre vrykul con las muestras de peste de Harris cercanas hasta que obtengas un brebaje equilibrado.","","Preséntate ante el jefe pesteador Harris cuando hayas completado esta tarea."}}
D[11307] = {"Ensayo de campo",{"Aventúrate en Haltorboll y utiliza el spray de peste con 10 vrykuls Desuelladragones apestados. Vuelve a ver al jefe pesteador Harris para informarle de los resultados."}}
D[11308] = {"Es hora de limpiar",{"Habla con \"Sierra\" Jenny en Nuevo Agamand."}}
D[11309] = {"Partes para el trabajo",{"\"Sierra\" Jenny en Nuevo Agamand quiere que consigas 6 ligamentos de colmipala y 1 porción de medio kilo de carne fresca."}}
D[11310] = {"Aviso: requiere montaje",{"Utiliza el juego de montaje de abominación en Haltorboll y reúne vrykuls apestados con tu abominación descerebrada. Acaba por lo menos con 20 y vuelve a ver a \"Sierra\" Jenny a Nuevo Agamand cuando hayas terminado."}}
D[11311] = {"Dar muerte a los elementos",{"El domador del viento Kajan, del Campamento Pezuña Invernal, quiere que mates 8 elementales de montaña. Puedes matar ciclones rugientes o elementales de fragmentos de hielo."}}
D[11312] = {"El Claro Helado",{"Habla con Lurielle en El Claro Helado."}}
D[11313] = {"Espíritus del hielo",{"Lurielle en El Claro Helado quiere que le lleves 15 núcleos helados."}}
D[11314] = {"Las hermanas caídas",{"Lurielle, en El Claro Helado, quiere que uses su colgante con 7 ninfas escalofrío."}}
D[11315] = {"Enredaderas salvajes",{"Lurielle, en El Claro Helado, quiere que mates 8 hiedras escarlata."}}
D[11316] = {"Engendros de El Claro Retorcido",{"Lurielle en El Claro Helado quiere que mates a 10 trepadores viñaespina."}}
D[11317] = {"La limpieza",{"El sabio Caminaniebla en Las Puertas de Acero te ha aconsejado que limpies tu alma de tu conflicto interior meditando en el Santuario Filoescarcha."}}
D[11318] = {"Carrera de carneros... o algo parecido",{"Tienes 4 minutos para montar el carnero y mantener 3 niveles de velocidad diferentes durante 8 segundos."}}
D[11319] = {"Semillas de los vigilantes de alma negra",{"Lurielle en El Claro Helado quiere que congeles 8 esporas."}}
