D[11536] = {"No te pares ahora",{"La herrera Hauthaa, en el Arsenal de Tramo del Sol, quiere que mates mirmidones Espina Siniestra al este y que uses sus llaves para robar 3 menas de sus cofres."}}
D[11537] = {"La batalla debe continuar",{"El presagista Inuuro quiere que mates a 6 demonios de la Legión Ardiente y al emisario del Odio en La Plaza Crepuscular. Usa el estandarte de Sol Devastado para empalar el cadáver del emisario del Odio."}}
D[11538] = {"La batalla por el Arsenal de Tramo del Sol",{"El presagista Inuuro quiere que mates a 6 demonios de la Legión Ardiente y al emisario del Odio en La Plaza Crepuscular o en el Arsenal de Tramo del Sol. Usa el estandarte de Sol Devastado para empalar el cadáver del emisario del Odio."}}
D[11539] = {"Tomar el puerto",{"El Magister Ilastar en el Arsenal de Tramo del Sol quiere que mates 6 invocadores Hojalba, 6 caballeros de sangre Hojalba y 3 tiradores Hojalba."}}
D[11540] = {"Aplasta a los Hojalba",{"El Magister Ilastar en el Arsenal de Tramo del Sol quiere que mates 6 invocadores Hojalba, 6 caballeros de sangre Hojalba y 3 tiradores Hojalba."}}
D[11541] = {"Perturbar la Costa Branquia Verde",{"La capitana Valindria quiere que liberes a 10 esclavos Branquia Verde. Vuelve junto a ella a bordo del Orgullo de Lunargenta en el Puerto de Tramo del Sol cuando hayas terminado."}}
D[11542] = {"Interceptar a los refuerzos",{"El Vindicador Kaalan del Arsenal de Tramo del Sol quiere hables con Ayren Rompenubes y que vueles sobre la flota de refuerzo de Hojalba. Usa el aceite en llamas para incendiar las velas de los barcos mientras los sobrevuelas y cuando aterrices, mata a 6 reservistas Hojalba."}}
D[11543] = {"Mantén al enemigo a raya",{"El Vindicador Kaalan del Arsenal de Tramo del Sol quiere hables con Ayren Rompenubes y que vueles sobre la flota de refuerzo de Hojalba. Usa el aceite en llamas para incendiar las velas de los barcos mientras los sobrevuelas y cuando aterrices, mata a 6 reservistas Hojalba."}}
D[11544] = {"Armamentos de Ata'mal",{"La herrera Hauthaa necesita que crees 5 metales de Ata'mal purificados. Puedes crearlos destruyendo armamentos de Ata'mal en su yunque en el Arsenal de Tramo del Sol en la Isla de Quel'Danas."}}
D[11545] = {"Una donación caritativa",{"La anacoreta Ayuri de Tramo del Sol, en la Isla de La Fuente del Sol, quiere que dones 10 oros."}}
D[11546] = {"Abierto al negocio",{"Mar'nah del Puerto de Tramo del Sol quiere que recojas 5 bayas de sangre de los arbustos de Quel'Danas."}}
D[11547] = {"Conoce tus líneas Ley",{"El astromante Darnarian, en el Sagrario de Tramo del Sol, quiere que uses el cristal de astromante en el cristal de sangre, el portal de La Plaza Crepuscular y el sagrario naga en la Costa Branquia Verde."}}
D[11548] = {"Tu incesante apoyo",{"La anacoreta Ayuri de Tramo del Sol, en la Isla de La Fuente del Sol, quiere que dones 10 oros."}}
D[11549] = {"Un benefactor magnánimo",{"El anacoreta Kairthos quiere que dones 1000 oros para ayudar a la causa de la anacoreta Ayuri. Si completas esta misión, serás conocido como Sharmon del Sol Devastado."}}
D[11550] = {"Adelante, Falsario...",{"Preséntate ante el archimago Ne'thul en la Isla de Quel'Danas, al norte de Quel'Thalas.","","Los maestros de vuelo de Forjaz y de Ciudad de Lunargenta te llevarán hasta tu destino."}}
D[11551] = {"Agamath, la primera puerta"}
D[11552] = {"Rohendor, la segunda puerta"}
D[11553] = {"Archonisus, la puerta final"}
D[11554] = {"Un amigo en primera línea"}
D[11555] = {"Honrado por tus aliados"}
D[11556] = {"Venerado en el campo de batalla"}
D[11557] = {"Exaltado entre todos los combatientes"}
D[11558] = {"Amor peligroso",{"Lleva una tarjeta mohosa de guardián a Fenstad Argyle a Entrañas."}}
D[11559] = {"Comercio Aleta Invernal",{"Reúne 5 almejas Aleta Invernal y llévaselas a Ahlurglgr en el Refugio Aleta Invernal."}}
D[11560] = {"¡Oh no! ¡Los renacuajos!",{"El rey Mrgl-Mrgl te ha pedido que rescates a 20 renacuajos Aleta Invernal. Vuelve a verlo al Refugio Aleta Invernal cuando hayas terminado."}}
D[11561] = {"¡Ellos!",{"Brglmurgl en el Refugio Aleta Invernal te ha pedido que mates a 15 múrlocs Aleta Invernal. Cualquier combinación de guerreros, oráculos y rompeolas servirá."}}
D[11562] = {"Mi limpiador me está chantajeando",{"El rey Mrgl-Mrgl te ha pedido que hables con Mrmrglmr al extremo noroeste del Refugio Aleta Invernal."}}
D[11563] = {"¡¡¡Grmmurggll Mrllggrl Glrggl!!!",{"Mrmrglmr quiere que regreses al Refugio Aleta Invernal con la cabeza de Glrggl."}}
D[11564] = {"Suculento estofado de orca",{"El acuchillador Bmurglbrm te ha encargado 7 piezas de grasa de orca suculenta. Llévaselas al Refugio Aleta Invernal."}}
D[11565] = {"El traje de muda",{"Devuélvele al rey Mrgl-Mrgl su traje de muda. Lo encontrarás en el Refugio Aleta Invernal."}}
D[11566] = {"¡De rendirse... nada!",{"El rey Mrgl-Mrgl en el Refugio Aleta Invernal te ha pedido que le traigas una garra de Claximus."}}
D[11567] = {"La antigua armadura de los Kvaldir",{"Recupera la antigua armadura de los Kvaldir y entrégasela a Orfus de Komawa en el Fiordo Aquilonal."}}
D[11568] = {"Volver a descansar en paz",{"Usa el fardo de artefactos vrykul en los túmulos funerarios de Colina Escudo para devolver el corazón congelado de Isuldof, el escudo de los Aesirites, el bastón de la Furia de la Tormenta y la antigua armadura de los Kvaldir.","","Vuelve con Orfus de Komawa en El Antiguo Elevador si lo consigues."}}
D[11569] = {"El maestro de llaves Urmgrgl",{"Glrglrglr en el interior de las Cavernas Aleta Invernal te ha pedido que consigas la llave de Urmgrgl."}}
D[11570] = {"Escapa de las Cavernas Aleta Invernal",{"Escolta a Lurgglbr hasta un lugar seguro y después dale la buena noticia al rey Mrgl-Mrgl en el Refugio Aleta Invernal."}}
D[11571] = {"Aprendiendo a comunicarse",{"El rey Mrgl-Mrgl te ha dado una caracola para que la uses sobre los restos de Escaldadora. Devuélvele la caracola del Rey llena en el Refugio Aleta Invernal."}}
D[11572] = {"Regresa junto a Atuik",{"Dale las malas noticias al ancestro Atuik en Komawa."}}
D[11573] = {"Orfus de Komawa",{"Encuentra a Orfus de Komawa en El Antiguo Elevador de Fiordo Aquilonal."}}
D[11574] = {"Por los pelos",{"Endorah quiere que vayas a El Saliente Ámbar al noroeste del Bastión Grito de Guerra y les des las gracias a los magos por haberla rescatado."}}
D[11575] = {"Justo a tiempo",{"Menudencia de la Fortaleza Denuedo quiere que vayas hasta El Saliente Ámbar al norte y des las gracias a quienes la rescataron."}}
D[11576] = {"Observar la falla: anomalía del Acantilado Agrietado",{"Garren de El Saliente Ámbar quiere que utilices el arcanómetro en la anomalía del Acantilado Agrietado."}}
D[11577] = {"Coleccionista de WoW Edition: - DEM - E - BANDERA"}
