D[11581] = {"¡Profana este fuego!"}
D[11582] = {"Observar la falla: Sima Quebrada",{"Garren en El Saliente Ámbar quiere que uses el arcanómetro en la anomalía de la Sima Quebrada y que vuelvas con las lecturas."}}
