D[11586] = {"La vigilia de Grito Infernal",{"Habla con Garrosh Grito Infernal en Bastión Grito de Guerra."}}
D[11587] = {"Rescata como puedas",{"El bibliotecario Donathan en El Saliente Ámbar quiere que consigas la llave de la prisión de Berilo de alguno de los cazadores de magos de Berilo y la uses para liberar de su prisión arcana a un mago atrapado."}}
D[11590] = {"Abducción",{"Donathan quiere que utilices la mordaza Arcana sobre un hechicero de Berilo en Alto de Berilo y lo lleves hasta él en El Saliente Ámbar."}}
D[11591] = {"Preséntate en la Caravana de Quijacero",{"Habla con la bruta Puñofuria en la Caravana de Quijacero."}}
D[11592] = {"¡Atacamos!",{"Ayuda al enviado Pezuña Orgullosa y a sus asaltantes Grito de Guerra a sobrevivir al ataque en la Caravana de Quijacero y a acabar con el espíritu del comandante en jefe Quijacero.","","Si lo consigues, informa al señor supremo Bor'gorok en la Avanzada Bor'gorok."}}
D[11593] = {"Homenaje a los difuntos",{"La bruta Puñofuria en la Caravana de Quijacero te ha pedido que uses la antorcha de Puñofuria para quemar cualquier combinación de 10 guardias y trabajadores de la caravana muertos."}}
D[11594] = {"Ayúdalos a encontrar la paz",{"Devuelve la paz a 20 espíritus taunka, ya sean sabios fantasmales o enviados resucitados y después vuelve a informar a la bruta Puñofuria en la Caravana de Quijacero."}}
D[11595] = {"La defensa del Bastión Grito de Guerra",{"Preséntate ante el señor supremo Razgor en la barraca del flanco sur del Bastión Grito de Guerra."}}
D[11596] = {"La defensa del Bastión Grito de Guerra",{"Preséntate ante el señor supremo Razgor en la barraca del flanco sur del Bastión Grito de Guerra."}}
D[11597] = {"La defensa del Bastión Grito de Guerra",{"Preséntate ante el señor supremo Razgor en la barraca del flanco sur del Bastión Grito de Guerra."}}
D[11598] = {"La reconquista de la Cantera de Piedra de Poderío",{"El señor supremo Razgor en el Bastión Grito de Guerra quiere que mates a 15 nerubianos Nerub'ar."}}
D[11599] = {"Thassarian, hermano mío",{"Busca a William Allerton en la Mina de Lindeallá."}}
D[11600] = {"El difunto William Allerton",{"Llévale la tarjeta de alistamiento a Leryssa a la Fortaleza Denuedo, en la Tundra Boreal."}}
D[11601] = {"Perdido y hallado",{"Habla con James Diácono en la posada de la Fortaleza Denuedo."}}
D[11602] = {"Elimina el problema de raíz",{"El señor supremo Razgor, en el Bastión Grito de Guerra, quiere que destruyas 10 sacos de huevos Nerub'ar."}}
D[11603] = {"In vino veritas",{"Recupera una botella de vino de Kul Tiras del barco hundido al noreste de la Fortaleza Denuedo y llévasela al viejo Colburn en la posada de la Fortaleza Denuedo."}}
D[11604] = {"Un desertor",{"Encuentra la cárcel dentro del cuartel en la Fortaleza Denuedo y habla con el desertor."}}
D[11605] = {"Homenaje a los ancestros",{"El ancestro Atkanok a las afueras de la Cantera Frioescollo quiere que identifiques las estatuas del ancestro Kesuk, el ancestro Sagani y del ancestro Takret."}}
D[11606] = {"La paciencia es una virtud que no necesitamos",{"El intendente Holgoth en el Bastión Grito de Guerra quiere que recuperes 15 cajones de municiones Grito de Guerra."}}
D[11607] = {"Los espíritus perdidos",{"El ancestro Atkanok a las afueras de la Cantera Frioescollo quiere que liberes a los espíritus de 3 artesanos de Kashala y de 3 chamanes de Kashala."}}
D[11608] = {"¡Entierra a esas cucarachas!",{"El intendente Holgoth en el Bastión Grito de Guerra quiere que uses el fajo de cargas de profundidad de seforio para destruir los sumideros Nerub'ar al sur, este, oeste y norte del Bastión Grito de Guerra."}}
D[11609] = {"Recoger los pedazos",{"Llévale 6 objetos rituales colmillarr al ancestro Atkanok, que se encuentra fuera de la Cantera Frioescollo."}}
D[11610] = {"Llevar a los ancestros a casa",{"El ancestro Atkanok quiere que guíes a los espíritus del ancestro Kesuk, del ancestro Sagani y del ancestro Takret hasta sus monumentos de piedra."}}
D[11611] = {"Retenidos por la Plaga",{"El supervisor Mortuus del Bastión Grito de Guerra quiere que liberes 5 peones Grito de Guerra."}}
D[11612] = {"Recuperar la cantera",{"Etaruk, que está acampado cerca de la entrada a la Cantera Frioescollo, quiere que mates a 12 cazatesoros de Berilo."}}
D[11613] = {"El juramento de Karuk",{"Karuk quiere que mates a 6 asaltantes Skadir y a 5 barqueros Skadir."}}
D[11614] = {"Verdades jamás contadas",{"Encuentra al acechasombras Luther en la Cantera Piedra de Poderío."}}
D[11615] = {"Secretos Nerub'ar",{"Llévale el diario de Luther al acechasombras Barthus al Bastión Grito de Guerra."}}
D[11616] = {"Mensaje para Grito Infernal",{"Llévale la nota de Barthus a Garrosh Grito Infernal al Bastión Grito de Guerra."}}
D[11617] = {"Impedir que escapen",{"Etaruk, fuera de la Cantera Frioescollo, quiere que destruyas la plataforma norte, la plataforma este y la plataforma oeste."}}
D[11618] = {"Llegan los refuerzos...",{"Busca al acechasombras Ickoris en las Granjas Grito de Guerra al oeste del Bastión Grito de Guerra."}}
D[11619] = {"Gamel el Cruel",{"Karuk quiere que derrotes a Gamel el Cruel en el Litoral Tralladón."}}
D[11620] = {"Las palabras de un padre",{"Busca a Veehja en el Santuario de Escamas en el Litoral Tralladón."}}
D[11621] = {"La tablilla de Leviroth",{"Vuelve a ver a Karuk con la información que has encontrado en la tablilla."}}
D[11622] = {"Secretos de Tralladón",{"Encuentra a Veehja en las ruinas de Tralladón en la Tundra Boreal."}}
D[11623] = {"Una visita al comisario",{"Etaruk, en las afueras de la Cantera Frioescollo, quiere que mates al comisario Insivius."}}
D[11624] = {"El cielo lo sabrá",{"Habla con Imperean en las Ruinas de Eldra'nath."}}
D[11625] = {"El tridente de Naz'jan",{"Veehja en Tralladón quiere que vayas al extremo noreste de las Ruinas Tralladón. Una vez allí, mata a Ragnar Drakkarlund y consigue el tridente de Naz'jan que está en su poder."}}
D[11626] = {"El emisario",{"Encuentra a Leviroth en las aguas bajo el iceberg que flota en el límite norte de las Ruinas Tralladón. Utiliza el tridente de Naz'jan para matarlo y vuelve hasta Karuk al norte del Litoral Tralladón."}}
D[11627] = {"Punto de ebullición",{"Imperean quiere que sometas a Cocer y a Xurn. Cuando lo hayas logrado, vuelve a verla a las Ruinas de Eldra'nath."}}
D[11628] = {"Embozos de la Plaga",{"El cabecilla Vendaval de Invierno del Poblado Taunka'le quiere que le lleves 5 pelambres de mamut plagado."}}
D[11629] = {"Regresa junto a la médium",{"Lleva el primordial de Imperean a la médium Colmillo Gruñente a la Avanzada Bor'gorok."}}
D[11630] = {"La tierra mala",{"Lleva 8 montones de tierra plagada al cabecilla Vendaval de Invierno al Poblado Taunka'le."}}
D[11631] = {"Una visión de aire",{"Usa el primordial de Imperean para realizar un ritual en el tótem de Colmillo Gruñente en la Avanzada Bor'gorok y consigue información sobre el clarividente Caminante Siniestro.","","Después, habla con la médium Colmillo Gruñente."}}
D[11632] = {"Lo que nos trae el frío...",{"Lleva el caparazón endurecido de Ith'rix al alto señor supremo Colmillosauro al Bastión Grito de Guerra."}}
D[11633] = {"Pasar desapercibido",{"El cabecilla Vendaval de Invierno, del Poblado Taunka'le, quiere que te pongas el embozo de la Plaga imbuido en la Ciudad Templo de En'kilah y que investigues la Aguja de Sangre, la Aguja de Dolor y la Aguja de Putrefacción."}}
D[11634] = {"Maestro del viento To'bor",{"Preséntate ante el maestro del viento To'bor en el Bastión Grito de Guerra."}}
D[11635] = {"El espíritu del clarividente Caminante Siniestro",{"Habla con el espíritu del clarividente Caminante Siniestro dentro de Magmoth."}}
D[11636] = {"Viaje en alfombra mágica",{"Habla con Yanni en el Bastión Grito de Guerra para organizar un viaje seguro hasta la costa. Cuando llegues al Desembarco de Garroh, habla con el aniquilador Grek'lor."}}
D[11637] = {"Kajanishu",{"Recupera el fetiche de Kajanishu y úsalo sobre los restos del clarividente Caminante Siniestro.","","Tendrás que darle el fetiche al espíritu del clarividente Caminante Siniestro, dentro de Magmoth."}}
D[11638] = {"Devuelve mis restos",{"Entrega los restos del clarividente Caminante Siniestro, que descansan debajo de su espíritu, a la médium Colmillo Gruñente en la Avanzada Bor'gorok."}}
D[11639] = {"Venganza en Magmoth",{"Mata a 10 chamanes de Magmoth, 5 batidores de Magmoth, 3 trituradores de Magmoth y 3 compañeras de Magmothregar. Después, vuelve a ver a Ortrosh en la Avanzada Bor'gorok."}}
D[11640] = {"Palabras de poder",{"Lleva el pergamino del sumo sacerdote Naferset, el pergamino del sumo sacerdote Talet-Kha y el pergamino del sumo sacerdote Andorath al cabecilla Vendaval de Invierno del Poblado Taunka'le."}}
D[11641] = {"Un ataque valeroso",{"Mata a 15 necrófagos de En'kilah y a 5 nigromantes de En'kilah y vuelve a informar a Durm Pellejo de Hielo, en el Poblado Taunka'le."}}
D[11642] = {"El tanque no se va a reparar solo",{"Habla con Mobu en el Desembarco de Garrosh."}}
D[11643] = {"El transijigamárigo neumático para tanques de Mobu",{"Mobu en la Costa de los Ecos de la Tundra Boreal quiere que recuperes su transijigamárigo neumático para tanques."}}
D[11644] = {"¡Placas de metal superfuertes!",{"Mobu en la Costa de los Ecos de la Tundra Boreal quiere que consigas 10 placas de metal superfuertes."}}
D[11645] = {"¡Sucios y apestosos snóbolds!",{"Recupera 10 cajas de cosas de Ingeniosa y devuélveselas a Ingeniosa Piñonflojo en la Pista de Aterrizaje de Palanqueta."}}
D[11646] = {"La inquisición boreal",{"Donathan te ha ordenado que ofrezcas tu ayuda al bibliotecario Normantis en la Torre de los Magos en El Saliente Ámbar."}}
D[11647] = {"Neutralizar las calderas",{"La sabia Aeire, del Poblado Taunka'le, quiere que uses su tótem para neutralizar la caldera este, la caldera central y la caldera oeste en la Ciudad Templo de En'kilah."}}
D[11648] = {"El arte de la persuasión",{"El bibliotecario Normantis de El Saliente Ámbar quiere que uses el taladro neural con el hechicero de Berilo encarcelado hasta que revele la ubicación de Lady Evanor."}}
D[11649] = {"Motas de los iracundos",{"Consigue 5 motas de tempestad y entrégaselas a Imperean en las Ruinas de Eldra'nath."}}
D[11650] = {"Un par de cositas más...",{"Consigue las herramientas de Ingeniosa, un condensador sobrecargado y un puñado de polvo de Rocanar. Llévaselos a Ingeniosa Piñonflojo en la Pista de Aterrizaje de Palanqueta."}}
D[11651] = {"Muchas gracias...",{"Habla con el aniquilador Grek'lor en la Costa de los Ecos."}}
D[11652] = {"Las Llanuras de Nasam",{"Usa el tanque de asedio de la Horda para matar a 100 soldados de la Plaga y rescatar a 3 soldados Grito de Guerra heridos en las Llanuras de Nasam. También tienes que revelar la identidad del líder del asalto de la Plaga.","","Informa a Garrosh Grito Infernal en el Bastión Grito de Guerra si tienes éxito."}}
D[11653] = {"¡Ja!... ¡Ya no eres tan grande!",{"Pon a prueba el rayo reductor prototípico ultraavanzado de Ingeniosa sobre 5 trituradores de Magmoth o sobre 5 compañeras de Magmothregar. Cuando lo hayas hecho, vuelve a hablar con ella a la Pista de Aterrizaje de Palanqueta."}}
D[11654] = {"La Aguja de Sangre",{"Busca más información sobre el vial de sangre fresca en La Aguja de Sangre."}}
D[11655] = {"En la niebla",{"Waltor de Pal'ea en la Costa de los Ecos, en la Tundra Boreal, quiere que mates Kvaldir y recuperes 8 reliquias colmillarr."}}
D[11656] = {"Quema en efigie",{"Waltor de Pal'ea en la Costa de los Ecos en la Tundra Boreal quiere que utilices la antorcha colmillarr para quemar los barcos Kvaldir en Pal'ea y en el Desembarco de Garrosh. Debes destruir los siguientes barcos: Las Fauces de la Sierpe, El Kur Drakkar, Martillo de Bor y Yunque de Bor."}}
D[11657] = {"Caza de antorchas",{"Atrapa 4 antorchas seguidas y después ve a hablar con el maestro tragafuegos."}}
D[11658] = {"Plan B",{"Reúne 10 conjuntos Grito de Guerra y un estandarte Grito de Guerra. Llévaselos a Ingeniosa Piñonflojo a la Pista de Aterrizaje de Palanqueta."}}
D[11659] = {"¡Destruye los globos!",{"Destruye 5 globos de sangre e informa al rastreador de nieve Junek en el Poblado Taunka'le."}}
D[11660] = {"El cuerno del viejo marinero",{"Waltor de Pal'ea en la Costa de los Ecos, en la Tundra Boreal, quiere que le lleves el cuerno del viejo marinero."}}
D[11661] = {"Orabus el Timonel",{"Waltor de Pal'ea en la Costa de los Ecos en la Tundra Boreal quiere que uses el cuerno del viejo marinero para invocar a Orabus el Timonel. Cuando lo hayas invocado, mata a Orabus el Timonel."}}
D[11662] = {"¡Encuentra a Karuk!",{"Busca a Karuk en el Litoral Tralladón."}}
D[11663] = {"Informando de las noticias",{"Normantis te ha pedido que te presentes ante el bibliotecario Donathan en El Saliente Ámbar."}}
D[11664] = {"Escapar de la niebla",{"Sigue a Mootoo la Joven para salir de la niebla. Habla con el anciano Mootoo si consigues salvar a Mootoo la Joven."}}
D[11665] = {"Crocoliscos en la ciudad",{"Llévale una cría de crocolisco al viejo Barlo, que está pescando en el Lago Silmyr, al noreste de la Ciudad de Shattrath."}}
D[11666] = {"Pilluelos de cebo",{"Llévale un dardo aleta negra al viejo Barlo, que está pescando en el Lago Silmyr, al noreste de la Ciudad de Shattrath."}}
D[11667] = {"Aquel que se escapó",{"Pesca el pezfango más grande del mundo y llévaselo al viejo Barlo, que está pescando en el Lago Silmyr, al noreste de la Ciudad de Shattrath."}}
D[11668] = {"No es fácil pescar gambas",{"Llévale 10 gambas de agua dulce gigantes al viejo Barlo, que está pescando en el Lago Silmyr, al noreste de la Ciudad de Shattrath."}}
D[11669] = {"Filete de sangrevil",{"Llévale un pargo sangrevil enorme al viejo Barlo, que está pescando en el Lago Silmyr, al noreste de la Ciudad de Shattrath."}}
D[11670] = {"¡Han sido los orcos! ¡Lo juro!",{"Ponte el disfraz de orco Grito de Guerra y a continuación clava el estandarte Grito de Guerra sobre el cadáver de Magmothregar. Después, devuelve el disfraz a Ingeniosa Piñonflojo en la Pista de Aterrizaje de Palanqueta."}}
D[11671] = {"Carrera a contrarreloj",{"Donathan en El Saliente Ámbar te ha encargado que uses el detonador de escudo de Berilo para destruir el escudo en Alto de Berilo. Entonces, tendrás que derrotar a Salrand para conseguir la llave que guarda."}}
D[11672] = {"Día de alistamiento",{"Reúnete con el general Arlos en el cuartel de la Fortaleza Denuedo."}}
D[11673] = {"¡Sácame de aquí!",{"Escolta a Chalati Voltiflop hasta un lugar seguro y después informa a Palanqueta Todogás en la Pista de Aterrizaje de Palanqueta."}}
D[11674] = {"La sabia Altamesa ha desaparecido",{"Encuentra a la sabia Altamesa cerca de Los Cubiles de los Moribundos."}}
D[11675] = {"Una muerte digna",{"Mata a 10 magnatauros apestados y después vuelve a ver a la sabia Altamesa al sur de Los Cubiles de los Moribundos."}}
D[11676] = {"Clemente libertad",{"El acechasombras Canarius en la Avanzada de las Granjas Grito de Guerra quiere que liberes a 5 prisioneros de la Plaga."}}
D[11677] = {"Detén a la Plaga",{"La sabia Altamesa, al sur de Los Cubiles de los Moribundos, te ha pedido que uses las semillas de purificación de Altamesa en la caldera de peste de Los Cubiles de los Moribundos para neutralizarla."}}
D[11678] = {"Encuentra a Cornopúa",{"Encuentra al enviado Cornopúa en Talramas."}}
D[11679] = {"Volver a forjar la llave",{"Donathan te ha enviado a hablar con Surristrasz en El Saliente Ámbar."}}
D[11680] = {"¡Volando!",{"Cuando estés listo para liberar a Evanor, entrégale la llave de Salrand al mago de guerra Anzim."}}
D[11681] = {"Rescatar a Evanor",{"Anzim en El Saliente Ámbar quiere que vueles con sus magos de guerra para liberar a Lady Evanor en Alto de Berilo. Después tendrás que ir a informarle en la Torre de los Magos."}}
D[11682] = {"Una charla con el dragón",{"Lady Evanor te ha enviado a hablar con Surristrasz en El Saliente Ámbar."}}
D[11683] = {"La necrópolis caída",{"Mata a 20 miembros de la Plaga de cualquier tipo en Talramas y las Pozas Purulentas. Después vuelve junto a la sabia Altamesa que se encuentra justo al sur de Los Cubiles de los Moribundos."}}
D[11684] = {"Marcando los sumideros",{"El Abuelo Mahan en el Poblado Taunka'le quiere que uses el mapa de Los Campos de Géiseres para marcar la ubicación del sumidero sur, el sumidero noroeste y el sumidero noreste."}}
D[11685] = {"El corazón de los elementos",{"Llévale 5 corazones elementales a la domadora del viento Barah en el Poblado Taunka'le."}}
D[11686] = {"Las Granjas Grito de Guerra",{"El acechasombras Ickoris en la Avanzada de las Granjas Grito de Guerra quiere que explores el Granero Grito de Guerra, la Granja de Torp y el Matadero Grito de Guerra"}}
D[11687] = {"El doctor y el señor exánime",{"Acaba con el doctor Muecafilada y con el señor exánime Invierno Helado. Después vuelve junto a la sabia Altamesa al sur de Los Cubiles de los Moribundos."}}
D[11688] = {"Malditos puercos apestosos",{"El granjero Torp en las Granjas Grito de Guerra quiere que mates a 10 puercos sin vida."}}
D[11689] = {"Regresa con las malas noticias",{"Habla con la abuela Taiga en el Poblado Taunka'le."}}
D[11690] = {"Tráelos de vuelta con vida",{"El granjero Torp en las Granjas Grito de Guerra quiere que rescates a 8 bestias kodo infectadas."}}
D[11691] = {"Invocar a Ahune",{"Lleva el tótem de magma del Anillo de la Tierra a la piedra de hielo."}}
D[11692] = {"Preséntate ante Bixie",{"Mordle Volopiñón te ha pedido que encuentres a Bixie Patituerca al sur de Los Cubiles de los Moribundos."}}
D[11693] = {"Oh genial... ¡magnatauros apestados!",{"Mata 10 magnatauros apestados y después vuelve a ver a Bixie Patituerca que está al sur de Los Cubiles de los Moribundos."}}
D[11694] = {"En esas cuevas pasa algo raro",{"Bixie Patituerca, que merodea al sur de Los Cubiles de los Moribundos, te ha pedido que uses el polvo de inhibición de Bixie en la caldera de peste del Cubil de los Moribundos para neutralizarlo."}}
D[11695] = {"El Cuerno de Furia Elemental",{"Reclama la mitad inferior del cuerno y la mitad superior del cuerno al cabecilla Gorgogluglú y al cabecilla Borbogluglú y llévaselas a la domadora del viento Barah en el Poblado Taunka'le."}}
D[11696] = {"¡Ahune está aquí!",{"Encuentra a Luma Cielomater en el Recinto de los Esclavos."}}
D[11697] = {"¡Demontre, Mañosa se ha metido en la necrópolis!",{"Encuentra a Mañosa Silbatín dentro de Talramas."}}
D[11698] = {"También se podría hacer limpieza de la Plaga",{"Mata a 20 miembros de la Plaga de cualquier tipo en Talramas y las Pozas Purulentas. Después vuelve junto a Bixie Patituerca, que se encuentra justo al sur de Los Cubiles de los Moribundos."}}
D[11699] = {"Estoy encerrada en esta maldita jaula... ¡Pero no por mucho tiempo!",{"Consigue un cristal del núcleo de motor, un giroscopio mágico y una piedra de la Plaga de pilotaje. Entrégaselas a Mañosa Silbatín en Talramas."}}
D[11700] = {"Avisa a Bixie",{"Habla con Bixie Patituerca, justo al sur de Los Cubiles de los Moribundos."}}
D[11701] = {"De vuelta a la Pista de Aterrizaje",{"Habla con Palanqueta Todogás en la Pista de Aterrizaje de Palanqueta, en la Tundra Boreal."}}
D[11702] = {"El rey Mrgl-Mrgl",{"Habla con el rey Mrgl-Mrgl en el Refugio Aleta Invernal."}}
D[11703] = {"Llega hasta Getry",{"Encuentra al acechasombras Getry en las Granjas Grito de Guerra."}}
D[11704] = {"El rey Mrgl-Mrgl",{"Habla con el rey Mrgl-Mrgl en el Refugio Aleta Invernal."}}
D[11705] = {"Una empresa insensata",{"Ayuda a Getry a derrotar a Varidus el Desollador en las Granjas Grito de Guerra.","","Informa a Garrosh Grito Infernal si tienes éxito."}}
D[11706] = {"El derrumbamiento",{"La domadora del viento Barah en el Poblado Taunka'le quiere que derrumbes los sumideros nerubianos usando el Cuerno de Furia Elemental y que derrotes a Lord Kryxix."}}
D[11707] = {"Llamada de socorro",{"Habla con Palanqueta Todogás en la Pista de Aterrizaje de Palanqueta."}}
D[11708] = {"Los mecagnomos",{"Escucha la historia de Palanqueta Todogás y después busca a Jinky Alatuerca en la Pista de Aterrizaje de Palanqueta."}}
D[11709] = {"La carga de Nork Ansiasangre",{"Habla con el celador Nork Ansiasangre en el Bastión Grito de Guerra en la Tundra Boreal."}}
D[11710] = {"No es seria esta transmateria...",{"Reúne 15 piezas de repuesto de Palanqueta y llévaselas a Mordle Volopiñón en la Pista de Aterrizaje de Palanqueta."}}
D[11711] = {"Entrega de cobardes... en menos de 30 minutos, o será gratis",{"Lleva al desertor de la Alianza hasta el cruce al este del Bastión Grito de Guerra y dispara tu pistola de bengalas Grito de Guerra para mandar una señal a la Alianza.","","Informa al explorador Tungok cuando hayas llevado al desertor de la Alianza a su destino con éxito."}}
D[11712] = {"Remaldeciente",{"Jinky Alatuerca en la Pista de Aterrizaje de Palanqueta te ha pedido que uses la inyección de transmateria remaldeciente en 6 mecagnomos de Palanqueta."}}
D[11713] = {"Marcando los sumideros",{"Abner Dinamométrica en la Pista de Aterrizaje de Palanqueta quiere que uses el mapa de Los Campos de Géiseres para marcar la ubicación del sumidero sur, el sumidero noroeste y el sumidero noreste."}}
D[11714] = {"Exterminación de alimañas",{"El explorador Tungok en las Llanuras Sanguiespora en la Tundra Boreal quiere que mates a 8 cosechadores Sanguiespora, a 5 ignitores Sanguiespora y a 2 asadores Sanguiespora."}}
D[11715] = {"¡Dale más gasolina!",{"Abner Dinamométrica en la Pista de Aterrizaje de Palanqueta quiere que recojas 8 barriles de aceite gracias al recolector de aceite portátil."}}
D[11716] = {"Las maravillosas sanguiesporas",{"La maga sangrienta Laurith en las Llanuras Sanguiespora de la Tundra Boreal quiere que recuperes 10 carpelos de sanguiespora."}}
D[11717] = {"La fuente del polen",{"La maga sangrienta Laurith, en las Llanuras Sanguiespora de la Tundra Boreal, quiere que recuperes 5 muestras de polen de polilla Sanguiespora."}}
D[11718] = {"Un robot bajo pieles de mamut",{"Abner Dinamométrica en la Pista de Aterrizaje de Palanqueta quiere que le lleves 6 pellejos de mamut gruesos."}}
D[11719] = {"Un sujeto de prueba adecuado",{"La maga sangrienta Laurith, en las Llanuras Sanguiespora de la Tundra Boreal, te ha pedido que uses la flor sanguiespora polinizada y le permitas ver los resultados."}}
D[11720] = {"La invasión de Gammoth",{"Habla con Primigenio Cuerno Poderoso en las Llanuras Sanguiespora en la Tundra Boreal."}}
D[11721] = {"Gammothra el Torturador",{"Mata a Gammothra y devuelve la cabeza de Gammothra a Primigenio Cuerno Poderoso en las Llanuras Sanguiespora en la Tundra Boreal."}}
D[11722] = {"Trofeos de Gammoth",{"Llévale la cabeza de Gammothra a Garrosh Grito Infernal al Bastión Grito de Guerra."}}
D[11723] = {"¡Utiliza el Vibro-Motor 5000!",{"Abner Dinamométrica de la Pista de Aterrizaje de Palanqueta quiere que uses el Vibro-Motor 5000 para derrumbar los túneles nerubianos y que venzas a Lord Kryxix."}}
D[11724] = {"¿Tortilla gigante de polilla?",{"Llévale el huevo gigante resplandeciente a la maga sangrienta Laurith que está en las Llanuras Sanguiespora en la Tundra Boreal."}}
D[11725] = {"Buscando al piloto Barrena",{"Encuentra a Iggy \"Barrena\" Conmutador en Los Campos de Géiseres."}}
D[11726] = {"Un poquito de picante",{"Iggy \"Barrena\" Conmutador, de Las Pozas Escaldantes, quiere que consigas 4 bolsas de especias de górloc."}}
D[11727] = {"La hora de los héroes",{"Preséntate ante el Sargento Colinamartillo en la Fortaleza Denuedo."}}
D[11728] = {"Lupus Pupus",{"Iggy \"Barrena\" Conmutador de Las Pozas Escaldantes quiere le lleves 8 trozos de microfilm."}}
D[11729] = {"El destornillador ultrasónico",{"Entrégale el destornillador ultrasónico a Ingeniosa Piñonflojo en la Pista de Aterrizaje de Palanqueta."}}
D[11730] = {"Maestro y servidor",{"Usa el destornillador ultrasónico para reprogramar 15 robots y después vuelve a ver a Ingeniosa Piñonflojo a la Pista de Aterrizaje de Palanqueta.","","Asegúrate de despojar al robot muerto antes de reprogramarlo."}}
D[11731] = {"Lanzamiento de antorchas",{"Gana la prueba de lanzamiento de antorchas y ve a hablar con el maestro tragafuegos."}}
D[11732] = {"¡Profana este fuego!"}
D[11733] = {"Atravesando la falla",{"Surristrasz quiere que viajes hasta Gelidar. Cuando estés allí, habla con el archimago Berinand."}}
