D[11788] = {"Dando media vuelta... Otra vuelta más",{"Desmonta a Twonky, ED-210, Max Blasto y El Moledor y vuelve para informar a Jinky Alatuerca en la Pista de Aterrizaje de Palanqueta."}}
D[11789] = {"Un soldado en apuros",{"El médico Espino, a las afueras de la Fortaleza Denuedo, quiere que te adentres en la bodega de El Rompetormentas y recuperes el contraveneno de Espino de un cajón de suministros de primeros auxilios."}}
D[11790] = {"Cultores entre nosotros",{"Habla con el capitán \"Zurdo\" Vela al Tercio a bordo de El Rompetormentas en la Fortaleza Denuedo."}}
D[11791] = {"Informa a Arlos",{"Habla con el general Arlos dentro del cuartel en la Fortaleza Denuedo."}}
D[11792] = {"Enemigos de la Luz",{"El presagista Vurenn quiere que luches contra los cultores necrólitos cerca de Lindeallá al norte de la Fortaleza Denuedo y les arrebates el comunicado de cultor."}}
D[11793] = {"Más investigación",{"Lleva el comunicado de cultor a la vindicadora Yaala dentro de la posada en la Fortaleza Denuedo."}}
D[11794] = {"La veda está abierta",{"La vindicadora Yaala quiere que uses el óculo del exorcista en tres puntos diferentes de la Fortaleza Denuedo para descubrir y derrotar a los miembros del Culto de los Malditos."}}
D[11795] = {"Protocolo de emergencia: sección 8.2, párrafo C",{"Recupera 6 insignias de piloto de Palanqueta de los cuerpos de los pilotos de reconocimiento de Palanqueta y devuélveselas a Iggy \"Barrena\" Conmutador en Las Pozas Escaldantes."}}
D[11796] = {"Protocolo de emergencia: sección 8.2, párrafo D",{"Iggy \"Barrena\" Conmutador quiere que hundas unos restos al este, unos restos al sur y unos restos al noroeste."}}
D[11797] = {"El asedio",{"El sargento Colinamartillo quiere que mates 6 reptadores de cripta en las Arenas de Nasam, a las afueras de la Fortaleza Denuedo."}}
D[11798] = {"El maestro de palancas",{"Busca el manual del maestro de palancas y vuelve con la cabeza de Mecazod junto a Palanqueta Todogás."}}
