D[11864] = {"Objetivos de una misión"}
D[11865] = {"No se merecen la muerte",{"Zaza en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que utilices el montón de pellejos falsos para tender una trampa a 8 tramperos de Nesingwary."}}
D[11866] = {"Las orejas de nuestros enemigos",{"El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal ha dicho que te recompensará si le traes 15 orejas de lacayo de Nesingwary."}}
D[11867] = {"No tenemos suficientes orejas...",{"El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal ha dicho que te recompensará si le traes 15 orejas de lacayo de Nesingwary."}}
D[11868] = {"La llegada de la Asesina",{"Zaza en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Karen la Asesina de Caribús."}}
D[11869] = {"Cada almeja con su pareja",{"La hierofante Cenius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a 10 buzos enloquecidos despojadores."}}
D[11870] = {"El Tramo Abandonado",{"Busca a la hierofante Liandra en El Tramo Abandonado."}}
D[11871] = {"No bajo nuestra vigilancia",{"La hierofante Liandra en El Tramo Abandonado en la Tundra Boreal quiere que recuperes 12 envíos de piezas de animales."}}
D[11872] = {"El villano maestro de almejas...",{"Mata al maestro de almejas K y vuelve con la hierofante Cenius en el Campamento D.E.H.T.A."}}
D[11873] = {"Dale la noticia a Palanqueta",{"Ábrete camino hasta la Pista de Aterrizaje de Palanqueta y habla con Palanqueta Todogás."}}
D[11874] = {"Upper Deck Promo - Rocket Mount"}
D[11875] = {"Lograr ventaja",{"Llévale 8 residuos abisales al emisario Mordin en la Ciudad de Shattrath."}}
D[11876] = {"Ayuda a aquellos que no pueden valerse por sí mismos",{"El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que utilices el aplasta trampas de D.E.H.T.A. para liberar a 8 crías de mamut."}}
D[11877] = {"Planes de ataque Furia del Sol",{"Lord Torvos en la Ciudad de Shattrath quiere que consigas los planes de ataque Furia del Sol."}}
D[11878] = {"Khu'nok sabrá qué hacer",{"Llévale la cría de mamut huérfana a Khu'nok el Behemoth en la Tundra Boreal."}}
D[11879] = {"Kaw el Destructor de Mamuts",{"Mata a Kaw el Destructor de Mamuts y consigue la alabarda de guerra de Kaw. Llévasela al archidruida Lathorius del Campamento D.E.H.T.A. en la Tundra Boreal."}}
D[11880] = {"La investigación multifase",{"El presagista Haronem de la Ciudad de Shattrath quiere que uses las gafas espectrográficas multifase para obtener 6 lecturas multifase."}}
D[11881] = {"¡Cárgala!",{"Fezzix Girarrosca quiere que ayudes a Jenny a llegar desde el lugar del accidente hasta el Poblado Taunka'le sin perder todo su cargamento."}}
D[11882] = {"Jugando con fuego",{"Habla con un maestro tragafuegos en cualquiera de las capitales de la Alianza."}}
D[11883] = {"¿Danza con fuego?",{"Habla con un maestro de danza del fuego en cualquier capital de la Horda."}}
D[11884] = {"Ned, señor de rinocerontes...",{"Kilinger el Vigía del Cubil en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Nedar, Señor de rinocerontes y a su compañero, \"Fiambrera.\""}}
D[11885] = {"Sangre adversaria",{"Encuentra los montones de cráneos en el centro de los círculos de invocación de Skettis. Invoca y derrota a cada uno de los descendientes usando 10 Pergaminos perdidos en el Tiempo en el montón de cráneos. Vuelve a ver a Hazzik al Alto de los Vientonegro."}}
D[11886] = {"Actividad sospechosa",{"Ve hasta el nuevo Campamento Crepúsculo al sur de la entrada a las Cavernas de Brazanegra en La Ensenada de Zoram de Vallefresno y recupera la correspondencia Crepuscular de los cultores. Después, pide la ayuda del guía Anillo de la Tierra mediante la baliza totémica."}}
D[11887] = {"Suministros de emergencia",{"Consigue 7 equipos de emergencia gnomos de los cuerpos de los pilotos de reconocimiento de Palanqueta estrellados y llévaselos a Fezzix Girarrosca al Poblado Taunka'le."}}
D[11888] = {"Vuela al Poblado Taunka'le",{"Habla con el sabio Tierra y Cielo en el Poblado Taunka'le."}}
D[11889] = {"Muertos desde arriba",{"El sargento Colinamartillo quiere que utilices la red reforzada para ayudarte a matar a 6 escupefuegos plagados a las afueras de la Fortaleza Denuedo."}}
D[11890] = {"¿Qué se traen entre manos?",{"Investiga la zona que rodea la Estación de Bombeo de Palanqueta. Después, vuelve a ver al sabio Tierra y Cielo en el Poblado Taunka'le."}}
D[11891] = {"Un disfraz inofensivo",{"Utiliza el orbe del reptador para espiar en el nuevo Campamento Crepuscular al oeste de la entrada de las Cavernas de Brazanegra en La Ensenada de Zoram en Vallefresno, luego invoca al guía del Anillo de la Tierra usando la baliza totémica."}}
D[11892] = {"El asesinato de Harold Sendero",{"El archidruida Lathorius en el Campamento D.E.H.T.A. en la Tundra Boreal quiere que mates a Harold Sendero."}}
D[11893] = {"El poder de los elementos",{"Dorain Pezuña Helada en el Poblado Taunka'le quiere que utilices el tótem alma de viento para reunir la energía de 10 furibundos de vapor."}}
D[11894] = {"Yo lo remendaba, yo lo remendé",{"Fezzix Girarrosca del Poblado Taunka'le quiere que le lleves 5 cueros curados con vapor."}}
D[11895] = {"Domina a la tormenta",{"Vence a la tempestad de tormenta y vuelve junto al sabio Tierra y Cielo en el Poblado Taunka'le."}}
D[11896] = {"Débiles ante el relámpago",{"Mientras estén debilitados por el Poder de la tormenta, destruye a 15 unidades robóticas, exceptuando a los mecagnomos, en la gran área de pozas que rodean la Estación de Bombeo de Palanqueta.","","Después, vuelve junto al sabio Tierra y Cielo en el Poblado Taunka'le."}}
D[11897] = {"Obstruye los sumideros",{"El sargento Colinamartillo quiere que uses los explosivos incendiarios para hacer explotar los sumideros suroeste y noroeste de la Fortaleza Denuedo."}}
D[11898] = {"Abriéndose paso",{"Derrota al príncipe Valanar y a sus tenientes, Vanthryn el Despiadado y Luthion el Vil, e informa de ello al cabecilla Vendaval de Invierno en el Poblado Taunka'le."}}
D[11899] = {"Las almas de los desembrujados",{"Usa el cazador de almas de la Abuela para capturar las almas de 10 mecagnomos de Palanqueta. Después, vuelve junto a la abuela Taiga en el Poblado Taunka'le cuando hayas terminado."}}
D[11900] = {"Lectura de medidores",{"El archimago Berinand en el Escudo de Tránsito te ha pedido que recojas las lecturas de sus instrumentos en Gelidar."}}
D[11901] = {"¿Destacamento? ¿Qué destacamento?",{"Gerald Verde de Lindeallá quiere que vayas a la mina del norte y descubras qué le ocurrió al destacamento militar que enviaron allí."}}
D[11902] = {"Una evidencia perniciosa",{"Vuelve junto a Gerald Verde en Lindeallá."}}
D[11903] = {"Es hora de actuar",{"Gerald Verde en Lindeallá quiere que mates a 14 carroñeros apestados."}}
D[11904] = {"Frutos de nuestro trabajo",{"Ve hasta la mina de Lindeallá, consigue la llave para liberar la vagoneta del capitán Jacobs y utilízala para liberar la vagoneta de mena. Vuelve a ver a Gerald Verde en Lindeallá cuando hayas completado esta misión."}}
D[11905] = {"Posponer lo inevitable",{"El archimago Berinand en el Escudo de Tránsito quiere que uses el refabricador interdimensional cerca de la falla de El Nexo."}}
D[11906] = {"Limpiando las Pozas",{"Recoge 15 piezas de repuesto de Palanqueta y entrégaselas a Ojos de Hierro en el Poblado Taunka'le."}}
D[11907] = {"Los subtenientes",{"Derrota a Twonky, ED-210, Max Blasto y El Moledor, y vuelve a ver al sabio Tierra y Cielo al Poblado Taunka'le."}}
D[11908] = {"Material de referencia",{"Jeremiah Hawning quiere que recuperes el libro \"Campos, fábricas y talleres\" del edificio en llamas junto a la mina en Lindeallá."}}
D[11909] = {"Vence al maestro de palancas",{"Busca el manual del maestro de palancas y llévale la cabeza de Mecazod a la abuela Taiga en el Poblado Taunka'le."}}
