D[12039] = {"Sangre negra de Yogg-Saron",{"Borus Doblahierro en Martillo de Agmar en el Cementerio de Dragones quiere que consigas 10 muestras de sangre negra de Yogg-Saron."}}
D[12040] = {"Un enemigo en Arthas",{"Kilix el Desenmarañador, en El Foso de Narjun del Cementerio de Dragones, te ha pedido que mates 6 infraseñores Anub'ar."}}
D[12041] = {"El imperio perdido",{"Llévale el plan de batalla de Kilix al señor supremo Agmar en Martillo de Agmar al este."}}
D[12042] = {"Corazón de los ancestros",{"Drakuru quiere que vayas al punto más alto del Aserradero Cielo Azul y que encuentres el corazón de los ancestros."}}
D[12043] = {"Defensa de Boquilla Oxidada",{"Mata a 12 cavadores de la Plaga y a 1 capataz del baldío en las excavaciones que rodean Reposo de Galakrond. Vuelve con Narf en el Puesto Boquilla Oxidada cuando hayas completado esta tarea."}}
D[12044] = {"Abasteciéndose",{"Reúne 8 montones de mena de amalgama de las excavaciones que rodean Reposo de Galakrond y llévaselos a Xink en el Puesto Boquilla Oxidada."}}
D[12045] = {"Hielo afilado",{"Recoge 4 montones de fragmentos de hielo de los elementales de hielo al norte y llévaselos a Zivlix en el Puesto Boquilla Oxidada."}}
D[12046] = {"Un recubrimiento suave",{"Recoge 12 pellejos de animal finos de los tuneladores jormungar o de los cóndores de hueso de dragón en los aledaños del Puesto Boquilla Oxidada. Cuando hayas encontrado los pellejos, llévaselos a Zivlix."}}
D[12047] = {"Algo que no se derrita",{"Busca 12 trozos de hueso astillados entre los huesos de dragón al este del Puesto Boquilla Oxidada."}}
D[12048] = {"Armamentos de la Plaga",{"Borus Doblahierro en Martillo de Agmar en el Cementerio de Dragones quiere que le traigas 8 armamentos de la Plaga."}}
D[12049] = {"Difícil de tragar",{"Lucha contra un jormungar descomunal al este del Puesto Boquilla Oxidada hasta que abra la boca y lánzale una carga explosiva potente dentro de la garganta. Recoge 6 trozos de carne de jormungar chamuscada del suelo cuando haya explotado y llévaselos a Xink."}}
D[12050] = {"¡Más madera!",{"Utiliza el dispositivo de control de la trituradora de Xink para llamar a una trituradora una vez que llegues a los nidales de las arpías al norte. Reúne 50 montones de madera de los árboles de la zona y luego vuelve junto a Xink en el Puesto Boquilla Oxidada.","","Si pierdes el dispositivo de control de la trituradora de Xink, habla con Xink en el Puesto Boquilla Oxidada para que te dé uno nuevo."}}
D[12051] = {"Machacar algunas plumas",{"Mata a 20 arpías al noroeste del Puesto Boquilla Oxidada para Narf en el Puesto Boquilla Oxidada."}}
D[12052] = {"¡Toma arpía!",{"Mata a la maestra del Viento Helado y a 15 arpías Viento Helado en las montañas al noroeste del Puesto Boquilla Oxidada. Vuelve con Narf cuando hayas completado esta tarea.","","Si necesitas el dispositivo de control de la trituradora de Xink, habla con Xink en el Puesto Boquilla Oxidada."}}
D[12053] = {"El poder de la Horda",{"El capataz primero Juktok en Martillo de Agmar en el Cementerio de Dragones quiere que utilices el confalón de batalla Grito de Guerra en el Poblado Bruma de Hielo y lo defiendas de sus atacantes.","","Devuelve el confalón de batalla Grito de Guerra cuando hayas terminado."}}
D[12054] = {"Descifrar el diario",{"Llévale una ramita de aliento de espíritus a la sabia Paluna en el Campamento Oneqwah."}}
D[12055] = {"Un extraño aparato",{"Lleva el extraño dispositivo de Goramosh a la imagen de la archimaga Modera en Reposo Estelar."}}
D[12056] = {"Marcado para morir: Sumo cultor Zangus",{"Mata al Sumo cultor Zangus y lleva la cabeza del Sumo cultor Zangus al capitán Gort en el Martillo de Agmar en el Cementerio de Dragones."}}
D[12057] = {"El escrito encuadernado en carne",{"Devuelve el escrito encuadernado en carne al capitán Gort del Martillo de Agmar."}}
D[12058] = {"Las profecías rúnicas",{"La sabia Paluna en el Campamento Oneqwah quiere que descifres las tres placas rúnicas."}}
D[12059] = {"Un extraño aparato",{"Lleva el extraño dispositivo de Goramosh a la imagen del archimago Aethas Atracasol a Martillo de Agmar."}}
D[12060] = {"Proyecciones y planos",{"Acércate y observa la proyección en la cumbre de la Aguja de Flujo que hay flotando sobre los Jardines Reposo Lunar.","","Luego vuelve hasta la imagen de la archimaga Modera en Reposo Estelar con la información."}}
D[12061] = {"Proyecciones y planos",{"Acércate y observa la proyección en la cumbre de la Aguja de Flujo que hay flotando sobre los Jardines Reposo Lunar.","","Luego vuelve hasta la imagen del archimago Aethas Atracasol en Martillo de Agmar con la información."}}
D[12062] = {"Insulta a Coren Cerveza Temible",{"Habla con Coren Cerveza Temible."}}
D[12063] = {"Fuerza de Bruma de Hielo",{"Encuentra a Banthok Bruma de Hielo en el Poblado Bruma de Hielo."}}
D[12064] = {"Las cadenas de los Anub'ar",{"Banthok Bruma de Hielo en el Poblado Bruma de Hielo en el Cementerio de Dragones te ha pedido que le traigas el fragmento de la llave de Anok'ra, el fragmento de la llave de Tivax y el fragmento de la llave de Sinok."}}
D[12065] = {"El foco de la playa",{"Consigue el anillo de control de foco de línea Ley y úsalo para conseguir información del foco de línea Ley en la Orilla Resplandeciente.","","Luego, vuelve con la imagen de la archimaga Modera en Reposo Estelar."}}
D[12066] = {"El foco de la playa",{"Consigue el anillo de control de foco de línea Ley y úsalo para conseguir información del foco de línea Ley en la Orilla Resplandeciente.","","Luego, vuelve con la imagen del archimago Aethas Atracasol en Martillo de Agmar."}}
D[12067] = {"Una carta para casa",{"Lleva la carta de la capitana Malin a la comandante Saia Aceroazur a Reposo Estelar."}}
D[12068] = {"Voces entre las ruinas",{"Drakuru quiere que reúnas las tablillas Drakkari de las Ruinas de Drakil'jin y 5 muestras de mojo sacro de los oráculos y protectores Drakkari. Después tendrás que utilizar el elixir de Drakuru en el pedestal de Drakuru en las ruinas para invocar su imagen."}}
D[12069] = {"El regreso del Gran Jefe",{"Libera al gran jefe Bruma de Hielo utilizando la llave de la prisión Anub'ar y ayúdale a derrotar al infrarrey Anub'et'kan.","","Recupera un fragmento del caparazón de Anub'et'kan y devuélveselo al señor supremo Agmar en Martillo de Agmar en el Cementerio de Dragones."}}
D[12070] = {"Alentando a las tropas",{"Utiliza el fragmento de la Tierra para alentar a los gigantes de las Colinas Pardas que luchan en las Colinas Pedrusco, mata a cualquier enano férreo que se enfrente a ti y luego ve a informar a Kurun a la colina que da a Thor Modan."}}
D[12071] = {"¡Ataque aéreo!",{"Habla con Valnok Furia del Viento en el Martillo de Agmar."}}
D[12072] = {"¡Malditas bestias de añublo!",{"Usa la pistola de bengalas de Valnok para llamar a un jinete de guerra Kor'kron en el Poblado Bruma de Hielo. Monta sobre el jinete de guerra Kor'kron y úsalo para matar a 25 bestias de añublo Anub'ar.","","Si completas esta misión, vuelve junto a Valnok Furia del Viento en el Martillo de Agmar."}}
D[12073] = {"Golpear el hierro",{"Mata a 10 enanos férreos que defienden Thor Modan y vuelve al Campamento Oneqwah para informar al explorador Vor'takh."}}
D[12074] = {"Un aliado muy oportuno",{"Habla con Kurun en la colina que da a Thor Modan."}}
D[12075] = {"Pocos restos",{"Consigue una muestra de carne de roca del cadáver del gigante de hielo de la entrada a la caverna en el Vicio de Cristal, al norte del emplazamiento de Zort. Cuando hayas hecho esto, vuelve junto a Zort, cerca del centro del cañón."}}
D[12076] = {"Negocios sucios",{"Recoge 2 viales de flema corrosiva de los jormungar utilizando la rasqueta en ti. Lleva los viales a Zort en el Vicio de Cristal cuando hayas terminado."}}
D[12077] = {"Aplicar dos veces al día",{"Ofrécele a Ko'char el Irrompible el elixir que ha preparado Zort."}}
D[12078] = {"Domador de gusanos",{"Entra en las cavernas del Vicio de Cristal y captura a 3 engendros jormungar dentro de cajones robustos. ¡No te olvides de recoger los cajones cuando los engendros jormungar estén bien atrapados dentro!","","Llévale los engendros jormungar a Zort en el Vicio de Cristal."}}
D[12079] = {"Territorio preferido",{"Adéntrate en la caverna al extremo norte del Vicio de Cristal y mata a 8 alimentadores jormungar Corazón de Hielo para Ko'char el Irrompible."}}
D[12080] = {"Un gusano muy grande",{"Entra en la Caverna Corazón de Hielo y mata a Cascabore. Si aún está en tu posesión, asegúrate de usar el elixir protector de Zort para protegerte de la flema corrosiva de jormungar.","","Vuelve a ver a Ko'char el Irrompible en el Vicio de Cristal cuando hayas completado la tarea."}}
D[12081] = {"Gavrock",{"Habla con Gavrock en las Ruinas de Tethys."}}
D[12082] = {"¡Tralarí, tralará!",{"Escolta a Harrison de las Ruinas de Drakil'jin, después habla con Harkor en el Campamento de Harkor."}}
D[12083] = {"En lo alto del bosque",{"Consigue el amuleto de control de foco de línea Ley del Bosque Lothalor.","","Después, vuelve con la imagen de la archimaga Modera en Reposo Estelar."}}
D[12084] = {"En lo alto del bosque",{"Consigue el amuleto de control de foco de línea Ley y úsalo para obtener información sobre el foco de línea Ley en el Bosque Lothalor.","","Después, vuelve con la imagen del archimago Aethas Atracasol en Martillo de Agmar."}}
D[12085] = {"Una carta para casa",{"Entrega la carta del teniente Ta'zinni al señor supremo Agmar en Martillo de Agmar."}}
D[12086] = {"El hijo de Karkut",{"Ve al Confín de la Muerte, pasando Unu'pe."}}
D[12087] = {"¿Un poco de ayuda? DEPRECATED",{"El cabo Venn en el Confín de la Muerte quiere que mates a 8 defensores del zigurat."}}
D[12088] = {"Thassarian, el caballero de la Muerte",{"Busca a Thassarian dentro de El Zigurat de los Lamentos, al norte de Confín de la Muerte."}}
D[12089] = {"Se busca: Magister Keldonus",{"Mata al magister Keldonus y ve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones."}}
D[12090] = {"Se busca: Gigantauro",{"Mata a Gigantauro y vuelve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones."}}
D[12091] = {"Se busca: Garra Temible",{"Mata a Garra Temible y vuelve a ver al capitán Gort al Martillo de Agmar en el Cementerio de Dragones."}}
D[12092] = {"Devuelve la fuerza a los ancestros",{"Usa la corteza de los caminantes para devolver la fuerza a 3 ancestros Lothalor y luego vuelve con Sarendryana en Reposo Estelar."}}
D[12093] = {"Runas de coacción",{"Gavrock en las Ruinas de Tethys quiere que neutralices las cuatro runas de coacción. Para ello tendrás que derrotar al sobrestante Durval, al sobrestante Korgan, al sobrestante Lochli y al sobrestante Brunon."}}
D[12094] = {"Poder latente",{"Carga el Fragmento de Gavrock en la primera piedra antigua, la segunda piedra antigua y la tercera piedra antigua, después regresa con Gavrock en las Ruinas de Tethys."}}
D[12095] = {"A Caída del Dragón",{"Habla con Rokhan en Caída del Dragón en el Cementerio de Dragones."}}
D[12096] = {"Devuelve la fuerza a los ancestros",{"Utiliza la corteza de los caminantes para devolver la fuerza a 3 ancestros Lothalor y vuelve con el celador de la tierra Grife en Martillo de Agmar."}}
D[12097] = {"Sarathstra, Plaga del norte",{"Habla con Rokhan para atraer a la vermis de escarcha Sarathstra.","","Mata a Sarathstra y lleva el corazón congelado de Sarathstra al capitán Gort en Martillo de Agmar."}}
D[12098] = {"Busca por el Poblado Indu'le",{"Busca al comandante de las fuerzas de cazadores de magos en el Poblado Indu'le y en el Lago Indu'le."}}
D[12099] = {"Por fin libres",{"Utiliza el romperrunas de Gavrock para liberar a 4 gigantes con runas y luego vuelve junto a Gavrock en las Ruinas de Tethys."}}
D[12100] = {"Contener la putrefacción",{"Soar Furia de Halcón en Martillo de Agmar en el Cementerio de Dragones quiere que mates a 15 ejemplares de fauna infectada y recuperes un órgano resistente a la putrefacción."}}
D[12101] = {"El buen doctor...",{"Entrega el órgano resistente a la putrefacción al doctor Sintar Malefious en Martillo de Agmar."}}
D[12102] = {"En busca de la lila de color rubí",{"El doctor Sintar Malefious en Martillo de Agmar en el Cementerio de Dragones quiere que consigas una lila de color rubí."}}
D[12104] = {"Regresa junto a Soar",{"Entrega la vacuna de Sintar a Soar Furia de Halcón en Martillo de Agmar."}}
D[12105] = {"Descenso a la oscuridad",{"Llévale el diario de Mikhail al teniente Dumont en el Refugio Pino Ámbar."}}
D[12106] = {"Busca por el Poblado Indu'le",{"Busca al comandante de las fuerzas de cazadores de magos en el Poblado Indu'le y en el Lago Indu'le."}}
D[12107] = {"El final de la línea",{"Utiliza el talismán de control de foco de línea Ley para obtener información del foco de línea Ley bajo el Lago Indu'le. Después, dirígete al este hasta el Santuario de Dragones Azur cerca del sur central del Cementerio de Dragones y observa lo que está ocurriendo desde el extremo oeste.","","Luego, vuelve junto a la imagen de la archimaga Modera en Reposo Estelar."}}
D[12108] = {"DEPRECATED",{"Llévale la nota de Mikhail al Cartógrafo Tobias en el Refugio Pino Ámbar."}}
D[12109] = {"Informa a Gryan Mantorrecio... otra vez",{"Habla con el capitán Gryan Mantorrecio en el Campamento de la Brigada de los Páramos de Poniente."}}
D[12110] = {"El final de la línea",{"Utiliza el talismán de control de foco de línea Ley para obtener información del foco de línea Ley bajo el Lago Indu'le. Después, dirígete al este hasta el Santuario de Dragones Azur cerca del sur central del Cementerio de Dragones y observa lo que está ocurriendo desde el extremo oeste.","","Luego, vuelve junto a la imagen del archimago Aethas Atracasol en Martillo de Agmar."}}
D[12111] = {"Donde vagan las cosas salvajes",{"Soar Furia de Halcón en Martillo de Agmar en el Cementerio de Dragones quiere que uses el paquete de vacunas para vacunar a 5 alces de avalancha y a 5 pardos árticos."}}
D[12112] = {"Negociaciones difíciles",{"Encuentra a Zort en el centro del Vicio de Cristal al noreste del Puesto Boquilla Oxidada."}}
D[12113] = {"Encantado de carnecerte",{"Harkor en el Campamento de Harkor quiere que consigas 10 trozos de carne fibrosa de huargo de los merodeadores aúllaocaso y 10 filetes de cornopala de los pastadores pezuña larga."}}
D[12114] = {"Terapia",{"Harkor en el Campamento de Harkor quiere que mates a 10 protectores Drakkari y a 10 oráculos Drakkari fuera de las Ruinas de Drakil'jin."}}
D[12115] = {"Koltira y el idioma de la muerte",{"Llévale el escrito encuadernado en carne a Koltira Tejemuerte."}}
D[12116] = {"Requiere agallas…",{"Kraz en Campamento de Harkor quiere que entres en las Ruinas de Drakil'jin y recojas 5 vasos canopes Drakkari."}}
D[12117] = {"Viaja hasta el Puerto Moa'ki",{"Viaja hasta el Puerto Moa'ki en el Cementerio de Dragones y habla con el ancestro Ko'nani."}}
D[12118] = {"Viaja hasta el Puerto Moa'ki",{"Viaja hasta el Puerto Moa'ki en el Cementerio de Dragones y habla con el ancestro Ko'nani."}}
D[12119] = {"Conseguir una audiencia",{"Entrega tu carta de presentación para el Templo del Reposo del Dragón a Tariolstrasz en el Templo del Reposo del Dragón."}}
D[12120] = {"La marra de Drak'aguul",{"Kraz en el Campamento de Harkor quiere que mates a Drak'aguul a las afueras de las Ruinas de Drakil'jin y vuelvas con la marra de Drakil'jin."}}
D[12121] = {"Te veo al otro lado",{"Kraz en Campamento de Harkor quiere que uses la marra de Drakil'jin en los gongs a las afueras de las Ruinas de Drakil'jin. Cuando te hayan matado, deberás entrar a las ruinas y hablar con el espíritu de Gan'jo mientras estés muerto."}}
D[12122] = {"Conseguir una audiencia",{"Entrega tu carta de presentación para el Templo del Reposo del Dragón a Tariolstrasz en el Templo del Reposo del Dragón."}}
D[12123] = {"Informar a la reina",{"Entrega tu carta de presentación para el Templo del Reposo del Dragón a Alexstrasza la Protectora en el Templo del Reposo del Dragón."}}
D[12124] = {"Informar a la reina",{"Entrega tu carta de presentación para el Templo del Reposo del Dragón a Alexstrasza la Protectora en el Templo del Reposo del Dragón."}}
D[12125] = {"Al servicio de la sangre",{"Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema de sangre sobre un habitante de Indu'le trastornado y vuelvas con una gema de sangre llena."}}
D[12126] = {"Al servicio de lo profano",{"Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema profana sobre el duque Vallenhal y vuelvas con una gema profana llena."}}
D[12127] = {"Al servicio de la escarcha",{"Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que uses la gema de escarcha con aparecidos de hielo y vuelvas con la gema de escarcha llena."}}
D[12128] = {"Visita a Raegar",{"Habla con Raegar Rompecejas en el Altozano del Prospector."}}
D[12129] = {"El plan perfecto",{"Llévale el plano de gólem de guerra completo a Raegar Rompecejas en Altozano del Prospector."}}
D[12130] = {"¿Por qué fabricarlo cuando puedes apropiártelo?",{"Llévale 8 piezas de gólem de guerra a Raegar Rompecejas en el Altozano del Prospector."}}
D[12131] = {"Tenemos el poder...",{"Llévale la célula de energía de Durar y la célula de energía de Kathorn a Raegar Rompecejas en el Altozano del Prospector."}}
D[12132] = {"El poder para destruir",{"Koltira Tejemuerte en Martillo de Agmar en el Cementerio de Dragones quiere que entres en el mundo de las sombras y derrotes a 6 torturadores enigmáticos.","","Habla con Koltira Tejemuerte si necesitas volver a entrar en el mundo de las sombras."}}
D[12133] = {"Aplasta la calabaza",{"Dale el símbolo sagrado chamuscado a la supervisora de huérfanos disfrazada."}}
D[12134] = {"La caza de Sasha",{"Sasha quiere que mates a 12 cazadores del solsticio en el Poblado Solsticio."}}
D[12135] = {"\"¡Dejad que el fuego se acerque!\"",{"La supervisora de huérfanos disfrazada quiere que ayudes a apagar todos los incendios de la ciudad que provoque el Jinete decapitado. Cuando termines, vuelve a hablar con ella."}}
D[12136] = {"El escrito traducido",{"Entrega el escrito encuadernado en carne traducido al capitán Gort en Martillo de Agmar."}}
D[12137] = {"Relá'hatee, coleega",{"Gan'jo quiere que recojas la nieve de sueño eterno de su cofre en las Ruinas de Drakil'jin.","","Deberás usar la nieve sobre los antiguos espíritus Drakkari allí y llevar sus partículas de espíritus Drakkari a Kraz en Campamento de Harkor."}}
D[12138] = {"... O quizás no",{"Carga tu gólem de guerra con la energía de 10 avizores de relámpagos y regresa junto a Raegar Rompecejas en Altozano del Prospector."}}
D[12139] = {"\"¡Dejad que el fuego se acerque!\"",{"La supervisora de huérfanos enmascarada quiere que ayudes a apagar todos los incendios en las ciudades. Cuando estén apagados, vuelve a hablar con ella."}}
D[12140] = {"¡Viva Roanauk!",{"Busca a Roanauk Bruma de Hielo en Martillo de Agmar e iníciale como miembro y líder de las fuerzas de la Horda.","","Vuelve junto al señor supremo Agmar con el juramento de sangre de la Horda cuando completes esta misión."}}
D[12141] = {"Una misión diplomática",{"Habla con Karuk en el Litoral Tralladón, al suroeste de la Fortaleza Denuedo."}}
D[12142] = {"Control de plagas",{"Duane en el Frente de la Séptima Legión quiere que mates a 10 snóbolds Llano Nevado y a 3 magnatauros del Cementerio de Dragones en los campos de magnatauros que rodean Reposo del Dragón."}}
D[12143] = {"Persecución por el cañón",{"Duane quiere que persigas a los snóbolds por el cañón al noreste del Frente de la Séptima Legión y que acabes con su líder."}}
D[12144] = {"Control de plagas",{"Kontokanis en Caída del Dragón quiere que mates a 10 discípulos Llano Nevado y a 3 magnatauros alfa en los campos de magnatauros que rodean Reposo del Dragón."}}
D[12145] = {"Persecución por el cañón",{"Kontokanis quiere que persigas a los snóbolds por el cañón al sur de Caída del Dragón y que acabes con su líder."}}
D[12146] = {"Implicaciones inquietantes",{"Lleva el cuerno de batalla blasonado hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en evaluar el nivel potencial de amenaza."}}
D[12147] = {"Implicaciones inquietantes",{"Lleva el cuerno de batalla blasonado hasta Reposo del Dragón y busca a alguien que pudiera estar interesado en evaluar el nivel potencial de amenaza."}}
D[12148] = {"Único",{"Encuentra y mata a Hiendehuesos cerca del cañón al noroeste del Santuario de Dragones Azur. Llévale cualquier prueba que encuentres a Aurastrasza en el Templo del Reposo del Dragón."}}
D[12149] = {"Un poderoso magnatauro",{"Da caza y muerte a Sangría, Trizahielo y a Dracogor al este de Reposo del Dragón.","","Sangría se encuentra en el rincón sureste del Baldío del Dragón, al norte del Santuario de Dragones Esmeralda. Trizahielo patrulla el extremo norte de El Espejo del Alba. Dracogor vaga por la parte inferior de los acantilados al oeste del Santuario de Dragones Bronce.","","Vuelve junto a Aurastrasza en Reposo del Dragón cuando hayas matado a los magnatauros."}}
D[12150] = {"Un maestro de runas solitario",{"Encuentra a Dregmar Runarrama cerca de su cueva en la senda que dirige a los acantilados que dan a El Espejo del Alba. Desafíale y revela el nombre del líder magnatauro utilizando los medios necesarios. Vuelve junto a Aurastrasza en Reposo del Dragón cuando hayas obtenido la información."}}
D[12151] = {"Un Señor de la Guerra atroz",{"Viaja hasta el anillo de antorchas al sur del Santuario de Dragones Azur y sopla el cuerno de batalla blasonado. Derrota a Grom'thar el Portador del Trueno y llévale su cabeza a Aurastrasza en Reposo del Dragón."}}
D[12152] = {"El final de Jin'arrak",{"Kraz en Campamento de Harkor quiere que recojas la ofrenda Drakkari sacra de las Ruinas de Drakil'jin y eches el polvo de espíritus Drakkari sobre ella. Debes usar la ofrenda Drakkari imbuida con los gongs que hay a las afueras de las Ruinas de Drakil'jin."}}
D[12153] = {"El señor feudal férreo y su Yunque",{"Utilizando las facultades de tu gólem de guerra, derrota al señor feudal férreo Martillo Furioso y luego vuelve junto a Raegar Rompecejas en Altozano del Prospector."}}
D[12154] = {"Apagón",{"Utiliza los explosivos de Raegar para destruir la batería de runas de Dun Argol y luego ve a informar a Raegar Rompecejas en Altozano del Prospector."}}
D[12155] = {"Aplasta la calabaza",{"Dale el símbolo sagrado chamuscado a la supervisora de huérfanos enmascarada."}}
D[12156] = {"DEPRECATED",{"Escolta al enviado de la Alianza hasta la ciudad de Arroyoplata. Informa al teniente Dumont en Refugio Pino Ámbar cuando hayas completado esta tarea."}}
D[12157] = {"El mensajero perdido",{"Habla con el mensajero Lanson en Reposo Estelar, en el Cementerio de Dragones."}}
D[12158] = {"Mina Piedrahueca",{"Busca pistas dentro de la Mina Piedrahueca al noroeste del Campamento de la Brigada de los Páramos de Poniente."}}
D[12159] = {"Almas sin descanso",{"Petrov en Mina Piedrahueca quiere que uses la linterna de minero para quemar los cadáveres de 8 mineros Piedrahueca."}}
D[12160] = {"Un nombre del pasado",{"Vuelve con el capitán Gryan Mantorrecio en el Campamento de la Brigada de los Páramos de Poniente."}}
