D[12165] = {"Un plan intrigante",{"Llévale el plano gólem de guerra completo al prospector Rokar en el Campamento Oneqwah."}}
D[12166] = {"El fuego líquido de Elune",{"La celadora Jodi Canción de Luna en Reposo Estelar te ha pedido que uses el fuego líquido de Elune para limpiar los cadáveres de 6 alces contagiados y 6 pardos rabiosos."}}
D[12167] = {"Mata a los cultores",{"Reúne 5 trajes funcionales de cultor para la celadora Jodi Canción de Luna en Reposo Estelar."}}
D[12168] = {"El Favor de Zangus",{"Entrega el Favor de Zangus a la celadora Jodi Canción de Luna en Reposo Estelar."}}
D[12169] = {"El sumo cultor",{"La celadora Jodi Canción de Luna en Reposo Estelar te ha pedido que mates al sumo cultor Zangus."}}
D[12170] = {"Pelea en Río Negro",{"El capitán de asaltantes Kronn quiere que mates a 10 unidades o jugadores de la Alianza en el Aserradero Río Negro."}}
D[12171] = {"De traidores y traición",{"Enséñale la misiva de la Alianza a Palena Nube de Plata en Reposo Estelar."}}
D[12172] = {"Armonización hacia Dalaran",{"La imagen de la archimaga Modera en Reposo Estelar te ha pedido que te armonices con las líneas Ley de Rasganorte."}}
D[12173] = {"Armonización hacia Dalaran",{"La imagen del archimago Aethas Atracasol en Martillo de Agmar te ha pedido que te armonices con las líneas Ley de Rasganorte."}}
D[12174] = {"Alto comandante Halford Aterravermis",{"Entrega la misiva de la Alianza al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde al este del Cementerio de Dragones."}}
D[12175] = {"Pieles de huargo gris",{"Jun'ik, el comerciante de pellejos en Bastión de la Conquista quiere que le consigas 3 pieles de huargo gris de los cazadores brumagris que hay en los bosques al norte."}}
D[12176] = {"Un pequeño cambio",{"El comerciante de pellejos Jun'ik quiere que le lleves 6 pellejos de oso pardo."}}
D[12177] = {"La mentirijilla de Jun'ik",{"Llévale 1 trozo de carbón y 5 paquetes de harina simple al comerciante de pellejos Jun'ik en Bastión de la Conquista en las Colinas Pardas."}}
D[12178] = {"Entrega a Krenna",{"Lleva el Fardo de Pieles a Krenna en Bastión de la Conquista."}}
D[12179] = {"Specialization 1 [PH]",{"LOG: Complete this quest for Specialization 1."}}
D[12180] = {"Los prospectores cautivos",{"Libera al prospector Gann, al prospector Torgan y a la prospectora Varana, y luego vuelve junto al montaraz Kilian en Altozano del Prospector."}}
D[12181] = {"Ponle un nombre",{"Enséñale el espécimen de añublo a Tobias Sarkhoff en Nuevo Agamand."}}
D[12182] = {"¡A Rencor Venenoso!",{"Entrega el espécimen de añublo al jefe pesteador Middleton en Rencor Venenoso, al este del Cementerio de Dragones."}}
D[12183] = {"Dando el pego",{"Llévale el uniforme de sobrestante al montaraz Kilian en Altozano del Prospector."}}
D[12184] = {"Cultivando una imagen",{"Utiliza la cámara de Kilian para grabar las imágenes de 8 enanos férreos en Dun Argol y luego vuelve junto al montaraz Kilian en Altozano del Prospector."}}
