D[12191] = {"¡Traga y tira!",{"Utiliza la jarra de degustación de la Fiesta de la cerveza de obsequio para golpear a la G.U.A.O. 5 veces, y luego ve a hablar con Bizzle Birlotutti."}}
D[12192] = {"Ese día que estaba borracho...",{"Habla con Bizzle Birlotutti en el campamento de la Fiesta de la cerveza."}}
D[12193] = {"Oye, ¿no habrá por casualidad un souvenir este año?",{"Entrega el vale de jarra de la Fiesta de la cerveza a Belbi Tiratrastos en el campamento de la Fiesta de la cerveza."}}
D[12194] = {"Oye, ¿no habrá por casualidad un souvenir este año?",{"Entrega el vale de jarra de la Fiesta de la cerveza a Blix Chirimbolo en la parte trasera del campamento de la Fiesta de la cerveza."}}
D[12195] = {"El \"invitado\" inesperado",{"Llévale 5 cuernos de venado adulto a Tormak el Cicatrices en el Campamento Oneqwah."}}
D[12196] = {"Desde cero",{"Llévale 8 trozos de gólem de guerra al prospector Rokar en el Campamento Oneqwah."}}
D[12197] = {"Tenemos el poder...",{"Llévale la célula de energía de Durar y la célula de energía de Kathorn al Prospector Rokar en el Campamento Oneqwah."}}
D[12198] = {"... O quizás no",{"Carga tu gólem de guerra con la energía de 10 avizores de relámpagos y regresa con el Prospector Rokar en el Campamento Oneqwah."}}
D[12199] = {"Acaba con el señor feudal férreo",{"Usando las habilidades de tu gólem de guerra derrota al señor feudal férreo Martillo Furioso y después habla con Tormak el Cicatrices en el Campamento Oneqwah."}}
D[12200] = {"Lágrimas de dragón esmeralda",{"El jefe pesteador Middleton en Rencor Venenoso en el Cementerio de Dragones quiere que recojas 8 lágrimas de dragón esmeralda."}}
D[12201] = {"La sombra del Sobrestante",{"Llévale un uniforme de sobrestante al Explorador Vor'takh en el Campamento Oneqwah."}}
D[12202] = {"Cultivando una imagen",{"Usa la Cámara de Rokar para conseguir las imágenes de 8 enanos férreos en Dun Argol, después regresa con el Explorador Vor'takh en el Campamento Oneqwah."}}
D[12203] = {"Las órdenes de Loken",{"Disfrázate de sobrestante Runaférrea, intercepta el mensaje de Loken y después informa al Explorador Vor'takh en el Campamento Oneqwah."}}
D[12204] = {"En nombre de Loken",{"Pregunta a Hugh Copa y a Gavrock acerca de Loken, después informa de tus descubrimientos al Explorador Vor'takh en el Campamento Oneqwah."}}
D[12205] = {"Se busca: El Embate Escarlata",{"Mata a 20 miembros de El Embate Escarlata e informa al sumo ejecutor Wroth en Rencor Venenoso."}}
D[12206] = {"Una extremaunción con añublo",{"La boticaria Vicky Levine en Rencor Venenoso te ha pedido que pruebes el frasco de añublo sobre un prisionero de El Embate Escarlata."}}
D[12207] = {"La caída de Vordrassil",{"La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil o a las Lágrimas de Vordrassil y consigas 6 muestras de babosa de los mocos entrópicos."}}
D[12208] = {"La caza de trols",{"El sargento Thurkin quiere que hables con Samir en el Manantial de Granito."}}
D[12209] = {"Saqueo de material",{"El intendente Bartlett en Rencor Venenoso te ha pedido que robes 8 armaduras y 8 armas de El Embate Escarlata."}}
D[12210] = {"¡Temporada de trols!",{"El teniente Dumont en el Refugio Pino Ámbar quiere que hables con Samir en el Manantial de Granito."}}
D[12211] = {"¡No dejes que se levanten!",{"La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses su contenedor de ratas para no dejar ni rastro de 15 miembros de El Embate Escarlata en Nueva Vega del Amparo"}}
D[12212] = {"Reabasteciendo el almacén",{"El maestro trabajador forestal Anderhol del Refugio Pino Ámbar quiere que mates a venados cornaaltas y que consigas 8 trozos de venado suculento."}}
D[12213] = {"La oscuridad interior",{"La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil y a las Lágrimas de Vordrassil y que uses el Orbe de geomántico en las profundidades de la superficie."}}
D[12214] = {"Monturas frescas",{"Hansel Bauer en Rencor Venenoso te ha pedido que robes 3 caballos de guerra de El Embate Escarlata y se los lleves. Para ello, entrégale las riendas."}}
D[12215] = {"¡O ellos, o nosotros!",{"Anderhol en el Refugio Pino Ámbar quiere que encuentres y mates a 6 cazadores Brumacana en Las Colinas Pardas."}}
D[12216] = {"¡Cógeles el trasero!",{"Anderhol en el Refugio Pino Ámbar quiere que recojas 8 costillares de oso de los osos pardos de Colinas Pardas."}}
D[12217] = {"Ojos de águila",{"Anderhol en el Refugio Pino Ámbar quiere que mates a 5 águilas imperiales y que luego vuelvas a informarle."}}
D[12218] = {"Transmite la buena nueva",{"El jefe pesteador Middleton en Rencor Venenoso en el Cementerio de Dragones quiere que utilices la bomba de añublo del propagador del añublo de los Renegados para acabar con 30 muertos hambrientos a las afueras de Los Campos de Carroña."}}
D[12219] = {"El árbol del mundo fallido",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil o las Lágrimas de Vordrassil y que le traigas 6 muestras de babosas de mocos entrópicos."}}
D[12220] = {"Una influencia oscura",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a la Extremidad de Vordrassil, al Corazón de Vordrassil y a las Lágrimas de Vordrassil y que uses el orbe de geomántico en las profundidades bajo la superficie."}}
D[12221] = {"El añublo de los Renegados",{"Entrega el añublo de los Renegados al doctor Sintar Malefious en Martillo de Agmar."}}
D[12222] = {"Secretos de las vinculadoras de llamas",{"Llévale 3 talismanes imbuidos en llamas al trabajador forestal Draco en el Refugio Pino Ámbar."}}
D[12223] = {"Reduciendo su número",{"Mata a 12 huscarles Desuelladragones y habla con el trabajador forestal Draco en el Refugio Pino Ámbar."}}
D[12224] = {"¡La Vanguardia Kor'kron!",{"Preséntate ante Colmillosauro el Joven en la Vanguardia Kor'kron."}}
D[12225] = {"Mmm... ¡Grano ámbar!",{"Habla con el maestro trabajador forestal Anderhol en el Refugio Pino Ámbar."}}
