D[12234] = {"Tengo que saber",{"La maestra de espías Lamento en Rencor Venenoso te ha pedido que robes las órdenes diarias de El Embate Escarlata: Abadía, las órdenes diarias de El Embate Escarlata: Barracones y las órdenes diarias de El Embate Escarlata: Playa."}}
D[12235] = {"Naxxramas y la caída de Hibergarde",{"Habla con el comandante de grifos Urik en la estación de grifos en la Fortaleza de Hibergarde."}}
D[12236] = {"Ursoc, el dios oso",{"La Vidente del viento Cuerno Gris en Bastión de la Conquista quiere que encuentres a Tur Patafuria cerca de la guarida de Ursoc y que derrotes a Ursoc con su ayuda. Cuando hayas logrado eso, usa las Cenizas purificadas de Vordrassil con el cadáver de Ursoc."}}
D[12237] = {"Vuelo del defensor de Hibergarde",{"Rescata a 10 habitantes de Hibergarde indefensos y vuelve con el comandante de grifos Urik a la Fortaleza de Hibergarde."}}
D[12238] = {"Limpiar Drak'Tharon",{"Drakuru quiere que uses el elixir de Drakuru en su pedestal dentro de Drak'Tharon. Para usar el elixir de Drakuru ahí vas a necesitar 5 mojos de resistencia."}}
D[12239] = {"La espía en Nueva Vega del Amparo",{"Entrega las órdenes diarias de El Embate Escarlata a la agente Skully en Nueva Vega del Amparo."}}
D[12240] = {"Medios para un fin",{"La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses las termitas de la familia Levine para sacar al supervisor Kaleiki y matarlo."}}
D[12241] = {"Destruir el árbol joven",{"La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que cojas la Antorcha verdeante y que la uses para quemar el árbol joven de Vordrassil. Dale las Cenizas de Vordrassil a la Vidente del viento Cuerno Gris."}}
D[12242] = {"Las semillas de Vordrassil",{"La Vidente del viento Cuerno Gris en el Bastión de la Conquista quiere que vayas a Fauceparda y consigas 8 semillas de Vordrassil."}}
D[12243] = {"Fuego sobre las aguas",{"La boticaria Vicky Levine en Rencor Venenoso te ha pedido que uses el agua de fuego de la boticaria para prender fuego a las velas del Locura del Pecador.","","Mientras los marineros de cubierta estén ocupados intentando apagar el fuego, dirígete a la cubierta inferior y recupera las rutas del capitán Shely, en posesión del capitán."}}
D[12244] = {"Reparación de trituradoras",{"Synipus del Aserradero Cielo Azul quiere que le traigas de vuelta 3 trituradoras averiadas."}}
D[12245] = {"Ninguna piedad con los cautivos",{"La maestra de espías Lamento te ha pedido que mates al guardia de la muerte Schneider, al escribano jefe Kinnedius, al ingeniero Burke y al canciller Amai.","","Cuando hayas cumplido esta tarea, informa de tu éxito al sumo ejecutor Wroth en Rencor Venenoso."}}
D[12246] = {"Una posible relación",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que consigas 8 unidades de sangre de fúrbolg enloquecido de los fúrbolgs en el Santuario Colmillo Iracundo y en el Santuario Sangre de Corazón."}}
D[12247] = {"Hijos de Ursoc",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que hables con Orsonn en el Santuario Colmillo Iracundo y con Kodian en el Santuario Sangre de Corazón."}}
D[12248] = {"El árbol joven de Vordrassil",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que cojas la Antorcha verdeante y que la uses para quemar el árbol joven de Vordrassil. Llévale las cenizas de Vordrassil a la Hierofante Thayreen."}}
D[12249] = {"Ursoc, el dios oso",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que encuentres a Tur Patafuria cerca de la guarida de Ursoc y derrotes a Ursoc con su ayuda. Cuando hayas logrado esto, usa las Cenizas purificadas de Vordrassil en el cadáver de Ursoc."}}
D[12250] = {"Las semillas de Vordrassil",{"La Hierofante Thayreen en el Refugio Pino Ámbar quiere que vayas a Fauceparda y consigas 8 semillas de Vordrassil."}}
D[12251] = {"Regresa junto al Alto Comandante",{"Habla con el alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones."}}
D[12252] = {"Tortura al torturador",{"El sumo ejecutor Wroth en Rencor Venenoso quiere que uses el hierro de marcar 5 veces sobre el torturador Alphonse para sonsacarle la información. Después, mátalo."}}
D[12253] = {"Rescátalos de Plaza de la Ciudad",{"El alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que rescates a 6 habitantes de Hibergarde atrapados."}}
D[12254] = {"Sin una oración",{"La agente Skully en Nueva Vega del Amparo te ha pedido que consigas el libro de oración del Obispo Calle."}}
D[12255] = {"El señor feudal de Runavold",{"Usa a Clamallamas para derrotar al señor feudal Torvald Eriksson e informa al trabajador forestal Draco en el Refugio Pino Ámbar."}}
D[12256] = {"Los secretos de las vinculadoras de llamas",{"Llévale 3 talismanes imbuidos en llamas al Sargento Nazgrim en el Bastión de la Conquista."}}
D[12257] = {"Una demostración de fuerza",{"Mata a 12 huscarles Desuelladragones y habla con el Sargento Nazgrim en el Bastión de la Conquista."}}
D[12258] = {"El destino de los muertos",{"La comandante Lynore Ventostryke en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que mates a 15 geists vengativos."}}
D[12259] = {"El señor feudal de Runavold",{"Usa a Clamallamas para derrotar al señor feudal Torvald Eriksson e informa al Sargento Nazgrim en el Bastión de la Conquista."}}
D[12260] = {"La máscara perfecta",{"La agente Skully en Nueva Vega del Amparo te ha pedido que robes la imagen de un sacerdote cuervo del Embate. Devuélvele el espejo mágico de alma en pena cuando hayas terminado."}}
D[12261] = {"Sin escapatoria",{"Coloca un resguardo destructivo en la senda de salida del Santuario de Dragones Obsidiana donde la carretera empieza a dar paso a la nieve. Protege el resguardo hasta que se cargue por completo y luego vuelve junto a Serinar."}}
D[12262] = {"Nadie para salvarte",{"Mata a 6 necrólitos de las profundidades ardientes y a 10 esqueletos en el exterior del Santuario de Dragones Obsidiana. Vuelve junto a Serinar cuando hayas completado la tarea."}}
D[12263] = {"La mejor de las intenciones",{"Espera a Serinar para que te administre el disfraz de un necrólito de las profundidades ardientes y luego entra hasta la parte posterior de las Fauces de Neltharion para averiguar lo que el Culto de los Malditos está haciendo allí. Vuelve junto a Serinar con los detalles de sus intenciones."}}
D[12264] = {"La matanza de los Malditos",{"Mata a 3 nigromantes de las profundidades ardientes, 6 ensamblajes en llamas y 6 geists en llamas en las Fauces de Neltharion, y luego vuelve junto a Serinar."}}
D[12265] = {"Profanando a los profanadores",{"Encuentra y destruye 8 runas nigrománticas que se han dibujado en el suelo dentro de las Fauces de Neltharion. Vuelve junto a Serinar cuando completes esta misión."}}
D[12266] = {"Historias de destrucción",{"Vuelve a Reposo del Dragón e informa a Nalice de que has completado la misión de Serinar."}}
D[12267] = {"La llama de Neltharion",{"Utiliza la llama de Neltharion para apagar la zona de invocación de la parte posterior de las Fauces de Neltharion. Cuando llames la atención de Rothin el Putrefacto, mátalo y vuelve junto a Serinar delante de la cueva."}}
D[12268] = {"Piezas y partes",{"Pipthchiflo en el Aserradero Cielo Azul quiere que consigas 4 engranajes con muescas, 3 ruedas dentadas y 2 resortes de alta tensión."}}
D[12269] = {"No en nuestra mina",{"El alto señor Leoric Von Zeldig en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que recuperes 10 tarjetas de minero de Hibergarde."}}
D[12270] = {"Machaca a la Alianza",{"Grekk en el Aserradero Cielo Azul quiere que consigas 3 trituradoras y se las lleves."}}
D[12271] = {"La vara de coacción",{"Entrega la vara de torturador al sumo ejecutor Wroth en Rencor Venenoso."}}
D[12272] = {"La mena sangrante",{"El ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que consigas 10 muestras de mena extraña de la Mina de Hibergarde."}}
D[12273] = {"La acusación",{"El sumo ejecutor Wroth en Rencor Venenoso te ha encargado la tarea de usar la vara de coacción con el comandante Jordan, el cañonero mayor Zierhut, el herrero Buenhombre y el maestro de establos Mercer.","","Cuando hayas usado la vara con ellos, mátalos para coaccionarlos a hacer de sus últimas palabras una acusación contra El Embate Escarlata."}}
D[12274] = {"Caída en desgracia",{"La agente Skully en Nueva Vega del Amparo te ha pedido que toques la campana de la abadía y luego vayas a hablar con el sumo abad para sonsacarle información."}}
D[12275] = {"El Demognomo",{"Habla con el ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones."}}
D[12276] = {"La búsqueda de Slinkin",{"Encuentra a Slinkin el Demognomo en la Mina de Hibergarde. Utiliza el buscabot de Quartoflash si necesitas ayuda para encontrar la mina."}}
D[12277] = {"No dejes nada a la suerte",{"Recupera una bomba de la Mina de Hibergarde y úsala para volar por los aires el eje de la Mina de Hibergarde alta y el eje de la Mina de Hibergarde baja. Vuelve a informar al ingeniero de asedio Quartoflash en la Fortaleza de Hibergarde en el Cementerio de Dragones cuando hayas completado esta misión."}}
D[12278] = {"Club de la Cerveza del Mes",{"Llévale el formulario de socio del Club de la \"Cerveza del Mes\" a Larkin Cebatruenos en la Taberna Roca de Fuego en Forjaz."}}
D[12279] = {"Hambre de osa",{"Llévale 6 salmones del norte a Hugh Copa en el Puesto de Venta Madera Roja."}}
D[12280] = {"Haciendo arreglos",{"Lurz en el Aserradero Cielo Azul quiere que consigas 4 engranajes con muescas, 3 ruedas dentadas y 2 resortes de alta tensión."}}
D[12281] = {"Comprender la máquina de guerra de la Plaga",{"Entrega el paquete de Quartoflash al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde."}}
D[12282] = {"Huellas en el pasado",{"Zelig el Visionario en la Fortaleza de Hibergarde del Cementerio de Dragones quiere que recuperes su orbe de visión."}}
D[12283] = {"La verdad saldrá",{"La agente Skully te ha pedido que consigas el diario de la alta general Abbendis y se lo lleves al sumo ejecutor Wroth en Rencor Venenoso."}}
D[12284] = {"Que se queden donde están",{"El comandante Bargok quiere que mates a 15 unidades o jugadores de la Alianza en el Aserradero Cielo Azul."}}
D[12285] = {"Hacer a los demás",{"El sumo ejecutor Wroth te ha ordenado que vuelvas con la cabeza de la Alta General."}}
