D[12290] = {"El elixir de hierba tiniebla",{"Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que recojas 5 muestras de hierba tiniebla de los Altos de Eldritch."}}
D[12291] = {"La historia olvidada",{"Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que escuches las historias de un campesino olvidado, un fusilero olvidado, un caballero olvidado y un lacayo olvidado."}}
D[12292] = {"Apoyo local",{"El teniente Dumont en el Refugio Pino Ámbar quiere que vayas al Puesto de Venta de Siempreverde y consigas el cofre de cedro."}}
D[12293] = {"Cierra el trato",{"Llévale el cofre de cedro a Ivan en el Puesto de la Alameda."}}
D[12294] = {"Un pacto provisional",{"Vuelve junto al teniente Dumont en el Refugio Pino Ámbar."}}
D[12295] = {"Un ejercicio de diplomacia",{"Habla con el enviado Ducal en Arroyoplata."}}
D[12296] = {"A vida o muerte",{"Rheanna en el Aserradero Cielo Azul quiere que uses el vendaje de renovación en 10 soldados de infantería de los Páramos de Poniente heridos."}}
D[12297] = {"De traidores y traición",{"El capitán Adams te ha pedido que le enseñes la misiva de la Alianza a Greer Martillo de Mena en la Fortaleza de la Guardia Oeste."}}
D[12298] = {"Alto comandante Halford Aterravermis",{"Entrega la misiva de la Alianza al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde al este del Cementerio de Dragones."}}
D[12299] = {"La hospitalidad norteña",{"Sergei en Arroyoplata quiere que mates a 8 maleantes del Bastión de la Conquista."}}
D[12300] = {"Prueba de valor",{"Encuentra al sargento Cascahueso al oeste de Arroyoplata y supera la prueba de valor."}}
D[12301] = {"La verdad nos hará libres",{"Orik Corazón Veraz en Tramo del Alba en el Cementerio de Dragones quiere que uses el orbe cristalino de Orik en las ruinas de La Orilla Olvidada para redimir a los Olvidados."}}
D[12302] = {"Una advertencia",{"Ve al extremo noroeste de Arroyoplata."}}
D[12303] = {"Financiar la guerra",{"El intendente Bartlett de Rencor Venenoso te ha pedido que recuperes 6 tesoros olvidados."}}
D[12304] = {"Propiedad delante de la playa",{"El perito Hansen, justo en el norte de La Orilla Olvidada, te ha pedido que mates a 20 fantasmas olvidados."}}
D[12305] = {"Pensamientos de despedida",{"Vuelve junto a Zelig el Visionario en la Fortaleza de Hibergarde en el Cementerio de Dragones."}}
