D[12309] = {"¡Encuentra a Durkon!",{"Busca al hidalgo Durkon en la Cripta de Hibergarde, Cementerio de Dragones."}}
D[12310] = {"Una reacción inmediata",{"El teniente Dumont quiere que vayas al Puesto Fronterizo del Bosque y mates a Vladek y a 7 cazadores de Arroyoplata."}}
