D[12451] = {"Hacia el Campamento Oneqwah",{"Habla con el Explorador Vor'takh en el Campamento Oneqwah."}}
D[12452] = {"zzOLD El destino del Santuario de Dragones Rubí",{"Lleva el broche de rubíes de Dahlia a Ceristrasz e infórmale sobre su destino."}}
D[12453] = {"Ojos en el cielo",{"La vidente del viento Cuerno Gris quiere que uses la Pluma de plata con 6 águilas imperiales de las Colinas Pardas."}}
D[12454] = {"El ciclo de la vida",{"Nishera la Jardinera en el Santuario de Dragones Esmeralda te ha pedido que mates a 5 Garfacielos esmeralda."}}
D[12455] = {"Esparcidos por los aires",{"Ambo Calderilla en el Mausoleo de Hibergarde en el Cementerio de Dragones quiere que recuperes 8 municiones de Hibergarde."}}
D[12456] = {"La pluma de Alystros",{"Nishera la Jardinera en el Santuario de Dragones Esmeralda te ha pedido que consigas la pluma de Alystros."}}
D[12457] = {"La ametralladora y tú",{"Ambo Calderilla en el Mausoleo de Hibergarde en el Cementerio de Dragones quiere salves a 8 soldados de la Séptima Legión heridos."}}
D[12458] = {"Semillas de los azotadores",{"Lord Itharius en lo alto del Templo del Reposo del Dragón te ha pedido que vuelvas con 3 semillas de azotador."}}
D[12459] = {"El que crea también puede destruir",{"Lord Itharius en lo alto del Templo del Reposo del Dragón te ha pedido que acabes con una vermis de escarcha reanimada debilitada, con Turgid el Vil debilitado y con el sobrestante Mirada Mortal debilitado."}}
D[12460] = {"Informa en el Santuario de Dragones Rubí",{"Preséntate ante Ceristrasz en la cresta este del Santuario de Dragones Rubí al oeste de Reposo del Dragón."}}
D[12461] = {"Informa en el Santuario de Dragones Rubí",{"Preséntate ante Vargastrasz en la cresta a las afueras del Santuario de Dragones Rubí justo al este de Martillo de Agmar."}}
D[12462] = {"Partir un trozo",{"Yord Barbahielo \"el Calamidad\" en el Mausoleo de Hibergarde del Cementerio de Dragones quiere que mates al necroseñor X'avius, al necroseñor Horus y a 15 miembros de la Plaga de Naxxramas."}}
D[12463] = {"¡Debemos encontrar a Barbarrapiña!",{"Ambo Calderilla en el Mausoleo de Hibergarde en el Cementerio de Dragones quiere que encuentres a Barbarrapiña."}}
D[12464] = {"Mi eterna enemiga",{"Entrega la cabeza de la Alta General al comandante Eligor Albar en la Fortaleza de Hibergarde."}}
D[12465] = {"El diario de Barbarrapiña",{"Recupera la página 4 del diario de Barbarrapiña, la página 5 del diario de Barbarrapiña, la página 6 del diario de Barbarrapiña y la página 7 del diario de Barbarrapiña, y llévaselas a Ambo Calderilla en el Mausoleo de Hibergarde en el Cementerio de Dragones."}}
D[12466] = {"Persiguiendo a Tormenta de Hielo: El Frente de la Séptima Legión",{"Preséntate ante el comandante de la Legión Tyralion en el Frente de la Séptima Legión en el centro del Cementerio de Dragones."}}
D[12467] = {"Persiguiendo a Tormenta de Hielo: la filacteria de Thel'zan",{"Recupera la filacteria de Thel'zan de Tormenta de Hielo y llévasela al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde."}}
D[12468] = {"La tarea del Conquistador",{"Habla con el Sargento Nazgrim en el Bastión de la Conquista."}}
D[12469] = {"Devolver al remitente",{"Sigue la cresta hacia el este y entrega el paquete de explosivos a Xink en el Puesto Boquilla Oxidada en el norte del Cementerio de Dragones."}}
D[12470] = {"El misterio del Infinito",{"Cromi en lo alto del Templo del Reposo del Dragón te pide que vayas hasta el santuario de Dragones Bronce. En cuanto estés dentro, sitúa el reloj de arena de eternidad en el suelo.","","Protégelo todo lo que dure y devuélvelo a Cromi con cualquier información que hayas obtenido."}}
D[12471] = {"La crueldad de los Kvaldir",{"Habla con Karuk sobre el prisionero colmillarr capturado."}}
D[12472] = {"El momento decisivo",{"Lleva la filacteria de Thel'zan al comandante de la Legión Yorik dentro del Mausoleo de Hibergarde en el Cementerio de Dragones."}}
D[12473] = {"Un final y un principio",{"Vence a Thel'zan el Portador del Ocaso e informa al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones."}}
D[12474] = {"¡Al Bastión de Fordragón!",{"Aventúrate en el Bastión Fordragón en el Cementerio de Dragones y habla con el alto señor Bolvar Fordragón."}}
D[12475] = {"Los secretos que esconden los hombres",{"Zelig el Visionario en la Fortaleza de Hibergarde del Cementerio de Dragones quiere que encuentres el mapa del Embate y que se lo devuelvas."}}
D[12476] = {"¿El retorno de la Cruzada?",{"La comandante Lynore Ventostryke de la Fortaleza de Hibergarde en el Cementerio de Dragones quiere que mates a 20 miembros de El Embate Escarlata en el campamento del Embate."}}
D[12477] = {"El Camino de la Redención",{"Devuelve \"El Camino de la Redención\" al alto comandante Halford Aterravermis en la Fortaleza de Hibergarde en el Cementerio de Dragones."}}
D[12478] = {"La Caverna Agonía de Escarcha",{"Zelig el Visionario en la Fortaleza de Hibergarde del Cementerio de Dragones quiere que uses el orbe de visión de Zelig en el fondo de la Caverna Agonía de Escarcha. ¡Desata los secretos del pasado!"}}
