D[12511] = {"Las colinas tienen ojos",{"Preséntate ante el teniente Dumont en el refugio Pino Ámbar al oeste de las Colinas Pardas."}}
D[12512] = {"Que nadie se quede atrás",{"El Dr. Rogers, en Drak'Sotra, quiere que encuentres al cruzado Lamoof, al cruzado Jonathan y a la cruzada Josephine. Ponles la venda de cruzado y procura que vuelvan sanos y salvos junto al Dr. Rogers."}}
D[12513] = {"Bonito sombrero...",{"Don Carlos te ha retado involuntariamente a que derrotes a su yo joven en la Antigua Trabalomas. Después, llévale el sombrero de Don Carlos a Tanaris como prueba."}}
D[12514] = {"Mezclando champiñones",{"Recoge 10 hongos fungilodos y llévaselos al aojador Ubungo en El Confín Argenta."}}
D[12515] = {"Bonito sombrero...",{"Don Carlos te ha retado involuntariamente a que derrotes a su yo joven en la Antigua Trabalomas. Después, llévale el sombrero de Don Carlos a Tanaris como prueba."}}
