D[12518] = {"La baraja de Magos",{"Usa la baraja de Magos para invocar a una clarividente de la Luna Negra y devuélveles la baraja."}}
D[12519] = {"Patrulla trol: ¿Qué quieres, una medalla?",{"El capitán Grondel fuera del Coliseo quiere que recojas 7 medallones Drakkari de los cadáveres Drakkari cercanos."}}
D[12520] = {"Domina el rinoceronte: la prueba",{"Mata a 15 rinocerontes Trozocuerno y vuelve a ver a Hemet Nesingwary al Campamento Base de Nesingwary."}}
D[12521] = {"¿Dónde se esconde Hemet Nesingwary?",{"Estás en esta misión"}}
D[12522] = {"Necesitar un motor, coger un motor",{"Weslex Llave Rápida en el Campamento Base de Nesingwary quiere que le lleves un motor de máquina voladora."}}
D[12523] = {"Tener una parte, dar una parte",{"Trae 7 piezas de repuesto de Ventura y Cía. a Weslex Llave Rápida en el Campamento Base de Nesingwary."}}
D[12524] = {"Desventura de Ventura y Cía.",{"Debaar en el Campamento Base de Nesingwary quiere que mates a 15 miembros de Ventura y Cía. Debes matar a rufianes de Ventura y Cía. o a excavadores de Ventura y Cía."}}
D[12525] = {"Bórrale esa sonrisa de la cara",{"Mata al supervisor Timomueca y a Pastel de Carne, y vuelve junto a Debaar al Campamento Base de Nesingwary."}}
D[12526] = {"Domina el rinoceronte: la persecución",{"Habla con el Oráculo Soo-liloquio en los Huesos de Nozronn."}}
D[12527] = {"Rondadores glotones",{"Llévale 5 cristales de basilisco al alquimista Finklestein en el santuario de Heb'Valok."}}
D[12528] = {"Seguir la corriente",{"Preséntate ante el alto chamán Rakjak en la Colina Corazón Frenético como el nuevo \"esclavo\"."}}
D[12529] = {"El esclavo del cazador de monos",{"Mata a 8 batidores Callonudillos y 6 destreros Callonudillos para el alto chamán Rakjak de la Colina Corazón Frenético.","","Si pierdes los grilletes de Goregek, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12530] = {"Atormentar a los badanudillos",{"Goregek te ha dado un atizador de badanudillos para hacer que la matriarca Callonudillo salga de su escondite. Mata a la matriarca Callonudillo e informa sobre su muerte al alto chamán Rajak en la Colina Corazón Frenético.","","Si pierdes los grilletes de Goregek, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12531] = {"La amenaza subterránea",{"Encuentra a Serfex bajo las arenas del río sur, mátalo y tráele su garra al alto chamán Rakjak en la Colina Corazón Frenético.","","Si pierdes la tiza desgastada de Dajik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12532] = {"¡Se dieron a la fuga!",{"Atrapa 12 pollos fugitivos para el anciano Harkek.","","Si pierdes la tiza desgastada de Dajik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12533] = {"El aprendiz de cazador de avispas",{"Mata 6 avispas del Enjambre Zafiro y 9 zánganos del Enjambre Zafiro para el alto chamán Rakjak en la Colina Corazón Frenético.","","Si pierdes la tiza desgastada de Dajik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12534] = {"La reina Zafiro",{"Llévale el aguijonero de la reina Zafiro al alto chamán Rakjak en la Colina Corazón Frenético.","","Si pierdes la tiza desgastada de Dajik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12535] = {"Malicia en la creación",{"El alto chamán Rakjak en la Colina Corazón Frenético quiere 8 marañas de cristal Trecho Celestial."}}
D[12536] = {"Un viaje complicado",{"Viaja sobre el crocolisco cautivo hasta el Refugio Susurraneblina y habla con Zepik para recibir instrucciones.","","Si pierdes el cuerno de caza de Zepik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
D[12537] = {"El rayo golpea dos veces sin duda",{"Zepik quiere que rompas las marañas de cristal Trecho Celestial delante del Santuario Climático Susurraneblina.","","Si pierdes el cuerno de caza de Zepik, habla con el anciano Harkek en la Colina Corazón Frenético."}}
