D[12541] = {"Patrulla trol: el aprendiz de alquimista",{"El alquimista Finklestein en Heb'Valok quiere que lo ayudes en la creación de un suero de la verdad.","","Cuando estés listo para empezar, habla con él y sigue sus instrucciones."}}
D[12542] = {"La Llamada de la Cruzada",{"Preséntate ante el cruzado Valus en la Confianza de la Luz del Cementerio de Dragones."}}
D[12543] = {"Una ofrenda para Soo-liloquio",{"Trae 5 colmillos de cobra intactos al Oráculo Soo-liloquio cerca de los Huesos de Nozronn."}}
D[12544] = {"Los Huesos de Nozronn",{"Utiliza el incienso de Soo-liloquio cerca de Los Huesos de Nozronn y luego vuelve junto a Hemet Nesingwary al Campamento Base de Nesingwary con la información que hayas conseguido."}}
D[12545] = {"La limpieza de Jintha'kalar",{"El cruzado Valus en la Confianza de la Luz del Cementerio de Dragones te pide que mates a 15 miembros de la Plaga en Jintha'kalar."}}
D[12546] = {"Reclamación",{"Ve a la Avalancha en la Cuenca de Sholazar y usa la runa omega para desplegar al Etimidiano. Úsalo para matar a 200 Esbirros de la Plaga, a Bythius el Formador de carne, a Urgreth de Las Mil Tumbas y a Iragélida.","","Habla con el avatar de Freya en la Cuenca de Sholazar cuando hayas terminado la misión."}}
D[12547] = {"La activación de la runa",{"Consigue la runa omega dentro del Bancal del Creador y llévasela a El Etimidiano."}}
D[12548] = {"El Etimidiano",{"Atraviesa la Puerta en el extremo sur de la Cuenca de Sholazar y busca el arma conocida como el Etimidiano al otro lado."}}
D[12549] = {"Domina el sable aterrador: convertirse en depredador",{"Mata 15 sables aterradores y vuelve a Buck Ladobién en el Campamento Base de Nesingwary."}}
D[12550] = {"Domina el sable aterrador: acechar a la presa",{"Buck Ladobién en el Campamento Base de Nesingwary quiere que identifiques 3 huellas de Shango entre las huellas de sable aterrador cerca del lago Olamarga."}}
