D[12603] = {"Afilar tus garras",{"Mata a 6 dracos primordiales y luego habla con Dorian Asoladracos en la Avanzada de Dorian."}}
D[12604] = {"¡Felicidades!"}
D[12605] = {"Conseguir el cebo",{"Lleva 6 proles primordiales a Dorian Asoladracos en la Avanzada de Dorian."}}
D[12606] = {"¡Encerrado!",{"El capitán Rupert quiere que abras capullos nerubianos en Drak'Sotra y que vuelvas cuando hayas liberado a 3 lacayos cautivos."}}
D[12607] = {"Cazar un mamut",{"Trae un mamut Partecolmillos a Zootsilbo en el campamento de Dorian."}}
D[12608] = {"Incursión cultora",{"Habla con el avatar de Freya en Rápidos de Hablalluvia."}}
D[12609] = {"Reponer las existencias",{"El capitán Arnath en Heb'Valok te ha pedido que recojas 7 unidades de icor de araña fresco de reptadores ctenízidos en Zul'Drak."}}
D[12610] = {"Cortar las alas",{"El capitán Arnath en Heb'Valok te ha pedido que recojas 7 alas de murciélago inmaculadas de los murciélagos de Zul'Drak."}}
D[12611] = {"Devolver en séptuplo",{"El avatar de Freya quiere que derrotes a Thalgran Añublador usando el resguardo de Freya para devolverle sus Descargas de muerte multiplicadas por siete."}}
D[12612] = {"El pilar caído",{"Viaja a El Pilar Sangrevida y busca pistas sobre su destrucción."}}
D[12613] = {"Activar la puerta: El Mirador de los Creadores",{"El avatar de Freya quiere que te dirijas al Mirador de los Creadores, al este de la Cuenca de Sholazar, y uses el interruptor de activación Theta."}}
D[12614] = {"Agresión posparto",{"Mata a la madre de linaje Slivina y vuelve junto a Dorian Asoladracos en la Avanzada de Dorian."}}
D[12615] = {"La bendición de Zim'Torga",{"El médico brujo Khufu quiere que presentes 10 ofrendas Drakkari a la estatua de Zim'Torga."}}
D[12616] = {"La Cámara de los Secretos",{"El emisario de El Alba Argenta quiere que encuentres la habitación de Tenris Sangre Penumbra dentro de los aposentos de los sirvientes en Karazhan."}}
D[12617] = {"Exterminar a los intrusos",{"El avatar de Freya en los Rápidos de Hablalluvia quiere que vayas al Campamento Mano de la Muerte al noroeste y que mates a 8 cultores infiltrados."}}
D[12618] = {"La bendición de Zim'Torga"}
D[12619] = {"La hojarruna blasonada",{"Encuentra una espada desgastada por la batalla en los expositores de armas de El Bastión de Ébano y úsala en una forja de runas para crear una espada de hojarruna.","","Devuelve la espada de hojarruna al instructor Razuvious en El Bastión de Ébano."}}
D[12620] = {"La cólera de la guardiana de vida",{"El avatar de Freya en los Rápidos de Hablalluvia quiere que utilices el cuerno de Freya en lo alto de El Pilar Iluminado."}}
D[12621] = {"El pacto de Freya",{"Escucha lo que tiene que decir el avatar de Freya."}}
D[12622] = {"Los líderes de Jin'Alai",{"El arrancacabelleras Ahunae, de Zim'Torga, te ha pedido que recuperes el tesoro de Kutube'sa, el tesoro de Gawanil y el tesoro de Chulo el Loco."}}
D[12623] = {"A ver al médico brujo",{"Habla con el médico brujo Khufu en Zim'Torga."}}
D[12624] = {"¡Podría estar en cualquier lugar!",{"Busca el anillo de compromiso dorado en las diversas criaturas de la Cuenca de Sholazar."}}
D[12625] = {"Dominio de Acherus",{"Preséntate ante el maestro herrero de asedio Corvus en el piso del cuartel de El Bastión de Ébano."}}
D[12627] = {"Abrirse paso entre los Jin'Alai",{"El médico brujo Khufu, de Zim'Torga, te ha pedido que estropees la caldera azul, la caldera verde, la caldera púrpura y la caldera roja."}}
D[12628] = {"A hablar con Har'koa",{"Habla con Har'koa en el Altar de Har'koa."}}
D[12629] = {"Puedes correr pero no esconderte",{"Stefan del Puesto de Vigilancia de Ébano te ha pedido que vayas al Relicario de Agonía y consigas 5 tripas de abominación pútrida y 5 babas de necrófago pegajosas."}}
D[12630] = {"Patadas a Nass para muestras",{"Stefan en el Puesto de Vigilancia de Ébano quiere que uses a Nass para recoger 10 muestras de pelo de trols marchitos.","","Si pierdes a Nass, vuelve con Stefan para recuperarlo."}}
D[12631] = {"Una especie de invitación…",{"Lleva la gargantilla sin vida a Stefan en el Puesto de Vigilancia de Ébano."}}
D[12632] = {"No sin mis crías",{"Har'koa te ha pedido que uses su bigote en los cadáveres de sus hijos para liberarlos y resucitarlos. Vuelve a verla al Altar de Har'koa cuando hayas acabado."}}
D[12633] = {"La llamada de la oscuridad",{"Lleva la gargantilla aviesa a Stefan del Puesto de Vigilancia de Ébano."}}
D[12634] = {"Algunos hacen limonada y otros hacen licores",{"Lleva 1 naranja, 2 racimos de plátanos y 1 papaya a Tragoamargo Cebatruenos, al Campamento Base de Nesingwary."}}
D[12635] = {"Reliquias de la diosa leopardo de la nieve",{"El cronista To'kini de Zim'Torga quiere que recuperes 10 reliquias de Har'koan."}}
D[12636] = {"El ojo de Acherus",{"Preséntate ante el Rey Exánime en El Bastión de Ébano."}}
D[12637] = {"Casi un fracaso",{"Stefan del Puesto de Vigilancia de Ébano quiere que le lleves la gargantilla sin vida a Rosangre Datura."}}
D[12638] = {"Llamada cercana",{"Stefan del Puesto de Vigilancia de Ébano quiere que le lleves la gargantilla aviesa a Rosangre Datura."}}
D[12639] = {"La tierra congelada",{"La domadora de elementos Dagoda de Zim'Torga quiere que recolectes 7 esencias de la tierra congelada."}}
D[12640] = {"Sellar fallas",{"El arrancacabelleras Ahunae de Zim'Torga te ha pedido que selles 7 fallas elementales."}}
D[12641] = {"La muerte viene de arriba",{"El Rey Exánime te ordena que uses el ojo de Acherus para analizar el Bastión Escarlata, la Forja de Nuevo Avalon, el Concejo de Nuevo Avalon y la Capilla de la Llama Carmesí.","","Controla el ojo de Acherus usando el mecanismo de control del ojo de Acherus."}}
D[12642] = {"El espíritu de Rhunok",{"Habla con el espíritu de Rhunok en el Altar de Rhunok."}}
D[12643] = {"Un resquicio de esperanza",{"Stefan del Puesto de Vigilancia de Ébano te ha pedido que vayas al Relicario de Agonía y consigas 5 tripas de abominación pútrida y 5 babas de necrófago pegajosas."}}
D[12644] = {"Seguimos destilando",{"Completa el proceso de destilación con éxito y trae el ponche salvaje de Cebatruenos a Tragoamargo Cebatruenos en el Campamento Base de Nesingwary."}}
D[12645] = {"La prueba de la cata",{"Ofrece una muestra de ponche salvaje de Cebatruenos a Hemet Nesingwary, Hadrius Harlowe y Tamara Piñonflojo, después regresa junto a Tragoamargo Cebatruenos al Campamento Base de Nesingwary."}}
D[12646] = {"Mi profeta, mi enemigo",{"El espíritu de Rhunok en el Altar de Rhunok te ha pedido que consigas el mojo de dios oso ártico."}}
D[12647] = {"Acabar con el sufrimiento",{"El espíritu de Rhunok te ha pedido que uses el incienso de torturador para despertar su cuerpo. Luego debes matar a Rhunok con el poder que te ha imbuido su espíritu.","","Si por alguna razón pierdes el aura de mojo de Rhunok, puedes volver con el espíritu de Rhunok para que te la vuelva a poner."}}
D[12648] = {"Vestirse humildemente",{"Stefan del Puesto de Vigilancia de Ébano quiere que uses la gargantilla embrujada para disfrazarte como la Plaga.","","Mientras estés en forma de la Plaga, tienes que comprar un plasma amargo de Cartilaginoso.","","Si pierdes la gargantilla embrujada, vuelve con Stefan en el Puesto de Vigilancia de Ébano para conseguir otra."}}
D[12649] = {"¡Vestirse para la ocasión!",{"Stefan del Puesto de Vigilancia de Ébano quiere que uses la gargantilla embrujada para disfrazarte como la Plaga.","","Mientras estés en forma de la Plaga, tienes que comprar un plasma amargo de Cartilaginoso.","","Si pierdes la gargantilla embrujada, vuelve con Stefan en el Puesto de Vigilancia de Ébano para conseguir otra."}}
D[12650] = {"Saqueo propio",{"El cronista To'kini de Zim'Torga quiere que recuperes 7 artefactos rhunokianos."}}
D[12651] = {"Pista del Lago",{"Habla con Tamara Piñonflojo en la Pista del Lago."}}
D[12652] = {"Da'd de comedd a ezoz necrófagoz",{"Cartilaginoso en el Relicario de Agonía quiere que uses el cuenco de intestinos y cerebros cerca de 10 necrófagos putrefactos."}}
D[12653] = {"Volver con Har’koa",{"Habla con Har’koa en el Altar de Har’koa."}}
D[12654] = {"El cazador a tiempo parcial",{"Lleva los restos de Brea a Tamara Piñonflojo en la Pista del Lago."}}
D[12655] = {"La bendición de Zim'Rhuk",{"El médico brujo Khufu quiere que presentes 10 ofrendas Drakkari ante la estatua de Zim'Rhuk."}}
D[12656] = {"La bendición de Zim'Rhuk"}
D[12657] = {"El poder de la Plaga",{"El Rey Exánime te pide que lleves sus órdenes al alto señor Darion Mograine en El Bastión de Ébano.","","Usa el teletransportador resplandeciente que hay detrás del Rey Exánime para llegar hasta el alto señor Darion Mograine en la Sala de Mando."}}
D[12658] = {"Mi mascota roc",{"Lleva 7 huevos de roc a Zootsilbo en la Avanzada de Dorian."}}
D[12659] = {"¡Cabelleras!",{"El arrancacabelleras Ahunae en Zim'Torga quiere que utilices el puñal de Ahunae para arrancar la cabellera a 10 trols de Heb'Drakkar.","","El arrancacabelleras te recuerda que primero tienes que despojarlos."}}
D[12660] = {"Armas de destrucción",{"El avatar de Freya quiere que vayas al Campamento Mano de la Muerte al noroeste y destruyas 4 explosivos inestables."}}
D[12661] = {"Infiltrarse en Voltarus",{"Stefan quiere que utilices la gargantilla embrujada para entrar en Voltarus y hacer lo que te pida el líder de la Plaga.","","Si pierdes la gargantilla embrujada, vuelve con Stefan en el Puesto de la Avanzada de Ébano para conseguir otra."}}
D[12662] = {"Abate a Heb'Jin",{"La domadora de elementos Dagoda de Zim'Torga quiere que mates a Heb'Jin."}}
D[12663] = {"Reunidos"}
D[12664] = {"Horizonte Oscuro",{"Drakuru de Voltarus quiere que hables con Bolsasangrienta y que des una vuelta por Zul'Drak."}}
D[12665] = {"Noto una alteración",{"Har'koa te ha pedido que averigües qué le ha pasado a Quetz'lun. Habla con ella para que te deje a una de sus crías y puedas ir sigilosamente al Altar de Quetz'lun.","","Vuelve con ella al Altar de Har'koa cuando lo hayas hecho."}}
D[12666] = {"Preparaciones para el inframundo",{"Har'koa quiere que recojas 8 adornos sacros. Entrégaselos en el Altar de Har'koa."}}
D[12667] = {"Busca a la diosa serpiente alada",{"Busca el espíritu de Quetz'lun en el Altar de Quetz'lun."}}
D[12668] = {"Cimientos de venganza",{"El espíritu de Quetz'lun te ha encargado la exterminación de 12 trols, beatos de Quetz'lun o rabiosos vipéridos, cerca de sus fuentes de almas. Solo cuando hayas cumplido con esto volverás con ella al Altar de Quetz'lun."}}
D[12669] = {"Por ahora todo mal",{"Stefan en el Puesto de Vigilancia de Ébano quiere que vuelvas con Drakuru y completes cualquier tarea que tenga para ti.","","Mientras estés en el Relicario de Dolor, utiliza el aditivo diluido en 5 calderas de añublo.","","Si pierdes tu gargantilla embrujada, vuelve con Stefan del Puesto de Vigilancia de Ébano para conseguir otra."}}
D[12670] = {"La cosecha Escarlata",{"Preséntate ante el príncipe Valanar en la Brecha de la Muerte."}}
D[12671] = {"Vuelo de reconocimiento",{"Ayuda al piloto Vic a completar el vuelo de reconocimiento."}}
D[12672] = {"Preparando el escenario",{"El espíritu de Quetz'lun te ha pedido que recojas 10 fragmentos de poder del inframundo. Vuelve con ella al Altar de Quetz'lun cuando hayas acabado."}}
D[12673] = {"Donde hay patrón…",{"El Señor supremo Drakuru en Voltarus quiere que utilices el cetro de sugerencia en geists de añublo y que les ordenes a recolectar 7 cristales de añublo."}}
D[12674] = {"Ira de mujer…",{"El espíritu de Quetz'lun quiere que utilices el palo de maleficios de Quetz'lun contra el sumo sacerdote Mu'funu, la suma sacerdotisa Tua-Tua y el sumo sacerdote Hawinni. Cuando lo hayas hecho, mátalos."}}
D[12675] = {"Una última cosa",{"Entrega el fragmento de poder del inframundo a Har'koa y suplícale que te dé una muestra de su espíritu. Aún debe estar en el Altar de Har'koa."}}
D[12676] = {"Sabotaje",{"Stefan del Puesto de Vigilancia de Ébano quiere que realices otra tarea para Drakuru.","","Además, tienes que poner 5 cargas explosivas en los carros de la Plaga en el Relicario de Dolor.","","Si pierdes tu gargantilla embrujada, vuelve con Stefan en el Puesto de Vigilancia de Ébano para conseguir otra."}}
D[12677] = {"Materiales arriesgados",{"Stefan del Puesto de Vigilancia de Ébano quiere que vayas a Voltarus y completes cualquier tarea que Drakuru tenga para ti. Mientras estés ahí, tienes que robar 5 cristales de añublo recolectados.","","Si pierdes la gargantilla embrujada, vuelve con Stefan en el Puesto de Vigilancia de Ébano para conseguir otra."}}
D[12678] = {"Cuando llegue el caos, deja que el sufrimiento tome las riendas",{"El príncipe Valanar en la Brecha de la Muerte te ordena que mates a 10 cruzados Escarlata o campesinos Escarlata y a 10 ciudadanos de Villa Refugio."}}
D[12679] = {"Esta noche cenamos en Villa Refugio",{"Orithos, el Ensombrecedor del Cielo en Brecha de la Muerte, quiere que recuperes 15 flechas de saronita."}}
D[12680] = {"El gran robo de Palomino",{"Salanar el Jinete te pide que robes un caballo del Establo de Villa Refugio y lo lleves a la Brecha de la Muerte"}}
D[12681] = {"Agente componente",{"Lleva 5 garras retorcidas de roc a Colvin Norrington en la avanzada de Dorian."}}
D[12682] = {"Uncharted Territory (DEPRECATED)"}
D[12683] = {"Ansioso por ayudar",{"Colvin Norrington en la avanzada de Dorian quiere que recojas 5 muestras de esputo de hidra y que mates a 5 hidras Olamarga."}}
D[12684] = {"Sangre de un dios muerto",{"Har'koa te ha pedido que recojas 7 muestras de sangre de Mam'toth. Llévaselas al Altar de Har'koa."}}
D[12685] = {"Recoges lo que siembras",{"Mata al profeta de Quetz'lun extenuado y luego informa al médico brujo Khufu en Zim'Torga."}}
D[12686] = {"Tolerancia cero",{"Drakuru en Voltarus quiere que vayas al Relicario de Dolor y que uses el cetro en el sirviente de Drakuru. Luego tendrás que hacer uso de tus talentos para derrotar a Darmuk."}}
D[12687] = {"En el Reino de las Sombras",{"Salanar el Jinete, en la Brecha de la Muerte, te desafía a matar al jinete oscuro de Acherus y tomar su destrero de la muerte de Acherus.","","Si lo consigues, lleva el destrero de la muerte de Acherus a la Brecha de la Muerte y usa la Llamada del jinete para invocar a Salanar."}}
D[12688] = {"Ingeniería de un desastre",{"Ayuda la ingeniera Hélice a escapar de la Excavación de Timomueca y luego habla con Hemet Nesingwary en el Campamento Base de Nesingwary."}}
D[12689] = {"Mano de los Oráculos"}
D[12690] = {"Combustible para el fuego",{"Drakuru en Voltarus quiere que uses el cetro de mando en abominaciones hinchadas y que hagas uso de sus talentos en la Brecha Gélida para matar a 60 trituracráneos Drakkari y que captures a 3 cabecillas Drakkari.","","Los cabecillas aparecerán cuando hayas matado suficientes trituracráneos."}}
D[12691] = {"Una arca estropeada por el tiempo",{"Consigue una llave de piedra enorme de los guardianes de Sholazar y tráela al arca estropeada por el tiempo en el Mirador de los Creadores."}}
D[12692] = {"El retorno del cazador de exánimes",{"Vuelve a la Colina Corazón Frenético y habla con el anciano Harkek."}}
D[12693] = {"Wolvar Faction Choice Tracker"}
D[12694] = {"Oracle Faction Choice Tracker"}
D[12695] = {"El retorno del pielseca amistoso",{"Regresa a la Espesura Hablalluvia y habla con el sumo Oráculo Soo-pinstán."}}
D[12696] = {"Reconocimiento aéreo",{"La profesora Calvert quiere que cojas el vuelo a la Pista del Lago y que hables con el piloto Vic."}}
D[12697] = {"Gothik el Cosechador",{"Habla con Gothik el Cosechador en la Brecha de la Muerte."}}
D[12698] = {"La ofrenda que sigue dando",{"Gothik el Cosechador en Brecha de la Muerte te ha dado el regalo del Cosechador para usarlo con los mineros escarlatas. Crea 5 necrófagos escarlata con este dispositivo y lleva los necrófagos a Gothik."}}
D[12699] = {"Un incidente embarazoso",{"Busca las llaves de Vic dentro del lago en el Corazón del Río."}}
D[12700] = {"Un ataque de oportunidad",{"Habla con el príncipe Valanar en la Brecha de la Muerte."}}
D[12701] = {"Masacre en la Punta de la Luz",{"El príncipe Valanar, en la Brecha de la Muerte, te ha ordenado que mates a 100 defensores Escarlata."}}
D[12702] = {"¡Fiesta de pollos!",{"Captura 12 pollos fugitivos para el anciano Harkek en la Colina Corazón Frenético."}}
D[12703] = {"La locura de Kartak",{"Lleva una muestra pura de sangre del Oráculo al altar de Kartak para invocar a Kartak. Con la ayuda de los poderes compartidos de Kartak, mata a 50 de los górlocs Pavesa para el Chamán Jakjek en el Bastión de Kartak."}}
D[12704] = {"Apaciguar la Gran Piedra de Lluvia",{"El sumo Oráculo Soo-pinstán, dla Espesura Hablalluvia, quiere que elijas un compañero para escavar y conseguir 6 tesoros lustrosos.","","Asegúrate de hablar con el sumo Oráculo Soo-pinstán en la Espesura Hablalluvia para conseguir la ayuda de uno de tus anteriores compañeros."}}
D[12705] = {"Voluntad de los titanes",{"Consigue un cristal máculo de los wolvar cerca de Retiro Pavesa y llévalo a la Gran Piedra de Rayos para invocar a Soo-brada. Con la ayuda de los poderes compartidos de Soo-brada, mata a 50 de los wolvar Corazón Frenético cercanos, después vuelve junto al Clamarelámpagos Soo-notone en el Retiro Pavesa."}}
D[12706] = {"¡Victoria en la Brecha de la Muerte!",{"Entrega el informe del príncipe Valanar al alto señor Darion Mograine en Acherus: El Bastión de Ébano."}}
D[12707] = {"El peso de la justicia",{"El arrancacabelleras Ahunae de Zim'Torga quiere que uses el medallón de Mam'toth para calmar y montar sobre un mamut enfurecido. Luego quiere que pisotees 12 discípulos de Mam'toth hasta que mueran."}}
D[12708] = {"Guerreros Tiki encantados",{"La domadora de elementos Dagoda en Zim'Torga te ha pedido que acabes con 12 guerreros Tiki encantados."}}
D[12709] = {"Alijos embrujados",{"El cronista To'kini en Zim'Torga te ha pedido que consigas 12 alijos del Bastión de Zol'Maz."}}
D[12710] = {"Revelación",{"Drakuru en Voltarus quiere que cojas el teletransportador hasta su cámara superior."}}
D[12711] = {"Mensaje abandonado"}
D[12712] = {"La llave del señor de la guerra Zol'Maz",{"Har'koa de Zim'Torga te ha pedido que consigas la llave del señor de la guerra Zol'Maz."}}
D[12713] = {"Traición",{"Stefan del Puesto de Vigilancia de Ébano quiere que derrotes a Drakuru.","","Si pierdes la gargantilla embrujada, vuelve con Stefan del Puesto de Vigilancia de Ébano para obtener otra."}}
D[12714] = {"La voluntad del Rey Exánime",{"Vuelve a Brecha de la Muerte e informa al príncipe Valanar."}}
D[12715] = {"La Cripta de los Recuerdos",{"Preséntate ante el príncipe Keleseth en la Cripta de los Recuerdos."}}
D[12716] = {"La solicitud del Pesteador",{"Noth el Pesteador ha solicitado que le traigas 1 caldera vacía, 1 cadena de hierro y 10 calaveras de cruzado."}}
D[12717] = {"El brebaje especial de Noth",{"Coloca la pila de calaveras de cruzado dentro de la caldera de peste."}}
D[12718] = {"Más calaveras para brebaje"}
D[12719] = {"No hay escapatoria",{"El príncipe Keleseth de la Cripta de los Recuerdos te ha ordenado matar al alcalde Quimby y recuperar el registro de Nuevo Avalon."}}
D[12720] = {"Cómo ganar amigos e influenciar a los enemigos",{"El príncipe Keleseth de la Cripta de los Recuerdos te ha ordenado que descubras la verdad sobre el \"Alba Carmesí\".","","Saca los persuasores de Keleseth de la caja ornamentada con joyas y úsalos para \"persuadir\" a la Cruzada Escarlata para que hable."}}
D[12721] = {"Arrasando",{"Har'koa en Zim'Torga te ha pedido que liberes a Akali y luego informes al médico brujo Khufu en Zim'Torga."}}
D[12722] = {"Corderos a la matanza",{"El barón Osahendido en la Cripta de los Recuerdos te ha ordenado que mates a 10 soldados de la Cruzada Escarlata y 15 ciudadanos de Nuevo Avalon."}}
D[12723] = {"Detrás de las líneas Escarlata",{"Preséntate ante Orbaz Malasangre en la Taberna Escarlata de Nuevo Avalon."}}
D[12724] = {"El camino del cruzado honrado",{"Orbaz de la Taberna Escarlata en Nuevo Avalon te ha ordenado que robes el horario de patrullas de Nuevo Avalon que hay en el Bastión Escarlata."}}
D[12725] = {"Hermanos en la muerte",{"Busca a Koltira Tejemuerte en el Bastión Escarlata"}}
D[12726] = {"Canción de viento y agua",{"Soo-nata quiere que uses los tambores de la tempestad en La Plataforma del Tormentoso y que ayudes a Haifón a devorar 3 aparecidos tormentosos y 3 espíritus acuosos."}}
D[12727] = {"Estallido sangriento",{"Mata al Alto Inquisidor Valroth y lleva su cabeza a Thassarian en la Taberna Escarlata de Nuevo Avalon."}}
D[12728] = {"Observar la falla: Cavernas Aleta Invernal",{"El bibliotecario Garren en El Saliente Ámbar quiere que uses el arcanómetro en las Cavernas Aleta Invernal."}}
D[12729] = {"Los dioses han hablado",{"Entrega el corazón del guardián inmaculado y la esencia ventosa del celador a Har'koa en Zim'Torga."}}
D[12730] = {"Convocatoria en Zol'Heb",{"Har'koa en Zim'Torga te ha pedido que mates al profeta de Akali."}}
D[12732] = {"La fuerza de corazón de sangre",{"Lleva un vial de corazón de sangre Toquesol a Rejek a la Colina Corazón Frenético."}}
D[12733] = {"Desafío de la Muerte",{"Olrun la Clamabatallas te ha ordenado que ganes 5 duelos contra otros caballeros de la Muerte.","","Deberías luchar contra caballeros de la Muerte iniciados o jugadores."}}
D[12734] = {"Rejek: Primeras manchas de sangre",{"Mancha de sangre la hoja de Rejek en los cadáveres de una avispa del Enjambre Zafiro, un destrero Callonudillo y 3 miembros de la tribu Susurraneblinas. Puedes manchar la hoja con sangre de Oráculos Susurraneblina o de guerreros Susurraneblina. Vuelve junto a Rejek a la Colina Corazón Frenético cuando acabes la tarea."}}
D[12735] = {"Canción de purificación",{"Soo-nata, en la Espesura Hablalluvia, quiere que hagas sonar la campana de purificación en el Lago Olamarga, el Río Conquista del Invierno y el Corazón del Río, y que mates a los espíritus maléficos que habitan en sus aguas."}}
D[12736] = {"Canción de reflexión",{"Soo-nata, en la Espesura Hablalluvia, quiere que uses el didgeridoo de contemplación en lo alto de El Pilar Iluminado, El Pilar Musgoluz y El Pilar del Trecho Celestial."}}
D[12737] = {"Canción de fecundidad",{"Soo-nata en la Espesura Hablalluvia quiere que vayas a la Plataforma del Tormentoso, al noroeste de El Pedestal de los Creadores y que toques el cuerno de fecundidad cerca de 8 montones de tierra fértil empapada."}}
