D[12877] = {"El guardián solitario",{"Recupera el sello Puño Helado de un amonestador enano férreo y llévaselo a Creteus en las Estepas Inferiores."}}
D[12878] = {"La reliquia oculta",{"Creteus en Las Estepas Inferiores te ha proporcionado la información necesaria para encontrar el núcleo de Norgannon."}}
D[12879] = {"La furia del rey Natoescarcha",{"Llévale el núcleo de Norgannon a Creteus en Las Estepas Inferiores."}}
D[12880] = {"El maestro expedicionario",{"Llévale el núcleo de Norgannon a Brann Barbabronce en el Motor de los Creadores."}}
D[12881] = {"Los hermanos Barbabronce"}
D[12882] = {"Reliquias antiguas",{"Estás en esta misión"}}
D[12883] = {"Órdenes de Drakuru",{"Lleva las órdenes de Drakuru al señor cruzado Lantinga en la Brecha de la Luz en Zul'Drak."}}
D[12884] = {"El Puesto de Vigilancia de Ébano",{"Lleva las órdenes de Drakuru a Stefan Vadu en el Puesto de Vigilancia de Ébano en Zul'Drak."}}
D[12885] = {"Los exiliados de Ulduar",{"Habla con Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12886] = {"El Drakkensryd",{"Usa el arpón Hyldnir para derrotar a 10 jinetes de dracos de El Encuentro Hyldnir en el Templo de las Tormentas. Usa el arpón Hyldnir en un adorno de columna para salir del Drakkensryd y habla con Thorim cuando lo hayas conseguido."}}
D[12887] = {"Pura diversión",{"Acaba con El Ocular y luego informa al Barón Tajada en La Cámara de las Sombras."}}
D[12888] = {"CHATARR-A",{"Llévale la tarjeta de acceso de CHATARR-A junto a 4 puñados de tornillos de cobalto y 5 condensadores sobrecargados a CHATARR-A en la Biblioteca del Inventor."}}
D[12889] = {"La consola prototipo",{"Interactúa con la consola prototipo en la Biblioteca del Inventor."}}
D[12890] = {"Si el tamaño importara…"}
D[12891] = {"Tengo una idea, pero primero…",{"El Barón Tajada en La Cámara de las Sombras te ha pedido que consigas una vara de cultor, un gancho de abominación, una cuerda Geist y 5 esencias de la Plaga."}}
D[12892] = {"Pura diversión",{"Acaba con El Ocular y luego informa al Barón Tajada en La Cámara de las Sombras."}}
D[12893] = {"Libera tu mente",{"El Barón Tajada en La Cámara de las Sombras quiere que uses la vara soberana en los cadáveres de Vil, Lady Bosqueténebro y El Saltador."}}
D[12894] = {"El Puesto de Avanzada de los Cruzados",{"Busca al cruzado MacKellar en el Puesto de Avanzada de los Cruzados en Zul'Drak."}}
D[12895] = {"El Barbabronce desaparecido",{"Estás en esta misión"}}
D[12896] = {"Si no puede ser transformado",{"Derrota al general Aterraluz e informa de tu éxito a Thassarian a bordo de El Rompecielos, la nave de guerra."}}
D[12897] = {"Si no puede ser transformado",{"Derrota al general Aterraluz e informa de tu éxito a Koltira Tejemuerte a bordo del Martillo de Orgrim, la nave de guerra."}}
D[12898] = {"La Cámara de las Sombras",{"Informa al Barón Tajada en La Cámara de las Sombras."}}
D[12899] = {"La Cámara de las Sombras",{"Informa al Barón Tajada en La Cámara de las Sombras."}}
D[12900] = {"Hacer un arnés",{"Astrid Bjornrittar en el Poblado Brunnhildar quiere que consigas 3 pellejos de yeti Pelohielo."}}
D[12901] = {"Hacer algo a partir de nada",{"El ingeniero Carrizo en el Puesto de Avanzada de los Cruzados en Zul'Drak te ha pedido que consigas 10 trozos de chatarra de la Plaga."}}
D[12902] = {"En busca de respuestas",{"Registra la Guarida de Garrafuria para buscar pistas sobre quién o qué inició el ataque contra los wolvar Garrafuria."}}
D[12903] = {"Para eso están los amigos…",{"El cruzado MacKellar en el Puesto de Avanzada de los Cruzados te ha pedido que encuentres al cruzado Dargath, a Gerk y a Burr."}}
D[12904] = {"La Luz no me dará la venganza",{"Gerk en el Fin de Thrym en Zul'Drak quiere que mates a 15 vargul."}}
D[12905] = {"Mildred la Cruel",{"Habla con Mildred la Cruel en la Mina Desolada."}}
D[12906] = {"Disciplina",{"Mildred la Cruel en La Mina Desolada quiere que uses la vara disciplinante sobre 6 vrykul agotados."}}
D[12907] = {"Castigos ejemplares",{"Mildred la Cruel en la Mina Desolada quiere que mates a Garhal."}}
D[12908] = {"Un prisionero concreto",{"Llévale la llave de Mildred a Lok'lira la Vieja Bruja en la Mina Desolada."}}
D[12909] = {"Por el olfato se sabe",{"Habla con Khaliisi a los pies de la montaña al este del lugar del accidente de Grom'arsh."}}
D[12910] = {"Encontrar al culpable",{"Monta a Mordisquielo y ve con ella a la fuente del olor de la nota de Brann. Luego, recupera el comunicador de Brann y úsalo para contactar con Brann Barbabronce."}}
D[12911] = {"Prueba de crédito por muerte",{"Saluda a la prueba de crédito por muerte escribiendo /wave"}}
D[12912] = {"Se acerca una gran tormenta",{"Gymer, rey de los gigantes de tormenta, te ha pedido que encuentres un modo de liberarlo de su celda. Habla con el ingeniero Carrizo en el Puesto de Avanzada de los Cruzados."}}
D[12913] = {"¡Habla orco, hombre!",{"Habla con Moteha Natoviento en el Lugar del accidente de Grom'arsh."}}
D[12914] = {"La salvación de Gymer",{"El ingeniero Carrizo en el Puesto de Avanzada de los Cruzados en Zul'Drak quiere que le traigas 6 esencias de alma en pena y 6 tierras de diatomeas."}}
D[12915] = {"Enmiendas",{"Thorim en el Templo de las Tormentas quiere que mates a Fjorn y a 5 gigantes de hierro Tronaforjado en el Yunque de Fjorn, al este de Dun Niffelem.","","Usando el talismán de tierra de Thorim invocarás a sus terráneos para que luchen a tu lado. El talismán requiere una roca de granito cerca del yunque de Fjorn."}}
D[12916] = {"Nuestra única esperanza",{"Habla con Gymer en el Fin de Thrym en Zul'Drak cuando hayas usado la carga de seforio enorme para abrir el recinto de la Plaga donde está prisionero."}}
D[12917] = {"Hablar con la voz del viento",{"Llévale 5 voces del viento a Moteha Natoviento en el Lugar del accidente de Grom'arsh."}}
D[12918] = {"Gemas perfectas",{"Llévale dos citrinos enormes, dos jades oscuros y dos cristales de sombras a Ounhulo en Valgarde."}}
D[12919] = {"La venganza del Rey de la Tormenta",{"Habla con Gymer para empezar.","","Con Gymer como montura, destruye a 100 de la Plaga y mata a Algar el Elegido, a Thrym y al príncipe Navarius. Informa al cruzado MacKellar en el Puesto de Avanzada de los Cruzados si tienes éxito."}}
D[12920] = {"Alcanzar a Brann",{"Usa el comunicador de Brann para contactar con Brann Barbabronce y habla con él, y luego habla con Boktar Furia Sangrienta en el lugar del accidente de Grom'arsh.","","Si pierdes el comunicador de Brann, habla con Moteha Natoviento en el lugar del accidente de Grom'arsh."}}
D[12921] = {"Un cambio de escenario",{"Reúnete con Lok'lira la Vieja Bruja en el poblado Brunnhildar."}}
D[12922] = {"El fuego del refinador",{"Debes reunir 10 chispas furiosas de aparecidos hirvientes en el lago Campo de Escarcha y usarlas en el yunque del Yunque de Fjorn."}}
D[12924] = {"Forjando una Alianza",{"Debes ir a Dun Niffelem y pedirle al rey Jokkum que permita que se vuelva a forjar la armadura de Thorim. Después de completar la tarea de Jokkum, habla con Njormeld en Dun Niffelem."}}
D[12925] = {"Aberraciones",{"Thyra Kvinnshal en el Poblado Brunnhildar quiere que vayas a Valkyrion y consigas viales de aceite de Escarcha de las aspirantes de Valkyrion. Usa los viales de aceite de Escarcha para destruir 30 huevos de protodraco apestado."}}
D[12926] = {"Piezas del rompecabezas",{"Usa el comunicador de Brann para contactar con Brann Barbabronce y que te explique qué hacer a continuación."}}
D[12927] = {"Extracción de datos",{"Usa el Disco del Inventor para recuperar las 7 partes de datos ocultos en los bancos de datos."}}
D[12928] = {"El caparazón de Norgannon",{"Recupera el caparazón de Norgannon del archivista Mechaton."}}
D[12929] = {"Los terráneos de Ulduar",{"Habla con Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12930] = {"Tierra rara",{"Usa el pico de minería terráneo para minar 7 puñados de tierra encantada. Lleva la tierra y 5 telas de tejido de Escarcha a Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12931] = {"Contraatacando",{"Pedruscón el Creador de rocas quiere que mates a 10 atacantes Tronaforjado y que vuelvas a hablar con él en el Refugio de Pedruscón. Puedes matar a asaltantes Tronaforjado o atracadores Tronaforjado."}}
D[12932] = {"El Anfiteatro de la Angustia: ¡Yggdras!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Yggdras! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12933] = {"El Anfiteatro de la Angustia: ¡Magnatauro!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Barbahedionda! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12934] = {"El Anfiteatro de la Angustia: ¡del más allá!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a uno de los señores elementales! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12935] = {"El Anfiteatro de la Angustia: ¡Colmillarrmagedón!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Orinoko Rompecolmillos! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12936] = {"El Anfiteatro de la Angustia: ¡Korrak el Sanguinario!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Korrak el Sanguinario! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12937] = {"Alivio para los caídos",{"Usa la cataplasma telúrica para sanar a 8 defensores terráneos caídos, después habla con Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12938] = {"El Duque",{"Habla con el duque Lankral en La Cámara de las Sombras."}}
D[12939] = {"Desafío de honor",{"El duque Lankral en La Cámara de las Sombras te ha pedido que uses la bandera de desafío para que desafíes y derrotes a 6 combatientes Mjordin."}}
D[12940] = {"Cubo de caramelos"}
D[12941] = {"Cubo de caramelos"}
D[12942] = {"Fuera sus alas negras",{"Iva la Vengativa en el poblado Brunnhildar quiere que vayas a Valkyrion y mates a 12 Val'kyr nacientes."}}
D[12943] = {"Decreto de La Cámara de las Sombras",{"El duque Lankral en La Cámara de las Sombras te ha ordenado que leas el decreto de La Cámara de las Sombras en presencia del señor feudal Ufrang el Poderoso y después lo mates."}}
D[12944] = {"Cubo de caramelos"}
D[12945] = {"Cubo de caramelos"}
D[12946] = {"Cubo de caramelos"}
D[12947] = {"Cubo de caramelos"}
D[12948] = {"El campeón de Angustia",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Vladof el Carnicero! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12949] = {"Consigue la llave",{"Vaelen el Despellejado en la Sala de Ufrang te ha pedido que recuperes la llave de las cadenas de Vaelen."}}
D[12950] = {"Cubo de caramelos"}
D[12951] = {"Que el Barón lo sepa",{"Habla con el Barón Tajada en La Cámara de las Sombras."}}
D[12952] = {"Gemas perfectas",{"Estás en esta misión"}}
D[12953] = {"Valkyrion debe arder",{"Usa los cañones de arpones de Valkyrion para incendiar 6 fardos de heno secos."}}
D[12954] = {"El Anfiteatro de la Angustia: ¡Yggdras!",{"¡Entra en la arena del Anfiteatro de la Angustia y derrota a Yggdras! Habla con Wodin el sirviente trol para recoger tu recompensa."}}
D[12955] = {"Eliminar a la competencia",{"El Saltador en La Cámara de las Sombras quiere que desafíes a duelo y derrotes a Sigrid Hielonato, Efrem el Leal, Ono'zun y a Mañosa Silbatín."}}
D[12956] = {"Una chispa de esperanza",{"Tienes que llevar la mena reluciente refinada a Thorim en el Templo de las Tormentas."}}
D[12957] = {"Esclavos de los Tronaforjado",{"Pedruscón el Creador de rocas en el Refugio de Pedruscón quiere que liberes a 6 mecagnomos cautivos y que mates a 3 capataces Tronaforjado."}}
D[12958] = {"Envío: amuleto de jade de sangre",{"Reúne un amuleto vrykul, un jade oscuro y una sangrita para hacer un amuleto de jade de sangre, y llévaselo a Timothy Jones en Dalaran.","","Podrás encontrar amuletos vrykul en cualquier vrykul de Rasganorte."}}
D[12959] = {"Envío: figurilla de marfil resplandeciente",{"Reúne un trozo de marfil de Rasganorte, una calcedonia y un cristal de Sombras para crear una figurilla de marfil resplandeciente, y llévasela a Timothy Jones en Dalaran.","","Podrás encontrar marfil de Rasganorte en cualquier colmipala o mamut de Rasganorte."}}
D[12960] = {"Envío: broche de sol maligno",{"Reúne un broche de enano de hierro, un citrino enorme y un cristal de sol para hacer un broche de sol maligno, y llévaselo a Timothy Jones en Dalaran.","","Podrás encontrar broches de enano de hierro en cualquier enano férreo de Rasganorte."}}
D[12961] = {"Envío: figurilla de hueso intrincada",{"Reúne un hueso de protodraco, un cristal de sol y un jade oscuro para hacer una figurilla de hueso intrincada, y llévasela a Timothy Jones en Dalaran.","","Podrás conseguir huesos de protodraco de cualquier protodraco de Rasganorte."}}
D[12962] = {"Envío: reliquia de armadura brillante",{"Reúne un fragmento de armadura elemental, una sangrita y un citrino enorme para hacer una reliquia de armadura brillante, y llévasela a Timothy Jones en Dalaran.","","Podrás encontrar fragmentos de armadura elemental en cualquier aparecido de Rasganorte."}}
D[12963] = {"Envío: bibelot de sol cambiante",{"Reúne un bibelot de la Plaga, un cristal de sol y un cristal de Sombras para hacer un bibelot de sol cambiante, y llévaselo a Timothy Jones en Dalaran.","","Podrás encontrar bibelots de la Plaga en cualquier Plaga de Rasganorte."}}
D[12964] = {"La mena oscura",{"Llévale 5 muestras de mena a Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12965] = {"Los obsequios de Loken",{"Destruye la Furia de Loken, el Poder de Loken y el Favor de Loken. Después regresa junto a Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12966] = {"No tiene pérdida",{"El rey Jokkum en Dun Niffelem quiere que busques a Njormeld en el Yunque de Fjorn."}}
D[12967] = {"Luchar contra los elementales",{"Njormeld quiere que acompañes a Snorri al Yunque de Fjorn y que lo ayudes a matar a 10 aparecidos hirvientes."}}
D[12968] = {"La insensatez de Yulda",{"Iva la Vengativa en el poblado Brunnhildar quiere que mates a Yulda la Hablatormentas en Valkyrion."}}
D[12969] = {"¿Es ese tu goblin?",{"Desafía a Agnetta Tyrsdottar para salvar a Zeev Chispeante. Cuando lo hayas conseguido, regresa junto a Lok'lira la Vieja Bruja en el poblado Brunnhildar."}}
D[12970] = {"El Encuentro Hyldnir",{"Escucha la propuesta de Lok'lira la Vieja Bruja."}}
D[12971] = {"Enfrentarse a todos los retos",{"Lok'lira la Vieja Bruja en el poblado Brunnhildar quiere que derrotes a 6 contendientes victoriosas."}}
D[12972] = {"Necesitarás un oso",{"Habla con Brijana a las afueras del poblado Brunnhildar."}}
D[12973] = {"Los hermanos Barbabronce",{"Acompaña a Brann Barbabronce y a su máquina voladora hasta Fuerte Escarcha."}}
D[12974] = {"¡La llamada del campeón!",{"Estás en esta misión"}}
D[12975] = {"En memoria",{"El rey Jokkum en Dun Niffelem quiere que recojas 8 fragmentos de cuerno en Truenotoño."}}
D[12976] = {"Un monumento a los caídos",{"El rey Jokkum quiere que le lleves los fragmentos del cuerno de Hodir a Njormeld, en Dun Niffelem."}}
D[12977] = {"La llamada de Hodir",{"Debes vencer a 5 antepasados de Niffelem y a 5 Natoescarchas inquietos en Truenotoño. Después, utiliza el cuerno de Hodir sobre sus cadáveres y vuelve al cuerno de Hodir en Dun Niffelem."}}
D[12978] = {"Enfrentarse a la tormenta",{"Bruor Temeferro en el Refugio de Pedruscón quiere que mates a 10 Tronaforjado de Nidavelir. Puedes matar campeones Tronaforjado, magi Tronaforjado o gólems de guerra Tronaforjado."}}
D[12979] = {"Armadura de oscuridad",{"Llévale 4 muestras de armadura oscura a Bruor Temeferro en el Refugio de Pedruscón."}}
D[12980] = {"Los secretos de la armadura",{"Lleva la placa de armadura oscura al Taller de Mimir y pídele al auxiliar Tock que lo examine. Cuando esto esté hecho, vuelve junto a Bruor Temeferro al Refugio de Pedruscón."}}
D[12981] = {"Caliente y frío",{"Ve al Lago Campo de Escarcha, mata a los aparecidos frágiles que hay allí y utiliza la Esencia de Hielo en la chatarra ardiente en el Yunque de Fjorn. Después deberás recoger 6 de los fragmentos de hierro congelado y volver junto al Yunque de Fjorn en Dun Niffelem."}}
D[12982] = {"Prisioneros de la Espada de Ébano",{"Vaelen el Despellejado en La Cámara de las Sombras quiere que liberes a 8 prisioneros de la Espada de Ébano. Los podrás encontrar en las jaulas en la región de Jotunheim."}}
D[12983] = {"La última de su raza",{"Astrid Bjornrittar en el poblado Brunnhildar quiere que rescates una matriarca faucehielo en la Caverna Hibernal."}}
D[12984] = {"Valduran el Natormento",{"Usa el cuerno de Guerra de Pedruscón cuando hayas encontrado a Valduran el Natormento. Vence a Valduran el Natormento y vuelve junto a Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12985] = {"Forjar una cabeza",{"Njormeld en Dun Niffelem necesita que uses el pico con punta de diamante en los gigantes de hierro muertos en el lago Campo de Escarcha y vuelvas cuando tengas 8 ojos de Tronaforjado."}}
D[12986] = {"El destino de los titanes",{"Creteus en Las Estepas Inferiores te ha pedido que viajes al Templo de la Invención, el Templo del Invierno, el Templo de la Vida y el Templo del Orden para utilizar el banco de datos y examinar cada zona."}}
D[12987] = {"Colocar el yelmo de Hodir",{"Njormeld quiere vueles a la cumbre de la Punta de Hielo del Norte de Dun Niffelem y uses las tablillas de Dictamen."}}
D[12988] = {"¡Destruye las forjas!",{"Destruye la forja de relámpagos norte, la forja de relámpagos central y la forja de relámpagos sur con las bombas de Pedruscón y después vuelve junto a Pedruscón el Creador de rocas al refugio de Pedruscón."}}
D[12989] = {"La oscuridad reptadora",{"Astrid Bjornrittar quiere que mates a 8 jormungar voraces en la Caverna Hibernal al este del poblado Brunnhildar."}}
D[12990] = {"El agujero de gusano",{"Llévale a Jon LeCraft los materiales que necesita para evitar una muerte rápida y para aprender un nuevo hechizo muy chulo."}}
D[12991] = {"Dales donde más duele",{"Mata a 10 artificieros Tronaforjado y vuelve junto a Bruor Temeferro al Refugio de Pedruscón."}}
D[12992] = {"¡Aplastar a los vrykuls!",{"Vil en La Cámara de las Sombras quiere que mates a 15 vrykuls cualesquiera en la región de Jotunheim."}}
D[12993] = {"Una amenaza colosal",{"Recupera el plan de ataque de coloso y el plan de defensa de coloso y llévaselos a Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[12994] = {"Cazador de espías",{"Debes derrotar a 3 espías Tronaforjado en el Valle de los Viejos Inviernos.","","Usa el colmillo de huargo etéreo sobre el cadáver de huargo caído para invocar a un huargo de escarcha etéreo que descubrirá a los enemigos ocultos. Debes volver junto a la madre del cubil huargo de escarcha en Dun Niffelem cuando hayas acabado con los espías del valle."}}
D[12995] = {"Dejar nuestra huella",{"El Barón Tajada en La Cámara de las Sombras quiere que coloques 15 estandartes de la Espada de Ébano sobre los cadáveres de los vrykuls que encuentres en la región de Jotunheim."}}
D[12996] = {"El calentamiento",{"Astrid Bjornrittar del poblado Brunnhildar quiere que uses las riendas de matriarca Osoguerra para derrotar a Kirgaraak."}}
D[12997] = {"Al foso",{"Astrid Bjornrittar del poblado Brunnhildar quiere que uses las riendas de matriarca Osoguerra dentro del Foso del Colmillo y derrotes a 6 osos de guerra de El Encuentro Hyldnir."}}
D[12998] = {"El Corazón de la Tormenta",{"Pedruscón el Creador de rocas en el Refugio de Pedruscón quiere que viajes a Uldis e intentes evitar que el Sobrestante Narvir consiga el Corazón de la Tormenta."}}
D[12999] = {"La Bruja Osaria",{"Habla con la Bruja Osaria en la cueva del poblado Njorndar."}}
D[13000] = {"Medidas de emergencia",{"Estás en esta misión"}}
D[13001] = {"Forjar la lanza de Hodir",{"El Tradicionalista Randvir en Dun Niffelem quiere que recojas 3 fragmentos de siempreescarcha en las profundidades de la Caverna Hibernal y 3 pieles de mamut estoico de los mamuts estoicos del Valle de los Viejos Inviernos."}}
D[13002] = {"Gemas perfectas",{"Llévale dos citrinos enormes, dos jades oscuros y dos cristales de Sombras a Geba'li en el Bastión Grito de Guerra."}}
D[13003] = {"Cómo matar a tu dragón",{"Debes usar la lanza de Hodir para retar a una vermis salvaje en el Valle de los Viejos Inviernos. Cuando estés entre sus garras, lucha contra ella hasta la muerte."}}
D[13004] = {"Gemas perfectas",{"Llévale dos citrinos enormes, dos jades oscuros y dos cristales de Sombras a Alestros en la Fortaleza Denuedo."}}
D[13005] = {"El juramento terráneo",{"Thorim, en el Bancal de los Creadores, quiere que uses el cuerno de Las Cumbres para llamar a los terráneos y derrotar a 20 enanos férreos y a 7 centinelas de hierro."}}
D[13006] = {"Una limpieza viscosa",{"Debes entrar en la Caverna Hibernal al oeste de Dun Niffelem y recoger 5 unidades de aceite viscoso de los aceites viscosos que hay allí.","","Después debes volver a Dun Niffelem y aplicar el aceite sobre el yelmo de Hodir."}}
D[13007] = {"El coloso de hierro",{"Usa a un jormungar domado para derrotar al coloso de hierro y volver con Pedruscón el Creador de rocas en el Refugio de Pedruscón."}}
D[13008] = {"Tácticas de la Plaga",{"El Comandante de Cruzada Entari en La Vanguardia Argenta en Corona de Hielo te ha pedido que liberes a 8 cruzados enredados."}}
D[13009] = {"Un nuevo comienzo",{"Njormeld quiere que le lleves la armadura reforjada a Thorim en el Templo de las Tormentas."}}
D[13010] = {"Krolmir, el Martillo de las Tormentas",{"Thorim quiere que hables con el rey Jokkum en Dun Niffelem y que descubras lo que sabe sobre Krolmir."}}
D[13011] = {"Jorcuttar debe morir",{"El rey Jokkum en Dun Niffelem quiere que mates a Jorcuttar en la Caverna Hibernal."}}
