D[13034] = {"El héroe y el testigo",{"Xantaur en el Campamento Tunka'lo quiere que leas el primer pergamino de Historia, el segundo pergamino de Historia y el tercer pergamino de Historia."}}
D[13035] = {"Los lacayos de Loken",{"Thorim quiere que mates a Eisenfaust, que está en la Sala del Creador, y a Halefnir el Natoviento y a Duronn el Runaforjado en el Bancal de los Creadores."}}
D[13036] = {"Honor por encima de todo",{"Preséntate ante el Comandante de Cruzada Entari en La Vanguardia Argenta en Corona de Hielo."}}
D[13037] = {"Recuerdos de Pezuña Tempestuosa",{"Habla con el cabecilla Lanza Presta en la Hondonada Témpano Gélido y después regresa junto a Xarantaur en el Campamento Tunka'lo."}}
D[13038] = {"Distorsiones temporales",{"Usa el tótem del cabecilla para cerrar 4 fallas Témpano Gélido, después lleva el tótem a Xarantaur en el Campamento Tunka'lo."}}
D[13039] = {"Defender la Vanguardia",{"El señor cruzado Dalfors en La Vanguardia Argenta en Corona de Hielo te ha pedido que mates a 15 nerubianos de las Profundidades Olvidadas."}}
D[13040] = {"Curar lo incurable",{"El padre Gustav de La Vanguardia Argenta en Corona de Hielo te ha pedido que le lleves 10 glándulas de veneno de las Profundidades Olvidadas."}}
D[13041] = {"Acabar el envío",{"Llévale una calcedonia a Timothy Jones en Dalaran."}}
D[13042] = {"En las profundidades de las Cámaras Subterráneas",{"La Bruja Osaria en la cueva del poblado Njorndar te ha pedido que saques a golpes del aprendiz Osterkilgr información referente a los planes del Dr. Terrible.","","Después debes matar al aprendiz."}}
D[13043] = {"La suma es mayor que las partes",{"Monta y controla a Nergeld. Defiéndelo de los moradores de la Cámara de los Horrores hasta que el Dr. Terrible aparezca.","","Usa a Nergeld para matar al doctor y después habla con la Bruja Osaria en el poblado Njorndar."}}
D[13044] = {"Si hay supervivientes...",{"Habla con Penumbrius en La Vanguardia Argenta de Corona de Hielo."}}
D[13045] = {"Dentro del gran verdor",{"Rescata a 3 Cruzados Argenta capturados de la Ciudad de la Plaga y llévalos a la Enfermería de la Vanguardia en el centro de La Vanguardia Argenta. Si tienes éxito informa al alto señor Tirion Vadín."}}
D[13046] = {"Alimentar a Arngrim",{"Debes alimentar a Arngrim con 5 jormungar incorpóreos. Después, vuelve con la imagen congelada de Arngrim en Dun Niffelem.","","Debes ir al Valle de los Viejos Inviernos y usar el diente de Arngrim con los jormungar vagabundos que hay allí. Una vez que sean incorpóreos, deberás luchar contra ellos hasta que queden debilitados."}}
D[13047] = {"La venganza",{"Reúnete con Thorim cerca del Templo de Sabiduría. Informa del resultado del combate al rey Jokkum en Dun Niffelem."}}
D[13048] = {"Cuando el tiempo se volvió loco",{"Usa el Martillo del Conocimiento con las reliquias Taunka para armonizarlo con la época de Pezuña Tormentosa. Una vez haya sido armonizado con 6 reliquias de la época de Pezuña Tormentosa, habla con Xarantaur en el Campamento Tunka'lo."}}
D[13049] = {"Las armas del héroe",{"Recupera la lanza de Pezuña Tempestuosa y la malla de Pezuña Tempestuosa y vuelve con ellas ante Xarantaur, en el Campamento Tunka'lo."}}
D[13050] = {"Veranus",{"Thorim, en el Altar de la Tempestad, quiere que consigas 5 huevos de protodraco pequeños de los picos cerca del poblado Brunnhildar."}}
D[13051] = {"Violación territorial",{"Coloca los huevos de protodraco robados en lo alto del nido de la madre de linaje y vuelve al Templo de las Tormentas para hablar con Thorim."}}
D[13052] = {"Reconocimiento aéreo",{"La profesora Calvert quiere que cojas el vuelo a la Pista del Lago y que hables con el piloto Vic."}}
D[13053] = {"Buscando supervivientes",{"Ayuda a Zac Piñónflojo a completar el vuelo de prueba."}}
D[13054] = {"El rastreador perdido",{"Estás en esta misión"}}
D[13055] = {"Medicina de cueva",{"El rastreador Val'zij, en la Guarida de Gimorak quiere que obtengas 1 glándula de toxinas de jormungar y 8 hongos de cueva."}}
D[13056] = {"Siempre hay tiempo para la venganza",{"El rastreador Val'zij quiere que mates a Gimorak, que está dentro de la Guarida de Gimorak."}}
D[13057] = {"El Bancal de los Creadores",{"Busca a Thorim en el límite sureste del Bancal de los Creadores, al noroeste de Dun Niffelem."}}
D[13058] = {"Cambiar el curso del viento",{"Usa el Martillo del Conocimiento para viajar atrás en el tiempo y enfréntate al Viento del Norte como si fueras Pezuña Tempestuosa. Cuando Pezuña Tempestuosa caiga y deje caer el Cuerno de Furia Elemental, úsalo para acabar con el Viento del Norte. Después habla con Xarantaur en el Campamento Tunka'lo."}}
D[13059] = {"Venganza para los vargul",{"En Las Cámaras Subterráneas, Bethod Feigr quiere que tires su espada para desafiar al señor feudal Maleskara y que después lo mates en El Círculo de Sufrimiento."}}
D[13060] = {"Cuando todo lo demás falla",{"Habla con Ricket para usar el Artefacto de entrega propulsado D16 para profundizar en Las Cumbres Tormentosas."}}
D[13061] = {"Prepárate para la gloria",{"Habla con Lok'lira la Vieja Bruja en el poblado Brunnhildar."}}
D[13062] = {"El regalo de despedida de Lok'lira",{"Habla con Gretta la Mediadora en el poblado Brunnhildar."}}
