(function() local D = SUIQuestScopeData.L10n.frFR.Quest
D[1] = {"La quête de Kanrethad",{"Parlez à Kanrethad pour que vos talents, votre arme et votre monture vous soient rendus."}}
D[2] = {"La griffe de Serres-tranchantes",{"Apportez la Griffe de Serres-tranchantes à Senani Cœur-de-tonnerre, au poste de Bois-brisé, en Orneval."}}
D[5] = {"L'estomac qui gargouille",{"Parlez au Chef Grual."}}
D[6] = {"La prime pour Garrick Ladétrousse",{"Tuez Garrick Ladétrousse et rapportez sa tête à l'Adjoint Willem de l'Abbaye de Comté-du-nord."}}
D[7] = {"Le nettoyage du camp des kobolds",{"Tuez 8 Vermines kobolds, puis revenez voir le Maréchal McBride."}}
D[8] = {"Un marché de voleur",{"Livrez une Lettre à Renée, dans les Clairières de Tirisfal."}}
D[9] = {"Les champs de mort",{"Le Fermier Saldean vous a demandé de tuer 20 Gardiens des moissons."}}
D[10] = {"La rédemption de Scrimshank",{"Découvrez ce qu'est devenu le Géomètre Scrimshank, et rapportez son Équipement topographique au Grand géomètre Radiésthéflop, à Gadgetzan."}}
D[11] = {"Prime pour les gnolls Rivepatte",{"Apportez 8 Brassards peints de gnoll à l'Adjoint Rainer, à la Caserne."}}
D[12] = {"La milice du peuple",{"Tuez 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des sentinelles."}}
D[13] = {"La milice du peuple",{"Tuez 15 Pilleurs défias et 15 Pillards défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des sentinelles."}}
D[14] = {"La milice du peuple",{"Tuez 15 Malandrins défias, 5 Éclaireurs défias et 5 Truands défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des sentinelles."}}
D[15] = {"Enquête sur la crête aux échos",{"Tuez 8 Ouvriers kobolds, puis revenez faire votre rapport au Maréchal McBride."}}
D[16] = {"Procurer de l'eau à Gerard"}
D[17] = {"Rechercher les composants à Uldaman",{"Apportez 12 Champignons magenta à Ghak Touchesoins, à Thelsamar."}}
D[18] = {"La confrérie des voleurs",{"Apportez 8 Masques rouges à l’Adjoint Willem, à l'extérieur de l’Abbaye de Comté-du-nord."}}
D[19] = {"Tharil'zun",{"Apportez la Tête de Tharil'zun au maréchal Marris, dans les Carmines."}}
D[20] = {"La menace des Rochenoires",{"Rapportez 10 Haches détériorées au Maréchal Marris de Comté-du-lac."}}
D[21] = {"Règlement de comptes à Écho-Coron",{"Tuez 8 Travailleurs kobolds, puis revenez voir le Maréchal McBride, à l’Abbaye de Comté-du-nord."}}
D[22] = {"La tourte au foie de broche-tripes",{"Salma Saldean a besoin de 8 Foies de broche-tripes pour faire une Tourte au foie de broche-tripes."}}
D[23] = {"La patte d'Ursangous",{"Apportez la Patte d'Ursangous à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, à Orneval."}}
D[24] = {"La tête de Shadumbra",{"Apportez la Tête de Shadumbra à Senani Cœur-de-tonnerre, au Poste de Bois-brisé, dans Orneval."}}
D[25] = {"Impasse aux Serres-Rocheuses",{"Tuer 12 Elémentaires d'eau corrompus au lac Mystral, à l'est de la Perce des Serres, et au sud-ouest du poste de Bois-brisé.","","Faire une reconnaissance sur le kiosque du lac Mystral ; celui qui a vue sur l'avant-poste de l'Alliance.","","Retourner voir Mastok Torvesiffle, au poste de Bois-brisé, dans Orneval."}}
D[26] = {"Une leçon à apprendre",{"Parlez à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[27] = {"Une leçon à apprendre",{"Parlez à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[28] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l'apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l'épreuve."}}
D[29] = {"L'épreuve du lac",{"Trouver un Colifichet du sanctuaire dans le Lac Elune'ara, et l'apporter au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utiliser le Colifichet du sanctuaire.","","Vous devez parler à Tajarri, au sanctuaire, afin de terminer l'épreuve."}}
D[30] = {"L'épreuve du lion de mer",{"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l'endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.","","Apporter le Pendentif reformé à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[31] = {"Forme aquatique",{"Retournez aux Pitons du Tonnerre et montrez le Pendentif du lion de mer à Turak Totem-runique."}}
D[32] = {"L'ascension des silithides",{"Apportez le Rapport à Zilzibin Kongadok, à Orgrimmar."}}
D[33] = {"Les loups derrière la frontière",{"Apportez 8 Peaux de loup malade à Eagan Tannepeau, à l'extérieur de l’Abbaye de Comté-du-nord."}}
D[34] = {"Un indésirable",{"Martie Jainrose de Comté-du-lac vous a demandé de tuer Fouailleventre. Rapportez-lui ses défenses comme preuve."}}
D[35] = {"Inquiétudes supplémentaires",{"Le Maréchal Dughan vous a demandé de parler au Garde Thomas."}}
D[36] = {"Le ragoût de la marche de l'Ouest",{"Verna Froncebouille vous a demandé d'apporter la Recette du ragoût de la marche de l'Ouest à Salma Saldean."}}
D[37] = {"Trouver les gardes disparus",{"Le Garde Thomas vous a demandé d'aller au nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai."}}
D[38] = {"Le ragoût de la marche de l'Ouest",{"Salma Saldean vous a demandé 3 morceaux de Viande filandreuse de vautour, 3 Groins de broche-tripes, 3 Yeux de murloc et 3 Okras."}}
D[39] = {"Remettre le rapport de Thomas",{"Avertir le maréchal Dughan de Comté-de-l'or."}}
D[40] = {"Péril en la rivière",{"Remy \"Deux fois\" veut que vous parliez au maréchal Dughan à Comté-de-l'or."}}
D[45] = {"La destinée de Rolf",{"Fouillez le village des murlocs pour trouver Rolf ou des traces de sa mort."}}
D[46] = {"Des primes pour les murlocs",{"Rapportez 8 Ailerons de murloc au Garde Thomas au pont, à l'est d’Elwynn."}}
D[47] = {"L'échange de poussière d'or",{"Rapporter 10 Poussières d'or à Remy \"Deux fois\" à Comté-de-l'or. La Poussière d'or se récupère sur les kobolds dans la forêt d'Elwynn."}}
D[48] = {"Doux whisky",{"Rapportez de l'Eau de source sacrée à Tristevin Tonnebière."}}
D[49] = {"Doux whisky",{"Tristevin Tonnebière vous a demandé un Sac d'orge, un Sac de seigle et un Sac de maïs."}}
D[50] = {"Doux whisky",{"Tristevin Tonnebière vous a demandé du Vrai-argent."}}
D[51] = {"Doux whisky",{"Apportez une Branche de sycomore à Tristevin Tonnebière."}}
D[52] = {"Protéger la frontière",{"Tuer 8 Rôdeurs et 5 Jeunes ours des forêts, et revenir voir le garde Thomas au pont, à l'est d'Elwynn."}}
D[53] = {"Doux whisky",{"Apportez un Fagot de chêne noirci à Tristevin Tonnebière."}}
D[54] = {"Rapport pour Comté-de-l'or",{"Apporter les documents du maréchal McBride au maréchal Dughan de Comté-de-l'or."}}
D[55] = {"Morbent Lagangrène",{"Utilisez le Fléau de Morbent sur Morbent Lagangrène, tuez-le, puis rapportez le Fléau de Morbent à Sven, dans son camp."}}
D[56] = {"Les Veilleurs",{"Le Commandant Althea Bouclenoire de Sombre-comté vous a demandé de tuer 8 Guerriers squelettes et 6 Mages squelettes."}}
D[57] = {"Les Veilleurs",{"Le commandant de Sombre-comté, Althea Bouclenoire, vous a demandé de tuer 15 Démons squelettes et 15 Squelettes infernaux."}}
D[58] = {"Les Veilleurs",{"Le Commandant de Sombre-comté, Althea Bouclenoire, vous a demandé de tuer 20 Répandeurs de peste dans le mausolée est de Colline-aux-Corbeaux."}}
D[59] = {"Les armures de cuir et d'étoffe",{"Donnez le Bon pour une pièce d'armure de Hurlevent à Sara Timberlain."}}
D[60] = {"Les bougies de kobolds",{"Rapporter 8 Grandes bougies à William Pilon de Comté-de-l'or."}}
D[61] = {"Une cargaison pour Hurlevent",{"Livrez la Cargaison de William à Morgan Pilon dans le Quartier commerçant de Hurlevent."}}
D[62] = {"La mine de Fondugouffre",{"Explorer la mine de Fondugouffre, puis revenir voir le maréchal Dughan de Comté-de-l'or."}}
D[63] = {"L'appel de l'eau",{"Abattez la Manifestation d'eau corrompue et placez les Bracelets de manifestation corrompue avec le reste d'eau pure sur le brasero de la Fontaine éternelle, dans la forêt des Pins argentés."}}
D[64] = {"Le cadeau oublié",{"Le Fermier Froncebouille vous a demandé de retrouver sa Montre, qui se trouve dans la penderie de sa ferme près du champ de citrouilles, à l'ouest."}}
D[65] = {"La Confrérie défias",{"Gryan Roidemantel vous a demandé de parler à Wiley à Comté-du-lac."}}
D[66] = {"La légende de Stalvan",{"Aller voir le Greffier Daltry à l'hôtel de ville de Sombre-comté."}}
D[67] = {"La légende de Stalvan",{"Allez à l'école de Ruisselune, et rapportez au Greffier Daltry des informations récentes sur Stalvan."}}
D[68] = {"La légende de Stalvan",{"Rapportez la Lettre poussiéreuse au greffier Daltry."}}
D[69] = {"La légende de Stalvan",{"Allez à l'Auberge de la Fierté du lion pour voir si quelqu'un a entendu parler de Stalvan."}}
D[70] = {"La légende de Stalvan",{"Retrouvez la Vieille lettre de Stalvan dans le coffre, et remettez-la au quartier du Canal, à Hurlevent."}}
D[71] = {"Faire son rapport au garde Thomas",{"Rapporter les Médaillons de Rolf et Malakai au garde Thomas au pont est d'Elwynn."}}
D[72] = {"La légende de Stalvan",{"Recherchez un indice dans le tas d'affaires."}}
D[74] = {"La légende de Stalvan",{"La Page de journal déchirée que vous avez découverte est votre deuxième indice."}}
D[75] = {"La légende de Stalvan",{"Le Maréchal Haggard vous a demandé d'aller chercher la Page de journal décolorée dans le coffre, à l'étage."}}
D[76] = {"La mine Veine-de-jaspe",{"Explorer la Mine Veine-de-jaspe, puis faites votre rapport au maréchal Dughan de Comté-de-l'or."}}
D[77] = {"Une situation délicate",{"Récupérez 10 bouteilles de Houle au miel des Hinterlands dans des caisses se trouvant aux environs de la base abandonnée de la Horde, au rocher de l'Affût."}}
D[78] = {"La légende de Stalvan",{"Prenez la Page de journal décolorée et montrez-la à Smitts l'aubergiste à Sombre-comté, au Bois de la Pénombre."}}
D[79] = {"La légende de Stalvan",{"Portez les pages au Commandant Bouclenoire."}}
D[80] = {"La légende de Stalvan",{"Montrer au Greffier Daltry la Page de journal maculé de sang."}}
D[81] = {"La livraison de Houle",{"Livrez le tonneau à Dran Droffers, à Orgrimmar."}}
D[82] = {"Enquête au Repaire nuisible",{"Apportez cinq morceaux de Centipaars du Repaire nuisible à l'Alchimiste Pilonzugg, à Gadgetzan."}}
D[83] = {"Articles rouges en lin",{"Apportez 6 Masques rouge en lin à Sara Timberlain, au Camp de bûcherons du Val d'est."}}
D[84] = {"Revenir voir Billy",{"Apportez la Tourte de panse de porc à Billy Maclure, aux Vignes des Maclure."}}
D[85] = {"Le collier perdu",{"Parlez à Billy Maclure."}}
D[86] = {"Une tourte pour Billy",{"Apportez 4 morceaux de Viande de sanglier à Tatie Bernice Champierreux, à la ferme des Champierreux."}}
D[87] = {"Dent-d'or",{"Rapportez le Collier de Bernice à « Tatie » Bernice Champierreux à la ferme des Champierreux."}}
D[88] = {"Princesse doit mourir !",{"Tuez Princesse, prenez son collier, puis apportez-le à Maman Champierreux, à la ferme des Champierreux."}}
D[89] = {"Le pont sur le lac",{"Apportez 5 Clous en fer et 5 Rivets en fer au Contremaître Oslow, à Comté-du-lac."}}
D[90] = {"Kébab de loup assaisonné",{"Récupérez 10 Steaks de loup et des Herbes aromatiques de Hurlevent, puis retournez voir le chef Grual à Sombre-comté."}}
D[91] = {"La loi de Salomon",{"Apportez 10 Pendentifs sombrepoil au Bailli Conacher, à l'Hôtel de ville de Comté-du-lac."}}
D[92] = {"Goulash des Carmines",{"Le chef Breanna de Comté-du-lac vous a demandé 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d'araignée."}}
D[93] = {"Gâteaux au crabe brun",{"Récupérez 6 Pattes d'araignée fondantes et apportez-les au chef Grual de Sombre-comté."}}
D[94] = {"L'œil attentif",{"Placez le Glyphe d'Azora sur la Statue de lion, près de la Tour d'Ilgalar dans les Carmines."}}
D[95] = {"La vengeance de Sven",{"Allez à la ferme de Sven et trouvez ce qui a été enterré derrière la vieille souche d'arbre."}}
