D[264] = {"Jusqu'à ce que la mort nous sépare",{"Placer le pendentif de Clarice sur la tombe de Yuriv, dans la forêt des Pins argentés."}}
D[265] = {"L'obscure recherche se poursuit",{"Voir si d'autres habitants ont des indices concernant l'obscure silhouette."}}
D[266] = {"Une enquête à l'auberge",{"Chercher à l'auberge des indices concernant l'obscure silhouette."}}
D[267] = {"La menace trogg",{"Rapportez 8 Dents de pierre de troggs au Capitaine Rudagite à la Tour de garde méridionale."}}
D[268] = {"Retourner voir Sven",{"Retourner voir Sven avec le journal complété de la Tremblote."}}
D[269] = {"À la recherche de la sagesse",{"Donner le Journal complété de la Tremblote à l'évêque Farthing à Hurlevent."}}
D[270] = {"La Flotte perdue",{"Aller au port de Menethil, dans les Paluns, et parler à Glorin Front-d'acier."}}
D[271] = {"La vengeance de Vyrin",{"Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Jeune au pavillon des Pérégrins."}}
D[272] = {"L'épreuve du lion de mer",{"Trouver le Demi-pendentif d'agilité aquatique et le Demi-pendentif d'endurance aquatique. Parler aux habitants de Reflet-de-Lune pour obtenir des indices quant à l'endroit où ces objets se trouvent.","","Reformer le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire ceci.","","Apporter le Pendentif reformé à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune."}}
D[273] = {"Approvisionnement du site de fouilles",{"Aller voir Huldar."}}
D[274] = {"Une sombre menace se dessine",{"Ashlan Rictus-de-pierre vous demande de retourner voir l'Ingénieur en chef Hinderweir à Loch Modan pour l'informer de la nouvelle découverte."}}
D[275] = {"Fièvre sur le pays",{"Tuer 8 Rampants des tourbières, puis retourner voir Rethiel le Gouverneur vert, dans les Paluns."}}
D[276] = {"Piétinements de pattes",{"Tuer 15 Gnolls Poils-moussus et 10 Bâtards Poils-moussus puis retourner voir Rethiel, le Gouverneur vert, dans les Paluns."}}
