D[3130] = {"Contre les Hainecrête",{"Se présenter devant Latronicus Lancelune au bastion de Pennelune."}}
D[3141] = {"Loramus",{"Écouter l'histoire de Loramus Thalipedes."}}
D[3161] = {"La gahz'ridienne",{"Marvon Chercherivet, à Tanaris, vous a demandé de ramasser 30 Ornements en gahz'ridienne."}}
D[3181] = {"La corne de la bête",{"Porter la Corne Gigantesque de Margol à la Montagnarde Minigravillon."}}
