D[3377] = {"Prière à Elune",{"Écouter le récit de Zamael."}}
D[3378] = {"Prière à Elune",{"Trouver la Prière à Elune et l'apporter à Astarii Cherchétoile à Darnassus."}}
D[3379] = {"Les tisseuses d'ombre",{"Tuer le groupe de braconniers Ombresoie qui rôde dans la gorge des Vents brûlants. Nilith a de bonnes raisons de croire qu'ils doivent être exterminés tous les cinq. Retourner voir Nilith dans la gorge des Vents brûlants lorsque vous aurez terminé."}}
D[3380] = {"Le Temple englouti",{"Trouver Marvon Chercherivet à Tanaris."}}
D[3381] = {"Une rencontre avec le maître",{"Apporter 2 Plumes d'hippogriffe sans défaut à Sanath Lim-yo, en Azshara, si vous souhaitez parler à son maître."}}
D[3382] = {"Doux whisky",{"Défendre la capitaine Vanessa Beltis, son équipage et les passagers de \"l'Horizon\" contre l'attaque des nagas. La capitaine Vanessa Beltis doit survivre."}}
D[3385] = {"Le Sous-marché",{"Tuer le Maître d'artisanat Kovic et son agent Clonk. Récupérer sur son corps la Sacoche du marchand et l'apporter à Nilith."}}
D[3402] = {"Le Sous-marché",{"Parler à Vizzklick à Gadgetzan."}}
