D[3633] = {"Ingénierie des gobelins",{"Pour en apprendre davantage sur l'ingénierie gobeline, apporter le Manuel d'Ingénierie à Nixx Elastirouage, à Gadgetzan, en Tanaris."}}
D[3634] = {"Ingénierie des gnomes",{"Pour en apprendre davantage sur l'ingénierie gnome, apporter le Manuel d'Ingénierie au maître-artisan Suprétincelle, à Forgefer."}}
