D[3638] = {"The Pledge of Secrecy",{"If you agree to become a Goblin Engineer, then right-click on the Pledge of Secrecy and speak once more with Nixx Sprocketspring in Gadgetzan."}}
D[3639] = {"Montrez votre travail",{"Apporter 20 Grandes Bombes en fer, 20 Dynamites Solides et 5 Moutons Explosifs à Nixx Elastirouage dans Gadgetzan."}}
D[3640] = {"Le Vœu du secret",{"If you agree to become a Gnome Engineer, then right-click on the Pledge of Secrecy and speak once more with Tinkmaster Overspark in Ironforge."}}
D[3641] = {"Montrez votre travail",{"Apportez 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître artisan Suprétincelle, à Forgefer."}}
D[3642] = {"Le vœu du secret"}
D[3643] = {"Montrez votre travail",{"Apportez 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés à Orguignard Odipnoticus à Baie-du-Butin."}}
