D[3661] = {"Dans les faveurs d'Elune ?",{"Collecter 15 Plumes d'Indomptable dans les Hinterlands, pour Erelas Ambreciel au village de Rut'theran."}}
D[3681] = {"Le Tome de divinité",{"Parler à Duthorian Rall à Hurlevent."}}
D[3701] = {"Les ruines fumantes de Thaurissan",{"Aller dans les ruines de Thaurissan, dans les Steppes ardentes. Récupérer des informations sur les Reliques de Thaurissan, puis retourner auprès de l'Historienne royale Archesonus."}}
D[3702] = {"Les ruines fumantes de Thaurissan",{"Écouter l'historienne royale Archesonus raconter l'histoire de Thaurissan."}}
D[3721] = {"Un OOX rien que pour vous"}
D[3741] = {"Le collier d'Hilary",{"Trouver le Collier d'Hilary et le rapporter à Hilary à Comté-du-lac."}}
D[3761] = {"L'humus d'Un'Goro",{"Apporter 20 Échantillons d'humus d'Un'Goro à Ghede, aux Pitons du Tonnerre."}}
D[3762] = {"L'aide à l'archidruide Totem-runique",{"Parler à l'archidruide Hamuul Totem-runique aux Pitons du Tonnerre."}}
D[3763] = {"L'aide à l'archidruide Forteramure",{"Parler à l'archidruide Fandral Forteramure à Darnassus."}}
D[3764] = {"L'humus d'Un'Goro",{"Apporter 20 échantillons d'Humus d'Un'Goro à Jenal dans l'Enclave cénarienne à Darnassus."}}
D[3765] = {"La dépravation au loin",{"Aller voir Gershala Murmenuit à Auberdine."}}
D[3781] = {"Recherches sur la fibre d'aurore",{"Apporter le Bon pour des graines de l'archidruide à Mathrengyl Pasdelours dans l'Enclave cénarienne à Darnassus."}}
D[3782] = {"La recherche sur la Fibre d'aurore",{"Apporter le Bon pour des graines à Bashana Totem-runique aux Pitons du Tonnerre."}}
D[3783] = {"Yéti ? Y es-tu ?",{"Récupérez 10 Fourrures épaisses de yéti pour Umi Sarcafroisse, à Long-guet."}}
D[3784] = {"L'aide à l'archidruide Totem-runique",{"Parler à l'archidruide Hamuul Totem-runique aux Pitons du Tonnerre."}}
D[3785] = {"Recherches sur la fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux échantillons d'Humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Mathrengyl Pasdelours à Darnassus."}}
D[3786] = {"Recherches sur la Fibre d'aurore",{"Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendis et deux Échantillons d'humus d'Un'Goro pour essayer de cultiver des Fibres d'aurore.","","Apporter 10 Fibres d'aurore à Bashana Totem-runique aux Pitons du Tonnerre."}}
