D[4182] = {"La menace des draconiens",{"Tuer 15 Rejetons noirs, 10 Draconides noirs, 4 Wyrmides noirs et 1 Drake noir."}}
D[4183] = {"Les véritables maîtres",{"Voyager jusqu'à Comté-du-lac, dans les Carmines et remettre la Lettre d'Helendis Ruissecorne au Magistrat Salomon."}}
D[4184] = {"Les véritables maîtres",{"Voyager jusqu'à Hurlevent et remettre la Demande d'aide de Salomon au roi Varian Wrynn.","","Le roi demeure dans le Donjon de Hurlevent."}}
D[4185] = {"Les véritables maîtres",{"Parler au généralissime Bolvar Fordragon après avoir parlé à dame Katrana Prestor."}}
D[4186] = {"Les véritables maîtres",{"Apporter le Décret de Wrynn au Magistrat Salomon à Comté-du-lac."}}
D[4201] = {"Le philtre d'amour",{"Apporter 4 Gromsang, 10 Veines d'argent de géant et la Fiole de Nagmara remplie à la gouvernante Nagmara dans les Profondeurs de Rochenoire."}}
D[4221] = {"La fleur-de-vent corrompue"}
D[4222] = {"La fleur-de-vent corrompue"}
D[4223] = {"Les véritables maîtres",{"Parler au maréchal Maxwell dans les Steppes ardentes."}}
D[4224] = {"Les véritables maîtres",{"Parlez à John le Loqueteux."}}
D[4241] = {"Maréchal Windsor",{"Partir pour le mont Rochenoire au nord-ouest et pénétrer dans les Profondeurs de Rochenoire. Découvrir ce qu'il est advenu du Maréchal Windsor.","","Vous vous souvenez que John le Loqueteux a dit que Windsor avait été traîné en prison."}}
D[4242] = {"Espoir abandonné",{"Apporter les mauvaises nouvelles au Maréchal Maxwell à la Veille de Morgan, dans les Steppes ardentes."}}
D[4243] = {"À la poursuite d'A-mi 01",{"Trouver A-mi 01 dans le Cratère d'Un'Goro."}}
D[4244] = {"À la poursuite d'A-mi 01",{"Trouver une Armature en mithril et retourner auprès d'A-mi 01 dans le Cratère d'Un'Goro."}}
D[4245] = {"À la poursuite d'A-mi 01",{"Escorter A-mi 01 sur le chemin du retour jusqu'à Karna Songerrance dans le Cratère d'Un'Goro."}}
D[4261] = {"Esprit d'un ancien",{"Escorter Arei jusqu'à un lieu sûr, puis parler à Kayneth Mortebrise au Chant des forêts, dans l'est d'Orneval."}}
D[4262] = {"Grand seigneur Pyron",{"Tuer le Grand seigneur Pyron.","","Jalinda vous a dit qu'il gardait la carrière. Peut-être devriez-vous chercher à cet endroit ?"}}
D[4263] = {"Incendius !",{"Trouver le Seigneur Incendius dans les Profondeurs de Rochenoire et le détruire !"}}
D[4264] = {"Une note chiffonnée",{"Il se peut que vous ayez simplement buté sur quelque chose qui pourrait intéresser le maréchal Windsor au plus haut point. Il reste peut-être encore un peu d'espoir, après tout..."}}
D[4265] = {"L'évasion de la ruche",{"Libérer Raschal de la ruche de Zukk'ash.","","Revenir voir Ginro Attisâtre au bastion de Pennelune et lui dire que Raschal est sain et sauf."}}
D[4266] = {"Accueil d'un héros",{"Parler à Shandris Pennelune dans le bastion de Pennelune."}}
D[4267] = {"L'ascension des silithides",{"Apporter le Rapport de Raschal à Gracina Forcesprit à Darnassus."}}
D[4281] = {"La livraison à Thalanaar",{"Apportez le Vieux colis à Falfindel Gardevoie, à Thalanaar."}}
D[4282] = {"Un espoir en lambeaux",{"Rapporter les Informations égarées du maréchal Windsor.","","Le maréchal Windsor pense qu'ils sont détenus par le seigneur golem Argelmach et par le général Forgehargne."}}
D[4283] = {"CINQUANTE ! OUI !",{"Récupérez 50 Médaillons de Rochenoire."}}
D[4284] = {"Cristaux de puissance",{"Récupérer 7 Cristaux de puissance de chaque couleur (rouge, bleu, jaune et vert). Les apporter à J.D. Collie au refuge des Marshal."}}
D[4285] = {"Le Pylône nord",{"Découvrir l'emplacement du Pylône de cristal nord dans le Cratère d'Un'Goro."}}
D[4286] = {"Du beau matériel",{"Trouvez 20 Sacoches Sombrefer."}}
