D[4740] = {"On recherche : Fondeboue !",{"Trouver et tuer le murloc connu sous le nom de Fondeboue. On pense que la créature défend les huttes des murlocs au sud d'Auberdine près de l'eau.","","Annoncer la mort de Fondeboue à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4741] = {"Les gardiens sauvages",{"Trull Faillemort à Gangrebois veut que vous chassiez 13 Chouettards lunaires."}}
D[4742] = {"Le Sceau d'ascension",{"Trouver les trois gemmes de commandement : la Gemme de Brûleronce, la Gemme de Pierre-du-pic et la Gemme de Hache-sanglante. Rapportez-les, ainsi que le Sceau d'ascension non décoré, à Vaelan.","","Les généraux, comme vous l'a dit Vaelan, sont : le maître de guerre Voone de Brûleronce ; le généralissime Omokk des Pierres-du-pic ; et le seigneur Wyrmthalak de Hache-sanglante."}}
D[4743] = {"Le Sceau d'ascension",{"Allez à la tourbière du Ver dans le marécage d'Âprefange. Trouvez l'ancien drake, Brandeguerre, et frappez-le sans merci jusqu'à ce que sa volonté soit brisée.","","À cet instant précis, vous devez placer le Sceau d'ascension brut devant l'énorme bête. Vous devez ensuite utiliser rapidement l'Orbe d'énergie draconique sur sa forme affaiblie et prendre possession de ses facultés mentales. Contrôlez la bête et dirigez les flammes du Vol noir sur le Sceau d'ascension brut !"}}
D[4761] = {"Thundris Tissevent",{"Parler à Thundris Tissevent, à Auberdine."}}
D[4762] = {"La Bondissante",{"Aller au nord d'Auberdine, à la première chute d'eau, le long de la Bondissante et prélever un échantillon de l'eau de l'étang.","","Retourner voir Thundris Tissevent, à Auberdine, avec le Prélèvement de la Bondissante."}}
D[4763] = {"La corruption des Noirbois",{"Remplir le Bol de purification vide au Puits de lune d'Auberdine.","","Collecter un échantillon de fruit, de noix et de céréales dans les camps nord des furbolgs Noirbois.","","Mélanger les échantillons de nourriture à l'eau du bol et le placer à proximité du feu le plus proche de la rivière Bondissante, au camp nord. Cela fera venir le satyre corrupteur.","","Prendre son Talisman de corruption et l'apporter à Thundris Tissevent, à Auberdine."}}
D[4764] = {"Le fermoir de Frèteruine",{"Apporter le Fermoir de Frèteruine à Mayara Luisaile, dans les Steppes ardentes."}}
D[4765] = {"La livraison à Bellornière",{"Apporter la Caisse de Bellornière au Comte Remington Bellornière au Donjon de Hurlevent, à Hurlevent."}}
D[4766] = {"Mayara Luisaile",{"Parler à Mayara Luisaile à la Veille de Morgan, dans les Steppes Ardentes."}}
D[4767] = {"Le coursier du vent",{"Apporter 10 Œufs de wyverne de Haut-perchoir à Elu au poste de Librevent."}}
D[4768] = {"La tablette de Sombrepierre",{"Apportez la Tablette de Sombrepierre à l'ombremage Vivian Lagrave à Kargath."}}
D[4769] = {"Vivian Lagrave et la tablette de Sombrepierre",{"Parler à l'ombremage Vivian Lagrave."}}
D[4770] = {"Vers le pays natal",{"Escorter Pao'ka Montagne-agile à partir de Haut-perchoir, puis parler à Motega Crin-de-feu au poste de Blanc-relais."}}
D[4771] = {"Le gambit de l'aube",{"Placer le Gambit de l'aube dans la Chambre des visions de la Scholomance. Vaincre Vectus, puis retourner auprès de Betina Bigglezink."}}
D[4781] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter une Barre d'or à Xizk Beaupiqué dans la vallée de Strangleronce."}}
D[4782] = {"Les composants de la robe sanglante dorée enchantée",{"Retourner voir Menara Taillevide dans les Tarides."}}
D[4783] = {"Les composants de la robe sanglante dorée enchantée",{"Apporter 10 Fioles de sang de Fielfurie et 1 Pierre infernale inférieure à Menara Taillevide dans les Tarides."}}
D[4784] = {"Les composants de la robe sanglante dorée enchantée",{"Apportez du Fil d'or fin, 2 Charbons ardents et un Fragment d'âme à Menara Taillevide dans les Tarides."}}
D[4785] = {"Fil d'or fin"}
D[4786] = {"La Robe terminée",{"Attendre que Menara Taillevide ait terminé votre robe puis lui parler de nouveau."}}
D[4787] = {"L'œuf antique",{"Apportez l'Oeuf antique à Yeh'kinya à Tanaris."}}
D[4788] = {"Les dernières tablettes",{"Apportez la Cinquième et la Sixième tablette Mosh'aru au Prospecteur Botte-de-fer à Tanaris."}}
D[4801] = {"L'E'ko des Sabres-de-givre"}
D[4802] = {"L'E'ko des Tombe-hiver"}
D[4803] = {"L'E'ko des Crocs acérés"}
D[4804] = {"L'E'ko de Noroît"}
D[4805] = {"L'E'ko des Chardons de Glace"}
D[4806] = {"L'E'ko de Cognegivre"}
D[4807] = {"L'E'ko des Indomptables"}
D[4808] = {"Felnok Ressordacier",{"Donner la Lettre de Brikolette à Felnok Ressordacier à Long-guet, à Berceau-de-l'Hiver."}}
D[4809] = {"Cornes de Noroît",{"Collectez 8 Cornes intactes de Noroît."}}
D[4810] = {"Retourner voir Brikolette",{"Apporter le Paquet de Felnok à Brikolette Toutevapeur à la Corniche des flammes, dans les Steppes ardentes."}}
D[4811] = {"Le cristal rouge",{"Voyager en direction de l'est en partant d'Auberdine et chercher un gros cristal rouge le long de la chaîne de montagne est de Sombrivage. Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4812] = {"Comme l'eau tombe en cascade",{"Remplir le Tube d'eau vide au Puits de lune d'Auberdine, puis chercher le cristal rouge le long des falaises des montagnes à l'est de Sombrivage."}}
D[4813] = {"Les fragments à l'intérieur",{"Aller faire un rapport de ce que vous avez trouvé à la Sentinelle Glynda Nal'Shea à Auberdine."}}
D[4821] = {"L'œuf étrange",{"Rapporter l'Œuf étrange à Hagar Sabot-de-foudre au Poste de Librevent."}}
D[4822] = {"Je veux une glaaaaace!"}
D[4841] = {"Pacifier les centaures",{"Tuer 12 Eclaireurs galak, 10 Querelleurs galak, et 6 Chasse-vent galak, puis retourner auprès du garde-falaise Longue-corne au Poste de Librevent."}}
D[4842] = {"Sources étranges",{"Suivre les instructions de Donova Antreneige, puis faire un rapport."}}
D[4861] = {"Les Indomptables enragés",{"Localiser le camp démoli et les fournitures de Jaron Sculptepierre, au sud du Berceau-de-l'Hiver."}}
D[4862] = {"Mauvais",{"Aller au Pic Rochenoire et ramasser 15 Œufs d'araignée du pic pour Kibler.","","Ces œufs peuvent être trouvés à proximité des araignées."}}
D[4863] = {"Les Indomptables enragés",{"Trouver le chariot saccagé de Jaron Sculptepierre."}}
D[4864] = {"Les Indomptables enragés",{"Ramasser les Fournitures de Jaron dans la neige, puis trouver l'Indomptable qui a volé l'amulette dont Jaron a parlé.","","Rapporter les fournitures de Jaron et l'Amulette de la plume bleue à Jaron Sculptepierre dans son pavillon au Berceau-de-l'Hiver."}}
D[4865] = {"Serpent sauvage",{"Faire un rapport de vos trouvailles à Motega Crin-de-feu au Poste de Blanc-relais, aux Milles pointes."}}
D[4866] = {"Le lait matriarcal",{"Vous trouverez la Matriarche Couveuse au cœur du pic Rochenoire. Attaquez-la et poussez-la à vous empoisonner. Vous devrez sans doute la tuer. Une fois empoisonné, trouvez John le Loqueteux afin qu'il puisse prélever un échantillon."}}
D[4867] = {"Urok Hurleruine",{"Lire le Parchemin de Warosh. Apporter le Mojo de Warosh à Warosh."}}
D[4881] = {"Complot d'assassinat",{"Prévenir Kanati Nuage-gris au Poste de Blanc-relais qu'un complot le menace."}}
D[4882] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Trull Faillemort au Poste de la Vénéneuse."}}
D[4883] = {"Secrets gardés",{"Apporter le Collier de plumes bleues à Nara Crin-sauvage."}}
D[4901] = {"Les gardiens de l'autel",{"Protéger Ranshalla pendant qu'elle s'efforce de réactiver l'Autel d'Elune. Faire un rapport de vos découvertes à Erelas Ambreciel, au village de Rut'theran."}}
D[4902] = {"Les Indomptables d'Elune",{"Parler à l'archidruide Fandral Forteramure, à Darnassus."}}
D[4903] = {"Ordre du chef de guerre",{"Tuer le généralissime Omokk, le maître de guerre Voone et le seigneur Wyrmthalak. Récupérer les Importants documents Rochenoire. Retourner voir le chef de guerre Sangredent à Kargath une fois la mission accomplie."}}
D[4904] = {"Libre, enfin !",{"Escorter Lakota Chant-du-vent hors de la Cime de Noir-nuage, puis parler à Thalia Peau-d'ambre au Poste de Librevent."}}
D[4906] = {"Plus de corruption",{"Eridan Ventebleu de Gangrebois veut que vous tuiez 8 Implorateurs de l'enfer Jadefeu, 8 Traîtres Jadefeu, 8 Entourloupeurs Jadefeu et Xavaric. Revenez auprès d'Eridan une fois la tâche accomplie."}}
D[4907] = {"Brikolette Toutevapeur",{"Parler à Brikolette Toutevapeur à la Corniche des flammes, dans les Steppes ardentes."}}
D[4921] = {"Disparition au combat",{"Trouver la femme de Mankrik puis retourner le voir à la Croisée."}}
D[4941] = {"Sagesse d'Eitrigg",{"Parler à Eitrigg, à Orgrimmar. Après avoir discuté avec Eitrigg, demander conseil à Thrall.","","Vous avez déjà vu Eitrigg dans les Appartements de Thrall."}}
D[4961] = {"La purification de l'Orbe d'Orahil",{"Tuer le Démon de l'Orbe, puis parler à Tabetha."}}
D[4962] = {"Un éclat de gangrechien",{"Prendre le Rubis de Felhas et l'utiliser sur l'un des gangrechiens de Désolace. Quand vous aurez réussi, rapporter le Rubis de Felhas et l'Esprit de gangrechien emprisonné à Menara Taillevide, dans les Tarides."}}
D[4963] = {"Un éclat d'infernal",{"Prendre l'Emeraude d'Infus et l'utiliser sur l'un des Infernaux qui se trouvent en Désolace. Quand vous aurez réussi, rapporter l'Emeraude d'Infus et l'Esprit d'Infernal emprisonné à Menara Taillevide, dans les Tarides."}}
D[4964] = {"L'Orbe complet de Dar'Orahil",{"Attendre que Menara Taillevide termine l'Orbe de Dar'Orahil, puis lui reparler."}}
D[4965] = {"Connaissance de l'Orbe d'Orahil",{"Parlez à Menara Taillevide, dans les Tarides."}}
D[4966] = {"Protéger Kanati Nuage-gris",{"Protéger Kanati Nuage-gris contre l'attaque centaure."}}
D[4967] = {"Connaissance de l'Orbe d'Orahil",{"Parlez à Menara Taillevide, dans les Tarides."}}
D[4968] = {"Connaissance de l'Orbe d'Orahil",{"Parlez à Menara Taillevide, dans les Tarides."}}
D[4969] = {"Connaissance de l'Orbe d'Orahil",{"Parlez à Menara Taillevide, dans les Tarides."}}
D[4970] = {"Provisions de sabres-de-givre",{"Collecter 5 morceaux de Viande de Croc acéré et 5 morceaux de Viande de Noroît pour Rivern Givrevent du Berceau-de-l'Hiver."}}
D[4971] = {"Une question de temps",{"Utiliser le Déplaceur temporel à côté de l'un des silos d'Andorhal pour révéler des Parasites temporels.","","Tuer 10 Parasites temporels et rapporter le Déplaceur temporel à Chromie, à l'auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4972] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal, dans des coffrets qui se trouvent parmi les décombres de la ville, et les rapporter à Chromie à l'Auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4973] = {"Arrêt du temps",{"Trouver 5 Montres d'Andorhal parmi les décombres de la ville et les rapporter à Chromie à l'Auberge d'Andorhal, dans les Maleterres de l'ouest."}}
D[4974] = {"Pour la Horde !",{"Aller au Pic Rochenoire et tuer le Chef de guerre, Rend Main-noire. Prendre sa tête et retourner à Orgrimmar."}}
D[4975] = {"L'Orbe complet de Noh'Orahil",{"Attendre que Menara Taillevide ait terminé l'Orbe de Noh'Orahil, puis lui reparler."}}
D[4976] = {"Rapporter l'Orbe purifié",{"Rapporter l'Orbe infernal purifié à Menara Taillevide, dans les Tarides."}}
D[4981] = {"Agent Bijou",{"Allez au Pic Rochenoire et découvrez ce qui est arrivé à Bijou."}}
D[4982] = {"Les affaires de Bijou",{"Trouver les Affaires de Bijou et les lui rapporter. Elle vous a dit les avoir cachées dans le niveau inférieur de la ville."}}
D[4983] = {"Rapport de reconnaissance de Bijou",{"Rapporter le Rapport de reconnaissance de Bijou au Grand-maître Lexlort, à Kargath."}}
D[4984] = {"La faune et la flore souffrent aussi",{"Détruire 8 Loups malades, puis retourner voir Mulgris Rivière-profonde, au Repaire putride dans les Maleterres de l'ouest."}}
D[4985] = {"La faune et la flore souffrent aussi",{"Détruire 8 Grizzlys malades, puis retourner voir Mulgris Rivière-profonde au Repaire putride, dans les Maleterres de l'ouest."}}
D[4986] = {"La branche de chêne glyphée",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, à Darnassus. Aller solliciter l'assistance de l'un des druides, là-bas."}}
D[4987] = {"La branche de chêne glyphée",{"D'après la magie contenue dans la Branche de chêne à glyphes, le druide tauren voulait qu'elle soit apportée au Cercle cénarien, aux Pitons du Tonnerre. Aller solliciter l'assistance de l'un des druides, là-bas."}}
D[5001] = {"Les affaires de Bijou",{"Retrouver les Affaires de Bijou et les lui rapporter. Bonne chance !"}}
D[5002] = {"Message à Maxwell",{"Se rendre dans les Steppes ardentes et confier les Renseignements de Bijou au maréchal Maxwell."}}
D[5021] = {"Mieux vaut tard que jamais",{"Le discours incohérent de la femme fantomatique indique qu'elle a besoin qu'on livre un colis pour elle. Elle a dit que le colis se trouvait là où se trouve son cheval. Le fantôme est incompréhensible lorsqu'il s'agit de préciser où se trouve son cheval ou l'endroit où le paquet doit être livré."}}
D[5022] = {"Mieux vaut tard que jamais",{"Rendre visite aux Facteurs royaux de Hurlevent pour apprendre l'adresse d'une certaine Emma Gangrepierre. En général, il y a un officier du recensement à l'Hôtel de ville."}}
D[5023] = {"Mieux vaut tard que jamais",{"Se renseigner auprès des Surveillants royaux de Fossoyeuse pour apprendre l'adresse d'un certain Jeremiah Gangrepierre. En général, il y a un officier du recensement près du bureau d'inscription des guildes et tabards."}}
D[5041] = {"Ravitaillement pour la Croisée",{"Trouver et rapporter les Caisses de ravitaillement de la Croisée à Thork dans les Tarides."}}
D[5042] = {"La force d'Agamaggan"}
D[5043] = {"L'agilité d'Agamaggan"}
D[5044] = {"La sagesse d'Agamaggan"}
D[5045] = {"L'essor de l'esprit"}
D[5046] = {"Peau tranchante"}
D[5047] = {"Pépin Preste-Jugeote, à votre service !",{"Parler à Malyfous Sombremartel à Long-guet."}}
D[5048] = {"Emma la bonne pâte",{"Trouver la vieille Emma à Hurlevent, et découvrir si elle est en fait Emma Gangrepierre. Si c'est le cas, elle appréciera peut-être le colis que Janice Gangrepierre lui a préparé."}}
D[5049] = {"Le blues de Jeremiah",{"Trouver Jeremiah Payson à Fossoyeuse et découvrir s'il est en fait Jeremiah Gangrepierre. Si c'est le cas, il appréciera peut-être le colis que Janice Gangrepierre lui a préparé."}}
D[5050] = {"Charme porte-bonheur",{"Rapporter son Demi-charme porte-bonheur à Janice Gangrepierre dans les Maleterres de l'ouest."}}
D[5051] = {"Deux moitiés deviennent Une",{"Trouver l'autre moitié du Charme porte-bonheur quelque part dans le périmètre de la Ferme Gangrepierre dans les Maleterres de l'ouest et le recoller.","","Donner le Charme porte-bonheur à Janice Gangrepierre à la Ferme Gangrepierre, dans les Maleterres de l'ouest."}}
D[5052] = {"Joyaux de sang d'Agamaggan",{"Apporter un Joyau de sang à Mutiledent, au Camp Taurajo, dans les Tarides.","","Collectez plus de Joyaux de sang si vous souhaitez qu'il vous gratifie de la puissance d'Agamaggan."}}
D[5054] = {"Ursius des Crocs acérés",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Ursius."}}
D[5055] = {"Brumeran des Noroît",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous tuiez Brumeran."}}
D[5056] = {"Shy-Rotam",{"Storm Sabot-d'ombre, à Long-guet au Berceau-de-l'Hiver, veut que vous triomphiez de Shy-Rotam."}}
D[5057] = {"Essais passés",{"Apportez le Marqueur de Storm Sabot-d'ombre à Melor Sabot-de-pierre aux Pitons du Tonnerre."}}
D[5058] = {"Journal de Mme Dalson"}
D[5059] = {"Enfermé"}
D[5060] = {"Enfermé"}
D[5061] = {"Forme aquatique",{"Retourner à Darnassus et montrer le Pendentif du lion de mer à Mathrengyl Pasdelours."}}
D[5062] = {"Feu sacré",{"Ramasser 10 boisseaux d'agave d'Incendia, puis consulter Magatha Totem-sinistre sur la Cime des Anciens dans les Pitons du Tonnerre."}}
D[5063] = {"La coiffe du savant écarlate",{"Pour créer la Coiffe du savant écarlate, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 8 Cristaux des arcanes ; 5 Fils écarlates enchantés.","","Il faudra aussi payer 50 pièces d'or pour le travail de fabrication."}}
D[5064] = {"Espionner le Totem-sinistre",{"Trouver et récupérer les trois Notes Secrètes à la Cime de Noir-nuage."}}
D[5065] = {"Les tablettes perdues de Mosh'aru",{"Apportez la Troisième et la Quatrième tablette Mosh'aru au Prospecteur Botte-de-fer, à Tanaris."}}
D[5066] = {"Un appel aux armes : les Maleterres",{"Trouvez le commandant Ashlam Vaillepoing. Il s'est installé au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5067] = {"Jambières d'Arcana",{"Pour fabriquer les Jambières d'Arcana, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 5 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Liquides d'embaumement de Murmegivre.","","Il faudra également payer 50 pièces d'or pour le travail de fabrication."}}
D[5068] = {"La cuirasse carnassière",{"Pour fabriquer la Cuirasse carnassière, il faut rapporter les éléments suivants à Malyfous Sombremartel : 1 Peau de la Bête en parfait état ; 10 Coutures d'Abomination effilochées ; 5 Barres d'arcanite ; 5 Peaux des ombres.","","Il faudra également payer 50 pièces d'or pour le travail de fabrication."}}
D[5081] = {"Mission de Maxwell",{"Se rendre au Pic Rochenoire et tuer le maître de guerre Voone, le généralissime Omokk, et le seigneur Wyrmthalak."}}
D[5082] = {"La menace des Tombe-hiver",{"Donova Antreneige du Berceau-de-l'Hiver veut que vous tuiez 8 Guides, 8 Protecteurs et 8 Totémiques de la tribu Tombe-hiver."}}
D[5083] = {"L'eau de feu des Tombe-hiver",{"Apportez le Flacon d'eau-de-feu vide à Donova Antreneige du Berceau-de-l'Hiver."}}
D[5084] = {"Corrompu",{"Chercher un indice dans le camp des furbolgs Mort-bois, dans le nord de Gangrebois."}}
D[5085] = {"Gelée mystère",{"Aller faire un rapport de vos trouvailles à Donova Antreneige."}}
D[5086] = {"Horreurs toxiques",{"Récolter 3 Gouttelettes d'Horreur toxique pour Donova Antreneige au Berceau-de-l'Hiver."}}
D[5087] = {"Les messagers Tombe-hiver",{"Trouver les Messagers Tombe-hiver et les empêcher de livrer leur cargaison au village Tombe-hiver."}}
D[5088] = {"Arikara",{"Tuer Arikara. Rapporter sa dépouille et de la poudre d'incendia à Motega Crin-de-feu au Poste de Blanc-relais comme preuve de votre acte."}}
D[5089] = {"Ordres du général Drakkisath",{"Remettre les Ordres du général Drakkisath au maréchal Maxwell dans les Steppes ardentes."}}
D[5090] = {"Un appel aux armes : les Maleterres",{"Trouvez le commandant Ashlam Vaillepoing. Il s'est installé au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5091] = {"Un appel aux armes : les Maleterres",{"Trouvez le commandant Ashlam Vaillepoing. Il s'est installé au Camp du Noroît, au nord des montagnes d'Alterac."}}
D[5092] = {"Nettoyer le passage",{"Tuer 10 Ecorcheurs Squelettes et 10 Goules écumantes sur la Colline des chagrins.","","Retourner auprès du commandant Ashlam Vaillepoing au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5093] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5094] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5095] = {"Un appel aux armes : les Maleterres",{"Partir à la recherche du Grand exécuteur Derrington. Son camp de base se trouve à la Barricade, à l'est des Clairières de Tirisfal et de Fossoyeuse."}}
D[5096] = {"Diversions écarlates",{"Se rendre au camp de base de la Croisade écarlate situé entre le Champ de Gangrepierre et les Larmes de Dalson et détruire leur tente d'état-major.","","Placer la bannière du Fléau sur le camp, puis revenir auprès du Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest."}}
D[5097] = {"Tout au long des tours de guet",{"À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au commandant Ashlam Vaillepoing au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5098] = {"Tout au long des tours de guet",{"À l'aide de la Torche-balise, marquer chaque tour à Andorhal ; il faut se tenir dans l'embrasure de la porte de la tour pour pouvoir la marquer.","","Quand les quatre tours seront marquées, rapporter la Torche-balise au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l'ouest."}}
D[5101] = {"Lee's Ultimate Test Quest... of Doom!",{"Kill 6 sheep for Benny and then run like hell!","","","","","Just kidding... about the running part."}}
D[5102] = {"La reddition du général Drakkisath",{"Rendez-vous au Pic Rochenoire et tuez le général Drakkisath."}}
D[5103] = {"Mort brûlante",{"Quelqu'un dans ce monde doit bien savoir à quoi servent ces gantelets. Bonne chance !"}}
D[5121] = {"Le grand chef Tombe-hiver",{"Donova Antreneige du Berceau-de-l'Hiver veut que vous triomphiez du Grand chef Tombe-hiver."}}
D[5122] = {"Le médaillon de foi"}
D[5123] = {"Le dernier morceau",{"Apportez le Journal mal écrit à Donova Antreneige au Berceau-de-l'Hiver."}}
D[5124] = {"Gantelets en plaques de feu",{"Apporter à Malyfous Sombremartel 6 Barres de thorium enchanté, 2 Essences de feu, et 4 Rubis étoilés. Lui remettre également vos Gantelets en plaques inachevés."}}
D[5125] = {"La rétribution d'Aurius"}
D[5126] = {"L'histoire de Lorax",{"Parler à Lorax. Écouter ce qu'il a à dire."}}
D[5127] = {"La forge démoniaque",{"Se rendre au pic Rochenoire et trouver Goraluk Brisenclume. Le tuer puis utiliser la Pique tachée de sang sur son cadavre. Après avoir siphonné son âme, la pique sera devenue Tachée d'âme.","","Trouver aussi la Cuirasse couverte de runes inachevée.","","Rapporter la Pique tachée d'âme et la Cuirasse couverte de runes inachevée à Lorax au Berceau-de-l'Hiver."}}
D[5128] = {"Paroles du Grand Chef",{"Rapporter le Journal mal écrit à Kelek Gardeciel dans le sud de Gangrebois."}}
D[5141] = {"Travail du cuir d'écailles de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Peter Galen, en Azshara.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l'apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5142] = {"La petite Pamela",{"Retrouver Pamela Senterouge à Comté-de-Darrow."}}
D[5143] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir fauve et un Casque en cuir fauve à Caryssia Chasselune en Féralas.","","L'accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L'accomplissement de cette quête vous empêchera d'apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5144] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Sarah Tanner dans la Gorge des Vents brûlants.","","L'accomplissement de cette quête donne accès aux arts du Travail du cuir élémentaire.","","L'accomplissement de cette quête vous empêchera d'apprendre le Travail du cuir de dragon et le Travail du cuir tribal ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5145] = {"Travail du cuir d'écailles de dragon",{"Apporter 2 Cuirasses armées du scorpide, 2 Gants armés du scorpide et 10 Ecailles de dragon usées à Thorkaf Oeil-de-dragon, dans les Terres ingrates.","","Terminer cette quête vous donnera accès aux arts du travail du cuir en écailles de dragon.","","Terminer cette quête avec succès vous interdira l'apprentissage du travail du cuir élémentaire et du travail du cuir tribal. Prenez le temps de réfléchir à la voie que vous souhaitez emprunter, avant de prendre une décision."}}
D[5146] = {"Travail du cuir élémentaire",{"Apporter 2 Coeurs de feu, 2 Globes d'eau, 2 Noyaux de terre, et 2 Souffles de vent à Brumn Sabot-d'hiver dans les montagnes d'Arathi.","","L'accomplissement de cette quête donne accès aux arts du travail du cuir élémentaire.","","L'accomplissement de cette quête vous empêchera d'apprendre le travail du cuir de dragon et le travail du cuir tribal ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5147] = {"On recherche : Arnak Totem-sinistre",{"Tuer Arnak Totem-sinistre et apporter une preuve de votre acte au garde-falaise Longue-corne au Poste de Librevent."}}
D[5148] = {"Travail du cuir tribal",{"Apporter un Gilet en cuir fauve et un Casque en cuir fauve à Se'Jib dans la vallée de Strangleronce.","","L'accomplissement de cette quête donne accès aux arts du travail du cuir tribal.","","L'accomplissement de cette quête vous empêchera d'apprendre le travail du cuir de dragon et le travail du cuir élémentaire ; il faut être sûr du chemin que l'on veut suivre avant de faire ce choix."}}
D[5149] = {"La poupée de Pamela",{"Trouver la poupée de Pamela."}}
D[5150] = {"Dadanga a faim !"}
D[5151] = {"Hypercapaciteur bidulotron",{"Tuer la bête et rapporter l'Hypercapaciteur et la Clé de la cage de la panthère à Wizlo Braquecoquard."}}
D[5152] = {"Tante Marlene",{"Parler à Marlene, au sud des ruines d'Andorhal."}}
D[5153] = {"Un étrange historien",{"Apporter l'Alliance de Joseph à Chromie."}}
D[5154] = {"Les annales de Comté-de-Darrow",{"Apportez les Annales de Comté-de-Darrow à Chromie, à Andorhal."}}
D[5155] = {"Les forces de Jaedenar",{"Entrer dans Jaedenar et tuer 4 Molosses de Jaedenar, 4 Gardiens de Jaedenar, 6 Adeptes de Jaedenar, et 6 Sectateurs de Jaedenar avant de retourner auprès de Greta Sabot-de-mousse dans Gangrebois."}}
D[5156] = {"Enquête sur la corruption",{"Trouver et détruire 2 Bêtes d'entropie et 2 Horreurs d'entropie tout en explorant le Val Grêlé. Après avoir vérifié que les cratères à cet endroit sont toujours remplis d'eau corrompue, retourner auprès de Taronn Plume-rouge dans Gangrebois."}}
D[5157] = {"Recueillir de l'eau souillée",{"Amener la Gourde vide au Puits de lune au centre de Jaedenar et la remplir avant de retourner voir Greta Sabot-de-mousse dans Gangrebois."}}
D[5158] = {"À la recherche de soutien spirituel",{"Apporter l'Eau de Puits de lune corrompue à Islen Oeil-des-rivières dans les Tarides."}}
D[5159] = {"L'eau purifiée retourne à Gangrebois",{"Apporter l'Eau de Puits de lune purifiée à Greta Sabot-de-mousse dans Gangrebois."}}
D[5160] = {"Le Protectorat de la matrone",{"Aller jusqu'au Berceau-de-l'Hiver et trouver Haleh. Lui donner l'Ecaille d'Awbee."}}
D[5161] = {"La colère du vol bleu",{"Si vous souhaitez continuer, parlez à Haleh."}}
D[5162] = {"La colère du vol bleu",{"Parler à Jeziba dans les Maleterres. Il vit à Andorhal."}}
D[5163] = {"Yéti ? Y es-tu ?",{"Prendre le yéti mécanique d'Umi et effrayer ses amis avec :","","Legacki, à Long-guet (Berceau-de-l'Hiver)","Saupoudr, à Gadgetzan (Tanaris)","Quixxil, au refuge des Marshal (Cratère d'Un'Goro)","","Quand vous aurez terminé, rapporter le yéti mécanique à Umi."}}
D[5164] = {"Guide de l'Indocile",{"Lire le Guide de l'Indocile."}}
D[5165] = {"Éteindre les flammes de protection",{"À l'aide de l'Eau de Puits de lune purifiée, éteignez les flammes des quatre braseros de protection à l'intérieur du Fort des ombres dans Gangrebois. Retournez ensuite auprès de Greta Sabot-de-mousse au Sanctuaire d'émeraude."}}
D[5166] = {"La cuirasse du vol chromatique",{"Pour forger la Cuirasse du vol chromatique, il faut apporter les éléments suivants à Jeziba le \"Sculpteur\" :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 doses de Sang des héros.","","10 Coutures d'Abomination effilochées."}}
D[5167] = {"Les cuissards de duelliste chromatique",{"Pour forger les Cuissards de duelliste chromatique, il faut apporter les éléments suivants à Jeziba le \"Sculpteur\" :","","1 Carapace chromatique.","","10 Ecailles chromatiques brillantes.","","10 doses de Sang des héros.","","5 Peaux des ombres."}}
D[5168] = {"Les héros de Comté-de-Darrow",{"Apporter le Libram de Davil et le Bouclier de Senterouge à Carlin Senterouge."}}
D[5181] = {"Les vilains de Comté-de-Darrow",{"Rapporter le Crâne d'Horgus et l'Epée brisée de Marduk à Carlin Senterouge à la chapelle de l'Espoir de Lumière."}}
D[5201] = {"L'incursion des Tombe-hiver",{"Rivern Givrevent veut que vous tuiez 5 Chamans Tombe-hiver et 5 Ursas Tombe-hiver."}}
D[5202] = {"Une étrange clé rouge",{"Chercher dans Jaedenar à quoi sert la Clé rouge sang."}}
D[5203] = {"Sauvetage à Jaedenar",{"Escorter Arko'narin à l'endroit où Sancteforge et son équipement sont détenus, puis la protéger lors de l'évasion du Fort des ombres. Ensuite, aller trouver Jessir Arquelune dans Gangrebois pour lui apprendre ce qui est arrivé à ses amis."}}
D[5204] = {"Le châtiment de la Lumière",{"Revenir à Jaedenar et tuer la succube Rakaiah avant de trouver le Cadavre de Trey Sancteforge."}}
D[5206] = {"Les maraudeurs de Comté-de-Darrow",{"Apporter 5 Crânes résonants et le Cristal mystique à Carlin Senterouge, dans les Maleterres de l'est."}}
D[5210] = {"Frère Carlin",{"Apporter les Annales complètes de Comté-de-Darrow à Carlin Senterouge dans les Maleterres de l'est."}}
D[5211] = {"Les défenseurs de Comté-de-Darrow",{"Libérer 15 Esprits de Comté-de-Darrow et retourner auprès de Carlin Senterouge."}}
D[5212] = {"La chair ne ment pas",{"Récupérer 10 Échantillons de chair pestiférée à Stratholme puis les rapporter à Betina Bigglezink. Vous pensez que toutes les créatures de Stratholme possèdent de tels échantillons de chair."}}
D[5213] = {"L'agent actif",{"Se rendre jusqu'à Stratholme et fouiller les ziggourats. Trouver et ramener de nouvelles informations sur le Fléau à Betina Bigglezink."}}
D[5214] = {"Le grand Ezra Grimm",{"Trouver le magasin de tabac d’Ezra Grimm à Stratholme et récupérer une boîte de Tabac d’Ezra. Retourner auprès de Smokey LaRue quand le travail est fait."}}
D[5215] = {"Les chaudrons du Fléau",{"Parler à la grande prêtresse MacDonnell à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5216] = {"Cible : le Champ de Gangrepierre",{"Se rendre au Champ de Gangrepierre dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille du Champ de Gangrepierre vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5217] = {"Retour au camp du Noroît",{"Apporter une Bouteille du Champ de Gangrepierre remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5218] = {"Le chaudron du champ de Gangrepierre"}
D[5219] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des Larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5220] = {"Retour au camp du Noroît",{"Apporter la Bouteille des Larmes de Dalson remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5221] = {"Le chaudron des Larmes de Dalson"}
D[5222] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille du Repaire putride vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5223] = {"Retour au camp du Noroît",{"Apporter la Bouteille du Repaire putride remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5224] = {"Le chaudron du Repaire putride"}
D[5225] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille de la Flétrissure de Gahrron vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5226] = {"Retour au camp du Noroît",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la grande prêtresse MacDonnell au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5227] = {"Le chaudron de la Flétrissure de Gahrron"}
D[5228] = {"Les chaudrons du Fléau",{"Parler à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5229] = {"Cible : le Champ de Gangrepierre",{"Se rendre au Champ de Gangrepierre, dans les Maleterres de l'ouest, pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve. Il aura peut-être une clé qui permet d'accéder au chaudron. Il faut se munir de la Bouteille du Champ de Gangrepierre vide pour pouvoir prélever un échantillon des poisons qui sont dans le chaudron."}}
D[5230] = {"Retour à la Barricade",{"Apporter la Bouteille du Champ de Gangrepierre remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5231] = {"Cible : les Larmes de Dalson",{"Se rendre aux Larmes de Dalson dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, puis utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille des Larmes de Dalson vide pour pouvoir prendre un échantillon des poisons qui sont dans le chaudron."}}
D[5232] = {"Retour à la Barricade",{"Apporter la Bouteille des Larmes de Dalson remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5233] = {"Cible : le Repaire putride",{"Se rendre au Repaire putride dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille du Repaire putride vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5234] = {"Retour à la Barricade",{"Ramener la Bouteille du Repaire putride remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5235] = {"Cible : la Flétrissure de Gahrron",{"Se rendre à la Flétrissure de Gahrron dans les Maleterres de l'ouest pour trouver et vaincre le Seigneur du Chaudron qui s'y trouve, et utiliser sa clé pour accéder au chaudron. Il faut se munir de la Bouteille de la Flétrissure de Gahrron vide pour pouvoir récupérer un échantillon des poisons à l'intérieur du chaudron."}}
D[5236] = {"Retour à la Barricade",{"Apporter la Bouteille de la Flétrissure de Gahrron remplie à la prêtresse des ombres Vandis à la Barricade, dans les Maleterres de l'ouest."}}
D[5237] = {"Mission accomplie !"}
D[5238] = {"Mission accomplie !"}
D[5241] = {"Oncle Carlin",{"Trouver Carlin Senterouge."}}
D[5242] = {"Un coup final",{"Tuer Moora et Salia, et rapporter la Tête du Seigneur des ténèbres Gangr'dan à Greta Sabot-de-mousse dans Gangrebois."}}
D[5243] = {"Les demeures du Sacré",{"Se rendre à Stratholme, au nord. Fouiller les caisses de fournitures qui encombrent la cité et récupérer 5 Eaux sacrées de Stratholme. Retourner auprès de Leonid Barthalomew le Révéré quand vous avez récolté assez de liquide béni."}}
D[5244] = {"Les ruines de Kel'Theril",{"Parler à Jaron Sculptepierre au village de Pluie-d'Étoiles."}}
D[5245] = {"Les esprits troublés de Kel'Theril",{"Utiliser la Pique de Jaron pour trouver les quatre Fragments de relique des Bien-nés. Les apporter à Aurora Mandeciel dans les Maleterres de l'est."}}
D[5246] = {"Fragments du passé",{"Trouver les Écrits sacrés des Bien-nés dans le temple de Zin-Malor en Azshara et les apporter à Aurora Mandeciel à la tour du Col du nord, dans les Maleterres de l'est."}}
D[5247] = {"Fragments du passé",{"Apporter une Barre de thorium enchanté, 5 Cristaux de restauration et une Fiole d'eau redoutable à Aurora Mandeciel à la tour du Col du nord, dans les Maleterres de l'est."}}
D[5248] = {"Tourmentée par le passé",{"Amener le Cristal de Zin-Malor au lac Kel'Theril au Berceau-de-l'Hiver et trouver un esprit Bien-né qui veuille bien vous parler."}}
D[5249] = {"Au Berceau-de-l'Hiver",{"Trouver le village de Pluie-d'Étoiles au Berceau-de-l'Hiver, et parler à Wynd Pistenuit."}}
D[5250] = {"Pluie-d'Étoiles",{"Trouver le village de Pluie-d'Étoiles au Berceau-de-l'Hiver et parler à Wynd Pistenuit."}}
D[5251] = {"L'archiviste",{"Voyager jusqu'à Stratholme et trouver l'Archiviste Galford de la Croisade écarlate. L'abattre et brûler les Archives écarlates."}}
D[5252] = {"Une Bien-née pénitente",{"Parler à Wynd Pistenuit au village de Pluie-d'Étoiles et lui demander quel est le bon endroit pour le Cristal de Zin-Malor."}}
D[5253] = {"Le Cristal de Zin-Malor",{"Apporter le Cristal de Zin-Malor à l'archidruide Fandral Forteramure à Darnassus."}}
D[5261] = {"Eagan Tannepeau",{"Parler à Eagan Tannepeau."}}
D[5262] = {"La vérité vient du ciel",{"Apporter la Tête de Balnazzar au duc Nicholas Zverenhoff dans les Maleterres de l'est."}}
D[5263] = {"Au-dessus et au-delà",{"S'aventurer dans Stratholme et tuer le baron Vaillefendre. Prendre sa tête et retourner auprès du duc Nicholas Zverenhoff."}}
D[5264] = {"Seigneur Maxwell Tyrosus",{"Parler au seigneur Maxwell Tyrosus. Il est à l'intérieur de l'église."}}
D[5265] = {"Le Coffre d'argent",{"Ouvrez le Coffre d'argent et prenez votre récompense."}}
D[5281] = {"Âmes tourmentées",{"Trouver Egan. Vous savez seulement qu'on l'a vu pour la dernière fois aux alentours de Stratholme."}}
D[5282] = {"Âmes tourmentées",{"Se servir de la Pétoire d'Egan sur les citoyens fantomatiques et spectraux de Stratholme. Quand les esprits sans repos se libèrent de leur enveloppes fantomatiques, utiliser de nouveau la Pétoire - ils seront enfin libres !","","Libérer 15 Esprits sans repos puis retourner auprès d'Egan."}}
D[5283] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants et les rapporter à Grumnus : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5284] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, il faut fabriquer les éléments suivants et les rapporter à Ferronus : 4 Epées d'acier lunaire, 4 Haches massives en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5301] = {"L'art de l'armurier",{"Pour devenir un fabricant d'armures, il faut fabriquer les éléments suivants puis les apporter à Okothos : 4 Heaumes ornés en mithril, 2 Bottes ornées en mithril, 1 Cuirasse ornée en mithril."}}
D[5302] = {"La voie du Forgeron d'armes",{"Pour devenir un Fabricant d'armes, vous devez fabriquer les éléments suivants et les rapporter à Borgosh : 4 Epées d'acier lunaire, 4 Haches massives en fer, 2 Haches en mithril lourd, et 2 Grandes masses noires."}}
D[5305] = {"Douce sérénité",{"Aller jusqu'à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le rapporter à Lilith."}}
D[5306] = {"Pierre du serpent de la chasseresse des ombres",{"Aller jusqu'au Pic Rochenoire et abattre la Chasseresse des ombres Vosh'gajin. Récupérer la Pierre du serpent de Vosh'gajin et la rapporter à Kilram."}}
D[5307] = {"Corruption",{"Trouver le Fabricant d'épées de la Garde noire à Stratholme et le tuer. Récupérer l'Insigne de la Garde noire et retourner auprès de Seril Plaie-du-Fléau."}}
D[5321] = {"Le dormeur s'est éveillé",{"Escorter Kerlonian Eternombre jusqu'à Liladris Ondelune au Poste de Maestra à Orneval."}}
D[5341] = {"Fortune de la famille Barov",{"S'aventurer jusqu'à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d'Austrivage. Revenir auprès d'Alexi Barov quand la tâche est accomplie."}}
D[5342] = {"Le dernier Barov",{"Voyagez jusqu'au Camp du Noroît, dans le territoire de l'Alliance, et assassinez Weldon Barov. Prenez sa tête et revenez auprès d'Alexi Barov.","","Attention : Weldon sera probablement bien protégé par la racaille de l'Alliance."}}
D[5343] = {"Fortune de la famille Barov",{"S'aventurer jusqu'à la Scholomance et récupérer la fortune de la famille Barov. Cette fortune se compose de quatre titres de propriété : le titre de propriété de Caer Darrow ; le titre de propriété de Brill ; le titre de propriété de Moulin-de-Tarren ; et le titre de propriété d'Austrivage. Revenir auprès de Weldon Barov quand la tâche est accomplie."}}
D[5344] = {"Le dernier Barov",{"Voyager jusqu'à la Barricade - territoire de la Horde - et assassiner Alexi Barov. Prendre sa tête et revenir auprès de Weldon Barov.","","Attention : Alexi sera probablement bien protégé par les vandales de la Horde."}}
D[5361] = {"Arbre familial",{"Apporter le Rapport du garde-falaise Longue-corne à Nataka Longue-corne au poste de Rôdeur-fantôme en Désolace."}}
D[5381] = {"La Main d'Iruxos",{"Récupérer la Boîte démoniaque dans la forteresse de Hache-Tonnerre, puis la rapporter à Taiga Crin-sage, à Proie-de-l'Ombre."}}
D[5382] = {"Docteur Theolen Krastinov, le boucher",{"Trouver le docteur Theolen Krastinov à l'intérieur de la Scholomance. Le tuer, puis brûler le Cadavre d'Eva Sarkhoff et le Cadavre de Lucien Sarkhoff. Retourner auprès d'Eva Sarkhoff quand la tâche est accomplie."}}
D[5383] = {"Sac des horreurs de Krastinov",{"Apportez le Sac des horreurs à Eva Sarkhoff, à Caer Darrow."}}
D[5384] = {"Kirtonos le héraut",{"Retournez à la Scholomance avec le Sang des innocents. Trouvez le porche et placez le Sang des innocents dans le brasero. Kirtonos viendra dévorer votre âme.","","Combattez vaillamment, sans perdre un pouce de terrain ! Détruisez Kirtonos et retournez auprès d'Eva Sarkhoff."}}
D[5385] = {"Le cadavre de Trey Sancteforge",{"Rapporter le Cadavre de Trey Sancteforge à Jessir Arquelune dans Gangrebois."}}
D[5386] = {"La prise du jour",{"Parler à Jinar'Zillen à Proie-de-l'Ombre, puis apporter 2 poissons Ventre-rouge à Nataka Longue-corne."}}
D[5401] = {"Brevet de l'Aube d'argent"}
D[5402] = {"Pierres du Fléau des serviteurs"}
D[5403] = {"Pierres du Fléau des envahisseurs"}
D[5404] = {"Pierres du Fléau des corrupteurs"}
D[5405] = {"Brevet de l'Aube d'argent"}
D[5406] = {"Pierres du Fléau des corrupteurs"}
D[5407] = {"Pierres du Fléau des envahisseurs"}
D[5408] = {"Pierres du Fléau des serviteurs"}
D[5421] = {"Poisson dans un seau"}
D[5441] = {"Les péons paresseux",{"Utiliser la Matraque du contremaître sur les Péons paresseux, lorsqu'ils sont en train de dormir. Réveiller 5 Péons, puis rapporter la Matraque du contremaître au contremaître Thazz'ril, dans la Vallée des épreuves."}}
D[5461] = {"L'humain, Ras Murmegivre",{"Voyager jusqu'aux hautes-terres Arathies, et aller aux ruines de Stromgarde. Fouiller Stromgarde pour trouver un Souvenir de la mémoire. Si une telle trouvaille est faite, rapporter l'objet au magistrat Marduke."}}
D[5462] = {"Le moribond, Ras Murmegivre",{"Voyager jusqu'à l'Espoir de lumière dans les Maleterres de l'est et trouver Leonid Barthalomew le Révéré. Lui montrer le Souvenir de la mémoire et lui dire tout ce que vous avez découvert."}}
D[5463] = {"Le Don de Menethil",{"Voyager jusqu'à Stratholme et trouver le Don de Menethil. Placer le Souvenir de la mémoire sur le sol impie."}}
D[5464] = {"Le Don de Menethil",{"Apporter le Souvenir lié à Leonid Barthalomew dans les Maleterres de l'est."}}
D[5465] = {"Souvenir lié",{"Retourner auprès du Magistrat Marduke à Caer Darrow. Lui montrer le Souvenir lié."}}
D[5466] = {"La Liche, Ras Murmegivre",{"Trouver Ras Murmegivre dans Scholomance. Après l'avoir trouvé, utiliser le Souvenir lié sur son visage mort-vivant. Si sa transformation en mortel réussit, l'abattre et prendre la Tête humaine de Ras Murmegivre. Apporter la tête au Magistrat Marduke."}}
D[5481] = {"La tâche de Gordo",{"Récolter 3 Herbes des ténèbres et les apporter à l'Apprenti Apothicaire Holland au Cimetière de Brill."}}
D[5482] = {"Herbe maléfique",{"Récolter 10 Herbes maléfiques et les apporter à l'apprenti apothicaire Holland."}}
D[5501] = {"Collectionneur d'os",{"Apporter à Bibbly F'ibulleur à la Hutte de Kormek 10 Os de kodo provenant du Cimetière des kodos."}}
D[5502] = {"Un surveillant de la Horde"}
D[5503] = {"Brevet de l'Aube d'argent"}
D[5504] = {"Les mantelets de l'Aube",{"Apporter 10 Marques de valeur de l'Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l'ouest"}}
D[5505] = {"La clé de Scholomance"}
D[5507] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l'Aube d'argent au quartier-maître Feuzopoudre au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5508] = {"Pierres du Fléau des corrupteurs"}
