D[5513] = {"Les mantelets de l'aube",{"Apporter 10 Marques de valeur de l'Aube d'argent à l'intendante Coinceculasse, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[5514] = {"À la pêche au moule...",{"Apporter les Fragments de squelette imprégnés et 15 pièces d'or à Froisse Bonnacier à Gadgetzan."}}
D[5515] = {"Sac des horreurs de Krastinov",{"Trouver Jandice Barov dans Scholomance et la tuer. Sur son cadavre, récupérer le Sac des horreurs de Krastinov. Rapporter le sac à Eva Sarkhoff."}}
D[5517] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent à l'intendante Coinceculasse, à la chapelle de l'Espoir de Lumière, dans les Maleterres de l'est."}}
D[5518] = {"La tenue d'ogre gordok",{"Apportez 4 Rouleaux d'étoffe runique, 8 Cuirs robustes, 2 Fils runiques et du Tanin ogre à Noué Dédodevie. Il est actuellement enchaîné dans l'aile gordok de Hache-tripes."}}
D[5519] = {"La tenue d'ogre gordok"}
D[5521] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent au quartier-maître Feuzopoudre au camp du Noroît, dans les Maleterres de l'ouest."}}
D[5522] = {"Leonid Barthalomew",{"Apporter les Oeufs congelés à Leonid Barthalomew dans les Maleterres de l'est."}}
D[5524] = {"Le mantelet de l'Aube chromatique",{"Apporter 25 Marques de valeur de l'Aube d'argent au Quartier-maître Hasana à la Barricade, dans les Maleterres de l'ouest."}}
D[5525] = {"Libérez Noué !"}
D[5526] = {"Fragment de la Gangrevigne",{"Trouvez la Gangrevigne à Hache-tripes et prenez-en un fragment. Il est probable que vous ne pourrez vous en emparer qu'après la mort d'Alzzin le Modeleur. Servez-vous du Reliquaire de Pureté pour conserver le fragment, et retournez à Reflet-de-Lune voir Rabine Saturna au village de Havrenuit."}}
D[5527] = {"Un reliquaire de pureté",{"Rendez-vous en Silithus et cherchez un Reliquaire de pureté dans les ruines du village de Sudevent. Si vous parvenez à le trouver, rapportez-le à Rabine Saturna à Havrenuit, Reflet-de-Lune."}}
D[5528] = {"La dégustation gordok"}
D[5529] = {"Portée contaminée",{"Tuer 20 Jeunes pestiférés, puis retourner auprès de Betina Bigglezink à la Chapelle de l'Espoir de Lumière."}}
D[5531] = {"Betina Bigglezink",{"Apportez les Œufs congelés à Betina Bigglezink."}}
D[5533] = {"Scholomance",{"Parler à l'alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5534] = {"L'équipement « manquant » de Kim'jael",{"Trouver \"une rune\" détenue par les nagas dans les ruines d'Eldarath et la rapporter à Kim'jael, en Azshara."}}
D[5535] = {"Agitation spirituelle",{"Détruire 6 Apparitions de Bien-nés et 6 Jeunes liches bien-nées avant de retourner auprès de Loh'atu en Azshara."}}
D[5536] = {"Un pays plein de haine",{"Tuer 6 Satyres Haldarr, 2 Entourloupeurs Haldarr, et 2 Gangreliges Haldarr puis revenir voir Loh'atu à la frontière d'Orneval."}}
D[5537] = {"Fragments de squelette",{"Apporter 15 Fragments de squelette à l'alchimiste Arbington à la pointe du Noroît, dans les Maleterres de l'ouest."}}
D[5538] = {"À la pêche au moule...",{"Apporter les Fragments de squelette imprégnés et 15 pièces d'or à Froisse Bonnacier à Gadgetzan."}}
D[5541] = {"Munitions pour Grondetrait",{"Apportez les Munitions de Grondetrait à Hegnar Grondetrait à Dun Morogh."}}
D[5542] = {"Chiens-démons",{"Tuer 20 Chiens pestiférés chétifs, 5 Chiens pestiférés et 5 Chiens pestiférés frénétiques. Retourner voir Tirion Fordring quand la mission sera terminée."}}
D[5543] = {"Ciel couleur de sang",{"Tuer 30 Chauves-souris pestiférées, puis retourner voir Tirion Fordring."}}
D[5544] = {"Larve putride",{"Chercher les Larves putrides et les Dévoreurs de la région. Les tuer et récupérer leur viande. Retourner voir Tirion Fordring quand 15 pièces de Chair de Ver putride auront été récupérées."}}
D[5545] = {"Un sac d'embrouilles",{"Apporter 8 fagots de bois à Raelen au Camp de bûcherons du Val d'est."}}
D[5561] = {"Le rassemblement des kodos",{"Ramenez cinq Kodos domptés et le Kombobulateur kodo à Smeed Fouillevis, au camp de Fouillevis."}}
D[5581] = {"Les portails de la Légion",{"Bannir 6 Portails, dans le convent de Mannoroc, puis retourner voir Taiga Crin-sage, à Proie-de-l'Ombre."}}
D[5582] = {"L'écaille de dragon luisante",{"Apporter l'Ecaille de dragon luisante à Betina Bigglezink à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est."}}
D[5601] = {"Pamela, ma sœur",{"Trouver Pamela Senterouge à Comté-de-Darrow."}}
D[5621] = {"Vêtements de la lune",{"Trouver la Sentinelle Shaya et la guérir de ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Laurna Clairematin, à Dolanaar."}}
D[5622] = {"Au service d'Elune",{"Parler à Laurna Clairematin à Teldrassil."}}
D[5623] = {"Au service de la Lumière",{"Parler à la prêtresse Josetta dans la Forêt d'Elwynn."}}
D[5624] = {"Vêtements de la Lumière",{"Trouver le garde Roberts et soigner ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir la prêtresse Josetta, à Comté-de-l'or."}}
D[5625] = {"Vêtements de la Lumière",{"Trouver le Montagnard Dolf et guérir ses blessures en utilisant Soins inférieurs (Rang 2). Lui accorder ensuite le Mot de pouvoir : Robustesse, puis retourner voir Maxan Anvol, à Kharanos."}}
