D[8053] = {"Parangons de puissance : les garde-bras de libre-penseur",{"Ramenez des Manchettes primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8054] = {"Parangons de puissance : la ceinture de libre-penseur",{"Ramenez un Châle primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Honorer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8055] = {"Parangons de puissance : la cuirasse de libre-penseur",{"Ramenez un Tabard primordial hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi vous Révérer (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8056] = {"Parangons de puissance : les brassards d'augure",{"Ramenez des Brachiales primordiales hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).","","Maywiki de Zuldazar se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8057] = {"Parangons de puissance : les brassards d'haruspice",{"Ramenez un Etançon primordial hakkari à Maywiki de Zuldazar. La tribu Zandalar doit aussi être Amicale (au minimum).","","Maywiki de Zuldazar se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
D[8058] = {"Parangons de puissance : les garde-bras de redresseur de torts",{"Ramenez des Brachiales primordiales hakkari à Jin'rokh le Briseur. La tribu Zandalar doit aussi être Amicale envers vous (au minimum).","","Jin'rokh le Briseur se trouve sur l'île de Yojamba, dans la vallée de Strangleronce."}}
