D[8800] = {"La tenue de combat cénarienne",{"Parlez à Vargus, au Fort cénarien en Silithus."}}
D[8801] = {"L'héritage de C'Thun",{"Remettre l'Oeil de C'Thun a Caelastrasz, dans le temple d'Ahn'Qiraj."}}
D[8802] = {"Le sauveur de Kalimdor",{"Apporter l'Oeil de C'Thun à Anachronos dans les Grottes du temps."}}
D[8803] = {"Un cadeau de fête"}
D[8804] = {"Survivre dans le désert",{"Ramener 4 Globes d'eau, 4 Anti-venins puissants et 4 Boulettes fumées du désert à Calandrath, à l'auberge du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique I."}}
D[8805] = {"Des bottes pour la garde",{"Remettre 3 Bottes ornées en mithril à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique II."}}
D[8806] = {"Des silex à aiguiser pour la Garde",{"Apporter 10 Silex à aiguiser denses, 10 Silex à aiguiser solides et 10 Silex à aiguiser lourds à Vish Kozus, capitaine de la garde du Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique III."}}
D[8807] = {"Le matériel de divination",{"Apporter un 1 Grand éclat brillant, 1 Gros éclat irradiant et 1 Enorme émeraude à la géologue Fablemort, au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing logistique V."}}
