D[8857] = {"Les secrets du Colosse - Ashi",{"Remettre la Carcasse du colosse d'Ashi à Orguignard Odipnoticus, à Baie-du-Butin."}}
D[8858] = {"Les secrets du Colosse - Regal",{"Apporter la Carcasse du colosse de Regal au surveillant Huilepoing, dans la gorge des Vents brûlants."}}
D[8859] = {"Les secrets du Colosse - Zora",{"Apporter la Carcasse du colosse de Zora au seigneur Maxwell Tyrosus, à la chapelle de l'Espoir de lumière, dans les Maleterres de l'est."}}
D[8860] = {"Les fêtes du Nouvel an !",{"Apportez les marchandises des Gourmandises Fumebois à l'Aubergiste Allison, à Hurlevent."}}
D[8861] = {"Les fêtes du Nouvel an !",{"Apportez les Marchandises des Gourmandises Fumebois à l'Aubergiste Pala, aux Pitons du Tonnerre."}}
D[8862] = {"La chandelle d'Elune"}
D[8863] = {"Des raviolis de fête"}
D[8864] = {"Les robes de la fête lunaire"}
D[8865] = {"Les habits de la fête lunaire"}
D[8866] = {"L'Ancien Barbe-de-bronze"}
D[8867] = {"Le feu d'artifice lunaire",{"Lancez 8 Feux d'artifice lunaires et 2 Chapelets de feux d'artifice lunaires et retournez voir une Messagère de la Fête lunaire dans l'une des capitales."}}
D[8868] = {"La bénédiction d'Elune",{"Invoquez Présage, et vainquez-le pour gagner la Bénédiction d'Elune. Puis retournez voir Valadar Chantétoile à Havrenuit."}}
D[8869] = {"Douce sérénité",{"Aller jusqu'à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le ramener à Lilith."}}
D[8870] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire à la Garde mystique de Forgefer. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales."}}
D[8871] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire au Parc de Hurlevent. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales."}}
D[8872] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire à l'Enclave cénarienne de Darnassus. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales."}}
D[8873] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire dans la Vallée de la sagesse à Orgrimmar. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales."}}
D[8874] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire à l'entrée de Fossoyeuse. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales."}}
D[8875] = {"La fête lunaire",{"Parler à la Messagère de la Fête lunaire à la Cime des Anciens des Pitons du Tonnerre. Vous pouvez aussi parler aux messagers de la Fête lunaire des autres capitales."}}
D[8876] = {"Les petites fusées"}
D[8877] = {"Le lanceur de fusées"}
D[8878] = {"Des recettes de fête"}
D[8879] = {"Les grandes fusées"}
D[8880] = {"Les chapelets de fusées"}
D[8881] = {"Les chapelets de grandes fusées"}
D[8882] = {"Le lanceur de chapelets"}
D[8883] = {"Valadar Chantétoile",{"Utilisez votre Invitation à la fête lunaire dans la lumière lunaire pour vous rendre à Reflet-de-Lune. À votre arrivée, parlez à Valadar Chantétoile."}}
D[8884] = {"Des têtes de poisson à la pelle",{"Collecter 8 Têtes de murloc Sinistrécaille et retourner voir Hathvelion Miresoleil dans le bois des Chants éternels sur le piton qui domine le Rivage paisible."}}
D[8885] = {"L'anneau de Mmmrrrggglll",{"Récupérez l'Anneau de Mmmrrrggglll sur la patte sans vie du chef des Sinistrécailles. Rapportez-le à Hathvelion Miresoleil dans le bois des Chants éternels sur le piton surplombant le Rivage paisible."}}
D[8886] = {"Les pirates Sinistrécaille !",{"Récupérez 6 caisses de la Cargaison du capitaine Kelisendra et rapportez-les à cette dernière au camp protégé juste à l'est du mouillage des Voiles du soleil dans le bois des Chants éternels."}}
D[8887] = {"Les portulans perdus du capitaine Kelisendra",{"Rendre les Portulans perdus du capitaine Kelisendra à cette dernière au camp protégé, juste à l'est du mouillage des Voiles du soleil dans le bois des Chants éternels."}}
D[8888] = {"L'apprentie du magistère",{"Parler à l'apprentie Loralthalis près de la Flèche de Ternesoir dans le bois des Chants éternels."}}
D[8889] = {"Désactiver la flèche",{"Désactiver les 3 Sources d'énergie de la Flèche de Ternesoir à l'intérieur de la flèche de Ternesoir. Puis rapporter le Joyau de désactivation à l'apprentie Loralthalis dans le bois des Chants éternels."}}
D[8890] = {"Une communication de la flèche",{"Retourner voir le magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels."}}
D[8891] = {"Des recherches abandonnées",{"Rapporter le Journal du magistère Ternesoir au magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels."}}
D[8892] = {"La situation au mouillage des Voiles du soleil",{"Tuez 5 Nervis déshérités et 5 Voyous déshérités, puis allez faire votre rapport au forestier Degolien au bois des Chants éternels."}}
D[8893] = {"Le Super-Oeuf-O-Matic"}
D[8894] = {"Corvée de nettoyage",{"Tuez 6 Serpents de mana et 6 Fieléthers, puis retournez voir le paysagiste Wyllithen, sur les Terres de Ternesoir, dans le bois des Chants éternels."}}
D[8895] = {"Une livraison au sanctum septentrional",{"Remettre la Lettre sans marque au telluriste Caidanis, au Sanctum septentrional du bois des Chants éternels."}}
D[8896] = {"L'espion des nains",{"Trouvez et tuez le prospecteur Garde-enclume au Sanctum septentrional, puis faites votre rapport à Aeldon Signesol, dans le bois des Chants éternels."}}
D[8897] = {"Très chère Colara,",{"Apporter la Note soigneusement calligraphiée du lieutenant Heldric à Colara Dean, devant la banque de Hurlevent."}}
D[8898] = {"Très chère Colara,",{"Apporter la Lettre froissée à Colara Dean, devant la banque de Hurlevent."}}
D[8899] = {"Très chère Colara,",{"Apporter la Lettre immaculée à Colara Dean, devant la banque à Hurlevent."}}
D[8900] = {"Très chère Elenia,",{"Apporter la Note légèrement froissée à Elenia Haydon, près de la banque de Fossoyeuse."}}
D[8901] = {"Très chère Elenia,",{"Apporter la Lettre écrite avec soin à Elenia Haydon, près de la banque de Fossoyeuse."}}
D[8902] = {"Très chère Elenia,",{"Apporter la Lettre pleine d'amour à Elenia Haydon, près de la banque de Fossoyeuse."}}
D[8903] = {"Les périls de l'amour",{"Obtenez une Carte de garde de Hurlevent et rapportez-la à Aristan Mottar, à Hurlevent."}}
D[8904] = {"Les périls de l'amour",{"Obtenez une Carte de garde moisie et rapportez-la à Fenstad Argyle, à Fossoyeuse."}}
