D[9030] = {"Les adieux d'Anthion",{"Parler à Deliana à Forgefer."}}
D[9032] = {"Le triste destin de Bodley",{"Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley."}}
D[9033] = {"Les échos de la guerre",{"Le commandant Eligor Portelaube, de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau-de-pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin."}}
D[9034] = {"Cuirasse de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d'armure en plaques, 4 Barres d'arcanite et 2 Cristaux de nexus."}}
D[9035] = {"Une embuscade au bord de la route",{"Parlez à l'apprenti Meledor dans le bois des Chants éternels, le long de la route qui part au sud depuis Lune-d'argent."}}
D[9036] = {"Cuissards de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des cuissards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Cuissards désacralisés, 20 Débris d'armure en plaques, 4 Barres d'arcanite et 3 Peaux robustes traitées."}}
D[9037] = {"Casque de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera un casque de cuirassier si vous lui apportez les choses suivantes : 1 Heaume désacralisé, 15 Débris d'armure en plaques, 5 Barres d'arcanite et 1 Cristal de nexus."}}
D[9038] = {"Espauliers de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des espauliers de cuirassier si vous lui apportez les choses suivantes : 1 paire d'Espauliers désacralisés, 12 Débris d'armure en plaques, 2 Barres d'arcanite et 3 Peaux robustes traitées."}}
D[9039] = {"Solerets de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des solerets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Solerets désacralisés, 12 Débris d'armure en plaques, 2 Barres d'arcanite et 3 Peaux robustes traitées."}}
D[9040] = {"Gantelets de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des gantelets de cuirassier si vous lui apportez les choses suivantes : 1 paire de Gantelets désacralisés, 8 Débris d'armure en plaques, 1 Barre d'arcanite et 5 Peaux robustes traitées."}}
D[9041] = {"Sangle de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une sangle de cuirassier si vous lui apportez les choses suivantes : 1 Sangle désacralisée, 8 Débris d'armure en plaques, 1 Barre d'arcanite et 5 Peaux robustes traitées."}}
D[9042] = {"Brassards de cuirassier",{"Korfax, à la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des brassards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Brassards désacralisés, 6 Débris d'armure en plaques, 1 Barre d'arcanite et 1 Cristal de nexus."}}
D[9043] = {"La tunique de rédemption",{"Le commandant Eligor Portelaube de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera une Tunique de rédemption si vous lui rapportez 1 Tunique désacralisée, 25 Débris d'armure en plaques, 4 Barres d'arcanite et 3 Peaux robustes traitées."}}
D[9044] = {"Les garde-jambes de rédemption",{"Le commandant Eligor Portelaube de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Garde-jambes de rédemption si vous lui rapportez 1 paire de Garde-jambes désacralisés, 20 Débris d'armure en plaques, 4 Barres d'arcanite et 2 Cristaux de nexus."}}
D[9045] = {"Le chapel de rédemption",{"Le commandant Eligor Portelaube de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera un Couvre-chef de rédemption si vous lui rapportez 1 Couvre-chef désacralisé, 15 Débris d'armure en plaques, 5 Barres d'arcanite et 2 Peaux robustes traitées."}}
D[9046] = {"Les spallières de rédemption",{"Le commandant Eligor Portelaube de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Spallières de rédemption si vous lui rapportez 1 paire de Spallières désacralisées, 12 Débris d'armure en plaques, 2 Barres d'arcanite et 2 Cristaux de nexus."}}
D[9047] = {"Les bottes de rédemption",{"Le commandant Eligor Portelaube de la chapelle de l'Espoir de Lumière dans les Maleterres de l'est, vous fabriquera des Bottes de rédemption si vous lui rapportez 1 paire de Bottes désacralisées, 12 Débris d'armure en plaques, 2 Barres d'arcanite et 3 Peaux robustes traitées."}}
