D[9996] = {"L'attaque de la halte Aile-de-feu",{"Tuez 10 Défenseurs Aile-de-feu, 10 Garde-sang Aile-de-feu et 10 Démonistes Aile-de-feu. Puis retournez au Poste allérien dans la forêt de Terokkar pour faire votre rapport au lieutenant Meridian."}}
D[9997] = {"L'attaque de la halte Aile-de-feu",{"Tuez 10 Défenseurs Aile-de-feu, 10 Garde-sang Aile-de-feu et 10 Démonistes Aile-de-feu. Puis retournez au camp des Brise-pierres dans la forêt de Terokkar pour faire votre rapport au sergent Chawni."}}
D[9998] = {"Des voisins encombrants",{"Tuez 12 Péons redimensionnés puis faites votre rapport à Theloria Capedombre au Poste allérien."}}
D[9999] = {"Gagner du temps",{"Altruis le Souffrant dans l'ouest de Nagrand vous a demandé de tuer 2 Légionnaires gangregarde, 3 Ingénieurs mo'arg et 8 Bricoleurs gan'arg."}}
D[10000] = {"Une présence indésirable",{"Tuez 12 Péons redimensionnés puis faites votre rapport au traqueur des ombres Kaide."}}
D[10001] = {"Le maître d'œuvre",{"Altruis le Souffrant dans l'ouest de Nagrand vous a demandé de récupérer les Plans du maître d'œuvre."}}
D[10002] = {"La messagère d'Aile-de-feu",{"Trouvez et tuez Lisaile Tissefeu, puis retournez voir Theloria Capedombre."}}
D[10003] = {"La messagère d'Aile-de-feu",{"Trouvez et tuez Lisaile Tissefeu, puis retournez voir le traqueur des ombres Kaide."}}
D[10004] = {"Patience et compréhension",{"Altruis le Souffrant dans l'ouest de Nagrand veut que vous apportiez les Plans du maître d'œuvre à Sal'salabim à Shattrath et que vous le convainquiez de vous aider."}}
D[10005] = {"Informer le lieur de terre Tavgren",{"Parlez au lieur de terre Tavgren juste à l'extérieur du Fourré cénarien dans la forêt de Terokkar."}}
D[10006] = {"Informer le lieur de terre Tavgren",{"Parlez au lieur de terre Tavgren juste à l'extérieur du Fourré cénarien dans la forêt de Terokkar."}}
D[10007] = {"Éclaircir les rangs",{"Tuez 10 Dévastateurs Mâche-les-os et 6 Brise-dos Mâche-les-os puis retournez voir Theloria Capedombre."}}
D[10008] = {"Ce qui se passe à Terokkar reste à Terokkar",{"Le traqueur des ombres Kaide veut que vous alliez tuer 10 Dévastateurs Mâche-les-os et 6 Brise-dos Mâche-les-os."}}
D[10009] = {"Casser des crânes",{"Sal'salabim de Shattrath veut que vous récupériez la Dette de Raliq, la Dette de Coosh'coosh et la Dette de Floon."}}
D[10010] = {"C'est si facile ?",{"Sal'salabim de Shattrath veut que vous retourniez voir Altruis le Souffrant dans l'ouest de Nagrand."}}
D[10011] = {"Le camp de forge Anéanti",{"Altruis le Souffrant dans l'ouest de Nagrand vous a demandé de détruire le Camp de forge Haine et le Camp de forge Peur."}}
D[10012] = {"Les plans des gangr'orcs",{"Apportez les Plans des gangr'orcs à Bertelm au Bastion allérien, dans la Forêt de Terokkar."}}
D[10013] = {"Une main invisible",{"Apportez les Plans des gangr'orcs à Rokag au Fort des Brise-pierres, dans la Forêt de Terokkar."}}
D[10014] = {"Le projet de la halte Aile-de-feu",{"Volez les quatre Feuilles de code de la bombe de mana et apportez-les au lieutenant Meridian au Poste allérien dans la forêt de Terokkar."}}
D[10015] = {"Le projet de la halte Aile-de-feu",{"Volez les quatre Feuilles de code de la bombe de mana et apportez-les au sergent Chawni au camp des Brise-pierres dans la forêt de Terokkar."}}
D[10016] = {"Les queues de worgs des bois",{"Bertelm du Bastion allérien veut que vous lui apportiez 12 Queues de worgs des bois. Vous pouvez prendre ces queues soit sur des worgs des bois, soit sur des worgs Alpha des bois."}}
D[10017] = {"Des réserves durement sollicitées",{"Apportez 8 Glandes à venin de croc-d'effroi à Sha'nir à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10018] = {"Les habits de l'esprit du loup",{"Apportez 12 Fourrures de worg des bois à Malukaz au fort des Brise-pierres."}}
D[10019] = {"Plus de glandes à venin"}
D[10020] = {"Un remède pour Zahlia",{"Apportez le Sang de Regard-de-pierre à Sha'nir à Shattrath.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10021] = {"Rétablir la Lumière",{"Ishanah veut que vous vous rendiez à l'avant-poste arakkoa à l'est de Shattrath et que vous utilisiez la Fiole bénite pour purifier l'Autel de l'est, l'Autel de l'ouest et l'Autel du nord.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10022] = {"L'insaisissable Gueule-de-fer",{"Apportez la Fourrure de Gueule-de-fer à Bertelm au Bastion allérien."}}
D[10023] = {"Le patriarche Gueule-de-fer",{"Apportez la Fourrure de Gueule-de-fer à Malukaz au fort des Brise-pierres."}}
D[10024] = {"Les visions de Voren'thal",{"Apportez 8 Yeux de basilic trempécaille à l'arcaniste Adyria à Shattrath.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10025] = {"Plus d'yeux de basilic"}
D[10026] = {"Perturbations magiques",{"Andarl du Bastion allérien veut que vous alliez tuer 10 Traqueurs dimensionnels."}}
D[10027] = {"Perturbations magiques",{"Tuez 10 Traqueurs dimensionnels et retournez voir Kurgatok au fort des Brise-pierres."}}
D[10028] = {"Calices de puissance",{"Apportez 8 Calices draeneï à Ros'eleth au Bastion allérien."}}
D[10029] = {"L'appel des esprits",{"L'anachorète Lyteera veut que vous trouviez son assistant, Soolaveen, à la Caravane des réfugiés dans le désert des Ossements de la forêt de Terokkar.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10030] = {"La récupération des os",{"Récupérez 10 Ossements sans repos. Apportez-les à Ramdor le Fol, juste à côté du côté ouest du Cercle d'observance à Auchindoun, qui se trouve au milieu du désert des Ossements de la forêt de Terokkar."}}
D[10031] = {"Aider les Perdus à trouver leur chemin",{"Détruisez 10 Esprits perdus et 10 Squelettes roués, puis parlez à Soolaveen à la Caravane de réfugiés, dans le désert des Ossements de la forêt de Terokkar."}}
D[10033] = {"On recherche : des Fouette-radius morts !",{"Tuez 20 Fouette-radius puis retournez voir Taela Vassanfin au Bastion allérien dans la forêt de Terokkar."}}
D[10034] = {"On recherche : des Fouette-radius morts !",{"Tuez 20 Fouette-radius puis retournez voir Mawg Trait-sinistre au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10035] = {"Torgos !",{"Faites venir Torgos à l'aide de la Carcasse de Trachela. Procurez-vous une Plume de la queue de Torgos et rapportez-la à Taela Vassanfin au Bastion allérien dans la forêt de Terokkar."}}
D[10036] = {"Torgos !",{"Faites venir Torgos à l'aide de la Carcasse de Trachela. Procurez-vous une Plume de la queue de Torgos et apportez-la à Mawg Trait-sinistre au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10037] = {"J'préférerais aller à la pêche",{"Apportez 8 Anguilles Scintécaille en parfait état à Seth à Shattrath."}}
D[10038] = {"Parler au soldat Weeks",{"Parlez au Soldat Weeks près de l'entrée nord de Grangol'var, dans la forêt de Terokkar."}}
D[10039] = {"Parler à l'éclaireur Neftis",{"Parlez à l'éclaireur Neftis près de l'entrée sud de Grangol'var, dans la forêt de Terokkar."}}
D[10040] = {"Qui sont-ils ?",{"Parlez avec l'Initié ténébreux, le Travailleur ténébreux et le Conseiller ténébreux en portant le déguisement. Puis retournez voir le soldat Weeks à Grangol'var dans la forêt de Terokkar."}}
D[10041] = {"Qui sont-ils ?",{"Parlez avec l'Initié ténébreux, le Travailleur ténébreux et le Conseiller ténébreux en portant le déguisement. Puis retournez voir l'éclaireur Neftis à Grangol'var dans la forêt de Terokkar."}}
D[10042] = {"Tuer le Conseil des ombres !",{"Tuez 10 Exécuteurs ténébreux, 10 Invocateurs ténébreux et le Maître d'ombre Dolent, puis retournez auprès du lieutenant Gravillemartel au Bastion allérien dans la forêt de Terokkar."}}
D[10043] = {"Tuer le Conseil des ombres !",{"Tuez 10 Exécuteurs ténébreux, 10 Invocateurs ténébreux et le Maître d'ombre Dolent, puis retournez auprès de la conseillère Faila au fort des Brise-pierres dans la forêt de Terokkar."}}
D[10044] = {"Une visite à la grande-mère",{"Parlez à la grande-mère Geyah et écoutez ce qu'elle a à vous dire."}}
D[10045] = {"Composants matériels",{"La grande-mère Geyah de Garadar en Nagrand vous a demandé de cueillir 1 Racine d'Olemba, 1 Canneberge, 1 Palme telaari et 1 Épine-de-dragon."}}
