D[10701] = {"Briser Néantroche",{"Tuez Néantroche, puis présentez-vous au Chef-de-fusée Karlingue dans la Zone 52 de Raz-de-Néant."}}
D[10702] = {"Un travail de grunt...",{"Le suzerain Or'barokh du village d'Ombrelune dans la vallée d'Ombrelune vous demande de tuer 20 spécimens de la Faune de la vallée d'Ombrelune.","","Ces créatures comprennent les Sangliers gangrenés, les Chimères Ailevile et les Pinceurs Brûlecoquille. N'importe quelle combinaison conviendra."}}
D[10703] = {"Mettez des bottes...",{"Le thane Yoregar du bastion des Marteaux-hardis dans la vallée d'Ombrelune vous demande de tuer 20 spécimens de la faune de la vallée d'Ombrelune.","","Ces créatures comprennent les Sangliers gangrenés, les Chimères Ailevile et les Pinceurs Brûlecoquille. N'importe quelle combinaison fera l'affaire."}}
D[10704] = {"Comment pénétrer dans l'Arcatraz",{"A'dal vous a chargé de récupérer les Pièces supérieures et inférieures de la clé de l'Arcatraz. Rapportez-les-lui et il s'en servira pour vous confectionner la Clé de l'Arcatraz."}}
D[10705] = {"Le voyant Udalo",{"Trouvez le voyant Udalo à l'intérieur de l'Arcatraz dans le Donjon de la Tempête."}}
D[10706] = {"Un mystérieux présage",{"Retournez voir Akama à la Cage de la gardienne dans la vallée d'Ombrelune."}}
D[10707] = {"La terrasse Ata'mal",{"Allez au sommet de la Terrasse Ata'mal dans la vallée d’Ombrelune, et procurez-vous le Cœur de fureur. Retournez voir Akama à la Cage de la gardienne dans la vallée d'Ombrelune quand vous aurez accompli cette tâche."}}
D[10708] = {"La promesse d'Akama",{"Apportez le Médaillon de Karabor à A'dal, à Shattrath."}}
D[10709] = {"Réunion",{"Parlez à Rexxar, au bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10710] = {"Vol d'essai : la Crête chantante",{"Signez la Décharge de Tally, puis allez parler à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium."}}
D[10711] = {"Vol d'essai : le point d'ancrage de Razaan",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium."}}
D[10712] = {"Vol d'essai : la sylve Ruuan",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium. Lors du vol vers la Sylve Ruuan, faites tourner la Girouette néantine. Remettez la Girouette néantine tournoyante à O'Mally Rossecoquin au Bosquet éternel."}}
D[10713] = {"... et un temps pour l'action",{"Tuez 10 Elagueurs du culte du Ver."}}
D[10714] = {"Sur les ailes de l'Esprit",{"Trouvez un Sous-chef de la Masse-sanglante et un Devin de la Masse-sanglante en pleine conversation, et utilisez le Sifflet de Rexxar pour appeler Esprit, afin qu’il les espionne."}}
D[10715] = {"Dans le Goulet bouillonnant",{"Procurez-vous 7 Glandes à venin de perceur de croûte."}}
D[10716] = {"Test Flight: Raven's Wood <needs reward>",{"Parlez à Rally Rossecoquin pour utiliser le Zephyrium Capacitorium. Puis retournez voir Tally Rossecoquin au Poste de Toshley."}}
D[10717] = {"Du braconnage chez les braconniers",{"Procurez-vous 5 Filets du culte du Ver."}}
D[10718] = {"Les esprits entendent des voix...",{"Parlez à Rexxar au Bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10719] = {"Vous avez eu la note ?",{"Apportez la Note de rendez-vous au Gardien des arbres Chawn au Bosquet éternel dans les Tranchantes."}}
D[10720] = {"Les plus petites des créatures",{"Utilisez le Tambour en cuir de kodo au Terrier des marmottes. Quand vous aurez pris le contrôle de la Marmotte, empoisonnez les trois tonneaux dans le camp des Masse-sanglante."}}
D[10721] = {"Un tour de cochon pour Grulloc",{"Procurez-vous le Sac de Grulloc."}}
D[10722] = {"Rendez-vous au convent de l'Aile noire",{"Rassemblez suffisamment de Guenilles sur les différents sectateurs du Ver pour vous fabriquer un Déguisement de surveillant. Utilisez ce déguisement pour vous rendre au rendez-vous de Kolphis Sombrécaille."}}
D[10723] = {"Gorgrom le Mange-dragon",{"Procurez-vous 3 Totems macabres sur les ogres de Roche'mok. Utilisez le Piège de Sablecrin à l'Autel de Gorgrom pour invoquer et tuer Gorgrom le Mange-dragon.","","Une fois Gorgrom mort, placez les 3 Totems macabres près de son cadavre."}}
D[10724] = {"Prisonnier de la Flèchelame",{"Tuez des Ogres de Flèchelame pour vous procurer la Clé de la cage à wyverne. Une fois que vous l'aurez, allez à la Cage à wyverne et utilisez le Sifflet d'Esprit pour appeler Esprit, qui déverrouillera la cage et libérera Leokk."}}
D[10725] = {"L'excellence auprès de l'Œil pourpre",{"Apportez votre Chevalière pourpre à l'archimage Leryda au défilé de Deuillevent après être devenu Exalté auprès de l'Œil pourpre."}}
