D[10737] = {"Le toucher du maître",{"Rendez-vous aux Grottes du temps et persuadez Medivh d'accepter votre Clé de l'apprenti réparée."}}
D[10738] = {"Une distinction pour services rendus",{"Apportez votre Chevalière pourpre à l'archimage Leryda au défilé de Deuillevent après être devenu Révéré auprès de l'Œil pourpre."}}
D[10739] = {"Une distinction pour services rendus",{"Apportez votre Chevalière pourpre à l'archimage Leryda au défilé de Deuillevent après être devenu Révéré auprès de l'Œil pourpre."}}
