D[10742] = {"Cartes sur table",{"Utilisez le Cor de bataille de Rexxar à l'Autel de Goc, puis tuez Goc."}}
D[10744] = {"Des nouvelles de la victoire",{"Retournez au Bastion des Marteaux-hardis et parlez à Kurdran Marteau-hardi."}}
D[10745] = {"Des nouvelles de la victoire",{"Retournez au village d'Ombrelune et parlez au suzerain Or'barokh."}}
D[10747] = {"Les dragonnets du culte du Ver",{"Utilisez le Filet à dragonnet noir pour capturer 10 Dragonnets noirs du culte du Ver."}}
D[10748] = {"Maxnar doit mourir !",{"Tuez Maxnar le Cendregueule."}}
D[10749] = {"Le poison du baron Sablecrin",{"Livrez le Poison du baron Sablecrin à Rexxar, au bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10750] = {"La voie de la Conquête",{"Voyagez vers la Voie de la Conquête dans la Vallée d’Ombrelune."}}
D[10751] = {"Ouvrir la voie",{"Tuez 20 Soldats éclipsions, 10 Cavaliers éclipsions et 10 Lieurs de sort éclipsions."}}
D[10752] = {"En direction d'Orneval",{"Parler à Raene Mène-loup à Astranaar."}}
D[10753] = {"Tuer les bêtes sauvages",{"Tuer 4 Gangreliges ailécaille, 4 Gangreliges Crocs-lames et 2 Corrupteurs gangrenés."}}
D[10754] = {"L'entrée dans la citadelle",{"Apportez le Moule à clé préparé au commandant de corps Danath au Bastion de l'Honneur, dans la Péninsule des Flammes infernales."}}
D[10755] = {"L'entrée dans la citadelle",{"Apportez le Moule à clé préparé à Nazgrel, à Thrallmar, dans la Péninsule des Flammes infernales."}}
D[10756] = {"Le grand maître Rohok",{"Apportez le Moule à clé préparé à Rohok à Thrallmar, dans la Péninsule des Flammes infernales."}}
D[10757] = {"La demande de Rohok",{"Apportez 4 Barres de gangrefer, 2 Poussières des arcanes et 4 Granules de feu à Rohok à Thrallmar dans la péninsule des Flammes infernales."}}
D[10758] = {"Plus chaud que l'enfer",{"Détruisez un Saccageur gangrené dans la péninsule des Flammes infernales et plongez le Moule à clé inachevé dans ce qu'il en reste. Apportez le Moule à clé carbonisé à Rohok à Thrallmar."}}
D[10759] = {"Trouver le déserteur",{"Trouvez Parshah dans les Champs de magma et parlez-lui."}}
D[10760] = {"Les débris de Sketh'lon",{"Récupérez la Page 1 du journal du commandant de Sketh'lon, la Page 2 du journal du commandant de Sketh'lon et la Page 3 du journal du commandant de Sketh'lon sur des arakkoa du sombre Conclave aux Débris sketh'lon et apportez-les au sergent Kargrul au village d'Ombrelune."}}
D[10761] = {"Trouver le déserteur",{"Trouvez Parshah dans les Champs de magma et parlez-lui."}}
D[10762] = {"Le grand maître Dumphry",{"Apportez le Moule à clé préparé à Dumphry au bastion de l'Honneur."}}
D[10763] = {"La demande de Dumphry",{"Apportez 4 Barres de gangrefer, 2 Poussières des arcanes et 4 Granules de feu à Dumphry au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[10764] = {"Plus chaud que l'enfer",{"Détruisez un Saccageur gangrené dans la péninsule des Flammes infernales et plongez le Moule à clé inachevé dans ce qu'il en reste. Apportez le Moule à clé carbonisé à Dumphry au bastion de l'Honneur."}}
D[10765] = {"Le choc des mondes...",{"Tuez la Chancelière Feuillesang et Corok le Puissant, et récupérez les Ordres d'Illidan."}}
D[10766] = {"Le site d'invasion Cataclysme",{"Présentez-vous à Plexi au Site d'invasion Cataclysme."}}
D[10767] = {"Le site d'invasion Cataclysme",{"Présentez-vous à Nakansi au Site d'invasion Cataclysme."}}
D[10768] = {"Les tabards des Illidari",{"Récupérez 10 Tabards illidari."}}
D[10769] = {"De la dissension dans les rangs...",{"Tuez 5 Colosses affolés en portant le déguisement d'un elfe de sang illidari, et retournez voir le suzerain Or'barokh au village d'Ombrelune dans la vallée d'Ombrelune. Il voudra aussi que vous lui rendiez son Lance-fusée de Kor'kron."}}
D[10770] = {"Petites braises",{"Boimoussu l'Ancien veut que vous tuiez 8 Diablotins de brûlure avant de retourner le voir à la Sylve Ruuan."}}
D[10771] = {"Tiré des cendres",{"Boimoussu l'Ancien veut que vous voyagiez jusqu'à Skald pour y planter des Graines de racine-de-fer dans trois monticules différents de Terre volcanique fertile et que vous retourniez ensuite le voir dans la Sylve Ruuan."}}
D[10772] = {"La voie de la Conquête",{"Voyagez vers la Voie de la Conquête dans la Vallée d’Ombrelune."}}
D[10773] = {"Ouvrir la voie",{"Tuez 20 Soldats éclipsions, 10 Cavaliers éclipsions et 5 Fils de Corok."}}
D[10774] = {"Elfe de sang + Géant = ???",{"Tuez la Chancelière Feuillesang et Corok le Puissant, et récupérez les Ordres d’Illidan."}}
D[10775] = {"Les tabards des Illidari",{"Récupérez 10 Tabards illidari."}}
D[10776] = {"De la dissension dans les rangs...",{"Tuez 5 Colosses affolés en portant le déguisement d'un agent d'Illidan, et retournez voir le thane Yoregar au bastion des Marteaux-hardis dans la vallée d'Ombrelune. Il voudra aussi que vous lui rendiez son Lance-fusée marteau-hardi."}}
D[10777] = {"Le totem d'Asghar",{"Apportez le Totem de guerre de Sketh'lon à Parshah dans les Champs de magma."}}
D[10778] = {"Le bâtonnet de Lianthe",{"Procurez-vous la Clé de Lianthe sur un elfe de sang de la Halte de l'éclipse, utilisez-la pour ouvrir le Coffre-fort de Lianthe et prenez-y le Bâtonnet de Lianthe. Apportez le bâtonnet à Parshah dans les Champs de magma."}}
D[10779] = {"La voie du chasseur",{"Parler à la chasseresse Kella Arquenuit QUELQUE PART."}}
D[10780] = {"Les plumes de Sketh'lon",{"Rassemblez 8 Plumes de Sketh'lon et apportez-les à Parshah dans les Champs de magma."}}
D[10781] = {"La bataille du Guet cramoisi",{"Combattez les forces d'Illidan au Guet cramoisi et survivez !","","Allez voir A'dal à Shattrath si vous avez réussi à vaincre."}}
D[10782] = {"L'imprégnation du bourdon",{"Portez le Bourdon inachevé, voyagez jusqu'à l'Autel de la damnation et utilisez-le en vous tenant près de Gul'dan. Quand le bourdon aura été imprégné d'énergie, retournez voir Parshah dans les Champs de magma."}}
D[10783] = {"Le baron Sablecrin",{"Parlez au baron Sablecrin au Cercle de sang, dans les Tranchantes."}}
D[10784] = {"Anéantir le camp Masse-sanglante",{"Tuez 10 Marteleurs de la Masse-sanglante et 5 Démonistes de la Masse-sanglante."}}
D[10785] = {"C'est un piège !",{"Apportez le Piège de feu draconique à Rexxar au bastion des Sire-tonnerre dans les Tranchantes."}}
D[10786] = {"Carnage à Roche'mok",{"Massacrez 5 Brutes de Roche'mok et 3 Chamans de Roche'mok, puis retournez voir Tor'chunk Doublegriffes au bastion des Sire-tonnerre, dans les Tranchantes."}}
D[10788] = {"Retourner voir Talionia",{"Parlez à Talionia à Lune-d'argent."}}
D[10789] = {"Retourner voir Carendin Halgar",{"Parlez à Carendin Halgar à Fossoyeuse."}}
D[10790] = {"Retourner voir Gan'rul Œil-sanglant",{"Parlez à Gan'rul Œil-sanglant à Orgrimmar."}}
D[10791] = {"Accueillir l'esprit du loup",{"Utilisez l'Encens de cérémonie près des bougies dans la hutte de Malukaz et assistez à la cérémonie. Quand elle sera terminée, parlez à nouveau à Malukaz."}}
D[10792] = {"Que Zeth'Gor brûle !",{"Tuez les Péons de l'Orbite-sanglante pour prendre leurs torches, allumez celles-ci à la forge de Zeth'Gor, puis jetez les torches enflammées sur les bâtiments de Zeth'Gor."}}
D[10793] = {"Le journal de Val'zareq : Des présages de guerre",{"Trouvez Marcus Auralion, grand général des Sha'tar, au Guet cramoisi.","","Cherchez-le à l'intérieur d'une prison cristalline."}}
D[10794] = {"Les voleurs de la Main brisée",{"Parlez à Shenthul à Orgrimmar."}}
D[10795] = {"Un rendez-vous avec Dorgok",{"Tuez Dorgok au camp de la Masse-sanglante."}}
D[10796] = {"Anéantissez le camp Masse-sanglante !",{"Tuez 10 Marteleurs de la Masse-sanglante et 5 Démonistes de la Masse-sanglante."}}
D[10797] = {"Une faveur des gronns",{"Apportez la Faveur de Gorgrom au commandant Haephus Lamuraille au Bosquet éternel, dans les Tranchantes."}}
D[10798] = {"Rendre visite au baron",{"Parlez au Baron Sablecrin au Cercle de sang, dans les Tranchantes."}}
D[10799] = {"Dans le Goulet bouillonnant",{"Procurez-vous 7 Glandes à venin de perceur de croûte."}}
D[10800] = {"Bonne nuit, l'horrible !",{"Trouvez le Sac de Grulloc."}}
D[10801] = {"C'est un piège !",{"Apportez le Piège de feu draconique au commandant Haephus Lamuraille au Bosquet éternel dans les Tranchantes."}}
D[10802] = {"Gorgrom le Mange-dragon",{"Procurez-vous 3 Totems macabres sur les ogres de Roche'mok. Utilisez le Piège de Sablecrin à l'Autel de Gorgrom pour invoquer et tuer Gorgrom le Mange-dragon.","","Une fois Gorgrom mort, placez les 3 Totems macabres près de son cadavre."}}
D[10803] = {"Carnage à Roche'mok",{"Massacrez 5 Brutes de Roche'mok et 3 Chamans de Roche'mok."}}
D[10804] = {"Un peu de gentillesse",{"Mordenai, aux champs de l'Aile-du-Néant, dans la vallée d'Ombrelune, veut que vous nourrissiez 8 Drakes Aile-du-Néant adultes."}}
D[10805] = {"Massacre au repaire de Gruul",{"Tuez 10 Massacreurs de Flèchelame, 5 Mages de bataille de Flèchelame, 5 Ravageurs de Flèchelame et leur chef, Fingrom."}}
D[10806] = {"Cartes sur table",{"Utilisez la Chevalière de Sablecrin à l’Autel de Goc, puis tuez Goc."}}
D[10807] = {"Les roués cendrelangues",{"Varen le Récupérateur veut que vous partiez pour les Ruines de Baa'ri afin d'y tuer 3 Dresseurs cendrelangues, 4 Guerriers cendrelangues et 6 Chamans cendrelangues.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10808] = {"Contrecarrer le sombre Conclave",{"Tuez les Ritualistes du sombre Conclave et utilisez le Bâton de Parshah pour mettre fin à leur rituel d'invocation. Retournez ensuite voir Parshah dans les Champs de magma."}}
D[10809] = {"On recherche : maître-worg Kruush",{"Tuez le Maître-worg Kruush et apportez sa tête au Capitaine Rugissombre dans le Poste de Brise-échine."}}
D[10810] = {"Le masque endommagé",{"Apportez le Masque endommagé à O'Mally Rossecoquin au Bosquet éternel, dans les Tranchantes."}}
D[10811] = {"Trouvez Neltharaku",{"Partez à la recherche de Neltharaku, le protecteur du Vol de l'Aile-du-Néant."}}
D[10812] = {"Le masque mystère",{"Apportez le Masque mystère au seigneur sauvage Antelarion au Bosquet éternel, dans les Tranchantes."}}
D[10813] = {"Les yeux de Grillok",{"Utilisez l'Éclat de Zezzak pour capturer un Oeil de Grillok, puis approchez-vous du Chaudron de Zezzak pour l'extraire. Une fois que ce sera fait, rendez son éclat à Zezzak."}}
D[10814] = {"L'histoire de Neltharaku",{"Parlez à Neltharaku et écoutez son histoire."}}
D[10815] = {"Le journal de Val'zareq : Des présages de guerre",{"Trouvez Marcus Auralion, grand général des Sha'tar, au Guet cramoisi.","","Cherchez-le à l'intérieur d'une prison cristalline."}}
D[10816] = {"La reconquête des terres sacrées",{"Le redresseur de torts Aluumen veut que vous tuiez 8 Pourfendeurs ombrelune, 8 Élus ombrelune et 4 Tisseurs d'ombre ombrelune.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10817] = {"La grande vindicte",{"Varen le Récupérateur veut que vous tuiez 8 Pourfendeurs ombrelune, 8 Élus ombrelune et 4 Tisseurs d'ombre ombrelune.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l'Aldor."}}
D[10818] = {"Le baron Sablecrin veut vous voir",{"Parlez au baron Sablecrin au Cercle de sang, dans les Tranchantes."}}
D[10819] = {"Le masque à gaz de gangrelige",{"Portez le Masque à gaz de gangrelige et utilisez le Communicateur de la Légion au Camp de Forge : Colère, dans les Tranchantes."}}
D[10820] = {"Ton ennemi tu tromperas",{"Tuez 4 Domestiques Forge-ruine et 4 Ingénieurs Forge-ruine."}}
D[10821] = {"Vous êtes virée !",{"Tuez Vocifuneste."}}
D[10822] = {"Une chevalière Solfurie"}
D[10823] = {"De nouvelles chevalières Solfurie"}
D[10824] = {"Les chevalières Solfurie",{"La Mage de bataille Vyara du Sanctum des Étoiles veut que vous lui apportiez 10 Chevalières Solfurie.","","Accomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de la faction Aldor."}}
D[10825] = {"La vérité toute nue",{"Apportez l'Orbe des Grishna au Gardien des arbres Chawn, au Bosquet éternel, dans les Tranchantes."}}
D[10826] = {"Les marques de Sargeras",{"Remettez 10 Marques de Sargeras au Messager Saronen, dans la Vallée d'Ombrelune.","","Accomplir des quêtes pour l'Aldor fera baisser votre réputation auprès des Clairvoyants."}}
D[10827] = {"De nouvelles marques de Sargeras"}
D[10828] = {"Une marque de Sargeras"}
D[10829] = {"Arbrobole doit savoir",{"Parlez à Arbrobole, un Ancien du savoir qui vit dans le Bois aux corbeaux, dans les Tranchantes."}}
D[10830] = {"Exorciser les arbres",{"Collectez 5 Orbes grishnath et 5 Plumules redoutables puis combinez-les pour en faire des Plumes d'exorcisme. Utilisez ces plumes pour procéder à l'exorcisme et tuer 5 Esprits Kui-kui sortis des Barbes-feuillues du Bois aux corbeaux."}}
D[10831] = {"Devenir un tailleur d'étoffe lunaire",{"Utilisez le Carré de tisse-néant imprégné en vous tenant près du puits de lune du Refuge cénarien pour créer un Échantillon d'étoffe lunaire primordiale. Apportez l'échantillon terminé à Nasmara Lunechant dans la Ville basse de Shattrath.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en couture."}}
D[10832] = {"Devenir un tailleur de feu-sorcier",{"Apportez un échantillon d'Essence d'âme en peine du Néant à Gidge Tisse-sort dans la Ville basse de Shattrath.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en couture."}}
D[10833] = {"Devenir un tailleur de tisse-ombre",{"Utilisez le Cristal des ombres profondes près de l'autel des Ombres pour renforcer votre harmonisation avec l'autel, puis retournez voir Andrion Sombrefileur dans la Ville basse de Shattrath.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en couture."}}
D[10834] = {"Grillok « Sombrœil »",{"Tuez Grillok Sombrœil et rapportez le Couvre-œil de Grillok à Zezzak au Poste de Brise-échine."}}
D[10835] = {"L'apothicaire Antonivitch",{"Apportez les Découvertes d’Albreck à l’Apothicaire Antonivitch à Thrallmar, dans la Péninsule des Flammes infernales."}}
D[10836] = {"Infiltrer la forteresse Gueule-de-dragon",{"Neltharaku, qui vole au-dessus des Champs de l'Aile-du-Néant dans la Vallée d'Ombrelune, veut que vous tuiez 15 Orcs Gueule-de-dragon.","","N'importe quels orcs de la Forteresse Gueule-de-dragon feront l'affaire."}}
D[10837] = {"Vers l'escarpement de l'Aile-du-Néant !",{"Neltharaku, qui vole au-dessus des champs de l'Aile-du-Néant dans la vallée d'Ombrelune, veut que vous ramassiez 12 cristaux vignéants à l'escarpement de l'Aile-du-Néant."}}
D[10838] = {"Le scrutateur démonien",{"Utilisez le Scrutateur démonien dans le Bassin des Flammes infernales, attendez qu'il soit harmonisé, puis faites un relevé.","","Rapportez le Scrutateur démonien et le Relevé du scrutateur démonien à l'Apothicaire Antonivitch à Thrallmar."}}
D[10839] = {"Voile Skith : Sombrepierre de Terokk",{"Utilisez le Bâtonnet de purification sur la Sombrepierre de Terokk au Voile Skith puis retournez auprès de Kirrik l'Eveillé à la Caravane des réfugiés, dans le désert des Ossements."}}
D[10840] = {"Le tombeau des lumières",{"Le Grand prêtre Orglum veut que vous vous rendiez au Tombeau des lumières et que vous tuiez 10 Néantomanciens éthériens et 10 Pilleurs éthériens avant de revenir le voir à la Caravane de réfugiés."}}
D[10841] = {"Le messager vengeur"}
D[10842] = {"Âmes vengeresses",{"Le grand prêtre Orglum veut que vous vous rendiez au Tombeau des lumières et que vous vainquiez 5 Draeneï vengeurs."}}
D[10843] = {"Depuis des temps immémoriaux...",{"Tuez Gnosh Brognat, le chef des ogres de l'avant-poste Flèchelame."}}
D[10844] = {"Le camp de forge Colère"}
D[10845] = {"Tuer la mère des couvées",{"Tuez Aile-de-peur."}}
D[10846] = {"Comprendre les Mok'Nathal",{"Tuez Vekh, chef des arakkoa vekh'nir."}}
D[10847] = {"Les yeux de Skettis",{"Apportez l'Œil de Reskk et l'Œil de Shienor à Rilak le Racheté dans le quartier de la Ville basse de Shattrath."}}
D[10848] = {"Voile Rhaze : Un mal sans vie",{"Tuez 4 Esprits Serres-mort, 4 Esprits hurlants et 2 Esprits corbeaux puis revenez voir Kirrik l'Eveillé à la Caravane des réfugiés."}}
D[10849] = {"À la recherche de Kirrik",{"Apportez la Missive de Rilak à Kirrik l'Eveillé à la Caravane des réfugiés, dans le désert des Ossements."}}
D[10850] = {"De l'essence de Néant dans un moteur gangrefeu"}
D[10851] = {"Les totems de mon ennemi",{"Collectez 5 Totems flèchelame."}}
D[10852] = {"Les amis perdus",{"Ethan veut que vous trouviez 12 de ses amis disparus au Voile Skith et que vous reveniez ensuite le voir à la Caravane des réfugiés."}}
D[10853] = {"L'appel des esprits",{"Utilisez les Totems d'appel des esprits pour collecter 8 Esprits de drakes du Néant inférieurs."}}
D[10854] = {"La force de Neltharaku",{"Neltharaku, qui vole au-dessus des champs de l'Aile-du-Néant dans la vallée d'Ombrelune, veut que vous libériez 5 Drakes de l'Aile-du-Néant asservis."}}
D[10855] = {"Les saccageurs gangrenés ne passeront pas !",{"Récupérez 5 mesures de Gaz de Néant condensé auprès des Mekgénieurs gan'arg de la Base de forge : Oubli, au nord-ouest de la Foudreflèche, et chargez-les dans un Saccageur gangrené inactif proche. Revenez voir le Traqueur-du-Néant Nauthis quand vous aurez terminé."}}
D[10856] = {"La meilleure défense",{"Le Traqueur-du-Néant Nauthis veut que vous tuiez 12 Porte-courroux à la Base de forge Géhenne, au nord de la Foudreflèche."}}
D[10857] = {"Téléportez-moi ça !",{"Le Traqueur-du-Néant Nauthis veut que utilisiez le Bâtonnet d'interférence mentale sur les mo'arg du Camp de forge Géhenne, et utilisez leur capacité pour Faire exploser le téléporteur sur les trois téléporteurs du camp de forge."}}
D[10858] = {"Karynaku",{"Trouvez Karynaku à la Forteresse Gueule-de-dragon."}}
D[10859] = {"Réunir les orbes",{"Utilisez le Totem collecteur d'orbe pour collecter 15 Orbes de lumière razaani."}}
D[10860] = {"Délices de Mok'Nathal",{"Récupérez 3 Côtelettes de raptor et 3 Chairs de serpent."}}
D[10861] = {"Voile Lithic : Frappe préventive",{"Cassez les œufs maudits au Voile Lithic. Rachetez 3 Oisillons et tuez 3 Oisillons maléfiques avant de retourner auprès de Kirrik l'Eveillé à la Caravane des réfugiés."}}
D[10862] = {"Se rendre à la Horde",{"Rokag veut que vous trouviez Rilak le Racheté dans le quartier de la Ville basse à Shattrath et que vous exigiez que lui et son peuple se rendent à la Horde."}}
D[10863] = {"Les secrets des arakkoa",{"Dame Dena Kennedy veut que vous alliez trouver Rilak le Racheté dans le quartier de la Ville basse à Shattrath pour découvrir quels secrets des arakkoa il est prêt à partager."}}
D[10864] = {"Le fardeau des âmes",{"Tuez 20 Orcs de la Main brisée, puis retournez voir l'Apothicaire Antonivitch à Thrallmar."}}
D[10865] = {"Informez Leoroxx !",{"Parlez à Leoroxx de ce que préparent les éthériens razaani. Vous le trouverez au village de Mok'Nathal dans les Tranchantes."}}
D[10866] = {"Zuluhed le Fourbu",{"Tuez Zuluhed le Fourbu et récupérez la Clé de Zuluhed. Utilisez-la sur les Chaînes de Zuluhed pour libérer Karynaku."}}
D[10867] = {"La seule réponse possible",{"Récupérez la Collection d'âmes."}}
D[10868] = {"Le sentier de la guerre arakkoa",{"La conseillère Faila vous demande de tuer 14 Serrénites shienor et 6 Ensorceleurs shienor avant de revenir la voir au Fort des Brise-pierres."}}
D[10869] = {"Restreindre la nuée",{"Le lieutenant Gravillemartel vous demande de tuer 14 Serrénites shienor et 6 Ensorceleurs shienor avant de revenir le voir au Bastion allérien."}}
D[10870] = {"Allié du vol du Néant",{"Permettez à Karynaku de vous ramener auprès de Mordenai dans les Champs de l'Aile-du-Néant."}}
D[10871] = {"Allié du vol du Néant",{"Permettez à Karynaku de vous ramener auprès de Mordenai dans les Champs de l'Aile-du-Néant."}}
D[10872] = {"Zuluhed le Fourbu",{"Tuez Zuluhed le Fourbu et récupérez la Clé de Zuluhed. Utilisez-la sur les Chaînes de Zuluhed pour libérer Karynaku."}}
D[10873] = {"Pris dans la nuit",{"L’Éclaireur Navrin veut que vous vous rendiez sur la Crête de Toile-néant et que vous libériez 6 Guerriers sha'tar entoilés. Revenez ensuite le voir au Camp de base sha'tari."}}
D[10874] = {"Voile Shalas : Feux de signal",{"Kirrik l'Eveillé de la Caravane des réfugiés vous demande d'éteindre les quatre feux de signal du Voile Shalas."}}
D[10875] = {"Se présenter à Nazgrel",{"Parlez avec Nazgrel à Thrallmar, dans la Péninsule des Flammes infernales."}}
D[10876] = {"Le pied de la citadelle",{"Tuez le Commandant de corps Gorax, placez le Défi de la Horde sur son cadavre, tuez la Main de Kargath, puis rapportez la Tête de la Main de Kargath à Nazgrel dans Thrallmar."}}
D[10877] = {"La relique de l'effroi",{"Chênuin veut que vous partiez vers l'est pour la Caravane abandonnée afin de récupérer la Relique de l'effroi. Revenez voir Chênuin quand cette tâche sera achevée."}}
D[10878] = {"Avant que l'ombre...",{"Mekeda de la Caravane de réfugiés veut que vous tuiez 8 Tirailleurs de la Cabale, 4 Tisse-sorts de la Cabale et 2 Initiés de la Cabale."}}
D[10879] = {"L'offensive de Skettis",{"Repoussez les attaquants et parlez à Rilak le Racheté."}}
D[10880] = {"Les ordres de la Cabale",{"Remettez les Ordres de la Cabale à Mekeda, à la Caravane de réfugiés, dans le Désert des Ossements."}}
D[10881] = {"La tombe des ombres",{"Rendez-vous dans la Tombe des ombres, à l'ouest de la Caravane de réfugiés. Récupérez-y le Drapé d'Arunen, le Marteau de K'alen et le Parchemin d'Atalor. Lorsque vous aurez terminé, retournez voir Mekeda à la Caravane de réfugiés."}}
D[10882] = {"Messager funeste",{"Vous avez été chargé d'aller sur le satellite de l'Arcatraz du donjon de la Tempête et de tuer le Messager Cieuriss. Revenez voir A'dal à la Terrasse de la Lumière de Shattrath quand ce sera fait."}}
D[10883] = {"La clé de la Tempête",{"Parlez à A'dal à Shattrath."}}
D[10884] = {"L'épreuve des naaru : Miséricorde",{"A'dal de Shattrath vous demande de prendre la Hache inutilisée du bourreau dans les Salles brisées de la citadelle des Flammes infernales.","","Cette quête doit être accomplie en mode de difficulté du donjon Héroïque."}}
D[10885] = {"L'épreuve des naaru : Force",{"A'dal de Shattrath vous demande de récupérer le Trident de Kalithresh et l'Essence de Marmon.","","Cette quête doit être accomplie en mode de difficulté du donjon Héroïque."}}
D[10886] = {"L'épreuve des naaru : Ténacité",{"A'dal de Shattrath vous demande de sauver Milhouse Tempête-de-mana de l'Arcatraz du donjon de la Tempête.","","Cette quête doit être accomplie en mode de difficulté du donjon Héroïque."}}
D[10887] = {"Sortir du tombeau",{"Aidez Akuno a trouver le chemin de la Caravane de réfugiés. Lorsque vous aurez terminé cette quête, parlez à Mekeda."}}
D[10888] = {"L'épreuve des naaru : Magtheridon",{"A'dal de Shattrath vous demande de tuer Magtheridon."}}
D[10889] = {"Retour à Shattrath",{"Rendez-vous à Shattrath et parlez à Rilak le Racheté dans la Ville Basse."}}
D[10891] = {"L'armure impériale en plaques",{"Parlez à Derotain Siroteboue à Gadgetzan, en Tanaris."}}
D[10892] = {"L'armure impériale en plaques",{"Parlez à Derotain Siroteboue à Gadgetzan, en Tanaris."}}
D[10893] = {"Longue-queue est le pivot",{"Éliminez Draaca Longue-queue, le chef des sectateurs du Ver dans le Tunnel Crâne-du-ver."}}
D[10894] = {"Le guetteur du Crâne-du-ver",{"Apportez la Note de rendez-vous au Guetteur Lunombrage à l'entrée du tunnel Crâne-du-ver dans les Tranchantes."}}
D[10895] = {"Que Zeth'Gor brûle !",{"Utilisez les Balises fumigènes sur chacune des tours de Zeth'Gor, puis retournez voir le Chef d'escadrille Dabir'ee à la Halte de l'expédition."}}
D[10896] = {"Les protecteurs infestés",{"Lakotae veut que vous tuiez 25 Mites des bois puis que vous reveniez le voir à la Caravane de réfugiés. On peut trouver les mites à l'intérieur des corps des Enragés des forêts pourrissants et des Marche-racine infestés."}}
D[10897] = {"Maître des potions",{"Lauranna Thar'well veut que vous vous rendiez dans la Botanica du donjon de la Tempête et que vous récupériez le Guide pratique du botaniste sur le Grand botaniste Freywenn. De plus, elle veut que vous lui rameniez 5 Potions de super-soins, 5 Potions de super-mana et 5 Potions de sommeil sans rêve majeures.","","*ATTENTION !* Vous ne pouvez choisir qu'une seule spécialité d'alchimie."}}
D[10898] = {"Aile-du-ciel",{"Escortez Aile-du-ciel et allez voir Rilak le Racheté à Shattrath."}}
D[10899] = {"Maître de la transmutation",{"Zarevhi, de la Foudreflèche du Raz-de-Néant, veut que vous lui rameniez 4 Pouvoirs primordiaux.","","*ATTENTION !* Vous ne pouvez choisir qu'une seule spécialité d'alchimie."}}
D[10900] = {"La marque de Vashj"}
D[10901] = {"Le gourdin de Kar'desh",{"Skar'this l'Hérétique, dans les Enclos aux esclaves héroïques du Réservoir de Glissecroc, veut que vous lui apportiez la Chevalière terrestre et la Chevalière flamboyante."}}
D[10902] = {"Maître des élixirs",{"Partez pour les Grottes du temps dans le Noir Marécage et procurez-vous 10 Essences d'infinité sur les Seigneurs des failles et Gardiens des failles. Apportez-les avec 5 Élixirs de défense majeure, 5 Élixirs de maîtrise et 5 Élixirs d'agilité majeure à Lorokeem dans la Ville basse de Shattrath.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en alchimie."}}
D[10903] = {"Retour au bastion de l'Honneur",{"Parlez à Klatu, à l'auberge du Bastion de l'Honneur."}}
D[10904] = {"La récolte des munitions gangrenées",{"Récupérez 5 Boulets de gangrecanon."}}
D[10905] = {"Maître des potions",{"Parlez à Lauranna Thar'well au Refuge cénarien dans le Marécage de Zangar.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en alchimie."}}
D[10906] = {"Maître des élixirs",{"Parlez à Lorokeem dans la Ville basse de Shattrath.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en alchimie."}}
D[10907] = {"Maître de la transmutation",{"Parlez à Zarevhi à la Foudreflèche au Raz-de-Néant.","","*ATTENTION !* Vous ne pouvez choisir qu'une spécialisation en alchimie."}}
D[10908] = {"Parler à Rilak le Racheté",{"Kirrik l'Éveillé veut que vous parliez à Rilak le Racheté dans la Ville basse de Shattrath."}}
D[10909] = {"Les esprits gangrenés",{"Klatu au Bastion de l'Honneur vous a demandé d'utiliser la Relique d'anachorète à l'Avant-poste de Gor'gaz, au sud-ouest du Bastion. Vous devrez ensuite tuer des Orcs de la Main brisée près de la relique, puis détruire les Esprits gangrenés libérés pour venger le Colonel Jules."}}
D[10910] = {"La Porte de la mort",{"Utilisez le Signal druidique à la Porte de la mort pour appeler et parler à un Druide du Bosquet éternel."}}
D[10911] = {"Feu à volonté !",{"Utilisez les Munitions naturalisées pour prendre le contrôle des Gangrecanons de la Porte de la mort. Utilisez-les pour détruire le Portail dimensionnel sud et le Portail dimensionnel nord."}}
D[10912] = {"Le maître-chien",{"Tuez Baelmon le Maître-chien."}}
D[10913] = {"Des funérailles inadéquates",{"Le commandant Ra'vaj de l'Avant-poste shat'ari du désert des Ossements, dans la forêt de Terokkar, veut que vous brûliez 8 Guerriers auchenaï tués et 8 Redresseurs de torts sha'tar tués."}}
D[10914] = {"Il nous faut un héros",{"Le commandant Ra'vaj de l'Avant-poste shat'ari du désert des Ossements, dans la forêt de Terokkar, veut que vous tuiez 12 Initiés auchenaï et 5 Auspices-funestes auchenaï."}}
D[10915] = {"L'exarque déchu",{"Le commandant Ra'vaj de l'Avant-poste shat'ari du désert des Ossements, dans la forêt de Terokkar, veut que vous détruisiez le contenu du Cercueil auchenaï."}}
D[10916] = {"À la recherche de chapelets",{"Retrouvez le Chapelet draeneï et rapportez-le à l'Assistant Klatu dans le Bastion de l'Honneur."}}
D[10917] = {"La souffrance du paria",{"Apportez 30 Plumes d'arakkoa à Vekax dans la Ville basse de Shattrath."}}
D[10918] = {"Plus de plumes"}
D[10919] = {"Les friandises de Fei Fei"}
D[10920] = {"Au nom des disparus",{"Le redresseur de torts Haylen veut que vous tuiez 20 Veuves croc-d'effroi, puis que vous reveniez le voir juste à l'ouest de la Crête de Toile-néant."}}
D[10921] = {"Terokkarantula",{"Le redresseur de torts Haylen veut que vous alliez tuer Terokkarantula et que vous reveniez le voir à l'ouest de la crête de Toile-néant."}}
D[10922] = {"En fouillant dans les os",{"Escortez Leglas et son équipe et protégez-les pendant les fouilles. Si vous réussissez, retournez voir Nanowitz à l'Avant-poste sha'tari."}}
D[10923] = {"L'approche du mal",{"Chênuin veut que vous emportiez la Relique de l'effroi au Monticule grouillant. Là-bas, tuez des nécrorateurs et des auspices-funestes auchenaï pour collecter 20 Crânes du destin. Trouvez ensuite le Cercle d'invocation du Monticule grouillant et utilisez la Relique de l'effroi pour invoquer et détruire Teribus le Maudit. Revenez voir Chênuin quand ce sera fait."}}
D[10924] = {"La part du diabl-otin !",{"Sab'aoth de la Cosmovrille veut 8 fioles de Sang de poursuivant dimensionnel."}}
D[10925] = {"L'approche du mal"}
D[10926] = {"Retour au camp de base sha'tari",{"Le redresseur de torts Haylen veut que vous retourniez au Camp de base sha'tari, dans le Désert des Ossements et que vous y parliez à l'Éclaireur Navrin."}}
D[10927] = {"Tuer les rampantes",{"Tuez 6 Rampantes des cavernes."}}
D[10928] = {"Tuer les rampantes",{"Tuez 6 Rampantes des cavernes."}}
D[10929] = {"Martelheurt",{"Nanowitz, de l'Avant-poste sha'tari du désert des Ossements, veut que vous lui rameniez 8 Carcasses de cribleurs des ossements adultes."}}
D[10930] = {"Le gros ver des ossements",{"Nanowitz, de l'Avant-poste sha'tari du désert des Ossements, veut que vous trouviez des Organes d'énorme ver des ossements.","","Il veut aussi qu'on lui rapporte son Martelheurt."}}
D[10931] = {"Retour à l'Exodar",{"Parlez à Caedmos à l'Exodar."}}
D[10932] = {"Retour à l'Exodar",{"Parlez à Caedmos à l'Exodar."}}
D[10933] = {"Retour à Lune-d'Argent",{"Parlez à Aldrae à Lune-d'argent."}}
D[10934] = {"Retour à Lune-d'Argent",{"Parlez à Aldrae à Lune-d'argent."}}
D[10935] = {"L'exorcisme du colonel Jules",{"Parlez à l'Anachorète Barada. Utilisez le chapelet pour l'aider pendant le rituel, puis parlez au Colonel Jules quand il sera sauvé. Pour finir, retournez voir l'Assistant Klatu."}}
D[10936] = {"Trollemort vous cherche !",{"L'Assistant Klatu vous a indiqué que le Commandant de corps Danath Trollemort vous cherchait. Allez lui parler à la caserne du Bastion de l'Honneur dans la Péninsule des Flammes infernales."}}
D[10937] = {"Détruisez le maître de manœuvre",{"Le Commandant de corps Danath Trollemort vous a ordonné de tuer au plus vite le Maître de manœuvre Zurok. Retournez voir le commandant de corps au Bastion de l'Honneur dans la Péninsule des Flammes infernales une fois que le maître de manœuvre sera mort."}}
D[10938] = {"Suite de Bénédictions de Sombrelune",{"Rapporter la suite de Bénédictions à la foire de Sombrelune quand elle reviendra en ville."}}
D[10939] = {"Suite de Tempêtes de Sombrelune",{"Rapporter la suite de Tempêtes à la foire de Sombrelune quand elle reviendra en ville."}}
D[10940] = {"Suite de Furies de Sombrelune",{"Rapporter la suite de Furies à la foire de Sombrelune quand elle reviendra en ville."}}
D[10941] = {"Suite de Déraison de Sombrelune",{"Rapporter la suite de Déraison à la foire de Sombrelune quand elle reviendra en ville."}}
D[10942] = {"La Semaine des enfants",{"Utiliser le Sifflet d'orphelin elfe de sang pour parler à l'enfant que vous surveillerez durant la Semaine des enfants."}}
D[10943] = {"La Semaine des enfants",{"Utiliser le Sifflet d'orphelin draeneï pour parler à l'enfant que vous surveillerez durant la Semaine des enfants."}}
D[10944] = {"Un secret compromis",{"Allez à la Cage de la gardienne dans la vallée d'Ombrelune et parlez avec Akama."}}
D[10945] = {"Hch'uu et le peuple champignon",{"Emmenez votre orpheline, Salandria, à Sporeggar dans le marécage de Zangar. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez. Puis aller parler à Hch'uu."}}
D[10946] = {"La ruse des Cendrelangues",{"Pénétrez dans le Donjon de la Tempête et tuez Al'ar en portant la Capuche de Cendrelangue. Retournez voir Akama dans la vallée d'Ombrelune une fois que ce sera fait."}}
D[10947] = {"Un artéfact du passé",{"Allez aux Grottes du temps en Tanaris, et rendez-vous à la Bataille du mont Hyjal. Quand vous y serez, triomphez de Rage Froidhiver et rapportez le Phylactère chronophasé à Akama dans la vallée d'Ombrelune."}}
D[10948] = {"L'âme otage",{"Rendez-vous à Shattrath pour soumettre la requête d'Akama à A'dal."}}
D[10949] = {"L'entrée dans le Temple noir",{"Rendez-vous à l'entrée du Temple noir dans la vallée d'Ombrelune et allez parler à Xi'ri."}}
D[10950] = {"Auchindoun et le Cercle d'observance",{"Emmenez votre orpheline, Dornaa, à la Pierre de rencontre du Cercle d'observance, au centre d'Auchindoun. Auchindoun est situé au centre du désert des Ossements de la forêt de Terokkar. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez."}}
D[10951] = {"Une visite à la Porte des ténèbres",{"Emmenez votre orpheline, Salandria, en haut de l'escalier du Destin, pour qu'elle puisse passer devant la Porte des ténèbres dans la péninsule des Flammes infernales. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez."}}
D[10952] = {"Une visite à la Porte des ténèbres",{"Emmenez votre orpheline, Dornaa, en haut de l'escalier du Destin pour qu'elle passe devant la Porte des ténèbres dans la péninsule des Flammes infernales. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez."}}
D[10953] = {"Une visite au Trône des éléments",{"Emmenez votre orpheline, Salandria, au Trône des éléments à Nagrand. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez. Ensuite, allez parler à l'Élémentaliste Sharvak."}}
D[10954] = {"Jheel est au point d'ancrage Aeris !",{"Emmenez votre orpheline, Dornaa, au Point d'ancrage Aeris en Nagrand. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez. Ensuite, parlez avec Jheel."}}
D[10955] = {"Morthis Murmedaile",{"Allez parler à Morthis Murmedaile au Refuge cénarien dans le marécage de Zangar."}}
D[10956] = {"Le Siège du naaru",{"Emmenez votre orpheline, Dornaa, voir O'ros au pied du Siège du naaru dans l'Exodar, sur l'île de Brume-azur. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez.","","Rappelez-vous que vous pouvez utiliser votre carte à l'intérieur de la ville."}}
D[10957] = {"La rédemption du Cendrelangue",{"Aidez Akama à reprendre le contrôle de son âme en vainquant l'Ombre d'Akama dans le Temple noir. Retournez voir le Voyant Kanai quand ce sera fait."}}
D[10958] = {"À la recherche des Cendrelangues",{"Trouvez les Ligemorts d'Akama à l'intérieur du Temple noir."}}
D[10959] = {"La chute du Traître",{"Le voyant Kanai veut que vous vainquiez Illidan à l'intérieur du Temple noir."}}
D[10960] = {"Quand je serai grande…"}
D[10961] = {"La protection de l'éveil",{"Apportez 10 Fleurs des tourbières, 10 Lichens anciens et 10 Glauriers à Morthis Murmedaile, au Refuge cénarien."}}
D[10962] = {"Il est temps de visiter les Grottes",{"Emmenez votre orpheline, Dornaa, devant Zaladormu, le dragon qui se trouve sur l'estrade au milieu des Grottes du temps. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez.","","Ensuite, achetez-lui une Figurine de dragon auprès de l'Intendant des Gardiens du temps, Alurmi, près du fond du tunnel d'entrée."}}
D[10963] = {"Il est temps de visiter les Grottes",{"Emmenez votre orpheline, Salandria, devant Zaladormu, le dragon qui se trouve sur l'estrade au milieu des Grottes du temps. N'oubliez pas de l'appeler si elle n'est pas présente lorsque vous arrivez.","","Ensuite, achetez-lui une Figurine de dragon auprès de l'Intendant des Gardiens du temps, Alurmi, près du fond du tunnel d'entrée."}}
D[10964] = {"Le réveil du dormeur",{"Utilisez le Gardien de l'éveil pour aider Clintar Marcherêve à sortir du Rêve d'émeraude. Une fois qu'il a repris connaissance, parlez-lui."}}
D[10965] = {"Plus qu'un simple rêve",{"Protégez l'Esprit de Clintar Marcherêve pendant qu'il recueille les reliques d'Aviana, puis allez trouver la Garderêve Lurosa."}}
D[10966] = {"Retour à l'orphelinat",{"Ramenez votre protégée à l'orphelinat de Shattrath, en rendant le Sifflet d'orphelin draeneï à Miss Hérikorde, directrice de l'orphelinat, dans la Ville basse."}}
D[10967] = {"Retour à l'orphelinat"}
D[10968] = {"En visite chez le long-voyant"}
D[10969] = {"Rechercher Ameer",{"Trouvez le Commandant Ameer au Poste de garde du Protectorat."}}
D[10970] = {"Une mission miséricordieuse",{"Procurez-vous la Clé de la prison de l'Ethereum récupérée pour le Commandant Ameer au Poste de garde du Protectorat."}}
D[10971] = {"Secrets de l'Ethereum",{"Le Commandant Ameer, au Poste de garde du Protectorat au Raz-de-Néant, veut que vous lui apportiez une Plaque d'identité de prisonnier de l'Ethereum."}}
D[10972] = {"Répertorier les prisonniers de l'Ethereum"}
D[10973] = {"Un millier de mondes",{"Le Commandant Ameer, au Poste de garde du Protectorat au Raz-de-Néant, veut que vous lui apportiez 5 Clés de la prison de l'Ethereum."}}
D[10974] = {"Les chambres de stase de Bash'ir",{"Utilisez la Tablette-clé de l'Ethereum - Alpha pour ouvrir la Chambre de stase alpha au Point d'ancrage de Bash'ir dans les Tranchantes.","","Rapportez les Indices de l'alpha à l'Image du commandant Ameer au Point d'ancrage de Bash'ir."}}
D[10975] = {"La purge des chambres de Bash'ir"}
D[10976] = {"La Marque du roi-nexus",{"L'Image du commandant Ameer au Point d'ancrage de Bash'ir dans les Tranchantes vous demande de lui rapporter une Marque du roi-nexus."}}
D[10977] = {"Les chambres de stase des Tombes-mana",{"L'Image du commandant Ameer au Point d'ancrage de Bash'ir dans les Tranchantes vous demande d'utiliser la Clé de la chambre de stase des Tombes-mana dans les Tombes-mana d'Auchindoun.","","Cette quête ne peut être accomplie qu'au niveau de difficulté Héroïque."}}
D[10978] = {"Retourner voir Morthis Murmedaile",{"Apportez les Reliques d'Aviana à Morthis Murmedaile au Refuge cénarien dans le marécage de Zangar."}}
D[10979] = {"En route pour le Bosquet éternel",{"Allez parler à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes."}}
D[10980] = {"Le Livre du Corbeau",{"Utilisez un Œil de raie de l'éther avec votre Pierre de prophète pour voir les fantômes du culte du corbeau. Cherchez l'esprit de Sai'kkal l'Ancien dans la Cime du vortex et interrogez-le au sujet du livre du corbeau, puis retournez auprès d'Arthorn Chant-du-vent."}}
D[10981] = {"La chambre personnelle du prince-nexus Shaffar"}
D[10982] = {"L'œil d'Haramad"}
D[10983] = {"Mog'dorg le Ratatiné",{"Allez voir Mog'dorg le Ratatiné au sommet de l'une des tours qui se trouvent devant le Cercle de sang dans les Tranchantes."}}
D[10984] = {"Parler avec l'ogre",{"Allez voir l'Ogre, Grok, dans le quartier de la Ville basse de Shattrath."}}
D[10985] = {"Une distraction pour Akama",{"Assurez-vous qu'Akama et Maiev pénètrent bien dans le Temple noir de la Vallée d'Ombrelune une fois que les forces de Xi'ri auront fait diversion."}}
D[10986] = {"Des yeux dans le ciel",{"Allez parler à la Gardienne Elaira sur la Crête du Crépuscule à Nagrand."}}
D[10987] = {"La chasse à la crécerelle",{"Utilisez le Filet à crécerelles pour capturer une Crécerelle sauvage, et ramenez-la à la Gardienne Elaira sur la Crête du Crépuscule."}}
D[10988] = {"Les pierres du Corbeau",{"Rassemblez 8 Pierres du Corbeau à Skettis et apportez-les à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes."}}
D[10989] = {"Mog'dorg le Ratatiné",{"Parlez à Mog'dorg le Ratatiné au sommet de la tour devant laquelle se tient Chort, juste devant le Cercle de sang, dans les Tranchantes."}}
D[10990] = {"L'essence de l'aigle",{"Terrassez le Gardien de l'Aigle et emparez-vous de l'Essence de l'Aigle. Utilisez le Sifflet à crécerelle d'Arthorn pour appeler la Crécerelle d'Arthorn afin de transmettre la nouvelle de votre succès.","","Si vous perdez le Sifflet à crécerelle d'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer."}}
D[10991] = {"L'essence de l'épervier",{"Terrassez le Gardien de l'Épervier et emparez-vous de l'Essence de l'Épervier. Utilisez le Sifflet à crécerelle d'Arthorn pour appeler la Crécerelle d'Arthorn afin de transmettre la nouvelle de votre succès.","","Si vous perdez le Sifflet à crécerelle d'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer."}}
D[10992] = {"L'essence du faucon",{"Terrassez le Gardien du Faucon et apportez l'Essence du faucon à Arthorn Chant-du-vent au Bosquet éternel."}}
D[10993] = {"Le retour au Refuge cénarien",{"Apportez le Colis d'Arthorn à Morthis Murmedaile au Refuge cénarien."}}
D[10994] = {"La chasse à la pierre de lune",{"Apportez une Pierre de lune de Furie-du-Sud à Morthis Murmedaile au Refuge cénarien."}}
D[10995] = {"Grulloc a deux crânes",{"Emparez-vous du Crâne de dragon de Grulloc."}}
D[10996] = {"Le coffre au trésor de Maggoc",{"Emparez-vous du Coffre au trésor de Maggoc."}}
D[10997] = {"L'étendard et la manière",{"Emparez-vous de l'Étendard de Skori."}}
D[10998] = {"Le tome de sa voix",{"Emparez-vous du Grimoire infâme de Vim'gol."}}
D[11000] = {"Face au Broyeur-d'âme",{"Récupérez l’Âme de Crânoc."}}
D[11001] = {"Triompher du dieu corbeau",{"Tuez le Dieu corbeau et retournez voir Morthis Murmedaile au Refuge cénarien.","","Cette quête doit être accomplie en mode de difficulté du donjon Héroïque."}}
D[11002] = {"La chute de Magtheridon",{"Rapportez la Tête de Magtheridon au Commandant de corps Danath Trollemort au bastion de l'Honneur dans la péninsule des Flammes infernales."}}
D[11003] = {"La chute de Magtheridon",{"Rapportez la Tête de Magtheridon à Nazgrel à Thrallmar dans la péninsule des Flammes infernales."}}
D[11004] = {"Un monde d'ombres",{"Séverin souhaite que vous vous aventuriez dans Skettis et que vous récupériez 6 Poussières ombreuses sur les arakkoa qui s'y trouvent."}}
D[11005] = {"Les secrets des prêtres de la Serre",{"Procurez-vous un Élixir des ombres auprès de Séverin et utilisez-le pour trouver et tuer le Prêtre de la serre Ishaal, le Prêtre de la serre Skizzik et le Prêtre de la serre Zellek à Skettis. Retournez voir le commandant Adaris lorsque vous aurez accompli cette tâche."}}
D[11006] = {"Plus de poussière ombreuse"}
D[11007] = {"Kael'thas et la sphère verdoyante",{"Apportez la Sphère verdoyante à A'dal dans Shattrath."}}
D[11008] = {"Un déluge de feu sur Skettis",{"Cherchez les Œufs de kaliri monstrueux au sommet des habitations de Skettis, et utilisez les Détonateurs de la Garde-ciel pour les détruire. Revenez voir ensuite le Sergent Doryn de la Garde-ciel."}}
D[11009] = {"Le paradis des ogres",{"Parlez à Chu'a'lor, à Ogri'la, dans les Tranchantes."}}
D[11010] = {"Mission de bombardement",{"Utilisez les Bombes de la Garde-ciel pour détruire 15 Piles de boulets de gangrecanon."}}
D[11011] = {"Une vigilance éternelle",{"Parlez à Morthis Murmedaile pour recevoir une Pierre de lune imprégnée d'essence."}}
D[11012] = {"Serment de sang de l'Aile-du-Néant"}
D[11013] = {"Au service des Illidari",{"Rendez-vous à l'Escarpement de l'Aile-du-Néant et remettez la Lettre de service illidari au Suzerain Mor'ghor au Campement des Gueules-de-dragon."}}
D[11014] = {"Le sous-chef entre en scène",{"Allez parler au Sous-chef Varkule Souffle-de-dragon au Campement des Gueules-de-dragon."}}
D[11015] = {"Les cristaux de l'Aile-du-Néant",{"Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui rapportiez 30 Cristaux de l'Aile-du-Néant."}}
D[11016] = {"Des peaux d'écorcheurs mine-néant",{"Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui rapportiez 35 Peaux d'écorcheurs mine-néant."}}
D[11017] = {"Du pollen de pruinéante",{"Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui rapportiez 40 échantillons de Pollen de pruinéante."}}
D[11018] = {"Du minerai de néanticite",{"Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui rapportiez 40 échantillons de Minerai de néanticite."}}
D[11019] = {"Un ami à l'intérieur"}
D[11020] = {"Une mort lente",{"Yarzill le Mercenaire du Campement des Gueules-de-dragon de la Vallée d'Ombrelune veut que vous utilisiez la Viande de mouton de Yarzill associée à des Gangreglandes pour empoisonner 12 Campements de péons Gueules-de-dragon."}}
D[11021] = {"L'almanach d'Ishaal",{"Apportez l'Almanach d'Ishaal au Commandant de la Garde-ciel Adaris, au nord de Skettis."}}
D[11022] = {"Parler à Mog'dorg",{"Allez parler à Mog'dorg le Ratatiné. Il se trouve au sommet de la tour située du côté est du Cercle de sang dans les Tranchantes."}}
D[11023] = {"Bombardez-les encore !",{"Utilisez les Bombes de la Garde-ciel pour détruire 15 Piles de boulets de gangrecanon."}}
D[11024] = {"Un allié dans la Ville basse",{"Apportez l'Almanach d'Ishaal à Rilak le Racheté dans la Ville basse, à Shattrath."}}
D[11025] = {"Les cristaux",{"Collectez 5 Éclats apogides."}}
D[11026] = {"Bannissez les démons",{"Utilisez le Cristal de bannissement pour bannir 15 démons au camp de forge : Courroux ou au camp de forge : Terreur."}}
D[11027] = {"Z'avez la sombrerune?"}
D[11028] = {"Compte à rebours avant anéantissement",{"Retournez voir le Commandant Adaris de la Garde-ciel au Raie'odrome de Noirvent, dans la Forêt de Terokkar, avec les nouvelles concernant le retour de Terokk."}}
D[11029] = {"Un déguisement miteux",{"Utilisez le Déguisement arakkoa miteux pour obtenir les Lignées antagonistes de Sahaak, puis retournez auprès de Hazzik."}}
D[11030] = {"Notre fils veut devenir patrouilleur de la Garde-ciel",{"Procurez-vous un Flacon instable de la bête."}}
D[11031] = {"Quitter la voie de l'archimage"}
D[11032] = {"Quitter la voie du protecteur"}
D[11033] = {"Quitter la voie de l'assassin"}
D[11034] = {"Quitter la voie du guérisseur"}
D[11035] = {"Les cieux pas si cléments...",{"Yarzill le Mercenaire du Campement des Gueules-de-dragon de la Vallée d'Ombrelune veut que vous récupériez 10 Reliques de l'Aile-du-Néant."}}
D[11036] = {"Marchandise extraordinaire !",{"Apportez les Fruits en conserve au Chef-de-fusée Karlingue dans la Zone 52, à Raz-de-Néant."}}
D[11037] = {"Une vision étrange",{"Parlez au Chef-de-fusée Karlingue dans la Zone 52."}}
D[11038] = {"Aider l'exarque Orelis",{"Parlez à l'Exarque Orelis dans la Zone 52."}}
D[11039] = {"Se présenter au maître-espion Thalodien",{"Présentez-vous au Maître-espion Thalodien dans la Zone 52."}}
D[11040] = {"Des pièces détachées pour le chef-de-fusée",{"Apportez les Pièces détachées de Bossi au Chef-de-fusée Karlingue dans la Zone 52, à Raz-de-Néant."}}
D[11041] = {"Un travail à terminer...",{"Tuez 10 Écorcheurs Supremine et Barash la Mère de la tanière. Revenez voir le Suzerain Mor'ghor au Campement des Gueules-de-dragon si vous réussissez."}}
D[11042] = {"Une vision mystique",{"Parlez au Chef-de-fusée Karlingue dans la Zone 52."}}
D[11043] = {"Le griffon de l'avenir",{"Parlez à Brunn Flammebarbe au Bastion des Marteaux-hardis, dans la Vallée d'Ombrelune."}}
D[11044] = {"Visions d'anéantissement",{"Parlez au Chef d'escadrille Nuainn au Bastion des Marteaux-hardis."}}
D[11045] = {"Zorus le Judicateur",{"Parlez à Zorus le judicateur au Bastion des Marteaux-hardis."}}
D[11046] = {"L'apothicaire en chef Hildagard",{"Parlez à l'Apothicaire en chef Hildagard au village d'Ombrelune."}}
D[11047] = {"La requête de l'apprenti",{"Parlez à Dama Crin-sauvage au village d'Ombrelune, dans la Vallée d'Ombrelune."}}
D[11048] = {"Le rapport de Kroghan",{"Parlez au Garde de sang Gulmok au village d'Ombrelune."}}
D[11049] = {"La ruée vers les œufs de l'Aile-du-Néant",{"Yarzill le Mercenaire, du campement des Gueules-de-dragon dans la vallée d'Ombrelune, veut que vous vous procuriez un Œuf de l'Aile-du-Néant."}}
D[11050] = {"Tous les œufs sont bons à prendre"}
D[11051] = {"Bannissez plus de démons",{"Utilisez le Cristal de bannissement pour bannir 15 démons au Camp de forge : Courroux ou au Camp de forge : Terreur."}}
D[11052] = {"La promesse d'Akama",{"Apportez le Médaillon de Karabor à A'dal, à Shattrath."}}
D[11053] = {"Debout, surveillant !",{"Parlez au Suzerain Mor'ghor au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11054] = {"Être surveillant : savoir faire les bons choix",{"Le Surveillant-chef Tadboue du campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui apportiez 10 morceaux de Cuir granuleux et 1 Peau de Tyrantus durcie."}}
D[11055] = {"Le botterang : un traitement pour les péons bons à rien",{"Le Surveillant-chef Tadboue du campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous punissiez 20 Péons Gueules-de-dragon paresseux. Vous devrez aussi rapporter votre Botterang."}}
D[11056] = {"Le marché d'Hazzik",{"Récupérez le Paquet d'Hazzik dans sa demeure, à l'est de Skettis, et remettez-le lui."}}
D[11057] = {"Des ennuis en contrebas",{"Parlez à Mog'dorg le Ratatiné, en haut d'une des tours juste à l'extérieur du Cercle de sang dans les Tranchantes."}}
D[11058] = {"Une relique apogide",{"Obtenir des Vibrations apogides d’une Relique apogide."}}
D[11059] = {"Le gardien du monument",{"Procurez-vous la tête d’un Gardien apogide."}}
D[11060] = {"Une sombrerune cristalforgée"}
D[11061] = {"Le devoir d'un père",{"Procurez-vous un Flacon instable du sorcier pour lui."}}
D[11062] = {"L'avant-poste de la Garde-ciel",{"Parlez au Commandant Keller de la Garde-ciel à l'Avant-poste de la Garde-ciel, dans les Tranchantes."}}
D[11063] = {"Mériter ses ailes..."}
D[11064] = {"Course Gueule-de-dragon : la ballade de Vieillot McVieux",{"Suivez Murg \"Vieillot\" Bourbegueule en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11065] = {"Allez dompter quelques raies de l'éther !",{"Utilisez le Lasso pour capturer 5 Raies de l’éther."}}
D[11066] = {"Allez dompter d'autres raies de l'éther !",{"Utilisez le Lasso pour capturer 5 Raies de l’éther."}}
D[11067] = {"Course Gueule-de-dragon : Trope le Rote-crasse",{"Suivez Trope le Rote-crasse en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11068] = {"Course Gueule-de-dragon : Corlok le Briscard",{"Suivez Corlok le Briscard en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11069] = {"Course Gueule-de-dragon : Chef d'escadrille Ichman",{"Suivez le Chef d'escadrille Ichman en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11070] = {"Course Gueule-de-dragon : Chef d'escadrille Mulverick",{"Suivez le Chef d'escadrille Mulverick en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11071] = {"Course Gueule-de-dragon : Capitaine Fracasse-ciel",{"Suivez le Capitaine Fracasse-ciel en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11072] = {"Lignées antagonistes",{"Trouvez les Piles de crânes au milieu des cercles d'invocation de Skettis. Invoquez et vainquez chacun des descendants des adversaires de Terokk en utilisant 10 Parchemins perdus dans le temps à la Pile de crâne. Retournez auprès de Hazzik au Raie'odrome de Noirvent avec un gage de chacun d'eux."}}
D[11073] = {"La chute de Terokk",{"Emportez l'Offrande perdue dans le temps préparée par Hazzik à la Pile de crânes qui se trouve au milieu de Skettis, puis invoquez et terrassez Terokk. Retournez voir le Commandant Adaris de la Garde-ciel quand vous aurez accompli votre mission."}}
D[11074] = {"Les attributs des descendants",{"Rassemblez des Parchemins perdus dans le temps détenus par les arakkoa de Skettis, et emportez-les jusqu'à une Pile de crânes au milieu d'un cercle d'invocation de Skettis. Invoquez et vainquez les descendants des adversaires de Terokk et rapportez les Serres d'Akkarai, l'Échine de Garrok, l'Écaille de Vekkaz et les Griffes de Gezzarak à Hakkiz."}}
D[11075] = {"Les mines de l'Aile-du-Néant",{"Allez voir la Maîtresse des mines sur l'Escarpement de l'Aile-du-Néant."}}
D[11076] = {"Ramasser les morceaux...",{"La Maîtresse des mines, des Mines de l'escarpement de l'Aile-du-Néant de la vallée d'Ombrelune, veut que vous récupériez 15 caisses de Cargaison de Mine-néant."}}
D[11077] = {"Les dragons sont les derniers de nos soucis",{"Le Contremaître Gueule-de-dragon des Mines de l'Aile-du-Néant de la vallée d'Ombrelune veut que vous tuiez 15 Ecorcheurs mine-néant et 5 Ravageurs mine-néant."}}
D[11078] = {"Pour régner sur les cieux",{"Récupérez des Dents de dragon."}}
D[11079] = {"Un gangrefouet pour Gahk",{"Procurez-vous un Gangrefouet."}}
D[11080] = {"Les émanations des reliques",{"Obtenir des Emanations apogides d’une Relique apogide."}}
D[11081] = {"La grande révolte des Bourbesang",{"Apportez les Plans d'évasion bourbesang à la Maîtresse des mines."}}
D[11082] = {"À la recherche de la vérité",{"Trouvez un Surveillant bourbesang et interrogez-le. Retournez voir la Maîtresse des mines avec les Informations des Bourbesang et la Main du surveillant."}}
D[11083] = {"Affolés et perturbés",{"Ronag l'Esclavagiste, des Mines de l'Aile-du-Néant dans la vallée d'Ombrelune, vous demande de tuer le Contremaître bourbesang affolé et 5 Mineurs bourbesang affolés."}}
D[11084] = {"Haut les cœurs, capitaine !",{"Parlez au Suzerain Mor'ghor au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11085] = {"L'évasion de Skettis",{"Escorter le Prisonnier de la Garde-ciel à l'abri, puis se présenter au Sergent Doryn de la Garde-ciel."}}
D[11086] = {"Perturber la Porte du crépuscule",{"Le Suzerain Mor'ghor du campement des Gueules-de-dragon dans la vallée d'Ombrelune vous demande de tuer 20 Agents ombremort."}}
D[11089] = {"Le canon à âmes de Reth'hedron",{"Le Seigneur illidari Balthas du campement des Gueules-de-dragon dans la vallée d'Ombrelune veut que vous lui apportiez 2 Barres de gangracier, 1 Structure en adamantite, 1 Batterie en khorium et 1 Essence des arcanes sans défaut."}}
D[11090] = {"Dominer le Dominateur",{"Le Seigneur illidari Balthas du campement des Gueules-de-dragon dans la vallée d'Ombrelune vous a chargé d'utiliser le Canon à âmes sur Reth'hedron le Dominateur en Nagrand.","","Vous devrez aussi rapporter le Canon à âmes."}}
D[11091] = {"Remerciement spécial",{"Parlez à Jho'nass, à Ogri'la, dans les Tranchantes."}}
D[11092] = {"Salut, commandant !",{"Parlez au Suzerain Mor'ghor au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11093] = {"Raies du Néant affamées",{"Utilisez la Cage de raie du Néant dans les bois qui se trouvent au sud du Raie'odrome de Noirvent et tuez des Poursuivants dimensionnels près de la Raie du Néant affamée. Retournez voir le Dresseur Deesak de la Garde-ciel quand vous aurez terminé."}}
D[11094] = {"Tuez-les tous !",{"Avertissez l'Arcaniste Thelis du contenu de votre mission et apportez-lui le Lance-fusée gueule-de-dragon au Sanctum des Étoiles dans la vallée d'Ombrelune."}}
D[11095] = {"Le commandant Hobb",{"Donnez le Lance-fusée gueule-de-dragon au Commandant Hobb au Sanctum des Étoiles dans la vallée d'Ombrelune."}}
D[11096] = {"La menace vient d'en haut",{"Tuez 20 Ogres Gordunni de n'importe quelle variété dans la Barrière, puis retournez voir Yuula à Shattrath."}}
D[11097] = {"Le plus mortel des pièges",{"Aidez le Commandant Hobb et les Clairvoyants à défendre le Sanctum des Étoiles. Une fois que l'ensemble des forces Gueule-de-dragon aura été vaincu, retournez voir le suzerain Mor'ghor au Campement des Gueules-de-dragon avec les Médailles de Clairvoyant."}}
D[11098] = {"En route pour Skettis !",{"Apportez le Paquet d'explosifs au Sergent Doryn de la Garde-ciel au Raie'odrome de Noirvent à l'extérieur de Skettis."}}
D[11099] = {"Tuez-les tous !",{"Avertissez l'Anachorète Ceyla du contenu de votre mission et apportez-lui le Lance-fusée gueule-de-dragon à l'Autel de Sha'tar."}}
D[11100] = {"Le commandant Arcus",{"Donnez le Lance-fusée gueule-de-dragon au Commandant Arcus à l'Autel de Sha'tar dans la vallée d'Ombrelune."}}
D[11101] = {"Le plus mortel des pièges",{"Aidez le Commandant Arcus et l'Aldor à défendre l'Autel de Sha'tar. Une fois que l'ensemble des forces Gueule-de-dragon aura été vaincu, retournez voir le suzerain Mor'ghor au Campement des Gueules-de-dragon avec les Médailles de l'Aldor."}}
D[11102] = {"Mission de bombardement",{"Utilisez les Bombes de la Garde-ciel pour détruire 15 Piles de boulets de gangrecanon."}}
D[11103] = {"Quitter la voie du sage"}
D[11104] = {"Quitter la voie du guérisseur"}
D[11105] = {"Quitter la voie du champion"}
D[11106] = {"Quitter la voie du défenseur"}
D[11107] = {"À genoux devant le généralissime !",{"Parlez au Suzerain Mor'ghor au Campement des Gueules-de-dragon dans la vallée d'Ombrelune."}}
D[11108] = {"Le seigneur Illidan Hurlorage",{"Rencontrez Illidan Hurlorage. Si jamais vous survivez, allez trouver Barthamus dans la Ville basse de Shattrath."}}
D[11109] = {"Jorus le drake de l'Aile-du-Néant cobalt"}
D[11110] = {"Malfas le drake de l'Aile-du-Néant violet"}
D[11111] = {"Onyxian le drake de l'Aile-du-Néant onyx"}
D[11112] = {"Suraku le drake de l'Aile-du-Néant azur"}
D[11113] = {"Voranaku le drake de l'Aile-du-Néant pourpre"}
D[11114] = {"Zoya le drake de l'Aile-du-Néant viride"}
D[11116] = {"L'épreuve des naaru: (DRAPEAU DE QUÊTE)"}
D[11117] = {"Attraper le Wolpertinger sauvage !",{"Archedor Chassebécasse vous a demandé de capturer 5 Wolpertingers sonnés avec le Filet à wolpertinger. Il a indiqué qu'il fallait être soûl ou porter des Lunettes Synthébière pour les voir."}}
D[11118] = {"Le défilé des elekk roses",{"Rendez-vous aux guinguettes à l'extérieur de Hurlevent, Darnassus et l'Exodar. Supprimez trois elekk dans chacune d'elles, puis revenez voir Archedor Chassebécasse. Vous devez vous soûler ou bien porter des Lunettes Synthébière pour voir les Elekk roses."}}
D[11119] = {"Haro sur le point d'ancrage de Bash'ir",{"Parlez au Techno-éther apprenti à l’Avant-poste de la Garde-ciel, dans les Tranchantes."}}
D[11120] = {"Le défilé des elekk roses",{"Rendez-vous aux guinguettes à l'extérieur de Lune-d'argent, des Pitons du Tonnerre et de Fossoyeuse. Supprimez trois elekk dans chacune d'elles, puis revenez voir Charedor Cassebéchasse. Vous devez vous soûler ou porter des Lunettes Synthébière pour voir les Elekk roses."}}
D[11122] = {"Histoire d'un aller et retour",{"Allez chercher un tonneau auprès de Flynn Brassefeu à Kharanos et rapportez-le à Pol Distillambre. Rapportez trois tonneaux avant que votre bélier ne s'en aille."}}
D[11123] = {"Inspection des ruines",{"Parlez à l'Inspecteur Tarem à l'Auberge du Repos ombragé."}}
D[11124] = {"Inspection des ruines",{"Parlez à l'Inspecteur Tarem à l'Auberge du Repos ombragé."}}
D[11126] = {"Des traîtres parmi nous",{"Démasquez 5 Agitateurs des déserteurs puis retournez voir Calia Hastings près des quais de Theramore."}}
D[11128] = {"Guerre de propagande",{"Remettez la Propagande des déserteurs à Calia Hastings près des quais de Theramore."}}
D[11129] = {"Kyle a disparu !",{"Ahab Sabot-de-blé, à Sabot-de-sang en Mulgore, veut que vous nourrissiez son précieux chiot, Kyle le Frénétique.","","Donnez de la Viande de trotteur tendre à Kyle puis retournez voir Ahab Sabot-de-blé."}}
D[11130] = {"Houuuu, ça brille !",{"Eskrokar veut que vous remettiez la Note d'Eskrokar à Budd, dans les Terres fantômes, à l'extérieur de Zul'Aman."}}
D[11131] = {"Éteignez les incendies !",{"La Directrice d'orphelinat costumée vous demande d'aider à éteindre tous les foyers d'incendie du village. Une fois qu'ils seront éteints, retournez lui parler."}}
D[11132] = {"Des promesses, toujours des promesses...",{"Budd Truducou, dans les collines de la Cognée, veut que vous récupériez sa carte. Elle se trouve sur la terrasse du Grand prêtre Nalorakk à Zul'Aman."}}
D[11133] = {"Discréditer les déserteurs",{"Calia Hastings veut que vous distribuiez les Pamphlets trafiqués à 6 Gardes de Theramore. Ensuite, retournez la voir près des quais de Theramore."}}
D[11134] = {"La fin des déserteurs",{"Capturez Gavis Targegrise, puis allez faire votre rapport à Calia Hastings près des quais de Theramore."}}
D[11135] = {"Le Cavalier sans tête",{"Trouvez le Sanctuaire de la citrouille du Cavalier sans tête."}}
D[11136] = {"Un développement inquiétant",{"Présentez-vous au capitaine Wymor à la Halte de la vigie."}}
D[11137] = {"Des défias à Âprefange ?",{"Récupérez les Ordres des défias sur Garn Mathers, et remettez-les au Capitaine Wymor à la halte de la Vigie."}}
D[11138] = {"Renn McBranchie",{"Apportez les Ordres des défias à Renn McBranchie dans les eaux au large du Rivage de Troubleffroi."}}
D[11139] = {"Équipement de plongée d'occasion",{"Apportez le Jeu d'outils et l'Équipement de plongée endommagé à Renn McBranchie dans le marécage d'Âprefange."}}
D[11140] = {"Récupérez la cargaison !",{"Remettez 6 Coffres récupérés à Renn McBranchie, dans le marécage d'Âprefange."}}
D[11141] = {"Jaina doit être informée",{"Parler à dame Jaina Portvaillant à Theramore."}}
D[11142] = {"Survoler l'île d'Alcaz",{"Parlez à Cassa Cramoissaile et utilisez l'un de ses griffons pour survoler l'île d'Alcaz. Lorsque vous aurez achevé vos observations, parlez à dame Jaina Portvaillant à Theramore."}}
D[11143] = {"Un lien Sinistre",{"Présentez-vous au Capitaine Darill à la Halte nord."}}
D[11144] = {"Confirmer les soupçons",{"Remettez le Plan de bataille du Totem-sinistre au Capitaine Darill, à la Tour de la halte nord."}}
D[11145] = {"Prisonniers des Totems-sinistres",{"Le Sergent Lukas, de la Tour de la halte nord, veut que vous libériez 5 Prisonniers de Theramore."}}
D[11146] = {"Rapt de raptor",{"Le Sergent Lukas, de la Tour de la halte nord, veut que vous capturiez 6 raptors. Vous pouvez capturer des Raptors Rougefange ou des Hurleurs Rougefange, au choix."}}
D[11147] = {"Lâcher les raptors",{"Le Sergent Lukas, de la Tour de la halte nord, veut que vous placiez l'Appât à raptor près du moulin à vent de Sabot-noir."}}
D[11148] = {"Les armes des Totems-sinistres",{"Le Capitaine Darill, de la Tour de la halte nord, veut que vous lui rameniez 7 Armes de Sabot-noir."}}
D[11149] = {"L'aide de Tabetha",{"Parlez à Tabetha dans sa ferme."}}
D[11150] = {"Rasez le poste de Navrecorne !",{"Brûlez la Tente nord, la Tente est et la Tente nord-est du Poste de Navrecorne, puis revenez voir Tabetha dans sa ferme."}}
D[11151] = {"Justice pour les Hyal",{"Parlez au Capitaine Garran Vimaire à la citadelle de Theramore."}}
D[11152] = {"Enfin la paix",{"Le Capitaine Garran Vimaire, de la citadelle de Theramore, veut que vous déposiez la Couronne au Monument de la famille Hyal."}}
D[11153] = {"Forcer le blocus",{"Prenez les Bombes à sous-munitions de Petrov et lâchez-les sur les pirates. Vous devez tuer 25 Pirates du blocus et détruire 10 Canons du blocus. Lorsque vous aurez terminé, retournez voir le Bombardier Petrov au Donjon de la Garde de l’ouest."}}
D[11154] = {"Dans le guano jusqu'au cou !",{"Récupérez 10 doses de Guano de sombregriffe et livrez-les à l’Ingénieur Fauboulon, à la Porte d’acier."}}
D[11155] = {"Encore de la soupe de brochepelle ?",{"Le chef Bouillenoire vous a demandé de récupérer 6 morceaux de Viande de brochepelle et de les lui remettre au donjon de la Garde de l'ouest."}}
D[11156] = {"Les écumeurs navrecorne",{"Tuez 12 Totem-sinistre de Navrecorne puis revenez voir l'Apprenti Morlann à la Ferme de Tabetha."}}
D[11157] = {"Les œufs maléfiques",{"Détruisez 15 Œufs de proto-drake et 15 Proto-dragonnets, puis retournez voir le Capitaine Adams au Donjon de la Garde de l'ouest."}}
D[11158] = {"Les plumes de Rougefange",{"Brogg de Bourbe-à-brac veut 5 Plumes de Rougefange."}}
D[11159] = {"Les esprits du bastion Cognepierre",{"Brogg de Bourbe-à-brac veut que vous apportiez le repos à 10 Esprits Cognepierre."}}
D[11160] = {"La bannière des Cognepierres",{"Récupérez la Bannière cognepierre et remettez-la à Brogg de Bourbe-à-brac."}}
D[11161] = {"L'essence de l'ennemi",{"Apportez 10 Essences de draconien noir à Brogg à Bourbe-à-brac."}}
D[11162] = {"Un défi au Vol noir",{"Plantez la Bannière cognepierre près de l'entrée du Repaire d'Onyxia, attendez la réponse d'Onyxia, puis rendez la bannière à Brogg de Bourbe-à-brac."}}
D[11163] = {"Taupe secrète",{"Présentez-vous à Donna Brascoe afin de recevoir une récompense pour votre héroïsme à Zul'Aman. Donna est actuellement postée dans les Terres fantômes, juste à l'extérieur de Zul'Aman."}}
D[11164] = {"Illégitimes défenses",{"Dasnob veut que vous récupériez 10 Défenses de trolls des forêts sur les trolls de Zul'Aman. Apportez-les-lui au camp de Budd dans les Terres fantômes."}}
D[11165] = {"Un troll parmi les trolls",{"Dasnob vous a chargé de trouver son cousin Zungam pour lui venir en aide, quelque part à l'intérieur de Zul'Aman."}}
D[11166] = {"X marque... votre mort !",{"Entrez dans Zul'Aman et visitez la Chambre d'Halazzi, la Plate-forme de Jan'alai et la Plate-forme d'Akil'zon. Rendez compte des détails de ces zones à Budd, dans son camp des Terres fantômes."}}
D[11167] = {"La Peste nouvelle",{"L'Apothicaire Lysander, à l'Accostage de la Vengeance, vous demande de récupérer 10 Conteneurs de peste intacts dans le navire échoué au sud-est."}}
D[11168] = {"Enrichir le mélange",{"Remettez 3 Glandes à toxine géantes prélevées sur des Clampants des marées géants à l'Apothicaire Lysander, à l'Accostage de la Vengeance, dans le Fjord hurlant."}}
D[11169] = {"L'arme des Totems-sinistres",{"L'Apprenti Garion, de la ferme de Tabetha, veut que vous testiez le Totem capturé sur 10 Crocilisques tachetés Sèchefange ou Crocs-lames Sèchefange."}}
D[11170] = {"Essai en mer",{"Parlez à l'Éleveuse de chauves-souris Camille et prenez une chauve-souris pour intercepter les renforts de l'Alliance. Lorsque vous serez au-dessus de leur flotte, utilisez les Fioles de peste pour contaminer 16 Réservistes de la flotte du nord."}}
D[11171] = {"Seigneur des maléfices ? Ha !",{"Budd Truducou, aux Collines de la Cognée, veut que vous alliez tuer le Seigneur des maléfices Malacrass à Zul'Aman."}}
D[11172] = {"L'épave du zeppelin",{"Parler à Moxie Grilledacier à l'Épave de Beezil."}}
D[11173] = {"Le voleur de composants",{"Apporter 6 fioles de Venin des marais à l'Apprenti Garion à la Ferme de Tabetha."}}
D[11174] = {"Prévention de la corrosion",{"Moxie Grilledacier vous demande de dissoudre 10 limons avant de retourner la voir à l'Épave de Beezil."}}
D[11175] = {"Ma fille",{"Le Vieux Mantepierre vous a demandé de trouver sa fille, la Surveillante Irena Mantepierre, à la Porte d'acier du Fjord hurlant."}}
D[11176] = {"Allez, au travail !",{"L’exploratrice Irena Mantepierre vous a demandé de parler avec un Chef archéologue de la Porte d’acier, à la Porte d’acier."}}
D[11177] = {"L'ermite du manoir des Flammeroles",{"Parler à Jarl \"Œil-des-marais\" au Manoir des Flammeroles."}}
D[11178] = {"Le sang du seigneur de guerre",{"Apportez le Sang de Zul'jin à Budd à son campement dans les Terres fantômes, à l'extérieur de Zul'Aman."}}
D[11179] = {"[En attente d'un nouveau monstre]Finlay manque de tripes",{"Récupérez 7 Boyaux de sabre-de-brume en parfait état pour Finlay Fléchier, et allez les lui remettre au donjon de la Garde de l’ouest."}}
D[11180] = {"Qui hante la Colline des sorcières ?",{"Mordant Grimsby du manoir des Flammeroles vous demande de collecter des informations auprès de 10 Carcasses ressuscitées ou Esprits ressuscités."}}
D[11181] = {"La plaie de la sorcière",{"Apporter 9 branches de Sorbier à Mordant Grimsby au Manoir des Flammeroles."}}
D[11182] = {"Aux racines du mal",{"Tuez 5 Dresseurs vrykuls et Skeld Fils-de-drake ; Si vous y parvenez, retournez voir un Ancien de l'Étreinte de braise."}}
D[11183] = {"Nettoyer la Colline des sorcières",{"Mordant Grimsby au Manoir des Flammeroles veut que vous plantiez la torche au bout du quai et que vous abattiez tout ce qui pourrait apparaître."}}
D[11184] = {"ON RECHERCHE : Griffétripe le Vorace",{"Tuer Griffétripe le Vorace et se présenter à Drazzit Suintevalve à Bourbe-à-brac."}}
D[11185] = {"La lettre de l'apothicaire",{"Apportez la Lettre scellée à Andello Porter à la Ferme de Tabetha."}}
D[11186] = {"Des signes de trahison ?",{"Apportez la Lettre scellée à Nazeer Pique-sanglante à Mur-de-Fougères."}}
D[11187] = {"Le lieutenant-mage Malister",{"Le Capitaine Adams vous a demandé de parler à son conseiller, le Lieutenant-mage Malister, au Donjon de la Garde de l'ouest."}}
D[11188] = {"Deux torts…",{"Le Lieutenant-mage Malister, du donjon de la Garde de l'ouest, vous a demandé de détruire 3 Proto-drakes."}}
D[11189] = {"Une dernière fois",{"Escortez le Fantôme de l'Explorateur Jaren à l'Exploratrice Irena Mantepierre, à la Porte d'acier du Fjord Hurlant."}}
D[11190] = {"Ce modèle n'existe pas en taille unique !",{"Le Canonnier Ely veut que vous récupériez 10 Boulets de canons de la Garde de l’ouest et que vous les lui remettiez, au donjon de la Garde de l’ouest."}}
D[11191] = {"Le vieux phare",{"Parler à Babs Patranivelle au phare sur l'île à l'est de Theramore."}}
D[11192] = {"L'huile de batteur",{"Apportez 4 récipients d'Huile de batteur à Babs Patranivelle au phare près de Theramore."}}
D[11193] = {"Créatures ignobles des profondeurs",{"Apporter « Créatures ignobles des profondeurs » à Michael « Crado » Crowe sur les docks de Theramore."}}
D[11194] = {"Il existe ?",{"Parlez à Nat Pagle au Point d’accostage de Nat, au Marécage d'Âprefange."}}
D[11195] = {"Jouer à la poupée",{"Apportez la Poupée vaudou en lambeaux à Eskrokar à Shattrath."}}
D[11196] = {"TEMP X",{"Dasnob vous a chargé de trouver son cousin Zungam pour lui venir en aide, quelque part à l'intérieur de Zul'Aman."}}
D[11198] = {"Il faut tuer Tethyr !",{"Le Major Mills aux Docks de Theramore veut que vous abattiez Tethyr."}}
D[11199] = {"Se présenter à l'éclaireur Knowles",{"Le capitaine Adams vous a demandé de vous présenter à l'Éclaireur Knowles, à la Tour de la Lance de braise."}}
D[11200] = {"Plus qu'une coïncidence",{"Krog, du village de Mur-de-Fougères, veut que vous lui rameniez 7 Armes de Sabot-noir."}}
D[11201] = {"Le complot totem-sinistre",{"Remettez le Plan de bataille du Totem-sinistre à Krog, du village de Mur-de-Fougères."}}
D[11202] = {"Mission : la flamme éternelle",{"L’Éclaireur Knowles, de la Tour de la Lance de braise, souhaite que vous utilisiez les Torches semperardentes pour détruire les quatre Chars de peste qui entourent Halegrince."}}
D[11203] = {"À la recherche de Tabetha",{"Parlez à Tabetha dans sa ferme du Bourbier."}}
D[11204] = {"Retourner voir Krog",{"Parler à Krog au village de Mur-de-Fougères."}}
D[11205] = {"Rasez le poste de Navrecorne !",{"Brûlez la Tente nord, la Tente est et la Tente nord-est du Poste de Navrecorne, puis revenez voir Tabetha dans sa ferme."}}
D[11206] = {"Justice est faite !",{"Retourner voir Krog au village de Mur-de-Fougères."}}
D[11207] = {"Sauvez la cargaison !",{"Moxie Grilledacier à l'Épave de Beezil veut que vous retrouviez 8 morceaux de Cargaison de zeppelin."}}
D[11208] = {"Une livraison pour Drazzit",{"Remettre la Cargaison du zeppelin à Drazzit Suintevalve à Bourbe-à-brac."}}
D[11209] = {"Le marché de Nat",{"Nat Pagle, au Point d'accostage de Nat, vous demande de tester son nouvel appât à poissons."}}
D[11210] = {"Il existe !",{"Parler au Major Mills sur les quais de Theramore."}}
D[11211] = {"De l'aide pour Bourbe-à-brac",{"Parler à Drazzit Suintevalve à Bourbe-à-brac."}}
D[11212] = {"La ferme de Tabetha",{"Allez trouver Tabetha dans sa ferme, dans le Bourbier."}}
D[11213] = {"Quelles nouvelles de Tabetha ?",{"Parlez à Tabetha dans sa ferme du Bourbier."}}
D[11214] = {"En mission à Bourbe-à-brac",{"Parler à Drazzit Suintevalve à Bourbe-à-brac."}}
D[11215] = {"Aider Bourbe-à-brac",{"Parler à Drazzit Suintevalve à Bourbe-à-brac."}}
D[11216] = {"L'archimage Alturus",{"Parlez à l'Archimage Alturus à l'extérieur de Karazhan au défilé de Deuillevent."}}
D[11217] = {"Attraper un dragon par la queue",{"Gizzix Glougloutache de Bourbe-à-brac vous a demandé de lui apporter 8 tiges de Queue de wyrm."}}
D[11218] = {"Danger ! Explosifs !",{"Utilisez la Dynamite sécurisée d’Anneau-d’acier pour récupérer 6 Fragments de minerai du goulet des Murmures et 18 Gemmes du goulet des Murmures. Ensuite, allez remettre tout ça au Sapeur Anneau-d’acier, au donjon de la Garde de l’ouest."}}
D[11219] = {"Éteignez les incendies !",{"La Directrice d'orphelinat masquée vous demande d'aider à éteindre tous les foyers d'incendie du village. Une fois qu'ils seront éteints, retournez lui parler en ville."}}
D[11220] = {"Le Cavalier sans tête",{"Trouvez le Sanctuaire de la citrouille du Cavalier sans tête."}}
D[11221] = {"Rapports de terrain",{"Parlez au Forestier-sombre Lyana et au Nécrotraqueur Razael, sur le champ de bataille du Val Sanglant, au sud de l’Accostage de la Vengeance. Lorsque ce sera fait, retournez voir le Grand exécuteur Anselme."}}
D[11222] = {"La preuve de la trahison",{"Parler au roi Varian Wrynn au Donjon de Hurlevent."}}
D[11223] = {"Retourner voir Jaina",{"Parler à dame Jaina Portvaillant à Theramore."}}
D[11224] = {"Têtes de mule",{"L’Exploratrice Abigail vous a demandé de faire /ohé devant 10 Mules de bât abandonnées, puis de retourner la voir au donjon de la Garde de l’ouest."}}
D[11225] = {"L'ermite de la Colline des sorcières",{"Parler à Jarl \"Œil-des-marais\" au Manoir des Flammeroles."}}
D[11227] = {"Qu'ils mangent du corbeau",{"Pontius, le maître du chenil de l’Accostage de la Vengeance, veut que vous utilisiez la Cage de chien pestiféré pour invoquer un Chien pestiféré affamé. Vous lui donnerez de la Viande de corbeau, prélevée sur les Corbeaux du Fjord, à l’ouest de l’Accostage de la Vengeance."}}
D[11228] = {"L'enfer a gelé…",{"Parlez au vice-amiral Keller au port de Valgarde."}}
D[11229] = {"La flotte du Coursevent",{"Parlez à l’Éleveuse de chauve-souris Camille à l’Accostage de la Vengeance, et demandez-lui de vous envoyer sur le Coursevent. Une fois à bord, présentez-vous au capitaine Harker."}}
D[11230] = {"Embusqués !",{"Le capitaine Harker, à bord du Coursevent, veut que vous tuiez 15 Soldats de marine de la flotte du nord."}}
D[11231] = {"Des clés et des cages",{"Le Père Levariol vous a demandé de récupérer assez de Clés de cage de Gjalerbron pour libérer 10 Prisonniers de Gjalerbron. Lorsque ce sera fait, retournez le voir au Donjon de la Garde de l’ouest."}}
D[11232] = {"Guidez nos tirs",{"Utilisez les Fumigènes aux emplacements des Canons de l’Alliance, sur la paroi nord de la Grève des Épaves. Lorsque ce sera fait, présentez-vous au Forestier-sombre Lyana, au Val Sanglant."}}
D[11233] = {"Le coup de grâce",{"Le forestier-sombre Lyana, au sud de l’Accostage de la Vengeance, veut que vous tuiez le Capitaine Olster, le Sergent Lorric et le Lieutenant Celeyne à la Grève des Épaves."}}
D[11234] = {"Se présenter à Anselme",{"Présentez-vous au Grand exécuteur Anselme à l'Accostage de la Vengeance, dans le Fjord hurlant."}}
D[11235] = {"S'occuper de Gjalerbron",{"Le Capitaine Adams vous a demandé de tuer 15 Guerriers de Gjalerbron, 8 Lanceurs de runes de Gjalerbron et 8 Gardiens du sommeil de Gjalerbron. Ensuite, revenez le voir au donjon de la Garde de l’ouest."}}
D[11236] = {"Le nécro-suzerain Mezhen",{"Tuez le Nécro-suzerain Mezhen, puis retournez voir le Capitaine Adams au Donjon de la Garde de l’ouest."}}
D[11237] = {"Les plans d'attaque de Gjalerbron",{"Remettez les Plans d'attaque de Gjalerbron au Lieutenant-mage Malister, au Donjon de la Garde de l'ouest."}}
D[11238] = {"Le wyrm de givre et son maître",{"Tuez le Mande-wyrm Vile et utilisez le Cor mande-wyrm pour appeler et tuer Glacion. Lorsque ce sera fait, retournez avec le cor voir le Lieutenant-mage Malister au Donjon de la Garde de l’ouest."}}
D[11239] = {"Au service de la Lumière",{"Tuer 10 Guetteurs impérissables, 4 Horreurs effroyables et 2 Nécrophages putrides. Lorsque ce sera fait, informez de votre réussite le Père Levariol au Donjon de la Garde de l’ouest."}}
D[11240] = {"Le chef des dérangés",{"Tuez Squeeg Chassidole, puis présentez-vous au Sapeur Anneau-d'acier, au Donjon de la Garde de l'ouest."}}
D[11241] = {"Une piste enflammée",{"Escortez l’Apothicaire Hanes jusqu’à la sortie de la Grève des Épaves. Lorsque ce sera fait, présentez-vous à l’Apothicaire Lysander à l’Accostage de la Vengeance."}}
D[11242] = {"Enfin libre !",{"Apportez le Tome de Thomas Thomson à la Directrice d'orphelinat costumée à Comté-de-l'or, à Kharanos ou au Guet d'azur."}}
D[11243] = {"Si Valgarde tombe…",{"Le Vice-amiral Keller, du port de Valgarde dans le Fjord hurlant, veut que vous tuiez 12 Envahisseurs écorche-dragon ou 12 Worgs écorche-dragon."}}
D[11244] = {"Au secours des secours",{"Le Vice-amiral Keller, du port de Valgarde dans le Fjord hurlant, veut que vous secouriez 8 Éclaireurs de Valgarde qui ont été empalés et laissés pour morts."}}
D[11245] = {"Les tours de la fatalité",{"Le Sergent de la Garde de l’ouest vous a expliqué qu’il serait souhaitable de marquer les quatre tours de Mörg en prévision d’une canonnade, à l'aide du Fumigène du sergent."}}
D[11246] = {"Salissant, mais nécessaire",{"Le Sergent de la Garde de l’ouest vous a demandé de démembrer 20 Vrykuls de la tribu Mörghiver, à Mörg, à l'aide de la Machette du sergent."}}
D[11247] = {"Brûle, Mörg, brûle !",{"Le Sergent de la Garde de l’ouest vous a ordonné de mettre le feu aux maisons longues du nord-est et du nord-ouest et à la caserne de Mörg, à l'aide de la Torche du sergent."}}
D[11248] = {"Opération Croque-Mörg",{"Le capitaine Adams vous a demandé d’utiliser l’Insigne de commandement de la Garde de l’ouest à Mörg, puis de parler avec le Sergent de la Garde de l’ouest."}}
D[11249] = {"Arrêter l'ascension !",{"Utilisez le Parchemin d’ascension vrykul près du Bûcher du thane pour faire venir ce dernier et le tuer. Lorsque ce sera fait, vous êtes sûr que le Père Levariol, au Donjon de la Garde de l’ouest, sera intéressé par le parchemin, en raison de la nature du rituel."}}
D[11250] = {"Gloire au conquérant de Mörg !",{"Allez rendre l’Insigne de commandement de la Garde de l’ouest au Capitaine Adams, au Donjon de la Garde de l’ouest."}}
D[11251] = {"Un second souffle",{"L’Éclaireur Valory veut que vous enquêtiez sur les bruits de combat qui viennent du nord-est de Crâne-du-ver."}}
D[11252] = {"Dans Utgarde !",{"Le Défenseur Mordun vous a demandé de tuer Ingvar le Pilleur, qui réside dans les profondeurs d’Utgarde.","","Lorsque ce sera fait, vous devez présenter sa tête au Vice-amiral Keller."}}
D[11253] = {"Renifler l'ennemi",{"Utilisez la Laisse de chien pestiféré près des cages des chiens pestiférés à l’Accostage de la Vengeance, et cherchez les indices là où vous conduira le Chien pestiféré traqueur."}}
D[11254] = {"La carte en peau de dragon",{"Apportez la Carte en peau de dragon au Grand exécuteur Anselme à l’Accostage de la Vengeance."}}
D[11255] = {"Les prisonniers de Crâne-du-ver",{"Le Vice-amiral Keller, au port de Valgarde dans le Fjord hurlant, veut que vous sauviez 3 Prisonniers de Valgarde capturés."}}
D[11256] = {"Mörg doit tomber !",{"Le Chef Totem-de-frêne vous a demandé d’utiliser l’Emblème de Sabot-d’hiver à Mörg, puis de parler avec le Brave Sabot-d’hiver."}}
D[11257] = {"Salissant, mais nécessaire",{"Le Brave Sabot-d’hiver vous a demandé de démembrer 20 Vrykuls Mörghiver, à Mörg, à l'aide de la Machette du brave."}}
D[11258] = {"Brûle, Mörg, brûle !",{"Le Brave Sabot-d’hiver suggère que vous mettiez le feu aux deux maisons longues les plus basses et à la caserne de Mörg à l'aide de la Torche du brave."}}
D[11259] = {"Les tours de la fatalité",{"Le Brave Sabot-d’hiver vous a informé qu’il serait souhaitable de marquer les quatre tours de Mörg en prévision de frappes aériennes à l'aide du Fumigène du brave."}}
D[11260] = {"Arrêter l'ascension !",{"Utilisez le Parchemin d’ascension vrykul près du Bûcher du thane pour faire apparaître ce dernier et le tuer. Lorsque ce sera fait, vous êtes sûr que la Grande-mère Ankha, au Camp Sabot-d’hiver, sera intéressée par le parchemin, en raison de la nature du rituel."}}
D[11261] = {"Le conquérant de Mörg",{"Allez rendre l’Emblème Sabot-d’hiver au Chef Totem-de-frêne, au Camp Sabot-d’hiver."}}
D[11262] = {"Ingvar doit mourir !",{"Le forestier-sombre Marrah vous a demandé de tuer Ingvar le Pilleur, qui réside dans les profondeurs d’Utgarde.","","Lorsque ce sera fait, vous devez présenter sa tête au Grand exécuteur Anselme, à l’Accostage de la Vengeance."}}
D[11263] = {"S'occuper de Gjalerbron",{"Le Chef Totem-de-frêne vous a demandé de tuer 15 Guerriers de Gjalerbron, 8 Lanceurs de runes de Gjalerbron et 8 Gardiens du sommeil de Gjalerbron. Ensuite, revenez le voir au Camp Sabot-d’hiver."}}
D[11264] = {"Le nécro-suzerain Mezhen",{"Tuez le nécro-suzerain Mezhen, puis retournez voir le Chef Totem-de-frêne au camp Sabot-d’hiver."}}
D[11265] = {"Des clés et des cages",{"La Grande-mère Ankha vous a demandé de récupérer assez de Clés de cages de Gjalerbron pour libérer 10 Prisonniers de Gjalerbron. Si vous y parvenez, retournez la voir au Camp Sabot-d’hiver."}}
D[11266] = {"Les plans d'attaque de Gjalerbron",{"Remettez les Plans d’attaque de Gjalerbron à Celea Crin-gelé, au Camp Sabot-d’hiver."}}
D[11267] = {"Le wyrm de givre et son maître",{"Tuez le Mande-wyrm Vile, puis utilisez le Cor mande-wyrm pour appeler Glacion. Tuez-le, et retournez voir Celea Crin-gelé au Camp Sabot-d’hiver avec le cor."}}
D[11268] = {"Les morts qui marchent",{"Tuez 10 Guetteurs impérissables, 4 Horreurs effroyables et 2 Nécrophages putrides. Lorsque ce sera fait, allez informer de votre succès la Grande-mère Ankha, au Camp Sabot-d’hiver."}}
D[11269] = {"Y laisser des plumes",{"Gil Grisert veut que vous lui rapportiez 10 touffes de Duvet d’hippogriffe tacheté."}}
D[11270] = {"La guerre, c'est l'enfer",{"Vous effectuez cette quête"}}
D[11271] = {"Des préparatifs hâtifs",{"Ahota Givre-blanc, du Camp Sabot-d’hiver, veut que vous lui rapportiez 10 touffes de Duvet d’hippogriffe tacheté."}}
D[11272] = {"Un compte à régler",{"Le Grand exécuteur Anselme veut que vous pénétriez dans Utgarde pour y tuer le prince Keleseth."}}
D[11273] = {"La ligue humaine",{"Fouillez Crâne-du-ver à la recherche de Pulroy."}}
D[11274] = {"Zedd est probablement mort",{"Fouiller le village de Crâne-du-ver à la recherche de Zedd."}}
D[11275] = {"Fabriquer le cor",{"Nokoma Œil-des-neiges, au camp Sabot-d’hiver, veut que vous lui rapportiez 6 Cornes de bélier intactes."}}
D[11276] = {"Ils étaient deux",{"Fouillez les Catacombes d'Utgarde à la recherche de Glorenfeld."}}
D[11277] = {"Les profondeurs de la dépravation",{"Glorenfeld, dans les Catacombes d'Utgarde, vous demande de réunir 10 Tablettes Crâne-du-ver."}}
D[11278] = {"Retour à Valgarde",{"Remettez le Paquet de Glorenfeld à Beltrand McSorf, au port de Valgarde."}}
D[11279] = {"Ces proto-dragonnets sont trop verts…",{"Le Porte-peste Tillinghast vous a demandé de récupérer 10 Spécimens de proto-dragonnets pestiférés, et de les lui remettre à la Nouvelle-Agamand."}}
D[11280] = {"Draconis Gastritis",{"Le Porte-peste Tillinghast, de la Nouvelle-Agamand, veut que vous utilisiez la Viande pestiférée de Tillinghast pour attirer un Proto-drake. Observez ses réactions lorsqu’il la mangera."}}
D[11281] = {"Imiter l'appel de la nature",{"Testez le Cor sculpté, puis allez faire part du résultat à Nokoma Œil-des-neiges, au Camp Sabot-d’hiver."}}
D[11282] = {"Une leçon de peur",{"Gorth veut que vous tuiez Ulf le Saigneur, Oric le Torve et Gunnar Thorvardsson, et que vous plantiez la Bannière des Réprouvés sur leurs corps. Tuez des vrykuls tout au long du blocus des Réprouvés jusqu’à ce qu’ils apparaissent."}}
D[11283] = {"Le décompte des cadavres de Torvheim",{"Le sergent Gorth veut que vous entriez dans Torvheim pour y tuer 16 Vrykuls de Mörghiver."}}
D[11284] = {"Le yéti d'à-côté",{"Le Contremaître Colbey de Fort Hardivar veut que vous battiez Brise-corne."}}
D[11285] = {"Torvheim doit brûler !",{"Le sergent Gorth veut que vous entriez dans Torvheim et que vous vous serviez de la Torche de Gorth pour brûler 1 Logis Mörghiver, 1 Tour de guet Mörghiver, 1 Pont Mörghiver et 1 Caserne Mörghiver."}}
D[11286] = {"Les artéfacts de la Porte d'acier",{"Le Sage Marche-brume veut que vous récupériez 10 Artéfacts de la Porte d’acier. Lorsque vous les aurez, remettez-les-lui à la Porte d’acier."}}
D[11287] = {"Trouver le sage Marche-brume",{"La Grande-mère Ankha vous a demandé d'aller vérifier si le Sage Marche-brume allait bien. Elle pense qu'il se trouve à la Porte d'acier ou bien à proximité."}}
D[11288] = {"La Lumière rayonnante",{"Arès le Féal des Catacombes d’Utgarde veut que vous récupériez l’Artéfact sacré.","","Cette quête est en temps limité."}}
D[11289] = {"Guidé par l'honneur",{"Rapportez l'Artéfact sacré au Seigneur Irulon Lamevraie à Valgarde."}}
D[11290] = {"Les plans de bataille des Écorche-dragon",{"Le Vice-amiral Keller, au port de Valgarde dans le Fjord hurlant, vous a demandé de lui apporter les plans de bataille des Écorche-dragon."}}
D[11291] = {"Au donjon de la Garde de l'ouest !",{"Remettez les Plans de bataille des Écorche-dragon au Capitaine Adams, au donjon de la Garde de l’ouest, dans le Fjord hurlant."}}
D[11292] = {"Faire des faibles sa proie",{"Le Trappeur Jethan, au Fort Hardivar, veut que vous lui rameniez 8 Proies piégées."}}
D[11293] = {"Des aboyeurs pour les Brasselorge!"}
D[11294] = {"Des aboyeurs pour les Tonnebière!"}
D[11295] = {"L'offensive commence",{"Parlez au Sergent Gorth, qui dirige le blocus, non loin de l’ascenseur, à l’ouest de l’Accostage de la Vengeance, dans le Fjord hurlant."}}
D[11296] = {"Les prisonniers de Clivebois",{"Le Long-coureur Nuage-du-ciel vous a demandé de libérer 7 Longs-coureurs Sabot-d’hiver. Lorsque ce sera fait, retournez à la Porte d’acier."}}
D[11297] = {"Garder un œil sur les intrus",{"Parlez à l’Apothicaire Malthus, au Camp des Apothicaires."}}
D[11298] = {"Mais qu'est-ce qu'il y a dans ce truc ?",{"L’Apothicaire Malthus, du Camp des Apothicaires, veut que vous lui rapportiez 5 Tonneaux des nains."}}
D[11299] = {"L'arène du Jugement",{"Trouvez Daegarn dans l’Arène du jugement, à l’intérieur des Catacombes d’Utgarde."}}
D[11300] = {"Formidable déconfiture dans l'arène",{"Triomphez des gladiateurs de l’Arène du Jugement et affrontez Oluf le Violent. Battez-le et récupérez le Code antique.","","Remettez le Code antique à Glorenfeld à l’entrée des Catacombes d’Utgarde."}}
D[11301] = {"Cerveaux ! Cerveaux ! Cerveaux !",{"L’Apothicaire Grick, du Camp des Apothicaires, veut que vous lui rapportiez 12 Cerveaux d’explorateurs dérangés."}}
D[11302] = {"Les énigmatiques nymphes de givre",{"Allez parler à Lurielle dans la Clairière Gelée."}}
D[11303] = {"L'embuscade",{"Parlez à Lydell à l'Embuscade de Lydell."}}
D[11304] = {"La Nouvelle-Agamand",{"Remettez la Souche de Lysander au Porte-peste en chef Harris, à la Nouvelle-Agamand, à l’ouest du Fjord Hurlant."}}
D[11305] = {"Une formule sur mesure",{"Procurez-vous le Sang du patriarche écorche-dragon sur Thorvald au Camp de Thorvald, et apportez-le au Porte-peste en chef Harris à la Nouvelle-Agamand."}}
D[11306] = {"Réchauffez et remuez",{"Remplissez le Flacon d’apothicaire vide au Chaudron de sang de vrykul, puis mélangez le contenu du Flacon de sang de vrykul avec les Échantillons de peste de Harris jusqu’à ce que vous obteniez une Décoction équilibrée.","","Lorsque ce sera fait, retournez voir le Porte-peste en chef Harris."}}
D[11307] = {"Essai sur le terrain",{"Pénétrez dans Halegrince et utilisez le Pestorisateur sur 10 Vrykuls Écorche-dragon pestiférés. Ensuite, retournez voir le Porte-peste en chef Harris pour lui présenter les résultats."}}
D[11308] = {"On nettoie et on ferme",{"Parlez à Jenny « Scie à métaux » à Nouvelle-Agamand."}}
D[11309] = {"Des p'tits bouts partout",{"Jenny « Scie à métaux », à la Nouvelle-Agamand, veut que vous récupériez 6 Ligaments de brochepelle et 1 Livre de chair fraîche."}}
D[11310] = {"Avertissement : assemblage nécessaire",{"Servez-vous de la Trousse de confection d’abomination à Halegrince. Attirez des Vrykuls pestiférés avec votre Abomination décérébrée. Tuez-en au moins 20, puis retournez voir Jenny « Scie à métaux » à la Nouvelle-Agamand."}}
D[11311] = {"Supprimer les éléments",{"Le Dompteur des vents Kagan, au Camp Sabot-d’hiver, veut que vous tuiez 8 élémentaires des montagnes. Il peut s’agir de Cyclones hurlants ou d’Élémentaires Glacéclat."}}
D[11312] = {"La clairière Gelée",{"Parlez à Lurielle à la Clairière Gelée."}}
D[11313] = {"Les esprits de la glace",{"Lurielle de la Clairière Gelée veut que vous lui rapportiez 15 Noyaux glacials."}}
D[11314] = {"Les sœurs déchues",{"Lurielle de la Clairière Gelée veut que vous utilisiez son pendentif sur 7 Nymphes algides."}}
D[11315] = {"Le lierre sauvage",{"Lurielle de la Clairière Gelée veut que vous tuiez 8 Lierres écarlates."}}
D[11316] = {"L'engeance de la clairière Tordue",{"Lurielle de la Clairière Gelée veut que vous tuiez 10 Rampants roncevigne."}}
D[11317] = {"La purification",{"Le Sage Marche-brume vous a conseillé de vous purifier de votre Trouble intérieur par la méditation au Sanctuaire de Givrelame."}}
D[11318] = {"Ça c'est de la course de béliers... enfin, presque.",{"Vous avez quatre minutes pour chevaucher le bélier et maintenir 3 différentes allures pendant 8 secondes chacune."}}
D[11319] = {"Les graines de gardiens à l'âme noircie",{"Lurielle de la Clairière Gelée veut que vous geliez 8 Spores."}}
D[11321] = {"Quelqu'un a dit «souvenir»?"}
D[11322] = {"La purification",{"La guetteuse Feuillelune vous a conseillé de vous purifier de votre Trouble intérieur par la méditation au Sanctuaire de Givrelame."}}
D[11323] = {"Déguisé en worg",{"Le Sage Marche-brume vous a demandé de trouver Ulfang et de l’aider. Il doit se trouver dans Clivebois.","","Si vous perdez le déguisement de worg, demandez au Sage Marche-brume de vous le remplacer."}}
D[11324] = {"L'alpha des worgs",{"Ulfang vous a demandé de tuer Garwal. Ensuite, retournez voir le Sage Marchebrume à la Porte d’acier et rendez-lui le Déguisement de worg."}}
D[11325] = {"Déguisé en worg",{"La guetteuse Feuillelune vous a demandé de trouver Ulfang et de l’aider. Il doit se trouver dans Clivebois.","","Si vous perdez le Déguisement de worg, demandez à la guetteuse Feuillelune de vous le remplacer."}}
D[11326] = {"L'alpha des worgs",{"Ulfang vous a demandé de tuer Garwal. Ensuite, retournez voir la Guetteuse Feuillelune à la Porte d’acier et rendez-lui le Déguisement de worg."}}
D[11327] = {"Mission : récupération de paquet",{"L’Éclaireur Knowles vous a demandé de récupérer le Paquet de l’apothicaire, qui est quelque part dans Halegrince. Lorsque vous l’aurez, retournez le voir à la tour de la Lance de braise."}}
D[11328] = {"Mission : des infos sur les Réprouvés",{"L’Éclaireur Knowles vous a demandé de livrer le Paquet de l’apothicaire à Peppy Tuyèrronée, au donjon de la Garde de l’ouest."}}
D[11329] = {"J'essayerai n'importe quoi !",{"Christopher Sloan, au Fort Hardivar, veut que vous lui rapportiez 5 Rascasses nordiques."}}
D[11330] = {"Farpaitement ! Cha va marcher !",{"Peppy Tuyèrronée suggère que vous preniez son Mélange spécial de Peppy et que vous l’administriez au Vrykul écorche-dragon prisonnier, pour voir."}}
D[11331] = {"Allez lui dire que... Hips !",{"Peppy Tuyèrronée vous a manipulé afin que ce soit vous qui annonciez au Capitaine Adams les mauvaises nouvelles concernant la peste des Réprouvés. Allez le voir au donjon de la Garde de l’ouest."}}
D[11332] = {"Mission : contamination !",{"Le Capitaine Adams vous a ordonné de larguer 5 bombes sur les Chars de peste de la Nouvelle-Agamand. Ne revenez pas le voir au donjon de la Garde de l’ouest tant que ce ne sera pas fait."}}
D[11333] = {"Dans le monde des esprits",{"Thoralius le Sage à Valgarde veut que vous retrouviez sa Bourse de réactifs."}}
D[11335] = {"Appel aux armes : bassin Arathi",{"Remportez la bataille dans le Bassin Arathi, puis présentez-vous à un Général de brigade de l'Alliance, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de l'Alliance."}}
D[11336] = {"Appel aux armes : vallée d'Alterac",{"Remportez la bataille dans la Vallée d'Alterac, puis présentez-vous à un Général de brigade de l'Alliance, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de l'Alliance."}}
D[11337] = {"Appel aux armes : Œil du cyclone",{"Gagnez dans l'Œil du cyclone, puis présentez-vous à un Général de brigade de l'Alliance, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de l'Alliance."}}
D[11338] = {"Appel aux armes : goulet des Chanteguerres",{"Remportez la bataille dans le Goulet des Chanteguerres, puis présentez-vous à un Général de brigade de l'Alliance, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de l'Alliance."}}
D[11339] = {"Appel aux armes : bassin Arathi",{"Remportez la bataille dans le Bassin Arathi, puis présentez-vous à un Porteguerre de la Horde, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de la Horde."}}
D[11340] = {"Appel aux armes : vallée d'Alterac",{"Remportez la bataille dans la Vallée d'Alterac, puis présentez-vous à un Porteguerre de la Horde, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de la Horde."}}
D[11341] = {"Appel aux armes : Œil du cyclone",{"Remportez la bataille dans l'Œil du cyclone, puis présentez-vous à un Porteguerre de la Horde, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de la Horde."}}
D[11342] = {"Appel aux armes : goulet des Chanteguerres",{"Remportez la bataille dans le Goulet des Chanteguerre, puis présentez-vous à un Porteguerre de la Horde, à Joug-d'hiver, à Dalaran, à Shattrath ou dans l'une des capitales de la Horde."}}
D[11343] = {"L'écho d'Ymiron",{"Thoralius le Sage veut que vous exploriez Crâne-du-ver dans le monde des esprits, à la recherche d’informations sur les Secrets de Crâne-du-ver."}}
D[11344] = {"Angoisse à Nifflevar",{"Thoralius le Sage veut que vous exploriez Nifflevar dans le monde des esprits, à la recherche d’informations sur les Secrets de Nifflevar."}}
D[11346] = {"Le Livre des runes",{"Le Prospecteur Belvar, de Fort Hardivar, veut que vous lui rapportiez le Livre des runes."}}
D[11348] = {"La rune de commandement",{"Le Prospecteur Belvar de Fort Hardivar veut que vous testiez la Rune de commandement et que vous battiez le Lieur Murdis."}}
D[11349] = {"Maîtriser les runes",{"Le Prospecteur Belvar à Fort Hardivar veut que vous lui rapportiez une série d’Outils de gravure de Runes-de-fer."}}
D[11350] = {"Le Livre des runes",{"Le Long-coureur Pembe, au Camp Sabot-d’hiver, veut que vous lui rapportiez le Livre des runes."}}
D[11351] = {"Maîtriser les runes",{"Le Long-coureur Pembe au Camp Sabot-d’hiver veut que vous lui rapportiez une série d’Outils de gravure de Runes-de-fer."}}
D[11352] = {"La rune de commandement",{"Le Long-coureur Pembe au Camp Sabot-d’hiver veut que vous testiez la Rune de commandement et que vous battiez le Lieur Murdis."}}
D[11354] = {"On recherche : La cravache de Nazan",{"Le Marchand des vents Zhareem vous a demandé de vous procurer la Cravache de Nazan. Apportez-la lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11355] = {"La marche des géants",{"Le Chercheur Aderan à Fort Hardivar veut que vous utilisiez le Piolet cherche-rune sur les cadavres de 4 Géants de pierre runifiés."}}
D[11356] = {"La directrice d'orphelinat costumée",{"Parlez à une Directrice d'orphelinat costumée à Comté-de-l'or, à Kharanos ou au Guet d'azur."}}
D[11357] = {"La directrice d'orphelinat masquée",{"Parlez à une Directrice d'orphelinat masquée à Tranchecolline, à Brill ou sur la Place de l'Épervier."}}
D[11358] = {"L'aimant",{"Le Chercheur Aderan, au Fort Hardivar, veut que vous compariez l’Échantillon de rune avec la Tablette brisée."}}
D[11359] = {"Démolir Mégalithe",{"Triomphez de Mégalithe puis revenez voir le Chercheur Aderan au Fort Hardivar."}}
D[11360] = {"Un entraînement de pompier",{"Jetez des seaux d'eau sur 5 feux, puis revenez parler à la Directrice d'orphelinat costumée."}}
D[11361] = {"L'entraînement au combat du feu",{"Jetez des seaux d'eau sur 5 feux, puis parlez à nouveau à la Directrice d'orphelinat masquée à Tranchecolline."}}
D[11362] = {"On recherche : Le bâton à plumes de Keli'dan",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Bâton à plumes de Keli'dan. Apportez-le lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
