D[11371] = {"On recherche : Des myrmidons de Glissecroc",{"Le Traqueur-du-Néant Mah'duun vous a chargé de tuer 14 Myrmidons de Glissecroc. Revenez le voir à la Ville basse de Shattrath quand ils seront tous morts pour recevoir votre prime."}}
D[11372] = {"On recherche : Le panache d'Ikiss",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Panache d'Ikiss. Apportez-le-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11373] = {"On recherche : L'amulette merveilleuse de Shaffar",{"Le Marchand des vents Zhareem vous a demandé de vous procurer l'Amulette merveilleuse de Shaffar. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11374] = {"On recherche : La gemme d'âme de l'exarque",{"Le Marchand des vents Zhareem vous a demandé de vous procurer la Gemme d'âme de l'exarque. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11375] = {"On recherche : Le murmure de Marmon",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Murmure de Marmon. Apportez-le-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11376] = {"On recherche : Des instructrices malveillantes",{"Le Traqueur-du-Néant Mah'duun vous a chargé de tuer 3 Instructrices malveillantes. Revenez le voir à la Ville basse de Shattrath quand elles seront toutes mortes pour recevoir votre prime."}}
D[11377] = {"La vengeance est un plat...",{"Le Rokk, dans la Ville basse, vous a demandé de préparer du Ragoût de kaliri avec sa Marmite. Retournez le voir quand ce sera fait."}}
D[11378] = {"On recherche : La tête du chasseur d'époques",{"Le Marchand des vents Zhareem vous a demandé de vous procurer la Tête du chasseur d'époques. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11379] = {"Un ragoût très épicé",{"Le Rokk, dans la Ville basse, vous a demandé de préparer de la Surprise grillée sur démon dans sa Marmite avec deux Côtelettes mok'nathal et un Serpent croustillant. Retournez le voir quand ce sera fait."}}
D[11380] = {"Manalicieux",{"Le Rokk, dans la Ville basse, vous a demandé de récupérer 15 Baies de mana dans les Écodômes de Raz-de-Néant."}}
D[11381] = {"Une soupe pour l'âme",{"Le Rokk, dans la Ville basse, vous a demandé de préparer de la Soupe spirituelle avec sa Marmite. Retournez le voir quand ce sera fait."}}
D[11382] = {"On recherche : Le sablier d'Aeonus",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Sablier d'Aeonus. Apportez-le-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11383] = {"On recherche : Des seigneurs des failles",{"Le Traqueur-du-Néant Mah'duun vous a chargé de tuer 4 Seigneurs des failles. Revenez le voir à la Ville basse de Shattrath quand ils seront tous morts pour recevoir votre prime."}}
D[11384] = {"On recherche : Une rognure de Brise-dimension",{"Le Marchand des vents Zhareem vous a demandé de vous procurer une Rognure de Brise-dimension. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11385] = {"On recherche : Des canalistes Cherche-soleil",{"Le Traqueur-du-Néant Mah'duun vous a chargé de tuer 6 Canalistes Cherche-soleil. Revenez le voir à la Ville basse de Shattrath quand ils seront tous morts pour recevoir votre prime."}}
D[11386] = {"On recherche : Le projecteur de Pathaleon",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Projecteur de Pathaleon. Apportez-le-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11387] = {"On recherche : Des destructeurs Forge-tempête",{"Le Traqueur-du-Néant Mah'duun vous a chargé de détruire 5 Destructeurs Forge-tempête. Revenez le voir à la Ville basse de Shattrath quand ils seront tous morts pour recevoir votre prime."}}
D[11388] = {"On recherche : Le parchemin de Cieuriss",{"Le Marchand des vents Zhareem vous a demandé de vous procurer le Parchemin de Cieuriss. Apportez-le-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'en mode héroïque."}}
D[11389] = {"On recherche : Des sentinelles de l'Arcatraz",{"Le Traqueur-du-Néant Mah'duun vous a chargé de démanteler 5 Sentinelles de l'Arcatraz. Revenez le voir à la Ville basse de Shattrath quand elles seront toutes mortes pour recevoir votre prime."}}
D[11390] = {"J'ai une machine volante !",{"Le Chef archéologue de la Porte d’acier veut que vous transportiez 3 Sacs de reliques du bas du site à la plate-forme qui se trouve du côté nord ou sud de la Porte d’acier.","","Pour cela, vous devez vous servir du grappin de la machine volante.","","Lorsque ce sera fait, retournez le voir."}}
D[11391] = {"Patrouille à la Porte d'acier",{"Vous êtes l’as des as de la Porte d’acier, désormais. Le Chef archéologue de la Porte d’acier veut que vous fassiez une patrouille autour du site et que vous abattiez tout ce qui vous attaquera.","","Lorsque la patrouille sera terminée, retournez le voir."}}
D[11392] = {"L'appel du Cavalier sans tête",{"Posez une Morne chandelle sur la Terre fraîchement retournée."}}
D[11393] = {"Où est l'explorateur Jaren ?",{"La Surveillante Irena Mantepierre vous a demandé de retrouver son fiancé, l’Explorateur Jaren."}}
D[11394] = {"Et vous pensiez que les murlocs sentaient mauvais !",{"L’Explorateur Jaren veut que vous tuiez 15 créatures du Fléau de n’importe quel type le long de la Côte de Frissonde. Lorsque vous aurez terminé, retournez le voir."}}
D[11395] = {"C'est un appareil du Fléau",{"Remettez l’Appareil du Fléau à l’Exporateur Jaren sur la Côte de Frissonde."}}
D[11396] = {"Abattez ces boucliers",{"L’Exporateur Jaren, sur la Côte de Frissonde, vous a demandé de détruire 3 Cristaux flaellants."}}
D[11397] = {"Et vous pensiez que les murlocs sentaient mauvais !",{"L’Apothicaire Anastasia veut que vous tuiez 15 créatures du Fléau de n’importe quel type le long de la Côte de Frissonde. Lorsque vous aurez terminé, retournez la voir au Camp des Apothicaires."}}
D[11398] = {"C'est un appareil du Fléau",{"Remettez l’Appareil du Fléau à l’Apothicaire Anastasia, au Camp des Apothicaires du Fjord Hurlant."}}
D[11399] = {"Abattez ces boucliers",{"L’Apothicaire Anastasia, du Camp des Apothicaires, vous a demandé de détruire 3 Cristaux flaellants."}}
D[11400] = {"Les béliers de la fête des Brasseurs",{"Apportez le tampon de « Brasseur honoraire » à Pol Distillambre, près de l'entrée de la fête des Brasseurs à Dun Morogh."}}
D[11401] = {"L'appel du Cavalier sans tête",{"Posez une Morne chandelle sur la Terre fraîchement retournée."}}
D[11402] = {"Quête de Clayton : extrême !",{"Allez donc me tuer ces Écureuils maléfiques !"}}
D[11403] = {"Enfin libre !",{"Apportez le Tome de Thomas Thomson à une Directrice d'orphelinat masquée à Durotar, à Brill ou sur la Place de l'Épervier."}}
D[11404] = {"L'appel du Cavalier sans tête",{"Posez une Morne chandelle sur la Terre fraîchement retournée."}}
D[11405] = {"L'appel du Cavalier sans tête",{"Posez une Morne chandelle sur la Terre fraîchement retournée."}}
D[11406] = {"Tout doit être prêt",{"Parlez à Gil Grisert à Fort Hardivar."}}
D[11407] = {"Des aboyeurs pour la distillerie Drohn !",{"Faites passer le mot au sujet de la fête des Brasseurs près des drapeaux à l'extérieur de l'hôtel des ventes dans la Vallée de la Force, dans la Vallée de l'Honneur, dans la Vallée de la Sagesse et dans la Vallée des Esprits."}}
D[11408] = {"Des aboyeurs pour la brasserie vaudou de T'chali !",{"Faites passer le mot au sujet de la fête des Brasseurs près des drapeaux à l'extérieur de l'hôtel des ventes dans la Vallée de la Force, dans la Vallée de l'Honneur, dans la Vallée de la Sagesse et dans la Vallée des Esprits."}}
D[11409] = {"Ça c'est de la course de béliers... enfin, presque.",{"Vous avez quatre minutes pour chevaucher le bélier et maintenir 3 différentes allures pendant 8 secondes chacune."}}
D[11410] = {"Celui qui s'échappa",{"Christopher Sloan, du Fort Hardivar, veut que vous triomphiez de Givraileron."}}
D[11411] = {"Le camp Sabot-d'hiver",{"Parlez au Chef Totem-de-frêne au camp Sabot-d’hiver."}}
D[11412] = {"Histoire d'un aller et retour",{"Obtenez un tonneau auprès du Gobelin coincé sur la route de Tranchecolline, et rapportez-le à l'assistant du Maître des béliers Ray. Faites-le 3 fois avant que votre bélier ne s'en aille."}}
D[11413] = {"Quelqu'un a dit «souvenir»?"}
D[11414] = {"Les frères félons",{"Ulfang vous a demandé de tuer les traîtres worgs, Bjomolf et Varg. Lorsque ce sera fait, retournez le voir, déguisé , à Clivebois.","","Si par hasard vous perdiez le Déguisement de worg, retournez voir la Guetteuse Feuillelune et demandez-lui un autre exemplaire."}}
D[11415] = {"Les frères félons",{"Ulfang vous a demandé de tuer les traîtres worgs, Bjomolf et Varg. Lorsque ce sera fait, retournez le voir, déguisé , à Clivebois.","","Si par hasard vous perdiez le Déguisement de worg, retournez voir le Sage Marche-brume et demandez-lui un autre exemplaire."}}
D[11416] = {"Les yeux de l'aigle",{"Ulfang vous a demandé de récupérer les Yeux de l’Aigle. Lorsque ce sera fait, retournez le voir déguisé à Clivebois.","","Si vous perdez votre Déguisement de worg, allez en demander un autre à la Guetteuse Feuillelune."}}
D[11417] = {"Les yeux de l'aigle",{"Ulfang vous a demandé de récupérer les Yeux de l’Aigle. Lorsque ce sera fait, retournez le voir déguisé à Clivebois.","","Si vous perdez votre Déguisement de worg, allez en demander un autre au Sage Marche-brume."}}
D[11418] = {"On l'appelle Plume-d'acier",{"Trouvez Plume-d’acier, qui tourne autour de Fort Hardivar, et utilisez le Charme orné de plumes pour découvrir son secret. Ensuite, allez faire part de vos découvertes à Gil Grisert."}}
D[11419] = {"Les béliers de la fête des Brasseurs",{"Apportez le tampon de « Brasseur honoraire » à Driz Voltevive, près de l'entrée de la fête des Brasseurs à Durotar."}}
D[11420] = {"La voie de la vengeance",{"Le capitaine de la garde Zorek, à Valgarde dans le Fjord Hurlant, vous demande de récupérer le Manuel d'utilisation du harpon."}}
D[11421] = {"Ça va jusqu'à 11…",{"Le lieutenant Martel-de-glace, dans le Fjord Hurlant, veut que vous détruisiez la Maison longue écorche-dragon, la Maison des quais écorche-dragon, l’Entrepôt et 8 Défenseurs écorche-dragon.","","Rapportez-lui le Mécanisme de commande de harpon quand vous aurez accompli votre mission."}}
D[11422] = {"Le trident du fils",{"Le Vieux Nageglace veut que vous récupériez le Trident de Branchie-pourrie. Lorsque ce sera fait, rapportez-le-lui sur sa petite île, sur la côte de Frissonde."}}
D[11423] = {"L'héritage de l'ennemi",{"Rendez-vous à Nifflevar, au nord du poste de la Lame-fantôme, et cherchez La saga de la malédiction de l’hiver, La saga des Val'kyrs et La saga des jumeaux."}}
D[11424] = {"La colline du Bouclier",{"Jenny « Scie à métaux » vous demande de lui apporter 5 Os de vrykuls anciens des vrykuls réanimés de la Colline du Bouclier, au sud de Nouvelle-Agamand."}}
D[11425] = {"Test Quest - Craig",{"La vermine, faut la bousiller !"}}
D[11426] = {"Localiser le mécanisme",{"Le capitaine de la garde Zorek, à Valgarde dans le Fjord Hurlant, vous demande de lui apporter un Mécanisme de commande de harpon."}}
D[11427] = {"Je vous présente le lieutenant Martel-de-glace…",{"Le capitaine de la garde Zorek vous demande d'apporter le Mécanisme de commande de harpon au Lieutenant Martel-de-glace stationné à l'extérieur de Nifflevar."}}
D[11428] = {"Le gardien Fânefeuille",{"Lurielle de la clairière Gelée veut que vous tuiez le Gardien Fânefeuille."}}
D[11429] = {"Posez, massacrez !",{"Le lieutenant Martel-de-glace, dans le Fjord Hurlant, veut que vous placiez la Bannière de l’Alliance à Torvheim et que vous la défendiez contre les attaquants.","","Revenez ensuite voir le lieutenant Martel-de-glace avec la Bannière de l’Alliance, si vous avez survécu."}}
D[11430] = {"Le maître harponneur Yavus",{"Le lieutenant Martel-de-glace, dans le Fjord Hurlant, vous demande de tuer le Maître harponneur Yavus à Nifflevar."}}
D[11431] = {"Attraper le Wolpertinger sauvage !",{"Le « nain » Charedor Cassebéchasse vous a demandé de capturer 5 Wolpertingers sonnés avec le Filet à wolpertinger. Il a indiqué qu'il fallait être soûl ou porter des Lunettes Synthébière pour les voir."}}
D[11432] = {"Les géants endormis",{"Le Lieutenant-mage Malister veut que vous tuiez 5 Vrykuls dormants. Lorsque ce sera fait, retournez le voir au donjon de la Garde de l’ouest."}}
D[11433] = {"Les géants endormis",{"Ahota Givre-blanc veut que vous tuiez 5 Vrykuls dormants. Lorsque ce sera fait, retournez le voir au Camp Sabot-d’hiver."}}
D[11434] = {"Trésors oubliés",{"Terry le beau gosse, du Cap du Forban, vous demande de lui rapporter un Vase amani et une Figurine d'aigle de l'épave de bateau au sud."}}
D[11436] = {"Et si on faisait du surf",{"Utilisez le grand Lance-harpons vrykul de Nifflevar pour vous lancer dans Valgarde. Informez le Capitaine de la garde Zorek de votre victoire sur les vrykuls."}}
D[11439] = {"Un entraînement de pompier",{"Jetez des seaux d'eau sur 5 feux, puis revenez parler à la Directrice d'orphelinat costumée."}}
D[11440] = {"Un entraînement de pompier",{"Jetez des seaux d'eau sur 5 feux, puis revenez parler à la Directrice d'orphelinat costumée."}}
D[11441] = {"La fête des Brasseurs !",{"Parlez à l'Organisateur de la fête des Brasseurs."}}
D[11442] = {"Bienvenue à la fête des Brasseurs !",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11443] = {"Plongée à Coiffedague",{"Harold Lagras, au fond de la Baie de Coiffedague, veut que vous récupériez 10 Caisses de fournitures de Valgarde."}}
D[11446] = {"La fête des Brasseurs !",{"Parlez à l'Organisateur de la fête des Brasseurs."}}
D[11447] = {"Bienvenue à la fête des Brasseurs !",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11448] = {"L'avant-poste de la Ligue des explorateurs",{"Remettre le Paquet de McSorf à Stanwad, à l’Avant-poste de la Ligue des explorateurs, dans le Fjord Hurlant."}}
D[11449] = {"L'entraînement au combat du feu",{"Jetez des Seaux d’eau sur 5 feux, puis retournez voir la Directrice d'orphelinat masquée à Brill."}}
D[11450] = {"L'entraînement au combat du feu",{"Jetez des Seaux d’eau sur 5 feux, puis retournez voir la Directrice d'orphelinat masquée sur la Place de l'Épervier."}}
D[11451] = {"Le poème d'Alicia",{"Alicia vous a demandé d'apporter son poème à Caylee Dak à Shattrath en Outreterre."}}
D[11452] = {"Le roi endormi",{"Triomphez de la Reine Angrboda et arrêtez le rituel destiné à éveiller le Roi Ymiron. Si vous y parvenez, retournez au Donjon de la Garde de l’ouest et annoncez votre succès au Capitaine Adams."}}
D[11453] = {"Le roi endormi",{"Triomphez de la Reine Angrboda et arrêtez le rituel destiné à éveiller le Roi Ymiron. Si vous y parvenez, retournez au Camp Sabot-d’hiver et annoncez votre succès au Chef Totem-de-frêne."}}
D[11454] = {"Trouver les saboteurs",{"Trouver Coren Navrebière dans le Sinistre écluseur, à l'intérieur des Profondeurs de Rochenoire."}}
D[11455] = {"L'odeur de l'argent",{"Terry le beau gosse, du Cap du Forban, vous demande de lui rapporter 4 échantillons de Musc d'ours prélevés sur les Ours bruns enragés des environs."}}
D[11456] = {"Nourrir les rescapés",{"L’Ancien Atuik, à Kamagua dans le Fjord Hurlant, veut que vous récupériez 6 morceaux de Viande de brochepelle insulaire sur des Brochepelles insulaires de l’Île des Lances."}}
D[11457] = {"Armer Kamagua",{"L’Ancien Atuik veut que vous récupériez 3 Cornes de chimères."}}
D[11458] = {"Venger Iskaal",{"L’Ancien Atuik veut que vous alliez à Iskaal et que vous tuiez 8 Esclavagistes des mers du Nord. En cas de besoin, sonnez du Cor de Kamagua."}}
D[11459] = {"Zeh'gehn li pale",{"Retournez voir Terry le beau gosse pour comprendre ce que vous demande Zeh’gehn."}}
D[11460] = {"La confiance, ça se mérite",{"Hidalgo, de l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous trouviez une Larve du fjord et que vous vous en serviez pour nourrir l’un des éperviers de la cage qui se trouve à ses pieds."}}
D[11461] = {"DEPRECATED"}
D[11464] = {"Une dette de jeu",{"Taruk, au Cap du Forban, veut que vous récupériez la Dette de Harry « Lune-d’argent »."}}
D[11465] = {"La caravane saccagée",{"Hidalgo, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous vous serviez de votre Epervier des rochers apprivoisé pour capturer 5 Dindes du Fjord.","","Lorsque ce sera fait, retournez voir Hidalgo avec la cage."}}
D[11466] = {"Jack aime trop la bouteille",{"Taruk, au Cap du Forban, veut que vous récupériez la Dette de Jack Adams."}}
D[11467] = {"La dette du mort",{"Taruk, au Cap du Forban, veut que vous retrouviez le Trésor de Conrad le Noir, sur le plateau à l'extrémité nord-est de l’Île des Lances, au nord d'Iskaal."}}
D[11468] = {"Faucon contre épervier",{"Hidalgo, de l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez votre Epervier des rochers apprivoisé pour capturer 10 Faucons du Fjord.","","Lorsque ce sera fait, retournez voir Hidalgo avec la cage."}}
D[11469] = {"Le savon à briquer",{"Sabord Givreproue veut que vous récupériez la Graisse de Gros Roy, l’ingrédient principal de son savon à briquer magique. Lorsque vous l’aurez, retournez la voir au vaisseau pirate le plus à l’est du Cap du Forban."}}
D[11470] = {"Les oiseaux n'ont pas d'honneur",{"Hidalgo, de l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez votre Épervier des rochers apprivoisé pour vous emparer de 8 Œufs de faucons du fjord.","","Lorsque ce sera fait, retournez voir Hidalgo avec la cage."}}
D[11471] = {"Le rideau tombe",{"Annie Bonn du Cap du Forban vous demande de lui apporter la Longue-vue de Jonas Sterling."}}
D[11472] = {"Le chemin de son cœur…",{"Lancez de Délicieux poissons des récifs à une Otarie des récifs mâle pour la conduire à une femelle. Lorsque vous aurez aidé ce couple à trouver l’amour, retournez voir Anuniaq à Kamagua."}}
D[11473] = {"Il y a un traître parmi nous",{"Parlez à Zeh’gehn au Cap du Forban."}}
D[11474] = {"Des problèmes au sommet",{"Parlez à Walt."}}
D[11475] = {"Il nous faut des outils pour faire le boulot",{"Walt, de l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous récupériez ses Outils de construction."}}
D[11476] = {"Un coupe-coupe et une coasseuse",{"Procurez-vous un Couteau rutilant auprès de Harry « Lune-d'argent » et capturez une Grenouille des forbans. Apportez tout cela à Zeh'Gehn au Cap du Forban."}}
D[11477] = {"Hors de mon élément ?",{"Donny, aux Ruines d'Ivald dans le Fjord Hurlant, vous demande de tuer 10 Destructeurs Rune-de-fer, 5 Travailleurs Rune-de-fer et 2 Sages Rune-de-fer."}}
D[11478] = {"L'avant-poste par là-bas…",{"Remettez la Lettre de Donny à Stanwad à l'Avant-poste de la Ligue des explorateurs."}}
D[11479] = {"Dan « Patte-de-corbeau »",{"Démasquez Dan « Patte-de-Corbeau », qui se trouve à bord de l’un des navires au Cap du Forban. Lorsque ce sera fait, allez parler à Terry le beau gosse."}}
D[11480] = {"Rencontrer le Numéro Deux",{"Parlez à Annie Bonn, au Cap du Forban."}}
D[11481] = {"Crise au Puits de soleil",{"Adyen le Gardelumière, de l'Éminence de l'Aldor à Shattrath, veut que vous vous rendiez au Plateau du Puits de soleil pour parler à Larethor."}}
D[11482] = {"L'appel du devoir",{"Dathris Heurtesoleil, du Degré des Clairvoyants de Shattrath, insiste pour que vous retourniez immédiatement en Azeroth et que vous vous présentiez à Larethor au Puits de soleil."}}
D[11483] = {"Nous pouvons le reconstruire",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous lui rapportiez un Grand tonneau, de la Corde à usage industriel et des Lingots de sombrefer."}}
D[11484] = {"Nous avons la technologie",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous lui rapportiez une Peau de brochepelle en parfait état et une Armature en acier."}}
D[11485] = {"Les assemblages Rune-de-fer et vous : les fusées de saut",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez les Fusées de saut de l’Assemblage Rune-de-fer avec la Gravure de rune de fer de Walt.","","Quittez votre assemblage en le renvoyant dans la fenêtre du familier, quand vous aurez terminé la quête."}}
D[11486] = {"La meilleure des bières"}
D[11487] = {"La meilleure des bières"}
D[11488] = {"La terrasse des Magistères",{"L'exarque Larethor, de la Zone de rassemblement du Soleil brisé, vous demande d'explorer la Terrasse des magistères à la recherche de Tyrith, un espion elfe de sang."}}
D[11489] = {"Les assemblages Rune-de-fer et vous : le recueil de données",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez le système de Recueil de données de l’Assemblage Rune-de-fer en vous plaçant près de la Relique des nains de fer.","","Quittez votre assemblage en le renvoyant dans la fenêtre du familier, quand vous aurez terminé la quête."}}
D[11490] = {"Clairvoyance pour les Clairvoyants",{"Tyrith veut que vous utilisiez l'orbe sur le balcon de la Terrasse des Magistères."}}
D[11491] = {"Les assemblages Rune-de-fer et vous : le grand bluff",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez le système de Bluff de l’Assemblage Rune-de-fer sur Lebronski quand vous aurez marché sur son tapis.","","Quittez votre assemblage en le renvoyant dans la fenêtre du familier, quand vous aurez terminé la quête."}}
D[11492] = {"L'increvable",{"Kalecgos vous a demandé de vaincre Kael'thas sur la Terrasse des Magistères. Vous devrez ramasser la tête de Kael avant de faire votre rapport à Larethor à la Zone de rassemblement du Soleil brisé."}}
D[11494] = {"La relique imprégnée d'éclair",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez le système de Recueil de données de l’Assemblage Rune-de-fer pour récolter 15 séries de Données Rune-de-fer.","","Quittez votre assemblage en le renvoyant dans la fenêtre du familier, quand vous aurez terminé la quête."}}
D[11495] = {"Le doux son du tonnerre",{"Walt, à l’Avant-poste de la Ligue des explorateurs du Fjord Hurlant, veut que vous utilisiez l’Assemblage Rune-de-fer pour explorer la caverne tonnante, aux Excavations de Baelgun.","","Quittez votre assemblage en le renvoyant dans la fenêtre du familier, quand vous aurez terminé la quête."}}
D[11496] = {"Les protections du sanctum",{"Le Capitaine Theris Âtraurore, de la Zone de rassemblement du Soleil brisé, vous demande de vous procurer 4 Restes de mana sur les Fielleux déshérités et les Dévoreurs déshérités et de vous en servir pour alimenter un des Cristaux de protection qui entoure le Sanctum des Confins du soleil, à l'est."}}
D[11497] = {"Apprendre à voler",{"Parlez à Ilsa Fulminebière au Bastion des Marteaux-hardis dans la Vallée d'Ombrelune."}}
D[11498] = {"Apprendre à voler",{"Parlez à Olrokk au Village d'Ombrelune dans la Vallée d'Ombrelune."}}
D[11499] = {"On recherche : La chevalière du prince Kael'thas",{"Le Marchand des vents Zhareem vous a demandé de vous procurer la Chevalière du prince Kael'thas. Apportez-la-lui à la Ville basse de Shattrath pour recevoir votre récompense.","","Cette quête ne peut être accomplie qu'à la Terrasse des Magistères en mode Héroïque."}}
D[11500] = {"On recherche : Les sœurs du tourment",{"Le Traqueur-du-Néant Mah'duun vous a chargé de tuer 4 Sœurs du tourment. Revenez le voir à la Ville basse de Shattrath lorsque ce sera fait pour recevoir votre prime."}}
D[11501] = {"Des nouvelles de l'est",{"Parler au Capitaine Adams au Donjon de la Garde de l'Ouest."}}
D[11502] = {"La défense de Halaa",{"Vaincre 10 joueurs ennemis à Halaa, puis retourner voir Lakoor à Telaar."}}
D[11503] = {"Ennemis, anciens et nouveaux",{"Abattez 10 joueurs ennemis à Halaa, puis retournez voir Karrtog à Garadar."}}
D[11504] = {"Les morts se lèvent !",{"Orfus de Kamagua, à l'Antique élévateur dans le Fjord Hurlant, veut que vous découvriez l’Indice de Fengir, l’Indice de Rodin, l’Indice d’Isuldof et l’Indice de Windan."}}
D[11505] = {"Les esprits d'Auchindoun",{"Aidez l'Alliance à prendre le contrôle d'une tour dans le désert des Ossements."}}
D[11506] = {"Les esprits d'Auchindoun",{"Aidez la Horde à prendre le contrôle d'une Tour des esprits dans le désert des Ossements."}}
D[11507] = {"L'Ancien Atuik et Kamagua",{"Orfus de Kamagua, dans le Fjord hurlant, vous demande d'apporter le Paquet d'Orfus à l'Ancien Atuik à Kamagua."}}
D[11508] = {"Grezzix Claquefuseau",{"Parlez à Grezzix Claquefuseau."}}
D[11509] = {"Un gars populaire…",{"Parlez à Harry « Lune-d’argent », au Cap du Forban, des artéfacts vrykuls manquants."}}
D[11510] = {"« Scoodles »",{"Harry « Lune-d’argent », au Cap du Forban, veut que vous repreniez son Cristal de divination sin’dorei à l’épaulard « Scoodles »."}}
D[11511] = {"Le bâton de la fureur de l'orage",{"Récupérez le Bâton de la fureur de l’orage et remettez-le à Orfus de Kamagua, dans le Fjord hurlant."}}
D[11512] = {"Le cœur gelé d'Isuldof",{"Récupérez le Cœur gelé d’Isuldof et remettez-le à Orfus de Kamagua dans le Fjord Hurlant."}}
D[11513] = {"Intercepter des cellules de mana",{"Procurez-vous 10 Cellules de mana de contrebande et apportez-les à l'Exarque Nasuun sur la Terrasse de la Lumière à Shattrath."}}
D[11514] = {"Maintenir le portail du Puits de soleil",{"Procurez-vous 10 Cellules de mana de contrebande et apportez-les à l'Exarque Nasuun sur la Terrasse de la Lumière à Shattrath."}}
D[11515] = {"Sang pour sang",{"La Magistrice Seyla, au Trône de Kil'jaeden, vous demande de tuer 4 Gangresangs émaciés en utilisant le gangresiphon sur eux. Vous aurez besoin de sang démoniaque, qui s'obtient sur les Hérauts de courroux des alentours, pour alimenter le siphon."}}
D[11516] = {"Détruire la porte",{"La Magistrice Seyla, au Trône de Kil'jaeden, vous demande d'utiliser les Braises grésillantes pour invoquer une Fusée vivante et de tuer les Gangrétincelles incandescentes près d'elle jusqu'à ce qu'elle devienne une Fusée vivante instable. Retournez à la Porte de la Légion avec la Fusée vivante instable pour la détruire."}}
D[11517] = {"Se présenter à Nasuun",{"Le Commerçant Portonuus veut que vous parliez à l'Exarque Nasuun, à la Terrasse de la Lumière de Shattrath."}}
D[11518] = {"Drapeau quotidien portail puits de soleil"}
D[11519] = {"Le bouclier perdu des Asirites",{"Parlez au Capitaine Ellis à bord du Sœur Miséricorde."}}
D[11520] = {"À la découverte de vos racines",{"Mar'nah, au Port des Confins du soleil, vous demande de vous rendre sur l'Éminence de Tranchépine en Outreterre et de réunir 5 Racines de Tranchépine avant de revenir la voir."}}
D[11521] = {"À la redécouverte de vos racines",{"Mar'nah, du port des Confins du soleil, vous demande de vous rendre sur l'Éminence de Tranchépine en Outreterre et de vous procurer 5 Racines de Tranchépine avant de retourner la voir."}}
D[11523] = {"Armez les protections !",{"Le Capitaine Theris Âtraurore, de la Zone de rassemblement du Soleil brisé, vous demande de vous procurer 4 Restes de mana sur les Fielleux déshérités et les Dévoreurs déshérités et de vous en servir pour alimenter un des Cristaux de protection qui entoure les bâtiments des Confins du soleil."}}
D[11524] = {"Comportement erratique",{"Le redresseur de torts Xayann, de la Zone de rassemblement du Soleil brisé, vous demande de placer les Noyaux cristallins en phase à l'intérieur de 5 Factionnaires erratiques vaincus afin d'en faire des unités alliées."}}
D[11525] = {"Plus de conversions",{"Le redresseur de torts Xayann, de la Zone de rassemblement du Soleil brisé, vous demande de placer les Noyaux cristallins en phase à l'intérieur de 5 Factionnaires erratiques vaincus afin d'en faire des unités alliées."}}
D[11526] = {"La magistrice disparue",{"Servez-vous du Parchemin de la Légion capturé près du portail de la place du Point-du-jour. Lorsque vous aurez franchi le portail, trouvez la magistrice Seyla."}}
D[11527] = {"Les mutins de la Miséricorde",{"Le Capitaine Ellis, à bord du Sœur Miséricorde dans le Fjord Hurlant, vous a demandé de récupérer 5 Tonneaux de poudre d'explosion dans la cale du bateau."}}
D[11528] = {"Un cadeau pour la fête du Voile d'hiver"}
D[11529] = {"Le butin de Sorlof",{"Tuez Sorlof à l'aide du Gros canon et récupérez le Butin de Sorlof. Rapportez le Butin de Sorlof au capitaine Ellis à bord du Sœur Miséricorde."}}
D[11530] = {"Le bouclier des Asirites",{"Rapportez le Bouclier des Asirites à Orfus de Kamagua à l'Antique élévateur dans le Fjord Hurlant."}}
D[11531] = {"Pièce de moteur étrange",{"Apportez la Pièce de moteur étrange à Manue Fretin à Telredor."}}
D[11532] = {"Diversion à la Malebrèche",{"La mage de bataille Arynna vous demande de parler à Ayren Brisenuée quand vous serez prêt à survoler la Malebrèche. Une fois là-bas, utilisez les Charges arcaniques pour tuer 2 Suzerains des abîmes, 3 Ensorceleurs érédars et 12 Massacreurs de courroux."}}
D[11533] = {"Les frappes aériennes doivent continuer",{"La mage de bataille Arynna vous demande de parler à Ayren Brisenuée quand vous serez prêt à survoler la Malebrèche. Une fois là-bas, utilisez les Charges arcaniques pour tuer 2 Suzerains des abîmes, 3 Ensorceleurs érédars et 12 Massacreurs de courroux."}}
D[11534] = {"Se présenter à Nasuun",{"Le Commerçant Portonuus veut que vous parliez à l'Exarque Nasuun, à la Terrasse de la Lumière de Shattrath."}}
D[11535] = {"Préparatifs",{"Le forgeron Hauthaa, de l'armurerie des Confins du soleil, veut que vous tuiez des Myrmidons Sombréchine, à l'est, et que vous utilisiez leurs clés pour dérober trois morceaux de minerai dans leurs coffres."}}
D[11536] = {"Ne vous arrêtez pas...",{"Le forgeron Hauthaa, de l'armurerie des Confins du soleil, veut que vous tuiez des Myrmidons Sombréchine, à l'est, et que vous utilisiez leurs clés pour dérober trois morceaux de minerai dans leurs coffres."}}
D[11537] = {"La bataille doit continuer",{"Le Messager Inuuro vous demande de tuer 6 Démons de la Légion ardente et l'Emissaire de haine sur la place du Point-du-jour. Utilisez la Bannière du Soleil brisé pour empaler le cadavre de l'Emissaire de haine."}}
D[11538] = {"La bataille pour l'Armurerie des Confins du soleil",{"Le Messager Inuuro vous demande de tuer 6 Démons de la Légion ardente et l'Emissaire de haine sur la place du Point-du-jour ou à l'armurerie des Confins du soleil. Utilisez la Bannière du Soleil brisé pour empaler le cadavre de l'Emissaire de haine."}}
D[11539] = {"Prendre le port",{"Le Magistère Ilastar, de l'Armurerie des Confins du soleil, vous demande de tuer 6 Invocateurs de la Lame de l'aube, 6 Chevaliers de sang de la Lame de l'aube et 3 Archers de la Lame de l'aube."}}
D[11540] = {"Écraser la Lame de l'aube",{"Le Magistère Ilastar, de l'Armurerie des Confins du soleil, vous demande de tuer 6 Invocateurs de la Lame de l'aube, 6 Chevaliers de sang de la Lame de l'aube et 3 Archers de la Lame de l'aube."}}
D[11541] = {"Déstabilisation de la Côte de Verte-branchie",{"Le capitaine Valindria vous demande de libérer 10 Esclaves verte-branchie. Retournez la voir au bord de la Fierté de Lune-d'argent au port des Confins du soleil quand ce sera fait."}}
D[11542] = {"Intercepter les renforts",{"Le redresseur de torts Kaalan, de l'Armurerie des Confins du soleil, vous demande de parler à Ayren Brisenuée et de survoler la flotte de renforts de la Lame de l'aube. Utilisez l'Huile enflammée pendant votre vol pour mettre le feu aux voiles des navires, et après avoir atterri, tuez 6 Réservistes de la Lame de l'aube."}}
D[11543] = {"Tenir l'ennemi à distance",{"Le redresseur de torts Kaalan, de l'Armurerie des Confins du soleil, vous demande de parler à Ayren Brisenuée et de survoler la flotte de renforts de la Lame de l'aube. Utilisez l'Huile enflammée pendant votre vol pour mettre le feu aux voiles des navires, et après avoir atterri, tuez 6 Réservistes de la Lame de l'aube."}}
D[11544] = {"Les armes d'Ata'mal",{"Le forgeron Hauthaa vous demande de produire 5 morceaux de Métal ata'mal purifié. Pour ce faire, cassez des Armes d'Ata'mal sur son enclume à l'Armurerie des Confins du soleil sur l'île de Quel'Danas."}}
D[11545] = {"Un don charitable",{"L'Anachorète Ayuri, des Confins du soleil sur l'île du Puits de soleil, vous demande de faire un don de 10 pièces d'or."}}
D[11546] = {"On est ouvert",{"Mar'nah, du port des Confins du soleil, vous demande de cueillir 5 Sangrelles sur les buissons de Quel'Danas."}}
D[11547] = {"Les lignes telluriques et vous",{"L'astromancien Darnarian du Sanctum des Confins du soleil vous demande d'utiliser le Cristal de l'astromancien sur le Cristal-sanglant, le portail de la place du Point-du-jour et le sanctuaire naga de la Côte de Verte-branchie."}}
D[11548] = {"Votre soutien indéfectible",{"L'Anachorète Ayuri, des Confins du soleil sur l'île du Puits de soleil, vous demande de faire un don de 10 pièces d'or."}}
D[11549] = {"Un bienfaiteur magnanime",{"L'anachorète Kairthos vous demande de faire don de 1000 pièces d'or pour soutenir l'action de l'anachorète Ayuri. Vous serez connu sous le nom de Sharmon du Soleil brisé si vous accomplissez cette quête."}}
D[11550] = {"Le Trompeur entre en scène",{"Présentez-vous à l'Archimage Ne'thul sur l'Île de Quel'Danas, au nord de Quel'Thalas.","","Les maîtres de vol de Forgefer et de Lune-d'argent peuvent vous y envoyer."}}
D[11551] = {"Agamath, la première porte"}
D[11552] = {"Rohendor, la deuxième porte"}
D[11553] = {"Archonisus, la dernière porte"}
D[11554] = {"Un ami sur le front"}
D[11555] = {"Honoré par vos alliés"}
D[11556] = {"Révéré sur le champ de bataille"}
D[11557] = {"Exalté parmi tous les combattants"}
D[11558] = {"Les périls de l'amour",{"Obtenez une Carte de garde moisie et rapportez-la à Fenstad Argyle, à Fossoyeuse."}}
D[11559] = {"Commercer avec les Ailerons-d'hiver",{"Ramassez 5 Palourdes aileron-d'hiver et apportez-les à Ahlurglgr à la Retraite des Ailerons-d'hiver."}}
D[11560] = {"Jamais sans mes têtards",{"Le Roi Mrgl-Mrgl vous a demandé de sauver 20 Têtards aileron-d'hiver. Retournez le voir à la Retraite des Ailerons-d'hiver quand ce sera fait."}}
D[11561] = {"Eux !",{"Brglmurgl, de la Retraite des Ailerons-d'hiver, vous a demandé de tuer 15 Murlocs aileron-d'hiver. N'importe quelle combinaison de guerriers, oracles et guerriers des rivages fera l'affaire."}}
D[11562] = {"Mon teinturier est un maître-chanteur",{"Le Roi Mrgl-Mrgl vous a demandé de parler à Mrmrglmr à l'extrémité nord-ouest de la Retraite des Ailerons-d'hiver."}}
D[11563] = {"Grmmurggll Mrllggrl Glrggl !!!",{"Mrmrglmr vous demande de revenir le voir à la Retraite des Ailerons-d'hiver avec la Tête de Glrggl."}}
D[11564] = {"Un ragoût d'épaulard succulent",{"Le Fendeur Bmurglbrm vous a demandé de récupérer 7 Succulentes graisses d'épaulard. Retournez ensuite le voir à la Retraite des Ailerons-d'hiver."}}
D[11565] = {"Le costume de rechange",{"Rapportez son Costume de rechange au Roi Mrgl-Mrgl à la Retraite des Ailerons-d'hiver."}}
D[11566] = {"Reddition... ou pas !",{"Le Roi Mrgl-Mrgl, de la Retraite des Ailerons-d’hiver, vous a demandé de lui rapporter une Pince de Claximus."}}
D[11567] = {"L'antique armure des kvaldirs",{"Récupérez l'Antique armure des kvaldirs et apportez-la à Orfus de Kamagua dans le Fjord Hurlant."}}
D[11568] = {"Le retour à la terre",{"Utilisez le Paquet d'artéfacts vrykuls aux tertres funéraires mis à sac de la Colline du Bouclier pour restituer le Cœur gelé d'Isuldof, le Bouclier des Asirites, le Bâton de la fureur de l'orage et l'Antique armure des kvaldirs.","","Retournez voir Orfus de Kamagua à l'Antique élévateur, si vous réussissez."}}
D[11569] = {"Le maître des clés Urmgrgl",{"Glrglrglr vous a demandé de récupérer la Clé d’Urmgrgl. Lorsque ce sera fait, retournez le voir dans les Cavernes des Ailerons-d’hiver."}}
D[11570] = {"L'évasion des cavernes des Ailerons-d'hiver",{"Escorter Lurgglbr jusqu’à ce qu'il soit en sécurité, puis aller annoncer la bonne nouvelle au Roi Mrgl-Mrgl à la Retraite des Ailerons-d'hiver."}}
D[11571] = {"Apprendre à communiquer",{"Le Roi Mrgl-Mrgl vous a donné une conque à utiliser sur les restes de Brûle-gueule. Rapportez-lui la Conque du roi remplie à la Retraite des Ailerons-d'hiver."}}
D[11572] = {"Retourner voir Atuik",{"Transmettez les mauvaises nouvelles à l’Ancien Atuik à Kamagua."}}
D[11573] = {"Orfus de Kamagua",{"Trouvez Orfus de Kamagua à l'Antique élévateur dans le Fjord Hurlant."}}
D[11574] = {"Un peu trop près à mon goût…",{"Endorah veut que vous alliez à l’Escarpement d’Ambre au nord du Bastion Chanteguerre, et que vous remerciiez ceux qui l’ont sauvée."}}
D[11575] = {"Juste à temps",{"Moucheronne, au Donjon de la Bravoure, veut que vous alliez à l’Escarpement d’Ambre au nord, et que vous remerciiez ceux qui l’ont sauvée."}}
D[11576] = {"Surveiller la faille : l'anomalie de la falaise fendue",{"Garren, de l'Escarpement d'Ambre, vous demande d'utiliser l'Arcanomètre à l'Anomalie de la falaise fendue."}}
D[11577] = {"WoW Collector's Edition: - DEM - E - FLAG"}
D[11578] = {"La quête « Chow » (123)aa",{"Tuer la vermine kobold, au moins 2."}}
D[11579] = {"La quête « Chow » (123)aa COPIE",{"Tuer la vermine kobold, au moins 2."}}
D[11580] = {"Désacralisez ce feu !"}
D[11581] = {"Désacralisez ce feu !"}
D[11582] = {"Surveiller la faille : l'anomalie du gouffre scindé",{"Garren, de l'Escarpement d'Ambre, vous demande d'utiliser l'Arcanomètre à l'Anomalie du Gouffre scindé et de retourner le voir avec les relevés."}}
D[11583] = {"Honorer la flamme"}
D[11584] = {"Honorer la flamme"}
D[11585] = {"La veillée de Hurlenfer",{"Parlez à Garrosh Hurlenfer au Bastion Chanteguerre."}}
D[11586] = {"La veillée de Hurlenfer",{"Parlez à Garrosh Hurlenfer au Bastion Chanteguerre."}}
D[11587] = {"La grande évasion",{"Le Bibliothécaire Donathan de l'Escarpement d'Ambre vous demande de récupérer la Clé de la prison de Béryl sur un Chasseur de mages de Béryl, à la Halte de Béryl, et de vous en servir pour libérer un mage retenu dans une Prison arcanique."}}
D[11590] = {"Enlèvement",{"Donathan veut que vous utilisiez le Lieur d’arcanes sur un Ensorceleur de Béryl blessé, à la Halte de Béryl, et que vous le rameniez à l’Escarpement d’Ambre."}}
D[11591] = {"Se présenter à la caravane de Mâchoire-d'acier",{"Parlez au Grunt Ragepoing à la Caravane de Mâchoire-d'acier."}}
D[11592] = {"Frapper",{"Aidez le Long-coureur Sabot-fier et ses écumeurs chanteguerre à survivre à l'assaut contre la Caravane de Mâchoire-d'acier et à en finir avec l'esprit du commandant de corps Mâchoire-d'acier.","","Si vous réussissez, allez faire votre rapport au Suzerain Bor'gorok à l'Avant-poste de Bor'gorok."}}
D[11593] = {"Les morts honorés",{"Le Grunt Ragepoing, à la Caravane de Mâchoire-d'acier, vous demande d'utiliser sa torche pour brûler un total de 10 Gardes ou Ouvriers morts de la caravane."}}
D[11594] = {"Donnez-leur le repos",{"Détruisez 20 esprits taunkas, qui peuvent être des Sages fantomatiques ou des Long-coureurs ressuscités, puis retournez voir le Grunt Ragepoing à la Caravane de Mâchoire-d'acier."}}
D[11595] = {"La défense du bastion Chanteguerre",{"Présentez-vous au suzerain Razgor, à la hutte du côté sud du Bastion Chanteguerre."}}
D[11596] = {"La défense du bastion Chanteguerre",{"Présentez-vous au suzerain Razgor, à la hutte du côté sud du Bastion Chanteguerre."}}
D[11597] = {"La défense du bastion Chanteguerre",{"Présentez-vous au suzerain Razgor, à la hutte du côté sud du Bastion Chanteguerre."}}
D[11598] = {"Reprendre la carrière de pierres de pouvoir",{"Le suzerain Razgor du Bastion Chanteguerre vous demande de tuer 15 Nérubiens nérub'ar."}}
D[11599] = {"Thassarian, mon frère",{"Partez à la recherche de William Allerton à l'intérieur de la Mine de Comté-lointaine."}}
D[11600] = {"Feu William Allerton",{"Apportez la Carte d'enrôlement à Leryssa au Donjon de la Bravoure, dans la Toundra Boréenne."}}
D[11601] = {"Objets trouvés",{"Parlez à James Lediacre à l’auberge du Donjon de la Bravoure."}}
D[11602] = {"Assécher la source",{"Le suzerain Razgor du Bastion Chanteguerre vous demande de détruire 10 Sacs d'œufs nérub'ar."}}
D[11603] = {"In vino veritas",{"Repêchez une bouteille de Vin de Kul Tiras dans l’épave, au nord-est du Donjon de la Bravoure, et apportez-la au Vieux Colburn à l'auberge du Donjon de la Bravoure."}}
D[11604] = {"Un déserteur",{"Trouvez la prison dans le Bastion intérieur du Donjon de la Bravoure et parlez au déserteur."}}
D[11605] = {"Les ancêtres honorés",{"L'Ancien Atkanok, à l'extérieur de la Carrière de Rochefroide, vous demande d'identifier les statues de l'Ancien Kesuk, l'Ancien Sagani et l'Ancien Takret."}}
D[11606] = {"La patience, une vertu dont nous nous passerons bien",{"L'intendant Holgoth, au Bastion Chanteguerre, vous demande de récupérer 15 caisses de Munitions chanteguerres."}}
D[11607] = {"Les esprits égarés",{"L'Ancien Atkanok, à la lisière de la Carrière de Rochefroide, vous demande de libérer les esprits de 3 Artisans de Kaskala et 3 Chamans de Kaskala."}}
D[11608] = {"Enterrez-moi ces cafards !",{"L'intendant Holgoth, au Bastion chanteguerre, vous demande d'utiliser le Paquet de charges de profondeur à l'hydroglycérine pour détruire les puisards nérub'ar au sud, à l'est, à l'ouest et au nord du Bastion Chanteguerre."}}
D[11609] = {"Ramasser les morceaux",{"Apportez 6 Objets rituels roharts à l'Ancien Atkanok, qui se trouve à l'extérieur de la Carrière de Rochefroide."}}
D[11610] = {"Conduire les ancêtres chez eux",{"L'Ancien Atkanok vous demande de guider les esprits des Anciens Kesuk, Sagani et Takret jusqu'à leurs monuments de pierre respectifs."}}
D[11611] = {"Pris par le Fléau",{"Le Contremaître Mortuus au Bastion Chanteguerre veut que vous libériez 5 Péons chanteguerre."}}
D[11612] = {"Reprendre la carrière",{"Etaruk, qui campe près de l'entrée de la Carrière de Rochefroide, vous demande de tuer 12 Chasseurs de trésor de Béryl."}}
D[11613] = {"Le serment de Karuk",{"Karuk vous demande de tuer 6 Ecumeurs skadir et 5 Skadirs d'équipage."}}
D[11614] = {"Vérités tues",{"Trouvez le Traqueur des ombres Luther dans la Carrière de pierres de pouvoir."}}
D[11615] = {"Les secrets nérub'ar",{"Apportez le Journal de Luther au Traqueur des ombres Barthus au Bastion Chanteguerre."}}
D[11616] = {"Un message pour Hurlenfer",{"Apportez la Note de Barthus à Garrosh Hurlenfer au Bastion Chanteguerre."}}
D[11617] = {"Gênez leur départ",{"Etaruk, à l'extérieur de la Carrière de Rochefroide, vous demande de détruire la Plate-forme nord, la Plate-forme est et la Plate-forme ouest."}}
D[11618] = {"Et voilà les renforts...",{"Allez trouver le Traqueur des ombres Ickoris à l'Avant-poste des fermes chanteguerres, à l'ouest du Bastion Chanteguerre."}}
D[11619] = {"Gamel le Cruel",{"Karuk vous demande de triompher de Gamel le Cruel sur la Grève des Courcinglants."}}
D[11620] = {"Les paroles d'un père",{"Partez à la recherche de Veehja dans le Sanctuaire des Écailles de la Grève des Courcinglants."}}
D[11621] = {"La tablette de Leviroth",{"Retournez voir Karuk avec les informations que vous avez trouvées sur la tablette."}}
D[11622] = {"Les secrets des Courcinglants",{"Trouvez Veehja dans les Ruines des Courcinglants de la toundra Boréenne."}}
D[11623] = {"En visite chez le conservateur",{"Etaruk, à la lisière de la Carrière de Rochefroide, vous demande de tuer le Conservateur Insivius."}}
D[11624] = {"Le ciel saura",{"Allez voir Impéréen dans les Ruines d'Eldra'nath."}}
D[11625] = {"Le trident de Naz'jan",{"Veehja, aux Courcinglants, vous demande d'aller à l'extrémité nord-est des ruines des Courcinglants. Une fois là-bas, tuez Ragnar Drakkarlund et prenez-lui le Trident de Naz'jan."}}
D[11626] = {"L'émissaire",{"Trouvez Leviroth sous l'iceberg flottant, le long de l'extrémité nord des Ruines des Courcinglants. Utilisez le Trident de Naz'jan pour le tuer, puis retournez voir Karuk au nord de la Grève des Courcinglants."}}
D[11627] = {"Le point d'ébullition",{"Impéréen vous demande de faire entendre raison à Frémiss et Bouillonn. Retournez la voir aux Ruines d'Eldra'nath quand ils auront plié."}}
D[11628] = {"Le voile du Fléau",{"Le Chef Trombe-de-l'hiver à Taunka'le veut que vous lui apportiez 5 Fourrures de mammouths flaellés."}}
D[11629] = {"Retourner voir la spirite",{"Apportez la Prime-essence d'Impéréen à la Spirite Grognecroc, à l'Avant-poste de Bor'gorok."}}
D[11630] = {"La mauvaise terre",{"Rapportez 8 mottes de Terre flaellée au Chef Trombe-de-l'hiver à Taunka'le."}}
D[11631] = {"Vision de l'Air",{"Utilisez la Prime-essence d'Impéréen pour accomplir un rituel devant le Totem de Grognecroc, à l'Avant-poste de Bor'gorok, afin de découvrir des informations sur le Long-voyant Marche-sinistre.","","Ensuite, allez parler à la Spirite Grognecroc."}}
D[11632] = {"Ce qu'apporte le vent froid…",{"Apportez la Carapace durcie d'Ith'rix au Haut seigneur Saurcroc au Bastion Chanteguerre."}}
D[11633] = {"Se fondre dans le paysage",{"Le Chef Trombe-de-l'hiver à Taunka'le veut que vous portiez le Voile du Fléau imprégné dans la Ville-temple d’En’kilah, et que vous alliez explorer la Flèche du Sang, la Flèche de la Douleur et la Flèche de la Décomposition."}}
D[11634] = {"Le maître du vent To'bor",{"Présentez-vous au Maître du vent To'bor au Bastion Chanteguerre."}}
D[11635] = {"L'esprit du long-voyant Marche-sinistre",{"Parlez à l’Esprit du long-voyant Marche-sinistre, à l’intérieur de Magmoth."}}
D[11636] = {"Un tour en tapis volant",{"Parlez à Yanni au Bastion Chanteguerre pour organiser votre voyage jusqu’à la côte. Une fois au Point d’accostage de Garrosh, trouvez l’annihilateur Grek’lor."}}
D[11637] = {"Kaganishu",{"Retrouvez le Fétiche de Kaganishu et utilisez-le près des Restes du long-voyant Marche-sinistre.","","Vous devrez donner le fétiche à l’Esprit du long-voyant Marche-sinistre dans Magmoth."}}
D[11638] = {"Rapatrier mes restes",{"Remettez les Restes du long-voyant Marche-sinistre, qui reposent en dessous de son esprit, à la Spirite Grognecroc, à l’Avant-poste de Bor’gorok."}}
D[11639] = {"La vengeance s'abat sur Magmoth",{"Tuez 10 Chamans de Magmoth, 5 Fourrageurs de Magmoth, 3 Écraseurs de Magmoth et 3 Compagnes de Magmothregar. Lorsque ce sera fait, retournez voir Ortrosh à l’Avant-poste de Bor’gorok."}}
D[11640] = {"Les mots de puissance",{"Apportez le Parchemin du grand prêtre Naferset, le Parchemin du grand prêtre Talet-Kha et le Parchemin du grand prêtre Andorath au Chef Trombe-de-l'hiver à Taunka'le."}}
D[11641] = {"Une frappe courageuse",{"Tuez 15 Goules d’En’kilah et 5 Nécromanciens d’En’kilah, puis allez faire votre rapport à Durm Cuir-de-glace à Taunka’le."}}
D[11642] = {"Un char, ça s'répare pas tout seul",{"Parlez à Mobu au Point d'accostage de Garrosh."}}
D[11643] = {"Le transbidulotron pneumatique pour char de Mobu",{"Mobu, sur la Côte des Échos dans la Toundra Boréenne veut que vous récupériez son Transbidulotron pneumatique pour char."}}
D[11644] = {"Des plaques de métal ultra-résistantes !",{"Mobu, sur la Côte des Échos dans la Toundra Boréenne veut que vous récupériez 10 Plaques de métal ultra-résistantes."}}
D[11645] = {"Stupides frigbolds joufflus !",{"Récupérez 10 boîtes de Matériel de Fufute et rapportez-les à Fufute Tremblerouage sur la Piste d'atterrissage de Spumelevier."}}
D[11646] = {"L'inquisition boréenne",{"Donathan vous a ordonné de proposer votre aide au Bibliothécaire Normantis dans la tour des mages de l'Escarpement d'Ambre."}}
D[11647] = {"Neutraliser les chaudrons",{"La Sage Aeire de Taunka'le vous demande d'utiliser son totem pour neutraliser le Chaudron de l'est, le Chaudron central et le Chaudron de l'ouest dans la Ville-temple d'En'kilah."}}
D[11648] = {"L'art de la persuasion",{"Le Bibliothécaire Normantis de l'Escarpement d'Ambre vous demande d'utiliser l'Aiguillonneur neural sur l'Ensorceleur de Béryl emprisonné jusqu'à ce qu'il révèle où se trouve dame Evanor."}}
D[11649] = {"Granules des enragés",{"Rassemblez 5 Granules de tempête et rapportez-les à Impéréen aux Ruines d'Eldra'nath."}}
D[11650] = {"Encore quelques bricoles…",{"Récupérez les Outils de Fufute, un Condensateur surchargé et une Poignée de sable de Rocnar. Apportez-les à Fufute Tremblerouage à la Piste d'atterrissage de Spumelevier."}}
D[11651] = {"Le char l'attend",{"Parlez à l’Annihilateur Grek’lor sur la Côte des Échos."}}
D[11652] = {"Les plaines de Nasam",{"Utilisez le Char de siège de la Horde pour détruire 100 Soldats du Fléau et secourir 3 Soldats chanteguerre blessés, sur les Plaines de Nasam. Vous devez aussi découvrir l’identité du chef de l’attaque du Fléau.","","Allez ensuite faire votre rapport à Garrosh Hurlenfer au Bastion Chanteguerre si vous réussissez."}}
D[11653] = {"Ha ! Z'êtes plus si grands que ça maintenant !",{"Testez la Pétoire Raccourcissante Proto-Typique Ultra-Avancée de Fufute sur 5 Écraseurs de Magmoth ou Compagnes de Magmothregar. Quand ce sera fait, retournez voir cette dernière à la Piste d'atterrissage de Spumelevier."}}
D[11654] = {"La flèche du Sang",{"Fouillez la Flèche du Sang à la recherche d'informations sur la Fiole de sang frais."}}
D[11655] = {"Dans la brume",{"Waltor, de Pal'ea sur la Côte des Échos dans la Toundra Boréenne, vous demande de tuer des kvaldirs pour récupérer 8 Reliques roharts."}}
D[11656] = {"Brûler en effigie",{"Waltor de Pal’ea, sur la Côte des Échos de la Toundra Boréenne, veut que vous utilisiez la Torche rohart pour brûler les vaisseaux kvaldirs à Pal’ea et au Point d'accostage de Garrosh. Vous devez détruire les vaisseaux suivants : La Gueule du serpent, Le Drakkar de Kur, Le Marteau de Bor et L’Enclume de Bor."}}
D[11657] = {"Attraper des torches",{"Attrapez 4 torches de suite, puis parlez au Maître mangeur de feu."}}
D[11658] = {"Plan B",{"Rapportez 10 Tenues chanteguerres et une Bannière chanteguerre à Fufute Tremblerouage à la Piste d'atterrissage de Spumelevier."}}
D[11659] = {"Brisez les orbes !",{"Détruisez 5 Globes de sang et allez avertir le Pisteur des neiges Junek à Taunka'le."}}
D[11660] = {"Le cor du vieux marinier",{"Waltor, de Pal'ea sur la Côte des Échos dans la Toundra Boréenne, vous demande de lui apporter le Cor du vieux marinier."}}
D[11661] = {"Orabus le Timonier",{"Waltor de Pal’ea, sur la Côte des échos, dans la Toundra Boréenne, veut que vous utilisiez le Cor du vieux marinier, pour appeler Orabus le Timonier. Quand vous l’aurez appelé, tuez-le."}}
D[11662] = {"Allez trouver Karuk !",{"Allez trouver Karuk sur la Grève des Courcinglants."}}
D[11663] = {"Rapporter les informations",{"Normantis vous a demandé de vous présenter au Bibliothécaire Donathan à l'Escarpement d'Ambre."}}
D[11664] = {"S'échapper de la brume",{"Suivez Meuhtou la Jeune hors de la brume. Parlez à l'Ancien Meuhtou si vous parvenez à sauver Meuhtou la Jeune."}}
D[11665] = {"Les crocilisques sont lâchés",{"Apportez un Bébé crocilisque au vieux Barlo. Vous le trouverez en train de pêcher au nord-est de Shattrath, au bord du lac Silmyr."}}
D[11666] = {"Succomber à vos appâts",{"Apportez un Dard aileron-noir au vieux Barlo. Vous le trouverez en train de pêcher au nord-est de Shattrath, au bord du lac Silmyr."}}
D[11667] = {"Celui qui s'échappa",{"Attrapez le Plus grand éperlan du monde et apportez-le au Vieux Barlo. Vous le trouverez en train de pêcher au nord-est de Shattrath au bord du lac Silmyr."}}
D[11668] = {"Les crevettes, c'est pas pour les mauviettes",{"Le Vieux Barlo veut 10 Crevettes géantes d'eau douce. Vous pouvez le trouver au nord-est de Shattrath, près du lac Silmyr."}}
D[11669] = {"Filet de gangresang",{"Apportez un Lutjan gangresang monstrueux au Vieux Barlo. Vous le trouverez en train de pêcher au nord-est de Shattrath, au bord du lac Silmyr."}}
D[11670] = {"C'était les orcs, j'vous jure !",{"Plantez la Bannière chanteguerre dans le cadavre de Magmothregar en portant le Déguisement d'orc chanteguerre. Puis rapportez le déguisement à Fufute Tremblerouage à la Piste d'atterrissage de Spumelevier."}}
D[11671] = {"Une course contre la montre",{"Donathan de l'Escarpement d'Ambre vous a chargé d'utiliser le Détonateur contre le bouclier de Béryl afin d'abattre le bouclier à la Halte de Béryl. Vous devez ensuite vaincre Salrand et prendre la clé qu'elle détient."}}
D[11672] = {"Le jour de l'incorporation",{"Rencontrez le Général Arlos à l'intérieur de la caserne du donjon de la Bravoure."}}
D[11673] = {"Sortez-moi de là !",{"Escortez Bonker Virevolt jusqu'en lieu sûr puis présentez-vous à Spumelevier Pleingaz à la Piste d'atterrissage de Spumelevier."}}
D[11674] = {"La sage Haute-mesa a disparu",{"Trouver la Sage Haute-mesa près des Tanières du Trépas."}}
D[11675] = {"Une mort décente",{"Détruisez 10 Magnataures pestiférés puis retournez voir la Sage Haute-mesa au sud des Tanières du Trépas."}}
D[11676] = {"Le cadeau de la liberté",{"Le traqueur des ombres Canarius, à l'Avant-poste des fermes chanteguerres, vous demande de libérer 5 Prisonniers du Fléau."}}
D[11677] = {"Mettre fin à la peste",{"La Sage Haute-mesa, qui se trouve juste au sud des tanières du Trépas, vous a demandé d'utiliser les Graines purificatrices de Haute-mesa à un Chaudron de peste des tanières du Trépas, afin de le neutraliser."}}
D[11678] = {"Trouvez Corne-dressée",{"Trouvez le Long-coureur Corne-dressée à Talramas."}}
D[11679] = {"Reforger la clé",{"Donathan veut que vous parliez à Surristrasz sur l'Escarpement d'Ambre."}}
D[11680] = {"L'envol",{"Lorsque vous serez prêt à libérer Evanor, donnez la Clé de Salrand au Mage de guerre Anzim."}}
D[11681] = {"Au secours d'Evanor",{"Anzim, de l'Escarpement d'Ambre, vous demande de vous envoler avec ses mages de guerre pour libérer dame Evanor à la Halte de Béryl. Vous devrez ensuite lui faire votre rapport dans la tour des mages de l'Escarpement d'Ambre."}}
D[11682] = {"Jargon & dragons",{"Dame Evanor vous a envoyé parler à Surristrasz sur l'Escarpement d'Ambre."}}
D[11683] = {"La nécropole écrasée",{"Détruisez 20 créatures du Fléau de n’importe quel type à Talramas et dans les Bassins Purulents. Lorsque ce sera fait, retournez voir la Sage Haute-mesa, juste au sud des Tanières du Trépas."}}
D[11684] = {"Reconnaissance des puisards",{"Grandpère Mahan, à Taunka'le, vous demande d'utiliser la Carte des champs de Geysers afin d'y écrire l'emplacement du Puisard sud, du Puisard nord-ouest et du Puisard nord-est."}}
D[11685] = {"Le cœur des éléments",{"Apportez 5 Cœurs élémentaires à la Dompteuse des vents Barah à Taunka'le."}}
D[11686] = {"Les fermes chanteguerre",{"Le traqueur des ombres Ickoris, à l'Avant-poste des fermes chanteguerres, vous demande d'explorer le Grenier chanteguerre, la Ferme de Torp et l'Abattoir chanteguerre."}}
D[11687] = {"Le docteur et le seigneur-liche",{"Détruisez le Docteur Trancherictus et le Seigneur-liche Frisshiver. Puis retournez voir la Sage Haute-mesa juste au sud des Tanières du Trépas."}}
D[11688] = {"Saleté de cochonnerie de pourceaux",{"Le fermier Torp, à l’Avant-poste des fermes chanteguerres, veut que vous tuiez 10 Pourceaux non-vivants."}}
D[11689] = {"Transmettre les mauvaises nouvelles",{"Parlez à la Grande-mère Taiga à Taunka'le."}}
D[11690] = {"Ram'nez-les vivants",{"Le fermier Torp, à l’Avant-poste des fermes chanteguerres, veut que vous sauviez 8 Kodos infectés."}}
D[11691] = {"L'invocation d'Ahune",{"Apportez le Totem de magma du Cercle terrestre à la Pierre de glace."}}
D[11692] = {"Allez voir Bixie",{"Mordle Tournepignon vous a demandé de trouver Bixie Tournechancre au sud des Tanières du Trépas."}}
D[11693] = {"Super… des magnataures pestiférés !",{"Tuez 10 Magnataures pestiférés puis retournez voir Bixie Tournechancre au sud des Tanières du Trépas."}}
D[11694] = {"Il se passe quelque chose dans ces grottes",{"Bixie Tournechancre, qui se planque au sud des Tanières du Trépas, veut que vous utilisiez la Poudre inhibitrice de Bixie sur un Chaudron de peste des Tanières du Trépas, afin de le neutraliser."}}
D[11695] = {"Le cor de fureur élémentaire",{"Reprenez la Moitié inférieure du cor et la Moitié supérieure du cor au Chef Brouillegargouille et au Chef Grouillebarbouille et apportez-les à la Dompteuse des vents Barah à Taunka'le."}}
D[11696] = {"Ahune est là !",{"Trouvez Luma Mère-des-cieux dans les Enclos aux esclaves."}}
D[11697] = {"Zut, Bricole est entrée dans la nécropole !",{"Trouvez Bricole Sifflemèche à Talramas."}}
D[11698] = {"On pourrait aussi bien éradiquer le Fléau",{"Détruisez 20 créatures du Fléau de n'importe quel type à Talramas et aux Bassins Purulents. Puis retournez voir Bixie Tournechancre juste au sud des Tanières du Trépas."}}
D[11699] = {"Je suis coincée dans cette maudite cage… mais pas pour longtemps !",{"Récupérez un Cristal du bloc-moteur, un Gyroscope magique et une Pierre du Fléau de pilotage, et remettez-les à Bricole Sifflemèche, à Talramas."}}
D[11700] = {"Prévenez Bixie",{"Parlez à Bixie Tournechancre juste au sud des Tanières du Trépas."}}
D[11701] = {"Retour à la piste d'atterrissage",{"Parlez à Spumelevier Pleingaz sur la Piste d'atterrissage de Spumelevier, dans la Toundra Boréenne."}}
D[11702] = {"Le roi Mrgl-Mrgl",{"Allez voir le Roi Mrgl-Mrgl à la Retraite des Ailerons-d'hiver."}}
D[11703] = {"Rallier Getry",{"Allez voir le Traqueur des ombres Getry aux Fermes chanteguerre."}}
D[11704] = {"Le roi Mrgl-Mrgl",{"Parlez au Roi Mrgl-Mrgl à la Retraite des Ailerons-d'hiver."}}
D[11705] = {"Opération absurde",{"Aidez Getry à vaincre Varidus le Dépiauteur aux Fermes chanteguerre.","","Faites votre rapport à Garrosh Hurlenfer si vous deviez réussir."}}
D[11706] = {"L'effondrement",{"La Dompteuse des vents Barah, de Taunka'le, vous demande de faire s'effondrer les puisards nérubiens à l'aide du Cor de fureur élémentaire et de vaincre le seigneur Kryxix."}}
D[11707] = {"Appel de détresse",{"Allez voir Spumelevier Pleingaz à la Piste d'atterrissage de Spumelevier."}}
D[11708] = {"Les mécagnomes",{"Écoutez l'histoire de Spumelevier Pleingaz puis allez voir Voltij Lazimuté à la Piste d'atterrissage de Spumelevier."}}
D[11709] = {"La charge de Nork Frénésie-sanglante",{"Parlez au Gardien Nork Frénésie-sanglante au Bastion Chanteguerre, dans la Toundra Boréenne."}}
D[11710] = {"Transmatière à rire",{"Ramassez 15 Pièces détachées de Spumelevier et rapportez-les à Mordle Tournepignon à la Piste d'atterrissage de Spumelevier."}}
D[11711] = {"Livraison de lâche… En moins de 30 minutes, ou c'est gratuit",{"Emmenez le Déserteur de l'Alliance à la croisée des chemins à l'est du Bastion Chanteguerre puis utilisez le Lance-fusée chanteguerre pour envoyer un signal à l'Alliance.","","Allez rendre compte à l'Éclaireur Tungok une fois que le Déserteur de l'Alliance sera bien arrivé."}}
D[11712] = {"Le re-maudisseur",{"Voltij Lazimuté, à la Piste d'atterrissage de Spumelevier, vous a demandé d'utiliser l'Injecteur transmatière re-maudisseur sur 6 Mécagnomes de Spumelevier."}}
D[11713] = {"Reconnaissance des puisards",{"Abner Patranivelle, à la Piste d’atterrissage de Spumelevier, vous demande d'utiliser la Carte des champs de Geysers afin d'y marquer l'emplacement du Puisard sud, du Puisard nord-ouest et du Puisard nord-est."}}
D[11714] = {"Extermination de la vermine",{"L'éclaireur Tungok, aux Plaines de Spore-sang dans la Toundra Boréenne, vous a demandé de tuer 8 Moissonneurs spore-sang, 5 Boute-flammes spore-sang et 2 Rôtisseurs spore-sang."}}
D[11715] = {"Faire carburer le projet",{"Abner Patranivelle, à la Piste d’atterrissage de Spumelevier, vous demande de récupérer 8 tonneaux de Naphte à l'aide du Collecteur de naphte portable."}}
D[11716] = {"Spore-sang merveilleuse !",{"La Mage de sang Laurith, des Plaines de Spore-sang dans la Toundra Boréenne, vous a demandé de récupérer 10 Carpelles spore-sang."}}
D[11717] = {"Le pollen à sa source",{"La Mage de sang Laurith, des Plaines de Spore-sang dans la Toundra Boréenne, vous a demandé de récupérer 5 échantillons de Pollen de phalène spore-sang."}}
D[11718] = {"L'habit fera le mammouth",{"Abner Patranivelle, à la Piste d’atterrissage de Spumelevier, veut que vous lui rapportiez 6 Peaux de mammouth épaisses."}}
D[11719] = {"Un cobaye adéquat",{"La Mage de sang Laurith, des Plaines de Spore-sang dans la Toundra Boréenne, vous a demandé d’utiliser la Fleur de spore-sang pollinisée et de la laisser examiner le résultat."}}
D[11720] = {"L'invasion de Gammoth",{"Parlez à l'Aîné Corne-de-pouvoir dans les Plaines de Spore-sang, dans la Toundra Boréenne"}}
D[11721] = {"Gammothra le Tourmenteur",{"Tuez Gammothra et rapportez la Tête de Gammothra à l'Aîné Corne-de-pouvoir dans les Plaines de Spore-sang, dans la Toundra Boréenne."}}
D[11722] = {"Les trophés de Gammoth",{"Apportez la Tête de Gammothra à Garrosh Hurlenfer au Bastion Chanteguerre."}}
D[11723] = {"Déployez le Sismo-trembleur !",{"Abner Patranivelle, à la Piste d’atterrissage de Spumelevier, vous demande d'utiliser le Sismo-trembleur 5000 pour faire s'effondrer les tunnels nérubiens et de vaincre le Seigneur Kryxix."}}
D[11724] = {"Une gigantesque omelette de phalènes ?",{"Apportez l'Oeuf massif luminescent à la Mage de sang Laurith dans les Plaines de Spore-sang, dans la Toundra Boréenne."}}
D[11725] = {"Trouver le pilote la Vrille",{"Trouvez Iggy \"la Vrille\" Virouage dans les champs de Geysers."}}
D[11726] = {"Un peu de piquant",{"Iggy \"la Vrille\" Virouage, dans les Bassins Brûlants, vous demande de ramasser 4 Bourses d'épices de Gorloc."}}
D[11727] = {"L'époque est aux héros",{"Présentez-vous au Sergent Martèlemont au Donjon de la Bravoure."}}
D[11728] = {"Lupus Pupus",{"Iggy \"la Vrille\" Virouage, dans les Bassins Brûlants, vous demande de lui apporter 8 morceaux de Microfilm."}}
D[11729] = {"Le Tournevis Ultrasonique",{"Apportez le Tournevis Ultrasonique à Fufute Tremblerouage à la Piste d'atterrissage de Spumelevier."}}
D[11730] = {"Maître et serviteur",{"Utilisez le Tournevis ultrasonique pour reprogrammer 15 robots, puis retournez voir Fufute Tremblerouage à la Piste d'atterrissage de Spumelevier.","","N'oubliez pas de prendre votre butin sur le robot avant de le reprogrammer."}}
D[11731] = {"Lancer des torches",{"Gagnez le jeu de lancer de torches, puis parlez au Maître mangeur de feu."}}
D[11732] = {"Désacralisez ce feu !"}
D[11733] = {"Traverser la faille",{"Surristrasz vous demande de partir pour Frimarra. Une fois là-bas, parlez à l'Archimage Bérinand."}}
