D[12773] = {"Darnassus"}
D[12774] = {"Hurlevent"}
D[12775] = {"Une alliance désespérée"}
D[12776] = {"L'Exodar"}
D[12777] = {"Une alliance désespérée"}
D[12778] = {"L'apocalypse écarlate",{"Cherchez le Roi-liche à Brèche-de-Mort."}}
D[12779] = {"La fin de toutes choses…",{"Le Roi-liche vous a ordonné d'éradiquer la Croisade écarlate.","","Utilisez le Cor des Couvegivres pour invoquer un Vainqueur couvegivre. Avec son aide, tuez 150 Soldats écarlates et détruisez 10 Balistes écarlates. Évitez les projectiles en sortant de leur ligne de tir !"}}
D[12780] = {"PÉRIMÉ>>L'ennemi de notre ennemi",{"Le Sergent Riannah à la Brèche de Lumière veut que vous parliez à Stefan au Guet d'Ébène et que vous lui offriez votre aide."}}
D[12781] = {"Bienvenue !",{"Apportez le Bon-cadeau du Fort d'Ébène à Siouxsie la banshee au Fort d'Ébène."}}
D[12782] = {"Recherche désespérée"}
D[12783] = {"Recherche désespérée"}
D[12784] = {"Recherche désespérée"}
D[12785] = {"Orgrimmar"}
D[12786] = {"Les Pitons-du-Tonnerre"}
D[12787] = {"Fossoyeuse"}
D[12788] = {"Lune-d’Argent"}
D[12789] = {"Dans la brèche !",{"Le Croisé Valus de la Confiance de Lumière veut que vous vous présentiez auprès du Sergent Riannah à la Brèche de Lumière, dans Zul'Drak."}}
D[12790] = {"Apprendre à partir et revenir : le chemin magique",{"L'Archimage Célindra à la Porte Pourpre à Dalaran vous a demandé d'utiliser le Téléporteur vers le Cristal du Séjour pourpre et le Téléporteur vers le Cristal de Dalaran."}}
D[12791] = {"Le royaume magique de Dalaran",{"Donnez la Chevalière du Kirin Tor à l'Archimage Célindra à la Porte Pourpre à Dalaran."}}
D[12792] = {"Chaque chose en son temps",{"Le Commandant Kunz au Séjour d'Argent vous a demandé d'aller rejoindre le Sergent Riannah à la Brèche de Lumière."}}
D[12793] = {"De la fumée à l'horizon",{"Khufu, dans Zim'Torga, veut que vous vous rendiez à la Brèche de Lumière et que vous vous présentiez au Sergent Riannah.","","Maaka vous fournira le transport."}}
D[12794] = {"Le royaume magique de Dalaran",{"Donnez la Chevalière du Kirin Tor à l'Archimage Célindra à la Porte Pourpre à Dalaran."}}
D[12795] = {"Passons au séjour",{"Datura Rose-sang au Guet d'Ébène veut que vous alliez parler au Commandant Falstaav au Séjour d'Argent."}}
D[12796] = {"Le royaume magique de Dalaran",{"Donnez la Chevalière du Kirin Tor à l'Archimage Célindra à la Porte Pourpre à Dalaran."}}
D[12797] = {"Retour par le portail d'accès",{"Apportez la Rune Oméga à l'Avatar de Freya aux Rapides Parlepluie, dans le Bassin de Sholazar."}}
D[12798] = {"Suite d'Épées",{"Utilisez la Suite d'Épées pour invoquer une Diseuse de bonne aventure de la foire de Sombrelune et donnez-lui la suite."}}
D[12799] = {"Récupération d'esprits",{"Le Capitaine Arnath à Heb'Valok vous demande de récupérer 5 Ectoplasmes anciens d'Esprits drakkari égarés aux Bassins de Zha'Jin."}}
D[12800] = {"Le dernier ordre du roi-liche",{"Faites votre rapport au Commandant du Fléau Thalanor à la Scierie de Browman."}}
D[12801] = {"La Lumière de l'Aube",{"Battez les forces de l'Aube d'argent et découvrez la Lumière de l'Aube.","","Si vous survivez, faites votre rapport au Généralissime Darion Mograine."}}
D[12802] = {"Mon cœur est entre tes mains",{"Drakuru vous a demandé de lui rapporter le Cœur des anciens au Passage de Drak'atal.","","Vous allez devoir récupérer 5 Mojos désespérés pour utiliser l'élixir sur place."}}
D[12803] = {"Une force de la nature",{"Rendez-vous à la Ligne de la désolation, entre les Rapides Parlepluie et les Terres Perdues du Bassin de Sholazar, et cherchez l'Avatar de Freya."}}
D[12804] = {"Un steak digne d'un chasseur",{"Apportez 5 Steaks de Longs-cous à Korg le Fendeur, au Camp de base de Nesingwary."}}
D[12805] = {"La préservation de la force vitale",{"L'Avatar de Freya veut que vous alliez à l'Éclat scindé au sud-est, et que vous utilisiez la Gemme de force vitale sur 8 Élémentaires sang-de-vie détruits."}}
D[12806] = {"Se lever en toute hâte !",{"Faites votre rapport au Seigneur-commandant Arete à la Cime de la Mort, dans la Couronne de glace."}}
D[12807] = {"Résumé des épisodes précédents…",{"Écoutez l'histoire du Seigneur-commandant Arete à la Cime de la Mort."}}
D[12808] = {"Une alliance désespérée"}
D[12809] = {"Forgefer"}
D[12810] = {"Du sang dans l'eau",{"Le Seigneur-commandant Arete, à la Cime de la Mort,vous a demandé de remplir la Vessie de sang avec le sang de 10 Dents voraces de la mer."}}
D[12811] = {"Recherche désespérée"}
D[12812] = {"Orgrimmar"}
D[12813] = {"Réanimez leurs cadavres !",{"Setaal Soignobscur à la Cime de la Mort vous a donné la Teinture du sombre réparateur. Appliquez-la sur les cadavres de 10 unités de l'Assaut écarlate trouvées au Port de l'Assaut."}}
D[12814] = {"Vous aurez besoin d'un griffon",{"Amenez un Griffon de l'Assaut à Uzo Mandemort à la Cime de la Mort."}}
D[12815] = {"Zone d'exclusion aérienne",{"Uzo Mandemort, à la Cime de la Mort, vous demande de tuer 10 Chevaucheurs de griffons de l'Assaut."}}
D[12816] = {"Enquêter au sujet du Fléau à Lune-d'argent",{"Récupérez 3 Pierres nécrotiques pâles du Fléau à l'extérieur de Lune-d'argent et enquêtez à propos des Cercles runiques brillants près de leur campement."}}
D[12817] = {"Enquêter au sujet du Fléau à l'Exodar",{"Récupérez 3 Pierres nécrotiques pâles sur les membres du Fléau à l'extérieur de l’Exodar et enquêtez sur les Cercles runiques brillants près de leur campement. Puis retournez voir le Lieutenant Kregor."}}
D[12818] = {"Nettoyage",{"Gouaille Grilledouille à K3 vous a demandé 10 morceaux de Débris calcinés."}}
D[12819] = {"Juste à côté",{"Gouaille Grilledouille, à K3, aimerait récupérer ses Outils de Grilledouille oubliés dans son champ de mines."}}
D[12820] = {"Une délicate attention",{"Ricket, à K3, veut que vous utilisiez les Mines améliorées à Plaie-de-Garm pour repousser 12 Attaquants de Garm. Les Envahisseurs de Garm et les Suivants Brûleglace comptent comme attaquants."}}
D[12821] = {"Le tango du pénitencier",{"Ricket à K3 voudrait que vous localisiez la Batterie de télétransporteur et que vous l'utilisiez pour activer la Plate-forme de téléportation à la Cime de Garm."}}
D[12822] = {"N'ayez pas peur",{"Ricket à K3 vous demande de tuer 6 Guetteurs de Garm et 8 Fidèles brûleglace."}}
D[12823] = {"Un plan sans accroc",{"Gino à la Cime de Garm vous a demandé de placer le Paquet d'explosifs durcis près de l'Autel de Givrebide, de tuer Tormar Givrebide puis de vous échapper avant que la caverne ne s'effondre sur vous."}}
D[12824] = {"Artificier extraordinaire",{"Retournez voir Ricket à K3."}}
D[12825] = {"Une preuve de gratitude",{"[PLACEHOLDER] Utilisez les mini avions pour jouer les kamikazes sur le chef gnoll."}}
D[12826] = {"Légèrement instable",{"Apportez les Mines améliorées de Gouaille à Ricket à K3."}}
D[12827] = {"Vol de rations",{"Ricket à K3 vous demande de récupérer 16 Rations gnolles séchées sur les Gnolls de la colline Sauvage, qui se trouvent non loin."}}
D[12828] = {"Une grande inspiration",{"Ricket, à K3, veut que vous récupériez un T.E.M.O.R. Utilisez-le pour faire sauter un mammouth et récupérez 8 Viandes de mammouth copieuses."}}
D[12829] = {"Installation",{"Tore Grondelevier à l'extérieur de la Caverne de la Toile cristalline vous a demandé de tuer 12 Araignées de la Toile cristalline."}}
D[12830] = {"Récupération de minerai",{"Tore Grondelevier à l'extérieur de la Caverne de la Toile cristalline vous a demandé de récupérer 5 échantillons de Minerai de saronite impur."}}
D[12831] = {"Seulement à moitié oublié",{"Un Mineur gobelin blessé à la Caverne de la Toile cristalline vous a demandé de lui apporter une Glande à venin pointeglace trouvée sur une Rampante pointeglace."}}
D[12832] = {"Un départ amer",{"Escortez le Mineur gobelin blessé hors de la Caverne de la Toile cristalline, puis parlez à Ricket à K3."}}
D[12833] = {"Surplus",{"Ricket, à K3, veut que vous utilisiez les Mines améliorées à Plaie-de-Garm pour repousser les attaquants de Garm. Les Envahisseurs de Garm et les Suivants Brûleglace comptent comme attaquants."}}
D[12834] = {"Ni la pluie, ni la neige, ni un avion qui explose",{"[PLACEHOLDER] Test bombardement temps froid sur géant."}}
D[12835] = {"Déjà grand",{"[PLACEHOLDER] Test Jormungar adulte sur géant"}}
D[12836] = {"Une preuve de gratitude",{"Ricket à K3 veut que vous tuiez Peau-noueuse."}}
D[12837] = {"Tore a les fournitures",{"[PLACEHOLDER] Faites votre rapport à Tore"}}
D[12838] = {"Trouver des informations",{"Morneplaie des aurochs, à la Cime de la Mort, vous a demandé de récupérer 5 Documents de renseignement de l'Assaut."}}
D[12839] = {"Le grand plan de l'amiral",{"Remettez la Note du Grand Amiral au seigneur-commandant Arete à la Cime de la Mort."}}
D[12840] = {"Que ça reste entre nous",{"Le Seigneur-commandant Arete, à la Cime de la Mort, vous a demandé d'extirper l'information des capitaines Welsington et Hartford."}}
D[12841] = {"La proposition de la mégère",{"Lok'lira la Mégère à l'intérieur de la Mine Lugubre vous a demandé de récupérer les Runes des Yrkvinn que détient la Surveillante Syra."}}
D[12842] = {"La runeforge : se préparer à la bataille",{"L’Instructeur Razuvious du Fort d’Ébène, vous ordonne de vous rendre à une runeforge, et de vous servir de votre talent Runeforge pour graver une rune de votre choix sur votre Lame d’âme runique.","","Vous pourrez la remplacer n’importe quand, tant que vous serez à proximité d’une runeforge."}}
D[12843] = {"Elles ont pris nos hommes !",{"Gretchen Pfutincelle vous demande d'aller à Sifreldar et de secourir 5 Prisonniers gobelins."}}
D[12844] = {"Récupération de l'équipement",{"Gretchen Pfutincelle vous a demandé d'obtenir 8 Equipements K3 à Sifreldar, au nord de K3."}}
D[12845] = {"Drapeau du cristal de téléportation à Dalaran"}
D[12846] = {"Le gobelin manquant",{"Trouvez l'entrée de la Mine Lugubre au nord du Village Sifreldar et cherchez des indices sur l'endroit où se trouve Zeev Pfutincelle."}}
D[12847] = {"Secondes chances",{"Tuez le Grand abbé Langrain, puis invoquez la Porte d'Arete en présence de son cadavre. Parlez au Seigneur-commandant Arete à l'intérieur de la Cathédrale cramoisie une fois qu'il aura questionné l'esprit du grand abbé."}}
D[12848] = {"La faim sans fin",{"L'Instructeur Razuvious à Fort d'Ébène vous a demandé de libérer un Initié indigne puis de tuer l'Initié indigne de sang-froid !","","C'est votre vie ou la sienne !"}}
D[12849] = {"Le pouvoir du sang, du givre et de l'impie"}
D[12850] = {"Rapport au commandant du Fléau Thalanor",{"Faites votre rapport au Commandant du Fléau Thalanor sur le balcon au premier étage du Fort d'Ébène."}}
D[12851] = {"La pro de l’ours",{"Brijana à Brunnhildar vous a demandé de chevaucher Croc-de-glace et d'abattre 7 Worgs de givre et 15 Géants du givre dans la Vallée des Anciens hivers."}}
D[12852] = {"L'amiral à découvert",{"Le Seigneur-commandant Arete vous a demandé de tuer le Grand amiral Ponevent. Retournez voir le Seigneur-commandant à la Cime de la Mort quand la tâche est accomplie."}}
D[12853] = {"Une escapade luxueuse !",{"Allez voir Gouaille Grilledouille à K3, aux Pics Foudroyés."}}
D[12854] = {"Sur les traces de Brann",{"Récupérez la Note enveloppée dans de la toile au bivouac de Brann et rapportez-la à l'Archéologue Andorin à Fort du Givre."}}
D[12855] = {"Renifler le coupable",{"Utilisez le Collier de molosse du givre au Camp abandonné pour suivre la piste des objets de Brann. Quand vous les aurez récupérés, utilisez l'appareil de communication et contactez qui vous pouvez."}}
D[12856] = {"Brisons la glace",{"Brijana, à l'est de Brunnhildar, veut que vous voliez jusqu'à Dun Niffelem, que vous libériez 3 Proto-drakes captifs et que vous sauviez 9 Prisonnières de Brunnhildar."}}
D[12857] = {"Avis de recherche : Nageoire de Crin-de-rage",{"Récupérez la Nageoire de Crin-de-rage et rapportez-la au Chef Grifferage à la Brèche de Lumière à Zul'Drak."}}
D[12858] = {"Les pièces du puzzle",{"Rassemblez les 6 Fragments du disque de l'inventeur et utilisez-les pour assembler le Disque de l'inventeur."}}
D[12859] = {"Nouvelle neuve : le feu ça brûle !",{"L'Ancien chaman Moky à la Brèche de Lumière à Zul'Drak vous demande d'utiliser l'Extincteur grifferage pour éteindre 15 Feux de hutte à la Tanière grifferage."}}
D[12860] = {"À la recherche de données",{"Utilisez le disque de l'inventeur pour récupérer 7 Fragments de données cachées dans les Banques de données."}}
D[12861] = {"Les trolls ils ont tombé sur la tête !",{"Le Chef Grifferage à la Brèche de Lumière à Zul'Drak vous demande d'utiliser les Ouvre-serrures de Drakuru trouvés sur différents trolls Drakuru pour libérer 8 Grifferages capturés."}}
D[12862] = {"Quand tout le reste a échoué…",{"Parlez à Ricket pour utiliser l'Engin de livraison à propulsion D16 de Ricket afin de pénétrer au cœur des Pics Foudroyés."}}
D[12863] = {"Des remerciements",{"Apportez la caisse de Fournitures médicales à Glorthal Barberêche à Fort du givre."}}
D[12864] = {"Les éclaireurs manquants",{"Glorthal, au Fort du Givre, vous a demandé d'explorer la vallée du Souffle de Bor et la Chute de Bor en quête d'une trace des Éclaireurs givre-nés disparus."}}
D[12865] = {"Des compagnons loyaux",{"Fjorlin Front-de-givre, au Fort du Givre, veut que vous récupériez 8 tranches de Viande fraîche de rhinocéros des glaces, et que vous les utilisiez pour nourrir les Aigles foudrecrête qui nichent au-dessus de la ville."}}
D[12866] = {"Contenir les agresseurs",{"Glorthal Barberêche au Fort du Givre veut que vous tuiez 8 Hurleuses givreplumes et 8 Sorcières givreplumes."}}
D[12867] = {"Voleurs de bébés",{"Fjorlin Front-de-givre au Fort du Givre vous a demandé de lui rapporter 15 Œufs d'aigles foudrecrêtes."}}
D[12868] = {"Sirana Hurleglace",{"Glorthal Barberêche au Fort du Givre veut que vous éliminiez Sirana Hurleglace."}}
D[12869] = {"Trop loin",{"Fjorlin Front-de-givre veut que vous chevauchiez un Aigle foudrecrête et que vous tuiez 16 Wyrms foudrepics dans le Pied-mont."}}
D[12870] = {"Reliques anciennes",{"Rapportez 10 Reliques d'Ulduar à Rork Menton-pointu au Fort du Givre."}}
D[12871] = {"De l'aide de la Ligue des explorateurs",{"Apportez la Coque de Norgannon à Lagnus, au Fort du Givre."}}
D[12872] = {"La coque de Norgannon",{"Récupérez la Coque de Norgannon auprès de l'Archiviste Mécaton."}}
D[12873] = {"Le roi des givre-nés",{"Parlez au Roi Yorg Foudrecœur au Fort du Givre."}}
D[12874] = {"La ferveur du givre-né",{"Yorg Foudrecœur, au Fort du givre, vous a demandé de parler à Fjorlin Front-de-givre pour récupérer une monture et passer votre épreuve."}}
D[12875] = {"Un guide expérimenté",{"Localiser Drom Poignegivre."}}
D[12876] = {"Des invités indésirables",{"Fjorlin Front-de-givre au Fort du givre vous a demandé de tuer 10 Envahisseurs forge-foudre."}}
D[12877] = {"Le guetteur solitaire",{"Reprenez la Chevalière de Poignegivre des mains d'un Observateur nain de fer et apportez-la à Creteus dans le Pied-mont."}}
D[12878] = {"La relique cachée",{"Creteus, dans le Pied-mont, vous a donné des informations qui vous permettent de localiser le Noyau de Norgannon."}}
D[12879] = {"La fureur du roi givre-né",{"Rapportez le noyau de Norgannon à Creteus au Pied-mont."}}
D[12880] = {"L'explorateur en chef",{"Rapportez le noyau de Norgannon à Brann Barbe-de-bronze au Moteur des Faiseurs."}}
D[12881] = {"Les frères Barbe-de-bronze"}
D[12882] = {"Reliques anciennes",{"Vous effectuez cette quête"}}
D[12883] = {"Ordres de Drakuru",{"Rapportez les Ordres de Drakuru au Seigneur croisé Lantinga à la Brèche de Lumière à Zul'Drak."}}
D[12884] = {"Le guet d'Ébène",{"Portez les Ordres de Drakuru à Stefan Vadu au Guet d'Ébène à Zul'Drak."}}
D[12885] = {"Les exilés d'Ulduar",{"Parlez à Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12886] = {"Le Drakkensryd",{"Utilisez le Harpon hyldnir pour vaincre 10 Chevaucheuses de drake du Hyldsmeet au Temple des Tempêtes. Utilisez le Harpon hyldnir sur un Ornement de colonne pour quitter le Drakkensryd et parler à Thorim une fois la tâche accomplie."}}
D[12887] = {"Qu'est-ce qu'on se marre",{"Détruisez l'Oculaire et faites votre rapport au Baron Lesquille au Caveau des Ombres."}}
D[12888] = {"FERRAILL-E",{"Apportez la Carte d'accès de FERRAILL-E, ainsi que 4 Poignées de boulons en cobalt et 5 Condensateurs surchargés à FERRAILL-E à la Bibliothèque de l'inventeur."}}
D[12889] = {"La console prototype",{"Utilisez la Console prototype à la Bibliothèque de l'inventeur."}}
D[12890] = {"Si la taille était importante"}
D[12891] = {"J'ai une idée mais d'abord…",{"Le Baron Lesquille, au Caveau des Ombres, vous a demandé de trouver un Bâtonnet de sectateur, un Crochet d'abomination, une Corde de Geist et 5 Essences du Fléau."}}
D[12892] = {"Qu'est-ce qu'on se marre",{"Détruisez l'Oculaire puis faites votre rapport au Baron Lesquille au Caveau des Ombres."}}
D[12893] = {"Libérez votre esprit",{"Le Baron Lesquille, au Caveau des Ombres, vous demande d'utiliser le Bâtonnet souverain sur les cadavres de Vil, Dame Bois-de-nuit et Le Bondisseur."}}
D[12894] = {"Le camp avancé des croisés",{"Allez trouver le Croisé MacKellar au Camp avancé des croisés à Zul'Drak."}}
D[12895] = {"Le Barbe-de-bronze manquant",{"Vous effectuez cette quête"}}
D[12896] = {"S'il ne peut pas être détourné…",{"Tuez le Général Plaie-de-lumière puis allez rapporter votre succès à Thassarian à bord de la canonnière Brise-ciel."}}
D[12897] = {"S'il ne peut pas être détourné…",{"Tuez le Général Plaie-de-lumière puis allez rapporter votre succès auprès de Koltira Tissemort à bord de la canonnière, le Marteau d'Orgrim."}}
D[12898] = {"Le caveau des Ombres",{"Présentez-vous au Baron Lesquille au Caveau des Ombres."}}
D[12899] = {"Le caveau des Ombres",{"Présentez-vous au Baron Lesquille au Caveau des Ombres."}}
D[12900] = {"Fabriquer un harnais",{"Astrid Bjornrittar à Brunnhildar veut que vous rapportiez 3 Peaux de yéti crins-de-glace."}}
D[12901] = {"Système D",{"L’Ingénieur Reed, du Camp avancé des croisés à Zul’Drak, vous a demandé de récupérer 10 Morceaux de ferraille du Fléau."}}
D[12902] = {"En quête de réponses",{"Fouillez la Tanière Grifferage à la recherche d’indices sur l’origine de ceux qui, ou de ce qui, a attaqué les varleus Grifferage."}}
D[12903] = {"Les amis sont là pour ça…",{"Le Croisé MacKellar, au Camp avancé des croisés, vous a demandé de trouver le Croisé Dargath, ainsi que Gerk et Burr."}}
D[12904] = {"La Lumière ne m'accorde pas la vengeance",{"Gerk, à la Fin de Thrym à Zul’Drak, veut que vous tuiez 15 Varguls."}}
D[12905] = {"Mildred la Cruelle",{"Parlez à Mildred la Cruelle à la Mine Lugubre."}}
D[12906] = {"Discipline",{"Mildred la Cruelle à la Mine Lugubre vous a demandé d'utiliser le Bâton de discipline sur 6 Vrykuls épuisés."}}
D[12907] = {"Faire des exemples",{"Mildred la Cruelle à la Mine Lugubre vous a demandé de tuer Garhal."}}
D[12908] = {"La bravache et la prisonnière",{"Apportez la Clé de Mildred à Lok'lira la Mégère à la Mine Lugubre."}}
D[12909] = {"Le nez sait",{"Parlez à Khaliisi au pied de la montagne au Point d'impact de Grom'arsh."}}
D[12910] = {"Renifler le coupable",{"Chevauchez Morsure-de-givre et amenez-la jusqu'à la source de l'odeur de la note de Brann. Puis, retrouvez le Communicateur de Brann et utilisez-le pour entrer en contact avec Brann Barbe-de-bronze."}}
D[12911] = {"Test de crédit de mort",{"/signe au test de crédit de mort"}}
D[12912] = {"Une grande tempête approche",{"Gymer, le roi des géants des tempêtes, vous a demandé de trouver un moyen de le libérer de sa cage. Allez voir l’Ingénieur Reed, au Camp avancé des croisés."}}
D[12913] = {"Vous ne pouvez pas parler orc comme tout le monde ?",{"Parlez à Moteha Né-du-vent, au Point d'impact de Grom'arsh."}}
D[12914] = {"Le salut de Gymer",{"L’Ingénieur Reed, du Camp avancé des croisés à Zul’Drak, a besoin de 6 Essences de banshees et de 6 Diatomites."}}
D[12915] = {"Rentrer dans les bonnes grâces",{"Thorim au Temple des Tempêtes vous a demandé de tuer Fjorn et 5 Géants de fer forge-foudre à l'Enclume de Fjorn, à l'est de Dun Niffelem.","","Utilisez le Charme de terre de Thorim pour invoquer ses Terrestres qui se battront à vos côtés. Vous aurez besoin d'un Rocher de granit près de l'Enclume de Fjorn pour que le charme fonctionne."}}
D[12916] = {"Notre seul espoir",{"Utilisez la Charge d’hydroglycérine éléphantesque pour détruire l’Enclos du Fléau qui retient Gymer prisonnier. Lorsque ce sera fait, parlez à Gymer, à la Fin de Thrym à Zul’Drak."}}
D[12917] = {"Parler avec la voix du vent",{"Apportez 5 Voix du vent à Moteha Né-du-vent, au Point d'impact de Grom'arsh."}}
D[12918] = {"La perfection des gemmes",{"Ounhulo, à Valgarde, a besoin de deux Énormes citrines, de deux Jades sombres et de deux Cristaux ombreux."}}
D[12919] = {"La vengeance du roi des tempêtes",{"Parlez à Gymer pour commencer.","","Lorsque vous serez sur son dos, détruisez 100 créatures du Fléau, et tuez Algar l’Élu, Thrym et le Prince Navarius. Si vous réussissez, allez faire votre rapport au Croisé MacKellar, au Camp avancé des croisés."}}
D[12920] = {"Retrouver Brann",{"Utilisez le Communicateur de Brann pour contacter Brann Barbe-de-bronze et parlez-lui, puis parlez à Boktar Rougefurie au Point d'impact de Grom'arsh.","","Si vous perdez le Communicateur de Brann, allez parler à Moteha Né-du-vent au Point d'impact de Grom'arsh."}}
D[12921] = {"Changer de décor",{"Retrouvez Lok'lira la Mégère à Brunnhildar."}}
D[12922] = {"Le feu du raffineur",{"Récupérez 10 Étincelles furieuses sur des Revenants vengeurs au Lac du Champ-gelé, puis utilisez l'enclume à l'Enclume de Fjorn."}}
D[12924] = {"Forger une alliance",{"Rendez-vous à Dun Niffelem et demandez au Roi Jokkum de permettre que l'Armure de Thorim soit reforgée. Après avoir terminé la tâche de Jokkum, allez parler à Njormeld à Dun Niffelem."}}
D[12925] = {"Aberrations",{"Thyra Kvinnshal à Brunnhildar vous demande de vous rendre à Valkyrion et d'obtenir des Fioles d'huile glaciale des Aspirantes de Valkyrion. Utilisez les Fioles d'huile glaciale pour détruire 30 Oeufs de Proto-drakes pestiférés."}}
D[12926] = {"Les pièces du puzzle",{"Utilisez le Communicateur de Brann pour contacter Brann Barbe-de-bronze afin de savoir que faire ensuite."}}
D[12927] = {"Collecte de données",{"Utilisez le Disque de l'inventeur pour retrouver 7 fragments de Données cachées dans les Banques de données."}}
D[12928] = {"La coque de Norgannon",{"Récupérez le Noyau de Norgannon auprès de l’Archiviste Mécaton."}}
D[12929] = {"Les Terrestres d'Ulduar",{"Parlez à Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12930] = {"Une terre rare",{"Utilisez la Pioche terrestre pour extraire 7 mottes de Terre enchantée. Apportez la Terre enchantée et 5 Etoffes de tisse-givre à Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12931] = {"Contre-attaquer",{"Rochecombe le Sculpteroc veut que vous tuiez 10 Attaquants forge-foudre et que vous retourniez le voir au Refuge de Rochecombe. Vous pouvez tuer soit des Ecumeurs forge-foudre soit des Saccageurs forge-foudre."}}
D[12932] = {"L'Amphithéâtre de l'Angoisse : Yggdras !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez d’Yggdras ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12933] = {"L'Amphithéâtre de l'Angoisse : magnataure !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez de Barbapue ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12934] = {"L'Amphithéâtre de l'Angoisse : de l'au-delà !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez de l’un des seigneurs élémentaires ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12935] = {"L'Amphithéâtre de l'Angoisse : rohart-maggedon !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez d’Orinoko Brise-défense ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12936] = {"L'Amphithéâtre de l'Angoisse : Korrak le Ragesang !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez de Korrak le Ragesang ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12937] = {"Soulager les blessés",{"Utilisez le Cataplasme tellurique pour soigner 8 Défenseurs terrestres tombés au combat, puis retournez voir Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12938] = {"Le duc",{"Parlez au Duc Lankral au Caveau des Ombres."}}
D[12939] = {"Un défi pour l'honneur",{"Le Duc Lankral, au Caveau des Ombres, vous a demandé d'utiliser le Drapeau de défi pour défier et vaincre 6 Combattants de Mjordin."}}
D[12940] = {"Seau de bonbons"}
D[12941] = {"Seau de bonbons"}
D[12942] = {"Qu'on leur coupe leurs ailes noires !",{"Iva la Vengeresse à Brunnhildar vous demande de vous rendre à Valkyrion et de tuer 12 Val'kyrs naissantes."}}
D[12943] = {"Le décret du caveau des Ombres",{"Le Duc Lankral, au Caveau des Ombres, vous a ordonné de lire le Décret du caveau des Ombres en présence du Thane Ufrang le Puissant, puis de le tuer."}}
D[12944] = {"Seau de bonbons"}
D[12945] = {"Seau de bonbons"}
D[12946] = {"Seau de bonbons"}
D[12947] = {"Seau de bonbons"}
D[12948] = {"Le Champion de l'Angoisse",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez de Vladof le Boucher ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12949] = {"Récupérer la clé",{"Vaelen l'Écorché dans la Salle d'Ufrang vous a demandé de récupérer la Clé des chaînes de Vaelen."}}
D[12950] = {"Seau de bonbons"}
D[12951] = {"Informer le baron",{"Parlez au Baron Lesquille au Caveau des Ombres."}}
D[12952] = {"La perfection des gemmes",{"Vous effectuez cette quête"}}
D[12953] = {"Brûle, Valkyrion, brûle !",{"Utilisez les Lance-harpons de Valkyrion pour brûler 6 Meules de foin sèches."}}
D[12954] = {"L'Amphithéâtre de l'Angoisse : Yggdras !",{"Entrez dans l’arène de l’Amphithéâtre de l’Angoisse et triomphez d’Yggdras ! Ensuite, allez voir Wodin le Serviteur-troll pour toucher votre récompense."}}
D[12955] = {"Éliminez la concurrence",{"Le Bondisseur, au Caveau des Ombres, vous demande d'affronter en duel et de vaincre Sigrid Née-de-glace, Efrem le Fidèle, Onu'zun et Bricole Sifflemèche."}}
D[12956] = {"Une faible lueur d'espoir",{"Vous devez apporter le Minerai resplendissant raffiné à Thorim au Temple des tempêtes."}}
D[12957] = {"Les esclaves des Forge-foudre",{"Rochecombe le Sculpteroc au Refuge de Rochecombe veut que vous libériez 6 Mécagnomes captifs et que vous tuiez 3 Sous-chefs forge-foudre."}}
D[12958] = {"Livraison : Amulette en jade de sang",{"Combinez une Amulette vrykule, un Jade sombre et une Pierre de sang pour créer une Amulette en jade de sang et l'apporter ensuite à Timothy Jones à Dalaran.","","Vous trouverez une Amulette vrykule sur n'importe quel vrykul du Norfendre."}}
D[12959] = {"Livraison : Figurine luminescente en ivoire",{"Combinez de l’Ivoire nordique, une Calcédoine et un Cristal ombreux pour créer une Figurine luminescente en ivoire et apportez-la à Timothy Jones à Dalaran. Vous trouverez de l’Ivoire nordique sur n'importe quel Brochepelle ou Mammouth du Norfendre."}}
D[12960] = {"Livraison : Broche du soleil pernicieux",{"Combinez une Broche des nains de fer, une Énorme citrine et un Cristal soleil pour créer une Broche du soleil pernicieux et apportez-la ensuite à Timothy Jones à Dalaran.","","Vous trouverez une Broche des nains de fer sur n'importe quel Nain de fer du Norfendre."}}
D[12961] = {"Livraison : Figurine complexe en os",{"Combinez un Os de proto-dragon, un Cristal soleil et un Jade sombre pour créer une Figurine complexe en os et l'apporter à Timothy Jones à Dalaran.","","Vous trouverez un Os de proto-dragon sur n'importe quel Proto-dragon du Norfendre."}}
D[12962] = {"Livraison : Relique de l'armure éclatante",{"Combinez un Morceau d'armure des éléments, une Pierre de sang et une Enorme citrine pour créer une Relique de l'armure éclatante et l'apporter à Timothy Jones à Dalaran.","","Vous trouverez un Morceau d'armure des éléments sur n'importe quel Revenant du Norfendre."}}
D[12963] = {"Livraison : Bibelot du soleil changeant",{"Combinez un Bibelot du Fléau, un Cristal soleil et un Cristal ombreux pour créer un Bibelot du soleil changeant et l'apporter à Timothy Jones à Dalaran.","","Vous trouverez un Bibelot du Fléau sur n'importe quel créature du Fléau en Norfendre."}}
D[12964] = {"Le minerai sombre",{"Apportez 5 Echantillons de minerai à Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12965] = {"Les cadeaux de Loken",{"Détruisez la Fureur de Loken, le Pouvoir de Loken et la Faveur de Loken, puis retournez voir Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12966] = {"Vous ne pourrez pas le rater",{"Le Roi Jokkum, à Dun Niffelem, veut que vous rejoigniez Njormeld à l'Enclume de Fjorn."}}
D[12967] = {"Affronter les éléments",{"Njormeld veut que vous accompagniez Snorri à l'Enclume de Fjorn et que vous l'aidiez à tuer 10 Revenants vengeurs."}}
D[12968] = {"La folie de Yulda",{"Iva la Vengeresse à Brunnhildar vous a demandé de tuer Yulda la Parlorage à Valkyrion."}}
D[12969] = {"Il est à vous, ce gobelin ?",{"Défiez Agnetta Tyrsdottar afin de sauver Zeev Pfutincelle. Retournez auprès de Lok'lira la Mégère à Brunnhildar une fois la tâche accomplie."}}
D[12970] = {"Le Hyldsmeet",{"Écoutez la proposition de Lok'lira la Mégère."}}
D[12971] = {"Accepter tous les défis",{"Lok'lira la Mégère à Brunnhildar vous a demandé de vaincre 6 Prétendantes victorieuses."}}
D[12972] = {"Vous aurez besoin d'un ours",{"Parlez à Brijana à l'extérieur de Brunnhildar."}}
D[12973] = {"Les frères Barbe-de-bronze",{"Accompagnez Brann Barbe-de-bronze et sa Machine volante au Fort du Givre."}}
D[12974] = {"L'appel du champion !",{"Vous effectuez cette quête"}}
D[12975] = {"In Memoriam",{"Le Roi Jokkum à Dun Niffelem veut que vous récupériez 8 Fragments de cor à Chute-tonnerre."}}
D[12976] = {"Un monument à ceux qui sont tombés",{"Le Roi Jokkum veut que vous apportiez les Fragments du Cor de Hodir à Njormeld à Dun Niffelem."}}
D[12977] = {"L’appel de Hodir",{"Vous devez vaincre 5 Ancêtres niffelem et 5 Givre-nés sans repos à Chute-tonnerre. Vous devez ensuite souffler dans le Cor de Hodir au-dessus de leurs cadavres, puis rapportez le Cor de Hodir à Dun Niffelem."}}
D[12978] = {"Face à la tempête",{"Bruor Plaie-du-fer au Refuge de Rochecombe veut que vous assassiniez 10 Forge-foudre nidavelirs. Vous pouvez tuer des Champions forge-foudre, des Magi forge-foudre, ou des Golems de guerre forge-foudre."}}
D[12979] = {"L'armure des ténèbres",{"Apportez 4 Echantillons d'armure sombre à Bruor Plaie-du-fer au Refuge de Rochecombe."}}
D[12980] = {"Les secrets de l'armure",{"Emportez la Plaque d'armure sombre à l'Atelier de Mimir et demandez au Domestique Tock de l'examiner. Quand ce sera fait, retournez auprès de Bruor Plaie-du-fer au Refuge de Rochecombe."}}
D[12981] = {"Chaud et froid",{"Vous devez vous rendre au Lac du Champ-gelé pour y tuer les Revenants vermoulus et utiliser ensuite l'Essence de glace sur les Ferrailles fumantes à l'Enclume de Fjorn. Vous devrez alors récupérer 6 Morceaux de fer gelé et retourner à l'Enclume de Fjorn à Dun Niffelem."}}
D[12982] = {"Les prisonniers de la Lame d'ébène",{"Vaelen l'Écorché, au Caveau des Ombres, vous a demandé de libérer 8 Prisonniers de la Lame d'ébène. Ils se trouvent dans des cages partout dans la région de Jotunheim."}}
D[12983] = {"La dernière de son espèce",{"Astrid Bjornrittar à Brunnhildar vous a demandé de sauver une Matriarche glacegueule à la Caverne de l'Hibernation."}}
D[12984] = {"Valduran Issu-des-tempêtes",{"Utilisez le Cor de guerre de Rochecombe quand vous aurez trouvé Valduran Issu-des-tempêtes. Battez Valduran Issu-des-tempêtes et retournez voir Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12985] = {"Forger une tête",{"Njormeld à Dun Niffelem a besoin de vous pour utiliser la Pioche à pointe de diamant sur les Géants de fer morts au lac du Champ-gelé, puis retournez le voir quand vous aurez récupéré 8 Yeux de Forge-foudre."}}
D[12986] = {"Le destin des titans",{"Creteus dans le Pied-mont vous a demandé de vous rendre au Temple de l'Innovation, au Temple de l'Hiver, au Temple de la Vie et au Temple de l'Ordre, et d'utiliser la Banque de données pour examiner chaque zone."}}
D[12987] = {"Placer le heaume de Hodir",{"Njormeld vous demande de voler vers le sommet des Pointes de glace du Nord à Dun Niffelem et d'utiliser les Tablettes de déclaration."}}
D[12988] = {"Détruisez les forges !",{"Détruisez la Forge de foudre du nord, la Forge de foudre centrale et la Forge de foudre du sud avec les Bombes de Rochecombe, puis retournez voir Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12989] = {"Les ténèbres rampantes",{"Astrid Bjornrittar vous a demandé de tuer 8 Jormungars voraces à la Caverne de l'Hibernation à l'est de Brunnhildar."}}
D[12990] = {"Le tunnel spatiotemporel",{"Apportez à Jon LeCraft les matériaux qu'il recherche pour éviter une mort rapide et obtenir un nouveau sort génial."}}
D[12991] = {"Tapez là où ça fait mal",{"Tuez 10 Artificiers forge-foudre, puis retournez voir Bruor Plaie-du-fer au Refuge de Rochecombe."}}
D[12992] = {"Écrasez les vrykuls !",{"Vil, au Caveau des Ombres, veut que vous assassiniez 15 Vrykuls dans la région de Jotunheim."}}
D[12993] = {"Une menace colossale",{"Récupérez le Plan des caractéristiques offensives du colosse et le Plan des caractéristiques défensives du colosse, puis rapportez-les à Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[12994] = {"À la chasse aux espions",{"Vous devez vaincre 3 Espions forge-foudre dans la Vallée des Anciens hivers.","","Utilisez le Croc de worg éthérien sur place pour invoquer un Chasseur éthérien qui débusquera les ennemis cachés. Vous devez retourner auprès de la Mère de la tanière worg de givre à Dun Niffelem une fois la vallée nettoyée de ces espions."}}
D[12995] = {"Laisser notre marque",{"Le Baron Lesquille, au Caveau des Ombres, veut que vous plantiez 15 Bannières de la Lame d'ébène près des cadavres de Vrykuls trouvés dans la région de Jotunheim."}}
D[12996] = {"Tour de chauffe",{"Astrid Bjornrittar à Brunnhildar veut que vous utilisiez les Rênes de matriarche ours de guerre pour vaincre Kirgaraak."}}
D[12997] = {"Dans la fosse",{"Astrid Bjornrittar à Brunnhildar veut que vous utilisiez les Rênes de matriarche ours de guerre dans la Fosse du croc et que vous battiez 6 Ours de guerre du Hyldsmeet."}}
D[12998] = {"Le Cœur de la tempête",{"Rochecombe le Sculpteroc au Refuge de Rochecombe veut que vous alliez à Uldis pour essayer d'empêcher que le Surveillant Narvir n'obtienne le Cœur de la tempête."}}
D[12999] = {"La sorcière des ossements",{"Parlez à la Sorcière des ossements dans la caverne, à Njorndar."}}
D[13000] = {"Mesures d'urgence",{"Vous effectuez cette quête"}}
D[13001] = {"Forger la lance de Hodir",{"Le Gardien du savoir Randvir à Dun Niffelem vous a demandé de récupérer 3 Éclats permagivre des profondeurs de la Caverne de l'hibernation et 3 Peaux de mammouth stoïque dans la Vallée des Anciens hivers."}}
D[13002] = {"La perfection des gemmes",{"Geba'li, du Bastion Chanteguerre, a besoin de deux Enormes citrines, de deux Jades sombres et de deux Cristaux ombreux."}}
D[13003] = {"L’art de bien tuer son dragon",{"Vous devez utiliser la Lance de Hodir pour défier un Wyrm sauvage dans la Vallée des Anciens hivers. Une fois que c'est fait, vous devez vous battre à mort."}}
D[13004] = {"La perfection des gemmes",{"Alestros, du Donjon de la Bravoure, a besoin de deux Énormes citrines, de deux Jades sombres et de deux Cristaux ombreux."}}
D[13005] = {"Le serment des Terrestres",{"Thorim, à la Terrasse des Faiseurs, vous demande d'utiliser le Cor des pics pour appeler les Terrestres, et vaincre 20 Nains de fer et 7 Sentinelles de fer."}}
D[13006] = {"Nettoyage à suc",{"Vous devez aller à la Caverne de l'hibernation à l'ouest de Dun Niffelem pour récupérer 5 unités d'Huile visqueuse sur les créatures du même nom sur place.","","Vous devez ensuite retourner à Dun Niffelem pour appliquer l'huile sur le Heaume de Hodir."}}
D[13007] = {"Le colosse de fer",{"Utilisez un Jormungar apprivoisé pour vaincre le Colosse de fer, puis retournez voir Rochecombe le Sculpteroc au Refuge de Rochecombe."}}
D[13008] = {"Les tactiques du Fléau",{"Le Commandant de la croisade Entari, à l'Avant-garde d'Argent dans la Couronne de glace, vous a demandé de libérer 8 Croisés entoilés."}}
D[13009] = {"Un nouveau départ",{"Njormeld veut que vous apportiez l'Armure reforgée à Thorim au Temple des tempêtes."}}
D[13010] = {"Krolmir, le marteau des tempêtes",{"Thorim vous demande d'aller parler au Roi Jokkum à Dun Niffelem et de découvrir ce qu'il sait à propos de Krolmir."}}
D[13011] = {"Éliminer Jorcuttar",{"Le Roi Jokkum à Dun Niffelem vous demande de tuer Jorcuttar à la Caverne de l’hibernation."}}
D[13012] = {"L'Ancien Sardis"}
D[13013] = {"L'Ancien Beldak"}
D[13014] = {"L'Ancien Mortie"}
D[13015] = {"L'Ancien Fargal"}
D[13016] = {"L'Ancien Nordal"}
D[13017] = {"L'Ancien Jarten"}
D[13018] = {"L'Ancien Sablon"}
D[13019] = {"L'Ancien Thoim"}
D[13020] = {"L'Ancien Barbe-de-pierre"}
D[13021] = {"L'Ancien Igasho"}
D[13022] = {"L'Ancien Nurgen"}
D[13023] = {"L'Ancien Kilias"}
D[13024] = {"L'Ancien Wanikaya"}
D[13025] = {"L'Ancien Lunaro"}
D[13026] = {"L'Ancien Loup-bleu"}
D[13027] = {"L'Ancien Tauros"}
D[13028] = {"L'Ancien Crin-gris"}
D[13029] = {"L'Ancien Pamuya"}
D[13030] = {"L'Ancien Whurain"}
D[13031] = {"L'Ancien Garde-ciel"}
D[13032] = {"L'Ancien Muraco"}
D[13033] = {"L'Ancien Arp"}
D[13034] = {"Le témoin et le héros",{"Xarantaur, au Camp Tunka'lo, veut que vous lisiez le Premier parchemin de l'histoire, le Second parchemin de l'histoire et le Troisième parchemin de l'histoire."}}
D[13035] = {"Les laquais de Loken",{"Thorim vous demande de tuer Eisenfaust dans le Hall du Façonneur, et Halefnir l'Enfant du vent et Duronn le Formerune à la Terrasse des Faiseurs."}}
D[13036] = {"L'honneur avant tout",{"Présentez-vous au Commandant de la croisade Entari à l'Avant-garde d'Argent, dans la Couronne de glace."}}
D[13037] = {"Souvenirs de Sabot-tempête",{"Parlez au Chef Vivelance au Gouffre du Sérac, puis retournez voir Xarantaur au Camp Tunka'lo."}}
D[13038] = {"Distortions temporelles",{"Utilisez le Totem du chef pour fermer 4 Failles du Sérac, puis rapportez le Totem à Xarantaur au Camp Tunka'lo."}}
D[13039] = {"Défendre l'avant-garde",{"Le Seigneur croisé Dalfors, à l'Avant-garde d'Argent dans la Couronne de glace, vous a demandé de tuer 15 Nérubiens des profondeurs oubliées."}}
D[13040] = {"Soigner l'insoignable",{"Le Père Gustav, à l'Avant-garde d'Argent dans la Couronne de glace, vous a demandé de lui apporter 10 Glandes à venin des profondeurs oubliées."}}
D[13041] = {"Terminer la livraison",{"Apportez une Calcédoine à Timothy Jones à Dalaran."}}
D[13042] = {"Dans les profondeurs des Basses-salles",{"La Sorcière des ossements à Njorndar vous a demandé de battre l'Apprenti Osterkilgr afin d'obtenir des informations concernant ce que prépare le Dr Terrible.","","Vous devez ensuite tuer l'Apprenti."}}
D[13043] = {"Le tout est plus grand que la somme des parties",{"Montez Nergeld et prenez-en le contrôle. Défendez-le contre les habitants de la Salle des Horreurs jusqu'à ce que le Dr Terrible se montre.","","Utilisez Nergeld pour tuer le docteur, puis retournez voir la Sorcière des ossements à Njorndar."}}
D[13044] = {"S'il reste des survivants...",{"Parlez à Penumbrius à l'Avant-garde d'Argent dans la Couronne de glace."}}
D[13045] = {"Ça va tanguer dans la verdure !",{"Sauvez 3 Croisés d'argent capturés à Fléaulme et amenez-les à l'Infirmerie de l'avant-garde au centre de l'Avant-garde d'Argent. Allez voir le Généralissime Tirion Fordring si vous réussissez."}}
D[13046] = {"Caler la dent creuse d'Arngrim",{"Vous devez donner à manger à Arngrim 5 Jormungars désincarnés puis retourner auprès de l'image gelée d'Arngrim à Dun Niffelem.","","Rendez-vous dans la Vallée des Anciens hivers et utilisez la Dent d'Arngrim sur les Jormungars mobiles qui s'y trouvent. Une fois qu'ils sont désincarnés, vous devez les combattre jusqu'à ce qu'ils soient affaiblis."}}
D[13047] = {"La rétribution",{"Rencontrez Thorim près du Temple de la Sagesse. Racontez l'issue du combat au Roi Jokkum à Dun Niffelem."}}
D[13048] = {"Lorsque le temps tourne court",{"Utilisez le Marteau de la connaissance sur les Reliques taunkas pour le mettre en phase avec l'époque de Sabot-tempête. Une fois que vous l'aurez mis en phase avec 6 Reliques de l'époque de Sabot-tempête, retournez voir Xarantaur au Camp Tunka'lo."}}
D[13049] = {"Les armes du héros",{"Retrouvez la Lance de Sabot-tempête et la Cotte de maille de Sabot-tempête, et rapportez-les à Xarantaur au Camp Tunka'lo."}}
D[13050] = {"Veranus",{"Thorim, au Temple des tempêtes, veut que vous obteniez 5 Petits œufs de proto-drake sur les pics proches de Brunnhildar."}}
D[13051] = {"Violation de territoire",{"Placez les Oeufs de proto-dragon volés au sommet du Nid de la mère des couvées, puis retournez voir Thorim au Temple des tempêtes."}}
D[13052] = {"Surveillance aérienne",{"Le Professeur Calvert veut que vous preniez le vol pour le Terrain d'atterrissage de Rive-du-lac et que vous parliez au Pilote Vic, une fois rendu là-bas."}}
D[13053] = {"À la recherche de survivants",{"Aidez Zak Tremblerouage à réussir le Vol d'essai."}}
D[13054] = {"Le pisteur disparu",{"Vous effectuez cette quête"}}
D[13055] = {"Remède de caverne",{"Le Traqueur Val'zij, à la tanière de Gimorak, vous a demandé de récupérer 1 Glande à toxine jormungar et 8 Champignons de la caverne."}}
D[13056] = {"La vengeance est un plat qui se mange à toute heure",{"Le Traqueur Val'zij vous demande de tuer Gimorak dans la Tanière de Gimorak."}}
D[13057] = {"La terrasse des Faiseurs",{"Trouvez Thorim à la limite sud-est de la Terrasse des Faiseurs, au nord-ouest de Dun Niffelem."}}
D[13058] = {"Changer le sens du vent",{"Utilisez le Marteau de la connaissance pour remonter le temps et affronter le Vent du nord sous les traits de Sabot-tempête. Quand Sabot-tempête perd, récupérez le Cor de fureur élémentaire et achevez le Vent du nord, puis retournez voir Xarantaur au Camp Tunka'lo."}}
D[13059] = {"Vengeance pour les varguls",{"Bethod Feigr, aux Basses-salles, vous demande de défier le Thane Illskar en jetant son épée, puis de le tuer au Cercle de Souffrance."}}
D[13060] = {"Quand tout le reste a échoué…",{"Parlez à Ricket pour utiliser l'Engin de livraison à propulsion D16 de Ricket afin de pénétrer au cœur des Pics Foudroyés."}}
D[13061] = {"Préparation pour la gloire",{"Parlez à Lok'lira la Mégère à Brunnhildar."}}
D[13062] = {"Cadeau d'adieu de Lok'lira",{"Parlez à Gretta la Médiatrice à Brunnhildar."}}
D[13063] = {"Digne de valeur",{"Brijana veut que vous alliez à Brunnhildar pour parler avec Astrid Bjornrittar."}}
D[13064] = {"Rivalité fraternelle",{"Thorim veut que vous écoutiez son histoire."}}
D[13065] = {"L'ancien Ohanzee"}
D[13066] = {"L'ancien Yurauk"}
D[13067] = {"L'ancien Chogan'gada"}
D[13068] = {"Une histoire de bravoure",{"Le Généralissime Tirion Fordring, à la Cime des Croisés, vous a demandé de trouver un héros, le Croisé Bridenbrad, à la Veille silencieuse, au nord-est de la Couronne de glace. Son feu de camp devrait être le signe le plus évident de sa position depuis les cieux."}}
D[13069] = {"Descendez-les tous !",{"Le Bondisseur, au Caveau des Ombres, veut que vous utilisiez un Harpon à tir rapide jotunheim pour abattre 15 Proto-Drakes jotunheim et leurs Chevaucheurs."}}
D[13070] = {"Un front froid se rapproche",{"Présentez-vous au Maître de siège Fezzik à l'Avant-garde d'Argent, dans la Couronne de glace."}}
D[13071] = {"Vil aime feu !",{"Vil, au Caveau des Ombres, vous a demandé de voler un Proto-drake njorndar et de l'utiliser pour mettre le feu à 8 Bâtiments vrykuls dans la région de Jotunheim.","","La forteresse de Balargarde, en raison de sa nature, ne peut pas être enflammée."}}
D[13072] = {"Un héros reste",{"Apportez des nouvelles du destin du Croisé Bridenbrad au Généralissime Tirion Fordring à la Cime des Croisés."}}
D[13073] = {"La faveur du gardien",{"Le Généralissime Tirion Fordring, à la Cime des Croisés, vous a demandé d'obtenir de l'Archidruide Lilliandra un passage vers Reflet-de-Lune afin de parler au Gardien Remulos."}}
D[13074] = {"Un espoir dans le cauchemar d'émeraude",{"Le Gardien Remulos, à Reflet-de-lune, vous a demandé de pénétrer dans le Rêve d'émeraude et de récupérer 3 Glands d'émeraude.","","Passez les limites extérieures du Sanctuaire de Remulos pour retourner en Azeroth."}}
D[13075] = {"La faveur de Remulos",{"Retournez voir le Croisé Bridenbrad à la Veille Silencieuse, dans la Couronne de glace, avec le Gland d'émeraude."}}
D[13076] = {"Encore un peu de temps",{"Retournez voir le Généralissime Tirion Fordring à la Cime des Croisés et rapportez-lui les effets du Gland d'émeraude."}}
D[13077] = {"Le toucher d'un Aspect",{"Demandez l'aide d'Alexstrasza la Lieuse-de-vie au Temple du Repos du ver."}}
D[13078] = {"Les larmes de Dahlia",{"Alexstrasza la Lieuse-de-vie, au Temple du Repos du ver, vous a demandé de récupérer les Larmes de Dahlia sur une terre récemment purifiée par les flammes d'un Gardien rubis."}}
D[13079] = {"La faveur d'Alexstrasza",{"Apportez le Souffle d'Alexstrasza au Croisé Bridenbrad à la Veille Silencieuse, dans la Couronne de glace."}}
D[13080] = {"L'espoir fait vivre",{"Retournez voir le Généralissime Tirion Fordring à la Cime des Croisés et rapportez-lui les effets du Souffle d'Alexstrasza."}}
D[13081] = {"La volonté des naaru",{"Demandez l'aide d'A'dal à Shattrath, dans la Forêt de Terokkar."}}
D[13082] = {"La faveur d'A'dal",{"Retournez auprès du Croisé Bridenbrad à la Veille Silencieuse, dans la Couronne de glace."}}
D[13083] = {"La Lumière dans les ténèbres",{"Apportez le Tabard du Croisé Bridenbrad au Généralissime Tirion Fordring à la Cime des Croisés."}}
D[13084] = {"Jouer les vandales à Jotunheim",{"Le Duc Lankral, au Caveau des Ombres, vous demande de brûler 10 Bannières vrykules."}}
D[13085] = {"Vaelen est de retour",{"Parlez à Vaelen l'Écorché au Caveau des Ombres."}}
D[13086] = {"La dernière ligne de défense",{"Utilisez un Canon d'Argent pour détruire 100 Attaquants du Fléau. Vous devez également tuer 3 Destructeurs couvegivres.","","Retournez voir le Maître de siège Fezzik si vous deviez réussir."}}
D[13087] = {"La cuisine du Grand Nord",{"Apportez 4 morceaux de Viande glacée à Brom Mouillebière à Valgarde. La viande glacée se trouve sur n’importe quelle bête du Norfendre."}}
D[13088] = {"La cuisine du Grand Nord",{"Apportez 4 Viandes glacées à Rollick Mackreel au Donjon de la Bravoure. Vous pouvez récupérer de la Viande glacée sur n'importe quelle bête du Norfendre."}}
D[13089] = {"La cuisine du Grand Nord",{"Apportez 4 morceaux de Viande glacée à Thomas Kolichio, à l'Accostage de la Vengeance. La viande glacée se trouve sur n’importe quelle bête du Norfendre."}}
D[13090] = {"La cuisine du Grand Nord",{"Apportez 4 Viandes glacées à Orn Tendre-sabot au Bastion Chanteguerre. Vous pouvez récupérer de la Viande glacée sur n'importe quelle bête du Norfendre."}}
D[13091] = {"L'art d'être une terreur d'eau",{"La Sorcière des ossements, à Njorndar, vous demande de posséder une Terreur d'eau et de l'utiliser pour tuer 10 Vrykuls dans la région de Jotunheim.","","Sont considérés comme des Vrykuls les Gardiens du sommeil jotunheim, les Guerriers jotunheim, les Magi d'eau mjordin, les Njorndars sœur-de-lance et les Varguls du Valhalas."}}
D[13092] = {"Lecture des ossements",{"La Sorcière des ossements, à Njorndar, vous a demandé de récupérer 15 Os vrykuls."}}
D[13093] = {"Lecture des ossements"}
D[13094] = {"Ils n'ont vraiment honte de rien, alors ?",{"La Bibliothécaire Serrah veut que vous pénétriez dans le Nexus pour y récupérer les Recherches de Bérinand."}}
D[13095] = {"Ils n'ont vraiment honte de rien, alors ?",{"La Bibliothécaire Serrah veut que vous pénétriez dans le Nexus pour y récupérer les Recherches de Bérinand."}}
D[13096] = {"Gal'darah doit payer",{"Tol'mar à Dubra'Jin veut que vous assassiniez Gal'darah à Gundrak."}}
D[13097] = {"Terminer le travail",{"Har'koa vous demande de parler à Tol'mar à Dubra'jin."}}
D[13098] = {"Pour la postérité",{"La chroniqueuse Bah'Kini à Dubra'Jin vous demande d'aller à Gundrak et de récupérer 6 Tablettes de l'histoire drakkari."}}
D[13099] = {"Petite vérification",{"To'kini vous a demandé de parler à Bah'kini à Dubra'Jin."}}
D[13100] = {"Pain de viande aux champignons infusés",{"Cuisinez 4 Champignons infusés des égouts de Dalaran avec 2 Viandes glacées dans votre Plat à pain de viande et apportez le Pain de viande à Orton Bennet aux Objets de la Moore, situé sur la Place Tisserune à Dalaran."}}
D[13101] = {"Convention à l'Abracadabar",{"Apportez 4 Ragoûts nordiques préparés avec votre compétence en cuisine et une Cruche de vin de la Fromagerie de Dalaran à Arille Mirazur, à l'Abracadabar qui se trouve sur la Place Tisserune de Dalaran."}}
D[13102] = {"Le ragoût des égouts",{"Cuisinez 4 Carottes du Chant de cristal de la Forêt du Chant de cristal avec 4 Viandes glacées dans la Marmite.","","Une fois qu'il est prêt, apportez le Ragoût de légumes à Ajay Green, l'Aubergiste des égouts de Dalaran."}}
D[13103] = {"Du fromage pour Froncelor",{"Combinez le Plateau à fromages avec un Vieux limbourg de Dalaran provenant de la fromagerie « Un dernier pour la route » et avec 6 Verres de vin à moitié pleins trouvés sur des tables à Dalaran.","","Apportez le Plateau de vin et de fromages à Ranid Froncelor chez les Tanneurs de peaux à la Halle des mages."}}
D[13104] = {"Encore une fois sur la Brèche, héros",{"Présentez-vous au Gardien d'ébène dans la Vallée des Échos, à l'extérieur de la Brèche."}}
D[13105] = {"Encore une fois sur la Brèche, héros",{"Présentez-vous au Gardien d'ébène dans la Vallée des Échos, à l'extérieur de la Brèche."}}
D[13106] = {"Le Guet noir",{"Parlez à la Cavalière noire Arly au Guet noir, dans la Couronne de glace."}}
D[13107] = {"Hot-dogs à la moutarde !",{"Remplissez le Panier à pique-nique vide avec 4 Saucisses de rhinocéros que vous aurez cuisinées avec votre compétence en cuisine et 4 Moutardes sauvages que vous trouverez dans les zones herbeuses de Dalaran.","","Apportez le Panier à pique-nique à l'Archimage Pentarus à l'Aire de Krasus à Dalaran."}}
D[13108] = {"Quoi qu'il en coûte !",{"Le Roi Jokkum à Dun Niffelem vous demande de pénétrer dans les Salles de Foudre et de battre Loken. Vous devez ensuite retournez voir le Roi Jokkum avec la Langue de Loken."}}
D[13109] = {"Diamétralement opposé",{"Le Roi Jokkum à Dun Niffelem vous demande de pénétrer dans les Salles de Foudre et de battre Volkhan."}}
D[13110] = {"Les morts sans repos",{"Le Père Gustav, de la Vallée des Échos dans la Couronne de glace, vous demande d'utiliser de l'Eau bénite sur les cadavres des Croisés réanimés afin de libérer 10 Âmes sans repos."}}
D[13111] = {"Unique en son genre",{"La Chroniqueuse Bah'Kini à Dubra'Jin vous demande d'entrer à Gundrak et de récupérer un morceau de Colosse drakkari."}}
D[13112] = {"Pain de viande aux champignons infusés",{"Cuisinez 4 Champignons infusés des égouts de Dalaran avec 2 Viandes glacées dans votre Plat à pain de viande et apportez le Pain de viande aux champignons à Orton Bennet, aux Objets de la Moore situé sur la Place Tisserune à Dalaran."}}
D[13113] = {"Convention à l'Abracadabar",{"Apportez 4 Ragoûts nordiques et une Cruche de vin de la Fromagerie de Dalaran à Arille Mirazur à l'Abracadabar sur la Place Tisserune à Dalaran."}}
D[13114] = {"Le ragoût des égouts",{"Cuisinez 4 Carottes du Chant de cristal de la Forêt du Chant de cristal avec 4 Viandes glacées dans la Marmite.","","Puis apportez le Ragoût de légumes à Ajay Green, l'Aubergiste des égouts de Dalaran."}}
D[13115] = {"Du fromage pour Froncelor",{"Combinez le Plateau à fromages avec un Vieux limbourg de Dalaran provenant de la fromagerie « Un dernier pour la route » et avec 6 Verres de vin à moitié pleins trouvés sur des tables à Dalaran.","","Apportez le Plateau de vin et de fromages à Ranid Froncelor chez les Tanneurs de peaux à la Halle des mages."}}
D[13116] = {"Hot-dogs à la moutarde !",{"Remplissez le Panier à pique-nique vide avec 4 Saucisses de rhinocéros que vous avez cuisinées avec votre compétence et 4 Moutardes sauvages que vous trouverez dans les zones herbeuses de Dalaran.","","Apportez le Panier à pique-nique à l'Archimage Pentarus à l'Aire de Krasus à Dalaran."}}
D[13117] = {"D'où viennent-ils ?",{"Enquêtez sur un Autel d'invocation dans la zone est de la Charognerie, puis retournez faire votre rapport à la Cavalière noire Arly au Guet noir."}}
D[13118] = {"La purification de Fléaulme",{"Le Gardien d'ébène, de la Vallée des Échos dans la Couronne de glace, vous demande de tuer 3 Grands prêtres des profondeurs oubliées, 3 Sous-rois des profondeurs oubliées et 8 Croisés réanimés."}}
D[13119] = {"Détruire les autels",{"Tuez le Maître invocateur Zarod et utilisez son Bâton d'invocation pour détruire le Premier autel d'invocation, le Deuxième autel d'invocation, le Troisième autel d'invocation et le Quatrième autel d'invocation. Une fois la tâche terminée, retournez voir la Cavalière noire Arly au Guet noir."}}
D[13120] = {"Le regard de la mort",{"Utilisez l'Orbe du regard de la mort pour placer des orbes sur le Socle de l'orbe du laboratoire des abominations, sur le Socle de l'orbe du laboratoire des géants de chair et sur le Socle de l'orbe de la zone du chaudron, puis retournez voir la Cavalière noire Arly au Guet noir."}}
D[13121] = {"À travers l'Œil",{"La Sorcière des ossements, à Njorndar, vous a demandé d'utiliser l'Œil du roi-liche pour obtenir des informations."}}
D[13122] = {"La pierre du Fléau",{"Le Gardien d'ébène, de la Vallée des Échos dans la Couronne de glace, vous a demandé de lui apporter 15 Pierres du Fléau."}}
D[13123] = {"WotLK Collector's Edition: - DEM - E - FLAG"}
D[13124] = {"La lutte continue",{"Raelorasz veut que vous pénétriez dans l'Oculus et que vous sauviez Belgaristrasz et ses compagnons."}}
D[13125] = {"L'air est immobile",{"Le Gardien d'ébène, de la Vallée des Échos dans la Couronne de glace, vous a demandé de tuer Salranax le Tranche-chair, le Sous-roi Talonox et le Grand prêtre Yath'amon."}}
D[13126] = {"Un front uni",{"Belgaristrasz veut que vous tuiez 10 Assemblages centrifuges pour détruire le Bouclier de Varos. Vous devez ensuite détruire Varos Arpentenuée."}}
D[13127] = {"Le seigneur-mage Urom",{"Belgaristrasz veut que vous triomphiez du Seigneur-mage Urom dans l’Oculus."}}
D[13128] = {"Une petite chance de réussir",{"Belgaristrasz veut que vous tuiez Eregos dans l'Oculus. Présentez-vous ensuite à Raelorasz au Bouclier Transitus à Frimarra."}}
D[13129] = {"Manipulation",{"Kurzel veut que vous utilisiez le Morceau de chemise de Kurzel sur le corps de Novos l’Invocateur, puis que vous remettiez le Tissu souillé d’ichor à Mack."}}
D[13130] = {"La pierre qui lança une révolution",{"L'Architecte de la croisade Silas, de la Vallée des Échos dans la Couronne de glace, vous demande de récupérer 10 Troncs de Cœur-du-bois cristallins et 10 morceaux de Pierres de construction elfique."}}
D[13131] = {"Des rebuts dans ma malle",{"Brigg, à la Cime d'Utgarde, vous a demandé de lui apporter 5 Barres d'argent immaculées, 3 Verroteries rutilantes, 2 Coupes dorées et une Statue en jade."}}
D[13132] = {"La vengeance sera mienne !",{"Brigg, à la Cime d'Utgarde, vous a demandé de tuer le Roi Ymiron."}}
D[13133] = {"Trouver l'ancien héros",{"La Sorcière des ossements, à Njorndar, veut que vous lui rameniez Iskalder."}}
D[13134] = {"Répandre leur sang"}
D[13135] = {"Elle pourrait nous tuer tous",{"L'Ingénieur de la croisade Spitzpatrick, de la Vallée des Échos dans la Couronne de glace, vous a demandé de récupérer 8 morceaux d'Énergie cristallisée."}}
D[13136] = {"Éclats dentelés"}
D[13137] = {"Combat pas-si-honorable-que-ça",{"La Sorcière des ossements, à Njorndar, vous demande de vaincre Iskalder sur la Flèche de la Balafre."}}
D[13138] = {"Je fonds… Je fonds!"}
