D[13214] = {"Du rififi au Valhalas : héros défunts",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre, au cours d'un même combat 6 Héros défunts : Eldreth, Geness Demi-Âme, Jhadras, Masud, Rith et Talla.","","Si vous réussissez, parlez à Gjonner le Sans-merci surveillant le rebord sud du Valhalas."}}
D[13215] = {"Du rififi au Valhalas : Khit'rix le Maître ténébreux",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre Khit'rix le Maître ténébreux.","","Si vous réussissez, parlez à Gjonner le Sans-merci surveillant le rebord sud du Valhalas."}}
D[13216] = {"Du rififi au Valhalas : le retour de Sigrid Née-de-glace",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre Sigrid Née-de-glace.","","Si vous réussissez, parlez à Gjonner le Sans-merci surveillant le rebord sud du Valhalas."}}
D[13217] = {"Du rififi au Valhalas : Carnage !",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre Carnage.","","Si vous réussissez, parlez à Gjonner le Sans-merci surveillant le rebord sud du Valhalas."}}
D[13218] = {"Du rififi au Valhalas : Thane « le Coup de grâce »",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre le Thane Banahogg, le Coup de grâce.","","Si vous réussissez, parlez à Gjonner le Sans-merci, surveillant le rebord sud du Valhalas."}}
D[13219] = {"Du rififi au Valhalas : l'ultime défi",{"Geirrvif, au Valhalas, vous a mis au défi de vaincre le Prince Sandoval.","","Si vous réussissez, parlez à Gjonner le Sans-merci, qui surveille le rebord sud du Valhalas."}}
