D[13221] = {"Je ne suis pas encore mort!"}
D[13222] = {"La défense du siège",{"Le Démolisseur en chef Legoso, à la Forteresse de Joug-d'hiver, vous demande de piloter ou de protéger un engin de siège pendant qu'il détruit trois structures.","","Les joueurs ayant un grade de soldat ou supérieur peuvent construire des engins de siège dans les Ateliers gobelins."}}
D[13223] = {"La défense du siège",{"Le Lieutenant Murp, à Joug-d'hiver, vous demande de défendre ou de piloter un véhicule de siège tandis que ce dernier détruit trois structures de l'Alliance.","","Les machines de siège peuvent être construites par des personnages-joueurs de la Horde gradés, dans les Ateliers gobelins."}}
D[13224] = {"Le Marteau d'Orgrim",{"Retrouvez le Saccageur-des-cieux Korm Noire-balafre à bord du Marteau d'Orgrim, qui survole la Couronne de glace."}}
D[13225] = {"Le Brise-ciel",{"Retrouvez le Grand capitaine Justin Bartlett à bord du Brise-ciel survolant la Couronne de glace."}}
