D[13228] = {"Le Front brisé",{"Korm Noire-balafre, sur le Marteau d'Orgrim, vous demande d'aller au Front brisé et de questionner un Berserker mourant pour apprendre ce qui s'est passé là-bas."}}
D[13229] = {"Je ne suis pas encore mort!"}
D[13230] = {"Vengez-moi !",{"Un Berserker mourant vous a demandé de tuer 5 Soldats mourants au Front brisé. Présentez-vous au Saccageur-des-cieux Korm Noire-balafre à bord du Marteau d'Orgrim une fois que c'est fait."}}
D[13231] = {"Le front brisé",{"Le Grand capitaine Justin Bartlett, à bord du Brise-ciel, vous demande d'aller au Front brisé et de questionner un Soldat mourant, puis de retourner lui faire votre rapport."}}
D[13232] = {"Achevez-moi !",{"Un Soldat mourant, au Front brisé, vous demande de tuer 5 Soldats mourants, puis de faire votre rapport au Grand capitaine Justin Bartlett, à bord du Brise-ciel."}}
D[13233] = {"Pas de pitié !",{"Le Grand capitaine Justin Bartlett, à bord du Brise-ciel, vous demande de tuer 15 personnages-joueurs de la Horde dans la Couronne de glace."}}
D[13234] = {"Faites-les payer !",{"Le Saccageur-des-cieux Korm Noire-balafre vous demande de tuer 15 personnages-joueurs de l'Alliance dans la Couronne de glace."}}
D[13235] = {"Le champion des géants de chair"}
D[13236] = {"L'armée des damnés"}
D[13237] = {"Titiller l'ennemi",{"Koltira Tissemort, à bord du Marteau d'Orgrim, vous demande de vous rendre au Front brisé et de vaincre 5 Abominations massives, 5 Nécromanciens maléfiques et 5 Adeptes des ombres."}}
D[13238] = {"Bon à quelque chose ?",{"Le Saccageur-des-cieux Korm Noire-balafre vous demande de parler à l'Ingénieur en chef Cuivregrif à bord du Marteau d'Orgrim."}}
D[13239] = {"Volatilité",{"L'Ingénieur en chef Cuivregrif vous demande d'utiliser l'Huile volatile de Cuivregrif au Front brisé pour attirer 3 Serre-du-ciel couvegivres.","","Pour utiliser l'huile, vous devez récupérer une Pile d'ossements, un Heaume abandonné et une Armure abandonnée sur le champ de bataille où vous vous trouvez."}}
D[13240] = {"Timear prédit des assemblages centrifuges dans votre avenir !",{"L'Archimage Timear à Dalaran a prédit que vous détruirez 10 Assemblages centrifuges."}}
D[13241] = {"Timear voit des berserkers ymirjar dans votre avenir !",{"Vous effectuez cette quête"}}
D[13242] = {"Les ténèbres s'agitent",{"Récupérez l'Armure de bataille de Saurcroc sur le champ de bataille et rapportez-la au Haut seigneur Saurcroc au Bastion Chanteguerre dans la Toundra Boréenne."}}
D[13243] = {"Timear prédit des agents infinis dans votre avenir !",{"L'Archimage Timear à Dalaran a prédit que vous tuerez 4 Agents infinis."}}
D[13244] = {"Timear prédit des avant-gardes en titane dans votre avenir !",{"L'Archimage Timear à Dalaran a prédit que vous tuerez 7 Avant-gardes en titane."}}
