D[351] = {"Найди КПХ-17/TN!",{"Отнесите аварийный маяк к автономному роботу Карлса."}}
D[353] = {"Посылка для Грозовой Вершины",{"Доставьте посылку горному пехотинцу Грозовой Вершине в Лок Модан."}}
D[354] = {"Смерти в семье",{"Принесите останки Грегора, останки Ниссы и останки Турмана Колману Фартингу в Брилл."}}
D[355] = {"Разговор с Севреном",{"Поговорите с мировым судьей Севреном в Брилле."}}
D[356] = {"Патруль в арьергарде",{"Убейте 8 кровоточащих ужасов и 8 странствующих духов, а потом доложите о своих успехах Линнее, ожидающей вас в своем лагере."}}
