D[1016] = {"Браслеты элементалей",{"Соберите 5 неповрежденных браслетов элементалей, а затем задействуйте на них божественный свиток. После отнесите разгаданный свиток Стражу Велене Звездный Всполох в Приют Серебряного Ветра."}}
D[1017] = {"Маг-призыватель",{"Убейте Сарилуса Грязнорожденного и принесите его голову часовому Велене Звездный Всполох в Приют Серебряного Ветра."}}
D[1018] = {"Новое пограничье",{"Обратитесь к верховному друиду Хамуулу Руническому Тотему на Вершине Старейшин Громового Утеса по поводу помощи Кругу Кенария в исследовании границ Калимдора."}}
D[1019] = {"Новое пограничье",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора."}}
D[1020] = {"Лекарство Орендила",{"Принесите лекарство Орендила Пельтуру Белой Луне в Астранаар."}}
D[1021] = {"Сатиры коварны! Дриады в опасности!",{"Найдите Анилию в Ксавиане, что в Ясеневом лесу."}}
D[1022] = {"Воющая долина",{"Отправляйтесь в Воющую Долину, изучите фолиант Мел'Тандрис, затем возвращайтесь к часовому Мелирии Ледяной Тени в Лесную Песнь."}}
D[1023] = {"Раэна – санитар Ясеневого леса",{"Найдите светящийся самоцвет и вернитесь к Раэне Волкопас в Астранаар с дневником Терониса."}}
D[1024] = {"Раэна – санитар Ясеневого леса",{"Найдите Шаэл'дрин у лунного колодца на северо-востоке."}}
D[1025] = {"Лучшая защита – нападение",{"Убейте 1 дозорного, 2 ведмедей, 10 тотемистов и 12 воинов из племени Гиблой Чащи, а затем вернитесь к Раэне Волкопас в Астранаар."}}
D[1026] = {"Раэна – санитар Ясеневого леса",{"Найдите деревянный ключ и обломок жезла Дартола прежде, чем вернуться к Шаэл'дрин у Лунного колодца."}}
D[1027] = {"Раэна – санитар Ясеневого леса",{"Найдите последний фрагмент жезла Дартола и вернитесь к Шаэл'дрин у Лунного колодца."}}
D[1028] = {"Раэна – санитар Ясеневого леса",{"Найдите потаенное святилище и снова наполните чарами жезл Дартола."}}
D[1029] = {"Раэна – санитар Ясеневого леса",{"Вернитесь к Раэне Волкопас в Астранаар."}}
D[1030] = {"Раэна – санитар Ясеневого леса",{"Найдите не затронутого порчей фурболга и поговорите с ним при помощи жезла преображения Дартола."}}
D[1031] = {"Ветвь Кенария",{"Убейте Гелтариса и верните Ветвь Кенария Иллиане в Лесную Песнь."}}
D[1032] = {"Убийство сатиров!",{"Принесите 16 рогов сатиров Иллиане в Лесную Песнь."}}
D[1033] = {"Слеза Элуны",{"Принесите Слезу Элуны Пельтуру в Астранаар."}}
D[1034] = {"Руины Звездной Пыли",{"Принесите 5 горстей звездной пыли Пельтуру в Астранаар."}}
D[1035] = {"Зеркало Небес",{"Отнимите лунный камень Упавшего Неба у Чащобного Оракула и принесите его Пельтуру в Астранаар."}}
D[1036] = {"Суши весла, сухопутная крыса",{"Поговорите с командиром флота Фираллоном на борту \"Кровавой завесы\" на побережье Тернистой долины."}}
D[1037] = {"Велинда Песнь Звезд",{"Поговорите с Тин'тель Танцем Клинка на террасе Воинов в Дарнасе."}}
D[1038] = {"Эффекты Велинды",{"Поищите в сундуке Велинды ее дневник, затем принесите его вместе с ключом Тинтэль Танцующий Клинок в Дарнас."}}
D[1039] = {"Порт в Степях",{"Поговорите с управляющим пристанью Головокружилкинсом в Кабестане, что в Степях."}}
D[1040] = {"Дорога до Пиратской Бухты",{"Плывите в Пиратскую Бухту и поговорите с караванщиком Раззготом."}}
D[1041] = {"Путь каравана",{"Поговорите с клерком Далтри из Темнолесья."}}
D[1042] = {"Семья Карвин",{"Поговорите с Джонатаном Карвином в Темнолесье."}}
D[1043] = {"Коса Элуны",{"Отыщите признаки местонахождения Косы Элуны и вернитесь к Джонатану Карвину в Темнолесье."}}
D[1044] = {"Полученные ответы",{"Вернитесь к Тин'тель Танцу Клинка в Дарнас."}}
D[1045] = {"Раэна – санитар Ясеневого леса",{"Убейте Рэна Кровавого Клыка, 4 кровозубых стражей и принесите череп Рэна Кролгу у озера Мистраль."}}
D[1046] = {"Раэна – санитар Ясеневого леса",{"Принесите череп Рэна Кровавого Клыка Раэне Волкопас в Астранаар."}}
D[1047] = {"Новое пограничье",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом из дарнасского анклава Кенария относительно призыва Круга Кенария к изучению окраин Калимдора."}}
D[1048] = {"В монастырь Алого ордена",{"Kill High Inquisitor Whitemane, Scarlet Commander Mograine, Herod, the Scarlet Champion and Houndmaster Loksey and then report back to Varimathras in the Undercity."}}
D[1049] = {"\"Компендиум павших\"",{"Добудьте \"Компендиум павших\" из монастыря в Тирисфальских лесах и возвращайтесь к Ведуну Искателю Истины в Громовой Утес."}}
D[1050] = {"\"Мифология Титанов\"",{"Добудьте \"Мифологию Титанов\" из монастыря и принесите ее библиотекарю Мае Белокожке в Стальгорн."}}
D[1051] = {"Месть Воррела",{"Верните обручальное кольцо Воррела Сенгутца Монике Сенгутц в Мельнице Таррен."}}
D[1052] = {"По пути Алого ордена",{"Отнесите рекомендательное письмо брата Антона Ролею Благочестивому в Южнобережье."}}
D[1053] = {"Во имя Света!",{"Убейте Верховного инквизитора Вайтмейн, командира Могрейна из Алого ордена, воителя Ирода из Алого ордена и псаря Локси, после этого вернитесь с докладом к Ролею Благочестивому в Южнобережье."}}
D[1054] = {"Устранение угрозы",{"Принесите череп Дала Жилотяга Раэне Волкопас в Астранаар."}}
D[1055] = {"Раэна – санитар Ясеневого леса",{"Вернитесь к Шаэл'дрин у лунного колодца."}}
D[1056] = {"Путешествие к Пику Каменного Когтя",{"Отправляйтесь к хранителю Албагорму на Пик Каменного Когтя."}}
D[1057] = {"Возвращение Горелой Долины",{"Хранитель Албагорм с Пика Каменного Когтя просит вас убить 7 гарпий, 7 душительниц, 7 душегубок и 7 бродяжниц из стаи Кровавой Ярости."}}
D[1058] = {"Лесная магия Джин'Зила",{"Знахарь Джин'Зил из Малака'джина требует принести 5 порций слизи Каменного когтя, 5 сумеречных усиков, 30 глаз бегового оленя и чешуйку волшебного дракончика."}}
D[1059] = {"Возвращение Обугленной долины",{"Отправляйтесь к Фалфиндеру Хранителю Дорог, живущему на границе Тысячи Игл и Фераласа."}}
D[1060] = {"Письмо Джин'Зилу",{"Отнесите письмо Дарсока Джин'Зилу в пещеру Малака'джин в Когтистых горах."}}
D[1061] = {"Духи Каменного Когтя",{"Поговорите с Сирит Камнелом на границе Когтистых гор и Степей."}}
D[1062] = {"Вторжение гоблинов",{"Убейте 15 лесорубов Торговой Компании, затем вернитесь к Сирет Камнелом на границу Каменного Когтя и Степей."}}
D[1063] = {"Мудрая старуха",{"Поковорите с Магатой в Громовом Утесе."}}
D[1064] = {"Помощь Отрекшихся",{"Поговорите с аптекаршей Замой у Прудов Видений в Громовом Утесе."}}
D[1065] = {"Путешествие в Мельницу Таррен",{"Принесите записку Замы аптекарю Лидону в Мельницу Таррен."}}
D[1066] = {"Невинная кровь",{"Принесите 5 фиалов крови невинных аптекарю Лидону в Мельницу Таррен."}}
D[1067] = {"Возвращение в Громовой Утес",{"Отнесите отраву Лидона аптекарю Заме в Громовой Утес."}}
D[1068] = {"Механические измельчители",{"Уничтожьте шреддеры XT:4 и XT:9, затем вернитесь к Сирит Камнелом на границу Когтистых гор и Степей."}}
D[1069] = {"Яйца мохового паука",{"Принесите Мебоку Миззриксу из Кабестана 15 яиц мохового паука."}}
D[1070] = {"На страже в Когтистых горах",{"Найдите Келу Копье Тени, которая наблюдает за долиной, выходящей к Утесу Ветрорезов в Когтистых горах."}}
D[1071] = {"Отсрочка для гнома",{"Убейте 10 лесорубов и 10 лесозаготовителей Торговой Компании и вернитесь к Гаксиму Ржавошиппи в Каменный Коготь."}}
D[1072] = {"Старый коллега",{"Поговорите с Ломаком Демонтирсом в Стальгорне."}}
D[1073] = {"Неумение + реактивы = потеха!",{"Принесите 4 крохотных флакона с зельем маны и 2 слабых эликсира стойкости Ломаку Демонтирсу в Стальгорн."}}
D[1074] = {"Неумение + реактивы = потеха!",{"Отнесите нитромирглицероний Гаксиму Ржавошиппи в Каменный Коготь."}}
D[1075] = {"Свиток от Маурена",{"Найдите в Штормграде Коллина Маурена."}}
D[1076] = {"Демоны в Западном Крае",{"Принесите прах Пыледемона Коллину Маурену в Штормград."}}
D[1077] = {"Особая посылка для Гаксима",{"Отнесите свиток с посланием Гаксиму Ржавошиппи в Каменный Коготь."}}
D[1078] = {"Поиск для Маурена",{"Принесите 8 кристаллических чешуй Коллину Маурену в Штормград."}}
D[1079] = {"Секретная операция – Альфа",{"Добудьте технические чертежи Торговой Компании с лесопилки на Утесе Ветрорезов."}}
D[1080] = {"Секретная операция – Бета",{"Добудьте документы Торговой Компании из Рудника Ветрорезов у восточного края Утеса Ветрорезов."}}
D[1081] = {"Приглашение от Тиранды",{"Найдите в Дарнасе Тиранду Шелест Ветра."}}
D[1082] = {"Новости для часового Тенисил",{"Вернитесь к часовому Тенисил в Ясеневый лес."}}
D[1083] = {"Разъяренные духи",{"Принесите 8 тлеющих углей от любых элементалей огня из Обугленной долины Келе Копье Тени в Когтистые горы."}}
D[1084] = {"Раны Дерев",{"Принесите образец ржавой шрапнели Келе Копье Тени в Каменный Коготь."}}
D[1085] = {"На страже в Когтистых горах",{"Поговорите с Гаксимом в Когтистых горах."}}
D[1086] = {"Аэропорт ветролетов",{"Отнесите распылитель ядовитого тумана в аэропорт Торговой Компании и вернуться к аптекарю Заме."}}
D[1087] = {"Наследие Кенария",{"Убейте 4 сыновей Кенария, 4 дочерей Кенария и 4 кенарийских ботаников по поручению Брайлин Огненной Длани из Приюта у Солнечного Камня."}}
D[1088] = {"Ордан",{"Принесите голову Ордана Брайлин Огненной Длани к Приюту у Солнечного Камня."}}
D[1089] = {"Логово",{"Отправляйтесь к пещере на Пике Каменного Когтя. При помощи Ключа Хранителя Врат добудьте предметы, спрятанные друидами. Используйте эти предметы для того, чтобы открыть сокровищницу Логова Когтя."}}
D[1090] = {"Приказы Геренцо",{"Возьмите образец загадочной руды у Пузника после того, как он ее добудет."}}
D[1091] = {"Новости для Каэлы",{"Отнесите документы Торговой Компании Келе Копье Тени в Когтистые горы."}}
D[1092] = {"Приказы Геренцо",{"Доставьте Неопознанную Руду Зизу Физзиксу в Когтистые горы."}}
D[1093] = {"Супер-дровосек 6000",{"Добудьте чертежи \"Супер-дровосека 6000\" для Зиза Физзикса с Когтистых гор."}}
D[1094] = {"Дальнейшие указания",{"Доставьте запечатанный конверт Пароклапану в Кабестан, что в Степях."}}
D[1095] = {"Дальнейшие указания",{"Отнесите Зизу Физзиксу в Когтистых горах новые приказы."}}
D[1096] = {"Геренцо Терминатрикс",{"Принесите механическую руку Геренцо Терминатрикса Зиззу Физзиксу в Когтистые горы."}}
D[1097] = {"Просьба Элмора",{"Поговорите с Гримандом Элмором в Штормграде."}}
D[1098] = {"Пропавшие стражи смерти",{"Найдите стражей смерти Адаманта и Винсента."}}
D[1099] = {"Гоблины победили!"}
D[1100] = {"Дневник Хмурня",{"Прочитайте дневник Хенрига Хмурня."}}
D[1101] = {"Хозяйка Лабиринтов",{"Принесите медальон Чарлги Остробок Фалфиндеру Хранителю Путей в Таланааре."}}
D[1102] = {"Отмщение грядет!",{"Принесите сердце Чарлги Остробок Ольду Каменному Копью в Громовой Утес."}}
D[1103] = {"Зов воды",{"Принесите Тьеву Мордуну, который находится в Серебряном бору, сапту воды, если вам не удалось поговорить с низшим воплощением воды."}}
D[1104] = {"Яд Соляных равнин",{"Принесите 6 порций соленого яда скорпида Пшиксу Медноштифу на Мерцающую равнину."}}
D[1105] = {"Крепкие панцири",{"Принесите 9 крепких черепашьих панцирей Виззлу Медноштифу на Мерцающую равнину."}}
D[1106] = {"Мартек Изгой",{"Отнесите письмо Пшикса Мартеку Изгою в Бесплодные земли."}}
D[1107] = {"Средство против трения",{"Принесите 10 соленых хвостовых плавников Виззлу Медноштифту на Мерцающую равнину."}}
D[1108] = {"Индарилий",{"Принесите 10 пластин индарилия Мартеку Изгою в Бесплодные земли."}}
D[1109] = {"Груды гуано",{"Принесите 1 кучку гуано летучей мыши Лабиринтов мастеру-аптекарю Фаранеллу в Подгород."}}
D[1110] = {"Обломки болидов",{"Принестие 30 деталей болида Кравелу Углебороду на Мерцающую равнину."}}
D[1111] = {"Управляющий пристанью Головокружилкинс",{"Отнесите заказ на детали Крейвела управляющему пристанью Головокружилкинcу в Кабестан, что в Степях."}}
D[1112] = {"Детали для Крейвела",{"Отнесите Кравелу Углебороду его детали на Мерцающую равнину, что в Тысяче Игл."}}
D[1113] = {"Сердца Доблести",{"Мастер-аптекарь Фаранелл из Подгорода просит принести ему 20 сердец Доблести."}}
D[1114] = {"Заказ гномов",{"Отнесите хрупкие детали машины Пшиксу Медноштифу на Мерцающую равнину."}}
D[1115] = {"Сплетник",{"Поговорите с Кразеком в Пиратской Бухте, что в Тернистой долине."}}
D[1116] = {"Сонная пыль в болоте",{"Принесите 10 щепоток сонной пыли Кразеку в Пиратскую Бухту. Сонную пыль можно собрать с дракончиков на Болоте Печали."}}
D[1117] = {"Сплетни для Крейвела",{"Отнесите письмо с гоблинскими сплетнями Кравелу Углебороду на Мерцающую равнину, что в Тысяче Игл."}}
D[1118] = {"Назад в Пиратскую Бухту",{"Отнесите план Крейвела Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине."}}
D[1119] = {"Смесь Занзила и \"Дурацкое Крепкое\"",{"Отнесите \"Дурацкое Крепкое\" Крейвелу на Мерцающую равнину, что в Тысяче Игл."}}
D[1120] = {"Напоить гномов",{"Отнесите \"Дурацкое Крепкое\" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл."}}
D[1121] = {"Напоить гоблинов",{"Отнесите \"Дурацкое Крепкое\" начальнику гномского гаража в поселок Виражи на Миражах, что в Тысяче Игл."}}
D[1122] = {"Возвращение к Пуззыриксу",{"Отнесите отчет о \"Дурацком Крепком\" Шиззи Пуззыриксу в Пиратскую Бухту, что в Тернистой долине."}}
D[1123] = {"Рабин Сатурна",{"Поговорите с Рабином Сатурной в селении Ночная Гавань на Лунной поляне. Лунная поляна находится между Оскверненным лесом и Зимними Ключами, туда можно добраться по дороге, идущей от крепости Древобрюхов."}}
D[1124] = {"Пустошь",{"Поговорите с Лайо Зведным Всполохом близ кладбища Погост Отважных в Силитусе и покажите ему письмо Рабина."}}
D[1125] = {"Духи Южного Ветра",{"Освободите в деревне Южного Ветра души 8 истерзанных друидов и 8 истерзанных часовых и вернитесь к Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных."}}
D[1126] = {"Улей в башне",{"Осмотрите башню деревни Южного Ветра и отыщите способ разворошить улей. Принесите все необычное, что попадется при выполнении задания Лайо Звездному Всполоху на кладбище Силитуса, Погост Отважных."}}
D[1127] = {"\"Дурацкое Крепкое\"",{"Принесите 12 порций смеси Занзила Шиззи Пуззыриксу в Пиратскую Бухту."}}
D[1130] = {"Весть от Мелора",{"Поговорите с Мелором Каменным Копытом в Громовом Утесе."}}
D[1131] = {"Сталезуб",{"Принесите ребро Сталезуба Мелору Каменному Копыту в Громовой Утес."}}
