D[3221] = {"Беседа с Ренферрелом",{"Поговорите с аптекарем Ренферрелом в Гробнице."}}
D[3261] = {"Джорн Небесный Провидец",{"Поговорите с Джорном Заклинателем Небес в Лагере Таурахо."}}
D[3281] = {"Похищенное серебро",{"Принесите украденное серебро Газрогу в Перекресток."}}
D[3301] = {"Муура Рунический Тотем",{"Поговорите с Муурой Руническим Тотемом в Гробнице, что в Серебряном бору."}}
D[3321] = {"Не ее ли ищете?",{"Дождитесь, пока Трентон закончит работу."}}
D[3341] = {"Да сгинет Хладовей",{"Эндрю Браунелл поручил вам убить Амненнара Хладовея и принести его череп."}}
D[3361] = {"Беда беженца",{"Принесите в Старую Наковальню ларец Феликса, сундук Феликса и ведро с винтиками и вручите все это Феликсу."}}
D[3362] = {"Долина Кактусов",{"Тран'рек из Прибамбасска просит вас убить 8 бугристых шипошкуров и 8 корнеплетов из долины Кактусов."}}
D[3363] = {"Оскверненный песнецвет"}
D[3364] = {"Жгучая бражка",{"Отнесите жгучую бражку в Старую Наковальню и передайте ее Дарнану Мехорезу, пока она не остыла!"}}
D[3365] = {"Возвращение кружки",{"Отнесите кружку хозяину – Нори по прозвищу Гордый Штрек. Он обитает в Холодной долине."}}
D[3366] = {"Светящийся осколок",{"Отправляйтесь в Кабестан и выясните, какие секреты скрывает кристалл кошмаров."}}
D[3367] = {"Камни Сунтары",{"Помогите Дориусу вернуться в Стальгорн."}}
D[3368] = {"Камни Сунтары",{"Доставьте опаленное письмо Ториусу в Стальгорн. Его можно найти в Зале Исследователей."}}
D[3369] = {"Кошмары",{"Принесите осколок кошмара Хамуулу Руническому Тотему на Вершине Старейшин."}}
D[3370] = {"Кошмары",{"Принесите осколок кошмара Матренгилу Медвежьей Лапе в Дарнас."}}
D[3371] = {"Правосудие дворфов",{"Вернитесь в Тлеющее ущелье и найдите археологов Дориуса."}}
D[3372] = {"Отпусти их",{"Найдите таинственный артефакт, охраняемый идолослужителями Сумеречного Молота в северо-западной области Тлеющего ущелья и возложите его на алтарь Сунтары в Шлаковой Яме."}}
D[3373] = {"Сущность Эраникуса",{"Поместите сущность Эраникуса в купель сущности в его логове в затонувшем храме."}}
D[3374] = {"Сущность Эраникуса",{"Принесите камень Клятвы драконьего выводка Изеры и скованную сущность Эраникуса на Болото Печали. Там вам придется сделать выбор: помогать Драконам Изеры или нет."}}
D[3375] = {"Запасной фиал",{"Принесите зелье маны, уголь и сладкий нектар Талвашу дель Кисселю в Стальгорн, чтобы получить запасной фиал виденья Талваша."}}
D[3376] = {"Сразить Остроклыка!",{"Принесите голову вождя Остроклыка Терновой Мантии Храбрецу Перу Ветра на плато Красного Облака."}}
D[3377] = {"Молитва Элуне",{"Выслушайте Зимаэля."}}
D[3378] = {"Молитва Элуне",{"Найдите молитву Элуне и принесите ее Астарии Ловцу Звезд в Дарнас."}}
D[3379] = {"Мастер по тенеткани",{"Убейте банду похитителей тенешелка, хозяйничающую в Тлеющем ущелье. Нилит полагает, что их пятеро. Вернитесь к Нилит по выполнению задания."}}
D[3380] = {"Затонувший храм",{"Найдите Марвона Клепальщика в Танарисе."}}
D[3381] = {"Встреча с господином",{"Принесите 2 неповрежденных пера гиппогрифа Санату Лим-Йо в в Азшару, если хотите говорить с его господином."}}
D[3382] = {"На абордаж!",{"Защитите капитана Ванессу Белтис, ее команду и пассажиров \"Покорителя Горизонтов\" от нападения наг. Капитан Ванесса Белтис должна выжить."}}
D[3385] = {"Черный рынок",{"Убейте торговца Ковица и его прихвостня Лязгуна. Снимите с тела сумку и вернитесь к Нилит."}}
D[3402] = {"Черный рынок",{"Поговорите с Визгликом в Прибамбасске."}}
D[3421] = {"Возвращение"}
D[3441] = {"Божественное воздаяние",{"Выслушайте Веларока Ветрореза."}}
D[3442] = {"Неугасимое пламя",{"Принесите 4 сердца пламени и 4 меры масла големов Велароку Ветрорезу."}}
D[3443] = {"Древко факела",{"Принесите 8 окованных торием кинжалов Велароку Ветрорезу."}}
D[3444] = {"Круглый камень",{"Заберите круглый камень из мастерской Марвона Клепальщика в Кабестане."}}
D[3445] = {"Затонувший храм",{"Найдите Марвона Клепальщика в Танарисе."}}
D[3446] = {"Во глубине болот",{"Найдите алтарь Хаккара в затонувшем храме на Болоте Печали."}}
D[3447] = {"Тайна камня",{"Отправляйтесь в затонувший храм и узнайте, что скрывается в круге статуй."}}
D[3448] = {"Передача поручения",{"Поговорите с Тимором в Стальгорне."}}
D[3449] = {"Чародейские руны",{"При помощи готовальни сделайте прорисовки руны Бет'Амары, руны Джин'йаэль, руны Маркри и руны Саэл'Хаи. Отправляйтесь на маленький островок близ южного полуострова Азшары и дайте сигнал пилоту Зиггсу Зажигателю забрать их."}}
D[3450] = {"Легкая доставка",{"Поговорите с Зиггсом Зажигателем в Стальгорне."}}
D[3451] = {"Сигнал \"Взять на борт!\"",{"Поговорите с Хиггсом Зажигателем в Стальгорне и получите от него сигнальное ружье."}}
D[3452] = {"Защита пламени",{"Найдите знак Рагнароса и принесите его Велароку Ветрорезу."}}
D[3453] = {"Факел воздаяния",{"Подождите, пока Веларок Ветрорез закончит факел воздаяния."}}
D[3454] = {"Факел воздаяния",{"Возьмите факел воздаяния."}}
D[3461] = {"Возвращение к Тимору",{"Принесите Тимору его готовальню назад в Стальгорн."}}
D[3462] = {"Оруженосец Малтрейк",{"Поговорите с оруженосцем Малтрейком."}}
D[3463] = {"Задай им жару!",{"Подожгите северную, южную, восточную и западную сторожевые башни с помощью факела воздаяния."}}
D[3481] = {"Безделушки...",{"Открыть сундук."}}
D[3482] = {"<NYI> <TXT> The Pocked Black Box",{"Отнесите ящик Крейвелу."}}
D[3483] = {"Сигнал \"Взять на борт!\""}
D[3501] = {"Счет идет на большие числа",{"Принесите Кум'ише несовершенные фрагменты дренетиста и получите награду за каждый из них."}}
D[3502] = {"Дренейский хлам...",{"Принесите Кум'ише несовершенные фрагменты дренетиста. У любого вида монстров в Выжженных землях могут быть эти фрагменты."}}
D[3503] = {"Встреча с господином"}
D[3504] = {"Предательница",{"Отнесите запечатанное письмо Аг'тору Кровопалу в Азшару."}}
D[3505] = {"Предательница",{"Убейте 10 эльфов крови-землемеров и 10 эльфов крови-геодезистов, потом разыщите лагерь волхва Римтори. В лагере найдите что-нибудь важное для мага, из-за чего она могла бы ринуться в бой."}}
D[3506] = {"Предательница",{"Уничтожьте кристалл средоточия чар, связанный с волхвом Римтори, затем убейте ее. Отнесите голову Римтори Аг'тору Кроволапу в Азшаре."}}
D[3507] = {"Предательница",{"Поговорите с Белгромом Каменной Булавой в Оргриммаре."}}
D[3508] = {"Минуя охрану",{"Подождите, пока Лорамус завершит заклинание просветления."}}
D[3509] = {"Имя Зверя",{"Поговорите в Азшаре с лордом Арккоросом. Начните поиски у кромки воды, чтобы найти храм Арккоран."}}
D[3510] = {"Имя Зверя",{"Убейте Хетайру и принесите окровавленную голову Хетайры, разбитую голову Хетайры и покрытую синяками голову Хетайры лорду Арккоросу."}}
D[3511] = {"Имя Зверя",{"Отнесите состав для закалки Лорамусу Многоногу."}}
D[3512] = {"Судя по словам Эраникуса...",{"Отправляйтесь в восточную часть Зимних Ключей и поговорите с Умбрансом Ищущим Духов."}}
D[3513] = {"Свиток с рунами",{"Отнесите свиток с рунами в северную сторожевую башню Степей."}}
D[3514] = {"Мощь Орды",{"Убейте предводительницу Логова Когтя, Ринтариэль Хранительницу Ключей."}}
D[3517] = {"Тайненькое знаньице",{"Найдите таблички Бет'Амары, Джин'яэль, Маркри и Саэль'Хай и принесите их Джедиге в Азшару."}}
D[3518] = {"Доставка Магате",{"Отнесите табличку Бет'Амары Магате в Громовой Утес."}}
D[3519] = {"Друг в беде",{"Поговорите с Диранией Серебряным Сиянием в Тенистой долине."}}
D[3520] = {"Духи крикунов",{"Поймайте души трех крикунов из Фераласа и возвращайтесь к Йе'кинье в Порт Картеля."}}
D[3521] = {"Противоядие для Иверрона",{"Соберите 7 гиацинтовых грибов, 4 лунные лилии и 1 порцию лимфы чащобного тенетника и принесите Дирании Серебряное Сияние в Тенистую долину."}}
D[3522] = {"Противоядие для Иверрона",{"Отнесите противоядие Иверрону, прежде чем оно потеряет свои целебные свойства. Иверрона можно найти около пещеры, что к северу отсюда."}}
D[3523] = {"Плеть в холмах",{"Если вы хотите помочь Белнистразу, поговорите с ним еще раз и верните ему Камень клятвы, который он дал вам."}}
D[3524] = {"Останки на берегу",{"Соберите кости морской твари, выброшенной на берег к югу от Аубердина, и принесите их Гвеннид Блай'Леггонд в Аубердин."}}
D[3525] = {"Уничтожить идола",{"Сопроводите Белнистраза к идолу свинобразов в Курганах Иглошкурых.","","Защищайте Белнистраза, пока он будет проводить ритуал, чтобы разрушить идола."}}
D[3526] = {"Гоблинское инженерное дело",{"Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск."}}
D[3527] = {"Пророчество Мошару",{"Принесите первую и вторую таблички Мошару Йе'кинье в Танарис."}}
D[3528] = {"Бог Хаккар",{"Отнесите заполненное яйцо Хаккара Йе'кинье в Танарис."}}
D[3541] = {"Доставка Джес'римону",{"Отнесите табличку Джин'яэль Джес'римону в Оргриммар."}}
D[3542] = {"Доставка Андрону Ганту",{"Отнесите табличку Маркри Андрону Ганту в Подгород."}}
D[3561] = {"Доставка верховному магу Ксилему",{"Отнесите табличку Саэль'Хай верховному магу Ксилему в Азшару."}}
D[3562] = {"Плата Магаты Джедиге",{"Отнесите записку Магаты Джедиге в Азшару."}}
D[3563] = {"Плата Джес'римона Джедиге",{"Доставьте записку Джес'римона Джедиге в Азшару."}}
D[3564] = {"Плата Андрона Джедиге",{"Доставьте записку Андрона Джедиге в Азшару."}}
D[3565] = {"Плата Ксилема Джедиге",{"Доставь записку Ксилема Джедиге в Азшару."}}
D[3566] = {"Восстань, Обсидион!",{"Убейте Латорика Черного и Обсидиона и принесите голову Латорика и сердце Обсидиона Ториусу в Стальгорн."}}
D[3567] = {"Умный в гору не пойдет..."}
D[3568] = {"Разносчик порчи",{"Наполните все 4 пустых фиала из приливных заводей в руинах Эльдарата и возвращайтесь к химику Карабосу."}}
D[3569] = {"Разносчик порчи",{"Дайте эликсир Карабоса Терсе Песне Ветра в Подгороде."}}
D[3570] = {"Разносчик порчи"}
D[3601] = {"Оскорбленный Ким'джаель",{"Обыщите Талассийское поселение и найдите компас, прицел, плюшевого цыпленка и центробежный растягиватель Ким'джаеля. Верните все это Ким'джаелю в Азшару."}}
D[3602] = {"Азшарит",{"Найдите в южной Азшаре двадцать кристаллов азшарита. Вы можете использовать Гончих Скверны, которые помогут вам \"вынюхивать\" местонахождение хорошо сокрытых залежей.","","Когда задача будет завершена, возвращайтесь к Лорамусу Многоногу."}}
D[3621] = {"Создание отравы Скверны",{"Отнести груз Гальвану Древнему в Тернистую долину."}}
D[3625] = {"Зачарованное азшаритовое оружие, отравленное Скверной",{"Подождите, пока Гальван закончит отковывать оружие."}}
D[3626] = {"Возвращение в Выжженные земли",{"Вернитесь к Павшему герою Орды на Развилку Расщепленного Копья, что на Болоте Печали."}}
D[3627] = {"Воссоединить расколотый амулет",{"Убейте Грола Разрушителя, леди Севину и верховного мага Аллистария. С их трупов заберите Амулет Грола, Амулет Севины и Амулет Аллистария.","","Помните о том, что нужно использовать зачарованное азшаритовое оружие, отравленное Скверной, чтобы ослабить троицу! Их нельзя убить иначе – но используйте оружие разумно..."}}
D[3628] = {"Ты – Рах'лих, демон!",{"Уничтожьте Разелиха Осквернителя и вернитесь к павшему герою Орды с отрубленным рогом Осквернителя. Вам также понадобится вернуть оберег Осквернителя, чтобы павший герой мог уничтожить его, дабы оберег не попал к тому, кто использует его во зло."}}
D[3629] = {"Гоблинское инженерное дело",{"Если вы хотите начать обучение гоблинскому инженерному делу, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск."}}
D[3630] = {"Гномское инженерное дело",{"Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн."}}
