D[3633] = {"Гоблинское инженерное дело",{"Если вы хотите узнать о гоблинском инженерном деле, отнесите cправочник по инженерным дисциплинам Никсу Шепружину в Прибамбасск, что в Танарисе."}}
D[3634] = {"Гномское инженерное дело",{"Если вы хотите узнать больше о гномском инженерном деле, отнесите справочник по инженерным дисциплинам мехмастеру Замыкальцу в Стальгорн."}}
D[3635] = {"Гномское инженерное дело",{"Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту."}}
D[3636] = {"Нести свет",{"Убейте Амненнара Хладовея в Курганах Иглошкурых."}}
D[3637] = {"Гномское инженерное дело",{"Если вы хотите узнать побольше о гномском инженерном деле, возьмите справочник по инженерным дисциплинам и отнесите его Карлсу Пропеллерзу в Пиратскую Бухту."}}
