D[8446] = {"Под покровом кошмара",{"Найдите того, кто сможет осознать значение поглощенного кошмарами предмета.","","Может быть, вам сможет помочь могущественный друид."}}
D[8447] = {"Пробуждение легенд",{"Дождитесь, пока хранитель Ремул с Лунной поляны очистит поглощенный кошмарами предмет."}}
D[8460] = {"Союзник Древобрюхов",{"Гразл желает, чтобы вы заслужили доверие. Вам нужно убить 6 воинов, 6 землепроходцев и 6 садовников из племени Мертвого Леса. Выполнив поручение, возвращайтесь в южную часть Оскверненного леса к Изумрудному святилищу."}}
D[8461] = {"Северные фурболги Мертвого Леса",{"Нафиэн просит вас убить 6 дозорных, 6 мстителей и 6 шаманов из племени Мертвого Леса. По выполнении возвращайтесь на север Оскверненного леса ко входу в крепость Древобрюхов."}}
D[8462] = {"Беседа с Нафиэном",{"Отправляйтесь на север по главной дороге в Оскверненном лесу и поговорите с фурболгом по имени Нафиэн. Он стоит на страже у входа в крепость Древобрюхов."}}
D[8463] = {"Нестабильные кристаллы маны",{"Верните 6 нестабильных кристаллов маны Аэльдону Озаренному Солнцем на площади Соколиных Крыльев."}}
D[8464] = {"Боевые действия в деревне Зимней Спячки",{"Убейте 8 шаманов, 8 дозорных и 8 ведмедей из племени Зимней Спячки по просьбе Сальфы. Он ждет у входа в Крепость Древобрюхов в Зимних Ключах."}}
D[8465] = {"Разговор с Сальфой",{"Пройдите через Крепость Древобрюхов и выйдите к Зимним Ключам. Поговорите с Сальфой, который стоит на страже у входа в Крепость Древобрюхов."}}
D[8466] = {"Перья для Гразла"}
D[8467] = {"Перья для Нафиэна"}
D[8468] = {"Разыскивается: Таэлис Ненасытный",{"Принесите голову Таэлиса сержанту Ка'рену на площадь Соколиных Крыльев в лесах Вечной Песни."}}
D[8469] = {"Бусы для Сальфы"}
D[8470] = {"Ритуальный тотем Мертвого Леса",{"Отнесите ритуальный тотем Мертвого Леса в Крепость Древобрюхов и посмотрите, не пригодится ли этот предмет кому из тамошних фурболгов. Фурболги Крепости Древобрюхов не станут говорить с вами – разве что их отношение к вам нейтральное или лучше."}}
D[8471] = {"Ритуальный тотем Зимней Спячки",{"Отнесите ритуальный тотем Зимней Спячки в берлогу Древобрюхов и отдайте его фурболгу, который им заинтересуется. Никто из племени Древобрюхов не заговорит с вами, пока вы не завоюете себе среди них достойную репутацию."}}
D[8472] = {"Серьезная неполадка",{"Соберите 6 волшебных сердечников с волшебных часовых, которые бродят по руинам Луносвета, и принесите их магистру Джаронису на площадь Соколиных Крыльев в лесах Вечной Песни."}}
D[8473] = {"Печальное задание",{"Убейте 10 высохших хранителей лесов в Выжженной роще. Вернитесь к Ларанне Речной Ветер в башне к северо-западу от Выжженной рощи в лесах Вечной Песни."}}
D[8474] = {"Подвеска Старого Белоствола",{"Отыщите того, кто мог изготовить подвеску Старого Белоствола. Возможно, он подскажет, что это за предмет?"}}
D[8475] = {"Тропа Мертвых",{"Убейте 8 чумных мародеров и вернитесь к следопыту Джеле на Тропе Мертвых в лесах Вечной Песни."}}
D[8476] = {"Угроза Амани",{"Убейте 5 аманийских берсерков и 5 аманийских метателей топоров по просьбе лейтенанта Вестницы Зари из обители Странников, что в лесах Вечной Песни."}}
D[8477] = {"Молот копьедела",{"Найдите в Тор'Вате к юго-востоку от обители Странников копьедела Отембе и принесите его молот Аратель Кузне Солнца в обитель Странников, что в лесах Вечной Песни."}}
D[8478] = {"Выбор оружия"}
D[8479] = {"Зул'Марош",{"Принесите Вень'яши, пленному троллю в Тор'Вате, голову вождя Зул'Мароша. Вождя можно найти в Зеб'Вате, за озером Элрендар."}}
D[8480] = {"Потерянное оружие",{"Принесите 8 комплектов оружия син'дорай Велендрису Белому Рассвету в лесах Вечной Песни."}}
D[8481] = {"Корень всех зол",{"Установите факел призыва демона у входа в пещеру верховного вождя племени Зимней Спячки в деревне фурболгов Зимней Спячки. Сразите демона и добудьте сущность Зандивиуса для Горна Одноглаза из Крепости Древобрюхов."}}
D[8482] = {"Обличающие документы",{"Отнесите обличающие документы Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни."}}
D[8483] = {"Дворфийский шпион",{"Принесите голову геолога Стража Наковальни Аэльдону Озаренному Солнцем на площадь Соколиных Крыльев в лесах Вечной Песни."}}
D[8484] = {"Знак мира",{"Отнесите мирное приношение Древобрюхов королю Магни Бронзобороду в Стальгорн."}}
D[8485] = {"Знак мира",{"Отнесите мирное приношение Древобрюхов Траллу в Оргриммар."}}
D[8486] = {"Магическая нестабильность",{"Убейте 5 магических призраков и 5 волшебных охотников по просьбе хранительницы энергии Велании."}}
D[8487] = {"Зараженная почва",{"Соберите 8 проб зараженной земли для ученицы Мирведы в Восточном святилище, что в лесах Вечной Песни."}}
D[8488] = {"Неожиданный результат",{"Защитите ученицу Мирведу от Плети, напавшей из засады."}}
D[8489] = {"Невредимый преобразователь",{"Принесите хранительнице энергии Велании невредимый чародейский преобразователь."}}
D[8490] = {"Усиление обороны",{"Установите заряженный кристалл рядом с восточным руническим камнем и в течение одной минуты обороняйте его от нежити. Затем верните кристалл хранителю рун Дериану в лесах Вечной Песни и получите награду."}}
D[8491] = {"Добывание шкур",{"Принесите 6 шкур прыголапов Велану Светлому Тополю из деревни Легкий Ветерок, что в лесах Вечной Песни."}}
D[8492] = {"Альянсу не хватает медных слитков!",{"Принесите 20 медных слитков сержанту Камнелобу в Палаты войны Стальгорна."}}
