D[8883] = {"Валадар Звездная Песня",{"Отправляйтесь на Лунную поляну при помощи приглашения на Лунный фестиваль. Прибыв на место, поговорите с Валадаром Звездной Песней в деревне Ночная Гавань."}}
D[8884] = {"Рыбьи головы, рыбьи головы...",{"Добудьте 8 голов мурлоков из племени Темной Чешуи. Принесите их Гатвелиону Солнечному Взору в лесах Вечной Песни на утес над Безмятежным берегом."}}
D[8885] = {"Кольцо Мррргла",{"Снимите кольцо Мррргла с трупа предводителя племени Темной Чешуи. Верните его Гатвелиону Солнечному Взору в лесах Вечной Песни на утесе над Безмятежным берегом."}}
D[8886] = {"На помощь! Пираты!",{"Отыщите 6 тюков из груза капитана Келисендры и верните их капитану Келисендре в укрепленный лагерь к востоку от причала Солнечного Паруса в лесах Вечной Песни."}}
D[8887] = {"Утраченные карты капитана Келисендры",{"Верните утраченные карты капитану Келисендре в укрепленный лагерь к востоку от причала Солнечного Паруса в лесах Вечной Песни."}}
D[8888] = {"Ученица магистра",{"Поговорите с ученицей Лоралталис возле шпиля Блеклых Сумерек, что в лесах Вечной Песни."}}
D[8889] = {"Отключить замок",{"Отключите 3 источника энергии в шпиле Блеклых Сумерек. Потом верните деактивирующий самоцвет ученице Лоралталис."}}
D[8890] = {"Весточка из замка",{"Вернитесь к магистру Блеклые Сумерки в обитель Странников, что в лесах Вечной Песни."}}
D[8891] = {"Неоконченное исследование",{"Верните журнал магистру Блеклые Сумерки в обитель Странников, что в лесах Вечной Песни."}}
D[8892] = {"Проблемы на причале Солнечного Паруса",{"Убейте 5 Презренных-лиходеев и 5 Презренных-бесчинников и вернитесь к следопыту Деголиену."}}
D[8893] = {"Супер Яйц-О-Матик"}
D[8894] = {"Зачистка территории",{"Убейте 6 мана-змеев и 6 эфирных призраков и вернитесь к смотрителю Виллитену в земли Блеклых Сумерек, что в лесах Вечной Песни."}}
D[8895] = {"Послание в Северное святилище",{"Доставьте непомеченное письмо хранителю энергии Кайданису в Северном святилище в лесах Вечной Песни."}}
D[8896] = {"Дворфийский шпион",{"Найдите и убейте геолога Стража Наковальни в Северном святилище, затем доложите о выполнении задания Аэльдону Озаренному Солнцем из Лесов Вечной Песни."}}
D[8897] = {"Дорогая моя Колара!",{"Отнесите тщательно продуманную записку лейтенанта Хельдрика Коларе Дин, обитающей поблизости от банка в Штормграде."}}
D[8898] = {"Дорогая моя Колара!",{"Отнесите смятое письмо Коларе Дин, обитающей поблизости от банка в Штормграде."}}
D[8899] = {"Дорогая моя Колара!",{"Отнесите безукоризненное письмо Коларе Дин, обитающей поблизости от банка в Штормграде."}}
D[8900] = {"Дорогая моя Эления!",{"Отнесите слегка помятую записку Элении Хайдон, обитающей поблизости от банка в Подгороде."}}
D[8901] = {"Дорогая моя Эления!",{"Отнесите написанное со старанием письмо Элении Хайдон, обитающей поблизости от банка в Подгороде."}}
D[8902] = {"Дорогая моя Эления!",{"Отнесите проникнутое любовью письмо Элении Хайдон, обитающей поблизости от банка в Подгороде."}}
D[8903] = {"Опасная любовь",{"Раздобудьте открытку штормградского стражника и отдайте ее Аристану Моттару в Штормграде."}}
D[8904] = {"Опасная любовь",{"Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде."}}
D[8905] = {"Серьезное предложение",{"Добудьте 15 порций крови животных Зимних Ключей и 20 золотых монет и отдайте их вместе с наручами Буйного Сердца Делиане в Стальгорне."}}
