D[10476] = {"Лютые враги",{"Принесите стражу-смотрителю Мой'прну Джиллу 10 обсидиановых боевых ожерелий, снятых с огров из Награнда."}}
D[10477] = {"Боевые ожерелья"}
D[10478] = {"Боевые ожерелья!"}
D[10479] = {"Покажи свою силу",{"Принесите 10 обсидиановых боевых ожерелий, снятых с огров, населяющих Награнд, стражу-смотрителю Быккроку в Гарадар."}}
D[10480] = {"Разъяренные бесы воды",{"Используйте тотем духов, чтобы поймать 5 бесов воды для целителя земли Торлока у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10481] = {"Разъяренные бесы воздуха",{"Поймайте с помощью тотема духов 10 бесов воздуха для целителя земли Торлока из Алтаря Проклятия."}}
D[10482] = {"Падальщики орков Скверны",{"Убейте 20 орков из клана Костеглодов и возвращайтесь к Амади в Оплот Чести."}}
D[10483] = {"Дурные предзнаменования",{"Принесите 1 проклятый талисман капралу Железному Хребту в лагерь экспедиции по просьбе лейтенанта Амади в Оплоте Чести."}}
D[10484] = {"Проклятые талисманы",{"Принесите 12 проклятых талисманов капралу Железному Хребту в Лагерь экспедиции."}}
D[10485] = {"Воевода клана Кровавой Глазницы",{"Принесите разбитые доспехи воеводы Морха капралу Железному Хребту в лагерь экспедиции."}}
D[10486] = {"Угроза хищников",{"Убейте 12 острокрылых кровопускателей."}}
D[10487] = {"Пыльца волшебных драконов",{"Соберите пыльцу с крыльев 4 волшебных драконов."}}
D[10488] = {"Защитить свой дом",{"Помажьте мазью Гор'дрека 5 лютых волков клана Громоборцев."}}
D[10489] = {"Свалить ходячее древо!",{"Добудьте ствол Лесодрева Глубокорня."}}
D[10490] = {"Зов Воды",{"Найдите на острове Лазурной Дымки в Кристальном зале Экзодара предсказателя Нобундо и поговорите с ним."}}
D[10491] = {"Зов воздуха",{"Поговорите с предсказателем Нобундо в Кристальном зале Экзодара на острове Лазурной Дымки."}}
D[10492] = {"Серьезное предложение",{"Добудьте 15 порций крови животных Зимних Ключей и 20 золотых и отдайте их вместе с наручниками Стихий Делиане в Стальгорне."}}
D[10493] = {"Серьезное предложение",{"Добудьте 15 порций яда силитида и 20 золотых и принесите их вместе с наручами из светлостали Моквару в Оргриммар."}}
D[10494] = {"Справедливое вознаграждение"}
D[10495] = {"Справедливое вознаграждение",{"Принесите Моквару в Оргриммар пояс из светлостали и рукавицы из светлостали."}}
D[10496] = {"Прощальные слова Антиона"}
D[10497] = {"Прощальные слова Антиона",{"Отдайте Моквару в Оргриммаре сапоги из светлостали, ножные латы из светлостали и наплеч из светлостали."}}
D[10498] = {"Сладкое – на закуску"}
D[10499] = {"Сладкое – на закуску",{"Отдайте Моквару шлем из светлостали и кирасу из светлостали."}}
D[10500] = {"Орде нужна твоя помощь!",{"Поговорите с вождем Горчуком на аллее Духов Оргриммара."}}
D[10501] = {"Альянсу нужна твоя помощь!",{"Поговорите с фельдмаршалом Снежной Лавиной, который находится в Палатах войны Стальгорна."}}
D[10502] = {"Клан Кровавого Молота",{"Убейте 30 любых огров Кровавого Молота на заставе Кровавого Молота."}}
D[10503] = {"Угроза Камнерогов",{"Убейте 30 любых огров из клана Камнерогов и 10 камнерогих ящеров в Форте Камнерогов и на землях Камнерогов."}}
D[10504] = {"Огры из клана Камнерогов",{"Убейте 30 любых огров из клана Камнерогов в Форте Камнерогов и на землях Камнерогов."}}
D[10505] = {"Клан Кровавого Молота",{"Убейте 30 любых огров Кровавого Молота на заставе Кровавого Молота."}}
D[10506] = {"Тяжелая ситуация",{"Рина Лунный Родник хочет, чтобы вы взяли ее уменьшающий порошок и посыпали им 5 лютых волков клана Кровавого Молота, которых можно найти на заставе и в лощине Кровавого Молота."}}
D[10507] = {"Поворотная точка",{"Используйте камень телепортации Сокретара в точке вторжения: Властитель к северу от базы Легиона: Забвение, чтобы перенести свой отряд в лагерь Сокретара. Оказавшись там, используйте \"Присутствие Ворен'таля\", чтобы победить Сокретара.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10508] = {"Дар для Ворен'таля",{"Патрон шпионов Талодиен, находящийся в Зоне 52, просит вас забрать первую половину камня Сокретара у начальника кузни Моруга с базы Легиона: Забвение и вторую половину камня Сокретара у Силрота с базы Легиона: Геенна.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10509] = {"И все ради славы",{"Отнесите камень телепортации Сокретара Ворен'талю Предсказателю на ярус Провидцев в Шаттрате.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10510] = {"В дренетистовые копи",{"Соберите 5 кристаллов дренетиста."}}
D[10511] = {"Странное пиво",{"Добудьте 11 бочонков забористого пойла Кровавого Молота."}}
D[10512] = {"Пусть Камнероги упьются!",{"Возьмите бочонок забористого пойла Кровавого Молота и попытайтесь напоить допьяна 5 огров Камнерогов."}}
D[10513] = {"Оронок Горемычный",{"Найдите Оронока Горемычного на Разрушенной Отмели, на северном берегу водохранилища Змеиных Колец."}}
D[10514] = {"Кем только я не был...",{"Принесите 10 клубней долины Призрачной Луны с Разоренных равнин Ороноку Горемычному на его ферму.","","Ему также необходимо вернуть его свисток."}}
D[10515] = {"Усвоенный урок",{"Уничтожьте 10 яиц прожорливого камнедера на Разоренных равнинах для Оронока Горемычного."}}
D[10516] = {"Вещи Поборницы",{"Добудьте клинок и щит воздаятельницы Вуулины."}}
D[10517] = {"Горр'Дим, твой час пробил...",{"Убейте Горр'Дима, вождя огров форта Камнерогов."}}
D[10518] = {"Водружение знамени",{"Водрузите знамя Камнерогов на башне Северного Молота, чтобы раздразнить Гурна Обжору. Добудьте знамя и шлем Гурна."}}
D[10519] = {"Код Проклятия – правда и миф",{"Поговорите с Ороноком Горемычным на его ферме и выслушайте историю, которую он вам поведает."}}
D[10520] = {"Помощь верховному друиду Оленьему Шлему",{"Поговорите с верховным друидом Фэндралом Оленьим Шлемом в Дарнасе."}}
D[10521] = {"Гром'тор, сын Оронока",{"Найдите Гром'тора сына Оронока в лагере Змеиных Колец в долине Призрачной Луны."}}
D[10522] = {"Код Проклятия: Вклад Гром'тора",{"Найдите первый фрагмент Кода Проклятия для Гром'тора, сына Оронока из лагеря Змеиных Колец в долине Призрачной Луны."}}
D[10523] = {"Код Проклятия: Первый Фрагмент",{"Принесите Сейф Гром'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны."}}
D[10524] = {"Сокровища клана Громоборцев",{"Добудьте барабан, стрелу и табличку клана Громоборцев."}}
D[10525] = {"Путеводный огонек",{"При помощи фрагмента пылающей души превратите свой дух в путеводный огонек, который приведет вас туда, где находится последнее сокровище Громоборцев."}}
D[10526] = {"Громовая пика",{"Добудьте Громовую пику."}}
D[10527] = {"Ар'тор, сын Оронока",{"Найдите Ар'тора, сына Оронока, на аванпосте иллидари в долине Призрачной Луны."}}
D[10528] = {"Тюрьма из демонических кристаллов",{"На аванпосте иллидари разыщите и убейте госпожу боли Габриссу и вернитесь к телу Ар'тора, сына Оронока, с хрустальным ключом."}}
D[10529] = {"Путь охотника",{"Поговорите с лейтенантом Вестницей Зари в Обители Странников, что в Лесах Вечной Песни."}}
D[10530] = {"Путь охотника",{"Поговорите с лейтенантом Вестницей Зари в Обители Странников, что в Лесах Вечной Песни."}}
D[10531] = {"Битва за Низину Арати",{"Нападите на рудник, лесопилку, кузницу и ферму и возвращайтесь к фельдмаршалу Освету в Опорный пункт."}}
D[10532] = {"Перекрыть линии поставок Аратора",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его стражу смерти Мортису в Павший Молот."}}
D[10533] = {"Новые ящики с ресурсами"}
D[10534] = {"Возвращение домой",{"Кедмос из Экзодара просит вас прийти поговорить с ним."}}
D[10535] = {"Ресурсы Низины Арати",{"Выиграйте битву за низину Арати, добудьте ящик с ресурсами из Арати и принесите его сержанту Маклир в Опорный пункт."}}
D[10536] = {"Новые ящики с ресурсами"}
D[10537] = {"Лон'горон, лук Горемычного",{"Отберите у демонов Лон'горон, лук Горемычного, и верните его духу Ар'тора на аванпосте иллидари."}}
D[10538] = {"Кипящая кровь",{"Поместите кровь орков из клана Кровавой Глазницы в проклятый котел, чтобы получить кипящую кровь. Принесите 12 образцов кипящей крови аптекарю Альбреку на заставу Хребтолома."}}
D[10539] = {"Возвращение домой",{"Кедмос из Экзодара просит вас прийти и поговорить с ним."}}
D[10540] = {"Код Проклятия: Вклад Ар'тора",{"Заберите вторую часть Кода Проклятия у Венератуса Многого для духа Ар'тора с аванпоста иллидари. Существа, убитые или раненые охотником на духов, не приносят вам ни добычи, ни опыта."}}
D[10541] = {"Код Проклятия – Второй фрагмент",{"Отнесите сейф Ар'тора Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны."}}
D[10542] = {"У меня сперли кальян и выпивку!",{"Добудьте кальян Т'чали и 10 кружек забористого пойла Кровавого Молота."}}
D[10543] = {"Гримнок и Коргаах, я за вами!",{"Убейте Гримнока Дитя Войны и Коргааха."}}
D[10544] = {"Чума на оба ваших клана!",{"При помощи сильного губительного фетиша прокляните 5 домов или башен в крепости Камнерогов и 2 на заставе Кровавого Молота."}}
D[10545] = {"Бочонок клана Камнерогов",{"С помощью бочонка забористого пойла Кровавого Молота напоите 5 огров из клана Камнерогов."}}
D[10546] = {"Борак, сын Оронока",{"Найдите Борака сына Оронока возле лагеря Затмения в долине Призрачной Луны."}}
D[10547] = {"Выгодный обмен",{"Найдите тухлое яйцо араккоа и доставьте его Тобиасу Грязежору в город Шаттрат, расположенный на северо-западе леса Тероккар."}}
D[10548] = {"Горькая правда",{"Эраланна из Транквиллиона просит вас найти усохшую голову археолога в одном из сундуков Зеб'Телы или Зеб'Новы."}}
D[10550] = {"Пучок кровопийки",{"Отнесите пучок кровопийки Бораку сыну Оронока на мост возле лагеря Затмения, в долине Призрачной Луны."}}
D[10551] = {"Присяга верности Алдорам"}
D[10552] = {"Присяга верности Провидцам"}
D[10553] = {"Ворен'таль Предсказатель",{"Поговорите с Ворен'талем в его библиотеке на ярусе Провидцев в Шаттрате.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10554] = {"Ишана",{"Поговорите с Ишаной в святилище Вечного Света на возвышенности Алдоров в Шаттрате.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10555] = {"Недомогание",{"Соберите 18 выдернутых перьев Лашш."}}
D[10556] = {"Рисунки",{"При помощи горсти перьев в круге заклинаний Лашш наложите заклинания."}}
D[10557] = {"Испытательный полет: Конденсаторий зефира",{"Поговорите с Ралли Быстроцапом и испытайте Конденсанторий зефира."}}
D[10558] = {"Уважительное отношение Оплота Чести",{"Командир армии Данат Троллебой из Оплота Чести на полуострове Адского Пламени желает, чтобы вы заслужили уважительное отношение Оплота Чести, продолжив сражаться с орками Скверны в Разрушенных залах цитадели Адского Пламени."}}
D[10559] = {"Уважительное отношение Траллмара",{"Заслужите уважение Траллмара, сражаясь с орками Скверны в Разрушенных залах цитадели Адского Пламени по совету Назгрела из Траллмара на полуострове Адского Пламени."}}
D[10560] = {"Почтительное отношение Ша'тар",{"Заслужите почтительное отношение Ша'тар, сразившись с силами Кель'таса в Крепости Бурь, после чего поговорите с А'далом в Шаттрате."}}
D[10561] = {"Уважение Хранителей Времени",{"Заслужите уважение Хранителей Времени. Для этого необходимо проследить, чтобы никто не нарушил течение времени и не изменил ход прошлых событий в старом Хилсбраде и в Черных топях в пещерах Времени."}}
D[10562] = {"Окружены!",{"Убейте 10 боевых инферналов для командира звена Нуаинна из цитадели Громового Молота."}}
D[10563] = {"В форт Легиона",{"Отправляйтесь в форт Легиона, найдите там переговорное устройство и, воспользовавшись маскировкой, выведайте планы Легиона. Вернитесь к командиру звена Нуаинну в цитадель Громового Молота, когда выполните задание."}}
D[10564] = {"Перебей инферналов!",{"Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить огненных големов. Доложите о выполнении задания командиру звена Нуаинну из цитадели Громового Молота."}}
D[10565] = {"Камни Векх'ниров",{"Добудьте кристалл Векх'ниров и отнесите в круг заклинаний Векх'ниров, чтобы зарядить его."}}
D[10566] = {"Пробы и ошибки",{"Испытайте все жезлы Дертрока на огре-рабе араккоа, затем возвращайтесь к Дертроку. Для использования каждого жезла понадобится пылающий кристалл Векх'ниров."}}
D[10567] = {"Создание подвески",{"Добудьте 6 когтей Рууан'оков и положите их круг оракула Рууан'ока, чтобы призвать Предвестника Ворона. Убейте его и получите подвеску Предвестника."}}
D[10568] = {"Таблички Баа'ри",{"Соберите для анахоретки Сейлы 12 табличек Баа'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10569] = {"Развалины Скет'лона",{"Добудьте у темного конклава араккоа и принесите наезднику на грифоне Киерану первую, вторую и третью страницы дневника командира Скет'лона."}}
D[10570] = {"Охота на Посла",{"Заберите письмо Ярости Бури на мосту возле лагеря Затмения для Борака сына Оронока."}}
D[10571] = {"Старец Орону",{"Найдите в руинах Баа'ри приказы Акамы, адресованные Орону Старцу, и принесите их анахоретке Сейле к алтарю Ша'тар.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10572] = {"Сборка бомбы",{"Добудьте энергетический сердечник и часть обшивки сквернобота и принесите материалы командиру звена Нуаинну из цитадели Громового Молота."}}
D[10573] = {"Кузница Смерти",{"Поговорите с штормером Эваном Дикокрылом в башне Кузницы Смерти."}}
D[10574] = {"Осквернители из клана Пеплоустов",{"Добудьте 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к анахоретке Сейле к алтарю Ша'тар в долине Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10575] = {"Клеть Стражницы",{"Отправляйтесь в Клеть Стражницы, к югу от руин Баа'ри и расспросите Санору о местонахождении Акамы для анахоретки Сейлы.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10576] = {"Уловки Призрачной Луны",{"Принесите 6 фрагментов доспехов из лагеря Затмения Бораку, сыну Оронока, на мост возле лагеря Затмения в долине Призрачной Луны."}}
D[10577] = {"Чего Иллидан хочет, Иллидан получит...",{"Доставьте послание Иллидана главнокомандующему Рууску в лагерь Затмения."}}
D[10578] = {"Код Проклятия – Вклад Борака",{"Отберите для Борака, сына Оронока, третью часть Кода Проклятия у Руула Светокрада.","","Для выполнения этого задания вам потребуются помощники."}}
D[10579] = {"Код Проклятия – Третий фрагмент",{"Принесите сейф Борака Ороноку Горемычному на ферму Оронока в Долине Призрачной Луны."}}
D[10580] = {"Куда подевались эти клятые гномы?",{"Обыщите южные районы Зазубренной гряды Острогорья, чтобы найти, где сейчас Тошли и прочие гномы."}}
D[10581] = {"Иди по крошечкам!",{"Пройдите по следу из запчастей вверх по склону на Островерхий гребень. Поговорите с Тошли на станции в Острогорье."}}
D[10582] = {"Приспешники Совета Теней",{"Убейте 10 стражей и 5 призывателей из Кузницы Смерти для штормера Эвана Дикокрыла."}}
D[10583] = {"Судьба Фланиса",{"Разыщите Фланиса Быстрокрыла в Кузнице Смерти, и принесите его сумку штормеру Эвану Дикокрылу в башню Кузницы Смерти."}}
D[10584] = {"Спасти преобразователи энергии!",{"C помощью протовольтаического магнетоколлектора поймайте 5 электроменталей."}}
D[10585] = {"Чертог Призыва",{"Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания штормеру Эвану Дикокрылу из башни Кузницы Смерти."}}
D[10586] = {"Смерть вестнику войны!",{"Убейте Разууна Завоевателя, заберите его приказы и вернитесь к командиру звена Нуаинну в цитадель Громового Молота."}}
D[10587] = {"Тренировочная площадка Карабора",{"Отберите для экзарха Онаалы у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10588] = {"Код Проклятия",{"Используйте Код Проклятия у Алтаря Проклятия, чтобы призвать Цируха Повелителя Огня.","","Уничтожьте его и пообщайтесь с целителем земли Торлоком, которого вы найдете там же."}}
D[10589] = {"Получение доступа",{"Принесите пульт от телепорта Легиона командиру звена Нуаинну из цитадели Громового Молота. Пульты можно найти у мо'аргов-оружейников в форте Легиона."}}
D[10590] = {"Доказательство ненависти",{"Принесите 20 камней приспешников Плети Мелару Клинку Рассвета из Бастиона."}}
D[10592] = {"Мудрость королевы банши",{"Отнесите фрагменты камня Плети Леди Сильване Ветрокрылой в Подгород."}}
D[10593] = {"Древнее зло",{"Раскройте тайны храма Атал'Хаккар, освободите Атал'алариона и добудьте гнилую лозу из его плоти. По выполнении задания вернитесь к Мелару в Бастион."}}
D[10594] = {"Калибровка резонансной частоты",{"Расположите осцилляционные сканеры таким образом, чтобы стоя среди них вы оказались в точке перекрытия пяти осцилляционных полей."}}
D[10595] = {"Окружены!",{"Убейте 10 боевых инферналов для кровавого стража Галмока из деревни Призрачной Луны."}}
D[10596] = {"В форт Легиона",{"Отправляйтесь в форт Легиона, найдите переговорное устройство и, замаскировавшись, выведайте планы Легиона. Вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны, когда выполните задание."}}
D[10597] = {"Сборка бомбы",{"Добудьте энергетический сердечник и часть обшивки сквернобота для кровавого стража Галмока из деревни Призрачной Луны."}}
D[10598] = {"Перебей инферналов!",{"Используйте бомбу Скверны, находясь в центре зеленого знака в форте Легиона, чтобы уничтожить инферналов. Доложите о выполнении кровавому стражу Галмоку из деревни Призрачной Луны."}}
D[10599] = {"Кузница Смерти",{"Поговорите с разведчиком Заграном на Вышке на золе."}}
D[10600] = {"Приспешники Совета Теней",{"Убейте 10 стражей и 5 призывателей из Кузницы Смерти для разведчика Заграна с Вышки на золе."}}
D[10601] = {"Судьба Кагроша",{"Разыщите Кагроша в Кузнице Смерти и принесите его сумку разведчику Заграну на вышку на золе."}}
D[10602] = {"Чертог Призыва",{"Раздобудьте стихийный подчинитель у кузнеца или ремонтника из Кузницы Смерти и используйте его, чтобы прервать ритуал в чертоге призыва. Доложите о выполнении задания разведчику Заграну на Вышке на золе."}}
D[10603] = {"Смерть вестнику войны!",{"Убейте завоевателя Разууна, добудьте у него приказы Разууна и вернитесь к кровавому стражу Галмоку в деревню Призрачной Луны."}}
D[10604] = {"Получение доступа",{"Принесите пульт от телепорта Легиона кровавому стражу Галмоку в деревню Призрачной Луны. Пульты можно найти у мо'аргов-оружейников в форте Легиона."}}
D[10605] = {"Призыв Карендина",{"Поговорите с Карендином Халгаром в Подгороде."}}
D[10606] = {"Искусство ухода за скверноботом",{"Убейте доктора Потрошилло и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите ее Плекси в Точку вторжения: Катаклизм."}}
D[10607] = {"Шепот Бога-ворона",{"Убейте араккоа Гришны, чтобы на две минуты обрести Понимание речи Ворона. Находясь под действием этого заклятия, вы можете найти и получить пророчества в четырех святилищах."}}
D[10608] = {"Ясно как день!",{"Убейте 10 кристальных камнедеров."}}
D[10609] = {"Что было первым, дракон или яйцо?",{"Соберите 3 сущностей прародителя драконов Пустоты, 3 субстанции взрослого дракона и 3 субстанции зрелого дракона."}}
D[10610] = {"Основы ведения разведки"}
D[10611] = {"Искусство ухода за скверноботом",{"Убейте доктора Потрошиллера и заберите у него ключ. Откройте этим ключом сейф доктора и заберите книгу \"Искусство ухода за скверноботом\". Принесите его Наканси в Точку вторжения: Катаклизм."}}
D[10612] = {"Машина для убийства",{"Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Плекси в точку вторжения: Катаклизм."}}
D[10613] = {"Машина для убийства",{"Используйте панель управления скверноботом, чтобы захватить контроль над скверноботом-часовым. Уничтожьте 60 инферналов из Кузницы Смерти, прежде чем ваш сквернобот падет. По выполнении вернитесь к Наканси в точку вторжения: Катаклизм."}}
D[10614] = {"Шепот ветра",{"Поговорите с Леороксом в деревне Мок'Натал в Острогорье."}}
D[10615] = {"Чащоба Рууан",{"Поговорите с Времионом в Вечной роще, что в чащобе Рууан в Острогорье."}}
D[10617] = {"Коконы шелкокрыла",{"Добудьте 8 коконов шелкокрыла с личинок шелкокрыла.","","Быстро убейте личинок, пока те не начали превращаться в шелкокрылов, прогрызая свои коконы."}}
D[10618] = {"Нежнейшие крылья",{"Соберите 12 радужных крыльев."}}
D[10619] = {"Клан Пеплоустов",{"Убейте для воздаятеля Алуумена 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10620] = {"Угроза горного хребта",{"Убейте 10 пауков высокогорья."}}
D[10621] = {"Осколок погибели Иллидари",{"Принесите осколок проклятия иллидари Ординну Громовому Кулаку в цитадель Громового Молота."}}
D[10622] = {"Доказательство верности",{"Убейте Зандраса в Клети Стражницы и возвращайтесь к Санору."}}
D[10623] = {"Осколок погибели Иллидари",{"Принесите осколок проклятия иллидари Грокому Мертвому Глазу в деревню Призрачной Луны."}}
D[10624] = {"История про привидений...",{"Принесите главному аптекарю Хильдегард из деревни Призрачной Луны 15 горстей неостывающего пепла."}}
D[10625] = {"Спектроскоп",{"Убейте для главного аптекаря Хильдегард из деревни Призрачной Луны 12 ревнителей из клана Призрачной Луны."}}
D[10626] = {"Сдать оружие!",{"Принесите глефу Маказрадона и глефу Моргророна Ординну Громовому Кулаку в цитадель Громового Молота."}}
D[10627] = {"Сдать оружие!",{"Принесите глефу Мазакрадона и глефу Моргророна Грокому Мертвому Глазу в деревню Призрачной Луны."}}
D[10628] = {"Акама",{"Поговорите с Акамой в тайной комнате Клети Стражницы."}}
D[10629] = {"Шизанутая работенка",{"Используйте свисток гончей Скверны, чтобы призвать гончую. Выведите ее на прогулку и убейте парочку безумных зловепрей. Поищите ключи от крошшера в помете гончей Скверны. Верните ключи штейгеру Разлкразу, который находится на руднике к северо-западу от Траллмара."}}
D[10630] = {"Рядом с Траллмаром",{"Убейте Урга'зза и возвращайтесь к штейгеру Разлкразу на рудник к северо-западу от Траллмара."}}
D[10632] = {"Точи зубы!",{"Соберите 5 острейших зубов Кинжальной Пасти."}}
D[10633] = {"Терон Кровожад – Правда и Вымысел",{"Найдите древнего духа долины Призрачной Луны для главного аптекаря Хильдегард из деревни Призрачной Луны в одноименной долине. Если вы потеряете свой спектроскоп, Хильдегард может сделать вам новый."}}
D[10634] = {"Прорицание: Броня Кровожада",{"Завладейте броней Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10635] = {"Прорицание: Плащ Кровожада",{"Завладейте плащом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10636] = {"Прорицание: буздыхан Кровожада",{"Завладейте буздыханом Кровожада по просьбе древнего духа Долины Призрачной Луны, что обитает у Алтаря Теней."}}
D[10637] = {"Необходимая уловка",{"Вернитесь в Руины Карабора и освободите для экзарха Онаалы Разрушителя Азалота.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10638] = {"NOT A QUEST",{"Seek <NAME> in the <DISTRICT> of Silvermoon City."}}
D[10639] = {"Терон Кровожад, то есть я...",{"Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.","","По выполнении задания вернитесь к главному аптекарю Хильдегард в деревню Призрачной Луны."}}
D[10640] = {"Алтруис",{"Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10641] = {"Против Легиона",{"Алтруис Страдалец просит вас добыть свежей крови зловещей жрицы на базе Легиона: Геенна в Пустоверти. Пролейте кровь на землю и убейте аватару Саталь. По выполнении задания вернитесь к Алтруису."}}
D[10642] = {"Дух из машины",{"Принесите 15 горстей неостывающего пепла Зорусу Ревнителю в цитадель Громового Молота в долине Призрачной Луны."}}
D[10643] = {"Вестники Призрачной Луны",{"Убейте 12 предвестников из клана Призрачной Луны для Зоруса Ревнителя из цитадели Громового Молота."}}
D[10644] = {"Терон Кровожад – Правда и Вымысел",{"Найдите древнего духа долины Призрачной Луны для Зоруса Ревнителя в цитадели Громового Молота. Если вы потеряете свой спектроскоп, Зорус может сделать вам новый."}}
D[10645] = {"Терон Кровожад, то есть я...",{"Древний дух долины Призрачной Луны обвел вас вокруг пальца! Вы сделали все, что он просил, но оказалось, что этот дух – сам Терон Кровожад. Чтобы освободиться от его власти вы должны выполнить его распоряжение и убить Карсиуса Дозорного Древности.","","По выполнении задания вернитесь к Зорусу Ревнителю в цитадель Громового Молота."}}
D[10646] = {"Ученик Иллидана",{"Выслушайте рассказ Алтруиса."}}
D[10647] = {"Разыскивается: Увурос, бич долины Призрачной Луны",{"Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Сардону Чистому Удару в деревню Призрачной Луны в одноименной долине."}}
D[10648] = {"Разыскивается: Увурос, бич долины Призрачной Луны",{"Убейте Увуроса и доставьте его пламенеющую гриву военному глашатаю Пивному Брюху в цитадель Громового Молота в долине Призрачной Луны."}}
D[10649] = {"Книга Имен Скверны",{"Проберитесь в Темный лабиринт в Аукиндоне и добудьте у Черносерда Подстрекателя Книгу Имен Скверны. После этого вернитесь в Награнд к Алтруису."}}
D[10650] = {"Возвращение к Алдорам",{"Поговорите с экзархом Онаалой у алтаря Ша'тар, в долине Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10651] = {"Варедиса нужно остановить!",{"Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к экзарху Онаале с книгой Имен Скверны, по выполнении задания.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10652] = {"В тылу врага",{"Поговорите с Веронией, когда будете готовы отбыть в манагорн Коруу. Оказавшись там, поговорите с Каледисом Сияющим Рассветом.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10653] = {"Знаки Саргераса",{"Принесите 10 знаков Саргераса Адуину Стражу Света в Шаттрат.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10654] = {"Больше знаков Саргераса"}
D[10655] = {"Знак Саргераса"}
D[10656] = {"Перстни Ярости Солнца",{"Принесите магистру Файленн 10 перстней Ярости Солнца.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10657] = {"Оседлать молнию",{"Абсорбируйте 25 ударов молний от чешуекрылых змеев при помощи реполяризованной магнитной сферы. Также добудьте 5 молниевых желез чешуекрылых."}}
D[10658] = {"Больше перстней Ярости Солнца"}
D[10659] = {"Перстень Ярости Солнца"}
D[10660] = {"Что за странные создания?",{"Добудьте 8 селезенок сквернопламенных деметродонов для ученого Тиоруса в деревне Призрачной Луны в одноименной долине."}}
D[10661] = {"Умопотрошительно!",{"Принесите 8 селезенок сквернопламенных деметродонов Гномусу в цитадель Громового Молота."}}
D[10662] = {"Кузнец–отшельник",{"Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар."}}
D[10663] = {"Кузнец–отшельник",{"Принесите ящик со слитками Дэвиду Уэйну в приют Уэйна, который находится в лесу Тероккар."}}
D[10664] = {"Дополнительные материалы",{"Принесите адамантитовую рамку, 4 куска толстой узловатой кожи и тотем защиты от демонов Дэвиду Уэйну в Приют Уэйна."}}
D[10665] = {"Новинка из Механара",{"Принесите избыточно заряженный аккумулятор маны Дэвиду Уэйну в Приют Уэйна."}}
D[10666] = {"Лексикон демоника",{"Добудьте книгу \"Лексикон демоника\" у великого мастера Ворпила и принесите его Дэвиду Уэйну в Приют Уэйна."}}
D[10667] = {"Суглинок из Нижнего мира",{"Достаньте фиал с суглинком Нижнего мира у гидромантки Теспии и принесите его Дэвиду Уэйну в приют Уэйна."}}
D[10668] = {"Против иллидари",{"Алтруис Страдалец просит вас убить Лотроса на аванпосте иллидари в долине Призрачной Луны."}}
D[10669] = {"Вопреки всему",{"Алтруис Страдалец хочет, чтобы вы взяли прочное серебряное копье и вонзили его на прогалине с порталом близ озера Болотных Огоньков, чтобы пробудить Кселета. Когда убьете демона, вернитесь к Алтруису."}}
D[10670] = {"Слеза Матери-Земли",{"Добудьте слезу Матери-Земли у О'мрогга Завоевателя и принесите ее Дэвиду Уэйну в приют Уэйна."}}
D[10671] = {"Не только фунт мяса",{"Добудьте 5 кусков мяса, напитанного энергией Астрала."}}
D[10672] = {"Честно говоря, это – бред!",{"Отправляйтесь к потокам лавы возле руин Баа'ри и используйте пульт управления чарами, чтобы контролировать волшебного скорпиона. Переправьтесь на нем через лаву и пометьте 8 больших сквернопламенных деметродонов для ученого Тиоруса."}}
D[10673] = {"Хребтоскверн Старший",{"Убейте Хребтоскверна Старшего и принесите его шкуру ученому Тиорусу в деревню Призрачной Луны в одноименной долине."}}
D[10674] = {"Ловля фантастического света",{"Поймайте 15 световых сфер братства Разаани при помощи световой ловушки."}}
D[10675] = {"Попомните гномскую доброту!",{"Добудьте коллекцию душ."}}
D[10676] = {"Проклятие иллидари",{"Подождите, пока Дэвид Уэйн откует для вас клинок."}}
D[10677] = {"Второе блюдо...",{"Добудьте для Гномуса из цитадели Громового Молота в долине Призрачной Луны потроха крупного деметродона."}}
D[10678] = {"Гвоздь программы",{"Принесите шкуру Хребтоскверна Гномусу в цитадель Громового Молота в долине Призрачной Луны."}}
D[10679] = {"Закалка Меча",{"Отправляйтесь к Жгучим прудам возле подножия Руки Гул'дана, и закалите кованый меч погибели иллидари в озерах лавы. После этого возвращайтесь к Дэвиду Уэйну в приют Уэйна."}}
D[10680] = {"Рука Гул'дана",{"Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10681] = {"Рука Гул'дана",{"Поговорите с целителем земли Торлоком у Алтаря Проклятия в Долине Призрачной Луны."}}
D[10682] = {"Время для переговоров...",{"Переговорите с надзирателем Нуааром."}}
D[10683] = {"Таблички Баа'ри",{"Соберите для чародея Тэлиса из святилища Звезд 12 табличек Баа'ри. Таблички могут быть где-то закопаны или находиться у Пеплоустов-рабочих.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10684] = {"Старец Орону",{"Найдите в руинах Баа'ри приказы Акамы, адресованные старцу Орону, и принесите их чародею Телису.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10685] = {"Осквернители из клана Пеплоустов",{"Соберите 4 фрагмента медальона у Хаалума, Айкенена, Уйлару, и Лакаана и вернитесь к чародею Тэлису в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10686] = {"Клеть Стражницы",{"Отправляйтесь в Клеть Стражницы, к югу от руин Баа'ри и расспросите Санору о местонахождении Акамы для чародея Телиса.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10687] = {"Тренировочная площадка Карабора",{"Отберите у соискателей и посвященных охотников на демонов, сосредоточенных в руинах Карабора, 8 глеф армии Ярости Солнца. Принесите их Лариссе Солнцесвет в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10688] = {"Необходимая уловка",{"Вернитесь в Руины Карабора и освободите Азалота для Лариссы Солнцесвет.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10689] = {"Алтруис",{"Отправляйтесь в западный Награнд и найдите Алтруиса Страдальца.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10690] = {"Мать логова",{"Убейте Рему."}}
D[10691] = {"Возвращение к Провидцам",{"Поговорите с Лариссой Солнцесвет в святилище Звезд в долине Призрачной Луны.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10692] = {"Варедиса нужно остановить!",{"Отправляйтесь в Руины Карабора и убейте Аландиен, Тераса, Нетариеля и самого Варедиса. Используйте Книгу Имен Скверны, когда Варедис будет перевоплощаться, чтобы ослабить его. Вернитесь к Лариссе Солнцесвет с Книгой Имен Скверны по выполнении задания.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
