D[10701] = {"Низвергнуть Глыбня Пустоты",{"Убейте Глыбня Пустоты и сообщите об этом ведущему ракетостроителю Фьюзеляжу, находящемуся в Зоне 52 в Пустоверти."}}
D[10702] = {"Наряд вне очереди",{"Убейте 20 животных, водящихся в долине Призрачной Луны для воеводы Ор'бароха.","","Тварями считаются скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым."}}
D[10703] = {"Зачистка",{"Убейте 20 животных, водящихся в долине Призрачной Луны, для тана Йорегара из цитадели Громового Молота.","","Подойдут скверносвины, мерзкокрылые химеры и огнепанцирные клешневики. Соотношение может быть любым."}}
D[10704] = {"Как проникнуть в Аркатрац",{"Принесите А'далу верхний и нижний обломок ключа Аркатраца, чтобы он собрал из них целый ключ."}}
D[10705] = {"Провидец Адало",{"Найдите провидца Адало в Аркатраце в Крепости Бурь."}}
D[10706] = {"Таинственное знамение",{"Вернитесь к Акаме в Клеть Стражницы в долине Призрачной Луны."}}
D[10707] = {"Терраса Ата'мала",{"Отправляйтесь на террасу Ата'мала, в Долине Призрачной Луны и раздобудьте Сердце Ярости. По выполнении задания вернитесь к Акаме в Клеть Стражницы."}}
D[10708] = {"Обещание Акамы",{"Принесите медальон Карабора А'далу в Шаттрат."}}
D[10709] = {"Воссоединение",{"Поговорите с Рексаром в Оплоте Громоборцев в Острогорье."}}
D[10710] = {"Испытательный полет: Звенящий гребень",{"Подпишите отказ от претензий к Талли, затем поговорите с Ралли Быстроцапом насчет Конденсатория зефира."}}
D[10711] = {"Испытательный полет: лагерь Разаана",{"Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира."}}
D[10712] = {"Испытательный полет: чащоба Рууан",{"Поговорите с Ралли Быстроцапом, чтобы узнать, как использовать Конденсаторий зефира. При полете в Чащобу Рууан крутите крутящийся флюгер Пустоты. Передайте крутящийся флюгер Пустоты О'Малли Быстроцапу, который находится в Вечной Роще."}}
D[10713] = {"...и время действовать",{"Убейте 10 лесорубов Культа Змея."}}
D[10714] = {"На крыльях Духа",{"Найдите занятых разговором ворожея и надсмотрщика из клана Кровавого Молота, затем при помощи свистка Рексара призовите Духа и проследите за ними."}}
D[10715] = {"Прогулка в Беспокойную лощину",{"Добудьте 7 ядовитых желез землероев."}}
D[10716] = {"Test Flight: Raven's Wood <needs reward>",{"Поговорите с Ралли Быстроцапом насчет использования Конденсатория зефира. Вернитесь к Талли Быстроцапу на станцию Тошли."}}
D[10717] = {"Вор у вора...",{"Добудьте 5 сетей Культа Змея."}}
D[10718] = {"У духов есть голоса",{"Поговорите с Рексаром в Оплоте Громоборцев в Острогорье."}}
D[10719] = {"Где записка?",{"Отдайте записку о встрече хранителю деревьев Чауну в Вечную рощу в Острогорье."}}
D[10720] = {"Самые маленькие создания",{"Ударьте в барабан из шкуры кодо возле норы сурка. Держа сурка под контролем, насыпьте яду в три бочонка в лагере Кровавого Молота."}}
D[10721] = {"Подложим Груллоку свинью",{"Добудьте мешок Груллока."}}
D[10722] = {"Встреча в пещере Крыла Тьмы",{"Соберите костюм инспектора из деталей одежды, собранных у различных адептов Культа Змея. Отправьтесь в этом костюме на встречу с Колфисом Черной Чешуей."}}
D[10723] = {"Горгром Драконоед",{"Добудьте 3 тотема гризли у огров Камен'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.","","Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши."}}
D[10724] = {"Пленник Камнерогов",{"Убивайте огров Камнерогов, пока не добудете ключ от клетки виверны. Как только добудете его, идите к клетке виверны и подуйте в свисток Духов чтобы призвать Духа, который отопрет клетку Леокка."}}
D[10725] = {"Аметистовое Око в восхищении",{"Принесите свой перстень Аметистового Ока верховному магу Лериде на Перевал Мертвого Ветра. Кроме того, необходимо заслужить полное доверие Аметистового Ока."}}
