D[10742] = {"Перед выстрелом",{"Протрубите в боевой рог Рексара у алтаря Гока, затем убейте Гока."}}
D[10744] = {"Вести о Победе",{"Вернитесь в цитадель Громового Молота и поговорите с Курдраном Громовым Молотом."}}
D[10745] = {"Вести о Победе",{"Возвращайтесь в деревню Призрачной Луны и поговорите с воеводой Ор'барохом."}}
D[10747] = {"Дракончики Культа Змея",{"Поймайте 10 черных дракончиков Культа Змея при помощи сети."}}
D[10748] = {"Да сгинет Макснар!",{"Убейте Макснара Бледную Пасть."}}
D[10749] = {"Яд барона Черногрива",{"Доставьте яд барона Черногрива Рексару в оплот Громоборцев в Острогорье."}}
D[10750] = {"Путь Завоевания",{"Отправляйтесь по Пути Завоевания в Долине Призрачной Луны."}}
D[10751] = {"Перерезанный путь",{"Убейте 20 солдат, 10 кавалеристов и 10 чароплетов лагеря Затмения."}}
D[10752] = {"Вперед, в Ясеневый лес",{"Поговорите с Раэной Волкопас в Астранааре."}}
D[10753] = {"Зачистка пустоши",{"Убейте 4 скверноподданных чешуекрылых змеев, 4 скверноподданных из каньона Кинжальной Пасти и 2 осквернителей."}}
D[10754] = {"Вход в цитадель",{"Принесите форму для отливки ключа командиру армии Данату в Оплот Чести на полуострове Адского Пламени."}}
D[10755] = {"Вход в цитадель",{"Принесите форму для отливки ключа Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[10756] = {"Великий мастер Рохок",{"Принесите форму для отливки ключа Рохоку в Траллмар, что на Полуострове Адского Пламени."}}
D[10757] = {"Просьба Рохока",{"Принесите Рохоку 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Траллмар на полуострове Адского Пламени."}}
D[10758] = {"Жарче, чем в пекле",{"Уничтожьте сквернобота на полуострове Адского Пламени и погрузите внутрь него необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Рохоку в Траллмар."}}
D[10759] = {"Найти дезертира",{"Найдите Паршаха в Магмовых полях и поговорите с ним."}}
D[10760] = {"Развалины Скет'лона",{"Добудьте у темного конклава араккоа и принесите сержанту Каргулу в деревню Призрачной Луны первую, вторую и третью страницы дневника командира Скет'лона."}}
D[10761] = {"Найти дезертира",{"Найдите Паршаха в Магмовых полях и поговорите с ним."}}
D[10762] = {"Великий Мастер Болтуй",{"Принесите форму для отливки ключа Болтую в Оплот Чести."}}
D[10763] = {"Просьба Болтуя",{"Принесите Болтую 4 слитка оскверненного железа, 2 горсти чародейской пыли и 4 частицы огня в Оплот Чести на полуострове Адского Пламени."}}
D[10764] = {"Жарче, чем в пекле",{"Уничтожьте сквернобота на полуострове Адского Пламени и закалите на его остатках необожженную форму для отливки ключа. Принесите обожженную форму для отливки ключа Болтую в Оплот Чести."}}
D[10765] = {"Война Миров",{"Убейте канцлера Кровавую Листву и Корока Могучего и добудьте приказ Иллидана."}}
D[10766] = {"Точка вторжения: Катаклизм",{"Доложитесь Плекси в Точке вторжения: Катаклизм."}}
D[10767] = {"Точка вторжения: Катаклизм",{"Доложитесь Наканси в Точке вторжения: Катаклизм."}}
D[10768] = {"Гербовые накидки Иллидари",{"Соберите 10 гербовых накидок Иллидари."}}
D[10769] = {"Удар исподтишка",{"Убейте 5 безумных колоссов в личине эльфа крови – иллидари и потом вернитесь к воеводе Ор'бароху в деревню Призрачной Луны в одноименной долине. Верните ему кор'кронское сигнальное ружье."}}
D[10770] = {"Угольки",{"Замшельник Древний просит вас убить 8 пламенных бесов, а затем вернуться к нему в чащобу Рууан."}}
D[10771] = {"Из пепла",{"Замшельник Древний хочет, чтобы вы отправились в Гарь и посадили семена железнокорня в три кучи плодородной вулканической почвы и вернулись к нему в чащобу Рууан."}}
D[10772] = {"Путь Завоевания",{"Отправляйтесь по Пути Завоевания в Долине Призрачной Луны."}}
D[10773] = {"Перерезанный путь",{"Убейте 20 солдат, 10 кавалеристов лагеря Затмения и 5 сынов Корока."}}
D[10774] = {"Великан плюс эльфийка равно...",{"Убейте канцлера Кровавую Листву и Корока Могучего и верните приказ Иллидана."}}
D[10775] = {"Гербовые накидки Иллидари",{"Соберите 10 гербовых накидок Иллидари."}}
D[10776] = {"Удар исподтишка",{"Убейте 5 безумных колоссов, находясь в облике посланника Иллидана, потом вернитесь к тану Йорегару в цитадель Громового Молота в долине Призрачной Луны. Верните ему сигнальное ружье клана Громового Молота."}}
D[10777] = {"Тотем Азгара",{"Принесите Паршаху в Магмовые поля военный тотем Скет'лона."}}
D[10778] = {"Жезл Лиантэ",{"Заберите ключ Лиантэ у любого из эльфов крови в лагере Затмения, откройте сейф и заберите жезл Лиантэ. Вернитесь с ветвью к Паршаху в Магмовые поля."}}
D[10779] = {"Путь охотника",{"Поговорите с охотницей Келлой Тетивой Ночи."}}
D[10780] = {"Перья Скет'лона",{"Соберите 8 перьев Скет'лона и принесите их Паршаху в Магмовые поля."}}
D[10781] = {"Битва у Кровавого дозора",{"Сразитесь с войском иллидари возле Кровавого дозора и останьтесь в живых!","","Вернитесь к А'далу в Шаттрат, если сумеете победить."}}
D[10782] = {"Зарядка набалдашника",{"Возьмите в руки Незавершенный Набалдашник. Отправляйтесь к Алтарю Проклятия и используйте его, пока вы находитесь возле Гул'дана. Когда набалдашник зарядится, возвращайтесь к Паршаху в Магмовые Поля."}}
D[10783] = {"Барон Черногрив",{"Поговорите с бароном Черногривом в Круге Крови в Острогорье."}}
D[10784] = {"Уничтожить лагерь Кровавого Молота!",{"Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота."}}
D[10785] = {"Ловушка!",{"Отнесите ловушку пламени дракона Рексару в оплот Громоборцев в Острогорье."}}
D[10786] = {"Резня в Камен'моке",{"Убейте 5 громил и 3 шаманов Камен'мока, затем вернитесь к Тор'чанку Двукогтю в Оплот Громоборцев в Острогорье."}}
D[10788] = {"Возвращение к Талионии",{"Поговорите с Талионией в Луносвете."}}
D[10789] = {"Возвращение к Карендину Халгару",{"Поговорите с Карендином Халгаром в Подгороде."}}
D[10790] = {"Возвращение к Ган'рулу Кровавому Глазу",{"Найдите Ган'рула Кровавого Глаза в Оргриммаре и поговорите с ним."}}
D[10791] = {"Приветствие духа Волка",{"Зажгите обрядовые благовония около свечей в хижине Малуказа и наблюдайте за церемонией. По завершении церемонии поговорите с Малуказом еще раз."}}
D[10792] = {"Сжечь Зет'Гор!",{"Убейте батраков из клана Кровавой Глазницы, заберите у них факелы, зажгите факелы в кузне Зет'Гора и забросьте горящие факелы в строения Зет'Гора."}}
D[10793] = {"Записи Вал'зарека: Предвестье Войны",{"Найдите Марка Аврелиона, верховного генерала Ша'тар в Кровавом дозоре.","","Ищите его в кристаллической тюрьме."}}
D[10794] = {"Разбойники Изувеченной Длани",{"Поговорите с Шентулом в Оргриммаре."}}
D[10795] = {"Встреча с Доргоком",{"Убейте Доргока в лагере Кровавого Молота."}}
D[10796] = {"Уничтожить лагерь Кровавого Молота!",{"Убейте 10 извергов и 5 чернокнижников клана Кровавого Молота."}}
D[10797] = {"Благоволение гронна",{"Отнесите благоволение Горгрома командиру Гефусу Камнестену в Вечную рощу в Острогорье."}}
D[10798] = {"Визит к барону",{"Поговорите с бароном Черногривом, живущим в Круге Крови в Острогорье."}}
D[10799] = {"Прогулка в Беспокойную лощину",{"Соберите 7 ядовитых желез землероев."}}
D[10800] = {"Спи спокойно, гронн",{"Украдите мешок Груллока."}}
D[10801] = {"Ловушка!",{"Отнесите ловушку пламени дракона командиру Гефусу Камнестену в Вечную рощу в Острогорье."}}
D[10802] = {"Горгром Драконоед",{"Добудьте 3 тотема гризли у огров Камен'мока. Поставьте ловушку Черногрива на алтарь Горгрома, затем призовите и убейте Горгрома Драконоеда.","","Когда Горгром будет убит, поставьте 3 тотема гризли возле его туши."}}
D[10803] = {"Резня в Камен'моке",{"Убейте 5 громил и 3 шаманов Камен'мока."}}
D[10804] = {"Доброта",{"Накормите 8 взрослых драконов Пустоты по просьбе Морденая на Полях Крыльев Пустоты."}}
D[10805] = {"Резня в логове Груула",{"Убейте 10 головорезов, 5 боевых магов, 5 опустошителей из клана Камнерогов и их предводителя, Фингрома."}}
D[10806] = {"Перед выстрелом",{"Воспользуйтесь перстнем Черногрива у алтаря Гока, затем убейте Гока."}}
D[10807] = {"Сломленные из племени Пеплоустов",{"Убейте для Варена Исправителя 3 укротителей, 4 воинов и 6 шаманов из племени Пеплоустов.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10808] = {"Крах темного конклава",{"Убейте ритуалистов Темного конклава и используйте посох Паршаха, чтобы прервать ритуал призыва. По выполнении задания вернитесь к Паршаху в Магмовые поля."}}
D[10809] = {"Разыскивается: повелитель воргов Крууш",{"Убейте повелителя воргов Крууша и принесите его голову капитану Мрачному Вою на Заставу Хребтолома."}}
D[10810] = {"Поврежденная маска",{"Отнесите поврежденную маску О'Малли Быстроцапу в Чащобу Рууан в Острогорье."}}
D[10811] = {"Поиски Нельтараку",{"Найдите Нельтараку, предводителя рода Крыльев Пустоты."}}
D[10812] = {"Тайная маска",{"Отнесите таинственную маску Владыке леса Антелариону в Чащобу Рууан в Острогорье."}}
D[10813] = {"Очи Гриллока",{"Используйте кристалл Зеззака, чтобы захватить Око Гриллока, затем приблизьтесь к котлу Зеззака, чтобы тот смог извлечь Око. После выполнения задания верните Зеззаку кристалл."}}
D[10814] = {"История Нельтараку",{"Поговорите с Нельтараку и выслушайте его историю."}}
D[10815] = {"Записи Вал'зарека: Предвестье Войны",{"Найдите Марка Аврелиона, верховного генерала Ша'тар, в Кровавом дозоре."}}
D[10816] = {"Восстановление Святых земель",{"Убейте для воздаятеля Алуумена 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10817] = {"Великое воздаяние",{"Убейте для Варена Исправителя 8 душегубов, 8 избранных и 4 темнопрядов клана Призрачной Луны.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10818] = {"Барон Черногрив желает вас лицезреть",{"Поговорите с бароном Черногривом в Круге Крови в Острогорье."}}
D[10819] = {"Респиратор Искаженных",{"Наденьте респиратор Искаженных и воспользуйтесь переговорным устройством Легиона в Острогорье в Лагере Легиона: Злость."}}
D[10820] = {"Обмануть врага",{"Убейте 4 рабочих Кузни Рока и 4 инженеров Кузни Рока."}}
D[10821] = {"Уволена!",{"Убейте Вестницу Рока."}}
D[10822] = {"Перстень Ярости Солнца"}
D[10823] = {"Больше перстней Ярости Солнца"}
D[10824] = {"Перстни Ярости Солнца",{"Принесите 10 перстней армии Ярости Солнца боевому магу Вияре в святилище Звезд.","","Выполнение заданий Провидцев отрицательно скажется на вашей репутации среди Алдоров."}}
D[10825] = {"Тайна сферы",{"Доставьте сферу Гришны хранителю деревьев Чауну в Вечнуу рощу в Острогорье."}}
D[10826] = {"Знаки Саргераса",{"Принесите 10 знаков Саргераса предвестнику Саронену в Долину Призрачной Луны.","","Выполнение заданий Алдоров отрицательно скажется на вашей репутации среди Провидцев."}}
D[10827] = {"Больше знаков Саргераса"}
D[10828] = {"Знак Саргераса"}
D[10829] = {"Древоствол должен знать!",{"Найдите Древоствола, древо мудрости, обитающее в Лесу Ворона в Острогорье, и поговорите с ним."}}
D[10830] = {"Экзорцизм для деревьев",{"Найдите 5 сфер Гришната и 5 перьев ужасающего ворона и превратите их в перья изгнания духов. При помощи этих перьев изгоните и уничтожьте 5 духов кои-кои из листобородов Леса Ворона."}}
D[10831] = {"Обучение шитью из луноткани",{"Возьмите отрез прочной ткани Пустоты, встаньте в лунный колодец Кенарийского приюта и изготовьте изначальную луноткань. Готовую ткань отнесите Назмаре Песне Луны в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде ткани."}}
D[10832] = {"Обучение шитью из огненной чароткани",{"Принесите образец сущности призрака Пустоты Гидже Чароплетке в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья."}}
D[10833] = {"Обучение шитью из тенеткани",{"Укрепите связь с Алтарем Теней при помощи кристалла Глубоких Теней, после чего вернитесь к Андриону Темнопряду в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде шитья."}}
D[10834] = {"Гриллок \"Пустой Глаз\"",{"Убейте Гриллока Пустого Глаза и принесите Зеззаку на Заставу Хребтолома повязку на глаз Гриллока."}}
D[10835] = {"Аптекарь Антонивич",{"Доставьте послание Албрека аптекарю Антонивичу в Траллмар на Полуостров Адского Пламени."}}
D[10836] = {"Переполох в крепости Драконьей Пасти",{"Убейте 15 орков из клана Драконьей Пасти для Нельтараку.","","Засчитывается орк любого ранга."}}
D[10837] = {"На кряж Крыльев Пустоты!",{"Соберите для Нельтараку 12 кристаллов лозы Пустоты на кряже Крыльев Пустоты."}}
D[10838] = {"Демонический кристалл",{"Отнесите демонический кристалл в Яму Адского Пламени, подождите, пока произойдет соединение, и примите сообщение.","","Верните демонический кристалл и его сообщение аптекарю Антонивичу в Траллмар."}}
D[10839] = {"Гнездовье Скит: Темный камень Терокка",{"Очистите темный камень Терокка в Гнездовье Скит при помощи Жезла Очищения, после чего вернитесь к Киррику Пробужденному в Караван Беженцев в Костяные Пустоши."}}
D[10840] = {"Гробница Света",{"Отправляйтесь в Гробницу Света и убейте там 10 эфириалов-пустомантов и 10 эфириалов-расхитителей, после чего вернитесь к верховному жрецу Орглуму в Караван беженцев."}}
D[10841] = {"Мстительный предвестник"}
D[10842] = {"Мстительные души",{"Верховный жрец Орглум велит вам отправиться в Гробницу Света и убить 5 мстительных дренеев."}}
D[10843] = {"С незапамятных времен...",{"Убейте Гноша Брогната, вождя огров на Заставе Камнерогов."}}
D[10844] = {"Лагерь Легиона: Злоба"}
D[10845] = {"Убить мать драконов",{"Убейте Крыло Ужаса."}}
D[10846] = {"Как понять Мок'Натал",{"Убейте Векха, предводителя араккоа Векх'нира."}}
D[10847] = {"Глаза Скеттиса",{"Принесите Око Рескка и Око Шиенор Рилаку Освобожденному в Нижний Город Шаттрата."}}
D[10848] = {"Гнездовье Рейз: неживое зло",{"Убейте 4 духа Когтя Смерти, 4 кричащих духа и 2 духа ворона, после чего вернитесь к Киррику Пробужденному в Караван Беженцев."}}
D[10849] = {"Поиски Киррика",{"Отнесите послание Риллака Киррику Пробужденному в Караван беженцев на Костяных Пустошах."}}
D[10850] = {"Газ хаоса в двигателе"}
D[10851] = {"Тотем врага моего",{"Добудьте 5 тотемов Камнерогов."}}
D[10852] = {"Пропавшие друзья",{"Найдите 12 друзей Итана в гнездовье Скит и вернитесь к нему в Караван беженцев."}}
D[10853] = {"Призыв духов",{"Соберите 8 духов младших драконов Пустоты при помощи тотемов вызова духов."}}
D[10854] = {"Силы Нельтараку",{"Освободите для Нельтараку 5 порабощенных драконов Крыльев Пустоты."}}
D[10855] = {"Сквернобот – нет, спасибо!",{"Заберите 5 единиц конденсированного газа Пустоты у ган'аргов-анжинеров на базе Легиона: Забвение, к северо-западу от Штормовой Вершины, и загрузите их в ближайший бездействующий сквернобот. После завершения задачи возвращайтесь к ловчему Пустоты Наутису."}}
D[10856] = {"Наилучшая защита",{"Ловчий Пустоты Наутис просит вас убить 12 вестников гнева на базе Легиона: Геенна к северу от Штормовой Вершины."}}
D[10857] = {"Телепортируй это!",{"Ловчий Пустоты Наутис просит вас применить жезл ментального вмешательства против мо'аргов, находящихся в лагере Легиона: Геенна и использовать их способность взорвать телепорт для того, чтобы уничтожить три телепорта в лагере Легиона."}}
D[10858] = {"Каринаку",{"Найдите Каринаку в крепости Драконьей Пасти."}}
D[10859] = {"Собрать шары",{"Соберите 15 световых сфер братства Разаани при помощи тотема для собирания сфер."}}
D[10860] = {"Лакомства Мок'Натал",{"Добудьте 3 ребра ящера и 3 куска змеиного мяса."}}
D[10861] = {"Гнездовье Литик: превентивный удар",{"Разбейте проклятые яйца в Гнездовье Литик. Освободите 3 птенцов и убейте 3 злобных птенцов, после чего вернитесь к Киррику Пробужденному в Караван беженцев."}}
D[10862] = {"Сдаться Орде",{"Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и потребуйте, чтобы он и его народ сдались Орде, как велел вам Рокаг."}}
D[10863] = {"Тайны араккоа",{"Найдите Рилака Освобожденного в Нижнем Городе Шаттрата и попытайтесь выведать у него несколько секретов араккоа по просьбе леди Дены Кеннеди."}}
D[10864] = {"Урожай душ",{"Убейте 20 орков из клана Изувеченной Длани, затем возвращайтесь к аптекарю Антонивичу в Траллмар."}}
D[10865] = {"Доложить Леороксу!",{"Расскажите Леороксу о том, что затеяли духи астрала Разаани. Его можно найти в деревне Мок'Натал в Острогорье."}}
D[10866] = {"Зулухед Измученный",{"Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку."}}
D[10867] = {"Ответ будет только один",{"Добудьте Собрание душ."}}
D[10868] = {"Тропа войны араккоа",{"Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к советнице Файле в форт Камнеломов."}}
D[10869] = {"Уменьшить стаю",{"Убейте 14 шиенорских когантов и 6 шиенорских колдунов, после чего вернитесь к лейтенанту Булыжному Молоту в бастион Аллерии."}}
D[10870] = {"Союзник Крыльев Пустоты",{"Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты."}}
D[10871] = {"Союзник Крыльев Пустоты",{"Позвольте Каринаку отнести вас к Морденаю на Поля Крыльев Пустоты."}}
D[10872] = {"Зулухед Измученный",{"Убейте Зулухеда Измученного и заберите Ключ Зулухеда. Используйте его на цепях Зулухеда, чтобы освободить Каринаку."}}
D[10873] = {"Захваченные в ночи",{"Пойдите на Гряду Пустопутов и освободите там 6 опутанных воинов Ша'тар, после чего вернитесь к разведчику Наврину на заставу Ша'тар."}}
D[10874] = {"Гнездовье Шалас: сигнальные огни",{"Потушите четыре сигнальных огня в Гнездовье Шалас по просьбе Киррика Пробужденного из Каравана Беженцев."}}
D[10875] = {"Донесение Назгрелу",{"Поговорите с Назгрелом в Траллмаре на Полуострове Адского Пламени."}}
D[10876] = {"Вступить в цитадель",{"Убейте командира соединения Горакса, положите на его труп Вызов Орды, убейте прислужника Каргата и принесите голову прислужника Каргата Назгрелу в Траллмар."}}
D[10877] = {"Реликвия Ужаса",{"Отыщите Реликвию Ужаса к востоку от Брошенного каравана, после чего вернитесь к Оакуну."}}
D[10878] = {"До наступления тьмы",{"Убейте 8 кабалистов-рыскателей, 4 кабалистов-чаропрядов и 2 кабалистов-посвященных по просьбе Мекеды из Каравана Беженцев."}}
D[10879] = {"Нападение Скеттиса",{"Отбейте атаку, а потом поговорите с Рилаком."}}
D[10880] = {"Распоряжения заговорщиков",{"Принесите кабалистические приказы Мекеде в караван беженцев в Костяных пустошах."}}
D[10881] = {"Гробница Тени",{"Войдите в Гробницу Тени, что к западу от Каравана беженцев и найдите там пелерину Арунена, молот К'алена и свиток Аталора, после чего вернитесь к Мекеде в Караван беженцев."}}
D[10882] = {"Вестник Рока",{"Отправьтесь в спутник Крепости Бурь Аркатрац и убейте там предвестника Скайрисса, после чего вернитесь к А'далу на террасу Света в Шаттрат."}}
D[10883] = {"Ключ Урагана",{"Поговорите с А'далом в Шаттрате."}}
D[10884] = {"Испытание наару: милосердие",{"А'дал из Шаттрата просит добыть неиспользованный топор палача из Разрушенных залов цитадели Адского Пламени.","","Это задание выполняется только в героическом режиме."}}
D[10885] = {"Испытание наару: сила",{"А'дал из Шаттрата просит добыть трезубец Калитреша и сущность Бормотуна.","","Это задание выполняется только в героическом режиме."}}
D[10886] = {"Испытание наару: упорство",{"А'дал из Шаттрата просит спасти Милхауса Манашторма из Аркатраца, что в Крепости Бурь.","","Это задание выполняется только в героическом режиме."}}
D[10887] = {"Побег из гробницы",{"Помогите Акуно добраться до Каравана беженцев, после чего поговорите с Мекедой."}}
D[10888] = {"Испытание наару: Магтеридон",{"По заданию А'дала из Шаттрата убейте Магтеридона."}}
D[10889] = {"Обратно в Шаттрат",{"Доберитесь до Шаттрата и поговорите там с Рилаком Освобожденным в Нижнем Городе."}}
D[10891] = {"Имперские латы",{"Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе."}}
D[10892] = {"Имперские латы",{"Поговорите с Деротайном Грязеглотом в Прибамбасске, что в Танарисе."}}
D[10893] = {"За всем стоит Длиннохвостка",{"Устраните Драаку Длиннохвостку, предводительницу служителей культа Змея в туннеле Драконьего черепа."}}
D[10894] = {"Страж Драконьего черепа",{"Передайте записку о встрече дозорному Лунному Сумраку у входа в туннель Драконьего черепа в Острогорье."}}
D[10895] = {"Сжечь Зет'Гор!",{"Установите дымовые маяки у каждой из башен Зет'Гора и возвращайтесь к командиру звена Даби'ри в лагерь экспедиции."}}
D[10896] = {"Зараженные защитники",{"Убейте 25 лесных клещей и вернитесь к Лакотаю в Караван беженцев. Клещи живут в телах гниющих лесных гневней и зараженных корнеходов."}}
D[10897] = {"Мастер зелий",{"Отправляйтесь в Ботанику в Крепости Бурь и добудьте у старшего ботаника Фрейвинна \"Полевой справочник ботаника\". Принесите его Лоранне Тар'велл вместе с 5 отменными лечебными зельями, 5 отменными зельями маны и 5 большими зельями спокойного сна.","","<ВНИМАНИЕ!> Вы можете избрать только одну алхимическую специальность!"}}
D[10898] = {"Небокрыл",{"Проводите Небокрыла и вернитесь к Рилаку Освобожденному в Шаттрат."}}
D[10899] = {"Мастер трансмутации",{"Заревхи, находящийся Штормовой Вершине в Пустоверти просит вас принести ему 4 единицы изначальной мощи.","","ВНИМАНИЕ! Вы можете выбрать только одну алхимическую специализацию."}}
D[10900] = {"Медальон Вайш"}
D[10901] = {"Дубина Кардеша",{"Принесите печати земли и огня Скартису Еретику в Узилище (героический уровень сложности) в резервуар Кривого Клыка."}}
D[10902] = {"Мастер эликсиров",{"Отправляйтесь в Черные топи в Пещерах времени и добудьте 10 кристаллов сути бесконечности с повелителей и хранительниц временных разломов. Затем отнесите кристаллы, 5 хороших эликсиров защиты, 5 эликсиров власти и 5 хороших эликсиров ловкости Лорокиму в Нижний город Шаттрата.","","ВНИМАНИЕ! Вы можете специализироваться только на одном виде алхимии."}}
D[10903] = {"Возвращение в Оплот Чести",{"Поговорите с ассистентом Клату. Его можно найти в таверне Оплота Чести."}}
D[10904] = {"Боеприпасы Скверны",{"Соберите 5 ядер пушек Скверны."}}
D[10905] = {"Мастер зелий",{"Поговорите с Лоранной Тар'велл в Кенарийском приюте в Зангартопи.","","ВНИМАНИЕ! Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10906] = {"Мастер эликсиров",{"Поговорите с Лорокимом из Нижнего города Шаттрата.","","ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10907] = {"Мастер трансмутации",{"Поговорите с Заревхи из Штормовой Вершины Пустоверти.","","ВНИМАНИЕ!Вы можете выбрать лишь одно из направлений алхимии!"}}
D[10908] = {"Поговорите с Рилаком Освобожденным",{"Поговорите с Рилаком Освобожденным в Нижнем Городе Шаттрата по просьбе Киррика Пробужденного."}}
D[10909] = {"Духи Скверны",{"Задействуйте по просьбе Клату из Оплота Чести реликвию анахорета на Заставе Горгаза, к юго-западу от Оплота Чести, и убивайте берсерков из клана Изувеченной Длани рядом с этой реликвией. После этого уничтожьте 10 освобожденных духов Скверны, чтобы отомстить за полковника Джулса."}}
D[10910] = {"Врата Смерти",{"Воспользуйтесь сигнальным огнем друидов возле Врат Смерти, чтобы призвать друидов Вечной рощи и поговорить с ними."}}
D[10911] = {"Открыть огонь!",{"Используйте боеприпасы, наполненные силой Природы, для установления контроля над пушками Скверны Врат Смерти. Разрушьте Северный и Южный порталы при помощи пушек."}}
D[10912] = {"Псарь",{"Убейте Балмона Псаря."}}
D[10913] = {"Недостойные похороны",{"Сожгите 8 убитых аукенайских воинов и 8 павших поборников Ша'тар по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10914] = {"Требуется герой",{"Убейте 12 аукенайских посвященных и 5 аукенайских прорицателей по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10915] = {"Падший экзарх",{"Уничтожьте содержимое аукенайского гроба по поручению командира Ра'ваджа. Командира можно найти на заставе Ша'тар в Костяных пустошах в лесу Тероккар."}}
D[10916] = {"Откопать благословенные четки",{"Разыщите дренейские четки и принесите их ассистенту Клату в Оплот Чести."}}
D[10917] = {"Затруднительное положение изгнанника",{"Принесите 30 перьев араккоа Векаксу в Нижний город Шаттрата."}}
D[10918] = {"Больше перьев"}
D[10919] = {"Собачья радость"}
D[10920] = {"За павших",{"Убейте 20 жуткопалых черных вдов и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов."}}
D[10921] = {"Тероккарантул",{"Убейте Тероккарантула и вернитесь к воздаятелю Хайлену на западную сторону Гряды Пустопутов."}}
D[10922] = {"Костяные раскопки",{"Проводите Летолла и его команду и защищайте их, пока они будут копать. После этого вернитесь к Дворфовитцу на заставу Ша'тар."}}
D[10923] = {"Зло приближается",{"Отнесите Реликвию Ужаса на Перекопанный курган, как вам велел Оакун. В круге убивайте аукенайских вестников смерти и прорицателей, пока не соберете 20 роковых черепов. Затем найдите круг призыва Призрачного Кургана, при помощи Реликвии Ужаса призовите Жутуса Проклятого, убейте его и вернитесь к Оакуну."}}
D[10924] = {"Кровная м... есть!",{"Принесите 8 фиалов крови прыгуаны-ловца Саб'аофу, находящемуся в Космовороте."}}
D[10925] = {"Зло приближается"}
D[10926] = {"Обратно в лагерь Ша'тар",{"Вернитесь в лагерь Ша'тар и поговорите с разведчиком Наврином в Костяных пустошах по просьбе воздаятеля Хайлена."}}
D[10927] = {"Убийство пауков",{"Убейте 6 пещерных пауков."}}
D[10928] = {"Убийство пауков",{"Убейте 6 пещерных пауков."}}
D[10929] = {"Барабанный бой",{"Принесите 8 трупов взрослых просеивателей костей Дворфовитцу в лагерь Ша'тар в Костяных пустошах."}}
D[10930] = {"Большой костяной червь",{"Принесите органы гигантского костяного червя Дворфовитцу в лагерь Ша'тар в Костяных пустошах.","","Заодно верните ему барабан Фампер."}}
D[10931] = {"Возвращение в Экзодар",{"Поговорите с Кедмосом в Экзодаре."}}
D[10932] = {"Возвращение в Экзодар",{"Поговорите с Кедмосом в Экзодаре."}}
D[10933] = {"Возвращение в Луносвет",{"Поговорите с Альдрэ из Луносвета."}}
D[10934] = {"Возвращение в Луносвет",{"Поговорите с Альдрэ из Луносвета."}}
D[10935] = {"Экзорцизм над полковником Джулсом",{"Поговорите с анахоретом Берада. Используйте благословенные четки, чтобы провести ритуал. После окончания ритуала поговорите со спасенным полковником Джулсом. Возвращайтесь к ассистенту Клату."}}
D[10936] = {"Тебя ищет Троллебой",{"Ассистент Клату сообщает, что вас искал командир армии Данат Троллебой. Поговорите с Данатом в казармах Оплота Чести на полуострове Адского Пламени."}}
D[10937] = {"Перемастерить мастера",{"Убейте военного инструктора Зурока, и как можно скорее. Это приказ боевого командира командира армии Даната Троллебоя. После выполнения задания возвращайтесь к Данату в Оплот Чести на полуострове Адского Пламени."}}
D[10938] = {"Колода карт Новолуния: Благословения",{"Принесите колоду Благословений на ярмарку Новолуния."}}
D[10939] = {"Колода карт Новолуния: Вихри",{"Принесите карты Вихрей на ярмарку Новолуния."}}
D[10940] = {"Колода карт Новолуния: Ярость",{"Принесите карты Ярости на ярмарку Новолуния."}}
D[10941] = {"Колода карт Новолуния: Безумие",{"Принесите колоду Безумия на ярмарку Новолуния."}}
D[10942] = {"Детская неделя",{"Дуньте в эльфийскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели."}}
D[10943] = {"Детская неделя",{"Продудите в дренейскую детскую свистульку. Присматривайте за сиротой в течение всей Детской недели."}}
D[10944] = {"Тайна под угрозой",{"Отправляйтесь в Клеть Стражницы в долину Призрачной Луны и поговорите с Акамой."}}
D[10945] = {"Хч'уу и народ грибов",{"Отведите вашу подопечную Саландрию, в Спореггар в Зангартопь. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с Хч'уу."}}
D[10946] = {"Коварство Пеплоустов",{"Отправляйтесь в Крепость Бурь и, облачившись в клобук Пеплоуста, убейте Ал'ара. Затем возвращайтесь к Акаме в долину Призрачной Луны."}}
D[10947] = {"Артефакт из прошлого",{"Отправляйтесь в пещеры Времени в Танарисе и вступите в битву за гору Хиджал. Сразите Лютого Хлада и принесите амулет из прошлого Акаме в долину Призрачной Луны."}}
D[10948] = {"Пленная душа",{"Отправляйтесь в Шаттрат и расскажите А'далу о просьбе Акамы."}}
D[10949] = {"Вход в Черный храм",{"Отправляйтесь ко входу в Черный храм в долине Призрачной Луны и поговорите с Зи'ри."}}
D[10950] = {"Аукиндон и Ритуальный Круг",{"Отведите свою подопечную, сиротку Дорнаа, к камню встречи у Ритуального круга в центра Аукиндона. Аукиндон находится в центре Костяных пустошей, что в лесу Тероккар. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом."}}
D[10951] = {"Путешествие к Темному порталу",{"Отведите свою подопечную, сиротку Саландрию, на Ступени Судьбы, к Темному порталу на полуострове Адского Пламени. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом."}}
D[10952] = {"Путешествие к Темному порталу",{"Отведите свою подопечную, сиротку Дорнаа, на Ступени Судьбы, к Темному порталу на полуострове Адского Пламени. Обязательно призовите Дорнаа, если по прибытии ее не будет рядом."}}
D[10953] = {"Путешествие к Трону стихий",{"Отведите свою подопечную, сиротку Саландрию, к Трону стихий в Награнд. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом. Затем поговорите с повелительницей стихий Шарвак."}}
D[10954] = {"Джил находится в Небесном лагере!",{"Отведите свою подопечную, сиротку Дорнаа, в Небесный лагерь в Награнде. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом. Затем поговорите с Джилом."}}
D[10955] = {"Мортис Шелест Крыла",{"Найдите Мортиса Шелест Крыла в Кенарийском приюте в Зангартопи."}}
D[10956] = {"Трон наару",{"Отведите свою подопечную, сиротку Дорнаа, к О'росу, который находится у подножия Трона наару в Экзодаре. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.","","Не забывайте пользоваться картой, чтобы сориентироваться в столице."}}
D[10957] = {"Искупление Пеплоустов",{"Верните Акаме власть над его душой, сразив тень Акамы в Черном храме. Затем возвращайтесь в провидцу Канаи."}}
D[10958] = {"Найти Пеплоустов",{"Найдите Служителей Смерти Акамы в Черном храме."}}
D[10959] = {"Судьба Предателя",{"Провидец Канаи хочет, чтобы вы победили Иллидана в Черном храме."}}
D[10960] = {"Когда я вырасту..."}
D[10961] = {"Зелье пробуждения",{"Принесите 10 топлянников, 10 древних лишайников и 10 цветков сияния грез Мортису Шелесту Крыла в Кенарийский приют."}}
D[10962] = {"Время посетить Пещеры",{"Отведите свою подопечную, сиротку Дорнаа, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Дорнаа, если по прибытии ее не окажется рядом.","","Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, в конце входного туннеля."}}
D[10963] = {"Время посетить Пещеры",{"Отведите свою подопечную, сиротку Саландрию, к дракону на возвышении в центре пещер Времени, Заладорму. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом.","","Купите ей игрушечного дракона у начальника снабжения Хранителей Времени, Алурми, у входа в туннель."}}
D[10964] = {"Пробуждение спящего",{"Разбудите Клинтара Странника Снов при помощи зелья Пробуждения. Когда он придет в себя, поговорите с ним."}}
D[10965] = {"Не просто сон",{"Охраняйте дух Клинтара Странника Снов, пока он будет собирать реликвии Авианы. Потом поговорите с Луросой Хранительницей Снов."}}
D[10966] = {"Возвращение в приют",{"Отведите свою подопечную обратно в приют Шаттрата, вернув дренейскую детскую свистульку попечительнице сирот Миле в Нижнем городе."}}
D[10967] = {"Возвращение в приют"}
D[10968] = {"Зов предсказателя"}
D[10969] = {"В поисках Амира",{"Найдите командира Амира на заставе стражей Протектората."}}
D[10970] = {"Миссия милосердия",{"Раздобудьте ключ от найденной темницы Эфириума для командира Амира, находящегося на заставе стражей Протектората в Пустоверти."}}
D[10971] = {"Секреты Эфириума",{"Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, просит вас принести ему бирки пленников Эфириума."}}
D[10972] = {"Каталог бирок пленников Эфириума"}
D[10973] = {"Тысяча миров",{"Командир Амир, находящийся на заставе стражей Протектората в Пустоверти, хочет, чтобы вы принесли ему 5 ключей от тюрьмы братства Эфириум."}}
D[10974] = {"Стазисные камеры Баш'ира",{"Используйте табличку-ключ \"Альфа\" Эфириума, чтобы открыть стазисную камеру \"Альфа\" в лагере Баш'ира в Острогорье.","","Предоставьте свидетельства из камеры \"Альфа\" проекции командира Амира в лагере Баш'ира."}}
D[10975] = {"Очищение камер Баш'ира"}
D[10976] = {"Знак короля нексуса",{"Проекция командира Амира, находящаяся в лагере Баш'ира в Острогорье просит вас принести ему знак короля нексуса."}}
D[10977] = {"Стазисные камеры Гробниц маны",{"Проекция командира Амира, находящаяся в лагере Баш'ира в Острогорье просит вас использовать ключ от стазисной камеры Гробниц маны, чтобы открыть стазисную камеру внутри Гробниц маны Аукиндона.","","Это задание можно выполнить только в героическом режиме."}}
D[10978] = {"Возвращение к Мортису Шелесту Крыла",{"Отнесите реликвии Авианы Мортису Шелесту Крыла в Кенарийский приют в Зангартопи."}}
D[10979] = {"В Вечную рощу",{"Поговорите с Арторн Песней Ветра из Вечной рощи, что в Острогорье."}}
D[10980] = {"Книга Ворона",{"Усильте свое зрение при помощи ока летучего ската и камня Провидца и разгядите призраков сторонников культа Ворона. Отыщите на Нагорье Смерчей старейшину Сай'ккала и расспросите его про книгу Ворона. Затем возвращайтесь к Арторн Песне Ветра."}}
D[10981] = {"Личная палата принца Шаффара"}
D[10982] = {"Око Харамада"}
D[10983] = {"Мог'дорг Мудрый",{"Сходите к Мог'доргу Мудрому, который живет на вершине башни в Острогорье, сразу за Кругом Крови."}}
D[10984] = {"Разговор с огром",{"Поговорите с огром по имени Грок в Нижнем городе Шаттрата."}}
D[10985] = {"Отвлекающий маневр",{"Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Зи'ри совершат отвлекающий маневр."}}
D[10986] = {"Небесные очи",{"Поговорите с дозорной Элайрой на Сумеречной гряде в Награнде."}}
D[10987] = {"Поймать скальную пустельгу",{"Поймайте дикую пустельгу при помощи специальной сети и принесите ее дозорной Элайре на Сумеречную гряду."}}
D[10988] = {"Вороньи камни",{"Соберите в Скеттисе 8 вороньих камней и принесите их Арторн Песне Ветра в Вечную рощу в Острогорье."}}
D[10989] = {"Мог'дорг Мудрый",{"Поговорите с Мог'доргом Мудрым на вершине башни, где стоит Фырк, прямо у Круга Крови в Острогорье."}}
D[10990] = {"Сущность орла",{"Одолейте стража Орла и добудьте у него сущность орла. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.","","Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым."}}
D[10991] = {"Сущность сокола",{"Одолейте стража Сокола и добудьте у него сущность сокола. Призовите пустельгу Арторн особым манком, чтобы сообщить новости об успешном выполнении задания.","","Если вы потеряете манок Арторн для пустельги, вернитесь к Арторн в Вечную рощу за новым."}}
D[10992] = {"Сущность ястреба",{"Одолейте стража Ястреба и принесите сущность ястреба Арторне Песне Ветра в Вечную рощу."}}
D[10993] = {"Возвращение в Кенарийский приют",{"Отнесите сверток Арторны Мортису Шелесту Крыла в Кенарийский приют."}}
D[10994] = {"В поисках лунного камня",{"Принесите лунный камень реки Строптивая Мортису Шелесту Крыла в Кенарийский приют."}}
D[10995] = {"У Груллока два черепа",{"Добудьте драконий череп Груллока."}}
D[10996] = {"Сундук с сокровищами Маггока",{"Добудьте сундук с сокровищами Маггока."}}
D[10997] = {"Даже у гроннов есть штандарты",{"Добудьте штандарт Слаага."}}
D[10998] = {"Черно(книжн)ый бизнес",{"Добудьте гримуар Вимгола Зловещего."}}
D[11000] = {"В сердце Разрушителя Душ",{"Добудьте душу Черепона."}}
D[11001] = {"Изгнание бога-ворона",{"Убейте бога-ворона и возвращайтесь к Мортису Шелесту Крыла в Кенарийский приют.","","","","Это задание выполняется только в героическом режиме."}}
D[11002] = {"Падение Магтеридона",{"Доставьте голову Магтеридона командиру армии Данату Троллебою в Оплот Чести на полуострове Адского Пламени."}}
D[11003] = {"Падение Магтеридона",{"Доставьте голову Магтеридона Назгрелу в Траллмар на полуострове Адского Пламени."}}
D[11004] = {"Мир Теней",{"Проберитесь в Скеттис и добудьте 6 горстей теневой пыли с местных араккоа, после чего отнесите пыль Северину."}}
D[11005] = {"Тайны жрецов Когтя",{"Возьмите у Северина эликсир теней и с его помощью найдите и убейте жрецов Когтя: Ишааля, Скиззика и Зеллека в Скеттисе. После этого вернитесь к командиру Адарису."}}
D[11006] = {"Больше теневой пыли"}
D[11007] = {"Кель'тас и зеленеющая сфера",{"Отнесите зеленеющую сферу А'далу в Шаттрат."}}
D[11008] = {"Огонь над Скеттисом",{"Найдите яйца чудовищных калири на верхушках домов Скеттиса и сбросьте на них взрывчатку Стражи Небес, после чего вернитесь к небесному сержанту Дорину."}}
D[11009] = {"Огрские небеса",{"Поговорите с Чу'а'лором в Огри'ле в Острогорье."}}
D[11010] = {"Бомбардировка",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11011] = {"Вечная бдительность",{"Попросите у Мортиса Шелеста Крыла лунный камень Сущности."}}
D[11012] = {"Клятва в верности Крыльям Пустоты"}
D[11013] = {"В услужении у Иллидари",{"Отправляйтесь на кряж Крыльев Пустоты и доставьте докладные записки иллидари воеводе Мор'гору, в лагере Драконьей Пасти."}}
D[11014] = {"Задание десятника",{"Поговорите с надсмотрщиком Варкулом Дыханием Дракона в лагере клана Драконьей Пасти."}}
D[11015] = {"Кристаллы Крыльев Пустоты",{"Принесите 30 кристаллов Крыльев Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти."}}
D[11016] = {"Шкуры живодеров-пустокопов",{"Принесите 35 шкур живодеров-пустокопов из Копей Пустоты надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11017] = {"Пыльца пустопраха",{"Принесите 40 порций пыльцы пустопраха надсмотрщику Варкулу Дыханию дракона в лагерь Драконьей Пасти."}}
D[11018] = {"Хаотитовая руда",{"Принесите 40 порций хаотитовой руды надсмотрщику Варкулу Дыханию Дракона в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11019] = {"Друг в тылу врага"}
D[11020] = {"Медленная смерть",{"Возьмите у Язрилла Наемника из долины Призрачной Луны баранину. Смешайте ее с оскверненными железами и отравите 12 лагерей батраков из клана Драконьей Пасти."}}
D[11021] = {"Альманах Ишааля",{"Принесите альманах Ишааля небесному командиру Адарису к северу от Скеттиса."}}
D[11022] = {"Разговор с Мог'доргом",{"Поговорите с Мог'доргом Мудрым. Он находится на вершине башни на восточной стороне Круга Крови в Острогорье."}}
D[11023] = {"Еще разок задать им жару!",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11024] = {"Союзник в Нижнем городе",{"Принесите альманах Ишааля Рилаку Освобожденному в Нижний Город Шаттрата."}}
D[11025] = {"Кристаллы",{"Добудьте 5 осколков апексита."}}
D[11026] = {"Гони демонов!",{"При помощи кристалла изгоните 15 демонов из Лагеря Легиона: Гнев или Ужас в Острогорье."}}
D[11027] = {"Есть у тебя темная руна?"}
D[11028] = {"Оставшееся время",{"Расскажите небесному капитану Адарису о возвращении Терокка. Вы сможете найти его в лагере Черного Ветра в лесу Тероккар."}}
D[11029] = {"Потрепанная маскировка",{"Оденьтесь в потрепанный маскировочный костюм араккоа, возьмите книгу \"Кровная вражда\" у Сахаака и вернитесь к Хаззику."}}
D[11030] = {"Наш мальчик хочет быть следопытом Стражи Небес",{"Добудьте нестабильный настой Зверя."}}
D[11031] = {"Перестать быть верховным магом из Аметистового Ока"}
D[11032] = {"Перестать быть защитником из Аметистового Ока"}
D[11033] = {"Перестать быть убийцей из Аметистового Ока"}
D[11034] = {"Перестать быть исцелителем"}
D[11035] = {"Недружелюбные небеса",{"Верните Язриллу Наемнику в лагере Драконьей Пасти в долине Призрачной Луны 10 реликвий Крыльев Пустоты."}}
D[11036] = {"Еще один пункт долой!",{"Доставьте консервированные фрукты командующему ракетами Фюзеляжу в Зону 52 Пустоверти."}}
D[11037] = {"Странное видение",{"Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52."}}
D[11038] = {"Помощь экзарху Орелису",{"Поговорите с экзархом Орелисом в Зоне 52."}}
D[11039] = {"Отчет патрону шпионов Талодиену",{"Доложитесь патрону шпионов Талодиену в Зоне 52."}}
D[11040] = {"Детали для ведущего ракетостроителя",{"Доставьте запчасти Босси командующему ракетами Фюзеляжу в Зону 52 Пустоверти."}}
D[11041] = {"Неоконченное дело",{"Убейте 10 надземных живодеров и Бараш Мать Стаи. По выполнении вернитесь к властителю Мор'гору в лагерь Драконьей Пасти."}}
D[11042] = {"Таинственное видение",{"Поговорите с ведущим ракетостроителем Фьюзеляжем в Зоне 52."}}
D[11043] = {"Усовершенствованный грифон",{"Поговорите с Брюнном Жаробородом в Цитадели Громового Молота в Долине Призрачной Луны."}}
D[11044] = {"Страшные видения",{"Поговорите с командиром звена Нуаинном в цитадели Громового Молота."}}
D[11045] = {"Зорус Ревнитель",{"Поговорите с Зорусом Ревнителем в цитадели Громового Молота."}}
D[11046] = {"Главный аптекарь Хильдегард",{"Поговорите с главным аптекарем Хильдегард в деревне Призрачной Луны."}}
D[11047] = {"Просьба ученика",{"Поговорите с Дамой Буйногривой в Деревне Призрачной Луны, что находится в Долине Призрачной Луны."}}
D[11048] = {"Рапорт Крогхана",{"Объясните кровавому стражу Галмоку в деревне Призрачной Луны, почему Крогхан не может явиться к нему."}}
D[11049] = {"Большая Охота",{"Найдите яйцо дракона Крыльев Пустоты для Язрилла Наемника, находящегося в лагере Драконьей Пасти, что в долине Призрачной Луны."}}
D[11050] = {"Собрать их все!"}
D[11051] = {"Демонов – долой!",{"При помощи кристалла изгоните 15 демонов из Лагеря Легиона: Гнев или Ужас в Острогорье."}}
D[11052] = {"Обещание Акамы",{"Принесите медальон Карабора А'далу в Шаттрат."}}
D[11053] = {"Новое назначение",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11054] = {"Ты – инспектор: как делать все правильно",{"Принесите 10 кусков узловатой кожи и прочную шкуру Тирантия надзирателю Грязевику в лагерь Драконьей Пасти в долине Призрачной Луны."}}
D[11055] = {"Ботиранг: лекарство для нерадивых батраков",{"Призовите к порядку 20 ленивых батраков в лагере Драконьей Пасти. Ботиранг нужно будет вернуть надзирателю Грязевику."}}
D[11056] = {"Просьба Хаззика",{"Заберите сверток Хаззика из его дома в восточном Скеттисе и верните сверток хозяину."}}
D[11057] = {"Огрское подполье",{"Поговорите с Мог'доргом Мудрым на вершине одной из башен рядом с Кругом Крови в Острогорье."}}
D[11058] = {"Апекситовая реликвия",{"Получените вибрации Апекса от апекситовой реликвии."}}
D[11059] = {"Страж монумента",{"Принесите голову стража апексидов."}}
D[11060] = {"Кристалл с темными рунами"}
D[11061] = {"Отцовский долг",{"Добудьте нестабильный настой волшебника."}}
D[11062] = {"Застава Стражи Небес",{"Поговорите с небесным командиром Келлером на заставе Стражи Небес на вершинах Острогорья."}}
D[11063] = {"Заработай крылья"}
D[11064] = {"Гонки Драконьей Пасти: баллада о старине Макстаре",{"Следуйте за \"Стариной\" Маргом Сквернословом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11065] = {"Ловим летучих скатов!",{"Поймайте 5 летучих скатов при помощи веревочного аркана."}}
D[11066] = {"Нам нужно больше летучих скатов!",{"Поймайте 5 летучих скатов при помощи веревочного аркана."}}
D[11067] = {"Гонки Драконьей Пасти: Троп Смраднорыг",{"Следуйте за Тропом Смраднорыгом, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11068] = {"Гонки Драконьей Пасти: Корлок Ветеринар",{"Следуйте за Корлоком Ветеринаром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11069] = {"Гонки Драконьей Пасти: командир звена Ромеон",{"Следуйте за командиром звена Ромеоном, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11070] = {"Гонки Драконьей Пасти: командир звена Маэстр",{"Следуйте за командиром звена Маэстром, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11071] = {"Гонки Драконьей Пасти: капитан Небокрушитель",{"Следуйте за капитаном Небокрушителем, пытаясь удержаться на своем средстве передвижения. Если вам удастся победить его, сообщите об этом Джаю Нослаю в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11072] = {"Кровные враги",{"Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттика, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра."}}
D[11073] = {"Падение Терокка",{"Возьмите приготовленное Хаззиком Подношение Затерянного во Времени и отнесите его к груде черепов в центре Скеттиса. С помощью подношения призовите Терокка и сразитесь с ним, после чего вернитесь к небесному командиру Адарису."}}
D[11074] = {"Кровные враги",{"Добудьте у затерянных во времени араккоа их свитки и отнесите их к груде черепов в центре круга призыва в Скеттисе. Вызовите и победите потомков врагов Терокка, после чего отнесите Хаззику коготь Аккарая, хребет Гарокка, чешую Векказа и коготь Геззарака."}}
D[11075] = {"Копи Крыльев Пустоты",{"Найдите Госпожу Копей на кряже Крыльев Пустоты."}}
D[11076] = {"Собрать по кусочкам...",{"Соберите для Госпожи Копей груз 15 тачек в Долине Призрачной Луны."}}
D[11077] = {"Драконы – это не самое страшное",{"Убейте 15 живодеров-пустокопов и 5 опустошителей-пустокопов из Копей Пустоты для штейгера из клана Драконьей Пасти."}}
D[11078] = {"В небесах останется только один!",{"Добудьте драконьи зубы."}}
D[11079] = {"Бич Скверны для Гахка",{"Добудьте бич Скверны."}}
D[11080] = {"Излучение реликвии",{"Испытайте на себе излучение от апекситовой реликвии."}}
D[11081] = {"Восстание в племени Темной Крови",{"Отнесите планы побега племени Темной Крови Госпоже Копей."}}
D[11082] = {"Искатель Истины",{"Найдите надзирателя из племени Темной Крови и допросите его. Вернитесь к Госпоже Копей с информацией об организаторе побега и рукой надзирателя."}}
D[11083] = {"Спятившие и очень опасные...",{"Убейте для Ронага Деспота из копей Крыльев Пустоты безумного штейгера и 5 шахтеров из племени Темной Крови."}}
D[11084] = {"Стой прямо, капитан!",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11085] = {"Побег из Скеттиса",{"Проводите плененного Стража Небес в безопасное место, а затем доложите небесному сержанту Дорину."}}
D[11086] = {"Разрушение сумеречного портала",{"По поручению властителя Мор'гора из лагеря Драконьей Пасти в долине Призрачной Луны убейте 20 посланников Смертной Тени."}}
D[11089] = {"Пушка души Рет'хедрона",{"Принесите повелителю иллидари Балтасу, находящемуся в лагере Драконьей Пасти, 2 слитка оскверненной стали, 1 адамантитовую рамку, 1 кориевый сердечник и 1 безупречную чародейскую сущность."}}
D[11090] = {"Покорить Покорителя",{"Используйте пушку душ против Рет'хедрона Покорителя в Награнде. Потом верните пушку повелителю иллидари Балтасу в лагерь Драконьей Пасти, в долине Призрачной Луны."}}
D[11091] = {"Особая благодарность",{"Поговорите с Джо'нассом в Огри'ле на вершинах Острогорья."}}
D[11092] = {"Приветствую тебя, Командир!",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11093] = {"Пропитание для скатов Пустоты",{"Возьмите клетку для скатов Пустоты в лес к югу от лагеря Черного Ветра и убейте прыгуан-ловцов долины Черного Ветра около голодного ската Пустоты. После этого вернитесь к укротителю Диисаку из Стражи Небес."}}
D[11094] = {"Всех убей, один останься!",{"Доставьте информацию о вашей новой миссии вместе со сигнальным ружьем чародею Телису в святилище Звезд."}}
D[11095] = {"Командор Хобб",{"Отдайте сигнальную ракету клана Драконьей Пасти командору Хоббу в святилище Звезд в долине Призрачной Луны."}}
D[11096] = {"Угроза извне",{"Убейте 20 любых огров из клана Гордунни в Защитных холмах, после чего вернитесь к Юуле в Шаттрат."}}
D[11097] = {"Самая Опасная Ловушка",{"Помогите командору Хоббу защитить святилище Звезд. Когда войска клана Драконьей Пасти будут разгромлены, вернитесь к воеводе Мор'гору в лагерь Драконьей Пасти с медалями Провидцев."}}
D[11098] = {"В Скеттис!",{"Отнесите упаковку взрывчатки сержанту Дорину в лагерь Черного Ветра рядом со Скеттисом."}}
D[11099] = {"Всех убей, один останься!",{"Доставьте информацию о вашей новой миссии вместе с сигнальным ружьем анахоретке Сейле к алтарю Ша'тар."}}
D[11100] = {"Командор Аркус",{"Отдайте сигнальную ракету клана Драконьей Пасти командору Аркусу у алтаря Ша'тар."}}
D[11101] = {"Самая Опасная Ловушка",{"Помогите командору Аркусу защитить алтарь Ша'тар. Когда войска клана Драконьей Пасти будут разгромлены, вернитесь к воеводе Мор'гору в лагерь Драконьей Пасти с медалями Алдоров."}}
D[11102] = {"Бомбардировка",{"Уничтожьте 15 груд пушечных ядер Скверны при помощи бомб Стражи Небес."}}
D[11103] = {"Отказ мудреца"}
D[11104] = {"Перестать быть исцелителем"}
D[11105] = {"Отказ героя"}
D[11106] = {"Отказ защитника"}
D[11107] = {"Склонитесь перед верховным господином",{"Поговорите с властителем Мор'гором в лагере Драконьей Пасти в долине Призрачной Луны."}}
D[11108] = {"Владыка Иллидан Ярость Бури",{"Встретьтесь с Иллиданом Яростью Бури. Найдите Бартамуса в Нижнем городе Шаттрата, если останетесь в живых."}}
D[11109] = {"Кобальтовый дракон Пустоты Хорус"}
D[11110] = {"Лиловый дракон Пустоты Малфас"}
D[11111] = {"Ониксовый дракон Пустоты Ониксиен"}
D[11112] = {"Лазурный дракон Пустоты Сураку"}
D[11113] = {"Пурпурный дракон Пустоты Воранаку"}
D[11114] = {"Зои, изумрудный дракон Пустоты"}
D[11116] = {"Испытание Наару: Магтеридон (QUEST FLAG)"}
D[11117] = {"Поймать дикого зайцелопа!",{"Голдарк Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или надеть Синтехмельные очки."}}
D[11118] = {"Розовые элекки на марше",{"Отправляйтесь в сады спелого хмеля рядом с Штормградом, Дарнасом и Экзодаром, истребите по три элекка в каждом из мест и возвращайтесь к Голдарку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться или надеть Синтехмельные очки."}}
D[11119] = {"Налет на лагерь Баш'ира!",{"Поговорите с учеником эфир-теха на заставе Стражи Небес в Острогорье."}}
D[11120] = {"Розовые элекки на марше",{"Отправляйтесь в сады спелого хмеля рядом с Луносветом, Громовым Утесом и Подгородом, истребите по три элекка в каждом из них и возвращайтесь к Глодраку Меткому Охотнику. Чтобы увидеть розовых элекков, необходимо напиться – или хотя бы надеть Синтехмельные очки."}}
D[11122] = {"Туда и обратно",{"Возьмите бочку у Флинна Огневар и верните ее Полу Янтарлену. Пока баран не сбежит от вас, постарайтесь доставить три бочки."}}
D[11123] = {"Исследование пепелища",{"Поговорите с инспектором Таремом у трактира \"Последний привал\"."}}
D[11124] = {"Исследование пепелища",{"Поговорите с инспектором Таремом у трактира \"Последний привал\"."}}
D[11126] = {"Чужой среди своих",{"Прогоните 5 дезертиров-подстрекателей и вернитесь к докам Терамора к Калии Гастингс."}}
D[11128] = {"Пропагандистская война",{"Доставьте дезертирскую пропаганду Калии Гастингс к докам в Тераморе."}}
D[11129] = {"Пропал Кайл!",{"Анаб Пшеничная Грива из деревни Кровавого Копыта в Мулгоре попросил найти его лучшего щенка, Кайла Бесноватого.","","Покормите Кайла нежным мясом долгонога и возвращайтесь к Анабу Пшеничной Гриве."}}
D[11130] = {"Ой, блестяшечки!",{"Жуль хочет, чтобы вы взяли его записку и отнесли ее Бадду в Призрачные земли к Зул'Аману."}}
D[11131] = {"Гаси пожар!",{"Переодетая попечительница сирот просит вас помочь потушить пожар в деревне. Когда пожар будет потушен, снова поговорите с попечительницей сирот."}}
D[11132] = {"Все обещаешь и обещаешь",{"Разыщите карту Бадда Недрека на террасе верховного шамана Налоракка в Зул'Амане и верните ее хозяину."}}
D[11133] = {"Дискредитация вражеской агентуры",{"Калия Гастингс просит вас всучить подправленные листовки 6 тераморским стражникам. После этого вернитесь к Калии и доложите о выполнении задания."}}
D[11134] = {"Конец вражеской пропаганде",{"Арестуйте Гависа Серого Щита, затем доложитесь Калии Гастингс у доков Терамора."}}
D[11135] = {"Всадник без головы",{"Найдите святилище тыквы Всадника без головы."}}
D[11136] = {"Тревожные события",{"Поговорите с капитаном Ваймором на Сторожевом посту."}}
D[11137] = {"Братство Справедливости в Пылевых топях?",{"Добудьте приказы Братства Справедливости у Гарна Маферса и принесите его капитану Ваймору на Сторожевой пост."}}
D[11138] = {"Ренн Макгилл",{"Отнесите приказы Братства Справедливости Ренну Макгиллу. Он плавает недалеко от Зловещего берега."}}
D[11139] = {"Старое водолазное снаряжение",{"Принесите набор инструментов и испорченное водолазное снаряжение Ренну Макгиллу в Пылевые топи."}}
D[11140] = {"Вернуть груз!",{"Принесите 6 поднятых со дна сундуков Ренну Макгиллу в Пылевые топи."}}
D[11141] = {"Джайна должна быть в курсе",{"Поговорите с леди Джайной Праудмур в Тераморе."}}
D[11142] = {"Исследование острова Алькац",{"Поговорите с Коссой Багровое Крыло и возьмите одного из ее грифонов, чтобы обследовать остров Алькац. После выполнения поручения отрапортуйте леди Джайне Праудмур в Тераморе."}}
D[11143] = {"Мрачные выводы",{"Доложитесь капитану Дариллу в Северной башне."}}
D[11144] = {"Подтвержденные подозрения",{"Принесите боевой план племени Зловещий Тотем капитану Дариллу в Северную башню."}}
D[11145] = {"Пленники Зловещего Тотема",{"Сержант Лукас из Северной башни просит вас спасти 5 тераморских пленников."}}
D[11146] = {"Ловля ящеров",{"Сержант Лукас из Северной башни просит вас поймать 6 ящеров. Вы можете ловить как ящеров Кровавой Топи, так и крикунов Кровавой Топи."}}
D[11147] = {"Боевые ящеры",{"Сержант Лукас из Северной башни хочет, чтобы вы положили приманку на ящера близ ветряной мельницы в деревне Черного Копыта."}}
D[11148] = {"Оружие племени Зловещего Тотема",{"По просьбе капитана Дарилла из Северной башни принесите ему 7 предметов вооружения из деревни Черного Копыта."}}
D[11149] = {"Помощь Табеты",{"Поговорите с Табетой в ее доме."}}
D[11150] = {"Уничтожение заставы Дикого Рога",{"Сожгите северную, восточную и северо-восточную палатки на заставе Дикого Рога, затем вернитесь в усадьбу Табеты."}}
D[11151] = {"Справедливая месть за Хьялей",{"Поговорите с капитаном Гарраном Ваймсом в цитадели в Тераморе."}}
D[11152] = {"Обрести покой",{"По просьбе капитана Гаррана Ваймса из цитадели возложите венок к памятнику семейства Хьяль."}}
D[11153] = {"Прорвать блокаду",{"Возьмите кассетные бомбы Петрова и сбросьте их на корабли, убив 25 матросов абордажной команды и уничтожив 10 абордажных пушек. Как только задание будет выполнено, вернитесь к бомбардиру Петрову в Крепость Западной Стражи."}}
D[11154] = {"Пусть обделаются от страха!",{"Соберите 10 кусков гуано темнолапых летучих мышей и отнесите их инженеру Фекнату к Стальным воротам."}}
D[11155] = {"Снова суп из черпорога?",{"Шеф-повар Дымкотел поручила вам добыть 6 кусков мяса черпорогов и принести их ей в Крепость Западной Стражи."}}
D[11156] = {"Налетчики Дикого Рога",{"Убейте 12 тауренов из племени Зловещего Тотема с заставы Дикого Рога и вернитесь к ученику Морланну в усадьбу Табеты."}}
D[11157] = {"В тисках зла",{"Уничтожьте 15 яиц протодраконов и 15 детенышей протодраконов, после чего вернитесь к капитану Адамсу в Крепость Западной Стражи."}}
D[11158] = {"Перья Кровавой Топи",{"Принесите 5 перьев Кровавой Топи Броггу в Шестермуть."}}
D[11159] = {"Духи в руинах деревни Каменного Молота",{"Брогг из Шестермути просит вас дать покой 10 духам клана Каменного Молота."}}
D[11160] = {"Знамя Каменного Молота",{"Добудьте знамя Каменного Молота и принесите его Броггу в Шестермуть."}}
D[11161] = {"Сущность вражды",{"Принесите 10 сущностей черного дракона Броггу в Шестермуть."}}
D[11162] = {"Бросить вызов черным драконам",{"Установите знамя Каменного Молота у входа в Логово Ониксии, затем вернитесь к Броггу в Шестермуть."}}
D[11163] = {"Тайная Сестрица",{"Доберитесь до Донны Браско, чтобы получить причитающуюся вам награду. Найти Донну можно на Призрачных Землях, сразу за окраиной Зул'Амана."}}
D[11164] = {"Клыкастые всадники",{"Соберите для Пригмона 10 клыков лесных троллей в Зул'Амане и принесите их ему в лагерь Бадда в Призрачных Землях."}}
D[11165] = {"Троль из троллей",{"Найдите Зунгама и помогите ему выбраться из Зул'Амана."}}
D[11166] = {"Крестом на карте обозначена... твоя смерть!",{"Отправляйтесь в Зул'Аман и посетите чертог Халаззи, платформу Джан'алая и платформу Акил'зона. Заметьте все подробности и по возвращении доложите о них Бадду в его лагере в Призрачных землях."}}
D[11167] = {"Новая чума",{"Аптекарь Лисандер из Лагеря Возмездия просит вас собрать 10 неповрежденных флаконов с чумой с места кораблекрушения на юго-востоке."}}
D[11168] = {"Добавить крепости",{"Принесите 3 гигантские ядовитые железы гигантских прибрежных крабов аптекарю Лисандеру, который будет ждать вас в Лагере Возмездия в Ревущем фьорде."}}
D[11169] = {"Оружие племени Зловещего Тотема",{"Ученик Гарион из усадьбы Табеты хочет, чтобы вы испытали захваченный тотем на 10 крапчатых кроколисках-грязекупах или грязекупах-острозубах."}}
D[11170] = {"Испытания на море",{"Поговорите с дрессировщицей нетопырей Камиллой, возьмите ездового нетопыря и летите наперерез войскам Альянса. Когда вы будете пролетать над флотом, сбросьте склянки с чумой и заразите 16 резервистов Северного флота."}}
D[11171] = {"Повелитель Проклятий? Пффф!",{"Убейте в Зул'Амане повелителя проклятий Малакрасса и вернитесь к Бадду Недреку на Холмы Томагавков."}}
D[11172] = {"Крушение дирижабля",{"Поговорите с Мокси Сталегриль на месте крушения дирижабля Бизила."}}
D[11173] = {"Подмена реактива",{"Принесите 6 флаконов болотного яда ученику Гариону в усадьбу Табеты."}}
D[11174] = {"Профилактика коррозии",{"Мокси Сталегриль хочет, чтобы вы уничтожили 10 слизнюков и доложили ей о выполнении задания на месте крушения дирижабля Бизила."}}
D[11175] = {"Дочка моя",{"Старик Каменная Мантия попросил вас найти его дочку, надзирательницу Ирену Каменная Мантия в Стальных воротах."}}
D[11176] = {"Присматривая за работой",{"Надзиратель Ирена Каменная Мантия попросила вас поговорить с главным археологом Стальных ворот."}}
D[11177] = {"Отшельник из сторожки \"Болотный огонек\"",{"Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\"."}}
D[11178] = {"Кровь Вождя",{"Принесите кровь Зул'джина Бадду в его лагерь в Призрачных Землях. За пределами Зул'Амана."}}
D[11179] = {"У Финлея кишка тонка",{"Соберите 7 безупречных кишечных струн туманных саблезубов для Финлея Флетчера из Крепости Западной Стражи."}}
D[11180] = {"Что таится на Ведьмином холме?",{"Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы добыли информацию у 10 восставших мертвецов или духов."}}
D[11181] = {"Ведьмина погибель",{"Принесите 9 ростков ведьминой погибели Морганту Мрачнику в сторожку \"Болотный огонек\"."}}
D[11182] = {"В поисках первопричины",{"Убить 5 укротителей из клана Укротителей драконов и Скелда Сына Дракона. Если вам удастся выполнить это задание, вернитесь к древу Пылающего Гнездовья."}}
D[11183] = {"Очищение Ведьминого холма",{"Моргант Мрачник из сторожки \"Болотный огонек\" хочет, чтобы вы установили факел в конце дока и сразились с тем, что выйдет на свет."}}
D[11184] = {"Разыскивается: Кровокоготь Ненасытный",{"Уничтожьте Кровокогтя Ненасытного и сообщите об этом Драззиту Кранотеку, который находится в Шестермути."}}
D[11185] = {"Письмо аптекаря",{"Отнесите запечатанное письмо привратнику Анделло в усадьбу Табеты."}}
D[11186] = {"Свидетельство предательства?",{"Доставьте запечатанное письмо Назиру Кровавому Копью в Деревню Гиблотопь."}}
D[11187] = {"Маг-лейтенант Малистер",{"Капитан Адамс попросил вас поговорить с его советником, магом-лейтенаном Малистером. Его можно найти в Крепости Западной Стражи."}}
D[11188] = {"Минус на минус",{"Маг-лейтенант Малистер поручил вам уничтожить 3 протодраконов."}}
D[11189] = {"В последний раз",{"Сопроводите привидение исследователя Джарена к надзирательнице Ирене Каменная Мантия в Стальные ворота Ревущего фьорда."}}
D[11190] = {"К каждой пушке затычка",{"Канонир Эли поручил вам собрать 10 пушечных ядер и отнести их в Крепость Западной Стражи."}}
D[11191] = {"Этот старый маяк",{"Поговорите с Бабс Шипокруткой на маяке на острове к востоку от Терамора."}}
D[11192] = {"Жир крепкозуба",{"Принесите 4 контейнера жира крепкозуба Бабс Шипокрутке на маяк близ Терамора."}}
D[11193] = {"Подлые обитатели глубин",{"Отнесите книгу \"Подлые обитатели глубин\" в доки Терамора и отдайте \"Весельчаку\" Ленни Полечуду."}}
D[11194] = {"Так это правда?",{"Поговорите с Натом Пэглом в лагере Ната, который находится в Пылевых топях."}}
D[11195] = {"Игра в куклы",{"Отнесите потрепанную куклу вуду Жулю в Шаттрат."}}
D[11196] = {"TEMP X",{"Найдите Зунгама и помогите ему выбраться из Зул'Амана."}}
D[11198] = {"Сразить Тетура!",{"Майор Миллз из доков Терамора хочет, чтобы вы покончили с Тетуром."}}
D[11199] = {"Доклад разведчика Ноулса",{"Капитан Адамс попросил вас разыскать разведчика Ноулса у Тлеющей башни."}}
D[11200] = {"Не просто совпадение",{"Крог из Деревни Гиблотопь хочет, чтобы вы принесли ему 7 предметов оружия Черного Копыта."}}
D[11201] = {"Замысел племени Зловещего Тотема",{"Принесите боевые планы племени Зловещего Тотема Крогу в деревню Гиблотопь."}}
D[11202] = {"Задание: вечный огонь",{"Разведчик Ноулс посоветовал вам воспользоваться неугасимыми факелами, чтобы уничтожить четыре контейнера с чумой, окружающих Халгринд."}}
D[11203] = {"Найти Табету",{"Поговорите с Табетой в ее доме на Трясине."}}
D[11204] = {"Возвращение к Крогу",{"Поговорите с Крогом в деревне Гиблотопь."}}
D[11205] = {"Уничтожение заставы Дикого Рога",{"Сожгите северный, восточный и северо-западный шатры на заставе Дикого Рога, затем вернитесь в усадьбу Табеты."}}
D[11206] = {"Акт правосудия",{"Вернитесь к Крогу в деревню Гиблотопь."}}
D[11207] = {"Защитить груз!",{"Мокси Сталегриль попросила вас собрать 8 контейнеров груза с дирижабля и принести ей на место крушения Бизиля."}}
D[11208] = {"Поставка для Драззита",{"Доставьте груз с дирижабля Драззиту Кранотеку в Шестермуть."}}
D[11209] = {"Сделка Ната",{"Нат Пэгл из лагеря Ната хочет, чтобы вы испытали его новую наживку для рыбы."}}
D[11210] = {"Он настоящий!",{"Поговорите с майором Миллзом в доках Терамора."}}
D[11211] = {"Помощь деревне Шестермуть",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11212] = {"Ферма Табеты",{"Поговорите с Табетой в ее доме на Трясине."}}
D[11213] = {"Навестить Табету",{"Поговорите с Табетой в ее усадьбе на Трясине."}}
D[11214] = {"Миссия в Шестермуть",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11215] = {"Помощь Шестермути",{"Поговорите с Драззитом Кранотеком в Шестермути."}}
D[11216] = {"Верховный маг Альтур",{"Поговорите с верховным магом Альтуром близ Каражана на перевале Мертвого Ветра."}}
D[11217] = {"Тяни змею за хвост!",{"Гиззикс Грязебульк из Шестермути просит принести ему 8 стеблей змейкиного хвоста."}}
D[11218] = {"Осторожно! Взрывчатка!",{"Воспользуйтесь динамитом Стальной Чеки, чтобы собрать 6 кусков руды из Шепчущей теснины и 18 драгоценных камней из Шепчущей теснины. Затем принесите руду и камни саперу Стальной Чеке в Крепость Западной Стражи."}}
D[11219] = {"Гаси пожар!",{"Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе."}}
D[11220] = {"Всадник без головы",{"Найдите святилище тыквы Всадника без головы."}}
D[11221] = {"Донесения с полей",{"Поговорите с темным следопытом Лианой и стражем смерти Разаэлем на поле боя в Кровоточащей долине к югу от Лагеря Возмездия, после чего вернитесь к Верховному палачу Ансельму."}}
D[11222] = {"Доказательство измены",{"Поговорите с королем Варианом Ринном в Крепости Штормграда."}}
D[11223] = {"Возвращение к Джайне",{"Поговорите в Тераморе с леди Джайной Праудмур."}}
D[11224] = {"Пришли мулов сюда",{"Исследовательница Эбигейл просит вас пригрозить рукой (команда /рука) 10 брошенным груженым мулам, после чего вернуться к ней в Крепость Западной Стражи."}}
D[11225] = {"Отшельник с Ведьминого холма",{"Поговорите с Ярлом \"Болотным глазом\" в сторожке \"Болотный огонек\"."}}
D[11227] = {"Пусть едят вволю!",{"Понтий, псарь из Лагеря Возмездия, просит вас забрать голодного чумного пса из клетки и накормить его мясом ворон фьорда, которые кружат к югу от Лагеря Возмездия."}}
D[11228] = {"Во власти ледяного кошмара...",{"Поговорите с вице-адмиралом Келлером в Валгардском порту."}}
D[11229] = {"Флагман \"Ветрокрылая\"",{"Поговорите с дрессировщицей нетопырей Камиллой в Лагере Возмездия и летите к флагману \"Ветрокрылая\". Доложите о своем прибытии капитану Харкеру."}}
D[11230] = {"В засаде!",{"Капитан Харкер на борту \"Ветрокрылой\" просит вас убить 15 стражей бухты Северного флота."}}
D[11231] = {"О ключах и клетках",{"Отец Левариол попросил вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к нему в Крепость Западной Стражи."}}
D[11232] = {"Дайте нам знак",{"С помощью дымовых сигнальных ракет обозначьте местонахождение пушек Альянса вдоль северной стены Обнажившегося дна. Доложите о выполнении задания темному следопыту Лиане из Кровоточащей долины."}}
D[11233] = {"Решающий удар",{"Темный следопыт Лиана из Лагеря Возмездия послала вас убить капитана Ольстера, сержанта Лоррика и лейтенанта Селейну, обосновавшихся на Обнажившемся дне."}}
D[11234] = {"Доложите Ансельму",{"Вернитесь к верховному палачу Ансельму в Лагерь Возмездия в Ревущем фьорде."}}
D[11235] = {"Очистить Гьялерброн",{"Капитан Адамс поручил вам убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев. После чего вам надлежит вернуться к нему в Крепость Западной Стражи."}}
D[11236] = {"Некро-владыка Мезхен",{"Убейте некро-владыку Мезхена. Затем вернитесь к капитану Адамсу в Крепость Западной Стражи."}}
D[11237] = {"Гьялербронский план нападения",{"Отнесите гьялербронский план нападения магу-лейтенанту Малистеру в Крепость Западной Стражи."}}
D[11238] = {"Ледяной змей и его повелитель",{"Убейте Зловещего призывателя змей и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог магу-лейтенанту Малистеру в Крепость Западной Стражи."}}
D[11239] = {"На службе Света",{"Убейте 10 бессмертных дозорных, 4 кошмарных ужаса и 2 тлетворных существа по просьбе отца Левариола из Крепости Западной Стражи."}}
D[11240] = {"Предводитель Спятивших",{"Убейте Сквига Идолохотника и сообщите об этом саперу Стальная Чека, который находится в Крепости Западной Стражи."}}
D[11241] = {"Путь огня",{"Выведите аптекаря Хейнса из Обнажившегося дна после чего сообщите о произошедшем аптекарю Лисандеру из Лагеря Возмездия в Ревущем фьорде."}}
D[11242] = {"Наконец, свободен!",{"Возьмите книгу Томаса Томсона и отнесите ее переодетой попечительнице сирот в Златоземье, Каранос или на Лазурную заставу."}}
D[11243] = {"Если Валгард падет...",{"Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас убить 12 захватчиков из клана Укротителей драконов или воргов из клана Укротителей драконов."}}
D[11244] = {"На помощь спасателям",{"Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 8 валгардских разведчиков, которых проткнули гарпунами и оставили умирать."}}
D[11245] = {"Смертельно опасные башни",{"Сержант из крепости Западной Стражи сообщил вам, что сторожевые башни Скорна разумнее всего разрушить с воздуха."}}
D[11246] = {"Тяжело, но необходимо",{"Сержант из крепости Западной Стражи попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне."}}
D[11247] = {"Гори, Скорн, гори!",{"Сержант из крепости Западной Стражи поручил вам поджечь два больших дома и казармы в Скорне."}}
D[11248] = {"Операция: Атака на Скорн",{"Капитан Адамс попросил вас воспользоваться знаком отличия командира Западной Стражи в Скорне и поговорить с сержантом из крепости Западной Стражи."}}
D[11249] = {"Остановить вознесение!",{"Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что отцу Левариолу из Крепости Западной Стражи будет очень интересно взглянуть на этот свиток."}}
D[11250] = {"Слава покорителю Скорна!",{"Отнесите знак отличия командира Западной Стражи капитану Адамсу в Крепость Западной Стражи."}}
D[11251] = {"С новыми силами",{"Разведчица Валори просит вас узнать, что за звуки битвы доносятся из-за холма на северо-востоке Деревни Драконьего Черепа."}}
D[11252] = {"На Утгард!",{"Защитник Мордун поручил вам казнить Ингвара Грабителя, который обитает в Утгарде, и принести его голову вице-адмиралу Келлеру."}}
D[11253] = {"По следу врага",{"Воспользуйтесь ошейником чумного пса и заберите из клетки в Лагере Возмездия чумного пса-ищейку. Идите с ним по следу, куда бы он вас не привел."}}
D[11254] = {"Карта на шкуре дракона",{"Принесите карту на шкуре дракона верховному палачу Ансельму в Лагерь Возмездия."}}
D[11255] = {"Пленники в Деревне Драконьего Черепа",{"Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде просит вас спасти 3 пленных валгардских узников."}}
D[11256] = {"Скорн должен пасть!",{"Вождь Прахтотем попросил вас воспользоваться эмблемой Заиндевевшего Копыта в Скорне и поговорить с храбрецом из Лагеря Заиндевевшего Копыта."}}
D[11257] = {"Тяжело, но необходимо",{"Храбрец из лагеря Заиндевевшего Копыта попросил вас разрубить на куски 20 снежескорнских врайкулов в Скорне."}}
D[11258] = {"Гори, Скорн, гори!",{"Храбрец из Лагеря Заиндевевшего Копыта поручил вам поджечь северо-восточный большой дом, северо-западный большой дом и казармы в Скорне с помощью его факела. Когда дело будет сделано, поговорите с ним еще раз."}}
D[11259] = {"Смертельно опасные башни",{"Храбрец из Лагеря Заиндевевшего Копыта сообщил вам, что сторожевые башни Скорна разумнее всего разрушить атакой с воздуха, предварительно отметив их местонахождение с помощью сигнальной ракеты Храбреца."}}
D[11260] = {"Остановить вознесение!",{"Разверните врайкульский свиток вознесения рядом с погребальным костром тана, призовите и убейте его. Исходя из магической природы ритуала, вы можете предположить, что Великой Матери Анкхе из Лагеря Заиндевевшего Копыта будет очень интересно взглянуть на этот свиток."}}
D[11261] = {"Покоритель Скорна!",{"Верните эмблему Зимнего Копыта вождю Прахтотему в Лагерь Заиндевевшего Копыта."}}
D[11262] = {"Ингвар должен умереть!",{"Темный следопыт Марра просит вас убить Ингвара Расхитителя в Крепости Утгард и принести его голову верховному палачу Ансельму в Лагерь Возмездия."}}
D[11263] = {"Очистить Гьялерброн",{"Вождь Прахтотем попросил вас убить 15 гьялербронских воинов, 8 гьялербронских руночаров и 8 гьялербронских сноходцев, после чего вернитесь в Лагерь Заиндевевшего Копыта."}}
D[11264] = {"Некро-владыка Мезхен",{"Убейте некро-владыку Мезхена. Затем вернитесь к вождю Прахтотему в Лагерь Заиндевевшего Копыта."}}
D[11265] = {"О ключах и клетках",{"Великая Мать Анкха попросила вас собрать достаточное количество ключей от гьялербронских клеток, чтобы освободить 10 гьялербронских узников. Когда вы выполните задание, вернитесь к ней в Лагерь Заиндевевшего Копыта."}}
D[11266] = {"Гьялербронский план нападения",{"Отнесите гьялербронский план нападения Целее Ледогрив в Лагерь Заиндевевшего Копыта."}}
D[11267] = {"Ледяной змей и его повелитель",{"Убейте Зловещего призывателя змей и воспользуйтесь его рогом, чтобы позвать обратно Ледиона. Убейте ледяного змея и принесите рог Целее Ледогрив в Лагерь Заиндевевшего Копыта."}}
D[11268] = {"Ходячие мертвецы",{"Убейте 10 бессмертных дозорных, 4 кошмарных ужаса и 2 тлетворных существа, после чего уведомите Великую Мать Анкху из Лагеря Заиндевевшего Копыта об успешном выполнении поручения."}}
D[11269] = {"Работаем до упора",{"Гил Гризерт просит вас принести ему 10 клочков пуха пятнистых гиппогрифов."}}
D[11270] = {"Ужасы войны",{"Верховный палач Ансельм из Лагеря Возмездия просит вас взять горящий факел и сжечь десять трупов, лежащих к западу от города."}}
D[11271] = {"Спешные приготовления",{"Ахота Белый Иней из Лагеря Заиндевевшего Копыта просит вас принести ему 10 клочков пуха пятнистых гиппогрифов."}}
D[11272] = {"Сведение счетов",{"Верховный палач Ансельм повелел вам отправиться в Утгард и убить принца Келесета."}}
D[11273] = {"Объединение людей",{"Найдите Пулроя в Деревне Драконьего Черепа."}}
D[11274] = {"Зедд мертв, детка?",{"Найдите Зедда в Деревне Драконьего Черепа."}}
D[11275] = {"Охотничий рог",{"Нокома Заклинатель Снегов из Лагеря Заиндевевшего Копыта просит вас принести ей 6 неповрежденных рогов барана."}}
D[11276] = {"И их осталось двое...",{"Обыщите Катакомбы Утгард в поисках Глоренфелда."}}
D[11277] = {"Глубины порока",{"Глоренфелд из Катакомб Утгард просит вас собрать 10 табличек Драконьего Черепа."}}
D[11278] = {"Возвращение в Валгард",{"Отнесите сверток Глоренфелда Белтранду Максорфу в Валгардский порт."}}
D[11279] = {"Зеленые и светящиеся",{"Распространитель чумы Тилингаст попросил вас собрать 10 образцов плоти зачумленных детенышей протодраконов и отнести их к нему в Новый Агамонд."}}
D[11280] = {"Драконис гастритис",{"Распространитель чумы Тилингаст просит вас приманить протодракона с помощью куска зачумленного мяса Тилингаста и понаблюдать за его реакцией на угощение."}}
D[11281] = {"Подражая зову природы",{"Испытайте вырезанный рог и верните его Нокоме Заклинателю Снегов в Лагерь Заиндевевшего Копыта."}}
D[11282] = {"Урок страха",{"По приказу Горта вам надо победить Улфа Кровопускателя, Орика Зловещего и Гуннара Торвардссона, после чего проткнуть их тела древком знамени Отрекшихся. Убивайте врайкулов вдоль баррикады, возведенной Отрекшимися, пока не появятся чемпионы."}}
D[11283] = {"Кровавая бойня в Гибльхейме",{"Сержант Горт просит вас убить 16 снежескорнских врайкулов в Гибльхейме."}}
D[11284] = {"Соседство с йети",{"Старшина Колби из крепости Вилдервар просит вас убить Сколорога."}}
D[11285] = {"Гори, Гибльхейм!",{"Сержант Горт послал вас в Гибльхейм с факелом Горта, чтобы вы сожгли 1 снежескорнское здание, 1 снежескорнскую сторожевую башню, 1 снежескорнский мост и 1 снежескорнские казармы."}}
D[11286] = {"Артефакты Стальных ворот",{"Ведун Странник Туманов попросил вас принести 10 артефактов Стальных ворот. Когда вы соберете их все, вернитесь к ведуну в Стальные ворота."}}
D[11287] = {"Найти ведуна Странника Туманов",{"Великая Мать Анкха попросила вас найти ведуна Странника Туманов. Она полагает, что он сейчас находится где-то рядом со Стальными Воротами."}}
D[11288] = {"Сияние света",{"Арес Поклявшийся, лежащий при смерти в Катакомбах Утгард, попросил вас вернуть священный артефакт.","","Это задание ограничено по времени."}}
D[11289] = {"Ведомый честью",{"Верните священный артефакт лорду Ирулону Верный Клинок в Валгард."}}
D[11290] = {"Военные планы Укротителей драконов",{"Вице-адмирал Келлер из Валгардского порта в Ревущем фьорде поручил вам достать военные планы клана Укротителей драконов."}}
D[11291] = {"В Крепость Западной Стражи!",{"Отнесите военные планы Укротителей драконов капитану Адамсу в Крепость Западной Стражи в Ревущем фьорде."}}
D[11292] = {"Слабое звено",{"Зверолов Джетан из крепости Вилдервар просит вас принести ему 8 пойманных зверьков."}}
D[11293] = {"Пивоварня Ячменоваров ищет зазывалу!"}
D[11294] = {"Пивоварня Громоваров ищет зазывалу!"}
D[11295] = {"В наступление!",{"Поговорите с сержантом Гортом на баррикаде рядом с подъемником к западу от Лагеря Возмездия в Ревущем Фьорде."}}
D[11296] = {"Пленники терзающих вдов",{"Тученеб попросил вас освободить 7 выносливых гонцов из лагеря Заиндевевшего Копыта. Выполнив это задание, вернитесь к нему в Стальные ворота."}}
D[11297] = {"Слежка за нарушителями границ",{"Поговорите с аптекарем Малтусом в Аптекарском поселке."}}
D[11298] = {"Что они пьют?",{"Аптекарь Малтус из Аптекарского поселка просит вас принести ему 5 дворфийских бочонков."}}
D[11299] = {"Круг Правосудия",{"Найдите Дегарна в Круге Правосудия. Он заперт в Катакомбах Утгард."}}
D[11300] = {"Поражение на ринге",{"Победите гладиаторов в Круге Правосудия, сразитесь с Олуфом Неистовым и заберите у него древнюю тайнопись.","","Отнесите тайнопись Глоренфелду ко входу в Катакомбы Утгард."}}
D[11301] = {"Мозги! Мозги!",{"Аптекарь Грик из Аптекарского поселка просит вас принести ему 12 мозгов спятивших исследователей."}}
D[11302] = {"Загадочные ледяные нимфы",{"Поговорите с Луриэль на Заиндевевшей поляне."}}
D[11303] = {"Засада",{"Поговорите с Лиделлом в Засаде Лиделла."}}
D[11304] = {"Новый Агамонд",{"Отнесите штамм Лисандера главному распространителю чумы Харрису в Новый Агамонд на запад Ревущего фьорда."}}
D[11305] = {"Идеальная формула",{"Добудьте кровь патриарха Укротителей драконов – вождя Торвальда, который укрылся в Лагере Торвальда, и принесите ее главному распространителю чумы Харрису в Новый Агамонд."}}
D[11306] = {"Нагреть и перемешать",{"Наполните пустой аптекарский флакон кровью из котла с кровью врайкулов, после чего добавляйте во флакон с кровью врайкула образцы чумы Харисса, пока не получите равномерную смесь.","","Когда вы выполните это поручение, вернитесь к Главному распространителю чумы Харрису."}}
D[11307] = {"Полевые испытания",{"Отправляйтесь в Халгринд и заразите ассимилированным штаммом чумы 10 зачумленных врайкулов из клана Укротителей драконов, после чего вернитесь к главному распространителю чумы Харрису."}}
D[11308] = {"Пора заметать следы",{"Поговорите с Дженни по прозвищу \"Пила\" в Новом Агамонде."}}
D[11309] = {"Запчасти для Дженни",{"Принесите 6 жил черпорога и 1 килограмм свежего мяса Дженни по прозвищу \"Пила\" в Новый Агаманд."}}
D[11310] = {"Внимание: требуется сборка",{"Воспользуйтесь набором для сборки поганища в Халгринде и сгоните в одно место как минимум 20 зачумленных врайкулов. Взорвите их с помощью поганища, после чего вернитесь к Дженни по прозвищу \"Пила\" в Новый Агамонд."}}
D[11311] = {"Сопротивляясь стихиям",{"Укротитель ветра Каган из Лагеря Заиндевевшего Копыта просит вас убить 8 горных элементалей. Уничтожайте завывающих циклонов или осколочных ледяных элементалей."}}
D[11312] = {"Заиндевевшая поляна",{"Поговорите с Луриэль на Заиндевевшей поляне."}}
D[11313] = {"Духи льда",{"Луриэль с Заиндевевшей поляны просит вас принести ей 15 ледяных ядер."}}
D[11314] = {"Падшие сестры",{"Луриэль с Заиндевевшей поляны попросила вас воспользоваться ее подвеской, чтобы освободить 7 морозных нимф."}}
D[11315] = {"Дикие ветви",{"Луриэль с Заиндевевшей поляны попросила вас уничтожить 8 цветков алого плюща."}}
D[11316] = {"Порождения Холмистой поляны",{"Луриэль с Заиндевевшей поляны просит вас убить 10 терноплющей."}}
D[11317] = {"Очищение",{"Ведун Странник Туманов у Стальных ворот посоветовал вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка."}}
D[11318] = {"А теперь гонки на баранах... Или вроде того.",{"У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд."}}
D[11319] = {"Семена негодующих хранителей",{"Луриэль с Заиндевевшей поляны поручила вам заморозить 8 спор."}}
D[11321] = {"Кто сказал сувениры?"}
D[11322] = {"Очищение",{"Дозорная Лунный Лепесток у Стальных ворот посоветовала вам очиститься от внутреннего смятения путем медитации в святилище Ледяного Клинка."}}
D[11323] = {"В обличье ворга",{"Ведун Странник Туманов попросил вас найти Улклыка в Вырубках и помочь ему.","","Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую."}}
D[11324] = {"Альфа-ворг",{"Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга ведуну Страннику Туманов в Стальные ворота."}}
D[11325] = {"В обличье ворга",{"Дозорная Лунный Лепесток попросила вас найти Улклыка в Вырубках и помочь ему.","","Если вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она даст вам новую."}}
D[11326] = {"Альфа-ворг",{"Улклык попросил вас убить Гарвала. После этого вы должны будете вернуть личину ворга дозорной Лунный Лепесток в Стальные ворота."}}
D[11327] = {"Задание: найти сверток",{"Разведчик Ноулс просит вас найти сверток аптекаря в Халгринде. Принесите его разведчику в Тлеющую башню."}}
D[11328] = {"Задание: чума Отрекшихся",{"Разведчик Ноулс просит вас отнести сверток аптекаря Пеппи Нетосопло в Крепость Западной Стражи."}}
D[11329] = {"Я готов на все!",{"Принесите Кристоферу Слоану из крепости Вилдервар 5 северных рыб-шипов."}}
D[11330] = {"Это... точно сработает!",{"Пеппи Нетосопло предложила вам отнести ее особую смесь врайкулу-узнику из клана Укротителей драконов. Когда он выпьет смесь, вернитесь в Крепость Западной Стражи и расскажите Пеппи о результатах эксперимента."}}
D[11331] = {"Ик... Ты ему и скажи!",{"Пеппи Нетосопло уговорила вас сообщить плохие новости о новой чуме Отрекшихся капитану Адамсу. Его можно найти в Крепости Западной Стражи."}}
D[11332] = {"Задание: уничтожить чуму!",{"Капитан Адамс приказал вам сбросить 5 бомб на резервуары с чумой в Новом Агамонде. Вернитесь к нему в Крепость Западной Стражи, когда это поручение будет выполнено."}}
D[11333] = {"В мир духов",{"Торалиус Мудрый в Валгарде просит вас найти его мешочек с реагентами."}}
D[11335] = {"Призыв к оружию: низина Арати",{"Победите на поле боя Низины Арати и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11336] = {"Призыв к оружию: Альтеракская долина",{"Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11337] = {"Призыв к оружию: Око Бури",{"Победите на поле боя Ока Бури и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11338] = {"Призыв к оружию: ущелье Песни Войны",{"Победите на поле боя Ущелья Песни Войны и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11339] = {"Призыв к оружию: низина Арати",{"Победите на поле боя Низины Арати и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11340] = {"Призыв к оружию: Альтеракская долина",{"Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11341] = {"Призыв к оружию: Око Бури",{"Победите в игре на поле боя Ока Бури и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11342] = {"Призыв к оружию: ущелье Песни Войны",{"Победите на поле боя Ущелья Песни Войны и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[11343] = {"Эхо Имирона",{"Торалиус Мудрый просит вас обыскать Деревню Драконьего Черепа в мире духов и найти информацию о тайнах Ниффлвара."}}
D[11344] = {"Страдания Ниффлвара",{"Торалиус Мудрый поручил вам осмотреть Ниффлвар из мира духов и найти информацию о тайнах Ниффлвара."}}
D[11346] = {"Книга Рун",{"Геолог Белвар из крепости Вилдервар просит вас найти Книгу Рун."}}
D[11348] = {"Руна подчинения",{"Геолог Белвар из крепости Вилдервар просит вас испытать руну подчинения и сразиться с Мурдисом-обуздателем."}}
D[11349] = {"Освоение рун",{"Принесите геологу Белвару из крепости Вилдервар резной инструмент, который используют дворфы клана Железной Руны."}}
D[11350] = {"Книга Рун",{"Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас принести ему Книгу Рун."}}
D[11351] = {"Освоение рун",{"Принесите выносливому гонцу Пембе из Лагеря Заиндевевшего Копыта резной инструмент, который используют дворфы клана Железной Руны."}}
D[11352] = {"Руна подчинения",{"Выносливый гонец Пембе из Лагеря Заиндевевшего Копыта просит вас испытать руну подчинения и сразиться со Мурдисом-обуздателем."}}
D[11354] = {"Разыскивается: Ездовой хлыстик Назана",{"Торговец ветром Зарим просит вас добыть ездовой хлыст Назана. Доставьте его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11355] = {"Марш великанов",{"Ученый Адеран из крепости Вилдервар попросил вас использовать кирку поиска рун на трупах 4 рунических каменных великанов."}}
D[11356] = {"Переодетая попечительница сирот",{"Поговорите с переодетой попечительницей сирот в Златоземье, Караносе или на Лазурной заставе."}}
D[11357] = {"Попечительница сирот в маске",{"Поговорите с попечительницей сирот в маске в Колючем Холме, Брилле или на площади Соколиных Крыльев."}}
D[11358] = {"Магнит",{"Ученый Адеран из крепости Вилдервар просит вас сравнить образцы рун с надписями на расколотой скрижали."}}
D[11359] = {"Уничтожить Мегалита",{"Уничтожьте Мегалита и вернитесь к ученому Адерану в крепость Вилдервар."}}
D[11360] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11361] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Колючем Холме."}}
D[11362] = {"Разыскивается: Украшенный перьями посох Кели'дана",{"Торговец ветром Зарим просит вас добыть украшенный перьями посох Кели'дана. Принесите его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11363] = {"Разыскивается: печать Острорука",{"Торговец ветром Зарим просит вас добыть печать Острорука. Принесите ее ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11364] = {"Разыскиваются: Центурионы клана Изувеченной Длани",{"Ловчий Пустоты Ма'дуун поручает вам убить 4 центурионов из клана Изувеченной Длани. Вернитесь к нему в Нижний город Шаттрата за наградой, как только перебьете их всех."}}
D[11365] = {"Марш великанов",{"Ведун Эдан из Лагеря Заиндевевшего Копыта попросил вас использовать кирку поиска рун на трупах 4 рунных каменных великанов."}}
D[11366] = {"Магнит",{"Ведун Эдан из Лагеря Заиндевевшего Копыта просит вас сравнить образцы рун с надписями на расколотой скрижали."}}
D[11367] = {"Уничтожить Мегалита",{"Уничтожьте Мегалита и вернитесь к ведуну Эдану в Лагерь Заиндевевшего Копыта."}}
D[11368] = {"Разыскивается: сердце Квагмирран",{"Добудьте сердце Зыбуна и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11369] = {"Разыскивается: яйцо Черной Охотницы",{"Добудьте яйцо Черной Охотницы и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11370] = {"Требуется: трактат полководца",{"Добудьте трактат полководца и доставьте его торговцу ветром Зариму в Нижний город Шаттрата за вознаграждение.","","Задание можно выполнить только в героическом режиме."}}
D[11371] = {"Разыскиваются: Мирмидоны Резервуара Кривого Клыка",{"Ловчий Пустоты Ма'дуун требует, чтобы вы убили 14 мирмидонов из резервуара Кривого Клыка. По исполнению задания возвращайтесь к Ма'дууну в Нижний город Шаттрата за вознаграждением."}}
D[11372] = {"Разыскиваются: головные перья Айкисса",{"Добудьте перья с головы Айкисса и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11373] = {"Разыскивается: Заговоренный Амулет Шаффара",{"Добудьте заговоренный амулет Шаффара и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11374] = {"Разыскивается: Самоцвет души Экзарха",{"Добудьте самоцвет души экзарха и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11375] = {"Разыскивается: Шепот Бормотуна",{"Добудьте шепот Бормотуна и вернитесь к торговцу ветром Зариму, в Нижний город Шаттрата.","","Это задание может быть выполнено только в героическом режиме."}}
D[11376] = {"Разыскиваются: злобные инструкторы",{"Убейте для ловчего Пустоты Ма'дууна 3 злобных инструкторов, по выполнении вернитесь к нему в Нижний город Шаттрата, чтобы получить свою награду."}}
D[11377] = {"Месть сладка",{"Скалл из Нижнего города просит вас приготовить похлебку из калири в его кухонном котелке. По выполнении вернитесь к нему."}}
D[11378] = {"Разыскивается: Голова Охотника Вечности",{"Торговец ветром Зарим просит вас добыть голову Охотника Вечности. Доставьте ее в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11379] = {"Очень горячая похлебка",{"Скалл из Нижнего города просит вас приготовить немного невероятной демонической похлебки в его кухонном котелке. Вернитесь, когда приготовите."}}
D[11380] = {"Мания",{"Скалл из Нижнего города просит вас принести 15 манаягод из заповедников Пустоверти."}}
D[11381] = {"Супчик для души",{"Скалл из Нижнего города просит вас приготовить суп предков в его кухонном котелке. По выполнении вернитесь к нему."}}
D[11382] = {"Разыскиваются: песочные часы Эонуса",{"Торговец ветром Зарим просит вас добыть песочные часы Эонуса. Доставьте их в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11383] = {"Разыскиваются: Повелители временных разломов",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 повелителей временных разломов. Вернитесь к нему в Нижний город Шаттрата за наградой, когда они будут убиты."}}
D[11384] = {"Разыскивается: Отросток Узлодревня",{"Торговец ветром Зарим просит вас добыть отросток Узлодревня. Доставьте его ему в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11385] = {"Разыскиваются: Солнцеловы-чаротворцы",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 6 солнцеловов-чаротворцев. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11386] = {"Разыскивается: Проектор Паталеона",{"Торговец ветром Зарим просит вас добыть проектор Паталеона. Доставьте его в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11387] = {"Разыскиваются: разрушители из кузни бурь",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы уничтожили 5 разрушителей из кузни бурь. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11388] = {"Разыскивается: Свиток Скайрисса",{"Торговец ветром Зарим просит вас добыть свиток Скайрисса. Доставьте его в Нижний город Шаттрата и получите награду.","","Это задание выполняется только в героическом режиме."}}
D[11389] = {"Разыскиваются: Часовые Аркатраца",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы навсегда деактивировали 5 часовых Аркатраца. Вернитесь к нему в Нижний город Шаттрата, когда выполните задание, чтобы забрать награду."}}
D[11390] = {"У меня есть ветролет!",{"Главный археолог Стальных ворот просит вас отвезти 3 мешка с реликвиями из раскопа на платформы к северу и югу от Стальных ворот.","","Для этого вам надо будет воспользоваться погрузочным крюком ветролета.","","Выполнив задание, вернитесь к главному археологу."}}
D[11391] = {"Патрулирование Стальных Ворот",{"Теперь вы лучший пилот Стальных ворот, и главный археолог Стальных ворот поручил вам патрулировать раскопки.","","Отразите нападение агрессивных существ, после чего вернитесь к главному археологу."}}
D[11392] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11393] = {"Куда пропал исследователь Джарен?",{"Надзирательница Ирена Каменная Мантия попросила вас отыскать ее суженого, исследователя Джарена."}}
D[11394] = {"Думаешь, мурлоки – самые вонючие существа?",{"Исследователь Джарен поручил вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к нему."}}
D[11395] = {"Устройство Плети",{"Отнесите устройство Плети исследователю Джарену на Берег Стылой Межи."}}
D[11396] = {"Отключи защитное поле",{"Исследователь Джарен поручил вам уничтожить 3 смертоносных кристалла."}}
D[11397] = {"Думаешь, мурлоки – самые вонючие существа?",{"Аптекарь Анастасия поручила вам убить 15 любых солдат Плети, которые встретятся вам вдоль Берега Стылой Межи. Когда вы выполните это задание, вернитесь к ней в Аптекарский поселок."}}
D[11398] = {"Устройство Плети",{"Отнесите устройство Плети аптекарю Анастасии в Аптекарский поселок."}}
D[11399] = {"Отключи защитное поле",{"Аптекарь Анастасия поручила вам уничтожить 3 смертоносных кристалла."}}
D[11400] = {"Скаковые бараны Хмельного фестиваля",{"Покажите штамп Полу Янтарлену у входа на территорию Хмельного фестиваля в Дун Мороге."}}
D[11401] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11402] = {"Clayton's Quest: Extreme!",{"Seriously, go slay those Evil Squirrels!"}}
D[11403] = {"Наконец, свободен!",{"Возьмите книгу Томаса Томсона и отнесите ее попечительнице сирот в маске в Дуротар, Брилл или на Площадь Соколиных Крыльев."}}
D[11404] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11405] = {"Вызов Всадника без головы",{"Принесите мрачную свечу к груде рыхлой вывороченной почвы."}}
D[11406] = {"Все должно быть готово",{"Поговорите с Гилом Гризертом в крепости Вилдервар."}}
D[11407] = {"Пивоварня Дрона ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов."}}
D[11408] = {"Пивоварня Т'чали Вуду ищет зазывалу!",{"Зазывайте посетителей на Хмельной фестиваль у флагов на аллее Силы, на аллее Чести, на аллее Мудрости и на аллее Духов."}}
D[11409] = {"А теперь гонки на баранах... Или вроде того.",{"У вас есть 4 минуты, чтобы погонять барана на всех трех скоростях по 8 секунд."}}
D[11410] = {"Та самая рыбка",{"Кристофер Слоан из крепости Вилдервар просит вас победить Ледяного Плавника."}}
D[11411] = {"Лагерь Заиндевевшего Копыта",{"Поговорите с вождем Прахтотемом в Лагере Заиндевевшего Копыта."}}
D[11412] = {"Туда и обратно",{"Возьмите бочку у гоблина, застрявшего возле Колючего Холма, и отвезите ее помощнику Рэя, погонщика баранов. Пока баран не сбежит от вас, постарайтесь доставить три бочки."}}
D[11413] = {"Кто сказал сувениры?"}
D[11414] = {"Братья-предатели",{"Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Когда вы убьете их, вернитесь к нему в Вырубки в обличье ворга.","","Если вы потеряете личину ворга, возьмите другую у дозорной Лунный Лепесток."}}
D[11415] = {"Братья-предатели",{"Улклык попросил вас убить воргов-предателей, Бьомолфа и Варга. Выполнив его просьбу, наденьте личину ворга и вернитесь к Улклыку.","","Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую."}}
D[11416] = {"Глаза орлицы",{"Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.","","Если вы потеряете личину ворга, вернитесь к дозорной Лунный Лепесток, и она выдаст вам новую."}}
D[11417] = {"Глаза орлицы",{"Улклык поручил вам вырвать глаза великой орлицы. Вернитесь к нему в Вырубки, когда это задание будет выполнено.","","Если вы потеряете личину ворга, вернитесь к ведуну Страннику Туманов, и он даст вам новую."}}
D[11418] = {"Мы зовем его Стальное Перо",{"Найдите Стальное Перо, который кружит над крепостью Вилдервар, и воспользуйтесь оперенным амулетом, чтобы разгадать тайну этого загадочного гиппогрифа. Расскажите Гилу Гризерту о вашей находке."}}
D[11419] = {"Скаковые бараны Хмельного фестиваля",{"Покажите штамп Дризу Неуклюге у входа на территорию Хмельного фестиваля в Дуротаре."}}
D[11420] = {"Путь к отмщению",{"Капитан стражи Зорек из Валгарда в Ревущем фьорде поручил вам вернуть руководство по управлению гарпунной пушкой."}}
D[11421] = {"До упора...",{"Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы уничтожили большой дом Укротителей драконов, верфь Укротителей драконов, склад Укротителей драконов и 8 защитников из клана Укротителей драконов. Как только поручение будет выполнено, верните лейтенанту механизм управления гарпуном."}}
D[11422] = {"Трезубец сына",{"Старый Ледоспин просит вас принести ему трезубец Гниложабера. Он будет ждать вас на маленьком острове возле Берега Стылой Межи."}}
D[11423] = {"Наследие врагов",{"Отправляйтесь к северу Заставы Призрачного Клинка, в Ниффлвар, и найдите три свитка: \"Сагу о проклятии зимы\", \"Сагу о валькириях\" и \"Сагу о близнецах\"."}}
D[11424] = {"Заградительный холм",{"Дженни по прозвищу \"Пила\" просит вас принести ей 5 древних врайкульских костей оживших мертвецов с Заградительного холма, который находится к югу от Нового Агамонда."}}
D[11425] = {"Test Quest - Craig",{"Паразиты, ненавижу!"}}
D[11426] = {"В поисках механизма",{"Капитан стражи Зорек из Валгарда в Ревущем фьорде просит вас принести механизм управления гарпуном."}}
D[11427] = {"Познакомьтесь с лейтенантом Ледяным Молотом",{"Капитан стражи Зорек просит вас отнести механизм управления гарпуном лейтенанту Ледяному Молоту, который укрывается недалеко от Ниффлвара."}}
D[11428] = {"Хранитель Листопад",{"Луриэль с Заиндевевшей поляны просит вас убить Хранителя Листопада."}}
D[11429] = {"Защищай знамя до последнего!",{"Лейтенант Ледяной Молот из Ревущего фьорда хочет, чтобы вы закрепили Знамя Альянса в Гибльхейме и защищали его от нападающих.","","Если вам удастся выжить в этом испытании, верните знамя лейтенанту Ледяному Молоту."}}
D[11430] = {"Мастер-гарпунщик Явус",{"Лейтенант Ледяной Молот из Ревущего фьорда поручил вам убить мастера-гарпунщика Явуса в Ниффлваре."}}
D[11431] = {"Поймать дикого зайцелопа!",{"\"Дворф\", Глодрак Меткий Охотник попросил вас поймать 5 оглушенных диких зайцелопов с помощью особой сети. Он намекнул, что необходимо достичь состояния сильного алкогольного опьянения – или хотя бы надеть Синтехмельные очки."}}
D[11432] = {"Спящие великаны",{"Маг-лейтенант Малистер поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Крепость Западной стражи."}}
D[11433] = {"Спящие великаны",{"Ахота Белый Иней поручил вам уничтожить 5 спящих врайкулов. Когда задание будет выполнено, вернитесь к нему в Лагерь Заиндевевшего Копыта."}}
D[11434] = {"Забытое сокровище",{"Красавчик Терри из Лагеря Скалаваг просит вас достать аманийскую вазу и статуэтку орла с места кораблекрушения на юге."}}
D[11436] = {"Полетаем?",{"Воспользуйтесь большой врайкульской пушкой в Ниффлваре и запустите себя в Валгард. Доложите о победе над врайкулами капитану стражи Зореку."}}
D[11439] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11440] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с переодетой попечительницей сирот."}}
D[11441] = {"Хмельной фестиваль!",{"Поговорите с распорядителем Хмельного фестиваля."}}
D[11442] = {"Добро пожаловать на Хмельной фестиваль!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11443] = {"Подводное плавание в Бухте Кинжалов",{"Гарольд Лаграс из Бухты Кинжалов попросил вас найти 10 валгардских ящиков с припасами."}}
D[11446] = {"Хмельной фестиваль!",{"Поговорите с распорядителем Хмельного фестиваля."}}
D[11447] = {"Добро пожаловать на Хмельной фестиваль!",{"[PH] Speak to the Brewfest Organizer and receive a free beer."}}
D[11448] = {"Лагерь Лиги Исследователей",{"Отвезите сверток Максорфа Станваду в Лагерь Лиги Исследователей в Ревущем фьорде."}}
D[11449] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске в Брилле."}}
D[11450] = {"Учения пожарной бригады",{"Выплесните воду из ведра в 5 очагов пожара. Затем поговорите с попечительницей сирот в маске на Площади Соколиных Крыльев."}}
D[11451] = {"Стишок Алисии",{"Вас попросили отнести стишок Алисии Кайли Дак в Шаттрат в Запределье."}}
D[11452] = {"Спящий король",{"Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Крепость Западной Стражи и доложите о своей победе капитану Адамсу."}}
D[11453] = {"Спящий король",{"Убейте королеву Ангербоду и прервите ритуал пробуждения короля Имирона. Если вам удастся сделать это, вернитесь в Лагерь Заиндевевшего Копыта и сообщите о своей победе вождю Прахтотему."}}
D[11454] = {"Поиски диверсантов",{"Найдите Худовара в \"Угрюмом обжоре\" в Глубинах Черной горы."}}
D[11455] = {"Запах денег",{"Красавчик Терри из Лагеря Скалаваг в Ревущем фьорде просит вас добыть 4 мускусные железы бешеных бурых медведей, которые бродят по всему острову."}}
D[11456] = {"Мясо для выживших",{"Предок Атуик из Камагуа в Ревущем фьорде просит вас принести 6 кусков мяса островного черпорога с Острова Копий."}}
D[11457] = {"Вооружая Камагуа",{"Старейшина Атуик просит вас добыть 3 рога химеры."}}
D[11458] = {"Месть за Искаал",{"Старейшина Атуик просит вас отправиться в Искаал и убить 8 поработителей – пиратов Северных морей. Если вам понадобится помощь, воспользуйтесь Рогом Камагуа."}}
D[11459] = {"Что сказал Зех'ген",{"Вернитесь к Красавчику Терри и попросите объяснить, что хотел от вас Зех'ген."}}
D[11460] = {"Завоевание доверия",{"Идальго из Лагеря Лиги Исследователей в Ревущем фьорде послал вас найти червяка фьорда и скормить его одному из соколов в клетке, стоящей у его ног."}}
D[11461] = {"ИСКЛЮЧЕНО"}
D[11464] = {"Карточный долг",{"Тарук из Лагеря Скалаваг просит вас взыскать долг Гарри \"Луносвета\"."}}
D[11465] = {"Разграбленный караван",{"Идальго из Лагеря Лиги Исследователей в Ревущем Фьорде попросил вас поймать 5 индюков фьорда с помощью обученного скального сокола.","","Как только поручение будет выполнено, верните клетку сокольничему."}}
D[11466] = {"Стаканчик для Джека",{"Тарук из Лагеря Скалаваг просит вас взыскать долг Джека Адамса."}}
D[11467] = {"Долг мертвеца",{"Тарук из Лагеря Скалаваг просит вас выкопать сокровище Блэка Конрада с северо-восточного побережья острова Копий, что к северу от Искаала."}}
D[11468] = {"Ястреб против сокола",{"Идальго из Лагеря Лиги Исследователей в Ревущем фьорде просит вас поймать 10 ястребов фьорда с помощью вашего обученного скального сокола.","","Когда вы выполните это задание, верните Идальго клетку с соколом."}}
D[11469] = {"Мыло для чистки палуб",{"Побегушка Мерзлонос просит вас принести ей сальник Большого Роя, чтобы она могла сварить из него мыло для чистки палуб. Она ждет вас на восточном пиратском корабле в Лагере Скалаваг."}}
D[11470] = {"Птицы не знают о чести",{"Идальго из Лагеря Лиги Исследователей в Ревущем фьорде поручил вам выкрасть восемь яиц ястреба фьорда с помощью вашего обученного скального сокола.","","Когда вы выполните задание, верните Идальго клетку с соколом."}}
D[11471] = {"Конец игры",{"Энни Бонн из Лагеря Скалаваг хочет, чтобы вы принесли ей подзорную трубу Ионы Стерлинга."}}
D[11472] = {"Путь к его сердцу...",{"Подкиньте несколько вкусных рифовых рыб рифовому буйволу, чтобы он последовал за вами к рифовой корове. Когда эти двое одиноких сердец найдут друг друга, вернитесь к Ануниаку в Камагуа."}}
D[11473] = {"Предатель среди нас",{"Поговорите с Зех'геном в Лагере Скалаваг."}}
D[11474] = {"Беда на Крутых утесах",{"Поговорите с Уолтом."}}
D[11475] = {"Орудия труда",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас вернуть его строительные инструменты."}}
D[11476] = {"Нож и лягушка",{"Купите блестящий нож у Гарри \"Луносвета\" и поймайте скалавагскую лягушку. Отнесите все это Зех'гену в Лагерь Скалаваг."}}
D[11477] = {"Дворф другой породы",{"Донни из Руин Ивальда в Ревущем фьорде просит вас убить 10 разрушителей из клана Железной Руны, 5 работников из клана Железной Руны и 2 ведуна из клана Железной Руны."}}
D[11478] = {"На той заставе...",{"Доставьте письмо от Донни Станваду в Лагерь Лиги Исследователей."}}
D[11479] = {"\"Хромой\" Дэн",{"Проучите \"Хромого\" Дэна, который прячется на одном из кораблей в Лагере Скалаваг. Когда выполните это задание, поговорите с Красавчиком Терри."}}
D[11480] = {"Познакомьтесь с номером два",{"Поговорите с Энни Бонн в Лагере Скалаваг."}}
D[11481] = {"Чрезвычайная ситуация у Солнечного Колодца",{"Адиен Страж Света с возвышенности Алдоров в Шаттрате поручает вам отправиться на плато Солнечного Колодца и поговорить с Ларетором."}}
D[11482] = {"Зов долга",{"Датрис Солнцесвет с яруса Провидцев Шаттрата настаивает, чтобы вы отправились на Азерот немедленно и поговорили с Ларетором у Солнечного Колодца."}}
D[11483] = {"Мы тоже так можем!",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас достать ему большую бочку, крепкий промышленный канат и несколько слитков черного железа."}}
D[11484] = {"Мы знаем технологию",{"Уолт из Лагеря Лиги Исследователей просит вас достать ему безупречную шкуру черпорога и стальной каркас."}}
D[11485] = {"Голем Железной руны: обучение \"Реактивному прыжку\"",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас воспользоваться способностью \"Реактивный прыжок\" голема Железной Руны, стоя на вырезанной Уолтом руне.","","После выполнения упражнения отпустите голема."}}
D[11486] = {"Лучшее пиво"}
D[11487] = {"Лучшее пиво"}
D[11488] = {"Терраса Магистров",{"Экзарх Ларетор с плацдарма армии Расколотого Солнца просит вас найти на террасе Магистров своего разведчика – эльфа крови Тирита."}}
D[11489] = {"Голем Железной руны: обучение \"Сбору информации\"",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас воспользоваться способностью голема железной руны \"Сбор информации\", стоя рядом с реликвией железных дворфов.","","После выполнения упражнения отпустите голема."}}
D[11490] = {"Провидец Провидцев",{"Тирит просит вас использовать шар на балконе террасы Магистров."}}
D[11491] = {"Голем Железной руны: обучение \"Обманке\"",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас потренироваться в использовании способности \"Обманка\" голема Железной руны. Для этого вам надо наступить на коврик Лебронски.","","После выполнения упражнения отпустите голема."}}
D[11492] = {"Страшный противник",{"Калесгос велит вам уничтожить Кель'таса на террасе Магистров. Отрубите Келю голову и вернитесь к Ларетору на плацдарм армии Расколотого Солнца."}}
D[11494] = {"Заряженные молнией артефакты",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас собрать 15 наборов данных о Железной Руне с помощью способности \"Сбор информации\" голема Железной Руны.","","После выполнения задания отпустите голема."}}
D[11495] = {"Нежный звук грома",{"Уолт из Лагеря Лиги Исследователей в Ревущем фьорде просит вас исследовать грохочущую пещеру на Раскопках Бейлгуна с помощью голема из клана Железной Руны.","","После выполнения задания отпустите голема."}}
D[11496] = {"Охрана святилища",{"Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке."}}
D[11497] = {"Орлята учатся летать",{"Поговорите с Илсой Бурное Варево в цитадели Громового Молота в долине Призрачной Луны."}}
D[11498] = {"Орлята учатся летать",{"Поговорите с Олрокком в деревне Призрачной Луны в долине Призрачной Луны."}}
D[11499] = {"Разыскивается: перстень-печатка принца Кель'таса",{"Торговец ветром Зарим хочет, чтобы вы добыли ему перстень-печатку принца Кель'таса. Доставьте ее в Нижний город Шаттрата и получите награду.","","Это задание выполняется на террасе Магистров только в героическом режиме."}}
D[11500] = {"Разыскиваются: сестры Терзаний",{"Ловчий Пустоты Ма'дуун хочет, чтобы вы убили 4 сестер терзаний. Вернитесь к нему в Нижний город Шаттрата, когда перебьете их, чтобы забрать награду."}}
D[11501] = {"Вести с востока",{"Поговорите с капитаном Адамсом из Крепости Западной Стражи."}}
D[11502] = {"Защита Халаа",{"Победите 10 игроков вражеской фракции в Халаа и вернитесь в Телаар к Лакуру."}}
D[11503] = {"Враги старые и враги новые",{"Победите 10 игроков вражеской фракции в Халаа и вернитесь в Гарадар к Карртогу."}}
D[11504] = {"Ожившие мертвецы",{"Орфус Камагуанский с Древнего подъемника просит вас принести ему улики из могил Фенгира, Родина, Исулдофа и Ветрана."}}
D[11505] = {"Духи Аукиндона",{"Помогите Альянсу удерживать Башню духов в Костяных пустошах."}}
D[11506] = {"Духи Аукиндона",{"Помогите Орде удерживать Башню духов в Костяных пустошах."}}
D[11507] = {"Старейшина Атуик из Камагуа",{"Орфус Камагуанский из Ревущего фьорда просит вас отнести узелок старейшине Атуику из Камагуа."}}
D[11508] = {"Греззикс Иглохруст",{"Поговорите с Греззиксом Иглохрустом."}}
D[11509] = {"Чудак среди чудаков",{"Поговорите с Гарри \"Луносветом\" в Лагере Скалаваг и расспросите его о пропавших врайкульских артефактах."}}
D[11510] = {"\"Челюсти\"",{"Гарри \"Луносвет\" из Лагеря Скалаваг просит вас достать гадальный шар син'дорай, принадлежащий ему, из брюха дельфина-косатки по прозвищу \"Челюсти\"."}}
D[11511] = {"Посох Неистовства Бури",{"Найдите посох Неистовства Бури и отнесите его Орфусу Камагуанскому в Ревущий фьорд."}}
D[11512] = {"Ледяное сердце Исулдофа",{"Найдите ледяное сердце Исулдофа и отнесите его Орфусу Камагуанскому в Ревущий фьорд."}}
D[11513] = {"Перехват контейнеров с маной",{"Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат."}}
D[11514] = {"Поддержка портала Солнечного Колодца",{"Добудьте 10 контрабандных контейнеров с маной и отнесите их экзарху Назууну на террасу Света в Шаттрат."}}
D[11515] = {"Кровь за кровь",{"Магистр Сейла у трона Кил'джедена велит вам убить 4 истощенных сквернокровов при помощи конденсатора Скверны. Вам понадобится кровь демонов, которая течет по венам находящихся рядом зловещих глашатаев, чтобы наполнить конденсатор Скверны."}}
D[11516] = {"Взрыв врат",{"Магистр Сейла у трона Кил'джедена велит вам взять раскаленные угли, чтобы вызвать живую вспышку и убивать рядом с ней раскаленных искр Скверны, пока она не станет нестабильной живой вспышкой. Вернитесь к вратам Легиона вместе с нестабильной живой вспышкой, чтобы уничтожить врата."}}
D[11517] = {"Встреча с Назууном",{"Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате."}}
D[11518] = {"Еежедневный указатель портала Солнечного Колодца"}
D[11519] = {"Пропавший щит Эсиритса",{"Поговорите с капитаном Эллис на борту \"Сестренки милосердия\"."}}
D[11520] = {"Смотри в корень",{"Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа."}}
D[11521] = {"И опять – смотри в корень",{"Мар'на из гавани Солнечного Края просит вас отправиться на уступ Острого Шипа в Запределье, чтобы добыть для нее 5 корней Острого Шипа."}}
D[11523] = {"Подпитка для силового поля",{"Капитан Терис Рассветное Пламя с плацдарма армии Расколотого Солнца просит вас добыть 4 клочка маны у Презренных-злобней и Презренных-пожирателей и при их помощи активировать поле кристалла-хранителя, окружающее святилище Солнечного Края на востоке."}}
D[11524] = {"Хаотичное поведение",{"Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит, чтобы вы поместили настроенные кристаллы-сердечники в корпуса 5 побежденных магических стражей, чтобы перевести их в дружественный режим."}}
D[11525] = {"Дальнейшая перенастройка",{"Воздаятельница Ксаяна на подготовительном плацдарме Расколотого Солнца просит вас поместить настроенные кристаллы-сердечники в корпуса 5 побежденных блуждающих караульных, чтобы перевести их в дружественный режим."}}
D[11526] = {"Пропавший магистр",{"При помощи захваченного свитка Легиона, пройдите сквозь портал на Рассветной площади. Как только пройдете сквозь портал, найдите магистра Сейлу."}}
D[11527] = {"Бунт на корабле",{"Капитан Эллис на борту \"Сестренки милосердия\" в Ревущем фьорде просит вас принести 5 бочек с порохом из трюма корабля."}}
D[11528] = {"Подарок к Зимнему Покрову"}
D[11529] = {"Сокровища Сорлофа",{"Убейте Сорлофа из большой пушки и принесите капитану Эллис сокровища Сорлофа на борт \"Сестренки милосердия\"."}}
D[11530] = {"Щит Эсиритса",{"Верните щит Эсиритса Орфусу Камагуанскому на Древний подъемник в Ревущем фьорде."}}
D[11531] = {"Странная деталь мотора",{"Отнесите странную деталь мотора к К. Ли Мелюзге в Терелдор."}}
D[11532] = {"Отвлекающий маневр на Тропе Мертвых",{"Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов."}}
D[11533] = {"Воздушные атаки должны продолжаться!",{"Боевой маг Аринна хочет, чтобы вы поговорили с Айреном Ясное Небо, когда вы будете готовы к полету к Тропе Мертвых. Оказавшись над Тропой, при помощи чародейских зарядов уничтожьте 2 владык преисподней, 3 эредарских колдунов и 12 зловещих головорезов."}}
D[11534] = {"Встреча с Назууном",{"Торговец Портануус просит вас поговорить с экзархом Назууном на террасе Света в Шаттрате."}}
D[11535] = {"Подготовка к работе",{"Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков."}}
D[11536] = {"Продолжаем...",{"Кузнец Хаутаа из оружейной Солнечного Края просит вас перебить мирмидонов из клана Черноспинов к востоку отсюда и при помощи их ключей украсть три куска руды из их сундуков."}}
D[11537] = {"Битва должна продолжаться!",{"Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара Ненависти на Рассветной площади. Пригвоздите к земле древком Знамени Расколотого Солнца труп Эмиссара Ненависти."}}
D[11538] = {"Сражение за оружейную Солнечного Края",{"Предвестник Инууро просит вас убить 6 демонов Пылающего Легиона и эмиссара ненависти на Рассветной площади или в оружейной Солнечного Края. Пригвоздите труп эмиссара ненависти к земле древком знамени армии Расколотого Солнца."}}
D[11539] = {"Захват гавани",{"Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета."}}
D[11540] = {"Клинки Рассвета должны быть сокрушены!",{"Магистр Иластар из оружейной Солнечного Края просит вас убить 6 призывателей, 6 рыцарей крови и 3 стрелков из клана Клинка Рассвета."}}
D[11541] = {"Зачистить берег Зеленожабрых!",{"Капитан Валиндрия просит вас освободить 10 рабов из племени Зеленожабрых. Вернитесь к ней на борт \"Гордости Луносвета\" в гавань Солнечного Края по выполнении задания."}}
D[11542] = {"Перехватить подкрепление",{"Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета."}}
D[11543] = {"Загнать врага в угол",{"Воздаятель Каалан из оружейной Солнечного Края просит вас поговорить с Айреном Ясным Небом насчет полета до флота Клинков Рассвета. Затем при помощи горящего масла подожгите с воздуха паруса кораблей, а приземлившись, убейте 6 резервистов из армии Клинков Рассвета."}}
D[11544] = {"Оружие Ата'мала",{"Кузнец Хаутаа просит вас сделать для нее 5 кусков очищенного металла Ата'мала. Сделайте это, раздробив на ее наковальне оружие Ата'мала в оружейной Солнечного Края на острове Кель'Данас."}}
D[11545] = {"Никто не забыт...",{"Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых."}}
D[11546] = {"Взаимовыгодный бизнес",{"Мар'на из гавани Солнечного Края просит вас принести ей 5 ягод кровяники с кустов, которые можно найти на Кель'Данасе."}}
D[11547] = {"Знай свою силовую линию!",{"Звездочет Дарнариан из святилища Солнечного Края просит вас при помощи кристалла звездочета настроить кровавый кристалл, портал на Рассветной площади и святилище наг на берегу Зеленожабрых."}}
D[11548] = {"Щедрое пожертвование",{"Анахоретка Аюри из Солнечного Края у Солнечного Колодца просит вас пожертвовать 10 золотых."}}
D[11549] = {"Великодушный благодетель",{"Анахорет Каиртос просит вас пожертвовать 1000 золотых на дело анахоретки Аюри. Вас будут называть Nekoquestie из армии Расколотого Солнца, если вы это сделаете."}}
D[11550] = {"Входи, Искуситель...",{"Отнесите сообщение верховному магу Нет'улу на остров Кель'Данас, к северу от Кель'Таласа.","","Любой распорядитель полетов в Стальгорне или Луносвете доставит вас до места назначения."}}
D[11551] = {"Агамат, Первые врата"}
D[11552] = {"Рохендор, Вторые врата"}
D[11553] = {"Архониус, Последние врата"}
D[11554] = {"Солдатская дружба"}
D[11555] = {"Уважение союзников"}
D[11556] = {"Почтение боевых друзей"}
D[11557] = {"Восхищение всего войска"}
D[11558] = {"Опасная любовь",{"Возьмите заплесневелую открытку стража и отнесите ее Фенстаду Аргайлу в Подгороде."}}
D[11559] = {"Торговля с Зимними Плавниками",{"Соберите 5 моллюсков Зимних Плавников и отдайте их Ахлурглгру в Приюте Зимних Плавников."}}
D[11560] = {"О нет, наши бедные малыши!",{"По поручению короля Мргла-Мргла спасите 20 головастиков Зимних Плавников. Вернитесь к королю в Приют Зимних Плавников, когда выполните задание."}}
D[11561] = {"Они!",{"По просьбе Брглмургла в Приюте Зимних Плавников убейте воинов, оракулов и гарпунеров Зимних Плавников – всего 15 мурлоков."}}
D[11562] = {"Меня хотят очернить!",{"По просьбе короля Мргла-Мргла поговорите с Мрмрглмром на северо-западной стороне Приюта Зимних Плавников."}}
D[11563] = {"Грммурглл Мрллглл Глрггл!",{"Принесите Мрмрглмру в Приюте Зимних Плавников голову Глрггла."}}
D[11564] = {"Сочное жаркое из косатки",{"По поручению Колуна Бмурглбрма добудьте и принесите 7 кусков мясистого сальника косатки. С мясом возвращайтесь к нему в Приют Зимних Плавников."}}
D[11565] = {"Запасной комплект",{"Верните запасной костюм короля Мргла-Мргла королю Мрглу-Мрглу в Приют Зимних Плавников."}}
D[11566] = {"Сдаться? Ни за что!",{"Принесите коготь Клаксимуса королю Мргл-Мргл в Приюте Зимних Плавников."}}
D[11567] = {"Древняя броня Квалдира",{"Найдите древнюю броню Квалдира и отнесите ее Орфусу Камагуанскому в Ревущий фьорд."}}
D[11568] = {"Возвращение святынь",{"Используйте мешок с врайкульскими артефактами на разграбленных курганах Заградительного холма и верните на место Ледяное сердце Исулдофа, Щит Эсиритса, Посох Неистовства Бури и Древнюю броню Квалдира. Когда поручение будет выполнено, вернитесь к Орфусу Камагуанскому на Древний подъемник."}}
D[11569] = {"Хранитель ключей Ургргрл",{"По просьбе Глрглрглра в пещерах Зимних Плавников раздобудьте ключ Ургргрла."}}
D[11570] = {"Бегство из пещер Зимних Плавников",{"Проводите Лургглбра в безопасное место и вернитесь к королю Мргл-Мрглу в Приют Зимних Плавников, чтобы сообщить ему хорошую новость."}}
D[11571] = {"Обучение коммуникации",{"Наполните ракушку, которую дал вам король Мргл-Мргл, над останками Скольдер. Верните наполненную ракушку короля Мрглу-Мрглу в Приют Зимних Плавников."}}
D[11572] = {"Возвращение к Атуику",{"Доставьте тревожные известия старейшине Атуику в Камагуа."}}
D[11573] = {"Орфус Камагуанский",{"Найдите Орфуса Камагуанского на Древнем подъемнике в Ревущем фьорде."}}
D[11574] = {"Переживания на грани",{"По просьбе Эндоры отправляйтесь на Янтарную Гряду к северу от крепости Песни Войны и поблагодарите тамошних обитателей за ее спасение."}}
D[11575] = {"Своевременное спасение",{"По просьбе Мушки из крепости Отваги отправляйтесь на Янтарную гряду к северу и поблагодарите тамошних обитателей за ее спасение."}}
D[11576] = {"Наблюдения за расселиной: обнаружена аномалия",{"По просьбе Гаррена с Янтарной гряды воспользуйтесь тайнометром у аномалии утеса Западной расселины."}}
D[11577] = {"Коллекционное издание WoW: – DEM – E – FLAG"}
