D[11580] = {"Осквернение огня"}
D[11581] = {"Осквернение огня"}
D[11582] = {"Наблюдения за расселиной: Расколотая бездна",{"По поручению Гаррена с Янтарной гряды воспользуйтесь тайнометром у Расколотой бездны и возвращайтесь к нему с полученными данными."}}
D[11583] = {"Поклонение огню"}
D[11584] = {"Поклонение огню"}
D[11585] = {"Бдение Адского Крика",{"Поговорите с Гаррошем Адским Криком в крепости Песни Войны."}}
D[11586] = {"Бдение Адского Крика",{"Поговорите с Гаррошем Адским Криком в крепости Песни Войны."}}
D[11587] = {"Побег из тюрьмы",{"По просьбе библиотекаря Донатана с Янтарной гряды добудьте берилловый магический ключ у охотника на магов в Берилловом лагере и используйте его, чтобы освободить пленного мага из магической клетки."}}
D[11590] = {"Похищение",{"Заключите в магические оковы раненого бериллового колдуна в Берилловом лагере и возвращайтесь вместе с ним к Донатану."}}
D[11591] = {"Явиться в караван Стальной Челюсти",{"Поговорите с рубакой Гневной Дланью в караване Стальной Челюсти."}}
D[11592] = {"Мы ударим!",{"Помогите выносливому гонцу Гордому Копыту и его налетчикам Песни Войны выжить во время нападения на караван Стальной Челюсти и прикончить дух командира соединения Стальной Челюсти.","","В случае успеха доложитесь властителю Бор'гороку на заставе Бор'горока."}}
D[11593] = {"Последние почести",{"По просьбе рубаки Гневной Длани близ каравана Стальной Челюсти используйте факел Гневной Длани для сожжения мертвых стражей каравана и рабочих каравана (10 тел в любой комбинации)."}}
D[11594] = {"Пусть обретут покой!",{"Упокойте 20 духов таунка, фантомных ведунов либо восставших выносливых гонцов, и сообщите об этом рубаке Гневной Длани, который ожидает в Караване Стальной Челюсти."}}
D[11595] = {"Оборона крепости Песни Войны",{"Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны."}}
D[11596] = {"Оборона крепости Песни Войны",{"Доложитесь властителю Разгору, находящемуся в хижине на южной стороне крепости Песни Войны."}}
D[11597] = {"Оборона крепости Песни Войны",{"Явитесь к властителю Разгору в хижине у южной стены крепости Песни Войны."}}
D[11598] = {"Отвоевывание карьера Камня Силы",{"По заданию властителя Разгора из крепости Песни Войны убейте 15 неруб'арцев."}}
D[11599] = {"Тассариан, мой брат",{"Найти Вильяма Аллертона в шахте Далечья."}}
D[11600] = {"Последние новости о Вильяме Аллертоне",{"Отнесите воинское удостоверение Лериссе в Крепость Отваги в Борейской тундре."}}
D[11601] = {"Потерянный и обретенный",{"Поговорите с Джеймсом Диконом в таверне в крепости Отваги."}}
D[11602] = {"Прервать на корню",{"По поручению властителя Разгора, находящегося в крепости Песни Войны, уничтожьте 10 неруб'арских яиц."}}
D[11603] = {"Истина в вине",{"Раздобудьте бутылку кул-тирасского вина на месте кораблекрушения к северо-востоку от Крепости Отваги и принесите старику Колберну в таверну в Крепости Отваги."}}
D[11604] = {"Дезертир",{"Найдите тюрьму во Внутренней крепости Отваги и поговорите с дезертиром."}}
D[11605] = {"Досточтимые предки",{"По просьбе старейшины Атканока, находящегося у карьера Ледяного Булыжника, отыщите статуи, предназначенные для старейшины Кесука, старейшины Сагани и старейшины Такрета."}}
D[11606] = {"Терпение – добродетель, которая не требуется",{"По поручению интенданта Холгота раздобудьте 15 ящиков с боеприпасами Песни Войны."}}
D[11607] = {"Заблудшие духи",{"Освободите дух 3 ремесленников клана Каскала и 3 шаманов клана Каскала по просьбе старейшины Атканока в окрестностях карьера Ледяного Булыжника."}}
D[11608] = {"Засыпать тараканьи норы!",{"По поручению интенданта Холгота используйте сверток с глубинными сефориевыми зарядами для уничтожения неруб'арских воронок к югу, востоку, западу и северу от крепости Песни Войны."}}
D[11609] = {"Сбор ритуальных предметов",{"Принесите 6 клыкаррских ритуальных предметов старейшине Атканоку, который стоит у карьера Ледяного Булыжника."}}
D[11610] = {"Возвращение предков",{"По просьбе старейшины Атканока проведите духов старейшины Кесука, старейшины Сагани и старейшины Такрета в их каменные изваяния."}}
D[11611] = {"Захваченные Плетью",{"По заданию штейгера Мортууса из Крепости Песни Войны освободите 5 батраков клана Песни Войны."}}
D[11612] = {"Бой за карьер",{"По просьбе Этарука, находящегося у входа в карьер Ледяного Булыжника, убейте 12 берилловых охотников за сокровищами."}}
D[11613] = {"Клятва Карука",{"По просьбе Карука убейте 6 скадирских налетчиков и 5 скадирских лодочников."}}
D[11614] = {"Невысказанные истины",{"Отыщите тенелова Лютера в карьере Камня Силы."}}
D[11615] = {"Неруб'арские тайны",{"Доставьте дневник Лютера тенелову Бартусу в Крепость Песни Войны."}}
D[11616] = {"Послание Адскому Крику",{"Отнесите записку Бартуса Гаррошу Адскому Крику в крепости Песни Войны."}}
D[11617] = {"Никто не должен уйти",{"По поручению Этарука из карьера Ледяного Булыжника уничтожьте Северную, Восточную и Западную платформы."}}
D[11618] = {"Подкрепление на подходе…",{"Отыщите тенелова Икориса на заставе у ферм Песни Войны к западу от крепости Песни Войны."}}
D[11619] = {"Геймел Жестокий",{"Убейте Геймела Жестокого с Берега Терзающего Бича по просьбе Карука."}}
D[11620] = {"Отцовские слова",{"Поищите Вихью у святилища Чешуи на берегу Терзающего Бича."}}
D[11621] = {"Табличка Левирота",{"Возвращайтесь к Каруку с информацией, обнаруженной вами на табличке."}}
D[11622] = {"Тайны Терзающего Бича",{"Найдите Вихью на развалинах Терзающего Бича в Борейской тундре."}}
D[11623] = {"Визит к смотрителю",{"По заданию Этарука с края карьера Ледяного Булыжника убейте смотрителя Инзивиуса."}}
D[11624] = {"Небо знает",{"Поговорите с Империан в руинах Элдра'ната."}}
D[11625] = {"Трезубец Наз'жана",{"Отправляйтесь к дальнему северо-восточному краю Руин Терзающего Бича. Убейте Рагнара Драккарлунда, завладейте трезубцем Наз'жана, а затем отнесите его Вихье на берег Терзающего Бича."}}
D[11626] = {"Посланник",{"Найдите Левирота в водах под айсбергом, плавающим у северной окраины Руин Терзающего Бича. Воспользуйтесь трезубцем Наз'жана, чтобы убить Левирота и возвращайтесь к Каруку, ожидающему вас на севере берега Терзающего Бича."}}
D[11627] = {"Точка кипения",{"По просьбе Империан нанесите поражение Шкварчуну и Вспеннеру, а затем вернитесь к ней в руины Элдра'ната."}}
D[11628] = {"Нечистое должно послужить чистому",{"Принесите вождю Зимней Стуже в деревню Таунка'ле 5 оскверненных шкур мамонта."}}
D[11629] = {"Назад, к говорящей с духами",{"Доставьте изначальную сущность Империан говорящей с духами Рычеклык на заставу Бор'горока."}}
D[11630] = {"Оскверненная Плетью земля",{"Принесите 8 комков оскверненной Плетью земли вождю Зимней Стуже в деревню Таунка'ле."}}
D[11631] = {"Воздушные видения",{"Воспользуйтесь изначальной сущностью Империан для проведения ритуала возле тотема говорящей с духами Рычеклык на заставе Бор'горока, чтобы получить информацию о предсказателе Печальном Путнике.","","После этого поговорите с говорящей с духами Рычеклык."}}
D[11632] = {"Что несет холодный ветер?..",{"Отнесите отвердевший панцирь Ит'рикса верховному правителю Саурфангу в Крепость Песни Войны."}}
D[11633] = {"Вписаться в ландшафт",{"По поручению вождя Зимней Стужи отправляйтесь в храмовый город Эн'кила, наденьте прочную накидку Плети и исследуйте Шпиль Крови, Шпиль Боли и Шпиль Порчи."}}
D[11634] = {"Повелитель ветра То'бор",{"Явитесь к повелителю ветра То'бору в крепости Песни Войны."}}
D[11635] = {"Дух предсказателя Печального Путника",{"Поговорите с духом предсказателя Печального Путника в глубинах Магмота."}}
D[11636] = {"Полет на ковре-самолете",{"Поговорите с Янни в крепости Песни Войны, чтобы организовать вам безопасную доставку на побережье. Когда прибудете в лагерь Гарроша, поговорите с крушителем Грек'лором."}}
D[11637] = {"Каганишу",{"Добудьте амулет Каганишу и задействуйте его над останками предсказателя Печального Путника.","","Вам нужно будет передать амулет предсказателю Печальному Путнику в Магмоте."}}
D[11638] = {"Вернуть мои останки",{"Доставьте останки предсказателя Печального Путника, которые покоятся под его духом, говорящей с духами Рычеклык на заставу Бор'горока."}}
D[11639] = {"Месть в Магмоте",{"Убейте магмотов: 10 шаманов, 5 добытчиков, 3 сокрушителя и 3 жен Магмотрегара. Затем возвращайтесь к Орторошу на заставу Бор'горока."}}
D[11640] = {"Слова могущества",{"Принесите свиток верховного жреца Наферсета, свиток верховного жреца Талет-Ха и свиток верховного жреца Андората вождю Зимней Стуже в деревне Таунка'ле."}}
D[11641] = {"Смелость города берет!",{"Убейте 15 вурдалаков и 5 некромантов из Эн'кила и доложите об этом Дурму Ледяной Шкуре, который живет в деревне Таунка'ле."}}
D[11642] = {"Танк сам собой не починится!",{"Поговорите с Мобу в лагере Гарроша."}}
D[11643] = {"Танковая пневматическая трансзажиматрица Мобу",{"Принесите Мобу на берег Эха в Борейской тундре его танковую пневматическую трансзажиматрицу."}}
D[11644] = {"Сверхпрочные металлические пластины!",{"По заданию Мобу соберите 10 сверхпрочных металлических пластин и принесите ему на берег Эха в Борейской тундре."}}
D[11645] = {"Грязные, вонючие снобольды!",{"Добудьте 10 ящиков с вещами Умейки и верните их Умейке Шестеркрут на взлетной полосе Выкрутеня."}}
D[11646] = {"Борейские дознаватели",{"По приказу Донатана пойдите к библиотекарю Нормантису в башню магов на Янтарной гряде и предложите ему свою помощь."}}
D[11647] = {"Обезвредить чумные котлы",{"Используйте тотем ведуньи Эйри из деревни Таунка'ле, чтобы нейтрализовать восточный котел, центральный котел и западный котел в Храмовом городе Эн'кила."}}
D[11648] = {"Искусство убеждения",{"Используйте генератор боли против закованного бериллового колдуна, пока тот не выдаст местонахождение леди Эванор, по просьбе библиотекаря Нормантиса с Янтарной гряды."}}
D[11649] = {"Частицы разгневанных бурь",{"Добудьте 5 частиц бури и принесите Империан в руины Элдра'ната."}}
D[11650] = {"Еще кое-что…",{"Найдите инструменты Умейки, перегруженный конденсатор и горсть песка Рокнара. Доставьте все это Умейке Шестеркрут на взлетную полосу Выкрутеня."}}
D[11651] = {"Броня крепка, и танки наши…",{"Поговорите с крушителем Грек'лором на берегу Эха."}}
D[11652] = {"Равнины Назама",{"Используйте ордынский осадный танк, чтобы уничтожить 100 солдат Плети и спасти 3 раненых солдата Песни Войны на равнинах Назама. Кроме того, выясните, кто возглавляет наступление Плети.","","Выполнив все это, отправляйтесь к Гаррошу Адскому Крику в крепость Песни Войны."}}
D[11653] = {"Ха! Не такой уж ты и большой теперь!",{"Испробуйте прототип ультрасовременного укорачивающего излучателя Умейки на 5 магмотах-сокрушителях или женах Магмотрегара. Когда все будет сделано, вернитесь к Умейке на взлетную полосу Выкрутеня."}}
D[11654] = {"Шпиль Крови",{"Поищите на Шпиле Крови информацию касательно склянки со свежей кровью."}}
D[11655] = {"В туман",{"Убейте квалдиров, найдите 8 реликвий клыкарров и принесите их Вальтору из Пал'ии на берег Эха в Борейской тундре."}}
D[11656] = {"Показательное сожжение",{"По заданию Вальтора из Пал'ии с Берега Эха сожгите квалдирские корабли у Пал'ии и у лагеря Гарроша с помощью клыкаррского факела. Нужно уничтожить следующие суда: \"Змеиная Пасть\", \"Кур Драккар\", \"Молот Бора\" и \"Наковальня Бора\"."}}
D[11657] = {"Поймай факел!",{"Поймайте подряд 4 факела, затем поговорите с мастером-огнеглотателем."}}
D[11658] = {"План Б",{"По просьбе Умейки Шестеркрут со взлетной полосы Выкрутеня соберите 10 комплектов одежды и знамя клана Песни Войны."}}
D[11659] = {"Уничтожьте шары!",{"Уничтожьте 5 кровавых сфер и сообщите о случившемся снежному следопыту Джунеку в деревне Таунка'ле."}}
D[11660] = {"Рог старого морехода",{"Принесите рог старого морехода Вальтору из Пал'ии на берег Эха в Борейской тундре."}}
D[11661] = {"Орабус Кормчий",{"По заданию Вальтора из Пал'ии с берега Эха в Борейской тундре протрубите в рог древнего моряка, чтобы призвать Орабуса Кормчего. Когда Орабус появится, убейте его."}}
D[11662] = {"Найти Карука",{"Найдите Карука на берегу Терзающего Бича."}}
D[11663] = {"Передача сведений",{"По просьбе Нормантиса отчитайтесь библиотекарю Донатану на Янтарной гряде."}}
D[11664] = {"Спастись из тумана",{"Выведите Муту Младшую из тумана. Если вам удастся спасти Муту Младшую, поговорите со старейшиной Муту."}}
D[11665] = {"Кроколиски в городе",{"Принесите старине Барло детеныша кроколиска. Он рыбачит на озере Силмир на северо-востоке от Шаттрата."}}
D[11666] = {"Поймай бандюгу",{"Поймайте черноперого ерша и принесите его старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир."}}
D[11667] = {"Та самая рыбка",{"Поймайте величайшую ильную рыбу в мире и принесите ее старине Барло. Он рыбачит к северо-востоку от Шаттрата на озере Силмир."}}
D[11668] = {"Ловить креветок – это не жук чихнул",{"Принесите 10 гигантских пресноводных креветок старине Барло. Он рыбачит на озере Силмир на северо-востоке от Шаттрата."}}
D[11669] = {"Филе сквернокровного луциана",{"Принесите старине Барло чудовищного сквернокровного луциана. Старик удит рыбу к северо-востоку от Шаттрата в озере Силмир."}}
D[11670] = {"Это были орки, честно!",{"Переоденьтесь орком Песни Войны и водрузите знамя клана Песни Войны над трупом Магмотрегара. Затем вернитесь вместе с личиной к Умейке Шестеркрут на взлетную полосу Выкрутеня."}}
D[11671] = {"Наперегонки со временем",{"По поручению Донатана с Янтарной гряды уничтожьте щит в Берилловом лагере, воспользовавшись разрушителем Бериллового щита. Затем сразите Салранд и заберите найденный у нее ключ."}}
D[11672] = {"День зачисления",{"Поговорите с генералом Арлосом в казармах крепости Отваги."}}
D[11673] = {"Вытащите меня отсюда!",{"Проводите Бонкера Тумблевольта в безопасное место и сообщите об этом Выкрутеню Разгоняйло со взлетной полосы Выкрутеня."}}
D[11674] = {"Ведунья Высокий Холм пропала!",{"Найдите ведунью Высокий Холм близ Келий Смерти."}}
D[11675] = {"Достойная смерть",{"Уничтожьте 10 чумных магнатавров и возвращайтесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти."}}
D[11676] = {"Наконец-то свобода!",{"Освободить 5 узников Плети по просьбе тенелова Канариуса с заставы у ферм Песни Войны."}}
D[11677] = {"Остановить чуму!",{"Используйте очистительные семена ведуньи Высокий Холм у чумного котла в Кельях Смерти, чтобы нейтрализовать его, по просьбе ведуньи Высокий Холм, стоящей к югу от Келий Смерти."}}
D[11678] = {"Поиски Торчащего Рога",{"Найти выносливого гонца Торчащего Рога в Талрамасе."}}
D[11679] = {"Воссоздание ключа",{"По поручению Донатана поговорите с Сурристразом на Янтарной гряде."}}
D[11680] = {"Полетаем?",{"Отдайте ключ Салранд военному магу Анзиму, когда будете готовы освободить Эванор."}}
D[11681] = {"Спасение Эванор",{"Отправляйтесь с боевыми магами и освободите леди Эванор из Бериллового лагеря по просьбе Анзима с Янтарной гряды. Затем явитесь к ней в башню магов на Янтарной гряде."}}
D[11682] = {"Беседа с драконом",{"Поговорите с Сурристразом по приказу леди Эванор с Янтарной гряды."}}
D[11683] = {"Упавший некрополь",{"Уничтожьте 20 созданий Плети любого вида в Талрамасе и Гнойных прудах. Затем возвращайтесь к ведунье Высокий Холм, находящейся к югу от Келий Смерти."}}
D[11684] = {"Исследование воронок",{"По просьбе Великого Отца Махана, находящегося в деревне Таунка'ле, отметьте на карте Поля гейзеров Южную воронку, Северо-западную воронку и Северо-восточную воронку."}}
D[11685] = {"Сердце стихий",{"Принесите 5 сердец элементалей укротителю ветра Баре в деревне Таунка'ле."}}
D[11686] = {"Фермы Песни Войны",{"Разведать положение дел в Амбаре Песни Войны, на ферме Торпа и на скотобойне Песни Войны по просьбе тенелова Икориса с заставы у ферм Песни Войны."}}
D[11687] = {"Доктор и Лич-Лорд",{"Убейте доктора Щербохмыла и Лич-Лорда Хладолюта. Затем вернитесь к ведунье Высокий Холм, которая ждет вас к югу от Келий Смерти."}}
D[11688] = {"Проклятые грязные свиньи",{"По просьбе фермера Торпа с заставы у ферм Песни Войны убейте 10 неживых кабанов."}}
D[11689] = {"Вестник печали",{"Поговорите с Великой Матерью Тайгой в деревне Таунка'ле."}}
D[11690] = {"Верни их живыми!",{"Спасите 8 зараженных кодо по просьбе фермера Торпа с Заставы у ферм Песни Войны."}}
D[11691] = {"Призовите Ахуна",{"Принесите тотем магмы Служителей Земли к Камню Льда."}}
D[11692] = {"В поисках Бикси",{"Как и просил вас Мордл Шестеренок, отправляйтесь на поиски Бикси Винтодер к югу от Келий Смерти."}}
D[11693] = {"Только не чумной магнатавр!",{"Убейте 10 чумных магнатавров и возвращайтесь к Бикси Винтодер к югу от Келий Смерти."}}
D[11694] = {"В пещерах что-то происходит...",{"По просьбе Бикси Винтодер, что прячется к югу от Келий Смерти, всыпьте лечебный порошок Бикси в чумной котел в Кельях Смерти, чтобы нейтрализовать отвар в нем."}}
D[11695] = {"Рог неистовства стихий",{"Добудьте нижнюю половину рога и верхнюю половину рога у вождя Бурблгубля и вождя Гурглбугля и принесите их укротителю ветра Баре в деревне Таунка'ле."}}
D[11696] = {"Ахун явился!",{"Найдите Луму Матерь Небес в Узилище."}}
D[11697] = {"Тинки в некрополе!",{"Отыщите Тинки Свистопляс внутри Талрамаса."}}
D[11698] = {"Может, проще уничтожить Плеть?",{"Уничтожьте 20 воинов Плети любого рода в Талрамасе и Гнойных прудах. Потом вернитесь к Бикси Винтодер к югу от Келий Смерти."}}
D[11699] = {"Я застряла в проклятой клетке… но ненадолго!",{"Найдите кристалл энергетического ядра, магический гироскоп и направляющий камень Плети и отдайте их Тинки Свистопляс в Талрамасе."}}
D[11700] = {"Сообщение для Бикси",{"Поговорите с Бикси Винтодер, находящейся рядом с Кельями Смерти, к югу от них."}}
D[11701] = {"Возвращение к взлетной полосе",{"Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня в Борейской тундре."}}
D[11702] = {"Король Мргл-Мргл",{"Поговорите с королем Мрглом-Мрглом в Приюте Зимних Плавников."}}
D[11703] = {"Добраться до Гетри",{"Найдите тенелова Гетри у ферм Песни Войны."}}
D[11704] = {"Король Мргл-Мргл",{"Поговорите с королем Мрглом-Мрглом у Приюта Зимних Плавников."}}
D[11705] = {"Бесполезные старания",{"Помогите Гетри одолеть Варидуса Свежевателя у ферм Песни Войны.","","Если вам это удастся, явитесь к Гаррошу Адскому Крику."}}
D[11706] = {"Обрушение",{"Обрушьте нерубские воронки с помощью рога неистовства стихий и уничтожьте лорда Криксиса по просьбе укротителя ветра Бары из деревни Таунка'ле."}}
D[11707] = {"Просьба о помощи",{"Поговорите с Выкрутенем Разгоняйло на взлетной полосе Выкрутеня."}}
D[11708] = {"Мехагномы",{"Выслушайте рассказ Выкрутеня Разгоняйло и найдите на взлетной полосе Выкрутеня Джинки Гайковорот."}}
D[11709] = {"Поручение Нока Кровавое Бешенство",{"Поговорите со стражем-смотрителем Ноком Кровавое Бешенство из Крепости Песни Войны в Борейской тундре."}}
D[11710] = {"Что такое с передачником?",{"Соберите 15 запасных деталей Выкрутеня и доставьте их Мордлу Шестеренку на взлетную полосу Выкрутеня."}}
D[11711] = {"Доставка дезертиров: 30 минут, или вы не платите!",{"Отведите дезертира Альянса к перекрестку восточнее крепости Песни Войны и выстрелите из сигнального ружья Песни Войны, чтобы дать сигнал представителям Альянса.","","Доложитесь разведчику Тунгоку, когда успешно доставите дезертира Альянса по месту назначения."}}
D[11712] = {"Перепроклятие",{"Используйте перепроклинальную передачниковую инъекцию на 6 мехагномах со станции Выкрутеня по просьбе Джинки Гайковорот со взлетной полосы Выкрутеня."}}
D[11713] = {"Исследование воронок",{"Отметьте на карте Поля гейзеров расположение Южной воронки, Северо-западной воронки и Северо-восточной воронки по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня."}}
D[11714] = {"Дератизация",{"По просьбе разведчика Тунгока на равнинах Кровавых Спор в Борейской тундре убейте 8 жнецов, 5 поджигателей и 2 обжарщика из стаи Кровавых Спор."}}
D[11715] = {"В поисках топлива",{"Соберите 8 баррелей нефти в портативный нефтесборник по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня."}}
D[11716] = {"Удивительный кровоспор",{"Добудьте 10 кровоспоровых плодолистиков по просьбе волшебницы крови Лаурит с равнин Кровавых Спор в Борейской тундре."}}
D[11717] = {"Быстродействующая пыльца",{"Принесите волшебнице крови Лаурит на равнины Кровавых Спор 5 щепоток пыльцы кровоспоровых мотыльков."}}
D[11718] = {"Автомат в мамонтовой шкуре",{"Принесите Абнеру Шипокруту на взлетную полосу Выкрутеня 6 толстых шкур мамонта."}}
D[11719] = {"Подопытное животное",{"По просьбе волшебницы крови Лаурит, находящейся на Равнинах Кровавых Спор в Борейской тундре, используйте опыленный цветок кровоспора и позвольте ей изучить полученные результаты."}}
D[11720] = {"Вторжение в Гаммот",{"Поговорите со старцем Крутым Рогом на равнинах Кровавых Спор в Борейской тундре."}}
D[11721] = {"Гаммотра Мучитель",{"Убейте Гаммотру и вернитесь с головой Гаммотры к старцу Крутому Рогу на равнинах Кровавых Спор в Борейской тундре."}}
D[11722] = {"Трофеи из Гаммота",{"Отнесите голову Гаммотры Гаррошу Адскому Крику в крепость Песни Войны."}}
D[11723] = {"Запустить Страх-и-ужас",{"Используйте Страх-и-ужас 5000, чтобы обрушить нерубские туннели и уничтожить лорда Криксикса по просьбе Абнера Шипокрута со взлетной полосы Выкрутеня."}}
D[11724] = {"Для гигантского омлета?",{"Отнесите массивное светящееся яйцо волшебнице крови Лаурит на равнины Кровавых Спор в Борейской тундре."}}
D[11725] = {"Поиски пилота \"Штопора\"",{"Отыщите Игги \"Штопора\" Шестероверта на Поле Гейзеров"}}
D[11726] = {"Добавить специй по вкусу...",{"По просьбе Игги \"Штопора\" Шестероверта, что стоит возле Жгучих прудов, соберите 4 мешочка с горлокскими специями."}}
D[11727] = {"Время героев",{"Доложитесь сержанту Молотогору в крепости Отваги."}}
D[11728] = {"Собаки-каки",{"Принесите 8 кусков микропленки Игги \"Штопору\" Шестероверту у Жгучих прудов."}}
D[11729] = {"Ультразвуковая отвертка",{"Принесите ультразвуковую отвертку Умейке Шестеркрут на взлетную полосу Выкрутеня."}}
D[11730] = {"Хозяин и слуга",{"Используйте ультразвуковую отвертку, чтобы перепрограммировать 15 роботов, затем вернитесь к Умейке Шестеркрут на взлетной полосе Выкрутеня.","","Не забудьте обыскать убитых роботов прежде, чем перепрограммировать их."}}
D[11731] = {"Жонглирование факелами",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11732] = {"Осквернение огня"}
D[11733] = {"Переход через расселину",{"Отправляйтесь в Хладарру по распоряжению Сурристраза. Оказавшись там, поговорите с верховным магом Беринардом."}}
