D[11864] = {"Вступление"}
D[11865] = {"Им рано умирать",{"Используйте охапку искусственных шкур, чтобы поймать в ловушки 8 звероловов Эрнестуэя по просьбе Зазы из лагеря Д.Э.Г.О.Ж. в Борейской тундре."}}
D[11866] = {"Уши мертвых врагов",{"Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду."}}
D[11867] = {"Коллекция ушей",{"Принесите верховному друиду Латориусу из лагеря Д.Э.Г.О.Ж. в Борейской тундре 15 ушей прихвостней Эрнестуэя и получите награду."}}
D[11868] = {"Сортировщица грядет!",{"По заданию Заза из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Карину Сортировщицу."}}
D[11869] = {"Судьба моллюсков",{"По заданию иерофанта Сениуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте 10 загребущих ныряльщиков."}}
D[11870] = {"Покинутый предел",{"Найдите иерофанта Лиандру в Покинутом пределе."}}
D[11871] = {"Пока мы на страже",{"Добудьте 12 партий частей тел животных по просьбе иерофанта Лиандры из Покинутого предела в Борейской тундре."}}
D[11872] = {"Гнусный специалист по моллюскам",{"Убейте специалиста по моллюскам К и возвращайтесь к иерофанту Сениус в лагерь Д.Э.Г.О.Ж."}}
D[11873] = {"Новости для Выкрутеня",{"Вернитесь на взлетную полосу Выкрутеня и поговорите с Выкрутенем Разгоняйло."}}
D[11874] = {"Upper Deck Promo – Верховая ракета"}
D[11875] = {"Обретение преимущества",{"Принесите 8 горстей пыли Пустоты эмиссару Мордину в Шаттрат."}}
D[11876] = {"Помоги тем, кто не может помочь себе сам",{"По заданию верховного друида Латориуса в лагере Д.Э.Г.О.Ж. в Борейской тундре освободите 8 мамонтят с помощью уничтожителя ловушек Д.Э.Г.О.Ж."}}
D[11877] = {"План нападения клана Ярости Солнца",{"Лорд Торвос из Шаттрата хочет, чтобы вы захватили планы нападения клана Ярости Солнца."}}
D[11878] = {"Ку'нок обо всем позаботится!",{"Отведите мамонтенока-сиротку к Ку'ноку Чудовищу в Борейской тундре."}}
D[11879] = {"Кау Гроза Мамонтов",{"Убейте Кау Грозу Мамонтов и добудьте боевую алебарду Кау. Доставьте ее верховному друиду Латориусу в лагерь Д.Э.Г.О.Ж. в Борейской тундре."}}
D[11880] = {"Мультифазовый подход",{"Предвестник Харонем из Шаттрата просит вас при помощи мультифазовых спектрографических очков 6 раз провести считывание мультифазовых данных."}}
D[11881] = {"Ценный груз",{"Помогите ослице Дженни добраться с места крушения к Феззиксу Штукельверту в деревню Таунка'ле, не растеряв груз."}}
D[11882] = {"Игра с огнем",{"Поговорите с мастером-огнеглотателем в любой из столиц Альянса."}}
D[11883] = {"Танцы с огнем?",{"Поговорите с мастером огненного танца в любой из столиц Орды."}}
D[11884] = {"Нед, \"Повелитель люторогов\"",{"По заданию Киллинджера Смотрителя Логова из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Недара, \"Повелителя люторогов\", и его спутника, люторога по кличке \"Закуска\"."}}
D[11885] = {"Кровные враги",{"Найдите груды черепов в середине кругов призыва Скеттиса. С помощью 10 свитков затерянных во времени призовите каждого потомка Скеттиса, уничтожьте их и отнесите трофеи Хаззику в лагерь Черного Ветра."}}
D[11886] = {"Необычная активность",{"Отправляйтесь в новый лагерь культа Сумеречного Молота к югу от входа в Непроглядную Пучину на Зорамском взморье, что в Ясеневом лесу, и добудьте сумеречную корреспонденцию, затем при помощи тотема-маяка свяжитесь с проводником из Служителей Земли."}}
D[11887] = {"Неприкосновенный запас",{"Соберите 7 гномских ремонтных наборов с тел погибших пилотов-разведчиков со станции Выкрутеня и принесите их Феззиксу Штукельверту в деревню Таунка'ле."}}
D[11888] = {"Поездка в деревню Таунка'ле",{"Поговорите с ведуном земли и неба в деревне Таунка'ле."}}
D[11889] = {"Смерть с небес",{"По поручению сержанта Молотогора убейте вне стен крепости Отваги 6 порабощенных Плетью изрыгателей огня с помощью укрепленной сети."}}
D[11890] = {"Что там с ними?",{"Исследуйте область вокруг насосной станции Выкрутеня, а затем возвращайтесь к ведуну земли и неба в деревню Таунка'ле."}}
D[11891] = {"Невинный маскарад",{"При помощи сферы Краба проникните в новый Сумеречный лагерь к западу от входа в Непроглядную Пучину на Зорамском взморье в Ясеневом лесу, затем вызовите проводника из Служителей Земли при помощи тотема-маяка."}}
D[11892] = {"Убить Гарольда Лейна!",{"По поручению верховного друида Латориуса из лагеря Д.Э.Г.О.Ж. в Борейской тундре убейте Гарольда Лейна."}}
D[11893] = {"Сила стихий",{"Дорейн Морозное Копыто из деревни Таунка'ле просит вас использовать тотем духа ветра, чтобы собрать энергию 10 паровых яростней."}}
D[11894] = {"Заплатки",{"Принесите 5 пропаренных шкур Феззиксу Штукельверту в деревню Таунка'ле."}}
D[11895] = {"Одолеть бурю",{"Одолейте порыв шторма, затем возвращайтесь к ведуну земли и неба в деревне Таунка'ле."}}
D[11896] = {"Уязвимы для молний",{"Уничтожьте 15 любых роботов, кроме механогномов, ослабленных воздействием ярости шторма, в области прудов вокруг насосной станции Выкрутеня.","","После этого вернитесь к ведуну земли и неба в деревне Таунка'ле."}}
D[11897] = {"Заткнуть воронки!",{"По поручению сержанта Молотогора используйте зажигательную взрывчатку, чтобы взорвать и обвалить воронки к юго-западу и северо-западу от крепости Отваги."}}
D[11898] = {"Прорыв",{"Одолейте принца Валанара с его подручными, Вантрином Безжалостным и Лютионом Злобным, потом явитесь к вождю Зимней Стуже в деревне Таунка'ле."}}
D[11899] = {"Души распроклятых",{"Используйте ловца душ Великой Матери, чтобы захватить души 10 мехагномов со станции Выкрутеня. Затем вернитесь к Великой Матери Тайге в деревне Таунка'ле."}}
D[11900] = {"Что показывают приборы?",{"По просьбе верховного мага Беринанда из лагеря под Маскировочным щитом соберите показания его приборов в Хладарре."}}
D[11901] = {"Военные? Какие военные?",{"По просьбе Джеральда Грина из Далечья отправляйтесь на север, в шахту, и выясните, что случилось с направленным туда воинским подразделением."}}
D[11902] = {"Ужасное свидетельство",{"Возвращайтесь в Далечье к Джеральду Грину."}}
D[11903] = {"Время действовать!",{"По просьбе Джеральда Грина из Далечья убейте 14 чумных падальщиков."}}
D[11904] = {"Плоды трудов наших",{"Отправляйтесь на шахту Далечья, добудьте ключ от повозки у капитана Якобса и используйте его для того, чтобы пустить повозку с рудой. По завершении задания вернитесь к Джеральду Грину в Далечье."}}
D[11905] = {"Оттянуть неотвратимое",{"Используйте восстановитель измерений вблизи разлома в Нексусе по просьбе верховного мага Беринарда из лагеря под Маскировочным щитом."}}
D[11906] = {"Очищение прудов",{"Соберите 15 запасных деталей Выкрутеня и доставьте их Стальным Глазам в деревню Таунка'ле."}}
D[11907] = {"Подручные Механозода",{"Уничтожьте Шатунишку, ЕД-210, Макса Шмякса и Шлифовальщика, затем вернитесь к Ведуну земли и неба в деревню Таунка'ле."}}
D[11908] = {"Справочные материалы",{"По просьбе Иеремии Хоунинга вынесите книгу \"Поля, заводы и мастерские\" из горящего здания рядом с рудником Далечья."}}
D[11909] = {"Убить механизатора!",{"Изучите Руководство механизатора и принесите голову Механозода Великой матери Тайге в деревню Таунка'ле."}}
D[11910] = {"Тайны Древних",{"По просьбе верховного мага Беринарда из-под Маскировочного щита принесите 3 ледяных осколка и 3 щепки зачарованного древа, собранных с древ в Хладарре."}}
D[11911] = {"Преображение",{"По заданию верховного мага Беринанда из лагеря под Маскировочным щитом отправьтесь в Нексус и соберите 5 магических обломков кристаллических заступников."}}
D[11912] = {"На подножном корму",{"Соберите 10 ягод снежевики с кустов снежевики в Хладарре по просьбе библиотекаря Серры из лагеря под Маскировочным щитом."}}
D[11913] = {"Надо действовать наверняка",{"По просьбе Венди Даррен сожгите 8 мешков с зерном Далечья, воспользовавшись факелом Венди."}}
D[11914] = {"Сохранение секретности",{"По просьбе библиотекаря Серры убейте волшебных змеев и принесите за Маскировочный щит 5 субстанций маны Нексуса."}}
D[11915] = {"Игра с огнем",{"Поговорите с пламеглотателем-виртуозом в любой из столиц Орды."}}
D[11916] = {"Воин Адского Крика",{"Отыщите вождя Зимнюю Стужу в деревне Таунка'ле."}}
D[11917] = {"Ответный удар"}
D[11918] = {"Первое знакомство",{"Убейте 10 чароплетов Хладарры по просьбе Релораза из лагеря под Маскировочным щитом."}}
D[11919] = {"Охота на драконов",{"По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите Релоразу копье назад за Маскировочный щит."}}
D[11920] = {"Сектанты среди нас",{"Поговорите с капитаном \"Левшой\" Люггером на \"Рассекателе туч\" в Крепости Отваги."}}
D[11921] = {"Опять бросаем факелы",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11922] = {"Жонглирование факелами",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11923] = {"Поймай факел!",{"Поймайте подряд 4 факела, затем поговорите с пламеглотателем-виртуозом."}}
D[11924] = {"Опять жонглирование факелами",{"Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом."}}
D[11925] = {"Опять жонглирование факелами",{"Поймайте 10 факелов подряд, затем поговорите с пламеглотателем-виртуозом."}}
D[11926] = {"Опять бросаем факелы",{"Выиграйте игру в бросание факелов, затем поговорите с пламеглотателем-виртуозом."}}
D[11927] = {"Встреча в трактире",{"Найдите Лериссу в таверне в крепости Отваги."}}
D[11928] = {"Далечье",{"Отправляйтесь в Далечье в Борейской Тундре и поговорите с Джеральдом Грином."}}
D[11929] = {"Гибель деревни Таунка'ле",{"Поговорите с матерью Тауранук у ворот деревни Таунка'ле."}}
D[11930] = {"Через Трансборею",{"Проводите эвакуированных жителей Таунка'ле через Трансборею на границу Драконьего Погоста, где их ждет Вартук Дитя Льда."}}
D[11931] = {"Взломать шифр",{"Добудьте Лазурный кодекс у инквизитора Калераса и 3 мерцающих руны у его чародеев Хладарры и отнесите Релоразу за Маскировочный щит."}}
D[11932] = {"Дураки и трусы",{"Поговорить с Атаикой в Каскале, к северо-востоку от крепости Отваги."}}
D[11933] = {"Похищение пламени Экзодара",{"Верните Пламя Экзодара Праздничному сказителю."}}
D[11935] = {"Похищение пламени Луносвета",{"Верните пламя Луносвета хранителю мудрости Праздника."}}
D[11936] = {"Наклевывается план!",{"Убейте драконидов из Хладарры и используйте их застывшие топоры, чтобы разбить 5 яиц синих драконов по просьбе Релораза из лагеря под Маскировочным щитом."}}
D[11937] = {"УКАЗАТЕЛЬ – все факелы возвращены, задание выполнено"}
D[11938] = {"Отвлечь противника",{"Подстройте 20 несчастных случаев, в которых пострадает Плеть в Храмовом городе Эн'кила, по просьбе Тассариана из Стонущего зиккурата в Борейской тундре. Используйте кости Лурида, если вам понадобится помощь."}}
D[11939] = {"?????"}
D[11940] = {"Охота на драконов",{"По просьбе Релораза используйте копье с окровавленным наконечником, чтобы подчинить детеныша дракона Нексуса, а затем принесите ему копье за Маскировочный щит."}}
D[11941] = {"Загадочный обломок",{"Принесите искрометный обломок Релоразу за Маскировочный щит."}}
D[11942] = {"Слова могущества",{"По поручению Тассариана, который находится у Стонущего зиккурата, отправляйтесь в храмовый город Эн'кила и раздобудьте свиток верховного жреца Талет-Ха в Шпиле Боли, свиток верховного жреца Наферсета – в Шпиле Порчи и свиток верховного жреца Андората – в Шпиле Крови."}}
D[11943] = {"Магическая клетка",{"Добудьте тюремную обшивку у генерала Церулеана и энергетическое ядро у завоевателя Кровозмея по просьбе Релораза из лагеря под Маскировочным щитом."}}
D[11944] = {"В окружении!",{"По заданию капрала Венна убейте 7 защитников зиккурата."}}
D[11945] = {"Подготовка к самому худшему",{"По просьбе Утайка соберите в Каскале 8 ящиков припасов Каскала."}}
D[11946] = {"Керистраза",{"Поговорите с Керистразой, когда будете готовы к встрече с Малигосом.","","Если потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита."}}
D[11947] = {"Ответный удар"}
D[11948] = {"Ответный удар"}
D[11949] = {"Не сдаваться без боя!",{"По просьбе Атаики убейте 12 налетчиков из племени Квалдир в Каскале."}}
D[11950] = {"Мудрость Муахита",{"Найдите в Каскале старейшину Муахита."}}
D[11951] = {"Приманка",{"Соберите в Хладарре 10 осколков кристаллизованной маны по просьбе Керистразы.","","Если потеряете свою магическую клетку, поговорите с Релоразом у Маскировочного щита."}}
D[11952] = {"Ответный удар"}
D[11953] = {"Ответный удар",{"Убейте лейтенанта Хладноглыба, помощника Ахуна, вызвав его при помощи Камня Льда в Сумеречной пещере в северном Силитусе, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11954] = {"Ответный удар",{"Убейте ледяного храмовника, помощника Ахуна, вызвав его при помощи камня льда к Темному порталу на полуострове Адского Пламени, затем вернитесь к старейшине Служителей Земли в столицу."}}
D[11955] = {"Ахун, Повелитель Холода",{"Отправляйтесь в Узилище в резервуар Кривого Клыка, что в Зангартопи, и поговорите с Нумой Сестрой Облаков."}}
D[11956] = {"Поиски талисмана",{"Отправляйтесь на Стоянку Смерти и скачите на Сумраке к месту, где находится талисман Танатала. Добудьте его и принесите Тассариану в Стонущий зиккурат."}}
D[11957] = {"Смерть Сарагосе!",{"По просьбе Керистразы используйте средоточие магии для привлечения внимания Сарагосы, а затем сразитесь с ней."}}
D[11958] = {"Чтоб ничего не пропало!",{"Отберите у волчеров 6 украденных припасов Моа'ки. Верните их старейшине Ко'нани в Гавани Моа'ки."}}
D[11959] = {"Убить Логуна!",{"Намажьтесь кровью Логуна и возвращайтесь к старейшине Ко'нани в гавань Моа'ки."}}
D[11960] = {"Планы на будущее",{"Соберите 12 щенков Поляны Снегопада. Принесите их зверолову Мау'и в гавани Моа'ки."}}
D[11961] = {"Духи присматривают за нами",{"Найдите тело Ирука в воде, заберите тотем Иссилрука и принесите старейшине Муахиту в бухту Дыхания Ньорда."}}
D[11962] = {"Последняя партия",{"Доставьте ящик руды из Далечья Хильде Каменной Кузне в крепость Отваги."}}
D[11963] = {"Оружие для Далечья",{"Вернитесь к Джеральду Грину в Далечье."}}
D[11964] = {"Благовония для летних пламеней",{"Хранитель мудрости Праздника хочет, чтобы вы отнесли благовония Лета летнему пламеню к любому поселению Альянса."}}
D[11965] = {"К оружию!",{"Войдите в здание ратуши в Далечье и позвоните в колокол, находящийся в этом здании."}}
D[11966] = {"Благовония для праздничных сполохов",{"Праздничный сказитель хочет, чтобы вы отнесли благовония Лета праздничному сполоху к любому поселению Орды."}}
D[11967] = {"Сбор красных драконов",{"Отведите Керистразу к Релоразу к Маскировочному щиту."}}
D[11968] = {"Поворот колеса Фортуны",{"По просьбе старейшины Муахита убейте Хейгарра Душегуба в бухте Дыхания Ньорда."}}
D[11969] = {"Сработавший капкан",{"Используйте сигнальный огонь Релораза у северо-западного входа в Нексус по просьбе Релораза."}}
D[11970] = {"Хранитель мудрости праздника Середины Лета",{"Поговорите с Хранителем мудрости Празднества в любой из столиц Альянса."}}
D[11971] = {"Сказитель Летнего праздника",{"Поговорите с праздничным сказителем в любой из столиц Орды."}}
D[11972] = {"Осколки Ахуна",{"Принесите ледяные осколки Луме Матери Небес."}}
D[11973] = {"Пленница",{"По просьбе Релораза из лагеря под Маскировочным щитом отправьтесь в Нексус и освободите Керистразу."}}
D[11975] = {"Когда я вырасту...",{"Отведите свою подопечную, сиротку Саландрию, посмотреть на группу \"Вожди тауренов\" в Луносвет на Путь Старейшин. Обязательно позовите Саландрию, если по прибытии ее не окажется рядом."}}
D[11976] = {"Ледяные осколки",{"Принесите ледяные осколки Луме Матери Небес."}}
D[11977] = {"Таурен среди таунка",{"Поищите эмиссара Светлое Копыто в лагере беженцев Западного Ветра."}}
D[11978] = {"Добро пожаловать в Орду",{"По просьбе эмиссара Светлое Копыто из лагеря беженцев Западного Ветра на Драконьем Погосте добудьте 10 ящиков с ордынским оружием."}}
D[11979] = {"Таунка и таурены",{"Отыщите эмиссара Светлое Копыто в лагере беженцев Западного Ветра."}}
D[11980] = {"Гордость Орды",{"Убейте 15 ануб'арских душителей по просьбе кровавого стража Рох'килла из лагеря беженцев Западного Ветра в Драконьем Погосте."}}
D[11981] = {"Найди Куруна!",{"Поговорите с Куруном, который стоит на холме, возвышающимся над Тор Моданом."}}
D[11982] = {"Каменный дождь",{"Курун, стоящий на холме, рядом с Тор Моданом, просит вас помешать железным дворфам, сбросив в котлован Тор Модана несколько булыжников."}}
D[11983] = {"Клятва крови Орды",{"Поговорите с таунка в лагере беженцев Западного Ветра и примите у пятерых из них клятву верности Орде.","","Верните клятву крови Орды эмиссару Светлое Копыто, когда выполните задание."}}
D[11984] = {"Захлопнуть клетку",{"Самир из Гранитных ключей просит вас запереть в клетку охотника оглушенного Баддом ледяного тролля."}}
D[11985] = {"Битва в Проломе",{"Курун, стоящий на холме, возвышающемся над Тор Моданом, просит вас убить железного тана Аргрума."}}
D[11986] = {"Потрепанный дневник",{"Разыщите 8 недостающих страниц, вклейте их в дневник и принесите его Тортену Глубокопу в Лагерь дружины Западного Края."}}
D[11988] = {"Рунический краеугольный камень",{"Принесите 5 фрагментов рунического краеугольного камня Тортену Глубокопу в Лагерь дружины Западного Края."}}
D[11989] = {"Перемирие?",{"Дракуру из Гранитных ключей просит вас скрепить перемирие кровью, поцарапав свою руку тупым резаком, лежащим возле его клетки."}}
D[11990] = {"Пузырек видений",{"Дракуру из Гранитных ключей просит вас принести ему укрепленную колбу, сплетение водорослей и три листа туманнолистника."}}
D[11991] = {"Требуется расшифровка",{"Дракуру просит вас добыть 5 застывших настоев у Драккари, обитающих среди Руин Драк'Зина, и затем выпить эликсир возле жаровни Дракуру."}}
D[11993] = {"Рунические пророчества",{"Тортен Глубокоп из Лагеря дружины Западного Края просит вас расшифровать три рунических диска."}}
D[11994] = {"Juno's Flag Tester"}
D[11995] = {"Безотлагательное путешествие в Покой Звезд",{"Поговорите с проекцией верховного мага Модеры в Покое Звезд."}}
D[11996] = {"Безотлагательное путешествие в Молот Агмара",{"Поговорите с проекцией верховного мага Этаса Похитителя Солнца в Молоте Агмара."}}
D[11997] = {"REUSE",{"Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края."}}
D[11998] = {"Подсластить пилюлю",{"Принесите Бругару Гравировщику из Лагеря дружины Западного Края бочку старого доброго самогона."}}
D[11999] = {"Обшарить трупы",{"Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара."}}
D[12000] = {"Обшарить трупы",{"Найдите планы в Садах Лунного Покоя и вернитесь с ними к проекции верховного мага Модеры в Покое Звезд."}}
D[12002] = {"Братья по оружию",{"Убейте 10 рунических боевых големов и вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края."}}
D[12003] = {"В поисках туннелей",{"Бругар Гравировщик из Лагеря дружины Западного Края просит вас осмотреть северное, восточное и южное строения в Тор Модане."}}
D[12004] = {"Предотвратить союз",{"Принесите проекции верховного мага Модеры в Покой Звезд останки торговца Ветром Му'фа и чешую Горамоша."}}
D[12005] = {"Предотвратить союз",{"Доставьте останки Му'фы Торговца Ветром и чешую Горамоша к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара."}}
D[12006] = {"Месть за бесчинства!",{"Убейте охотников на магов с Драконьего Погоста, ловчих из Садов Лунного Покоя, колдунов Волноловов и волшебников средоточия, общим числом 15, после чего возвращайтесь к Этениалу Тени Луны в Сады Лунного Покоя."}}
D[12007] = {"Необходимые жертвы",{"Дракуру просит принести ему Око пророка к жаровне в Зеб'Халаке.","","Чтобы эликсир Дракуру сработал на пьедестале, вам придется добыть настой Зим'бо."}}
D[12008] = {"Молот Агмара",{"Отправляйтесь в Молот Агмара на Драконьем Погосте и поговорите с командиром Агмаром."}}
D[12009] = {"Крабовые ловушки Туа'кеа",{"Соберите 8 ловушек Туа'кеа для крабов и принесите их ему в гавань Моа'ки."}}
D[12010] = {"Что случилось с Орлондом?",{"Найдите геодезиста Орлонда в Тор Модане."}}
D[12011] = {"Признаки большой проблемы",{"Сообщите рыбаку Туа'кеа о разрушенной ловушке на крабов."}}
D[12012] = {"Сообщи старейшинам",{"Отправляйтесь в столицу и поговорите со старейшиной Служителей Земли."}}
D[12013] = {"Покончить с Арканимусом!",{"Уничтожьте Арканимуса и вернитесь к Этениалу Тени Луны в сады Лунного Покоя."}}
D[12014] = {"Крепкий как камень?",{"Верните портативный сейсмограф и сделайте последний замер колебаний в Тор Модане, после чего вернитесь к Бругару Гравировщику в Лагерь дружины Западного Края."}}
D[12015] = {"Тестовое задание для Крейга",{"Принесите 5 незнамо чего Крейгу Амай незнамо куда."}}
D[12016] = {"Наживка",{"Добудьте мясо матриарха по прозвищу \"Огромные Клешни\" и принесите его Туа'кеа в гавань Моа'ки."}}
D[12017] = {"Наживка на крючке",{"Убейте Ту'у'гвара, а затем вернитесь к Туа'кеа в гавань Моа'ки."}}
D[12019] = {"Последние ритуалы",{"Отправьтесь в Храмовый город Эн'кила и отыщите сферу телепортации под парящей цитаделью Наксанар. Используйте сферу, чтобы попасть на вершину цитадели и помочь Тассариану."}}
D[12020] = {"Однажды, напившись в...",{"Поговорите с Бокси Болтокрутом в лагере Хмельного фестиваля."}}
D[12021] = {"Письмо домой",{"Доставьте письмо домой к леди Алистре на восточные Поля Падальщиков."}}
D[12022] = {"Пей до дна!",{"Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Бокси Болтокрутом."}}
D[12023] = {"Сладость мести"}
D[12026] = {"Порванный журнал",{"Разыщите 8 недостающих страниц, вклейте их в дневник и верните его Ведунье Палуне в Лагерь Уанква."}}
D[12027] = {"Удивительное приключение мистера Ушастика",{"Помогите Эмили и мистеру Ушастику вернуться в Лагерь дружины Западного Края, после чего поговорите с оруженосцем Волтером."}}
D[12028] = {"Духовное озарение",{"Поговорите с Тоалу'у Мистиком после того, как пройдете обряд поиска видений."}}
D[12029] = {"Пылающая Плеть",{"Мак с Гранитных ключей просит вас поджечь 20 голодающих троллей Плети с помощью его грога."}}
D[12030] = {"Старейшина Мана'лоа",{"Поговорите со статуей старейшины Мана'лоа в деревне Инду'ле."}}
D[12031] = {"Свобода перемещения",{"Успокойте рыбаков, мистиков и воинов из деревни Инду'ле (общим числом 15 противников), а затем вернитесь к старейшине Мана'лоа в деревню Инду'ле."}}
D[12032] = {"Разговор с бездной",{"Обратитесь к Жемчужине Бездны и выполните распоряжения морской богини Оача'ноа.","","Если вы переживете все испытания, вернитесь к Тоалу'у Мистику в гавани Моа'ки."}}
D[12033] = {"Послание с запада",{"Прочитайте письмо от Саурфанга и уничтожьте его.","","Выполнив это, поговорите с посланником Торвусом."}}
D[12034] = {"Победа близка…",{"Поговорите с главным сержантом Юктоком в Молоте Агмара."}}
D[12035] = {"Переналадка технологии",{"По поручению Иеремии Хоунинга обезвредьте 5 сборщиков урожая, а затем воспользуйтесь инструментами Иеремии, чтобы перемонтировать их."}}
D[12036] = {"Глубины Азжол-Неруба",{"Исследуйте Провал Наржуна и возвращайтесь с данными к главному сержанту Юктоку, ожидающему у Молота Агмара."}}
D[12037] = {"Спасательная операция",{"Мак из Гранитных ключей просит вас отправиться в Драк'Тарон и узнать, все ли в порядке с Курцель."}}
D[12038] = {"Пылающая Плеть",{"Мак из Гранитных ключей просит вас поджечь 30 голодающих троллей Плети с помощью его грога."}}
D[12039] = {"Черная кровь Йогг-Сарона",{"Принесите Борусу Железные Клещи из Молота Агмара на Драконьем Погосте 10 образцов черной крови Йогг-Сарона."}}
D[12040] = {"Общий враг в лице Артаса",{"По заданию Киликса Разрушителя у Провала Наржуна на Драконьем Погосте убейте 6 ануб'арских владык подземелий."}}
D[12041] = {"Потерянная империя",{"Доставьте боевые планы Киликса командиру Агмару в Молот Агмара на востоке."}}
D[12042] = {"Сердце древних",{"Дракуру просит вас отправиться в самую верхнюю комнату Лесозаготовок Синего Неба и найти Сердце древних."}}
D[12043] = {"Защита Лагеря Соплозабилось",{"Убейте 12 землекопов пустошей и одного надсмотрщика пустошей на раскопках, окружающих Покой Галакронда. Вернитесь к Нарфу в Лагерь Соплозабилось, когда задание будет выполнено."}}
D[12044] = {"Припасти руды",{"Соберите 8 пригоршней композитной руды на раскопках, окружающих Покой Галакронда и принесите их Зинку в Лагерь Соплозабилось."}}
D[12045] = {"Битый лед",{"Соберите 4 горсти осколков льда от ледяных элементалей на севере и принесите их Живликс в Лагерь Соплозабилось."}}
D[12046] = {"Мягкая оболочка",{"Соберите 12 тонких шкур животных, убив нужное количество туннельных йормунгаров или глодателей драконьих костей близ Лагеря Соплозабилось. Добыв шкуры, вернитесь с ними к Живликс."}}
D[12047] = {"Нечто тугоплавкое",{"Найдите среди драконьих костей к востоку от лагеря Соплозабилось 12 расколотых костей."}}
D[12048] = {"Доспехи воинов Плети",{"Принесите 8 элементов доспехов воинов Плети Борусу Железные Клещи из Молота Агмара."}}
D[12049] = {"Мясо с пылу с жару",{"К востоку от Лагеря Соплозабилось сразитесь с огромным йормунгаром – до тех пор, пока тот не откроет рот. Затем бросьте ему в глотку мощную взрывчатку. После взрыва соберите 6 кусков обугленного мяса йормунгара с земли и принесите их Зинку."}}
D[12050] = {"Лесорубы",{"Используйте пульт управления Крошшером Зинка, чтобы вызвать Крошшер, когда доберетесь до гнездовья гарпий на севере. Соберите 50 связок бревен и возвращайтесь к Зинку в Лагерь Соплозабилось.","","Если потеряете пульт управления Крошшером Зинка, поговорите с Зинком в Лагере Соплозабилось, чтобы получить новый."}}
D[12051] = {"Выдирание перьев",{"По просьбе Нарфа из лагеря Соплозабилось убейте 20 гарпий к северо-западу от Лагеря Соплозабилось."}}
D[12052] = {"Смерть гарпиям!",{"Убейте госпожу Морозной выси и 15 гарпий Морозной выси в горах к северо-западу от лагеря Соплозабилось. Когда задание будет выполнено, возвращайтесь к Нарфу.","","Если вам понадобится пульт управления крошшером Зинка, обратитесь к Зинку в Лагерь Соплозабилось."}}
D[12053] = {"Мощь Орды",{"Установите боевой штандарт клана Песни Войны в деревне Ледяной Пыли и защитите его от нападающих.","","Затем верните боевой штандарт клана Песни Войны главному сержанту Юктоку в Молот Агмара на Драконьем Погосте."}}
D[12054] = {"Расшифровать записи",{"Принесите пучок дыхания духа ведунье Палуне в Лагерь Уанква."}}
D[12055] = {"Странное приспособление",{"Отнесите странное устройство Горамоша проекции верховного мага Модеры в Покой Звезд."}}
D[12056] = {"Приговорен к смерти: верховный сектант Зангус",{"Убейте верховного сектанта Зангуса и отнесите его голову капитану Горту в Молот Агмара на Драконьем Погосте."}}
D[12057] = {"Сшитый плотью фолиант",{"Доставьте сшитый плотью фолиант капитану Горту в Молот Агмара."}}
D[12058] = {"Рунические пророчества",{"Ведунья Палуна из Лагеря Уанква просит вас перевести надписи на трех Рунических дисках."}}
D[12059] = {"Странное приспособление",{"Отнесите странное устройство Горамоша проекции верховного мага Этаса Похитителю Солнца в Молот Агмара."}}
D[12060] = {"Проекты и проекции",{"Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.","","После этого возвращайтесь с полученной информацией к проекции верховного мага Модеры в Покой Звезд."}}
D[12061] = {"Проекты и проекции",{"Подберитесь поближе и обследуйте конструкцию на вершине волнолова, плавающего в воздухе над Садами Лунного Покоя.","","После этого возвращайтесь с полученной информацией к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара"}}
D[12062] = {"Оскорбить Корена Худовара",{"Поговорите с Кореном Худоваром."}}
D[12063] = {"Сила Ледяной Пыли",{"Найдите Бантока Ледяную Пыль в окрестностях деревни Ледяной Пыли."}}
D[12064] = {"Ануб'арские оковы",{"Принесите Бантоку Ледяной Пыли, ожидающему у деревни Ледяной Пыли на Драконьем Погосте, фрагмент ключа Анок'ры, фрагмент ключа Тивакса и фрагмент ключа Синока."}}
D[12065] = {"Фокусы на взморье",{"Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.","","Затем вернитесь к проекции верховного мага Модеры в Покое Звезд."}}
D[12066] = {"Фокусы на взморье",{"Добудьте кольцо управления средоточием силовых линий и воспользуйтесь им для получения информации о средоточии силовых линий на Сверкающем взморье.","","Затем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара."}}
D[12067] = {"Письмо домой",{"Доставьте письмо капитана Малин командиру Сайе Лазурной Стали в Покой Звезд."}}
D[12068] = {"Голоса прошлого",{"Дракуру просит вас собрать скрижали Драккари в Руинах Дракил'джин и отобрать 5 священных настоев у оракулов и заступников Драккари. Затем вам надо будет выпить эликсир Дракуру возле жаровни в руинах, чтобы призвать его дух."}}
D[12069] = {"Возвращение верховного вождя",{"Освободите верховного вождя Ледяную Пыль с помощью ключа от ануб'арской темницы и помогите ему одолеть короля подземелий Ануб'ет'кана.","","Добудьте кусок панциря Ануб'ет'кана и вернитесь с ним к командиру Агмару в Молоте Агмара в Драконьем Погосте."}}
D[12070] = {"Второе дыхание",{"Воспользуйтесь осколком земли, чтобы излечить великанов с Седых холмов, сражающихся в Каменистых холмах, убейте всех железных дворфов, что осмелятся встать у вас на пути, и вернитесь к Куруну на холм, возвышающийся над Тор Моданом."}}
D[12071] = {"Ударим с воздуха!",{"Поговорите с Вальноком Ветрояром в Молоте Агмара."}}
D[12072] = {"Будь прокляты эти чумные звери!",{"С помощью сигнального ружья Вальнока вызовите в деревню Ледяной Пыли кор'кронскую боевую виверну. Воспользовавшись ею, убейте 25 ануб'арских гнилостных зверей!","","Если выполните задание, возвращайтесь к Вальноку Ветрояру в Молот Агмара."}}
D[12073] = {"Куй железо, пока горячо",{"Убейте 10 любых железных дворфов, охраняющих Тор Модан, после чего доложите разведчику Вор'такху из Лагеря Уанква об успешном выполнении его поручения."}}
D[12074] = {"Удобный союзник",{"Поговорите с Куруном, который стоит на вершине холма рядом с Тор Моданом."}}
D[12075] = {"Образец каменной плоти",{"Возьмите образец каменной плоти с тела ледяного великана у входа в пещеру в ущелье Порочных Кристаллов, к северу от места, где стоит Зорт. Выполнив это задание, вернитесь к Зорту, ожидающему вас у центра каньона."}}
D[12076] = {"Грязное дело",{"Соберите два фиала едкой слюны йормунгаров с помощью скребка. Выполнив задачу, принесите сосуды Зорту в ущелье Порочных Кристаллов."}}
D[12077] = {"Употреблять дважды в день",{"Предложите приготовленный Зортом эликсир Ко'чару Неуязвимому."}}
D[12078] = {"Червячный наездник",{"Отправляйтесь в пещеры в ущелье Порочных кристаллов и заманите 3 порождения йормунгаров в крепкие ящики. Не забудьте собрать ящики, когда порождения йормунгаров окажутся в них!","","Принесите пойманные порождения йормунгаров Зорту в ущелье Порочных кристаллов."}}
D[12079] = {"Излюбленное место червяков",{"Отправляйтесь в пещеру у северной оконечности ущелья Порочных кристаллов и убейте по поручению Ко'чара Неуязвимого 8 йормунгаров-трутней Ледяного Сердца."}}
D[12080] = {"Вот это червяк!",{"Войдите в пещеру Ледяного Сердца и убейте Грохотунью. Не забудьте использовать защитный эликсир Зорта, чтобы спастись от едких плевков йормунгаров – если, конечно, этот эликсир у вас еще есть.","","Выполнив задачу, вернитесь к Ко'чару Неуязвимому в ущелье Порочных кристаллов."}}
D[12081] = {"Гаврок",{"Поговорите с Гавроком в Руинах Тетиса."}}
D[12082] = {"Дун-да-Дун-та!",{"Сопроводите Харрисона по пути из руин Дракил'джин, после чего поговорите с Харкором в лагере Харкора."}}
D[12083] = {"В лесах",{"Добудьте амулет управления средоточием силовых линий и используйте его для получения сведений о средоточии силовых линий в Лоталорском редколесье.","","После этого вернитесь к проекции верховного мага Модеры в Покое Звезд."}}
D[12084] = {"В лесах",{"Добудьте амулет управления средоточием силовых линий и воспользуйтесь им для получения сведений от средоточия силовых линий в Лоталорском редколесье.","","Затем вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молот Агмара."}}
D[12085] = {"Письмо домой",{"Отнесите письмо лейтенанта Та'зинни командиру Агмару в Молот Агмара."}}
D[12086] = {"Сын Каркута",{"Идите на восток к Стоянке Смерти, находящейся сразу за Уну'пе."}}
D[12087] = {"Немного помочь? DEPRECATED",{"Убейте 8 защитников зиккурата по просьбе капрала Венна со Стоянки Смерти."}}
D[12088] = {"Тассариан, рыцарь Смерти",{"Отыщите Тассариана внутри Стонущего зиккурата, к северу от Стоянки Смерти."}}
D[12089] = {"Разыскивается: магистр Кельдонус!",{"Убейте магистра Кельдонуса и вернитесь к капитану Горту в Молот Агмара в Драконьем Погосте."}}
D[12090] = {"Разыскивается: Гигантавр",{"Убейте Гигантавра и приходите за вознаграждением к капитану Горту в Молоте Агмара на Драконьем Погосте."}}
D[12091] = {"Разыскивается: Коготь Ужаса",{"Убейте Когтя Ужаса и вернитесь за вознаграждением к капитану Горту в Молот Агмара на Драконьем Погосте."}}
D[12092] = {"Усиление древняков",{"Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к Сарендриане в Покой Звезд."}}
D[12093] = {"Руны порабощения",{"Гаврок с Руин Тетиса просит вас отключить четыре руны порабощения, убив надзирателя Дюрваля, надзирателя Коргана, надзирателя Лочли и надзирателя Брунона."}}
D[12094] = {"Спящая сила",{"Зарядите осколок Гаврока у первого, второго и третьего древних камней, после чего вернитесь к Гавроку в Руины Тетиса."}}
D[12095] = {"В Драконью Погибель",{"Поговорите с Рокханом в Драконьей Погибели в Драконьем Погосте."}}
D[12096] = {"Усиление древняков",{"Воспользуйтесь корой древня для усиления 3 древ Лоталора, а затем вернитесь к хранителю земли Грифу в Молот Агмара."}}
D[12097] = {"Сарастра, бич Севера",{"Поговорите с Рокханом, чтобы призвать ледяного змея Сарастру.","","Убейте змея и отнесите ледяное сердце Сарастры капитану Горту в Молот Агмара."}}
D[12098] = {"Поиски в деревне Инду'ле",{"Найдите командира охотников на магов в деревне Инду'ле либо на озере Инду'ле."}}
D[12099] = {"Долгожданная свобода",{"Воспользуйтесь Руноломом Гаврока, чтобы освободить четырех рунических великанов, после чего вернитесь к Гавроку в Руины Тетиса."}}
D[12100] = {"Сдерживание гнили",{"По заданию Соара Ярости Ястреба из Молота Агмара на Драконьем Погосте убейте 15 зараженных тварей и добудьте орган сопротивления гниению."}}
D[12101] = {"Добрый доктор...",{"Отнесите орган сопротивления гниению доктору Синтару Злобениусу в Молот Агмара."}}
D[12102] = {"В поисках рубиновой сирени",{"Принесите 1 цветок рубиновой сирени доктору Синтару Злобениусу в Молот Агмара на Драконьем Погосте."}}
D[12104] = {"Вакцина для Соара",{"Отнесите вакцину Синтара Соару Ярости Ястреба в Молот Агмара."}}
D[12105] = {"Погружение во мрак",{"Отнесите дневник Михаила лейтенанту Думонту в Приют Янтарной Сосны."}}
D[12106] = {"Поиски в деревне Инду'ле",{"Поищите командующего силами охотников на магов в деревне Инду'ле и озере Инду'ле."}}
D[12107] = {"Конец цепочки",{"Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий под озером Инду'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.","","После этого вернитесь к проекции верховного мага Модеры в Покое Звезд."}}
D[12108] = {"ИСКЛЮЧЕНО",{"Принесите дневник Михаила картограферу Тобиасу в Приют Янтарной Сосны."}}
D[12109] = {"И снова к Гриану Камнегриву...",{"Поговорите с капитаном Грианом Камнегривом в Лагере дружины Западного Края."}}
D[12110] = {"Конец цепочки",{"Используйте талисман управления средоточием силовых линий, чтобы получить сведения о средоточии силовых линий на дне озера Инду'ле. Затем отправляйтесь на восток, к Лазуритовому святилищу драконов, расположенному почти в центре южного Драконьего Погоста, и с западного уступа понаблюдайте за тем, что там происходит.","","После этого вернитесь к проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара."}}
D[12111] = {"Где бродят дикие звери",{"Используйте суму с вакцинами, чтобы привить 5 снегопадных лосей и 5 полярных гризли по просьбе Соара Ярости Ястреба из Молота Агмара в Драконьем Погосте."}}
D[12112] = {"Деловые отношения",{"Найдите Зорта в центре ущелья порочных кристаллов, к северо-востоку от Лагеря Соплозабилось."}}
D[12113] = {"Здравствуй, мяско!",{"Харкор из Лагеря Харкора просит вас принести 10 кусков жилистого мяса ворга, которые можно добыть, поохотившись на хищников Ночного Воя, и 10 стейков из черпоклыка. Их можно вырезать из туш травоядных веслорогов."}}
D[12114] = {"Анти-стрессовая терапия",{"Харкор из Лагеря Харкора просит вас убить 10 заступников Драккари и 10 оракулов Драккари возле Руин Дракил'джин."}}
D[12115] = {"Кольтира и язык смерти",{"Отнесите сшитый плотью фолиант Кольтире Ткачу Смерти."}}
D[12116] = {"Только смелым покоряются...",{"Краз из Лагеря Харкора просит вас войти в Руины Дракил'джина и собрать 5 каноп Драккари."}}
D[12117] = {"Путешествие в гавань Моа'ки",{"Отправляйтесь в гавань Моа'ки на Драконий Погост и поговорите со старейшиной Ко'нани."}}
D[12118] = {"Путешествие в гавань Моа'ки",{"Отправляйтесь в гавань Моа'ки на Драконий Погост и поговорите со старейшиной Ко'нани."}}
D[12119] = {"Добиться аудиенции",{"Вручите свое приглашение Тариолстразу в храме Драконьего Покоя."}}
D[12120] = {"Молот Драк'агуула",{"Краз из Лагеря Харкора просит вас убить Драк'агуула возле Руин Дракил'джин и принести ему Дракил'джинский молот."}}
D[12121] = {"Увидимся в другом мире",{"Краз из Лагеря Харкора просит вас ударить Дракил'джинским молотом в гонги, окружающие Руины Дракил'джин. После этого вас, скорее всего, убьют, и тогда вы сможете войти в руины, чтобы поговорить с Ган'джо из мира мертвых."}}
D[12122] = {"Добиться аудиенции",{"Вручите свое приглашение в храм Драконьего Покоя Тариолстразу в храме Драконьего Покоя."}}
D[12123] = {"Информация для королевы",{"Вручите свое приглашение Алекстразе Хранительнице Жизни в храме Драконьего Покоя."}}
D[12124] = {"Информация для королевы",{"Вручите свое приглашение в храм Драконьего Покоя Алекстразе Хранительнице Жизни в храме Драконьего Покоя."}}
D[12125] = {"Ради крови",{"По просьбе Кольтиры Ткача Смерти воздействуйте кровавым самоцветом на спятившего селянина Инду'ле, а затем возвращайтесь к Кольтире в Молот Агмара на Драконьем Погосте с наполненным кровавым самоцветом."}}
D[12126] = {"На службе нечестивости",{"Используйте нечестивый самоцвет против герцога Валленхола и вернитесь с наполненным нечестивым самоцветом к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост."}}
D[12127] = {"На службе у мороза",{"Используйте ледяной самоцвет против загробников льда и вернитесь к Кольтире Ткачу Смерти в Молот Агмара на Драконий Погост с наполненным ледяным самоцветом."}}
D[12128] = {"Как дела у Регара?",{"Поговорите с Регаром Бровебоем в Лагере горняков."}}
D[12129] = {"Безукоризненный замысел",{"Принесите полный набор чертежей боевого голема Регару Бровебою в Лагерь горняков."}}
D[12130] = {"Зачем ковать то, что можно отобрать?",{"Принесите 8 частей боевого голема Регару Бровебою в Лагерь горняков."}}
D[12131] = {"Нам нужна энергия",{"Принесите энергобатареи Дурара и Каторна Регару Бровебою в Лагерь горняков."}}
D[12132] = {"Сила разрушения",{"По просьбе Кольтиры Ткача Смерти из Молота Агмара, что на Драконьем Погосте, войдите в мир теней и сразите 6 мрачных мучителей.","","Если вам нужно будет еще раз войти в мир теней, обратитесь к Кольтире."}}
D[12133] = {"Разбей тыкву!",{"Отдайте опаленный священный символ переодетой попечительнице сирот."}}
D[12134] = {"Саша выходит на охоту",{"Саша просит вас убить 12 охотников солнцестояния в Деревне Солнцестояния."}}
D[12135] = {"\"И гори все огнем!\"",{"Переодетая попечительница сирот просит вас помочь потушить пожар в деревне, если ее подожжет Всадник без головы. Когда пожар будет потушен, снова поговорите с попечительницей сирот."}}
D[12136] = {"Переведенная книга",{"Доставьте переведенный сшитый плотью фолиант капитану Горту в Молот Агмара."}}
D[12137] = {"Остынь, чудо!",{"Ган'джо просит вас собрать снег вечного сна из его сундука в руинах Дракил'джин.","","Им надо окропить древних духов Драккари и отнести крупицы духов Драккари Кразу в Лагерь Харкора."}}
D[12138] = {"... а может быть, и нет",{"Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к Регару Бровебою в Лагерь горняков."}}
D[12139] = {"\"И гори все огнем!\"",{"Попечительница сирот в маске просит вас помочь потушить пожар в деревне. Когда пожар потухнет, снова поговорите с попечительницей сирот в маске в городе."}}
D[12140] = {"Славься, Роанук!",{"Найдите Роанука Ледяную Пыль в Молоте Агмара, примите его в лоно Орды и посвятите его в вожди сил Орды.","","Когда ритуал будет завершен, вернитесь к командиру Агмару с клятвой крови Орды."}}
D[12141] = {"Дипломатическое поручение",{"Поговорите с Каруком на берегу Терзающего Бича, к юго-западу от крепости Отваги."}}
D[12142] = {"Контроль над чумой",{"По заданию Дуана с передовой 7-го легиона убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, окружающих Драконий Покой."}}
D[12143] = {"Преследование в каньоне",{"Дуан просит вас идти по следу снобольдов по каньону к северо-востоку от передовой 7-го легиона и разобраться с их вожаком."}}
D[12144] = {"Заразу – под контроль!",{"Убейте 10 снобольдов Снежных равнин и 3 магнатавров Драконьего Погоста в лагерях магнатавров, расположенных к юго-востоку от Драконьего Покоя. Выполнив задачу, вернитесь к Контоканису в Драконьей Погибели в северо-западных Драконьих пустошах."}}
D[12145] = {"Преследование в каньоне",{"По поручению Контоканиса преследуйте снобольдов по каньону к югу от Драконьего Зова и разберитесь с их вожаком."}}
D[12146] = {"Зловещие выводы",{"Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто захотел бы оценить исходящую от него угрозу."}}
D[12147] = {"Зловещие выводы",{"Отнесите расписанный боевой рог к Драконьему Покою и найдите того, кто заинтересовался бы возможностью оценить потенциальную угрозу."}}
D[12148] = {"Единственный в своем роде",{"Найдите и убейте Расщепителя Костей в каньоне (или рядом с ним), находящемся к северо-западу от Лазуритового святилища драконов. Принесите найденное вами свидетельство Аурастразе в храм Драконьего Покоя."}}
D[12149] = {"Могучие магнатавры",{"Выследите и убейте Кровавого Пира, Ледоскала и Дракрова к востоку от Драконьего Покоя.","","Кровавый Пир обитает в юго-восточном углу Драконьих Пустошей, прямо к северу от изумрудного святилища драконов. Ледоскал патрулирует северную оконечность Зеркала Рассвета. Дракров бродит у подножья утесов к западу от бронзового святилища драконов.","","Когда все три магнатавра будут убиты, возвращайтесь к Аурастразе в Драконий Покой."}}
D[12150] = {"Мастер рун-затворник",{"Отыщите Дрегмара Рунического Знака неподалеку от его пещеры, на тропе, ведущей в утесы над Зеркалом Рассвета. Бросьте ему вызов и любой ценой узнайте имя повелителя магнатавров. Добыв нужные сведения, вернитесь к Аурастразе в Драконьем Покое."}}
D[12151] = {"Распоясавшийся полководец",{"Отправляйтесь к кругу факелов к югу от лазуритового святилища драконов и протрубите в расписанный боевой рог. Сразите Гром'тара Громовержца и принесите его голову Аурастразе в Драконий Покой."}}
D[12152] = {"Погибель Джин'аррака",{"Краз из Лагеря Харкора просит вас найти cвященное подношение Драккари в руинах Дракил'джина и осенить его пылью духов Драккари. После этого положите подношение к гонгам у руин Дракил'джина."}}
D[12153] = {"Тан и его Наковальня",{"Воспользовавшись боевым големом, убейте тана Гневного Топора, после чего вернитесь к Регару Бровебою в Лагерь горняков."}}
D[12154] = {"Затмение",{"Воспользуйтесь взрывчаткой Регара, чтобы уничтожить руническое силовое ядро в Дун Арголе. Доложите о своем успехе Регару Бровебою из Лагеря горняков."}}
D[12155] = {"Разбей тыкву!",{"Отдайте опаленный священный символ попечительнице сирот в маске."}}
D[12156] = {"DEPRECAED",{"Сопроводите посланца Альянса в Среброречье. Выполнив это задание, вернитесь к лейтенанту Думонту в Приют Янтарной Сосны."}}
D[12157] = {"Пропавший курьер",{"Поговорите с курьером Лансоном в Покое Звезд, что в Драконьем Погосте."}}
D[12158] = {"Рудник Полого Камня",{"Обыщите Рудник Полого Камня к северо-западу от Лагеря дружины Западного Края."}}
D[12159] = {"Неупокоенные души",{"Петров с Рудника Полого Камня просит вас поджечь с помощью шахтерского фонаря трупы 8 шахтеров с Рудника Полого Камня."}}
D[12160] = {"Имя из прошлого",{"Вернитесь к капитану Гриану Камнегриву в Лагерь дружины Западного Края."}}
D[12161] = {"Рууна Слепая",{"Поговорите с Рууной Слепой, которая живет в Лагере Рууны рядом с Перевалом Фордрассил."}}
D[12162] = {"Деревня Солнцестояния"}
D[12163] = {"The Evil Below"}
D[12164] = {"Час ворга",{"Саша из Торговой лавки Белой Сосны посылает вас на Остров Кровавой Луны убить Селаас, Варлама, Вспоробрюха и Тень Аругала."}}
D[12165] = {"Коварный план",{"Принесите полный комплект чертежей боевого голема геологу Рокару в Лагерь Уанква."}}
D[12166] = {"Жидкое пламя Элуны",{"По просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд воспользуйтесь жидким пламенем Элуны для очищения трупов 6 гнилостных маралов и 6 бешеных гризли."}}
D[12167] = {"Убить сектантов",{"Соберите 5 рабочих костюмов сектантов по просьбе стража-смотрителя Джоди Песни Луны из Покоя Звезд."}}
D[12168] = {"Памятный дар Зангуса",{"Принесите памятный дар Зангуса стражу-смотрителю Джоди Песни Луны в Покой Звезд."}}
D[12169] = {"Верховный сектант",{"По заданию Стража-смотрителя Джоди Песни Луны из Покоя Звезд убейте верховного сектанта Зангуса."}}
D[12170] = {"Схватка в Черноречье",{"Капитан налетчиков Кронн просит вас убить 10 представителей или игроков Альянса на Лесопилке Черноречья."}}
D[12171] = {"О предателях и предательстве",{"Покажите депешу Альянса Палене Серебряное Облако в Покое Звезд."}}
D[12172] = {"Настройка на Даларан",{"По заданию проекции верховного мага Модеры в Покое Звезд настройтесь на силовые линии Нордскола."}}
D[12173] = {"Настройка на Даларан",{"По заданию проекции верховного мага Этаса Похитителя Солнца в Молоте Агмара настройтесь на силовые линии Нордскола."}}
D[12174] = {"Главнокомандующий Халфорд Змеевержец",{"Доставьте депешу Альянса главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в восточной части Драконьего Погоста."}}
D[12175] = {"Серые шкуры воргов",{"Торговец шкурами Джун'ик из Крепости Завоевателей просит вас добыть 3 серые шкуры ворга с серо-дымчатых охотников, которые водятся в лесах на севере."}}
D[12176] = {"Мелкая подмена",{"Торговец шкурами Джун'ик просит вас принести ему 6 шкур медведей гризли."}}
D[12177] = {"Уловка Джун'ика",{"Принесите кусок угля и пять горстей простой муки торговцу шкурами Джун'ику в Крепость Завоевателей в Седых холмах."}}
D[12178] = {"Сверток для Кренны",{"Отнесите связку шкур Кренне в Крепость Завоевателей."}}
D[12179] = {"Specialization 1 [PH]",{"LOG: Complete this quest for Specialization 1."}}
D[12180] = {"Пленные геологи",{"Освободите геолога Ганна, геолога Торгана и геолога Варана, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков."}}
D[12181] = {"Имя для заразы",{"Покажите образец гнили Тобиасу Саркхоффу в Ядозлоби."}}
D[12182] = {"В Ядозлобь!",{"Передайте образец гнили Главному распространителю чумы Миддлтону, который живет в Ядозлоби на востоке Драконьего Погоста."}}
D[12183] = {"Часть маскировки",{"Принесите униформу надзирателя горному пехотинцу Килиану в Лагерь горняков."}}
D[12184] = {"Улыбайтесь, вас снимают!",{"С помощью камеры Килиана сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к горному пехотинцу Килиану в Лагерь горняков."}}
D[12185] = {"Лучшая маскировка для Локена",{"Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его горному пехотинцу Килиану в Лагерь горняков."}}
D[12186] = {"УКАЗАТЕЛЬ: Победитель"}
D[12187] = {"УКАЗАТЕЛЬ: Участник"}
D[12188] = {"Гниль Отрекшихся и вы: как не заразиться самим",{"Принесите главному распространителю чумы Миддлтону из Ядозлоби в Драконьем Погосте 10 образцов эктоплазменного осадка."}}
D[12189] = {"Меня окружают идиоты!",{"Отправляйтесь в Ядозлобь в Драконьем Погосте и поговорите с главным распространителем чумы Миддлтоном."}}
D[12190] = {"Поздоровайся с моим маленьким другом",{"Пригмон просит вас отнести ингредиенты для Харкора в Лагерь Харкора."}}
D[12191] = {"Пей до дна!",{"Попадите кружкой с бесплатным пивом в С.С.М. 5 раз, затем поговорите с Биззлем Эхпрокачуном."}}
D[12192] = {"Однажды, напившись в...",{"Поговорите с Биззлем Эхпрокачуном в лагере Хмельного фестиваля."}}
D[12193] = {"А не будет ли сувенирчика в нынешнем году?",{"Найдите в лагере Хмельного фестиваля Белби Быстросмен, отдайте ей купон и получите бесплатную праздничную пивную кружку."}}
D[12194] = {"А не будет ли сувенирчика в нынешнем году?",{"Найдите в лагере Хмельного фестиваля Бликса Чиништукса, отдайте ему купон и получите бесплатную праздничную пивную кружку."}}
D[12195] = {"Незваный гость",{"Принесите 5 рогов взрослых оленей Тормаку Бывалому из Лагеря Уанква."}}
D[12196] = {"С самого начала",{"Принесите 8 частей боевого голема геологу Рокару в Лагерь Уанква."}}
D[12197] = {"Нам нужна энергия",{"Принесите энергобатареи Дурара и Каторна Геологу Рокару в Лагерь Уанква."}}
D[12198] = {"... а может быть, и нет",{"Подзарядите вашего Боевого голема от десяти грозовых караульных и вернитесь к геологу Рокару в Лагерь Уанква."}}
D[12199] = {"Свержение железного тана",{"Воспользовавшись особой функцией вашего Боевого голема, убейте железного тана Гневного Топора, после чего вернитесь к Тормаку Бывалому в Лагерь Уанква."}}
D[12200] = {"Слезы изумрудного дракона",{"Принесите 8 слез изумрудного дракона главному распространителю чумы Миддлтону в Ядозлобь в Драконьем Погосте."}}
D[12201] = {"Тень надзирателя",{"Принесите униформу надзирателя Разведчику Вор'такху в Лагерь Уанква."}}
D[12202] = {"Улыбайтесь, вас снимают!",{"С помощью камеры Рокара сделайте снимки 8 железных дворфов в Дун Арголе, после чего вернитесь к Разведчик Вор'такху в Лагерь Уанква."}}
D[12203] = {"Приказы Локена",{"Замаскируйтесь под железного надзирателя рун, перехватите послание от Локена и передайте его разведчику Вор'такху в Лагерь Уанква."}}
D[12204] = {"Во имя Локена",{"Поговорите с Хью Глассом и Гавроком о Локене, после чего передайте полученные сведения разведчику Вор'такху из Лагеря Уанква."}}
D[12205] = {"Разыскивается: Алый Натиск",{"Убейте 20 членов Алого Натиска и доложите об этом верховному палачу Росу из Ядозлоби."}}
D[12206] = {"Испорченные последние ритуалы",{"По просьбе аптекаря Вики Левин из Ядозлоби испробуйте настой порчи на узнике Алого Натиска."}}
D[12207] = {"Падение Фордрассила",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться к Ветвям Фордрассила, Сердцу Фордрассила или Слезам Фордрассила и принести ей 6 образцов слизи энтропических слизнюков."}}
D[12208] = {"Удачи в охоте за троллями!",{"Сержант Туркин отправил вас к Самиру в Гранитные ключи."}}
D[12209] = {"Кража материальных ценностей",{"По заданию интенданта Бартлетта из Ядозлоби похитьте 8 доспехов Алого Натиска и 8 единиц оружия Алого Натиска."}}
D[12210] = {"Сезон охоты на троллей!",{"Лейтенант Думонт из Приюта Янтарной Сосны послал вас поговорить с Самиром в Гранитных ключах."}}
D[12211] = {"Не дадим им подняться!",{"По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь ее клеткой с крысами в Новом Дольном Очаге, чтобы ободрать дочиста 15 тел, принадлежащих Алому Натиску."}}
D[12212] = {"Пополнение запасов",{"Старший лесник Андорхол из Приюта Янтарной Сосны просит вас убить несколько высокорогих оленей и принести ему 8 кусков сочной оленины."}}
D[12213] = {"Подземная тьма",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии."}}
D[12214] = {"Новые кони",{"Украдите 3 боевых коней Алого Натиска и доставьте их Ханзелу Бауэру в Ядозлобь. Передайте Ханзелу поводья из рук в руки."}}
D[12215] = {"Мы или они!",{"Андерхол из Приюта Янтарной Сосны просит вас найти и убить 6 серо-дымчатых охотников в Седых холмах."}}
D[12216] = {"Бери самое нежное!",{"Андерхол из Приюта Янтарной Сосны просит вас добыть 8 боков медведей гризли, которые водятся в Седых холмах."}}
D[12217] = {"Орлиный взор",{"Андерхол из Приюта Янтарной Сосны просит вас убить 5 императорских орлов и доложить ему о выполнении задания."}}
D[12218] = {"Добрые вести не ждут на месте",{"Используйте чумную бомбу распространителя гнили Отрекшихся, чтобы уничтожить 30 голодающих покойников на краю Полей Падальщиков по приказу главного распространителя чумы Миддлтона из Ядозлоби в Драконьем Погосте."}}
D[12219] = {"Обломки мирового древа",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Ветви Фордрассила, Сердце Фордрассила или Слезы Фордрассила и принести ей 6 образцов слизи энтропических слизнюков."}}
D[12220] = {"Темное влияние",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас отыскать Сердце Фордрассила, Слезы Фордрассила и Ветви Фордрассила, углубиться под землю и воспользоваться Геомантской сферой для измерения уровня энергии."}}
D[12221] = {"Гниль Отрекшихся",{"Доставьте образец гнили Отрекшихся доктору Синтару Злобениусу в Молот Агмара."}}
D[12222] = {"Тайны прядильщиц пламени",{"Принесите 3 огнепрочных талисмана плотнику Дрейку в Приют Янтарной Сосны."}}
D[12223] = {"Ослабление врага",{"Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к плотнику Дрейку в Приют Янтарной Сосны."}}
D[12224] = {"Авангард кор'крона",{"Явитесь к Саурфангу Младшему в авангард кор'крона."}}
D[12225] = {"М-м-м... Янтарные желуди!",{"Поговорите с искусным резчиком по дереву Андерхолом в Приюте Янтарной Сосны."}}
D[12226] = {"Ух, пронесло!",{"Андерхол из Приюта Янтарной Сосны просит вас принести ему 5 стеблей чернокорня."}}
D[12227] = {"За дело!",{"Андерхол из Приюта Янтарной Сосны просит вас взять слабительную настойку Андерхола и воспользоваться ближайшим туалетом, чтобы извлечь частично переваренные янтарные желуди."}}
D[12228] = {"Возвращение магии [PH]"}
D[12229] = {"Возможная связь",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас принести 8 образцов крови безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка."}}
D[12230] = {"Кража у осадных мастеров",{"По поручению Стража смерти Молдера из Ядозлоби раздобудьте 6 осадных бомб."}}
D[12231] = {"Отпрыски медвежьего бога",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца."}}
D[12232] = {"Бомбардировка баллист",{"По заданию Стража смерти Молдера из Ядозлоби уничтожьте 5 баллист Нового Дольного Очага с помощью осадных бомб."}}
D[12233] = {"[Depricated]Высадить семена"}
D[12234] = {"Надо знать",{"Украдите текущие приказы Алого Натиска в аббатстве, в казармах и на побережье по просьбе госпожи шпионов Репины из Ядозлоби."}}
D[12235] = {"Наксрамас и падение крепости Стражей Зимы",{"Поговорите с командиром грифонов Уриком на грифоньей площадке в крепости Стражей Зимы."}}
D[12236] = {"Урсок, медвежий бог",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила."}}
D[12237] = {"Полет защитника Стражей Зимы",{"Спасите 10 беспомощных селян Стражей Зимы и возвращайтесь к командиру грифонов Урику в крепость Стражей Зимы."}}
D[12238] = {"Очищение Драк'Тарона",{"Дракуру просит вас выпить эликсир возле его жаровни в Драк'Тароне. Для использования эликсира вам понадобится пять настоев терпения."}}
D[12239] = {"Шпион в Новом Дольном Очаге",{"Доставьте текущие приказы Алого Натиска агенту Скулли в Новый Дольный Очаг."}}
D[12240] = {"Цель и средства",{"Используйте термитов семейки Левин, чтобы выманить штейгера Калейки и убить его по просьбе аптекаря Вики Левин из Ядозлоби."}}
D[12241] = {"Уничтожить саженец",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас взять лиственный факел и сжечь саженец Фордрассила. Принесите пепел Фордрассила Серому Рогу."}}
D[12242] = {"Семена Фордрассила",{"Заклинательница ветра Серый Рог из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила."}}
D[12243] = {"Огонь над водами",{"По заданию аптекаря Вики Левин из Ядозлоби воспользуйтесь Пылающей водой аптекаря, чтобы поджечь паруса \"Глупости Грешника\".","","Пока матросы будут заняты тушением пожара, спуститесь вниз и раздобудьте у капитана лоцию капитана Шели."}}
D[12244] = {"Починка крошшеров",{"Синипус с Лесозаготовок Синего Неба просит вас привезти ему 3 сломанных крошшера."}}
D[12245] = {"Никакой пощады пленникам",{"По поручению главы шпионов Репайн убейте Стража смерти Шнайдера, главного писаря Киннедия, инженера Бурка и канцлера Амай.","","Когда выполните это задание, сообщите об этом верховному палачу Росу в Ядозлобь."}}
D[12246] = {"Возможная связь",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас принести 8 образцов безумных фурболгов, обитающих в Святилище Кровавого Сердца и Святилище Красного Клыка."}}
D[12247] = {"Дети Урсока",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас разыскать Орсонна в Святилище Красного Клыка и Кодиан в Святилище Кровавого Сердца."}}
D[12248] = {"Саженец Фордрассила",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас взять зеленый факел и сжечь саженец Фордрассила. Принесите ей пепел Фордрассила."}}
D[12249] = {"Урсок, медвежий бог",{"Иерофант Тайрин из Приюта Янтарной Сосны просит вас найти Тура Яролапа возле Логова Урcока и победить Урсока с его помощью. Когда Урсок падет, осыпьте его тело очищенным пеплом Фордрассила."}}
D[12250] = {"Семена Фордрассила",{"Иерофант Тайрин из Приюта Янтарной Сосны из Крепости Завоевателей просит вас отправиться в Седую Пасть и принести ей 8 семян Фордрассила."}}
D[12251] = {"Возвращение к верховному главнокомандующему",{"Поговорите с верховным главнокомандующим Халфордом Змеевержцем в крепости Стражей Зимы на Драконьем Погосте."}}
D[12252] = {"Истязание истязателя",{"По поручению верховного палача Роса из Ядозлоби пять раз припечатайте клеймом истязателя Альфонса, чтобы вытянуть из него нужную информацию. Получив ее, убейте Альфонса."}}
D[12253] = {"Спасение с городской площади",{"Спасите 6 пойманных жителей крепости Стражей Зимы по просьбе главнокомандующего Халфорда Змеевержца из крепости Стражей Зимы в Драконьем Погосте."}}
D[12254] = {"Без молитвы – никак",{"По заданию агента Скулли из Нового Дольного Очага раздобудьте молитвенник епископа Стрита."}}
D[12255] = {"Тан Волдруна",{"Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите об успехе плотнику Дрейку из Приюта Янтарной Сосны."}}
D[12256] = {"Тайны огневязов",{"Принесите 3 огнепрочных талисмана сержанту Назгриму в Крепость Завоевателей."}}
D[12257] = {"Демонстрация силы",{"Убейте 12 хускерлов из клана Укротителей драконов и вернитесь к сержанту Назгриму в Крепость Завоевателей."}}
D[12258] = {"Судьба погибших",{"Убейте 15 мстительных упырей по приказу командира Линоры Порыв Ветра в крепости Стражей Зимы в Драконьем Погосте."}}
D[12259] = {"Тан Волдруна",{"Одержите победу над таном Торвальдом Эрикксоном с помощью Огнедышащего и доложите сержанту Назгриму из Крепости Завоевателей."}}
D[12260] = {"Полное несходство",{"По заданию агента Скулли из Нового Дольного Очага похитьте образ жреца-ворона Алого Натиска. После этого верните Волшебное зеркало банши агенту Скалли."}}
D[12261] = {"Отрезать пути к отступлению",{"Поместите тотем уничтожения в конце тропы, ведущей из Обсидианового святилища драконов, там, где дорогу начинает заносить снегом. Защищайте его до полной зарядки, затем вернитесь к Серинару."}}
D[12262] = {"Без надежды на спасение",{"Убейте 6 некролитов Пылающих Глубин и 10 тлеющих скелетов за пределами Обсидианового святилища драконов, после этого вернитесь к Серинару."}}
D[12263] = {"С наилучшими намерениями",{"Дождитесь, пока Серинар замаскирует вас под некролита Пылающих Глубин, потом проникните в глубь Пасти Нелтариона, чтобы узнать, что там делает Культ Проклятых. Вернитесь к Серинару и расскажите о том, что они замышляют."}}
D[12264] = {"Разборка с Проклятыми",{"Убейте 3 некромантов Пылающих Глубин, 6 тлеющих созданий и 6 тлеющих упырей в Пасти Нелтариона, а затем возвращайтесь к Серинару."}}
D[12265] = {"Осквернение осквернителей",{"Найдите и уничтожьте 8 некромантских рун, выявленных на дне Пасти Нелтариона. Выполнив это, возвращайтесь к Серинару."}}
D[12266] = {"Рассказ о разрушении",{"Отправляйтесь обратно в Драконий Покой и расскажите Нэлис, что задание Серинара выполнено."}}
D[12267] = {"Пламя Нелтариона",{"Используйте пламя Нелтариона, чтобы очистить область призыва в глубине Пасти Нелтариона. После того как привлечете внимание Ротина Гниющего, убейте его, затем вернитесь к Серинару у входа в пещеру."}}
D[12268] = {"Запчасти",{"Трубкочист с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и 2 тугих пружины."}}
D[12269] = {"Только не c нашего рудника!",{"По поручению верховного лорде Леорика фон Цельдига из крепости Стражей Зимы на Драконьем Погосте добудьте 10 удостоверений шахтера Стражей Зимы."}}
D[12270] = {"Искрошить Альянс",{"Грекк с Лесозаготовок Синего Неба просит вас добыть для него 3 крошшера."}}
D[12271] = {"Жезл принуждения",{"Отнесите жезл истязателя верховному палачу Росу в Ядозлобь."}}
D[12272] = {"Кровоточащая руда",{"По поручению осадного инженера Полувспыха из крепости Стражей Зимы на Драконьем Погосте добудьте 10 образцов странной руды на руднике Стражей Зимы."}}
D[12273] = {"Отречение",{"По заданию верховного палача Роса из Ядозлоби воздействуйте жезлом принуждения на командира Джордана, главного канонира Зирхата, кузнеца Гудмана и смотрителя стойл Мерсера.","","Когда они подпадут под влияние жезла, убейте каждого из них, вырвав у них перед смертью признание об отречении от Алого Натиска."}}
D[12274] = {"Греховное падение",{"Позвоните в колокол аббатства, затем поговорите с верховным настоятелем по просьбе агента Скулли из Нового Дольного Очага."}}
D[12275] = {"Демогном",{"Поговорите с осадным инженером Полувспыхом в крепости Стражей Зимы в Драконьем Погосте."}}
D[12276] = {"В поисках Слинкина",{"Отыщите Слинкина Демогнома в руднике Стражей Зимы. Используйте самонаводящегося робота Полувспыха, если вам нужна будет помощь в поисках рудника."}}
D[12277] = {"Ничего не оставлять на волю случая",{"Добудьте бомбу Стражей Зимы и используйте ее, чтобы взорвать верхний и нижний стволы рудника Стражей Зимы. Выполнив задачу, вернитесь к осадному инженеру Полувспыху в крепость Стражей Зимы в Драконьем Погосте."}}
D[12278] = {"Клуб \"Пиво месяца\"",{"Отнесите членскую карточку \"Лучшего пивовара месяца\" Ларкину Громовару в таверну \"Горючий камень\" в Стальгорне."}}
D[12279] = {"Медвежий аппетит",{"Принесите 6 северных лососей Хью Глассу в Торговую лавку Красного леса."}}
D[12280] = {"Текущий ремонт",{"Лурц с Лесозаготовок Синего Неба просит вас собрать 4 рифленых шестеренки, 3 зубчатых колеса и две тугих пружины."}}
D[12281] = {"Понимание военной машины Плети",{"Доставьте амуницию Полувспыха главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы."}}
D[12282] = {"Отпечатки былого",{"Принесите Зелигу Иллюзорному из крепости Стражей Зимы в Драконьем Погосте его гадальный шар."}}
D[12283] = {"Правду не скроешь",{"Добудьте дневник верховного генерала Аббендис по просьбе агента Скулли и передайте этот дневник верховному палачу Росу в Ядозлоби."}}
D[12284] = {"Преследуй по пятам",{"Командир Баргок приказал вам убить 15 представителей или игроков Альянса на Лесозаготовках Синего Неба."}}
D[12285] = {"Без головы не возвращайся!",{"По заданию верховного палача Роса из Ядозлоби убейте верховного генерала Аббендис и принесите ему ее голову."}}
D[12286] = {"Кулек конфет"}
D[12287] = {"Орик Чистосердечный и Забытое взморье",{"Ищите помощи у Орика Чистосердечного в Рассветном краю на Драконьем Погосте."}}
D[12288] = {"В военном лазарете",{"Аумана с Лесозаготовок Синего Неба просит вас перевязать медицинским жгутом 10 израненных рыскателей."}}
D[12289] = {"Нападем, пока враг слаб!",{"Сержант Хартсман поручил вам убить 15 игроков или представителей Орды на Лесозаготовках Синего Неба."}}
D[12290] = {"Эликсир из темноплевела",{"Добудьте на Зловещей возвышенности 5 экземпляров темноплевела по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте."}}
D[12291] = {"Забытая повесть",{"Выслушайте повесть о бедствиях забытого крестьянина, забытого ружейника, забытого рыцаря и забытого пехотинца по просьбе Орика Чистосердечного из Рассветного края в Драконьем Погосте."}}
D[12292] = {"Помощь местных жителей",{"Лейтенант Думонт из Приюта Янтарной Сосны поручил вам добраться до Торговой лавки Вечнозеленого леса и забрать кедровый сундук."}}
D[12293] = {"Дело сделано",{"Отнесите кедровый сундук Ивану на Заставу Тополиной рощи."}}
D[12294] = {"Заключение договора",{"Вернитесь к лейтенанту Думонту в Приют Янтарной Сосны."}}
D[12295] = {"Урок дипломатии",{"Поговорите с военным атташе Дюкалем в Среброречье."}}
D[12296] = {"На грани жизни и смерти",{"Реанна с Лесозаготовок Синего Неба просит вас перевязать медицинскими бинтами 10 израненных пехотинцев отряда Западного Края."}}
D[12297] = {"О предателях и предательстве",{"Капитан Адамс попросил вас показать депешу Альянса Гриру Рудомолоту из Крепости Западной Стражи."}}
D[12298] = {"Главнокомандующий Халфорд Змеевержец",{"Отвезите депешу Альянса главнокомандующему Халфорду Змеевержцу в Крепость Стражей Зимы, которая находится на востоке Драконьего Погоста."}}
D[12299] = {"Северное гостеприимство",{"Сергей из Среброречья просит вас убить 8 мародеров из Крепости Завоевателей."}}
D[12300] = {"Испытание смелости",{"Найдите часового Костехвата к северо-западу от Среброречья и пройдите испытание смелости."}}
D[12301] = {"Правда вернет нам свободу",{"По просьбе Орика Чистосердечного из Рассветного края, что на Драконьем Погосте, задействуйте хрустальную сферу Орика в развалинах, расположенных на Забытом взморье, для освобождения обитающих там Забытых."}}
D[12302] = {"Предупреждение",{"Дойдите до северо-западного края Среброречья."}}
D[12303] = {"Финансовое обеспечение военных нужд",{"По заданию интенданта Бартлетта из Ядозлоби добудьте 6 сундучков с забытыми сокровищами."}}
D[12304] = {"Недвижимость на взморье",{"По поручению наблюдателя Хансена, находящегося к северу от Забытого взморья убейте 20 призраков Забытого взморья."}}
D[12305] = {"Прощальные мысли",{"Вернитесь к Зелигу Иллюзорному в крепость Стражей Зимы в Драконьем Погосте."}}
D[12306] = {"Клуб \"Пиво месяца\"",{"Отнесите заполненную членскую карточку \"Лучшего пивовара месяца\" Рай'ме в Пристанище Темнотерна. Оно находится в Оргриммаре, в Аллее Духов."}}
D[12307] = {"Аконитовый корень",{"Катя из Среброречья просит вас выдернуть восемь аконитовых кореньев."}}
D[12308] = {"Побег из Среброречья",{"Откройте деревянную клетку и помогите освобожденному разведчику Альянса сбежать из Среброречья. Когда вы доберетесь до Приюта Янтарной Сосны, доложите лейтенанту Думонту обо всем, что вы видели."}}
D[12309] = {"Найти Дюркона!",{"Отыщите кавалериста Дюркона в склепе Стражей Зимы в Драконьем Погосте."}}
D[12310] = {"Мгновенный ответ",{"Лейтенант Думонт отправил вас к Заставе на опушке убить Владека и 7 охотников Среброречья."}}
D[12311] = {"Подземная обитель некролорда",{"По заданию кавалериста Дюркона из крепости Стражей Зимы убейте некролорда Амариона."}}
D[12312] = {"Тайны Плети",{"Отнесите сшитый плотью фолиант кавалеристу Дюркону, находящемуся в крепости Стражей Зимы на Драконьем Погосте."}}
D[12313] = {"Unused Save Brewfest!",{"Поговорите со шпионом Хмельного фестиваля в \"Угрюмом обжоре\" , что в Глубинах Черной горы."}}
D[12314] = {"Смерть капитану Зорне!",{"Убейте капитана Зорну и вернитесь к барону Фриману в Бухту торговцев."}}
D[12315] = {"Смерть капитану Брайтвотеру!",{"Убейте капитана Брайтвотера и доложите о своей победе генералу Хазгару из Бухты торговцев."}}
D[12316] = {"Припрем их к стенке!",{"Убейте 10 представителей или игроков Орды в Бухте торговцев, после чего вернитесь к лейтенанту Стюарту."}}
D[12317] = {"Припрем их к стенке",{"Убейте 10 представителей или игроков Альянса в Бухте торговцев, после чего вернитесь к центуриону Каггруму."}}
D[12318] = {"Спасем Хмельной фестиваль!",{"Поговорите со шпионом Хмельного фестиваля в таверне \"Угрюмый обжора\" в Глубинах Черной горы."}}
D[12319] = {"Тайна книги",{"Отнесите сшитый плотью фолиант главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы в Драконьем Погосте."}}
D[12320] = {"Язык Смерти",{"Отнесите сшитый плотью фолиант инквизитору Халларду в тюрьме крепости Стражей Зимы."}}
D[12321] = {"Праведная проповедь",{"Дождитесь, пока инквизитор Халлард закончит свою праведную проповедь, и возвращайтесь к главнокомандующему Халфорду Змеевержцу в крепость Стражей Зимы на Драконьем Погосте с добытой информацией."}}
D[12323] = {"Выкурим их!",{"С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения сержанту Дауни."}}
D[12324] = {"Выкурим их!",{"С помощью дымовой шашки выкурите 20 отставших работников Торговой Компании из зданий. Доложите об успешном выполнении поручения Каменному стражу Тотему Ярости."}}
D[12325] = {"Заброс на вражескую территорию",{"Поговорите с командиром грифонов Уриком, чтобы организовать полет на заставу Торсона на Драконьем Погосте. Когда прибудете на заставу, доложитесь герцогу Августу Крушителю Врагов."}}
D[12326] = {"Паровой сюрприз",{"Воспользовавшись паровым танком Альянса, уничтожьте 6 чумных телег и доставьте гвардейцев 7-го легиона к усыпальнице Стражей Зимы. Если успешно выполните задание, поговорите с Амбо Кэшем внутри усыпальницы Стражей Зимы на Драконьем Погосте."}}
D[12327] = {"Опыт вне тела",{"Выпейте зелье из легчайшей пыльцы возле хрустального шара Рууны и узрите видение из прошлого."}}
D[12328] = {"Просьба Рууны",{"Рууна Слепая просит вас принести ей четыре горсти легчайшей пыльцы."}}
D[12329] = {"Судьба и совпадения",{"Поговорите с Сашей в Торговой лавке Белой Сосны."}}
D[12330] = {"Слабое место Анатолия",{"Саша из Торговой лавки Белой Сосны просит вас выстрелить усыпляющим дротиком в Татьяну, жительницу Деревни Солнцестояния. Принесите ее в Торговую лавку Белой Сосны."}}
