D[12789] = {"В Разлом!",{"По распоряжению рыцаря Валуса из Опоры Света доложите о своем прибытии сержанту Рианне из Разлома Света в Зул'Драке."}}
D[12790] = {"Как уйти и вернуться: магический путь",{"Воспользуйтесь кристаллом телепортации на Аметистовую заставу у Даларана и кристаллом телепортации в Даларан по просьбе верховного мага Селиндры из Даларана."}}
D[12791] = {"Магическое королевство Даларан",{"Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана."}}
D[12792] = {"Первым делом",{"По поручению командира Кунца помогите сержанту Рианне в Разломе Света."}}
D[12793] = {"Дым на горизонте",{"По поручению Кхуфу из Зим'Торги переговорите с сержантом Рианной в Разломе Света.","","Маака обеспечит вам безопасное путешествие."}}
D[12794] = {"Магическое королевство Даларан",{"Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана."}}
D[12795] = {"На помощь заставе",{"По поручению Датуры Кровавой Розы поговорите с командиром Фальштавом на Серебряной заставе."}}
D[12796] = {"Магическое королевство Даларан",{"Отнесите кирин-торский перстень верховному магу Селиндре к Аметистовым Вратам Даларана."}}
D[12797] = {"Назад по Связующей спирали",{"Принесите Аватаре Фрейи руну \"Омега\". Вы найдете Аватару в Низине Шолазар у водопадов Гласа Дождя."}}
D[12798] = {"Карты Новолуния: колода Мечей",{"Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Мечей."}}
D[12799] = {"Сбор эктоплазмы",{"Соберите 5 колб древней эктоплазмы от заблудших духов Драккари на озерах Жа'Джина для капитана Арната из Хеб'Валока."}}
D[12800] = {"Приказ Короля-лича",{"Найдите Командира Плети Таланора у лесопилки Бровача."}}
D[12801] = {"Сияние Рассвета",{"Разбейте войска Серебряного Рассвета и найдите Сияние Рассвета.","","Если вам удастся выжить, доложите о своей победе верховному лорду Дариону Могрейну."}}
D[12802] = {"Мое сердце – в твоих руках",{"Дракуру просит вас принести Сердце древних на его пьедестал в Перевале Драк'атала.","","Но сначала вам надо будет собрать 5 настоев безнадеги – иначе эликсир не сработает."}}
D[12803] = {"Сила природы",{"Отправляйтесь на Увядшую поляну, расположенную между водопадами Гласа Дождя и Затерянными землями и найдите Аватару Фрейи."}}
D[12804] = {"Стейк, достойный охотника",{"Принесите Коргу Тесаку в лагерь Эрнестуэя 5 стейков из длинношеего травояда."}}
D[12805] = {"Сохранение жизненной силы",{"По просьбе Фрейи отправляйтесь к Одинокому осколку на юго-восток и примените самоцвет жизненной силы к 8 уничтоженным элементалям жизненной силы."}}
D[12806] = {"На Уступ Смерти со всех ног!",{"Отправляйтесь к лорду-командиру Арету на Уступ Смерти, что в Ледяной Короне."}}
D[12807] = {"Немного истории...",{"Выслушайте рассказ лорда-командира Арета на Уступе Смерти."}}
D[12808] = {"Вынужденный союз"}
D[12809] = {"Стальгорн"}
D[12810] = {"Кровавая вода",{"Соберите кровь 10 прожорливых акул в бурдюк для крови и принесите его лорду-командиру Арету на Уступ Смерти."}}
D[12811] = {"Отчаянный поиск"}
D[12812] = {"Оргриммар"}
D[12813] = {"Из праха восстаньте!",{"Возьмите настойку Темной Целительницы, которую дала вам Сетаал Темная Целительница на Уступе Смерти, и окропите тела любых 10 бойцов Алого Натиска, которых найдете."}}
D[12814] = {"Потребность в грифоне",{"Отведите грифона Алого Натиска к Узо Призывателю Смерти на Уступ Смерти."}}
D[12815] = {"Закрытое воздушное пространство",{"Убейте 10 всадников на грифонах из Алого Натиска по распоряжению Узо Призывателя Смерти с Уступа Смерти."}}
D[12816] = {"Нападение Плети на Луносвет",{"Соберите три тусклых Некротических камня Плети, которые носит при себе нежить, откружившая Луносвет, и исследуйте светящиеся рунические круги вблизи лагеря Плети."}}
D[12817] = {"Нападение Плети на Экзодар",{"Соберите три тусклых некротических камня созданий Плети, бродящих вокруг Экзодара, и изучите светящиеся рунические круги вокруг лагеря, после чего вернитесь к лейтенанту Крегору."}}
D[12818] = {"Сбор деталей",{"Принесите Глуму Свечекруту в К-3 10 деталей из обугленных обломков."}}
D[12819] = {"Плевое дело",{"По поручению Глума Свечекрута из К-3 принесите инструменты Свечекрута с минного поля."}}
D[12820] = {"Осторожное прикосновение",{"Рикет из К-3 просит вас воспользоваться усовершенствованными противопехотными минами на Побоище Гарма, чтобы оттеснить 12 противников: захватчиков из Гарма или последователей с Холмов Снежной Слепоты."}}
D[12821] = {"Танго в тюремном блоке",{"По поручению Рикет из К-3 разыщите батарею для телепортера и с ее помощью активируйте площадку телепортера у Подъема Гарма."}}
D[12822] = {"Средство для устрашения",{"По заданию Рикет из К-3 убейте 6 дозорных Гарма и 8 приверженцев с Холмов Снежной Слепоты."}}
D[12823] = {"Безупречный план",{"Джино у Подъема Гарма просит вас положить надежно перевязанный сверток со взрывчаткой у алтаря Хладонутра, убить Тормара Хладонутра и выбраться из пещеры до того, как она обрушится."}}
D[12824] = {"Выдающийся подрывник",{"Возвращайтесь к Рикет в К-3."}}
D[12825] = {"Выражение благодарности",{"[PLACEHOLDER] Используйте мини-самолет с камикадзе на вождя гноллов."}}
D[12826] = {"Почти безопасны",{"Отнесите усовершенствованные противопехотные мины Глума Рикет в К-3."}}
D[12827] = {"Пополнение запасов провизии",{"По заданию Рикет из К-3 стащите 16 сухих пайков гноллов из ближайшего лагеря свирепых гноллов холмов."}}
D[12828] = {"Полет вдохновения",{"По просьбе Рикет из К-3 возьмите УРВР, убейте мамонта и принесите в К-3 8 больших кусков мяса мамонта."}}
D[12829] = {"Перед тем, как входить",{"По заданию Торы Громыхалы у пещеры Хрустальной Паутины убейте 12 пауков в этой пещере."}}
D[12830] = {"Изъятие руды",{"По просьбе Тор Громыхалы у пещеры Хрустальной Паутины соберите 5 образцов нечистой саронитовой руды."}}
D[12831] = {"Ядовитый укус",{"Принесите раненому гоблину-рудокопу в пещере Хрустальной Паутины ядовитую железу ледяного ползуна."}}
D[12832] = {"Побег",{"Проводите раненого гоблина-рудокопа из пещеры Хрустальной Паутины в К-3, а потом поговорите с Рикет."}}
D[12833] = {"Излишки",{"Рикет из К-3 просит вас воспользоваться усовершенствованными противопехотными минами на Побоище Гарма, чтобы оттеснить захватчиков из Гарма и последователей с Холмов Снежной Слепоты."}}
D[12834] = {"Ни дождь, ни снег, ни катастрофа",{"[PLACEHOLDER] Испытайте всепогодный бомбардировщик на великане."}}
D[12835] = {"Все взрослые",{"[PLACEHOLDER] Испытайте взрослого йормунгара на великане."}}
D[12836] = {"Выражение благодарности",{"По заданию Рикет из К-3 убейте Кривошерста."}}
D[12837] = {"У Тор есть все, что надо",{"[PLACEHOLDER] Явиться к Тор."}}
D[12838] = {"Сбор информации",{"Соберите 5 донесений разведки Алого Натиска по заданию Аурока Мрачного Проклятия с Уступа Смерти."}}
D[12839] = {"Грандиозные планы верховного адмирала",{"Отнесите письмо верховного адмирала лорду-командиру Аретy на Уступ Смерти."}}
D[12840] = {"Совершенно секретно",{"Выбейте информацию из капитанов Вельсингтона и Хартфорда, убейте обоих и возвращайтесь к лорду-командиру Арету на Уступ Смерти."}}
D[12841] = {"Сделка с Каргой",{"По просьбе Лок'лиры Карги принесите ей в Заброшенный рудник руны Ирквинн, отобрав их у надзирательницы Сиры."}}
D[12842] = {"Ковка рун: подготовка к битве",{"Инструктор Разувий из Черного оплота приказал вам выгравировать любую руну на вашем руническом клинке души.","","Выбранную гравировку можно заменить в любой момент, воспользовавшись ближайшей кузней рун."}}
D[12843] = {"Они забрали наших мужчин!",{"По просьбе Гретхен Искрошип отправляйтесь в деревню Сифрельдар и спасите 5 плененных гоблинов."}}
D[12844] = {"Вернуть оборудование",{"По просьбе Гретхен Искрошип принесите ей 8 предметов из снаряжения К-3, которые вы найдете в деревне Сифрельдар к северу от K-3."}}
D[12845] = {"Даларанский кристалл телепортации: флаг"}
D[12846] = {"Найти всех до единого...",{"Разыщите вход в Заброшенный рудник на севере деревни Сифрельдар и попробуйте выяснить, где может быть Зив Искрошип."}}
D[12847] = {"Второй шанс",{"Убейте архиепископа Ландгрена и откройте Врата Арета рядом с трупом. Поговорите с лордом-командиром Аретом, когда тот закончит допрашивать дух архиепископа в Багровом соборе."}}
D[12848] = {"Вечный голод",{"Инструктор Разувий из Черного оплота приказал вам освободить недостойного ученика и хладнокровно убить его!","","Выжить должен только один!"}}
D[12849] = {"Сила крови, льда и нечестивости"}
D[12850] = {"Командир сил Плети Таланор",{"Найдите командира сил Плети Таланора на балконе первого этажа Черного оплота."}}
D[12851] = {"Медвежья хватка",{"По заданию Бриджаны из деревни Бруннхильдар оседлайте Ледоклыка и застрелите 7 снежных воргов и 15 снежных великанов в долине Древней Зимы."}}
D[12852] = {"Поиски адмирала",{"Убейте верховного адмирала Вествинда, а потом возвращайтесь к лорду-командиру Арету на Уступ Смерти."}}
D[12853] = {"Поторопить события",{"Поговорите с Глумом Свечекрутом в лаборатории К-3 в Грозовой Гряде."}}
D[12854] = {"По следам Бранна",{"Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к археологу Андорину в Ледяную крепость."}}
D[12855] = {"Найти преступника",{"Используйте ошейник северной гончей в Заброшенном лагере, чтобы выследить тех, кто забрал вещи Бранна. Когда вы их разыщете, включите переговорное устройство и свяжитесь с теми, с кем получится связаться."}}
D[12856] = {"Холодные сердца",{"По заданию Бриджаны летите в Дун Ниффелем, освободите 3 пленных протодраконов, спасите 9 пленных бруннхильдарок и привезите их обратно, к востоку от деревни Бруннхильдар."}}
D[12857] = {"Плавник Ярогрива",{"Принесите плавник Ярогрива вождю Яростного Когтя в Разлом Света в Зул'Драке."}}
D[12858] = {"Кусочки головоломки",{"Соберите 6 фрагментов диска изобретателя и сложите из них диск изобретателя."}}
D[12859] = {"Негасимый огонь",{"Используйте огнетушитель Яростного Когтя, чтобы потушить 15 пожаров в логове Яростного Когтя по просьбе старого шамана Моки в Разломе Света в Зул'Драке."}}
D[12860] = {"Сбор информации",{"Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных."}}
D[12861] = {"Плохие тролли",{"По заданию вождя Яростного Когтя из Разлома Света в Зул'Драке отберите у троллей Дракуру необходимое количество \"Отмычек\" Дракуру и освободите 8 пойманных волчеров из стаи Яростного Когтя."}}
D[12862] = {"Когда остается единственный выход...",{"Воспользуйтесь принадлежащим Рикет пропеллерным доставочным аппаратом Д16, чтобы продвинуться вглубь Грозовой Гряды."}}
D[12863] = {"Большое спасибо",{"Отнесите ящик с медикаментами Глорталу Жесткобороду из Ледяной крепости."}}
D[12864] = {"Пропавшие разведчики",{"Обыщите долину Дыхания Бора и водопад Бора и попробуйте разыскать пропавших разведчиков из клана Зиморожденных."}}
D[12865] = {"Верные друзья",{"По поручению Фьюрлина Ледоброва из Ледяной крепости добудьте 8 кусков свежего мяса люторога и покормите грозовестников, обитающих прямо над городом."}}
D[12866] = {"Сопротивление агрессорам",{"По заданию Глортала Жесткоборода из Ледяной крепости убейте 8 крикуний и 8 ведьм из стаи Ледяного Пера."}}
D[12867] = {"Похитители птенцов",{"Принесите Фьюрлину Ледоброву из Ледяной крепости 15 яиц грозовестников."}}
D[12868] = {"Источник всех бед",{"По просьбе Глортала Жесткоборода убейте Сирану Ледяной Вопль."}}
D[12869] = {"Все слишком далеко зашло",{"По поручению Фьюрлина Ледоброва убейте с помощью грозовестника 16 змеев Грозовой Гряды в Подножии."}}
D[12870] = {"Древние реликвии",{"Принесите Рорку Остробороду в Ледяную крепость 10 реликвий Ульдуара."}}
D[12871] = {"Помощь Лиги исследователей",{"Отнесите оболочку Норганнона Лагнусу в Ледяную крепость."}}
D[12872] = {"Оболочка Норганнона",{"Заберите оболочку Норганнона у архивариуса Мехатона."}}
D[12873] = {"Король Зиморожденных",{"Поговорите с Йоргом Грозовым Сердцем в Ледяной крепости."}}
D[12874] = {"Рвение Зиморожденного",{"По указанию Йорга Грозового Сердца из Ледяной Крепости поговорите с Фьюрлином Ледобровом, который организует вам поездку и назначит для вас испытание."}}
D[12875] = {"Опытный проводник",{"Разыщите Дрома Ледохвата."}}
D[12876] = {"Нежеланные гости",{"По просьбе Фьюрлина Ледоброва убейте 10 погромщиков из клана Закаленных Бурей."}}
D[12877] = {"Одинокий часовой",{"Заберите у наблюдателя железных дворфов перстень-печатку Ледохвата и покажите его Кретею в Подножии."}}
D[12878] = {"Спрятанная реликвия",{"Найдите ядро Норганнона, руководствуясь информацией, которую дал Кретей в Подножии."}}
D[12879] = {"Ярость короля Зиморожденных",{"Отнесите ядро Норганнона Кретею в Подножие."}}
D[12880] = {"Главный исследователь",{"Отнесите ядро Норганнона Бранну Бронзобороду к Машине Творцов."}}
D[12881] = {"Братья Бронзобороды"}
D[12882] = {"Древние реликвии",{"Отнесите 10 реликвий Ульдуара Олуту Пивобрюху на место крушения Гром'арша."}}
D[12883] = {"Приказы Дракуру",{"Отнесите приказы Дракуру главе рыцарей Лантинге в Разлом Света в Зул'Драке."}}
D[12884] = {"Черная застава",{"Отнесите приказы Дракуру Стефану Ваду на Черную Заставу в Зул'Драке."}}
D[12885] = {"Изгнанники Ульдуара",{"Поговорите с Глыбоскалом Камнетесом в Приюте Глыбоскала."}}
D[12886] = {"Драконобойца",{"Воспользуйтесь хильдским гарпуном, чтобы победить 10 наездниц на драконе Круга хильд в Храме Штормов, после чего выстрелите гарпуном в украшение на колонне и поговорите с Торимом."}}
D[12887] = {"Непростая работа",{"Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде."}}
D[12888] = {"УБЕР-И",{"Принесите в Библиотеку Изобретателя карту доступа к УБЕР-И, 4 пригоршни кобальтовых болтов и 5 перегруженных конденсаторов и попробуйте починить УБЕР-И."}}
D[12889] = {"Панель управления прототипом",{"Попробуйте разобраться с панелью управления прототипом в Библиотеке Изобретателя."}}
D[12890] = {"Если размер имеет значение..."}
D[12891] = {"Воплощение идеи",{"Принесите скипетр сектанта, крюк поганища, веревку упыря и 5 эссенций Плети барону Раздору в Мрачный Свод."}}
D[12892] = {"Непростая работа",{"Уничтожьте Глаз и переговорите с бароном Раздором в Мрачном Своде."}}
D[12893] = {"Освобождение разума",{"Подействуйте скипетром повеления на тела Злоба, леди Найтсвуд и Прыгуна, а потом возвращайтесь к барону Раздору в Мрачный Свод."}}
D[12894] = {"Передовой лагерь рыцарей",{"Разыщите рыцаря Маккеллара в Передовом лагере рыцарей в Зул'Драке."}}
D[12895] = {"Пропавший Бронзобород",{"Заберите завернутую в мешковину записку из лагеря Бранна и возвращайтесь к Боктару Кровавому Безумию на место крушения Гром'арша."}}
D[12896] = {"Последний аргумент",{"Убейте генерала Погибель Света и доложите об исполнении Тассариану на борту \"Усмирителя небес\"."}}
D[12897] = {"Последний аргумент",{"Убейте генерала Погибель Света и доложите об исполнении Кольтире Ткачу Смерти на борту \"Молота Оргрима\"."}}
D[12898] = {"Мрачный Свод",{"Поговорите с бароном Раздором в Мрачном Своде."}}
D[12899] = {"Мрачный Свод",{"Поговорите с бароном Раздором в Мрачном Своде."}}
D[12900] = {"Изготовление сбруи",{"По заданию Астрид Бьорнриттар из деревни Бруннхильдар раздобудьте 3 шкуры ледогривых йети."}}
D[12901] = {"Что-то из ничего",{"Принесите 10 обломков металлолома Плети инженеру Риду в Передовой лагерь рыцарей в Зул'Драке."}}
D[12902] = {"Кто за этим стоит?",{"Обыщите логово Яростного Когтя и попытайтесь узнать, кто был зачинщиком атаки на волчеров Яростного Когтя."}}
D[12903] = {"Для того и нужны друзья...",{"Разыщите рыцаря Даргата, Герка и Бурра по просьбе рыцаря Маккеллара из Передового лагеря рыцарей."}}
D[12904] = {"Орудие мести",{"Убейте 15 варгулов по просьбе Герка из Тупика Трыма в Зул'Драке."}}
D[12905] = {"Милдред Жестокая",{"Поговорите с Милдред Жестокой в Заброшенном руднике."}}
D[12906] = {"Поучить уму-разуму",{"По заданию Милдред Жестокой из Заброшенного рудника накажите 6 обессиленных врайкулов с помощью вразумляющего жезла."}}
D[12907] = {"Нужны показательные примеры",{"По заданию Милдред Жестокой из Заброшенного рудника убейте Гархала."}}
D[12908] = {"Наглая пленница",{"Отнесите ключ Милдред Лок'лире Карге в Заброшенный рудник."}}
D[12909] = {"Острый нюх",{"Поговорите с Калииси у подножья горы, на востоке от места крушения Гром'арша."}}
D[12910] = {"Найти преступника",{"Садитесь верхом на Ледокус и езжайте на юг, взяв след по записке Бранна. Когда вам удастся заполучить переговорное устройство Бранна, свяжитесь с его помощью с Бранном Бронзобородом."}}
D[12911] = {"Kill Credit Test",{"/wave at Kill Credit Test"}}
D[12912] = {"Приближение великой бури",{"Придумайте способ, как освободить из клетки Гимера, короля штормовых великанов. Поговорите с инженером Ридом в Передовом лагере рыцарей."}}
D[12913] = {"Говори по-орочьи!",{"Отправляйтесь на место крушения Гром'арша и узнайте, не сможет ли Мотеха Дитя Ветра вам помочь."}}
D[12914] = {"Спасение Гимера",{"Принесите 6 субстанций банши и 6 комьев диатомовой земли инженеру Риду в Передовой лагерь рыцарей в Зул'Драке."}}
D[12915] = {"Возобновление старых связей",{"По заданию Торима из Храма Штормов убейте Фьорна и 5 железных великанов из клана Закаленных Бурей у Наковальни Фьорна к востоку от Дун Ниффелема. Чтобы вызвать на подмогу воинов земли, воспользуйтесь оберегом земли Торима. Чтобы его задействовать, нужен гранитный валун из Наковальни Фьорна."}}
D[12916] = {"Наша единственная надежда",{"Поговорите с Гимером в Тупике Трыма в Зул'Драке после того, как освободите его из клетки Плети с помощью огромного сефориевого заряда."}}
D[12917] = {"Поймай голос ветра!..",{"Поймайте 5 голосов ветра, Мотеха Дитя Ветра на месте крушения Гром'арша ждет, чтобы вы их принесли."}}
D[12918] = {"Огранка камней",{"Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Унгуло в Валгард."}}
D[12919] = {"Месть короля Бурь",{"Когда будете готовы к битве, скажите об этом Гимеру.","","Сидя на голове у Гимера, уничтожьте 100 воинов Плети и убейте Алгара Избранного, Трыма и принца Навариуса. В случае успешного исхода доложите об этом серебряному рыцарю Маккеллару из передового лагеря рыцарей."}}
D[12920] = {"Вдогонку за Бранном",{"Используйте переговорное устройство Бранна, чтобы связаться с Бранном Бронзобородом. Потом доложите о результатах Боктару Кровавому Безумию, который ждет вас на месте крушения Гром'арша.","","Если вы потеряете переговорное устройство Бранна, вам поможет Мотеха Дитя Ветра на месте крушения Гром'арша."}}
D[12921] = {"Смена декораций",{"Поговорите с Лок'лирой Каргой в деревне Бруннхильдар."}}
D[12922] = {"Очищающее пламя",{"Соберите 10 гневных искр с пылающих загробников на Промерзшем озере и с их помощью разожгите огонь в Наковальне Фьорна."}}
D[12924] = {"Возобновление союза",{"Отправляйтесь в Дун Ниффелем и попросите короля Йоккума разрешить воссоздать доспех Торима. Выполнив поручение Йоккума, поговорите с Ньормельдом в Дун Ниффелеме."}}
D[12925] = {"Верность традициям",{"По заданию Тиры Квиншал из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте их, чтобы уничтожить 30 зачумленных яиц протодраконов."}}
D[12926] = {"Кусочки головоломки",{"Воспользуйтесь переговорным устройством Бранна, чтобы связаться с Бранном Бронзобородом и выяснить, что делать дальше."}}
D[12927] = {"Сбор информации",{"Воспользуйтесь диском изобретателя, чтобы считать 7 фрагментов секретных данных из банков данных."}}
D[12928] = {"Оболочка Норганнона",{"Заберите оболочку Норганнона у архивариуса Мехатона."}}
D[12929] = {"Земельники Ульдуара",{"Поговорите с Глыбоскалом Камнетесом в Приюте Глыбоскала."}}
D[12930] = {"Редкоземельный элемент",{"С помощью шахтерской кирки земельника добудьте 7 комков зачарованной земли и принесите 5 отрезов ледяной ткани Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12931] = {"Контратака",{"По заданию Глыбоскала Камнетеса убейте 10 мародеров или разорителей из клана Закаленных Бурей и возвращайтесь к нему в Приют Глыбоскала."}}
D[12932] = {"Амфитеатр Страданий: Иггдрас!",{"Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12933] = {"Амфитеатр Страданий: магнатавр!",{"Выйдите на арену в Амфитеатре Страданий и победите Смрадоборода! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12934] = {"Амфитеатр Страданий: существо из другого мира!",{"Выйдите на арену в Амфитеатре Страданий и победите повелителя элементалей! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12935] = {"Амфитеатр Страданий: Клыкаррмагеддон!",{"Выйдите на арену в Амфитеатре Страданий и победите Ориноко Клыколома! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12936] = {"Амфитеатр Страданий: Коррак Кровопуск!",{"Выйдите на арену в Амфитеатре Страданий и победите Коррака Кровопуска! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12937] = {"Исцеление раненых",{"Используйте земляные примочки, чтобы вылечить 8 раненых земельников-защитников, потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12938] = {"Герцог",{"Поговорите с герцогом Ланкралом в Мрачном Своде."}}
D[12939] = {"Вызов чести",{"Возьмите флаг вызова, вызовите на поединок и победите 6 мьординских бойцов по просьбе герцога Ланкрала из Мрачного Свода."}}
D[12940] = {"Кулек конфет"}
D[12941] = {"Кулек конфет"}
D[12942] = {"Черные крылья",{"По заданию Ивы Мстительной из деревни Бруннхильдар отправляйтесь в Валькирион и убейте 12 рождающихся валь'кир."}}
D[12943] = {"Указ Мрачного Свода",{"Зачитайте указ Мрачного Свода, составленный герцогом Ланкралом, тану Уфрангу Могущественному, после чего убейте Уфранга."}}
D[12944] = {"Кулек конфет"}
D[12945] = {"Кулек конфет"}
D[12946] = {"Кулек конфет"}
D[12947] = {"Кулек конфет"}
D[12948] = {"Чемпион Амфитеатра Страданий",{"Выйдите на арену в Амфитеатре Страданий и победите Владофа Мясника! Потом возвращайтесь к троллю-прислужнику Водину и получите награду."}}
D[12949] = {"Ключ от кандалов",{"Добудьте ключ от цепей Вэлена и отдайте его Вэлену Разоблаченному в Зале Уфранга."}}
D[12950] = {"Кулек конфет"}
D[12951] = {"Известия для барона",{"Поговорите с бароном Раздором в Мрачном Своде."}}
D[12952] = {"Огранка камней",{"Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Картеру Тиффенсу в Лагерь Возмездия."}}
D[12953] = {"Гори, Валькирион, гори",{"С помощью валькирионских гарпунных пушек подожгите 6 валькирионских стогов сена."}}
D[12954] = {"Амфитеатр Страданий: Иггдрас!",{"Выйдите на арену в Амфитеатре Страданий и победите Иггдраса! Потом вернитесь к троллю-прислужнику Водину и получите награду."}}
D[12955] = {"Унижение соперников",{"Вызовите на дуэль и победите Сигрид Дитя Льда, Ефрема Верного, Ону'Зуна и Тинки Свистопляс по поручению Прыгуна из Мрачного Свода."}}
D[12956] = {"Лучик надежды",{"Отнесите очищенный светящийся металл Ториму в Храм Штормов."}}
D[12957] = {"Рабы Закаленных Бурей",{"По заданию Глыбоскала Камнетеса из Приюта Глыбоскала освободите 6 пленных мехагномов и убейте 3 надсмотрщиков из клана Закаленных Бурей."}}
D[12958] = {"Заказ от торговой компании: амулет из кровавого нефрита",{"Создайте амулет из кровавого нефрита, объединив амулет врайкулов, темный нефрит и кровавый камень, после чего принесите его Тимоти Джонсу в Даларан. Амулет врайкулов можно добыть с любого врайкула в Нордсколе."}}
D[12959] = {"Заказ от торговой компании: блестящая статуэтка из бивня",{"Создайте блестящую статуэтку из бивня черпорога, объединив кальцедоний, сумрачный кристалл и бивень черпорога, и принесите ее Тимоти Джонсу в Даларан. Для того чтобы раздобыть бивень черпорога, вам нужно будет убить черпорога или мамонта в Нордсколе."}}
D[12960] = {"Заказ от торговой компании: брошь Беспощадного солнца",{"Создайте брошь Беспощадного солнца из броши железных дворфов, огромного цитрина и солнечного хрусталя и принесите ее Тимоти Джонсу в Даларан.","","Брошь железных дворфов можно добыть у любого железного дворфа в Нордсколе."}}
D[12961] = {"Заказ от торговой компании: изысканная костяная статуэтка",{"Создайте изысканную костяную статуэтку из кости протодракона, солнечного хрусталя и темного нефрита и принесите ее Тимоти Джонсу в Даларан. Кость протодракона можно добыть с любого протодракона в Нордсколе."}}
D[12962] = {"Заказ от торговой компании: Реликвия из сияющей брони",{"Создайте реликвию Сияющей брони из осколка элементальной брони, кровавого камня и огромного цитрина и принесите ее Тимоти Джонсу в Даларан. Осколок элементальной брони можно добыть у любого элементаля-загробника в Нордсколе."}}
D[12963] = {"Заказ от торговой компании: реликвия Восходящего Солнца",{"Создайте реликвию Восходящего Солнца из реликвии Плети, солнечного хрусталя и сумрачного кристалла и принесите ее Тимоти Джонсу в Даларан. Реликвию Плети можно добыть у любого последователя Плети в Нордсколе."}}
D[12964] = {"Темная руда",{"Принесите 5 образцов руды Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12965] = {"Дары Локена",{"Уничтожьте Неистовство Локена, Мощь Локена и Благосклонность Локена, а затем вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12966] = {"Мимо него не пройдешь",{"По поручению короля Йоккума из Дун Ниффелема разыщите Ньормельда у Наковальни Фьорна."}}
D[12967] = {"Сражение со стихиями",{"По поручению Ньормельда отправляйтесь к наковальне Фьорна вместе с Храппи и помогите ему убить 10 пылающих загробников."}}
D[12968] = {"Безрассудство Юльды",{"По заданию Ивы Мстительной из деревни Бруннхильдар убейте Юльду Опустошительницу в Валькирионе."}}
D[12969] = {"Это твой гоблин?",{"Бросьте вызов Агнете Тирсдоттар, чтобы спасти Зива Искрошипа. Добившись успеха, возвращайтесь к Лок'лире Карге из деревни Бруннхильдар."}}
D[12970] = {"Круг хильд",{"Выслушайте предложение Лок'лиры Карги."}}
D[12971] = {"Вызов принят",{"Сразите 6 дуэлянтов-победителей по заданию Лок'лиры Карги из деревни Бруннхильдар."}}
D[12972] = {"Тебе понадобится медведь",{"Поговорите с Бриджаной неподалеку от деревни Бруннхильдар."}}
D[12973] = {"Братья Бронзобороды",{"Прикрывайте Бранна и ветролет, пока не доберетесь до Ледяной крепости."}}
D[12974] = {"Призыв бойцовского клуба",{"Разыщите Гаргтокa в Амфитеатре Страданий в Зул'Драке."}}
D[12975] = {"Мемориал",{"По заданию короля Йоккума из Дун Ниффелема соберите 8 фрагментов рога в Громовержье."}}
D[12976] = {"Памятник павшим",{"По поручению короля Йоккума отнесите фрагменты рога Ходира Ньормельду в Дун Ниффелем."}}
D[12977] = {"Зов Ходира",{"Убейте 5 ниффелемских прародителей и 5 неупокоенных дворфов из клана Зиморожденных в Громовержье. Протрубите над их телами в рог, затем вернитесь к рогу Ходира в Дун Ниффелем."}}
D[12978] = {"Навстречу буре",{"По заданию Брюора Железоруба в Приюте Глыбоскала убейте 10 Закаленных Бурей из Нидавелира. Вы можете убивать воителей клана Закаленных Бурей, волхвов клана Закаленных Бурей или боевых големов клана Закаленных Бурей."}}
D[12979] = {"Доспехи тьмы",{"Принесите 4 образца темной пластины для доспехов Брюору Железорубу в Приют Глыбоскала."}}
D[12980] = {"Секрет доспехов",{"Отнесите темную пластину для доспехов в Мастерскую Мимира и попросите рабочего Тока осмотреть ее. Потом возвращайтесь к Брюору Железорубу в Приют Глыбоскала."}}
D[12981] = {"Жар и холод",{"Идите к Промерзшему озеру, убейте хрупких загробников, обитающих в тех краях, и с помощью субстанции Льда остудите дымящиеся осколки у наковальни Фьорна. Потом соберите 6 кусков застывшего железа и вернитесь к наковальне Фьорна в Дун Ниффелем."}}
D[12982] = {"Пленники из ордена Черного Клинка",{"Освободите 8 пленных рыцарей Черного Клинка по просьбе Вэлена Разоблаченного из Мрачного Свода. Пленников держат в клетках в районе Йотунхейма."}}
D[12983] = {"Последняя из рода",{"Спасите медведицу-матриарха в пещере зимней спячки по просьбе Астрид Бьорнриттар из деревни Бруннхильдар."}}
D[12984] = {"Валдуран Дитя Бури",{"Протрубите в боевой рог Глыбоскала, когда разыщете Валдурана Дитя Бури. Одержите победу над ним и вернитесь к Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12985] = {"Ковка шлема",{"По заданию Ньормельда в Дун Ниффелеме возьмите кирку с алмазным наконечником, вырвите с ее помощью глаза у мертвых железных великанов у Промерзшего озера и принесите ему 8 глаз Закаленных Бурей."}}
D[12986] = {"Судьба титанов",{"По заданию Кретея из Подножия посетите Храм Изобретений, Храм Зимы, Храм Жизни и Храм Порядка. Используйте банк данных для изучения каждого из них."}}
D[12987] = {"Шлем Ходира",{"Летите к острию ледяного шипа в северной части Дун Ниффелема и прочитайте народу Ньормельда текст со скрижалей Утверждения."}}
D[12988] = {"Штормовые кузни",{"Разрушьте северную штормовую кузню, центральную штормовую кузню и южную штормовую кузню с помощью бомб Глыбоскала. Потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12989] = {"Нашествие тьмы",{"По заданию Астрид Бьорнриттар убейте 8 прожорливых йормунгаров в пещере зимней спячки на востоке от деревни Бруннхильдар."}}
D[12990] = {"Червоточина",{"Принесите Джону Лекрафту нужные ему материалы – и вы не только останетесь в живых, но и узнаете новое заклинание."}}
D[12991] = {"Удар по больному месту",{"Убейте 10 изобретателей из клана Закаленных Бурей и возвращайтесь к Брюору Железорубу в Приют Глыбоскала."}}
D[12992] = {"Истребление врайкулов",{"Убейте 15 врайкулов в районе Йотунхейма по заданию Злоба из Мрачного Свода."}}
D[12993] = {"Колоссальная опасность",{"Разыщите документы с наступательными и оборонительными характеристиками колосса и принесите их Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[12994] = {"Контрразведчик",{"Убейте 3 Секретных агентов клана Закаленных Бурей в долине Древних Зим.","","С помощью клыка астрального ворга призовите призрачного ледяного ворга, который поможет вам обнаружить скрывающихся врагов. По выполнении задания вернитесь к повелительнице логова ледяных воргов в Дун Ниффелем."}}
D[12995] = {"Наша метка",{"По заданию барона Раздора из Мрачного Свода воткните 15 знамен Черного Клинка рядом с телами мертвых врайкулов в районе Йотунхейма."}}
D[12996] = {"Тренировочный заезд",{"Воспользуйтесь поводьями матриарха ледочревов, чтобы сразиться с Киргарааком, как вам велела Астрид Бьорнриттар из деревни Бруннхильдар."}}
D[12997] = {"В Яму!",{"Отправляйтесь в Яму Клыка, воспользуйтесь поводьями матриарха ледочревов и победите 6 боевых медведей Круга хильд по заданию Астрид Бьорнриттар из деревни Бруннхильдар."}}
D[12998] = {"Сердце бури",{"По поручению Глыбоскала Камнетеса из Приюта Глыбоскала отправляйтесь в Ульдис и сделайте все возможное, чтобы надзиратель Нарвир не сумел заполучить Сердце бури."}}
D[12999] = {"Костяная ведьма",{"Поговорите с костяной ведьмой в пещере в деревне Ньорндар."}}
D[13000] = {"Чрезвычайные меры",{"Отправляйтесь в Логово Гиморака на востоке и добудьте 6 шкур воргов по просьбе кровостража Лорги."}}
D[13001] = {"Копье Ходира",{"Добудьте 3 осколка Вечного льда в пещере зимней спячки и 3 шкуры спокойных мамонтов в долине Древних Зим и отнесите все сказителю Рандвиру в Дун Ниффелем."}}
D[13002] = {"Огранка камней",{"Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Геба'ли в Крепость Песни Войны."}}
D[13003] = {"Как убить дракона",{"С помощью копья Ходира загарпуньте дикого змея в долине Древних Зим и сразитесь с ним не на жизнь, а на смерть."}}
D[13004] = {"Огранка камней",{"Принесите два огромных цитрина, два темных нефрита и два сумрачных кристалла Алестосу в Крепость Отваги."}}
D[13005] = {"Клятва детей земли",{"Используйте рог Вершин, чтобы призвать земельников на битву с железными дворфами и убить 20 железных дворфов и 7 железных часовых по просьбе Торима с Террасы Творцов."}}
D[13006] = {"Полировка кислотой",{"Идите в пещеру зимней спячки и соберите 5 сгустков вязкого масла злобных масленышей. Потом возвращайтесь в Дун Ниффелем и натрите маслом шлем Ходира."}}
D[13007] = {"Железный колосс",{"Уничтожьте железного колосса с помощью прирученного йормунгара, а потом возвращайтесь к Глыбоскалу Камнетесу в Приют Глыбоскала."}}
D[13008] = {"Тактика Плети",{"Освободите 8 опутанных рыцарей по заданию командира рыцарей Энтари из Оплота Серебряного Авангарда в Ледяной Короне."}}
D[13009] = {"Новое начало",{"Отнесите перекованные доспехи Торима в Храм Штормов по просьбе Ньормельда."}}
D[13010] = {"Кролмир, Молот Бурь",{"Поговорите с королем Йоккумом в Дун Ниффелеме и попробуйте выяснить, что ему известно о Кролмире, принадлежавшем Ториму."}}
D[13011] = {"Усмирение Йормуттар",{"По приказу короля Йоккума из Дун Ниффелема убейте Йоркуттар в пещере зимней спячки."}}
D[13012] = {"Предок Сардис"}
D[13013] = {"Предок Белдак"}
D[13014] = {"Предок Морти"}
D[13015] = {"Предок Фаргал"}
D[13016] = {"Предок Нортал"}
D[13017] = {"Предок Яртен"}
D[13018] = {"Предок Сандрин"}
