D[13023] = {"Предок Килиас"}
D[13024] = {"Предок Ваникая"}
D[13025] = {"Предок Лунаро"}
D[13026] = {"Предок Синий Волк"}
D[13027] = {"Предок Таурос"}
D[13028] = {"Предок Серогрив"}
D[13029] = {"Предок Памуя"}
D[13030] = {"Предок Вурайн"}
D[13031] = {"Предок Хранитель Неба"}
D[13032] = {"Предок Мурако"}
D[13033] = {"Предок Арп"}
D[13034] = {"Наблюдатель и герой",{"По просьбе Ксанатавра из лагеря Тунка'ло прочитайте Первый, Второй и Третий свитки."}}
D[13035] = {"Прислужники Локена",{"Убейте Айзенфауста в Зале Творца, а также Халефнира Дитя Ветра и Даррона Рунокова на Террасе Творцов по просьбе Торима."}}
D[13036] = {"Великая миссия",{"Поговорите с командиром рыцарей Энтари в Оплоте Серебряного Авангарда в Ледяной Короне."}}
D[13037] = {"Воспоминания о Штормовом Копыте",{"Поговорите с вождем Быстрое Копье в Ледяных Глубинах и возвращайтесь к Ксанатавру в лагерь Тунка'ло."}}
D[13038] = {"Искажения времени",{"Закройте 4 расселины в Ледяных глубинах с помощью тотема вождя, а затем отправляйтесь в лагерь Тунка'ло и отдайте тотем Ксанатавру."}}
D[13039] = {"Оборона аванпоста",{"Убейте 15 нерубов Забытых глубин по просьбе лорда Далфорса из Оплота Серебряного Авангарда в Ледяной Короне."}}
D[13040] = {"Исцеление неисцелимого",{"Принесите 10 ядовитых желез душителей Забытых глубин отцу Густаву в Оплот Серебряного Авангарда в Ледяной Короне."}}
D[13041] = {"Недостающий камень",{"Принесите кусок кальцедония Тимоти Джонсу в Даларан."}}
D[13042] = {"В недрах Глубинных чертогов",{"По поручению костяной ведьмы из деревни Ньорндар выбейте информацию из ученика Остеркилгра: узнайте, где находится доктор Ужас.","","Потом убейте ученика."}}
D[13043] = {"Когда сумма больше слагаемых",{"Заберитесь в Нергельда и возьмите над ним контроль. Защищайте его от обитателей Зала Ужасов, пока не покажется доктор Ужас.","","Используйте Нергельда, чтобы убить доктора, а потом возвращайтесь в деревню Ньорндар, в пещеру к костяной ведьме."}}
D[13044] = {"Пропавшие без вести",{"Поговорите с Пенумбриусом в Оплоте Серебряного Авангарда в Ледяной Короне."}}
D[13045] = {"В чащобу",{"Вытащите из Плетхольма 3 плененных рыцарей Серебряного Авангарда и доставьте их в лазарет в центре Оплота Серебряного Авангарда. После этого поговорите с верховным лордом Тирионом Фордрингом."}}
D[13046] = {"Муки Арнгрима",{"Вы должны накормить Арнгрима пятью бесплотными йормунгарами и вернуться к замерзшему изображению Арнгрима в Дун Ниффелем.","","Идите в долину Древних Зим и воспользуйтесь зубом Арнгрима, чтобы воздействовать на блуждающих йормунгаров. Когда они развоплотятся, сражайтесь с ними, пока они не ослабнут."}}
D[13047] = {"Свидетель",{"Встретьтесь с Торимом у храма Мудрости. Потом отправляйтесь к Йоккуму в Дун Ниффелем и расскажите ему об исходе сражения."}}
D[13048] = {"Откуда время пошло не туда",{"Разыщите реликвии таунка и настройте Молот Знаний на истинное время Штормового Копыта. Когда он настроится на 6 реликвий из времени Штормового Копыта, возвращайтесь к Ксанатавру в лагерь Тунка'ло."}}
D[13049] = {"Доспехи героя",{"Добудьте копье и кольчугу Штормового Копыта и верните их Ксанатавру в лагерь Тунка'ло."}}
D[13050] = {"Веранус",{"Раздобудьте 5 маленьких яиц протодракона в горах рядом с деревней Бруннхильдар и принесите их Ториму в Храм Штормов."}}
D[13051] = {"Нарушение границ",{"Отнесите похищенные яйца протодракона в гнездо праматери и возвращайтесь к Ториму в Храм Штормов."}}
D[13052] = {"Воздушная разведка",{"Отправляйтесь в Лагерь у озера по просьбе профессора Кальверт и поговорите там с пилотом Виком."}}
D[13053] = {"В поисках уцелевших",{"Помогите Заку Шестеркруту совершить испытательный полет."}}
D[13054] = {"Пропавший следопыт",{"Разыщите следопыта Вал'зижа в логове Гиморака, на юго-востоке от места крушения Гром'арша."}}
D[13055] = {"Лекарство из пещер",{"Добудьте 1 ядовитую железу йормунгара и 8 пещерных грибов и доставьте следопыту Вал'зижу в Логово Гиморака."}}
D[13056] = {"Всегда найдется время для мести",{"Убейте Гиморака в пещере Ледяного Воя по просьбе следопыта Вал'зижа."}}
D[13057] = {"Терраса Творцов",{"Разыщите Торима на юго-восточном конце Террасы Творцов, к северо-западу от Дун Ниффелема."}}
D[13058] = {"Чтобы ветер переменился",{"Используйте Молот Знаний, чтобы вернуться в прошлое и сразиться с Северным Ветром под личиной Штормового Копыта. Когда Штормовое Копыто падет, возьмите рог неистовства стихий и прикончите Северного Ветра, а затем возвращайтесь к Ксанатавру в лагерь Тунка'ло."}}
D[13059] = {"Месть за варгулов",{"Бросьте меч в Круге Страдания, вызовите на бой и убейте тана Иллскара по просьбе Бетода Фейгра из Глубинных чертогов."}}
D[13060] = {"Когда остается единственный выход...",{"Воспользуйтесь принадлежащим Рикет пропеллерным доставочным аппаратом Д16, чтобы продвинуться вглубь Грозовой Гряды."}}
D[13061] = {"Победа или смерть",{"Поговорите с Лок'лирой Каргой в деревне Бруннхильдар."}}
D[13062] = {"Прощальный подарок Лок'лиры",{"Поговорите с Греттой Судьей в деревне Бруннхильдар."}}
D[13063] = {"Посмотрим, чего ты стоишь",{"По просьбе Бриджаны отправляйтесь в деревню Бруннхильдар и поговорите с Астрид Бьорнриттар."}}
D[13064] = {"Соперничество братьев",{"Выслушайте историю Торима."}}
D[13065] = {"Предок Оханзи"}
D[13066] = {"Предок Яруак"}
D[13067] = {"Предок Чоган'гада"}
D[13068] = {"Отважный герой",{"Отправляйтесь в северо-восточную часть Ледяной Короны, разыщите героя, рыцаря Бриденбрада, в Молчаливом Бдении и приведите его к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Возле его стоянки обычно горит костер, заметный с воздуха."}}
D[13069] = {"Пристрели их",{"По заданию Прыгуна из Мрачного Свода сбейте с помощью йотунхеймского скорострельного гарпуна 15 йотунхеймских протодраконов и их наездников."}}
D[13070] = {"Приближение холодного фронта",{"Поговорите с осадным мастером Феззиком в Оплоте Серебряного Авангарда в Ледяной Короне."}}
D[13071] = {"Злоб любит огонь!",{"По просьбе Злоба из Мрачного Свода украдите ньорндарского протодракона и заставьте его поджечь 8 построек врайкулов в Йотунхейме.","","Цитадель Балагарда, в силу своей природы, гореть не может."}}
D[13072] = {"Горькая участь героя",{"Расскажите о том, что случилось с рыцарем Бриденбрадом, верховному лорду Тириону Фордрингу на Вершине Рыцарей."}}
D[13073] = {"Благосклонность хранителя",{"По просьбе верховного лорда Тириона Фордринга с Вершины Рыцарей поговорите с верховным друидом Лилиандрой и доберитесь до хранителя Ремула на Лунной поляне."}}
D[13074] = {"Изумрудный кошмар",{"По заданию хранителя Ремула с Лунной поляны погрузитесь в Изумрудный Сон и добудьте 3 изумрудных желудя.","","Чтобы пробудиться, покиньте святилище Ремула или ущипните себя."}}
D[13075] = {"Дар Ремула",{"Отнесите изумрудный желудь рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне."}}
D[13076] = {"Время еще есть",{"Возвращайтесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей и сообщите ему о том, каким действием обладают изумрудные желуди."}}
D[13077] = {"Прикосновение Аспекта",{"Попросите о помощи Алекстразу Хранительницу Жизни из храма Драконьего Покоя."}}
D[13078] = {"Слезы Далии",{"Сорвите слезы Далии с земли, очищенной пламенем Рубиновых хранителей, и принесите их Алекстразе Хранительнице Жизни в храм Драконьего Покоя."}}
D[13079] = {"Дар Алекстразы",{"Отнесите Дыхание Алекстразы рыцарю Бриденбраду в Молчаливое Бдение, что в в Ледяной Короне."}}
D[13080] = {"Надежда жива",{"Вернитесь к верховному лорду Тириону Фордрингу на Вершину Рыцарей. Расскажите ему о действии Дыхания Алекстразы."}}
D[13081] = {"Завещание наару",{"Попросите о помощи А'дала из Шаттрата, который находится в лесу Тероккар."}}
D[13082] = {"Дар А'дала",{"Вернитесь к рыцарю Бриденбраду в Молчаливое Бдение, что в Ледяной Короне."}}
D[13083] = {"Свет во тьме",{"Отнесите плащ рыцаря Бриденбрада верховному лорду Тириону Фордрингу на Вершину Рыцарей."}}
D[13084] = {"Психологическая атака",{"Сожгите 10 знамен врайкулов по поручению герцога Ланкрала из Мрачного Свода."}}
D[13085] = {"Возвращение Вэлена",{"Поговорите с Вэленом Разоблаченным в Мрачном Своде."}}
D[13086] = {"Последний рубеж",{"Уничтожьте 100 солдат Плети с помощью пушки Серебряного Авангарда. Также уничтожьте 3 ледяных драконов-разрушителей.","","В случае успеха вернитесь к осадному мастеру Феззику."}}
D[13087] = {"Кулинария севера",{"Принесите четыре куска охлажденного мяса зверей Нордскола Брому Выпивастеру в Валгард."}}
D[13088] = {"Кулинария севера",{"Принесите четыре куска охлажденного мяса зверей Нордскола Роллику Маккрилу в Крепость Отваги."}}
D[13089] = {"Кулинария севера",{"Принесите четыре куска охлажденного мяса зверей Нордскола Томасу Количио в Лагерь Возмездия."}}
D[13090] = {"Кулинария севера",{"Принесите четыре куска охлажденного мяса зверей Нордскола Орну Хрупкое Копыто в Крепость Песни Войны. Охлажденное мясо можно достать только убивая зверей, обитающих на континенте Нордскол."}}
D[13091] = {"Нелегко быть водным ужасом",{"По заданию костяной ведьмы из деревни Ньорндар завладейте водяным ужасом и уничтожьте с его помощью 10 врайкулов в окрестностях Йотунхейма.","","Ваша кара может коснуться йотунхеймских хранителей снов, йотунхеймских воинов, мьординских волхвов воды, ньорндарских копьеносиц и валхальских варгулов."}}
D[13092] = {"Гадание по костям",{"Принесите 15 костей врайкулов костяной ведьме в деревню Ньорндар."}}
D[13093] = {"Гадание по костям"}
D[13094] = {"Ни стыда, ни совести",{"Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда."}}
D[13095] = {"Ни стыда, ни совести",{"Библиотекарь Серра просит вас зайти в Нексус и найти книгу с исследованиями Беринарда."}}
D[13096] = {"Гал'дара заплатит за все",{"Отправляйтесь в Гундрак и убейте Гал'дара по поручению Тол'мара из Дубра'джина."}}
D[13097] = {"Неоконченное дело",{"Поговорите с Тол'маром в Дубра'джине по просьбе Хар'коа."}}
D[13098] = {"Для наших потомков",{"Отправляйтесь в Гундрак и заберите оттуда 6 табличек с летописью Драккари по поручению летописца Ба'Кини из Дубра'джина."}}
D[13099] = {"Просто проверка",{"Поговорите с Ба'Кини в Дубра'джине по просьбе То'кини."}}
D[13100] = {"Мясной рулет в странногрибном соусе",{"Запеките 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса в форме для мясного рулета и отнесите готовое блюдо Ортону Беннету в лавку \"Диковины и редкости\" на площадь Руноплета в Даларане."}}
D[13101] = {"Сбор в Приюте фокусника",{"Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в \"Приют фокусника\" на площади Руноплета."}}
D[13102] = {"Рагу для завсегдатаев Стоков",{"Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.","","Когда овощное рагу будет готово, отнесите его хозяину таверны Аджаю Грину в Стоки Даларана."}}
D[13103] = {"Сыр для Златоплава",{"Возьмите зрелый даларанский камамбер в сырной лавке \"Еще по сто\", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.","","Отнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников."}}
D[13104] = {"И снова в Пролом",{"Отправляйтесь в распоряжение черного хранителя в Долине Эха, рядом с Проломом."}}
D[13105] = {"И снова в Пролом",{"Поговорите с черным хранителем в Долине Эха у входа в Пролом."}}
D[13106] = {"Черный дозор",{"Поговорите с темной всадницей Арли в Черном дозоре, что в Ледяной Короне."}}
D[13107] = {"Сосиски с горчицей!",{"Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.","","Отнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане."}}
D[13108] = {"Любой ценой!",{"Отправляйтесь в Чертоги Молний и убейте Локена. Потом возвращайтесь к королю Йоккуму в Дун Ниффелем и отдайте ему язык Локена."}}
D[13109] = {"Диаметральные противоположности",{"Отправляйтесь в Чертоги Молний и убейте Волхана по поручению короля Йоккума из Дун Ниффелема."}}
D[13110] = {"Неупокоенные",{"По поручению отца Густава из Долины Эха в Ледяной Короне окропите кости 10 оживленных рыцарей святой водой, чтобы освободить наконец их неупокоенные души."}}
D[13111] = {"Единственный в своем роде",{"Отправляйтесь в Гундрак, добудьте обломок колосса Драккари и отнесите его летописцу Ба'Кини в Дубра'джин."}}
D[13112] = {"Мясной рулет в странногрибном соусе",{"Сварите 4 странных гриба из Стоков Даларана и 2 куска охлажденного мяса, чтобы получить мясной рулет, и отнесите готовое блюдо Ортону Беннету в лавку \"Диковины и редкости\" на площадь Руноплета в Даларане."}}
D[13113] = {"Сбор в Приюте фокусника",{"Приготовьте 4 порции северной похлебки, возьмите кувшин с вином из сырной лавки в Даларане и отнесите все Ариллю Лазурному Взгляду в \"Приют фокусника\" на площади Руноплета."}}
D[13114] = {"Рагу для завсегдатаев Стоков",{"Потушите 4 морковки из леса Хрустальной Песни с 4 кусками охлажденного мяса в кухонном горшке.","","Потом отнесите овощное рагу хозяину таверны Аджаю Грину в Стоки Даларана."}}
D[13115] = {"Сыр для Златоплава",{"Возьмите зрелый даларанский камамбер в сырной лавке \"Еще по сто\", потом пройдитесь по Даларану и слейте в бутылку остатки вина из 6 полупустых бокалов, стоящих на столах.","","Отнесите вино и сыр Раниду Златоплаву в кожевенную лавку в Торговой палате волшебников."}}
D[13116] = {"Сосиски с горчицей!",{"Заполните пустую корзинку для пикника. Положите туда 4 сосиски из мяса люторога, которые вы приготовите сами, и 4 побега полевой горчицы, которая растет на зеленых участках в черте Даларана.","","Отнесите корзинку для пикника верховному магу Пентарусу на площадку Краса в Даларане."}}
D[13117] = {"Откуда они берутся?",{"Проведите разведку у алтаря призыва в восточной части Мясопилки и возвращайтесь с докладом к темной всаднице Арли, которая ждет вас в Черном дозоре."}}
D[13118] = {"Очищение Плетхольма",{"По заданию черного хранителя из Долины Эха в Ледяной Короне уничтожьте 3 верховных жрецов Забытых глубин, 3 королей Забытых глубин и 8 оживленных рыцарей."}}
D[13119] = {"Разрушение алтарей",{"Убейте главного призывателя Зарода и используйте его посох призыва, чтобы уничтожить первый, второй, третий и четвертый алтари призыва. Когда все будет сделано, возвращайтесь к темной всаднице Арли в Черный дозор."}}
D[13120] = {"Взгляд смерти",{"Разместите сферу взгляда смерти на стойке у лаборатории поганищ, стойке у лаборатории мясистых великанов и стойке в окрестностях котла. Когда все будет готово, возвращайтесь к темной всаднице Арли в Черный дозор."}}
D[13121] = {"Чужими глазами",{"По просьбе костяной ведьмы из деревни Ньорндар добудьте информацию о противнике с помощью Ока Короля-лича."}}
D[13122] = {"Камень Плети",{"Принесите черному хранителю из Долины Эха в Ледяной Короне 15 камней Плети."}}
D[13123] = {"WotLK Collector's Edition: - DEM - E - FLAG"}
D[13124] = {"И вновь продолжается бой",{"Релораз просит вас войти в Окулус и спасти Белгаристраза с его командой."}}
D[13125] = {"Чистое небо",{"По заданию черного хранителя из Долины Эха в Ледяной Короне убейте Салнаракса Резчика, короля подземелий Талонокса и верховного жреца Ят'амона."}}
D[13126] = {"Единым фронтом",{"Белгаристраз просит вас уничтожить 10 Центрифужных созданий, разрушить щит Вароса и одолеть самого Заоблачного Странника."}}
D[13127] = {"Маг-лорд Уром",{"Белгаристраз просит вас победить Мага-лорда Урома в Окулусе."}}
D[13128] = {"Высокие ставки",{"Белгаристраз просит вас убить Эрегоса в Окулусе, после чего оповестить о его смерти Релораза из лагеря под Маскировочным щитом в Хладарре."}}
D[13129] = {"Игры разума",{"Курцель просит вас приложить клочок ее рубахи к трупу Новоса Призывателя, после чего отнести запятнанную лимфой ткань Маку."}}
D[13130] = {"Первый камень",{"По заданию архитектора ордена Силаса из Долины Эха добудьте 10 бревен хрустальной древесины и 10 обломков древней эльфийской кладки."}}
D[13131] = {"Пустой сундук",{"Принесите Бриггу на вершину Утгард 5 непотускневших серебряных слитков, 3 сверкающих кристалла, 2 золотых кубка и нефритовую статуэтку."}}
D[13132] = {"Отмщение",{"Убейте короля Имирона по просьбе Бригга из вершины Утгард."}}
D[13133] = {"Поиски древнего героя",{"Приведите Искальдера к костяной ведьме в деревню Ньорндар."}}
D[13134] = {"Пролитая кровь"}
D[13135] = {"Кристаллы энергии",{"Принесите 8 источников кристаллизованной энергии инженеру ордена Шпицпатрику в Долину Эха в Ледяной Короне."}}
D[13136] = {"Зазубренные осколки"}
D[13137] = {"Не совсем честный бой",{"Одержите победу над Искальдером на вершине Боевого шрама по поручению костяной ведьмы из деревни Ньорндар."}}
D[13138] = {"Непонятный металл"}
D[13139] = {"Ледяное сердце Нордскола",{"Доставьте донесение отца Густава верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне."}}
D[13140] = {"Руноковы Маликрисса"}
D[13141] = {"Битва за Вершину Рыцарей",{"Отправляйтесь на Вершину Рыцарей и установите благословенное знамя Авангарда на груде рыцарских черепов. Защищайте знамя от солдат Плети, пока земля на Вершине Рыцарей не очистится от порчи. Затем возвращайтесь к отцу Густаву в Долину Эха в Ледяной Короне."}}
D[13142] = {"Месть банши",{"Отомстите за костяную ведьму из деревни Ньорндар, бросив вызов верховному тану Балагарду и победив его."}}
