D[13180] = {"Убить всех и каждого!",{"Убейте 10 игроков Альянса по приказу командира Дардоша с Озера Ледяных Оков."}}
D[13181] = {"Победа на Озере Ледяных Оков",{"Выиграйте битву на Озере Ледяных Оков и вернитесь к офицеру-стратегу Абрамису. Необходимо принять участие в битве, чтобы выиграть ее."}}
D[13182] = {"И не забудь про яйца!",{"Проникните в Азжол-Неруб по просьбе Киликса Разрушителя из Провала Наржуна и уничтожьте 6 нерубских яиц Плети."}}
D[13183] = {"Победа на Озере Ледяных Оков",{"Выиграйте битву на поле боя Озера Ледяных Оков и вернитесь к офицеру-стратегу Килрату в крепость Ледяных Оков. Необходимо принять участие в битве, чтобы выиграть ее."}}
D[13184] = {"Больше нет нужды"}
D[13185] = {"Остановка осады",{"Уничтожьте 3 осадных машины Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков."}}
D[13186] = {"Остановка осады",{"Уничтожьте по приказу главного подрывника Легосо из крепости Ледяных Оков 3 осадных машины Орды."}}
D[13187] = {"Безликие",{"Убейте глашатая Волажа из Ан'кахета и трех позабытых, по просьбе Киликса Разрушителя из Провала Наржуна."}}
D[13188] = {"Шаги короля",{"Отнесите письмо в Штормград и отдайте королю Вариану Ринну."}}
D[13189] = {"Благословение вождя",{"Отнесите письмо в Оргриммар и отдайте Траллу, вождю Орды."}}
D[13190] = {"Все хорошо в свое время",{"Заполучите труп наблюдателя Ан'кахара по поручению Киликса Разрушителя из Провала Наржуна и поместите его на ан'кахетскую жаровню в Ан'кахете.","","Это задание может быть выполнено только на героическом уровне сложности."}}
D[13191] = {"Горючее для разрушителей",{"Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков."}}
