D[13199] = {"Кости и стрелы",{"Раздобудьте 10 колчанов со стрелами из драконьих костей у игроков Альянса в лесу Теней по просьбе лейтенанта Виерона Огненного Пера из крепости Ледяных Оков."}}
D[13200] = {"Горючее для разрушителей",{"Соберите 10 неугасимых угольков с тел воинов Альянса в Огненной котловине по приказу осадного кузнеца Могучее Копыто из крепости Ледяных Оков."}}
D[13201] = {"Целительные розы",{"Отыщите 10 сумок Альянса с травами в степи Жизни по просьбе идолопоклонника Мулфорта."}}
D[13202] = {"Заколдованные стены"}
D[13203] = {"Подарок к Зимнему Покрову"}
D[13204] = {"Странные грибочки",{"Соберите 6 кусков диковинной плесени с диких пещерных зверей в Ан'кахете и принесите их Киликсу Разрушителю в Провал Наржуна."}}
D[13205] = {"Разоружение",{"Защитник Мордун поручил вам проникнуть в Крепость Утгард и украсть 5 образцов врайкульского оружия."}}
D[13206] = {"Разоружение",{"Темный следопыт Марра просит вас украсть в крепости Утгард 5 образцов врайкульского оружия и принести их верховному палачу Ансельму в Лагерь Возмездия."}}
D[13207] = {"Чертоги Камня",{"Примите предложение Бранна Бронзоборода и сопровождайте его, пока он раскрывает тайны, хранящиеся в Чертогах Камня."}}
D[13210] = {"Blizzard Account: - DEM - E - FLAG"}
D[13211] = {"Сила очищающего огня"}
D[13212] = {"Части тела"}
D[13213] = {"Битва при Валхаласе",{"Поговорите с Джейрвиф из Валхаласа."}}
D[13214] = {"Битва при Валхаласе: павшие герои",{"Джейрвиф из Валхаласа передала вам вызов на битву, в которой вам предстоит за один раз одолеть всех шестерых павших героев: Элдрета, Генесса Полдуши, Джадраса, Масуда, Рита и Таллу.","","Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13215] = {"Битва при Валхаласе: Кит'рикс Темный Повелитель",{"Джейрвиф из Валхаласа передала вам вызов от Кит'рикса Темного Повелителя.","","Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13216] = {"Битва при Валхаласе: возвращение Сигрид Дитя Льда",{"Джейрвиф из Валхаласа передала вам вызов от Сигрид Дитя Льда.","","Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13217] = {"Битва при Валхаласе: Резчик-по-живому!",{"Джейрвиф из Валхаласа передала вам вызов от Резчика-по-живому.","","Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13218] = {"Битва при Валхаласе: тан Смертельный Удар",{"Джейрвиф из Валхаласа передала вам вызов от тана Банахогга Смертельного Удара.","","Если вам удастся победить, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13219] = {"Битва при Валхаласе: последний бой",{"Джейрвиф из Валхаласа передала вам вызов от принца Сандовала.","","Если вам удастся победить его, поговорите с Гьоннером Безжалостным, контролирующим южную часть Валхаласа."}}
D[13220] = {"Воскрешение Олакина"}
D[13221] = {"Я еще жив!"}
D[13222] = {"Защита осадных машин",{"По приказу главного подрывника Легосо из крепости Ледяных Оков защитите осадную машину или управляйте ею, пока она не уничтожит три строения.","","Осадные машины могут изготавливать игроки в звании \"рядовой\" и выше в гоблинских мастерских."}}
D[13223] = {"Защита осадных машин",{"Защитите осадную машину или управляйте ею, пока она не уничтожит три строения Альянса по приказу лейтенанта Мурпа из крепости Ледяных Оков.","","Осадные машины могут изготавливать лишь имеющие воинские звания игроки Орды в гоблинских мастерских."}}
D[13224] = {"Молот Оргрима",{"Найдите покорителя небес Корма Черного Шрама. Он находится на борту \"Молота Оргрима\", летающего над Ледяной Короной."}}
D[13225] = {"Усмиритель небес",{"Найдите старшего капитана Джастина Бартлетта. Он находится на борту \"Усмирителя небес\", патрулирующего Ледяную Корону."}}
D[13226] = {"И пришел Судный День!",{"Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне."}}
D[13227] = {"И пришел Судный День!",{"Отправляйтесь к верховному лорду Тириону Фордрингу в Оплот Серебряного Авангарда в Ледяной Короне."}}
D[13228] = {"Прорванный фронт",{"По заданию Корма Черного Шрама с \"Молота Оргрима\" отправляйтесь к Прорванному фронту и, поговорив с умирающим берсерком, узнайте, что там произошло."}}
D[13229] = {"Я еще жив!"}
D[13230] = {"Отомсти за меня!",{"Добейте 5 умирающих солдат у Прорванного фронта по просьбе умирающего берсерка. Об исполнении доложите покорителю небес Корму Черному Шраму на борту \"Молота Оргрима\"."}}
D[13231] = {"Прорванный фронт",{"Отправляйтесь на Прорванный фронт и расспросите умирающего солдата, после чего возвращайтесь к старшему капитану Джастину Бартлетту на борт \"Усмирителя небес\"."}}
D[13232] = {"Прикончи меня!",{"По просьбе умирающего солдата добейте 5 умирающих солдат у Прорванного фронта и доложите об исполнении старшему капитану Джастину Бартлетту на борту \"Усмирителя небес\"."}}
D[13233] = {"Пощады не будет!",{"По заданию старшего капитана Джастина Бартлетта с борта \"Усмирителя Небес\" убейте 15 игроков, сражающихся на стороне Орды в Ледяной Короне."}}
D[13234] = {"Они заплатят!",{"Убейте 15 игроков Альянса в Ледяной Короне по поручению покорителя небес Корма Черного Шрама."}}
D[13235] = {"Победитель мясистого великана"}
D[13236] = {"Войско проклятых"}
D[13237] = {"Тычки и тумаки",{"По поручению Кольтиры Ткача Смерти, находящегося на борту \"Молота Оргрима\", вы должны отправиться на Прорванный фронт и уничтожить 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы."}}
D[13238] = {"Какая-то полезная штука",{"Поговорите с главным инженером Меднопалом на борту \"Молота Оргрима\" по поручению покорителя небес Корма Черного Шрама."}}
D[13239] = {"Непостоянство",{"Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.","","Для того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенный доспех."}}
D[13240] = {"Времиар превидит встречу с центрифужными созданиями!",{"Исполните волю верховного мага Времиара, обитающего в Даларане, которого посетило видение, где вы уничтожаете 10 центрифужных созданий."}}
D[13241] = {"Времиар превидит встречу имирьярскими берсерками!",{"Уничтожьте по заданию верховного мага Времиара, обитающего в Даларане, 7 имирьярских берсерков."}}
D[13242] = {"Шевеление Тьмы",{"Соберите на поле боя боевые доспехи Саурфанга и верните их верховному правителю Саурфангу в крепость Песни Войны, что в Борейской тундре."}}
D[13243] = {"Времиар превидит встречу с посланницами из рода Бесконечности!",{"Верховный маг Времиар из Даларана предчувствует, что вам необходимо убить 4 посланниц из рода Бесконечности."}}
D[13244] = {"Времиар превидит встречу с титановыми воинами!",{"Убейте 7 титановых воинов, дабы предсказанное верховным магом Времиаром из Даларана сбылось."}}
D[13245] = {"Доказательство смерти: Ингвар Расхититель",{"Принесите секиру Расхитителя верховному магу Лан'далоку, обитающему в Даларане.","","Это задание выполняется в героическом режиме."}}
D[13246] = {"Доказательство смерти: Керистраза",{"Принесите в Даларан по заданию кровавого верховного мага Лан'далока разбитое сердце Керистразы.","","Это задание выполняется в героическом режиме."}}
D[13247] = {"Доказательство смерти: хранитель энергии Эрегос",{"Принесите устройство для настройки силовых линий верховному магу Лан'далоку в Даларан.","","Это задание выполняется в героическом режиме."}}
D[13248] = {"Доказательство смерти: король Имирон",{"Принесите медальон Усопшей королевы верховному магу Лан'далоку в Даларан.","","Это задание выполняется в героическом режиме."}}
D[13249] = {"Доказательство смерти: пророк Тарон'джа",{"Принесите верховному магу Лан'далоку в Даларан заколдованный амулет пророка.","","Это задание выполняется в героическом режиме."}}
D[13250] = {"Доказательство смерти: Гал'дара",{"Принесите верховному магу Лан'далоку в Даларан остатки колдунства Акали.","","Это задание выполняется в героическом режиме."}}
D[13251] = {"Доказательство смерти: Мал'Ганис",{"Принесите артефакт из родного мира натрезимов верховному магу Лан'далоку в Даларан.","","Это задание выполняется в героическом режиме."}}
D[13252] = {"Доказательство смерти: Сьоннир Литейщик",{"Принесите верховному магу Лан'далоку в Даларан диск о Проклятии Плоти.","","Это задание выполняется в героическом режиме."}}
D[13253] = {"Доказательство смерти: Локен",{"Принесите верховному магу Лан'далоку в Даларан божественное рубиновое кольцо.","","Это задание выполняется в героическом режиме."}}
D[13254] = {"Доказательство смерти: Ануб'арак",{"Принесите бесполезную корону Ануб'арака верховному магу Лан'далоку из Даларана.","","Это задание выполняется в героическом режиме."}}
D[13255] = {"Доказательство смерти: глашатай Волаж",{"Принесите верховному магу Лан'далоку в Даларан усохший мозг Безликого.","","Это задание выполняется в героическом режиме."}}
D[13256] = {"Доказательство смерти: Синигоса",{"Принесите верховному магу Лан'далоку в Даларан голову Синигосы.","","Это задание выполняется в героическом режиме."}}
D[13257] = {"Глашатай войны",{"Доложите о своем прибытии Траллу, который находится в крепости Громмаш в Оргриммаре."}}
D[13258] = {"Замечательная возможность",{"Поговорите с сержантом Креггой под стенами Цитадели Ледяной Короны."}}
D[13259] = {"Закрепить преимущество",{"Убейте 10 неповоротливых громад по поручению сержанта Крегги, находящегося у Цитадели Ледяной Короны."}}
D[13260] = {"Уж кто бы говорил!",{"По заданию покорителя небес Корма поговорите с Кольтирой Ткачом Смерти на борту \"Молота Оргрима\"."}}
D[13261] = {"Непостоянство",{"Отправляйтесь к Прорванному фронту и воспользуйтесь летучим маслом Меднопала, чтобы привлечь 3 ледяных небесных когтей.","","Для того чтобы использовать масло, соберите на поле сражения груду костей, брошенный шлем и брошенную броню."}}
D[13262] = {"Мощный взрыв",{"Идите к ближайшему штабелю саронитовых бомб и подожгите фитиль."}}
D[13263] = {"Фитиль короток!",{"Ищите следы и подсказки, независимо от того, куда вас занесет взрывной волной."}}
D[13264] = {"Как все погано!",{"По заданию Кольтиры Ткача Смерти с \"Молота Оргрима\", используя набор для оживления, воскресите поганище и с его помощью уничтожьте 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса."}}
D[13265] = {"Сбор ткани"}
D[13266] = {"Жизнь без сожалений",{"Воспользуйтесь порталом в Подгород, расположенном в крепости Громмаш, и доложите о своем прибытии Вол'джину."}}
D[13267] = {"Битва за Подгород",{"Помогите Траллу и Сильване вернуть Орде контроль над Подгородом.","","В случае успеха отрапортуйте об этом Траллу."}}
D[13268] = {"Сбор ткани"}
D[13269] = {"Сбор ткани"}
D[13270] = {"Сбор ткани"}
D[13271] = {"Голос во тьме"}
D[13272] = {"Сбор ткани"}
D[13273] = {"В поисках ядра",{"Найдите записи геолога Хроны и записи геолога Сорена в главном лагере Бранна."}}
D[13274] = {"Хранитель ядра",{"Добудьте ядро Норганнона."}}
D[13275] = {"Пора прятаться!"}
D[13276] = {"Как все погано!",{"Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Кольтиры Ткача Смерти с \"Молота Оргрима\"."}}
D[13277] = {"Борьба с великанами",{"Принесите Кольтире Ткачу Смерти на борт \"Молота Оргрима\" 5 гноящихся позвоночников пустулезных ужасов из Морд'ретара."}}
D[13278] = {"Корпой Оскверненный",{"Убейте Корпоя Оскверненного из Морд'ретара по просьбе Кольтиры Ткача Смерти с \"Молота Оргрима\"."}}
D[13279] = {"Основы химии",{"Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд'ретаре по просьбе Кольтиры Ткача Смерти с борта \"Молота Оргрима\"."}}
D[13280] = {"Царь горы",{"Используйте прыгобот Зуботески, чтобы установить боевой штандарт Альянса в груде черепов на вершине горы, по просьбе Фраззл Зуботески."}}
D[13281] = {"Избавление от чумы"}
D[13282] = {"Возвращение на поверхность"}
D[13283] = {"Царь горы",{"Используйте прыгобот Громбабаха, чтобы установить боевой штандарт Орды в груде черепов на вершине горы, по просьбе Бубуха Громбабаха."}}
D[13284] = {"Атака пехоты",{"Сопроводите войска \"Усмирителя небес\" к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к востоку от Имирхейма к военачальнику Купу за наградой."}}
D[13285] = {"Изготовление краеугольного камня",{"Встретьтесь с Бранном Бронзобородом в Храме Изобретений и помогите Бранну сложить вместе оболочку Норганнона и ядро Норганнона. После этого вернитесь к Боктару Кровавому Безумию на место крушения Гром'арша."}}
D[13286] = {"Хоть какая-нибудь помощь!",{"Поговорите с Тассарианом по просьбе старшего капитана Джастина Бартлетта на борту \"Усмирителя небес\"."}}
D[13287] = {"Тычки и тумаки",{"Убейте 5 неповоротливых поганищ, 5 злокозненных некромантов и 5 адептов Тьмы по просьбе Тассариана, находящегося на борту \"Усмирителя небес\", корабля Альянса."}}
D[13288] = {"Как все погано!",{"Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с \"Усмирителя Небес\"."}}
D[13289] = {"Как все погано!",{"Используйте набор для оживления, чтобы воскресить поганище и убить с его помощью 15 ледяных вурдалаков, 15 агрессивных упырей и 15 восставших солдат Альянса по просьбе Тассариана с \"Усмирителя небес\"."}}
D[13290] = {"Немного внимания",{"Поговорите с главным инженером Болтоключом на борту \"Усмирителя небес\" по просьбе старшего капитана Джастина Бартлетта."}}
D[13291] = {"Заимствованная технология",{"Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту \"Усмирителя небес\".","","Для этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте."}}
D[13292] = {"Решение проблемы",{"Используйте краденый раствор на Прорванном фронте по просьбе главного инженера Болтоключа на борту \"Усмирителя небес\".","","Для этого вам понадобится брошенный шлем, брошенная броня и груда костей. Все это можно найти на Прорванном фронте."}}
D[13293] = {"В Имирхейм!",{"Поговорите с Бубухом Громбабахом в Имирхейме."}}
D[13294] = {"Борьба с великанами",{"Принесите Тассариану с \"Усмирителя небес\" 5 позвоночников пустулезных ужасов из Морд'ретара."}}
D[13295] = {"Основы химии",{"Вылейте пустулезную спинномозговую жидкость в чумной котел в Морд'ретаре по просьбе Тассариана на борту \"Усмирителя небес\"."}}
D[13296] = {"В Имирхейм!",{"Поговорите с Фраззл Зуботеской в Имирхейме."}}
D[13297] = {"Избавление от чумы",{"По приказу Тассариана с \"Усмирителя небес\" отправляйтесь в Морд'ретар и нейтрализуйте содержимое чумного котла с помощью пустулезной спинномозговой жидкости.","","Пустулезная спинномозговая жидкость изготовляется из позвоночника великана. Его можно получить, убивая пустулезных ужасов."}}
D[13298] = {"Корпой Оскверненный",{"Убейте Корпоя Оскверненного из Морд'ретара по просьбе Тассариана с \"Усмирителя небес\"."}}
D[13299] = {"zzOLDПлащ огонька"}
D[13300] = {"Рабы саронитовых шахт",{"Абсалан Благочестивый, находящийся на борту \"Усмирителя небес\", просит вас освободить 10 рабов из саронитовых шахт."}}
D[13301] = {"Атака пехоты",{"Сопроводите кор'кронские войска к вратам Имирхейма. Выполнив задание, вернитесь на край ледника к северу от Имирхейма к командиру наземных войск Ксутье за наградой."}}
D[13302] = {"Рабы саронитовых шахт",{"Брат Келтан, находящийся на борту \"Молота Оргрима\", просит вас освободить 10 рабов из саронитовых шахт."}}
D[13304] = {"Ремонт в полевых условиях"}
D[13305] = {"Все к худшему"}
D[13306] = {"Строим баррикады!",{"Постройте 8 баррикад с помощью комплекта для возведения баррикад по просьбе Кольтиры Ткача Смерти, находящегося на борту \"Молота Оргрима\"."}}
D[13307] = {"Окровавленные знамена",{"Убейте 5 знаменосцев Плети, 5 обратителей Плети и 20 обращенных героев по просьбе Кольтиры Ткача Смерти, который находится на борту \"Молота Оргрима\"."}}
D[13308] = {"Игры разума",{"Добудьте ключ штейгера от оков темного проповедника Р'кхема в Саронитовых шахтах."}}
D[13309] = {"Воздушный десант",{"По приказу командира Купа, который расположился на склоне ледника к востоку от Имирхейма, воспользуйтесь подавительной пушкой \"Усмирителя небес\". Обеспечьте прикрытие для транспортного самолета, пока тот будет высаживать десант."}}
D[13310] = {"Воздушный десант",{"Командир наземных войск Ксутья на краю ледника возле Имирхейма приказал вам использовать кор'кронскую заградительную пушку, чтобы обеспечить прикрытие для кор'кронского транспортника, так чтобы десант был сброшен, а транспортный самолет остался целым."}}
D[13311] = {"Карты Новолуния: колода Демонов",{"Призовите предсказателя судьбы с Ярмарки Новолуния и отдайте ему колоду Демонов."}}
D[13312] = {"Железный вал",{"Убейте Гримкора Злобного и возвращайтесь к Кольтире Ткачу Смерти на \"Молот Оргрима\"."}}
D[13313] = {"Ослепить соглядатаев!",{"С помощью ЗГ-3 уничтожьте 6 разведывательных истребителей \"Усмирителя небес\", потом вернитесь к покорителю небес Корму Черному Шраму на борт \"Молота Оргрима\"."}}
D[13314] = {"Перехватить донесения",{"Заберите 6 донесений для \"Молота Оргрима\" у разведчиков с \"Молота Оргрима\" и отдайте их старшему капитану Джастину Бартлетту на борту \"Усмирителя небес\"."}}
D[13315] = {"Предварительная разведка",{"Слетайте к Вратам Горя и ознакомьтесь с южной, центральной, северной и северо-западной частями Врат по просьбе Тассариана с \"Усмирителя небес\"."}}
