D[13404] = {"Войска статического разряда: Зона бомбардировки",{"Убейте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию Кибли Киллогерца."}}
D[13405] = {"К оружию! Берег Древних",{"Выиграйте битву на поле боя Берега Древних и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[13406] = {"Новое излучение. Зона бомбардировки",{"Уничтожьте 50 пехотинцев из зоны бомбардировки, 10 капитанов из зоны бомбардировки и 20 горгулий-душительниц по заданию инженера-экспериментатора Теззлы."}}
D[13407] = {"К оружию! Берег Древних",{"Выиграйте битву на поле боя Берега Древних и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[13408] = {"Штурмовые укрепления",{"Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени."}}
D[13409] = {"Штурмовые укрепления",{"Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны."}}
D[13410] = {"Штурмовые укрепления",{"Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь к прапорщику Трейси Праудвелл в Оплот Чести на Полуострове Адского Пламени."}}
D[13411] = {"Штурмовые укрепления",{"Захватите Дозорное укрепление, Ристалище и Изрезанный холм, и возвращайтесь в Траллмар к Черноглазке Зову Войны."}}
D[13412] = {"Корастраза",{"Поговорите с Корастразой в Хладарре по просьбе библиотекаря Серры."}}
D[13413] = {"Асы, ввысь!",{"Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев."}}
D[13414] = {"Асы, ввысь!",{"Возьмите дракона Корастразы из верхнего кольца Нексуса в Хладарре и убейте 5 чешуеклятов-гвардейцев."}}
D[13415] = {"Пульт в библиотеке",{"Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя."}}
D[13416] = {"Пульт в библиотеке",{"Активируйте пульт в Библиотеке Изобретателя с помощью диска изобретателя."}}
D[13417] = {"Братья Бронзобороды"}
D[13418] = {"Подготовка к войне",{"Поговорите с офицером ван Россемом, который переправит вас на борт \"Усмирителя небес\" в Ледяной Короне, а потом побеседуйте со старшим капитаном Джастином Бартлеттом."}}
D[13419] = {"Подготовка к войне",{"Поговорите с покорителем небес Клумом, который переправит вас на борт \"Молота Оргрима\" в Ледяной Короне, а потом побеседуйте с покорителем небес Кормом Черным Шрамом."}}
D[13420] = {"Вечный лед",{"Возвращайтесь в Дун Ниффелем и расспросите Кальдера насчет осколка Вечного льда."}}
D[13421] = {"Больше Вечного льда!"}
D[13422] = {"Поучить уму-разуму",{"Накажите 6 обессиленных врайкулов из Заброшенного рудника с помощью вразумляющего жезла по заданию Гретты Судьи из деревни Бруннхильдар."}}
D[13423] = {"Подтверждение победы",{"Одержите победу над 6 дуэлянтами-победителями по заданию Гретты Судьи из деревни Бруннхильдар."}}
D[13424] = {"Обратно в Яму Клыка"}
D[13425] = {"Смерть гнусным тварям!",{"По заданию Гретты Судьи из деревни Бруннхильдар отправляйтесь в Валькирион и добудьте у валькирионских претенденток флаконы масла льда. Используйте флаконы масла льда, чтобы уничтожить 30 зачумленных яиц протодраконов."}}
D[13426] = {"Ксанатавр, Свидетель",{"Поговорите с Ксанатавром в лагере Тунка'ло."}}
D[13427] = {"К оружию! Альтеракская долина",{"Победите на поле боя Альтеракской долины и вернитесь к бригадному генералу Альянса в любую из столиц Альянса, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[13428] = {"К оружию! Альтеракская долина",{"Победите на поле боя Альтеракской долины и вернитесь к ордынскому вестнику войны в любую из столиц Орды, на Озеро Ледяных Оков, в Даларан или в Шаттрат."}}
D[13429] = {"Отвлекающий маневр",{"Убедитесь, что Акама и Майев вошли в Черный храм в долине Призрачной Луны после того, как войска Кси'ри совершат отвлекающий маневр."}}
D[13430] = {"Испытание наару: Магтеридон",{"По заданию А'дала из Шаттрата убейте Магтеридона."}}
D[13431] = {"Дубина Кардеша",{"Принесите эталоны земли и огня Скартису Еретику в Узилище (героический уровень сложности) в Резервуар Кривого Клыка."}}
D[13432] = {"Сосуды Вечности",{"Соридорми из Пещер Времени желает, чтобы вы принесли ей неполный фиал Леди Вайш из Резервуара Кривого Клыка и неполный фиал Кель'таса из Крепости Бурь."}}
