D[64142] = {"Доказательство лояльности",{"Леди Лиадрин из Луносвета просит уничтожить 3 мясных фургона и убить 15 инженеров Плети."}}
D[64217] = {"Темный портал",{"Поговорите с полководцем Дар'туном в Выжженных землях. Он ждет вас у Темного портала."}}
D[64319] = {"Источник силы",{"Поговорите с магистром Асталором Кровавой Клятвой в тайной зале, расположенной под штабом рыцарей крови."}}
D[64845] = {"Военная кампания Альянса",{"Победите в игре на поле боя и вернитесь к бригадному генералу сил Альянса в любую из столиц Альянса или в Шаттрат."}}
